PRAGMA journal_mode=WAL;
BEGIN;
CREATE TABLE IF NOT EXISTS courses (id TEXT PRIMARY KEY, category TEXT, title TEXT, content TEXT, quizzes_json TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, video_url TEXT, mode TEXT DEFAULT 'quiz', sort_order INTEGER DEFAULT 0, subcategory TEXT DEFAULT '', guide_json TEXT, instructions TEXT, i18n_json TEXT DEFAULT '');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1772714171694','基要真理','第一课 人为何需要神？','信仰不是困难时的慰藉，而是人与创造宇宙的真神建立互动关系。本课辨明人造宗教与基督信仰的根本区别，从宇宙规律认识真神，脱离功利信仰观。愿这真理成为你信仰的稳固根基。','[{"type": "verse", "q": "【经文填空】自从造天地以来，神的________和________是明明可知的，虽是眼不能见，但藉着所造之物就可以晓得，叫人无可推诿", "o": "《罗马书》1章20节", "s": "创造显明神", "a": "永能|神性"}, {"type": "verse", "q": "【经文填空】耶和华，耶和华，是有________、有________的神，不轻易发怒，并有丰盛的慈爱和诚实", "o": "《出埃及记》34章6节", "s": "神的属性", "a": "怜悯|恩典"}, {"type": "verse", "q": "【经文填空】诸天述说神的________，穹苍传扬他的________", "o": "《诗篇》19章1节", "s": "诸天述说", "a": "荣耀|手段"}, {"type": "fill", "q": "基督徒的信仰不是人造宗教的产物，而是神所________的真理", "o": "", "s": "启示的信仰", "a": "启示"}, {"type": "fill", "q": "宗教是人站在自己的角度找神，找不到就造神，把________神化", "o": "", "s": "人造神", "a": "人"}, {"type": "fill", "q": "在人造的宗教里，人判断神明是否值得敬拜的标准是「________不灵」", "o": "", "s": "灵验标准", "a": "灵"}, {"type": "fill", "q": "既然神的智慧能力都比我们高，正确的人神关系是________听神，而不是神听我们", "o": "", "s": "谁听谁", "a": "我们"}, {"type": "fill", "q": "无限的神进入有限的人类历史，在祂的智慧里选择了________的巴勒斯坦，借以色列民族启示真理", "o": "", "s": "神的选择", "a": "中东"}, {"type": "fill", "q": "正如椅子必有制造它的人，精密规律的宇宙必有一位________", "o": "", "s": "宇宙的工匠", "a": "创造者"}, {"type": "single", "q": "根据本课，基督教信仰与一般宗教的根本区别是什么？", "o": "A.基督教历史更悠久,B.基督教是神启示的真理，不是人造的宗教,C.基督教的仪式更庄严,D.基督教的信徒更多", "s": "启示与人造", "a": "B"}, {"type": "single", "q": "为什么不能说「把神拿出来给我看，我就信」？", "o": "A.因为神不存在,B.真神不是人可以召之即来、挥之即去的仆人,C.因为神离我们太远,D.因为科学家还没有找到神", "s": "神非仆人", "a": "B"}, {"type": "single", "q": "本课提到，神借着与以色列民族的互动，向人显明祂是怎样的神？", "o": "A.只有能力，没有慈爱,B.慈爱怜悯，又公义圣洁,C.只讲公义，不讲慈爱,D.神秘莫测，无法认识", "s": "神的属性", "a": "B"}, {"type": "multiple", "q": "本课提到，哪些宇宙现象显明有一位创造者？（多选）", "o": "A.地球以23.5度倾斜规律运转,B.浩瀚银河系中唯有地球适合人居住,C.热力学第二定律表明规律来自设计而非偶然,D.月球表面布满陨石坑洞", "s": "宇宙的见证", "a": "A|B|C"}, {"type": "multiple", "q": "本课指出，人造宗教有哪些特征？（多选）", "o": "A.把人神化,B.以「灵不灵」为判断标准,C.神人关系由人自己来定,D.神主动启示真理", "s": "宗教的特征", "a": "A|B|C"}, {"type": "judge", "q": "基督教信仰认为，信仰只是为生活有难处的人预备的。", "o": "", "s": "信仰的对象", "a": "错"}, {"type": "judge", "q": "根据本课，真有一位独一的真神，祂渴慕与人建立正确的关系。", "o": "", "s": "独一真神", "a": "对"}, {"type": "judge", "q": "本课认为，基督教是从西方传来的西方宗教。", "o": "", "s": "信仰非地域", "a": "错"}, {"type": "essay", "q": "为什么说人造宗教里「灵不灵」不能作为判断真神的标准？请结合本课内容说明。", "o": "", "s": "灵验标准", "a": "人造宗教的神是人造出来的，标准由人定：所求的成就了就继续拜，不灵就换一个，把神当成解决问题的工具，用完即弃。若真有一位神，祂的智慧能力都比人高，就应是人听祂、由祂带领，而不是人定标准差遣祂。真正的信仰是人与创造宇宙的真神建立互动的关系，不是拿神当仆人使唤。"}, {"type": "essay", "q": "本课如何用「椅子」的比喻说明宇宙必有一位创造者？", "o": "", "s": "椅子的比喻", "a": "没有人见过造椅子的人，却都相信椅子必有人设计制造，不会相信它是偶然自然出现的。宇宙比椅子精密无数倍——地球以23.5度倾斜规律运转、绕太阳一周就是一年、银河系中唯有地球适合人居住——更不可能是无目的的偶然。正如圣经所说：「自从造天地以来，神的永能和神性是明明可知的。」"}]','https://youtu.be/GA9Db6u97Y8
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.772853586fGZy','quiz','[{"points": ["有人认为神只是失业、失婚、失败之人的慰藉，成功的人不需要神", "电影《唐山大地震》中，面对不可抗力时人会喊“老天啊祢在干什么”", "基督信仰告诉我们：信仰是人与创造宇宙的真神之间的互动关系"], "title": "信仰不只是为难处预备的"}, {"points": ["如果神只是解决问题后就走，像仆人随叫随到，这样的神很怪", "人不太注重与神的关系，只看重所求的对象“灵不灵”", "基督信仰强调的是人跟神之间真实的关系，而非利用关系"], "title": "神不是阿拉丁神灯"}, {"points": ["从未听过儿女带领父母亲，总是父母带领儿女", "孩子不一定喜欢父母的管教，但那是孩子真正需要的", "天父与我们的关系也是如此：是祂带领我们，而非我们定标准要求祂"], "title": "父母与儿女的类比"}, {"points": ["宗教是站在人的角度去找神，找不到就造神、把人神化", "各宗教把古代伟人、圣人神化，如皇帝封神、希腊神话满天神", "基督信仰是宇宙间真有一位神，祂自显其存在，而非人所造"], "title": "宗教与基督信仰的分别"}, {"points": ["罗马书1:20：自从造天地以来，神的永能和神性是明明可知的", "椅子类比：没人相信椅子是偶然出现，何况精密的宇宙", "地球23.5度倾斜、自转公转的规律，热力学第二定律显明背后有设计者"], "title": "宇宙规律见证神的存在"}, {"points": ["神进入人类历史必须选择一个地方，祂选择了巴勒斯坦的以色列", "以色列被拣选作神启示真理的管道，并非他们优越于别人", "神爱以色列人，也一样爱全世界所有的人"], "title": "神不只属于西方"}, {"points": ["借着以色列认识神：慈爱、怜悯、满有恩慈，也公义、圣洁", "出埃及记34章6节：神有恩典有怜悯，不轻易发怒，断不以有罪为无罪", "人以自我为中心制造许多问题；神要根本解决人与神之间的问题"], "title": "借着以色列认识神与人"}]','','1','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 1 Why do people need God?", "content": "Faith is not a consolation in times of difficulty, but an interactive relationship between man and the true God who created the universe. In this lesson, we identify the fundamental difference between artificial religion and Christianity, learn about the true God from the laws of the universe, and break away from the utilitarian view of belief. May this truth be a firm foundation of your faith.", "instructions": "", "guide": [{"title": "Faith is not just for the difficult", "points": ["Some people think that God is only a consolation for the unemployed, the unmarried, and the defeated. Successful people do not need God.", "In the movie \"Tangshan Earthquake\", people shout \"God, what are you doing\" in the face of force majeure", "Christianity teaches us that faith is the interaction between man and the true God who created the universe."]}, {"title": "God is not Aladdin''s lamp", "points": ["If the god just solves the problem and then leaves, like a servant on call, such a god is very strange", "People pay less attention to their relationship with God, and only pay attention to the \"spirituality\" of the desired object.", "Christianity emphasizes the true relationship between man and God, not the use of it"]}, {"title": "Analogies between parents and children", "points": ["Never heard of children leading parents, always parents leading children", "Kids don''t necessarily like parental discipline, but that''s what kids really need", "The same is true of Heavenly Father''s relationship with us: He leads us, not that we set standards for Him."]}, {"title": "The difference between religion and Christianity", "points": ["Religion is looking for God from the perspective of people. If you can''t find it, you can create God and deify people.", "Various religions deify ancient great men and saints, such as emperors and gods, and Greek mythology is full of gods.", "Christianity is that there really is a God in the universe, who reveals his existence, not that of man."]}, {"title": "The laws of the universe bear witness to the existence of God", "points": ["Romans 1:20: Since the creation of the heavens and the earth, God''s eternal power and divinity have been clearly known", "Chair analogy: no one believes that chairs are accidental, not to mention the precision of the universe", "The second law of thermodynamics shows that there is a designer behind the 23.5 degree tilt and rotation of the earth."]}, {"title": "God doesn''t just belong in the West", "points": ["God entered human history must choose a place, He chose Israel in Palestine", "Israel was chosen as a conduit for God''s revelation of truth, not that they were superior to others.", "God loves the Israelites as much as He loves all the people of the world."]}, {"title": "Getting to know God and people through Israel", "points": ["Knowing God through Israel: mercy, compassion, kindness, righteousness, holiness", "Exodus 34:6: God is gracious and merciful, not easily angry, never innocent of sin", "Man is self-centered and creates many problems; God wants to fundamentally solve the problems between man and God."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] Since the creation of the heavens and the earth, God''s ________ and ________ have been clearly known, although they are invisible to the eyes, but they can be known through the created things, so that people can not be denied.", "s": "Creation reveals God", "a": "eternal power|divine nature"}, {"q": "[Scripture Fill in the Blank] Jehovah, Jehovah, there is a God of ________, there is ________, there is not easy anger, and there is abundant love and honesty", "s": "Attributes of God", "a": "mercy|grace"}, {"q": "[Scripture Fill in the Blank] The heavens tell of God''s ________, and the sky tells of his ________", "s": "All Heavens Narrate", "a": "glory|means"}, {"q": "The Christian faith is not the product of artificial religion, but the truth of God''s ________", "s": "Faith in Revelation", "a": "revelation"}, {"q": "Religion is when people stand in their own perspective to find God, find and create God, and deify ________", "s": "artificial God", "a": "man"}, {"q": "In man-made religions, the criterion for judging whether a god is worthy of worship is “________ not working”.", "s": "Psychic standards", "a": "Spirit"}, {"q": "Since God''s wisdom power is higher than ours, the correct relationship between man and God is to ________ listen to God, not God listen to us.", "s": "Who listens to whom", "a": "us"}, {"q": "Infinite God enters the finite history of mankind, choosing ________ Palestine in his wisdom to reveal the truth through the nation of Israel", "s": "God''s Choice", "a": "the Middle East"}, {"q": "Just as the chair must have the person who made it, the precision law of the universe must have a ________", "s": "Cosmic Craftsman", "a": "the Creator"}, {"q": "According to this lesson, what is the fundamental difference between Christian faith and general religion?", "s": "Revelation and Artificiality", "a": "B", "o": "A.A Longer History of Christianity,B.Christianity is a divinely revealed truth, not a man-made religion,C.Christian rituals are more solemn,D.More believers in Christianity"}, {"q": "Why can''t we say, “Show me God and I''ll believe”?", "s": "God is not a servant", "a": "B", "o": "A.Because God doesn''t exist,B.The true God is not a servant who can be summoned and waved away,C.Because God is too far away from us,D.Because scientists haven''t found God yet."}, {"q": "As mentioned in this lesson, through his interaction with the nation of Israel, what kind of God did God reveal Himself to mankind?", "s": "Attributes of God", "a": "B", "o": "A.Only ability, no loving kindness,B.Mercy, compassion, and righteousness and holiness,C.Speak only of righteousness, not of mercy.,D.Mysterious and unknowable"}, {"q": "In this lesson, what cosmic phenomena reveal a Creator? (Multiple choice)", "s": "Witness of the Universe", "a": "A|B|C", "o": "A.The Earth moves at a 23.5 degree tilt,B.The only habitable planet in the vast galaxy,C.The second law of thermodynamics states that laws come from design, not chance.,D.The lunar surface is full of craters"}, {"q": "What are some of the characteristics of man-made religions identified in this lesson? (Multiple choice)", "s": "Characteristics of Religion", "a": "A|B|C", "o": "A.Divine a person,B.Judging by \"not working\",C.The relationship between God and man is determined by man himself,D.God''s Active Revelation of Truth"}, {"q": "The Christian faith believes that faith is only for those who have difficulties in life.", "s": "Who Believes", "a": "False"}, {"q": "According to this lesson, there is truly one true God, who longs to have the right relationship with people.", "s": "Unique True God", "a": "True"}, {"q": "This lesson argues that Christianity is a Western religion that came from the West.", "s": "Beliefs Non-Regional", "a": "False"}, {"q": "Why is it that in artificial religion, \"spirituality\" cannot be used as a criterion for judging the true God? Please explain in conjunction with this lesson.", "s": "Psychic standards", "a": "人造宗教的神是人造出来的，标准由人定：所求的成就了就继续拜，不灵就换一个，把神当成解决问题的工具，用完即弃。若真有一位神，祂的智慧能力都比人高，就应是人听祂、由祂带领，而不是人定标准差遣祂。真正的信仰是人与创造宇宙的真神建立互动的关系，不是拿神当仆人使唤。"}, {"q": "How does this lesson use the “chair” metaphor to illustrate that the universe must have a creator?", "s": "Parable of the Chair", "a": "没有人见过造椅子的人，却都相信椅子必有人设计制造，不会相信它是偶然自然出现的。宇宙比椅子精密无数倍——地球以23.5度倾斜规律运转、绕太阳一周就是一年、银河系中唯有地球适合人居住——更不可能是无目的的偶然。正如圣经所说：「自从造天地以来，神的永能和神性是明明可知的。」"}]}, "ja": {"title": "レッスン1なぜ人々は神を必要とするのか？", "content": "信仰は困難な時の慰めではなく、人間と宇宙を創造した真の神との間の相互関係です。このレッスンでは、人工宗教とキリスト教の根本的な違いを特定し、宇宙の法則から真の神について学び、功利主義的な信念の見方から脱却します。この真理があなたの信仰の堅固な基盤となりますように。", "instructions": "", "guide": [{"title": "信仰は困難な人のためだけのものではありません", "points": ["神は失業者、未婚者、敗北者のための慰めに過ぎないと考える人もいます。成功した人は神を必要としません。", "映画「唐山地震」では、不可抗力に直面して人々が「神よ、あなたは何をしているのですか」と叫びます", "キリスト教は、信仰とは人間と宇宙を創造した真の神との相互作用であると教えています。"]}, {"title": "神はアラジンのランプではない", "points": ["神が問題を解決しただけで、召使いのように去っていくと、そのような神は非常に奇妙です", "人々は神との関係にあまり注意を払わず、望ましい対象の「霊性」だけに注意を払います。", "キリスト教は、人と神の間の真の関係を強調しているのであって、それを使うことを強調しているのではない"]}, {"title": "親子のアナロジー", "points": ["子供が親をリードしていると聞いたことがなく、常に親が子供をリードしている", "子供は必ずしも親の規律が好きではありませんが、それが子供が本当に必要としているものです", "天の御父とわたしたちとの関係も同じです。わたしたちが御父のために基準を定めているのではなく，御父がわたしたちを導いてくださるのです。"]}, {"title": "宗教とキリスト教の違い", "points": ["宗教とは、人の視点から神を求めることであり、見つからなければ、神を創造し、人を神格化することができます。", "様々な宗教は、皇帝や神などの古代の偉人や聖人を神格化し、ギリシャ神話は神々でいっぱいです。", "キリスト教は、人間の存在ではなく、自分の存在を明らかにする神が本当に宇宙にいるということです。"]}, {"title": "宇宙の法則が神の存在を証しする", "points": ["ローマ1 ： 20 ：天と地が創造されて以来，神の永遠の力と神性ははっきりと知られてきました", "椅子のアナロジー：宇宙の精度は言うまでもなく、椅子は偶然であるとは誰も信じていません", "熱力学の第二法則は、地球の23.5度の傾きと回転の背後にデザイナーがいることを示しています。"]}, {"title": "神は西洋だけに属しているのではありません", "points": ["神は人類の歴史に入り、場所を選ばなければならず、パレスチナでイスラエルを選ばれました", "イスラエルは，神の真理の啓示の導管として選ばれたのであって，他の人々よりも優れているというわけではありません。", "神は，世界のすべての人々を愛しておられるのと同じように，イスラエルの人々を愛しておられます。"]}, {"title": "イスラエルを通して神と人々を知る", "points": ["イスラエルを通して神を知る：憐れみ、思いやり、親切、正義、聖性", "出エジプト記34章6節 ：神は恵み深く憐れみ深く，容易に怒ることはなく，決して罪のない方ではない", "人間は自己中心的であり、多くの問題を引き起こします。神は人間と神との間の問題を根本的に解決したいと望んでいます。"]}], "quizzes": [{"q": "[Scripture Fill in the Blank]天と地の創造以来、神の________と________ははっきりと知られていますが、目には見えませんが、創造されたものを通して知ることができるので、人々は否定することができません。", "s": "創造は神を明らかにする", "a": "永遠の力|神性"}, {"q": "〔聖句の穴埋め〕主，主は________と________の神であり，怒りに鈍く，憐れみと真理に富んでおられます。", "s": "神の属性", "a": "憐れみ|恵み"}, {"q": "[Scripture Fill in the Blank]天は神の________を告げ、空は神の________を告げる", "s": "オールヘブンズ・ナレーツ", "a": "栄光|手段"}, {"q": "キリスト教信仰は人工的な宗教の産物ではなく、神の________の真理です。", "s": "啓示への信仰", "a": "啓示"}, {"q": "宗教とは、人々が自分の視点で立ち、神を見つけ、神を見つけ、創造し、________を神格化することです", "s": "人工神", "a": "人"}, {"q": "人工宗教では、神が崇拝に値するかどうかを判断する基準は「________働かない」です。", "s": "サイキック・スタンダード", "a": "霊"}, {"q": "神の知恵の力は私たちよりも高いので、人間と神との正しい関係は、神が私たちに耳を傾けるのではなく、神に耳を傾けることです。", "s": "誰が誰に耳を傾けるか", "a": "私たち"}, {"q": "無限の神は人類の有限の歴史に入り、その知恵の中で________パレスチナを選び、イスラエルの民を通して真理を明らかにされました", "s": "神の選び", "a": "中東"}, {"q": "ちょうど椅子がそれを作った人を持っていなければならないように、宇宙の精密な法則は________を持っていなければなりません", "s": "コズミック職人", "a": "創造主"}, {"q": "このレッスンによれば，キリスト教信仰と一般宗教の根本的な違いは何ですか。", "s": "啓示と人工知能", "a": "B", "o": "A.キリスト教の長い歴史,B.キリスト教は神から啓示された真理であり、人工的な宗教ではありません,C.キリスト教の儀式はより厳粛です,D.キリスト教の信者を増やす"}, {"q": "「神を示しなさい。そうすれば信じる」と言えないのはなぜでしょうか。", "s": "神は召使いではない", "a": "B", "o": "A.神は存在しないから,B.真の神は召喚されて手を振ることができる召使いではありません,C.神は私たちから遠すぎるから,D.なぜなら、科学者たちはまだ神を見つけていないからです。"}, {"q": "この課で述べたように，神はイスラエルの民との交流を通して，どのような神を人類に現されたのでしょうか。", "s": "神の属性", "a": "B", "o": "A.能力だけで、愛情のある優しさはありません,B.憐れみ，憐れみ，正義と聖性,C.憐れみではなく，ただ義について語りなさい。,D.謎めいた未知の世界"}, {"q": "このレッスンでは、どのような宇宙現象がクリエイターを明らかにしますか？ （複数選択可）", "s": "宇宙の目撃者", "a": "A|B|C", "o": "A.地球は23.5度傾いて動きます,B.広大な銀河系で唯一の居住可能な惑星,C.熱力学の第二法則は、法則は偶然ではなく設計から来ると述べています。,D.月面はクレーターでいっぱいです"}, {"q": "このレッスンで特定された人工宗教の特徴には，どのようなものがありますか。（複数選択可）", "s": "宗教の特徴", "a": "A|B|C", "o": "A.人を神聖にする,B.「動作していない」で判断,C.神と人との関係は人自身が決める,D.神の積極的な真理の啓示"}, {"q": "キリスト教の信仰は，信仰は人生に困難を抱えている人だけのものであると信じています。", "s": "信じる者", "a": "×"}, {"q": "このレッスンによると，人々と正しい関係を築くことを切望している真の神がいます。", "s": "唯一の真の神", "a": "○"}, {"q": "このレッスンでは、キリスト教は西洋から来た西洋の宗教であると主張します。", "s": "地域外の信念", "a": "×"}, {"q": "なぜ人工宗教では、真の神を判断する基準として「霊性」を用いることができないのか。このレッスンと併せて説明してください。", "s": "サイキック・スタンダード", "a": "人造宗教的神是人造出来的，标准由人定：所求的成就了就继续拜，不灵就换一个，把神当成解决问题的工具，用完即弃。若真有一位神，祂的智慧能力都比人高，就应是人听祂、由祂带领，而不是人定标准差遣祂。真正的信仰是人与创造宇宙的真神建立互动的关系，不是拿神当仆人使唤。"}, {"q": "このレッスンでは、「椅子」のメタファーをどのように使用して、宇宙には創造主がいる必要があることを説明しますか？", "s": "椅子のたとえ話", "a": "没有人见过造椅子的人，却都相信椅子必有人设计制造，不会相信它是偶然自然出现的。宇宙比椅子精密无数倍——地球以23.5度倾斜规律运转、绕太阳一周就是一年、银河系中唯有地球适合人居住——更不可能是无目的的偶然。正如圣经所说：「自从造天地以来，神的永能和神性是明明可知的。」"}]}, "ko": {"title": "제1과 왜 사람에게 하나님이 필요한가?", "content": "신앙은 어려울 때의 위로가 아니라 인간과 우주를 창조하신 참 하나님 사이의 상호 작용적인 관계입니다. 이 수업에서는 인위적인 종교와 기독교의 근본적인 차이를 파악하고, 우주의 법칙에서 참된 하나님에 대해 배우고, 신앙에 대한 공리주의적 관점에서 벗어납니다. 이 진리가 여러분의 신앙의 굳건한 기초가 되기를 바랍니다.", "instructions": "", "guide": [{"title": "신앙은 어려운 사람들만을 위한 것이 아닙니다.", "points": ["어떤 사람들은 하나님은 실업자, 결혼하지 않은 자, 패배한 자에게만 위로가 된다고 생각합니다. 성공한 사람들은 하나님을 필요로 하지 않습니다.", "영화 \"탕산 지진\" 에서 사람들은 불가항력에 직면하여 \"신이시여, 무슨 일을 하십니까\" 라고 외칩니다.", "기독교는 믿음이 인간과 우주를 창조하신 참 하나님 사이의 상호 작용이라고 가르칩니다."]}, {"title": "신은 알라딘의 등불이 아니다", "points": ["만약 신이 문제를 해결하고 나서 당직자처럼 떠난다면, 그런 신은 매우 이상합니다.", "사람들은 하나님과의 관계에 덜주의를 기울이고 원하는 대상의 \"영성\" 에만주의를 기울입니다.", "기독교는 사용이 아닌 인간과 하나님 사이의 진정한 관계를 강조합니다."]}, {"title": "부모와 자녀의 유추", "points": ["부모를 이끄는 자녀, 항상 자녀를 이끄는 부모에 대해 들어 본 적이 없습니다", "아이들은 반드시 부모의 훈육을 좋아하지는 않지만, 그것이 아이들에게 정말로 필요한 것입니다.", "하나님 아버지께서 우리와 맺으신 관계도 마찬가지입니다. 그분은 우리가 그분에 대한 기준을 세우는 것이 아니라 우리를 인도하십니다."]}, {"title": "종교와 기독교의 차이점", "points": ["종교는 사람의 입장에서 하나님을 찾는 것이니 찾지 못하면 하나님을 창조하고 사람을 신격화할 수 있습니다.", "다양한 종교가 황제와 신과 같은 고대 위인과 성인을 신격화하고 있으며, 그리스 신화는 신으로 가득합니다.", "기독교는 우주에 인간의 존재가 아닌 자신의 존재를 드러내시는 하나님이 실제로 존재하신다는 것입니다."]}, {"title": "우주의 법칙은 하나님의 존재를 증거합니다", "points": ["로마서 1:20: 천지가 창조된 이래로 하나님의 영원하신 능력과 신성이 분명하게 알려졌습니다.", "의자 비유: 아무도 의자가 우발적이라고 생각하지 않습니다. 우주의 정밀도는 말할 것도 없습니다.", "열역학 제 2 법칙은 지구의 23.5도 기울기와 회전 뒤에 디자이너가 있음을 보여줍니다."]}, {"title": "신은 서양에만 속하지 않는다", "points": ["인류 역사에 들어오신 하나님은 반드시 한 곳을 선택하셔야 하며, 팔레스타인에서 이스라엘을 선택하셨습니다.", "이스라엘은 다른 사람들보다 우월하다는 것이 아니라 하나님의 진리 계시의 통로로 선택되었습니다.", "하나님께서는 세상 모든 사람들을 사랑하시는 것만큼 이스라엘 백성을 사랑하십니다."]}, {"title": "이스라엘을 통해 하나님과 사람들을 알아가기", "points": ["이스라엘을 통해 하나님을 아는 것: 자비, 동정심, 친절, 의로움, 거룩함", "출애굽기 34장 6절: 하나님은 은혜로우시고 자비로우시며, 쉽게 분노하지 않으시고, 죄에 대해 결백하지 않으십니다.", "인간은 자기 중심적이며 많은 문제를 만듭니다. 하나님은 인간과 하나님 사이의 문제를 근본적으로 해결하기를 원하십니다."]}], "quizzes": [{"q": "[경전 빈칸 채우기] 하늘과 땅이 창조 된 이래로 하나님의 ________ 와 ________ 은 눈에 보이지 않지만 피조물을 통해 알 수 있으므로 사람들을 부인할 수 없습니다.", "s": "피조물이 하나님을 드러냄", "a": "영원하신 능력|신성"}, {"q": "[Scripture Fill in the Blank] 여호와, 여호와, ________ 의 하나님이 계시고, ________ 가 계시고, 쉬운 분노가 없고, 풍부한 사랑과 정직이 있습니다.", "s": "하나님의 속성", "a": "긍휼|은혜"}, {"q": "[Scripture Fill in the Blank] 하늘은 하나님의 ________ 을 말하고, 하늘은 그의 ________", "s": "만국 서술", "a": "영광|수단"}, {"q": "기독교 신앙은 인위적인 종교의 산물이 아니라 하나님의 ________ 의 진리입니다.", "s": "요한계시록에 나타난 신앙", "a": "계시"}, {"q": "종교는 사람들이 하나님을 찾고, 찾고, 창조하고, 신화하기 위해 자신의 관점에 서있을 때입니다. ________", "s": "인공 신", "a": "사람"}, {"q": "인간이 만든 종교에서 신이 숭배받을 가치가 있는지 여부를 판단하는 기준은 \"________ 작동하지 않음\" 입니다.", "s": "심령 기준", "a": "영"}, {"q": "하나님의 지혜의 능력이 우리보다 높기 때문에 인간과 하나님의 올바른 관계는 하나님이 우리의 말을 들으시는 것이 아니라 하나님의 말씀을 ________ 듣는 것입니다.", "s": "누가 누구의 말을 경청하는가", "a": "우리"}, {"q": "무한하신 하나님은 이스라엘 민족을 통해 진리를 계시하기 위해 그의 지혜로 ________ 팔레스타인을 선택하여 인류의 유한한 역사 속으로 들어오십니다.", "s": "신의 선택", "a": "중동"}, {"q": "의자에 그것을 만든 사람이 있어야 하듯이, 우주의 정밀 법칙에는 ________", "s": "우주 장인", "a": "창조주"}, {"q": "이 교훈에 따르면, 기독교 신앙과 일반 종교의 근본적인 차이점은 무엇입니까?", "s": "계시와 인위성", "a": "B", "o": "A.기독교의 더 긴 역사,B.기독교는 인간이 만든 종교가 아니라 신성하게 계시된 진리입니다.,C.기독교 의식은 더 엄숙합니다,D.기독교에 대한 더 많은 신자"}, {"q": "왜 우리는 “하나님을 보여 주시면 믿겠습니다” 라고 말할 수 없는가?", "s": "하나님은 종이 아니십니다.", "a": "B", "o": "A.신이 존재하지 않기 때문에,B.참 하나님은 소환되어 흔들릴 수 있는 종이 아닙니다.,C.하나님은 우리에게서 너무 멀리 떨어져 계시기 때문입니다.,D.왜냐하면 과학자들은 아직 하나님을 찾지 못했기 때문입니다."}, {"q": "이 수업에서 언급했듯이, 이스라엘 민족과의 상호 작용을 통해 하나님은 인류에게 어떤 종류의 하나님이 되셨습니까?", "s": "하나님의 속성", "a": "B", "o": "A.오직 능력, 인자함 없음,B.자비, 동정심, 그리고 의로움과 거룩함,C.의로움에 대해서만 말하고 자비에 대해서는 말하지 마십시오.,D.미스터리하고 알 수 없는"}, {"q": "이 수업에서 창조주를 드러내는 우주 현상은 무엇인가? (복수 선택)", "s": "우주의 증인", "a": "A|B|C", "o": "A.지구는 23.5도 기울기에서 움직입니다.,B.광활한 은하계에서 유일하게 거주 가능한 행성,C.열역학 제2법칙은 법칙이 우연이 아니라 설계에서 나온다고 말한다.,D.달 표면은 분화구로 가득 차 있습니다"}, {"q": "이 수업에서 확인된 인공 종교의 특징은 무엇인가? (복수 선택)", "s": "종교의 특징", "a": "A|B|C", "o": "A.인격을 신성시함,B.\"작동하지 않음\" 으로 판단,C.하나님과 인간의 관계는 인간 스스로가 결정한다.,D.하나님의 적극적인 진리 계시"}, {"q": "그리스도교 신앙은 신앙이 삶에서 어려움을 겪는 사람들만을 위한 것이라고 믿습니다.", "s": "믿음의 대상", "a": "×"}, {"q": "이 교훈에 따르면, 사람들과 올바른 관계를 갖기를 갈망하는 진정한 하나님은 한 분뿐입니다.", "s": "유일무이한 참 하나님", "a": "○"}, {"q": "이 과는 기독교가 서양에서 온 서양 종교라고 주장한다.", "s": "비지역적 신념", "a": "×"}, {"q": "인위적인 종교에서 ''영성'' 이 참 하나님을 판단하는 기준으로 사용될 수 없는 이유는 무엇입니까? 이 수업과 함께 설명해 주십시오.", "s": "심령 기준", "a": "人造宗教的神是人造出来的，标准由人定：所求的成就了就继续拜，不灵就换一个，把神当成解决问题的工具，用完即弃。若真有一位神，祂的智慧能力都比人高，就应是人听祂、由祂带领，而不是人定标准差遣祂。真正的信仰是人与创造宇宙的真神建立互动的关系，不是拿神当仆人使唤。"}, {"q": "이 수업에서는 우주에 창조주가 있어야 함을 설명하기 위해 \"의자\" 비유를 어떻게 사용합니까?", "s": "의자의 비유", "a": "没有人见过造椅子的人，却都相信椅子必有人设计制造，不会相信它是偶然自然出现的。宇宙比椅子精密无数倍——地球以23.5度倾斜规律运转、绕太阳一周就是一年、银河系中唯有地球适合人居住——更不可能是无目的的偶然。正如圣经所说：「自从造天地以来，神的永能和神性是明明可知的。」"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1772717037643','基要真理','第二课 罪为何物？','罪的标准是神的标准，连心中的恨人与贪念都是罪。本课讲罪的本质、根源与普世性，说明人人都在罪中，以及神为罪人预备的唯一出路。愿你真正认识罪的严重，珍惜救恩。','[{"type": "verse", "q": "【经文填空】你们得救是本乎________，也因着________；这并不是出于自己，乃是神所赐的", "o": "《以弗所书》2章8节", "s": "本乎恩信", "a": "恩|信"}, {"type": "verse", "q": "【经文填空】因为世人都犯了________，亏缺了神的________", "o": "《罗马书》3章23节", "s": "世人都犯了罪", "a": "罪|荣耀"}, {"type": "verse", "q": "【经文填空】凡看见妇女就动________的，这人心里已经与她犯________了", "o": "《马太福音》5章28节", "s": "内心的罪", "a": "淫念|奸淫"}, {"type": "fill", "q": "国家法律只能采取________标准，守住了法律不等于在神的标准下无罪", "o": "", "s": "法律标准", "a": "低"}, {"type": "fill", "q": "圣经所定义的罪不只看外在行为，更包括人的________和意念", "o": "", "s": "罪的定义", "a": "思想"}, {"type": "fill", "q": "按圣经的标准，心里恨人就等于犯了________的罪", "o": "", "s": "恨如杀人", "a": "杀人"}, {"type": "fill", "q": "孩子无人教导就会显出争抢悖逆，证明人里面有________的根源", "o": "", "s": "罪的根源", "a": "罪"}, {"type": "fill", "q": "刘备告诫孩子「________以恶小而为之」，提醒小罪会累积延伸成大罪", "o": "", "s": "小罪与大罪", "a": "勿"}, {"type": "fill", "q": "基督徒承认自己是________的罪人，而不是自认圣洁去定罪别人", "o": "", "s": "蒙恩的罪人", "a": "蒙恩"}, {"type": "single", "q": "本课说，人觉得自己「不是罪人」的根本原因是什么？", "o": "A.人真的没有罪,B.人用国家法律的低标准来衡量自己,C.神的标准太低了,D.罪在今天已经不存在了", "s": "罪的标准", "a": "B"}, {"type": "single", "q": "关于苦难与犯罪的关系，本课的立场是什么？", "o": "A.受苦的人一定是因为犯了罪,B.不能把个人的遭遇与犯罪直接挂钩来定罪,C.基督徒不会遭遇苦难,D.天灾都是神对罪人的惩罚", "s": "苦难与罪", "a": "B"}, {"type": "single", "q": "本课提到小罪与大罪的关系是怎样的？", "o": "A.小罪无所谓，不用在意,B.大罪都是突然发生的，与小罪无关,C.大罪多是小罪累积延伸的结果,D.只有大罪才是真正的罪", "s": "小罪与大罪", "a": "C"}, {"type": "multiple", "q": "按本课，圣经把哪些内心状态也定义为罪？（多选）", "o": "A.恨人,B.看见妇女就动非分之想,C.贪念,D.孝顺父母", "s": "内心的罪", "a": "A|B|C"}, {"type": "multiple", "q": "本课指出，罪带来哪些层面的破坏？（多选）", "o": "A.人与神的关系破裂,B.人与人之间紧张冲突,C.天灾人祸,D.犯罪者立刻遭到报应", "s": "罪的后果", "a": "A|B|C"}, {"type": "judge", "q": "按本课，国家法律是高标准，守住法律就等于在神面前无罪。", "o": "", "s": "法律标准", "a": "错"}, {"type": "judge", "q": "本课认为，孩子生来就有的悖逆争抢显明了罪的根源。", "o": "", "s": "原罪的证据", "a": "对"}, {"type": "judge", "q": "基督徒面对灾难中的受苦者，应当做定罪者而不是支援者。", "o": "", "s": "怜悯的心", "a": "错"}, {"type": "essay", "q": "为什么基督徒说「我是罪人」不是在定别人的罪？请结合本课说明。", "o": "", "s": "蒙恩的罪人", "a": "基督徒说「我是罪人」，是先承认自己在神的高标准下也是亏缺的，是「蒙恩的罪人」，而不是自认圣洁去审判别人。神的标准连思想意念都涵盖，无人能达到；但神爱世人，已在十字架上为我们付了代价，人只要凭信心接受，就能出黑暗入光明。传讲罪，是为了让人认识自己真正的需要、领受救恩，而不是定罪。"}, {"type": "essay", "q": "本课为什么反对把个人的苦难遭遇直接解释为犯罪的结果？", "o": "", "s": "苦难与罪", "a": "圣经没有启示苦难与个人犯罪之间有必然的对应关系，重大天灾人祸发生时基督徒从未被豁免。若以受苦定罪，普世无人能例外。本课主张：面对受苦者不做定罪者，而做支援者，发挥神所赐怜悯的心去帮助；同时人应在神的怜悯中自省，把握现今的处境好好而活。"}]','https://youtu.be/CZRXWhS3Ybc
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134ToDT','quiz','[{"points": ["一般人以为救赎是解决失业、健康、婚姻等现实问题", "基督信仰讲的救赎不是治标，而是治本：解决罪的问题", "基督徒常说落在罪的捆绑中，需要出黑暗入光明"], "title": "救赎是治本而非治标"}, {"points": ["国家法律只能采取低标准，也就是最起码的共同规范", "孝顺父母、夫妻彼此敬重，法律无法规范", "我们在低标准下自认无罪，但在神的高标准下人人都不完全"], "title": "何谓罪：标准不同"}, {"points": ["世人说杀人才是罪，圣经说恨人就是罪", "世人说犯奸淫才是罪，圣经说动淫念就是犯罪", "世人说贪污才是罪，圣经说有贪心就是犯罪；人者心之器也"], "title": "罪包括思想意念"}, {"points": ["亚当夏娃违背神，罪就入了世界，影响至今", "孩子无人教就会争玩具、哭闹、悖逆，显出与生俱来的劣根性", "“人之初性本善”无法解释这些现象，印证罪有根源"], "title": "原罪的证据：孩子"}, {"points": ["刘备告诫孩子：勿以恶小而为之，勿以善小而不为", "差之毫厘，失之千里；小地方不注意，以后延伸很大", "贪心投机致倾家荡产、对婚姻不忠有钱后出轨，都是小罪累积"], "title": "小罪累积成大罪"}, {"points": ["天灾人祸发生时，基督徒从未被豁免于难", "若犯罪必遭祸，全世界的人都在此范畴，不能轻易定罪他人", "正确态度：谦卑自省、珍惜神的怜悯，并以怜悯去支援受灾者"], "title": "不把遭遇与犯罪挂钩"}, {"points": ["罪使神人关系破裂，为人预备的环境受咒诅", "人与人之间也变得紧张、冲突，甚至战争", "基督徒是蒙恩的罪人；得救本乎恩，也因着信，白白领受"], "title": "蒙恩的罪人"}]','','2','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 2 What is sin?", "content": "The standard of sin is the standard of God. Even hatred and covetousness in the heart are sins. This lesson on the nature, roots, and universality of sin illustrates that everyone is in sin and the only way God has prepared for sinners. May you truly recognize the gravity of sin and cherish salvation.", "instructions": "", "guide": [{"title": "Redemption addresses the root cause, not just the symptoms.", "points": ["The average person thinks that redemption is the solution to real problems such as unemployment, health, marriage, etc.", "Christianity speaks of salvation not as a cure, but as a cure for the root cause: the problem of solving sin", "Christians often say that falling into the bondage of sin requires coming out of the darkness into the light."]}, {"title": "What is Sin: Different Standards", "points": ["National laws can only adopt low standards, that is, minimum common norms", "Dutiful parents, husbands and wives respect each other, and the law cannot regulate", "We confess our innocence under low standards, but no one is perfect under God''s high standards."]}, {"title": "Sin includes thoughts and ideas", "points": ["The world says that killing people is a sin, and the Bible says that hating people is a sin.", "The world says that committing adultery is a sin, and the Bible says that lust is a crime.", "The world says that embezzlement is sin, and the Bible says that greed is sin; the weapon of the human heart is also"]}, {"title": "Evidence of original sin: child", "points": ["Adam and Eve rebelled against God, and sin entered the world, affecting the world to this day.", "Children who are uneducated will fight for toys, cry, and rebel, showing their innate inferiority.", "\"Human nature is inherently good\" cannot explain these phenomena, proving that there are roots in sin."]}, {"title": "Small sins accumulate into big sins", "points": ["Liu Bei warns children: Do not do it with small evil, do not do it with small good", "A difference of milliseconds, a loss of thousands of miles; small places do not pay attention, and it will stretch a lot in the future", "Greedy speculation leads to bankruptcy, cheating after being unfaithful to the marriage and rich, all of which are accumulated petty crimes."]}, {"title": "Don''t link encounters to crime", "points": ["When natural and man-made disasters occur, Christians are never exempt from them.", "If the crime is bound to suffer, people all over the world are in this category and can not easily convict others", "Correct attitude: Humble yourself, cherish God''s mercy, and support those affected by the disaster with mercy"]}, {"title": "Gracious Sinner", "points": ["Sin breaks the relationship between God and man, and the environment prepared for man is cursed.", "tensions, conflicts and even wars between people.", "Christians are gracious sinners; salvation by grace and by faith is freely received"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] Your salvation is from ________, and because ________; it is not from yourselves, but from God", "s": "By grace, through faith", "a": "grace|faith"}, {"q": "[Scripture Fill in the Blank] Because the world has committed ________, it lacks God''s ________", "s": "The Guilt of the Whole World", "a": "sin|glory"}, {"q": "[Scripture Fill in the Blank] Anyone who sees a woman and moves ________ has already committed ________ with her in their heart.", "s": "Inner Sin", "a": "lust|adultery"}, {"q": "National law can only adopt the ________ standard, and keeping the law does not mean being innocent under God''s standard.", "s": "Legal standards", "a": "low"}, {"q": "Scripture defines sin not only in terms of outward actions, but also in terms of people''s ________ and thoughts.", "s": "Definition of Crime", "a": "thought"}, {"q": "According to biblical standards, hatred in one''s heart is tantamount to committing ________ sins.", "s": "Hate is like killing", "a": "murder"}, {"q": "If the child is not taught, it will show contention and disobedience, proving that there is a root of ________ in the person", "s": "Causes of Sin", "a": "sin"}, {"q": "Liu Bei warned the child that \"________ is small for evil\", reminding that minor sins will cumulatively extend to major sins.", "s": "Petty and Major Sins", "a": "勿"}, {"q": "Christians confess that they are sinners of ________, rather than professing holiness to condemn others", "s": "Gracious Sinner", "a": "receiving grace"}, {"q": "What does this lesson say is the root cause of why people feel they are “not sinners”?", "s": "Criteria for Sin", "a": "B", "o": "A.People are really not guilty,B.People measure themselves by the low standards of national law,C.God''s standards are too low,D.Sin no longer exists today"}, {"q": "What is your position on the relationship between suffering and crime in this lesson?", "s": "Suffering and Sin", "a": "B", "o": "A.Sufferers must be guilty of sin,B.Individuals cannot be convicted by linking their suffering directly to the crime,C.Christians will not suffer,D.Natural disasters are God''s punishment for sinners."}, {"q": "What is the relationship between minor and major sins mentioned in this lesson?", "s": "Petty and Major Sins", "a": "C", "o": "A.It doesn''t matter what the petty crime is, don''t worry about it,B.Major sins are sudden and have nothing to do with minor sins.,C.Major sins are mostly the result of the cumulative extension of minor sins,D.Only great sins are true sins."}, {"q": "According to this lesson, what inner states of mind does the Bible also define as sin? (Multiple choice)", "s": "Inner Sin", "a": "A|B|C", "o": "A.Hate people,B.When you see a woman, you are impatient.,C.greedy idea,D.Dutiful Parents"}, {"q": "In this lesson, what are some of the aspects of destruction that come from sin? (Multiple choice)", "s": "Sin’s consequences?", "a": "A|B|C", "o": "A.Fractured relationship between man and God,B.Interpersonal tensions,C.natural and man-made disaster,D.Immediate retribution for the perpetrator"}, {"q": "According to this lesson, national law is a high standard, and keeping the law is equivalent to not being guilty before God.", "s": "Legal standards", "a": "False"}, {"q": "In this lesson, we believe that the rebellious struggle that children are born with reveals the root cause of sin.", "s": "Evidence of original guilt", "a": "True"}, {"q": "Christians should be condemners rather than supporters in the face of suffering in the midst of tribulation.", "s": "Heart of Compassion", "a": "False"}, {"q": "Why is it that Christians who say “I am a sinner” do not condemn others? Please combine the instructions in this lesson.", "s": "Gracious Sinner", "a": "基督徒说「我是罪人」，是先承认自己在神的高标准下也是亏缺的，是「蒙恩的罪人」，而不是自认圣洁去审判别人。神的标准连思想意念都涵盖，无人能达到；但神爱世人，已在十字架上为我们付了代价，人只要凭信心接受，就能出黑暗入光明。传讲罪，是为了让人认识自己真正的需要、领受救恩，而不是定罪。"}, {"q": "Why does this lesson object to the direct interpretation of a person''s suffering as the result of a crime?", "s": "Suffering and Sin", "a": "圣经没有启示苦难与个人犯罪之间有必然的对应关系，重大天灾人祸发生时基督徒从未被豁免。若以受苦定罪，普世无人能例外。本课主张：面对受苦者不做定罪者，而做支援者，发挥神所赐怜悯的心去帮助；同时人应在神的怜悯中自省，把握现今的处境好好而活。"}]}, "ja": {"title": "レッスン2罪とは何か？", "content": "罪の旗は神の旗です。心の中の憎しみや貪欲さでさえも罪です。罪の性質，根源，普遍性に関するこのレッスンは，すべての人が罪の中にあり，神が罪人のために備えられた唯一の方法であることを示しています。あなたが真に罪の重さを認識し，救いを大切にしてくださいますように。", "instructions": "", "guide": [{"title": "贖いは癒しであって、癒しではありません。", "points": ["平均的な人は、償還は失業、健康、結婚などの実際の問題の解決策であると考えています。", "キリスト教は救いを癒しとしてではなく、根本原因の癒しとして語ります：罪を解決する問題", "クリスチャンはしばしば，罪の束縛に陥るには，暗闇から光の中に出る必要があると言います。"]}, {"title": "罪とは何か：異なる基準", "points": ["国内法は低基準、すなわち最低限の共通規範のみを採用できます", "義務のある両親、夫、妻はお互いを尊重し、法律で規制することはできません", "私たちは低い基準の下で自分の無実を告白しますが、神の高い基準の下で完璧な人はいません。"]}, {"title": "罪には考えやアイデアが含まれます", "points": ["世界は人を殺すことは罪であると言い、聖書は人を憎むことは罪であると言います。", "世界は姦淫を犯すことは罪であると言い、聖書は欲望は犯罪であると言います。", "世界は横領は罪であると言い、聖書は貪欲は罪であると言います。人間の心の武器は"]}, {"title": "原罪の証拠：子供", "points": ["アダムとエバは神に背き，罪が世に入り，今日まで世に影響を与えています。", "教育を受けていない子供たちは、おもちゃのために戦ったり、泣いたり、反抗したりして、生来の劣等感を示します。", "「人間の本性は本質的に善である」は、これらの現象を説明することができず、罪の根源があることを証明しています。"]}, {"title": "小さな罪が大きな罪に蓄積されます", "points": ["劉備は子供たちに警告する：小さな悪でそれをしないでください、小さな善でそれをしないでください", "ミリ秒の差、数千マイルの損失。小さな場所は注意を払わず、将来的には多くのことが起こります", "貪欲な憶測は破産につながり、結婚や金持ちに不貞を働いた後に浮気をします。これらはすべて、蓄積された軽犯罪です。"]}, {"title": "遭遇を犯罪と結びつけないでください", "points": ["自然災害や人為的災害が発生した場合，クリスチャンはそれらから免除されることはありません。", "犯罪が苦しむことになる場合、世界中の人々がこのカテゴリーに属しており、簡単に他の人に有罪判決を下すことはできません", "正しい態度：謙遜になり、神の憐れみを大切にし、災害の影響を受けた人々を憐れみをもって支援する"]}, {"title": "優雅な罪人", "points": ["罪は神と人間の関係を壊し、人間のために用意された環境は呪われます。", "人々の間の緊張、紛争、さらには戦争さえあります。", "クリスチャンは恵み深い罪人であり、恵みと信仰による救いは自由に受け入れられます"]}], "quizzes": [{"q": "[Scripture Fill in the Blank]あなたの救いは________からであり、________からではありません。それはあなた自身からではなく、神からです。", "s": "円心のエッセンス", "a": "恵み|信仰"}, {"q": "[Scripture Fill in the Blank]世界は________を犯しているので、神の________に欠けています", "s": "全世界が罪を犯しました。", "a": "罪|栄光"}, {"q": "[Scripture Fill in the Blank]女性を見て________を動かす人は，すでに________を心に抱いています。", "s": "内なる罪", "a": "淫らな思い|姦淫"}, {"q": "国内法は________の基準のみを採用することができ、法律を守ることは神の基準の下で無実であることを意味するものではありません。", "s": "法的基準", "a": "低い"}, {"q": "聖書は，外向きの行動だけでなく，人々の________や考えの観点からも罪を定義しています。", "s": "犯罪の定義", "a": "思い"}, {"q": "聖書の基準によれば，心の中の憎しみは________の罪を犯すことに等しいのです。", "s": "憎しみは殺すことに似ています", "a": "殺人"}, {"q": "子供が教えられていない場合、それは争いと不従順を示し、その人に________の根があることを証明します", "s": "罪の原因", "a": "罪"}, {"q": "劉備は、「________は悪にとって小さい」と子供に警告し、小さな罪が累積して大きな罪に及ぶことを思い出させました。", "s": "軽い罪と重大な罪", "a": "勿"}, {"q": "クリスチャンは、他者を非難するために聖性を告白するのではなく、自分が________の罪人であることを告白する", "s": "優雅な罪人", "a": "恵みを受けた"}, {"q": "このレッスンでは，人々が「罪人ではない」と感じる根本的な原因は何だと述べていますか。", "s": "罪の基準", "a": "B", "o": "A.人々は本当に無罪です,B.人々は国内法の低い基準で自分自身を評価します,C.神の基準が低すぎる,D.SINは今日は存在しません"}, {"q": "このレッスンでは，苦しみと犯罪の関係についてどのような立場をとりますか。", "s": "苦しみと罪", "a": "B", "o": "A.被害者は罪を犯さなければなりません,B.個人は、彼らの苦しみを犯罪に直接結びつけることによって有罪判決を受けることはできません,C.クリスチャンは苦しむことはありません,D.自然災害は、罪人に対する神の罰です。"}, {"q": "この課で言及されている軽い罪と大きな罪の関係はどのようなものですか。", "s": "軽い罪と重大な罪", "a": "C", "o": "A.ちっぽけな犯罪なんてどうでもいい、気にしなくていい,B.大きな罪は突然のもので，小さな罪とは何の関係もありません。,C.主な罪は、主に軽微な罪の累積的な延長の結果です,D.大きな罪だけが真の罪です。"}, {"q": "このレッスンによると，聖書はどのような心の内側の状態を罪と定義していますか。（複数選択可）", "s": "内なる罪", "a": "A|B|C", "o": "A.人を憎む,B.女性を見ると、焦ってしまいます。,C.貪欲,D.義務感のある両親"}, {"q": "この課では，罪から来る破壊の側面にはどのようなものがあるでしょうか。（複数選択可）", "s": "罪の結果", "a": "A|B|C", "o": "A.人間と神の壊れた関係,B.対人的緊張,C.自然災害と人為的災害,D.加害者への即時報復"}, {"q": "このレッスンによると、国内法は高い水準であり、法律を守ることは神の前で罪を犯さないことと同等です。", "s": "法的基準", "a": "×"}, {"q": "この課では，子供が生まれるときに伴う反抗的な闘争が，罪の根本的な原因を明らかにすると信じています。", "s": "元の有罪の証拠", "a": "○"}, {"q": "苦難の中での苦しみに直面しているクリスチャンは、支援者ではなく非難者であるべきです。", "s": "思いやりの心", "a": "×"}, {"q": "「わたしは罪人である」と言うクリスチャンが他の人を非難しないのはなぜですか。このレッスンの指示を組み合わせてください。", "s": "優雅な罪人", "a": "基督徒说「我是罪人」，是先承认自己在神的高标准下也是亏缺的，是「蒙恩的罪人」，而不是自认圣洁去审判别人。神的标准连思想意念都涵盖，无人能达到；但神爱世人，已在十字架上为我们付了代价，人只要凭信心接受，就能出黑暗入光明。传讲罪，是为了让人认识自己真正的需要、领受救恩，而不是定罪。"}, {"q": "なぜこのレッスンは、犯罪の結果としての人の苦しみの直接的な解釈に反対するのでしょうか？", "s": "苦しみと罪", "a": "圣经没有启示苦难与个人犯罪之间有必然的对应关系，重大天灾人祸发生时基督徒从未被豁免。若以受苦定罪，普世无人能例外。本课主张：面对受苦者不做定罪者，而做支援者，发挥神所赐怜悯的心去帮助；同时人应在神的怜悯中自省，把握现今的处境好好而活。"}]}, "ko": {"title": "제 2과 죄란 무엇인가?", "content": "죄의 기준은 하나님의 기준입니다. 마음의 미움과 탐심도 죄입니다. 죄의 본질, 뿌리 및 보편성에 대한 이 교훈은 모든 사람이 죄에 빠져 있으며 하나님께서 죄인을 위해 준비하신 유일한 방법임을 보여줍니다. 여러분이 진정으로 죄의 중대성을 인식하고 구원을 소중히 여길 수 있기를 바랍니다.", "instructions": "", "guide": [{"title": "구속은 치료법이지 치료법이 아닙니다.", "points": ["보통 사람들은 구속이 실업, 건강, 결혼 등과 같은 실제 문제에 대한 해결책이라고 생각합니다.", "기독교는 구원을 치료가 아니라 근본 원인, 즉 죄를 해결하는 문제의 치료로 말합니다.", "그리스도인들은 종종 죄의 속박에 빠지려면 어둠에서 빛으로 나와야 한다고 말합니다."]}, {"title": "죄란 무엇인가: 다양한 기준", "points": ["국내법은 낮은 기준, 즉 최소 공통 규범만 채택할 수 있습니다.", "정직한 부모와 남편과 아내는 서로를 존중하며, 법이 규율할 수 없습니다.", "우리는 낮은 기준에서 우리의 무죄를 고백하지만, 하나님의 높은 기준 하에서 완벽한 사람은 없습니다."]}, {"title": "죄에는 생각과 아이디어가 포함됩니다", "points": ["세상은 사람을 죽이는 것이 죄라고 하고, 성경은 사람을 미워하는 것이 죄라고 합니다.", "세상은 간음은 죄라고 하고, 성경은 정욕은 죄라고 합니다.", "세상은 횡령이 죄라고 말하고, 성경은 탐욕이 죄라고 말합니다. 인간 마음의 무기도"]}, {"title": "원죄의 증거: 자녀", "points": ["아담과 이브는 하나님을 거역했고, 죄가 세상에 들어와 오늘날까지 세상에 영향을 미쳤습니다.", "교육을 받지 못한 아이들은 장난감, 울음, 반항을 위해 싸우며 타고난 열등감을 드러냅니다.", "\"인간의 본성은 본질적으로 선하다\" 는 것은 이러한 현상을 설명 할 수 없으므로 죄에 뿌리가 있음을 증명합니다."]}, {"title": "작은 죄가 큰 죄로 축적됨", "points": ["Liu Bei는 어린이들에게 경고합니다: 작은 악으로하지 말고 작은 선으로하지 마십시오.", "밀리 초의 차이, 수천 마일의 손실; 작은 장소는주의를 기울이지 않으며, 앞으로 많이 늘어날 것입니다.", "탐욕과 투기로 인한 재정적 파탄, 그리고 혼외정사를 통해 부를 축적한 후 저지르는 부정행위는 모두 작은 죄악이 쌓여가는 예입니다."]}, {"title": "만남을 범죄와 연결하지 마세요", "points": ["자연 재해와 인공 재해가 발생하면 그리스도인은 결코 그것에서 면제되지 않습니다.", "범죄가 발생할 수밖에 없는 경우, 전 세계 사람들은 이 범주에 속하며 다른 사람들을 쉽게 유죄 판결할 수 없습니다.", "올바른 태도: 자신을 낮추고, 하나님의 자비를 소중히 여기며, 재난으로 피해를 입은 사람들을 자비로이 지원하십시오."]}, {"title": "은혜로운 죄인", "points": ["죄는 하나님과 인간의 관계를 깨뜨리고, 인간을 위해 준비된 환경은 저주를 받습니다.", "긴장, 갈등, 심지어 사람들 사이의 전쟁까지.", "그리스도인은 은혜로운 죄인입니다. 은혜와 믿음으로 얻는 구원은 자유롭게 받습니다."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 당신의 구원은 ________ 로부터 온 것이며, ________ 때문에, 그것은 당신 자신에게서가 아니라 하나님으로부터 온 것입니다.", "s": "엔신의 정수", "a": "은혜|믿음"}, {"q": "[Scripture Fill in the Blank] 세상은 ________ 을 (를) 저질렀기 때문에 하나님의 ________ 이 (가) 부족합니다.", "s": "온 세상이 죄를 지었습니다.", "a": "죄|영광"}, {"q": "여자를 보고 ________ 품는 자는 누구나 이미 마음으로 그 여자와 ________하였느니라", "s": "내신", "a": "음욕|간음"}, {"q": "국내법은 ________ 표준만 채택할 수 있으며, 법을 지킨다고 해서 하나님의 표준에 따라 무죄가 되는 것은 아닙니다.", "s": "법적 기준", "a": "낮은"}, {"q": "성경은 죄를 외적인 행동뿐만 아니라 사람들의 ________ 과 생각의 관점에서 정의합니다.", "s": "범죄의 정의", "a": "생각"}, {"q": "성경의 기준에 따르면, 마음에 있는 증오는 ________ 죄를 짓는 것과 같습니다.", "s": "증오는 죽이는 것과 같습니다.", "a": "살인"}, {"q": "아이를 가르치지 않으면 다툼과 불복종을 보여 그 사람에게 ________ 의 뿌리가 있음을 증명합니다.", "s": "죄의 원인", "a": "죄"}, {"q": "리우 베이 (Liu Bei) 는 아이에게 \"________ 은 (는) 악을 위해 작다\" 고 경고하면서 사소한 죄가 누적되어 주요 죄까지 확장될 것임을 상기시켰다.", "s": "하찮은 죄와 주요 죄", "a": "勿"}, {"q": "그리스도인들은 다른 사람들을 정죄하기 위해 거룩함을 고백하기보다는 ________ 의 죄인임을 고백합니다.", "s": "은혜로운 죄인", "a": "은혜를 받은"}, {"q": "이 수업은 사람들이 “죄인이 아니다” 라고 느끼는 근본 원인은 무엇이라고 말하는가?", "s": "죄의 기준", "a": "B", "o": "A.사람들은 정말 죄가 없습니다,B.사람들은 국가법의 낮은 기준에 따라 스스로를 측정합니다.,C.하나님의 기준이 너무 낮음,D.오늘날 SIN은 더 이상 존재하지 않습니다"}, {"q": "이 수업에서 고통과 범죄의 관계에 대한 귀하의 입장은 무엇입니까?", "s": "고통과 죄", "a": "B", "o": "A.고통받는 사람은 죄가 있어야 합니다,B.개인은 자신의 고통을 범죄와 직접 연결하여 유죄 판결을받을 수 없습니다.,C.그리스도인들은 고통받지 않을 것입니다.,D.자연재해는 죄인에 대한 하나님의 형벌입니다."}, {"q": "이 수업에서 언급된 사소한 죄와 주요 죄의 관계는 무엇인가?", "s": "하찮은 죄와 주요 죄", "a": "C", "o": "A.사소한 범죄가 무엇이든 상관없습니다. 걱정하지 마세요.,B.주요 죄는 갑작스럽고 사소한 죄와는 아무 상관이 없습니다.,C.주요 죄는 대부분 사소한 죄의 누적된 확장의 결과입니다.,D.큰 죄만이 참된 죄입니다."}, {"q": "이 교훈에 따르면, 성경은 또한 죄로 정의하는 마음의 내적 상태는 무엇인가? (복수 선택)", "s": "내신", "a": "A|B|C", "o": "A.증오하는 사람,B.여자를 보면 참을성이 없습니다.,C.탐욕,D.의무를 다하는 부모"}, {"q": "이 수업에서 죄에서 오는 파괴의 측면에는 어떤 것이 있는가? (복수 선택)", "s": "죄의 결과", "a": "A|B|C", "o": "A.인간과 하나님 사이의 골절된 관계,B.대인 관계의 긴장,C.자연재해 및 인공재해,D.가해자에 대한 즉각적인 보복"}, {"q": "이 교훈에 따르면, 국법은 높은 표준이며, 율법을 지키는 것은 하나님 앞에 죄를 짓지 않는 것과 같습니다.", "s": "법적 기준", "a": "×"}, {"q": "이 수업에서 우리는 아이들이 태어나는 반항적인 투쟁이 죄의 근본 원인을 드러낸다고 믿습니다.", "s": "원죄의 증거", "a": "○"}, {"q": "그리스도인은 환난 가운데서 고통에 직면하여 지지자가 아니라 정죄자가 되어야 한다.", "s": "연민의 마음", "a": "×"}, {"q": "“나는 죄인이다” 라고 말하는 그리스도인들은 왜 다른 사람들을 정죄하지 않는가? 이 수업의 지침을 결합하십시오.", "s": "은혜로운 죄인", "a": "基督徒说「我是罪人」，是先承认自己在神的高标准下也是亏缺的，是「蒙恩的罪人」，而不是自认圣洁去审判别人。神的标准连思想意念都涵盖，无人能达到；但神爱世人，已在十字架上为我们付了代价，人只要凭信心接受，就能出黑暗入光明。传讲罪，是为了让人认识自己真正的需要、领受救恩，而不是定罪。"}, {"q": "왜 이 수업은 사람의 고통을 범죄의 결과로 직접 해석하는 것에 반대하는가?", "s": "고통과 죄", "a": "圣经没有启示苦难与个人犯罪之间有必然的对应关系，重大天灾人祸发生时基督徒从未被豁免。若以受苦定罪，普世无人能例外。本课主张：面对受苦者不做定罪者，而做支援者，发挥神所赐怜悯的心去帮助；同时人应在神的怜悯中自省，把握现今的处境好好而活。"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1772723705856','基要真理','第三课 救恩是什么？','救恩是恢复与神断绝的关系，靠基督十字架白白领受，人的善行无法交换。本课讲救恩的内容、领受的途径，以及得救的确据。愿你确知自己已经得救，满有平安。白白的恩典，当存感恩领受。','[{"type": "verse", "q": "【经文填空】神爱________，甚至将他的________赐给他们，叫一切信他的，不致灭亡，反得永生", "o": "《约翰福音》3章16节", "s": "神爱世人", "a": "世人|独生子"}, {"type": "verse", "q": "【经文填空】你若口里认________为主，心里信神叫他从________里复活，就必得救", "o": "《罗马书》10章9节", "s": "得救之道", "a": "耶稣|死"}, {"type": "verse", "q": "【经文填空】因他受的________，我们得医治；因他受的________，我们得平安", "o": "《以赛亚书》53章5节", "s": "代赎之恩", "a": "鞭伤|刑罚"}, {"type": "fill", "q": "救恩不是治标，而是________，解决人与神关系断绝的根本问题", "o": "", "s": "治本", "a": "治本"}, {"type": "fill", "q": "「耶稣」这个名字的意义是：他要将他的百姓从________里救出来", "o": "", "s": "耶稣之名", "a": "罪恶"}, {"type": "fill", "q": "若有人在基督里，他就是________的人，旧事已过，都变成新的了", "o": "", "s": "新造的人", "a": "新造"}, {"type": "fill", "q": "善行是人之所以为人的________，不是交换恩典的筹码", "o": "", "s": "善行的本分", "a": "本分"}, {"type": "fill", "q": "神造人时给了人________，让人可以自主选择接受救恩，而不是被操控的洋娃娃", "o": "", "s": "自由意志", "a": "自由意志"}, {"type": "fill", "q": "真正的得救在于________如一：口里认耶稣为主，心里信神叫他从死里复活", "o": "", "s": "心口如一", "a": "心口"}, {"type": "single", "q": "根据本课，基督教救恩的核心是指什么？", "o": "A.治好疾病,B.解决财务问题,C.把人从被罪捆绑、带向灭亡的生命中救出来，进入新生,D.改善夫妻关系", "s": "救恩的本质", "a": "C"}, {"type": "single", "q": "为什么人不能靠善行功德换取救恩？", "o": "A.善行本身没有价值,B.善行是人的本分，不是交换恩典的筹码；人也无法靠自己恢复与神的关系,C.神不喜欢人行善,D.只有犹太人才能行善", "s": "恩典非交换", "a": "B"}, {"type": "single", "q": "根据罗马书10章9节，怎样才算真正得救？", "o": "A.在布道会举手、教会登记名字,B.心口如一：认耶稣为主，信神叫他从死里复活,C.受过洗就够了,D.多做善事积功德", "s": "得救的确据", "a": "B"}, {"type": "multiple", "q": "本课提到，神为我们预备救恩的方式包括哪些？（多选）", "o": "A.差遣独生子为人的罪死在十字架上,B.让人用善行功德来换取,C.亲自承担犯罪的代价,D.让人一生下来就在救恩里", "s": "救恩的预备", "a": "A|C"}, {"type": "multiple", "q": "按本课，「认耶稣为主」包含哪两层含义？（多选）", "o": "A.接受耶稣成为生命的主，遵行他的吩咐,B.相信耶稣是神来做人的那一位，为罪死而复活,C.整天在口头上喊「主啊，主啊」,D.只把耶稣当作解决困难的救主", "s": "以耶稣为主", "a": "A|B"}, {"type": "judge", "q": "本课认为，基督徒生病或遭遇财务损失，说明他还没有真正得救。", "o": "", "s": "救恩非环境", "a": "错"}, {"type": "judge", "q": "得救是一个开始，之后一生要在他的光中经历他的带领。", "o": "", "s": "得救是开始", "a": "对"}, {"type": "judge", "q": "善行可以作为交换恩典的筹码，积功德就能换得救恩。", "o": "", "s": "善行与恩典", "a": "错"}, {"type": "essay", "q": "为什么说救恩是「治本」而不是「治标」？请结合本课说明。", "o": "", "s": "治本之恩", "a": "治标是解决环境问题——治病、脱离破产、改善关系，这些宗教也能应许。治本是解决人与神关系断绝的根本问题：人因罪与神隔绝，生命走向灭亡。神差遣独生子在十字架上付上罪的代价，人凭信心接受就恢复与神的关系，成为新造的人。根本问题解决后，人即使仍活在苦难的世代中，也能活出不一样的生命力，得着真正的平安喜乐。"}, {"type": "essay", "q": "本课为什么说神没有把人造成「不会犯罪的洋娃娃」？", "o": "", "s": "自由意志", "a": "神爱人，不是要造一个任人摆布的洋娃娃，而是给了人自由意志。人经历犯罪的痛苦、看见自己无法自救，再运用自主权选择接受神预备的救恩，才能真正体会救恩的美善，得着真实的喜乐与荣耀。若人一生下来就在救恩里、别无选择，这份关系就失去了爱的真意。"}]','https://youtu.be/G66Q96O5CYQ
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.7730551344cbd','quiz','[{"points": ["人遇到难处就想找神帮忙，宗教多扮演趋吉避凶的角色", "基督的救恩不是“我生病了医好我、破产了帮我解决”", "救恩指向生命本质的改变，而不只是处境的改善"], "title": "救恩不是治标"}, {"points": ["约翰福音3:16：不致灭亡，反得永生", "把人从被罪捆绑、带向灭亡的生命中带出来", "“耶稣”之名的意思：祂要将祂的百姓从罪恶里救出来"], "title": "救恩是治本：出黑暗入光明"}, {"points": ["罪的核心是人跟创造他的神关系断绝", "这关系断绝后，人自己没有能力恢复", "人想靠做善事积功德自救，是以自我为中心的想法"], "title": "罪是关系断绝，人无法自救"}, {"points": ["神的属性是慈爱也是公义，罪必须付代价", "神差遣祂的儿子，为我们的罪死在十字架上", "以赛亚书53章5节：因祂受的鞭伤我们得医治，因祂受的刑罚我们得平安"], "title": "神自己预备救恩"}, {"points": ["神不要造被操控的洋娃娃，祂造人给了自由意志", "人经历犯罪的痛苦、发现无法自救，再接受救恩", "人正确使用自由意志回应神，才是真正的喜乐与荣耀"], "title": "为什么要有选择的过程"}, {"points": ["罗马书10:9：口里认耶稣为主，心里信神叫祂从死里复活，就必得救", "“主”不只是救主，更是生命的主：按圣经标准生活", "心里相信耶稣是神来做人、在十字架上付了代价；心口如一就必得救"], "title": "如何得救：心口如一"}, {"points": ["不是看布道会举手、教会登记名字", "接受耶稣为生命的主之后，生命与价值观产生变化", "诗篇34:8：尝尝主恩的滋味，便知道祂的美善；得救是一生的开始"], "title": "得救的确据与开始"}]','','3','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 3 What is Salvation?", "content": "Salvation is the restoration of a broken relationship with God, freely received by the cross of Christ, and the good deeds of man cannot be exchanged. This lesson is about the content of salvation, ways to receive it, and the assurance of salvation. May you know that you are saved and at peace. Receive gratitude for free grace.", "instructions": "", "guide": [{"title": "Salvation is not a symptomatic remedy", "points": ["When people encounter difficulties, they want to seek God''s help. Religion often plays the role of aiding and abstaining from evil.", "Christ''s salvation is not “I am sick, I am healed, I am broke, help me solve”", "Salvation points to a change in the nature of life, not just an improvement in circumstances"]}, {"title": "Salvation is healing: out of darkness into light", "points": ["John 3:16: Do not perish, but have eternal life", "Bringing people out of the bonds of sin and into the lives of those who perish", "The meaning of the name “Jesus”: He will save His people from their sins"]}, {"title": "Sin is the breakdown of relationships, people can not save themselves", "points": ["The core of sin is the severance of man''s relationship with the God who created him.", "After this relationship is broken, people themselves are unable to recover", "It is self-centered thinking that people want to save themselves by doing good deeds."]}, {"title": "God Himself Prepares Salvation", "points": ["God''s attributes are mercy and righteousness, and sin must pay the price.", "God sent His Son to die on the cross for our sins", "Isaiah 53: 5: Through His stripes we are healed, through His chastisement we are at peace"]}, {"title": "Why have a selective process", "points": ["God did not create manipulated dolls; He created man and gave him free will.", "People experience the pain of sin, find themselves unable to save themselves, and then receive salvation.", "The right use of free will to respond to God is true joy and glory."]}, {"title": "How to Be Saved: Heart and Mouth as One", "points": ["Romans 10: 9: Confess the Lord Jesus with your mouth, trust God in your heart to raise Him from the dead, and you will be saved", "The “Lord” is not just the Savior, but the Lord of life: living by biblical standards", "Believe in your heart that Jesus is God who came to be a man and paid the price on the cross; your heart will be as one and you will be saved"]}, {"title": "The Assurance and Beginning of Salvation", "points": ["Not watching the sermon raise your hand and register the name of the church", "Life and values change after accepting Jesus as Lord of life", "Psalm 34: 8: Taste the Lord''s grace and know His goodness; salvation is the beginning of life"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] God loves ________, and even gave them his ________, so that everyone who believes in him will not perish, but have eternal life.", "s": "God Loves The Common People", "a": "the world|only Son"}, {"q": "[Scripture Fill in the Blank] If you recognize ________ as the Lord in your mouth and believe in God to resurrect him from ________ in your heart, you will be saved", "s": "The Path to Salvation", "a": "Jesus|death"}, {"q": "[Scripture Fill in the Blank] Because of the ________ he received, we are healed; because of the ________ he received, we are at peace", "s": "The Blessing of Redemption", "a": "wounds|punishment"}, {"q": "Salvation is not a symptomatic remedy, but a ________ that solves the fundamental problem of the severance of man''s relationship with God.", "s": "Radical Therapy", "a": "root cure"}, {"q": "The meaning of the name “Jesus” is that He will save His people from ________", "s": "Name of Jesus", "a": "sin"}, {"q": "If anyone is in Christ, he is a person of ________. The old things have passed away and become new.", "s": "Newly Created Man", "a": "new creation"}, {"q": "Good deeds are people''s ________, not a bargaining chip for grace", "s": "The duty of good deeds", "a": "duty"}, {"q": "When God created man, He gave man ________, so that man can choose to receive salvation, not the manipulated doll.", "s": "Free will", "a": "free will"}, {"q": "The real salvation lies in ________ as one: confessing Jesus as Lord by mouth and believing in God to raise him from the dead", "s": "I have the same heart and mouth", "a": "heart and mouth"}, {"q": "According to this lesson, what is at the heart of Christian salvation?", "s": "The Nature of Salvation", "a": "C", "o": "A.Cure the disease,B.Resolving Financial Issues,C.To rescue people from the bondage of sin, to bring them to perdition, to enter a new life.,D.Improve the relationship between husband and wife"}, {"q": "Why can''t people exchange merit for salvation?", "s": "Grace is not exchangeable", "a": "B", "o": "A.Good deeds have no value in themselves,B.Good deeds are man''s duty, not a bargaining chip for grace; nor can man restore his relationship with God on his own.,C.God does not like people to do good deeds,D.Only Jews can do good."}, {"q": "According to Romans 10: 9, what constitutes true salvation?", "s": "___ Assurance of Salvation", "a": "B", "o": "A.Raise your hand at a sermon, register your name with the church,B.One Mouth: Confess Jesus as Lord, Believe in God and Resurrect Him from the Dead,C.Being baptized is enough.,D.Do more good deeds and accumulate merit"}, {"q": "In this lesson, what are some of the ways God has prepared salvation for us? (Multiple choice)", "s": "Preparation for Salvation", "a": "A|C", "o": "A.Sent the only begotten to die on the cross for the sins of man,B.Let people use good deeds in exchange for good deeds,C.Personally bear the cost of the crime,D.Let a person be born in salvation"}, {"q": "According to this lesson, what are the two meanings of “confessing Jesus as Lord”? (Multiple choice)", "s": "Focus on Jesus", "a": "A|B", "o": "A.Accept Jesus as Lord of life and do His bidding,B.Believe that Jesus is the One who came to be man and rose from the dead for sin,C.Shouting “Lord, Lord” all day long,D.Only Jesus as the Savior who solves difficulties"}, {"q": "This lesson argues that a Christian''s illness or financial loss indicates that he has not been truly saved.", "s": "Salvation is not an environment", "a": "False"}, {"q": "Salvation is a beginning, followed by a lifetime of experiencing his leading in his light.", "s": "Salvation is the beginning", "a": "True"}, {"q": "Good works can be used as a bargaining chip for grace, and merit can be exchanged for salvation.", "s": "Good deeds and grace", "a": "False"}, {"q": "Why is salvation the “cure” and not the “cure”? Please combine the instructions in this lesson.", "s": "Grace to cure the root causes", "a": "治标是解决环境问题——治病、脱离破产、改善关系，这些宗教也能应许。治本是解决人与神关系断绝的根本问题：人因罪与神隔绝，生命走向灭亡。神差遣独生子在十字架上付上罪的代价，人凭信心接受就恢复与神的关系，成为新造的人。根本问题解决后，人即使仍活在苦难的世代中，也能活出不一样的生命力，得着真正的平安喜乐。"}, {"q": "Why does this lesson say that God did not create a “doll that cannot sin”?", "s": "Free will", "a": "神爱人，不是要造一个任人摆布的洋娃娃，而是给了人自由意志。人经历犯罪的痛苦、看见自己无法自救，再运用自主权选择接受神预备的救恩，才能真正体会救恩的美善，得着真实的喜乐与荣耀。若人一生下来就在救恩里、别无选择，这份关系就失去了爱的真意。"}]}, "ja": {"title": "レッスン3救いとは何か？", "content": "救いとは，キリストの十字架によって無駄に受け入れられた神との壊れた関係を回復することであり，人の善行は交換することができません。この課では，救いの内容，救いを受ける方法，救いの確信について学びます。あなたが救われ、平安であることを知ることができますように。無料の恩寵への感謝を受け取りましょう。", "instructions": "", "guide": [{"title": "救いは癒しではありません", "points": ["人々は困難に直面すると、神の助けを求めます。宗教はしばしば悪を助け、避ける役割を果たします。", "キリストの救いは，「わたしは病気で，癒され，破綻しています。解決するのを助けてください」ということではありません。", "救いは，状況の改善だけでなく，人生の性質の変化を指し示しています"]}, {"title": "救いは癒し：闇から光へ", "points": ["ヨハネ3 ： 16 ：滅びないで，永遠の命を持つ", "人々を罪の絆から救い出し，滅びる人々の生活の中に入らせる", "「イエス」という名の意味：主は御自分の民を罪から救われる"]}, {"title": "罪は人間関係の崩壊であり、人々は自分自身を救うことができません", "points": ["罪の核心は，人を創造した神との関係の断絶です。", "この関係が壊れた後、人々自身は回復することができません", "人は善行をすることで自分を救いたいという自己中心的な考え方です。"]}, {"title": "神ご自身が救いを備えてくださる", "points": ["神の特質は憐れみと義であり、罪は代償を払わなければなりません。", "神は御子をわたしたちの罪のために十字架で死なせるために遣わされました", "イザヤ53 ： 5 ：わたしたちは主の鞭によって癒され，主の懲らしめによって平安に包まれています"]}, {"title": "選択的なプロセスがある理由", "points": ["神は操作された人形を創造しませんでした。彼は人間を創造し、彼に自由意志を与えました。", "人々は罪の苦しみを経験し，自分自身を救うことができず，救いを受けます。", "自由意志を正しく用いて神に応答することは，真の喜びと栄光です。"]}, {"title": "救われる方法：口から口へ", "points": ["ローマ10 ： 9 ：口をもって主イエスを告白し，神を死人の中からよみがえらせてくださることを心の中で信頼してください。そうすれば，あなたは救われるでしょう", "「主」は単なる救い主ではなく，命の主である：聖書の基準に従って生きる", "イエスが人となり，十字架の代価を払われた神であることを心の中で信じてください。あなたの心は一つになり，あなたは救われるのです。"]}, {"title": "救いの確信と始まり", "points": ["伝道集会で手を挙げることでも、教会に名前を登録することでもありません", "イエスを命の主として受け入れた後、人生と価値観が変わる", "詩篇34 ： 8 ：主の恵みを味わい、主の恵みを知りましょう。救いは命の始まりです"]}], "quizzes": [{"q": "〔空白の聖句を埋める〕神は________を愛しておられ， ________さえお与えになり，御自分を信じるすべての人が滅びることなく，永遠の命を得ることができるようにされました。", "s": "神は世界を愛しておられる", "a": "世の人々|独り子"}, {"q": "〔聖句の穴埋め〕あなたが口で________を主と告白し、心で神が彼を________からよみがえらせたと信じるなら、あなたは救われる", "s": "救いへの道", "a": "イエス|死"}, {"q": "〔聖句の穴埋め〕彼が受けた________によって私たちは癒され、彼が受けた________によって私たちは平安を得る", "s": "贖いの祝福", "a": "打たれた傷|刑罰"}, {"q": "救いは癒しではなく，人と神との関係を断絶するという根本的な問題を解決する________です。", "s": "根本原因の解決", "a": "根本的な治療"}, {"q": "「イエス」という名前の意味は，主がご自分の民を________から救われるということです。", "s": "イエスの御名", "a": "罪悪"}, {"q": "誰かがキリストにあるなら、その人は________の人です。古いものは過ぎ去り、新しいものになりました。", "s": "新しく創造された男", "a": "新しく造られた者"}, {"q": "善行は人々の________であり、恩寵のための交渉チップではありません", "s": "善行の義務", "a": "本分"}, {"q": "神が人を創造されたとき、人が操作された人形ではなく、救いを受けることを選択できるように、神は人に________を与えました。", "s": "自由意志", "a": "自由意志"}, {"q": "真の救いは、口でイエスを主として告白し、イエスを死者の中からよみがえらせるために神を信じる________にあります", "s": "私は同じ心と口を持っています", "a": "心と口"}, {"q": "この課によれば，キリスト教の救いの中心にあるものは何でしょうか。", "s": "救いの性質", "a": "C", "o": "A.病気を治す,B.財務上の問題の解決,C.人々を罪の束縛から救い，滅びに導き，新しいいのちに入るためです。,D.夫婦関係の改善"}, {"q": "なぜ人々は救いのために功績を交換することができないのでしょうか。", "s": "恵みは交換できません", "a": "B", "o": "A.善行自体に価値はない,B.善行は人の義務であり、恵みのための交渉のチップではありません。また、人は自分自身で神との関係を回復することもできません。,C.神は人々が善行をするのを好まれない,D.ユダヤ人だけが善を行うことができます。"}, {"q": "ローマ10 ： 9によれば，真の救いとは何でしょうか。", "s": "救いの確信", "a": "B", "o": "A.説教で手を挙げ、教会に名前を登録する,B.一言：イエスを主として告白し、神を信じ、神を死者の中から復活させる,C.バプテスマを受けるだけで十分です。,D.より多くの善行を行い、功績を蓄積する"}, {"q": "この課では，神がわたしたちのために救いを備えてくださった方法にはどのようなものがありますか。（複数選択可）", "s": "救いへの準備", "a": "A|C", "o": "A.人の罪のために十字架で死ぬ独り子を遣わされた,B.人々が善行と引き換えに善行を使用できるようにする,C.個人的に犯罪の費用を負担する,D.人は救いの中に生まれる"}, {"q": "この課によれば，「イエスを主と告白する」という二つの意味は何でしょうか。（複数選択可）", "s": "イエスに焦点を当てる", "a": "A|B", "o": "A.イエスを命の主として受け入れ，イエスの命令を果たす,B.イエスが人となり，罪のために死からよみがえられた方であることを信じる,C.一日中「主よ、主よ」と叫ぶ,D.困難を解決する救い主としてのイエスのみ"}, {"q": "この課では，クリスチャンの病気や経済的損失は，彼が真に救われていないことを示していると主張します。", "s": "救いは環境ではありません", "a": "×"}, {"q": "救いは始まりであり，それに続いて彼の光の中で彼の導きを経験する生涯が続きます。", "s": "救いは始まりです", "a": "○"}, {"q": "良い行いは恩寵のための交渉のチップとして使用することができ、功績は救いと交換することができます。", "s": "善行と恵み", "a": "×"}, {"q": "なぜ救いは「癒し」ではなく「癒し」なのでしょうか。このレッスンの指示を組み合わせてください。", "s": "根本原因を治すための恵み", "a": "治标是解决环境问题——治病、脱离破产、改善关系，这些宗教也能应许。治本是解决人与神关系断绝的根本问题：人因罪与神隔绝，生命走向灭亡。神差遣独生子在十字架上付上罪的代价，人凭信心接受就恢复与神的关系，成为新造的人。根本问题解决后，人即使仍活在苦难的世代中，也能活出不一样的生命力，得着真正的平安喜乐。"}, {"q": "このレッスンでは，なぜ神は「罪を犯すことのできない人形」を創造されなかったと述べているのでしょうか。", "s": "自由意志", "a": "神爱人，不是要造一个任人摆布的洋娃娃，而是给了人自由意志。人经历犯罪的痛苦、看见自己无法自救，再运用自主权选择接受神预备的救恩，才能真正体会救恩的美善，得着真实的喜乐与荣耀。若人一生下来就在救恩里、别无选择，这份关系就失去了爱的真意。"}]}, "ko": {"title": "제3과 구원이란 무엇인가?", "content": "구원은 그리스도의 십자가로 말미암아 헛되이 받은 하나님과의 끊어진 관계를 회복하는 것이며, 인간의 선행은 교환될 수 없습니다. 이 수업은 구원의 내용, 구원을 받는 방법, 구원의 확신에 관한 것이다. 여러분이 구원받고 평안하다는 것을 알 수 있기를 바랍니다. 무료 은혜에 대한 감사를 받는다.", "instructions": "", "guide": [{"title": "구원은 치유가 아닙니다", "points": ["사람들은 어려움에 부딪히면 하나님의 도우심을 구하기를 원합니다. 종교는 종종 악을 돕고 멀리하는 역할을합니다.", "그리스도의 구원은 “내가 병들었다, 내가 나았다, 내가 부서졌다, 내가 해결하도록 도와라” 가 아닙니다.", "구원은 단순히 상황의 개선이 아니라 삶의 본질의 변화를 가리킵니다."]}, {"title": "구원은 치유입니다: 어둠에서 빛으로", "points": ["요한복음 3:16: 멸망하지 말고 영생을 얻으라", "사람들을 죄의 사슬에서 끌어내어 멸망하는 사람들의 삶으로 이끄는 것", "“예수” 라는 이름의 의미: 그분은 당신의 백성을 그들의 죄에서 구원하실 것입니다."]}, {"title": "죄는 관계의 붕괴이며, 사람들은 자신을 구할 수 없습니다.", "points": ["죄의 핵심은 인간을 창조하신 하나님과의 관계의 단절입니다.", "이 관계가 깨진 후에는 사람들 스스로가 회복할 수 없습니다.", "사람들이 선행을 함으로써 자신을 구원하고자 하는 것은 자기중심적 사고입니다."]}, {"title": "구원을 준비하시는 하나님 자신", "points": ["하나님의 속성은 자비와 의로움이며, 죄는 대가를 치러야 합니다.", "하나님께서는 우리의 죄를 위해 당신의 아들을 십자가에 죽게 보내셨습니다.", "이사야 53장 5절: 그의 채찍에 맞음으로 우리가 나음을 입었고 그의 징계로 우리가 평안함을 얻었도다"]}, {"title": "선택적 프로세스가 필요한 이유", "points": ["하나님은 조작된 인형을 창조하신 것이 아니라 인간을 창조하시고 그에게 자유 의지를 주셨습니다.", "사람들은 죄의 고통을 경험하고, 자신을 구원할 수 없다는 것을 알게 되고, 그런 다음 구원을 받습니다.", "하나님 께 응답하기 위해 자유 의지를 올바르게 사용하는 것은 진정한 기쁨과 영광입니다."]}, {"title": "구원을 받는 방법: 입에서 입으로", "points": ["로마서 10: 9: 네 입으로 주 예수를 시인하고 네 마음에 하나님을 의지하여 그를 죽은 자 가운데서 살리라 그리하면 구원을 얻으리라", "“주님” 은 단지 구주일 뿐 아니라 생명의 주님이십니다: 성경의 표준에 따라 생활하는 것", "예수님이 사람으로 오셔서 십자가에서 값을 치르신 하나님이심을 마음에 믿으십시오. 당신의 마음은 하나가 될 것이고 당신은 구원을 얻을 것입니다."]}, {"title": "구원의 확신과 시작", "points": ["전도집회에서 손을 드는 것도, 교회에 이름을 등록하는 것도 아닙니다", "예수님을 생명의 주님으로 영접한 후 삶과 가치관이 변화합니다.", "시편 34: 8: 주님의 은혜를 맛보고 그분의 선하심을 아십시오. 구원은 삶의 시작입니다."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 하나님은 ________ 을 (를) 사랑하시며, 심지어 ________ 을 (를) 주셨습니다. 이는 그를 믿는 모든 사람이 멸망하지 않고 영생을 얻을 수 있도록 하기 위함입니다.", "s": "하나님은 세상을 사랑하십니다", "a": "세상 사람들|독생자"}, {"q": "[Scripture Fill in the Blank] ________ 을 (를) 입안의 주님으로 인식하고 하나님을 믿어 마음속의 ________ 에서 그를 부활시킨다면, 당신은 구원을 얻을 것입니다.", "s": "구원에 이르는 길", "a": "예수님|죽음"}, {"q": "[Scripture Fill in the Blank] 그가 받은 ________ 때문에 우리는 치유되었습니다. 그가 받은 ________ 때문에 우리는 평화롭습니다.", "s": "구원의 축복", "a": "채찍에 맞으심|형벌"}, {"q": "구원은 치료가 아니라 인간과 하나님과의 관계의 단절이라는 근본적인 문제를 해결하는 ________ 입니다.", "s": "근본 원인 치료", "a": "근본적인 치료"}, {"q": "\"예수\" 라는 이름의 의미는 그분이 자신의 백성을 ________ 으로부터 구원하실 것이라는 것입니다.", "s": "예수의 이름", "a": "죄악"}, {"q": "누구든지 그리스도 안에 있으면 ________ 의 사람입니다. 옛 것은 지나가고 새 것이 되었습니다.", "s": "새로 창조된 인간", "a": "새로운 피조물"}, {"q": "선행은 사람들의 ________ 이며, 은혜를 위한 협상 칩이 아닙니다.", "s": "선행의 의무", "a": "본분"}, {"q": "하나님께서 인간을 창조하실 때 인간에게 ________ 을 주셨기 때문에 인간은 조작된 인형이 아니라 구원을 받기로 선택할 수 있습니다.", "s": "자유 의지", "a": "자유 의지"}, {"q": "진정한 구원은 다음과 같은 ________ 에 있습니다: 예수님을 입으로 주님으로 고백하고 그를 죽은 자 가운데서 살리시기 위해 하나님을 믿는 것.", "s": "나는 마음과 입이 같다", "a": "마음과 입"}, {"q": "이 교훈에 따르면, 그리스도인 구원의 핵심은 무엇인가?", "s": "구원의 본질", "a": "C", "o": "A.질병 치료하기,B.재정적 문제 해결,C.사람들을 죄의 속박에서 구출하고, 멸망에 이르게 하고, 새로운 삶에 들어가게 하는 것.,D.남편과 아내의 관계 개선"}, {"q": "왜 사람들은 구원을 위해 공로를 교환할 수 없는가?", "s": "은혜는 교환할 수 없습니다", "a": "B", "o": "A.선행은 그 자체로 가치가 없습니다.,B.선행은 인간의 의무이지 은혜를 위한 협상 칩이 아닙니다. 또한 인간은 하나님과의 관계를 스스로 회복할 수 없습니다.,C.하나님은 사람들이 선을 행하는 것을 좋아하지 않으십니다.,D.오직 유대인만이 선을 행할 수 있습니다."}, {"q": "로마서 10장 9절에 따르면, 무엇이 참된 구원을 구성하는가?", "s": "구원의 확신", "a": "B", "o": "A.설교에서 손을 들고 교회에 이름을 등록하십시오,B.한 입: 예수님을 주님으로 고백하고, 하나님을 믿고, 그분을 죽은 자들 가운데서 부활시키십시오.,C.침례를 받는 것만으로도 충분합니다.,D.더 많은 선행을 행하고 공로를 쌓으십시오"}, {"q": "이 수업에서 하나님께서 우리를 위해 구원을 준비하신 방법에는 어떤 것들이 있는가? (복수 선택)", "s": "구원을 위한 준비", "a": "A|C", "o": "A.인간의 죄를 위해 십자가에서 죽도록 독생자를 보내심,B.사람들이 선행의 대가로 선행을 사용하게 하십시오.,C.개인적으로 범죄 비용을 부담합니다.,D.사람이 구원에서 태어나게 하십시오"}, {"q": "이 수업에 따르면, “예수님을 주님으로 고백하는 것” 의 두 가지 의미는 무엇인가? (복수 선택)", "s": "예수님께 집중하기", "a": "A|B", "o": "A.예수님을 생명의 주님으로 영접하고 그분의 명령을 행하십시오.,B.예수님은 사람이 되기 위해 오셨고 죄를 위해 죽은 자 가운데서 부활하신 분이심을 믿으십시오.,C.하루 종일 “주님, 주님” 을 외치며,D.오직 예수님만이 어려움을 해결하시는 구주이십니다."}, {"q": "이 과는 그리스도인의 질병이나 재정적 손실이 진정으로 구원받지 못했음을 나타낸다고 주장한다.", "s": "구원은 환경이 아닙니다", "a": "×"}, {"q": "구원은 시작이며, 그분의 빛 안에서 그분의 인도를 경험하는 일생이 뒤따른다.", "s": "구원은 시작입니다", "a": "○"}, {"q": "선행은 은혜를 위한 교섭의 장으로 사용될 수 있고, 공로는 구원을 위해 교환될 수 있다.", "s": "선행과 은혜", "a": "×"}, {"q": "왜 구원은 “치유” 가 아니라 “치유” 인가? 이 수업의 지침을 결합하십시오.", "s": "근본 원인을 치료하는 은혜", "a": "治标是解决环境问题——治病、脱离破产、改善关系，这些宗教也能应许。治本是解决人与神关系断绝的根本问题：人因罪与神隔绝，生命走向灭亡。神差遣独生子在十字架上付上罪的代价，人凭信心接受就恢复与神的关系，成为新造的人。根本问题解决后，人即使仍活在苦难的世代中，也能活出不一样的生命力，得着真正的平安喜乐。"}, {"q": "이 교훈은 왜 하나님께서 “죄를 지을 수 없는 인형” 을 창조하지 않으셨다고 말하는가?", "s": "자유 의지", "a": "神爱人，不是要造一个任人摆布的洋娃娃，而是给了人自由意志。人经历犯罪的痛苦、看见自己无法自救，再运用自主权选择接受神预备的救恩，才能真正体会救恩的美善，得着真实的喜乐与荣耀。若人一生下来就在救恩里、别无选择，这份关系就失去了爱的真意。"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1772732370110','基要真理','第四课 谁是神？','神是灵，超越感官却藉宇宙的精密显明自己，祂是独一真神。本课认识这位真神是谁，以及祂慈爱怜悯与公义圣洁的属性。愿你更深认识这位又真又活的神。单单敬拜事奉这位独一真神。','[{"type": "verse", "q": "【经文填空】神是个________，所以拜他的必须用心灵和________拜他", "o": "《约翰福音》4章24节", "s": "神是灵", "a": "灵|诚实"}, {"type": "verse", "q": "【经文填空】我们在________的父：愿人都尊你的名为________", "o": "《马太福音》6章9节", "s": "天上的父", "a": "天上|圣"}, {"type": "verse", "q": "【经文填空】人造的偶像有口却不________，有眼却不________，有耳却不________", "o": "《诗篇》115章5节", "s": "偶像的虚空", "a": "言|看|听"}, {"type": "fill", "q": "要求「把神拿出来给我看」，本质上是以________为中心，要神满足人开出的条件", "o": "", "s": "眼见为信", "a": "人"}, {"type": "fill", "q": "神是灵，不像人有身体，不受________和空间的限制", "o": "", "s": "超越时空", "a": "时间"}, {"type": "fill", "q": "圣经说，人是按着神的________和样式造的", "o": "", "s": "神的形象", "a": "形象"}, {"type": "fill", "q": "神在旧约称以色列为「我的长子」，又在________书中把悖逆的以色列比作妻子", "o": "", "s": "父与夫妻", "a": "何西阿"}, {"type": "fill", "q": "称神为父，就要遵行他的________，而不只是在口头上喊「主啊，主啊」", "o": "", "s": "遵行旨意", "a": "旨意"}, {"type": "fill", "q": "与真神恢复关系的方法是________：因着他的恩典，藉着我们运用自由意志相信接受", "o": "", "s": "因恩藉信", "a": "因恩藉信"}, {"type": "single", "q": "本课说，「眼见为信」这种看法的问题在哪里？", "o": "A.人的眼睛经常看错,B.以人为中心，要求一切满足自己开出的条件,C.神太小了看不见,D.科学已经证明神不存在", "s": "眼见为信", "a": "B"}, {"type": "single", "q": "为什么基督徒称神为「父」？", "o": "A.自己高兴，想怎么叫就怎么叫,B.神俯就卑微的人，借圣经教导人用能懂的方式与他建立关系,C.神就是每个人的生身父亲,D.这是教会规定的称呼", "s": "称神为父", "a": "B"}, {"type": "single", "q": "人造的神与又真又活的神最根本的区别是什么？", "o": "A.体积大小不同,B.人造神有眼不能看、有口不能言，关系由人定；真神主动启示，关系由他定,C.制造材料不同,D.出现的年代不同", "s": "真神与偶像", "a": "B"}, {"type": "multiple", "q": "本课提到哪些「看不见却真实存在」的事物，说明看不见不等于不存在？（多选）", "o": "A.X光、紫外线、红外线,B.人听不见、狗能听见的哨声,C.颜色光谱中人眼看不见的部分,D.神话故事里的神仙", "s": "看不见的存在", "a": "A|B|C"}, {"type": "multiple", "q": "神借「父子」与「夫妻」的关系向人显明什么？（多选）", "o": "A.父子关系强调保护与带领,B.夫妻关系强调恩爱与恩怜,C.父子关系强调严厉管教,D.夫妻关系强调互不相欠", "s": "关系的比喻", "a": "A|B"}, {"type": "judge", "q": "神像人一样有身体，在空间中只能同时存在于一点。", "o": "", "s": "神是灵", "a": "错"}, {"type": "judge", "q": "与神恢复关系之后，善行是生命的流露，不是交换恩典的筹码。", "o": "", "s": "善行的意义", "a": "对"}, {"type": "judge", "q": "一次决志受洗之后，神人关系就永远不需要再经营了。", "o": "", "s": "一生追随", "a": "错"}, {"type": "essay", "q": "为什么看不见神，不能作为神不存在的理由？请结合本课说明。", "o": "", "s": "看不见的存在", "a": "生活中许多看不见的事物真实存在，如X光、紫外线、人听不见而狗能听见的哨声，人的眼耳感知范围本就有限。神是灵，不像人有身体受时空限制，本就超越人的感官。圣经说「自从造天地以来，神的永能和神性是明明可知的」，人可借着宇宙的精密规律——如银河系中唯有地球适合人居住——认识这位创造者的存在。"}, {"type": "essay", "q": "称神为「父」，对基督徒的生活有什么实际要求？", "o": "", "s": "父的权柄", "a": "称神为父不是口头亲热，而是承认他的权柄：父是真理的源头，比我们更清楚当行的路。正如主耶稣所说，「凡称呼我主啊主啊的人不能都进天国，惟独遵行我天父旨意的人才能进去」。基督徒当遵行他借圣经启示的旨意，调整生活的脚步，一生追随，这才是真实的神人关系。"}]','https://youtu.be/LCWjJfcotFQ
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134CIsE','quiz','[{"points": ["“把神拿出来给我看，我就信”；法利赛人求耶稣显神迹", "英文说 Seeing is believing，眼见为信", "这背后是以人为中心的立场：必须满足我开的条件才接受"], "title": "眼见为信的迷思"}, {"points": ["颜色光谱、X光、紫外线、红外线，人看不见但科学证实存在", "训狗的哨子一吹，人听不见，狗却听得见", "人的感官有限，看不见不等于不存在"], "title": "看不见不等于不存在"}, {"points": ["人活在长宽高加时间的四度空间里，这是人的有限", "神是个灵，祂不像人有一个身体，不受时空限制", "神是创造者，人是被造者，两者本质不同"], "title": "神是灵，不受时空限制"}, {"points": ["罗马书1:20：借着所造之物就可以晓得神的存在", "月球坑坑洞洞无法居住，与地球最近却完全不同", "浩瀚银河系唯地球适合人居住，空气阳光比例皆经精算"], "title": "借着创造认识神"}, {"points": ["神俯就卑微，用人懂得的方式启示自己", "旧约：以色列是神的长子（父子）；何西阿书：以色列如妻子（夫妻）", "新约主祷文：我们在天上的父，是主耶稣亲自教导的"], "title": "为什么称神为父"}, {"points": ["父代表权威，父是真理的源头，比我们更清楚", "马太福音7:21：惟独遵行天父旨意的人才能进天国", "称祂为父不只是口头喊，更要遵行祂的话"], "title": "父代表权威与顺服"}, {"points": ["人造神的特征：有眼不能看，有耳不能听，有口不能言", "人造神的关系全由人自定：积功德、杀猪宰羊换恩典", "真神是又真又活的神，关系由祂来定：因恩借信，一次决志、一生追随"], "title": "神人关系由神来定"}]','','4','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 4 Who is God?", "content": "God is spirit, but transcends the senses to reveal Himself through the precision of the universe, and He is the only true God. This lesson recognizes who this true God is and His attributes of mercy and righteousness and holiness. May you know this true and living God better. Simply worship and serve this one true God.", "instructions": "", "guide": [{"title": "Myth of seeing as believing", "points": ["“Show me God, and I will believe.” The Pharisees asked Jesus to do a miracle.", "Seeing is believing in English", "Behind this is a people-centered position: you must meet my conditions to accept"]}, {"title": "Invisible does not mean non-existent", "points": ["Color spectrum, X-ray, ultraviolet, infrared, invisible to humans but scientifically proven to exist", "The dog''s whistle blew, and people couldn''t hear it, but the dog could hear it.", "Human senses are limited, invisibility does not mean non-existence"]}, {"title": "God is spirit, not limited by time and space", "points": ["People live in a four-dimensional space of length, width, height and time, which is the limit of people", "God is a spirit, He does not have a body like a human being, and He is not limited by time and space.", "God is the Creator, man is the created being, the two are essentially different"]}, {"title": "Knowing God through Creation", "points": ["Romans 1:20: God''s existence is known through creation", "The craters of the moon are uninhabitable, but they are completely different from Earth''s lately.", "The vast galaxy is only suitable for human habitation, and the proportion of sunshine in the air is actuarial."]}, {"title": "Why do you call God the Father?", "points": ["God humbles Himself and reveals Himself in a way that man understands.", "Old Testament: Israel is God''s firstborn (father and son); Hosea: Israel is like a wife (husband and wife)", "New Testament Lord''s Prayer: Our Father in Heaven taught by the Lord Jesus Himself"]}, {"title": "Father Represents Authority and Obedience", "points": ["The Father represents authority, the Father is the source of truth and knows it better than we do.", "Matthew 7:21: Only those who do the Father''s will enter the kingdom of heaven", "Calling Him Father is more than just shouting, it''s about obeying His Word."]}, {"title": "The relationship between God and man is determined by God", "points": ["Characteristics of artificial gods: eyes can''t see, ears can''t hear, mouth can''t speak", "The relationship between artificial gods is completely determined by man: accumulated merit, slaughtering pigs and slaughtering sheep for grace", "The true God is a true and living God, and the relationship is determined by Him: by grace and faith, a decision, a lifetime of following"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] God is a ________, so you must worship him with your heart and ________", "s": "God is Spirit", "a": "Spirit|truth"}, {"q": "[Fill in the blank] Our Father in ________: May all honor your name as ________", "s": "Heavenly Father", "a": "heaven|holy"}, {"q": "[Scripture Fill in the Blank] Artificial idols have mouths but not ________, eyes but not ________, ears but not ________", "s": "Void of Idols", "a": "speech|看|hear"}, {"q": "The request to \"show me God\" is essentially centered on ________, asking God to satisfy the conditions issued by man.", "s": "Seeing is believing", "a": "man"}, {"q": "God is spirit, unlike human beings who have bodies and are not limited by ________ and space", "s": "Beyond time and space", "a": "time"}, {"q": "The Bible says that man was made in God''s ________ and likeness.", "s": "Image of God", "a": "image"}, {"q": "God called Israel “my firstborn son” in the Old Testament and likened disobedient Israel to a wife in the book of ________", "s": "Fathers and Husbands", "a": "Hosea"}, {"q": "To call God Father is to follow his ________, not just shout “Lord, Lord” verbally.", "s": "Do Your Will", "a": "will"}, {"q": "The way to restore a relationship with the true God is ________: by His grace, through our exercise of free will, believing in acceptance", "s": "by grace through faith", "a": "by grace through faith"}, {"q": "In this lesson, what is the problem with the perception of seeing as believing?", "s": "Seeing is believing", "a": "B", "o": "A.The human eye is often mistaken,B.People-centered, requiring everything to meet their own conditions,C.God is too small to see,D.Science has proven that God does not exist"}, {"q": "Why do Christians call God “Father”?", "s": "Calling God the Father", "a": "B", "o": "A.I''m happy, I can call it whatever I want,B.God bows down to the humble and uses the Bible to teach people to build a relationship with Him in a way they can understand.,C.God is everyone''s biological father,D.This is a name prescribed by the Church"}, {"q": "What is the fundamental difference between an artificial God and a true and living God?", "s": "True Gods & Idols", "a": "B", "o": "A.Different volume sizes,B.Artificial gods have eyes that can''t see, mouths that can''t speak, and the relationship is determined by people; the true god takes the initiative to inspire, and the relationship is determined by him.,C.Different manufacturing materials,D.appearing in different ages"}, {"q": "What are some of the things mentioned in this lesson that are \"invisible but real\", indicating that invisibility is not the same as non-existence? (Multiple choice)", "s": "Invisible Presence", "a": "A|B|C", "o": "A.X-ray, ultraviolet, infrared,B.Humans can''t hear, dogs can hear whistles,C.Invisible parts of the color spectrum,D.Immortals in mythology"}, {"q": "What does God reveal to people through the relationship between “father and son” and “husband and wife”? (Multiple choice)", "s": "Parable of Relationships", "a": "A|B", "o": "A.The father-son relationship emphasizes protection and leadership,B.The relationship between husband and wife emphasizes love and compassion,C.The father-son relationship emphasizes strict discipline,D.The couple''s emphasis is on not being indebted to each other"}, {"q": "God has a body like a human being, and can only exist at a point in space at the same time.", "s": "God is Spirit", "a": "False"}, {"q": "After restoring a relationship with God, good deeds are an outpouring of life, not a bargaining chip for grace.", "s": "The Meaning of Good Deed", "a": "True"}, {"q": "After a decision to be baptized, the relationship between God and man will never need to be managed again.", "s": "A lifetime of following", "a": "False"}, {"q": "Why can''t we see God and use it as a reason for God''s existence? Please combine the instructions in this lesson.", "s": "Invisible Presence", "a": "生活中许多看不见的事物真实存在，如X光、紫外线、人听不见而狗能听见的哨声，人的眼耳感知范围本就有限。神是灵，不像人有身体受时空限制，本就超越人的感官。圣经说「自从造天地以来，神的永能和神性是明明可知的」，人可借着宇宙的精密规律——如银河系中唯有地球适合人居住——认识这位创造者的存在。"}, {"q": "What are the practical demands on the Christian life of referring to God as “Father”?", "s": "Father''s Authority", "a": "称神为父不是口头亲热，而是承认他的权柄：父是真理的源头，比我们更清楚当行的路。正如主耶稣所说，「凡称呼我主啊主啊的人不能都进天国，惟独遵行我天父旨意的人才能进去」。基督徒当遵行他借圣经启示的旨意，调整生活的脚步，一生追随，这才是真实的神人关系。"}]}, "ja": {"title": "レッスン4神とは誰か？", "content": "神は霊であるが、感覚を超越して宇宙の精密さを通してご自身を現し、唯一の真の神である。この課では，この真の神がだれであるか，また憐れみと正義と聖性という神の特質を認識します。あなたがこの真の生ける神をよりよく知ることができますように。ただこの真の神を礼拝し，仕えるだけです。", "instructions": "", "guide": [{"title": "信じていると見なすという神話", "points": ["「神を見せなさい。そうすれば信じます。」パリサイ人たちはイエスに奇跡を起こすように頼みました。", "Seeing is believing in English", "この背後には、人を中心としたポジションがあります。受け入れるには、私の条件を満たす必要があります"]}, {"title": "目に見えないということは、存在しないということではありません", "points": ["カラースペクトル、X線、紫外線、赤外線、人間には見えないが、科学的に存在することが証明されている", "犬の笛が鳴り、人々はそれを聞くことができませんでしたが、犬はそれを聞くことができました。", "人間の感覚は限られており、目に見えないということは存在しないということではありません"]}, {"title": "神は霊であり、時間と空間に制限されない", "points": ["人々は長さ、幅、高さ、時間の4次元空間に住んでいます。これは人々の限界です", "神は霊であり、人間のような体を持っておらず、時間と空間に制限されていません。", "神は創造主であり、人間は被造物であり、両者は本質的に異なる"]}, {"title": "創造を通して神を知る", "points": ["ローマ1 ： 20 ：神の存在は創造を通して知られている", "月のクレーターは住めませんが、最近の地球とはまったく異なります。", "広大な銀河系は人間の居住にしか適しておらず、空気中の太陽光の割合は数理計算上のものです。"]}, {"title": "なぜ神を父と呼ぶのですか。", "points": ["神はご自身をへりくだらせ，人が理解できる方法でご自身を現されます。", "旧約聖書：イスラエルは神の長子（父と子）である；ホセア：イスラエルは妻（夫と妻）のようなものである", "新約聖書主の祈り：主イエスご自身によって教えられた天の御父"]}, {"title": "父は権威と従順を表わす", "points": ["父は権威を表し，父は真理の源であり，わたしたちよりもよく知っておられます。", "マタイ7 ： 21 ：父のものを行う者だけが天の王国に入る", "神を「父」と呼ぶことは，単に叫ぶことではなく，神の言葉に従うことです。"]}, {"title": "神と人との関係は神によって決定される", "points": ["人工神の特徴：目が見えない、耳が聞こえない、口が話せない", "人為的な神々の関係は完全に人間によって決定されます：蓄積された功績、豚の屠殺、恵みのための羊の屠殺", "真の神は真の生ける神であり、その関係は神によって決定されます：恵みと信仰、決断、一生続く"]}], "quizzes": [{"q": "〔聖句の穴埋め〕神は________です。ですから神を礼拝する者は、御霊と________をもって礼拝しなければなりません", "s": "神は霊です", "a": "霊|真実"}, {"q": "〔聖句の穴埋め〕________におられる私たちの父よ、御名が________とされますように", "s": "天の御父", "a": "天|聖なる"}, {"q": "[聖文は空白を埋めてください]人工の偶像には口がありますが________ではありません。目は________ではありません。耳は________ではありません。", "s": "偶像の虚無", "a": "言葉|看|聞く"}, {"q": "「私に神を示してください」という要求は、基本的に________を中心にしており、人間が発した条件を満たすように神に求めています。", "s": "見ることは信じること", "a": "人"}, {"q": "身体を持ち、________と空間に制限されない人間とは異なり、神は霊です", "s": "時間と空間を超えて", "a": "時間"}, {"q": "聖書には，人は神の________と肖像の中で造られたと書かれています。", "s": "神の画像", "a": "形"}, {"q": "神は旧約聖書でイスラエルを「わたしの長子」と呼び，不従順なイスラエルを________の書の妻にたとえられました。", "s": "父親と夫", "a": "ホセア"}, {"q": "神の御父を呼ぶことは，単に「主よ，主よ」と口頭で叫ぶのではなく，神の________に従うことです。", "s": "自分の意志で行動する", "a": "御心"}, {"q": "真の神との関係を回復する方法は________です：彼の恵みによって、私たちの自由意志の行使を通して、受け入れを信じる", "s": "恵みにより、信仰によって", "a": "恵みにより、信仰によって"}, {"q": "このレッスンでは，見ていることを信じているという認識にどのような問題がありますか。", "s": "見ることは信じること", "a": "B", "o": "A.人間の目はしばしば間違っています,B.人を中心に据え、すべてが自分の条件を満たす必要がある,C.神は小さすぎて見えない,D.科学は神が存在しないことを証明しました"}, {"q": "クリスチャンが神を「父」と呼ぶのはなぜですか。", "s": "神を父と呼ぶ", "a": "B", "o": "A.私は幸せです、私はそれを好きなように呼ぶことができます,B.神は謙遜な人にひれ伏し，聖書を使って人々に理解できる方法で神との関係を築くよう教えます。,C.神はすべての人の生物学的な父である,D.これは教会によって規定された名前です"}, {"q": "人工的な神と真の生ける神との根本的な違いは何ですか。", "s": "真の神々と偶像", "a": "B", "o": "A.さまざまなボリュームサイズ,B.人工的な神々は目が見えず、口が話せず、人間関係が決まり、真の神々は主導権を握ってインスピレーションを与え、人間関係が決まります。,C.異なる製造材料,D.異なる年齢で現れる"}, {"q": "このレッスンで言及されていることの中で、「見えないが現実的」であり、見えないことが存在しないことと同じではないことを示すものは何ですか？ （複数選択可）", "s": "見えない存在", "a": "A|B|C", "o": "A.X線、紫外線、赤外線,B.人間には聞こえない、犬には笛が聞こえる,C.カラースペクトルの見えない部分,D.神話の不滅の者たち"}, {"q": "「父と子」と「夫と妻」の関係を通して，神は人々に何を明らかにされるでしょうか。（複数選択可）", "s": "関係のたとえ話", "a": "A|B", "o": "A.父子関係は保護とリーダーシップを強調する,B.夫と妻の関係は愛と思いやりを強調する,C.父子関係は厳格な規律を重視している,D.夫婦はお互いに借金をしないことを重視しています"}, {"q": "神は人間のような体を持っており、同時に空間のある地点にのみ存在することができます。", "s": "神は霊です", "a": "×"}, {"q": "神との関係を回復した後、善行は命の流れであり、恵みのための交渉のチップではありません。", "s": "善行の意味", "a": "○"}, {"q": "バプテスマを受ける決心をした後，神と人間の関係は二度と管理される必要はありません。", "s": "生涯にわたるフォロー", "a": "×"}, {"q": "なぜ私たちは神を見て、それを神の存在の理由として使うことができないのでしょうか。このレッスンの指示を組み合わせてください。", "s": "見えない存在", "a": "生活中许多看不见的事物真实存在，如X光、紫外线、人听不见而狗能听见的哨声，人的眼耳感知范围本就有限。神是灵，不像人有身体受时空限制，本就超越人的感官。圣经说「自从造天地以来，神的永能和神性是明明可知的」，人可借着宇宙的精密规律——如银河系中唯有地球适合人居住——认识这位创造者的存在。"}, {"q": "神を「父」と呼ぶことのクリスチャン生活に対する実際的な要求は何ですか。", "s": "父の権威", "a": "称神为父不是口头亲热，而是承认他的权柄：父是真理的源头，比我们更清楚当行的路。正如主耶稣所说，「凡称呼我主啊主啊的人不能都进天国，惟独遵行我天父旨意的人才能进去」。基督徒当遵行他借圣经启示的旨意，调整生活的脚步，一生追随，这才是真实的神人关系。"}]}, "ko": {"title": "제 4과 하나님은 누구신가?", "content": "하나님은 영이시지만, 우주의 정밀함을 통해 자신을 드러내는 감각을 초월하시며, 유일하신 참 하나님이십니다. 이 과는 이 참 하나님이 누구신지와 그분의 자비와 의로움과 거룩함의 속성을 인식한다. 이 참되고 살아계신 하나님을 더 잘 알 수 있기를 바랍니다. 이 한 분의 참 하나님을 경배하고 섬기기만 하면 됩니다.", "instructions": "", "guide": [{"title": "믿는다고 보는 신화", "points": ["“하나님을 내게 보이라 그리하면 내가 믿겠노라.” 바리새인들은 예수님께 기적을 행해 달라고 부탁했습니다.", "보는 것은 영어를 믿는 것입니다", "이 배후에는 사람 중심의 입장이 있습니다. 내 조건을 충족해야 수락할 수 있습니다."]}, {"title": "보이지 않는다고 해서 존재하지 않는 것은 아닙니다.", "points": ["색 스펙트럼, X-선, 자외선, 적외선, 인간에게는 보이지 않지만 과학적으로 존재가 입증됨", "개는 휘파람을 불었고, 사람들은 그 소리를 들을 수 없었지만 개는 그 소리를 들을 수 있었습니다.", "인간의 감각은 제한적이며, 보이지 않는 것이 존재하지 않는 것을 의미하지는 않습니다."]}, {"title": "하나님은 영이시며 시간과 공간에 구애받지 않으십니다.", "points": ["사람들은 길이, 너비, 높이, 시간의 4차원 공간에 살고 있으며, 이는 사람들의 한계입니다.", "하나님은 영이시며, 인간과 같은 육체를 가지지 않으시고, 시간과 공간에 구애받지 않으십니다.", "하나님은 창조주이시고, 인간은 피조물이시며, 이 둘은 본질적으로 다릅니다."]}, {"title": "창조를 통해 하나님을 아는 것", "points": ["로마서 1:20: 하나님의 존재는 창조를 통해 알 수 있습니다", "달의 분화구는 사람이 살 수 없지만 최근의 지구와는 완전히 다릅니다.", "광활한 은하는 사람이 거주하기에 적합하며, 공중에서 햇빛의 비율은 계리적이다."]}, {"title": "왜 하나님을 아버지라고 부르는가?", "points": ["하나님께서는 자신을 낮추시고 인간이 이해하는 방식으로 자신을 계시하십니다.", "구약성경: 이스라엘은 하나님의 장자 (아버지와 아들), 호세아: 이스라엘은 아내 (남편과 아내) 와 같다.", "신약성경 주님의 기도: 주 예수께서 친히 가르치신 하늘에 계신 우리 아버지"]}, {"title": "권위와 순종을 대표하는 아버지", "points": ["아버지는 권위를 나타내시고, 아버지는 진리의 근원이시며, 우리보다 더 잘 아십니다.", "마태복음 7:21: 오직 아버지의 뜻대로 행하는 자만이 천국에 들어갈 수 있다", "그분을 아버지라고 부르는 것은 단순히 외치는 것이 아니라 그분의 말씀에 순종하는 것입니다."]}, {"title": "하나님과 인간의 관계는 하나님에 의해 결정됩니다.", "points": ["인공 신의 특징: 눈은 볼 수 없고, 귀는 들을 수 없으며, 입으로는 말할 수 없다.", "인공 신들 사이의 관계는 인간에 의해 완전히 결정됩니다: 축적 된 공로, 돼지 도살 및 은혜를 위해 양 도살", "참 하나님은 참되고 살아계신 하나님이시며, 그 관계는 그분에 의해 결정됩니다: 은혜와 믿음, 결정, 평생 따르는 것."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 하나님은 ________ 이시니 마음으로 예배하고 ________", "s": "하나님은 영이시다", "a": "영|진실"}, {"q": "[Scripture Fill in the Blank] ________ 안에 계신 우리 아버지: 아버지의 이름이 거룩히 여김을 받으시오며 ________", "s": "하나님 아버지", "a": "하늘|거룩한"}, {"q": "[Scripture Fill in the Blank] 인조 우상은 입이 있어도 ________ 이 없고, 눈이 있어도 ________ 이 없고, 귀가 있어도 ________ 이 (가) 없습니다.", "s": "우상 무효", "a": "말|看|듣다"}, {"q": "\"하나님 께 보여달라\" 는 요청은 본질적으로 ________ 를 중심으로 인간이 발행 한 조건을 충족 시키도록 하나님 께 요청합니다.", "s": "보는 것이 믿는 것이다", "a": "사람"}, {"q": "몸이 있고 __________ 및 공간에 의해 제한받지 않는 인간과 달리 하나님은 영이십니다.", "s": "시간과 공간을 초월한 공간", "a": "시간"}, {"q": "성경은 인간이 하나님의 ________ 와 형상으로 창조되었다고 말합니다.", "s": "하나님의 형상", "a": "형상"}, {"q": "하나님께서는 구약에서 이스라엘을 “내 맏아들” 이라고 부르셨고, 불순종하는 이스라엘을 ________ 의 책에서 아내로 비유하셨습니다.", "s": "아버지와 남편", "a": "호세아"}, {"q": "하나님 아버지를 부르는 것은 말로만 “주님, 주님” 을 외치는 것이 아니라 그분의 ________ 을 따르는 것입니다.", "s": "당신의 의지를 행하십시오", "a": "뜻"}, {"q": "참 하나님과의 관계를 회복하는 방법은 ________ 입니다. 그분의 은혜로, 우리의 자유 의지 행사를 통해, 받아들이는 것을 믿습니다.", "s": "은혜로 믿음으로", "a": "은혜로 믿음으로"}, {"q": "이 수업에서 믿는다고 보는 인식의 문제점은 무엇인가?", "s": "보는 것이 믿는 것이다", "a": "B", "o": "A.인간의 눈은 종종 착각을 합니다.,B.사람 중심, 모든 것이 자신의 조건을 충족해야 함,C.하나님은 너무 작아서 볼 수 없습니다,D.과학은 신이 존재하지 않는다는 것을 증명했습니다."}, {"q": "그리스도인들은 왜 하나님을 “아버지” 라고 부릅니까?", "s": "하나님을 아버지로 부름", "a": "B", "o": "A.저는 행복합니다. 제가 원하는 대로 부를 수 있어요.,B.하나님께서는 겸손한 사람들에게 몸을 굽히시고 성경을 사용하여 사람들이 이해할 수 있는 방식으로 그분과 관계를 맺도록 가르치십니다.,C.하나님은 모든 사람의 생물학적 아버지이십니다.,D.교회에서 정한 이름입니다."}, {"q": "인공 신과 참되고 살아 있는 신의 근본적인 차이점은 무엇인가?", "s": "진정한 신과 우상", "a": "B", "o": "A.다양한 볼륨 크기,B.인위적인 신은 볼 수 없는 눈이 있고, 말할 수 없는 입이 있으며, 그 관계는 사람에 의해 결정됩니다. 참된 신은 주도적으로 영감을 주고, 그 관계는 그분에 의해 결정됩니다.,C.다양한 제조 재료,D.다른 연령대에 나타남"}, {"q": "이 수업에서 언급된 \"보이지 않지만 실제\" 는 보이지 않는 것이 존재하지 않는 것과 같지 않다는 것을 나타내는 것은 무엇인가? (복수 선택)", "s": "보이지 않는 존재감", "a": "A|B|C", "o": "A.X-선, 자외선, 적외선,B.인간은 소리를 들을 수 없고, 개는 호루라기를 들을 수 있다.,C.색 스펙트럼의 보이지 않는 부분,D.신화 속의 불멸자"}, {"q": "하나님께서는 “아버지와 아들” 과 “남편과 아내” 의 관계를 통해 사람들에게 무엇을 계시하시는가? (복수 선택)", "s": "관계의 비유", "a": "A|B", "o": "A.아버지-아들 관계는 보호와 리더십을 강조합니다.,B.남편과 아내의 관계는 사랑과 연민을 강조합니다.,C.아버지-아들 관계는 엄격한 규율을 강조합니다.,D.부부는 서로에게 빚을 지지 않는 것에 중점을 둡니다."}, {"q": "신은 인간과 같은 몸을 가지고 있으며, 동시에 공간의 한 지점에만 존재할 수 있다.", "s": "하나님은 영이시다", "a": "×"}, {"q": "하나님과의 관계를 회복한 후, 선행은 은혜를 위한 교섭의 장이 아니라 생명의 부어짐입니다.", "s": "선행의 의미", "a": "○"}, {"q": "침례를 받기로 결정한 후에는 하나님과 인간의 관계를 다시 관리할 필요가 없습니다.", "s": "평생 팔로잉", "a": "×"}, {"q": "왜 우리는 하나님을 볼 수 없고 하나님의 존재의 이유로 사용할 수 없는가? 이 수업의 지침을 결합하십시오.", "s": "보이지 않는 존재감", "a": "生活中许多看不见的事物真实存在，如X光、紫外线、人听不见而狗能听见的哨声，人的眼耳感知范围本就有限。神是灵，不像人有身体受时空限制，本就超越人的感官。圣经说「自从造天地以来，神的永能和神性是明明可知的」，人可借着宇宙的精密规律——如银河系中唯有地球适合人居住——认识这位创造者的存在。"}, {"q": "하나님을 “아버지” 라고 부르는 그리스도인의 삶에 대한 실제적인 요구는 무엇인가?", "s": "아버지의 권위", "a": "称神为父不是口头亲热，而是承认他的权柄：父是真理的源头，比我们更清楚当行的路。正如主耶稣所说，「凡称呼我主啊主啊的人不能都进天国，惟独遵行我天父旨意的人才能进去」。基督徒当遵行他借圣经启示的旨意，调整生活的脚步，一生追随，这才是真实的神人关系。"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1772732768606','基要真理','第五课 谁是耶稣？','耶稣是神来做人，童贞女生子、死里复活为证。本课认识基督的身份与工作，明白祂是神与人之间唯一的道路。愿你认定基督，单单信靠祂。除祂以外，别无拯救，唯祂是主。','[{"type": "verse", "q": "【经文填空】道成了________，住在我们中间，充充满满地有________有真理", "o": "《约翰福音》1章14节", "s": "道成肉身", "a": "肉身|恩典"}, {"type": "verse", "q": "【经文填空】按圣善的灵说，因从________里复活，以大能显明是神的________", "o": "《罗马书》1章4节", "s": "复活显明", "a": "死|儿子"}, {"type": "verse", "q": "【经文填空】基督若没有________，你们的信便是________，你们仍在罪里", "o": "《哥林多前书》15章17节", "s": "复活的根基", "a": "复活|徒然"}, {"type": "fill", "q": "耶稣由童贞女马利亚从________感孕而生，与常人的出生不同", "o": "", "s": "童女怀孕", "a": "圣灵"}, {"type": "fill", "q": "保罗在主后55年写下复活见证时，与耶稣同时代的人都还________在世，复活的事可被检验", "o": "", "s": "同时代见证", "a": "活着"}, {"type": "fill", "q": "耶稣的十一个门徒除老约翰外全部________，无人会为自己编造的谎言付上生命的代价", "o": "", "s": "殉道见证", "a": "殉道"}, {"type": "fill", "q": "耶稣的坟墓门口封着一块________，外面还有兵丁把守", "o": "", "s": "封墓的巨石", "a": "巨石"}, {"type": "fill", "q": "耶稣在世时曾多次公开宣告，他死后________要复活", "o": "", "s": "三日复活", "a": "三天"}, {"type": "fill", "q": "耶稣活出无罪的生命，才有资格以无罪的代替________的，成为挽回祭", "o": "", "s": "无罪代赎", "a": "有罪"}, {"type": "single", "q": "本课说，证明耶稣是「神来做人」最关键、可公开检验的证据是什么？", "o": "A.童贞女怀孕,B.死里复活,C.在世时行神迹,D.道德高尚", "s": "复活的证据", "a": "B"}, {"type": "single", "q": "为什么「门徒偷走尸体、编造复活」的说法不成立？", "o": "A.门徒一向很诚实,B.门徒当时四散惊恐不敢接近坟墓，且无人会为自编的谎言殉道,C.门徒力气太小搬不动石头,D.门徒不识字写不出圣经", "s": "驳偷尸论", "a": "B"}, {"type": "single", "q": "为什么人必须借着耶稣才能得救，不能说「只信上帝、不信耶稣」？", "o": "A.这是教会的规定,B.这是神的安排：神定意借爱子在十字架上付上罪价，信神就是接受他一切的安排,C.因为耶稣比较有名,D.因为上帝太遥远够不着", "s": "神的安排", "a": "B"}, {"type": "multiple", "q": "哪些事实使「有人偷走耶稣尸体」的说法站不住脚？（多选）", "o": "A.门徒当时四散惊恐，不敢接近坟墓,B.十一个门徒除约翰外都为复活的见证殉道,C.犹太人和罗马人始终拿不出耶稣的尸体,D.坟墓有巨石封口并有兵丁把守", "s": "空坟的见证", "a": "A|B|C|D"}, {"type": "multiple", "q": "根据本课，耶稣与「被神化的人」有何不同？（多选）", "o": "A.耶稣由童贞女从圣灵感孕而生,B.耶稣从死里复活，空坟可被公开检验,C.耶稣是神来做人，不是人被神化,D.耶稣只是一个道德高尚的好人", "s": "耶稣非被神化", "a": "A|B|C"}, {"type": "judge", "q": "本课认为，单凭童贞女怀孕、在理性上就能完全证明耶稣是神，不需要复活的证据。", "o": "", "s": "证据的层次", "a": "错"}, {"type": "judge", "q": "如果耶稣没有复活，基督教的信仰就是枉然。", "o": "", "s": "复活的根基", "a": "对"}, {"type": "judge", "q": "「耶稣在十字架上没有真死，后来自己爬出坟墓」的说法符合历史事实。", "o": "", "s": "驳假死论", "a": "错"}, {"type": "essay", "q": "为什么复活是证明耶稣是神儿子的关键证据？请结合本课说明。", "o": "", "s": "复活的证据", "a": "复活是写在圣经中任世人检验的事实：保罗在主后55年写下见证时，与耶稣同时代的人都还活着，若是编造，第一世纪就会被推翻。门徒偷尸不可能——他们当时四散惊恐，且无人会为自编的谎言殉道；敌人偷尸也不可能——犹太人和罗马人始终拿不出尸体；假死爬出更不可能——罗马酷刑、巨石封墓、兵丁把守。空坟至今无人能推翻，证明耶稣胜过死亡，是神来做人的那一位。"}, {"type": "essay", "q": "本课如何回应「人做不到，神也做不到」的质疑（如童贞女生子）？", "o": "", "s": "神的全能", "a": "这种质疑预设了「人做不到的事，神也做不到」；但人寻求神，正是因为自己有做不到的事——若神只能做人能做的事，他就不是神。宇宙中神已做了许多人做不到的事：地球自转、公转、23.5度倾斜，人人都接受。若神是自有永有的创造者，他借圣灵使童贞女怀孕，在理性上完全可以接受；不接受的人，其实是把神降格成了「人造的神」。"}]','https://youtu.be/QaMyuZ9fFhc
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134wsN2','quiz','[{"points": ["你们不就是把耶稣神化了吗？跟一般宗教有何不同", "关公妈祖不是神，为什么耶稣是神", "有疑虑是好的，表示对真理有追求的心"], "title": "慕道友的疑问：把耶稣神化了吗"}, {"points": ["约翰福音1:14：道成了肉身，住在我们中间", "方向是神来做人，不是人变成神", "充充满满地有恩典，有真理"], "title": "道成了肉身"}, {"points": ["耶稣是童贞女马利亚因圣灵感孕而生", "“人做不到，神也做不到”是个矛盾：正因做不到才需要神", "创造宇宙的真神做超乎人理性的事，完全可以接受"], "title": "童贞女生子"}, {"points": ["罗马书1:4：因从死里复活，以大能显明是神的儿子", "哥林多前书15:17：基督若没有复活，所传所信都枉然", "复活不是纪念故事，而是信仰的根基"], "title": "复活是核心证据"}, {"points": ["这事在第一世纪就可检验：带你去看坟墓便知", "门徒偷？当时四散逃跑不敢回来；11门徒为见证复活殉道", "敌人偷？犹太人罗马人始终拿不出尸体；“没死论”不合酷刑、巨石、兵丁的事实"], "title": "空坟无法推翻"}, {"points": ["真理是神说了算，不是人说了算", "神安排祂的爱子以无罪的代替有罪的，为我们付代价", "信神就是诚心接受祂一切的安排，不能自己定规矩"], "title": "为什么非要耶稣"}, {"points": ["耶稣是神来做人的那一位，彰显神的爱", "祂成为挽回祭、赎罪祭，恢复神人关系", "希伯来书4:16：坦然无惧来到施恩座前，得怜恤蒙恩惠"], "title": "耶稣是谁"}]','','5','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 5 Who is Jesus?", "content": "Jesus was a man of God, born of a virgin and raised from the dead. This lesson understands the identity and work of Christ as the only way between God and man. May you affirm Christ and trust in Him alone. There is no salvation except in Him, who is Lord.", "instructions": "", "guide": [{"title": "Fellow Daoists'' question: Has Jesus been deified?", "points": ["Didn''t you just deify Jesus? How it differs from general religion", "Guan Gongmaozu is not God, why is Jesus God?", "It is good to have doubts, indicating a desire for the truth"]}, {"title": "Dao becomes flesh", "points": ["John 1:14: The Word became flesh and dwelt among us", "The direction is that God becomes man, not that man becomes God.", "Full of grace and truth"]}, {"title": "Virginity Birth Child", "points": ["Jesus was born of the Virgin Mary by the inspiration of the Holy Spirit", "\"If people can''t do it, God can''t do it\" is a contradiction: It is because they can''t do it that they need God", "It is perfectly acceptable for the true God who created the universe to do things that are beyond human reason."]}, {"title": "Resurrection is the central piece of evidence", "points": ["Romans 1: 4: Because of the resurrection from the dead, it was revealed by power that he was the Son of God", "1 Corinthians 15:17: If Christ is not resurrected, the preaching and beliefs are in vain", "The resurrection is not a memorial story, but the foundation of faith"]}, {"title": "Empty tombs cannot be overthrown", "points": ["This can be tested in the first century: take you to the tomb to know", "The disciples stole? At that time, they fled and did not dare to come back; 11 The disciples were martyred for witnessing the resurrection", "The enemy steals? The Jews, the Romans never come up with a corpse; the \"deathless theory\" is not compatible with the facts of torture, megaliths, soldiers"]}, {"title": "Why Jesus?", "points": ["Truth is in God''s hands, not in man''s.", "God arranged for His beloved Son to substitute sinlessness for sinful ones, paying the price for us.", "Believing in God is sincerely accepting all of His arrangements, and can''t set rules on your own."]}, {"title": "Who is Jesus?", "points": ["Jesus is the One who came as a man to show God''s love", "He became the sacrifice of redemption, the sacrifice of atonement, and the restoration of the relationship between God and", "Hebrews 4:16: Come boldly to the mercy seat and receive mercy"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] The Word has become ________, lives among us, and is filled with ________ Truth", "s": "Dao Incarnation Body"}, {"q": "[Scripture Fill in the Blank] According to the holy and good spirit, because of the resurrection from ________, it is revealed by power that it is the ________ of God.", "s": "Resurrection is evident"}, {"q": "[Scripture Fill in the Blank] If Christ does not have ________, your letter is ________, and you are still in sin", "s": "Foundations of the Resurrection"}, {"q": "Jesus was conceived by the Virgin Mary from ________, unlike ordinary human birth", "s": "virgin pregnancy"}, {"q": "When Paul wrote his resurrection testimony in A.D. 55, all of Jesus'' contemporaries were still ________, and the resurrection could be tested.", "s": "contemporaneous testimony"}, {"q": "All eleven disciples of Jesus, with the exception of John the Elder, ________, no one will pay the price of their lives for the lies they made up.", "s": "Martyrdom Witness"}, {"q": "A piece of ________ is sealed at the door of Jesus'' tomb, and soldiers are guarding it outside.", "s": "Megaliths sealing the tomb"}, {"q": "Jesus publicly proclaimed many times during his lifetime that he would be resurrected ________ after his death", "s": "Three Day Resurrection"}, {"q": "Only by living a sinless life can Jesus qualify to replace ________ with a sinless one and become a sacrifice for salvation.", "s": "Innocence"}, {"q": "In this lesson, what is the most critical, publicly testable evidence that Jesus is “God for man”?", "s": "Evidence of the Resurrection", "o": "A.Virgin Pregnancy,B.Resurrection from the dead,C.Performing miracles while alive,D.Moral and noble"}, {"q": "Why is it not true that the disciples stole the body and invented the resurrection?", "s": "Refute the theory of corpse theft", "o": "A.Disciples are always honest,B.The disciples were scattered and afraid to approach the tomb, and no one would be martyred for their lies.,C.The disciple''s strength is too small to move the stone,D.Disciples can''t read or write the Bible"}, {"q": "Why must man be saved by Jesus, not by saying, “Believe in God only, and not in Jesus”?", "s": "God''s arrangement", "o": "A.It''s a church rule.,B.This is God''s arrangement: God is determined to pay the price of sin on the cross by the Beloved Son, and to believe in God is to accept all His arrangements,C.Because Jesus is more famous.,D.Because God is too far away to reach"}, {"q": "What facts make the claim that someone stole Jesus'' body untenable? (Multiple choice)", "s": "Empty Tomb Witness", "o": "A.The disciples were scared and did not dare to approach the tomb.,B.Eleven disciples were martyred for their testimony of the Resurrection, with the exception of John.,C.Jews and Romans were never able to come up with the body of Jesus.,D.The tomb is sealed with boulders and guarded by soldiers"}, {"q": "According to this lesson, how is Jesus different from a “deified person”? (Multiple choice)", "s": "Jesus is not deified", "o": "A.Jesus was conceived by a virgin inspired by the Holy Spirit,B.Jesus rises from the dead and the empty tomb can be publicly examined,C.Jesus is God to be man, not man to be deified,D.Jesus was just a good, virtuous man."}, {"q": "This lesson argues that virgin pregnancy alone is a perfect intellectual proof that Jesus is God and does not require proof of resurrection.", "s": "Level of evidence"}, {"q": "If Jesus had not been resurrected, the Christian faith would have been in vain.", "s": "Foundations of the Resurrection"}, {"q": "The statement that “Jesus did not really die on the cross, but later climbed himself out of the tomb” is consistent with historical facts.", "s": "Disprove the false death doctrine"}, {"q": "Why is the resurrection a key proof that Jesus is the Son of God? Please combine the instructions in this lesson.", "s": "Evidence of the Resurrection"}, {"q": "How does this lesson respond to the question “What man cannot do, God cannot do” (such as virgin birth)?", "s": "God''s Almighty"}]}, "ja": {"title": "レッスン5イエスはだれですか？", "content": "イエスは神の人であり，処女から生まれ，死者の中からよみがえられました。この課では，神と人との間の唯一の道としてのキリストの身分と働きを理解します。あなたがキリストを肯定し，キリストだけを信頼するようにしてください。主であられるかた以外に救いはありません。", "instructions": "", "guide": [{"title": "仲間の道教者の質問：イエスは神格化されましたか？", "points": ["ジーザスを神格化したんじゃなかったのか？一般的な宗教との違い", "Guan Gongmaozuは神ではありません、なぜイエスは神ですか？", "疑いを持つことは良いことであり、真理への欲求を示している"]}, {"title": "道は肉となる", "points": ["ヨハネ1 ： 14 ：御言葉は肉となり，わたしたちの間に住まわれた", "方向性は、神が人間になるということであり、人間が神になるということではありません。", "恵みと真理に満ちている"]}, {"title": "処女誕生児", "points": ["イエスは聖霊の霊感によって聖母マリアから生まれました", "「人にはできない、神にはできない」は矛盾している：人にはできないからこそ神が必要なのだ", "宇宙を創造した真の神が人間の理性を超えたことを行うことは完全に受け入れられます。"]}, {"title": "復活は証拠の中心です", "points": ["ローマ1 ： 4 ：死者の中からの復活のために，彼が神の子であることが力によって啓示されました", "1コリント15 ： 17 ：キリストが復活されなければ，説教と信仰は無駄になります", "復活は記念の物語ではなく、信仰の基礎です"]}, {"title": "空の墓は倒せません", "points": ["これは1世紀にテストすることができます：知るために墓に連れて行ってください", "弟子たちは盗みましたか？その時、彼らは逃げ出し、敢えて戻って来ませんでした。11弟子たちは復活を目撃したために殉教しました", "敵が盗む？ユダヤ人、ローマ人は死体を決して思いつかない。「不死説」は拷問、巨石、兵士の事実とは相容れない"]}, {"title": "なぜイエスなのか？", "points": ["真理は神の御手の中にあり、人間の手の中にはありません。", "神は，御自分の愛する御子が罪のない御子を罪深い御子の代わりにしてくださるよう手配され，わたしたちのために代価を払ってくださったのです。", "神を信じることは，神のすべての取り決めを心から受け入れることであり，自分で規則を定めることはできません。"]}, {"title": "ジーザスとは誰ですか？", "points": ["イエスは神の愛を示すために人として来られた方", "彼は贖いの犠牲となり，贖罪の犠牲となり，神と", "ヘブル4 ： 16 ：大胆に慈しみの座に着き，慈しみを受ける"]}], "quizzes": [{"q": "〔聖句の穴埋め〕御言葉は________となり，わたしたちの間に住み， ________の真理に満ちていました。", "s": "道の化身の体"}, {"q": "[空白の聖句を埋める]聖なる良い霊によれば、________からの復活のために、それが神の________であることが力によって啓示されています。", "s": "復活は明らかである"}, {"q": "〔聖句の穴埋め〕キリストが________を持っていない場合、あなたの手紙は________であり、あなたはまだ罪の中にいます", "s": "復活の基礎"}, {"q": "イエスは、通常の人間の誕生とは異なり、________から聖母マリアによって考案されました", "s": "処女妊娠"}, {"q": "パウロが西暦55年に復活の証を書いたとき，イエスの同時代の人々はまだすべて________であり，復活は試される可能性がありました。", "s": "同時代の証言"}, {"q": "長老ヨハネを除いて，イエスの11人の弟子全員が，自分たちが作った嘘のために命の代価を払うことはありません。", "s": "殉教の証人"}, {"q": "イエスの墓の戸口に________の破片が封印されており、兵士たちが外でそれを守っています。", "s": "墓を封印するメガリス"}, {"q": "イエスは生涯に何度も，自分が死後________に復活すると公に宣言しました", "s": "3日間の復活"}, {"q": "イエスは，罪のない人生を送ることによってのみ， ________を罪のない人生に置き換え，救いのための犠牲となる資格を得ることができます。", "s": "無実"}, {"q": "このレッスンでは，イエスが「人のための神」であるという最も重要で，公的に検証可能な証拠は何ですか。", "s": "復活の証拠", "o": "A.処女妊娠,B.死者の中からの復活,C.生きている間に奇跡を起こす,D.道徳と高貴さ"}, {"q": "弟子たちが体を盗んで復活を発明したというのは，なぜ真実ではないのでしょうか。", "s": "死体窃盗の理論に反論する", "o": "A.弟子は常に正直である,B.弟子たちは散り散りになり、墓に近づくことを恐れ、誰も彼らの嘘のために殉教することはありませんでした。,C.弟子の力が小さすぎて石を動かすことができません,D.弟子は聖書を読んだり書いたりできない"}, {"q": "「イエスを信じないで，神だけを信じなさい」と言わないで，なぜ人はイエスによって救われなければならないのでしょうか。", "s": "神の整理", "o": "A.これは教会の規則です。,B.これは神の取り決めです：神は愛する子によって十字架上の罪の代償を払うことを決意しており、神を信じることは神のすべての取り決めを受け入れることです,C.なぜなら、イエスはもっと有名だからです。,D.神は遠すぎて手が届かないから"}, {"q": "誰かがイエスの遺体を盗んだという主張には，どのような事実がありますか。（複数選択可）", "s": "空の墓の目撃者", "o": "A.弟子たちは怯え、墓に近づく勇気がありませんでした。,B.ヨハネを除いて，復活の証しのために11人の弟子が殉教しました。,C.ユダヤ人とローマ人はイエスの体を持ち出すことができませんでした。,D.墓は岩で封印され、兵士によって守られています"}, {"q": "このレッスンによると，イエスは「神格化された人」とどのように異なりますか。（複数選択可）", "s": "イエスは神格化されていない", "o": "A.イエスは聖霊に触発された処女によって考案されました,B.イエスは死者の中からよみがえられ、空の墓は公の場で調べることができます,C.イエスは人であるための神であり，神格化されるための人ではありません,D.イエスは善良で高潔な人でした。"}, {"q": "この課では，処女の妊娠だけが，イエスが神であるという完全な知的証拠であり，復活の証拠を必要としないと主張します。", "s": "エビデンスのレベル"}, {"q": "イエスが復活しなかったら，キリスト教の信仰は無駄になっていたでしょう。", "s": "復活の基礎"}, {"q": "「イエスは実際に十字架で死なれたのではなく，後に墓から上り下りした」という記述は，歴史的事実と一致しています。", "s": "偽りの死の教義を否定する"}, {"q": "なぜ復活は，イエスが神の子であることの鍵となる証拠なのでしょうか。このレッスンの指示を組み合わせてください。", "s": "復活の証拠"}, {"q": "この課は，「人にはできないこと，神にはできないこと」（処女懐胎など）という質問にどのように答えていますか。", "s": "全能の神"}]}, "ko": {"title": "제 5과 예수는 누구인가?", "content": "예수님은 동정녀에게서 태어나고 죽은 자 가운데서 부활하신 하나님의 사람이었습니다. 이 과는 하나님과 인간 사이의 유일한 길로서 그리스도의 정체성과 역사를 이해한다. 그리스도를 확증하고 그분만을 신뢰하게 하십시오. 주님이신 그분 외에는 구원이 없습니다.", "instructions": "", "guide": [{"title": "동료 도교도들의 질문: 예수가 신화되었는가?", "points": ["방금 예수님을 신격화하지 않았습니까? 일반 종교와 다른 점", "관공마오즈는 하나님이 아닌데, 왜 예수님은 하나님이신가?", "의심하는 것이 좋으며, 진리에 대한 열망을 나타냅니다."]}, {"title": "DAO가 육체가 됨", "points": ["요한복음 1:14: 말씀이 육신이 되어 우리 가운데 거하셨다", "방향은 신이 인간이 되는 것이지 인간이 신이 되는 것이 아닙니다.", "은혜와 진리가 충만함"]}, {"title": "처녀 출생 자녀", "points": ["예수님은 성령의 영감으로 동정녀 마리아에게서 태어나셨습니다.", "\"사람들이 할 수 없다면, 신은 할 수 없다\" 는 모순입니다. 신이 필요한 것은 그들이 할 수 없기 때문입니다.", "우주를 창조하신 참 하느님께서 인간의 이성을 초월한 일을 하시는 것은 완전히 용납될 수 있습니다."]}, {"title": "부활은 증거의 중심입니다", "points": ["로마서 1: 4: 죽은 자 가운데서 부활하심으로 말미암아 그가 하나님의 아들이심을 권능으로 나타내셨으니", "고린도전서 15:17: 그리스도께서 부활하지 않으셨다면, 설교와 믿음은 헛된 것입니다.", "부활은 기억의 이야기가 아니라 신앙의 기초입니다."]}, {"title": "빈 무덤은 전복될 수 없습니다", "points": ["1세기에 테스트할 수 있습니다. 무덤으로 이동하여 알아보세요.", "제자들이 훔쳤다고요? 그때 그들은 도망쳤고 감히 돌아오지 못했습니다. 11 제자들은 부활을 목격했다는 이유로 순교를 당했습니다.", "적이 훔친다고요? 유대인들, 로마인들은 결코 시체를 내놓지 않습니다. \"죽음 없는 이론\" 은 고문, 거석, 병사들의 사실과 양립할 수 없습니다."]}, {"title": "왜 예수인가?", "points": ["진리는 사람의 손이 아니라 하나님의 손에 있습니다.", "하나님께서는 그분의 사랑하는 아들이 죄 없는 자들을 대신하여 우리를 대신하여 대가를 치르게 하셨습니다.", "하나님을 믿는 것은 그분의 모든 준비를 진심으로 받아들이는 것이며 스스로 규칙을 정할 수 없습니다."]}, {"title": "예수님은 누구신가요?", "points": ["예수님은 하나님의 사랑을 나타내기 위해 사람으로 오신 분입니다.", "그는 구속의 희생이 되었고, 속죄의 희생이 되었으며, 하나님과 하나님과의 관계의 회복이 되었다.", "히브리서 4:16: 대담하게 속죄소에 와서 자비를 받으십시오."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 말씀은 ________ 이 (가) 되었고, 우리 가운데 살고 있으며, ________ 진리로 가득 차 있습니다", "s": "DAO 화신 몸"}, {"q": "[Scripture Fill in the Blank] 거룩하고 선한 영에 따라 ________ 로부터의 부활로 인해 하나님의 ________ 이라는 것이 권능으로 드러납니다.", "s": "부활이 분명합니다"}, {"q": "[Scripture Fill in the Blank] 그리스도께 ________ 가 없다면, 당신의 편지는 ________ 이며, 당신은 여전히 죄 가운데 있습니다", "s": "부활의 기초"}, {"q": "예수님은 일반적인 인간의 출생과는 달리 ________ 에서 동정녀 마리아에 의해 잉태되었습니다.", "s": "처녀 임신"}, {"q": "바울이 서기 55년에 부활 간증을 썼을 때, 예수님의 동시대 사람들은 모두 여전히 ________ 였고, 부활은 시험받을 수 있었습니다.", "s": "동시대의 증언"}, {"q": "장로 요한을 제외하고 예수님의 열한 제자 모두 ________ 을 (를) 제외하고는 아무도 그들이 지어낸 거짓말에 대한 대가를 치르지 않을 것입니다.", "s": "순교 증인"}, {"q": "예수님의 무덤 문에 ________ 조각이 봉인되어 있고, 병사들이 밖에서 지키고 있습니다.", "s": "무덤을 봉인하는 거석"}, {"q": "예수께서는 생전에 자신이 죽은 후 ________ 부활할 것이라고 여러 번 공개적으로 선언하셨습니다.", "s": "3일 부활"}, {"q": "예수님은 죄 없는 삶을 사셔야만 ________ 을 (를) 죄 없는 삶으로 대체하고 구원을 위한 희생이 될 수 있습니다.", "s": "무죄"}, {"q": "이 수업에서 예수님이 “인간을 위한 하나님” 이라는 가장 비판적이고 공개적으로 입증할 수 있는 증거는 무엇인가?", "s": "부활의 증거", "o": "A.처녀 임신,B.죽은 자 가운데서 부활,C.살아있는 동안 기적 수행,D.도덕적이고 고귀한"}, {"q": "제자들이 시신을 훔치고 부활을 발명했다는 것은 왜 사실이 아닌가?", "s": "시체 절도 이론 반박", "o": "A.제자들은 항상 정직합니다,B.제자들은 흩어져서 무덤에 다가가는 것을 두려워했고, 아무도 그들의 거짓말 때문에 순교하지 않았습니다.,C.돌을 옮기기에는 제자의 힘이 너무 작습니다.,D.제자들은 성경을 읽거나 쓸 수 없습니다"}, {"q": "왜 인간은 “예수가 아니라 하나님만 믿어라” 라는 말이 아니라 예수로 말미암아 구원받아야 하는가?", "s": "하나님의 준비", "o": "A.그것은 교회의 규칙입니다.,B.이것은 하나님의 준비입니다: 하나님은 사랑하는 아들에 의해 십자가에서 죄의 값을 지불하기로 결정하고, 하나님을 믿는 것은 그의 모든 준비를 받아들이는 것입니다,C.예수님이 더 유명하니까.,D.신이 도달하기에는 너무 멀리 있기 때문에"}, {"q": "누군가가 예수님의 시신을 훔쳤다는 주장을 지지할 수 없게 만드는 사실은 무엇인가? (복수 선택)", "s": "빈 무덤 목격자", "o": "A.제자들은 겁에 질려 감히 무덤에 다가가지 못했다.,B.요한을 제외한 11명의 제자가 부활에 대한 간증을 위해 순교했다.,C.유대인과 로마인은 결코 예수님의 시체를 생각해 낼 수 없었습니다.,D.무덤은 바위로 봉인되어 있고 군인들이 지키고 있습니다."}, {"q": "이 교훈에 따르면, 예수님은 “신명기” 와 어떻게 다른가? (복수 선택)", "s": "예수님은 신화되지 않았습니다", "o": "A.예수님은 성령의 영감을 받은 동정녀에게서 잉태되셨습니다.,B.예수님은 죽은 자 가운데서 부활하셨고 빈 무덤은 공개적으로 조사될 수 있습니다.,C.예수님은 사람이 되셔야 할 하나님이시지, 신성화되어야 할 분이 아닙니다.,D.예수님은 착하고 고결한 분이셨어요."}, {"q": "이 과는 동정녀 임신만이 예수님이 하나님이시며 부활의 증거가 필요하지 않다는 완전한 지적 증거라고 주장한다.", "s": "증거 수준"}, {"q": "예수님이 부활하지 않았다면 기독교 신앙은 헛수고였을 것입니다.", "s": "부활의 기초"}, {"q": "“예수님은 실제로 십자가에서 돌아가신 것이 아니라 나중에 무덤에서 자신을 등반하셨습니다.” 라는 진술은 역사적 사실과 일치합니다.", "s": "거짓 사망 교리를 반증하십시오"}, {"q": "부활이 예수님이 하나님의 아들이라는 중요한 증거인 이유는 무엇인가? 이 수업의 지침을 결합하십시오.", "s": "부활의 증거"}, {"q": "이 수업은 “사람이 할 수 없는 것, 하나님이 할 수 없는 것” (예: 동정녀 출산) 이라는 질문에 어떻게 반응하는가?", "s": "전능하신 하나님"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773052626274','基要真理','第六课 圣灵','圣灵是三位一体真神中的一位，是保惠师，内住在信徒里面。本课认识圣灵的位格与工作，学习分辨并顺服祂的带领。愿你经历圣灵的同在与能力。让圣灵充满你每一天的生活。','[{"a": "保惠师|真理", "o": "《约翰福音》14章16节", "q": "耶稣说：我要求父，父就另外赐给你们一位________，就是________的圣灵，叫祂永远与你们同在。", "s": "保惠师", "type": "verse"}, {"a": "仁爱|喜乐", "o": "《加拉太书》5章22节", "q": "圣灵所结的果子，就是________、________、和平、忍耐、恩慈、良善、信实、温柔、节制。", "s": "圣灵的果子", "type": "verse"}, {"a": "意思|圣灵", "o": "《约翰福音》3章8节", "q": "耶稣对尼哥底母说：风随着自己的________吹，你听见风的响声，却不晓得从哪里来，往哪里去；凡从________生的，也是如此。", "s": "圣灵重生", "type": "verse"}, {"a": "良知良能", "o": "", "q": "圣灵是三位一体真神中的一位，祂不是人的________。", "s": "圣灵不是良心", "type": "fill"}, {"a": "圣灵", "o": "", "q": "听了道、信了福音的基督徒，有________成为印记住在生命里。", "s": "圣灵印记", "type": "fill"}, {"a": "旧人", "o": "", "q": "圣灵带领我们脱下________，穿上新人，迎接真理进来。", "s": "脱下旧人", "type": "fill"}, {"a": "消灭", "o": "", "q": "圣经提醒我们：不要________圣灵的感动。", "s": "消灭感动", "type": "fill"}, {"a": "意思", "o": "", "q": "圣灵随祂自己的________，把特殊的恩赐分给不同的人。", "s": "恩赐主权", "type": "fill"}, {"a": "神", "o": "", "q": "以马内利的意思是________与人同在。", "s": "以马内利", "type": "fill"}, {"a": "B", "o": "A.天使,B.保惠师圣灵,C.先知,D.使徒", "q": "耶稣应许向父求，谁来永远与信徒同在？", "s": "保惠师", "type": "single"}, {"a": "C", "o": "A.感动催逼,B.安慰鼓励,C.包办一切事务,D.禁止管教", "q": "以下哪一项不是视频中提到的圣灵在信徒生命中的工作？", "s": "圣灵工作", "type": "single"}, {"a": "B", "o": "A.两者完全一样,B.良心会麻木泯灭，圣灵持续做工,C.圣灵会停止做工,D.良知也是神的一位", "q": "关于圣灵与良知良能的区别，正确的是？", "s": "圣灵与良知", "type": "single"}, {"a": "A|B|D", "o": "A.仁爱,B.喜乐,C.贪婪,D.节制", "q": "视频提到圣灵的果子包括哪些？（多选）", "s": "圣灵九果", "type": "multiple"}, {"a": "A|B|D", "o": "A.叫世人为罪、为义、为审判自己责备自己,B.感动人谦卑认罪,C.代替人做决定,D.帮助信徒想起神的话", "q": "圣灵在传福音中的工作包括哪些？（多选）", "s": "圣灵与传福音", "type": "multiple"}, {"a": "错", "o": "", "q": "圣灵只是基督徒的一种心理感受，不是真神的一位。", "s": "圣灵是神", "type": "judge"}, {"a": "对", "o": "", "q": "人可以消灭圣灵的感动，但不能消灭圣灵自己。", "s": "消灭感动", "type": "judge"}, {"a": "错", "o": "", "q": "拥有圣灵内住的人自然就会得到医病、说预言等特殊恩赐。", "s": "特殊恩赐", "type": "judge"}, {"a": "良知良能会麻木、泯灭，会随世界标准降低而失去功能；圣灵是真神的一位，不会因人的软弱停止做工。即使人消灭感动不理祂，祂仍继续做工，这正是神永不放弃的爱。", "o": "", "q": "为什么说圣灵与人的良知良能不一样？请结合视频内容说明。", "s": "圣灵与良知", "type": "essay"}, {"a": "带领信徒生命更新：脱下旧人、穿上新人，活出真理的仁义和圣洁，结出圣灵的果子。祂天天感动、催逼、安慰、禁止、带领、管教，使信徒的生命不断被改变。", "o": "", "q": "圣灵在基督徒生命中最主要的工作是什么？", "s": "生命更新", "type": "essay"}]','https://youtu.be/P3649cpBf5k
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134FWpN','quiz','[{"title": "圣灵是谁：三位一体中的一位", "points": ["圣父、圣子、圣灵是三位一体真神中的一位，同尊同荣", "不能用有限的人去局限无限的神，圣经既启示就谦卑领受", "理性在绝大部分真理上够用，唯在奥秘上用信心替代困惑"]}, {"title": "圣灵不是良知良能", "points": ["良心会麻木、泯灭，会被世界标准不断调整拉低", "圣灵在信徒生命中的工作不会因人的软弱而停止", "你可以消灭圣灵的感动（不理他），但不能消灭圣灵"]}, {"title": "保惠师的应许：永远同在", "points": ["主耶稣应许：求父赐下保惠师，就是真理的圣灵，永远同在", "以弗所书一章：听了真道、信了福音，就受了圣灵为印记", "以马内利（神与人同在）借着圣灵内住成为真实经历"]}, {"title": "圣灵的工作：生命更新", "points": ["带领信徒天天脱下旧人、穿上新人，活出真理的仁义和圣洁", "结出圣灵九果：仁爱、喜乐、和平、忍耐、恩慈、良善、信实、温柔、节制", "我们原是神的工作，在基督耶稣里造成的杰作"]}, {"title": "圣灵的感动与带领", "points": ["催逼、感动、鼓励、安慰、禁止、带领、管教", "常提醒我们想起神的话，知道行事为人的原则", "叫世人为罪、为义、为审判自己责备自己，领人信主"]}, {"title": "特殊恩赐与神迹", "points": ["医病、说方言、预言等特殊恩赐确实存在", "圣灵随自己的意思赐给不同的人，目的都是把人带到神面前", "圣灵最大的能力是改变人自己，而非改变环境"]}, {"title": "圣灵是得救的印记", "points": ["印记证明你是得救的，与神恢复了关系", "印记证明你在他的保守、带领与赐福之中", "风随着意思吹：看不见摸不着，却能真实经历他的存在"]}]','','6','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 6 The Holy Spirit", "content": "The Holy Spirit is one of the true Gods of the Trinity, the Comforter, who dwells within the believer. This lesson is about recognizing the person and work of the Holy Ghost and learning to discern and submit to His leadership. May you experience the presence and power of the Holy Spirit. Fill your daily life with the Holy Ghost.", "instructions": "", "guide": [{"title": "Who is the Holy Spirit: One in the Trinity?", "points": ["The Father, the Son, and the Holy Spirit are one and the same God in the Trinity.", "You can''t use a limited number of people to limit the infinite God, the Bible humbly receives from revelation", "Reason is sufficient for most truths, but mysteriously substitutes faith for confusion."]}, {"title": "The Holy Spirit is not conscience", "points": ["Conscience will be numb and annihilated, and will be constantly adjusted and lowered by world standards", "The work of the Holy Spirit in the life of believers does not stop because of human weakness", "You can extinguish the Holy Spirit''s touch (ignore him), but you cannot extinguish the Holy Spirit"]}, {"title": "The Marshal''s Promise: Always", "points": ["The Lord Jesus'' Promise: Ask the Father for a Helper, the Spirit of Truth, to be with you forever", "Ephesians 1: Having heard the truth and believed the gospel, he received the seal of the Holy Spirit", "Immanuel (God is with man) through the indwelling of the Holy Spirit as a real experience"]}, {"title": "The Work of the Holy Spirit: Life Updates", "points": ["Lead the believer to take off the old man every day, put on the new man, and live the righteousness and holiness of the truth.", "Produce the nine fruits of the Holy Spirit: benevolence, joy, peace, patience, kindness, goodness, faithfulness, gentleness, temperance", "We are God''s workmanship, a masterpiece created in Christ Jesus"]}, {"title": "Moved and guided by the Holy Spirit", "points": ["urging, touching, encouraging, comforting, forbidding, leading, disciplining", "Always remind us of the Word of God and know the principles of conduct", "Let the world blame itself for sin, for righteousness, for judging oneself, and lead people to believe in the Lord"]}, {"title": "Special gifts and miracles", "points": ["Special gifts such as healing, speaking in tongues, and prophecy do exist", "The Holy Spirit is given to different people according to their own wishes, and the purpose is to bring people to God.", "The Holy Spirit''s greatest power is to change the person, not the environment."]}, {"title": "The Holy Spirit is the seal of salvation", "points": ["The seal proves that you were saved and restored to relationship with God", "The seal proves that you are in his conservative, leading and blessing", "The wind blows with intention: you can''t see it, you can''t touch it, but you can really experience his existence"]}], "quizzes": [{"q": "Jesus saith unto them, I will ask the Father, and he shall give you another ________, the Holy Ghost of ________, that he may be with you for ever.", "s": "Guarantor"}, {"q": "The fruit of the Holy Spirit is ________, ________, peace, patience, kindness, goodness, faithfulness, gentleness, temperance.", "s": "<bpt i=\"1\" type=\"bold\">{}</bpt>The Fruit of the Spirit<ept i=\"1\">{}</ept>"}, {"q": "And Jesus said unto Nicodemus, The wind bloweth with thine own ________, and thou hearest the sound of the wind, and knowest not where it cometh and where it goeth; neither is he that is born of ________.", "s": "Holy Spirit Rebirth"}, {"q": "The Holy Spirit is one of the true Gods of the Trinity, who is not the ________ of man.", "s": "The Holy Spirit is not conscience"}, {"q": "Christians who have heard the word and believed the gospel have ________ as a mark to live in.", "s": "Holy Spirit Mark"}, {"q": "The Holy Spirit leads us to take off the ________, put on the new person, and welcome the truth in.", "s": "Take off the old man"}, {"q": "The Bible reminds us not to be moved by the Holy Spirit.", "s": "Destroy Motion"}, {"q": "The Holy Spirit distributes special gifts to different people according to His own ________.", "s": "Gift Sovereignty"}, {"q": "Immanuel means ________ to be with people.", "s": "Emanuel"}, {"q": "Who will be with the believers forever, as Jesus promised to ask the Father?", "s": "Guarantor", "o": "A.Angel,B.Paramedic Holy Spirit,C.prophet,D.apostle"}, {"q": "Which of the following is not the work of the Holy Spirit in the life of a believer mentioned in the video?", "s": "Holy Spirit Work", "o": "A.Touching and urging,B.Placebo Encouragement,C.Arranging everything,D.No Discipline"}, {"q": "What is the difference between the Holy Spirit and conscience and goodness?", "s": "The Holy Spirit and Conscience", "o": "A.Exactly the same,B.Conscience will be numb and the Holy Spirit will continue to work,C.The Holy Spirit will stop working,D.Conscience is also one of God"}, {"q": "What does the video mention about the fruit of the Holy Spirit? (Multiple choice)", "s": "Holy Spirit Nine Fruit", "o": "A.Nhon Ai,B.joy,C.Greedy,D.Temperance"}, {"q": "What does the work of the Holy Ghost in evangelism include? (Multiple choice)", "s": "The Holy Spirit and Evangelism", "o": "A.Let the world condemn itself for sin, for righteousness, for judgment.,B.Moving Humility to Plead Guilty,C.Making decisions on behalf of others,D.Helping believers remember the Word of God"}, {"q": "The Holy Spirit is only a psychological feeling among Christians, not one of the true Gods.", "s": "The Holy Spirit is God"}, {"q": "One can extinguish the impulse of the Holy Spirit, but one cannot extinguish the Spirit Himself.", "s": "Destroy Motion"}, {"q": "Those who have the indwelling of the Holy Spirit will naturally receive special gifts such as healing and prophecy.", "s": "Special Gift"}, {"q": "Why is the Holy Spirit different from the conscience of man? Please combine the description with the video content.", "s": "The Holy Spirit and Conscience"}, {"q": "What is the Holy Spirit''s primary work in the Christian life?", "s": "Life Updates"}]}, "ja": {"title": "レッスン6聖霊", "content": "聖霊は、信者の中に住む三位一体の真の神、慰め主の一人です。この課では，聖霊の人格と業を認識し，聖霊の指導力を見分け，従うことを学びます。聖霊の臨在と力を経験してくださいますように。日常生活を聖霊で満たしましょう。", "instructions": "", "guide": [{"title": "聖霊とはだれですか：三位一体の一人ですか？", "points": ["御父、御子、聖霊は、三位一体の同一の神です。", "無限の神を制限するために限られた数の人々を使うことはできません、聖書は謙虚に啓示から受け取ります", "理由はほとんどの真理には十分ですが、神秘的に混乱の代わりに信仰を置き換えます。"]}, {"title": "聖霊は良心ではない", "points": ["良心は麻痺して消滅し、世界基準で絶えず調整され、低下します", "信者の生活における聖霊の働きは、人間の弱さのために止まることはありません", "聖霊の触れを消す（無視する）ことはできますが、聖霊を消すことはできません"]}, {"title": "元帥の約束：常に", "points": ["主イエスの約束：永遠にあなたと共におられるように，真理の御霊である助け主を父に願い求めましょう", "エペソ1 ：真理を聞き，福音を信じて，聖霊の印を受けた", "インマヌエル（神は人と共におられる）は、実際の経験として聖霊の内在を通して"]}, {"title": "聖霊の働き：人生の最新情報", "points": ["信者を導いて，毎日古い人を脱ぎ捨て，新しい人を着て，真理の義と聖さを実践してください。", "聖霊の九つの実を結ぶ：慈悲，喜び，平安，忍耐，親切，善良，忠実，優しさ，節制", "わたしたちは神の作品であり，キリスト・イエスにあって創造された傑作です"]}, {"title": "聖霊に動かされ導かれて", "points": ["促す、触れる、励ます、慰める、禁止する、導く、懲らしめる", "常に神の言葉を思い起こさせ，行動の原則を知る", "世は，罪，義，自分自身を裁くことを自分のせいにし，人々が主を信じるように導きましょう。"]}, {"title": "特別な贈り物と奇跡", "points": ["癒し、異言を話すこと、預言などの特別な賜物は存在します", "聖霊は自分の望みに従って異なる人々に与えられており、その目的は人々を神のもとに連れて行くことです。", "聖霊の最大の力は，人を変えることであり，環境を変えることではありません。"]}, {"title": "聖霊は救いの印", "points": ["封印は，あなたが救われ，神との関係を回復したことを証明しています", "封印は、あなたが彼の保守的で、指導的で、祝福されていることを証明しています", "風は意図的に吹きます：あなたはそれを見ることはできません、あなたはそれに触れることはできませんが、あなたは本当に彼の存在を体験することができます"]}], "quizzes": [{"q": "イエスは彼らに言われた。「わたしは父に願います。父は別の________、________の聖霊をお与えになり、永遠にあなたがたと共におられるようにしてくださいます。」", "s": "保証人"}, {"q": "聖霊の実りは， ________ ， ________ ，平安，忍耐，優しさ，善良さ，忠実さ，優しさ，節制です。", "s": "聖霊の実"}, {"q": "イエスはニコデモに言われた、「風はあなた自身の________で吹き、あなたは風の音を聞き、それがどこから来るのか、どこへ行くのかを知りません。________から生まれた者でもありません。", "s": "聖霊の再生"}, {"q": "聖霊は三位一体の真の神の一人であり，人間の________ではありません。", "s": "聖霊は良心ではない"}, {"q": "この言葉を聞いて福音を信じたクリスチャンは， ________を生きるためのしるしとして持っています。", "s": "聖霊の刻印"}, {"q": "聖霊は，わたしたちが________を脱ぎ，新しい人を身につけ，真理を受け入れるよう導いてくださいます。", "s": "老人を脱ぐ"}, {"q": "聖書は，聖霊に動かされないようにと思い起こさせています。", "s": "モーションを破壊"}, {"q": "聖霊は，御自身の________に従って，異なる人々に特別な賜物を配ります。", "s": "主権を贈る"}, {"q": "インマヌエルとは、人と一緒にいることを意味します。", "s": "イマヌエル"}, {"q": "イエスは父なる神に「信じる者たちと永遠に共にいるのは誰ですか？」と尋ねると約束した。", "s": "保証人", "o": "A.天使,B.救急隊員の聖霊,C.預言者,D.使徒"}, {"q": "ビデオで言及されている信者の生活における聖霊の働きではないのは，次のうちどれですか。", "s": "聖霊の働き", "o": "A.感動と衝動,B.プラセボ奨励,C.すべてを手配する,D.規律がありません"}, {"q": "聖霊と良心と善との違いは何ですか。", "s": "聖霊と良心", "o": "A.まったく同じ,B.良心は麻痺し、聖霊は働き続けます,C.聖霊が働きを止める,D.良心もまた神のものである"}, {"q": "ビデオでは，聖霊の実についてどのようなことが言及されていますか。（複数選択可）", "s": "聖霊九果", "o": "A.ノンアイ,B.喜び,C.グリード,D.テンペランス"}, {"q": "伝道における聖霊の働きには，どのようなものが含まれますか。（複数選択可）", "s": "聖霊と福音伝道", "o": "A.世界は罪、義、裁きのために自分自身を非難しましょう。,B.謙虚さをもって有罪を認める,C.他者に代わって意思決定を行う,D.信者が神の言葉を覚えるのを助ける"}, {"q": "聖霊はクリスチャンの間の心理的な感情に過ぎず、真の神ではありません。", "s": "聖霊は神である"}, {"q": "聖霊の衝動を消すことはできますが、聖霊自身を消すことはできません。", "s": "モーションを破壊"}, {"q": "聖霊の住まいを持つ人は，当然，癒しや預言などの特別な賜物を受け取ります。", "s": "スペシャルギフト"}, {"q": "なぜ聖霊は人間の良心と違うのでしょうか。説明と動画コンテンツを組み合わせてください。", "s": "聖霊と良心"}, {"q": "クリスチャン生活における聖霊の主な働きは何ですか。", "s": "ライフアップデート"}]}, "ko": {"title": "제 6과 성령", "content": "성령은 믿는 자 안에 거하시는 보혜사 삼위일체의 참 하나님 중 한 분입니다. 이 수업은 성신의 인격과 역사를 인식하고 그분의 리더십을 분별하고 복종하는 법을 배우는 것이다. 성령의 임재와 권능을 경험하게 하소서. 여러분의 일상을 성신으로 채우십시오.", "instructions": "", "guide": [{"title": "성령은 누구인가: 삼위일체 안에 한 분이신가?", "points": ["성부, 성자, 성령은 삼위일체 안에서 한 분 하나님이십니다.", "무한하신 하나님을 제한하기 위해 제한된 수의 사람들을 사용할 수는 없습니다. 성경은 겸손하게 계시를 받습니다.", "대부분의 진리에는 이성이 충분하지만, 신비롭게도 신앙을 혼란으로 대체합니다."]}, {"title": "성령은 양심이 아닙니다", "points": ["양심은 무감각해지고 소멸될 것이며, 세계 표준에 따라 끊임없이 조정되고 낮아질 것입니다.", "신자들의 삶에서 성령의 역사는 인간의 연약함 때문에 멈추지 않습니다.", "성령의 감동을 소멸시킬 수는 있지만 (무시할 수는 없다), 성령을 소멸시킬 수는 없다."]}, {"title": "원수의 약속: 항상", "points": ["주 예수님의 약속: 아버지께 영원히 너희와 함께할 돕는 자 곧 진리의 영을 구하라", "에베소서 1장: 진리를 듣고 복음을 믿은 그는 성령의 인을 받았다.", "임마누엘 (하나님께서 인간과 함께 계심) 은 실제 경험으로서 성령의 내주하심을 통해"]}, {"title": "성령의 역사: 생명 업데이트", "points": ["신자가 매일 옛 사람을 벗고 새 사람을 입으며 진리의 의로움과 거룩함을 실천하도록 인도하십시오.", "성령의 아홉 가지 열매를 맺으십시오: 자비, 기쁨, 평화, 인내, 친절, 선, 신실, 온유, 절제", "우리는 하나님의 작품이며, 그리스도 예수 안에서 창조된 걸작품입니다."]}, {"title": "성령의 감동과 인도하심을 받음", "points": ["촉구, 만지기, 격려, 위로하기, 금지하기, 이끌기, 훈육하기", "항상 하나님의 말씀을 상기시키고 행동의 원리를 아십시오", "세상이 스스로 죄와 의로움을 탓하고 스스로 판단하게 하시고, 사람들이 주님을 믿게 하소서."]}, {"title": "특별한 선물과 기적", "points": ["치유, 방언, 예언과 같은 특별한 은사가 존재합니다", "성령은 각자의 소원에 따라 다른 사람들에게 주어지며, 그 목적은 사람들을 하나님께로 인도하는 것입니다.", "성령의 가장 큰 능력은 환경이 아니라 사람을 변화시키는 것입니다."]}, {"title": "성령은 구원의 인이다", "points": ["인은 당신이 구원받았고 하나님과의 관계로 회복되었다는 것을 증명합니다", "인장은 당신이 그의 보수적이고 주도적이며 축복을 받고 있음을 증명합니다.", "바람은 의도적으로 불어옵니다: 당신은 그것을 볼 수 없고, 만질 수 없지만, 당신은 그의 존재를 실제로 경험할 수 있습니다."]}], "quizzes": [{"q": "예수께서 이르시되 내가 아버지께 구하겠으니 그가 또 다른 ________, 곧 ________ 의 성신을 너희에게 주사 영원토록 너희와 함께 있게 하시리니", "s": "보증인"}, {"q": "성령의 열매는 ________, ________, 평화, 인내, 친절, 선, 신실, 온유, 절제입니다.", "s": "성령의 열매"}, {"q": "예수께서 니고데모에게 이르시되 바람이 네 ________ 에 불매 네가 바람 소리를 듣고 어디로서 오며 어디로 가는지 알지 못하나니 ________ 에서 난 자도 없느니라", "s": "성령 거듭남"}, {"q": "성령은 인간의 ________ 이 아닌 삼위일체의 참된 신들 중 하나입니다.", "s": "성령은 양심이 아닙니다"}, {"q": "말씀을 듣고 복음을 믿은 그리스도인들은 ________ 을 (를) 살기 위한 표식으로 삼고 있습니다.", "s": "성령 마크"}, {"q": "성령께서는 우리로 하여금 ________ 을 벗고, 새 사람을 입고, 진리를 영접하도록 인도하십니다.", "s": "노인을 벗겨라"}, {"q": "성경은 우리에게 성령의 감동을 받지 말라고 일깨워 줍니다.", "s": "감정을 제거하세요"}, {"q": "성령께서는 자신의 ________ 에 따라 다른 사람들에게 특별한 은사를 나누어 주십니다.", "s": "은사 주권"}, {"q": "임마누엘은 ________ 을 (를) 사람들과 함께 한다는 의미입니다.", "s": "이매뉴얼"}, {"q": "예수님께서 아버지께 구하겠다고 약속하신 대로 믿는 자들과 영원히 함께할 사람은 누구입니까?", "s": "보증인", "o": "A.천사,B.구급대원 성령,C.예언자,D.사도"}, {"q": "다음 중 영상에서 성령께서 신자의 삶에서 행하시는 사역으로 언급되지 않은 것은 무엇입니까?", "s": "성령의 사역", "o": "A.만지고 재촉하기,B.위약 격려,C.모든 것 정리하기,D.징계 없음"}, {"q": "성령과 양심과 선의 차이점은 무엇인가?", "s": "성령과 양심", "o": "A.정확히 동일함,B.양심은 무감각해지고 성령님은 계속해서 일하실 것입니다.,C.성령께서 더 이상 일하지 않으실 것입니다.,D.양심도 하나님의 하나이다"}, {"q": "이 동영상은 성령의 열매에 대해 무엇을 언급하는가? (복수 선택)", "s": "성령의 아홉 가지 열매", "o": "A.자비,B.기쁨,C.탐심,D.절제"}, {"q": "복음주의에서 성신의 사업에는 무엇이 포함되는가? (복수 선택)", "s": "성령과 전도", "o": "A.세상은 죄로 인해, 의로움으로 인해, 심판으로 인해 스스로를 정죄해야 합니다.,B.겸손을 죄책감으로 옮기기,C.다른 사람을 대신하여 의사 결정하기,D.신자들이 하나님의 말씀을 기억하도록 돕는다."}, {"q": "성령은 그리스도인들 사이의 심리적 느낌일 뿐, 참된 신들 중 하나가 아닙니다.", "s": "성령은 하나님이십니다"}, {"q": "성령의 충동을 소멸시킬 수는 있지만 성령 자체를 소멸시킬 수는 없습니다.", "s": "모션 파괴"}, {"q": "성령의 내주하심을 가진 자들은 자연히 치유와 예언과 같은 특별한 은사를 받게 될 것이다.", "s": "특별 선물"}, {"q": "성령은 왜 인간의 양심과 다른가? 설명과 동영상 콘텐츠를 결합하세요.", "s": "성령과 양심"}, {"q": "그리스도인의 삶에서 성령의 주요 사업은 무엇인가?", "s": "수명 업데이트"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773053216845','基要真理','第七课 三位一体','独一真神有圣父、圣子、圣灵三个位格，同质同荣。本课思想三位一体超越理性的奥秘，以及它对信仰生活的意义。愿这奥秘坚固你对神的敬畏。三一真神配得我们全然敬拜。','[{"a": "除了|别的", "o": "《出埃及记》20章3节", "q": "十诫第一条说：________我以外，你不可有________的神。", "s": "独一真神", "type": "verse"}, {"a": "奇妙策士|永在的父", "o": "《以赛亚书》9章6节", "q": "必有一婴孩为我们而生，政权必担在祂的肩头上；祂名称为________、全能的神、________、和平的君。", "s": "婴孩预言", "type": "verse"}, {"a": "我与父", "o": "《约翰福音》10章30节", "q": "耶稣说：________原为一。", "s": "原为一", "type": "verse"}, {"a": "本质", "o": "", "q": "三位一体的“体”原文是Substance，指________。", "s": "体的含义", "type": "fill"}, {"a": "一位", "o": "", "q": "圣父是神，圣子是神，圣灵也是神，但神只有________。", "s": "独一真神", "type": "fill"}, {"a": "圣灵", "o": "", "q": "圣父不是圣子，圣子不是________，圣灵也不是圣父。", "s": "三位格", "type": "fill"}, {"a": "圣父受苦说", "o": "", "q": "早期教会把“圣父变成圣子再变成圣灵”的说法定为异端，叫________。", "s": "异端", "type": "fill"}, {"a": "次序", "o": "", "q": "耶稣说“父是比我大的”，是指救恩计划执行上的________，不是本质有大小。", "s": "父比我大", "type": "fill"}, {"a": "收取", "o": "", "q": "大卫在诗篇51篇中祷告：求祢不要从我________祢的圣灵。", "s": "大卫祷告", "type": "fill"}, {"a": "B", "o": "A.圣父就是圣子,B.在救恩工作上完全一致,C.两人变成一人,D.本质有大小", "q": "“我与父原为一”指的是什么？", "s": "原为一", "type": "single"}, {"a": "B", "o": "A.水没有本质,B.水的三态不能同时存在,C.水太少,D.圣经禁止比喻", "q": "为什么不能用水有固态、液态、气态来解释三位一体？", "s": "比喻局限", "type": "single"}, {"a": "A", "o": "A.那位以神第一人称说话、接受敬拜的使者,B.大卫,C.摩西,D.以利亚", "q": "旧约中哪一位的记载与一般天使不同，被认为指向神自己？", "s": "旧约证据", "type": "single"}, {"a": "A|B|C", "o": "A.圣父是神,B.圣子是神,C.圣灵是神,D.圣父就是圣子", "q": "三位一体的正统表述包括哪些？（多选）", "s": "三一表述", "type": "multiple"}, {"a": "A|B|C", "o": "A.客西马尼园耶稣变成在跟自己祷告,B.十字架上“谁离弃谁”成了矛盾,C.若圣父死了，宇宙无人维护,D.完全符合圣经", "q": "视频指出“圣父受苦说”的错误包括哪些？（多选）", "s": "圣父受苦说", "type": "multiple"}, {"a": "错", "o": "", "q": "“三位一体”这四个字在圣经中可以找到。", "s": "神学名词", "type": "judge"}, {"a": "对", "o": "", "q": "圣灵在旧约时代已经在士师、君王、先知身上做工。", "s": "旧约圣灵", "type": "judge"}, {"a": "对", "o": "", "q": "能把三位一体解释得人人都清楚的人，一定讲错了。", "s": "三一奥秘", "type": "judge"}, {"a": "因为三位一体超越人的有限经验和理性，是神那边的特质；不能以有限的人去限制无限的神。正确的态度是谦卑领受圣经的启示，承认神与人不一样，同时用理性认真明白圣经中能明白的部分。", "o": "", "q": "为什么说三位一体是奥秘？基督徒应持什么态度？", "s": "三一奥秘", "type": "essay"}, {"a": "人造的偶像都按人的样子造——能力比人强却听人的话，游戏规则由人来定；真神超越人、与人不一样。三位一体正是显明祂超越人的理性与经验，这样的神是人造不出来的。", "o": "", "q": "人造偶像与真神有何根本区别？", "s": "人造偶像", "type": "essay"}]','https://youtu.be/MiT9WITmgEI
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134G5Ey','quiz','[{"title": "三位一体：神学名词的含义", "points": ["“三位一体”在圣经中找不到这四个字，是神学名词", "“体”原文是本质的意思：三个位格的神，只有一个本质", "这是历代圣徒读经时发现的神那边的特质"]}, {"title": "三一真理的四点定义", "points": ["圣父是神，圣子是神，圣灵也是神", "圣父不是圣子，圣子不是圣灵，圣灵也不是圣父：各自独立的位格", "神只有一位；三位一体是奥秘，超越人的理性经验"]}, {"title": "异端的鉴戒：圣父受苦说", "points": ["主张圣父变圣子、圣子变圣灵，只有一位轮流登场", "客西马尼园的祷告、十字架上的呼喊都成了自言自语，矛盾百出", "早期教会已将其定为异端，不合圣经"]}, {"title": "受造物的类比都不完全", "points": ["水有三态但不会同时存在；太阳光热能本质并不相同", "人有父亲、儿子、丈夫三重身份，但终究是同一个人", "以受造之物类比神，注定做不到完全"]}, {"title": "“父比我大”与“我与父原为一”", "points": ["“我与父原为一”指在救恩工作上完全一致", "“父是比我大的”指救恩计划执行上有策划者与执行者的次序", "本质上三者同尊同荣，没有大小之分"]}, {"title": "旧约中的三一痕迹", "points": ["耶和华的使者接受敬拜，以神第一人称说话", "以赛亚预言婴孩名称为“全能的神、永在的父”", "圣灵降在士师、君王、先知身上；大卫求“不要收回你的圣灵”"]}, {"title": "谦卑：神超越理性", "points": ["神的事情，人所能知道的原显明在人心里；也有些是人不能知道的", "理性不是判断一切的最后标准，它会随知识经验不断修正", "承认受造者的有限，谦卑领受创造主的启示"]}, {"title": "三一神与我们同在", "points": ["圣父早已为人预备救恩，圣子道成肉身完成救恩", "圣灵保惠师永远与信徒同在，带领活出新生命", "三一真神从旧约到新约，直到永恒都与我们同在"]}]','','7','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 7 Trinity", "content": "The one true God has three persons, the Father, the Son, and the Holy Spirit, who are homogeneous and equal in glory. In this lesson, the idea of the Trinity transcends the mysteries of reason and what it means for the life of faith. May this mystery strengthen your fear of God. Trinity is worthy of all our worship.", "instructions": "", "guide": [{"title": "Trinity: Meaning of Theological Nouns", "points": ["\"Trinity\" is a theological term that cannot be found in the Bible.", "\"Body\" is the original meaning of essence: three personalities of God, only one essence", "This is a characteristic of God''s side discovered by the saints in the past when they read the Bible."]}, {"title": "Four Definitions of Trinity", "points": ["The Father is God, the Son is God, and the Holy Spirit is God.", "The Father is not the Son, the Son is not the Holy Spirit, and the Holy Spirit is not the Father: separate persons", "There is only one God; the Trinity is a mystery that transcends human rational experience"]}, {"title": "Lessons from Heresy: The Suffering Sayings of the Holy Father", "points": ["Advocate that the Father becomes the Son and the Son becomes the Holy Spirit, and only one person takes turns to appear", "The prayers in the Garden of Gethsemane and the cries on the cross have become self-talking and contradictory.", "The early church had classified it as heresy, unbiblical."]}, {"title": "The analogy of creation is incomplete", "points": ["Water has three states but does not exist at the same time; the nature of solar thermal energy is not the same", "A person has the triple status of father, son, and husband, but it is the same person after all.", "By analogy with God, created things are destined to be incomplete."]}, {"title": "“The Father is greater than I” and “I and the Father are one”", "points": ["“I am one with the Father” means that there is complete agreement in the work of salvation", "\"The Father is greater than I am\" refers to the sequence of planners and executors in the execution of the plan of salvation", "In essence, the three are equally honored, and there is no distinction between size and size."]}, {"title": "Trinity in the Old Testament", "points": ["Jehovah''s messenger receives worship and speaks in the first person of God", "Isaiah prophesied that the baby''s name would be “Almighty God, Eternal Father”", "The Holy Spirit descends on judges, kings, prophets; David pleads, “Do not take your Holy Spirit back.”"]}, {"title": "Humility: God Transcends Reason", "points": ["The things of God that can be known by man are manifested in man''s heart; there are also things that cannot be known by man.", "Reason is not the final criterion for judging everything, it will continue to be corrected with knowledge and experience", "Acknowledging the limitedness of the Creator, humbly receiving revelation from the Creator"]}, {"title": "The Trinity is with us", "points": ["The Father has long prepared salvation for man, and the Son has become flesh to accomplish salvation", "The Spiritual Comforter is always with the believer, leading a new life", "The true God of the Trinity is with us from the Old Testament to the New Testament to eternity."]}], "quizzes": [{"q": "The first of the Ten Commandments says: Thou shalt have no gods other than ________ me.", "s": "Unique True God"}, {"q": "There shall be a child born unto us, and the government shall be upon his shoulders; and his name shall be called ________, God Almighty, ________, Prince of Peace.", "s": "Baby prophecy"}, {"q": "Jesus said: ________ Originally one.", "s": "Originally one"}, {"q": "The original text of the \"body\" of the Trinity is Substance, which refers to ________.", "s": "Meaning of body"}, {"q": "The Father is God, the Son is God, and the Holy Spirit is God, but God has only ________.", "s": "Unique True God"}, {"q": "The Father is not the Son, the Son is not ________, and the Holy Spirit is not the Father.", "s": "Three Persons"}, {"q": "The early Church characterized the claim that the Father became the Son and then the Holy Spirit as heresy, called ________.", "s": "heresy"}, {"q": "Jesus said that “the Father is greater than I”, referring to the execution of the plan of salvation ________, not the nature of size.", "s": "My father is older than me"}, {"q": "David prayed in Psalm 51: Please do not take your Holy Spirit from me ________.", "s": "David''s Prayer"}, {"q": "What does “I and the Father are one” mean?", "s": "Originally one", "o": "A.The Father is the Son,B.Totally aligned in the work of salvation,C.Two people become one person,D.Intrinsic size"}, {"q": "Why can''t the Trinity be explained by the solid, liquid, and gaseous state of water?", "s": "Parable Limitations", "o": "A.Water has no essence,B.The three states of water cannot exist at the same time,C.it means that the sponge has little water<g id=\"1\">.</g>,D.The Bible forbids parables"}, {"q": "Which of the Old Testament accounts, unlike the average angel, is considered to point to God Himself?", "s": "Old Testament Evidence", "o": "A.The messenger who speaks in the first person of God and receives worship,B.David,C.Moses,D.elijah"}, {"q": "What does the orthodoxy of the Trinity include? (Multiple choice)", "s": "Trinity Expressions", "o": "A.The Holy Father is God,B.The Son is God,C.The Holy Spirit is God,D.The Father is the Son"}, {"q": "What are some of the errors identified in the video of the Holy Father''s Suffering Speech? (Multiple choice)", "s": "The Holy Father Suffers", "o": "A.Jesus in Gethsemane becomes praying to Himself,B.“Who forsakes who” on the cross becomes a contradiction,C.If the Holy Father dies, the universe is unmaintained,D.Fully biblical"}, {"q": "The four words “Trinity” can be found in the Bible.", "s": "Theological terminology"}, {"q": "The Holy Spirit was already working in judges, kings, and prophets in Old Testament times.", "s": "Old Testament Spirit"}, {"q": "Those who can explain the Trinity clearly to everyone must be wrong.", "s": "Trinity Mystery"}, {"q": "Why is Trinity a mystery? What attitude should Christians adopt?", "s": "Trinity Mystery"}, {"q": "What is the fundamental difference between an artificial idol and a true god?", "s": "Faux Idol"}]}, "ja": {"title": "レッスン7トリニティ", "content": "唯一の真の神には、父、子、聖霊という3つの位格があり、それらは同質であり、栄光において平等です。この課では，三位一体という考えは，理性の神秘とそれが信仰生活にとって何を意味するかを超越しています。この謎があなたの神への恐れを強めますように。トリニティは，わたしたちのすべての崇拝にふさわしい存在です。", "instructions": "", "guide": [{"title": "三位一体：神学名詞の意味", "points": ["「三位一体」は聖書には見られない神学用語です。", "「体」は本質の本来の意味：神の三つの人格、一つの本質", "これは，聖書を読んでいた聖徒たちが過去に発見した神の側面の特徴です。"]}, {"title": "三位一体の4つの定義", "points": ["父は神であり、子は神であり、聖霊は神です。", "御父は御子ではなく，御子は聖霊ではなく，聖霊は御父ではありません。", "神は一人しかおらず、三位一体は人間の理性的経験を超越する神秘である"]}, {"title": "異端からの教訓：聖父の苦しみの言葉", "points": ["御父が御子となり、御子が聖霊となり、一人の人だけが交代で現れることを提唱する", "ゲツセマネの園での祈りと十字架上の叫びは，自分自身を語るようになり，矛盾するようになりました。", "初期の教会はそれを異端、非聖書的と分類していました。"]}, {"title": "創造のアナロジーは不完全です", "points": ["水には3つの状態がありますが、同時には存在しません。太陽熱エネルギーの性質は同じではありません", "人は父親、息子、夫の3つの地位を持っていますが、結局は同じ人です。", "神に例えれば、創造されたものは不完全である運命にあります。"]}, {"title": "「父はわたしよりも偉大である」と「わたしと父とは一つである」", "points": ["「わたしは父と一つである」とは，救いの業に完全な一致があることを意味します", "「父はわたしよりも偉大である」とは，救いの計画を実行する際の計画者と実行者の順序を指します", "本質的に、この3つは同等に尊重されており、サイズとサイズの区別はありません。"]}, {"title": "旧約聖書の三位一体", "points": ["エホバの使者は礼拝を受け，神の一人称で語る", "イザヤは，赤ちゃんの名前が「全能の神，永遠の父」であると預言しました", "聖霊が士師，王，預言者の上に降り，ダビデは「あなたがたの聖霊を取り戻してはならない」と嘆願します。"]}, {"title": "謙虚さ：神は理性を超越する", "points": ["人が知ることのできる神の事柄は人の心の中に現れ、人が知ることのできない事柄もある。", "理由はすべてを判断するための最終的な基準ではなく、知識と経験で修正され続けます", "創造主の限界を認め、創造主から謙虚に啓示を受ける"]}, {"title": "三位一体は私たちと共にあります", "points": ["父は長い間人のために救いを準備しておられ，御子は救いを成し遂げるために肉となられた", "霊的な慰め手は常に信者と共にいて、新しい生活を送っています", "三位一体の真の神は，旧約聖書から新約聖書，そして永遠にわたしたちと共におられます。"]}], "quizzes": [{"q": "十戒の最初の戒めは次のように述べています。「あなたには，わたし以外の神々があってはならない。", "s": "ユニークな真の神"}, {"q": "私たちのために生まれる子があり、政府は彼の肩にかかっています。彼の名前は________、全能の神、________、平和の君と呼ばれるでしょう。", "s": "赤ちゃんの予言"}, {"q": "イエスは言いました： ________もともとは1つでした。", "s": "もともと1つ"}, {"q": "三位一体の「体」の元のテキストは物質であり、________を指します。", "s": "本文の意味"}, {"q": "父は神であり、子は神であり、聖霊は神ですが、神には________しかありません。", "s": "ユニークな真の神"}, {"q": "御父は御子ではなく，御子は________ではなく，聖霊は御父ではありません。", "s": "3名"}, {"q": "初期の教会では， ________と呼ばれる，御父が御子となり，その後聖霊が異端者となったという主張を特徴づけていました。", "s": "異端"}, {"q": "イエスは，「御父はわたしよりも偉大である」と述べ，大きさの性質ではなく，救いの計画________の実行に言及しました。", "s": "父は私より年上です"}, {"q": "ダビデは詩篇51篇で次のように祈りました。「どうか， ________あなたの聖霊をわたしから奪わないでください。", "s": "ダビデの祈り"}, {"q": "「わたしと父とは一つである」とはどういう意味でしょうか。", "s": "もともと1つ", "o": "A.父は子である,B.救いの業に完全に同調している,C.2人が1人になる,D.本質的なサイズ"}, {"q": "水の固体、液体、気体の状態で三位一体を説明できないのはなぜですか？", "s": "たとえ話の限界", "o": "A.水には本質がない,B.水の3つの状態は同時に存在することはできません,C.水分が少なすぎる,D.聖書はたとえ話を禁じている"}, {"q": "旧約聖書のどの記述が，平均的な天使とは異なり，神ご自身を指し示していると考えられていますか。", "s": "旧約聖書の証拠", "o": "A.神の一人称で語り、礼拝を受ける使徒,B.デビッド,C.モーセ,D.エリヤ，i"}, {"q": "三位一体の正統性には何が含まれていますか？ （複数選択可）", "s": "トリニティ式", "o": "A.教皇は神である,B.御子は神である,C.聖霊は神である,D.父は子である"}, {"q": "教皇の苦難の言葉のビデオで特定された誤りには，どのようなものがありますか。（複数選択可）", "s": "教皇が苦しむ", "o": "A.ゲツセマネのイエスは自分自身に祈るようになる,B.十字架上の「誰が誰を捨てるのか」は矛盾になります,C.教皇が死んだ場合、宇宙は維持されていません,D.完全に聖書的"}, {"q": "「三位一体」という4つの言葉は聖書にあります。", "s": "神学用語"}, {"q": "旧約聖書の時代には，聖霊はすでに裁判官，王，預言者の中で働いていました。", "s": "旧約聖書の霊"}, {"q": "三位一体をすべての人に明確に説明できる人は間違っているに違いありません。", "s": "トリニティミステリー"}, {"q": "なぜトリニティは謎なのでしょうか？クリスチャンはどのような態度をとるべきでしょうか。", "s": "トリニティミステリー"}, {"q": "人工の偶像と真の神の根本的な違いは何ですか？", "s": "フェイクアイドル"}]}, "ko": {"title": "제 7과 삼위일체", "content": "유일하신 참 하느님은 세 위격, 즉 성부, 성자, 성령을 가지고 계시며, 그들은 동질적이고 영광이 평등합니다. 이 수업에서 삼위일체 사상은 이성의 신비와 그것이 신앙 생활에 의미하는 바를 초월한다. 이 신비가 하나님에 대한 여러분의 경외심을 강화하기를 바랍니다. 삼위일체는 우리의 모든 예배에 합당합니다.", "instructions": "", "guide": [{"title": "삼위일체: 신학적 명사의 의미", "points": ["\"삼위일체\" 는 성경에서 찾을 수 없는 신학 용어입니다.", "\"몸\" 은 본질의 원래 의미입니다: 하나님의 세 인격, 오직 하나의 본질", "이것은 과거 성도들이 성경을 읽을 때 발견한 하나님의 측면의 특징입니다."]}, {"title": "삼위일체에 대한 네 가지 정의", "points": ["아버지는 하나님이시고, 아들은 하나님이시며, 성령은 하나님이십니다.", "성부는 성자가 아니며, 성자는 성령이 아니며, 성령은 성부가 아닙니다. 분리된 위격들", "하나님은 한 분뿐이십니다. 삼위일체는 인간의 이성적 경험을 초월하는 신비입니다."]}, {"title": "이단의 교훈: 교황의 고난의 말씀", "points": ["성부가 성자가 되고 성자가 성령이 되며 오직 한 사람만 차례로 나타난다고 옹호하십시오.", "겟세마네 동산의기도와 십자가의 외침은 자기 이야기와 모순이되었습니다.", "초대 교회는 그것을 비성경적인 이단으로 분류했다."]}, {"title": "창조의 비유는 불완전하다", "points": ["물은 세 가지 상태를 가지고 있지만 동시에 존재하지 않습니다. 태양열 에너지의 본질은 동일하지 않습니다.", "사람은 아버지, 아들, 남편의 삼중적 지위를 가지고 있지만 결국 같은 사람입니다.", "하느님과 비유하자면, 피조물은 불완전할 운명입니다."]}, {"title": "“아버지는 나보다 크시다”, “나와 아버지는 하나이시다”", "points": ["“나는 아버지와 하나라” 는 것은 구원 사업에 완전한 동의가 있다는 것을 의미합니다.", "\"아버지는 나보다 크시다\" 는 구원의 계획을 실행할 때 계획자와 집행자의 순서를 말합니다.", "본질적으로 세 가지는 동등하게 존중되며 크기와 크기가 구별되지 않습니다."]}, {"title": "구약의 삼위일체", "points": ["여호와의 사자는 경배를 받으며 하나님의 첫 번째 인격으로 말씀합니다.", "이사야는 아기의 이름이 “전능하신 하나님, 영원하신 아버지” 가 될 것이라고 예언했습니다.", "성령께서 사사, 왕, 선지자들에게 내려오십니다. 다윗은 “네 성령을 거두지 말라” 고 간청합니다."]}, {"title": "겸손: 이성을 초월한 하나님", "points": ["사람이 알 수 있는 하나님의 것들은 사람의 마음속에 나타납니다. 또한 사람이 알 수 없는 것들도 있습니다.", "이성은 모든 것을 판단하는 최종 기준이 아니며, 지식과 경험으로 계속 수정될 것입니다.", "창조주의 한계를 인정하고, 겸손하게 창조주로부터 계시를 받음"]}, {"title": "삼위일체가 우리와 함께 계십니다", "points": ["아버지는 오랫동안 인간을 위해 구원을 준비해 오셨고, 아들은 구원을 이루기 위해 육신이 되셨다.", "영적 보혜사는 항상 신자와 함께하며 새로운 삶을 영위합니다.", "삼위일체의 참 하느님은 구약에서 신약에 이르기까지 영원까지 우리와 함께 계십니다."]}], "quizzes": [{"q": "십계명 중 첫 번째 계명은 다음과 같습니다. ________ 나 외에는 다른 신을 네게 있게 말지니라.", "s": "유일무이한 참 하나님"}, {"q": "우리에게 한 아기가 태어날 것이요, 그의 어깨에는 정부가 있을 것이며, 그의 이름은 ________, 전능하신 하나님, ________, 평화의 왕자라고 불릴 것입니다.", "s": "아기 예언"}, {"q": "예수님은 이렇게 말씀하셨습니다. ________ 원래는 하나였습니다.", "s": "원래 하나"}, {"q": "삼위일체의 \"몸\" 의 원문은 ________ 을 가리키는 실체입니다.", "s": "신체의 의미"}, {"q": "아버지는 하나님이시고, 아들은 하나님이시며, 성령은 하나님이시지만, 하나님은 오직 ________ 만 가지고 계십니다.", "s": "유일무이한 참 하나님"}, {"q": "아버지는 아들이 아니시고, 아들은 ________ 이 아니며, 성령은 아버지가 아닙니다.", "s": "3인"}, {"q": "초대 교회는 성부께서 성자가 되신 다음 성령을 ________ 라고 불리는 이단이라고 주장했다.", "s": "이단"}, {"q": "예수께서는 “아버지는 나보다 위대하시다” 라고 말씀하셨으며, 크기의 본질이 아니라 구원의 계획 ________ 의 실행을 언급하셨습니다.", "s": "아버지는 저보다 나이가 많으십니다"}, {"q": "다윗은 시편 51편에서 다음과 같이 기도했다. “당신의 성령을 내게서 거두지 마소서. ________.", "s": "다윗의 기도"}, {"q": "“나와 아버지는 하나이니라” 는 것은 무엇을 의미하는가?", "s": "원래 하나", "o": "A.아버지는 아들이다,B.구원의 사업에 전적으로 일치,C.두 사람이 한 사람이 됨,D.내재 크기"}, {"q": "삼위일체는 왜 물의 고체, 액체, 기체 상태로 설명할 수 없는가?", "s": "비유의 한계", "o": "A.물에는 에센스가 없다,B.세 가지 상태의 물은 동시에 존재할 수 없습니다.,C.물이 너무 적음,D.성경은 비유를 금한다"}, {"q": "구약성경의 어떤 기록이 보통의 천사들과 달리 하나님 자신을 가리키는 것으로 간주되는가?", "s": "구약의 증거", "o": "A.하나님의 첫 번째 인격으로 말하고 예배를 받는 메신저,B.다윗,C.모세,D.엘리야"}, {"q": "삼위일체의 정통성에는 무엇이 포함되는가? (복수 선택)", "s": "삼위일체 표현식", "o": "A.거룩하신 아버지는 하나님이십니다,B.아들은 하나님이시다,C.성령은 하나님이십니다,D.아버지는 아들이다"}, {"q": "성부의 고난 연설 동영상에서 확인된 오류에는 어떤 것들이 있는가? (복수 선택)", "s": "교황 성하께서 고난을 겪으십니다", "o": "A.겟세마네에 계신 예수님은 자신에게 기도하게 됩니다,B.십자가 위에서 “누가 누구를 버리는가” 는 모순이 된다.,C.교황이 죽으면 우주는 유지되지 않는다,D.완전히 성경적임"}, {"q": "“삼위일체” 라는 네 단어는 성경에서 찾을 수 있습니다.", "s": "신학 용어"}, {"q": "성령께서는 구약 시대에 이미 재판관, 왕, 선지자에서 일하고 계셨다.", "s": "구약의 영"}, {"q": "모든 사람에게 삼위일체를 분명하게 설명할 수 있는 사람은 틀렸을 것입니다.", "s": "트리니티 미스터리"}, {"q": "삼위일체는 왜 신비인가? 그리스도인들은 어떤 태도를 취해야 하는가?", "s": "트리니티 미스터리"}, {"q": "인공 우상과 참 신의 근본적인 차이점은 무엇입니까?", "s": "인조 아이돌"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773053523682','基要真理','第八课 圣经为何是权威？','圣经是神藉历史的公开启示，超越文化、预言准确、改变生命。本课讲圣经权威的根基，以及如何以它为行事为人的标准。愿你立志以圣经为生命的最高权威。天天读经，让神的话语引导你。','[{"a": "神", "o": "《提摩太后书》3章16节", "q": "圣经都是________所默示的，于教训、督责、使人归正、教导人学义都是有益的，叫属神的人得以完全，预备行各样的善事。", "s": "圣经默示", "type": "verse"}, {"a": "田角", "o": "《利未记》19章9节", "q": "在你们的地收割庄稼，不可割尽________，也不可拾取所遗落的；要留给穷人和寄居的。", "s": "田角条例", "type": "verse"}, {"a": "芥菜种", "o": "《马太福音》17章20节", "q": "耶稣说：你们若有信心像一粒________，就是对这座山说“你从这边挪到那边”，它也必挪去。", "s": "芥菜种信心", "type": "verse"}, {"a": "来源", "o": "", "q": "圣经与一般宗教经典的本质区别在于________：是独一真神启示，还是人写的。", "s": "本质区别", "type": "fill"}, {"a": "孤儿", "o": "", "q": "摩西五经规定收割时田角不可收尽，要留给________和寡妇。", "s": "照顾弱势", "type": "fill"}, {"a": "1948", "o": "", "q": "以色列在主前586年亡国，在________年复国，相隔近2500年。", "s": "以色列复国", "type": "fill"}, {"a": "一百", "o": "", "q": "旧约中关于弥赛亚的预言约有________多处，耶稣百分之百应验。", "s": "弥赛亚预言", "type": "fill"}, {"a": "原本", "o": "", "q": "圣经的无误指的是第一手________在圣灵感动下写出，百分之百正确。", "s": "圣经无误", "type": "fill"}, {"a": "六千", "o": "", "q": "今天圣经已被翻译成________多种文字，是全世界销量最大的书。", "s": "圣经发行", "type": "fill"}, {"a": "B", "o": "A.销量大,B.3500年前摩西律法已有照顾弱势的条例,C.作者很多,D.纸张保存好", "q": "证明圣经超越文化的证据是？", "s": "超越文化", "type": "single"}, {"a": "B", "o": "A.神做错了事,B.神的原则不变，人转回神就调整,C.圣经有错误,D.神会随意改变心意", "q": "“耶和华后悔了”应如何正确理解？", "s": "正确解经", "type": "single"}, {"a": "B", "o": "A.原本还存在,B.经文鉴别学已还原约99%,C.抄本完全不可靠,D.全世界只有一份抄本", "q": "关于圣经抄本，正确的是？", "s": "抄本证据", "type": "single"}, {"a": "A|B|C", "o": "A.超越文化的记载,B.准确的预言,C.历代圣徒的见证,D.作者都是同一时代", "q": "视频提出的圣经权威证据包括哪些？（多选）", "s": "权威证据", "type": "multiple"}, {"a": "A|B|C", "o": "A.指第一手原本无误,B.手抄本可能有抄写误差,C.要用正确方式解经,D.每句都要按字面科学理解", "q": "关于圣经无误，正确的是？（多选）", "s": "圣经无误", "type": "multiple"}, {"a": "错", "o": "", "q": "圣经自己宣告自己是神所默示的，光有这个宣告就足以证明圣经的权威。", "s": "循环论证", "type": "judge"}, {"a": "对", "o": "", "q": "耶稣讲芥菜种是最小的种子，是按当时听众能理解的文化来讲的。", "s": "芥菜种", "type": "judge"}, {"a": "对", "o": "", "q": "以色列亡国2500年后复国，是圣经预言准确的证据。", "s": "以色列复国", "type": "judge"}, {"a": "关键在于来源：圣经是独一真神藉着历史向人启示祂心意的公开记录，人人可读、可查验；而一般宗教经典是人的经验和盼望的产物，只能当作参考。神所启示的真理要求人绝对顺服，照着去行就能亲身体验神的话大有能力。", "o": "", "q": "为什么说圣经与一般宗教经典有本质区别？", "s": "本质区别", "type": "essay"}, {"a": "圣经无误指第一手作者在圣灵感动下写出的原本百分之百正确；今天我们手中的是抄本，经文鉴别学已还原约99%，对真理传递足够用。同时要用正确的解经方式理解，如“神后悔”是神按原则回应人的转向，不是神做错；经文是按当时人的文化，用他们能懂的方式表达。", "o": "", "q": "圣经无误应如何正确理解？", "s": "圣经无误", "type": "essay"}]','https://youtu.be/kbMDV8sVdMs
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.77305513408qB','quiz','[{"title": "关键问题：到底有没有神", "points": ["圣经与一般宗教经典的本质区别，首先在于来源", "若没有真神，圣经只是人的产物；若有真神，圣经就是他的启示", "是神说的还是人说的，决定了圣经是参考还是绝对标准"]}, {"title": "神为何借圣经说话：公开可查验", "points": ["神把心意显明在圣经上，是每一个人都可以读、可以查验的", "不像某些大师的私下启示，无法查验是否删减增添", "圣经摊在全人类面前：销量最大、译本最多的书"]}, {"title": "圣经自己宣告：神所默示", "points": ["提摩太后书：圣经都是神所默示的，于教训督责都是有益的", "圣经先自己宣告从神而来，这是重要的第一步", "但光有宣告还不够，还需要证据支持"]}, {"title": "神借人记录：四十多位作者", "points": ["从摩西、先知到耶稣的门徒，前后约一千四百多年", "表面看是人写的，实质是神借着人记录神人互动", "记录的人满有神的同在，准确写下神要传达的话"]}, {"title": "证据一：超越文化", "points": ["摩西律法规定照顾孤儿寡妇，超越当时弱肉强食的文化", "以弗所书要求丈夫爱妻子如同基督为教会舍己，超越罗马男尊女卑", "这些观念不可能是当时文化里产生出来的"]}, {"title": "证据二：预言准确", "points": ["以赛亚主前七百多年预言以色列复国，1948年准确应验", "旧约一百多处关于弥赛亚的预言，在耶稣身上百分之百应验", "真神能讲将来的事，且百分之百应验"]}, {"title": "证据三：圣徒的见证", "points": ["历代圣徒按圣经价值观生活，都经历从神来的平安喜乐", "圣经超越潮流，不是潮流来修正圣经", "真理放诸四海、超越时空，都是绝对标准"]}, {"title": "圣经无误与正确解经", "points": ["无误指原稿在圣灵感动下写出时百分之百正确", "今天手中的抄本经鉴别已还原约百分之九十九，足够传递真理", "要用正确方式解经，如“耶和华后悔”、芥菜种的例子"]}]','','8','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 8 Why is the Bible an authority?", "content": "The Bible is God''s public revelation through history, transcending culture, prophesying accurately, and changing lives. This lesson is about the foundation of biblical authority and how it can be used as a standard for behavior. May you aspire to take the Bible as the supreme authority for your life. Read the Bible every day and let the Word of God guide you.", "instructions": "", "guide": [{"title": "Key question: Is there a God?", "points": ["The essential difference between the Bible and general religious scriptures is, first and foremost, the source", "If there is no true God, the Bible is only a product of man; if there is a true God, the Bible is his revelation.", "Whether God or man speaks determines whether the Bible is a reference or an absolute standard."]}, {"title": "Why God Speaks from the Bible: Publicly Testable", "points": ["God reveals His will in the Bible, something that everyone can read and examine.", "Unlike the private revelations of some masters, it is not possible to check whether the addition", "The Bible in the Presence of All Mankind: The Largest Selling and Most Translated Book"]}, {"title": "The Bible Proclaims Itself: God Inspired", "points": ["2 Timothy: All Scripture is inspired by God, and teaching reproof is beneficial", "The Bible first proclaims itself from God, which is an important first step", "But declarations alone are not enough. Evidence is needed."]}, {"title": "Divine Borrower Records: Forty + Authors", "points": ["From Moses and the prophets to Jesus'' disciples, about 1,400 years ago and back", "On the surface, it is written by people. The essence is that God records the interaction between God and man through people.", "The person who records is full of the presence of God, and accurately writes down the words that God wants to convey."]}, {"title": "Evidence 1: Beyond Culture", "points": ["The Law of Moses provided for the care of orphans and widows, going beyond the prey culture of the time.", "Ephesians requires husbands to love their wives as Christ sacrificed himself for the church, surpassing Roman male superiority and female inferiority.", "These ideas could not have arisen in the culture of the time"]}, {"title": "Evidence 2: Prediction accurate", "points": ["More than 700 years before Isaiah prophesied the restoration of Israel, which was accurately fulfilled in 1948.", "More than 100 prophecies about the Messiah in the Old Testament are 100% fulfilled in Jesus", "True God can talk about the future, and it is 100% fulfilled"]}, {"title": "Evidence 3: The Testimony of the Saints", "points": ["Throughout the ages, Saints lived by biblical values and experienced peace and joy from God.", "The Bible goes beyond trends, not trends to correct the Bible", "Truth is an absolute standard that transcends all oceans and transcends time and space."]}, {"title": "Bible Inerrancy and Correct Interpretation", "points": ["Accuracy means that the manuscript is 100% correct when written by the Holy Spirit", "The manuscript in our hands today has been identified as having been reduced by about 99%, which is enough to convey the truth.", "To interpret the Scriptures in the correct way, such as \"Jehovah repents\", examples of mustard seeds"]}], "quizzes": [{"q": "The Bible is inspired by ________, which is beneficial for teaching, condemning, converting, and teaching people to learn righteousness, so that those who belong to God can be perfected and prepared to do all kinds of good deeds.", "s": "Biblical inspiration"}, {"q": "Harvest the harvest in your land, thou shalt not cut it ________, nor gather up that which is left behind; but leave it for the poor and the sojourner.", "s": "Tien Kok Ordinance"}, {"q": "And Jesus said unto them, If ye have faith as a grain of ________, say unto this mountain, Move thou from this side unto that side, and it shall be moved also.", "s": "Mustard Seed Confidence"}, {"q": "The essential difference between the Bible and the general religious scriptures is ________: is it the revelation of the one true God, or is it written by man?", "s": "Intrinsic Difference"}, {"q": "The Pentateuch decreed that the corners of the field should not be exhausted at the time of harvest, and that they should be left to ________ and the widow.", "s": "Caring for the vulnerable"}, {"q": "Israel fell in 586 B.C. and was restored in ________, nearly 2,500 years apart.", "s": "The Return of Israel"}, {"q": "There are more than ________ prophecies about the Messiah in the Old Testament, and Jesus fulfilled them 100%.", "s": "Messianic prophecy"}, {"q": "Biblical infallibility refers to the fact that the first-hand ________ is written by the Holy Spirit and is 100% correct.", "s": "Biblical Inerrancy"}, {"q": "Today, the Bible has been translated into ________ languages and is the largest-selling book in the world.", "s": "Bible Issue"}, {"q": "What is the evidence that the Bible transcends culture?", "s": "Beyond culture", "o": "A.Large sales volume,B.3500 years ago, the Law of Moses had regulations to take care of the weak.,C.Lots of authors,D.Save the paper"}, {"q": "How should “Jehovah regrets” be properly understood?", "s": "Correct sutra interpretation", "o": "A.God did something wrong,B.The principle of God remains unchanged, and man adjusts when he returns to God.,C.The Bible is wrong,D.God will change His mind at will"}, {"q": "What is true about Bible manuscripts?", "s": "Transcript Evidence", "o": "A.Originally Existed,B.Scripture discrimination has been reduced by about 99%,C.The transcript is completely unreliable,D.There is only one copy in the world"}, {"q": "What is the authoritative biblical evidence presented in the video? (Multiple choice)", "s": "Authoritative Evidence", "o": "A.A transcendent cultural record,B.Accurate predictions,C.The Testimony of the Saints,D.The authors are all from the same era"}, {"q": "What is true about biblical inerrancy? (Multiple choice)", "s": "Biblical Inerrancy", "o": "A.Refers to the original correctness of the first hand,B.Manuscripts may have transcription errors,C.To solve the meridian in the correct way,D.Every sentence has to be taken literally and scientifically."}, {"q": "The Bible itself declares itself to be inspired by God, and this declaration alone is sufficient to justify the authority of Scripture.", "s": "Circular Argumentation"}, {"q": "Jesus speaks of the mustard seed as the smallest seed, according to the culture understood by the audience at the time.", "s": "Mustard seeds"}, {"q": "The restoration of Israel 2,500 years after its fall is accurate evidence of biblical prophecy.", "s": "The Return of Israel"}, {"q": "Why is there an essential difference between the Bible and general religious scripture?", "s": "Intrinsic Difference"}, {"q": "How should biblical inerrancy be properly understood?", "s": "Biblical Inerrancy"}]}, "ja": {"title": "レッスン8なぜ聖書は権威なのか？", "content": "聖書は、歴史を通して、文化を超越し、正確に預言し、人生を変える神の公の啓示です。このレッスンでは，聖書の権威の基礎と，それを行動の基準としてどのように使用できるかについて説明します。聖書をあなたの人生の至高の権威として受け入れることを熱望してください。毎日聖書を読んで，神の言葉に導かれましょう。", "instructions": "", "guide": [{"title": "重要な質問：神はいますか？", "points": ["聖書と一般的な宗教的経典の本質的な違いは、何よりもまず、", "真の神がなければ、聖書は人間の産物にすぎず、真の神があれば、聖書は人間の啓示である。", "神が語るか人が語るかは，聖書が参照であるか絶対的な基準であるかを決定します。"]}, {"title": "聖書から神が語る理由：公的に検証可能", "points": ["神は聖書の中で御心を明らかにされ，だれもが読んで調べることができます。", "一部のマスターの私的な啓示とは異なり、追加されているかどうかを確認することはできません", "全人類の前にある聖書：最も売れていて最も翻訳されている本"]}, {"title": "聖書はそれ自体を宣言しています：神に霊感を受けた", "points": ["2テモテ：すべての聖文は神に霊感を受けており、非難を教えることは有益です", "聖書はまず神から自分自身を宣言します。これは重要な第一歩です", "しかし、申告だけでは不十分です。証拠が必要です。"]}, {"title": "Divine Borrower Records ： 40人以上の著者", "points": ["モーセと預言者からイエスの弟子まで、約1,400年前から", "表面上は人によって書かれており、本質は神が人を通して神と人との相互作用を記録しているということである。", "記録する人は神の臨在に満ちており，神が伝えたい言葉を正確に書き留めています。"]}, {"title": "エビデンス1 ：文化を超えて", "points": ["モーセの律法は，当時の獲物の文化を超えて，孤児ややもめの世話をしました。", "エペソ人への手紙は、キリストが教会のために自分自身を犠牲にされたように、夫が妻を愛することを求めています。ローマの男性の優位性と女性の劣等性を超えています。", "これらのアイデアは、当時の文化では生まれることはできませんでした"]}, {"title": "証拠2 ：正確な予測", "points": ["イザヤが1948年に正確に成就したイスラエルの回復を預言する700年以上前のことです。", "旧約聖書のメシアに関する100以上の預言は、イエスにおいて100 ％成就しています", "真の神は未来について話すことができ、それは100 ％満たされています"]}, {"title": "証3 ：聖徒の証", "points": ["聖徒は何世紀にもわたって，聖書の価値観に従って生活し，神からの平安と喜びを経験してきました。", "聖書は、聖書を修正するための傾向ではなく、傾向を超えています", "真理は、すべての海を超越し、時間と空間を超越する絶対的な基準です。"]}, {"title": "聖書の誤りのない解釈と正しい解釈", "points": ["正確性とは、原稿が聖霊によって書かれたときに100 ％正確であることを意味します", "今日、私たちの手元にある原稿は約99 ％削減されていることが確認されており、真実を伝えるのに十分です。", "「エホバの悔い改め」など，聖文を正しい方法で解釈するため，マスタードシードの例"]}], "quizzes": [{"q": "聖書は________に触発されています。________は，神に属する人々が完全にされ，あらゆる種類の善行をする準備ができるように，義を学ぶように人々を教え，非難し，改心させ，教えるのに有益です。", "s": "聖書の霊感"}, {"q": "あなたの土地で収穫を収穫しなさい。あなたはそれを________切り取ったり、残っているものを集めたりしてはならず、貧しい人や寄留者のためにそれを残しておいてください。", "s": "ティエンコク条例"}, {"q": "イエスは彼らに言われた、「もしあなたがたが一粒の穀物のような信仰を持っているならば、この山に言いなさい、『あなたがたはこの辺からその辺に動かしなさい。そうすれば、それも動かされるであろう。", "s": "マスタードシードの自信"}, {"q": "聖書と一般的な宗教的経典の本質的な違いは________です：それは唯一の真の神の啓示ですか、それとも人間によって書かれたものですか？", "s": "本質的な違い"}, {"q": "モルモン書は，収穫時に畑の四隅を使い果たしてはならず， ________とやもめに任せるように定めています。", "s": "弱者への配慮"}, {"q": "イスラエルは紀元前586年に陥落し、2,500年近くの間隔を置いて________に復元されました。", "s": "イスラエルの帰還"}, {"q": "旧約聖書には，メシアに関する________以上の預言があり，イエスはそれらを100 ％成就されました。", "s": "メシアの預言"}, {"q": "聖書の絶対誤りのないとは、直接________が聖霊によって書かれ、100 ％正しいという事実を指します。", "s": "聖書の無謬性"}, {"q": "今日，聖書は________言語に翻訳され，世界で最も売れている本となっています。", "s": "聖書の問題"}, {"q": "聖書が文化を超越しているという証拠は何ですか。", "s": "文化を超えて", "o": "A.大規模な販売量,B.3500年前、モーセの律法には弱者の世話をするための規制がありました。,C.多くの著者,D.論文を保存する"}, {"q": "「エホバの悔い改め」は，どのように正しく理解すべきでしょうか。", "s": "正しい経典の解釈", "o": "A.神は何か悪いことをした,B.神の原則は変わらず、人は神に戻るときに適応します。,C.聖書が間違っている,D.神は御心を変えてくださる"}, {"q": "聖書の原稿について，どのようなことが真実ですか。", "s": "トランスクリプトのエビデンス", "o": "A.もともと存在した,B.聖文の差別は約99 ％減少しました,C.トランスクリプトはまったく信頼性がありません,D.世界に1つしかコピーがありません"}, {"q": "ビデオに示されている権威ある聖書の証拠は何ですか。（複数選択可）", "s": "権威ある証拠", "o": "A.卓越した文化的記録,B.正確な予測,C.聖徒の証,D.著者はすべて同じ時代の出身です"}, {"q": "聖書の無誤性について，どのようなことが真実なのでしょうか。（複数選択可）", "s": "聖書の無謬性", "o": "A.最初の手の元の正確さを指します,B.原稿に転写エラーがある可能性があります,C.メリディアンを正しい方法で解くには,D.すべての文章は、文字通り、科学的に解釈されなければなりません。"}, {"q": "聖書自体は神に霊感を受けていると宣言しており、この宣言だけで聖書の権威を正当化するのに十分です。", "s": "循環引数"}, {"q": "イエスは、当時の聴衆が理解していた文化によると、マスタードシードを最小の種と言います。", "s": "マスタードシード"}, {"q": "イスラエルの陥落から2,500年後の回復は，聖書の預言の正確な証拠です。", "s": "イスラエルの帰還"}, {"q": "なぜ聖書と一般的な宗教的聖句には本質的な違いがあるのでしょうか。", "s": "本質的な違い"}, {"q": "聖書の無誤性を正しく理解するには，どのようにすればよいでしょうか。", "s": "聖書の無謬性"}]}, "ko": {"title": "제 8과 왜 성경이 권위인가?", "content": "성경은 역사를 통해 문화를 초월하고 정확하게 예언하고 삶을 변화시키는 하나님의 공개적인 계시입니다. 이 수업은 성경적 권위의 기초와 그것이 어떻게 행동의 표준으로 사용될 수 있는지에 관한 것이다. 성경을 삶의 최고 권위로 삼고자 하는 열망이 있기를 바랍니다. 매일 성경을 읽고 하나님의 말씀이 여러분을 인도하게 하십시오.", "instructions": "", "guide": [{"title": "핵심 질문: 신은 존재하는가?", "points": ["성경과 일반 종교 경전의 본질적인 차이는 무엇보다도", "참 신이 없다면 성경은 인간의 산물일 뿐이고, 참 신이 있다면 성경은 그의 계시일 뿐이다.", "하나님이나 인간이 말하는지 여부는 성경이 참조 또는 절대 표준인지 여부를 결정합니다."]}, {"title": "하나님이 성경에서 말씀하시는 이유: 공개적으로 테스트 가능", "points": ["하나님께서는 모든 사람이 읽고 검토할 수 있는 성경에서 그분의 뜻을 계시하십니다.", "일부 고수들의 사적인 계시와 달리 추가 여부는 확인할 수 없습니다.", "The Bible in the Presence of All Mankind: The Largest Selling and Most Translated Book"]}, {"title": "성경은 스스로를 선포합니다: 하나님께서 영감을 주셨습니다", "points": ["디모데후서: 모든 성경은 하나님의 영감으로 된 것이며, 책망을 가르치는 것은 유익합니다.", "성경은 먼저 하나님으로부터 자신을 선포하며, 이는 중요한 첫 걸음입니다.", "하지만 선언만으로는 충분하지 않습니다. 증거가 필요합니다."]}, {"title": "Divine Borrower Records: 40명 이상의 저자", "points": ["약 1,400년 전에 모세와 선지자로부터 예수님의 제자들에 이르기까지", "표면적으로는 사람에 의해 기록되어 있는데, 본질은 하나님이 사람을 통해 하나님과 사람 사이의 상호 작용을 기록하신다는 것입니다.", "기록하는 사람은 하나님의 임재로 가득 차 있으며, 하나님이 전하고자 하시는 말씀을 정확하게 기록합니다."]}, {"title": "증거 1: 문화를 넘어서", "points": ["모세의 율법은 당시의 먹이 문화를 넘어 고아와 과부를 돌보는 것을 제공했습니다.", "에베소서는 그리스도께서 교회를 위해 자신을 희생하신 것처럼 남편이 아내를 사랑하도록 요구하며, 로마 남성의 우월감과 여성의 열등감을 능가합니다.", "이러한 아이디어는 당시의 문화에서 생겨날 수 없었습니다."]}, {"title": "증거 2: 정확한 예측", "points": ["이사야가 1948년에 정확하게 성취된 이스라엘의 회복을 예언하기 700년 이상 전에.", "구약의 메시아에 대한 100가지 이상의 예언은 예수님 안에서 100% 성취된다.", "참된 하나님은 미래에 대해 말씀하실 수 있으며, 그것은 100% 성취됩니다."]}, {"title": "증거 3: 성도들의 간증", "points": ["성도들은 시대를 통틀어 성경적 가치에 따라 살았고, 하나님으로부터 오는 평화와 기쁨을 경험했습니다.", "성경은 경향을 넘어서는 것이지 성경을 바로잡는 경향을 넘어서는 것이 아닙니다.", "진리는 모든 바다를 초월하고 시간과 공간을 초월하는 절대적인 표준입니다."]}, {"title": "성경의 무오성과 올바른 해석", "points": ["정확성은 원고가 성령에 의해 쓰여졌을 때 100% 정확하다는 것을 의미합니다.", "오늘날 우리 손에 있는 원고는 진실을 전달하기에 충분한 약 99% 감소한 것으로 확인되었습니다.", "\"여호와 께서 회개 하심\" 과 같이 경전을 올바르게 해석하기 위해 겨자 씨앗의 예"]}], "quizzes": [{"q": "성경은 사람들에게 의를 가르치고, 정죄하고, 개종하고, 가르치는 데 유익한 ________ 에서 영감을 얻어 하나님께 속한 사람들이 모든 종류의 선행을 행할 수 있도록 완성되고 준비될 수 있도록 합니다.", "s": "성경적 영감"}, {"q": "너희 땅에서 추수하되 ________ 을 (를) 베지 말며 남은 것을 거두지 말고 가난한 자와 거류민을 위하여 남겨두라", "s": "Tien Kok 조례"}, {"q": "예수께서 이르시되 너희가 만일 믿음이 ________ 의 한 알 같으면 이 산을 명하여 이편에서 저편으로 옮기라 하라 그리하면 또한 옮길지니라", "s": "겨자씨 자신감"}, {"q": "성경과 일반 종교 경전의 본질적인 차이점은 ________ 입니다. 그것은 유일한 참 하나님에 대한 계시입니까, 아니면 인간이 기록한 것입니까?", "s": "내재적 차이"}, {"q": "오경은 추수할 때 밭 모퉁이를 다치지 말고 ________ 와 과부에게 맡겨야 한다고 선포했다.", "s": "취약계층 돌보기"}, {"q": "이스라엘은 기원전 586년에 함락되었고 거의 2,500년 간격으로 ________ 년에 복원되었습니다.", "s": "이스라엘의 귀환"}, {"q": "구약성경에는 메시아에 대한 ________ 개 이상의 예언이 있는데, 예수님은 100% 성취하셨습니다.", "s": "메시아 예언"}, {"q": "성경적 무류성은 직접 ________ 은 (는) 성령에 의해 쓰여졌으며 100% 정확하다는 사실을 의미합니다.", "s": "성경의 무오성"}, {"q": "오늘날 성경은 ________ 개 언어로 번역되었으며 세계에서 가장 많이 판매되는 책입니다.", "s": "성경 문제"}, {"q": "성경이 문화를 초월한다는 증거는 무엇인가?", "s": "문화를 넘어", "o": "A.대규모 판매량,B.3500년 전, 모세의 율법에는 약자를 돌보는 규정이 있었습니다.,C.많은 작가,D.보고서 저장"}, {"q": "“여호와께서 후회하신다” 는 것을 어떻게 올바르게 이해해야 하는가?", "s": "올바른 수트라 해석", "o": "A.하나님께서 잘못을 저질렀습니다.,B.하나님의 원칙은 변하지 않으며, 인간은 하나님께로 돌아갈 때 조정됩니다.,C.성경이 틀렸습니다,D.하나님께서는 마음대로 마음을 바꾸실 것입니다."}, {"q": "성경 원고에 대한 진실은 무엇인가?", "s": "성적 증명서 증거", "o": "A.원래 존재함,B.경전의 차별이 약 99% 감소했습니다.,C.성적표가 완전히 신뢰할 수 없습니다.,D.세상에는 단 한 권의 사본이 있습니다."}, {"q": "동영상에 제시된 권위 있는 성경적 증거는 무엇인가? (복수 선택)", "s": "권위 있는 증거", "o": "A.초월적인 문화적 기록,B.정확한 예측,C.성도들의 간증,D.저자는 모두 같은 시대 출신이다."}, {"q": "성경의 무오성에 대한 진실은 무엇인가? (복수 선택)", "s": "성경의 무오성", "o": "A.첫 번째 손의 원래 정확도를 나타냅니다.,B.원고에 전사 오류가 있을 수 있음,C.올바른 방법으로 경락을 풀기 위해,D.모든 문장은 문자 그대로 과학적으로 받아들여야 합니다."}, {"q": "성경 자체는 하나님에 의해 영감을 받았다고 선언하며, 이 선언만으로도 성경의 권위를 정당화하기에 충분합니다.", "s": "원형 인수"}, {"q": "예수님은 당시 청중이 이해하는 문화에 따라 겨자씨를 가장 작은 씨앗으로 말씀하십니다.", "s": "겨자씨"}, {"q": "이스라엘이 멸망한 지 2,500년 만에 회복된 것은 성경적 예언의 정확한 증거입니다.", "s": "이스라엘의 귀환"}, {"q": "왜 성경과 일반 종교 경전 사이에 본질적인 차이가 있는가?", "s": "내재적 차이"}, {"q": "성경의 무오성은 어떻게 올바르게 이해되어야 하는가?", "s": "성경의 무오성"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773054031124','基要真理','第九课 人的被造和堕落','人按神形象被造尊贵无比，却因悖逆堕落与神隔绝。本课讲人的被造、堕落的后果，以及神在创世前就预备的救赎计划。愿你珍惜神形象的尊贵，远离罪恶。在基督里找回起初的尊贵形象。','[{"a": "起初|天地", "o": "《创世记》1章1节", "q": "________，神创造________。", "s": "创造天地", "type": "verse"}, {"a": "造人|男", "o": "《创世记》1章27节", "q": "神就照着自己的形象________，乃是照着祂的形象造________造女。", "s": "神的形象", "type": "verse"}, {"a": "永能|神性", "o": "《罗马书》1章20节", "q": "自从造天地以来，神的________和________是明明可知的，虽是眼不能见，但藉着所造之物就可以晓得。", "s": "神的永能", "type": "verse"}, {"a": "假说", "o": "", "q": "进化论从科学角度看只是一个________，不是经过反复实验证明的定理。", "s": "进化论假说", "type": "fill"}, {"a": "推翻", "o": "", "q": "视频指出进化论的四个主要证据支柱在科学上都被________了。", "s": "支柱推翻", "type": "fill"}, {"a": "同时", "o": "", "q": "在寒武纪初期化石群中，生物分类的界门纲目科属种________出现。", "s": "澄江化石", "type": "fill"}, {"a": "悖逆", "o": "", "q": "人堕落的本质是被造的人________，不肯顺服创造主。", "s": "人的悖逆", "type": "fill"}, {"a": "伊甸园", "o": "", "q": "起初神设立________，让人与祂有美好的关系。", "s": "伊甸园", "type": "fill"}, {"a": "自由意志", "o": "", "q": "神给人________，因为爱的对象必须有自主选择权。", "s": "自由意志", "type": "fill"}, {"a": "C", "o": "A.米勒的原生汤实验,B.海克尔的胚胎图,C.DNA双螺旋结构,D.始祖鸟化石检验", "q": "视频中提到的进化论支柱不包括哪一项？", "s": "进化论支柱", "type": "single"}, {"a": "B", "o": "A.神做不到,B.爱的对象必须有自主权，被迫的不是真爱,C.神喜欢麻烦,D.圣经没有解释", "q": "为什么神不直接造一批只会听话的人？", "s": "自由意志", "type": "single"}, {"a": "B", "o": "A.在比较中胜过别人,B.按神形象被造，价值从被造时已存在,C.赚钱多少,D.别人的眼光", "q": "基督徒的价值根基是什么？", "s": "人的价值", "type": "single"}, {"a": "A|B|C", "o": "A.DNA极其复杂精密,B.跨种化石从未找到,C.澄江化石群与进化论推论相悖,D.进化论已被证明是定理", "q": "视频中支持创造论的科学观察包括哪些？（多选）", "s": "创造论证据", "type": "multiple"}, {"a": "B|C|D", "o": "A.放弃人类,B.永不放弃的爱,C.主动为我们预备救恩,D.差遣儿子在十字架上付代价", "q": "人堕落后，神的回应包括哪些？（多选）", "s": "神的爱", "type": "multiple"}, {"a": "错", "o": "", "q": "进化论是经过反复实验证明的科学定理。", "s": "进化论假说", "type": "judge"}, {"a": "对", "o": "", "q": "人之所以尊贵，是因为按着神的形象样式被造。", "s": "人的尊贵", "type": "judge"}, {"a": "错", "o": "", "q": "人堕落后，神就放弃了人类。", "s": "神不放弃", "type": "judge"}, {"a": "因为爱的对象必须有自主选择权，被迫的顺服不是真爱，就像洋娃娃任人摆布毫无意义。神尊重人，给人自由选择的权柄；人可能选错，神知道风险仍愿承担，并在人失败时不放弃、继续带领人回转。", "o": "", "q": "为什么说神给人自由意志是爱的表现？", "s": "自由意志", "type": "essay"}, {"a": "人是独一真神按祂形象样式创造的，不是偶然进化的。进化论只是假说，其四大证据支柱已被推翻；DNA的精密复杂指向精心设计，跨种化石从未找到，寒武纪化石群与进化论推论相悖。圣经宣告“起初，神创造天地”，并藉宇宙的精密向人显明祂的永能和神性。", "o": "", "q": "人从哪里来？为什么创造论比进化论更合理？", "s": "创造论", "type": "essay"}]','https://youtu.be/ddqASyoheyM
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134GE99','quiz','[{"title": "人从哪里来：大哉问", "points": ["自有人类以来，人都在问：我从哪里来，往哪里去", "若对来龙去脉弄清楚，才能作出正确判断", "在时空限制下，人只能猜想"]}, {"title": "进化论只是假说", "points": ["进化论从来不是科学定理，只是一个假设性说法", "米勒实验、海克尔胚胎图、达尔文进化树、始祖鸟化石四大支柱都被推翻", "跨物种的化石从来没有找到过"]}, {"title": "科学证据指向创造", "points": ["DNA的复杂度与精密度远超偶然，必经过精密设计", "按或然率计算，进化所需时间是宇宙现有年龄的297倍", "寒武纪澄江化石群与进化论的预期背道而驰"]}, {"title": "创造论：按神形象被造", "points": ["起初，神创造天地；在创造的高峰，神按自己形象样式造人", "自从造天地以来，神的永能和神性是明明可知的", "人的出现不是偶然，是上帝精心的设计"]}, {"title": "人的尊贵：价值已定", "points": ["神按自己形象造人，人是他爱的对象的彰显", "价值在被造时已经存在，不需在比较中寻找", "在比较中找价值，带来斗争、竞争与伤害"]}, {"title": "堕落：关系的破裂", "points": ["伊甸园中，人与神关系美好，条件是听神的话", "人悖逆：不要神做神，想自己变成跟创造者一样", "关系破裂的结果就是堕落，带来人与人之间的伤害"]}, {"title": "神没有放弃：永不放弃的爱", "points": ["神给人自由意志，因为爱的对象必须有自主选择权", "人会选错，神知道风险却愿意承担，从不放弃", "神主动为人预备救恩，差遣儿子付代价，恢复关系"]}]','','9','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 9 The Creation and Fall of Man", "content": "Man was created in the image and dignity of God, but because of his rebellion and fall, he was separated from God. This lesson is about the creation of man, the consequences of the Fall, and God''s plan of redemption that He prepared before the creation of the world. May you cherish the dignity of the image of God and keep away from sin. Find back in Christ the noble image of the beginning.", "instructions": "", "guide": [{"title": "Where do people come from: Big questions", "points": ["Ever since there have been humans, people have asked: where did I come from, where did I go?", "If you understand the background of the dragon, you can make a correct judgment.", "Under the constraints of time and space, people can only guess"]}, {"title": "Evolution is just a hypothesis.", "points": ["Evolution has never been a scientific theorem, it''s just a hypothetical statement.", "Miller experiment, Haeckel embryo map, Darwinian evolutionary tree, Archaeopteryx fossil four pillars are all overthrown", "Cross-species fossils have never been found"]}, {"title": "Scientific evidence points to creation", "points": ["The complexity and precision of DNA is far more than accidental, and it must be precisely designed", "By chance, evolution took 297 times longer than the current age of the universe", "Cambrian Chengjiang Fossils Contrary to Evolutionary Expectations"]}, {"title": "Creationism: Creation in the Image of God", "points": ["In the beginning, God created the heavens and the earth; at the peak of creation, God created man in His own image and likeness.", "Since the creation of the heavens and the earth, God''s eternal power and divinity have been clearly known.", "The appearance of people is not accidental, it is God''s careful design"]}, {"title": "Human dignity: value determined", "points": ["God created man in His own image, and man is the manifestation of the object of His love.", "Value existed at the time it was created, not to be looked for in comparisons", "Finding value in comparisons leads to struggle, competition and harm"]}, {"title": "Fallen: relationship breakdown", "points": ["In the Garden of Eden, people have a good relationship with God, provided they listen to God''s words.", "Human disobedience: Don''t be a god, want to become like the creator", "The result of a broken relationship is degradation, bringing harm to people."]}, {"title": "God Didn''t Give Up: The Love That Never Gives Up", "points": ["God gives people free will, because the object of love must have the right to choose.", "People choose wrong, God knows the risk but is willing to take it, never give up", "God took the initiative to prepare man for salvation, sent his son to pay the price, and restored the relationship."]}], "quizzes": [{"q": "________, God created ________.", "s": "Creating Heaven and Earth"}, {"q": "God made ________ in his own image, but created ________ women in his image.", "s": "Image of God"}, {"q": "Since the creation of the heavens and the earth, God''s ________ and ________ have been clearly known. Although they are invisible to the eyes, they can be known through the created things.", "s": "The Eternal Power of God"}, {"q": "Evolution is only a ________ from a scientific point of view, not a theorem proven by repeated experiments.", "s": "The evolutionary hypothesis"}, {"q": "The video points out that the four main pillars of evidence for evolution are all ________ scientifically.", "s": "Pillar Overthrow"}, {"q": "In the early Cambrian fossil population, there were ________ species of taxonomic taxa.", "s": "Chengjiang Fossil"}, {"q": "The essence of man''s fall is that he was created ________ and refused to obey the Creator.", "s": "Human disobedience"}, {"q": "In the beginning, God established ________ so that people could have a good relationship with Him.", "s": "Garden of Eden"}, {"q": "God gives people ________, because the object of love must have the right to choose.", "s": "Free will"}, {"q": "Which of the evolutionary pillars mentioned in the video is not included?", "s": "Evolutionary Pillars", "o": "A.Miller''s Native Soup Experiment,B.Embryo diagram of Haeckel,C.DNA Double Helix Structure,D.Archaeopteryx Fossil Inspection"}, {"q": "Why didn''t God just create a group of obedient people?", "s": "Free will", "o": "A.God can''t do it.,B.The object of love must have autonomy, and it is not true love that is forced,C.God loves trouble,D.The Bible does not explain"}, {"q": "What are the roots of Christian values?", "s": "The value of people", "o": "A.Better than others in comparison,B.Created in the image of God, the value has existed since the time of creation,C.How much you earn,D.The Eyes of Others"}, {"q": "What are some of the scientific observations in the video that support creationism? (Multiple choice)", "s": "Creationist Evidence", "o": "A.DNA is extremely complex and sophisticated,B.Cross-species fossils never found,C.The Chengjiang fossil population contradicts evolutionary theories,D.Evolution has proven to be a theorem"}, {"q": "What does God''s response to the Fall include? (Multiple choice)", "s": "The Love of God", "o": "A.Abandon Humans,B.Love that never gives up,C.Take the initiative to prepare for our salvation,D.Sent his son to pay the price on the cross"}, {"q": "Evolution is a scientific theorem proven by repeated experiments.", "s": "The evolutionary hypothesis"}, {"q": "Man is noble because he was created in the image and likeness of God.", "s": "The dignity of man"}, {"q": "After the fall of man, God abandoned mankind.", "s": "God does not give up"}, {"q": "Why does God give free will as an expression of love?", "s": "Free will"}, {"q": "Where do people come from? Why is creation more plausible than evolution?", "s": "Creationism"}]}, "ja": {"title": "レッスン9「人の創造と堕落」", "content": "人は神のかたちと尊厳をもって造られましたが、その反抗と堕落のために神から引き離されました。このレッスンでは，人間の創造，堕落の結果，神が世界の創造の前に準備された贖いの計画について学びます。神の像の尊厳を大切にし，罪を避けてくださいますように。初めの高貴な姿をキリストの中に取り戻しましょう。", "instructions": "", "guide": [{"title": "人はどこから来たのか：大きな疑問", "points": ["人間が存在して以来、人々は私はどこから来たのか、どこへ行ったのかと尋ねてきました。", "ドラゴンの背景を理解できれば、正しい判断を下すことができます。", "時間と空間の制約の下では、人々は推測することしかできません"]}, {"title": "進化は単なる仮説に過ぎません。", "points": ["進化は科学的な定理ではなく、単なる仮説です。", "ミラー実験、ヘッケル胚マップ、ダーウィン進化樹、アーケオプテリクス化石4本の柱がすべて転覆", "異種間の化石は一度も見つかっていません"]}, {"title": "科学的証拠が創造を指し示す", "points": ["DNAの複雑さと精度は偶然以上のものであり、正確に設計されなければなりません", "偶然にも、進化には現在の宇宙の年齢の297倍の時間がかかりました。", "進化の期待に反するカンブリア紀の成江化石"]}, {"title": "創造論：神のかたちによる創造", "points": ["初めに神は天と地を創造され、創造の頂点で神はご自身のかたちとかたちに人を創造されました。", "天地創造以来，神の永遠の力と神性がはっきりと知られてきました。", "人の出現は偶然ではなく、神の慎重な設計です"]}, {"title": "人間の尊厳：価値が決まる", "points": ["神はご自身のかたちに人を創造されました。人は神の愛の対象の顕現です。", "比較で探すべきではなく、作成時に存在していた価値", "比較で価値を見出すことは、苦労、競争、害につながります"]}, {"title": "堕落：関係の崩壊", "points": ["エデンの園では、人々は神の言葉に耳を傾ければ、神との良好な関係を持っています。", "人間の不従順：神ではなく、創造主のようになりたい", "壊れた関係の結果は堕落し、人々に害をもたらします。"]}, {"title": "神はあきらめなかった：決してあきらめない愛", "points": ["神は人々に自由意志を与えます。なぜなら、愛の対象は選択する権利を持たなければならないからです。", "人々は間違った選択をします。神はリスクを知っていますが、それを喜んで受け入れ、決してあきらめません", "神は率先して人を救いに備えさせ，その代償を払うために息子を遣わし，人間関係を回復されました。"]}], "quizzes": [{"q": "________、神は________を創造しました。", "s": "天地創造"}, {"q": "神はご自分のかたちに________をお造りになりましたが，ご自分のかたちに________女性をお造りになりました。", "s": "神の画像"}, {"q": "天地創造以来、神の________と________ははっきりと知られており、目には見えませんが、被造物を通して知ることができます。", "s": "神の永遠の力"}, {"q": "進化は科学的観点からの________にすぎず、繰り返しの実験によって証明された定理ではありません。", "s": "進化論的仮説"}, {"q": "ビデオは、進化の証拠の4つの主要な柱がすべて科学的に________であることを指摘しています。", "s": "柱の崩壊"}, {"q": "初期のカンブリア紀の化石集団には、________種の分類学的分類群がありました。", "s": "澄江化石"}, {"q": "人の堕落の本質は、彼が________創造され、創造主に従うことを拒否したということです。", "s": "人間の不従順"}, {"q": "初めに，人々が神と良い関係を築くことができるように，神は________を定められました。", "s": "エデンの園"}, {"q": "神は人々に________を与えます。なぜなら、愛の対象は選択する権利を持たなければならないからです。", "s": "自由意志"}, {"q": "ビデオで言及されている進化の柱のうち、含まれていないものはどれですか？", "s": "進化の柱", "o": "A.ミラーのネイティブスープ体験,B.ヘッケルの胚ダイアグラム,C.DNA二重らせん構造,D.始祖鳥の化石検査"}, {"q": "神はなぜ従順な人々の集団を造られなかったのでしょうか。", "s": "自由意志", "o": "A.神にはそれができません。,B.愛の対象は自主性を持たなければならず、強制されるのは真の愛ではありません,C.神は苦難を愛しておられる,D.聖書は説明していない"}, {"q": "キリスト教の価値観のルーツは何ですか？", "s": "人の価値", "o": "A.他社と比較して優れている,B.神のかたちに創造され、創造の時から価値が存在していた,C.売り上げの金額,D.他人の目"}, {"q": "創造論を支持するビデオの科学的観察にはどのようなものがありますか？ （複数選択可）", "s": "創造論者の証拠", "o": "A.DNAは非常に複雑で洗練されています,B.異種間の化石が見つからなかった,C.澄江の化石個体群は進化論と矛盾する,D.進化は定理であることが証明されている"}, {"q": "堕落に対する神の反応には，どのようなものが含まれますか。（複数選択可）", "s": "神の愛", "o": "A.人間を捨てる,B.決してあきらめない愛,C.主導権を握って，わたしたちの救いに備える,D.十字架の代償を払うために息子を送った"}, {"q": "進化は、繰り返しの実験によって証明された科学的定理です。", "s": "進化論的仮説"}, {"q": "人が高貴なのは，神のかたちと似姿に造られたからです。", "s": "人間の尊厳"}, {"q": "人類の堕落後、神は人類を見捨てました。", "s": "神はあきらめない"}, {"q": "なぜ神は愛の表現として自由意志をお与えになるのでしょうか。", "s": "自由意志"}, {"q": "人はどこから来たのか？なぜ創造は進化よりももっともらしいのでしょうか？", "s": "創造論"}]}, "ko": {"title": "제 9과 인간의 창조와 타락", "content": "인간은 하나님의 형상과 존엄성으로 창조되었지만 반역과 타락으로 인해 하나님과 분리되었습니다. 이 수업은 인간의 창조, 타락의 결과, 그리고 창세 전에 준비하신 하나님의 구속 계획에 관한 것입니다. 하나님의 형상의 존엄성을 소중히 여기고 죄를 멀리하십시오. 태초의 고귀한 모습을 그리스도 안에서 다시 찾으십시오.", "instructions": "", "guide": [{"title": "사람들은 어디에서 왔습니까: 큰 질문", "points": ["인간이 존재한 이래로, 사람들은 묻습니다: 나는 어디에서 왔는가, 어디로 갔는가?", "드래곤의 배경을 이해한다면 올바른 판단을 내릴 수 있다.", "시간과 공간의 제약 속에서 사람들은 추측만 할 수 있습니다."]}, {"title": "진화는 단지 가설일 뿐입니다.", "points": ["진화는 결코 과학적 정리가 아니며 단지 가상의 진술일 뿐입니다.", "밀러 실험, 헤켈 배아 지도, 다윈 진화 나무, 시조새 화석 네 개의 기둥이 모두 전복됨", "교차종 화석은 발견된 적이 없습니다."]}, {"title": "과학적 증거는 창조를 가리킨다", "points": ["DNA의 복잡성과 정밀도는 우발적 인 것 이상이며 정밀하게 설계되어야합니다.", "우연히 진화는 현재 우주의 나이보다 297배나 더 오래 걸렸다.", "진화론적 기대에 어긋나는 캄브리아기 청장 화석"]}, {"title": "창조론: 하나님의 형상으로 창조", "points": ["태초에 하나님은 하늘과 땅을 창조하셨습니다. 창조의 절정에서 하나님은 자신의 형상대로 사람을 창조하셨습니다.", "하늘과 땅이 창조된 이래로 하나님의 영원한 능력과 신성은 분명하게 알려졌습니다.", "사람의 외모는 우연이 아니라 하나님의 신중한 설계입니다."]}, {"title": "인간의 존엄성: 결정된 가치", "points": ["하나님께서는 자신의 형상대로 인간을 창조하셨고, 인간은 그분의 사랑의 대상을 나타냅니다.", "값은 비교에서 찾을 수 없는 생성 시점에 존재했습니다.", "비교에서 가치를 찾는 것은 투쟁, 경쟁 및 해로움으로 이어집니다."]}, {"title": "쓰러짐: 관계 붕괴", "points": ["에덴 동산에서 사람들은 하나님의 말씀을 듣기만 하면 하나님과 좋은 관계를 맺습니다.", "인간의 불순종: 신이 되지 말고 창조주처럼 되고 싶다.", "부러진 관계의 결과는 타락이며, 사람들에게 해를 끼칩니다."]}, {"title": "하나님은 결코 포기하지 않으셨다: 포기하지 않는 사랑", "points": ["사랑의 대상은 선택할 권리가 있어야 하기 때문에 하느님께서는 사람들에게 자유 의지를 주십니다.", "사람들은 잘못 선택하고, 신은 위험을 알고 있지만 기꺼이 감수하고, 절대 포기하지 않습니다.", "하나님께서는 구원을 위해 사람을 준비시키기 위해 주도권을 주셨고, 그 대가를 치르도록 아들을 보내셨고, 그 관계를 회복시키셨습니다."]}], "quizzes": [{"q": "________, 하나님은 ________ 을 (를) 창조하셨습니다.", "s": "천지창조"}, {"q": "하나님께서는 자신의 형상대로 ________ 을 (를) 만드셨지만, 자신의 형상대로 ________ 여성을 창조하셨습니다.", "s": "하나님의 형상"}, {"q": "천지가 창조된 이래 하나님의 ________ 과 ________ 은 (는) 눈에 보이지 않지만 피조물을 통해 알 수 있습니다.", "s": "하나님의 영원한 권능"}, {"q": "진화는 과학적 관점에서 ________ 일 뿐이며 반복된 실험으로 증명된 정리가 아닙니다.", "s": "진화론적 가설"}, {"q": "이 동영상은 진화에 대한 증거의 네 가지 주요 기둥이 모두 과학적으로 ________ 임을 지적합니다.", "s": "기둥 전복"}, {"q": "초기 캄브리아기 화석 개체군에는 ________ 종의 분류학적 분류군이 있었다.", "s": "청장 화석"}, {"q": "인간의 타락의 본질은 그가 ________ 창조되었고 창조주께 순종하기를 거부했다는 것입니다.", "s": "인간 불순종"}, {"q": "태초에 하나님께서는 사람들이 그분과 좋은 관계를 맺을 수 있도록 ________ 을 (를) 세우셨습니다.", "s": "에덴동산"}, {"q": "사랑의 대상은 선택할 권리가 있어야 하기 때문에 하나님은 사람들에게 ________ 을 (를) 주십니다.", "s": "자유 의지"}, {"q": "동영상에 언급된 진화 기둥 중 포함되지 않은 것은 무엇인가요?", "s": "진화의 기둥", "o": "A.밀러의 토종 수프 실험,B.헤켈의 배아도,C.DNA 이중 나선 구조,D.시조새 화석 조사"}, {"q": "왜 하나님께서는 순종하는 사람들의 그룹을 만들지 않으셨는가?", "s": "자유 의지", "o": "A.신은 그것을 할 수 없습니다.,B.사랑의 대상은 자율성을 가져야 하며, 강요되는 것은 진정한 사랑이 아니다.,C.하나님은 문제를 사랑하십니다,D.성경은 설명하지 않습니다"}, {"q": "그리스도인의 가치의 뿌리는 무엇인가?", "s": "사람의 가치", "o": "A.비교할 때 다른 사람들보다 낫습니다.,B.하나님의 형상대로 창조된 가치는 창조 때부터 존재해 왔습니다.,C.수입,D.타인의 시선"}, {"q": "동영상에서 창조론을 지지하는 과학적 관찰은 무엇입니까? (복수 선택)", "s": "창조론적 증거", "o": "A.DNA는 매우 복잡하고 정교합니다,B.발견되지 않은 교차종 화석,C.청장 화석 집단은 진화론과 모순된다.,D.진화는 하나의 정리임이 입증되었습니다."}, {"q": "타락에 대한 하나님의 반응에는 무엇이 포함되는가? (복수 선택)", "s": "하나님의 사랑", "o": "A.인간 포기하기,B.포기하지 않는 사랑,C.우리의 구원을 위해 주도적으로 준비하십시오,D.아들을 보내어 십자가에서 대가를 치르게 했습니다."}, {"q": "진화는 반복된 실험으로 증명된 과학적 정리이다.", "s": "진화론적 가설"}, {"q": "인간은 하나님의 형상대로 창조되었기 때문에 고귀합니다.", "s": "인간의 존엄성"}, {"q": "인간이 타락한 후, 하나님은 인류를 버리셨습니다.", "s": "하나님은 포기하지 않으신다"}, {"q": "하나님은 왜 사랑의 표현으로 자유 의지를 주시는가?", "s": "자유 의지"}, {"q": "사람들은 어디에서 왔을까요? 왜 창조가 진화보다 더 그럴듯한가?", "s": "창조론"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773054335715','基要真理','第十课 神的救赎, 公义 vs 慈爱','神兼慈爱与公义：慈爱主动预备救恩，公义要求罪付代价。本课看基督在十字架上的代赎，如何同时成全神的这两面。愿十字架的爱激励你一生跟随主。在十架前俯伏敬拜这位奇妙救主。','[{"a": "耶稣|主", "o": "《罗马书》10章9节", "q": "你若口里认________为________，心里信神叫祂从死里复活，就必得救。", "s": "口里承认", "type": "verse"}, {"a": "基督|新造", "o": "《哥林多后书》5章17节", "q": "若有人在________里，他就是________的人，旧事已过，都变成新的了。", "s": "新造的人", "type": "verse"}, {"a": "苦难|胜", "o": "《约翰福音》16章33节", "q": "在世上你们有________，但你们可以放心，我已经________了世界。", "s": "胜过苦难", "type": "verse"}, {"a": "公义", "o": "", "q": "圣经的救恩观中，除了神的慈爱，还有一个重要成分叫________。", "s": "公义慈爱", "type": "fill"}, {"a": "挽回祭", "o": "", "q": "神让无罪的儿子代替有罪的人，在十字架上成为我们的________。", "s": "挽回祭", "type": "fill"}, {"a": "仁义", "o": "", "q": "新造的人要活出真理的________和圣洁。", "s": "仁义圣洁", "type": "fill"}, {"a": "鬼魔", "o": "", "q": "雅各书说：你信神只有一位，你信的不错；________也信，只是战兢。", "s": "鬼魔也信", "type": "fill"}, {"a": "基督台", "o": "", "q": "基督徒将来要站在________前，按所行的受报，那是关乎奖赏的审判。", "s": "基督台前", "type": "fill"}, {"a": "白色大宝座", "o": "", "q": "全人类都要面对的终极审判，是________前的审判。", "s": "终极审判", "type": "fill"}, {"a": "B", "o": "A.解决人的困难,B.把人从罪中救出，恢复神人关系并改变生命,C.让人发财,D.普渡众生", "q": "圣经的救赎主要是指什么？", "s": "救赎定义", "type": "single"}, {"a": "B", "o": "A.神不爱他们,B.活在有罪的世代，圣经从未应许无灾无难,C.信心不够,D.救恩无效", "q": "基督徒为什么仍然会经历苦难？", "s": "苦难", "type": "single"}, {"a": "B", "o": "A.善行太多,B.人不是审判官，无权定功过相抵的规则,C.神不喜欢善行,D.圣经从没提过", "q": "“功过相抵”的观念错在哪里？", "s": "功过相抵", "type": "single"}, {"a": "B|C|D", "o": "A.信耶稣就无灾无难,B.苦难不能吞吃我们,C.在患难中神是随时的帮助,D.苦难中可活出不一样的生命力", "q": "基督徒面对苦难的正确认识包括哪些？（多选）", "s": "胜过苦难", "type": "multiple"}, {"a": "A|B|D", "o": "A.白色大宝座是终极审判,B.基督台前是基督徒按所行领赏,C.基督徒不再面对任何审判,D.基督徒得救却可能像从火里经过", "q": "关于两种审判，正确的是？（多选）", "s": "两种审判", "type": "multiple"}, {"a": "错", "o": "", "q": "只要积功德、做善事，不改变生命，将来也能得救。", "s": "功德观", "type": "judge"}, {"a": "对", "o": "", "q": "神看善行之前，先看作善行的那个人。", "s": "神看人", "type": "judge"}, {"a": "错", "o": "", "q": "“信耶稣保平安、保发财、一切苦难都没有”是圣经的真理。", "s": "成功神学", "type": "judge"}, {"a": "神是慈爱的，主动为我们预备救恩，差遣无罪的儿子在十字架上代替有罪的人成为挽回祭；神也是公义圣洁的，罪必须付代价。救恩恢复人与神的关系，更要求得救的人生命改变，活出真理的仁义和圣洁，满足神公义的要求。", "o": "", "q": "为什么说圣经的救恩包含公义与慈爱两个方面？", "s": "公义与慈爱", "type": "essay"}, {"a": "因为基督徒仍活在有罪的世代，圣经从未应许信耶稣就无灾无难。耶稣说“在世上你们有苦难，但你们可以放心，我已经胜了世界”。基督徒不免于苦难，却能胜过苦难——神在患难中是随时的帮助，苦难不能吞吃我们，也不能把我们与神的爱隔绝，反而使人更深认识神。", "o": "", "q": "基督徒得救后为什么还会有苦难？应如何面对？", "s": "面对苦难", "type": "essay"}]','https://youtu.be/gg7sI505B7w
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134FLhU','quiz','[{"title": "救恩不是解决我的问题", "points": ["人常把救恩定义为“神帮我解决困难”", "圣经的救恩是把人从罪的捆绑中救出，恢复到正确位置", "救恩带来生命特质的改变：真理的仁义和圣洁"]}, {"title": "公义与慈爱：救赎的两个层面", "points": ["神是慈爱的那位，也是公义圣洁的那位", "爱子在十字架上无罪代替有罪，满足了神的公义", "得救的人生命要转换，满足神属性中公义的一面"]}, {"title": "人造宗教的功德观", "points": ["人造宗教：积功德、修桥补路，将来换福报", "不管人本身如何，人际关系、婚姻忠贞一塌糊涂也无妨", "神看善行之前，先看作善行的这个人"]}, {"title": "为什么不能普渡众生", "points": ["若作奸犯科、贩卖人口都自然得救，这样的神合适吗", "得救却不改变生命本质，天堂只会是地球的翻版", "爱的关系不是由孩子主导，乃由智慧更高的父母主导"]}, {"title": "得救的条件：接待他为主", "points": ["雅各书：鬼魔也信，却是战兢——光信不够", "约翰福音：凡接待他的，就是信他名的人", "罗马书：口里认耶稣为主，心里信神叫他从死里复活，就必得救"]}, {"title": "得救仍有苦难", "points": ["主早已宣告：在世上你们有苦难，但放心，我已胜了世界", "人类死于彼此冲突战争的，远多于死于天灾的", "苦难不能吞吃我们，不能把我们与神的爱隔绝"]}, {"title": "白色大宝座与基督台前", "points": ["白色大宝座：全人类面对终极审判，盖棺并未论定", "基督台前：信徒按今生所行或善或恶受报，是奖赏而非定罪", "奖赏是爱的激励，不是功德交换，也不是威胁利诱"]}, {"title": "蒙恩的罪人：往前迈进", "points": ["基督徒承认仍会软弱跌倒，不是信了就变成圣人", "但不安于罪中，靠恩典圣灵不断往正确方向迈进", "从得救那一刻起，在每一天活出光盐荣美的生命"]}]','','10','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 10 God''s Redemption, Righteousness vs. Mercy", "content": "God is both loving and righteous: mercy takes the initiative to prepare for salvation, and righteousness demands the price of sin. This lesson looks at how the atonement of Christ on the cross can fulfill both aspects of God at the same time. May the love of the cross inspire you to follow the Lord throughout your life. Fall down before the cross and worship this marvelous Savior.", "instructions": "", "guide": [{"title": "Salvation is not the solution to my problems", "points": ["People often define salvation as \"God helps me solve difficulties\"", "Biblical salvation is delivering people from the bondage of sin and restoring them to their rightful place.", "Salvation changes the character of life: the righteousness and holiness of truth"]}, {"title": "Righteousness and mercy: two dimensions of redemption", "points": ["God is loving and righteous and holy.", "God''s justice was satisfied by the Son''s innocence on the cross in lieu of guilt.", "The life of the saved will be transformed to satisfy the righteous side of God''s attributes."]}, {"title": "The Karmic Virtue View of Artificial Religion", "points": ["Artificial religion: accumulating merit, repairing bridges and repairing roads, and exchanging for blessings in the future", "No matter who you are, relationships, marital fidelity are a mess.", "Before God sees good deeds, He sees this person as good deeds."]}, {"title": "Why can''t ubiquitous beings", "points": ["If adulterers and human traffickers are naturally saved, is such a god appropriate?", "Salvation does not change the essence of life, heaven will only be a replica of the earth", "Love relationships are not dominated by children, but by smarter parents"]}, {"title": "Conditions of salvation: receiving him as the main", "points": ["James: The devil also believes, but trembles - not enough.", "John: All Who Receive Him Are Those Who Believe in His Name", "Romans: Confess Jesus as Lord with your mouth, trust God in your heart to raise him from the dead, and you will be saved"]}, {"title": "There is still suffering to be saved", "points": ["The Lord has already declared: In the world you have suffering, but rest assured that I have overcome the world", "Human beings die in conflicts and wars with each other, far more than from natural disasters.", "Suffering cannot devour us, it cannot isolate us from the love of God."]}, {"title": "The Great White Throne and the Stand of Christ", "points": ["The Great White Throne: All Mankind Faces the Ultimate Judgment, and the Coffin Is Undecided", "Before Christ: It is a reward, not a condemnation, for believers to be rewarded according to what they have done in this life, for good or evil.", "Rewards are an incentive for love, not an exchange of merit or a threat of inducement."]}, {"title": "Gracious Sinner: Moving Forward", "points": ["Christians admit that they will still be weak and fall. If they don''t believe, they will become saints.", "But uncomfortable with sin, by grace the Holy Spirit continues to move in the right direction", "From the moment of salvation, live a glorious life of light and salt every day"]}], "quizzes": [{"q": "If you confess ________ as ________, and believe in your heart that God raised him from the dead, you will be saved.", "s": "Mouth acknowledgement"}, {"q": "If someone is in ________, he is a person of ________. The old things have passed away and become new.", "s": "Newly Created Man"}, {"q": "You have ________ in the world, but you can rest assured that I have ________ the world.", "s": "Victory over Suffering"}, {"q": "In the biblical view of salvation, in addition to God''s mercy, there is an important element called ________.", "s": "Righteousness and mercy"}, {"q": "God made sinless sons instead of sinners to be our ________ on the cross.", "s": "Sacrificial Sacrifice"}, {"q": "The new creation will live the ________ of truth and holiness.", "s": "Benevolence and Holiness"}, {"q": "James saith: Thou hast believed that there is one God; thou hast believed well: thou hast believed, and hast trembled.", "s": "Demons also believe"}, {"q": "In the future, Christians will stand before ________ and be rewarded according to their deeds, which is a judgment of reward.", "s": "In front of Christ"}, {"q": "The final judgment to be faced by all mankind is the judgment before ________.", "s": "Ultimate Trial"}, {"q": "What does biblical redemption primarily mean?", "s": "Definition of Redemption", "o": "A.Solving People''s Difficulties,B.Saving People from Sin, Restoring God-Man Relationships, and Changing Lives,C.Making people rich,D.Purdue sentient beings"}, {"q": "Why do Christians still suffer?", "s": "Ku Nan", "o": "A.God doesn''t love them,B.Living in a guilty age, the Bible never promises to be disaster-free,C.Not enough confidence,D.Salvation Nullified"}, {"q": "What is wrong with the concept of \"balance of merit\"?", "s": "Excess of merit", "o": "A.Too many good deeds,B.A person is not a judge, and has no right to set rules for the balance of merit,C.God does not like good deeds,D.The Bible never mentions"}, {"q": "What does it mean to be a Christian in the face of suffering? (Multiple choice)", "s": "Victory over Suffering", "o": "A.Believe in Jesus and you''ll be safe.,B.Suffering cannot eat us.,C.God is always there to help in times of trouble,D.Can live with different vitality in the midst of suffering"}, {"q": "What is true about the two trials? (Multiple choice)", "s": "Two Trial Types", "o": "A.The Great White Throne is the Final Judgment,B.Before Christ, Christians receive rewards according to their deeds.,C.Christians no longer face any trials,D.Christian salvation may be like passing through fire"}, {"q": "As long as you accumulate merit and do good deeds, you can still be saved in the future without changing your life.", "s": "Karmic virtue view"}, {"q": "Before God looks at good deeds, He looks at the person who has done the good deeds.", "s": "God sees people"}, {"q": "“Believe in Jesus for peace, wealth, and all suffering” is the biblical truth.", "s": "Success theology"}, {"q": "Why is it that biblical salvation encompasses both righteousness and mercy?", "s": "Justice and Mercy"}, {"q": "Why is there suffering after Christian salvation? How should you approach it?", "s": "Facing Suffering"}]}, "ja": {"title": "レッスン10神の贖い，義と憐れみ", "content": "神は愛に満ち，義に満ちておられます。憐れみは救いに備えるために主導権を握り，義は罪の代価を要求します。この課では，十字架上のキリストの贖罪がどのように神の両方の側面を同時に満たすことができるかを見ていきます。十字架の愛が，あなたの生涯を通して主に従うよう霊感を与えますように。十字架の前にひれ伏し，このすばらしい救い主を礼拝しましょう。", "instructions": "", "guide": [{"title": "救いは私の問題の解決策ではない", "points": ["人々はしばしば救いを「神は私が困難を解決するのを助けてくださる」と定義します", "聖書の救いは，人々を罪の束縛から救い，正しい場所に戻すことです。", "救いはいのちの性質，すなわち真理の義と聖性を変える"]}, {"title": "義と憐れみ：贖いの2つの側面", "points": ["神は愛にあふれ，正しく，聖なるお方です。", "神の義は，罪悪感の代わりに十字架上の御子が潔白であることによって満たされました。", "救われた人の生活は，神の属性の義の側面を満たすように変容されます。"]}, {"title": "人工宗教のカルマ的徳観", "points": ["人工宗教：功徳の蓄積、橋梁の修復、道路の修復、将来の祝福との交換", "あなたが誰であろうと、人間関係、夫婦の忠誠心はめちゃくちゃです。", "神は善行を見る前に，この人を善行と見なされます。"]}, {"title": "ユビキタスができない理由", "points": ["姦通者や人身売買業者が自然に救われるのであれば、そのような神は適切ですか？", "救いは人生の本質を変えることはありません、天国は地球のレプリカに過ぎません", "恋愛関係は子供によって支配されているのではなく、より賢い親によって支配されている"]}, {"title": "救いの条件：主を受け入れる", "points": ["ジェームズ：悪魔も信じていますが、十分ではありません。", "ヨハネ：御子を受け入れる者はみな，御子の御名を信じる者です", "ローマ人への手紙：イエスをあなたの口で主として告白し、心の中で神を信頼して彼を死者の中から復活させてください。そうすればあなたは救われます"]}, {"title": "救われるべき苦しみがまだ残っています", "points": ["主はすでに次のように宣言されています。「世にあってあなたがたは苦しんでいるが，わたしは世に打ち勝ったことを安心しなさい。", "人間は、自然災害よりもはるかに多く、お互いの紛争や戦争で命を落としています。", "苦しみは私たちを食い尽くすことはできませんし、神の愛から私たちを孤立させることもできません。"]}, {"title": "大いなる白い玉座とキリストの御座", "points": ["大いなる白い玉座：全人類が究極の審判に直面し、棺は未定", "キリストの前に：それは報いであり、非難ではありません。信者が善悪を問わず、この世で行ったことに応じて報いられるためです。", "報酬は愛のインセンティブであり、メリットの交換や誘惑の脅威ではありません。"]}, {"title": "恵み深い罪人：前進", "points": ["クリスチャンは、自分はまだ弱くて倒れることを認めています。信じなければ、彼らは聖人になるでしょう。", "しかし、罪に不快感を抱き、恵みによって聖霊は正しい方向に進み続けます", "救いの瞬間から、毎日光と塩の輝かしい人生を送りましょう"]}], "quizzes": [{"q": "もしあなたが________を________として告白し，神が彼を死者の中から復活させたと心の中で信じるなら，あなたは救われるでしょう。", "s": "口頭での謝辞"}, {"q": "誰かが________にいる場合、その人は________の人です。古いものは過ぎ去り、新しいものになりました。", "s": "新しく創造された男"}, {"q": "あなたは世界に________を持っていますが、私が世界に________を持っていることは安心できます。", "s": "苦しみに勝利する"}, {"q": "聖書的な救いの観点では，神の憐れみに加えて， ________と呼ばれる重要な要素があります。", "s": "義と憐れみ"}, {"q": "神は，罪人の代わりに罪のない息子たちを十字架上のわたしたちの________とされました。", "s": "生贄の犠牲"}, {"q": "新しい創造物は，真理と聖性の________を生きるでしょう。", "s": "慈悲と神聖さ"}, {"q": "ヤコブは言った。「あなたは神はただひとりであると信じ、よく信じた。あなたは信じておののいた。", "s": "悪魔も信じています"}, {"q": "将来，クリスチャンは________の前に立ち，自分の行いに応じて報いられるようになります。これは報いの裁きです。", "s": "キリストの前で"}, {"q": "全人類が直面する最後の審判は、________の前の審判です。", "s": "最後の審判"}, {"q": "聖書の贖いとは，主にどのような意味ですか。", "s": "償還の定義", "o": "A.人々の困難を解決する,B.罪から人々を救い，神と人の関係を回復し，人生を変える,C.人々を豊かにする,D.パーデューの知的存在"}, {"q": "なぜクリスチャンはいまだに苦しんでいるのでしょう", "s": "苦しみ", "o": "A.神は彼らを愛していない,B.罪悪感のある時代に生きている聖書は、災害のないことを約束することは決してありません,C.自信が足りない,D.救済が無効化されました"}, {"q": "「バランス・オブ・メリット」という概念のどこが間違っているのでしょうか？", "s": "メリットの超過", "o": "A.善行が多すぎる,B.人は裁判官ではなく、メリットのバランスのためのルールを設定する権利はありません,C.神は善行を好まない,D.聖書は決して言及しない"}, {"q": "苦しみに直面してクリスチャンになるとは，どういう意味でしょうか。（複数選択可）", "s": "苦しみに勝利する", "o": "A.イエスを信じれば、あなたは安全です。,B.苦しみは私たちを食べることはできません。,C.神は困難な時にいつでも助けてくださる,D.苦しみの中でさまざまな活力を持って生きることができます"}, {"q": "2つの試練について，どのようなことが当てはまりますか。（複数選択可）", "s": "2つのトライアルタイプ", "o": "A.大いなる白い玉座が最後の審判,B.キリストの前では，クリスチャンは自分の行いに応じて報酬を受け取ります。,C.クリスチャンはもはや試練に直面していない,D.キリスト教の救いは，火の中を通るようなものかもしれません"}, {"q": "メリットを蓄積し、善行をしていれば、人生を変えることなく、将来も救われることができます。", "s": "カルマの美徳ビュー"}, {"q": "神は善行を見る前に，善行をした人を見ておられます。", "s": "神は人を見る"}, {"q": "「平和のために，富のために，すべての苦しみのためにイエスを信じる」ことは聖書の真理です。", "s": "成功神学"}, {"q": "聖書の救いには，なぜ義と憐れみの両方が含まれているのでしょうか。", "s": "正義と慈悲"}, {"q": "キリスト教の救いの後に苦しみがあるのはなぜですか。どのようにアプローチすべきでしょうか？", "s": "苦しみに直面する"}]}, "ko": {"title": "제 10과 하나님의 구속, 의로움 vs. 자비", "content": "하나님은 사랑이시며 의로우십니다. 자비는 구원을 준비하기 위해 주도권을 잡으며, 의는 죄의 대가를 요구합니다. 이 과는 십자가에서 그리스도의 속죄가 어떻게 하나님의 두 가지 측면을 동시에 성취할 수 있는지 살펴본다. 십자가의 사랑이 여러분이 평생 동안 주님을 따르도록 영감을 주기를 바랍니다. 십자가 앞에 엎드려 이 놀라운 구주께 경배하십시오.", "instructions": "", "guide": [{"title": "구원은 내 문제의 해결책이 아니다.", "points": ["사람들은 종종 구원을 \"하나님은 내가 어려움을 해결할 수 있도록 도와주신다\" 라고 정의합니다.", "성경적 구원은 사람들을 죄의 속박에서 구하고 그들을 정당한 장소로 회복시키는 것입니다.", "구원은 삶의 성격을 변화시킵니다: 진리의 의로움과 거룩함"]}, {"title": "의와 자비: 구속의 두 가지 차원", "points": ["하나님은 사랑이 많으시고 의로우시며 거룩하십니다.", "하나님의 공의는 죄책감 대신에 십자가에서 아들의 무죄로 충족되었습니다.", "구원받은 자들의 삶은 하나님의 속성의 의로운 면을 만족시키기 위해 변화될 것이다."]}, {"title": "인위적 종교에 대한 카르마적 미덕의 관점", "points": ["인공종교: 공로 축적, 교량 보수 및 도로 보수, 향후 축복 교환", "당신이 누구이든, 관계, 결혼 충실도는 엉망입니다.", "하나님께서는 선한 행실을 보시기 전에 이 사람을 선한 행실로 보십니다."]}, {"title": "유비쿼터스 존재는 왜 유비쿼터스 존재가 될 수", "points": ["간통자와 인신매매범이 자연적으로 구원받는다면, 그런 신이 적절한가?", "구원은 삶의 본질을 변화시키지 않으며, 천국은 단지 지구의 복제품일 뿐입니다.", "사랑 관계는 자녀가 아니라 더 똑똑한 부모가 지배합니다."]}, {"title": "구원의 조건: 그분을 주요한 존재로 영접함", "points": ["야고보서: 악마도 믿지만 떨립니다. 충분하지 않습니다.", "요한: 그분을 영접하는 모든 사람은 그분의 이름을 믿는 사람들입니다.", "로마서: 당신의 입으로 예수님을 주님으로 고백하고, 당신의 마음에 하나님을 신뢰하여 그분을 죽은 자 가운데서 살리십시오. 그러면 당신은 구원을 얻을 것입니다."]}, {"title": "아직 구원받아야 할 고통이 남아 있습니다", "points": ["주님은 이미 선언하셨습니다: 세상에서는 너희가 고난을 당하나 내가 세상을 이기었으니 안심하라.", "인간은 자연 재해보다 훨씬 더 많은 갈등과 전쟁에서 서로 죽습니다.", "고난은 우리를 삼킬 수 없으며, 우리를 하나님의 사랑에서 고립시킬 수 없습니다."]}, {"title": "위대한 백보좌와 그리스도의 스탠드", "points": ["위대한 백좌: 모든 인류는 궁극적인 심판에 직면하고 관은 결정되지 않습니다.", "그리스도 앞에서: 신자들이 선과 악에 대해 현세에서 행한 것에 따라 보상을 받는 것은 정죄가 아니라 보상입니다.", "보상은 사랑의 인센티브이지, 가치의 교환이나 유도의 위협이 아닙니다."]}, {"title": "은혜로운 죄인: 앞으로 나아가기", "points": ["그리스도인들은 여전히 연약하고 넘어질 것을 인정합니다. 믿지 않으면 성인이 될 것입니다.", "그러나 죄에 대해 불편함을 느끼며, 성령께서는 은총으로 계속해서 올바른 방향으로 나아가신다.", "구원의 순간부터 매일 빛과 소금의 영광스러운 삶을 살아가십시오."]}], "quizzes": [{"q": "당신이 ________ 을 ________________________________________________________________________________________________", "s": "입안 확인"}, {"q": "만약 누군가가 ________ 에 있다면, 그는 ________ 의 사람입니다. 옛 것은 사라지고 새로워졌습니다.", "s": "새로 창조된 인간"}, {"q": "세상에 ________ 이 (가) 있지만, 나에게도 ________ 이 (가) 있으니 안심하셔도 됩니다.", "s": "고통에 대한 승리"}, {"q": "구원에 대한 성경적 견해에는 하나님의 자비 외에도 ________ 이라는 중요한 요소가 있습니다.", "s": "의와 자비"}, {"q": "하나님께서는 죄인들 대신에 죄 없는 아들들을 십자가에서 우리의 ________ 이 되게 하셨습니다.", "s": "희생"}, {"q": "새로운 피조물은 진리와 거룩함의 ________ 을 살게 될 것이다.", "s": "자비와 거룩함"}, {"q": "야고보가 가로되 네가 하나님은 한 분이신 줄을 믿느냐 잘 믿느냐 믿고 떨었도다", "s": "악마도 믿는다"}, {"q": "앞으로 그리스도인들은 ________ 앞에 서서 그들의 행동에 따라 보상을 받게 될 것이며, 이는 보상의 심판입니다.", "s": "그리스도 앞에서"}, {"q": "모든 인류가 직면해야 할 최종 심판은 ________ 이전의 심판입니다.", "s": "최후의 심판"}, {"q": "성경적 구속은 주로 무엇을 의미하는가?", "s": "구속의 정의", "o": "A.사람들의 어려움 해결하기,B.사람들을 죄에서 구원하고, 하나님과 인간의 관계를 회복하고, 삶을 변화시키는 것,C.사람들을 부유하게 만드는 것,D.Purdue sentient beings"}, {"q": "왜 그리스도인들은 여전히 고통을 겪는가?", "s": "고통", "o": "A.하나님은 그들을 사랑하지 않으십니다.,B.죄가 없는 시대에 살면서 성경은 결코 재앙이 없을 것이라고 약속하지 않습니다.,C.자신감이 부족함,D.구원이 무효화됨"}, {"q": "''능력의 균형'' 이라는 개념에서 무엇이 잘못되었습니까?", "s": "과도한 실적", "o": "A.선행이 너무 많음,B.사람은 판사가 아니며 공로 균형에 대한 규칙을 설정할 권리가 없습니다.,C.하나님은 선한 행위를 좋아하지 않으신다.,D.성경은 결코 언급하지 않습니다"}, {"q": "고통 앞에서 그리스도인이 된다는 것은 무엇을 의미하는가? (복수 선택)", "s": "고통에 대한 승리", "o": "A.예수님을 믿으면 안전할 거예요.,B.고난은 우리를 잡아먹을 수 없습니다.,C.하나님은 어려움에 처했을 때 항상 도와주십니다.,D.고통 속에서 다양한 활력을 느끼며 살아갈 수 있습니다."}, {"q": "두 가지 시련에 대한 진실은 무엇인가? (복수 선택)", "s": "두 가지 임상시험 유형", "o": "A.대백자좌는 최후의 심판이다,B.그리스도 앞에서 그리스도인들은 자신의 행위에 따라 보상을 받습니다.,C.그리스도인들은 더 이상 어떤 시련도 겪지 않습니다.,D.그리스도인의 구원은 불을 통과하는 것과 같을 수 있습니다."}, {"q": "공로를 쌓고 선을 행하는 한 인생을 바꾸지 않고도 미래에 구원받을 수 있습니다.", "s": "공덕관"}, {"q": "하나님께서는 선한 행실을 보시기 전에 선한 행실을 행한 사람을 먼저 보십니다.", "s": "하나님은 사람을 보신다"}, {"q": "“평화와 부와 모든 고통을 위해 예수님을 믿으십시오” 는 성경적 진리입니다.", "s": "성공회 신학"}, {"q": "왜 성경적 구원이 의와 자비를 모두 포괄하는가?", "s": "정의와 자비"}, {"q": "그리스도인의 구원 후에 고통이 있는 이유는 무엇인가? 어떻게 접근해야 할까요?", "s": "고통에 직면하기"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773054757941','基要真理','第十一课 因信称义 vs 因行为称义','因信称义是信仰核心：与神建立关系，而非靠行善积功德与神交换。本课辨明真信心与行为的关系，脱离律法主义。愿你因信得生，在恩典中长进。唯独信心，唯独恩典，唯独基督。','[{"type": "verse", "q": "【经文填空】因为神的________正在这福音上显明出来，如经上所记：________。", "o": "《罗马书》1章17节", "s": "因信称义", "a": "义|义人必因信得生"}, {"type": "verse", "q": "【经文填空】你若口里认________，心里信神叫他从死里________，就必得救。", "o": "《罗马书》10章9节", "s": "口里承认心里相信", "a": "耶稣为主|复活"}, {"type": "verse", "q": "【经文填空】你们得救是本乎________，也因着________；这并不是出于自己，乃是神所赐的。", "o": "《以弗所书》2章8节", "s": "得救本乎恩", "a": "恩|信"}, {"type": "fill", "q": "人所造的宗教想靠修桥铺路积功德来与神交换福报，而真神启示的信仰更看重的是________必须先对。", "o": "", "s": "宗教与信仰之别", "a": "人"}, {"type": "fill", "q": "因信称义的“信”不是口头宣告，而是扎根在与神的________上，并带来生命的改变。", "o": "", "s": "真信心的含义", "a": "关系"}, {"type": "fill", "q": "保罗引用哈巴谷书说明“义人必因信得生”，哈巴谷在环境恶劣中仍坚信神仍然________。", "o": "", "s": "哈巴谷的信心", "a": "掌权"}, {"type": "fill", "q": "雅各书说，你信神只有一位，你信的不错，________也信，却是战兢。", "o": "", "s": "真假信心", "a": "鬼魔"}, {"type": "fill", "q": "雅各书强调：真信心必带出________的改变，“你将你没有行为的信心指给我看，我便借着我的行为将我的信心指给你看”。", "o": "", "s": "信心与行为", "a": "行为"}, {"type": "fill", "q": "真正的决志包括：承认宇宙间有独一真神、承认自己是________、接受神所预备的救恩。", "o": "", "s": "决志的内容", "a": "罪人"}, {"type": "single", "q": "根据本课，因信称义中的“信”主要是指什么？", "o": "A.在布道会上举手表示相信,B.口里认耶稣为主、心里信神叫他从死里复活，并以他为生命的主,C.相信神会保平安保发财,D.相信神无条件接纳我本来的样子", "s": "信的含义", "a": "B"}, {"type": "single", "q": "罗马书与雅各书关于“称义”的教导，二者的关系是？", "o": "A.互相矛盾，只能信其一,B.罗马书讲因信称义，雅各书讲真信心必带出行为，两者互相说明,C.雅各书否定了保罗的因信称义,D.两卷书讲的是完全不同的救恩", "s": "两卷书的关系", "a": "B"}, {"type": "single", "q": "本课指出，有些布道会把真理传讲不清楚，会导致什么危机？", "o": "A.信徒奉献太少,B.人以为自己得救了其实没有得救，生命从未被改变,C.教会人数增长太慢,D.信徒过于热心", "s": "传讲清楚的福音", "a": "B"}, {"type": "multiple", "q": "本课提到，真正的得救包括哪几个方面？（多选）", "o": "A.承认宇宙间有一位独一真神，得救的方法由他定,B.承认自己是罪人，靠自己无法自救,C.接受神所预备的救恩,D.在今生按着真理活出新生的样式", "s": "得救的含义", "a": "A|B|C|D"}, {"type": "multiple", "q": "以下哪些是本课所批判的错误观念？（多选）", "o": "A.信耶稣保平安保顺利的成功神学,B.积功德换福报的人造宗教观,C.举手决志就保证上天堂、生命不需改变,D.只要我喜欢有什么不可以的老我心态", "s": "错误观念", "a": "A|B|C|D"}, {"type": "judge", "q": "因信称义意味着信主后什么都不必做，只要相信就能上天堂。", "o": "", "s": "因信称义", "a": "错"}, {"type": "judge", "q": "雅各书与罗马书都出于圣灵感动，因此关于称义的教导不会互相矛盾。", "o": "", "s": "圣经无矛盾", "a": "对"}, {"type": "judge", "q": "真信心一定会带来生命的改变，活出行为称义的现象。", "o": "", "s": "信心与行为", "a": "对"}, {"type": "essay", "q": "请简述本课中“人造的宗教”与“神启示的信仰”的根本区别。", "o": "", "s": "宗教与信仰", "a": "人造的宗教靠人行善积功德与神交换福报；神启示的信仰强调人必须先对——恢复与神的关系、接受耶稣作生命的主，人对了自然流露出善行。得救本乎恩也因着信，不是靠行为，免得有人自夸。"}, {"type": "essay", "q": "为什么说罗马书的因信称义与雅各书的因行为称义并不矛盾？", "o": "", "s": "两卷书调和", "a": "两者都出于圣灵感动。罗马书强调人得救不是靠行为，而是靠与神建立关系、接受他作生命的主；雅各书说明何为真信心——真信心必带出行为，使人脱下旧人穿上新人。信心带来行为的改变，两卷书是互相说明的。"}]','https://youtu.be/hdbttfZVAlU
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134z0xN','quiz','[{"title": "人造宗教与神启信仰的根本区别", "points": ["人造宗教：用人行善去跟神交换福报", "神看重的是“人”先对了，善行才有意义", "人不对也能行善，神看的是人有没有按神形象活出样式"]}, {"title": "因信称义不是廉价的相信", "points": ["罗马书：神的义在福音上显明（罗1:17）", "哈巴谷书：义人必因信得生（哈2:4），不凭环境信靠", "信是扎根在与神的关系上，带出生命改变"]}, {"title": "什么是真正的信", "points": ["口里认耶稣为主，心里信神叫祂从死里复活（罗10:9）", "主是生命的主：圣经真理成为行事为人的标准", "种子落在荆棘里的比喻：苦难来就不信，不是真信"]}, {"title": "雅各书与罗马书：冲突还是互补", "points": ["雅各书：鬼魔也信，只是战兢（雅2:19）", "信心若只停在意念里，连撒旦的标准都达不到", "两卷书同为圣灵感动，互相说明、不矛盾"]}, {"title": "行为的真义：新生命的流露", "points": ["雅各书的行为不是积功德，而是脱下旧人穿上新人", "因信称义必定带出行为称义的结果", "新生命的改变：价值观、品格被更新"]}, {"title": "布道会的危机与真正的决志", "points": ["只讲祝福不讲罪，可能让人“得救”了却没重生", "真正的决志：独一真神、承认是罪人、接受救恩、活出新生", "以弗所书：得救本乎恩因着信，不是出于行为（弗2:8-9）"]}]','','11','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 11 Justification by Faith vs. Justification by Action", "content": "Justification by faith is the core of faith: a relationship with God, not an exchange with God for good works. In this lesson, we identify the relationship between true faith and action, free from legalism. Thou shalt live by faith, and thou shalt grow in grace. Faith alone, grace alone, Christ alone.", "instructions": "", "guide": [{"title": "The fundamental difference between artificial religion and divine revelation", "points": ["Artificial religion: using people to do good deeds to exchange blessings with God", "What God values is that \"people\" are right first, and good deeds have meaning", "People can do good even if they are wrong. What God looks at is whether people live in the image of God."]}, {"title": "Justification by faith is not cheap belief.", "points": ["Romans: God''s righteousness is revealed in the gospel (Romans 1:17)", "Habakkuk: The righteous shall live by faith (Habakkuk 2: 4), not by circumstances.", "Faith is rooted in a relationship with God that changes lives"]}, {"title": "What is a true letter?", "points": ["Confessing the Lord Jesus with his mouth and believing in God in his heart, he raised him from the dead (Romans 10: 9)", "The Lord is the Lord of Life: Biblical Truths Become the Criteria for Acting", "Parable of the Seed in the Thorns: Suffering Does Not Believe, It Is Not True Faith"]}, {"title": "Jacob and Romans: Conflict or Complementarity?", "points": ["James: Demons also believe, but tremble (James 2:19)", "If faith stays in the mind, even Satan''s standards are not met", "The two books are both inspired by the Holy Spirit, explaining each other and not contradicting each other"]}, {"title": "The Truth of Behavior: The Unfolding of New Life", "points": ["The act of Jacob is not to accumulate merit, but to take off the old man and put on the new man.", "Justification by faith must produce the result of righteousness by works.", "Changes in new life: values, character are renewed"]}, {"title": "The Crisis of Evangelism and True Determination", "points": ["Only talking about blessings and not sin, may make people \"saved\" but not reborn", "True Determination: One True God, Admit to Being a Sinner, Receive Salvation, Live a New Life", "Ephesians: Salvation by grace, by faith, not by works (Ephesians 2: 8-9)"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] Because the ________ of God is being manifested in this gospel, as it is written: ________.", "s": "Justification by Faith"}, {"q": "[Scripture Fill in the Blank] If you confess ________ in your mouth and believe in God to make him ________ from the dead, you will be saved.", "s": "Acknowledge by mouth what you believe in your heart"}, {"q": "[Scripture fills in the blanks] Your salvation is by ________ and by ________; it is not of yourselves, but of God.", "s": "Salvation is by Grace"}, {"q": "The religion created by man wants to exchange blessings with God by building bridges and paving roads, and the belief revealed by the true God is more important that ________ must be correct first.", "s": "Religion vs. Faith"}, {"q": "The “faith” justified by faith is not a verbal statement, but is rooted in the ________ with God and brings about a change in life.", "s": "The Meaning of True Faith"}, {"q": "Paul quotes the book of Habakkuk to explain that \"the righteous shall live by faith\", and Habakkuk still firmly believes that God is still ________ in the harsh environment.", "s": "Habakkuk''s Faith"}, {"q": "James saith, Thou believest that there is one God; thou doest well: thou also believeest, and trembleth.", "s": "True or False Faith"}, {"q": "James emphasizes that true faith will bring about a change of ________, “Show me your faith that you have not done, and I will show you my faith by my works.”", "s": "Confidence & Behavior"}, {"q": "Real decisions include recognizing that there is only one true God in the universe, acknowledging that you are ________, and accepting God''s prepared salvation.", "s": "Content of the decision"}, {"q": "According to this lesson, what is the main meaning of “letter” in justification by faith?", "s": "The meaning of the letter", "o": "A.Raise your hand at a sermon to show you believe,B.Confessing the Lord Jesus with his mouth and believing in God in his heart, he raised him from the dead and made him the Lord of life.,C.Believe that God will keep you safe and rich,D.Believe that God unconditionally accepts me as I am"}, {"q": "What is the relationship between Romans and Jacob''s teaching on “justification”?", "s": "The Relationship Between Two Books", "o": "A.Contradict each other, only one can be trusted,B.The book of Romans speaks of justification by faith, the book of James speaks of true faith and will bring out deeds, and the two explain each other,C.James denies Paul''s justification by faith,D.The two books are about a completely different kind of salvation."}, {"q": "This lesson points out that some sermons can lead to crises when the truth is not clearly preached.", "s": "Preach the gospel clearly", "o": "A.Believers give too little,B.People think that they are saved, but in fact, they are not saved, and their lives have never been changed.,C.Church Growth Too Slow,D.Believers are too enthusiastic"}, {"q": "What aspects of true salvation are mentioned in this lesson? (Multiple choice)", "s": "Meaning of Salvation", "o": "A.Recognize that there is only one true God in the universe, and the way to salvation is determined by him,B.Admit that you are a sinner and can''t save yourself,C.Receiving God''s provision for salvation,D.Living a new life according to the truth in this life"}, {"q": "Which of the following are misconceptions that are criticized in this lesson? (Multiple choice)", "s": "Misconceptions", "o": "A.Believe in the prosperity theology of Jesus'' peace and security,B.The Artificial Religion View of Jakongdeok for Blessing,C.Raise your hand to make a decision to go to heaven, life does not need to change,D.As long as I like the old mentality that something can''t be done"}, {"q": "Justification by faith means that after believing in the Lord, you don''t have to do anything, as long as you believe, you can go to heaven.", "s": "Justification by Faith"}, {"q": "Both James and Romans are inspired by the Holy Ghost, so the teachings on justification do not contradict each other.", "s": "Biblical uncontradictory"}, {"q": "True faith must bring about life-changing, living out the phenomenon of righteous deeds.", "s": "Confidence & Behavior"}, {"q": "Briefly describe the fundamental difference between “man-made religion” and “divinely revealed faith” in this lesson.", "s": "Religion & Spirituality"}, {"q": "Why is there no contradiction between the justification by faith in Romans and the justification by works in Jacob?", "s": "Two Volume Book Harmony"}]}, "ja": {"title": "レッスン11信仰による正当化と行動による正当化", "content": "信仰による義認は信仰の核心です。良い行いとの交換ではなく、神との関係です。このレッスンでは，律法主義のない真の信仰と行動との関係を特定します。あなたは信仰によって生き，恵みのうちに成長するでしょう。信仰のみ、恵みのみ、キリストのみ。", "instructions": "", "guide": [{"title": "人工宗教と神の啓示の根本的な違い", "points": ["人工宗教：人を使って善行をし、神と祝福を交換する", "神が大切にしているのは、「人」が先に正しく、善行には意味があるということです", "人は間違っていても善を行うことができます。神が見ているのは、人が神のかたちに生きているかどうかです。"]}, {"title": "信仰による義認は，安っぽい信仰ではありません。", "points": ["ローマ：神の義は福音に啓示されています（ローマ1 ： 17 ）", "ハバクク：義人は状況ではなく、信仰によって生きるべきです（ハバクク2 ： 4 ）。", "信仰は、人生を変える神との関係に根ざしています"]}, {"title": "本当の文字とは何ですか？", "points": ["彼は口をもって主イエスを告白し，心の中で神を信じて，イエスを死人の中からよみがえらせました（ローマ10 ： 9 ）。", "主はいのちの主である：聖書の真理は行動するための基準になる", "いばらの種のたとえ：苦しみは信じない、それは真の信仰ではない"]}, {"title": "ヤコブとローマ人：対立か補完か？", "points": ["ジェームズ：悪霊も信じていますが、身震いしています（ジェームズ2 ： 19 ）", "信仰が心にとどまっていれば，サタンの基準さえ満たされません", "この2冊の本はどちらも聖霊に触発されており、互いに説明し合っており、矛盾していません"]}, {"title": "行動の真実：新しい人生の展開", "points": ["ヤコブの行為は、功績を蓄積することではなく、古い人を脱ぎ捨てて新しい人を着ることです。", "信仰による義は，行いによる義の結果を生み出さなければなりません。", "新しい人生の変化：価値観、キャラクターが更新されます"]}, {"title": "伝道の危機と真の決意", "points": ["罪ではなく祝福について話すだけで、人々は「救われる」が、生まれ変わることはない", "真の決意：唯一の真の神、罪人であることを認め、救いを受け、新しい人生を送る", "エペソ：恵みによる救い，行いによるのではなく信仰による救い（エペソ2 ： 8 － 9 ）"]}], "quizzes": [{"q": "〔聖句の穴埋め〕なぜなら，神の________は，次のように書かれているこの福音書に現れているからです： ________。", "s": "信仰による義認"}, {"q": "〔聖句の穴埋め〕もしあなたが口で________を告白し，心の中で神が死者の中から________を告げられたと信じるなら，あなたは救われるでしょう。", "s": "自分が心の中で信じていることを口で認める"}, {"q": "[聖文は空白を埋めます]あなたの救いは________と________によるものです。それはあなた自身のものではなく、神のものです。", "s": "救いは恵みによってもたらされる"}, {"q": "人間によって創造された宗教は、橋を架け、道を舗装することによって神と祝福を交換したいと望んでおり、真の神によって明らかにされた信仰は、________が最初に正しくなければならないということがより重要です。", "s": "宗教vs.信仰"}, {"q": "信仰によって義とされる「信仰」は，口頭で述べるものではなく，神とともにある________に根ざしており，人生に変化をもたらします。", "s": "真の信仰の意味"}, {"q": "パウロはハバククの書を引用して「義人は信仰によって生きる」と説明し、ハバククは依然として神が依然として過酷な環境の中で________であると確信しています。", "s": "ハバククの信仰"}, {"q": "ヤコブは言った。「あなたは神はただひとりであると信じている。あなたはよく働いている。あなたもまた信じておののいている。", "s": "真または偽の信仰"}, {"q": "ヤコブは，真の信仰が________の変化をもたらすことを強調しています。「あなたがしていない信仰を見せてください。そうすれば，わたしの行いによってわたしの信仰を見せてあげます。」", "s": "自信と行動"}, {"q": "真の決断には，宇宙に真の神はただひとりであることを認識し，自分が________であることを認め，神が備えられた救いを受け入れることが含まれます。", "s": "決定の内容"}, {"q": "このレッスンによると，信仰による義認における「文字」の主な意味は何ですか。", "s": "文字の意味", "o": "A.信じることを示す説教で手を挙げてください,B.彼は口をもって主イエスを告白し，心の中で神を信じて，イエスを死人の中からよみがえらせ，命の主としました。,C.神があなたを安全で豊かに保ってくださると信じる,D.神は私をあるがままに無条件に受け入れてくださると信じる"}, {"q": "「義認」に関するローマ人の教えとヤコブの教えの間には，どのような関係があるでしょうか。", "s": "2冊の本の関係", "o": "A.お互いに矛盾しています。信頼できるのは1つだけです,B.ローマ書は信仰による義について語り，ヤコブ書は真の信仰について語り，行いをもたらし，両者は互いに説明し合います。,C.ヤコブは信仰によるパウロの義認を否定する,D.この二つの書は，まったく異なる種類の救いについて書かれています。"}, {"q": "この課では，真理が明確に説教されていない場合，一部の説教は危機につながる可能性があることを指摘します。", "s": "福音をはっきりと宣べ伝える", "o": "A.信者は与えるものが少なすぎる,B.人々は自分は救われていると思っていますが、実際には救われておらず、自分の人生は決して変わっていません。,C.教会の成長が遅すぎる,D.信者は熱心すぎる"}, {"q": "この課では，真の救いのどのような側面について言及していますか。（複数選択可）", "s": "救いの意味", "o": "A.宇宙には真の神はただ一人しかおらず、救いへの道は神によって定められていることを認識する,B.自分が罪人であり、自分自身を救うことができないことを認める,C.神の救いの備えを受ける,D.この世で真理に従って新しい生活を送る"}, {"q": "この課で批判されている誤解は，次のうちどれですか。（複数選択可）", "s": "誤解", "o": "A.イエスの平和と安全の繁栄神学を信じる,B.祝福のためのジャコンドクの人工宗教観,C.天国に行く決断をするために手を挙げてください、人生は変わる必要はありません,D.何かができないという古い考え方が好きである限り"}, {"q": "信仰による義とは，主を信じた後は何もする必要がなく，信じる限り天国に行けることを意味します。", "s": "信仰による義認"}, {"q": "ヤコブもローマ人も聖霊に触発されているので，義認に関する教えは互いに矛盾しません。", "s": "聖書的に矛盾しない"}, {"q": "真の信仰は，人生を変えるものであり，義にかなった行いという現象を実践するものでなければなりません。", "s": "自信と行動"}, {"q": "この課では，「人が造った宗教」と「神が啓示された信仰」の根本的な違いを簡単に説明してください。", "s": "宗教と信仰"}, {"q": "ローマ人への信仰による義とヤコブの行いによる義との間には，なぜ矛盾がないのでしょうか。", "s": "ツー・ボリューム・ブック・ハーモニー"}]}, "ko": {"title": "제 11과 믿음에 의한 의화 vs 행동에 의한 의화", "content": "신앙에 의한 의화는 신앙의 핵심입니다. 하나님과의 관계는 선행을 위한 하나님과의 교환이 아닙니다. 이 수업에서 우리는 율법주의에서 벗어나 참된 신앙과 행동의 관계를 파악한다. 당신은 믿음으로 살며 은혜 안에서 성장할 것입니다. 오직 믿음, 오직 은혜, 오직 그리스도.", "instructions": "", "guide": [{"title": "인공 종교와 신성한 계시의 근본적인 차이점", "points": ["인위적 종교: 선행을 위해 사람들을 사용하여 하나님과 축복을 교환하는 것", "하나님이 중요하게 생각하시는 것은 \"사람\" 이 먼저 옳고 선행에는 의미가 있다는 것입니다.", "사람은 잘못되어도 선을 행할 수 있습니다. 하나님께서 보시는 것은 사람이 하나님의 형상대로 살고 있느냐는 것입니다."]}, {"title": "믿음에 의한 칭의는 값싼 믿음이 아닙니다.", "points": ["로마서: 하나님의 의가 복음에 나타남 (로마서 1:17)", "하박국: 의인은 상황이 아니라 믿음으로 살리라 (하박국 2: 4).", "신앙은 삶을 변화시키는 하나님과의 관계에 뿌리를 두고 있습니다."]}, {"title": "참된 편지란 무엇인가?", "points": ["주 예수를 입으로 시인하고 그 마음에 하나님을 믿어 죽은 자 가운데서 살리셨도다 (로마서 10: 9)", "주님은 생명의 주님이십니다: 성경적 진리는 행동의 기준이 됩니다", "가시덤불 속 씨앗의 비유: 고난은 믿지 않는다, 그것은 참된 믿음이 아니다"]}, {"title": "야곱과 로마서: 갈등 또는 보완?", "points": ["야고보서: 귀신도 믿으나 떨리라 (야고보서 2:19)", "믿음이 마음에 머물러 있으면 사탄의 기준조차 충족되지 않습니다.", "두 책은 모두 성령의 영감을 받아 서로를 설명하고 서로 모순되지 않습니다."]}, {"title": "행동의 진실: 새로운 삶의 전개", "points": ["야곱의 행위는 공적을 축적하는 것이 아니라 옛 사람을 벗고 새 사람을 입는 것입니다.", "믿음으로 의롭게 되는 것은 행위로 의의 결과를 낳아야 한다.", "새로운 삶의 변화: 가치, 성격이 갱신됩니다."]}, {"title": "복음주의의 위기와 참된 결단", "points": ["죄가 아닌 축복에 대해서만 이야기하는 것은 사람들을 \"구원\" 할 수는 있지만 다시 태어나지는 않을 수 있습니다.", "참된 결단: 한 분의 참된 하나님, 죄인이 됨을 인정하고, 구원을 받고, 새로운 삶을 살기", "에베소서: 행위가 아닌 은혜로, 믿음으로 구원 (에베소서 2: 8-9)"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 하나님의 ________ 이 (가) 이 복음에 나타나고 있기 때문입니다.", "s": "믿음에 의한 의화"}, {"q": "[Scripture Fill in the Blank] ________ 을 (를) 입으로 고백하고 하나님을 믿어 죽은 자들로부터 ________ 을 (를) 만들면 구원을 얻을 수 있습니다.", "s": "마음속으로 믿는 것을 입으로 인정하라"}, {"q": "[성경은 빈칸을 채웁니다] 여러분의 구원은 ________ 와 ________ 에 의해 이루어집니다. 그것은 여러분 자신이 아니라 하느님께 속한 것입니다.", "s": "구원은 은혜로"}, {"q": "인간이 만든 종교는 다리를 만들고 길을 닦아 하나님과 축복을 주고받기를 원하며, 참 하나님이 계시하신 믿음은 ________ 가 먼저 옳아야 한다는 믿음이 더 중요합니다.", "s": "종교 vs 신앙"}, {"q": "믿음으로 의롭게 되는 “믿음” 은 언어적 진술이 아니라 하나님과의 ________ 에 뿌리를 두고 삶의 변화를 가져옵니다.", "s": "참된 신앙의 의미"}, {"q": "바울은 하박국의 책을 인용하여 \"의인은 믿음으로 살리라\" 고 설명하고, 하박국은 여전히 하나님께서 여전히 열악한 환경에 ________ 계시다고 굳게 믿고 있다.", "s": "하박국의 신앙"}, {"q": "야고보가 가로되 네가 하나님은 한 분이신 줄을 믿느냐 잘하는도다 너도 믿고 떠느니라", "s": "참 또는 거짓 신앙"}, {"q": "제임스는 참된 신앙이 ________ 의 변화를 가져올 것이라고 강조한다. “네가 행하지 않은 믿음을 내게 보여라. 내가 행함으로 내 믿음을 네게 보이리라.”", "s": "자신감 및 행동"}, {"q": "진정한 결정에는 우주에 오직 한 분의 참 하나님이 계심을 인식하고, 자신이 ________ 임을 인정하고, 하나님의 준비된 구원을 받아들이는 것이 포함됩니다.", "s": "결정 내용"}, {"q": "이 수업에 따르면, 신앙에 의한 의화에서 “편지” 의 주요 의미는 무엇인가?", "s": "글자의 의미", "o": "A.설교에서 손을 들어 믿음을 보여주세요,B.주 예수님을 입으로 고백하고 마음속으로 하나님을 믿은 그는 예수님을 죽은 자 가운데서 살리시고 생명의 주가 되게 하셨습니다.,C.하나님께서 여러분을 안전하고 풍요롭게 지켜주실 것임을 믿으십시오.,D.하나님께서 나를 있는 그대로 무조건 받아주신다는 것을 믿으십시오."}, {"q": "“의화” 에 대한 로마서와 야곱의 가르침은 어떤 관계가 있는가?", "s": "두 책의 관계", "o": "A.서로 모순, 오직 하나만 신뢰할 수 있음,B.로마서는 믿음으로 의롭다 하심을 말하고, 야고보서는 참된 믿음을 말하고 행위를 이끌어 낼 것이며, 두 사람은 서로 설명합니다.,C.제임스는 믿음으로 바울의 의롭다 하심을 부인한다,D.두 책은 전혀 다른 종류의 구원에 관한 책이다."}, {"q": "이 수업은 진리가 명확하게 전파되지 않을 때 일부 설교가 위기로 이어질 수 있음을 지적한다.", "s": "복음을 분명하게 전하십시오", "o": "A.믿는 자들은 너무 적게 준다.,B.사람들은 자신이 구원받았다고 생각하지만, 사실은 구원받지 못했고, 그들의 삶은 변한 적이 없습니다.,C.교회 성장이 너무 느림,D.신자들은 너무 열정적입니다."}, {"q": "이 수업에서 참된 구원의 어떤 측면이 언급되는가? (복수 선택)", "s": "구원의 의미", "o": "A.우주에는 오직 한 분의 참 하나님이 계시고, 그분에 의해 구원의 길이 결정된다는 것을 인식하십시오.,B.당신은 죄인이며 자신을 구원할 수 없다는 것을 인정하십시오.,C.구원을 위한 하나님의 공급하심을 받음,D.이생에서 진리에 따라 새로운 삶을 사는 것"}, {"q": "다음 중 이 수업에서 비판하는 오해는 무엇인가? (복수 선택)", "s": "오해", "o": "A.예수님의 평화와 안보의 번영 신학을 믿으십시오,B.축복을 기원하는 자공덕의 인위적인 종교적 풍경,C.손을 들어 천국에 가기로 결심하세요. 삶은 변할 필요가 없습니다.,D.무언가 할 수 없다는 낡은 사고방식이 마음에 드는 한"}, {"q": "믿음으로 의롭다 함을 얻는다는 것은 주님을 믿은 후에 아무 것도 할 필요가 없다는 것을 의미합니다. 당신이 믿는 한, 당신은 천국에 갈 수 있습니다.", "s": "믿음에 의한 의화"}, {"q": "야고보와 로마서 모두 성신의 영감을 받았으므로 칭의에 대한 가르침은 서로 모순되지 않습니다.", "s": "성경적 모순"}, {"q": "참된 신앙은 의로운 행위의 현상을 실천하면서 삶을 변화시켜야 합니다.", "s": "자신감 및 행동"}, {"q": "이 수업에서 “인간이 만든 종교” 와 “신성하게 계시된 신앙” 의 근본적인 차이점을 간략하게 설명한다.", "s": "종교와 신앙"}, {"q": "왜 로마서에 있는 신앙에 의한 칭의와 야곱서에 있는 행위에 의한 칭의 사이에 모순이 없는가?", "s": "두 권의 책 조화"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773055009215','基要真理','第十二课 成为新造的人','在基督里就是新造的人，旧事已过，一切都变成新的了。本课讲生命改变的真义、成长的过程，以及如何脱离老我的捆绑。愿你的生命天天被主更新改变。向着标竿直跑，得神的奖赏。','[{"type": "verse", "q": "【经文填空】若有人在________，他就是新造的人，________，都变成新的了。", "o": "《哥林多后书》5章17节", "s": "新造的人", "a": "基督里|旧事已过"}, {"type": "verse", "q": "【经文填空】不要效法这个世界，只要________而变化，叫你们察验何为神的善良、纯全、可喜悦的旨意。", "o": "《罗马书》12章2节", "s": "心意更新", "a": "心意更新"}, {"type": "verse", "q": "【经文填空】圣灵所结的果子，就是________、喜乐、和平、忍耐、恩慈、良善、信实、________、节制。", "o": "《加拉太书》5章22节", "s": "圣灵的果子", "a": "仁爱|温柔"}, {"type": "fill", "q": "主耶稣照着我们的________接纳我们，但我们不要带着本相离开，要在福音里被真理改变。", "o": "", "s": "本相与改变", "a": "本相"}, {"type": "fill", "q": "“旧事已过”指过去主导我们生命的________都要过去，不再活在老我伤害自己也伤害别人的生命里。", "o": "", "s": "旧事已过", "a": "错误价值观"}, {"type": "fill", "q": "成为新造的人是一个________，像生命成长不能揠苗助长，家人应能看见我们渐进的改变。", "o": "", "s": "成长的过程", "a": "过程"}, {"type": "fill", "q": "腓立比书说要“恐惧战兢，做成你们得救的________”，基督徒天天要选择顺服圣灵。", "o": "", "s": "得救的功夫", "a": "功夫"}, {"type": "fill", "q": "主耶稣应许求父另赐一位________，就是真理的圣灵，永远与我们同在。", "o": "", "s": "圣灵内住", "a": "保惠师"}, {"type": "fill", "q": "神给人________，人有责任正确地使用它，选择听神的话、顺服圣灵。", "o": "", "s": "人的责任", "a": "自由意志"}, {"type": "single", "q": "“在基督里”是什么意思？", "o": "A.在教会里聚会,B.在耶稣基督所完成的救恩里面,C.心里相信耶稣,D.在基督徒群体中", "s": "在基督里", "a": "B"}, {"type": "single", "q": "本课指出，“旧事已过”主要指什么？", "o": "A.过去犯的罪都被赦免,B.过去主导生命的错误价值观和老我生命被拿去,C.过去的失败经历被遗忘,D.过去的人际关系一笔勾销", "s": "旧事已过", "a": "B"}, {"type": "single", "q": "关于“做成得救的功夫”与“得救本乎恩因着信”，本课的立场是？", "o": "A.两者冲突，只能取其一,B.得救全靠自己努力,C.得救是神的恩典，人有责任运用意志选择顺服神，两者不冲突,D.做成得救的功夫是得救的条件", "s": "恩典与责任", "a": "C"}, {"type": "multiple", "q": "圣灵在信徒生命中的工作包括哪些？（多选）", "o": "A.催逼、感动、禁止,B.鼓励、安慰,C.带领信徒活在神的光中,D.强制人顺服，否则就处罚", "s": "圣灵的工作", "a": "A|B|C"}, {"type": "multiple", "q": "以下哪些是“新造的人”生命改变的表现？（多选）", "o": "A.结出圣灵的果子：仁爱、喜乐、和平等,B.行公义、好怜悯、存谦卑的心与神同行,C.老我个性被改变，不再伤害自己和别人,D.信耶稣后凡事顺利发财", "s": "新造的表现", "a": "A|B|C"}, {"type": "judge", "q": "照着本相来到主面前，就等于可以一直活在本来的样子里，不必改变。", "o": "", "s": "本相与改变", "a": "错"}, {"type": "judge", "q": "成为新造的人是一触可及的，信耶稣第二天就应完全变成另一个人。", "o": "", "s": "成长过程", "a": "错"}, {"type": "judge", "q": "神永不放弃属他的人，失败软弱时回转归向神仍蒙接纳。", "o": "", "s": "神不放弃", "a": "对"}, {"type": "essay", "q": "请解释“旧事已过，都变成新的了”的真正含义。", "o": "", "s": "旧事已过", "a": "不只是过去的罪得赦免、错误一笔勾销，更是指过去主导生命的错误价值观、老我生命被神拿去；靠着圣灵内住，结出仁爱、喜乐、和平等果子，活出公义、良善、诚实的新生命。这是神的恩典，人也要负责任天天选择顺服。"}, {"type": "essay", "q": "为什么说成为新造的人是一个过程？基督徒在这过程中当如何自处？", "o": "", "s": "成长过程", "a": "生命成长有其过程，如大卫穿扫罗战袍不相称、揠苗助长反致死。基督徒当持定方向，运用自由意志天天选择顺服圣灵；有成长时感恩不骄傲，失败时不气馁、回转归向神，因为神永不放弃属他的人。"}]','https://youtu.be/eVvgslVgFN8
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134zFjm','quiz','[{"title": "照本相来，不要带本相走", "points": ["主照我们的本相接纳我们：残破不堪也接纳", "有人来到救恩里却不被救恩改变，仍活在老样子里", "礼拜天像打强心针，问题在于没有被真理改变"]}, {"title": "旧事已过的真义", "points": ["不是过去捅的篓子一笔勾销而已", "是主导生命的错误价值观过去，不再活在老我里", "圣灵九果、光明之子的生命特质活出来"]}, {"title": "新造是一个过程", "points": ["大卫穿扫罗战袍：不相称，做不了事", "揠苗助长：生命成长有过程，不是一蹴而就", "家人天天看得见：老我渐被控制，新生命散发出来"]}, {"title": "人的责任：恐惧战兢做成得救的功夫", "points": ["腓2:12 不是靠自己赚救恩，而是运用意志选择顺服", "神给人自由意志：正确使用是爱的回应", "体贴圣灵乃是生命平安（罗8:6）"]}, {"title": "圣灵内住的带领", "points": ["保惠师真理的圣灵永远与我们同在（约14:16-17）", "以马内利：神透过圣灵天天做更新的工作", "圣灵感动就停就回应，这是基督徒的日常"]}, {"title": "初熟的果子：今生先尝天堂美善", "points": ["圣灵如初熟的果子，今生先尝到好处", "天堂最大的美善是与良善的神永远同在", "失败不气馁：回转吧，神从不放弃"]}]','','12','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 12 Becoming a New Creation", "content": "In Christ is the new creation, the old things have passed away, and all things have become new. This lesson is about the true meaning of life change, the process of growing up, and how to break free from the bondage of the old self. May your life be renewed and changed by the Lord every day. Run straight to the pole and receive God''s reward.", "instructions": "", "guide": [{"title": "When you take a photo, don''t take it with you", "points": ["The Lord accepts us as we are: mutilated and embraced", "Some people come to salvation but are not changed by salvation and still live in the same way.", "It''s like a strong needle on Sunday, the problem is that it hasn''t been changed by the truth"]}, {"title": "The truth that the old things have passed", "points": ["It''s not just that the basket that was stabbed in the past was written off in one stroke.", "is the false values that dominate life. In the past, I no longer live in my old self.", "The life traits of the nine fruits of the Holy Spirit and the Son of Light come to life"]}, {"title": "New creation is a process", "points": ["David wears Saul''s robe: disproportionate, unable to do anything", "Miao nurtures: Life grows in a process, not overnight", "Family can see it every day: old me is gradually controlled, new life is emanating"]}, {"title": "Human responsibility: Fear and trembling are the kung fu of salvation", "points": ["Phil 2:12 Not to earn salvation by oneself, but to use one''s will to choose obedience", "God Gives Free Will: Using Rightly Is a Response to Love", "To be considerate of the Holy Spirit is to live in peace (Romans 8: 6)"]}, {"title": "Led by the indwelling of the Holy Spirit", "points": ["Comforter The Holy Spirit of truth is always with us (John 14:16 -17)", "Immanuel: God does the work of renewal through the Holy Spirit every day", "When the Holy Spirit moves, it stops and responds. This is the daily life of Christians."]}, {"title": "First fruits: first taste of heaven in this life", "points": ["The Holy Spirit is like the first ripened fruit, tasting the benefits in this life first", "The greatest good in heaven is always with the good God.", "Failure does not discourage: Turn around, God never gives up"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] If someone is in ________, he is a new creation, and ________ has become new.", "s": "Newly Created Man"}, {"q": "[Scripture Fill in the Blank] Do not imitate the world, but change it by ________, so that you may examine what is the good, pure, and pleasing will of God.", "s": "Mind update"}, {"q": "[Scripture fills in the blank] The fruit of the Holy Spirit is ________, joy, peace, patience, kindness, goodness, faithfulness, ________, temperance.", "s": "<bpt i=\"1\" type=\"bold\">{}</bpt>The Fruit of the Spirit<ept i=\"1\">{}</ept>"}, {"q": "The Lord Jesus accepts us according to our ________, but let us not depart with the truth, but be changed by the truth in the gospel.", "s": "Factors and Changes"}, {"q": "\"Old things have passed\" means that the ________ who dominated our lives in the past will pass away, and no longer live in the life where I hurt myself and others.", "s": "Old things are over"}, {"q": "Becoming a new creation is a ________, like the growth of life cannot be fostered by seedlings, and our families should be able to see our gradual change.", "s": "Growth process"}, {"q": "Philippians says to “tremble with fear, and do the ________ of your salvation,” and Christians choose to obey the Holy Ghost every day.", "s": "Saved Kung Fu"}, {"q": "The Lord Jesus promises to ask the Father for another ________, the Spirit of truth, to be with us forever.", "s": "The indwelling of the Holy Spirit"}, {"q": "God has given people ________, and it is man''s responsibility to use it correctly, choose to listen to God''s words, and obey the Holy Spirit.", "s": "Human Responsibility"}, {"q": "What does “in Christ” mean?", "s": "In Christ", "o": "A.Gathering in the Church,B.In the completed salvation of Jesus Christ,C.Believe in Jesus in your heart,D.In the Christian community"}, {"q": "In this lesson, what is the main meaning of “old things are over”?", "s": "Old things are over", "o": "A.Sins committed in the past are forgiven,B.The false values that used to dominate life and my old life were taken away,C.Past failures forgotten,D.Past relationships written off"}, {"q": "What is the position of this lesson on \"doing the work of salvation\" and \"salvation is by grace through faith\"?", "s": "Grace and Responsibility", "o": "A.Conflict between the two, you can only choose one,B.To be saved is to do it all on your own.,C.Salvation is by the grace of God. It is the duty of man to use his will to choose to obey God. The two do not conflict.,D.Achieving salvation is a condition of salvation"}, {"q": "What does the work of the Holy Ghost in the lives of believers include? (Multiple choice)", "s": "The Work of the Holy Spirit", "o": "A.Urging, touching, forbidding,B.Encouragement, Reassurance,C.Leading believers to live in the light of God,D.Force people to obey, or you will be punished"}, {"q": "Which of the following are manifestations of life-changing “newly created man”? (Multiple choice)", "s": "New Performance", "o": "A.Producing the Fruit of the Holy Spirit: Love, Joy, and Equality,B.Walk with God in righteousness, compassion, and humility,C.My personality has changed and I no longer hurt myself and others,D.Become rich after believing in Jesus"}, {"q": "When you come to the Lord according to the true image, you can always live in the way you are, without having to change.", "s": "Factors and Changes"}, {"q": "Being a new creation is within reach, and believing in Jesus the next day should be completely transformed into another person.", "s": "Growth process"}, {"q": "God never gives up on those who belong to him. When he fails and is weak, he returns to God and is still accepted.", "s": "God does not give up"}, {"q": "Please explain the true meaning of “old things are gone and become new”.", "s": "Old things are over"}, {"q": "Why is it a process to become a new creation? How should Christians approach this process?", "s": "Growth process"}]}, "ja": {"title": "レッスン12新しい創造物になる", "content": "キリストには新しい創造があり、古いものは過ぎ去り、すべてが新しいものになりました。このレッスンでは、人生の変化の真の意味、成長の過程、古い自己の束縛から解放する方法について説明します。あなたの人生が毎日主によって新たにされ，変えられますように。ポールに直行して、神の報酬を受け取りましょう。", "instructions": "", "guide": [{"title": "写真を撮るときは、一緒に撮らないでください", "points": ["主はわたしたちをありのままに受け入れてくださる：切断され，抱きしめられる", "救いに来ても救いによって変えられず，それでも同じように生きる人もいます。", "日曜日には強力な針のようなものですが、問題は真実によって変更されていないことです"]}, {"title": "古いものが過ぎ去ったという真実", "points": ["過去に刺されたバスケットが一気に消えただけではない。", "は、人生を支配する偽りの価値観です。過去には、私はもはや古い自分の中に住んでいません。", "聖霊と光の子の九つの実のいのちの特質が生まれる"]}, {"title": "新しい作成はプロセスです", "points": ["デビッドはソールのローブを着ています：不釣り合いで、何もできません", "ミャオが育む：人生は一夜にして成長するのではなく、プロセスの中で成長する", "家族は毎日それを見ることができます：古い私は徐々にコントロールされ、新しい人生が広がっています"]}, {"title": "人間の責任：恐怖と震えは救いのカンフーです", "points": ["フィリピ2 ： 12自分で救いを得るためではなく、従順を選ぶために自分の意志を使うため", "神は自由意志を与えます：正しく使うことは愛への応答です", "聖霊に配慮することは，平安のうちに生きることです（ローマ8 ： 6 ）。"]}, {"title": "聖霊の内在に導かれる", "points": ["慰める者真理の聖霊はいつもわたしたちと共におられます（ヨハネ14 ： 16 － 17 ）", "インマヌエル：神は毎日，聖霊を通して更新の働きをしておられます", "聖霊が動くと、止まって反応します。これがクリスチャンの日常生活です。"]}, {"title": "ファーストフルーツ：この人生で初めての天国の味", "points": ["聖霊は最初に熟した果実のようなものであり、この人生の恩恵を最初に味わいます", "天で最も偉大な善は、常に良い神と共にあります。", "失敗は思いとどまらない：振り返れ、神は決してあきらめない"]}], "quizzes": [{"q": "〔聖句の穴埋め〕誰かが________にいる場合、彼は新しい創造物であり、________は新しいものになりました。", "s": "新しく創造された男"}, {"q": "〔聖句の穴埋め〕この世を模倣するのではなく， ________までに変えてください。そうすれば，神の良い，完全な，喜ばしい御心とは何かを調べることができます。", "s": "マインドアップデート"}, {"q": "〔聖文は空白を埋めます〕聖霊の実は， ________ ，喜び，平安，忍耐，親切，善良さ，忠実さ， ________ ，節制です。", "s": "聖霊の実"}, {"q": "主イエスはわたしたちの________に従ってわたしたちを受け入れておられますが，真理をもって去るのではなく，福音の真理によって変えられましょう。", "s": "要因と変化"}, {"q": "「古いものは過ぎ去った」とは、過去に私たちの生活を支配していた________が過ぎ去り、私が自分自身や他の人を傷つけた生活はもはや生きていないことを意味します。", "s": "古いものは終わった"}, {"q": "新しい創造物になることは________であり、生命の成長は苗木によって育まれることはできず、私たちの家族は私たちの徐々に変化を見ることができるはずです。", "s": "成長プロセス"}, {"q": "ピリピ人は「恐れに震え，あなたの救いの________を行ないなさい」と言い，クリスチャンは毎日聖霊に従うことを選びます。", "s": "救われたカンフー"}, {"q": "主イエスは，永遠にわたしたちと共におられるもう一つの________ ，すなわち真理の御霊を父に求めると約束されています。", "s": "聖霊の住まい"}, {"q": "神は人々に________を与えておられ，それを正しく使い，神の言葉に耳を傾け，聖霊に従うことを選ぶのは人間の責任です。", "s": "人間の責任"}, {"q": "「キリストにあって」とはどういう意味でしょうか。", "s": "キリストにあって", "o": "A.教会での集まり,B.イエス・キリストの完全な救いにおいて,C.心の中でイエスを信じる,D.キリスト教徒のコミュニティで"}, {"q": "このレッスンでは，「古いものは終わった」の主な意味は何でしょうか。", "s": "古いものは終わった", "o": "A.過去に犯した罪は赦される,B.人生を支配していた誤った価値観と私の昔の人生は取り除かれました,C.過去の失敗を忘れた,D.過去の関係が償却されました"}, {"q": "「救いの業を行なう」と「救いは信仰による恵みによって行なわれる」に関するこの課の立場はどのようなものですか。", "s": "恵みと責任", "o": "A.2つの間の競合、あなたは1つだけを選択することができます,B.救われるということは、すべて自分で行うことです。,C.救いは神の恵みによるものです。神に従うことを選択するために彼の意志を使用するのは人間の義務です。両者は矛盾しません。,D.救いを得ることは救いの条件です"}, {"q": "信者の生活における聖霊の業には，どのようなものが含まれますか。（複数選択可）", "s": "聖霊の働き", "o": "A.促す、触れる、禁止する,B.励まし、安心,C.神の光の中で生きるように信者を導く,D.人々に服従を強いるか、さもなければあなたは罰せられます"}, {"q": "次のうち、人生を変える「新しく創造された人」の現れはどれですか？ （複数選択可）", "s": "新しいパフォーマンス", "o": "A.聖霊の実を結ぶ：愛，喜び，平等,B.義と憐れみと謙遜さをもって神とともに歩む,C.性格が変わり、もはや自分や他の人を傷つけることはない,D.イエスを信じて豊かになる"}, {"q": "真の姿に従って主のもとに来ると，変わることなく，いつでも自分のように生きることができます。", "s": "要因と変化"}, {"q": "新しい創造物であることは手の届くところにあり、翌日にイエスを信じることは完全に別の人に変わるべきです。", "s": "成長プロセス"}, {"q": "神はご自分に属する者を決してあきらめません。彼が失敗して弱いとき、彼は神に戻り、まだ受け入れられています。", "s": "神はあきらめない"}, {"q": "「古いものはなくなり、新しいものになる」の本当の意味を説明してください。", "s": "古いものは終わった"}, {"q": "なぜ新しい創造物になるためのプロセスなのでしょうか？クリスチャンはこのプロセスにどのように取り組むべきでしょうか。", "s": "成長プロセス"}]}, "ko": {"title": "제 12과 새로운 창조물이 됨", "content": "그리스도 안에는 새로운 피조물이 있고, 옛 것은 지나갔으며, 모든 것이 새로워졌습니다. 이 수업은 삶의 변화의 진정한 의미, 성장하는 과정, 옛 자아의 속박에서 벗어나는 방법에 관한 것입니다. 여러분의 삶이 매일 주님에 의해 새롭게 되고 변화되기를 바랍니다. 곧장 극으로 달려가 하나님의 보상을 받으세요.", "instructions": "", "guide": [{"title": "사진을 찍을 때는 사진과 함께 찍지 마세요.", "points": ["주님은 우리를 있는 그대로 받아주십니다: 훼손되고 포옹됨", "어떤 사람들은 구원에 이르지만 구원에 의해 변화되지 않고 여전히 같은 방식으로 살고 있습니다.", "일요일의 강한 바늘과 같아서, 문제는 진실에 의해 변경되지 않았다는 것입니다."]}, {"title": "옛것이 지나갔다는 진리", "points": ["과거에 찔렸던 바구니가 한 방에 없어진 것도 아니다.", "인생을 지배하는 그릇된 가치들이다. 과거에 나는 더 이상 예전의 나 자신 속에 살지 않는다.", "성령과 빛의 아홉 열매의 생명 특성이 살아난다"]}, {"title": "새 생성은 프로세스입니다", "points": ["다윗은 사울의 옷을 입는다: 불균형, 아무것도 할 수 없음", "먀오족 양육: 삶은 하룻밤이 아닌 과정 속에서 성장한다.", "가족은 매일 그것을 볼 수 있습니다: 오래된 나는 점차적으로 통제되고, 새로운 삶이 뿜어져 나옵니다."]}, {"title": "인간의 책임: 두려움과 떨림은 구원의 쿵푸입니다.", "points": ["PHIL 2:12 스스로 구원을 얻으려 함이 아니요 오직 자기의 뜻대로 순종을 택하려 함이니라", "하느님께서는 자유 의지를 주십니다: 올바르게 사용하는 것은 사랑에 대한 반응입니다", "성령님을 배려하는 것은 평화롭게 사는 것입니다 (로마서 8: 6)."]}, {"title": "성령의 내주하심에 의해 인도됨", "points": ["위로자 진리의 성령께서 항상 우리와 함께 계십니다 (요한복음 14:16 ~ 17)", "임마누엘: 하나님은 매일 성령을 통해 갱신의 일을 하십니다", "성령이 움직이면 멈추고 응답합니다. 이것이 그리스도인의 일상 생활입니다."]}, {"title": "첫 열매: 생애 첫 천국 맛보기", "points": ["성령은 처음 익은 열매와 같아서 이생의 유익을 먼저 맛보신다.", "천국에서 가장 큰 선은 항상 선하신 하나님과 함께하는 것입니다.", "실패해도 낙담하지 않습니다. 돌아서세요. 하나님은 결코 포기하지 않으십니다."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] ________ 에 속한 사람은 새로운 피조물이며, ________ 은 (는) 새로워졌습니다.", "s": "새로 창조된 인간"}, {"q": "[Scripture Fill in the Blank] 세상을 모방하지 말고 ________ 로 바꾸어 하나님의 선하시고 깨끗하시고 기뻐하시는 뜻이 무엇인지 살펴본다.", "s": "마인드 업데이트"}, {"q": "[성경은 빈칸을 채웁니다] 성령의 열매는 ________, 기쁨, 평화, 인내, 친절, 선, 신실, ________, 절제입니다.", "s": "성령의 열매"}, {"q": "주 예수께서는 우리의 ________ 에 따라 우리를 받아들이시지만, 진리를 떠나지 말고 복음 안에서 진리에 의해 변화되게 하십시오.", "s": "요인 및 변화"}, {"q": "\"오래된 것들이 지나갔다\" 는 것은 과거에 우리의 삶을 지배했던 ________ 이 (가) 사라지고, 더 이상 나 자신과 다른 사람들을 해치는 삶에서 살지 않는다는 것을 의미합니다.", "s": "오래된 것은 끝났습니다"}, {"q": "새로운 피조물이 되는 것은 생명의 성장이 묘목으로 육성될 수 없는 것과 마찬가지로 ________ 이며, 우리 가족은 점진적인 변화를 볼 수 있어야 합니다.", "s": "성장 과정"}, {"q": "빌립보서는 “두려워 떨며 구원의 ________ 을 (를) 행하라” 고 말하며, 그리스도인들은 매일 성신께 순종하기로 선택합니다.", "s": "저장된 쿵푸"}, {"q": "주 예수께서는 또 다른 ________, 즉 진리의 영이 우리와 영원히 함께하시도록 아버지께 간구하겠다고 약속하십니다.", "s": "성령의 거하심"}, {"q": "하느님께서는 사람들에게 ________ 을 주셨고, 올바르게 사용하고, 하느님의 말씀을 듣고, 성령께 순종하는 것은 인간의 책임입니다.", "s": "인간의 책임"}, {"q": "“그리스도 안에서” 는 무엇을 의미하는가?", "s": "그리스도 안에서", "o": "A.교회에서 모이기,B.예수 그리스도의 완전한 구원 안에서,C.마음속으로 예수님을 믿으세요,D.기독교 공동체에서"}, {"q": "이 수업에서 “낡은 것은 끝났다” 의 주요 의미는 무엇인가?", "s": "오래된 것은 끝났습니다", "o": "A.과거에 저지른 죄는 용서받습니다,B.삶과 내 옛 삶을 지배하던 그릇된 가치들을 빼앗겼습니다.,C.잊혀진 과거의 실패,D.과거 관계가 삭제됨"}, {"q": "\"구원의 일을 하는 것\" 과 \"구원은 믿음으로 말미암아 은혜로 받는 것\" 에 대한 이 교훈의 입장은 무엇인가?", "s": "은혜와 책임", "o": "A.둘 사이의 충돌, 하나만 선택할 수 있습니다,B.구원받는다는 것은 모든 것을 스스로 행하는 것입니다.,C.구원은 하나님의 은혜로 말미암은 것입니다. 하나님의 뜻에 따라 순종하는 것이 인간의 의무입니다. 이 둘은 서로 상충되지 않습니다.,D.구원을 얻는 것은 구원의 조건입니다."}, {"q": "신자들의 삶에서 성신의 사업에는 무엇이 포함되는가? (복수 선택)", "s": "성령의 역사", "o": "A.촉구, 만지기, 금지,B.격려, 안심,C.신자들이 하나님의 빛 가운데 살도록 이끄는 것,D.사람들에게 복종을 강요하지 않으면 처벌을 받게 됩니다."}, {"q": "다음 중 삶을 변화시키는 “새로 창조된 인간” 의 표현은 무엇인가? (복수 선택)", "s": "새로운 실적", "o": "A.성령의 열매를 맺음: 사랑, 기쁨, 평등,B.의와 긍휼과 겸손으로 하나님과 동행하십시오.,C.내 성격이 바뀌었고 더 이상 나 자신과 다른 사람들을 해치지 않는다.,D.예수님을 믿은 후 부자가 되세요"}, {"q": "참된 모습을 따라 주님께 나아갈 때, 여러분은 변화할 필요 없이 언제나 있는 그대로의 모습으로 살아갈 수 있습니다.", "s": "요인 및 변화"}, {"q": "새로운 피조물이 되는 것은 손이 닿는 곳에 있으며, 다음 날 예수님을 믿는 것은 완전히 다른 사람으로 변화되어야 합니다.", "s": "성장 과정"}, {"q": "하나님은 자기에게 속한 자들을 결코 포기하지 않으십니다. 그가 실패하고 약해질 때, 그는 하나님께로 돌아가고 여전히 받아들여집니다.", "s": "하나님은 포기하지 않으신다"}, {"q": "“옛 것이 없어지고 새로워지다” 의 진정한 의미를 설명해 주십시오.", "s": "오래된 것은 끝났습니다"}, {"q": "왜 새로운 창조물이 되는 과정인가? 그리스도인들은 이 과정에 어떻게 접근해야 하는가?", "s": "성장 과정"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773055291998','基要真理','第十三课 分别为圣 迈向得胜','分别为圣是归属神、按真理而活。得救是起点，得胜是必然的结果。本课讲成圣生活的操练，以及靠主得胜的秘诀。愿你活出圣洁，在世上为主发光。成为圣洁，合乎主用。','[{"type": "verse", "q": "【经文填空】故此你们要________。务要抵挡魔鬼，魔鬼就必________逃跑了。", "o": "《雅各书》4章7节", "s": "抵挡魔鬼", "a": "顺服神|离开你们"}, {"type": "verse", "q": "【经文填空】就要脱去你们从前行为上的________，这旧人是因私欲的迷惑渐渐________的。", "o": "《以弗所书》4章22节", "s": "脱去旧人", "a": "旧人|变坏"}, {"type": "verse", "q": "【经文填空】人若________全世界，赔上自己的________，有什么益处呢？", "o": "《马太福音》16章26节", "s": "赚得全世界", "a": "赚得|生命"}, {"type": "fill", "q": "分别为圣的意思是从这个世界________出来，归属于神，按圣经真理而活。", "o": "", "s": "分别为圣", "a": "分别"}, {"type": "fill", "q": "圣洁是神的________与属性，活在有罪世代中的人没有一个敢说自己全然圣洁。", "o": "", "s": "圣洁的属性", "a": "本质"}, {"type": "fill", "q": "得救与得胜不能切成两段，得救是一个________，从得救那天起就学习过得胜的生活。", "o": "", "s": "得救与得胜", "a": "开始"}, {"type": "fill", "q": "得胜胜的是老我、世界的引诱和________的诱惑。", "o": "", "s": "得胜的对象", "a": "撒旦"}, {"type": "fill", "q": "主耶稣在旷野四十天受试探时，用________的话回应抵挡撒旦。", "o": "", "s": "抵挡试探", "a": "神"}, {"type": "fill", "q": "圣灵充满最重要的意义，是我们这人被圣灵完全________，按圣经真理被提醒而愿意改变。", "o": "", "s": "圣灵充满", "a": "掌控"}, {"type": "single", "q": "本课对“分别为圣”的定义是？", "o": "A.跑到深山修行，远离世界,B.从世界分别出来归属于神，按圣经真理而活并作见证,C.自认为全然圣洁、高人一等,D.只在礼拜天去教会做礼拜", "s": "分别为圣", "a": "B"}, {"type": "single", "q": "关于“只得救不得胜”的说法，本课的立场是？", "o": "A.可以，得胜太辛苦是可选项,B.不可能，得胜是得救后必然的结果，否则可能根本没有得救,C.得胜只属于少数属灵伟人,D.得救与得胜毫无关系", "s": "得胜非选项", "a": "B"}, {"type": "single", "q": "本课说基督徒作“光”和“盐”的含义是？", "o": "A.光是行神迹，盐是调味,B.光照亮黑暗使人看见真理，盐发挥防腐作用拦阻罪恶蔓延,C.光和盐都是指教会建筑,D.光指知识，盐指财富", "s": "光和盐", "a": "B"}, {"type": "multiple", "q": "神帮助我们得胜所赐的资源有哪些？（多选）", "o": "A.一本圣经，载明行事为人的标准,B.圣灵内住，不断提醒更新我们,C.人运用自由意志选择顺服,D.特殊的属灵恩赐外显", "s": "得胜的资源", "a": "A|B|C"}, {"type": "multiple", "q": "以下哪些是“分别为圣”在生活中的体现？（多选）", "o": "A.在情欲之风盛行的世代活出守约的婚姻之爱,B.不贪财，有衣有食就当知足,C.活出恒久忍耐、又有恩慈、不嫉妒不自夸的爱,D.与世界同流合污以便传福音", "s": "分别为圣的体现", "a": "A|B|C"}, {"type": "judge", "q": "分别为圣就是自认全然圣洁、高人一等，轻看罪人。", "o": "", "s": "分别为圣", "a": "错"}, {"type": "judge", "q": "得胜的生活是神赐福的必经之路，靠着主可以战胜老我、世界和撒旦。", "o": "", "s": "得胜生活", "a": "对"}, {"type": "judge", "q": "圣灵充满主要是指说方言、说预言、赶鬼等外显恩赐的彰显。", "o": "", "s": "圣灵充满", "a": "错"}, {"type": "essay", "q": "为什么说基督徒“只得救不得胜”是不可能的？", "o": "", "s": "得胜非选项", "a": "得救是开始不是终点。从决志称耶稣为主那天起，他就接管生命成为生命的主，必带领人朝得胜迈进。若终其一生从未活出得胜的生命，可能根本没有得救。得胜不是可选项，而是得救后必然的结果，也是神赐福的必经之路。"}, {"type": "essay", "q": "请说明得胜的关键及其实践方法。", "o": "", "s": "得胜的关键", "a": "关键是雅各书4章7至8节：亲近神，神就亲近你们；抵挡魔鬼，魔鬼就必逃跑。如主耶稣在旷野用神的话抵挡试探。实践上：以圣经为行事为人标准，敏锐于圣灵的提醒（如快快地听、慢慢地说、慢慢地动怒），运用自由意志选择顺服，天天脱下旧人穿上新人，在与人互动中被改变。"}]','https://youtu.be/TbdnoIvC0lA
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134nAH1','quiz','[{"title": "分别为圣的真义", "points": ["不是全然圣洁，而是从世界分别出来归属于神", "不按世界价值观活，按圣经真理活", "基督教是入世的信仰，不是跑到山里修行"]}, {"title": "以色列的鉴戒", "points": ["神拣选以色列作列邦中的见证", "先知指责：你们认识神，怎么活得跟列邦一样", "同流合污是以色列亡国的关键"]}, {"title": "作光作盐的见证", "points": ["光照在黑暗里：给摸索的世界带来真光", "盐防腐：阻止世代道德继续下滑", "活在人群中活出不一样，就是见证"]}, {"title": "生活中的分别为圣", "points": ["婚姻：守约的盟约之爱（林前13章）", "金钱：不贪财，有衣有食就知足（提前6:8）", "先求神的国和神的义（太6:33）"]}, {"title": "得救与得胜不可分割", "points": ["得胜不是选项，是得救的必然结果", "只得救不得胜？可能根本没有得救", "神既不爱惜自己的儿子，岂不把万物白白赐给我们（罗8:32）"]}, {"title": "得胜的关键：亲近神、抵挡魔鬼", "points": ["雅各书：亲近神，抵挡魔鬼，魔鬼就逃跑（雅4:7-8）", "像主在旷野用神的话抵挡试探", "圣经给原则：贪财是万恶之根（提前6:10）"]}, {"title": "圣灵充满的真义", "points": ["不是外显恩赐，而是被圣灵完全掌控", "圣灵按真理提醒，我们选择顺服", "雅各书：快快地听，慢慢地说，慢慢地动怒（雅1:19）"]}]','','13','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 13 Sacred Steps to Victory", "content": "To be holy is to belong to God and live according to the truth. Salvation is the starting point, and victory is the inevitable result. This lesson is about the practice of living a life of sanctification and the secret of victory through the Lord. May you live holy and shine for the Lord in the world. To be holy and to serve the Lord.", "instructions": "", "guide": [{"title": "The Truths That Are Separately Sacred", "points": ["Not completely holy, but separate from the world and belong to God", "Living not according to world values, living according to biblical truths", "Christianity is a belief that enters the world, not a practice in the mountains."]}, {"title": "Lessons from Israel", "points": ["God chose Israel as a witness among the nations", "Prophet''s accusation: How do you live like the nations when you know God?", "Convergence is the key to Israel''s downfall"]}, {"title": "Witness the salt of light", "points": ["Light in the Dark: Bringing True Light to the World of Groping", "Salt preservation: stopping the continuing decline of generational morality", "To live differently in a crowd is to witness"]}, {"title": "The difference in life is holy", "points": ["Marriage: the covenant of covenant love (1 Corinthians 13)", "Money: not greedy, content with food and clothing (1 Timothy 6: 8)", "Seek first the kingdom of God and the righteousness of God (Matthew 6:33)"]}, {"title": "Salvation and victory are inseparable", "points": ["Victory is not an option, it is the inevitable result of salvation", "Unsurvivable? Probably not saved at all", "Since God does not spare His own Son, He will not give us all things in vain (Romans 8:32)"]}, {"title": "The Key to Victory: Getting Close to God and Resisting the Devil", "points": ["James: Draw near to God and resist the devil, and he will flee (James 4: 7-8)", "Like the Lord resisting temptation with the word of God in the wilderness", "Biblical Giving Principle: Greed for Money is the Root of All Evil (1 Timothy 6:10)"]}, {"title": "The Spirit-filled Truth", "points": ["Not as an outward gift, but under the complete control of the Holy Spirit", "The Holy Spirit reminds us according to the truth that we choose obedience", "James: Listen quickly, speak slowly, be angry slowly (James 1:19)"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] Therefore, you want ________. Be sure to resist the devil, and the devil will ________ escape.", "s": "Resist the Devil"}, {"q": "[Scripture Fill in the Blank] You will remove the ________ from your previous behavior. This old man is gradually ________ because of the confusion of selfish desires.", "s": "Get rid of old people"}, {"q": "[Scripture Fill in the Blank] If people ________ all over the world lose their ________, what is the benefit?", "s": "Earn Worldwide"}, {"q": "To be sanctified means to come out of this world ________, to belong to God, and to live according to biblical truth.", "s": "<bpt i=\"1\" type=\"bold\">{}</bpt>CONSECRATION<ept i=\"1\">{}</ept>"}, {"q": "Holiness is the ________ and attribute of God. No one living in the guilty age dares to claim to be completely holy.", "s": "Sacred Attributes"}, {"q": "Salvation and victory can not be cut into two, salvation is a ________, from the day of salvation to learn to live a victorious life.", "s": "Salvation and Victory"}, {"q": "The victory is the old self, the temptation of the world and the temptation of ________.", "s": "Who wins"}, {"q": "When the Lord Jesus was tempted for forty days in the wilderness, He responded with ________ words to resist Satan.", "s": "Resist Temptation"}, {"q": "The most important significance of the Holy Spirit is that we are completely ________ by the Holy Spirit and are reminded according to biblical truth and are willing to change.", "s": "The filling of the Holy Spirit"}, {"q": "What is the definition of “sanctified” in this lesson?", "s": "<bpt i=\"1\" type=\"bold\">{}</bpt>CONSECRATION<ept i=\"1\">{}</ept>", "o": "A.Run to the mountains to practice and stay away from the world,B.Separated from the world and belonging to God, living and witnessing according to biblical truth,C.Self-identified as completely holy and superior,D.Attend church only on Sundays"}, {"q": "What is the position of this lesson on the statement “there is no victory but salvation”?", "s": "Victory is not an option", "o": "A.Yes, winning too hard is optional,B.Impossible, victory is the inevitable result of being saved, otherwise there may be no salvation at all,C.Victory belongs only to a few spiritual giants,D.Salvation has nothing to do with victory"}, {"q": "What does this lesson say about Christians as “light” and “salt”?", "s": "Light and Salt", "o": "A.Just do miracles, salt is seasoning,B.Light illuminates the darkness so that people can see the truth. Salt acts as an antiseptic to stop the spread of evil.,C.Light and salt both refer to church buildings,D.Light refers to knowledge, salt refers to wealth"}, {"q": "What are some of the resources God gives us to help us overcome? (Multiple choice)", "s": "Winning Resources", "o": "A.A Bible that sets out the standards for acting as a person,B.The Holy Spirit dwells within us, constantly reminding us to update,C.People use their free will to choose obedience,D.Exposure to special spiritual gifts"}, {"q": "Which of the following are manifestations of “being holy” in your life? (Multiple choice)", "s": "Embodiment of being holy separately", "o": "A.Live the covenanted love of marriage in a generation where the wind of passion prevails,B.Don''t be greedy, be content with food and clothing,C.Live a long-lasting, patient, kind, unenviable love,D.Communion with the world in order to preach the gospel"}, {"q": "To be holy separately is to consider oneself completely holy, superior, and despise sinners.", "s": "<bpt i=\"1\" type=\"bold\">{}</bpt>CONSECRATION<ept i=\"1\">{}</ept>"}, {"q": "A victorious life is the only way to God''s blessing, and the Lord can overcome the old me, the world, and Satan.", "s": "Winning Life"}, {"q": "The fullness of the Holy Spirit mainly refers to the manifestation of outward gifts such as speaking in tongues, prophesying, and casting out demons.", "s": "The filling of the Holy Spirit"}, {"q": "Why is it impossible for Christians to be “saved only”?", "s": "Victory is not an option"}, {"q": "Please explain the key to winning and how to do so.", "s": "The Key to Victory"}]}, "ja": {"title": "レッスン13勝利への神聖なステップ", "content": "聖なる者となることは，神に属し，真理に従って生きることです。救いは出発点であり、勝利は避けられない結果です。この課では，主を通して聖化された生活を送る実践と，勝利の秘訣について学びます。あなたが神聖に生き，世界で主のために輝きますように。聖なる者となり，主に仕えること。", "instructions": "", "guide": [{"title": "別々に神聖な真理", "points": ["完全に聖なるものではありませんが、世界から分離し、神に属しています", "世界の価値観に従わず、聖書の真理に従って生きる", "キリスト教は、山での実践ではなく、世界に入ってくる信念です。"]}, {"title": "イスラエルからの教訓", "points": ["神はイスラエルを諸国民の証人として選ばれた", "預言者の告発：神を知っているとき，あなたはどのように国々のように生きていますか。", "コンバージェンスはイスラエルの没落の鍵"]}, {"title": "光の塩を目の当たりにしよう", "points": ["暗闇の光：模索の世界に真の光をもたらす", "塩の保存：世代間道徳の継続的な低下を止める", "群衆の中で違った生き方をすることは、"]}, {"title": "人生の違いは聖なるものです", "points": ["結婚：聖約の愛の聖約（ 1コリント13章）", "お金：貪欲ではなく、食べ物と衣服で満足しています（ 1テモテ6 ： 8 ）", "まず神の王国と神の義を求める（マタイ6 ： 33 ）"]}, {"title": "救いと勝利は切り離せない", "points": ["勝利は選択肢ではなく、救いの必然的な結果です", "生き残れないのか？まったく保存されていない可能性がある", "神はご自分の御子を惜しまれないので，すべてのものをむなしくわたしたちにお与えになることはありません（ローマ8 ： 32 ）。"]}, {"title": "勝利への鍵：神に近づき、悪魔に抵抗する", "points": ["ジェームズ：神に近づいて悪魔に抵抗すると，悪魔は逃げてしまいます（ジェームズ4 ： 7 － 8 ）", "荒れ野で神の言葉で誘惑に立ち向かう主のように", "聖書の与える原則：お金を欲することはすべての悪の根源です（ 1テモテ6 ： 10 ）"]}, {"title": "御霊に満たされた真理", "points": ["外からの贈り物としてではなく、聖霊の完全な支配下にある", "聖霊は，わたしたちが従順を選ぶことを真理に従って思い起こさせてくださる", "ジェームズ：早く聞いて，ゆっくり話して，ゆっくり怒ってください（ジェームズ1 ： 19 ）"]}], "quizzes": [{"q": "[Scripture Fill in the Blank]したがって、あなたは________を望んでいます。必ず悪魔に抵抗してください。そうすれば、悪魔は________逃げるでしょう。", "s": "悪魔に抵抗"}, {"q": "[Scripture Fill in the Blank]あなたは以前の行動から________を取り除きます。この老人は利己的な欲望の混乱のために徐々に________です。", "s": "年寄りを追い払う"}, {"q": "[Scripture Fill in the Blank]世界中の人々が________を失った場合、何の利点がありますか？", "s": "世界中で収入を得る"}, {"q": "聖化されるということは，この世から________出て，神に属し，聖書の真理に従って生きることを意味します。", "s": "別々に神聖"}, {"q": "神聖さは神の________と属性です。罪深い時代に生きる人は誰も、完全に聖なるものであると主張することはありません。", "s": "神聖な属性"}, {"q": "救いと勝利は2つに分けることはできません。救いは________であり、救いの日から勝利の人生を送ることを学びます。", "s": "救いと勝利"}, {"q": "勝利は古い自己であり、世界の誘惑であり、________の誘惑です。", "s": "誰が勝つか"}, {"q": "主イエスは荒野で40日間試みられたとき，サタンに抵抗するために________の言葉で答えられました。", "s": "誘惑に抵抗"}, {"q": "聖霊の最も重要な意義は，わたしたちが聖霊によって完全に________され，聖書の真理に従って思い出され，変化しようとしていることです。", "s": "聖霊に満たされている"}, {"q": "この課の「聖められた」の定義は何ですか。", "s": "別々に神聖", "o": "A.山に走って練習し、世界から離れよう,B.世から切り離され、神に属し、聖書の真理に従って生き、証しする,C.完全に神聖で優れていると自認している,D.日曜日のみ教会に出席する"}, {"q": "「救いのほかに勝利はない」という言葉について，このレッスンはどのような立場にありますか。", "s": "勝利は選択肢ではありません", "o": "A.はい、一生懸命勝ちすぎることは任意です,B.不可能、勝利は救われることの必然的な結果であり、さもなければ救いはまったくないかもしれません,C.勝利は少数の精神的な巨人にのみ属します,D.救いは勝利とは関係ありません"}, {"q": "このレッスンでは，クリスチャンが「光」と「塩」についてどのように述べていますか。", "s": "光と塩", "o": "A.ただ奇跡を起こしてください、塩は調味料です,B.光は人々が真実を見ることができるように闇を照らします。塩は悪の広がりを止めるための防腐剤として機能します。,C.光と塩はどちらも教会の建物を指します,D.光は知識を意味し、塩は富を意味します"}, {"q": "わたしたちが克服するのを助けるために神が与えてくださるリソースには，どのようなものがありますか。（複数選択可）", "s": "勝利の資源", "o": "A.人として行動するための基準を定めた聖書,B.聖霊はわたしたちの内に住んでおられ，更新するよう絶えずわたしたちに思い出させてくれます。,C.人々は自由意志を使って服従を選択します,D.特別な霊的な賜物に触れる"}, {"q": "次のうち，あなたの生活の中で「聖なること」を示すものはどれですか。（複数選択可）", "s": "別々に聖なるものであることの実施形態", "o": "A.情熱の風が吹く世代で、結婚への約束された愛を生きる,B.欲張らないで、食べ物と服で満足してください,C.長く、忍耐強く、親切で、羨ましくない愛を生きる,D.福音を宣べ伝えるための世との交わり"}, {"q": "別々に聖なる者となることは，自分が完全に聖なる者であり，優越しており，罪人を軽蔑していると考えることです。", "s": "別々に神聖"}, {"q": "勝利する人生は神の祝福への唯一の道であり，主は古いわたしと世とサタンに打ち勝つことができます。", "s": "人生を勝ち取る"}, {"q": "聖霊の完全さは，主に異言を話したり，預言をしたり，悪霊を追い出したりするなどの外向きの賜物の現れを指します。", "s": "聖霊に満たされている"}, {"q": "クリスチャンが「救われるだけ」では不可能なのはなぜでしょうか。", "s": "勝利は選択肢ではありません"}, {"q": "勝つための鍵とその方法を説明してください。", "s": "勝利への鍵"}]}, "ko": {"title": "제13과 승리를 향한 성스러운 발걸음", "content": "거룩해지는 것은 하나님께 속하고 진리에 따라 사는 것입니다. 구원은 출발점이며, 승리는 피할 수 없는 결과입니다. 이 과는 성화의 삶을 사는 연습과 주님을 통한 승리의 비결에 관한 것이다. 여러분이 거룩하게 살고 세상에서 주님을 위해 빛나기를 바랍니다. 거룩해지고 주님을 섬기기 위해.", "instructions": "", "guide": [{"title": "따로따로 거룩한 진리", "points": ["완전히 거룩하지는 않지만 세상과 분리되어 있으며 하나님께 속해 있습니다.", "세상 가치에 따라 살지 않고 성경의 진리에 따라 살기", "기독교는 산속의 관습이 아니라 세상에 들어오는 신념입니다."]}, {"title": "이스라엘이 주는 교훈", "points": ["하나님께서는 이스라엘을 이방인들 가운데서 증인으로 선택하셨다.", "선지자의 비난: 하나님을 알 때 어떻게 이방인처럼 살 수 있습니까?", "수렴은 이스라엘의 몰락의 열쇠입니다"]}, {"title": "빛의 소금을 목격하라", "points": ["어둠 속의 빛: 더듬이의 세계에 진정한 빛을 불어넣기", "소금 보존: 세대 도덕의 지속적인 쇠퇴 막기", "군중 속에서 다르게 사는 것은 목격하는 것입니다."]}, {"title": "삶의 차이는 거룩하다", "points": ["결혼: 성약의 사랑의 성약 (고린도전서 13장)", "돈: 욕심내지 말고 음식과 옷에 만족하라 (디모데전서 6: 8)", "먼저 하나님의 나라와 하나님의 의를 구하라 (마태복음 6:33)"]}, {"title": "구원과 승리는 떼려야 뗄 수 없는 관계입니다.", "points": ["승리는 선택이 아니라 구원의 필연적인 결과입니다.", "살아남을 수 없나요? 전혀 저장되지 않았을 수 있음", "하나님은 자기 아들을 아끼지 않으시므로 우리에게 모든 것을 헛되이 주시지 않을 것입니다 (로마서 8:32)."]}, {"title": "승리의 열쇠: 하느님께 가까이 다가가고 악마를 물리치기", "points": ["야고보서: 하나님께 가까이 나아가 마귀를 대적하라 그리하면 그가 도망하리라 (야고보서 4: 7 ~ 8)", "광야에서 하나님의 말씀으로 유혹을 물리치시는 주님처럼", "성경적 기부 원칙: 돈에 대한 탐욕은 모든 악의 뿌리입니다 (디모데전서 6:10)"]}, {"title": "영으로 충만한 진리", "points": ["외적인 선물이 아니라 성령의 완전한 통제하에 있습니다.", "성령께서는 우리가 순종을 선택한다는 진리에 따라 우리를 일깨워주십니다.", "제임스: 빨리 듣고, 천천히 말하고, 천천히 화를 내세요 (야고보서 1:19)"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 따라서 ________ 을 (를) 원합니다. 악마를 물리치면 악마는 ________ 탈출합니다.", "s": "악마에 저항하기"}, {"q": "[Scripture Fill in the Blank] 이전 행동에서 ________ 을 (를) 제거합니다. 이 노인은 이기적인 욕망의 혼란으로 인해 점차 ________ 입니다.", "s": "노인을 없애라"}, {"q": "[Scripture Fill in the Blank] 전 세계의 ________ 사람들이 ________ 을 (를) 잃으면 어떤 이점이 있습니까?", "s": "전 세계 수입 올리기"}, {"q": "성화된다는 것은 ________ 이 세상에서 나와 하나님께 속하고 성경의 진리에 따라 사는 것을 의미합니다.", "s": "별도로 거룩함"}, {"q": "거룩함은 하느님의 ________ 이고 속성입니다. 죄악의 시대에 살고 있는 누구도 감히 자신을 완전히 거룩하다고 주장할 수 없습니다.", "s": "신성한 속성"}, {"q": "구원과 승리는 둘로 나눌 수 없습니다. 구원은 구원의 날부터 승리하는 삶을 배우는 ________ 입니다.", "s": "구원과 승리"}, {"q": "승리는 낡은 자아, 세상의 유혹, ________ 의 유혹이다.", "s": "승자"}, {"q": "주 예수님께서 광야에서 40일 동안 시험을 받으셨을 때, 사탄을 대적하기 위해 ________ 단어로 응답하셨습니다.", "s": "유혹에 저항하세요"}, {"q": "성령의 가장 중요한 의미는 우리가 성령에 의해 완전히 ________ 이며 성경적 진리에 따라 상기되고 기꺼이 변화한다는 것입니다.", "s": "성령으로 충만함"}, {"q": "이 수업에서 “성화됨” 의 정의는 무엇인가?", "s": "별도로 거룩함", "o": "A.산으로 달려가 연습하고 세상과 거리를 두세요.,B.세상과 동떨어져 하나님께 속하여 성경의 진리에 따라 살아가고 증언함,C.완전히 거룩하고 우월한 자아 정체성,D.일요일에만 교회 출석"}, {"q": "“구원 외에는 다른 승리가 없다” 는 말씀에 대한 이 수업의 입장은 무엇인가?", "s": "승리는 선택 사항이 아닙니다", "o": "A.예, 너무 어렵게 이기는 것은 선택 사항입니다.,B.불가능합니다. 승리는 구원받음의 피할 수 없는 결과입니다. 그렇지 않으면 구원이 전혀 없을 수 있습니다.,C.승리는 소수의 영적 거인들에게만 속합니다.,D.구원은 승리와는 아무 상관이 없습니다."}, {"q": "이 과는 그리스도인들을 “빛” 과 “소금” 으로서 무엇이라고 말하는가?", "s": "빛과 소금", "o": "A.그냥 기적을 행하세요, 소금은 조미료입니다,B.빛은 사람들이 진리를 볼 수 있도록 어둠을 밝힙니다. 소금은 악의 확산을 막는 살균제 역할을 합니다.,C.빛과 소금은 모두 교회 건물을 의미합니다.,D.빛은 지식을, 소금은 부를 의미한다."}, {"q": "우리가 극복하는 데 도움이 되도록 하나님께서 우리에게 주시는 자원에는 어떤 것들이 있는가? (복수 선택)", "s": "승리 관련 자료", "o": "A.사람으로서 행동하기 위한 기준을 제시하는 성경,B.성령은 우리 안에 거하시며, 끊임없이 우리에게 업데이트하라고 일깨워 주십니다.,C.사람들은 순종을 선택하기 위해 자유 의지를 사용합니다.,D.특별한 영적 은사에 노출"}, {"q": "다음 중 여러분의 삶에서 “거룩함” 을 나타내는 것은 무엇인가? (복수 선택)", "s": "별개로 거룩한 것의 구현", "o": "A.열정의 바람이 불어오는 세대에 결혼에 대한 성약의 사랑을 실천하십시오.,B.욕심내지 말고 음식과 옷에 만족하세요.,C.오래 참고, 인내하며, 친절하고, 부럽지 않은 사랑을 실천하세요.,D.복음을 전파하기 위한 세상과의 친교"}, {"q": "별도로 거룩하다는 것은 자신을 완전히 거룩하고 우월하며 죄인을 경멸하는 것입니다.", "s": "별도로 거룩함"}, {"q": "승리하는 삶만이 하나님의 축복에 이르는 유일한 길이며, 주님께서는 옛 나, 세상, 사탄을 이길 수 있습니다.", "s": "승리하는 삶"}, {"q": "성령 충만은 주로 방언 말하기, 예언하기, 귀신 쫓아내기 등 외적인 은사가 나타나는 것을 말한다.", "s": "성령으로 충만함"}, {"q": "그리스도인들이 “구원만” 받는 것은 왜 불가능한가?", "s": "승리는 선택 사항이 아닙니다"}, {"q": "승리의 열쇠와 그 방법을 설명해 주십시오.", "s": "승리의 열쇠"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773055589552','基要真理','第十四课 受洗和圣餐','受洗是公开宣告与主同死同复活；圣餐是记念主的死，直等到祂来。本课讲解两大圣礼的意义，以及信徒当存的心态。愿你以感恩的心记念主、见证主。与众圣徒一同记念主的爱。','[{"type": "verse", "q": "【经文填空】所以，你们要去，使万民作我的________，奉父、子、圣灵的名给他们________。", "o": "《马太福音》28章19节", "s": "大使命", "a": "门徒|施洗"}, {"type": "verse", "q": "【经文填空】你若口里________为主，心里信神叫他从死里复活，就必________。", "o": "《罗马书》10章9节", "s": "口里承认", "a": "认耶稣|得救"}, {"type": "verse", "q": "【经文填空】耶稣对他说：我实在告诉你，________你要同我在________里了。", "o": "《路加福音》23章43节", "s": "强盗得救", "a": "今日|乐园"}, {"type": "fill", "q": "主耶稣与撒玛利亚妇人谈道时说，拜他的必须用________和诚实拜他。", "o": "", "s": "敬拜的本质", "a": "心灵"}, {"type": "fill", "q": "受洗是________的吩咐，凡能行的基督徒都应当遵行。", "o": "", "s": "受洗的依据", "a": "主耶稣"}, {"type": "fill", "q": "受洗的意义是公开宣告与主同死同________，出黑暗入光明。", "o": "", "s": "受洗的意义", "a": "复活"}, {"type": "fill", "q": "十字架上的强盗未经受洗仍蒙主应许，说明神的救恩不被________所限制。", "o": "", "s": "救恩与仪式", "a": "仪式"}, {"type": "fill", "q": "圣餐设立的目的是________主的死：饼表他的身体为我们擘开，杯表他的血为我们流出。", "o": "", "s": "圣餐的意义", "a": "记念"}, {"type": "fill", "q": "每次领受圣餐都当省察：他为我死，我当为他而________，天天脱下旧人穿上新人。", "o": "", "s": "圣餐的提醒", "a": "活"}, {"type": "single", "q": "本课认为，基督徒应当受洗的主要依据是？", "o": "A.受洗了就能上天堂,B.这是主耶稣的吩咐，称他为主就当遵行,C.教会传统要求人多好看,D.受洗的水有神奇能力", "s": "受洗的依据", "a": "B"}, {"type": "single", "q": "关于婴儿洗，本课的立场是？", "o": "A.赞成，可以洗去原罪,B.不认同，受洗者本人必须清楚所信，圣经没有“水洗去原罪”的根据,C.无所谓，看父母意愿,D.必须等孩子成年才能决定", "s": "婴儿洗", "a": "B"}, {"type": "single", "q": "圣餐中饼和杯的意义是？", "o": "A.吃了饼喝了杯属灵能力就暴增,B.记念主的死：饼表主身体为我们擘开，杯表主血为我们流出，提醒我们为他而活,C.把饼变成耶稣的身体才有功效,D.只是一种社交聚餐", "s": "饼杯的意义", "a": "B"}, {"type": "multiple", "q": "以下哪些是本课所反对的错误受洗观？（多选）", "o": "A.为在教堂结婚而受洗,B.为给朋友捧人场而受洗,C.认为水点到身上就自动得救,D.受洗前与牧者谈话确认明白信仰", "s": "错误的受洗观", "a": "A|B|C"}, {"type": "multiple", "q": "关于圣餐的频率与形式，本课指出？（多选）", "o": "A.圣经没有明定多久一次，每月一次是教会传统而非真理,B.每天、每周、每月都可以，重要的是达到记念与省察的目的,C.无酵饼和葡萄汁预表性强，当存敬虔谨慎的心预备,D.必须用汉堡和可乐才算与时俱进", "s": "圣餐的实践", "a": "A|B|C"}, {"type": "judge", "q": "基督的信仰是仪式化的宗教，行礼如仪就能蒙福。", "o": "", "s": "信仰非仪式", "a": "错"}, {"type": "judge", "q": "圣经只吩咐了受洗和圣餐这两个圣礼，其余是教会传统中人自己加上去的。", "o": "", "s": "两个圣礼", "a": "对"}, {"type": "judge", "q": "未明白圣餐意义、未信主的人也应当来领圣餐，好叫他蒙福。", "o": "", "s": "领圣餐的资格", "a": "错"}, {"type": "essay", "q": "请说明受洗的圣经依据与属灵意义。", "o": "", "s": "受洗的意义", "a": "依据是主耶稣的吩咐（马太福音28章19节）：奉父、子、圣灵的名施洗；称他为主就当遵行他的命令。意义是公开宣告与主同死、同复活，出黑暗入光明，从此不再活在自己和世界王权下，而是进入爱子的国度，成为神的儿女。受洗者必须清楚所信，反对形式化。"}, {"type": "essay", "q": "圣餐对基督徒生命有何提醒作用？", "o": "", "s": "圣餐的提醒", "a": "圣餐为记念主的死：他为我们的罪死，身体擘开、宝血流出，我们是被重价买回来的。每次领受都提醒我们：他为我死，我为他活；省察自己是否走偏，若走偏就回转，若行在光中就感恩；天天脱下旧人穿上新人，在世代中活出光盐的生命。"}]','https://youtu.be/06zzDWZKrJg
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134snId','quiz','[{"title": "信仰不是仪式化宗教", "points": ["神无所不在，不会被仪式限制住", "用心灵和诚实敬拜（约4:24）", "但主仍吩咐我们守这两个圣礼"]}, {"title": "受洗是主的吩咐", "points": ["太28:19：使万民作门徒，奉父子圣灵的名施洗", "口里认祂为主，就当遵行祂的吩咐", "条件允许却拒绝受洗，是越过圣经"]}, {"title": "受洗的意义：与主同死同复活", "points": ["公开宣告：出黑暗入光明（彼前2:9）", "入水预表同死，出水预表同复活（罗6:3-4）", "从今以后按属灵原则活，不再以自我为中心"]}, {"title": "关于受洗的常见问题", "points": ["浸礼点水皆可，意义清楚最重要", "婴儿洗无圣经根据：受洗者须明白为何受洗", "十字架上的强盗没受洗也得救：仪式不能限制神"]}, {"title": "圣餐的意义：纪念主的死", "points": ["林前11:24-25：吃饼喝杯是纪念主", "饼预表身体擘开，杯预表宝血流出", "祂为我死，我为祂活；被重价买回（林前6:20）"]}, {"title": "圣餐的操练与提醒", "points": ["定期提醒：每月一次是传统中的容忍度", "每次圣餐都是回转的机会：走偏了就回来", "在基督台前，主纪念我们在世的忠心"]}, {"title": "回到圣经：只有两个圣礼", "points": ["天主教七圣事中五个无圣经根据", "不要把神仪式化、偶像化", "明白意义、照主吩咐行，必蒙赐福"]}]','','14','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 14 Baptism and the Eucharist", "content": "Baptism is the public proclamation of death and resurrection with the Lord; the sacrament is the remembrance of the Lord''s death until his coming. This lesson explains the meaning of the two sacraments and the mindset of the believer. May you remember and testify of the Lord with a grateful heart. Remember the love of the Lord with all the saints.", "instructions": "", "guide": [{"title": "Belief is not a ritualized religion", "points": ["God is everywhere, not limited by rituals", "Worship with Heart and Honesty (John 4:24)", "But the Lord still commands us to keep these two sacraments."]}, {"title": "Baptism is commanded by the Lord", "points": ["Matthew 28:19: To make disciples of all nations and baptize them in the name of the Father and the Son and the Holy Spirit", "When you acknowledge Him as Lord in your mouth, do His commandments.", "Permitted but refused to be baptized, is beyond the Bible"]}, {"title": "The Meaning of Baptism: Death and Resurrection with the Lord", "points": ["Public declaration: Out of darkness into light (1 Peter 2: 9)", "The water entry table is the same as death, and the water outlet table is the same as resurrection (Romans 6: 3-4)", "Live according to spiritual principles from now on, no longer self-centered"]}, {"title": "Frequently asked questions about baptism", "points": ["Baptism can be done with water, the meaning is clear and the most important", "There is no biblical basis for infant baptism: the baptized person must understand why they were baptized", "Robbers on the Cross Are Saved Without Baptism: Rituals Can''t Restrict God"]}, {"title": "Significance of the Eucharist: Commemoration of the Lord", "points": ["1 Corinthians 11:24 -25: Eat bread and drink cups to commemorate the Lord", "The cake pre-meter body broke open, and the cup pre-meter blood flowed out", "He died for me and I live for him; bought back with a price (1 Corinthians 6:20)"]}, {"title": "Communion Drills and Reminders", "points": ["Regular reminder: once a month is traditional tolerance", "Every sacrament is an opportunity to turn around: come back when you''ve gone astray", "In the presence of Christ, the Lord commemorates our faithfulness on earth"]}, {"title": "Back to the Bible: Only Two Sacraments", "points": ["Five of the seven sacraments of the Catholic Church have no biblical basis", "Don''t ritualize or idolize gods", "Understand the meaning, do as the Lord tells you, and you will be blessed"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] Therefore, go and make all nations my ________, and give them ________ in the name of the Father, the Son, and the Holy Spirit.", "s": "The Great Commission"}, {"q": "[Scripture Fill in the Blank] If you have ________ in your mouth and believe in God to raise him from the dead, you will ________.", "s": "Mouth acknowledgement"}, {"q": "[Scripture Fill in the Blank] Jesus said to him: I tell you the truth, you will be with me in ________.", "s": "Bandit saved"}, {"q": "Speaking to the Samaritan woman, the Lord Jesus said that those who worshiped him must worship him with ________ and honesty.", "s": "The Nature of Worship"}, {"q": "Baptism is the commandment of the ________, which every practicable Christian ought to do.", "s": "Basis for baptism"}, {"q": "The meaning of baptism is to publicly declare that you will die with the Lord ________ and come out of darkness into light.", "s": "The Meaning of Baptism"}, {"q": "The robbers on the cross were promised by the Lord without being baptized, indicating that God''s salvation is not limited by ________.", "s": "Salvation & Rituals"}, {"q": "The sacrament was instituted for the ________ death of the Lord: the cake table broke his body for us, and the cup table shed his blood for us.", "s": "Meaning of the Eucharist"}, {"q": "Every time I receive the Eucharist, I should examine it: he died for me, I should ________ for him, and take off the old man and put on the new man every day.", "s": "Reminder of the Eucharist"}, {"q": "In this lesson, what is the primary basis on which Christians should be baptized?", "s": "Basis for baptism", "o": "A.Once baptized, you can go to heaven.,B.This is the commandment of the Lord Jesus, call him Lord and do it,C.Church tradition asks how good-looking people are,D.Baptized water has magical powers"}, {"q": "What is the position of this lesson on baby washing?", "s": "Baby wash", "o": "A.Yes, it can wash away original sins,B.Do not agree, the baptized person must clearly believe that the Bible has no basis for “washing away original sin”,C.It doesn''t matter. It depends on the wishes of the parents.,D.Must wait for the child to come of age to decide"}, {"q": "What do bread and cups mean in the Eucharist?", "s": "The Meaning of Cupcakes", "o": "A.Eat bread, drink a cup, and your spiritual abilities will skyrocket.,B.Remembering the Lord''s death: The cake table Lord''s body broke open for us, and the cup table Lord''s blood spilled for us, reminding us to live for him,C.Turning bread into the body of Jesus is what works.,D.It''s just a social gathering."}, {"q": "Which of the following is a false view of baptism that is opposed in this lesson? (Multiple choice)", "s": "Wrong view of baptism", "o": "A.Baptized for marriage in a church,B.Baptized to host a friend,C.Think that if the water reaches the body, it will be automatically saved,D.Talking to pastors before baptism confirms a clear understanding of faith"}, {"q": "What does this lesson say about the frequency and form of the sacrament? (Multiple choice)", "s": "Practice of the Eucharist", "o": "A.The Bible does not specify how often, once a month is church tradition rather than truth,B.Every day, every week, every month, it is important to achieve the purpose of remembrance and reflection,C.Unleavened cakes and grape juice are highly prespecified, and should be prepared with a godly and cautious heart.,D.You have to use hamburgers and Coke to keep up with the times."}, {"q": "The faith of Christ is a ritualized religion, blessed by ritual.", "s": "Faith is not a ritual"}, {"q": "The Bible only commands the two sacraments of baptism and the sacrament of the Lord''s Supper, the rest being added by man himself in the tradition of the Church.", "s": "Two Sacraments"}, {"q": "Those who do not understand the meaning of the sacrament and do not believe in the Lord should also come and receive the sacrament, so that he may be blessed.", "s": "Eligibility for Communion"}, {"q": "Please explain the biblical basis and spiritual meaning of baptism.", "s": "The Meaning of Baptism"}, {"q": "How does the Eucharist serve as a reminder of the Christian life?", "s": "Reminder of the Eucharist"}]}, "ja": {"title": "レッスン14バプテスマと聖餐", "content": "バプテスマとは，主とともに死と復活を告げ知らせることであり，聖餐は主が来られるまで主の死を思い起こすことです。この課では， 2つの秘跡の意味と信者の考え方について説明します。感謝の心をもって主を思い出し，主を証しますように。すべての聖徒に主の愛を思い起こしてください。", "instructions": "", "guide": [{"title": "信仰は儀式化された宗教ではない", "points": ["神はどこにでもおられ、儀式によって制限されることはありません", "心と正直さをもって礼拝する（ヨハネ4 ： 24 ）", "しかし，主は依然として，この2つの秘跡を守るようわたしたちに命じておられます。"]}, {"title": "バプテスマは主によって命じられている", "points": ["マタイ28 ： 19 ：すべての国民を弟子とし，御父と御子と聖霊の御名によってバプテスマを授ける", "あなたの口の中で主を主として認めるときは，主の戒めを実行してください。", "許可されたが、バプテスマを受けることを拒否した、聖書を超えている"]}, {"title": "バプテスマの意味：主と共に死と復活", "points": ["公の宣言：暗闇から光へ（ 1ペテロ2 ： 9 ）", "入水台は死と同じで，出水台は復活と同じです（ローマ6 ： 3 － 4 ）。", "これからは、もはや自己中心的ではなく、霊的な原則に従って生きる"]}, {"title": "バプテスマに関するよくある質問", "points": ["バプテスマは水で行うことができ、その意味は明確で最も重要です", "幼児のバプテスマには聖書的な根拠はありません：バプテスマを受けた人は、なぜ自分がバプテスマを受けたのかを理解しなければなりません", "十字架上の強盗はバプテスマなしで救われる：儀式は神を制限することはできない"]}, {"title": "聖餐の意義：主の記念", "points": ["1コリント11 ： 24 － 25 ：主を記念するためにパンを食べ，杯を飲む", "ケーキのメーター前の本体が割れて、カップのメーター前の血が流れ出た", "彼は私のために死に、私は彼のために生きています。代価を払って買い戻されました（ 1コリント6 ： 20 ）"]}, {"title": "聖体拝領ドリルとリマインダー", "points": ["定期的なリマインダー：月に1回は伝統的な寛容さです", "すべての聖餐は振り向く機会です：道に迷ったら戻ってきてください", "キリストの御前で，主は地上でのわたしたちの忠実さを記念しておられます"]}, {"title": "聖書に戻る： 2つの秘跡だけ", "points": ["カトリック教会の7つの秘跡のうち5つには聖書的な根拠がありません", "神々を儀式化したり、偶像化したりしないでください", "意味を理解し，主が言われるとおりにしてください。そうすれば，あなたは祝福を受けるでしょう"]}], "quizzes": [{"q": "[聖書は空白を埋める]したがって、行って、すべての国を私の________とし、父、子、聖霊の名によって________を与えてください。", "s": "グレート・コミッション"}, {"q": "〔聖句の穴埋め〕あなたが口に________を持っていて、彼を死者の中から復活させるために神を信じるなら、あなたは________するでしょう。", "s": "口頭での謝辞"}, {"q": "[Scripture Fill in the Blank]イエスは彼に言いました。「本当のことを言うと、あなたは________で私と一緒にいるでしょう。", "s": "無法者を救出しました"}, {"q": "主イエスはサマリアの女性に話しかけて，ご自分を崇拝する人々は________と正直さをもってご自分を崇拝しなければならないと言われました。", "s": "礼拝の本質"}, {"q": "バプテスマは，実践可能なすべてのクリスチャンが行うべき________の戒めです。", "s": "バプテスマの基礎"}, {"q": "バプテスマの意味は，あなたが________主と共に死に，暗闇から光の中に来ることを公に宣言することです。", "s": "バプテスマの意味"}, {"q": "十字架上の強盗は，バプテスマを受けずに主から約束されたものであり，神の救いは________によって制限されていないことを示しています。", "s": "救いと儀式"}, {"q": "聖餐は主の________の死のために制定されました：ケーキテーブルは私たちのために彼の体を折り、カップテーブルは私たちのために彼の血を流しました。", "s": "聖体の意味"}, {"q": "聖体を受けるたびに、私はそれを調べる必要があります。彼は私のために死にました。私は彼のために________し、古い人を脱ぎ、毎日新しい人を着ます。", "s": "聖体拝領のリマインダー"}, {"q": "この課では，クリスチャンがバプテスマを受ける主な基礎は何ですか。", "s": "バプテスマの基礎", "o": "A.バプテスマを受けたら，天国に行くことができます。,B.これは主イエスの命令であり、彼を主と呼んでそれを行います,C.教会の伝統は、人々がどれほど見栄えが良いかを尋ねる,D.洗礼を受けた水には魔法の力があります"}, {"q": "赤ちゃんの洗濯に関するこのレッスンの立場はどのようなものですか？", "s": "ベビーウォッシュ", "o": "A.はい、それは元の罪を洗い流すことができます,B.同意しないでください。バプテスマを受けた人は、聖書には「元の罪を洗い流す」ための根拠がないと明確に信じなければなりません,C.それは関係ありません。それは両親の願い次第です。,D.子供が成人するまで待たなければならない"}, {"q": "聖体におけるパンとカップとはどういう意味でしょうか。", "s": "カップケーキの意味", "o": "A.パンを食べ，杯を飲むと，あなたの霊的な能力は急上昇します。,B.主の死を覚えておく：ケーキテーブル主の体は私たちのために開かれ、カップテーブル主の血は私たちのためにこぼれ、主のために生きることを思い出させました,C.パンをイエスの体に変えることが効果的です。,D.ただの懇親会だ。"}, {"q": "この課で反対されているバプテスマの誤った見方は，次のうちどれですか。（複数選択可）", "s": "バプテスマの誤った見方", "o": "A.教会で結婚のためにバプテスマを受ける,B.友達を迎え入れるためにバプテスマを受けた,C.水が体に届くと自動的に救われると思います,D.バプテスマの前に牧師と話すことで，信仰を明確に理解できるようになります"}, {"q": "このレッスンでは，聖餐の頻度と形式についてどのようなことが分かりますか。（複数選択可）", "s": "聖体の実践", "o": "A.聖書は、月に1回が真理ではなく教会の伝統であることをどのくらいの頻度で指定していません,B.毎日、毎週、毎月、記憶と省察の目的を達成することが重要です,C.種入れぬケーキやブドウジュースはあらかじめ指定されており、敬虔で用心深い心で準備する必要があります。,D.時代に追いつくためには、ハンバーガーとコーラを使用する必要があります。"}, {"q": "キリストの信仰は，儀式によって祝福された儀式化された宗教です。", "s": "信仰は儀式ではない"}, {"q": "聖書は、バプテスマと主の晩餐の聖餐の2つの秘跡のみを命じています。残りは、教会の伝統の中で人間自身によって追加されます。", "s": "2つの秘跡"}, {"q": "聖餐の意味を理解しておらず，主を信じていない人も，祝福を受けるために来て聖餐を受けるべきです。", "s": "聖体拝領の資格"}, {"q": "バプテスマの聖書的根拠と霊的な意味を説明してください。", "s": "バプテスマの意味"}, {"q": "聖体は，クリスチャンの生活をどのように思い起こさせるのでしょうか。", "s": "聖体拝領のリマインダー"}]}, "ko": {"title": "제14과 세례와 성체성사", "content": "침례는 주님과 함께하는 죽음과 부활을 공개적으로 선포하는 것입니다. 성찬은 주님이 오실 때까지 주님의 죽으심을 기억하는 것입니다. 이 수업은 두 성사의 의미와 신자의 마음가짐을 설명한다. 감사하는 마음으로 주님을 기억하고 간증하길 바랍니다. 모든 성도들과 함께 주님의 사랑을 기억하십시오.", "instructions": "", "guide": [{"title": "믿음은 의식화된 종교가 아닙니다", "points": ["하나님은 의식에 의해 제한되지 않고 모든 곳에 계십니다.", "마음과 정직으로 예배하라 (요한복음 4:24)", "그러나 주님께서는 여전히 우리에게 이 두 가지 성사를 지키라고 명령하십니다."]}, {"title": "침례는 주님께서 명령하신 것입니다.", "points": ["마태복음 28:19: 모든 족속으로 제자를 삼아 아버지와 아들과 성령의 이름으로 침례를 주다", "입으로 그분을 주님으로 인정할 때, 그분의 계명을 행하십시오.", "침례를 받는 것은 허용되었지만 거부된 것은 성경을 넘어서는 것입니다."]}, {"title": "침례의 의미: 주님과 함께하는 죽음과 부활", "points": ["공언: 어둠에서 빛으로 (베드로전서 2: 9)", "물 입구 테이블은 죽음과 같고, 물 출구 테이블은 부활과 같습니다 (로마서 6: 3-4).", "이제부터는 더 이상 자기중심적이지 않고 영적인 원리에 따라 살아가십시오."]}, {"title": "침례에 관해 자주 묻는 질문과 답변", "points": ["세례는 물로 할 수 있습니다. 의미는 명확하고 가장 중요합니다.", "유아 침례에는 성경적 근거가 없습니다. 침례를 받은 사람은 자신이 침례를 받은 이유를 이해해야 합니다.", "침례 없이 십자가에 달린 강도들은 구원받습니다: 의식은 하나님을 제한할 수 없습니다"]}, {"title": "성찬의 의의: 주님 기념", "points": ["고린도전서 11:24 ~ 25: 주님을 기념하기 위해 빵과 잔을 먹으십시오.", "케이크 프리미터 바디가 열리고 컵 프리미터 피가 흘러나왔다.", "그분은 나를 위해 죽으셨고 나는 그분을 위해 살았습니다. 값으로 되찾았습니다 (고린도전서 6:20)"]}, {"title": "영성체 훈련 및 알림", "points": ["정기 알림: 한 달에 한 번은 일반적인 허용 범위입니다.", "모든 성찬은 돌이킬 수 있는 기회입니다. 길을 잃었을 때 돌아오세요.", "주님께서는 그리스도 앞에서 지상에서의 우리의 신실함을 기념하십니다."]}, {"title": "성경으로 돌아가기: 오직 두 성사", "points": ["가톨릭 교회의 일곱 성사 중 다섯 성사는 성경적 근거가 없다.", "신을 의식하거나 우상화하지 마세요", "의미를 이해하고, 주님께서 시키는 대로 하십시오. 그러면 축복을 받게 될 것입니다."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 그러므로 너희는 가서 모든 족속으로 나의 ________ (을) 를 삼아 아버지와 아들과 성령의 이름으로 ________ (을) 를 주라.", "s": "위대한 임무"}, {"q": "[Scripture Fill in the Blank] 만약 당신이 ________ 을 (를) 입에 넣고 그를 죽은 자 가운데서 살리실 하나님을 믿는다면, 당신은 ________ 할 것입니다.", "s": "입안 확인"}, {"q": "[Scripture Fill in the Blank] 예수께서 이르시되 내가 진실로 네게 이르노니 네가 ________ 안에 나와 함께 있으리라", "s": "산적 저장 완료"}, {"q": "주 예수께서는 사마리아 여인에게 말씀하시면서 당신을 숭배하는 사람들은 ________ 와 정직함으로 당신을 숭배해야 한다고 말씀하셨습니다.", "s": "예배의 본질"}, {"q": "침례는 실행 가능한 모든 그리스도인이 해야 할 ________ 의 계명이다.", "s": "침례의 기초"}, {"q": "침례의 의미는 여러분이 주님과 함께 ________ 죽고 어둠에서 빛으로 나올 것임을 공개적으로 선언하는 것입니다.", "s": "침례의 의미"}, {"q": "십자가에 달린 강도들은 침례를 받지 않고 주님의 약속을 받았으며, 이는 하나님의 구원이 ________ 에 의해 제한되지 않음을 나타냅니다.", "s": "구원 및 의식"}, {"q": "성찬은 주님의 죽음을 위해 제정되었습니다. 케이크 테이블은 우리를 위해 그분의 몸을 부수고 컵 테이블은 우리를 위해 그분의 피를 흘렸습니다.", "s": "성찬의 의미"}, {"q": "성찬을 받을 때마다 나는 성찬을 살펴봐야 한다. 그는 나를 위해 죽었고, 나는 그를 위해 ________ 해야 하며, 노인을 벗고 매일 새 사람을 입어야 한다.", "s": "성체성사 알림"}, {"q": "이 수업에서 그리스도인이 침례를 받아야 하는 주된 근거는 무엇인가?", "s": "침례의 기초", "o": "A.침례를 받으면 천국에 갈 수 있습니다.,B.이것이 주 예수님의 계명입니다. 그분을 주님이라 부르고 행하십시오.,C.교회 전통은 사람들이 얼마나 잘 생겼는지 묻습니다.,D.세례받은 물에는 마법의 힘이 있습니다"}, {"q": "이 수업의 아기 세척에 대한 입장은 무엇입니까?", "s": "베이비 워시", "o": "A.예, 원죄를 씻을 수 있습니다.,B.동의하지 마십시오. 침례받은 사람은 성경이 “원죄를 씻을” 근거가 없음을 분명히 믿어야 합니다.,C.상관없다. 부모의 바람에 달렸다.,D.자녀가 성년이 될 때까지 기다려야 합니다."}, {"q": "성찬에서 빵과 잔은 무엇을 의미하는가?", "s": "컵케이크의 의미", "o": "A.빵을 먹고, 잔을 마시면 영적 능력이 급상승합니다.,B.주님의 죽으심을 기억하며: 주님의 몸이 우리를 위해 떡상이 열리고, 주님의 피가 우리를 위해 쏟아져서 우리가 그분을 위해 살 것을 상기시키는 잔상이 열렸습니다.,C.빵을 예수님의 몸으로 바꾸는 것이 효과가 있습니다.,D.그저 친목 모임일 뿐입니다."}, {"q": "다음 중 이 수업에서 반대되는 침례에 대한 잘못된 견해는 무엇인가? (복수 선택)", "s": "침례에 대한 잘못된 견해", "o": "A.교회에서 결혼을 위한 침례를 받음,B.세례를 받고 친구를 호스팅함,C.물이 몸에 닿으면 자동으로 저장된다고 생각하세요.,D.침례 전에 목회자들과 이야기하는 것은 신앙에 대한 명확한 이해를 확인합니다."}, {"q": "이 수업은 성찬의 빈도와 형태에 대해 무엇을 말하는가? (복수 선택)", "s": "성찬례의 실제", "o": "A.성경은 얼마나 자주, 한 달에 한 번이 진리보다는 교회의 전통인지를 명시하지 않습니다.,B.매일, 매주, 매월, 기억과 성찰의 목적을 달성하는 것이 중요합니다.,C.누룩을 넣지 않은 케이크와 포도즙은 미리 정해진 양이 많으므로 경건하고 신중한 마음으로 준비해야 합니다.,D.시간을 맞추기 위해 햄버거와 콜라를 사용해야 합니다."}, {"q": "그리스도의 신앙은 의식에 의해 축복된 의식화된 종교입니다.", "s": "신앙은 의식이 아닙니다"}, {"q": "성경은 세례의 두 성사와 주님의 만찬의 성사를 명령하며, 나머지는 교회의 전통에서 인간이 직접 추가합니다.", "s": "두 성사"}, {"q": "성찬의 의미를 이해하지 못하고 주님을 믿지 않는 사람들도 와서 성찬을 받아야 그분이 축복을 받으실 수 있습니다.", "s": "친교 자격"}, {"q": "침례의 성경적 기초와 영적 의미를 설명해 주십시오.", "s": "침례의 의미"}, {"q": "성찬례는 어떻게 그리스도인의 삶을 상기시키는 역할을 하는가?", "s": "성체성사 알림"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773056005974','基要真理','第十五课 加入教会','教会是神呼召的生命共同体，基督的身体。加入教会是神建造我们的重要途径。本课建立正确的教会观与委身的意义。愿你在教会中找到属灵的家。在爱中彼此建立，同奔天路。','[{"type": "verse", "q": "【经文填空】你要尽心、尽性、尽意、________爱主你的________。", "o": "《马可福音》12章30节", "s": "最大的诫命", "a": "尽力|神"}, {"type": "verse", "q": "【经文填空】我以神的慈悲劝你们，将________献上，当作________；你们如此事奉乃是理所当然的。", "o": "《罗马书》12章1节", "s": "将身体献上", "a": "身体|活祭"}, {"type": "verse", "q": "【经文填空】我栽种了，________浇灌了，惟有神叫他________。", "o": "《哥林多前书》3章6节", "s": "神叫他生长", "a": "亚波罗|生长"}, {"type": "fill", "q": "教会按希腊原文的意思，是神所________出来的一批人聚集在一起。", "o": "", "s": "教会的定义", "a": "呼召"}, {"type": "fill", "q": "教会不是________的地方，但它是朝着圣洁完美标准迈进的地方。", "o": "", "s": "教会的真相", "a": "完美"}, {"type": "fill", "q": "葛理翰牧师说：世界上没有完美的教会，若真有，从你________那天起也就不完美了。", "o": "", "s": "没有完美教会", "a": "加入"}, {"type": "fill", "q": "以弗所书启示：基督是教会的________，教会是基督的身体。", "o": "", "s": "基督与教会", "a": "元首"}, {"type": "fill", "q": "服事不是与神________，而是生命更新、神赐福我们的方法。", "o": "", "s": "服事的本质", "a": "交易"}, {"type": "fill", "q": "腓立比书教导：各人不要单顾自己的事，也要顾________的事。", "o": "", "s": "彼此相顾", "a": "别人"}, {"type": "single", "q": "本课指出，教会与一般社团的根本区别是？", "o": "A.教会人数更多,B.社团以兴趣结合，教会是以属灵新生命结合的生命共同体,C.教会建筑更宏伟,D.社团收费，教会免费", "s": "教会与社团", "a": "B"}, {"type": "single", "q": "关于在教会中受伤，本课的劝勉是？", "o": "A.立刻离开教会，避免再受伤,B.靠主再站起来，检讨自己，做在主面前，定睛于主的肯定,C.以牙还牙，批评回去,D.从此只做观众不再服事", "s": "面对伤害", "a": "B"}, {"type": "single", "q": "主日崇拜与团契小组的关系是？", "o": "A.二选一，参加一个就够了,B.主日重在领受真理，团契重在学习活出真理，两者功能不同不可偏废,C.团契只是查经班的重复,D.在网上看节目就可以取代两者", "s": "主日与团契", "a": "B"}, {"type": "multiple", "q": "加入教会是神建造我们的重要途径，原因包括？（多选）", "o": "A.众圣徒恩赐不同，在基督身体里彼此建造装备,B.在与人的横向关系中生命被更新改变,C.横向的人际关系能反映纵向的与神关系,D.教会里都是完美圣徒不会受伤", "s": "加入教会的原因", "a": "A|B|C"}, {"type": "multiple", "q": "以下哪些是本课所纠正的错误服事观？（多选）", "o": "A.多给神、神就多给的交易式服事,B.把教会当作展现才华的舞台,C.只愿单干、不愿与不同的人配搭,D.先将自己献上当作活祭再服事", "s": "错误的服事观", "a": "A|B|C"}, {"type": "judge", "q": "教堂是建筑物，教会是属灵生命的集合体，两者不可混淆。", "o": "", "s": "教堂与教会", "a": "对"}, {"type": "judge", "q": "在网上看讲道节目就可以完全取代参加教会的主日崇拜和团契生活。", "o": "", "s": "不可取代", "a": "错"}, {"type": "judge", "q": "保罗说“判断我的乃是主”，因此在教会服事当定睛于主，不被人的论断捆绑。", "o": "", "s": "定睛于主", "a": "对"}, {"type": "essay", "q": "为什么基督徒应当加入教会？请结合本课说明。", "o": "", "s": "加入教会", "a": "加入教会是神的吩咐，也是神建造我们的重要途径。教会是神呼召出来的生命共同体，众圣徒恩赐不同，在基督身体里彼此建造、装备，然后在各自处境中作光作盐。基督徒生命不只有与神的纵向关系，还有与人的横向关系，横向关系反映纵向关系；在互动中老我被改变，学会谦卑、感恩、欣赏他人，这是神赐福的方法。"}, {"type": "essay", "q": "请说明合乎圣经的服事观。", "o": "", "s": "服事观", "a": "服事不是与神交易（多给神神就多给），也不是展现个人才华的舞台。罗马书12章1节：先将身体献上当作活祭，先成为被神更新的正确的人，再自然活出正确的生命。服事是带领一群不同的人同做一件事，在配搭中彼此被建造；做在主面前，只问耕耘不问收获，定睛于主的肯定。"}]','https://youtu.be/bb3qEoB4WIc
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134rXo8','quiz','[{"title": "为什么有人不想加入教会", "points": ["觉得时间被占用、怕受伤、怕太累", "教会里有闲话、分党、把重担都堆给热心人", "但这些现象不能否定教会本身的价值"]}, {"title": "教会是什么", "points": ["希腊文原意：神呼召出来的一批人", "是生命共同体，不是兴趣社团", "教堂是建筑物，教会是属灵生命的集合体"]}, {"title": "教会不是完美的地方", "points": ["哥林多教会分党、老底嘉教会不冷不热", "但教会是朝圣洁完美标准迈进的地方", "神没有放弃不理想的教会，用真道继续建造"]}, {"title": "身体的比喻：彼此建造", "points": ["林前12章21节：眼不能对手说我用不着你", "不同恩赐结合，才能发挥身体的功能", "在教会装备好，到各处去作光作盐"]}, {"title": "纵向与横向的关系", "points": ["最大诫命：爱神，其次爱人如己（太22:37-38）", "人际关系反映出我们跟神的关系", "在互动中被改变：脱下旧人穿上新人"]}, {"title": "服事的真义", "points": ["不是交易：多做多得不是圣经标准", "罗12:1：将身体献上当作活祭", "服事是神赐福的方法：人在服事中被建造"]}, {"title": "主日与团契：都要，不二选一", "points": ["主日崇拜：领受真理；团契小组：学习活出真理", "属灵成熟不在乎背多少，而在乎活出多少", "腓2:4：各人不要单顾自己的事，也要顾别人的事"]}]','','15','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 15 Joining the Church", "content": "The church is a community of life called by God, the body of Christ. Joining the Church is an important way God builds us. This lesson establishes a correct view of the Church and the meaning of commitment. May you find a spiritual home in the Church. Build each other up in love and go to heaven together.", "instructions": "", "guide": [{"title": "Why does someone not want to join the church?", "points": ["Feeling time-consuming, afraid of injury, afraid of being too tired", "There is gossip in the church, splitting the party, and piling burdens on enthusiasts", "But these phenomena do not negate the value of the Church itself."]}, {"title": "What is the Church?", "points": ["Greek original meaning: A group of people called out by God", "It''s a community of life, not a community of interest.", "Churches are buildings, churches are collections of spiritual life"]}, {"title": "The Church is not a perfect place", "points": ["Corinthian church branch, Laodicean church lukewarm", "But the church is a place that moves towards the standard of holiness and perfection.", "God did not abandon the unsatisfactory church and continue to build it with the true word"]}, {"title": "The Body Parable: Building Each Other", "points": ["1 Corinthians 12:21: The eye cannot say to the opponent that I do not need you", "Different gifts are combined to play the function of the body", "Gear up at church and go everywhere to make salt from light"]}, {"title": "Vertical versus horizontal", "points": ["The greatest commandment: Love God, and secondly, love others as yourself (Matthew 22:37 -38)", "Relationships reflect our relationship with God", "Changed during the interaction: taking off the old man and putting on the new one"]}, {"title": "The Truth of Service", "points": ["Not a deal: Doing more is not a biblical standard", "Romans 12: 1: Offer your body as a living sacrifice", "Serving is a Blessed Way: Man is Built in Serving"]}, {"title": "Sunday and fellowship: all, no choice", "points": ["Sunday Worship: Receiving the Truth; Fellowship Group: Learning to Live the Truth", "Spiritual maturity doesn''t care how much you memorize, but how much you live.", "Philippians 2: 4: Each person should not focus solely on his own affairs, but also on the affairs of others"]}], "quizzes": [{"q": "[Scripture Fill in the blanks] You must love the Lord your ________ with all your heart, soul, and mind.", "s": "The Greatest Commandment"}, {"q": "[Scripture Fill in the Blank] With the mercy of God, I exhort you to offer ________ as ________; it is a matter of course that you serve this way.", "s": "Offer your body"}, {"q": "[Scripture Fill in the Blank] I planted, ________ watered, only God called him ________.", "s": "God told him to grow."}, {"q": "The original Greek meaning of the church is that a group of people from God''s ________ gathered together.", "s": "Definition of the Church"}, {"q": "The Church is not a place of ________, but it is a place of progress toward the standard of holiness and perfection.", "s": "The Truth of the Church"}, {"q": "Pastor Graham said: There is no perfect church in the world, and if there is, it will not be perfect from the day you ________.", "s": "There is no perfect church"}, {"q": "Ephesians revelation: Christ is the ________ of the church, and the church is the body of Christ.", "s": "Christ and the Church"}, {"q": "Service is not a ________ with God, but a way of life renewal, of God blessing us.", "s": "The Nature of Service"}, {"q": "Philippians teaches that each person should not focus solely on his or her own affairs, but also on ________.", "s": "Looking out for each other"}, {"q": "What is the fundamental difference between the church and the general community?", "s": "Churches & Societies", "o": "A.Larger number of churches,B.The community is united by interest, and the church is a community of life united by new spiritual life.,C.Church buildings are bigger,D.Club Fee, Free for Church"}, {"q": "What is the exhortation in this lesson about being injured in the church?", "s": "Facing Injury", "o": "A.Leave the church immediately to avoid further injury,B.Stand up again by the Lord, review yourself, stand before the Lord, and focus on the Lord''s affirmation.,C.Tooth for tooth, criticize back,D.Since then, only the audience has ceased to serve."}, {"q": "What is the relationship between Sunday worship and fellowship groups?", "s": "Sunday & Fellowship", "o": "A.Choose one of the two, it''s enough to participate in one,B.The Lord''s Day focuses on receiving the truth, and fellowship focuses on learning to live the truth. The two functions are different and cannot be overlooked.,C.Fellowship is just a repetition of a Bible study class,D.Watching a show online can replace both"}, {"q": "Why is joining a church an important way for God to build us? (Multiple choice)", "s": "Reasons to join a church", "o": "A.The gifts of the saints are different, building equipment for each other in the body of Christ,B.Life is renewed and altered in lateral relationships with people,C.Horizontal relationships reflect vertical relationships with God,D.The church is full of perfect saints who don''t get hurt."}, {"q": "Which of the following is an incorrect view of service corrected in this lesson? (Multiple choice)", "s": "Wrong view of service", "o": "A.More transactional service to God, more transactional service to God,B.Use the Church as a stage to showcase your talents,C.Only willing to do it alone, unwilling to pair with different people,D.Offer yourself as a living sacrifice before serving"}, {"q": "Churches are buildings, and churches are collections of spiritual life, and the two cannot be confused.", "s": "Churches & Churches"}, {"q": "Watching a sermon online can completely replace attending church Sunday worship and fellowship.", "s": "Non-replaceable"}, {"q": "Paul says, “It is the Lord who judges me,” and therefore, in the service of the church, let your eye be fixed on the Lord, and not bound by the judgments of men.", "s": "Focus on the Lord"}, {"q": "Why should Christians join the church? Please combine the instructions in this lesson.", "s": "Join the Church"}, {"q": "Please explain the biblical concept of service.", "s": "Concept of service"}]}, "ja": {"title": "レッスン15教会に加わる", "content": "教会は，キリストのからだである神によって召された命の共同体です。教会に加わることは，神がわたしたちを建てる重要な方法です。この課では，教会についての正しい見解とコミットメントの意味を確立します。教会に霊的な家がありますように。お互いを愛の中に築き上げ、一緒に天国に行きましょう。", "instructions": "", "guide": [{"title": "教会に参加したくない人がいるのはなぜですか。", "points": ["時間がかかり、怪我を恐れ、疲れ過ぎることを恐れている", "教会にはゴシップがあり、パーティーを分割し、愛好家に負担をかけています", "しかし，これらの現象は教会自体の価値を否定するものではありません。"]}, {"title": "教会とは何ですか。", "points": ["ギリシャ語の元の意味：神に呼び出された人々の集団", "それは人生のコミュニティであり、関心のあるコミュニティではありません。", "教会は建物であり、教会は霊的生活の集合体です"]}, {"title": "教会は完璧な場所ではありません", "points": ["コリント教会支部、ラオディキア教会ぬるま湯", "しかし，教会は聖性と完全性の基準に向かって進む場所です。", "神は不満足な教会を捨てて、真の言葉をもって教会を建て続けたのではありません"]}, {"title": "体のたとえ話：互いに築きあう", "points": ["1コリント12 ： 21 ：私はあなたを必要としていないと相手に言うことはできません", "さまざまな贈り物を組み合わせて体の機能を発揮します", "教会で装備を整え、光から塩を作るためにどこへでも行こう"]}, {"title": "垂直対水平", "points": ["最大の戒め：神を愛し，第二に，自分自身のように他者を愛すること（マタイ22 ： 37 － 38 ）", "人間関係は，わたしたちと神との関係を反映しています", "インタラクション中に変更：古い人を脱ぎ、新しい人を着る"]}, {"title": "奉仕の真実", "points": ["取引ではありません：より多くのことをすることは聖書的な基準ではありません", "ローマ12 ： 1 ：生ける犠牲として体を捧げる", "奉仕は祝福された方法です：人は奉仕の中に建てられています"]}, {"title": "日曜日と親睦：すべて、選択の余地なし", "points": ["日曜礼拝：真理を受ける；親睦グループ：真理に生きることを学ぶ", "霊的な成熟は、あなたがどれだけ暗記しているかではなく、どれだけ生きているかにかかっています。", "ピリピ2 ： 4 ：各人は自分の問題だけに集中すべきではなく、他の人の問題にも集中すべきです"]}], "quizzes": [{"q": "[Scripture Fill in the blanks]あなたは心、魂、思いを尽くして________主を愛さなければなりません。", "s": "最大の戒め"}, {"q": "[Scripture Fill in the Blank]神の憐れみにより、私はあなたに________を________として提供することを勧めます。あなたがこのように奉仕することは当然のことです。", "s": "身体を捧げる"}, {"q": "〔聖句の穴埋め〕私はそれを植えて________水をやりましたが、神は彼を________と呼ばれました。", "s": "神は彼に成長するように命じました。"}, {"q": "教会のもともとのギリシャ語の意味は、神の________から集まった人々のグループです。", "s": "教会の定義"}, {"q": "教会は________の場所ではありませんが，聖性と完全性の基準に向かって進歩する場所です。", "s": "教会の真理"}, {"q": "グラハム牧師は次のように述べています。「この世に完璧な教会はありません。もしあるとすれば，あなたが________した日から完璧になることはありません。", "s": "完璧な教会はありません"}, {"q": "エペソの啓示：キリストは教会の________であり，教会はキリストの体です。", "s": "キリストと教会"}, {"q": "奉仕とは，神と共にある________ではなく，神がわたしたちを祝福してくださる生き方の刷新です。", "s": "サービスの性質"}, {"q": "ピリピ人は，各人が自分の事柄だけに焦点を当てるべきではなく， ________にも焦点を当てるべきであると教えています。", "s": "お互いに気を配る"}, {"q": "教会と一般社会の根本的な違いは何ですか。", "s": "教会と社会", "o": "A.教会の数が多い,B.共同体は関心によって結びついており，教会は新しい霊的生活によって結びついた生活の共同体です。,C.教会の建物はもっと大きい,D.クラブ手数料、教会は無料"}, {"q": "この課では，教会で怪我をしたことについて，どのような勧告がありますか。", "s": "負傷に直面している", "o": "A.さらなる怪我を避けるために、直ちに教会を離れてください,B.主によって再び立ち上がり，自分自身を振り返り，主の前に立ち，主の確信に焦点を当ててください。,C.歯を歯に、背中を批判する,D.それ以来、聴衆だけが奉仕することをやめました。"}, {"q": "日曜日の礼拝と交わりのグループの関係はどのようなものですか。", "s": "日曜日とフェローシップ", "o": "A.2つのうち1つを選択してください。1つに参加するだけで十分です,B.主の日は真理を受けることに焦点を当て、フェローシップは真理を生きることを学ぶことに焦点を当てています。2つの機能は異なり、見過ごすことはできません。,C.親睦は聖書学習クラスの繰り返しに過ぎません,D.ショーをオンラインで視聴すると、両方を置き換えることができます"}, {"q": "なぜ教会に加わることは，神がわたしたちを建てるための重要な方法なのでしょうか。（複数選択可）", "s": "教会に参加する理由", "o": "A.聖徒の賜物は異なり、キリストの体の中にお互いのための装備を作る,B.人生は人々との横の関係で更新され、変化します,C.水平的な関係は、神との垂直的な関係を反映しています,D.教会は傷つかない完璧な聖人でいっぱいです。"}, {"q": "このレッスンで修正された誤ったサービスの見方は次のうちどれですか？ （複数選択可）", "s": "誤ったサービスの見方", "o": "A.神へのより多くの取引サービス、神へのより多くの取引サービス,B.教会をステージとして使用して、自分の才能をアピールしましょう,C.一人で行うことを望まず、異なる人とペアリングすることを望まない,D.奉仕する前に、自分自身を生きた犠牲として差し出す"}, {"q": "教会は建物であり、教会は霊的生活の集合体であり、両者を混同することはできません。", "s": "教会&教会"}, {"q": "オンラインで説教を見ることは，教会の日曜日の礼拝と親睦に完全に取って代わることができます。", "s": "交換不可"}, {"q": "パウロは，「わたしを裁くのは主です」と言います。したがって，教会への奉仕においては，人々の裁きに縛られることなく，主に目を向けてください。", "s": "主に焦点を当てる"}, {"q": "クリスチャンが教会に加わるべき理由は何でしょうか。このレッスンの指示を組み合わせてください。", "s": "教会に参加する"}, {"q": "聖書的な奉仕の概念を説明してください。", "s": "サービスのコンセプト"}]}, "ko": {"title": "제 15과 교회에 가입하기", "content": "교회는 그리스도의 몸이신 하나님께서 부르신 생명의 공동체입니다. 교회에 가입하는 것은 하나님께서 우리를 세우시는 중요한 방법입니다. 이 수업은 교회에 대한 올바른 관점과 헌신의 의미를 정립한다. 교회에서 영적인 집을 찾을 수 있기를 바랍니다. 사랑으로 서로를 세우고 함께 천국에 가요.", "instructions": "", "guide": [{"title": "왜 누군가가 교회에 가입하기를 원하지 않는가?", "points": ["시간이 많이 걸리고, 부상을 두려워하고, 너무 피곤해지는 것을 두려워한다.", "교회에 험담이 있고, 파티를 나누고, 애호가들에게 짐을 쌓고 있습니다.", "그러나 이러한 현상들이 교회 자체의 가치를 부정하지는 않는다."]}, {"title": "교회란 무엇인가?", "points": ["그리스어 원어 의미: 하나님의 부르심을 받은 사람들의 모임", "그것은 삶의 공동체이지 관심의 공동체가 아닙니다.", "교회는 건물이고, 교회는 영적 삶의 집합체입니다."]}, {"title": "교회는 완벽한 장소가 아닙니다.", "points": ["고린도 교회 지부, 라오디게아 교회 미지근함", "그러나 교회는 거룩함과 완전함의 표준으로 나아가는 곳입니다.", "하나님께서는 만족스럽지 못한 교회를 버리지 않으시고 참된 말씀으로 교회를 계속 세우셨습니다."]}, {"title": "몸의 비유: 서로 구축하기", "points": ["고린도전서 12:21: 눈은 상대방에게 내가 당신을 필요로 하지 않는다고 말할 수 없습니다.", "신체의 기능을 수행하기 위해 서로 다른 선물이 결합됩니다.", "교회에서 준비하고 빛으로 소금을 만들기 위해 어디든 가세요"]}, {"title": "수직 vs. 수평", "points": ["가장 큰 계명: 하나님을 사랑하고, 둘째로 다른 사람을 네 몸과 같이 사랑하라 (마태복음 22:37 -38)", "관계는 하나님과의 관계를 반영합니다", "대화 도중 변경됨: 옛 사람을 벗고 새 사람을 입음"]}, {"title": "봉사의 진실", "points": ["거래가 아님: 더 많은 일을 하는 것은 성경의 표준이 아닙니다.", "로마서 12: 1: 당신의 몸을 산 제물로 바치십시오", "섬김은 복된 길입니다: 사람은 섬김으로 세워집니다"]}, {"title": "일요일과 친교: 모두, 선택의 여지가 없음", "points": ["주일 예배: 진리 영접, 친교 모임: 진리 실천 배우기", "영적 성숙은 얼마나 많이 암기하느냐가 아니라 얼마나 많이 사느냐에 달려 있습니다.", "빌립보서 2: 4: 각 사람은 자신의 일에만 집중하지 말고 다른 사람들의 일에도 집중해야합니다."]}], "quizzes": [{"q": "[Scripture Fill in the blanks] 마음과 영혼과 뜻을 다하여 주님을 사랑해야 합니다.", "s": "가장 위대한 계명"}, {"q": "[Scripture Fill in the Blank] 하나님의 자비하심으로 ________ 을 ________ 로 바치시기를 권고합니다. 물론 이렇게 섬기는 것은 당연한 일입니다.", "s": "나만의 몸 만들기"}, {"q": "[Scripture Fill in the Blank] 나는 심었고, ________ 물을 주었으며, 오직 하나님만이 그를 ________ 라고 부르셨다.", "s": "하나님께서는 그에게 성장하라고 말씀하셨습니다."}, {"q": "교회의 원래 그리스어 의미는 하나님의 ________ 에서 온 사람들의 그룹이 함께 모였다는 것입니다.", "s": "교회의 정의"}, {"q": "교회는 ________ 의 장소가 아니라 거룩함과 완전함의 표준을 향한 진보의 장소입니다.", "s": "교회의 진리"}, {"q": "그레이엄 목사는 이렇게 말했습니다. “세상에 완벽한 교회는 없습니다. 교회가 있다면 여러분이 ________ 하는 날부터는 교회가 완벽하지 않을 것입니다.", "s": "완벽한 교회는 없습니다"}, {"q": "에베소서 계시: 그리스도는 교회의 ________ 이며, 교회는 그리스도의 몸입니다.", "s": "그리스도와 교회"}, {"q": "봉사는 하나님과 함께하는 _________________________________________________________________________", "s": "봉사의 본질"}, {"q": "빌립보서는 각 사람이 자신의 일에만 집중하지 말고 ________ 에도 집중해야 한다고 가르칩니다.", "s": "서로를 보살피며"}, {"q": "교회와 일반 공동체의 근본적인 차이는 무엇인가?", "s": "교회 및 사회", "o": "A.더 많은 수의 교회,B.공동체는 관심으로 결합되어 있고, 교회는 새로운 영적 삶으로 결합된 삶의 공동체입니다.,C.교회 건물이 더 큽니다,D.클럽 이용료, 교회 무료"}, {"q": "이 수업에서 교회에서 부상을 당하는 것에 대한 권고는 무엇인가?", "s": "상해에 직면", "o": "A.더 이상의 부상을 피하기 위해 즉시 교회를 떠나라.,B.주님 곁에서 다시 일어서고, 자신을 돌아보고, 주님 앞에 서서, 주님의 단언에 집중한다.,C.치아에 대한 치아, 다시 비판,D.그 이후로 청중만 서비스를 중단했습니다."}, {"q": "주일 예배와 친교 그룹은 어떤 관계가 있는가?", "s": "주일 및 친교", "o": "A.둘 중 하나를 선택하십시오. 하나에 참여하는 것으로 충분합니다.,B.주님의 날은 진리를 영접하는 데 초점을 맞추고, 교제는 진리를 실천하는 법을 배우는 데 초점을 맞춥니다. 두 기능은 다르므로 간과할 수 없습니다.,C.펠로우십은 성경 공부 수업의 반복일 뿐입니다.,D.온라인으로 쇼를 시청하는 것은 두 가지 모두를 대체할 수 있습니다."}, {"q": "교회에 합류하는 것이 하나님께서 우리를 세우시는 중요한 방법인 이유는 무엇인가? (복수 선택)", "s": "교회에 가입해야 하는 이유", "o": "A.성도들의 은사는 다르며, 그리스도의 몸 안에서 서로를 위한 장비를 구축합니다.,B.삶은 사람들과의 측면 관계에서 갱신되고 변화됩니다.,C.수평적 관계는 하나님과의 수직적 관계를 반영합니다,D.교회는 다치지 않는 완벽한 성도로 가득합니다."}, {"q": "다음 중 이 수업에서 정정된 서비스에 대한 잘못된 견해는 무엇입니까? (복수 선택)", "s": "서비스에 대한 잘못된 견해", "o": "A.하나님에 대한 더 많은 거래적 서비스, 하나님에 대한 더 많은 거래적 서비스,B.교회를 무대로 자신의 재능을 보여주세요,C.다른 사람들과 짝을 짓고 싶지 않고 혼자서만 할 의향이 있습니다.,D.봉사하기 전에 자신을 산 제물로 바치십시오"}, {"q": "교회는 건물이고, 교회는 영적 삶의 집합체이며, 이 둘을 혼동해서는 안 됩니다.", "s": "교회 & 교회"}, {"q": "온라인 설교를 시청하는 것은 교회 주일 예배 참석과 친교를 완전히 대체할 수 있습니다.", "s": "교체 불가"}, {"q": "바울은 “나를 심판하시는 분은 주님이시다.” 라고 말합니다. 그러므로 교회를 섬길 때, 사람들의 판단에 얽매이지 말고 주님을 바라보십시오.", "s": "주님께 초점 맞추기"}, {"q": "왜 그리스도인들이 교회에 가입해야 하는가? 이 수업의 지침을 결합하십시오.", "s": "교회에 가입하기"}, {"q": "성경적 봉사의 개념을 설명해 주십시오.", "s": "서비스 개념"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773056511541','基要真理','第十六课 灵修，祷告，见证','灵修是每天亲近神、建立关系；祷告包括赞美、感恩、代祷、认罪，不只祈求。本课学习稳定的祷告生活，并为作见证。愿你的祷告生活日益亲密有力。作盐作光，将福音传给万人。','[{"type": "verse", "q": "应当一无________，只要凡事借着________、祈求和感谢，将你们所要的告诉神。神所赐________的平安，必在基督耶稣里保守你们的心怀意念。", "o": "《腓立比书》4章6节", "s": "一无挂虑", "a": "挂虑|祷告|出人意外"}, {"type": "verse", "q": "神是个________，所以拜他的必须用________和________拜他。", "o": "《约翰福音》4章24节", "s": "心灵诚实", "a": "灵|心灵|诚实"}, {"type": "verse", "q": "那税吏远远地站着，连举目望天也不敢，只捶着胸说：________，________我这个罪人。", "o": "《路加福音》18章13节", "s": "税吏祷告", "a": "神啊|开恩可怜"}, {"type": "fill", "q": "基督徒的灵修就是属灵生命的________，让人从神而来的新生命在今生发挥功能。", "o": "", "s": "灵修定义", "a": "操练"}, {"type": "fill", "q": "灵修式的读经与研经式的查经不一样：教会每天鼓励15分钟灵修，但要全面明白神的话，教会需要有________来系统教导。", "o": "", "s": "查经学习", "a": "成人主日学"}, {"type": "fill", "q": "祷告的内容很丰富，除了祈求之外，还包括赞美、感恩、________和认罪。", "o": "", "s": "祷告内容", "a": "代祷"}, {"type": "fill", "q": "祷告不是去改变神，而是让神来改变________。", "o": "", "s": "祷告目的", "a": "我们"}, {"type": "fill", "q": "见证不是告诉别人基督徒都是成功的，而是我在同样的处境里，能靠主胜过环境，活出不一样的________。", "o": "", "s": "见证真义", "a": "生命"}, {"type": "fill", "q": "亚伯拉罕被称为信心之父，他在创世记第15章________神的话，神就算他为义。", "o": "", "s": "信心之父", "a": "信"}, {"type": "single", "q": "关于灵修与查经的关系，以下哪项说法正确？", "o": "A.灵修就是查经，每天15分钟足以全面明白圣经,B.灵修是来到神面前亲近祂、建立关系，查经是系统明白神的话，两者不同,C.灵修只需要读经，不需要祷告,D.一年读完圣经四遍就是最好的灵修方式", "s": "灵修查经", "a": "B"}, {"type": "single", "q": "关于祷告的正确态度，以下哪项最符合圣经？", "o": "A.祷告是把神该做的事告诉祂,B.祷告就是用华丽的辞藻背诵经文给人听,C.祷告是孩子真诚地来到天父面前，用心灵和诚实与祂交谈,D.祷告时背的经文越多，生命就越属灵", "s": "祷告态度", "a": "C"}, {"type": "single", "q": "以下哪一项最能说明基督徒的见证？", "o": "A.基督徒从不生病、从不失败,B.基督徒一定比别人富有成功,C.在同样的压力和处境中，靠主活出不一样的生命力,D.向所有人宣告自己是基督徒", "s": "见证真义", "a": "C"}, {"type": "multiple", "q": "祷告的内容包括以下哪些？（多选）", "o": "A.赞美,B.感恩,C.代祷,D.只为自己的需要祈求", "s": "祷告内容", "a": "A|B|C"}, {"type": "multiple", "q": "以下哪些是灵修生活带来的益处？（多选）", "o": "A.提醒自己是属乎神的新造的人,B.明白神藉着话语向我们说的话,C.学会分辨神的声音,D.保证每天都有特别的亮光", "s": "灵修益处", "a": "A|B|C"}, {"type": "judge", "q": "灵修就是每天花15分钟读经，等于查经，所以不需要教会的成人主日学。", "o": "", "s": "灵修查经", "a": "错"}, {"type": "judge", "q": "祷告完了之后，可以安静一段时间，等候神藉着经文和圣灵的感动提醒我们。", "o": "", "s": "祷告等候", "a": "对"}, {"type": "judge", "q": "基督徒的见证是说自己从不失败、永远成功。", "o": "", "s": "见证真义", "a": "错"}, {"type": "essay", "q": "为什么说灵修不是查经？两者有什么区别？", "o": "", "s": "灵修查经", "a": "灵修是每天来到神面前亲近祂、建立关系，提醒自己是新造的人，领受神藉着话语的提醒；查经是系统地明白整本圣经的真理，需要教会透过成人主日学有次序地教导。每天只读15分钟很难全面明白圣经，所以灵修不能代替查经。"}, {"type": "essay", "q": "根据本课，基督徒的见证是什么？请举例说明。", "o": "", "s": "见证真义", "a": "见证不是宣告自己成功或从不失败，而是在同样的处境里活出不一样的生命力。例如在硅谷同样高压工作的工程师中，基督徒靠着圣经真理和圣灵的工作，能有智慧有力量面对压力，处理好夫妻关系和金钱，这就是见证。"}]','https://youtu.be/YWFhmc_m6Ks
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.7730551344aKi','quiz','[{"points": ["灵修是属灵生命的操练，帮助神赐的新生命在今生发挥功能", "不是临时抱佛脚，而是一生持续的操练", "灵修不是查经：灵修是亲近神，查经是系统明白神的话"], "title": "灵修的定义：属灵生命的操练"}, {"points": ["灵修式读经：每天十几分钟，亲近神、建立关系", "查经式读经：系统教导、全面明白整本圣经，是教会的责任", "圣经不是签书；整本圣经都应好好读，不可偏废"], "title": "灵修与查经的区别"}, {"points": ["提醒自己是属乎神的新造的人", "明白属天原则，作为行事为人的标准", "与神关系亲近，才能辨别神的声音"], "title": "灵修的功能：提醒与辨别"}, {"points": ["祷告内容丰富：祈求、赞美、感恩、代祷、认罪", "祷告不是告诉神该做什么，神是全知的", "祷告是让神告诉我们该做什么；改变的是我们，不是神"], "title": "祷告不只是祈求"}, {"points": ["税吏的祷告：“神啊，开恩可怜我这个罪人”（路18:13）", "不需要华丽辞藻堆砌，那是表演不是祷告", "用心灵和诚实祷告；忧伤痛悔的心，主必不轻看"], "title": "真诚的祷告"}, {"points": ["祷告后要安静等候神的回应", "腓4:6-7：出人意外的平安保守心怀意念", "外在形式不是绝对；群体中要顾念他人感受"], "title": "祷告是双向的"}, {"points": ["见证不是成功神学，而是在同样处境中活出不一样的生命", "基督徒也会生病、赔钱，但不随之起伏", "生命改变需要时间累积；亚伯拉罕信心累积的榜样"], "title": "活出见证"}]','','16','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 16 Devotional, Prayer, Witness", "content": "Devotionals are daily intimacy and relationships with God; prayer includes praise, gratitude, intercession, confession, and not just pleading. This lesson is about living a steady prayerful life and bearing witness to it. May your prayer life grow closer and stronger. Salt is light, and the gospel is preached to all men.", "instructions": "", "guide": [{"title": "Spiritual Definition: Spiritual Life Exercises", "points": ["Spiritual practice is the practice of spiritual life, helping God-given new life to function in this life", "Not a temporary Buddha-footing, but a lifelong drill", "Spiritual practice is not biblical study: spiritual practice is to be close to God, and biblical study is to systematically understand God''s words"]}, {"title": "The difference between devotional practice and Bible study", "points": ["Devotional Bible Reading: Dozens of minutes a day to get close to God and build relationships", "Biblical Reading: It is the Church''s responsibility to teach systematically and comprehensively the entire Bible", "The Bible is not a signed book; the whole Bible should be read, not scrapped"]}, {"title": "The Function of Spirituality: Reminder and Discernment", "points": ["Remind yourself that you are a new creation of God", "Understanding the Heavenly Principle, Standards for Acting as a Person", "A close relationship with God allows us to discern God''s voice"]}, {"title": "Prayer is more than just praying", "points": ["Prayer rich: prayer, praise, gratitude, intercession, confession", "Prayer does not tell God what to do, God is omniscient", "Prayer is about letting God tell us what to do; it''s us who change, not God."]}, {"title": "Sincere Prayer", "points": ["Tax collector''s prayer: “God, have mercy on me, a sinner” (Luke 18:13)", "You don''t need gorgeous rhetoric, it''s a performance, not a prayer", "Pray with heart and honesty; the Lord will not despise a broken and contrite heart."]}, {"title": "Prayer is two-way", "points": ["Wait quietly for God''s response after prayer", "Philippians 4: 6-7: Unexpected peace of mind", "The external form is not absolute; the feelings of others should be taken into account in the group"]}, {"title": "Living Testimonials", "points": ["Testimony is not a prosperity theology, but living a different life in the same situation", "Christians get sick and lose money, but they don''t go with it.", "Life change takes time to accumulate; Abraham''s example of accumulated faith"]}], "quizzes": [{"q": "There should be no ________, as long as you tell God what you want by means of ________, prayer, and thanksgiving. The peace of God ________ will guard your hearts and minds in Christ Jesus.", "s": "No worries"}, {"q": "God is a ________, so one must worship Him with ________ and ________.", "s": "Honesty of Heart"}, {"q": "The tax collector stood far away, not daring to even lift his eyes to the heavens, only punching his chest and saying: ________, ________ I am a sinner.", "s": "Tax Collector''s Prayer"}, {"q": "Christian spirituality is the ________ of spiritual life, allowing new life from God to function in this life.", "s": "Spiritual Definition"}, {"q": "Devotional reading is different from scriptural study: the church encourages 15 minutes of devotional practice every day, but to fully understand the word of God, the church needs to have ________ to teach systematically.", "s": "Scripture Study"}, {"q": "Prayer is rich and includes, in addition to prayer, praise, gratitude, ________, and confession.", "s": "Prayer Content"}, {"q": "Prayer is not about changing God, but about letting God change ________.", "s": "Purpose of Prayer"}, {"q": "Testimony is not to tell others that Christians are successful, but that I can rely on the Lord to overcome the environment in the same situation and live a different ________.", "s": "Witness the Truth"}, {"q": "Abraham was called the father of faith, and God justified him by his word in Genesis 15 ________.", "s": "Father of Faith"}, {"q": "Which of the following statements is true about the relationship between spiritual practice and Bible study?", "s": "Spiritual Sutras", "o": "A.Devotionals are Bible studies, 15 minutes a day is enough to fully understand the Bible,B.Spiritual practice is to come to God to be close to Him and establish relationships. Bible study is to systematically understand God''s words. The two are different.,C.Devotionals only need to read the Bible, not pray,D.Reading the Bible four times a year is the best way to practice spirituality"}, {"q": "Which of the following is most biblical about the right attitude to prayer?", "s": "Prayer Attitude", "o": "A.Prayer is telling God what to do,B.Prayer is the recitation of Scripture in gorgeous words.,C.Prayer is when the child comes sincerely to Heavenly Father and speaks to Him in spirit and honesty.,D.The more verses you recite during prayer, the more spiritual your life becomes."}, {"q": "Which of the following best describes a Christian''s testimony?", "s": "Witness the Truth", "o": "A.Christians never get sick and never fail.,B.Christians must be more successful than others,C.In the same stress and situation, live with different vitality from the Lord,D.Declare yourself a Christian to everyone"}, {"q": "What does the prayer include? (Multiple choice)", "s": "Prayer Content", "o": "A.Praise,B.Thanksgiving,C.Intercessory prayer.,D.Pray only for your own needs"}, {"q": "Which of the following are benefits of living a spiritual life? (Multiple choice)", "s": "Devotional Benefits", "o": "A.Remind yourself that you are a new creation of God,B.Understand what God is saying to us through His Word,C.Learn to distinguish between the voices of God,D.Guarantee a special light every day"}, {"q": "Devotional practice is 15 minutes of Bible reading per day, which is equivalent to Bible study, so there is no need for adult Sunday school in the church.", "s": "Spiritual Sutras"}, {"q": "After praying, you can be quiet for a while, waiting for God to remind us through the scriptures and the Holy Ghost.", "s": "Prayer Waiting"}, {"q": "The Christian testimony is that he never fails and always succeeds.", "s": "Witness the Truth"}, {"q": "Why is spirituality not a Bible study? What''s the difference?", "s": "Spiritual Sutras"}, {"q": "According to this lesson, what is a Christian''s testimony? Give me an example.", "s": "Witness the Truth"}]}, "ja": {"title": "レッスン16献身，祈り，証", "content": "ディボーショナルとは，日々の親密さと神との関係です。祈りには，賛美，感謝，執り成し，告白が含まれ，嘆願だけではありません。このレッスンでは，安定した祈りに満ちた生活を送り，それを証することについて学びます。あなたの祈りの生活がより近づいて強くなりますように。塩は軽く，福音はすべての人に宣べ伝えられています。", "instructions": "", "guide": [{"title": "霊的な定義：霊的な生活の練習", "points": ["霊的な実践とは，霊的な生活の実践であり，神が与えられた新しい生活がこの生活の中で機能するのを助けます", "一時的な仏足ではなく、生涯にわたる訓練", "霊的な実践は聖書的な研究ではありません：霊的な実践は神に近づくことであり、聖書的な研究は神の言葉を体系的に理解することです"]}, {"title": "献身的な実践と聖書研究の違い", "points": ["ディボーショナル聖書朗読： 1日に数十分，神に近づき，人間関係を築く", "聖書の読み方：聖書全体を体系的かつ包括的に教えることは教会の責任です", "聖書は署名された本ではありません。聖書全体を読むべきであり、廃棄すべきではありません"]}, {"title": "霊性の機能：思い出させと識別", "points": ["あなたは神の新しい創造物であることを思い出してください", "天の原則，人として行動するための基準を理解する", "神との密接な関係は、神の声を見分けることを可能にします"]}, {"title": "祈りは単なる祈りではありません", "points": ["豊かな祈り：祈り、賛美、感謝、執り成し、告白", "祈りは神に何をすべきかを告げるものではありません。神は全知です", "祈りとは、何をすべきかを神に指示させることです。神ではなく、私たちが変わるのです。"]}, {"title": "誠実な祈り", "points": ["徴税人の祈り：「神よ，罪人であるわたしを憐れんでください」（ルカ18 ： 13 ）", "ゴージャスなレトリックは必要ありません。祈りではなく、パフォーマンスです", "心と正直さをもって祈りなさい。主は傷ついた悔い改めた心を軽んじられることはありません。"]}, {"title": "祈りは双方向です", "points": ["祈りの後に神の応答を静かに待つ", "ピリピ4 ： 6 － 7 ：思いがけない安らぎ", "外形は絶対的なものではなく、グループ内で他者の感情を考慮する必要があります"]}, {"title": "生きた証", "points": ["証は繁栄神学ではなく，同じ状況で異なる人生を送ることです", "キリスト教徒は病気になり、お金を失いますが、それには賛成しません。", "人生の変化は蓄積するのに時間がかかります。アブラハムの蓄積された信仰の例"]}], "quizzes": [{"q": "あなたが望むことを________、祈り、感謝祭を通して神に伝える限り、________はあってはなりません。神の平安は，キリスト・イエスにあってあなたの心と思いを守ります。", "s": "ご安心ください"}, {"q": "神は________であるため、________と________をもって神を礼拝しなければなりません。", "s": "心の正直さ"}, {"q": "徴税人は遠くに立って、あえて天に目を向けることさえしませんでした。ただ胸を殴り、「________、________私は罪人です。", "s": "徴税人の祈り"}, {"q": "キリスト教の霊性は霊的生活の________であり，神からの新しい生活がこの生活の中で機能することを可能にします。", "s": "霊的な定義"}, {"q": "献身的な読書は聖文研究とは異なります。教会は毎日15分間の献身的な実践を奨励していますが、神の言葉を完全に理解するためには、体系的に教えるために________が必要です。", "s": "聖文研究"}, {"q": "祈りは豊かで，祈りに加えて賛美，感謝， ________ ，告白を含みます。", "s": "祈りの内容"}, {"q": "祈りとは神を変えることではなく、神に________を変えることです。", "s": "祈りの目的"}, {"q": "証とは，クリスチャンが成功していることを他の人に伝えることではなく，同じ状況で環境を克服し，異なる________を生きるために主に頼ることができるということです。", "s": "真実を目撃する"}, {"q": "アブラハムは信仰の父と呼ばれ，神は創世記15章________節の御言葉によってアブラハムを義とされました。", "s": "信仰の父"}, {"q": "霊的な実践と聖書研究の関係について，次の記述のうち，正しいものはどれですか。", "s": "スピリチュアル・スートラ", "o": "A.ディボーショナルは聖書研究であり、1日15分で聖書を完全に理解するのに十分です,B.霊的な実践は、神に近づき、関係を確立するために神のもとに来ることです。聖書研究は、神の言葉を体系的に理解することです。2つは異なります。,C.ディボーショナルは、祈るのではなく、聖書を読むだけでよい,D.年に4回聖書を読むことは，霊性を実践するための最良の方法です"}, {"q": "祈りに対する正しい態度について，聖書に最も当てはまるものは次のうちどれですか。", "s": "祈りの態度", "o": "A.祈りとは，神に何をすべきかを告げることです,B.祈りとは，豪華な言葉で聖句を暗唱することです。,C.祈りとは，子供が誠実に天の御父のもとに来て，霊と誠実さをもって御父に語ることです。,D.祈りの間に暗唱する聖句が多いほど，あなたの人生はより霊的になります。"}, {"q": "次のうち，クリスチャンの証に最も当てはまるものはどれですか。", "s": "真実を目撃する", "o": "A.クリスチャンは決して病気にならず、失敗することもありません。,B.クリスチャンは他の人よりも成功しなければなりません,C.同じストレスや状況の中で，主とは異なる活力をもって生きる,D.すべての人に自分がクリスチャンであることを宣言する"}, {"q": "祈りには何が含まれていますか。（複数選択可）", "s": "祈りの内容", "o": "A.好意的なコメント,B.感謝の気持ち,C.執り成しの祈り,D.自分の必要のためだけに祈る"}, {"q": "次のうち，霊的な生活を送ることの利点はどれですか。（複数選択可）", "s": "献身的なメリット", "o": "A.あなたは神の新しい創造物であることを思い出してください,B.神が御言葉を通してわたしたちに語っておられることを理解する,C.神の声を区別する方法を学ぶ,D.毎日特別な光を確保"}, {"q": "ディボーショナルの練習は1日15分の聖書読書で、聖書研究に相当するので、教会では大人の日曜学校は必要ありません。", "s": "スピリチュアル・スートラ"}, {"q": "祈りの後，しばらく静かにして，聖文と聖霊を通して神がわたしたちに思い出させてくださるのを待つことができます。", "s": "祈りの待ち時間"}, {"q": "クリスチャンの証は、彼は決して失敗せず、常に成功するということです。", "s": "真実を目撃する"}, {"q": "なぜ霊性は聖書研究ではないのでしょうか。違いは何ですか？", "s": "スピリチュアル・スートラ"}, {"q": "この課によると，クリスチャンの証とは何でしょうか。例を挙げてください。", "s": "真実を目撃する"}]}, "ko": {"title": "제 16과 영적 모임, 기도, 증인", "content": "영적 모임은 매일의 친밀함과 하나님과의 관계입니다. 기도는 단순히 간청하는 것이 아니라 찬양, 감사, 전구, 고백을 포함합니다. 이 수업은 꾸준히 기도하는 삶을 살고 이를 증언하는 것입니다. 여러분의 기도 생활이 더욱 가까워지고 강해지기를 바랍니다. 소금은 빛이며, 복음은 모든 사람에게 전파됩니다.", "instructions": "", "guide": [{"title": "영적 정의: 영적인 삶 연습", "points": ["영적 실천은 하나님께서 주신 새로운 생명이 이생에서 기능하도록 돕는 영적 삶의 실천입니다.", "일시적인 부처님 발자국이 아닌 평생의 훈련", "영적 연습은 성경 공부가 아닙니다. 영적 연습은 하나님과 가까워지는 것이고, 성경 공부는 하나님의 말씀을 체계적으로 이해하는 것입니다."]}, {"title": "영적 모임과 성경공부의 차이점", "points": ["영적 성경 봉독: 하나님과 가까워지고 관계를 형성하는 데 하루에 수십 분", "성경 읽기: 전체 성경을 체계적이고 포괄적으로 가르치는 것은 교회의 책임입니다.", "성경은 서명된 책이 아닙니다. 성경 전체를 폐기하지 말고 읽어야 합니다."]}, {"title": "영성의 기능: 상기와 식별", "points": ["당신이 하나님의 새로운 창조물임을 상기시키십시오.", "하늘의 원리, 사람으로서 행동하는 기준 이해하기", "하나님과의 긴밀한 관계를 통해 하나님의 음성을 분별할 수 있습니다."]}, {"title": "기도는 단순히 기도하는 것 그 이상입니다.", "points": ["풍부한 기도: 기도, 찬양, 감사, 전구, 고백", "기도는 하나님께 무엇을 해야 할지 알려주지 않습니다. 하나님은 전지전능하십니다.", "기도는 하느님께서 우리에게 무엇을 하라고 말씀하시게 하는 것입니다. 하느님이 아니라 우리가 변화하는 것입니다."]}, {"title": "진실한 기도", "points": ["세리의 기도: “하나님, 죄인인 저를 불쌍히 여기소서” (누가복음 18:13)", "화려한 수사는 필요하지 않습니다. 기도가 아닌 공연입니다.", "마음과 정직으로 기도하십시오. 주님은 상하고 통회하는 마음을 경멸하지 않으실 것입니다."]}, {"title": "기도는 양방향입니다", "points": ["기도 후 하나님의 응답을 조용히 기다리십시오.", "빌립보서 4: 6 ~ 7: 뜻밖의 마음의 평화", "외부 형태는 절대적이지 않습니다. 다른 사람들의 감정을 그룹에서 고려해야 합니다."]}, {"title": "살아있는 추천사", "points": ["간증은 번영 신학이 아니라 동일한 상황에서 다른 삶을 사는 것입니다.", "그리스도인들은 병에 걸리고 돈을 잃지만, 그것과 함께 가지 않습니다.", "삶의 변화는 축적되는 데 시간이 걸립니다. 축적된 믿음에 대한 아브라함의 모범"]}], "quizzes": [{"q": "________, 기도 및 감사를 통해 원하는 것을 하나님 께 말하면 ________ 은 (는) 없어야합니다. 하나님의 평강 ________ 은 그리스도 예수 안에서 여러분의 마음과 생각을 지킬 것입니다.", "s": "걱정하지 마세요"}, {"q": "하나님은 ________ 이시기 때문에 ________ 와 ________ 로 그분을 경배해야 합니다.", "s": "마음의 정직"}, {"q": "세리는 감히 눈을 들어 하늘을 쳐다보지도 못하고 멀찍이 서서 가슴을 치며 말했다. ________, ________ 나는 죄인이다.", "s": "세금 징수원의 기도"}, {"q": "그리스도인의 영성은 영적 삶의 ________ 이며, 이 삶에서 하나님의 새로운 삶이 작동하도록 허용합니다.", "s": "영적 정의"}, {"q": "경전 읽기는 경전 공부와 다릅니다. 교회는 매일 15분씩 경전 연습을 장려하지만, 하나님의 말씀을 완전히 이해하려면 교회가 체계적으로 가르칠 ________ 가 있어야 합니다.", "s": "경전 공부"}, {"q": "기도는 풍부하며 기도, 찬양, 감사, ________, 고백을 포함합니다.", "s": "기도 내용"}, {"q": "기도는 하나님을 변화시키는 것이 아니라 하나님이 ________ 을 (를) 변화시키게 하는 것입니다.", "s": "기도의 목적"}, {"q": "간증은 그리스도인이 성공했다고 다른 사람들에게 말하는 것이 아니라 동일한 상황에서 환경을 극복하고 다른 ________ 을 (를) 살기 위해 주님을 의지할 수 있다는 것입니다.", "s": "진실을 목격하라"}, {"q": "아브라함은 믿음의 조상이라고 불렸고, 하나님께서는 창세기 15장 ________ 에서 그의 말씀으로 그를 의롭게 하셨습니다.", "s": "믿음의 아버지"}, {"q": "다음 중 영적 실천과 성경 공부의 관계에 대한 설명으로 옳은 것은?", "s": "영적인 수트라", "o": "A.영적 모임은 성경 공부이며, 하루에 15분만 투자하면 성경을 완전히 이해할 수 있습니다.,B.영적인 실천은 하나님과 가까워지고 관계를 맺기 위해 하나님께 나아가는 것입니다. 성경공부는 하나님의 말씀을 체계적으로 이해하는 것입니다. 이 둘은 다릅니다.,C.영적 모임은 기도가 아니라 성경을 읽기만 하면 됩니다.,D.1년에 4번 성경을 읽는 것이 영성을 실천하는 가장 좋은 방법입니다."}, {"q": "다음 중 기도에 대한 올바른 태도에 대해 가장 성경적인 것은 무엇인가?", "s": "기도 태도", "o": "A.기도는 하나님께 무엇을 해야 할지 말씀드리는 것입니다.,B.기도는 멋진 말로 성경을 암송하는 것입니다.,C.기도는 자녀가 하나님 아버지께 진심으로 나아가 영과 정직으로 그분께 말할 때입니다.,D.기도 중에 더 많은 구절을 암송할수록 여러분의 삶은 더 영적이 됩니다."}, {"q": "다음 중 그리스도인의 간증을 가장 잘 설명한 것은 무엇입니까?", "s": "진실을 목격하라", "o": "A.그리스도인은 결코 아프지 않고 결코 실패하지 않습니다.,B.그리스도인은 다른 사람들보다 더 성공적이어야 합니다.,C.동일한 스트레스와 상황에서 주님과 다른 활력을 가지고 살아가십시오.,D.모든 사람에게 자신을 그리스도인으로 선언하십시오"}, {"q": "기도에는 무엇이 포함되는가? (복수 선택)", "s": "기도 내용", "o": "A.칭찬,B.감사,C.중보 기도,D.자신의 필요를 위해서만 기도하십시오"}, {"q": "다음 중 영적인 삶을 사는 것의 이점은 무엇인가? (복수 선택)", "s": "영적 혜택", "o": "A.당신이 하나님의 새로운 창조물임을 상기시키십시오.,B.말씀을 통해 하나님께서 우리에게 하시는 말씀 이해하기,C.하나님의 음성을 구별하는 법 배우기,D.매일 특별한 조명을 보장하세요"}, {"q": "영적 수련은 하루에 15분씩 성경을 읽는 것으로 성경공부와 같기 때문에 교회에서 성인 주일학교를 할 필요가 없습니다.", "s": "영적인 수트라"}, {"q": "기도한 후에는 경전과 성신을 통해 하느님께서 우리에게 상기시켜 주실 때까지 기다리면서 잠시 동안 조용히 있을 수 있습니다.", "s": "기도 대기 중"}, {"q": "그리스도인의 간증은 그가 결코 실패하지 않고 항상 성공한다는 것입니다.", "s": "진실을 목격하라"}, {"q": "왜 영성은 성경 공부가 아닌가? 차이점은 무엇인가요?", "s": "영적인 수트라"}, {"q": "이 수업에 따르면, 그리스도인의 간증은 무엇인가? 예를 들어주세요.", "s": "진실을 목격하라"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773056921986','基要真理','第十七课 服事与生命','服事不是与神交换的筹码，而是神赐的礼物。本课讲服事的正确心态，在配搭中学习谦卑，让生命被神塑造。愿你在服事中找到喜乐与成长。甘心乐意，成为多人的祝福。','[{"type": "verse", "q": "弟兄们，我以神的慈悲劝你们，将身体________，当作________。你们如此事奉，乃是________的。", "o": "《罗马书》12章1节", "s": "活祭事奉", "a": "献上|活祭|理所当然"}, {"type": "verse", "q": "神既不爱惜自己的儿子为我们众人舍了，岂不也把________一同白白地________我们吗？", "o": "《罗马书》8章32节", "s": "神白白赐恩", "a": "万物|赐给"}, {"type": "verse", "q": "你们或吃或喝，无论做什么，都要为________而行。", "o": "《哥林多前书》10章31节", "s": "荣耀神而行", "a": "荣耀神"}, {"type": "fill", "q": "服事从来不是拿来跟上帝________恩典的筹码，因为当我们还作罪人的时候，基督就为我们死了。", "o": "", "s": "服事本质", "a": "交换"}, {"type": "fill", "q": "在服事的互动配搭中，我们学习尊重、谦卑、看重别人，我们的品格和个性被________。", "o": "", "s": "生命被建造", "a": "改变"}, {"type": "fill", "q": "我们的服事是全人的：在教会是服事，在________、公司、学校也是服事。", "o": "", "s": "全人服事", "a": "家庭"}, {"type": "fill", "q": "保罗说：所求于管家的，是要他有________。", "o": "", "s": "忠心管家", "a": "忠心"}, {"type": "fill", "q": "那位在日本教会的弟兄因骄傲不练诗、只上台表演，后来出车祸伤了________，才学会谦卑。", "o": "", "s": "骄傲管教", "a": "喉咙"}, {"type": "fill", "q": "在教会的服事中，若看见弟兄有明显的罪却视而不见，不是真正的爱；真正的爱是按真理________，把他从错误中带回来。", "o": "", "s": "彼此劝勉", "a": "爱心说诚实话"}, {"type": "single", "q": "以下哪项最符合圣经中服事的意义？", "o": "A.用服事积功德，换取神的祝福,B.服事是神建造我们生命、改变我们品格的方法,C.服事越多，神就越喜欢我们,D.只有在教会里的服事才讨神喜悦", "s": "服事本质", "a": "B"}, {"type": "single", "q": "关于服事与才华展现，以下哪项说法正确？", "o": "A.服事就是把自己的才华展现给众人看,B.声音好的人在诗班只负责独唱就是最好的服事,C.服事是彼此建造，用恩赐帮助别人成长，而不是自我表演,D.有治理恩赐的人就该独揽财务大权", "s": "服事与表演", "a": "C"}, {"type": "single", "q": "那位整天泡在教会、家里衣服不洗孩子不顾的姐妹，牧者给她的劝勉是？", "o": "A.继续多多在教会服事，神必纪念,B.回到家里把母亲妻子的本分做好，在家里也是服事神,C.把孩子送到教会让别人带,D.减少奉献，把时间都给家庭", "s": "全人服事", "a": "B"}, {"type": "multiple", "q": "以下哪些属于全人服事的范围？（多选）", "o": "A.家庭主妇按属灵原则经营家庭,B.职员在公司正直忠心做事,C.学生在学业上努力并帮助同学,D.只有主日站在讲台上的服事", "s": "全人服事", "a": "A|B|C"}, {"type": "multiple", "q": "在服事中不容易受伤、眼光正确的表现包括？（多选）", "o": "A.看重神在我身上的作为，而不是人怎么看我,B.把服事当成交换恩典的筹码,C.在服事中学习被建造、被改变,D.计较自己做了多少、别人知不知道", "s": "服事心态", "a": "A|C"}, {"type": "judge", "q": "多奉献、多做圣工，神就会感动多给我们，这是圣经的真理。", "o": "", "s": "服事本质", "a": "错"}, {"type": "judge", "q": "每一项服事在神面前都是宝贵的，在厨房默默做饭与在讲台讲道一样重要。", "o": "", "s": "恩赐平等", "a": "对"}, {"type": "judge", "q": "教会的讲台可以成为个人才华展现的舞台。", "o": "", "s": "服事与表演", "a": "错"}, {"type": "essay", "q": "为什么说服事不是与神交换恩典的筹码？请说明理由。", "o": "", "s": "服事本质", "a": "因为当我们还作罪人、抵挡神的时候，神就把祂最宝贵的爱子赐给我们了；没有什么我们需要的东西比耶稣更宝贵，需要我们用服事去交换。服事是神赐给我们的方法，在服事中我们的生命被改变，改变后的生命才能领受神的赐福。"}, {"type": "essay", "q": "服事与才华展现有什么区别？请结合本课的例子说明。", "o": "", "s": "服事与表演", "a": "服事是彼此建造，用恩赐帮助别人成长；才华展现只是表现自己。日本那位声音很好的弟兄不练诗、只上台独唱是表演，不是服事；后来他学会谦卑，愿意分享所学、帮助别人，才是真正的服事。恩赐的目的是建造教会，不是自我彰显。"}]','https://youtu.be/FHp_K9bo2bs
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.7730551340OLx','quiz','[{"points": ["当我们还作罪人时，基督已为我们死（罗5:8），无需再拿什么交换", "天使做事比我们更好；神不缺我们做什么", "服事不是积功德、修桥补路换祝福"], "title": "服事不是交换恩典的筹码"}, {"points": ["在互动配搭中学习尊重、谦卑、看重别人", "品格个性被改变，这是服事最重要的意义", "眼光转向神就不易受伤"], "title": "服事是生命被改变的过程"}, {"points": ["家庭主妇、公司职员、学生各尽本分都是服事", "不要放下家庭本分专跑教会，那是本末倒置", "或吃或喝，都为荣耀神而行"], "title": "服事是全人的"}, {"points": ["诗班配合是服事，一个人出风头是表演", "厨房、打扫同样宝贵；所求于管家的是忠心", "你有什么不是领受的？不可自夸（林前4:7）"], "title": "服事不是才华展现"}, {"points": ["多奉献神就多给，不是圣经真理", "天天都在服事，没有多寡之分", "关键不在量的多少，而在方向是否正确"], "title": "破除“多做多得”的迷思"}, {"points": ["罗12:1：如此事奉乃是理所当然的", "像祭牲全然归主：心思意念作为都朝神的方向", "生命改变不是一蹴而就，在服事中渐渐被建造"], "title": "将身体献上当作活祭"}, {"points": ["爱心说诚实话：看见弟兄犯罪要挽回", "做工的人比工作更重要；圣洁生命是服事的前提", "拦下诗班弟兄、奉献炫耀的鉴戒"], "title": "彼此建造与圣洁生命"}]','','17','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 17 Serving and Life", "content": "Service is not a bargain with God, but a gift from God. This lesson is about the right mindset to serve, learning humility in pairing, and allowing life to be shaped by God. May you find joy and growth in your ministry. Be willing to be a blessing to many.", "instructions": "", "guide": [{"title": "Serving is not a bargaining chip", "points": ["When we were still sinners, Christ died for us (Romans 5: 8) and there was no need to exchange anything else for it.", "Angels do things better than we do; God doesn''t need what we do", "Serving is not accumulating merit, repairing bridges and repairing roads for blessings"]}, {"title": "Serving is a life-changing process", "points": ["Learn to be respectful, humble, and valued in your interactions", "Character personality is changed, which is the most important significance of service", "It is not easy to get hurt when your eyes turn to God"]}, {"title": "Serving is holistic", "points": ["Housewives, company employees, and students are all ministers.", "Don''t let the family run the church, it''s the end of the book inverted", "Eat or drink, all for the glory of God"]}, {"title": "Serving is not a talent show", "points": ["Choir cooperation is service, one person''s publicity is performance", "Kitchen, cleaning are equally valuable; what is asked of a housekeeper is loyalty", "What have you not received? Do not boast (1 Corinthians 4: 7)"]}, {"title": "Break the myth of doing more", "points": ["Giving more is giving more, not biblical truth", "They serve every day, and there is no difference between them.", "The key is not how much, but whether the direction is correct"]}, {"title": "Offer your body as a living sacrifice", "points": ["Ro 12: 1: Such service is taken for granted", "Like a sacrifice to return to the Lord completely: the heart, the mind, and the mind are all heading in the direction of God", "Life change does not happen overnight, it is gradually built in the service"]}, {"title": "Building each other and holy life", "points": ["Love Speaks Honestly: Seeing Brothers Committing Crimes to Redeem", "Workers are more important than work; a holy life is a prerequisite for service", "Stop the choirbrothers and dedicate their precepts to show off."]}], "quizzes": [{"q": "Brethren, I exhort you by the mercy of God to regard the body ________ as ________. You serve in this way, but ________.", "s": "Live Sacrifice Service"}, {"q": "Since God did not spare His own Son for us all, will He not also take ________ with us in vain ________ us?", "s": "God''s grace is free"}, {"q": "Whether you eat or drink, whatever you do, do it for ________.", "s": "Walk in the Glory of God"}, {"q": "Service is never a bargain for grace with God, for Christ died for us while we were still sinners.", "s": "The nature of service"}, {"q": "In the interactive collocation of ministry, we learn to respect, be humble, value others, and our character and personality are ________.", "s": "Life is built"}, {"q": "Our service is holistic: at church, at ________, at work, at school.", "s": "Whole-person service"}, {"q": "Paul said: What is asked of the steward is that he should have ________.", "s": "Faithful Butler"}, {"q": "The brother in the Japanese church learned to be humble because he did not practice poetry, only performed on stage, and later got injured in a car accident ________.", "s": "Pride Discipline"}, {"q": "In the service of the church, if you see that your brother has obvious sins but ignores them, it is not true love; true love is to bring him back from his mistakes according to the truth ________.", "s": "Encourage each other"}, {"q": "Which of the following best describes what it means to serve in the Bible?", "s": "The nature of service", "o": "A.Serve merit in exchange for God''s blessing,B.Serving is God''s way of building our lives and changing our character,C.The more we serve, the more God likes us.,D.Serving in the church is pleasing to God"}, {"q": "Which of the following statements is true about service and talent?", "s": "Ministries & Performances", "o": "A.Serving is showing your talents to everyone.,B.A good voice in a choir is best served by a soloist.,C.Service is about building each other up, using gifts to help others grow, not self-acting,D.Those who have the gifts of governance should have sole financial power"}, {"q": "What is the pastor''s exhortation to the sister who spends her days at church and at home washing her clothes and not caring for her children?", "s": "Whole-person service", "o": "A.Continue to serve more in the church, God will remember,B.Go home and do your duty as a mother and wife, and serve God at home.,C.Sending a child to church to be brought by someone else,D.Reduce dedication and give time to your family"}, {"q": "Which of the following falls under the scope of whole-person ministry? (Multiple choice)", "s": "Whole-person service", "o": "A.Housewives run their families according to spiritual principles,B.Employees work with integrity and loyalty at the company,C.Students work hard academically and help their classmates,D.Only the Sunday service standing on the podium"}, {"q": "Is it not easy to be injured in the service and behave correctly in the eyes, including? (Multiple choice)", "s": "Serving Mindset", "o": "A.Value what God does in me, not what people think of me,B.Treat service as a bargaining chip for grace,C.Learning to be built and transformed in service,D.Consider how much you have done, and whether others know it"}, {"q": "If we give more and do more sacred work, God will move more and give more to us. This is the truth of the Bible.", "s": "The nature of service"}, {"q": "Every service is precious before God, and silent cooking in the kitchen is as important as preaching from the pulpit.", "s": "Gift Equality"}, {"q": "The pulpit of the Church can be a stage for personal talent.", "s": "Ministries & Performances"}, {"q": "Why is persuasion not a bargaining chip for grace with God? Please explain.", "s": "The nature of service"}, {"q": "What is the difference between serving and showing talent? Please explain with an example from this lesson.", "s": "Ministries & Performances"}]}, "ja": {"title": "レッスン17奉仕と人生", "content": "奉仕は神との取引ではなく、神からの贈り物です。このレッスンでは，奉仕する正しい考え方，ペアリングで謙遜さを学び，人生を神によって形作ることができるようにすることについて学びます。ミニストリーで喜びと成長が得られますように。喜んで多くの人の祝福になるようにしましょう。", "instructions": "", "guide": [{"title": "サービングは交渉のチップではありません", "points": ["わたしたちがまだ罪人であったとき，キリストはわたしたちのために死なれ（ローマ5 ： 8 ） ，それ以外のものと交換する必要はありませんでした。", "天使は私たちよりも優れたことをします。神は私たちがすることを必要としません", "奉仕することは、メリットを蓄積したり、橋を修復したり、祝福のために道路を修復したりすることではありません"]}, {"title": "奉仕することは人生を変えるプロセスです", "points": ["やり取りにおいて、敬意を払い、謙虚であり、大切にすることを学びましょう", "キャラクターの性格が変わる、これが奉仕の最も重要な意義", "神に目を向けたときに傷つくことは容易ではありません"]}, {"title": "サービングは全体的なものです", "points": ["主婦、会社の従業員、学生はすべて大臣です。", "家族に教会を運営させないでください、それは本の終わりが反転しています", "食べるにも飲むにも，すべては神の栄光のために"]}, {"title": "サービングはタレントショーではありません", "points": ["合唱団の協力は奉仕、一人の宣伝は演奏", "キッチン、清掃も同様に価値があります。ハウスキーパーに求められるのは忠誠心です", "受け取っていないものは何ですか？自慢してはならない（ 1コリント4 ： 7 ）"]}, {"title": "より多くのことをするという神話を打ち破る", "points": ["より多くを与えることは、聖書の真理ではなく、より多くを与えることです", "毎日サービスを提供しており、違いはありません。", "重要なのは金額ではなく、方向が正しいかどうかです"]}, {"title": "生ける犠牲として自分の体を捧げる", "points": ["Ro 12 ： 1 ：そのようなサービスは当たり前だと考えられています", "完全に主に立ち返るための犠牲のようなものです：心、心、心はすべて神の方向に向かっています", "人生の変化は一夜にして起こるものではなく、徐々にサービスに組み込まれています"]}, {"title": "互いに築きあい、聖なる生活を送る", "points": ["愛は正直に語る：贖いのために罪を犯す兄弟たちを見る", "労働者は仕事よりも重要です。聖なる生活は奉仕の前提条件です", "聖歌隊の兄弟たちを止め、彼らの教えを誇示するために捧げましょう。"]}], "quizzes": [{"q": "兄弟たち，わたしは神の憐れみにより，体________を________とみなすよう勧めます。あなたはこのようにサービスを提供していますが、________。", "s": "生贄サービス"}, {"q": "神はわたしたちすべてのためにご自分の御子を惜しまれなかったので， ________も無駄にわたしたちと一緒に連れて行かれたのではないでしょうか。", "s": "神の恵みは自由です"}, {"q": "食べるにしても飲むにしても、何をするにしても、________のためにしてください。", "s": "神の栄光の中を歩む"}, {"q": "奉仕は決して神との恵みの取引ではありません。なぜなら、キリストは私たちがまだ罪人であったときに私たちのために死んでくださったからです。", "s": "サービスの性質"}, {"q": "ミニストリーのインタラクティブなコロケーションでは、私たちは尊敬し、謙虚になり、他者を大切にすることを学び、私たちの性格と人格は________です。", "s": "人生は築かれる"}, {"q": "私たちのサービスは、教会で、________で、職場で、学校で、全体的なものです。", "s": "まるまる貸切サービス"}, {"q": "パウロは言いました：スチュワードに求められているのは、彼が________を持つべきであるということです。", "s": "忠実な執事"}, {"q": "日本の教会の兄弟は、詩を練習せず、舞台でのみ演奏し、後に交通事故で負傷したため、謙虚になることを学びました________。", "s": "プライドの訓練"}, {"q": "教会への奉仕において，あなたの兄弟が明らかな罪を持っているのにそれを無視しているのを見れば，それは真の愛ではありません。真の愛とは，彼を真理________に従って過ちから連れ戻すことです。", "s": "お互いに励まし合う"}, {"q": "聖書で奉仕することの意味を最もよく表しているのは，次のうちどれですか。", "s": "サービスの性質", "o": "A.神の祝福と引き換えに功績を挙げる,B.奉仕することは，わたしたちの生活を築き，性格を変える神の方法です,C.わたしたちが奉仕すればするほど，神はわたしたちをより好んでくださるのです。,D.教会で奉仕することは神に喜ばれる"}, {"q": "サービスと才能について、次の記述のうち正しいものはどれですか？", "s": "ミニストリー＆パフォーマンス", "o": "A.奉仕とは、あなたの才能をすべての人に示すことです。,B.合唱団の良い声は、ソリストが演奏するのが一番です。,C.サービスとは、お互いを成長させることであり、贈り物を使って他の人を成長させることであり、自己行動ではありません,D.ガバナンスの才能を持っている人は、唯一の財政力を持つべきです"}, {"q": "教会や家で衣服を洗っていて，子供の世話をしていない姉妹に，牧師はどのように勧めていますか。", "s": "まるまる貸切サービス", "o": "A.教会でより多くの奉仕を続けてください。神は覚えておられます,B.家に帰って母と妻としての義務を果たし、家で神に仕えましょう。,C.誰かに連れて行かれるために子供を教会に送る,D.献身を減らし、家族に時間を与える"}, {"q": "次のうち、全人ミニストリーの範囲に該当するものはどれですか？ （複数選択可）", "s": "まるまる貸切サービス", "o": "A.主婦は霊的な原則に従って家族を経営する,B.従業員は会社で誠実さと忠誠心を持って働く,C.生徒は学業に熱心に取り組み、クラスメートを助けます,D.表彰台に立つ日曜礼拝のみ"}, {"q": "サービスで怪我をしたり、目を正しく見せたりするのは簡単ではありませんか？ （複数選択可）", "s": "サービスマインドセット", "o": "A.人々が私をどう思っているかではなく、神が私の中でなさることを大切にする,B.サービスを優雅さのための交渉のチップとして扱う,C.サービスで構築され、変革されることを学ぶ,D.あなたがどれだけのことをしたか、そして他の人がそれを知っているかどうかを考えてください"}, {"q": "私たちがより多くを与え、より神聖な働きをするならば、神はより多くを動かし、より多くを私たちに与えてくださるでしょう。これが聖書の真理です。", "s": "サービスの性質"}, {"q": "すべてのサービスは神の前で貴重であり、台所での静かな料理は、説教壇から説教するのと同じくらい重要です。", "s": "平等な贈り物"}, {"q": "教会の説教壇は、個人的な才能の舞台になることができます。", "s": "ミニストリー＆パフォーマンス"}, {"q": "説得が神との恵みのための交渉チップではないのはなぜですか？説明してください。", "s": "サービスの性質"}, {"q": "奉仕することと才能を示すことの違いは何ですか？このレッスンの例を使って説明してください。", "s": "ミニストリー＆パフォーマンス"}]}, "ko": {"title": "제 17과 섬김과 삶", "content": "봉사는 하나님과의 거래가 아니라 하나님의 선물입니다. 이 수업은 섬길 수 있는 올바른 마음가짐, 짝짓기에서 겸손을 배우고, 삶이 하나님에 의해 형성되도록 하는 것에 관한 것이다. 사역에서 기쁨과 성장을 찾을 수 있기를 바랍니다. 많은 사람들에게 기꺼이 축복이 되십시오.", "instructions": "", "guide": [{"title": "서빙은 흥정 칩이 아닙니다", "points": ["우리가 여전히 죄인이었을 때, 그리스도는 우리를 위해 죽으셨고 (로마서 5: 8), 그것을 위해 다른 것을 교환할 필요가 없었습니다.", "천사들은 우리보다 일을 더 잘합니다. 하나님은 우리가 하는 일을 필요로 하지 않으십니다.", "봉사는 공로를 쌓고, 다리를 수리하고, 축복을 위해 도로를 수리하는 것이 아닙니다."]}, {"title": "봉사는 삶을 변화시키는 과정입니다", "points": ["상대방을 존중하고, 겸손하며, 존중하는 법을 배워보세요.", "봉사의 가장 중요한 의미인 성격이 변화됨", "눈이 하나님께로 향할 때 다치기란 쉽지 않습니다."]}, {"title": "서빙은 전체적입니다", "points": ["주부, 회사원, 학생 모두 목사입니다.", "가족이 교회를 운영하도록 내버려 두지 마십시오. 책의 끝이 뒤집혀 있습니다.", "먹든지 마시든지 다 하나님의 영광을 위하여"]}, {"title": "서빙은 탤런트 쇼가 아닙니다", "points": ["합창단 협연은 봉사, 한 사람의 홍보는 공연", "주방, 청소도 똑같이 가치가 있습니다. 하우스키퍼에게 요구되는 것은 충성도입니다.", "무엇을 받지 못했는가? 자랑하지 말라 (고린도전서 4: 7)"]}, {"title": "더 많은 일을 한다는 신화를 깨뜨리세요", "points": ["더 많이 주는 것은 성경적 진리가 아니라 더 많이 주는 것이다.", "그들은 매일 봉사하며, 그들 사이에는 차이가 없습니다.", "핵심은 양이 아니라 방향이 올바른지 여부입니다."]}, {"title": "몸을 산 제물로 바치세요", "points": ["롬 12: 1: 그러한 봉사는 당연한 것으로 여겨진다.", "주님께 온전히 돌아가기 위한 희생 제물처럼 마음과 정신과 정신은 모두 하나님의 방향으로 향하고 있습니다.", "인생의 변화는 하룻밤 사이에 일어나는 것이 아니라 점차적으로 서비스에 구축됩니다."]}, {"title": "서로를 구축하고 거룩한 삶을 누리세요", "points": ["사랑은 정직하게 말합니다: 형제가 구속하기 위해 범죄를 저지르는 것을 보는 것", "일꾼은 일보다 더 중요합니다. 거룩한 삶은 봉사의 전제 조건입니다.", "합창단 형제들을 막고 그들의 교훈을 바쳐 자랑하십시오."]}], "quizzes": [{"q": "형제 여러분, 저는 하나님의 자비로 ________ 을 (를) ________ (으) 로 여길 것을 권고합니다. 당신은 이런 식으로 봉사하지만 ________.", "s": "산 제물의 섬김"}, {"q": "하느님께서 우리 모두를 위해 당신 아들을 아끼지 않으셨으니, 그분께서도 우리를 ________ 헛되이 ________ 데려가시지 않겠는가?", "s": "하나님의 은혜는 무료입니다"}, {"q": "먹든 마시든, 무엇을 하든 ________ 을 (를) 위해 노력하세요.", "s": "하나님의 영광 속을 걸으십시오"}, {"q": "우리가 아직 죄인일 때 그리스도께서 우리를 위해 죽으셨기 때문에, 봉사는 결코 하나님과의 은혜를 위한 거래가 아닙니다.", "s": "서비스 성격"}, {"q": "사역의 상호 배치에서 우리는 존중하고 겸손하며 다른 사람들을 소중히 여기는 법을 배웁니다. 우리의 성격과 성격은 ________ 입니다.", "s": "삶은 만들어진다"}, {"q": "우리의 봉사는 교회에서, ________ 에서, 직장에서, 학교에서 총체적입니다.", "s": "전인 서비스"}, {"q": "바울은 다음과 같이 말했습니다. 청지기에게 요구되는 것은 ________ 를 가져야 한다는 것입니다.", "s": "충실한 집사"}, {"q": "일본 교회의 형제는 시를 연습하지 않고 무대에서만 공연하다가 나중에 교통사고로 부상을 입었기 때문에 겸손해지는 법을 배웠습니다 ________.", "s": "교만 규율"}, {"q": "교회에서 봉사할 때, 형제가 명백한 죄를 지었지만 그것을 무시하는 것을 본다면, 그것은 진정한 사랑이 아닙니다. 진정한 사랑은 ________ ___________________________________________________________", "s": "서로 격려하기"}, {"q": "다음 중 성경에서 봉사하는 것이 무엇을 의미하는지 가장 잘 설명하는 것은 무엇인가?", "s": "서비스 성격", "o": "A.하나님의 축복을 받는 대가로 공로를 섬기십시오.,B.섬김은 하나님께서 우리의 삶을 세우시고 우리의 성품을 변화시키시는 방법입니다.,C.우리가 더 많이 섬길수록 하나님은 우리를 더 좋아하십니다.,D.교회에서 봉사하는 것은 하나님을 기쁘시게 하는 일입니다."}, {"q": "다음 중 봉사와 인재에 대한 설명으로 옳은 것은?", "s": "사역 및 공연", "o": "A.봉사는 당신의 재능을 모두에게 보여주는 것입니다.,B.합창단에서 좋은 목소리는 솔리스트가 제공하는 것이 가장 좋습니다.,C.봉사는 서로를 키우고, 선물을 사용하여 다른 사람들이 스스로 행동하지 않고 성장하도록 돕는 것입니다.,D.지배구조의 은사를 가진 사람들은 단독의 재정적 권력을 가져야 한다."}, {"q": "교회와 집에서 옷을 빨고 자녀를 돌보지 않는 자매에게 보내는 목사의 권고는 무엇인가?", "s": "전인 서비스", "o": "A.교회에서 계속 더 많이 봉사하십시오. 하나님은 기억하실 것입니다.,B.집으로 돌아가 어머니와 아내로서의 의무를 다하고 집에서 하나님을 섬기십시오.,C.다른 사람이 데려올 아이를 교회에 보내는 것,D.헌신을 줄이고 가족에게 시간을 할애하세요"}, {"q": "다음 중 전인 사역의 범위에 속하는 것은 어느 것입니까? (복수 선택)", "s": "전인 서비스", "o": "A.주부들은 영적 원리에 따라 가족을 운영합니다.,B.직원들은 회사에서 성실하고 충성스럽게 일합니다.,C.학생들은 학업적으로 열심히 일하고 학우들을 돕습니다.,D.단상에 선 주일 예배만"}, {"q": "다음을 포함하여 서비스에서 부상을 입고 눈에서 올바르게 행동하는 것이 쉽지 않습니까? (복수 선택)", "s": "섬기는 마음가짐", "o": "A.사람들이 나를 어떻게 생각하는지가 아니라, 하나님이 내 안에서 하시는 일을 소중히 여겨라.,B.봉사를 은혜를 위한 교섭의 장으로 여겨라,C.봉사를 통해 구축되고 변화되는 것을 배우는 것,D.당신이 얼마나 많은 일을 했는지, 그리고 다른 사람들이 그것을 알고 있는지 생각해보십시오."}, {"q": "우리가 더 많이 베풀고 더 많이 성역을 행하면 하나님께서 더 많이 움직이시고 더 많이 주실 것입니다. 이것이 성경의 진리입니다.", "s": "서비스 성격"}, {"q": "모든 예배는 하나님 앞에서 소중하며, 강단에서 설교하는 것만큼이나 주방에서 조용히 요리하는 것도 중요합니다.", "s": "선물 평등"}, {"q": "교회의 강단은 개인적인 재능의 무대가 될 수 있다.", "s": "사역 및 공연"}, {"q": "왜 설득은 하나님과의 은혜를 위한 협상 칩이 아닌가요? 설명해 주십시오.", "s": "서비스 성격"}, {"q": "봉사하는 것과 재능을 보이는 것의 차이점은 무엇입니까? 이 수업의 예를 들어 설명해 주십시오.", "s": "사역 및 공연"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773057316482','基要真理','第十八课 发掘属灵恩赐','属灵恩赐是神所赐、用在圣工上的特质，圣灵随己意分给各人。本课帮助你发掘自己的恩赐，并在教会中找到位置。愿你善用恩赐，荣神益人。各尽其职，建立基督的身体。','[{"type": "verse", "q": "你们若切慕属灵的恩赐，就更要切慕那些________教会的恩赐。", "o": "《哥林多前书》14章12节", "s": "造就教会", "a": "造就"}, {"type": "verse", "q": "岂都是________的吗？岂都是________的吗？", "o": "《哥林多前书》12章29节", "s": "恩赐各异", "a": "说方言|翻方言"}, {"type": "verse", "q": "你要尽心、尽性、尽意、尽力，爱________你的神。", "o": "《马可福音》12章30节", "s": "尽力爱神", "a": "主"}, {"type": "fill", "q": "属灵恩赐极可能是神让人在________时就预备好的特质，信主后更有智慧用在正确的位置上。", "o": "", "s": "恩赐来源", "a": "出生"}, {"type": "fill", "q": "说方言的恩赐既不是________的记号，也不是成圣的记号。", "o": "", "s": "方言恩赐", "a": "得救"}, {"type": "fill", "q": "圣灵________把不同的恩赐分给不同的人，没有人可以越过圣灵的主权去教人说方言。", "o": "", "s": "圣灵主权", "a": "随己意"}, {"type": "fill", "q": "保罗说恩赐好像人身体上的各个________，眼睛不能对手说我用不着你。", "o": "", "s": "彼此配搭", "a": "器官"}, {"type": "fill", "q": "在教会里，看得见的讲台恩赐与在后面默默打扫、关怀的恩赐，在神面前________重要。", "o": "", "s": "恩赐无大小", "a": "一样"}, {"type": "fill", "q": "寇牧师说自己对绘画没有恩赐，若去教儿童主日学教孩子们绘画，那就是________了。", "o": "", "s": "认清恩赐", "a": "浪费"}, {"type": "single", "q": "关于属灵恩赐，以下哪项说法最符合圣经？", "o": "A.信主后神会突然赐下一个原来没有的特殊能力,B.恩赐是与生俱来的特质，信主后更有智慧用在正确位置上,C.每个人都必须有说方言的恩赐,D.恩赐有大小之分，讲台上的恩赐最大", "s": "恩赐本质", "a": "B"}, {"type": "single", "q": "关于方言的恩赐，以下哪项正确？", "o": "A.会说方言是得救的记号,B.会说方言的人属灵生命更高,C.方言是造就自己的恩赐，主权在神，不是每人都需要,D.不会说方言的人应该找人教他说方言", "s": "方言恩赐", "a": "C"}, {"type": "single", "q": "发现自己有某方面恩赐后，正确的态度是？", "o": "A.羡慕别人的恩赐，想站在更显眼的位置,B.存谦卑感恩的心竭力操练，让恩赐发挥得更好,C.自高自大，觉得自己了不起,D.闲散不做工，等神自己使用", "s": "使用恩赐", "a": "B"}, {"type": "multiple", "q": "以下哪些符合圣经中关于恩赐的原则？（多选）", "o": "A.没有一个人有所有的恩赐,B.没有一个人一样恩赐都没有,C.每一个恩赐都一样重要,D.某些恩赐特别大，值得人人追求", "s": "恩赐原则", "a": "A|B|C"}, {"type": "multiple", "q": "关于操练恩赐，以下哪些说法正确？（多选）", "o": "A.有了恩赐要加上努力，让它发挥得更好,B.恩赐发挥得好时要存谦卑感恩的心,C.天分好就不需要努力了,D.若不好好使用，神可能把恩赐收回", "s": "操练恩赐", "a": "A|B|D"}, {"type": "judge", "q": "一个人信主后一定要会说方言，否则就是没有得救。", "o": "", "s": "方言恩赐", "a": "错"}, {"type": "judge", "q": "恩赐有大小之分，站在讲台上教导的恩赐比默默打扫的恩赐更大。", "o": "", "s": "恩赐无大小", "a": "错"}, {"type": "judge", "q": "若有人没有某方面的恩赐却硬要站在那个位置上，应该用规劝的方式让他站在更合适的位置。", "o": "", "s": "认清恩赐", "a": "对"}, {"type": "essay", "q": "为什么说没有哪一个恩赐是每个人都要有的？请用方言的恩赐举例说明。", "o": "", "s": "方言恩赐", "a": "圣经明说“岂都是说方言的吗”，可见不是每人都需要说方言。方言的恩赐是造就自己的，不是得救或成圣的记号，主权在神，圣灵随己意分给不同的人。把个人经历高举超过圣经对全体的教导，是不合圣经的态度。"}, {"type": "essay", "q": "保罗为什么把恩赐比作身体上的器官？这对教会配搭有什么提醒？", "o": "", "s": "彼此配搭", "a": "因为眼睛不能说不需要耳朵，手不能说不需要脚，各器官配搭才能让身体功能全面发挥。这提醒教会：每个恩赐都一样重要，不可用世界的价值观衡量；要彼此欣赏、彼此尊重，特别看重那些看不见的、隐藏的恩赐，形成正确的风气。"}]','https://youtu.be/dYLQe4jMLHw
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134FODs','quiz','[{"points": ["恩赐不是信主后突然加添的特殊能力", "理性、感性、音乐、逻辑等特质，神在出生时已预备", "信主后用属天智慧把才干放在正确位置上"], "title": "恩赐是神与生俱来的特质"}, {"points": ["方言今天仍有，但主权在神，圣灵随己意分给", "不是得救的记号，也不是成圣的记号", "说方言是造就自己；更要切慕造就教会的恩赐（林前14）"], "title": "方言恩赐的辨析"}, {"points": ["不可贬低方言，那是神给人的恩赐", "也不可把它高举到不合适的位置", "不能教人说方言，那是越过圣灵的主权"], "title": "不要高举也不要贬低"}, {"points": ["如同身体的器官：眼不可说不需要耳（林前12）", "讲台、诗班与清洁、关怀同样重要", "彼此配搭、欣赏、尊重"], "title": "恩赐没有大小"}, {"points": ["在与人互动和成长中慢慢看见", "弟兄姐妹可以印证", "不要站在不适合的位置上羡慕别人的恩赐"], "title": "发现自己的恩赐"}, {"points": ["恩赐是拿来用的，不是自高或闲懒的理由", "不好好运用，神可能把恩赐拿走", "要操练精进，如运动员在天分上加努力"], "title": "好好使用恩赐"}, {"points": ["尽心尽性尽意尽力爱神", "带着谦卑感恩的心发挥恩赐", "彼此配搭服事，建立别人、自己也被建立"], "title": "谦卑感恩、全力以赴"}]','','18','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 18 Discovering Spiritual Gifts", "content": "Spiritual gifts are attributes given by God and used in sacramental work, and the Holy Spirit distributes them to everyone at will. This lesson can help you discover your gifts and find your place in the Church. May you make good use of your gifts and glorify God for the good of others. Do your part to build up the body of Christ.", "instructions": "", "guide": [{"title": "Gifts are an innate quality of God", "points": ["Gifts are not special abilities that are suddenly added after believing in the Lord", "Reason, sensibility, music, logic, etc., God prepared at birth", "Put your talents in the right place with heavenly wisdom after believing in the Lord"]}, {"title": "Dialectic Gift Discernment", "points": ["There are still dialects today, but the sovereignty is in God, and the Holy Spirit gives it to you as you wish.", "Not a sign of salvation, not a sign of sanctification.", "To speak in tongues is to build oneself up; it is even more important to yearn for the gift of building up the church (1 Corinthians 14)"]}, {"title": "Don''t exalt or belittle", "points": ["Don''t belittle tongues, that''s a gift from God.", "and don''t lift it up in an inappropriate position.", "You can''t teach people to speak in tongues, that''s beyond the sovereignty of the Holy Spirit."]}, {"title": "Gift has no size", "points": ["Like the organs of the body: the eye does not need the ear (1 Cor. 12)", "Podiums, choirs are just as important as cleaning and caring", "Matching, appreciating, and respecting each other"]}, {"title": "Discover your gift", "points": ["Slowly seeing as you interact and grow with others", "Brothers and sisters can confirm", "Don''t stand in an inappropriate position and envy the gifts of others"]}, {"title": "Make the most of your gifts", "points": ["Gifts are for use, not for reasons of self-importance or idleness", "If you don''t use it well, God may take the gift away", "Exercise refinement, such as athletes working hard on their talents"]}, {"title": "Humility, gratitude, commitment", "points": ["Love God with all your heart and soul", "Giving with humility and gratitude", "Pair up with each other to serve, build others, and be built yourself"]}], "quizzes": [{"q": "If you desire spiritual gifts, you must desire even more the gifts of the church of ________.", "s": "Building the Church"}, {"q": "Are they all ________? Are they all ________?", "s": "Gifts vary"}, {"q": "Love ________ thy God with all thy heart, thy soul, thy mind, and thy strength.", "s": "Love God as much as you can"}, {"q": "Spiritual gifts are likely to be traits that God has prepared for people at ________, and after believing in the Lord, they are more wisely used in the right place.", "s": "Bounty Source"}, {"q": "The gift of speaking in tongues is neither a sign of ________ nor a sign of sanctification.", "s": "Gift of tongues"}, {"q": "The Holy Spirit ________ distributes different gifts to different people, and no one can teach tongues beyond the sovereignty of the Holy Spirit.", "s": "Holy Spirit Sovereignty"}, {"q": "Paul said that the gifts are like each ________ on the human body, and the eyes can''t tell the opponent that I don''t need you.", "s": "Matching each other"}, {"q": "In the church, the visible gift of the pulpit, the gift of silent cleaning and care behind it, is important ________ before God.", "s": "Gift without size"}, {"q": "Pastor Kou said that he had no gifts for painting. If he went to teach children Sunday School to teach children to draw, it would be ________.", "s": "Recognize the Gift"}, {"q": "Which of the following statements about spiritual gifts is most biblical?", "s": "Gifted Essence", "o": "A.After believing in the Lord, God will suddenly grant a special ability that originally did not exist,B.Gifts are innate traits, and after believing in the Lord, it is wiser to use them in the right position.,C.Everyone must have the gift of speaking in tongues,D.Gifts are big and small, and the greatest gifts are on the podium"}, {"q": "Which of the following is true about the gift of tongues?", "s": "Gift of tongues", "o": "A.Speaking in tongues is a sign of salvation,B.People who can speak in tongues have higher spiritual life,C.Tongues are a gift to build oneself. Sovereignty is in God, not everyone needs it.,D.People who don''t speak in tongues should find someone to teach him tongues"}, {"q": "After discovering that you have a gift, what is the correct attitude?", "s": "Use Boon", "o": "A.Envy the gifts of others and want to stand in a more prominent position,B.Practice with a humble and grateful heart to make your gifts work better,C.Self-importance, feeling great,D.Idle and not working, waiting for God to use it himself"}, {"q": "Which of the following is consistent with biblical principles about gifts? (Multiple choice)", "s": "Gift Principle", "o": "A.No one person has all the gifts,B.No one has the same gifts as you.,C.Every gift counts,D.Some gifts are especially great and deserve to be pursued by everyone"}, {"q": "Which of the following statements is true about exercise gifts? (Multiple choice)", "s": "Practice Gift", "o": "A.With the gift, work hard to make it work better,B.Be humble and grateful when the gifts are well played,C.If you have good talent, you don''t need to work hard,D.If not used well, God may take back the gift"}, {"q": "A person must be able to speak in tongues after believing in the Lord, otherwise there is no salvation.", "s": "Gift of tongues"}, {"q": "The gifts are great and small, and the gifts taught from the pulpit are greater than the gifts of silent cleansing.", "s": "Gift without size"}, {"q": "If a person does not have a gift in some way and insists on standing in that position, he should be persuaded to stand in a more suitable position.", "s": "Recognize the Gift"}, {"q": "Why isn''t there a gift for everyone? Give me an example of the gift of dialect.", "s": "Gift of tongues"}, {"q": "Why does Paul compare gifts to organs in the body? What is this reminder of church matching?", "s": "Matching each other"}]}, "ja": {"title": "レッスン18霊的な賜物を発見する", "content": "霊的な賜物は，神から与えられ，聖餐の業に用いられる特質であり，聖霊はそれをすべての人に自由に配ります。このレッスンは，自分の賜物を見つけ，教会で自分の居場所を見つけるのに役立ちます。あなたの賜物をうまく活用し，他の人のために神を賛美してくださいますように。キリストのからだを築くために，自分の役割を果たしてください。", "instructions": "", "guide": [{"title": "贈り物は神の生来の特質である", "points": ["贈り物は、主を信じた後に突然追加される特別な能力ではありません", "理性、感性、音楽、論理など、神は誕生時に備えられた", "主を信じた後，天の知恵をもって自分の才能を正しい場所に置く"]}, {"title": "弁証法的贈り物の識別", "points": ["今日でも方言はありますが、主権は神にあり、聖霊はあなたが望むようにそれをあなたに与えます。", "救いのしるしでもなく、聖化のしるしでもありません。", "異言を話すことは自分自身を築くことです。教会を築くという贈り物を切望することはさらに重要です（ 1コリント14章）"]}, {"title": "昇進したり、軽蔑したりしないでください", "points": ["舌を軽蔑しないでください。それは神からの贈り物です。", "不適切な位置で持ち上げないでください。", "人々に異言を話すことを教えることはできません。それは聖霊の主権を超えています。"]}, {"title": "ギフトにはサイズがありません", "points": ["身体の器官のように：目は耳を必要としない（ 1コリント12 ）", "表彰台や聖歌隊は、清掃やお手入れと同じくらい重要です", "お互いにマッチングし、感謝し、尊重する"]}, {"title": "ギフトを見つけよう", "points": ["あなたが他の人と交流し、成長しているのをゆっくりと見ている", "兄弟姉妹は確認することができます", "不適切な立場に立って、他人の贈り物を羨ましがらない"]}, {"title": "ギフトを最大限に活用しましょう", "points": ["贈答品は、自尊心や怠惰のためではなく、使用のためのものです", "うまく使わなければ、神は贈り物を取り上げるかもしれません", "アスリートが自分の才能に一生懸命取り組むなどのエクササイズの洗練"]}, {"title": "謙虚さ、感謝、献身", "points": ["心と魂を尽くして神を愛する", "謙虚さと感謝の気持ちを持って与える", "お互いにペアを組んで奉仕し、他者を構築し、自分自身を構築する"]}], "quizzes": [{"q": "霊的な賜物を望むなら， ________教会の賜物をさらに望まなければなりません。", "s": "教会を建てる"}, {"q": "それらはすべて________ですか？それらはすべて________ですか？", "s": "ギフトはさまざまです"}, {"q": "________あなたの心、あなたの魂、あなたの心、そしてあなたの力であなたの神を愛してください。", "s": "できるだけ神を愛する"}, {"q": "霊的な賜物は，神が________で人々のために用意された特質である可能性が高く，主を信じた後は，より賢明に正しい場所で使われます。", "s": "報奨金の源"}, {"q": "異言を話すという賜物は， ________のしるしでも，聖化のしるしでもありません。", "s": "舌の贈り物"}, {"q": "聖霊は異なる人々に異なる賜物を配り，聖霊の主権を超えて異言を教えることはできません。", "s": "聖霊の主権"}, {"q": "ポールは、贈り物は人体のそれぞれの________のようなものであり、目は私があなたを必要としていないことを相手に伝えることはできないと言いました。", "s": "お互いにマッチングする"}, {"q": "教会では、説教壇の目に見える贈り物、静かな清掃とその背後の世話の贈り物は、神の前で________重要です。", "s": "サイズなしのギフト"}, {"q": "コウ牧師は、絵を描く才能がないと言い、子供たちに日曜学校に行って子供たちに絵を描くように教えるとしたら、それは________です。", "s": "贈り物を認識する"}, {"q": "霊的な賜物についての次の記述のうち，最も聖書的なものはどれですか。", "s": "ギフテッド・エッセンス", "o": "A.主を信じた後、神は突然、もともと存在しなかった特別な能力を与えてくださる,B.賜物は生来の特質であり，主を信じた後は，適切な立場で使う方が賢明です。,C.誰もが異言を話す才能を持っていなければなりません,D.ギフトは大きくても小さくても、最高のギフトは表彰台の上にあります"}, {"q": "異言の賜物について，次のうちどれが正しいですか。", "s": "舌の贈り物", "o": "A.異言を話すことは救いのしるし,B.異言を話すことができる人は、より高い霊的生活をしています,C.舌は自分自身を構築するための贈り物です。主権は神にあり、誰もがそれを必要としているわけではありません。,D.異言を話さない人は，異言を教える人を見つけるべきです"}, {"q": "贈り物を持っていることがわかった後、正しい態度は何ですか？", "s": "ブーンを使う", "o": "A.他人の贈り物をうらやみ、より目立つ立場に立ちたい,B.謙虚で感謝の気持ちを持って練習して、贈り物をより良くする,C.自尊心、気分がいい,D.怠惰で働かず、神自身がそれを使用するのを待っている"}, {"q": "次のうち，賜物に関する聖書の原則と一致するものはどれですか。（複数選択可）", "s": "贈答の原則", "o": "A.誰もがすべての贈り物を持っているわけではありません,B.あなたと同じ才能を持っている人はいません。,C.すべてのギフトが重要です,D.いくつかの贈り物は特に素晴らしく、誰もが追求する価値があります"}, {"q": "エクササイズの贈り物について、次の記述のうち正しいものはどれですか？ （複数選択可）", "s": "練習ギフト", "o": "A.贈り物で、より良い仕事をするために一生懸命働きましょう,B.贈り物がうまくプレーされているときは、謙虚で感謝してください,C.優れた才能を持っていれば、一生懸命働く必要はありません,D.うまく使わなければ、神は贈り物を取り戻すかもしれません"}, {"q": "人は主を信じた後に異言を話すことができなければなりません。そうでなければ救いはありません。", "s": "舌の贈り物"}, {"q": "贈り物は大きくても小さくても，説教壇から教えられる贈り物は，静かな清めの贈り物よりも大きいものです。", "s": "サイズなしのギフト"}, {"q": "何らかの形で贈り物を持っておらず、その立場に立つことを主張する人は、より適切な立場に立つよう説得されるべきです。", "s": "贈り物を認識する"}, {"q": "みんなへの贈り物がないのはなぜですか？方言の才能の例を挙げてください。", "s": "舌の贈り物"}, {"q": "パウロが贈り物を体の臓器と比較するのはなぜでしょうか。教会のマッチングのこのリマインダーは何ですか？", "s": "お互いにマッチングする"}]}, "ko": {"title": "제 18과 영적인 은사를 발견하기", "content": "영적인 은사는 하느님께서 주시고 성사 활동에 사용하시는 속성이며, 성령께서는 모든 사람에게 마음대로 나누어 주십니다. 이 수업은 여러분이 은사를 발견하고 교회에서 자신의 자리를 찾는 데 도움이 될 수 있다. 여러분의 은사를 잘 활용하고 다른 사람들의 유익을 위해 하나님께 영광을 돌리기를 바랍니다. 그리스도의 몸을 세우기 위해 여러분의 역할을 다하십시오.", "instructions": "", "guide": [{"title": "선물은 타고난 하나님의 품질입니다", "points": ["은사는 주님을 믿은 후에 갑자기 추가되는 특별한 능력이 아닙니다.", "이성, 감성, 음악, 논리 등, 태어나면서부터 준비하신 하나님", "주님을 믿은 후 하늘의 지혜로 달란트를 올바른 곳에 두십시오."]}, {"title": "변증법적 은사 분별력", "points": ["오늘날에도 방언은 있지만 주권은 하나님 안에 있으며 성령께서는 원하시는 대로 주십니다.", "구원의 표징도, 성화의 표징도 아니다.", "방언을 말하는 것은 자신을 세우는 것입니다. 교회를 세우는 은사를 갈망하는 것이 더욱 중요합니다 (고린도전서 14장)."]}, {"title": "칭찬하거나 과소평가하지 마세요.", "points": ["방언을 경시하지 마세요. 그것은 하나님께서 주신 선물입니다.", "부적절한 자세로 들어 올리지 마십시오.", "사람들이 방언으로 말하도록 가르칠 수 없습니다. 그것은 성령의 주권을 벗어난 것입니다."]}, {"title": "선물에 사이즈가 없습니다", "points": ["신체의 기관과 마찬가지로 눈은 귀를 필요로 하지 않습니다 (고전 12장).", "단상, 합창은 청소와 배려만큼이나 중요합니다.", "서로를 일치시키고, 감사하고, 존중하기"]}, {"title": "내 선물 찾아보기", "points": ["당신이 다른 사람들과 상호 작용하고 성장하는 것을 천천히 봅니다.", "형제자매가 확인할 수 있습니다", "부적절한 입장에 서서 다른 사람의 은사를 부러워하지 마세요."]}, {"title": "선물을 최대한 활용하세요", "points": ["선물은 자기 중요성이나 게으름 때문이 아니라 사용하기 위한 것입니다.", "잘 사용하지 않으면 하나님께서 선물을 빼앗아 가실 수도 있습니다.", "운동 선수가 자신의 재능을 열심히 발휘하는 것과 같은 정교한 운동"]}, {"title": "겸손, 감사, 헌신", "points": ["마음을 다하고 성품을 다하여 하나님을 사랑하십시오.", "겸손과 감사의 마음을 담아 기부하기", "서로 짝을 지어 봉사하고, 다른 사람들을 만들고, 자신을 구축하십시오."]}], "quizzes": [{"q": "영적인 은사를 원한다면 ________ 교회의 은사를 더욱 원해야 합니다.", "s": "교회 세우기"}, {"q": "모두 ________ 인가요? 모두 ________ 인가요?", "s": "선물은 다양합니다"}, {"q": "네 마음을 다하고, 네 영혼을 다하고, 네 정신을 다하고, 네 힘을 다하여 네 하나님을 ________ 사랑하라.", "s": "할 수 있는 한 하나님을 사랑하라"}, {"q": "영적인 은사는 하나님께서 ________ 에서 사람들을 위해 준비하신 특성일 가능성이 높으며, 주님을 믿은 후에 올바른 장소에서 더 현명하게 사용됩니다.", "s": "현상금 출처"}, {"q": "방언을 말하는 은사는 ________ 의 표시도 아니고 성화의 표시도 아닙니다.", "s": "언어의 은사"}, {"q": "성령 ________ 은 (는) 다른 사람들에게 다른 은사를 나누어 주며, 아무도 성령의 주권을 넘어서는 방언을 가르칠 수 없습니다.", "s": "성령주권"}, {"q": "바울은 선물이 인체에 각 ________ 와 같다고 말했고, 눈은 상대방에게 당신이 필요 없다고 말할 수 없습니다.", "s": "서로 매칭"}, {"q": "교회에서 강단이라는 눈에 보이는 선물, 그 뒤에 있는 침묵의 청소와 보살핌이라는 선물은 하나님 앞에서 ________ 중요합니다.", "s": "사이즈가 없는 선물"}, {"q": "코우 목사는 그림에 대한 선물이 없다고 말했다. 만약 그가 어린이들에게 주일학교를 가르치러 가서 어린이들에게 그림을 가르친다면, 그것은 ________ 일 것이다.", "s": "선물 인식하기"}, {"q": "영적 은사에 관한 다음 말씀 중 가장 성경적인 것은 무엇인가?", "s": "기프트 에센스", "o": "A.주님을 믿은 후, 하나님은 갑자기 원래 존재하지 않았던 특별한 능력을 부여하실 것입니다.,B.은사는 타고난 특성이며, 주님을 믿은 후에는 올바른 자세로 사용하는 것이 더 현명하다.,C.모든 사람은 방언을 말하는 재능이 있어야 합니다.,D.선물은 크고 작고, 가장 위대한 선물은 연단에 있습니다."}, {"q": "방언 은사에 대해 다음 중 어느 것이 옳은가?", "s": "언어의 은사", "o": "A.방언을 말하는 것은 구원의 표시입니다,B.방언을 할 수 있는 사람은 영적인 삶이 더 높습니다.,C.혀는 자신을 키우기 위한 선물입니다. 주권은 모든 사람이 필요로 하는 것이 아니라 하나님 안에 있습니다.,D.방언을 말하지 않는 사람은 그에게 방언을 가르칠 사람을 찾아야 한다."}, {"q": "선물이 있다는 것을 알게 된 후, 올바른 태도는 무엇입니까?", "s": "Boon 사용", "o": "A.다른 사람들의 은사를 부러워하고 더 눈에 띄는 위치에 서기를 원합니다.,B.선물을 더 잘 사용할 수 있도록 겸손하고 감사하는 마음으로 연습하세요.,C.자기 중요성, 기분 좋음,D.유휴 상태이며 작동하지 않음, 하나님이 직접 사용하기를 기다림"}, {"q": "다음 중 은사에 관한 성경의 원칙과 일치하는 것은 무엇인가? (복수 선택)", "s": "선물 원칙", "o": "A.아무도 모든 선물을 가지고 있지 않습니다,B.아무도 당신과 같은 선물을 가지고 있지 않습니다.,C.모든 선물은 소중합니다,D.일부 선물은 특히 훌륭하며 모든 사람이 추구해야 할 가치가 있습니다."}, {"q": "다음 중 운동 선물에 대한 설명으로 옳은 것은? (복수 선택)", "s": "연습 선물", "o": "A.선물과 함께 더 잘 작동할 수 있도록 열심히 노력하세요,B.선물이 잘 연주될 때 겸손하고 감사하십시오,C.좋은 재능이 있다면 열심히 일할 필요가 없습니다.,D.잘 사용하지 않으면 하나님께서 선물을 회수하실 수 있습니다."}, {"q": "사람은 주님을 믿은 후에 방언을 말할 수 있어야 합니다. 그렇지 않으면 구원이 없습니다.", "s": "언어의 은사"}, {"q": "은사는 크고 작으며, 강단에서 가르치는 은사는 조용한 정화의 은사보다 큽니다.", "s": "사이즈가 없는 선물"}, {"q": "어떤 사람이 어떤 식으로든 선물을 가지고 있지 않고 그 위치에 서기를 고집한다면, 그는 더 적합한 위치에 서도록 설득되어야 한다.", "s": "선물 인식하기"}, {"q": "왜 모두를 위한 선물이 없을까요? 방언의 선물에 대한 예를 들어주세요.", "s": "언어의 은사"}, {"q": "바울은 왜 은사를 몸의 기관에 비유하는가? 교회 매칭에 대한 이 알림은 무엇입니까?", "s": "서로 매칭"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773057694644','基要真理','第十九课 一次得救 永远得救论','真得救是交出生命主权、跟随基督。本课审慎思想一次得救教义的含义，分辨真假得救的确据，免得自欺。愿你确知得救的确据，安心跟随主。一次交托主，永远稳妥不动摇。','[{"type": "verse", "q": "你若口里________为主，心里信神叫他从死里________，就必________。", "o": "《罗马书》10章9节", "s": "得救确据", "a": "认耶稣|复活|得救"}, {"type": "verse", "q": "差我来者的意思就是：他所赐给我的，叫我________，在末日却叫他复活。", "o": "《约翰福音》6章39节", "s": "一个不失落", "a": "一个也不失落"}, {"type": "verse", "q": "因此，在你们中间有好些________的与________的，死的也不少。", "o": "《哥林多前书》11章30节", "s": "混乱圣餐", "a": "软弱|患病"}, {"type": "fill", "q": "一次得救永远得救这八个字在圣经里________，它是神学探讨得出的一个结论。", "o": "", "s": "神学结论", "a": "找不到"}, {"type": "fill", "q": "有人自称基督徒，一年只聚会三次：复活节、感恩节和________。", "o": "", "s": "挂名基督徒", "a": "圣诞节"}, {"type": "fill", "q": "真正的得救不只是受洗或举手决志，而是口里认耶稣为主，心里信神叫祂从死里复活，就必________。", "o": "", "s": "得救确据", "a": "得救"}, {"type": "fill", "q": "那位为朋友充场面而受洗的弟兄，牧师告诉他：他第一次只是到水里泡了一下，那根本不算________。", "o": "", "s": "真受洗", "a": "受洗"}, {"type": "fill", "q": "神的恩典不仅是要什么给什么，恩典里面也包括________：当我们执意走错路时，神把我们带回来。", "o": "", "s": "恩典管教", "a": "管教"}, {"type": "fill", "q": "保罗吩咐把那与继母犯淫乱的人交给________，败坏他的肉体，使他的灵魂在主耶稣的日子可以得救。", "o": "", "s": "教会纪律", "a": "撒旦"}, {"type": "single", "q": "关于“一次得救永远得救”，以下哪项说法正确？", "o": "A.圣经原文中有这八个字，是明确的真理,B.它是神学探讨的结论，至今仍有不同看法，处理时要审慎,C.只要受过洗就一定得救，无论生命有无改变,D.一次得救后就可以放心犯罪，反正将来上天堂", "s": "神学结论", "a": "B"}, {"type": "single", "q": "根据罗马书，真正的得救是指？", "o": "A.加入教会、受洗,B.布道会举手决志,C.口里认耶稣为主，心里信神叫祂从死里复活,D.一年聚会三次的基督徒", "s": "得救确据", "a": "C"}, {"type": "single", "q": "对于那些信主后生命从未被改变、仍活在自我里的人，最合乎本课的看法是？", "o": "A.他们肯定已经得救了,B.他们是否真正得救值得深思，可能根本没弄清楚什么是得救,C.他们需要再受一次洗,D.他们已经失去救恩了", "s": "真得救", "a": "B"}, {"type": "multiple", "q": "以下哪些人对得救的认识是马马虎虎、不准确的？（多选）", "o": "A.以为受洗了就是得救了,B.以为布道会举手决志就是得救了,C.以为加入教会就是得救了,D.口里认耶稣为主、心里信神叫祂从死里复活", "s": "真得救", "a": "A|B|C"}, {"type": "multiple", "q": "真正得救的人若执意犯罪，神会怎样？（多选）", "o": "A.用各样的方法管教，把他带回来,B.任凭他继续犯罪，不管他,C.可能终止他犯罪的生命，接他回天家，免得他沉沦,D.立刻宣布他失去救恩", "s": "恩典管教", "a": "A|C"}, {"type": "judge", "q": "圣经原文中有“一次得救永远得救”这八个字。", "o": "", "s": "神学结论", "a": "错"}, {"type": "judge", "q": "得救是出黑暗入光明，既有出黑暗，也有入光明的行动。", "o": "", "s": "得救真义", "a": "对"}, {"type": "judge", "q": "既然一次得救永远得救，就可以一手抓天堂的福分、一手抓今世的罪中之乐。", "o": "", "s": "得救真义", "a": "错"}, {"type": "essay", "q": "为什么有些人会对“一次得救永远得救”产生疑惑？本课如何回应？", "o": "", "s": "得救疑惑", "a": "因为看到有些人信主受洗后生命从未改变，甚至一年只聚会三次，让人怀疑这样的人也得救吗；加上希伯来书第六章的经文，似乎带来矛盾。本课回应：关键在于什么是真正的得救——口里认耶稣为主、心里信神叫祂从死里复活，生命出黑暗入光明。若从未被改变，可能根本没弄清楚什么是得救。"}, {"type": "essay", "q": "真正得救的人犯罪时，神会如何对待？这给我们什么提醒？", "o": "", "s": "恩典管教", "a": "神像父亲一样不会轻易放弃孩子：会用各样方法管教、挽回；若执意不听，甚至终止他犯罪的生命、接他回天家，免得他将来沉沦。这提醒我们：不要把“永蒙保守”当作放纵的借口，要带着敬虔的心，尊主为大、活出改变。"}]','https://youtu.be/4vcTTuTC-i4
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134r3dW','quiz','[{"points": ["“一次得救永远得救”八个字，圣经里找不到", "是神学探讨的结论，神学界仍有不同看法", "不可因看法不同就把别人定为异端"], "title": "一个需要审慎的问题"}, {"points": ["看见有人信主后生命从不改变", "一年只聚会三次的“圣诞基督徒”", "没接触信仰核心：吃喝玩乐不是基督教"], "title": "疑惑从何而来"}, {"points": ["罗10:9：口里认耶稣为主，心里信神叫祂从死里复活", "口里认主＝站在仆人位置，主人吩咐什么就做什么", "心里相信＝信耶稣是道成肉身的神，不只是古圣先贤"], "title": "什么是真正的得救"}, {"points": ["举手决志、加入教会、受洗不等于得救的确据", "为朋友充场面受洗的例子：那只是泡了一下水", "成功神学、廉价恩典神学都不是圣经福音"], "title": "错误的得救观"}, {"points": ["得救是出黑暗入光明，有出也有入", "不能脚踏两条船：一手抓永生，一手抓罪中之乐", "重生的生命自带生命力，朝神的至善迈进"], "title": "真得救必有生命改变"}, {"points": ["林前11章30节：混乱圣餐的人，有的病弱、有的死去", "林前5章5节：把犯罪的人交给撒旦，为要灵魂得救", "真得救的人执意犯罪，神必管教、带回"], "title": "神的管教"}, {"points": ["约6章：凡父所赐给我的，一个也不失落", "主像父亲，不会轻易登报断绝孩子", "由神而来的保障，可以放心领受"], "title": "圣经的把握"}, {"points": ["不要把“永远得救”当放纵的借口", "在恩典中战兢，尊主为大", "神的话成为安慰、鼓励和帮助"], "title": "带着敬虔的心"}]','','19','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 19 Theory of One Salvation and Eternal Salvation", "content": "To be truly saved is to surrender to the sovereignty of life and follow Christ. In this lesson, we will carefully consider the meaning of the doctrine of one-time salvation and discern the evidence of true and false salvation, so as not to deceive ourselves. May you know the proof of your salvation and follow the Lord with peace of mind. Once entrusted to the Lord, always steady and unwavering.", "instructions": "", "guide": [{"title": "An issue that requires caution", "points": ["Eight words \"one salvation, eternal salvation\", not found in the Bible", "is the conclusion of theological exploration, and there are still different views in the theological community", "Don''t identify others as heretics because of differences of opinion"]}, {"title": "Where do doubts come from?", "points": ["After seeing someone believe in the Lord, life never changes", "A “Christmas Christian” who meets only three times a year", "No Faith Core: Eating, Drinking, Playing, Not Christianity"]}, {"title": "What is true salvation", "points": ["Romans 10: 9: Confessing Jesus as Lord with his mouth, believing in God to raise him from the dead", "Recognize the Lord by mouth = stand in the position of a servant, and do whatever the master tells you to do", "Believe in your heart = Believe that Jesus is the incarnate God, not just the ancient saints and sages"]}, {"title": "Wrong view of salvation", "points": ["Lifting a hand, joining a church, being baptized does not equal the assurance of salvation", "Example of setting up a friend to be baptized: It was just a soak in the water", "Prosperity theology, cheap grace theology are not biblical gospels"]}, {"title": "True salvation is life-changing", "points": ["To be saved is to go out of darkness into light, in and out", "Can''t step on two boats: one grasping eternal life, one grasping the joy of sin", "The reborn life carries its own vitality and marches toward the supreme goodness of God."]}, {"title": "God''s discipline", "points": ["1 Corinthians 11:30: Those who confuse the sacrament, some are weak, some die", "1 Corinthians 5: 5: Delivering sinners to Satan for the salvation of souls", "Those who are truly saved will persist in sin, and God will discipline and bring back"]}, {"title": "Biblical grasp", "points": ["John 6: All that the Father hath given me shall not be lost.", "The Lord is like a father, and he will not easily report and cut off the child", "Protection from God, you can feel at ease"]}, {"title": "With a godly heart", "points": ["Don''t use “always saved” as an excuse for indulgence", "Tremble in grace, revere the Lord as great", "The Word of God becomes comfort, encouragement and help"]}], "quizzes": [{"q": "If your mouth is dominated by ________ and your heart believes that God told him to ________ from death, you will ________.", "s": "Assurance of Salvation"}, {"q": "He who sent me meant that what he gave me he called me ________, but raised him up on the last day.", "s": "One that doesn''t get lost"}, {"q": "Therefore, there are many ________ and ________ among you, and there are many dead.", "s": "Confusion Eucharist"}, {"q": "The eight words of one salvation and eternal salvation are found in the Bible ________, which is a conclusion of theological exploration.", "s": "Theological Conclusions"}, {"q": "Some call themselves Christians and meet only three times a year: Easter, Thanksgiving, and ________.", "s": "Pseudo-Christian"}, {"q": "Real salvation is not just about being baptized or lifting up your hands to decide, but about confessing Jesus as Lord with your mouth, believing in God to raise Him from the dead, and you will ________.", "s": "Assurance of Salvation"}, {"q": "The brother who was baptized for his friend''s scene, the pastor told him that he had only soaked in the water for the first time, which did not count as ________.", "s": "True Baptism"}, {"q": "God''s grace not only wants to give something, but also includes ________: when we insist on going the wrong way, God brings us back.", "s": "Grace Discipline"}, {"q": "Paul commanded that the man who had committed adultery with his stepmother should be handed over to ________, and that his flesh should be corrupted, so that his soul might be saved in the day of the Lord Jesus.", "s": "Church Discipline."}, {"q": "Which of the following statements is true about “once saved, always saved”?", "s": "Theological Conclusions", "o": "A.These eight words in the original text of the Bible are clear truths.,B.It is the conclusion of theological exploration, there are still different views to this day, and it should be handled with caution,C.As long as you are baptized, you will be saved, regardless of whether your life has changed or not.,D.Once you are saved, you can rest assured that you will be able to commit a crime, and you will go to heaven anyway."}, {"q": "According to Romans, what does it mean to be truly saved?", "s": "Assurance of Salvation", "o": "A.Join a church, be baptized,B.Sermons Raise Hands Decision,C.Confessing Jesus as Lord with his mouth and believing in God in his heart, he raised him from the dead.,D.Christians meet three times a year"}, {"q": "What is the most appropriate view in this lesson for those who have never been changed in their lives and are still living in their selves after believing in the Lord?", "s": "Truly saved.", "o": "A.They must have been saved.,B.Whether they are truly saved is worth pondering, and it may not be clear what salvation is at all.,C.They need to be baptized again.,D.They have lost their salvation."}, {"q": "Which of the following people''s perceptions of salvation are so-so and inaccurate? (Multiple choice)", "s": "Truly saved.", "o": "A.Thought being baptized was salvation.,B.Thought that the sermon would raise a hand and make a decision is to be saved,C.Thought joining the church was salvation.,D.Confessing Jesus as Lord with his mouth and believing in God in his heart, he raised him from the dead."}, {"q": "What will happen to God if the truly saved persist in sinning? (Multiple choice)", "s": "Grace Discipline", "o": "A.Discipline him in all sorts of ways and bring him back,B.Let him continue to sin, regardless of his,C.May terminate his criminal life and take him back to his heavenly home, lest he sink,D.Immediately declare that he has lost his salvation"}, {"q": "There are eight words in the original text of the Bible, \"one salvation and eternal salvation.\"", "s": "Theological Conclusions"}, {"q": "Salvation is coming out of the darkness into the light, both out of the darkness and into the light.", "s": "Saving the Truth"}, {"q": "Since you are saved once and for all, you can grasp the blessings of heaven with one hand and the joys of this world''s sins with the other.", "s": "Saving the Truth"}, {"q": "Why do some people have doubts about “once saved, always saved”? How did you respond in this lesson?", "s": "Rescue Doubt"}, {"q": "How does God deal with truly saved people when they sin? What does this remind us of?", "s": "Grace Discipline"}]}, "ja": {"title": "レッスン19「一つの救いと永遠の救いの理論」", "content": "真に救われるとは，命の主権に従い，キリストに従うことです。この課では，一度限りの救いの教義の意味を注意深く検討し，自分自身を欺かないように，真の救いと偽の救いの証拠を見分けます。あなたが救いの証を知り，安心して主に従うことができますように。一度主に託されると，常に揺るぎなく揺るぎないものとなります。", "instructions": "", "guide": [{"title": "注意が必要な問題", "points": ["聖書にはない「一つの救い、永遠の救い」という八つの言葉", "神学探究の結論であり、神学界には依然として異なる見解がある", "意見の相違を理由に、他の人を異端者と特定しないでください"]}, {"title": "疑問はどこから来るのでしょうか？", "points": ["誰かが主を信じるのを見た後、人生は決して変わりません", "年に3回しか会わない「クリスマスクリスチャン」", "No Faith Core ：キリスト教ではなく、食べる、飲む、遊ぶ"]}, {"title": "真の救いとは何か", "points": ["ローマ10 ： 9 ：イエスを死人の中からよみがえらせる神を信じ、口で主として告白する", "口で主を認識する=召使いの立場に立って，主人があなたに指示することを何でも行います", "自分の心を信じる=イエスは受肉した神であり、古代の聖人や賢人だけではないと信じる"]}, {"title": "救いの誤った見方", "points": ["手を挙げたり，教会に参加したり，バプテスマを受けたりすることは，救いの確信とは等しくありません", "友人にバプテスマを受けるように設定する例：ただ水に浸かっただけだった", "繁栄神学、安価な恵み神学は聖書の福音ではありません"]}, {"title": "真の救いは人生を変える", "points": ["救われるということは、暗闇から光の中へ、出入りすることです。", "永遠の命を掴む舟と，罪の喜びを掴む舟の二つの舟に乗ることはできません。", "生まれ変わった人生はそれ自身の活力を持ち、神の至高の善に向かって進みます。"]}, {"title": "神の懲らしめ", "points": ["1コリント11 ： 30 ：聖餐を混乱させる者には，弱い者もいれば，死ぬ者もいる", "1コリント5 ： 5 ：魂の救いのために罪人をサタンに救う", "本当に救われた者は罪にとどまり，神は懲らしめ，"]}, {"title": "聖書の把握", "points": ["ヨハネ6 ：父がわたしに与えてくださったものは，すべて失われることはありません。", "主は父親のようなもので，子供を簡単に報告して断ち切ることはありません", "神からの保護、あなたは安心することができます"]}, {"title": "敬虔な心をもって", "points": ["「常に保存されている」を耽溺の言い訳として使用しないでください", "恵みに身震いし、主を大いなるものとして畏れ敬いなさい", "神の言葉は慰め，励まし，助けとなる"]}], "quizzes": [{"q": "あなたの口が________に支配されていて、あなたの心が神が死から________を彼に告げたと信じているなら、あなたは________するでしょう。", "s": "救いの確信"}, {"q": "わたしを遣わされた方は，わたしに与えられたものを________と呼び，終わりの日に彼をよみがえらせられました。", "s": "迷子にならないもの"}, {"q": "したがって、あなた方の中には多くの________と________があり、多くの死者がいます。", "s": "混乱の聖体拝領"}, {"q": "1つの救いと永遠の救いの8つの言葉は、神学的探求の結論である聖書________にあります。", "s": "神学的結論"}, {"q": "クリスチャンと自称する人もいますが、イースター、感謝祭、________の年に3回しか会っていません。", "s": "疑似キリスト教"}, {"q": "真の救いとは，単にバプテスマを受けたり，決断するために手を上げたりすることではなく，口でイエスを主と告白し，神を信じて死者の中から復活させることです。そうすれば，あなたは________となるでしょう。", "s": "救いの確信"}, {"q": "友人のシーンのためにバプテスマを受けた兄弟である牧師は、彼が初めて水に浸かっただけだと言いました。これは________としてカウントされませんでした。", "s": "真のバプテスマ"}, {"q": "神の恵みは何かを与えることを望んでいるだけでなく、________も含まれています。私たちが間違った道を進むことを主張するとき、神は私たちを連れ戻してくださいます。", "s": "恩寵の訓練"}, {"q": "パウロは，継母と姦淫した人を________に引き渡し，その人の肉体を堕落させて，主イエスの日にその人の魂が救われるように命じました。", "s": "教会の懲らしめ"}, {"q": "「一度救われれば，常に救われる」について，次の記述のうち，正しいものはどれですか。", "s": "神学的結論", "o": "A.聖書の原文にあるこれらの8つの言葉は明確な真理です。,B.これは神学的探求の結論であり、今日でも異なる見解があり、慎重に扱う必要があります,C.バプテスマを受けている限り，人生が変わったかどうかにかかわらず，救われます。,D.一度救われると、罪を犯すことができるので安心して、とにかく天国に行くことができます。"}, {"q": "ローマ人によれば，真に救われるとはどういう意味でしょうか。", "s": "救いの確信", "o": "A.教会に参加してバプテスマを受ける,B.説教挙手の決断,C.イエスを口で主として告白し，心の中で神を信じて，イエスを死人の中からよみがえらせました。,D.クリスチャンは年に3回会う"}, {"q": "主を信じた後も自分自身の中で生きている，人生で一度も変わったことのない人にとって，この課で最も適切な見解は何ですか。", "s": "本当に助かりました。", "o": "A.彼らは救われたに違いありません。,B.彼らが本当に救われているかどうかは深く考える価値があり，救いとは何なのかはまったくはっきりしないかもしれません。,C.彼らは再びバプテスマを受ける必要があります。,D.彼らは救いを失いました。"}, {"q": "次の人々の救いの認識のうち，ありのままで不正確なものはどれですか。（複数選択可）", "s": "本当に助かりました。", "o": "A.バプテスマを受けることは救いだと思いました。,B.説教が手を挙げて決断を下すことになると思って救われる,C.教会に加わることは救いだと思っていました。,D.イエスを口で主として告白し，心の中で神を信じて，イエスを死人の中からよみがえらせました。"}, {"q": "真に救われた者が罪を犯し続けると，神はどうなるでしょうか。（複数選択可）", "s": "恩寵の訓練", "o": "A.あらゆる方法で彼を訓練し、彼を連れ戻す,B.彼の罪に関係なく、彼が罪を犯し続けるようにしてください,C.彼が沈むことのないように、彼の犯罪生活を終わらせ、彼を天国の家に連れ戻すかもしれない,D.彼が救いを失ったことを直ちに宣言する"}, {"q": "聖書の原文には「一つの救いと永遠の救い」という8つの言葉があります。", "s": "神学的結論"}, {"q": "救いは，暗闇から光の中に，暗闇からも光の中にももたらされます。", "s": "真実を救う"}, {"q": "あなたは完全に救われているので，天の祝福を片手で，この世の罪の喜びを片手でつかむことができます。", "s": "真実を救う"}, {"q": "「一度救われれば，いつも救われる」という疑問を抱く人がいるのはなぜでしょうか。このレッスンでは，どのように対応しましたか。", "s": "救出の疑念"}, {"q": "真に救われた人が罪を犯したとき，神はどのように対処するのでしょうか。これは何を思い起こさせますか？", "s": "恩寵の訓練"}]}, "ko": {"title": "제 19과 하나의 구원과 영원한 구원에 대한 이론", "content": "진정으로 구원받는다는 것은 생명의 주권에 항복하고 그리스도를 따르는 것입니다. 이 수업에서는 일회성 구원의 교리의 의미를 주의 깊게 살펴보고 자신을 속이지 않도록 참되고 거짓된 구원의 증거를 분별할 것이다. 구원의 증거를 알고 안심하고 주님을 따르기를 바랍니다. 한 번 주님께 맡기면 항상 흔들리지 않고 흔들리지 않는다.", "instructions": "", "guide": [{"title": "주의가 필요한 문제", "points": ["성경에서 찾을 수 없는 \"하나의 구원, 영원한 구원\" 이라는 여덟 단어", "신학 탐구의 결론이며, 신학 공동체에는 여전히 다른 견해가 있습니다.", "의견 차이 때문에 다른 사람을 이단으로 규정하지 마세요."]}, {"title": "의심은 어디에서 오는가?", "points": ["주님을 믿는 사람을 본 후에도 삶은 변하지 않습니다.", "일 년에 단 세 번 만나는 ''크리스마스 크리스천''", "믿음의 핵심 없음: 기독교가 아닌 먹고, 마시고, 놀기"]}, {"title": "참된 구원이란 무엇인가?", "points": ["로마서 10: 9: 그의 입으로 예수님을 주님으로 고백하고, 그를 죽은 자 가운데서 살리시기 위해 하나님을 믿었습니다.", "입으로 주님을 인식하라 = 종의 입장에 서서 주인이 시키는 대로 하라", "네 마음을 믿어라 = 예수님이 고대 성인들과 현자들만이 아니라 성육신하신 하나님임을 믿어라"]}, {"title": "구원에 대한 잘못된 견해", "points": ["손을 들고, 교회에 가입하고, 침례를 받는 것은 구원의 확신과 같지 않습니다.", "침례받을 친구를 설정하는 예: 그냥 물에 몸을 담그는 것이었습니다.", "번영신학, 값싼 은혜신학은 성경적 복음서가 아니다"]}, {"title": "진정한 구원은 삶을 변화시킵니다", "points": ["구원받는다는 것은 어둠에서 벗어나 빛 속으로, 안팎으로 나아가는 것이다.", "두 배를 밟을 수 없다: 하나는 영생을 움켜쥐고 하나는 죄의 기쁨을 움켜쥐고", "거듭난 생명은 자신의 생명력을 지니고 하나님의 최고의 선하심을 향해 행진합니다."]}, {"title": "하나님의 징계", "points": ["고린도전서 11:30: 성찬을 혼동하는 자들, 어떤 이들은 연약하고 어떤 이들은 죽습니다", "고린도전서 5: 5: 영혼 구원을 위해 죄인을 사탄에게 넘겨주기", "진정으로 구원받은 자들은 죄 가운데 존속할 것이며, 하나님께서는 징계하시고 다시 돌아오게 하실 것입니다."]}, {"title": "성경적 이해", "points": ["요한복음 6장: 아버지께서 내게 주신 모든 것은 잃지 않을 것이다.", "주님은 아버지와 같아서 쉽게 보고하지 않으시고 아이를 잘라 버리실 것입니다.", "하나님으로부터의 보호, 편안함을 느낄 수 있습니다"]}, {"title": "경건한 마음으로", "points": ["방종을 핑계로 ''항상 저장됨'' 을 사용하지 마세요.", "은혜 안에서 떨고, 위대하신 주님을 경외하십시오", "하나님의 말씀은 위로와 격려와 도움이 됩니다"]}], "quizzes": [{"q": "당신의 입이 ________ 에 의해 지배되고 당신의 마음이 하나님께서 그에게 죽음으로부터 ________ 하라고 말씀하셨다고 믿는다면, 당신은 ________ 할 것입니다.", "s": "구원의 확신"}, {"q": "나를 보내신 분은 나를 ________ 라고 부르셨지만 마지막 날에 그를 일으켜 세우셨다는 뜻입니다.", "s": "길을 잃지 않는 것"}, {"q": "따라서 여러분 중에는 많은 ________ 및 ________ 이 있고, 많은 사망자가 있습니다.", "s": "혼란스러운 성체성사"}, {"q": "하나의 구원과 영원한 구원의 여덟 단어는 신학 탐구의 결론인 성경 ________ 에서 찾을 수 있습니다.", "s": "신학적 결론"}, {"q": "어떤 사람들은 스스로를 그리스도인이라고 부르며 부활절, 추수감사절, ________ 등 일 년에 세 번만 만난다.", "s": "유사 기독교인"}, {"q": "진정한 구원은 단순히 침례를 받거나 손을 들어 결정하는 것이 아니라 입으로 예수님을 주님으로 고백하고 하나님을 믿어 그분을 죽은 자 가운데서 살리는 것입니다. 그러면 여러분은 ________ 할 것입니다.", "s": "구원의 확신"}, {"q": "친구의 장면을 위해 침례를 받은 형제는 처음 물에 담갔을 뿐 ________ 로 계산되지 않는다고 말했다.", "s": "진정한 침례"}, {"q": "하나님의 은혜는 무언가를 주기를 원할 뿐만 아니라 ________ 을 (를) 포함합니다. 우리가 잘못된 길로 가기를 고집할 때, 하나님은 우리를 돌아오게 하십니다.", "s": "은혜의 징계"}, {"q": "바울은 계모와 간음한 사람을 ________ 에게 넘겨주고 그의 육체가 타락하여 주 예수님의 날에 그의 영혼이 구원을 받도록 명령했습니다.", "s": "교회 규율"}, {"q": "다음 중 “한 번 저장된 후에는 항상 저장됨” 에 대한 설명으로 옳은 것은?", "s": "신학적 결론", "o": "A.성경 원문에 나오는 이 여덟 단어는 분명한 진리입니다.,B.그것은 신학 탐구의 결론이며, 오늘날까지도 다른 견해가 있으며, 신중하게 다루어야합니다.,C.침례를 받는 한, 여러분의 삶이 변했는지 여부에 관계없이 여러분은 구원을 받을 것입니다.,D.일단 구원받으면 범죄를 저지를 수 있고, 어쨌든 천국에 갈 수 있다는 것을 안심할 수 있습니다."}, {"q": "로마서에 따르면, 진정으로 구원받는다는 것은 무엇을 의미하는가?", "s": "구원의 확신", "o": "A.교회에 가입하고 침례를 받으세요,B.설교는 손을 든다 결정,C.입으로 예수님을 주님으로 고백하고 마음속으로 하나님을 믿은 그는 예수님을 죽음에서 살렸습니다.,D.그리스도인들은 일 년에 세 번 만난다."}, {"q": "이 수업에서 자신의 삶에서 변화된 적이 없고 주님을 믿은 후에도 여전히 자신 안에 살고 있는 사람들에게 가장 적절한 견해는 무엇인가?", "s": "진정으로 구원을 받았습니다.", "o": "A.그들은 구원받았을 것입니다.,B.그들이 진정으로 구원받았는지는 생각해 볼 가치가 있으며, 구원이 무엇인지 명확하지 않을 수도 있습니다.,C.그들은 다시 침례를 받아야 합니다.,D.그들은 구원을 잃었습니다."}, {"q": "구원에 대한 사람들의 인식 중 어느 것이 그렇게 정확하고 부정확한가? (복수 선택)", "s": "진정으로 구원을 받았습니다.", "o": "A.침례를 받는 것이 구원이라고 생각했다.,B.설교가 손을 들어 결정을 내릴 것이라고 생각하면 구원받을 것입니다.,C.교회에 합류하는 것이 구원이라고 생각했다.,D.입으로 예수님을 주님으로 고백하고 마음속으로 하나님을 믿은 그는 예수님을 죽음에서 살렸습니다."}, {"q": "진정으로 구원받은 사람들이 죄를 계속 짓는다면 하나님은 어떻게 되시겠는가? (복수 선택)", "s": "은혜의 징계", "o": "A.온갖 방법으로 그를 징계하고 다시 데려오십시오.,B.그의 죄와 상관없이 계속 죄를 짓게 하십시오.,C.그가 가라앉지 않도록 그의 범죄 생활을 끝내고 하늘의 집으로 데려갈 수 있습니다.,D.즉시 그가 구원을 잃었다고 선언하십시오"}, {"q": "성경의 원문에는 \"하나의 구원과 영원한 구원\" 이라는 여덟 단어가 있습니다.", "s": "신학적 결론"}, {"q": "구원은 어둠에서 빛으로, 어둠에서 빛으로 들어오는 것입니다.", "s": "진실을 구하기"}, {"q": "단번에 구원받았기 때문에 한 손으로는 하늘의 축복을, 다른 한 손으로는 이 세상 죄의 기쁨을 붙잡을 수 있습니다.", "s": "진실을 구하기"}, {"q": "왜 어떤 사람들은 “한 번 저장되면 항상 저장됨” 에 대해 의구심을 갖는가? 이 수업에서 어떻게 대응했는가?", "s": "구조 의구심"}, {"q": "하나님께서는 진정으로 구원받은 사람들이 죄를 지을 때 어떻게 대처하시는가? 이것은 무엇을 상기시켜 주는가?", "s": "은혜의 징계"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773058100021','基要真理','第二十课 谁是撒旦和偶像','撒旦是因骄傲堕落的天使，昼夜迷惑控告人。本课认清仇敌的真面目，明白偶像的虚空，专一敬拜独一真神。愿你靠主站立，不再被迷惑捆绑。抵挡试探，靠主过圣洁生活。','[{"type": "verse", "q": "你们务要________魔鬼，魔鬼就必________你们逃跑了。", "o": "《雅各书》4章7节", "s": "抵挡魔鬼", "a": "抵挡|离开"}, {"type": "verse", "q": "明亮之星，早晨之子啊，你何竟从天________！你这攻败列国的，何竟被________在地上！", "o": "《以赛亚书》14章12节", "s": "撒旦堕落", "a": "坠落|砍倒"}, {"type": "verse", "q": "因为那在你们里面的，比那在________的更大。", "o": "《约翰一书》4章4节", "s": "主已得胜", "a": "世界"}, {"type": "fill", "q": "按照圣经，人死了之后是回不来的，不会变成________。", "o": "", "s": "人死不为鬼", "a": "鬼"}, {"type": "fill", "q": "撒旦本来是神所造极其完美的天使，因________想与神同等而堕落。", "o": "", "s": "撒旦堕落", "a": "骄傲"}, {"type": "fill", "q": "撒旦这个名字的意思是欺哄、迷惑、骗人，也是一个________者。", "o": "", "s": "撒旦特质", "a": "控告"}, {"type": "fill", "q": "圣经让我们看见，跟随撒旦一起堕落的天使，很可能占了全部天使的________。", "o": "", "s": "堕落天使", "a": "三分之一"}, {"type": "fill", "q": "撒旦被称为这个世界的王，牠掌控的是那些不尊神为大、________的人。", "o": "", "s": "世界之王", "a": "以自我为中心"}, {"type": "fill", "q": "启示录告诉我们，将来白色大宝座审判之后，撒旦要被丢在________里面。", "o": "", "s": "撒旦结局", "a": "火湖"}, {"type": "single", "q": "关于撒旦的来源，以下哪项符合圣经？", "o": "A.神创造了一个恶神与善神对打,B.撒旦是神所造的天使，因骄傲堕落，神没有创造撒旦,C.撒旦是人死后变成的鬼,D.撒旦与神是平起平坐的两位神", "s": "撒旦来源", "a": "B"}, {"type": "single", "q": "为什么神今天还没有消灭撒旦？", "o": "A.神打不过撒旦,B.神忘记了这件事,C.神有祂的时间表，今天还给人悔改、与神建立关系的时间,D.神纵容撒旦作恶", "s": "神的时间表", "a": "C"}, {"type": "single", "q": "关于偶像，以下哪项说法正确？", "o": "A.可以把明星神化，一生追随,B.可以把钱和儿女当作偶像,C.可以欣赏别人的杰出表现，但不可崇拜敬拜，神才是唯一追求对象,D.偶像崇拜只要不过分就可以", "s": "偶像真义", "a": "C"}, {"type": "multiple", "q": "撒旦有哪些特质？（多选）", "o": "A.欺哄迷惑人,B.控告破坏诋毁人,C.知道过去的事，常用来骗人,D.能预知将来的一切", "s": "撒旦特质", "a": "A|B|C"}, {"type": "multiple", "q": "以下哪些是把人或物偶像化的表现？（多选）", "o": "A.把明星的一颦一笑当作人生方向，盲目跟随,B.把钱当作偶像,C.把儿女当作偶像,D.欣赏别人在专业领域的杰出表现", "s": "偶像表现", "a": "A|B|C"}, {"type": "judge", "q": "人死了之后会变成鬼，冤死的人会穿红衣服回来。", "o": "", "s": "人死不为鬼", "a": "错"}, {"type": "judge", "q": "基督徒不必怕鬼，因为那在我们里面的比这世界更大。", "o": "", "s": "不必怕鬼", "a": "对"}, {"type": "judge", "q": "算命师讲过去的事很准，所以他讲将来的事也一定准。", "o": "", "s": "撒旦欺哄", "a": "错"}, {"type": "essay", "q": "圣经中的撒旦是谁？牠是怎样形成的？", "o": "", "s": "撒旦来源", "a": "撒旦是一位堕落的天使。神没有创造撒旦，神创造的是好的天使；其中一位本是受造极其完美的，却因骄傲想与神同等而堕落，还带走了约三分之一的天使。牠的名字意思是欺哄、迷惑、控告者，被称为这个世界的王。"}, {"type": "essay", "q": "为什么说把明星、钱财、儿女神化是偶像崇拜？基督徒该如何对待？", "o": "", "s": "偶像真义", "a": "偶像就是把人或物当作追求的方向、盲目跟随敬拜。但人不是敬拜的对象，神才是；每个人在神眼中都尊贵，耶稣的宝血为超级巨星流的和为你流的一模一样。可以欣赏别人在专业领域的杰出表现，但不可崇拜、不可盲目跟随，要按圣经原则处理人际关系。"}]','https://youtu.be/xr2FYaoyjmY
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134g5rl','quiz','[{"points": ["民间的吊死鬼、红衣女鬼是人自己创造的", "圣经说人死后去阴间，回不来", "交鬼时看到的“亲人”，是邪灵的装扮欺哄"], "title": "人死不会变鬼"}, {"points": ["邪灵知道过去的事，所以算命有时很准", "将来的事只有独一真神知道", "算命师比“1”的手势：任何结果都对，是讽刺"], "title": "邪灵的伎俩"}, {"points": ["神没有创造撒旦；神造的是好的天使", "一位天使领袖因骄傲想与神同等而堕落", "约三分之一的天使跟随堕落"], "title": "撒旦的来源"}, {"points": ["名字意思是欺哄、迷惑、骗人，也是控告者", "在约伯记、撒迦利亚书中控告、破坏、诋毁", "从天上堕落；主耶稣也看见"], "title": "撒旦的特质"}, {"points": ["指撒旦的控制：不尊神为大就落在罪的捆绑里", "出黑暗入光明，就是离开它的权势", "教会的元首是基督；在我们里面的比世界更大"], "title": "这世界的王"}, {"points": ["神的智慧高过我们，神有祂的时间表", "今天仍是救恩的门敞开的时候，给人悔改的时间", "神保守属祂的人，在苦难中不跌倒"], "title": "为什么神不消灭撒旦"}, {"points": ["白色大宝座审判后，撒旦被丢入火湖", "圣洁公义的神不让邪恶永远存在", "敌基督、假先知、古龙的结局都是火湖"], "title": "撒旦的结局"}, {"points": ["可以欣赏明星的才华，不要崇拜敬拜", "钱、儿女也不要当偶像", "十字架宝血为巨星流的，跟为你流的一样"], "title": "不要把人偶像化"}]','','20','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 20 Who are Satan and the Idols?", "content": "Satan, by the pride of fallen angels, deceives his accusers day and night. This lesson recognizes the true face of the enemy, understands the void of idols, and devotes itself to worshiping the one true God. May you stand in the Lord, no longer bound by confusion. Resist temptation and live a holy life through the Lord.", "instructions": "", "guide": [{"title": "People don''t turn into ghosts when they die", "points": ["Folk hanging ghosts and red-clothed female ghosts were created by people themselves.", "The Bible says that when a person dies, he goes to the underworld and cannot return.", "The \"relatives\" you see when you meet ghosts are demonic spirits pretending to be deceitful."]}, {"title": "Evil spirits'' tricks", "points": ["Evil spirits know the past, so fortune-telling is sometimes accurate", "The future is known only to the one true God.", "Fortune teller than \"1\" gesture: any result is correct, it is ironic"]}, {"title": "Satan''s Source", "points": ["God did not create Satan; God made good angels.", "An angelic leader falls because he is proud to want to be equal with God", "About a third of the angels follow the Fall"]}, {"title": "Satanic qualities", "points": ["Name means to deceive, confuse, deceive, accuser", "Accuse, destroy, denigrate in Job, Zechariah", "Fallen from heaven; the Lord Jesus saw it too"]}, {"title": "King of this world", "points": ["Refers to Satan''s control: disrespect for God falls into the bondage of sin", "Out of the darkness into the light, is to leave its power", "The Head of the Church is Christ; greater in us than the world"]}, {"title": "Why doesn''t God destroy Satan?", "points": ["God''s wisdom is higher than ours, and God has His timetable", "Today is still a time for repentance when the doors of salvation are open", "God keeps His people and does not stumble in their afflictions"]}, {"title": "The End of Satan", "points": ["After the Great White Throne Judgment, Satan was thrown into the Lake of Fire", "God of holiness and righteousness does not allow evil to exist forever.", "The end of the Antichrist, the False Prophet, the Dragon is the Lake of Fire"]}, {"title": "Don''t idolize", "points": ["Can appreciate the talent of the stars, do not worship and worship", "Don''t be an idol for money, children, etc.", "The blood of the cross flows like a giant star, just like the blood that flows for you."]}], "quizzes": [{"q": "You must ________ the devil, and the devil will ________ you flee.", "s": "Resist the Devil"}, {"q": "Bright Star, son of the morning, how can you be ________ from heaven! You who defeated the nations, how you were ________ on the ground!", "s": "The Fall of Satan"}, {"q": "For that which is in you is greater than that which is in ________.", "s": "The Lord has prevailed"}, {"q": "According to the Bible, people do not come back after they die, and they do not become ________.", "s": "People don''t die as ghosts"}, {"q": "Satan was originally an extremely perfect angel created by God, and fell because ________ wanted to be equal with God.", "s": "The Fall of Satan"}, {"q": "The name Satan means to deceive, to deceive, to deceive, and to be a ________.", "s": "Satanic Traits"}, {"q": "The Bible shows us that the fallen angels who followed Satan probably accounted for ________ of all the angels.", "s": "Fallen Angels"}, {"q": "Satan is known as the king of this world, and he rules over those who do not honor God as great and ________.", "s": "King of the World"}, {"q": "Revelation tells us that in the future, after the Great White Throne Judgment, Satan will be cast into ________.", "s": "Satan''s End"}, {"q": "Which of the following is biblical about Satan''s origin?", "s": "Satan''s Source", "o": "A.God created an evil god to fight with a good god,B.Satan is an angel created by God. God did not create Satan because of the fall of pride.,C.Satan is the ghost a person becomes after death.,D.Satan and God are two equal gods"}, {"q": "Why hasn''t God annihilated Satan today?", "s": "God''s timetable", "o": "A.God can''t beat Satan,B.God forgot about it.,C.God has His timetable, and today He gives people time to repent and build a relationship with Him,D.God allows Satan to do evil"}, {"q": "Which of the following statements is true about idols?", "s": "Idol True Meaning", "o": "A.Can deify stars and follow them for a lifetime,B.Money and children can be used as idols,C.You can appreciate the outstanding performance of others, but you can''t worship and worship, God is the only object of pursuit,D.Idolatry is fine as long as you don''t overdo it."}, {"q": "What are some characteristics of Satan? (Multiple choice)", "s": "Satanic Traits", "o": "A.Deceive and confuse,B.Accuse the saboteur,C.Knowing the past is often used to deceive people,D.Predict everything in the future"}, {"q": "Which of the following is an idolization of a person or thing? (Multiple choice)", "s": "Idolatry", "o": "A.Take the star''s smile as the direction of life and blindly follow it,B.Treat money like an idol,C.Treat your children as idols,D.Appreciate others'' professional excellence"}, {"q": "When a person dies, he will become a ghost, and the wrongdoer will come back in red.", "s": "People don''t die as ghosts"}, {"q": "Christians need not fear ghosts, for that which is in us is greater than the world.", "s": "Don''t be afraid of ghosts"}, {"q": "The fortune teller was very accurate about the past, so he must also be accurate about the future.", "s": "Satan deceives"}, {"q": "Who is Satan in the Bible? How did it form?", "s": "Satan''s Source"}, {"q": "Why is it idolatry to deify stars, money, and children? How should Christians be treated?", "s": "Idol True Meaning"}]}, "ja": {"title": "レッスン20サタンと偶像とは誰か？", "content": "サタンは，堕天使の高慢によって，昼も夜も告発者を欺きます。この課では，敵の真の顔を認識し，偶像の虚無を理解し，唯一の真の神を崇拝することに専念します。もはや混乱に縛られることなく、主の中に立つことができますように。誘惑に抵抗し，主を通して聖なる生活を送りましょう。", "instructions": "", "guide": [{"title": "人は死んでも幽霊にはならない", "points": ["ぶら下がっている幽霊や赤い服を着た女性の幽霊は、人々自身によって作られました。", "聖書には、人は死ぬと冥界に行き、戻ることはできないと書かれています。", "幽霊に会ったときに見える「親戚」は、偽りを装った悪魔の霊です。"]}, {"title": "悪霊のトリック", "points": ["悪霊は過去を知っているので、占いは時に正確です", "未来は唯一の真の神のみに知られています。", "「1」ジェスチャーよりも占い師：どんな結果でも正しい、それは皮肉です"]}, {"title": "サタンの源", "points": ["神は悪魔を造られたのではなく、善き天使を造られたのです。", "天使のようなリーダーは、神と対等であることを誇りに思っているために倒れます", "天使の約3分の1が堕落に従っています"]}, {"title": "悪魔的な資質", "points": ["名前は、欺く、混乱させる、欺く、告発することを意味します", "ヨブの中で非難、破壊、中傷、ゼカリヤ", "天から落ち、主イエスもそれを見た"]}, {"title": "この世界の王", "points": ["サタンの支配を指す：神への無礼は罪の束縛に陥る", "暗闇から光の中へ、その力を残すことです", "教会のかしらはキリストであり，わたしたちのうちにあって世よりも偉大である"]}, {"title": "なぜ神はサタンを滅ぼさないのでしょうか。", "points": ["神の知恵はわたしたちの知恵よりも高く，神には神のスケジュールがあります", "今日も，救いの扉が開かれている今，悔い改めの時があります", "神は御自分の民を守り，苦難の中でつまずくことはない"]}, {"title": "サタンの終わり", "points": ["大いなる白い玉座の裁きの後、サタンは火の湖に投げ込まれました", "神聖さと正義の神は，悪が永遠に存在することを許しません。", "反キリスト、偽預言者、ドラゴンの終わりは火の湖です"]}, {"title": "偶像化しないでください", "points": ["星の才能に感謝し、崇拝したり、崇拝したりしない", "お金や子供などでアイドルになってはいけません。", "十字架の血は、あなたのために流れる血のように、巨大な星のように流れています。"]}], "quizzes": [{"q": "あなたは悪魔を________しなければなりません、そして悪魔はあなたが逃げることを________します。", "s": "悪魔に抵抗"}, {"q": "明るい星、朝の息子よ、どうしてあなたは天国から________になれるのですか！諸国の民を打ち負かしたお前は、地上で________だった！", "s": "サタンの堕落"}, {"q": "なぜなら、あなたの中にあるものは、________の中にあるものよりも大きいからです。", "s": "主が勝利された"}, {"q": "聖書によると、人は死後に戻ってくることはなく、________になることもありません。", "s": "人は幽霊として死ぬことはありません"}, {"q": "サタンはもともと神によって創造された非常に完璧な天使であり、________が神と対等になりたかったために堕落しました。", "s": "サタンの堕落"}, {"q": "サタンという名前は，欺くこと，欺くこと，欺くこと，そして________になることを意味します。", "s": "悪魔的特性"}, {"q": "聖書は，サタンに従った堕天使がおそらくすべての天使の中で________を占めていたことを示しています。", "s": "堕天使"}, {"q": "サタンはこの世の王として知られており，偉大で________として神を敬わない者たちを支配しています。", "s": "世界の王"}, {"q": "啓示は，将来，大いなる白い御座の裁きの後，サタンが________に投げ込まれることを示しています。", "s": "サタンの終わり"}, {"q": "次のうち，サタンの起源について聖書的なものはどれですか。", "s": "サタンの源", "o": "A.神は善なる神と戦うために邪悪な神を創造した,B.サタンは神によって創造された天使です。神がサタンを創造されたのは、プライドの低下のためではありません。,C.サタンは、人が死後になる幽霊です。,D.サタンと神は2つの等しい神です"}, {"q": "なぜ神は今日，サタンを滅ぼされなかったのでしょうか。", "s": "神の時刻表", "o": "A.神はサタンを打ち負かすことはできません,B.神は忘れてしまった。,C.神には日程があり，今日，悔い改めて神との関係を築く時間を与えてくださる,D.神はサタンが悪を行うことを許します"}, {"q": "偶像について，次の記述のうち，正しいものはどれですか。", "s": "偶像の真の意味", "o": "A.星を神格化し、一生星を追いかけることができる,B.お金と子供は偶像として使うことができます,C.他者の優れた業績を評価することはできますが、崇拝や崇拝はできません。神だけが追求の対象です,D.偶像崇拝は、やり過ぎない限り問題ありません。"}, {"q": "サタンにはどのような特徴がありますか。（複数選択可）", "s": "悪魔的特性", "o": "A.騙して混乱させる,B.妨害者を非難する,C.過去を知ることは、人々を欺くためにしばしば使用されます,D.将来のすべてを予測する"}, {"q": "次のうち、人や物を崇拝しているものはどれですか？ （複数選択可）", "s": "偶像崇拝", "o": "A.星の笑顔を人生の方向として、盲目的にそれに従ってください,B.お金をアイドルのように扱う,C.お子様をアイドルとして扱う,D.他者のプロフェッショナルとしての卓越性を評価する"}, {"q": "人が死ぬと幽霊になり、悪人は赤くなって戻ってきます。", "s": "人は幽霊として死ぬことはありません"}, {"q": "クリスチャンは幽霊を恐れる必要はありません。なぜなら、私たちの中にあるものは世界よりも大きいからです。", "s": "幽霊を恐れる必要はありません"}, {"q": "占い師は過去について非常に正確だったので、将来についても正確でなければなりません。", "s": "サタンは欺く"}, {"q": "聖書の中でサタンとはだれですか。どのように形成されましたか？", "s": "サタンの源"}, {"q": "星やお金，子供を神格化することが偶像崇拝であるのはなぜでしょうか。クリスチャンはどのように扱われるべきでしょうか。", "s": "偶像の真の意味"}]}, "ko": {"title": "제 20과 사탄과 우상들은 누구인가?", "content": "사탄은 타락한 천사들의 교만으로 밤낮으로 고발자들을 속인다. 이 수업은 원수의 진정한 얼굴을 인식하고 우상의 공허함을 이해하며 유일하신 참 하나님을 경배하는 데 전념한다. 더 이상 혼란에 얽매이지 않고 주님 안에 서 있기를 바랍니다. 유혹에 저항하고 주님을 통해 거룩한 삶을 산다.", "instructions": "", "guide": [{"title": "사람들은 죽을 때 유령으로 변하지 않습니다.", "points": ["매달린 민속 유령과 붉은 옷을 입은 여성 유령은 사람들이 직접 만들었습니다.", "성경은 사람이 죽으면 지하세계로 가서 돌아갈 수 없다고 했습니다.", "유령을 만날 때 볼 수 있는 \"친척\" 은 속이는 척하는 악령입니다."]}, {"title": "악령의 속임수", "points": ["악령은 과거를 알고 있으므로 운세는 때때로 정확합니다.", "미래는 오직 한 분의 참된 하나님만이 아십니다.", "\"1\" 제스처보다 점쟁이: 모든 결과가 정확합니다. 아이러니합니다."]}, {"title": "사탄의 근원", "points": ["하나님은 사탄을 창조하지 않으셨고, 선한 천사들을 창조하셨습니다.", "천사의 지도자는 하나님과 동등해지기를 자랑스러워하기 때문에 넘어집니다.", "약 1/3의 천사들이 타락을 따른다"]}, {"title": "사탄의 특성", "points": ["이름은 속이고, 혼동하고, 속이고, 고발하는 것을 의미합니다.", "욥기, 스가랴에서 고발, 파괴, 폄하", "하늘에서 타락하셨다. 주 예수께서도 그것을 보셨다."]}, {"title": "이 세계의 왕", "points": ["사탄의 통제를 말합니다. 하나님을 경외하지 않는 것은 죄의 속박에 빠집니다.", "어둠에서 빛으로, 그 힘을 떠나는 것입니다", "교회의 머리는 그리스도이시며, 우리 안에서 세상보다 더 위대하십니다."]}, {"title": "하나님은 왜 사탄을 멸하지 않으시는가?", "points": ["하나님의 지혜는 우리보다 높으시고 하나님은 그분의 시간표를 가지고 계십니다.", "오늘도 구원의 문이 열려있는 회개의 시간입니다.", "하나님은 자기 백성을 지키시고 그들의 고난에 걸려 넘어지지 않으십니다."]}, {"title": "사탄의 종말", "points": ["대백좌 심판이 있은 후 사탄은 불못에 던져졌습니다.", "거룩함과 의로움의 하느님께서는 악이 영원히 존재하는 것을 허락하지 않으십니다.", "적그리스도의 종말, 거짓 선지자, 용은 불의 호수"]}, {"title": "우상화하지 마세요", "points": ["별의 재능을 감상할 수 있으며, 숭배하거나 숭배하지 않습니다.", "돈, 아이 등의 이유로 우상이 되지 마세요.", "십자가의 피는 마치 당신을 위해 흐르는 피처럼 거대한 별처럼 흐릅니다."]}], "quizzes": [{"q": "당신은 악마를 ________ 해야 하며, 악마는 당신이 도망칠 것입니다.", "s": "악마에 저항하기"}, {"q": "밝은 별아, 아침의 아들아, 네가 어찌하여 하늘로부터 ________ 이 될 수 있느냐! 열방을 물리친 자들아 너희가 어찌 그리 땅에 ________ 있었는지!", "s": "사탄의 타락"}, {"q": "왜냐하면 당신 안에 있는 것이 ________ 안에 있는 것보다 더 크기 때문입니다.", "s": "주님께서 승리하셨다"}, {"q": "성경에 따르면 사람은 죽은 후에 돌아오지 않으며 ________ 가 되지 않습니다.", "s": "사람들은 유령처럼 죽지 않습니다."}, {"q": "사탄은 원래 하나님에 의해 창조된 극도로 완전한 천사였으며, ________ 이 (가) 하나님과 동등해지기를 원했기 때문에 타락했습니다.", "s": "사탄의 타락"}, {"q": "사탄이라는 이름은 ________ 을 (를) 속이고, 속이고, 속이며, ______________________________________________________", "s": "사탄적 특성"}, {"q": "성경은 사탄을 따르는 타락한 천사들이 모든 천사 중 ________ 을 (를) 설명했을 것이라고 알려줍니다.", "s": "타락천사"}, {"q": "사탄은 이 세상의 왕으로 알려져 있으며, 하나님을 위대하고 ________ (으) 로 존경하지 않는 사람들을 다스립니다.", "s": "세계의 왕"}, {"q": "계시록은 앞으로 큰 백보좌 심판 후에 사탄이 ________ 에 던져질 것이라고 알려줍니다.", "s": "사탄의 종말"}, {"q": "다음 중 사탄의 기원에 대한 성경적인 것은 무엇인가?", "s": "사탄의 근원", "o": "A.하나님은 선한 신과 싸우기 위해 악한 신을 창조하셨습니다.,B.사탄은 하느님께서 창조하신 천사입니다. 하느님께서는 교만의 타락 때문에 사탄을 창조하신 것이 아닙니다.,C.사탄은 사람이 죽은 후에 되는 유령입니다.,D.사탄과 하나님은 동등한 두 신입니다."}, {"q": "하나님은 왜 오늘날 사탄을 멸망시키지 않으셨는가?", "s": "하나님의 시간표", "o": "A.하나님은 사탄을 이길 수 없습니다,B.하나님은 잊어버리셨습니다.,C.하나님께서는 그분의 시간표를 가지고 계시며, 오늘날 사람들에게 회개하고 그분과 관계를 맺을 시간을 주십니다.,D.하나님은 사탄이 악을 행하도록 허락하십니다."}, {"q": "다음 중 우상에 대한 설명으로 옳은 것은?", "s": "아이돌의 진정한 의미", "o": "A.별을 신격화하고 평생 동안 따라다닐 수 있음,B.돈과 자식은 우상으로 쓸 수 있다,C.다른 사람들의 탁월한 성과를 감상할 수는 있지만, 예배하고 숭배할 수는 없습니다. 하나님은 유일한 추구의 대상이십니다.,D.우상 숭배는 무리하지 않는 한 괜찮습니다."}, {"q": "사탄의 특징은 무엇인가? (복수 선택)", "s": "사탄적 특성", "o": "A.속이고 혼동하기,B.방해꾼을 고발하세요.,C.과거를 아는 것은 종종 사람들을 속이는 데 사용됩니다.,D.미래의 모든 것을 예측합니다."}, {"q": "다음 중 사람이나 사물에 대한 우상화는 무엇입니까? (복수 선택)", "s": "우상 숭배", "o": "A.별의 미소를 삶의 방향으로 삼고 맹목적으로 그것을 따르십시오.,B.돈을 우상처럼 대한다.,C.자녀를 우상처럼 대하라,D.다른 사람의 전문적인 우수성에 감사를 표합니다"}, {"q": "사람이 죽으면 그는 유령이 될 것이고, 죄인은 빨간색으로 돌아올 것입니다.", "s": "사람들은 유령처럼 죽지 않습니다."}, {"q": "그리스도인은 유령을 두려워 할 필요가 없습니다. 우리 안에있는 것이 세상보다 큽니다.", "s": "유령을 두려워하지 마세요"}, {"q": "점쟁이는 과거에 대해 매우 정확했으므로 미래에 대해서도 정확했음에 틀림없다.", "s": "사탄이 속임수"}, {"q": "성경에서 사탄은 누구인가? 어떻게 형성되었나요?", "s": "사탄의 근원"}, {"q": "왜 별, 돈, 아이들을 신격화하는 것이 우상 숭배인가? 그리스도인은 어떻게 대우받아야 하는가?", "s": "아이돌의 진정한 의미"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773058459738','基要真理','第二十一课 属灵争战','得救后仍有属灵争战，圣经教导不是躲开而是胜过：抵挡魔鬼牠就逃跑。本课讲争战的本质、仇敌的诡计与得胜兵器。愿你穿戴神的军装，打美好的仗。靠主站立得稳，得胜有余。','[{"type": "verse", "q": "【经文填空】我从前________有你，现在________看见你", "o": "《约伯记》42章5节", "s": "约伯的见证", "a": "风闻|亲眼"}, {"type": "verse", "q": "【经文填空】你们________神，神就________你们；务要________魔鬼，魔鬼就必________你们逃跑了", "o": "《雅各书》4章7节", "s": "抵挡魔鬼", "a": "亲近|亲近|抵挡|离开"}, {"type": "verse", "q": "【经文填空】________倚靠你的，你必________他十分平安", "o": "《以赛亚书》26章3节", "s": "坚心倚靠", "a": "坚心|保守"}, {"type": "fill", "q": "视频中提到苦难的来源至少有三方面：全人类对神的________、人________的结果，以及________的攻击。", "o": "", "s": "苦难来源", "a": "背离|犯罪|恶者"}, {"type": "fill", "q": "根据启示录12章，撒但从天上被________下来，气愤愤地去与神的儿女们________。", "o": "", "s": "撒但被击落", "a": "击落|争战"}, {"type": "fill", "q": "主祷文中主耶稣教导我们祷告：不叫我们遇见________，救我们脱离________。", "o": "", "s": "主祷文", "a": "试探|凶恶"}, {"type": "fill", "q": "彼得书信形容撒但如同________的狮子，遍地游行，寻找可________的人。", "o": "", "s": "吼叫的狮子", "a": "吼叫|吞吃"}, {"type": "fill", "q": "以弗所书6章的属灵军装中，真理当作________束腰，公义当作________，圣灵的宝剑就是________。", "o": "", "s": "属灵军装", "a": "带子|护心镜|神的道"}, {"type": "fill", "q": "希伯来书11章说：信是所望之事的________，是未见之事的________。", "o": "", "s": "信的定义", "a": "实底|确据"}, {"type": "single", "q": "约伯遭遇撒但攻击后，对神的认识有何改变？", "o": "A.更加怀疑神,B.从风闻变为亲眼看见,C.决定离弃信仰,D.认为神不公平", "s": "约伯的认识", "a": "B"}, {"type": "single", "q": "基督徒落在难处中，按视频所讲第一步应当怎么做？", "o": "A.到处找人赶鬼,B.先安静下来，在神面前省察自己,C.立刻辞职换环境,D.指责是别人的错", "s": "面对难处", "a": "B"}, {"type": "single", "q": "以下哪一项不是以弗所书6章提到的属灵军装？", "o": "A.真理当作带子束腰,B.公义当作护心镜,C.金钱当作盾牌,D.救恩的头盔", "s": "属灵军装", "a": "C"}, {"type": "multiple", "q": "（多选）以下哪些是以弗所书6章提到的属灵军装？", "o": "A.真理当作带子束腰,B.公义当作护心镜,C.平安的福音当作鞋穿在脚上,D.成功神学的应许", "s": "属灵军装", "a": "A|B|C"}, {"type": "multiple", "q": "（多选）视频中提到苦难的来源包括以下哪些？", "o": "A.全人类背离神导致地受咒诅,B.人犯罪的结果,C.恶者的攻击,D.神故意刁难人", "s": "苦难来源", "a": "A|B|C"}, {"type": "judge", "q": "基督徒信主后就完全豁免于今世的苦难。", "o": "", "s": "苦难与信徒", "a": "错"}, {"type": "judge", "q": "面对撒但的攻击，圣经教导我们要靠主胜过它，而不是躲开它。", "o": "", "s": "胜过攻击", "a": "对"}, {"type": "judge", "q": "一个人好吃懒做，就一定是身上有“懒鬼”需要赶鬼。", "o": "", "s": "分辨处境", "a": "错"}, {"type": "essay", "q": "视频中提到，基督徒落在难处中，不知是撒但攻击、自己犯罪还是大环境造成时，应当如何面对？", "o": "", "s": "面对难处", "a": "先安静下来不慌乱，省察自己有无得罪神、执意犯罪之处；若有就认罪悔改，若没有就安心把处境交给神。相信若非神允许处境不会临到，神必给力量面对，坚心倚靠祂继续往前行，并在处境中做该做的事。"}, {"type": "essay", "q": "为什么视频反对把什么问题都归为“鬼附”、动不动就赶鬼的做法？", "o": "", "s": "正确分辨", "a": "因为很多难处是犯罪后果、大环境或身体因素造成的，把责任推给鬼附是逃避自己在神面前站稳立场。圣灵九果之一是节制，基督徒应在神的光中用正确态度回应处境。滥用赶鬼还会给弟兄姐妹带来更大伤害，如视频中癌症姐妹被赶鬼后病情仍恶化、传道人却怪她没信心的例子。"}]','https://youtu.be/4KT8S-lEMhI
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134gmla','quiz','[{"title": "苦难的困惑：得救之后为何仍有苦难", "points": ["基督徒得救后仍面对今世各样的苦难与挑战", "有人质疑：神不是爱我们吗，撒旦不是不及神吗", "本课要回答苦难的来源，以及如何靠主胜过"]}, {"title": "苦难的三重来源", "points": ["全人类对神的背离：大地受咒诅，天灾人祸由此而来", "犯罪的结果：以自我为中心，伤害别人也伤害自己", "恶者的攻击：撒旦气愤愤地下去，与神的儿女争战"]}, {"title": "约伯的见证：攻击中的正直人", "points": ["约伯行事正直、远离恶，仍遭撒旦攻击", "神允许攻击，却有智慧保守，能化腐朽为神奇", "约伯从“风闻”到“亲眼看见”，对神的认识更深"]}, {"title": "面对攻击：胜过而非躲避", "points": ["主祷文与约翰福音十七章：神保守我们脱离那恶者", "雅各书：务要抵挡魔鬼，魔鬼就必离开你们逃跑了", "留在主的羊圈里，不要跑出去给魔鬼留地步"]}, {"title": "辨别的误区：不必事事归因灵界", "points": ["一件事的发生常是多种因素错综复杂，不必纠结来源", "把懒惰、疾病都归因鬼附，是错误的教导", "圣灵所结果子的最后一个是节制，要活出健康的生命"]}, {"title": "信心的本质：希伯来书的见证人", "points": ["信是所望之事的实底，是未见之事的确据", "见证人在各自的处境中为荣耀神而活", "得医治是见证，未得医治仍专心依靠神是更大的见证"]}, {"title": "落在难处中的回应之道", "points": ["先安静：得救在乎归回安息，得力在乎平静安稳", "省察自己：犯罪就认罪，无罪就安心把处境交给神", "坚心倚赖神，弟兄姐妹彼此相爱、互相扶持"]}, {"title": "全副的军装：以弗所书第六章", "points": ["真理当作带子束腰，公义当作护心镜", "平安的福音当作鞋穿在脚上，信德当作藤牌", "戴上救恩的头盔，拿着圣灵的宝剑就是神的道"]}]','','21','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 21 Spiritual Warfare", "content": "There is still spiritual warfare after salvation, and the Bible teaches not to hide but to prevail: to resist the devil and flee. This lesson is about the nature of war, the tricks of the enemy, and the weapons of victory. May you put on the armor of God and fight a good battle. Stand firm in the Lord, and be victorious.", "instructions": "", "guide": [{"title": "The Perplexity of Suffering: Why Suffering Remains After Salvation", "points": ["After being saved, Christians still face all kinds of hardships and challenges in this world.", "Some people question: Doesn''t God love us, and isn''t Satan inferior to God?", "This lesson answers the sources of suffering and how to overcome the Lord"]}, {"title": "The Triple Source of Suffering", "points": ["The deviation of all mankind from God: the earth is cursed, and natural and man-made disasters come from it", "Consequences of Crime: Self-Centered, Hurting Others and Hurting Myself", "Attack of the Evil One: Satan goes down angry and fights against the children of God"]}, {"title": "Job''s Testimony: The Righteous in Attack", "points": ["Job walked uprightly, stayed away from evil, and was still attacked by Satan.", "God allows attack, but has wisdom and protection, and can turn decay into magic.", "Job learned more about God from “hearing” to “seeing” with his own eyes"]}, {"title": "Facing Attack: Overcoming rather than dodging", "points": ["Lord''s Prayer and John 17: God Keeps Us Free from the Evil One", "James: Resist the devil and he will flee from you", "Stay in the Lord''s sheepfold and don''t run out to make room for the devil"]}, {"title": "Distinguishing Misconceptions: Not Attributing Things to the Spirit World", "points": ["A thing often happens when multiple factors are intricate and there is no need to worry about the source", "Attributing laziness and illness to demons is a false teaching", "The final fruit of the Holy Spirit is temperance, to live a healthy life"]}, {"title": "The Nature of Faith: A Witness to Hebrews", "points": ["Faith is the substance of what is hoped for, the confirmation of what is not seen.", "Witnesses live for the glory of God in their respective situations", "Getting healed is a testimony, but still concentrating on relying on God without healing is a greater testimony."]}, {"title": "How to Respond in Difficult Situations", "points": ["Quiet first: salvation is about returning to rest, strength is about peace and tranquility", "Examine yourself: if you commit a crime, you confess your guilt. If you are not guilty, you can safely surrender your situation to", "Firmly rely on God, brothers and sisters love and support each other"]}, {"title": "Full Armor: Ephesians 6", "points": ["Truth as a belt, righteousness as a goggle", "The Gospel of Peace is worn as a shoe on the feet, and Faith as a rattan.", "Putting on the helmet of salvation and holding the sword of the Holy Spirit is the Word of God"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] I used to have you in ________, now I see you in ________", "s": "Job''s Testimony"}, {"q": "[Scripture Fill in the Blank] You ________ God, God will ________ you; be sure to ________ the devil, the devil will ________ you ran away", "s": "Resist the Devil"}, {"q": "[Scripture Fill in the Blank] ________ Rely on you, you will ________ He is very safe", "s": "Rely on it with all your heart"}, {"q": "There are at least three sources of suffering mentioned in the video: the ________ of all mankind against God, the results of the ________ of man, and the attack of the ________.", "s": "Source of Suffering"}, {"q": "According to Revelation 12, Satan was ________ from heaven and went angrily to ________ with the children of God.", "s": "Satan was shot down"}, {"q": "In the Lord''s Prayer, the Lord Jesus teaches us to pray: Do not let us meet ________, save us from ________.", "s": "The Lord’s Prayer"}, {"q": "The Epistle of Peter describes Satan as a lion of ________, marching through the land in search of someone who could be ________.", "s": "Roaring Lion"}, {"q": "In the spiritual armor of Ephesians 6, truth is girded as ________, righteousness is ________, and the sword of the Holy Spirit is ________.", "s": "Spiritual Uniform"}, {"q": "Hebrews 11 says: Faith is the ________ of things hoped for, the ________ of things not seen.", "s": "Definition of Letter"}, {"q": "How did Job''s understanding of God change after he was attacked by Satan?", "s": "Job''s acquaintance", "o": "A.Be more suspicious of God,B.From wind to seeing with your own eyes,C.Deciding to Abandon the Faith,D.Thinking God is unfair"}, {"q": "What should a Christian do in the first step of a difficult situation as described in the video?", "s": "Facing difficulties", "o": "A.Finding people everywhere to drive out ghosts,B.First, calm down and examine yourself before God.,C.Immediate resignation and change of environment,D.Accusations are someone else''s fault"}, {"q": "Which of the following is not a spiritual uniform mentioned in Ephesians 6?", "s": "Spiritual Uniform", "o": "A.Truth as a belt,B.Justice as a protective goggle,C.Money as a shield,D.Helm of Salvation"}, {"q": "(Multiple choice) Which of the following is a spiritual uniform mentioned in Ephesians 6?", "s": "Spiritual Uniform", "o": "A.Truth as a belt,B.Justice as a protective goggle,C.The Gospel of Peace is worn as a shoe on your feet,D.The Promise of Prosperity Theology"}, {"q": "(Multiple choice) Which of the following sources of suffering are mentioned in the video?", "s": "Source of Suffering", "o": "A.All mankind is cursed for turning away from God.,B.Consequences of human crimes,C.Attack of the Evil One,D.God deliberately makes things difficult"}, {"q": "The Christian, being a believer, is wholly exempt from mortal suffering.", "s": "Suffering and Believers"}, {"q": "In the face of Satan''s attacks, the Bible teaches that we should rely on the Lord to overcome it, not avoid it.", "s": "Victory over attack"}, {"q": "If a person is delicious and lazy, he must have a \"lazy ghost\" on his body to drive out ghosts.", "s": "Distinguish the situation"}, {"q": "In the video, it is mentioned that when a Christian falls in a difficult situation and does not know whether it is Satan''s attack, his own crime, or the result of the general environment, how should he face it?", "s": "Facing difficulties"}, {"q": "Why does the video oppose the practice of classifying any problem as \"ghost attachment\" and casting out ghosts without moving?", "s": "Correct discrimination"}]}, "ja": {"title": "レッスン21霊的な戦い", "content": "救いの後にはまだ霊的な戦いがあり、聖書は隠れるのではなく、勝つこと、すなわち悪魔に抵抗して逃げることを教えています。このレッスンでは、戦争の性質、敵のトリック、勝利の武器について説明します。神の武具を身に着けて、良い戦いをしてください。主にあってしっかりと立ち，勝利を収めなさい。", "instructions": "", "guide": [{"title": "苦しみの戸惑い：救いの後も苦しみが残る理由", "points": ["救われた後も，クリスチャンはこの世でいろいろな困難や試練に直面しています。", "神はわたしたちを愛しておらず，サタンは神に劣っているのではないかと疑う人もいます。", "この課では，苦しみの源と，主を克服する方法について答えます"]}, {"title": "苦しみの3つの源泉", "points": ["全人類の神からの逸脱：地球は呪われ、自然災害と人為的災害がそこから生じる", "犯罪の結果：自己中心的、他人を傷つける、自分自身を傷つける", "悪者の攻撃：サタンは怒って倒れ、神の子供たちと戦う"]}, {"title": "ヨブの証：攻撃を受けた義人", "points": ["ヨブはまっすぐに歩み、悪から遠ざかり、それでもサタンに襲われました。", "神は攻撃を許しますが、知恵と保護を持ち、腐敗を魔法に変えることができます。", "ヨブは，自分の目で「聞く」ことから「見る」ことまで，神についてさらに学びました"]}, {"title": "攻撃に立ち向かう：回避ではなく克服する", "points": ["主の祈りとヨハネ17章：神はわたしたちを邪悪な者から解放してくださる", "ジェームズ：悪魔に抵抗して、彼はあなたから逃げるでしょう", "主の羊囲いにとどまり、悪魔のために場所を空けるために逃げないでください"]}, {"title": "誤解を区別する：物事を霊界のせいにしない", "points": ["複数の要因が複雑で、ソースを心配する必要がない場合によく起こります", "怠惰と病気を悪魔のせいにすることは，誤った教えです", "聖霊の最後の実りは、健康的な生活を送るための節制です"]}, {"title": "信仰の本質：ヘブル人への証人", "points": ["信仰とは，望まれていることの本質であり，見られていないことを確認することです。", "証人はそれぞれの状況で神の栄光のために生きる", "癒されることは証ですが，それでも癒されずに神に頼ることに集中することは，より大きな証です。"]}, {"title": "困難な状況での対応方法", "points": ["まず静かに：救いとは安息に戻ることであり、強さとは平安と安らぎです", "自分自身を調べる：あなたが犯罪を犯した場合、あなたはあなたの罪を告白します。あなたが有罪でない場合、あなたは安全にあなたの状況を放棄することができます", "神にしっかりと頼り、兄弟姉妹は互いに愛し合い、支え合う"]}, {"title": "フルアーマー：エペソ6", "points": ["ベルトのような真実、ゴーグルのような正義", "平和の福音は足の上の靴のように、信仰は藤のように身に着けられています。", "救いの兜をかぶり、聖霊の剣を持つことは神の言葉です"]}], "quizzes": [{"q": "〔聖句の穴埋め〕以前は________にいましたが、今は________でお会いしましょう", "s": "ヨブの証"}, {"q": "〔聖句の穴埋め〕あなたがたは________神に近づきなさい。そうすれば、神はあなたがたに________くださいます。悪魔には________しなさい。そうすれば、悪魔はあなたがたから________逃げ去ります。", "s": "悪魔に抵抗"}, {"q": "[Scripture Fill in the Blank] ________あなたに頼ってください。________彼は非常に安全です", "s": "心から頼りにしてください"}, {"q": "ビデオで言及されている苦しみの源は少なくとも3つあります：神に対する全人類の________、人の________の結果、および________の攻撃。", "s": "苦しみの源"}, {"q": "黙示録12章によれば，サタンは________天から来て，神の子供たちと共に________に怒りをもって行きました。", "s": "サタンは撃墜された"}, {"q": "主の祈りの中で，主イエスは祈るように教えておられます。わたしたちを________から救ってください。________に会わせないでください。", "s": "主の祈り"}, {"q": "ペテロの手紙によると，サタンは________の獅子であり， ________である可能性のある人物を探して地上を行進しています。", "s": "咆哮するライオン"}, {"q": "エペソ6章の霊的な武具では，真理は________として帯びており，義は________ ，聖霊の剣は________です。", "s": "スピリチュアルユニフォーム"}, {"q": "ヘブル11章には次のように書かれています。「信仰とは，望まれていることの________ ，見られていないことの________です。", "s": "レターの定義"}, {"q": "サタンに攻撃された後，ヨブの神に対する理解はどのように変化しましたか。", "s": "ジョブの知人", "o": "A.神をもっと疑え,B.風から自分の目で見るまで,C.信仰を捨てる決意,D.神は不公平だと考える"}, {"q": "ビデオで説明されているように，クリスチャンは困難な状況の最初のステップで何をすべきでしょうか。", "s": "困難に直面する", "o": "A.ゴーストを追い払うために世界中の人々を見つける,B.まず、落ち着いて、神の前で自分自身を調べてください。,C.直ちに辞任し、環境を変える,D.告発は誰かのせいです"}, {"q": "エペソ6章で言及されている霊的な制服ではないのは，次のうちどれですか。", "s": "スピリチュアルユニフォーム", "o": "A.ベルトとしての真実,B.保護ゴーグルとしての正義,C.盾としてのお金,D.救いの兜"}, {"q": "（複数選択可）エペソ6章で言及されている霊的な制服は，次のうちどれですか。", "s": "スピリチュアルユニフォーム", "o": "A.ベルトとしての真実,B.保護ゴーグルとしての正義,C.平和の福音はあなたの足の上の靴のように身に着けられています,D.繁栄神学の約束"}, {"q": "（複数選択可）ビデオで言及されている苦しみの原因は次のうちどれですか？", "s": "苦しみの源", "o": "A.全人類は，神から背を向けたために呪われています。,B.人間犯罪の結果,C.悪者の攻撃,D.神は意図的に物事を困難にする"}, {"q": "クリスチャンは、信者であるため、死すべき苦しみから完全に免除されています。", "s": "苦しみと信者"}, {"q": "サタンの攻撃に直面して，聖書は，それを避けるのではなく，克服するために主に頼るべきであると教えています。", "s": "攻撃に勝利"}, {"q": "美味しくて怠け者なら、幽霊を追い払うためには、体に「怠け者の幽霊」がいるに違いありません。", "s": "状況を区別する"}, {"q": "ビデオでは、クリスチャンが困難な状況に陥り、それがサタンの攻撃なのか、自分の罪なのか、一般的な環境の結果なのかわからないとき、どのように直面すべきかについて言及されています。", "s": "困難に直面する"}, {"q": "何らかの問題を「幽霊愛着」に分類し、動かずに幽霊を追い出す慣習に反対するのはなぜですか？", "s": "正しい差別"}]}, "ko": {"title": "제21과 영적 전쟁", "content": "구원 후에도 여전히 영적 전쟁이 있으며, 성경은 숨지 말고 승리하라고 가르칩니다. 마귀를 대적하고 도망치는 것입니다. 이 교훈은 전쟁의 본질, 적의 속임수, 승리의 무기에 관한 것입니다. 하나님의 갑옷을 입고 선한 싸움을 싸우시길 바랍니다. 주님 안에 굳게 서서 승리하십시오.", "instructions": "", "guide": [{"title": "고통의 복잡성: 고통이 구원 후에 남아있는 이유", "points": ["구원받은 후에도 그리스도인들은 여전히 이 세상에서 온갖 고난과 도전에 직면해 있습니다.", "어떤 사람들은 질문합니다: 하나님은 우리를 사랑하지 않으시고 사탄은 하나님보다 열등하지 않습니까?", "이 과는 고통의 근원과 주님을 극복하는 방법에 대해 답한다."]}, {"title": "고통의 3중 근원", "points": ["온 인류가 하나님에게서 벗어남: 땅은 저주받았고, 자연재해와 인간이 만든 재앙은 거기서 나왔다.", "범죄의 결과: 자기 중심적, 타인을 해치는 행위, 자신을 해치는 행위", "악마의 공격: 사탄은 분노하여 내려가서 하나님의 자녀들과 싸웁니다."]}, {"title": "욥의 간증: 공격하는 의인", "points": ["욥은 바르게 걸었고, 악에서 멀어졌으며, 여전히 사탄의 공격을 받았다.", "하나님은 공격을 허용하시지만 지혜와 보호가 있으며 부패를 마법으로 바꿀 수 있습니다.", "욥은 자신의 눈으로 “듣는” 것부터 “보는” 것까지 하나님에 대해 더 많이 배웠습니다."]}, {"title": "페이스 어택: 회피하기보다는 극복하기", "points": ["주님의 기도와 요한복음 17장: 하나님은 악한 자에게서 우리를 자유롭게 하십니다", "야고보서: 악마를 물리치면 그는 당신을 피할 것입니다.", "주님의 양 우리에 머물면서 마귀를 위한 공간을 마련하기 위해 뛰쳐나가지 마십시오."]}, {"title": "오해의 구별: 사물을 영의 세계에 귀속시키지 않음", "points": ["여러 요인이 복잡하고 출처에 대해 걱정할 필요가 없을 때 종종 발생하는 일", "게으름과 질병을 악마에게 돌리는 것은 잘못된 가르침입니다.", "성령의 마지막 열매는 건강한 삶을 사는 절제입니다."]}, {"title": "신앙의 본질: 히브리인에 대한 증인", "points": ["믿음은 바라는 것의 실체이며 보이지 않는 것의 확인입니다.", "증인들은 각자의 상황에서 하나님의 영광을 위해 산다.", "치유받는 것은 간증이지만, 여전히 치유 없이 하나님께 의지하는 것에 집중하는 것은 더 큰 간증입니다."]}, {"title": "어려운 상황에서 대응하는 방법", "points": ["먼저 조용함: 구원은 쉼으로 돌아가는 것이고, 힘은 평화와 평온에 관한 것입니다.", "자신을 살펴보십시오: 범죄를 저지르면 자신의 죄책감을 고백합니다. 죄책감이 없다면 자신의 상황을 안전하게 포기할 수 있습니다.", "하나님을 굳게 의지하십시오. 형제자매들은 서로 사랑하고 지지합니다."]}, {"title": "전신갑주: 에베소서 6장", "points": ["띠와 같은 진리, 고글과 같은 의로움", "평화의 복음은 발에 신을 신듯이, 믿음은 등나무처럼 신는다.", "구원의 투구를 쓰고 성령의 검을 잡는 것은 하나님의 말씀입니다."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 예전에는 ________ 에서 만나셨는데, 지금은 ________ 에서 뵙겠습니다.", "s": "욥의 간증"}, {"q": "[Scripture Fill in the Blank] 당신은 ________ 하나님, 하나님은 당신을 ________ 할 것입니다. 악마를 ________ 하고 악마는 ________ 할 것입니다.", "s": "악마에 저항하기"}, {"q": "[Scripture Fill in the Blank] ________ 당신을 의지하세요, 당신은 ________ 그는 매우 안전합니다", "s": "온 마음을 다해 의지하세요"}, {"q": "동영상에는 하나님을 대적하는 모든 인류의 ________, 인간의 ________ 의 결과 및 ________ 의 공격이라는 세 가지 고통의 원천이 언급되어 있습니다.", "s": "고통의 근원"}, {"q": "요한계시록 12장에 따르면, 사탄은 하늘에서 ________ 이었고 하나님의 자녀들과 함께 ________ 에게 화를 냈습니다.", "s": "사탄이 격추됨"}, {"q": "주 예수께서는 주님의 기도에서 우리에게 기도하라고 가르치십니다. ________ 을 (를) 만나지 못하게 하시고 ________ 에서 우리를 구하소서.", "s": "주님의 기도"}, {"q": "베드로 서신은 사탄을 ________ 의 사자로 묘사하며, ________ 이 될 수 있는 사람을 찾아 그 땅을 행진한다.", "s": "포효하는 사자"}, {"q": "에베소서 6 장의 영적 갑옷에서 진리는 ________ (으) 로, 의는 ________ (으) 로, 성령의 검은 ________ (으) 로 띠를 띠고 있습니다.", "s": "영적인 제복"}, {"q": "히브리서 11장은 이렇게 말합니다. 신앙은 바라는 것들의 ________, 보이지 않는 것들의 __________________________________________________________", "s": "글자의 정의"}, {"q": "욥이 사탄의 공격을 받은 후 하나님에 대한 욥의 이해는 어떻게 바뀌었는가?", "s": "욥의 지인", "o": "A.하나님을 더 의심하십시오,B.바람에서 눈으로 직접 보기까지,C.신앙을 버리기로 결심함,D.신이 불공평하다고 생각하는 것"}, {"q": "그리스도인은 동영상에 설명된 대로 어려운 상황의 첫 번째 단계에서 무엇을 해야 하는가?", "s": "어려움에 직면", "o": "A.유령을 쫓아낼 사람들을 어디에서나 찾는 것,B.먼저 진정하고 하나님 앞에서 자신을 점검하십시오.,C.즉각적인 사임 및 환경 변화,D.고발은 다른 사람의 잘못입니다"}, {"q": "다음 중 에베소서 6장에 언급된 영적 제복이 아닌 것은?", "s": "영적인 제복", "o": "A.띠로서의 진리,B.보호 고글로서의 정의,C.방패로서의 돈,D.구원의 투구"}, {"q": "(복수 선택) 다음 중 에베소서 6장에 언급된 영적 제복은 무엇입니까?", "s": "영적인 제복", "o": "A.띠로서의 진리,B.보호 고글로서의 정의,C.평화의 복음은 여러분의 발에 신발처럼 착용됩니다.,D.번영신학의 약속"}, {"q": "(복수 선택) 다음 중 동영상에 언급된 고통의 원인은 무엇인가요?", "s": "고통의 근원", "o": "A.모든 인류는 하나님께 등을 돌렸기 때문에 저주를 받습니다.,B.인간 범죄의 결과,C.악마의 공격,D.하나님은 일부러 일을 어렵게 만드신다."}, {"q": "그리스도인은 신자이기 때문에 필멸의 고통에서 완전히 면제됩니다.", "s": "고통과 신자"}, {"q": "사탄의 공격에 직면하여 성경은 우리가 그것을 피하지 말고 그것을 극복하기 위해 주님을 의지해야한다고 가르칩니다.", "s": "공격에 대한 승리"}, {"q": "맛있고 게으른 사람은 몸에 ''게으른 귀신'' 이 있어야 귀신을 쫓아낼 수 있다.", "s": "상황을 구분합니다."}, {"q": "동영상에서 그리스도인이 어려운 상황에 빠지고 그것이 사탄의 공격인지, 자신의 범죄인지, 또는 일반적인 환경의 결과인지 모를 때 어떻게 직면해야 한다고 언급된다.", "s": "어려움에 직면"}, {"q": "왜 동영상은 문제를 \"유령 첨부\" 로 분류하고 움직이지 않고 유령을 쫓아내는 관행에 반대합니까?", "s": "올바른 차별"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773058778280','基要真理','第二十二课 苦难与罪','苦难根源是神人关系破裂。神的爱治本：差独生子亲身为我们受苦。本课从苦难看神的爱，学习在苦难中的回应。愿你在苦难中经历神的同在与安慰。在泪水中仍赞美信实的主。','[{"type": "verse", "q": "【经文填空】在世上你们有________，但你们可以________，我已经________了世界", "o": "《约翰福音》16章33节", "s": "胜过苦难", "a": "苦难|放心|胜了"}, {"type": "verse", "q": "【经文填空】受造之物________在虚空之下，切望等候神的________显出来", "o": "《罗马书》8章19节", "s": "受造之物叹息", "a": "服|众子"}, {"type": "verse", "q": "【经文填空】神________世人，甚至将他的________赐给他们，叫一切________他的，不至灭亡，反得永生", "o": "《约翰福音》3章16节", "s": "神爱世人", "a": "爱|独生子|信"}, {"type": "fill", "q": "苦难不是神创造的：人________以前没有苦难，将来________里也没有眼泪、悲哀和痛苦。", "o": "", "s": "苦难非神造", "a": "犯罪|新天新地"}, {"type": "fill", "q": "从圣经真理看，所有苦难的来源是________关系的破裂。", "o": "", "s": "苦难根源", "a": "神人"}, {"type": "fill", "q": "苦难可分为天灾与________，人类历史中人祸制造的苦难远远________天灾。", "o": "", "s": "天灾人祸", "a": "人祸|大过"}, {"type": "fill", "q": "神学上有一句话：苦难是上帝的________，提醒人在苦难中谦卑下来，看见自己的有限。", "o": "", "s": "苦难的意义", "a": "传声筒"}, {"type": "fill", "q": "真正的无辜只有一位，就是________基督；彼拉多三次审判都说查不出他有________。", "o": "", "s": "无罪的代替", "a": "耶稣|罪"}, {"type": "fill", "q": "神今天没有立即审判罪恶，不是纵容或忘记，乃是________；今天仍然是________广传的恩典时代。", "o": "", "s": "神的宽容", "a": "宽容|福音"}, {"type": "single", "q": "按视频所讲，神处理苦难问题的方式是？", "o": "A.像救火员一样随叫随到解决表面问题,B.治本：恢复神人关系，更新人的生命,C.把苦难全部立刻挪去,D.让人靠自己积功德抵消", "s": "神的智慧", "a": "B"}, {"type": "single", "q": "视频中说，把责任都推给亚当夏娃的做法对吗？", "o": "A.对，都是亚当的错,B.不对，我们自己也常不尊神为大,C.对，与我们无关,D.无所谓", "s": "认罪悔改", "a": "B"}, {"type": "single", "q": "“盖棺论定”的说法按圣经真理应当如何理解？", "o": "A.人死后一切就结束了,B.盖棺没有论定，白色大宝座前才是论定,C.死后靠子孙烧纸钱决定,D.轮回转世重新来过", "s": "最后审判", "a": "B"}, {"type": "multiple", "q": "（多选）视频中提到，人自己定义的错误的“爱”包括以下哪些？", "o": "A.溺爱,B.盲爱,C.建立在真理基础上的爱,D.迷爱", "s": "真爱", "a": "A|B|D"}, {"type": "multiple", "q": "（多选）按视频所讲，神没有立即处理一切罪恶的原因包括？", "o": "A.神纵容罪恶,B.神忘记了,C.神宽容，给人回转认识神的机会,D.今天仍是福音广传的恩典时代", "s": "神的宽容", "a": "C|D"}, {"type": "judge", "q": "圣经应许基督徒信主之后就无灾无难、一切顺利。", "o": "", "s": "成功神学", "a": "错"}, {"type": "judge", "q": "神的爱是建立在真理的基础之上，而不是由人自己定义。", "o": "", "s": "神的爱", "a": "对"}, {"type": "judge", "q": "成功神学“信耶稣一切顺利发财”的说法符合圣经真理。", "o": "", "s": "成功神学", "a": "错"}, {"type": "essay", "q": "视频如何解释“天灾也是神人关系破裂的结果”？", "o": "", "s": "天灾的来源", "a": "神创造大地时看一切都甚好（创世记1章）；人背离神后地受了咒诅，罗马书8章说受造之物服在虚空之下、失去原被造的目的。大地原是有规律的创造，受咒诅后出现天灾地变，提醒人若没有神的护理世界就会如此，也显明人的能力有限，人在许多天灾面前其实无能为力。"}, {"type": "essay", "q": "为什么神不立刻审判今世一切的不公不义？", "o": "", "s": "神的时间", "a": "因为神是宽容的，今天仍是恩典时代，给人回转、认识神、传福音的机会；若神今天就审判一切罪恶，恩典就结束了，每个人都要立刻面对审判台。圣洁公义的神必在祂的时间（白色大宝座前）处理一切罪恶，盖棺没有论定。"}]','https://youtu.be/biAQvg_fb_k
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134PIHW','quiz','[{"title": "苦难的困惑：世人对神的质疑", "points": ["世人对基督徒的常见挑战：若有慈爱又大能的神，为何世上有苦难", "以结果反推原因，得出没有神的结论，这也是许多宗教共同面对的问题", "这是以人为的角度思想人与神的关系，但不是唯一的方向"]}, {"title": "圣经看苦难：两段时间无苦难", "points": ["圣经有两段时间没有苦难：人犯罪以前，以及主再来后进入的新天新地", "启示录说新天新地没有眼泪、悲哀、哭号、疼痛，以前的事都过去了", "神从未告诉基督徒信主之后就无灾无难、一切顺利，这是圣经清楚的宣告"]}, {"title": "苦难的源头：神人关系破裂", "points": ["创世纪记载神创造伊甸园时一切甚好，神人关系正常，是理想的环境", "人要以自己为中心，配合撒旦自高、要与神同等，神人关系断裂", "神人关系的破坏是所有苦难的来源，人受造的环境也随之受破坏"]}, {"title": "人祸远大于天灾：罪性的无限扩张", "points": ["人祸是人自己造成的，纵观历史，人祸制造的苦难远远大过天灾", "人以自我为中心，从个人到民族、国家、集团彼此对抗、杀人无数", "两次世界大战就是人罪性扩张的明证，总不能说是神造成的"]}, {"title": "天灾的由来：大地受了咒诅", "points": ["天灾也是神人关系破坏的结果，人犯罪后地受了咒诅", "罗马书8章说受造之物伏在虚空之下，一同等候神的众子显出来", "苦难是上帝的传声筒，使人谦卑，看见自己的有限而转向创造的主"]}, {"title": "神的爱：救火员与领航员", "points": ["世人期待的神像救火员：有苦难时才出现灭火，问题解决了生命却不变", "圣经启示的神是领航员：天天带领人活出健康正确的生命", "神先恢复神人关系、更新人的价值观生命观，而非只解决眼前的问题"]}, {"title": "十字架：无罪代替有罪的爱", "points": ["真正无辜的只有一位，就是耶稣基督；彼拉多三次审判都查不出祂有罪", "基督为我们死，神的爱在此向我们显明了，神治本而非只治标", "圣经是救赎之书：救我们出黑暗入光明，活在神的恩典与圣灵的带领中"]}, {"title": "神的时间：宽容中的永恒盼望", "points": ["神会处理苦难，只是按祂的时间，不是按我们的时间", "彼得书信说神今天没有处理不是纵容或忘记，乃是宽容，给人回转的机会", "基督徒带着使命活在有限的今生，在永恒盼望中靠主面对苦难"]}]','','22','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 22 Suffering and Sin", "content": "The root of suffering is the breakdown of the relationship between God and man. God''s love governs the root cause: He sends His only begotten Son to suffer for us personally. This lesson looks at God''s love from affliction and learns to respond in affliction. May you experience God''s presence and comfort in your afflictions. Still praising the faithful Lord in tears.", "instructions": "", "guide": [{"title": "The Perplexity of Suffering: The World''s Questioning of God", "points": ["A Common Challenge for Christians: Why is there suffering in the world when there is a loving and powerful God?", "Reverse the cause with the result and conclude that there is no God, which is also a common problem faced by many religions.", "This is an artificial way of thinking about the relationship between man and God, but it is not the only direction"]}, {"title": "Biblical Perspective on Suffering: Two Periods Without Suffering", "points": ["There are two periods in the Bible when there is no suffering: before sin, and after the Lord''s return into the new heavens and the new earth.", "Apocalypse says that there are no tears, sorrows, cries, and pains in the new heavens and new earth, and the previous things are over.", "God has never told Christians that after believing in the Lord, there will be no disaster, everything will be fine, this is a clear declaration of the Bible"]}, {"title": "Source of Suffering: God-Man Relationship Breakdown", "points": ["Genesis records that when God created the Garden of Eden, everything was very good, and the relationship between God and man was normal, which is an ideal environment.", "People should take themselves as the center, cooperate with Satan''s ego, be equal with God, and the relationship between God and man should be broken.", "The destruction of the relationship between God and man is the source of all suffering, and the man-made environment is also destroyed."]}, {"title": "Man-made disasters far outweigh natural disasters: sinful infinite expansion", "points": ["Man-made disasters are caused by man himself. Throughout history, the suffering caused by man-made disasters has far exceeded that of natural disasters.", "People are self-centered, from individuals to nations, countries, and groups to each other, killing countless people", "The two world wars are proof of man''s sinful expansion, and cannot be said to have been caused by God."]}, {"title": "Origin of the natural disaster: the earth is cursed", "points": ["Natural disasters are also the result of the destruction of the relationship between God and man. People are cursed after committing crimes.", "Romans 8 says that creatures lie beneath the void, waiting together for the sons of God to appear.", "Suffering is God''s voice, humbling people to see their limitations and turn to the Creator."]}, {"title": "God''s Love: Firefighters and Navigators", "points": ["Expected firefighters of the world''s idols: when there is suffering, the fire is extinguished, the problem is solved, but the life remains unchanged", "The God of biblical revelation is the navigator: leading people to a healthy and correct life every day", "God first restores the relationship between God and man, updating people''s values and outlook on life, rather than just solving the immediate problem."]}, {"title": "The Cross: Innocence Replaces Guilty Love", "points": ["There is only one true innocent, and that is Jesus Christ, whose guilt Pilate found not guilty on three occasions.", "Christ died for us, and God''s love is here to show us that God governs the cause, not just the mark.", "The Bible is the Book of Redemption: Bringing us out of darkness into light and living in the grace of God and the guidance of the Holy Spirit"]}, {"title": "God''s Time: Eternal Hope in Tolerance", "points": ["God will deal with suffering only in His time, not ours.", "Peter writes that what God is not dealing with today is not indulgence or forgetting, but tolerance, giving people a chance to turn back", "Christians live in limited mortal life with a mission, facing suffering through the Lord in eternal hope"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] In the world you have ________, but you can ________, I have ________ the world", "s": "Victory over Suffering"}, {"q": "[Scripture Fill in the Blank] The created thing ________ is under the void, eager to wait for God''s ________ to appear", "s": "Created Beings Sigh"}, {"q": "[Scripture fills in the blanks] God ________ people, even gave them his ________, so that all his ________ will not perish, but have eternal life", "s": "God Loves The Common People"}, {"q": "Suffering was not created by God: there was no suffering before ________, and there will be no tears, sorrow, or pain in the future ________.", "s": "Suffering is not divine"}, {"q": "From biblical truth, the source of all suffering is the breakdown of ________ relationships.", "s": "Root of Suffering"}, {"q": "Suffering can be divided into natural disasters and ________. The suffering caused by man-made disasters in human history is far from ________ natural disasters.", "s": "natural and man-made disaster"}, {"q": "There is a saying in theology: Suffering is God''s ________, reminding people to humble themselves in suffering and see their limitations.", "s": "The Meaning of Suffering"}, {"q": "There is but one true innocent, and that is Christ ________; and Pilate, on three occasions, did not find out that he had ________.", "s": "A substitute for innocence"}, {"q": "God does not immediately judge sin today, not to condone or forget, but to ________; today is still ________ the era of grace.", "s": "God''s Tolerance"}, {"q": "According to the video, how does God deal with suffering?", "s": "The Wisdom of God", "o": "A.Solve surface problems on call like a firefighter,B.Governance: Restoring the relationship between God and man and renewing human life,C.Get all the suffering out of here right now.,D.Let people offset on their own merit"}, {"q": "The video says it''s right to put the blame on Adam and Eve?", "s": "Confession and repentance", "o": "A.Yeah, it''s all Adam''s fault.,B.No, we often do not respect God as great ourselves,C.Yeah, it''s none of our business.,D.No opinion"}, {"q": "How should the term “coffin conclusion” be understood in light of biblical truth?", "s": "The Last Judgment", "o": "A.When a person dies, it''s all over.,B.The coffin is undecided, the white throne is the conclusion,C.After death, it is decided by the grandchildren to burn paper money,D.Reincarnation Reincarnated"}, {"q": "(Multiple choice) In the video, it is mentioned that the wrong “love” defined by people themselves includes which of the following?", "s": "true love", "o": "A.manja,B.Blind Love,C.Love built on truth,D.Fetish"}, {"q": "(Multiple choice) According to the video, the reasons why God did not deal with all sins immediately include?", "s": "God''s Tolerance", "o": "A.God condones sin,B.God forgets.,C.God is tolerant, giving people the opportunity to return to knowing God,D.Today is still the Age of Grace when the Gospel was widely preached"}, {"q": "The Bible promises that after Christians believe in the Lord, they will be safe from disaster and all will be well.", "s": "Success theology"}, {"q": "God''s love is based on truth, not man''s own definition.", "s": "The Love of God"}, {"q": "The prosperity theology statement that “all goes well with believing in Jesus” is consistent with biblical truth.", "s": "Success theology"}, {"q": "How does the video explain that \"natural disasters are also the result of the breakdown of the relationship between God and man\"?", "s": "Sources of Natural Disasters"}, {"q": "Why doesn''t God immediately judge all the injustices of this world?", "s": "Time of God"}]}, "ja": {"title": "レッスン22苦しみと罪", "content": "苦しみの根源は、神と人間の関係の崩壊です。神の愛が根本的な原因を支配しています。神はご自分の独り子をわたしたちのために苦しませるために遣わされます。この課では，苦難から神の愛に目を向け，苦難に対処することを学びます。あなたが苦難の中で神の臨在と慰めを経験することができますように。まだ涙を流して忠実な主を賛美しています。", "instructions": "", "guide": [{"title": "苦しみの戸惑い：世界の神への問いかけ", "points": ["クリスチャンに共通する課題：愛に満ちた力強い神がおられるのに，なぜ世の中に苦しみがあるのでしょうか。", "その結果で原因を逆転させ、多くの宗教が直面している共通の問題である神がいないと結論づけます。", "これは人間と神との関係についての人為的な考え方ですが、唯一の方向性ではありません"]}, {"title": "苦しみに関する聖書の視点：苦しみのない2つの期間", "points": ["聖書には，苦しみがない時期が2つあります。罪の前と，主が新しい天と新しい地に再臨された後です。", "アポカリプスは、新しい天と新しい地には涙、悲しみ、叫び、痛みがなく、以前のものは終わったと言います。", "神はキリスト教徒に、主を信じた後、災害はなく、すべてがうまくいくと言ったことはありません。これは聖書の明確な宣言です"]}, {"title": "苦しみの源：神と人間の関係の崩壊", "points": ["創世記によると、神がエデンの園を造ったとき、すべてが非常に良く、神と人間の関係は正常であり、理想的な環境であったと記録されています。", "人は自らを中心とし、サタンのエゴに協力し、神と対等であり、神と人との関係を断ち切るべきである。", "神と人との関係の破壊はすべての苦しみの源であり、人為的な環境も破壊されます。"]}, {"title": "人為的災害は自然災害をはるかに上回る：罪深い無限の拡大", "points": ["人為的な災害は人間自身が引き起こすものであり、人為的な災害によって引き起こされる苦しみは歴史を通じて自然災害をはるかに上回ってきました。", "個人から国家、国、グループまで、人々は自己中心的であり、数え切れないほどの人々を殺しています", "二つの世界大戦は、人間の罪深い拡張の証拠であり、神によって引き起こされたとは言えません。"]}, {"title": "自然災害の起源：地球は呪われている", "points": ["自然災害も神と人との関係の破壊の結果であり、人は罪を犯した後に呪われます。", "ローマ8章には，被造物は空虚の下に横たわり，神の子たちが現れるのを一緒に待っていると書かれています。", "苦しみは神の声であり、人々が自分の限界を見て創造主に向かうことを謙虚にします。"]}, {"title": "神の愛：消防士とナビゲーター", "points": ["世界のアイドルの予想される消防士：苦しみがあるとき、火は消え、問題は解決されますが、人生は変わりません", "聖書の啓示の神はナビゲーターであり、人々を毎日健康で正しい生活に導きます", "神はまず神と人間の関係を回復させ、差し迫った問題を単に解決するのではなく、人々の価値観と人生観を更新します。"]}, {"title": "十字架：無実が罪深い愛に取って代わる", "points": ["真の罪のない人はただ一人，それはイエス・キリストです。ピラトは3回，その罪を無罪としました。", "キリストはわたしたちのために死なれました。神の愛は，印だけでなく，神が原因を支配しておられることを示すためにここにあります。", "聖書は贖いの書です：私たちを暗闇から光の中に連れ出し、神の恵みと聖霊の導きの中で生きる"]}, {"title": "神の時：寛容さにおける永遠の希望", "points": ["神は苦しみに対処されるのはご自分の時だけであり，わたしたちの時ではありません。", "ペテロは、神が今日対処しているのは耽溺や忘却ではなく、寛容であり、人々に引き返す機会を与えていると書いています", "クリスチャンは，使命を持って限られた現世の生活を送り，永遠の希望をもって主を通して苦しみに直面しています"]}], "quizzes": [{"q": "〔聖句の穴埋め〕あなたが持っている世界では________、しかしあなたは________することができます、私は________世界を持っています", "s": "苦しみに勝利する"}, {"q": "[Scripture Fill in the Blank]創造されたもの________は空虚の下にあり、神の________が現れるのを待ち望んでいます", "s": "創造された存在のため息"}, {"q": "[聖書は空白を埋める]神________の人々は、彼の________のすべてが滅びることなく、永遠の命を持つように、彼らに彼の________を与えました", "s": "神は世界を愛しておられる"}, {"q": "苦しみは神によって創造されたものではありません。________以前には苦しみはなく、将来________には涙、悲しみ、痛みはありません。", "s": "苦しみは神のものではない"}, {"q": "聖書の真理から，すべての苦しみの源は________関係の崩壊です。", "s": "苦しみの根源"}, {"q": "苦しみは自然災害と________に分けられ、人類史上の人為的災害によって引き起こされた苦しみは________の自然災害とは程遠い。", "s": "自然災害と人為的災害"}, {"q": "神学には次のようなことわざがあります。「苦しみは神の________であり，苦しみの中で自分自身を謙遜にし，自分の限界を見るように人々に思い出させます。", "s": "苦しみの意味"}, {"q": "真の罪のない人はただ一人，それはキリスト________です。ピラトは3回，自分が________を持っていたことを知りませんでした。", "s": "無実の代わり"}, {"q": "神は今日，罪を直ちに裁かれるのではなく，容認したり忘れたりするのではなく， ________を裁かれるのです。今日は依然として________恵みの時代です。", "s": "神の寛容"}, {"q": "ビデオによると，神は苦しみにどのように対処しておられますか。", "s": "神の知恵", "o": "A.消防士のようにオンコールで表面の問題を解決,B.ガバナンス：神と人間の関係を回復し、人間の生活を新しくする,C.今すぐここからすべての苦しみを取り除いてください。,D.人々が自分のメリットでオフセットできるようにする"}, {"q": "ビデオによると、アダムとイブに責任を負わせるのは正しいことですか？", "s": "告白と悔い改め", "o": "A.ああ、すべてアダムのせいだ。,B.いいえ、私たちはしばしば自分自身を偉大なものとして神を尊重しません,C.ああ、俺たちには関係ない。,D.関係ありません"}, {"q": "「棺の結論」という用語は，聖書の真理に照らしてどのように理解すべきでしょうか。", "s": "最後の審判", "o": "A.人が死ぬと、すべてが終わる。,B.棺は決まっておらず、白い玉座が結論です,C.死後、孫が紙幣を燃やすことを決める,D.転生転生"}, {"q": "（複数選択可）ビデオでは、人々自身が定義した間違った「愛」には、次のうちどれが含まれていると言及されていますか？", "s": "真実の愛", "o": "A.ドーティング,B.盲目の愛,C.真実の上に築かれた愛,D.フェチ"}, {"q": "（複数選択可）ビデオによると，神がすべての罪にすぐに対処しなかった理由には，次のようなものが含まれていますか。", "s": "神の寛容", "o": "A.神は罪を赦してくださる,B.神は忘れる。,C.神は寛容であり、人々に神を知ることに戻る機会を与えます,D.今日は，福音が広く宣べ伝えられた恵みの時代です。"}, {"q": "聖書は，クリスチャンが主を信じた後，災害から安全になり，すべてがうまくいくと約束しています。", "s": "成功神学"}, {"q": "神の愛は，人間自身の定義ではなく，真理に基づいています。", "s": "神の愛"}, {"q": "「イエスを信じることはすべてうまくいく」という繁栄神学の言葉は，聖書の真理と一致しています。", "s": "成功神学"}, {"q": "「自然災害も神と人との関係の崩壊の結果である」とビデオはどのように説明していますか？", "s": "自然災害の発生源"}, {"q": "なぜ神はこの世のすべての不正を直ちに裁かれないのでしょうか。", "s": "神の時間"}]}, "ko": {"title": "제 22과 고통과 죄", "content": "고통의 뿌리는 하나님과 인간 사이의 관계의 붕괴입니다. 하나님의 사랑은 근본 원인을 지배합니다. 그분은 독생자를 보내셔서 우리를 위해 개인적으로 고난을 겪게 하십니다. 이 수업은 고난으로부터 하나님의 사랑을 바라보고 고난 속에서 대응하는 법을 배운다. 여러분이 고난 속에서 하나님의 임재와 위로를 경험하기를 바랍니다. 여전히 눈물로 신실하신 주님을 찬양합니다.", "instructions": "", "guide": [{"title": "고난의 당혹감: 세상에 대한 하나님의 질문", "points": ["그리스도인들이 공통적으로 겪는 어려움: 사랑이 많고 전능하신 하나님이 계시는데 왜 세상에는 고통이 있는가?", "그 결과로 원인을 뒤집고 많은 종교가 직면한 공통된 문제이기도 한 신은 없다는 결론을 내린다.", "이것은 인간과 하나님의 관계에 대한 인위적인 사고 방식이지만, 그것이 유일한 방향은 아닙니다."]}, {"title": "고난에 대한 성경적 관점: 고난 없는 두 시기", "points": ["성경에는 고난이 없는 두 시기가 있습니다. 죄가 있기 전과 주님께서 새 하늘과 새 땅으로 돌아오신 후입니다.", "묵시록은 새 하늘과 새 땅에는 눈물과 슬픔과 외침과 고통이 없고 이전 것은 끝났다고 말합니다.", "하나님은 그리스도인들에게 주님을 믿은 후에는 재앙이 없을 것이며 모든 것이 잘 될 것이라고 말씀하신 적이 없습니다. 이것은 성경의 분명한 선언입니다."]}, {"title": "고통의 원천: 신-인간 관계 붕괴", "points": ["창세기는 하나님이 에덴 동산을 창조하실 때 모든 것이 매우 좋았으며 하나님과 인간의 관계는 정상이었으며 이상적인 환경이라고 기록하고 있습니다.", "사람들은 자신을 중심으로 삼고 사탄의 자존심에 협력하며 하나님과 동등해야 하며 하나님과 인간의 관계가 깨져야 합니다.", "하나님과 인간 관계의 파괴는 모든 고통의 근원이며, 인간이 만든 환경도 파괴됩니다."]}, {"title": "인간이 만든 재난은 자연 재난보다 훨씬 큽니다: 죄 많은 무한 확장", "points": ["인간이 만든 재난은 인간이 직접 일으킨다. 역사를 통틀어 인간이 만든 재난으로 인한 고통은 자연재해의 고통을 훨씬 뛰어넘었다.", "사람들은 개인에서 국가, 국가 및 집단에 이르기까지 자기 중심적이며 수많은 사람들을 죽입니다.", "두 번의 세계 대전은 인간의 죄의 확장의 증거이며, 하나님에 의해 야기되었다고 말할 수 없습니다."]}, {"title": "자연재해의 기원: 지구는 저주받았다", "points": ["자연재해는 하나님과 인간의 관계가 파괴된 결과이기도 합니다. 사람들은 범죄를 저지른 후 저주를 받습니다.", "로마서 8 장은 피조물이 공허함 아래에 누워 하나님의 아들들이 나타나기를 함께 기다린다고 말합니다.", "고통은 하나님의 음성이며, 사람들이 자신의 한계를 보고 창조주께 의지하도록 낮추는 것입니다."]}, {"title": "하나님의 사랑: 소방관과 항해사", "points": ["세계 우상의 예상 소방관: 고통이있을 때 불은 꺼지고 문제는 해결되지만 삶은 변하지 않습니다.", "성경적 계시의 하나님은 매일 사람들을 건강하고 올바른 삶으로 이끄시는 항해자이십니다.", "하나님께서는 먼저 하나님과 인간 사이의 관계를 회복하셔서 당면한 문제를 해결하는 것이 아니라 삶에 대한 사람들의 가치관과 전망을 업데이트하십니다."]}, {"title": "십자가: 죄 없는 사랑이 죄 없는 사랑을 대신한다", "points": ["참된 무죄자는 오직 한 분뿐입니다. 바로 예수 그리스도입니다. 빌라도의 죄는 세 번이나 무죄로 판명되었습니다.", "그리스도는 우리를 위해 죽으셨고, 하나님의 사랑은 마크뿐만 아니라 하나님이 원인을 지배한다는 것을 보여주기 위해 여기에 있습니다.", "성경은 구속의 책입니다: 우리를 어둠에서 빛으로 이끌어 내고 하나님의 은혜와 성령의 인도하심 안에서 살아가게 하소서."]}, {"title": "하나님의 시간: 관용에 대한 영원한 희망", "points": ["하나님께서는 우리의 고통이 아니라 그분의 때에만 고통을 다루실 것입니다.", "베드로는 하나님께서 오늘날 다루지 않으시는 것은 방종이나 망각이 아니라 관용이며, 사람들에게 등을 돌릴 기회를 주신다고 기록합니다.", "그리스도인들은 사명을 가지고 제한된 필멸의 삶을 살아가며 영원한 소망 안에서 주님을 통한 고난에 직면합니다."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 세상에는 ________ 이 있지만, ________ 할 수 있습니다. 나는 ________ 세계를 가지고 있습니다.", "s": "고통에 대한 승리"}, {"q": "[Scripture Fill in the Blank] 피조물 ________ 은 (는) 하나님의 ________ 이 (가) 나타나기를 간절히 바라고 있습니다.", "s": "창조된 존재 한숨"}, {"q": "[경전은 빈칸을 채웁니다] 하나님 ________ 사람들은, 심지어 자신의 ______________________________________________________________________________________________________________", "s": "하나님은 세상을 사랑하십니다"}, {"q": "고통은 하나님에 의해 창조되지 않았습니다. ________ 이전에는 고통이 없었고, 앞으로는 눈물, 슬픔 또는 고통이 없을 것입니다 ________.", "s": "고통은 신성한 것이 아닙니다"}, {"q": "성경의 진리에서 모든 고통의 원천은 ________ 관계의 붕괴입니다.", "s": "고통의 뿌리"}, {"q": "고통은 자연 재해와 ________ 로 나눌 수 있습니다. 인류 역사에서 인간이 만든 재해로 인한 고통은 ________ 자연 재해와는 거리가 멀다.", "s": "자연재해 및 인공재해"}, {"q": "신학에는 다음과 같은 말이 있습니다. 고통은 하나님의 ________ 이며, 사람들에게 고통 속에서 자신을 낮추고 자신의 한계를 보도록 상기시킵니다.", "s": "고통의 의미"}, {"q": "참된 무죄자는 오직 한 분뿐입니다. 그것은 그리스도 ________ 입니다. 빌라도는 세 번이나 자신이 ________ 을 가지고 있다는 것을 알지 못했습니다.", "s": "무죄의 대용품"}, {"q": "하나님께서는 오늘날 죄를 즉각적으로 심판하지 않으시고, ________ 을 (를) 용서하거나 잊지 않으십니다. 오늘날은 여전히 ________ 은총의 시대입니다.", "s": "하나님의 관용"}, {"q": "동영상에 따르면, 하나님은 고난을 어떻게 다루시는가?", "s": "하나님의 지혜", "o": "A.소방관처럼 통화 중 표면 문제 해결,B.거버넌스: 하나님과 인간의 관계를 회복하고 인간의 삶을 새롭게 함,C.지금 당장 모든 고통에서 벗어나세요.,D.사람들이 자신의 장점을 상쇄하도록 하십시오"}, {"q": "비디오에 따르면 아담과 하와를 비난하는 것이 옳다고요?", "s": "고백과 회개", "o": "A.네, 모두 아담의 잘못입니다.,B.아니요, 우리는 종종 하나님을 우리 자신만큼 위대하게 존중하지 않습니다.,C.네, 저희가 상관할 바가 아닙니다.,D.상관없어"}, {"q": "“관의 결론” 이라는 용어는 성경적 진리에 비추어 어떻게 이해되어야 하는가?", "s": "최후의 심판", "o": "A.사람이 죽으면 모든 것이 끝납니다.,B.관은 결정되지 않았고, 백좌는 결론이다.,C.사망 후 손주들은 종이돈을 태우기로 결정한다.,D.환생 환생"}, {"q": "(복수 선택) 동영상에서 사람들이 스스로 정의한 잘못된 ''사랑'' 에는 다음 중 어느 것이 포함됩니까?", "s": "진정한 사랑", "o": "A.도팅,B.맹목적인 사랑,C.진리 위에 세워진 사랑,D.페티쉬"}, {"q": "(객관식) 동영상에 따르면, 하나님께서 모든 죄를 즉시 처리하지 않으신 이유는 다음과 같습니다.", "s": "하나님의 관용", "o": "A.하나님은 죄를 묵인하십니다,B.하나님은 잊어버리십니다.,C.하나님은 관대하십니다. 사람들에게 하나님을 알기 위해 돌아갈 수 있는 기회를 주십니다.,D.오늘날은 여전히 복음이 널리 전파된 은혜의 시대입니다."}, {"q": "성경은 그리스도인들이 주님을 믿는 후에 재앙으로부터 안전하고 모든 것이 잘 될 것이라고 약속합니다.", "s": "성공회 신학"}, {"q": "하나님의 사랑은 인간 자신의 정의가 아니라 진리에 근거합니다.", "s": "하나님의 사랑"}, {"q": "“모든 것이 예수님을 믿는 것과 잘 어울린다” 는 번영 신학의 진술은 성경적 진리와 일치한다.", "s": "성공회 신학"}, {"q": "동영상은 \"자연 재해도 하나님과 인간의 관계가 무너진 결과\" 라고 어떻게 설명합니까?", "s": "자연 재해의 근원"}, {"q": "하나님께서는 왜 이 세상의 모든 불의를 즉시 심판하지 않으시는가?", "s": "하나님의 시간"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773059101551','基要真理','第二十三课 最后的审判','盖棺没有论定，还有最后的审判。审判者是创造宇宙的真神，原则是你与神的关系。本课思想审判的真实与永恒盼望。愿审判的真理带给你敬畏与盼望。预备自己，迎见你的神。','[{"type": "verse", "q": "【经文填空】因为神差他的儿子降世，不是要________世人，乃是要叫世人因他________", "o": "《约翰福音》3章17节", "s": "为拯救而来", "a": "定|得救"}, {"type": "verse", "q": "【经文填空】耶和华有________、有怜悯，不轻易发怒，________以有罪的为无罪", "o": "《出埃及记》34章6节", "s": "神的属性", "a": "恩典|断不"}, {"type": "verse", "q": "【经文填空】叫一切信他的，不至________，反得________", "o": "《约翰福音》3章16节", "s": "不至灭亡", "a": "灭亡|永生"}, {"type": "fill", "q": "最后审判的审判者是________宇宙的真神，不是人所________的偶像。", "o": "", "s": "审判者", "a": "创造|造"}, {"type": "fill", "q": "审判的原则按照________所启示的，不是我们________定的。", "o": "", "s": "审判原则", "a": "圣经|自己"}, {"type": "fill", "q": "大使命吩咐门徒在耶路撒冷、犹太全地、________，直到________作主的见证。", "o": "", "s": "大使命", "a": "撒马利亚|地极"}, {"type": "fill", "q": "按圣经真理，人活出道德美好的一面叫做________，不是功劳，不能拿来________。", "o": "", "s": "本分非功劳", "a": "本分|将功补过"}, {"type": "fill", "q": "圣经说神愿意________得救，不愿意一人________。", "o": "", "s": "神的心意", "a": "万人|沉沦"}, {"type": "fill", "q": "以色列人任意而为时神就管教：北国亡于________，南国亡于________，显明神的公义圣洁。", "o": "", "s": "以色列亡国", "a": "亚述|巴比伦"}, {"type": "single", "q": "按视频所讲，“将功补过”的观念错在哪里？", "o": "A.善事做得不够多,B.做得好的是本分不是功劳，且原则是人自己定的不是神定的,C.神不喜欢人行善,D.功劳可以抵罪但数量不够", "s": "将功补过", "a": "B"}, {"type": "single", "q": "基督徒来到审判神面前时正确的态度是？", "o": "A.数算自己的功劳要求奖赏,B.感恩领受救恩，承认软弱蒙赦免，靠基督的代赎被接纳,C.与神讨价还价,D.否认自己犯过罪", "s": "面对审判", "a": "B"}, {"type": "single", "q": "神第一次差遣儿子到世上来，目的是？", "o": "A.为了审判世人,B.为了拯救世人，预备救恩,C.为了建立地上的王国,D.为了废除旧约", "s": "道成肉身", "a": "B"}, {"type": "multiple", "q": "（多选）按出埃及记34章，神的属性包括以下哪些？", "o": "A.有恩典,B.有怜悯,C.不轻易发怒,D.断不以有罪的为无罪", "s": "神的属性", "a": "A|B|C|D"}, {"type": "multiple", "q": "（多选）按视频所讲，关于最后的审判，正确的认识包括？", "o": "A.审判者是创造宇宙的真神,B.审判原则按圣经启示不是人自定,C.看你是否与神恢复关系、尊祂为主,D.看你烧了多少香、捐了多少钱", "s": "审判原则", "a": "A|B|C"}, {"type": "judge", "q": "人可以用今生做的善事来与神交换、将功抵过。", "o": "", "s": "将功补过", "a": "错"}, {"type": "judge", "q": "一个真正决志信主的人，新生命会产生改变生命的动力。", "o": "", "s": "真决志", "a": "对"}, {"type": "judge", "q": "神是慈爱的，所以祂不会审判罪恶，人人都可进天堂。", "o": "", "s": "神的公义", "a": "错"}, {"type": "essay", "q": "为什么视频说“球员兼裁判”是人对审判的盲点？", "o": "", "s": "谁来审判", "a": "因为人是将来要面对审判的，却自己定审判者、定审判原则、定行善的标准。真实情况是：有一位创造宇宙的真神，审判的原则由祂按圣经启示来定——看人是否在今生与祂恢复关系、尊祂为生命的主，而不是人自己发明的积功德、将功补过。"}, {"type": "essay", "q": "旧约以色列亡国的历史给我们什么关于神属性的启示？", "o": "", "s": "以色列亡国", "a": "以色列白白领受出埃及、进迦南的恩典，却在应许之地任意而为、拜偶像、强凌弱，神就管教刑罚他们，北国亡于亚述、南国亡于巴比伦。这显明真神不只是赐福的“圣诞老公公”，祂是公义圣洁的，断不以有罪的为无罪；同时祂也有怜悯，为余民存留重新站起来的机会。"}]','https://youtu.be/FutGowSd16k?is=X1hphC1PoxtUU77q
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134gaHR','quiz','[{"points": ["人对“审判”的心态矛盾：有人觉得应该有审判，有人不太喜欢", "民间常说“好人有好报”，但现实中常看到恶人寿终正寝、未受报应", "圣经告诉我们：盖棺并未论定，因为有一位神设立了最后的审判"], "title": "审判的困惑：世人对公义的渴望"}, {"points": ["人自己定审判者、自己定审判原则，如同“球员兼裁判”，这是很大的盲点", "民间信仰（玉皇大帝、关公、妈祖）说不清谁有权决定人的永恒结局", "真正的审判者是创造宇宙的真神，不是人所造、人所封的偶像"], "title": "谁来审判：真神而非人造偶像"}, {"points": ["审判的原则按圣经所启示，不由人自己来定", "核心问题：你在有限的今生，有没有与这位创造主恢复关系", "认识祂、尊祂为生命的主，生命被改变，在基督里作新造的人"], "title": "审判的原则：与神的关系"}, {"points": ["约翰福音启示：祂第一次来不是为了审判，乃是为了拯救", "祂在十字架上以无罪的代替有罪的，为全人类预备了救恩", "这是恩典的时代；祂第二次再来，就是为审判"], "title": "两次降临：先拯救，后审判"}, {"points": ["人按神的形象受造，活出道德美好的一面叫做“本分”，不叫功劳", "做不好的部分是罪恶，不能拿本分来抵消", "“将功补过”是人自己定的原则，不是神的属灵原则"], "title": "破除“将功补过”的迷思"}, {"points": ["不自夸：做得正确的部分全是神的恩典", "软弱的部分：感谢神，祂的儿子在十字架上承担了一切", "带着感恩、战兢却平安确据的心，迎见主"], "title": "基督徒面对审判：战兢感恩"}, {"points": ["得救不是靠仪式或外在行为与神交换恩典", "真正决志的人，新生命进来后会产生动力：价值观改变、品格提升", "信心没有行为是死的；圣灵内住带领我们往前行"], "title": "真信心必有行为"}, {"points": ["出埃及记34章6节：神有恩典、有怜悯、不轻易发怒，但断不以有罪的为无罪", "不能只要神的慈爱怜悯、不要神的公义圣洁——那是人造的偶像", "以色列白白领受恩典却因任意妄为而亡国（北国亡于亚述、南国亡于巴比伦），是神公义的鉴戒"], "title": "神的属性：公义与慈爱并存"}, {"points": ["约翰福音3:16：叫一切信他的，不致灭亡，反得永生", "神愿万人得救，不愿一人沉沦（彼后3:9）", "执行大使命、活出大诫命：基督徒是在永恒盼望中好好过今生的人"], "title": "传福音的紧迫：大使命"}]','','23','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 23 The Last Judgment", "content": "The coffin was undecided, and there was a final judgment. The Judge is the true God who created the universe, and the principle is your relationship with God. This lesson is about the true and eternal hope of judgment. May the truth of judgment bring you awe and hope. Prepare yourself to meet your God.", "instructions": "", "guide": [{"title": "Confusion of Judgment: The World''s Desire for Righteousness", "points": ["Contradictions in people''s mentality about \"judgment\": Some people think that there should be a judgment, some people don''t like it very much", "Folk often say that \"good people have good rewards\", but in reality, it is often seen that the wicked are dying and not receiving retribution.", "The Bible tells us that the coffin is undecided because there was a God who instituted the Last Judgment."]}, {"title": "Who Will Judge: True Gods, Not Artificial Idols", "points": ["The person decides the judge and decides the principle of judgment by himself, just like \"player and referee\", which is a big blind spot.", "Folk beliefs (Jade Emperor, Guan Gong, Mazu) cannot say who has the right to decide the eternal end of man", "The true Judge is the true God who created the universe, not an idol created and sealed by man."]}, {"title": "Principle of Judgment: Relationship with God", "points": ["The principle of judgment is inspired by the Bible and not determined by man himself.", "Core question: Have you restored a relationship with this Creator in your limited mortal life?", "Knowing Him and honoring Him as Lord of life, life is transformed to be a new creation in Christ"]}, {"title": "Two Adventures: First to Save, Then to Judge", "points": ["John''s Gospel Revelation: He did not come for judgment the first time, but for salvation", "He substituted sinlessness for sinfulness on the cross and prepared salvation for all mankind.", "This is the Age of Grace; His Second Coming is for Judgment"]}, {"title": "Destroy the myth of \"compensate for the merits\"", "points": ["Man was created in the image of God to live out the good side of morality. It is called \"duty\", not credit.", "The part that can''t be done well is sin and can''t be offset.", "\"Make up for the merits\" is a principle set by man himself, not a spiritual principle of God"]}, {"title": "Christian Facing Judgment: Trembling Gratitude", "points": ["Not boasting: doing the right part is all about God''s grace", "Weakness: Thank God His Son took everything on the cross", "Meet the Lord with a heart of gratitude, trembling but assured peace"]}, {"title": "True Faith Must Behave", "points": ["Salvation is not a ritual or outward exchange of grace with God", "Those who are truly determined, when new life comes in, it will generate momentum: values change, character improvement", "Faith without works is dead; the indwelling of the Holy Spirit leads us forward"]}, {"title": "God''s Attribute: Justice and Mercy Coexist", "points": ["Exodus 34: 6: God is gracious, merciful, slow to anger, but never guiltless of sin", "Not just God''s mercy, not God''s righteousness and holiness - it''s a man-made idol.", "The grace received by Israel''s white-collar workers, but the kingdom was destroyed by arbitrary acts (the northern kingdom died in Assyria and the southern kingdom died in Babylon), which is a lesson in God''s righteousness."]}, {"title": "The Urgency of Evangelism: The Great Commission", "points": ["John 3:16: That whosoever believeth in him should not perish but have everlasting life", "God wants all people to be saved, not one to perish (2Pe 3: 9)", "Executing the Great Commission and Living the Great Commandments: Christians are people who are better off in this life in eternal hope"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] Because God sent his Son into the world, not to ________ the world, but to make the world because of him ________", "s": "Coming to the rescue"}, {"q": "[Scripture Fill in the Blank] The Lord is ________, merciful, not easily angry, ________ is not guilty of sin", "s": "Attributes of God"}, {"q": "[Scripture Fill in the Blank] so that everyone who believes in him will not ________, but ________", "s": "Not perishable"}, {"q": "The Judge of the Last Judgment is the true God of the universe, not the idol of man.", "s": "Judgement Arbiter"}, {"q": "The principle of judgment is inspired by ________, not by our ________.", "s": "Trial principle"}, {"q": "The Great Commission commanded the disciples to bear witness of the Lord in Jerusalem, throughout Judea, until ________.", "s": "The Great Commission"}, {"q": "According to biblical truth, people living the good side of morality is called ________, which is not a credit and cannot be brought to ________.", "s": "This is not due to merit"}, {"q": "The Bible says that God wants ________ to be saved, not ________ to be alone.", "s": "The Will of God"}, {"q": "God disciplined the Israelites at will: the northern kingdom died in ________, and the southern kingdom died in ________, showing God''s righteousness and holiness.", "s": "The Fall of Israel"}, {"q": "According to the video, where is the concept of \"making up for it\" wrong?", "s": "make amends for one&apos;s faults by good deeds", "o": "A.Don''t do enough good deeds,B.What is done well is that the duty is not merit, and the principle is determined by man himself, not by God.,C.God does not like people to do good deeds,D.Credit can be offset, but not enough"}, {"q": "What is the right attitude for Christians to have when they come before God for judgment?", "s": "Facing trial", "o": "A.Count your credit Requirement Reward,B.Gratitude for salvation, acknowledgment of weakness, forgiveness, acceptance through Christ''s Atonement,C.Bargain with God,D.Deny having sinned"}, {"q": "What was the purpose of God sending His Son into the world for the first time?", "s": "Dao Incarnation Body", "o": "A.To judge the world,B.To save the world, prepare for salvation,C.In order to establish a kingdom on earth,,D.In order to abolish the Old Testament,"}, {"q": "(Multiple Choice) According to Exodus 34, which of the following are attributes of God?", "s": "Attributes of God", "o": "A.Graceful,B.Merciful,C.Slightly angry,D.Never acquit the guilty"}, {"q": "(Multiple choice) According to the video, about the final trial, the correct understanding includes?", "s": "Trial principle", "o": "A.The Judge is the true God of the universe,B.The principle of judgment according to biblical revelation is not human-determined,C.See if you are restoring a relationship with God and honoring Him as Lord,D.See how much incense you burn and how much money you donate"}, {"q": "People can use the good deeds they do in this life to exchange with God and counteract the work.", "s": "make amends for one&apos;s faults by good deeds"}, {"q": "A truly determined believer, a new life generates a life-changing dynamic.", "s": "True Resolve"}, {"q": "God is loving, so he does not judge sin, and everyone can go to heaven.", "s": "God''s justice"}, {"q": "Why does the video say “player and referee” is a blind spot in the trial?", "s": "Who will judge?"}, {"q": "What does the history of the fall of Israel in the Old Testament teach us about the attributes of God?", "s": "The Fall of Israel"}]}, "ja": {"title": "レッスン23最後の審判", "content": "棺は決まっておらず、最後の審判がありました。審判者は宇宙を創造した真の神であり、原則はあなたと神との関係です。この課では，裁きの真の永遠の希望について学びます。裁きの真理があなたに畏敬と希望をもたらしますように。あなたの神に会う準備をしてください。", "instructions": "", "guide": [{"title": "裁きの混乱：世界の義への願望", "points": ["「判断」についての人々のメンタリティの矛盾：判断があるべきだと考える人もいれば、あまり好きではない人もいます", "民衆はよく「善人には善い報いがある」と言いますが、実際には、悪人が死に、報いを受けていないことがよく見られます。", "聖書には、最後の審判を制定した神がいたため、棺は未定であると書かれています。"]}, {"title": "裁くのは誰か：人工の偶像ではなく、真の神々", "points": ["「選手と審判」のように、裁判官を決め、判断の原則を自分で決めますが、これは大きな盲点です。", "民間信仰（翡翠帝、関宮、麻津）は、誰が人間の永遠の終わりを決定する権利を持っているかを言うことはできません", "真の審判者は、宇宙を創造した真の神であり、人間によって創造され、封印された偶像ではありません。"]}, {"title": "裁きの原則：神との関係", "points": ["裁きの原則は聖書に触発されたものであり、人間自身によって決定されるものではありません。", "中核的な質問：あなたは限られた現世の生活の中で、この創造主との関係を回復しましたか？", "主を知り，主をいのちの主として尊ぶことで，いのちはキリストにある新しい創造物に変わります"]}, {"title": "2つのアドベンチャー：まず救い、次に裁く", "points": ["ヨハネの福音書の啓示：彼は最初に裁きを受けるためではなく、救いを受けるために来られたのです", "彼は十字架上で罪のないことを罪のないことに置き換え，全人類のために救いを準備しました。", "これは恵みの時代であり，主の再臨は裁きのためのものである"]}, {"title": "「功績を償え」の神話を破壊する", "points": ["人間は、道徳の良い面を生きるために神のかたちに創造されたものであり、信用ではなく「義務」と呼ばれています。", "うまくできない部分は罪であり、相殺できません。", "「メリットを補う」は人間自身が定めた原則であり、神の霊的な原則ではない"]}, {"title": "クリスチャンが直面する裁き：震える感謝の気持ち", "points": ["自慢しない：正しいことをすることはすべて神の恵みである", "弱さ：神の御子が十字架上ですべてを引き受けてくださったことを感謝します", "感謝の心をもって主に会い，震えながらも安らかな平安を得る"]}, {"title": "真の信仰は行動しなければならない", "points": ["救いは神との儀式や外面的な恵みの交換ではありません", "真に決意している人は、新しい人生がやってくるとき、それは勢いを生み出します：価値観の変化、性格の向上", "行いのない信仰は死んでいます。聖霊の内在はわたしたちを前進させます"]}, {"title": "神の属性：正義と憐れみは共存する", "points": ["出エジプト記34 ： 6 ：神は恵み深く，憐れみ深く，怒るのは遅いが，決して罪のない方ではない", "神の憐れみだけでなく、神の義と聖さでもありません。それは人が作った偶像です。", "イスラエルのホワイトカラー労働者が受けた恵みは、神の義の教訓である恣意的な行為によって王国が破壊されました（北王国はアッシリアで死に、南王国はバビロンで死にました）。"]}, {"title": "伝道の緊急性：偉大な使命", "points": ["ヨハネ3 ： 16 ：彼を信じる者が滅びないで、永遠の命を得るために", "神はすべての人が救われることを望んでおられ，一人の人が滅びることを望んでおられません（ペテロ第二3 ： 9 ）。", "大いなる使命を遂行し，大いなる戒めを守る：クリスチャンは，永遠の希望を抱いてこの世でより良い生活を送る人々です"]}], "quizzes": [{"q": "〔聖句の穴埋め〕神が御子を世に遣わされたのは，御子のおかげで， ________世にではなく， ________世にお遣わしになったからです。", "s": "救助に向かっています"}, {"q": "〔聖句の穴埋め〕主は________ ，憐れみ深く，怒るのが遅く， ________罪人を赦してくださいます。", "s": "神の属性"}, {"q": "彼を信じるすべての人が________ではなく________になるように、[聖句は空白を埋めてください]", "s": "生鮮食品ではありません"}, {"q": "最後の審判の審判者は、人間の偶像ではなく、宇宙の真の神です。", "s": "審査員"}, {"q": "判断の原則は、私たちの________ではなく________に触発されています。", "s": "トライアルの原則"}, {"q": "大宣教は， ________までエルサレム，ユダヤ全土で主を証するよう弟子たちに命じました。", "s": "グレート・コミッション"}, {"q": "聖書の真理によると、道徳の良い面を生きる人々は________と呼ばれています。これは信用ではなく、________にもたらすことはできません。", "s": "これは功績によるものではありません"}, {"q": "聖書は，神は________が一人でいることではなく， ________が救われることを望んでおられると述べています。", "s": "神の御心"}, {"q": "神はイスラエル人を意のままに懲らしめられました。北の王国は________で死に、南の王国は________で死に、神の義と聖さを示しました。", "s": "イスラエルの陥落"}, {"q": "ビデオによると、「埋め合わせ」という概念はどこが間違っているのでしょうか？", "s": "メリットを補償します", "o": "A.十分な善行をしない,B.うまくいっているのは、義務は価値ではなく、原則は神によってではなく、人間自身によって決定されるということです。,C.神は人々が善行をするのを好まれない,D.クレジットは相殺できますが、十分ではありません"}, {"q": "クリスチャンが裁きのために神の前に来るとき，正しい態度とはどのようなものでしょうか。", "s": "試練に直面している", "o": "A.クレジット要件報酬を数える,B.救いへの感謝，弱さの認識，赦し，キリストの贖罪による受け入れ,C.神との取引,D.罪を犯したことを否定する"}, {"q": "神が御子を初めて世に遣わされた目的は何でしたか。", "s": "道の化身の体", "o": "A.世界を裁くために,B.世界を救うために，救いに備える,C.地上に王国を築くためには、,D.旧約聖書を廃止するために、"}, {"q": "（複数選択可）出エジプト34章によると，次のうち，神の属性はどれですか。", "s": "神の属性", "o": "A.グレースフル,B.慈悲深い,C.やや怒っている,D.有罪を決して無罪にしない"}, {"q": "（複数選択可）ビデオによると、最終トライアルについて、正しい理解には次のものが含まれますか？", "s": "トライアルの原則", "o": "A.審判者は宇宙の真の神である,B.聖書の啓示による裁きの原則は人間が決めるものではありません,C.あなたが神との関係を回復し、神を主として尊んでいるかどうかを確認してください,D.どれだけのお香を燃やし、どれだけのお金を寄付するかを確認します"}, {"q": "人々は，この世で行っている善行を使って神と交換し，その働きに対抗することができます。", "s": "メリットを補償します"}, {"q": "真に断固とした信者である新しい人生は、人生を変えるダイナミクスを生み出します。", "s": "真の解決"}, {"q": "神は愛しておられるので、罪を裁かず、誰もが天国に行くことができます。", "s": "神の正義"}, {"q": "「プレーヤーと審判」がトライアルの盲点であるとビデオに書かれているのはなぜですか？", "s": "誰が判断するのですか？"}, {"q": "旧約聖書のイスラエルの陥落の歴史は，神の属性についてどのようなことを教えていますか。", "s": "イスラエルの陥落"}]}, "ko": {"title": "제23과 최후의 심판", "content": "관은 정해지지 않았고, 최후의 심판이 있었다. 심판자는 우주를 창조하신 참 하나님이시며, 원칙은 여러분과 하나님과의 관계입니다. 이 수업은 심판의 참되고 영원한 희망에 관한 것이다. 심판의 진리가 여러분에게 경외심과 희망을 가져다 주기를 바랍니다. 하나님을 만날 준비를 하세요.", "instructions": "", "guide": [{"title": "판단의 혼란: 의에 대한 세상의 욕망", "points": ["\"판단\" 에 대한 사람들의 사고방식의 모순: 어떤 사람들은 판단이 있어야 한다고 생각하고, 어떤 사람들은 그것을 별로 좋아하지 않습니다.", "사람들은 종종 \"좋은 사람들은 좋은 보상을 받는다\" 고 말하지만, 실제로는 악인들이 죽어가고 보복을받지 않는 것을 종종 볼 수 있습니다.", "성경은 최후의 심판을 세우신 하나님이 계셨기 때문에 관이 결정되지 않았다고 말합니다."]}, {"title": "누가 판단할 것인가: 인위적인 우상이 아닌 진정한 신", "points": ["큰 사각지대인 \"선수와 심판\" 처럼 개인이 심판을 결정하고 스스로 판단의 원칙을 결정합니다.", "민속 신앙 (옥황상제, 관공, 마주) 은 누가 인간의 영원한 종말을 결정할 권리가 있는지 말할 수 없습니다.", "진정한 심판자는 인간이 창조하고 봉인한 우상이 아니라 우주를 창조하신 참 하나님이십니다."]}, {"title": "판단의 원리: 하나님과의 관계", "points": ["판단의 원리는 성경에 의해 영감을 받고 인간 자신이 결정하지 않습니다.", "핵심 질문: 제한된 필멸의 삶에서 이 창조주와의 관계를 회복했습니까?", "그분을 알고 그분을 생명의 주님으로 공경하는 삶은 그리스도 안에서 새로운 피조물로 변화됩니다."]}, {"title": "두 가지 모험: 먼저 저장한 다음 판단하기", "points": ["요한 복음 계시록: 그는 처음 심판을 위해 오신 것이 아니라 구원을 위해 오셨습니다.", "십자가에서 무죄를 죄로 치환하시고 온 인류를 위한 구원을 예비하셨습니다.", "지금은 은혜의 시대입니다. 그분의 재림은 심판을 위한 것입니다."]}, {"title": "\"장점에 대한 보상\" 이라는 신화를 파괴하십시오", "points": ["인간은 도덕의 선한 면을 살기 위해 하나님의 형상대로 창조되었습니다. 그것은 신용이 아니라 \"의무\" 라고 불립니다.", "잘 할 수 없는 부분은 죄이고 상쇄될 수 없다.", "\"공로를 만회하라\" 는 것은 인간이 스스로 정한 원칙이지, 하나님의 영적인 원칙이 아니다."]}, {"title": "그리스도인이 직면하는 심판: 떨리는 감사", "points": ["자랑하지 않음: 옳은 일을 하는 것은 모두 하나님의 은혜에 관한 것입니다.", "약점: 그분의 아들이 십자가에서 모든 것을 취하신 것에 대해 하나님 께 감사드립니다.", "떨리지만 확실한 평화, 감사의 마음으로 주님을 만나십시오."]}, {"title": "진정한 신앙은 행동해야 합니다", "points": ["구원은 하느님과 은총을 교환하는 의식이나 외적인 것이 아닙니다.", "진정으로 결단력 있는 사람들은 새로운 생명이 들어오면 가치관 변화, 성격 개선이라는 모멘텀을 생성합니다.", "행함이 없는 믿음은 죽은 것이며, 성령의 내주하심은 우리를 앞으로 나아가게 합니다."]}, {"title": "하나님의 속성: 정의와 자비가 공존한다", "points": ["출애굽기 34: 6: 하나님은 은혜로우시고 자비로우시며 노하기를 더디 하시나 죄가 없으시니라", "하느님의 자비, 하느님의 의로움과 거룩함이 아니라 인간이 만든 우상입니다.", "이스라엘의 화이트 칼라 일꾼들이 받은 은혜이지만, 그 나라는 독단적인 행위 (북쪽 나라는 앗수르에서 죽고 남쪽 나라는 바벨론에서 죽었음) 에 의해 파괴되었는데, 이는 하나님의 의에 대한 교훈입니다."]}, {"title": "전도의 긴급성: 위대한 임무", "points": ["요한복음 3:16: 이는 저를 믿는 자마다 멸망치 않고 영생을 얻게 하려 하심이라", "하나님은 모든 사람이 구원을 받기를 원하시지 아무도 멸망하지 않기를 원하십니다 (벧후 3: 9).", "위대한 계명 실행과 위대한 계명 실천: 그리스도인은 이생에서 영원한 소망 안에서 더 나은 삶을 사는 사람들입니다."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 하나님이 아들을 세상에 보내신 것은 세상을 ________ 하기 위해서가 아니라 그로 인해 세상을 만들기 위해서였기 때문이다 ________", "s": "구조를 위해 오기"}, {"q": "[Scripture Fill in the Blank] 주님은 ________, 자비로우시고, 쉽게 화내지 않으시며, ________ 은 (는) 죄가 없습니다", "s": "하나님의 속성"}, {"q": "[Scripture Fill in the Blank] 그래야 그를 믿는 모든 사람이 ________ 가 아니라 ________", "s": "부패할 수 없음"}, {"q": "최후의 심판자는 우주의 참 하나님이시지 인간의 우상이 아닙니다.", "s": "판사"}, {"q": "판단의 원칙은 ________ 에서 비롯된 것이지 ________ 에서 비롯된 것이 아닙니다.", "s": "시험 원리"}, {"q": "대명령은 제자들에게 ________ 까지 유대 전역의 예루살렘에서 주님을 증거하라고 명령했다.", "s": "위대한 임무"}, {"q": "성경적 진리에 따르면, 도덕의 좋은 면을 사는 사람들은 ________ 라고 불리는데, 이는 신용이 아니며 ________ 에게 가져갈 수 없습니다.", "s": "이는 메리트 때문이 아닙니다."}, {"q": "성경은 하나님께서 ________ 이 (가) 혼자가 아니라 ________ 이 (가) 구원을 받기를 원하신다고 말합니다.", "s": "하나님의 뜻"}, {"q": "하나님께서는 이스라엘 백성을 마음대로 징계하셨습니다. 북쪽 왕국은 ________ 에서 죽었고, 남쪽 왕국은 ________ 에서 죽어 하나님의 의와 거룩함을 보여주었습니다.", "s": "이스라엘의 멸망"}, {"q": "동영상에 따르면, ''보완한다'' 는 개념이 어디에서 틀렸나요?", "s": "장점에 대해 보상할 것입니다.", "o": "A.선행을 충분히 하지 마세요.,B.잘한 것은 의무가 공로가 아니며 원칙은 하나님이 아닌 인간 자신이 결정한다는 것입니다.,C.하나님은 사람들이 선을 행하는 것을 좋아하지 않으십니다.,D.크레딧은 상쇄할 수 있지만 충분하지는 않습니다."}, {"q": "그리스도인들이 심판을 받기 위해 하나님 앞에 나아갈 때 올바른 태도는 무엇인가?", "s": "심판을 맞이함", "o": "A.크레딧 요건 보상 계산,B.구원에 대한 감사, 약점 인정, 용서, 그리스도의 속죄를 통한 수용,C.하나님과 거래하기,D.죄를 지었음을 부인함"}, {"q": "하나님께서 처음으로 아들을 세상에 보내신 목적은 무엇이었는가?", "s": "DAO 화신 몸", "o": "A.세상을 심판하기 위해,B.세상을 구하기 위해 구원을 준비하세요.,C.지상에 왕국을 세우기 위해,,D.구약을 폐지하기 위해서는"}, {"q": "(객관식) 출애굽기 34장에 따르면, 다음 중 하나님의 속성은 무엇입니까?", "s": "하나님의 속성", "o": "A.우아함,B.자비로운,C.약간 화남,D.절대로 유죄를 무죄로 인정하지 마십시오."}, {"q": "(복수 선택) 동영상에 따르면, 최종 시험에 대한 올바른 이해에는 다음이 포함됩니까?", "s": "시험 원리", "o": "A.심판자는 우주의 참 하나님이십니다.,B.성경의 계시에 따른 심판의 원리는 인간이 결정하는 것이 아니다.,C.하나님과의 관계를 회복하고 그분을 주님으로 공경하고 있는지 확인하십시오,D.얼마나 많은 향을 피우고 얼마나 많은 돈을 기부하는지 확인하십시오"}, {"q": "사람들은 이생에서 하는 선행을 하나님과 교환하고 일을 방해하는 데 사용할 수 있습니다.", "s": "장점에 대해 보상할 것입니다."}, {"q": "진정으로 결단력 있는 신자, 새로운 삶은 삶을 변화시키는 역동성을 만들어 냅니다.", "s": "참된 결단"}, {"q": "하나님은 사랑하셔서 죄를 심판하지 않으시고 모든 사람이 천국에 갈 수 있습니다.", "s": "하나님의 공의"}, {"q": "동영상에서 ''선수와 심판'' 이 평가전의 사각지대라고 말하는 이유는 무엇인가요?", "s": "누가 판단할까요?"}, {"q": "구약전서에 나오는 이스라엘의 타락 역사는 하나님의 속성에 대해 무엇을 가르쳐 주는가?", "s": "이스라엘의 멸망"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773059483795','基要真理','第二十四课 天堂与地狱','天堂是新天新地，没有眼泪死亡；地狱是与神永远隔绝。本课思想永恒的结局，激励今生活出有永恒价值的人生。愿永恒的盼望照亮你今生的道路。仰望那更美的家乡，存心忍耐。','[{"type": "verse", "q": "【经文填空】神要擦去他们一切的________，不再有死亡，也不再有________、哭号、疼痛", "o": "《启示录》21章4节", "s": "新天新地", "a": "眼泪|悲哀"}, {"type": "verse", "q": "【经文填空】在我父的家里有许多________；我去原是为你们________地方去", "o": "《约翰福音》14章2节", "s": "预备地方", "a": "住处|预备"}, {"type": "verse", "q": "【经文填空】不要________这个世界，只要心意________而变化", "o": "《罗马书》12章2节", "s": "心意更新", "a": "效法|更新"}, {"type": "fill", "q": "关于死后世界的各种说法，关键问题是“谁讲的”：唯有________宇宙、超越时空的真神有资格告诉我们从哪里来、往哪里去。", "o": "", "s": "谁有资格讲", "a": "创造"}, {"type": "fill", "q": "地狱最可怕的不是火窑刀山，而是一大堆不要神的人与创造永恒的神________隔绝。", "o": "", "s": "地狱真相", "a": "永远"}, {"type": "fill", "q": "C.S.路易斯说：地狱从来不是为________预备的；上帝造人原是看为________好的。", "o": "", "s": "地狱非为人备", "a": "人|甚"}, {"type": "fill", "q": "神今天预备的不只是一个天堂的位置，更是预备________的人；进天堂不是靠外在________交换。", "o": "", "s": "预备人", "a": "进入天堂|功德"}, {"type": "fill", "q": "哥林多书信说：我们既有属________的身体，也会有属________的身体，这是神给信徒最后的恩典。", "o": "", "s": "得赎的身体", "a": "血气|灵"}, {"type": "fill", "q": "按圣经启示，基督徒离世后神先带到________，不接受神的人则到________，等候最终的审判。", "o": "", "s": "死后去处", "a": "乐园|阴间"}, {"type": "single", "q": "视频中北加州大火后教会募款赈灾，牧师如何看待这件善事？", "o": "A.值得敲锣打鼓大肆宣传,B.是我们该做的，不值得夸耀，是操练生命成长的机会,C.可以用来向神交换祝福,D.只有华人才配得到帮助", "s": "善行意义", "a": "B"}, {"type": "single", "q": "按视频所讲，为什么神不只预备天堂这个地方，还要预备进天堂的人？", "o": "A.因为天堂位置不够,B.因为人若生命不改变，再美好的环境也会像伊甸园一样被破坏,C.因为神喜欢热闹,D.因为天使不够用", "s": "预备人", "a": "B"}, {"type": "single", "q": "基督徒的善行与恩典的关系是？", "o": "A.善行是交换恩典的筹码,B.善行是生命的流露，不是上天堂的保证,C.善行越多越能赎罪,D.不需要有善行", "s": "善行与恩典", "a": "B"}, {"type": "multiple", "q": "（多选）按圣经启示，新天新地（天堂）是怎样的地方？", "o": "A.没有眼泪,B.没有痛苦死亡,C.靠功德进入的享乐之地,D.神为属祂的人预备的地方", "s": "新天新地", "a": "A|B|D"}, {"type": "multiple", "q": "（多选）人要怎样被预备进入天堂？", "o": "A.与创造天堂的主恢复关系，接受救恩,B.圣灵内住，天天活出新生的样式,C.靠积功德、做善事与神交换,D.心意更新而变化", "s": "进入天堂", "a": "A|B|D"}, {"type": "judge", "q": "地狱最可怕的是上刀山、下油锅等刑罚。", "o": "", "s": "地狱真相", "a": "错"}, {"type": "judge", "q": "基督徒可以用外在的善行功德与神交换进天堂的门票。", "o": "", "s": "功德交换", "a": "错"}, {"type": "judge", "q": "天堂地狱的启示来自创造宇宙真神的圣经启示，不是人自己悟道想出来的。", "o": "", "s": "启示来源", "a": "对"}, {"type": "essay", "q": "为什么视频强调谈天堂地狱时“第一优先是谁讲的”？", "o": "", "s": "谁有资格讲", "a": "因为死后世界超越人生的时空和经验，有限的人不能改变过去、不知道将来，连今世都掌握不好，人自己悟道、造神、编轮回之说都没有可靠依据。唯有创造宇宙、超越时空的真神才有资格启示人从哪里来、往哪里去，所以天堂地狱必须建立在圣经的启示上，而不是人的想象。"}, {"type": "essay", "q": "按视频所讲，神为天堂所做的“预备”包括哪两方面？", "o": "", "s": "神的预备", "a": "一是预备地方：主耶稣说“我去为你们预备地方”，新天新地没有眼泪、痛苦和死亡；二是预备人：神在有限的今生改变信祂之人的生命，使其脱下旧人、穿上新人，至死虽不完全，但一生证明愿意尊神为大，最后神赐下得赎的属灵身体。人若生命不改变，再美好的环境也会重演伊甸园的悲剧。"}]','https://youtu.be/ktjAa_idJg4
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134qk1M','quiz','[{"title": "死后世界众说纷纭", "points": ["轮回观念：这辈子好好做人下辈子做人，不好好做人下辈子变畜生", "人死如灯灭：死亡之后像吹口气一样，什么都没有了", "上西天、下地狱：不好好做人，下辈子下十八层地狱"]}, {"title": "关键一问：这信息是谁说的", "points": ["死后世界超越人生经验与时空，谁能告诉我们真相", "悟道与想象都不可靠：没有一个死去的人回来告诉我们", "首要原则：先确认信息的发布者是谁，再判断信息真假"]}, {"title": "天堂与地狱：神的启示而非人的发明", "points": ["创造宇宙的真神超越时空，唯一有资格告诉我们从哪里来、往哪里去", "神为我们预备了新天新地，也为一辈子拒绝神的人预备了地狱", "天堂地狱不是人的幻想、悟道所得，也不是人造的乌托邦"]}, {"title": "人要被改变：天堂不是伊甸园重演", "points": ["伊甸园的教训：神称它“甚好”，人与神对立之后，美好就变成不好", "人带着有罪的生命进天堂，天堂还是天堂吗——要先预备进入天堂的人", "有限的今生在做什么：神在有罪的世代中预备一群人，生命被改变后进入荣美的环境"]}, {"title": "善行不是筹码：生命的流露", "points": ["基督徒的善行不是交换恩典的筹码，也不是上天堂的保证，而是生命的流露", "外表光鲜不代表生命健康：诺贝尔文学奖停颁、北美 Me Too 事件中的功成名就者", "善行需要被检验：教会赈灾捐款是操练生命成长的机会，不是积功德"]}, {"title": "如何预备：恢复与神的关系", "points": ["第一步是与创造天堂的主恢复关系：若不是神主动来找我们，我们根本找不到祂", "真信心不是仪式化宗教：迎接祂做生命的主，圣灵天天提醒我们活出新生的样式", "罗马书12章2节：不要效法这个世界，乃要心意更新而变化，活出光明、诚实、公义的生命"]}, {"title": "得赎的身体：最后的恩典", "points": ["基督徒至死都不完全，但神看我们一生是否愿意尊祂为大、持守恩典", "神最后的恩典：进入新天新地之前，赐给我们一个得赎的属灵身体", "用一生证明愿意，最后得着全然全新的身体，进入新天新地"]}, {"title": "地狱的可怕：与神永远隔绝", "points": ["地狱是圣洁公义的神必然的安排，神不喜悦人进地狱", "地狱真正可怕的不是不死的虫、不灭的火，而是没有神在那里——与神永远隔绝", "一大堆不要神、以自我为中心的人在一起，这种苦难比火更可怕"]}, {"title": "今天就预备：恩典向所有人打开", "points": ["信徒离世后先被带到乐园，不信者到阴间，等候白色大宝座的审判", "审判之后，乐园里的信徒被带到新天新地，阴间的不信者回到永远与神隔绝之处", "今天恩典向所有人打开：不需要积功德交换，好行为是生命的展现，不好的部分由救恩带领我们活出新生"]}]','','24','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 24 Heaven and Hell", "content": "Heaven is a new heaven and a new earth, without tears of death; hell is eternally cut off from God. The eternal ending of this lesson inspires a life of eternal value in today''s life. May eternal hope illuminate your path in this life. Look to a better home and be patient.", "instructions": "", "guide": [{"title": "Afterlife Opinions Diverge", "points": ["Reincarnation concept: Be a good person in this life, be a person in the next life, don''t be a good person and become an animal in the next life", "People die like a light: after death, it is like breathing, there is nothing left", "Up to Western Heaven, down to Hell: Don''t be a good person, down to 18 layers of hell in the next life"]}, {"title": "Key question: Who said this?", "points": ["The afterlife transcends experience and time. Who can tell us the truth?", "Enlightenment and imagination are not reliable: none of the dead came back to tell us", "First principle: first confirm who the publisher of the information is, and then judge whether the information is true or false"]}, {"title": "Heaven and Hell: God''s Revelation, Not Man''s Invention", "points": ["The true God who created the universe transcends time and space, and is uniquely qualified to tell us where we came from and where we are going.", "God has prepared a new heaven and a new earth for us, and a hell for those who reject God all their lives.", "Heaven and hell are not human fantasies, enlightenment, or artificial utopias."]}, {"title": "Man is to be changed: Paradise is not a repeat of the Garden of Eden", "points": ["Lesson from the Garden of Eden: God calls it “very good,” and after man confronts God, good becomes bad", "People go to heaven with sinful lives, is heaven still heaven - prepare people to go to heaven first", "What limited mortal life does: God prepares a group of people in a sinful generation to enter a glorious environment after their lives are changed"]}, {"title": "Good deeds are not chips: the outpouring of life", "points": ["A Christian''s good deeds are not a bargaining chip for grace or a guarantee of heaven, but an outpouring of life.", "Glossy appearance does not mean healthy life: Nobel Prize in Literature suspended, success in Me Too event in North America", "Good deeds need to be tested: Church disaster relief donations are an opportunity to practice life growth, not accumulate merit"]}, {"title": "How to Prepare: Restoring Your Relationship with God", "points": ["The first step is to restore the relationship with the Creator of Heaven: if God hadn''t come to us, we wouldn''t have found Him at all.", "True Faith Is Not a Ritualized Religion: Welcoming Him as Lord of Life, the Holy Spirit Reminds Us Every Day to Live in a New Life Style", "Romans 12: 2: Do not imitate the world, but change your heart and live a life of light, honesty, and righteousness"]}, {"title": "Redeemed body: last grace", "points": ["Christians are incomplete until death, but God sees whether we are willing to honor Him as great and keep His grace in our lifetime.", "God''s final grace: to give us a redeemed spiritual body before entering a new heaven and a new earth", "Prove your willingness with a lifetime, and finally get a completely new body and enter a new world"]}, {"title": "The horrors of hell: eternal separation from God", "points": ["Hell is an inevitable arrangement of God for holiness and righteousness, and God does not like people to go to hell.", "What is truly terrible about hell is not the immortal worm, the unquenchable fire, but the fact that there is no God there - eternal separation from God.", "A lot of godless, self-centered people together, this kind of suffering is more terrible than fire"]}, {"title": "Prepare today: grace opens TO all", "points": ["After the believer dies, he is first taken to paradise, and the unbeliever goes to the underworld to await the judgment of the great white throne.", "After the judgment, the believers in the paradise were taken to the new heavens and the new earth, and the unbelievers in the underworld returned to the place of eternal separation from God.", "Grace is open to everyone today: there is no need to exchange merit, good deeds are the manifestation of life, and the bad part is led by salvation to live a new life"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] God will wipe away all their ________, no more death, no more ________, no more crying, no more pain.", "s": "Xintianxintiandi"}, {"q": "[Scripture Fill in the Blank] There are many ________ in my father''s house; I went for your ________ place", "s": "Prepare a place"}, {"q": "[Scripture Fill in the Blank] Don''t ________ this world, just change your mind ________", "s": "Mind update"}, {"q": "The key question about the various claims about the afterlife is \"who said it\": only the ________ universe, the true God beyond time and space, is qualified to tell us where we come from and where we go.", "s": "Who is qualified to speak"}, {"q": "The most terrible thing about Hell is not the Kiln Blade Mountain, but a lot of people who do not want God to be separated from the creation of the eternal God ________.", "s": "Hell''s Truth"}, {"q": "C.S. Lewis said: Hell was never prepared for ________; God created man to be good for ________.", "s": "Hell is unprepared"}, {"q": "What God has prepared today is not just a place in heaven, but also a person who prepares ________; entering heaven does not rely on the exchange of external ________.", "s": "Prepared by"}, {"q": "Corinthians says: We have both a body of ________ and a body of ________, which is the last grace of God to believers.", "s": "Redeemed Body"}, {"q": "According to the biblical revelation, after the death of the Christian, God first brought to ________, and those who did not accept God came to ________, waiting for the final judgment.", "s": "Where to go after death"}, {"q": "In the video, how does the pastor feel about the church''s fundraising for disaster relief after the Northern California fires?", "s": "Meaning of good deeds", "o": "A.It''s worth beating the gongs and playing the drums,B.is what we should do, not to brag, is the opportunity to practice life growth,C.Can be used to exchange blessings with the gods,D.Only Chinese deserve help"}, {"q": "According to the video, why does God prepare not only the place of heaven, but also the people who go to heaven?", "s": "Prepared by", "o": "A.Because there are not enough places in heaven,B.Because if people''s lives do not change, the beautiful environment will be destroyed like the Garden of Eden.,C.Because God loves to be lively.,D.Because there aren''t enough angels"}, {"q": "What is the relationship between Christian good deeds and grace?", "s": "Good deeds and grace", "o": "A.Good deeds are a bargaining chip for grace,B.Good deeds are an expression of life, not a guarantee of heaven,C.The more good you do, the more you can atone for your sins.,D.No need for good deeds"}, {"q": "(Multiple Choice) What does the Bible reveal about the new heavens and the new earth (heaven)?", "s": "Xintianxintiandi", "o": "A.No tears,B.No painful death,C.A Land of Pleasure Entered by Karmic Virtue,D.A place prepared by God for His people"}, {"q": "(Multiple Choice) How can people be prepared to go to heaven?", "s": "Enter Paradise", "o": "A.Restore your relationship with the Creator of Heaven and receive salvation,B.The indwelling of the Holy Spirit, living a new life every day,C.By accumulating merit, doing good deeds and exchanging them with God,D.Changes due to renewed intentions"}, {"q": "The most terrible things in hell are penalties such as going up to Knife Mountain and going down to the oil pot.", "s": "Hell''s Truth"}, {"q": "Christians can exchange outward good works for a ticket to heaven with God.", "s": "Karmic exchange"}, {"q": "The revelation of heaven and hell comes from the biblical revelation of the true God who created the universe, not from man''s own understanding.", "s": "Source of Revelation"}, {"q": "Why does the video emphasize “who speaks first” when talking about heaven and hell?", "s": "Who is qualified to speak"}, {"q": "According to the video, what are two aspects of God''s “preparation” for heaven?", "s": "God''s Provision"}]}, "ja": {"title": "レッスン24天国と地獄", "content": "天は死の涙のない新しい天と新しい地であり，地獄は神から永遠に断たれます。この課の永遠の終わりは，今日の人生に永遠の価値のある人生をもたらします。永遠の希望があなたの人生の道を照らしますように。より良い家に目を向け、忍耐強くなりましょう。", "instructions": "", "guide": [{"title": "来世の意見の相違", "points": ["転生のコンセプト：この世では善人になり、来世では人になり、来世では善人にならず、動物になってください", "人は光のように死ぬ：死後、それは呼吸のようなもので、何も残っていない", "西の天国まで、地獄まで：来世では18層の地獄まで、良い人にならないでください"]}, {"title": "主な質問：誰がこれを言ったのですか？", "points": ["死後の世界は経験と時間を超越しています。誰が私たちに真実を伝えることができますか？", "悟りと想像力は信頼できません：死者の誰も私たちに教えに戻ってきませんでした", "最初の原則：最初に情報の発行者が誰であるかを確認し、次に情報が正しいか間違っているかを判断します"]}, {"title": "天国と地獄：人間の発明ではなく、神の啓示", "points": ["宇宙を創造した真の神は、時間と空間を超越し、私たちがどこから来て、どこへ行くのかを伝える独自の資格があります。", "神は，わたしたちのために新しい天と新しい地を備え，生涯神を拒む者のために地獄を備えてくださっています。", "天国と地獄は、人間の空想でも、悟りでも、人工的なユートピアでもありません。"]}, {"title": "人は変わるべきです：楽園はエデンの園の繰り返しではありません", "points": ["エデンの園からの教訓：神はそれを「非常に良い」と呼び、人が神と対峙すると、良いことが悪いことになる", "人々は罪深い人生を送って天国に行く、天国はまだ天国です-最初に天国に行くために人々を準備する", "限られた現世の生活とは：神は，罪深い世代の人々が人生が変わった後に栄光の環境に入るための準備をしておられます"]}, {"title": "善行は欠けではありません：生命の流れ", "points": ["クリスチャンの善行は、恵みや天国の保証のための交渉のチップではなく、命の流れです。", "光沢のある外観は健康的な生活を意味しません：ノーベル文学賞停止、北米でのMe Tooイベントでの成功", "善行は試される必要があります：教会の災害救援寄付は、人生の成長を実践する機会であり、功績を蓄積する機会ではありません"]}, {"title": "準備する方法：神との関係を回復する", "points": ["最初のステップは、天の創造主との関係を回復することです。もし神が私たちのもとに来ていなかったら、私たちは神をまったく見つけられなかったでしょう。", "真の信仰は儀式化された宗教ではありません：命の主として彼を歓迎し、聖霊は私たちに新しいライフスタイルで生きることを毎日思い出させます", "ローマ12 ： 2 ：世界を模倣するのではなく、心を変えて、光と誠実さと正義の人生を送りましょう"]}, {"title": "償還されたボディ：最後の恵み", "points": ["クリスチャンは死ぬまで不完全ですが，神はわたしたちが喜んで神を尊び，生涯にわたって神の恵みを守るかどうかを見ておられます。", "神の最後の恵み：新しい天と新しい地に入る前に、私たちに贖われた霊的な体を与える", "一生かけて意欲を証明し、ようやく完全に新しい身体を手に入れ、新しい世界に入りましょう"]}, {"title": "地獄の恐怖：神からの永遠の分離", "points": ["地獄は神の聖さと義のための必然的な取り決めであり、神は人々が地獄に行くのを好まれません。", "地獄について本当に恐ろしいのは、不滅の虫、消えることのない火ではなく、そこに神がいないという事実です。神からの永遠の分離です。", "多くの無神論者、自己中心的な人々が一緒になって、この種の苦しみは火よりも恐ろしいです"]}, {"title": "今日の準備：恵みがすべての人に開かれる", "points": ["信者が死んだ後、彼は最初に楽園に連れて行かれ、不信者は偉大な白い玉座の裁きを待つために冥界に行きます。", "裁きの後、楽園の信者は新しい天と新しい地に連れて行かれ、冥界の不信者は神からの永遠の分離の場所に戻りました。", "今日、恵みはすべての人に開かれています：メリットを交換する必要はなく、善行は人生の現れであり、悪い部分は新しい人生を送るために救いによって導かれます"]}], "quizzes": [{"q": "〔聖句の穴埋め〕神は彼らのすべての________、もはや死、もはや________、もはや泣き声、もはや痛みを拭い去ります。", "s": "Xintianxintiandi"}, {"q": "〔聖句の穴埋め〕私の父の家には多くの________があります。私はあなたの________の場所に行きました", "s": "宿泊先を準備する"}, {"q": "〔聖句の穴埋め〕この世界を________しないでください、あなたの考えを変えるだけです________", "s": "マインドアップデート"}, {"q": "死後の世界についてのさまざまな主張についての重要な質問は、「誰がそれを言ったのか」です。時間と空間を超えた真の神である________宇宙だけが、私たちがどこから来て、どこに行くのかを伝える資格があります。", "s": "話す資格のある人"}, {"q": "地獄で最も恐ろしいことは、窯刃山ではなく、神が永遠の神________の創造から切り離されることを望まない多くの人々です。", "s": "地獄の真実"}, {"q": "C.S.ルイスは次のように述べています。「地獄は決して________のために用意されたものではありませんでした。神は________のために人を造られました。", "s": "地獄は準備ができていない"}, {"q": "神が今日用意してくださったものは、天にある場所だけでなく、________を準備する人でもあります。天に入ることは、外部の________の交換に頼ることではありません。", "s": "作成者"}, {"q": "コリント人は次のように言います。「わたしたちは________の体と________の体の両方を持っています。これは信者に対する神の最後の恵みです。", "s": "償還されたボディ"}, {"q": "聖書の啓示によると、クリスチャンの死後、神は最初に________に連れて来られ、神を受け入れなかった人々は________に来て、最後の審判を待っていました。", "s": "死後に行くべき場所"}, {"q": "ビデオでは、北カリフォルニアの火災後の災害救援のための教会の募金活動について、牧師はどのように感じていますか？", "s": "善行の意味", "o": "A.ゴングを叩いたり、ドラムを叩いたりする価値があります,B.自慢するのではなく、私たちがすべきことは、人生の成長を実践する機会です,C.神々と祝福を交換するために使用,D.中国人だけが助けを必要としています"}, {"q": "ビデオによると，なぜ神は天の場所だけでなく，天に行く人々も備えておられるのでしょうか。", "s": "作成者", "o": "A.天国には場所が足りないから,B.人々の生活が変わらなければ、美しい環境はエデンの園のように破壊されるからです。,C.なぜなら、神は生き生きとすることが大好きだからです。,D.天使が足りないから"}, {"q": "クリスチャンの善行と恵みの関係はどのようなものですか。", "s": "善行と恵み", "o": "A.善行は恵みのための交渉のチップです,B.善行は人生の表現であり、天国の保証ではありません,C.善を行えば行なうほど，自分の罪を贖うことができます。,D.善行は必要ありません"}, {"q": "（複数選択可）聖書は，新しい天と新しい地（天）について何を明らかにしていますか。", "s": "Xintianxintiandi", "o": "A.涙はありません,B.痛みを伴う死はありません,C.カルマの美徳がもたらす快楽の地,D.神が御自分の民のために用意された場所"}, {"q": "（複数選択可）人々はどのようにして天国に行く準備ができているでしょうか。", "s": "楽園に入る", "o": "A.天の創造主との関係を回復し、救いを受ける,B.毎日新しい生活を送る、聖霊の住まい,C.功績を積み重ね、善行を行い、神と交換すること,D.更新された意図による変更"}, {"q": "地獄で最も恐ろしいことは、ナイフマウンテンに登り、オイルポットに降りるなどのペナルティです。", "s": "地獄の真実"}, {"q": "クリスチャンは，外側の良い行いを神と天国への切符と交換することができます。", "s": "カルマ交換"}, {"q": "天国と地獄の啓示は、人間自身の理解からではなく、宇宙を創造した真の神の聖書の啓示から来ています。", "s": "啓示の源"}, {"q": "天国と地獄について話すときに，「だれが最初に話すのか」を強調するのはなぜですか。", "s": "話す資格のある人"}, {"q": "ビデオによると，天国への神の「備え」の2つの側面は何ですか。", "s": "神の摂理"}]}, "ko": {"title": "제24과 천국과 지옥", "content": "천국은 죽음의 눈물이 없는 새 하늘과 새 땅입니다. 지옥은 영원히 하나님에게서 끊어집니다. 이 수업의 영원한 결말은 오늘날의 삶에서 영원한 가치를 지닌 삶에 영감을 준다. 영원한 희망이 이생에서 여러분의 길을 밝혀 주길 바랍니다. 더 나은 집을 기대하고 인내심을 가지세요.", "instructions": "", "guide": [{"title": "내세에 대한 의견이 분분하다", "points": ["환생 개념: 이생에서 좋은 사람이 되고, 다음 생에서 사람이 되고, 좋은 사람이 되지 말고 다음 생에서 동물이 되라.", "사람은 빛처럼 죽는다: 죽은 후에는 숨 쉬는 것과 같고, 아무것도 남지 않는다.", "서양 천국까지, 지옥까지: 다음 생에 18겹의 지옥까지, 좋은 사람이 되지 마십시오."]}, {"title": "핵심 질문: 누가 이런 말을 했나요?", "points": ["사후 세계는 경험과 시간을 초월합니다. 누가 우리에게 진실을 말할 수 있습니까?", "깨달음과 상상력은 신뢰할 수 없습니다: 죽은 자 중 누구도 우리에게 말하기 위해 돌아 오지 않았습니다.", "첫 번째 원칙: 먼저 정보 게시자가 누구인지 확인한 다음 정보가 참인지 거짓인지 판단합니다."]}, {"title": "천국과 지옥: 인간의 발명이 아닌 하나님의 계시", "points": ["우주를 창조하신 참 하나님은 시간과 공간을 초월하여 우리가 어디에서 왔고 어디로 가고 있는지를 말씀하실 수 있는 유일한 자격이 있으십니다.", "하나님께서는 우리를 위해 새 하늘과 새 땅을 준비하셨고, 평생 하나님을 거부하는 사람들을 위해 지옥을 준비하셨습니다.", "천국과 지옥은 인간의 환상, 깨달음, 인공 유토피아가 아닙니다."]}, {"title": "인간은 변화되어야 한다: 낙원은 에덴동산의 반복이 아니다", "points": ["에덴 동산에서 얻은 교훈: 하느님은 그것을 “매우 좋다” 고 부르시고, 인간이 하느님과 대면한 후에는 선이 나빠집니다.", "사람들은 죄 많은 삶으로 천국에 갑니다. 천국은 여전히 천국입니다. 사람들이 먼저 천국에 갈 수 있도록 준비하십시오.", "제한된 필멸의 삶이 하는 일: 하나님께서는 죄 많은 세대에 속한 한 무리의 사람들을 그들의 삶이 변화된 후에 영광스러운 환경에 들어가도록 준비시키십니다."]}, {"title": "선행은 칩이 아닙니다: 생명의 부으심", "points": ["그리스도인의 선행은 은혜를 위한 교섭이나 하늘의 보증이 아니라 생명의 부어주심입니다.", "광택있는 외모가 건강한 삶을 의미하는 것은 아닙니다: 노벨 문학상 수상 중단, 북미에서 Me Too 이벤트 성공", "선행을 검증해야 합니다. 교회 재난 구호 기부는 공로를 쌓는 것이 아니라 삶의 성장을 실천할 수 있는 기회입니다."]}, {"title": "준비 방법: 하나님과의 관계 회복", "points": ["첫 번째 단계는 하늘의 창조주와의 관계를 회복하는 것입니다. 하나님께서 우리에게 오시지 않았다면 우리는 그분을 전혀 찾지 못했을 것입니다.", "참된 신앙은 의식화된 종교가 아닙니다: 그분을 생명의 주님으로 맞이하며, 성령께서는 우리에게 매일 새로운 삶의 방식으로 살라고 일깨워 주십니다.", "로마서 12: 2: 세상을 본받지 말고 마음을 바꾸어 빛과 정직과 의의 삶을 살라"]}, {"title": "구속된 몸: 마지막 은총", "points": ["그리스도인은 죽을 때까지 불완전하지만, 하나님은 우리가 기꺼이 그분을 위대하게 공경하고 그분의 은혜를 우리의 생애 동안 지키고자 하는지를 보십니다.", "하나님의 마지막 은혜: 새 하늘과 새 땅에 들어가기 전에 구속받은 영체를 우리에게 주시는 것", "평생 동안 의지를 증명하고 마침내 완전히 새로운 몸을 얻어 새로운 세계로 들어갑니다."]}, {"title": "지옥의 공포: 하나님과의 영원한 분리", "points": ["지옥은 거룩함과 의로움을 위해 피할 수 없는 하나님의 계획이며, 하나님은 사람들이 지옥에 가는 것을 좋아하지 않으십니다.", "지옥에 대해 정말 끔찍한 것은 불멸의 벌레, 꺼지지 않는 불이 아니라 그곳에 하나님이 없다는 사실, 즉 하나님으로부터의 영원한 분리입니다.", "경건하지 않고 자기중심적인 사람들이 많이 모여서 이런 종류의 고통은 불보다 더 끔찍합니다."]}, {"title": "오늘 준비하세요: 모든 사람에게 은혜가 열립니다", "points": ["신자가 죽은 후, 그는 먼저 낙원으로 끌려가고, 불신자는 큰 흰 보좌의 심판을 기다리기 위해 지하 세계로 간다.", "심판 후에 낙원에 있는 신자들은 새 하늘과 새 땅으로 끌려갔고, 지하에 있는 불신자들은 하나님과 영원한 이별의 장소로 돌아갔습니다.", "은혜는 오늘날 모든 사람에게 열려 있습니다. 공로를 교환할 필요가 없으며, 선행은 삶의 표상이며, 나쁜 부분은 새로운 삶을 살기 위해 구원에 의해 인도됩니다."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 하나님께서는 그들의 모든 ________, 더 이상 죽음도, 더 이상 ________, 더 이상 울음도, 더 이상 고통도 없애실 것입니다.", "s": "Xintianxintiandi"}, {"q": "[Scripture Fill in the Blank] 아버지 집에 ________ 이 (가) 많습니다. ________ 을 (를) 위해 갔습니다.", "s": "숙소 준비하기"}, {"q": "[Scripture Fill in the Blank] 이 세상을 ________ 하지 말고 마음만 바꾸세요 ________", "s": "마인드 업데이트"}, {"q": "사후 세계에 대한 다양한 주장에 대한 핵심 질문은 \"누가 그것을 말했는가\" 입니다. ________ 우주, 즉 시간과 공간을 초월한 진정한 하나님 만이 우리가 어디에서 왔고 어디로 가는지 알려줄 자격이 있습니다.", "s": "발언 자격이 있는 사람"}, {"q": "지옥에서 가장 끔찍한 것은 킬른 블레이드 마운틴이 아니라 하나님이 영원하신 하나님의 창조와 분리되는 것을 원하지 않는 많은 사람들입니다.", "s": "지옥의 진실"}, {"q": "C.S. 루이스는 다음과 같이 말했습니다. 지옥은 ________ 을 (를) 위해 결코 준비되지 않았습니다. 하나님은 ________ 을 (를) 위해 선한 사람이 되도록 인간을 창조하셨습니다.", "s": "지옥은 준비되지 않았습니다"}, {"q": "오늘 하나님께서 준비하신 것은 단순히 천국에 있는 곳이 아니라 ________ 을 (를) 준비하는 사람입니다. 천국에 들어가는 것은 외부 ________ 의 교환에 의존하지 않습니다.", "s": "작성자"}, {"q": "고린도 교인은 다음과 같이 말합니다. 우리에게는 ________ 의 몸과 ________ 의 몸이 있으며, 이는 믿는 자들에게 하나님의 마지막 은혜입니다.", "s": "상환된 본문"}, {"q": "성경의 계시에 따르면, 그리스도인이 죽은 후 하나님께서는 먼저 ________ (으) 로 인도하셨고, 하나님을 받아들이지 않는 사람들은 ________ (으) 로 와서 마지막 심판을 기다렸습니다.", "s": "사망 후 가볼 만한 곳"}, {"q": "동영상에서 목사는 캘리포니아 북부 화재 이후 교회의 재난 구호 기금 모금에 대해 어떻게 생각하는가?", "s": "선행의 의미", "o": "A.징을 이기고 드럼을 연주할 가치가 있습니다,B.자랑하는 것이 아니라 우리가 해야 할 일은 인생의 성장을 실천할 수 있는 기회입니다.,C.신과 축복을 교환하는 데 사용할 수 있습니다,D.중국인만 도움을 받을 수 있습니다."}, {"q": "동영상에 따르면, 하나님께서는 왜 천국뿐만 아니라 천국에 가는 사람들도 준비하시는가?", "s": "작성자", "o": "A.천국에 자리가 부족해서,B.사람들의 삶이 바뀌지 않으면 에덴동산처럼 아름다운 환경이 파괴될 것이기 때문입니다.,C.하느님께서는 활기차기를 좋아하시기 때문입니다.,D.천사가 부족해서"}, {"q": "그리스도인의 선행과 은혜는 어떤 관계가 있는가?", "s": "선행과 은혜", "o": "A.선행은 은혜를 위한 협상 칩입니다,B.선행은 삶의 표현이지 천국을 보장하는 것이 아닙니다.,C.선을 더 많이 행할수록 더 많은 죄를 속죄할 수 있습니다.,D.선행이 필요 없음"}, {"q": "(객관식) 성경은 새 하늘과 새 땅 (천국) 에 대해 무엇을 계시하는가?", "s": "Xintianxintiandi", "o": "A.눈물 없음,B.고통스러운 죽음 없음,C.카르믹 덕이 이끄는 기쁨의 땅,D.하나님께서 자기 백성을 위해 준비하신 장소"}, {"q": "(객관식) 사람들은 어떻게 천국에 갈 준비를 할 수 있습니까?", "s": "파라다이스 입장", "o": "A.하늘의 창조주와의 관계를 회복하고 구원을 받으십시오,B.매일 새로운 삶을 살아가는 성령의 내주,C.공로를 쌓고, 선을 행하고, 하나님과 교환함으로써,D.새로운 의도로 인한 변경 사항"}, {"q": "지옥에서 가장 끔찍한 일은 나이프 마운틴에 올라가 기름 항아리로 내려가는 것과 같은 처벌입니다.", "s": "지옥의 진실"}, {"q": "그리스도인은 외적인 선행을 하나님과 함께 천국으로 가는 티켓으로 교환할 수 있습니다.", "s": "Karmic 교환"}, {"q": "천국과 지옥의 계시는 인간 자신의 이해가 아니라 우주를 창조하신 참 하나님에 대한 성경적 계시에서 비롯됩니다.", "s": "계시의 원천"}, {"q": "동영상에서 천국과 지옥에 대해 이야기할 때 “누가 먼저 말합니까?” 를 강조하는 이유는 무엇인가?", "s": "발언 자격이 있는 사람"}, {"q": "동영상에 따르면, 하나님께서 하늘을 위해 준비하시는 두 가지 측면은 무엇인가?", "s": "하나님의 공급하심"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773060038868','基要真理','第二十五课 永恒与今生','永生从认识真神开始。重生转换生命特质，在今生活出永恒的价值。本课讲永恒观如何影响我们今生的每一个选择。愿你为永恒而活，不虚度今生。积财宝在天上，讨主喜悦。','[{"type": "verse", "q": "【经文填空】认识你________的真神，并且认识你所________的耶稣基督，这就是永生", "o": "《约翰福音》17章3节", "s": "永生的定义", "a": "独一|差来"}, {"type": "verse", "q": "【经文填空】人若不是从________和________生的，就不能进神的国", "o": "《约翰福音》3章5节", "s": "重生", "a": "水|圣灵"}, {"type": "verse", "q": "【经文填空】你们要________主恩的滋味，便知道他是________", "o": "《诗篇》34篇8节", "s": "主恩滋味", "a": "尝尝|美善"}, {"type": "fill", "q": "诗篇90篇说：人一生的年岁是________十岁，若是强壮可到________十岁，其中所矜夸的不过是劳苦愁烦。", "o": "", "s": "人生短暂", "a": "七|八"}, {"type": "fill", "q": "不认识神的老我生命活在________主义、功利主义、享乐主义中，以自我为中心。", "o": "", "s": "老我生命", "a": "本位"}, {"type": "fill", "q": "罗马书说：在耶稣基督里，赐生命________的律胜过罪和________的律。", "o": "", "s": "圣灵的律", "a": "圣灵|死"}, {"type": "fill", "q": "圣灵九果包括仁爱、喜乐、________、忍耐、恩慈、良善、信实、________、节制。", "o": "", "s": "圣灵九果", "a": "和平|温柔"}, {"type": "fill", "q": "诗篇说：敬畏耶和华是________的开端，认识至圣者便是聪明。", "o": "", "s": "智慧开端", "a": "智慧"}, {"type": "fill", "q": "保罗说：我________种了，亚波罗浇灌了，唯有神叫他________。", "o": "", "s": "栽种浇灌", "a": "栽|生长"}, {"type": "single", "q": "按视频所讲，“永生”从什么时候开始？", "o": "A.从人死亡那一刻开始,B.从人认识真神、接受救恩、生命被改变的今生就开始,C.从世界末日开始,D.从人年老退休开始", "s": "永生开始", "a": "B"}, {"type": "single", "q": "视频用“初熟的果子”作比喻，是要说明什么？", "o": "A.基督徒要多种果树,B.今生先尝到主恩的滋味，便知道永恒的美善,C.初熟的果子要献给神,D.果子越多越属灵", "s": "初熟果子", "a": "B"}, {"type": "single", "q": "保罗“你们论断我，我当作极小的事”的态度表明基督徒的价值观是？", "o": "A.不在乎任何人的看法我行我素,B.不以人的评价为标准，判断我的是主,C.要讨好所有人,D.从不反省自己", "s": "保罗榜样", "a": "B"}, {"type": "multiple", "q": "（多选）按视频所讲，圣灵九果包括以下哪些？", "o": "A.仁爱,B.喜乐,C.和平,D.嫉妒纷争", "s": "圣灵九果", "a": "A|B|C"}, {"type": "multiple", "q": "（多选）按视频所讲，哪些是对“永生”的错误看法？", "o": "A.把今世解决不了的问题通通往后丢的虚幻盼望,B.因今世过得不好而消极逃避的心灵转移,C.从今生就开始的生命特质的改变,D.死了以后才开始的漫长时间", "s": "永生误解", "a": "A|B|D"}, {"type": "judge", "q": "永生只是将来死后才开始的无限延长的时间。", "o": "", "s": "永生本质", "a": "错"}, {"type": "judge", "q": "基督徒的丧礼有眼泪但不绝望，因为知道将来还要在主里再相见。", "o": "", "s": "复活盼望", "a": "对"}, {"type": "judge", "q": "只要参加过布道会举过手、受过洗、加入教会，就是圣经所说的得救。", "o": "", "s": "真得救", "a": "错"}, {"type": "essay", "q": "视频说“就是因为你不认识永生，你今生才过得不好”，这是什么意思？", "o": "", "s": "永恒眼光", "a": "因为人若眼光只局限在有限的今生，就会汲汲营营、斤斤计较，被人的评价和环境的得失捆绑，活得很苦。若有永恒的盼望，就知道什么是重要的、什么可以放下：尽本分、按真理而活，成果交托给神，不以今生为衡量一切的唯一标准，反而能在今生活出平安喜乐。"}, {"type": "essay", "q": "按视频所讲，圣经中的“得救”与人自己定义的“得救”有何不同？", "o": "", "s": "真得救", "a": "人自己定义的得救很短浅：落在难处中问题被解决就叫得救。圣经的得救是生命的改变：从以自我为中心的生命，进入有永恒特质的生命——口里认耶稣为主、心信神叫祂从死里复活，让耶稣成为生命的主，在今生就经历祂作主的美善、尝到新生命的滋味。"}]','https://youtu.be/P41NRTrLu5E
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134Cd88','quiz','[{"title": "永生是盼望还是困惑", "points": ["有人把今世无法解释的苦难通通往后丢，把永生当作虚幻的盼望", "有人觉得今生都过不好，谈永生只是心灵转移、消极避世", "这两种心态都不是基督信仰谈永生的正确方向"]}, {"title": "有限今生的真相", "points": ["人死如灯灭、一切结束的想法，其实带来更大的恐惧", "诗篇九十篇说，人一生的年日七十、强壮可到八十，所矜夸的不过是劳苦愁烦", "今世再功成名就也什么都带不走，有限的今生充满劳苦愁烦"]}, {"title": "永生从今生就开始", "points": ["耶稣对尼哥底母讲重生：从水和圣灵生，进入神的国", "约翰福音十七章说，认识独一真神并认识耶稣基督，这就是永生", "永生不只是时间的延长，更是生命特质的转换，从得救那天就开始"]}, {"title": "初熟果子的比喻", "points": ["圣经用初熟的果子比喻：先尝到树上第一颗果子的滋味，就知道整棵树的味道", "有限的今生必须先尝到主恩的滋味，才知道永恒是好得无比", "永恒若只是时间延长、生命本质不变，活得越久就痛苦得越久"]}, {"title": "脱下旧人穿上新人", "points": ["不认识神的老我生命：本位主义、功利主义、享乐主义、自我为中心", "在救恩里脱下旧人、穿上新人，活出新生的样式", "圣灵进驻生命，结出仁爱、喜乐、和平、忍耐、恩慈、良善、信实、温柔、节制九果"]}, {"title": "遵行带来确据", "points": ["敬畏耶和华是智慧的开端，认识至圣者便是聪明；遵行神的话才尝得到主恩", "保罗把别人的批评论断当作很小的事，因为判断他的是主", "我栽种、亚波罗浇灌，惟有神叫他生长：尽本分、成果交托神"]}, {"title": "不再惧怕死亡", "points": ["死是老我生命的终结；已经重生的人，永恒生命的特质仍然存在", "基督徒的丧礼有眼泪却不绝望，因为相信在主里将来还要再相见", "靠着永生的盼望，今生不再对死亡有恐慌无知的恐惧"]}, {"title": "真正的得救", "points": ["得救不只是布道会举手、受洗或加入教会，而是生命的改变", "口里认耶稣为主，心里信神叫他从死里复活，这样的人真正得救", "在有限今生经历祂作主的美善，活出有力的见证，迎向永恒"]}]','','25','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 25 Eternity and this life", "content": "Eternal life begins with knowing the true God. Rebirth transforms life traits and creates eternal value in today''s life. This lesson is about how the concept of eternity influences every choice we make in this life. May you live for eternity and live this life. Accumulate treasure in heaven to please the Lord.", "instructions": "", "guide": [{"title": "Is eternal life hope or confusion?", "points": ["Some people pass the inexplicable suffering of this world backwards, and regard eternal life as an illusory hope.", "Some people think that this life is not good, talking about eternal life is just a change of heart, negative avoidance of the world", "Neither of these mindsets is the right direction for Christianity to talk about eternal life"]}, {"title": "Limited Mortal Truth", "points": ["The thought of people dying like a light and everything ending actually brings greater fear", "Psalm 90 says that a person can be strong for 70 or 80 years of his life, and all he boasts about is toil and sorrow.", "If you become famous again in this world, you will not take anything with you. The limited life is full of toil and sorrow."]}, {"title": "Eternal life begins in this life", "points": ["Jesus speaks to Nicodemus about regeneration: being born of water and the Holy Spirit and entering the kingdom of God", "John 17 says that knowing the one true God and knowing Jesus Christ is eternal life.", "Eternal life is not only the extension of time, but also the transformation of life traits, starting from the day of salvation."]}, {"title": "Parable of the firstfruits", "points": ["The Bible compares the taste of the first fruit of a tree to the taste of the whole tree", "The finite mortal life must first taste the Lord''s grace to know that eternity is incomparably good", "If eternity is only the extension of time and the essence of life remains unchanged, the longer you live, the longer you suffer."]}, {"title": "Take off the old man and put on the new one.", "points": ["The old life without God: egotism, utilitarianism, hedonism, self-centeredness", "Take off the old man, put on the new man, and live a new life in salvation", "The Holy Spirit enters life and bears the nine fruits of love, joy, peace, patience, kindness, goodness, faithfulness, gentleness and temperance"]}, {"title": "Compliance brings certainty", "points": ["The fear of the Lord is the beginning of wisdom, and knowing the Holy One is wisdom; only by obeying the word of God can you taste the Lord''s grace.", "Paul took the criticism of others as a small matter, because it was the Lord who judged him.", "I planted and Apollo watered, but God told him to grow: do his duty and entrust the fruits to God"]}, {"title": "No more fear of death", "points": ["Death is the end of my old life; those who have been reborn, the trait of eternal life still exists", "Christian funerals have tears but not despair, because I believe that in the future we will see each other again in the Lord", "With the hope of eternal life, this life no longer has the fear of death."]}, {"title": "True Salvation", "points": ["Being saved isn''t just about raising your hand, being baptized, or joining a church, it''s about changing your life.", "Such a person is truly saved by confessing Jesus as Lord with his mouth and believing in God in his heart to raise him from the dead.", "Experience the goodness of His reign in the finite mortal life, live a powerful witness to eternity"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] To know the true God of your ________, and to know the Jesus Christ of your ________, is eternal life.", "s": "Definition of Immortality"}, {"q": "[Scripture Fill in the Blank] If one is not born from ________ and ________, one cannot enter the kingdom of God", "s": "Resurrection"}, {"q": "[Scripture Fill in the Blank] If you want the taste of the Lord''s grace, you know that He is ________", "s": "Taste of the Lord"}, {"q": "Psalm 90 says: The age of a person''s life is ________ ten years old. If he is strong, he can reach ________ ten years old. The boasting in it is nothing but toil and sorrow.", "s": "Life is short. "}, {"q": "The old me who does not know God lives in ________ doctrine, utilitarianism, and hedonism, and is self-centered.", "s": "Old My Life"}, {"q": "Romans says: In Jesus Christ, the law of life-giving ________ is better than sin and the law of ________.", "s": "The Law of the Holy Spirit"}, {"q": "The nine fruits of the Holy Spirit include love, joy, ________, patience, kindness, goodness, faithfulness, ________, temperance.", "s": "Holy Spirit Nine Fruit"}, {"q": "The Psalm says: The fear of the Lord is the beginning of ________, and to know the Holy One is to be wise.", "s": "Wisdom Beginnings"}, {"q": "Paul said: I ________, Apollo watered, only God called him ________.", "s": "Planting irrigation"}, {"q": "According to the video, when does “immortality” begin?", "s": "Beginning of eternal life", "o": "A.From the moment a person dies,B.Beginning in this life when man knows the true God, receives salvation, and his life is transformed,C.From the end of the world,D.Beginning with old age and retirement"}, {"q": "What does the video illustrate by using the metaphor of “first fruits”?", "s": "First fruits", "o": "A.Christians want a variety of fruit trees,B.Taste the Lord''s grace first in this life, and you will know the eternal goodness,C.First fruits to be offered to God,D.The more fruit, the more spiritual"}, {"q": "Paul''s attitude of “You judge me, I take it as a trivial matter” shows what Christian values are?", "s": "Paul Role Models", "o": "A.I don''t care what anyone thinks, I do what I do.,B.Not based on people''s evaluation, it is the Lord who judges me,C.to please everybody.,D.Never reflect on yourself"}, {"q": "(Multiple choice) According to the video, which of the following are the nine fruits of the Holy Spirit?", "s": "Holy Spirit Nine Fruit", "o": "A.Nhon Ai,B.joy,C.Peace,D.Jealousy and strife"}, {"q": "(Multiple choice) Which of these is the wrong view of “immortality” as stated in the video?", "s": "Immortal Misunderstanding", "o": "A.The illusory hope of passing the world''s unsolvable problems backwards,B.Negative escape mind shift due to bad life in this world,C.Changes in life traits from this life,D.The long time it took to start after death"}, {"q": "Eternal life is only an infinitely longer time that begins after death in the future.", "s": "Immortality Essence"}, {"q": "Christian funerals have tears but not despair, knowing that we shall see each other again in the Lord in the future.", "s": "Resurrection Hope"}, {"q": "As long as you have participated in the sermon, raised your hand, been baptized, and joined the church, it is what the Bible says about salvation.", "s": "Truly saved."}, {"q": "What does it mean when the video says, “You have a bad life because you don''t know eternal life”?", "s": "Eternal vision"}, {"q": "According to the video, how is “salvation” in the Bible different from “salvation” in people''s own definitions?", "s": "Truly saved."}]}, "ja": {"title": "レッスン25永遠と現世", "content": "永遠の命は，真の神を知ることから始まります。生まれ変わりは人生の特性を変え、今日の人生に永遠の価値を創造します。この課では，永遠という概念が，わたしたちがこの世で行うすべての選択にどのように影響するかについて説明します。あなたが永遠に生き、この人生を生きることができますように。主を喜ばせるために、天に宝を蓄えてください。", "instructions": "", "guide": [{"title": "永遠の命は希望でしょうか，それとも混乱でしょうか。", "points": ["この世の莫大な苦しみを後ろ向きに過ごし，永遠の命を幻想的な希望とみなす人もいます。", "この人生は良くないと思う人もいます。永遠の命について話すことは、心の変化であり、世の中を否定的に避けることです", "これらの考え方のいずれも、キリスト教が永遠の命について話す正しい方向ではありません"]}, {"title": "限られた人間の真実", "points": ["人々が光のように死に、すべてが終わるという考えは、実際にはより大きな恐怖をもたらします", "詩篇90篇には，人は70年から80年の人生を強く生きることができると書かれています。彼が自慢しているのは，苦労と悲しみだけです。", "あなたがこの世で再び有名になれば、あなたは何も持っていかないでしょう。限られた人生は苦労と悲しみに満ちています。"]}, {"title": "永遠の命はこの命から始まる", "points": ["イエスはニコデモに再生について話します：水と聖霊から生まれ、神の王国に入ること", "ヨハネ17章には，唯一の真の神を知り，イエス・キリストを知ることは永遠の命であると書かれています。", "永遠の命は時間の延長であるだけでなく、救いの日から始まる命の特性の変化でもあります。"]}, {"title": "初物のたとえ話", "points": ["聖書は、木の最初の果実の味と木全体の味を比較しています", "有限の現世は，まず主の恵みを味わい，永遠が比類のない良いものであることを知らなければなりません。", "永遠が時間の延長に過ぎず、人生の本質が変わらないのであれば、あなたが長生きすればするほど、あなたは長く苦しみます。"]}, {"title": "老人を脱いで、新しいのを着なさい。", "points": ["神のいない古い生活：利己主義、功利主義、快楽主義、自己中心主義", "古い人を脱ぎ捨て、新しい人を着て、救いの中で新しい人生を送る", "聖霊は命に入り、愛、喜び、平和、忍耐、親切、善、忠実、優しさ、節制の9つの果実を結びます"]}, {"title": "コンプライアンスは確実性をもたらします", "points": ["主を恐れることは知恵の初めであり，聖なる方を知ることは知恵です。神の言葉に従うことによってのみ，主の恵みを味わうことができます。", "パウロは、自分を裁いたのは主であるため、他人の批判をささいなこととして捉えていました。", "私は植え、アポロは水をやりましたが、神は彼に成長するように命じました：彼の義務を果たし、果実を神に託してください"]}, {"title": "死の恐怖はもうありません", "points": ["死は私の古い人生の終わりです。生まれ変わった人、永遠の命の特性はまだ存在します", "キリスト教の葬儀には涙がありますが、絶望はありません。なぜなら、将来、私たちは主の中で再びお互いに会うことになると信じているからです", "永遠の命の希望をもって，この命にはもはや死の恐れがありません。"]}, {"title": "真の救い", "points": ["救われるということは，手を挙げたり，バプテスマを受けたり，教会に参加したりすることだけではなく，人生を変えることです。", "そのような人は，口をもってイエスを主と告白し，心の中で神を信じてイエスを死者の中から復活させることによって，本当に救われます。", "有限の現世で主の治世の良さを経験し，永遠への強力な証人として生きる"]}], "quizzes": [{"q": "〔聖句の穴埋め〕あなたの________の真の神を知り，あなたの________のイエス・キリストを知ることは永遠の命です。", "s": "不死の定義"}, {"q": "〔聖句の穴埋め〕________と________から生まれなければ，神の王国に入ることはできません。", "s": "再生"}, {"q": "〔聖句の穴埋め〕主の恵みの味を味わいたいのであれば，主が________であることを知っているはずです。", "s": "主の味"}, {"q": "詩篇90篇は次のように述べています：人の人生の年齢は________ 10歳です。彼が強ければ、彼は________ 10歳に達することができます。その中で自慢することは、苦労と悲しみ以外の何ものでもありません。", "s": "人生は短い"}, {"q": "神を知らない年老いたわたしは， ________教義，功利主義，享楽主義の中に住み，自己中心的です。", "s": "オールド・マイ・ライフ"}, {"q": "ローマ人は次のように言います。「イエス・キリストにおいて，命を与える律法は，罪や________の律法よりも優れています。", "s": "聖霊の律法"}, {"q": "聖霊の九つの実には，愛，喜び， ________ ，忍耐，優しさ，善良さ，忠実さ， ________ ，節制が含まれます。", "s": "聖霊九果"}, {"q": "詩篇は次のように述べています。「主を恐れることは________の始まりであり、聖なる方を知ることは賢明であることです。", "s": "知恵の始まり"}, {"q": "パウロは言いました：私は________、アポロは水を注ぎました、神だけが彼を________と呼びました。", "s": "灌漑の植え付け"}, {"q": "ビデオによると、「不死」はいつ始まりますか？", "s": "永遠の命の始まり", "o": "A.人が死んだ瞬間から,B.人が真の神を知り、救いを受け、人生が変わるこの人生の始まり,C.世界の果てから,D.高齢と退職から始まる"}, {"q": "ビデオは，「最初の実」という比喩を使って何を示していますか。", "s": "最初のフルーツ", "o": "A.クリスチャンは様々な果樹を望んでいます,B.この世で最初に主の恵みを味わうと，あなたは永遠の恵みを知るでしょう,C.神に捧げる最初の実,D.果実が多いほど、より精神的に"}, {"q": "パウロの「あなたは私を裁き、私はそれを些細なこととみなします」という態度は、キリスト教の価値観が何であるかを示していますか？", "s": "ポールのロールモデル", "o": "A.私は誰が何を考えようと気にしません、私は私がすることをします。,B.人々の評価に基づくのではなく、私を裁くのは主です,C.皆を喜ばせるために。,D.決して自分自身を振り返らない"}, {"q": "（複数選択可）ビデオによると，次のうち，聖霊の九つの果実はどれですか。", "s": "聖霊九果", "o": "A.ノンアイ,B.喜び,C.平和,D.嫉妬と争い"}, {"q": "（複数選択可）ビデオに記載されている「不死」の間違った見方はどれですか？", "s": "不滅の者の誤解", "o": "A.世界の解決不可能な問題を逆行させる幻想的な希望,B.この世の悪い生活によるネガティブな脱出マインドシフト,C.この人生からの人生の特性の変化,D.死後に始まるまでにかかった長い時間"}, {"q": "永遠の命は，死後の将来に始まる無限に長い時間にすぎません。", "s": "不死のエッセンス"}, {"q": "キリスト教の葬儀には涙がありますが、絶望はありません。将来、主の中で再びお互いに会うことを知っています。", "s": "復活の希望"}, {"q": "説教に参加し，手を挙げ，バプテスマを受け，教会に参加している限り，聖書は救いについて述べています。", "s": "本当に助かりました。"}, {"q": "ビデオに「あなたは永遠の命を知らないために悪い人生を送っている」と書かれているのは，どういう意味でしょうか。", "s": "永遠のビジョン"}, {"q": "ビデオによると，聖書の「救い」は，人々自身の定義における「救い」とどのように異なりますか。", "s": "本当に助かりました。"}]}, "ko": {"title": "제 25과 영생과 현세", "content": "영생은 참 하나님을 아는 것에서 시작됩니다. 거듭남은 오늘날의 삶에서 삶의 특성을 변화시키고 영원한 가치를 창출합니다. 이 수업은 영원의 개념이 우리가 이생에서 내리는 모든 선택에 어떻게 영향을 미치는지에 관한 것이다. 여러분이 영원을 위해 살고 이 삶을 살기를 바랍니다. 하늘에 보물을 쌓아 주님을 기쁘시게 하십시오.", "instructions": "", "guide": [{"title": "영생은 희망입니까, 아니면 혼란입니까?", "points": ["어떤 사람들은 이 세상의 설명할 수 없는 고통을 거꾸로 전달하고, 영생을 환상적인 희망으로 여깁니다.", "어떤 사람들은 이 삶이 좋지 않다고 생각합니다. 영생에 대해 이야기하는 것은 단지 마음의 변화이며, 세상을 부정적으로 회피하는 것입니다.", "이 사고방식 중 어느 것도 기독교가 영생에 대해 이야기하는 올바른 방향이 아닙니다."]}, {"title": "제한된 필멸의 진리", "points": ["사람들이 빛처럼 죽어가고 모든 것이 끝나는 것에 대한 생각은 실제로 더 큰 두려움을 가져옵니다.", "시편 90 편은 사람이 70 년 또는 80 년 동안 강해질 수 있다고 말하며, 그가 자랑하는 것은 수고와 슬픔뿐입니다.", "이 세상에서 다시 유명해지면 아무것도 가지고 가지 않을 것입니다. 제한된 삶은 수고와 슬픔으로 가득합니다."]}, {"title": "영생은 이생에서 시작됩니다", "points": ["예수님은 니고데모에게 거듭남에 대해 말씀하십니다. 물과 성령으로 태어나 하나님 나라에 들어가는 것입니다.", "요한복음 17장은 유일하신 참 하나님을 알고 예수 그리스도를 아는 것이 영생이라고 말한다.", "영생은 시간의 연장일 뿐만 아니라 구원의 날부터 시작하여 생명 특성의 변화입니다."]}, {"title": "첫 열매의 비유", "points": ["성경은 나무의 첫 열매의 맛을 나무 전체의 맛과 비교합니다.", "유한한 필멸의 삶은 영원이 비교할 수 없이 좋다는 것을 알기 위해 먼저 주님의 은혜를 맛봐야 합니다.", "영원이 시간의 연장일 뿐이고 삶의 본질이 변하지 않는다면, 더 오래 살수록 더 오래 고통받게 됩니다."]}, {"title": "옛 사람을 벗고 새 사람을 입으십시오.", "points": ["하나님 없는 옛 생활: 이기주의, 공리주의, 쾌락주의, 자기중심주의", "옛 사람을 벗고 새 사람을 입으며 구원의 새 삶을 살라", "성령께서는 생명에 들어가 사랑, 기쁨, 평화, 인내, 친절, 선함, 신실함, 온유와 절제의 아홉 가지 열매를 맺으십니다."]}, {"title": "규정 준수로 확실성 확보", "points": ["주님을 경외하는 것이 지혜의 시작이며, 거룩하신 분을 아는 것이 지혜입니다. 오직 하나님의 말씀에 순종해야만 주님의 은혜를 맛볼 수 있습니다.", "바울은 다른 사람들에 대한 비판을 작은 문제로 받아들였습니다. 왜냐하면 그를 심판하신 분은 주님이셨기 때문입니다.", "나는 심었고 아폴로는 물을 주었으나 하나님은 그에게 자라라고 말씀하셨습니다. 자신의 의무를 다하고 열매를 하나님께 맡기십시오."]}, {"title": "죽음에 대한 두려움은 이제 그만", "points": ["죽음은 내 옛 삶의 끝이다. 거듭난 자들은 영생의 특성이 여전히 존재한다.", "그리스도인의 장례식에는 눈물이 있지만 절망하지 않습니다. 왜냐하면 장차 우리가 주님 안에서 다시 만날 것이라고 믿기 때문입니다.", "영생의 소망으로 이 생은 더 이상 죽음에 대한 두려움이 없습니다."]}, {"title": "참된 구원", "points": ["구원받는다는 것은 단순히 손을 들거나 침례를 받거나 교회에 가입하는 것이 아니라 삶을 변화시키는 것입니다.", "그러한 사람은 입으로 예수님을 주님으로 고백하고 그를 죽은 자 가운데서 살리려는 마음에서 하나님을 믿음으로써 진정으로 구원받습니다.", "유한한 필멸의 삶에서 그분의 통치의 선하심을 경험하고 영원에 대한 강력한 증인이 되십시오."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] ________ 의 참 하나님을 아는 것과 ________ 의 예수 그리스도를 아는 것은 영생입니다.", "s": "불멸의 정의"}, {"q": "[Scripture Fill in the Blank] ________ 와 ________ 에서 태어나지 않으면 하나님 나라에 들어갈 수 없다.", "s": "거듭남"}, {"q": "[Scripture Fill in the Blank] 당신이 주님의 은혜의 맛을 원한다면, 당신은 그분이 ________", "s": "주님의 맛"}, {"q": "시편 90편: 인생의 나이는 ________ 열 살입니다. 강하면 ________ 열 살에 이를 수 있습니다. 그 안에 담긴 자랑은 수고와 슬픔에 불과합니다.", "s": "인생은 짧습니다"}, {"q": "하나님을 모르는 늙은이는 ________ 교리, 공리주의, 쾌락주의에 살고 자기중심적입니다.", "s": "Old My Life"}, {"q": "로마서는 다음과 같이 말합니다. 예수 그리스도 안에서 생명을 주는 ________ 의 법은 죄와 ________ 의 법보다 낫습니다.", "s": "성령의 법"}, {"q": "성령의 아홉 가지 열매에는 사랑, 기쁨, ________, 인내, 친절, 선함, 신실함, ________, 절제가 포함됩니다.", "s": "성령의 아홉 가지 열매"}, {"q": "시편은 이렇게 말한다. 주님을 경외하는 것은 ________ 의 시작이며, 거룩하신 분을 아는 것은 현명해지는 것이다.", "s": "지혜의 시작"}, {"q": "바울은 말했다: 나는 ________, 아폴로는 물을 주었고, 오직 하나님만이 그를 ________ 라고 부르셨다.", "s": "식재 관개"}, {"q": "동영상에 따르면 ''불멸'' 은 언제 시작되나요?", "s": "영생의 시작", "o": "A.사람이 죽는 순간부터,B.사람이 참 하느님을 알고, 구원을 받고, 그의 삶이 변화될 때 이 삶에서 시작됩니다.,C.세상 끝에서,D.노후와 은퇴를 시작으로"}, {"q": "이 동영상은 \"첫 열매\" 라는 은유를 사용하여 무엇을 설명합니까?", "s": "첫 번째 과일", "o": "A.그리스도인들은 다양한 과일 나무를 원합니다,B.이생에서 먼저 주님의 은혜를 맛보면 영원한 선하심을 알게 될 것입니다.,C.하나님께 바칠 첫 열매,D.열매가 많을수록 영적인"}, {"q": "바울의 “너희가 나를 판단하니 나는 이것을 하찮은 일로 여긴다” 는 태도는 그리스도인의 가치관이 무엇인지를 보여준다.", "s": "Paul 역할 모델", "o": "A.저는 다른 사람이 어떻게 생각하든 상관하지 않습니다. 저는 제가 하는 일을 합니다.,B.사람들의 평가에 근거하지 않고 나를 심판하시는 분은 주님이십니다.,C.모두를 기쁘게 하기 위해서요.,D.절대로 자신을 반성하지 마세요."}, {"q": "(복수 선택) 동영상에 따르면, 다음 중 성령의 아홉 가지 열매는 무엇입니까?", "s": "성령의 아홉 가지 열매", "o": "A.자비,B.기쁨,C.평화,D.질투와 다툼"}, {"q": "(복수 선택) 다음 중 동영상에 명시된 ''불멸'' 에 대한 잘못된 견해는 무엇인가요?", "s": "불멸의 오해", "o": "A.세상의 해결할 수 없는 문제를 거꾸로 넘길 수 있다는 환상의 희망,B.이 세상의 나쁜 삶으로 인한 부정적인 탈출 마인드 시프트,C.이 삶에서 오는 삶의 특성의 변화,D.사망 후 시작까지 걸린 시간"}, {"q": "영생은 미래에 죽은 후에 시작되는 무한히 긴 시간입니다.", "s": "불멸의 정수"}, {"q": "그리스도인의 장례식에는 눈물이 있지만 절망하지 않습니다. 우리는 장차 주님 안에서 다시 만날 것임을 알고 있습니다.", "s": "부활 소망"}, {"q": "설교에 참여하고, 손을 들고, 침례를 받고, 교회에 가입한 이상, 구원에 대한 성경의 말씀입니다.", "s": "진정으로 구원을 받았습니다."}, {"q": "동영상에서 “영생을 알지 못해 나쁜 삶을 살고 있다” 는 말은 무엇을 의미하는가?", "s": "영원한 비전"}, {"q": "동영상에 따르면, 성경의 “구원” 은 사람들 자신의 정의에서 “구원” 과 어떻게 다릅니까?", "s": "진정으로 구원을 받았습니다."}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1773060749986','基要真理','第二十六课  活出信仰','真知才能力行。本课总结全系列基要真理：把所信的活出来，在生活中见证基督，做世上的光和地上的盐。愿这二十六课成为你一生的祝福。一生跟随主，至死忠心不偏离。','[{"type": "verse", "q": "【经文填空】只是你们要________，不要单单________，自己欺哄自己", "o": "《雅各书》1章22节", "s": "代赎之爱", "a": "行道|听道", "h": "《雅各书》1章22节"}, {"type": "verse", "q": "【经文填空】不要效法这个世界，只要心意更新而变化，叫你们查验何为神的________、纯全、可喜悦的旨意", "o": "《罗马书》12章2节", "s": "心意更新", "a": "善良"}, {"type": "verse", "q": "【经文填空】所以，你们或吃或喝，无论做什么，都要为________而行", "o": "《哥林多前书》10章31节", "s": "荣耀神而行", "a": "荣耀神"}, {"type": "fill", "q": "人造的宗教是人自己造神、用人定的规矩以功德与神________；基督信仰是真神主动________，人按圣经认识祂。", "o": "", "s": "宗教与信仰", "a": "交换|启示"}, {"type": "fill", "q": "视频强调：________才能力行；若知道的不是神所启示的，做得再多也不合神的心意。", "o": "", "s": "真知力行", "a": "真知"}, {"type": "fill", "q": "按圣经启示，一个重要的罪就是人明明知道有神，却不把神当________，宁可自己造偶像。", "o": "", "s": "罪的定义", "a": "神"}, {"type": "fill", "q": "主耶稣应许求父赐给我们另一位________，就是真理的圣灵，住在每个基督徒生命里。", "o": "", "s": "保惠师", "a": "保惠师"}, {"type": "fill", "q": "神赐给每个基督徒不同的________，如同身体上不同的肢体，彼此________、互相配搭。", "o": "", "s": "恩赐配搭", "a": "恩赐|配搭"}, {"type": "fill", "q": "按才干受托的比喻中，五千两和两千两的仆人因所赚是________比例，在神面前得着一样的称赞。", "o": "", "s": "按才干受托", "a": "等"}, {"type": "single", "q": "按视频所讲，圣灵充满最重要的意义是？", "o": "A.说方言行神迹,B.全然被圣灵管治，活出符合圣灵带领的生命,C.情绪特别高涨,D.拥有超能力", "s": "圣灵充满", "a": "B"}, {"type": "single", "q": "基督徒使用恩赐的正确态度是？", "o": "A.作个人才华的表演,B.在教会群体中彼此配搭服事，在事奉中生命被改变,C.高举某些恩赐、贬低另一些,D.藏起来不用", "s": "恩赐运用", "a": "B"}, {"type": "single", "q": "视频中“今世得百倍”的“百倍”主要指什么？", "o": "A.金钱物质上的百倍回报,B.生命成熟长大所带出来的丰盛,C.子孙满堂,D.长命百岁", "s": "百倍丰盛", "a": "B"}, {"type": "multiple", "q": "（多选）按视频所讲，圣灵在基督徒生命中的工作包括？", "o": "A.催逼,B.感动安慰,C.禁止鼓励,D.代替我们做决定不用思考", "s": "圣灵工作", "a": "A|B|C"}, {"type": "multiple", "q": "（多选）按视频所讲，基督徒作光作盐的生命包括？", "o": "A.在任何处境为荣耀神而活,B.用生命吸引人来到真神面前,C.只看重神是否提升自己的社会地位,D.不断在圣经真理上下功夫、顺服圣灵感动", "s": "光盐生命", "a": "A|B|D"}, {"type": "judge", "q": "奉献金钱、事奉、宣教可以作为与神交换更多恩典的筹码。", "o": "", "s": "白白恩典", "a": "错"}, {"type": "judge", "q": "真知才能力行，也必须力行，行出来才知道是真知。", "o": "", "s": "知行合一", "a": "对"}, {"type": "judge", "q": "基督徒的价值衡量在别人对我们的评断和称赞。", "o": "", "s": "价值标准", "a": "错"}, {"type": "essay", "q": "视频如何区分“人造的宗教”与“真神启示的信仰”？", "o": "", "s": "宗教与信仰", "a": "人造的宗教是人自己造神，神不会说话没有作为，神人互动由人来定规矩——做功德、积善事与神交换。基督信仰是宇宙间独一创造的真神主动启示：祂是活神，人神互动的方式由祂来定，祂借圣经、借与以色列民族的互动让人明白祂是怎样的神、人是怎样的状况、祂如何救人。"}, {"type": "essay", "q": "按视频所讲，基督徒在教会中运用恩赐、彼此服事的重点是什么？", "o": "", "s": "恩赐与服事", "a": "重点不是做了什么事，不是作个人才华的表演，也不是高举或贬低某种恩赐，而是在事奉过程中生命被改变、成熟长大。神把儿女召聚在教会中，借恩赐彼此配搭、彼此敬重，一面学习尽心爱神、一面学习爱人如己，共同对付老我，活出健康的新生命。"}]','https://youtu.be/Eqh8HNXF5xU
企业微盘|https://drive.weixin.qq.com/s?k=AGIARwdAAF8FEAyJn5#/preview?fileId=i.1970326435022690.1688856912704520_f.773055134zjjr','quiz','[{"title": "启示的信仰与人造宗教的根本区别", "points": ["人所发明的宗教：人自己造神，这个神不会说话、没有作为，神人互动的模式由人来定", "常见的模式是做功德与神交换，但这位神到底是谁，其实人并不清楚", "基督教信仰强调宇宙有一位创造的活神，人与神互动的方式是由祂来启示、由祂来定"]}, {"title": "回到圣经：真知才能力行", "points": ["神透过圣经，借着祂与一个民族之间的互动，让人明白祂是谁、人是什么光景", "真知才能够力行：若所知道的是人自己的想法盼望，做再多也不合神的心意", "真知也必须力行，力行才知道我们真知，要喜乐地遵行、放在蒙福的处境里"]}, {"title": "神的爱与人的需要：恢复神的形象", "points": ["人常误以为爱就是满足我一切需要、改变环境、脱离难处，这是人的定义", "圣经说神在祂的智慧里爱我们：祂知道人真正需要的，是恢复按神形象样式造的荣美特质", "生命不对时，环境纵被改变，人仍落在劳苦愁烦中，家庭破碎、婚姻失信正是明证"]}, {"title": "温习根基：独一真神与人的罪", "points": ["有一位独一的真神：祂是自有永有的，不是人造的，也不是人盼望什么样就什么样", "罪的定义按神的真理而定，不是按世间的法律；重要的一罪是明知有神却不把神当神", "人造偶像当神、心偏离落在老我与罪性中，神任凭人落在这光景里"]}, {"title": "温习根基：十字架的救赎与因信得生", "points": ["人不能自救，将功补过是人自己定的原则；罪要付代价，不是用善事抵消", "神爱我们的方法是治本：神差遣祂的儿子为我们的罪付上代价，打通神人之间被罪拦阻的道路", "因祂受的鞭伤我们得医治，因祂受的刑罚我们得平安；我们带着谦卑感恩的心，用信心领受"]}, {"title": "圣灵的带领与被圣灵管治的生命", "points": ["信主后行为仍不完美，神差遣圣灵住在每位基督徒生命里，做催逼、感动、安慰、禁止、鼓励的圣工", "圣灵充满最重要的意义，是全然被圣灵管治，活出符合圣灵带领要求的人生", "三位一体是神的启示，理性上只要承认神与人本质不同，便可以接受"]}, {"title": "恩赐配搭：在教会中事奉与成长", "points": ["神赐每位基督徒恩赐，恩赐是为配搭在教会群体中彼此服事、生命长大，不是个人才华表演", "恩赐没有大小轻重，没有人有所有恩赐，也没有人一个恩赐都没有，要尊重、欣赏、彼此配搭", "事奉、奉献、宣教都不是与神交换恩典的筹码；恩典是白白领受，事奉的重点是过程中生命被改变成熟"]}, {"title": "活出见证：作光作盐与永恒盼望", "points": ["基督徒的使命是作光作盐：在任何处境中活出有力的生命，吸引人来到独一真神面前", "保罗说判断我的乃是主：我们的价值衡量在神的评断，不在人的论断；按才干受托的比喻提醒我们忠心受托", "基督徒有永恒盼望，在永生确据里活好今生：经历今世得百倍（生命的丰盛）、来世得永生，得着人不能夺去的平安喜乐"]}]','','26','寇绍涵牧师•根基建造101','{"en": {"title": "Lesson 26 Living the Faith", "content": "True knowledge can do it. This lesson summarizes a series of fundamental truths: Live what you believe, testify of Christ in your life, and be the light and the salt of the earth. May these twenty-six lessons be a blessing in your life. He followed the Lord all his life and remained faithful until death.", "instructions": "", "guide": [{"title": "The fundamental difference between apocalyptic faith and artificial religion", "points": ["Religion invented by man: Man created God himself. This God cannot speak or act. The mode of interaction between God and man is determined by man.", "The common pattern is to do merit exchanges with gods, but who exactly is this god, in fact, people are not clear", "The Christian faith emphasizes that there is a living God of creation in the universe, and the way in which man interacts with God is revealed and determined by Him."]}, {"title": "Back to the Bible: True Knowledge Works", "points": ["Through the Bible, through His interactions with a people, God makes it clear who He is and what He is like.", "True knowledge can only be done: if what is known is people''s own thoughts and hopes, no amount of doing is contrary to God''s will", "True knowledge must also be practiced, to know our true knowledge, to be joyfully obeyed, to be placed in a blessed situation"]}, {"title": "God''s Love and Human Needs: Restoring God''s Image", "points": ["People often mistakenly think that love is to meet all my needs, change the environment, and get rid of difficulties. This is the definition of human", "The Bible says that God loves us in His wisdom: He knows that what man really needs is the restoration of the glorious qualities made in the likeness of God.", "When life is wrong, the environment is changed, people still fall into toil and sorrow, family breakdown, marital dishonesty is the proof"]}, {"title": "Review Foundation: The One True God and the Sins of Man", "points": ["There is one true God: He is eternal, not man-made, and not what man desires.", "Sin is defined according to the truth of God, not according to the law of the world; the important sin is knowing that there is God but not treating God as God", "Artificial idols When God, heart deviation falls in the old self and sinful nature, God allows people to fall in this situation"]}, {"title": "Fundamentals of Study: The Redemption of the Cross and Living by Faith", "points": ["People cannot save themselves, and it is a principle set by people themselves to make up for their merits; sin pays the price, not to offset it with good deeds.", "God''s way of loving us is to heal the root cause: God sent His Son to pay the price for our sins and open up the way between God and man that is blocked by sin", "We are healed by His scourge, we are at peace by His chastisement; we receive it in faith, with humility and gratitude."]}, {"title": "Led by the Holy Spirit and Ruled by the Holy Spirit", "points": ["After believing in the Lord, the behavior is still imperfect. God sends the Holy Spirit to live in every Christian''s life, doing the sacred work of urging, moving, comforting, forbidding, and encouraging.", "The Holy Spirit is full of the most important meaning is to be completely governed by the Holy Spirit and live a life that meets the requirements of the Holy Spirit''s leadership.", "The Trinity is a revelation of God, and rationally we can accept it as long as we acknowledge that God is different from human nature."]}, {"title": "Gift Matching: Serving and Growing in the Church", "points": ["God has given every Christian the gift of serving one another and growing up in the church community, not a talent show.", "Gifts are not small or small, no one has all the gifts, and no one has any gifts. Respect, appreciate, and match each other", "Service, devotion, and mission are not chips for exchanging grace with God; grace is a free gift, and the focus of service is that life is changed and matured in the process."]}, {"title": "Living the Witness: Salt of Light and Eternal Hope", "points": ["The Christian''s mission is to be the salt of light: to live a powerful life in any situation that draws people to the one true God.", "Paul said that it is the Lord who judges me: our value is measured in God''s judgment, not in human judgment; according to the parable of the talent entrustment, it reminds us of the faithful entrustment", "Christians have an eternal hope to live this life in the certainty of eternal life: to experience this life a hundred times (the fullness of life), to have eternal life in the next life, to have peace and joy that cannot be taken away by man"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] It''s just that you want ________, don''t just ________, deceive yourself", "s": "Redemption love"}, {"q": "[Scripture Fill in the Blank] Don''t imitate the world, as long as the heart is renewed and changed, let you check what is God''s ________, pure and joyful will.", "s": "Mind update"}, {"q": "[Scripture Fill in the Blank] So, whether you eat or drink, whatever you do, do it for ________", "s": "Walk in the Glory of God"}, {"q": "Man-made religion is man''s own creation of God, using the rules set by man to use merit and God ________; Christianity is the true God''s initiative ________, and man knows Him according to the Bible.", "s": "Religion & Spirituality"}, {"q": "The video emphasizes that only ________ can do it; if you know that it is not inspired by God, it is not God''s will to do more.", "s": "True Wisdom Practice"}, {"q": "According to the biblical revelation, an important sin is that people clearly know that there is a God, but they do not regard God as ________, preferring to make their own idols.", "s": "Definition of Crime"}, {"q": "The Lord Jesus promises to ask the Father to give us another ________, the Spirit of truth, to dwell in every Christian''s life.", "s": "Guarantor"}, {"q": "God gives each Christian a different ________, like different members of the body, to ________ each other, to match each other.", "s": "Gift Matching"}, {"q": "In the parable of the entrusted talents, the servants of five thousand taels and two thousand taels received the same praise before God because their earnings were in proportion to ________.", "s": "Entrusted by ability"}, {"q": "According to the video, what is the most important meaning of the fullness of the Holy Spirit?", "s": "The filling of the Holy Spirit", "o": "A.Speak in tongues and perform miracles,B.Fully ruled by the Holy Spirit and living a life guided by the Holy Spirit,C.Emotions are particularly high,D.Has superpowers"}, {"q": "What is the right attitude for Christians to use gifts?", "s": "Use of Gifts", "o": "A.Show off your talents,B.Matching service to each other in the church community, life is changed in the service,C.Exalt some gifts, demean others,D.Hide it away"}, {"q": "What is the \"100 times\" of \"100 times in this world\" in the video?", "s": "A hundred times more abundant", "o": "A.100x return on money and material goods,B.The abundance brought out by the maturity of life,C.Grandchildren''s Hall,D.live long for a hundred years"}, {"q": "(Multiple choice) According to the video, the work of the Holy Spirit in the Christian life includes?", "s": "Holy Spirit Work", "o": "A.Hustle,B.Touching consolation,C.No Encouragement,D.to make decisions for us without thinking."}, {"q": "(Multiple choice) According to the video, the life of a Christian as a salt of light includes?", "s": "Light Salt Life", "o": "A.Live for the glory of God in any situation,B.Drawing people to the true God with life,C.Only pay attention to whether God improves his social status,D.Constantly working on biblical truths and obeying the Holy Spirit"}, {"q": "Dedication of money, service, and mission can be used as a bargaining chip to exchange more grace with God.", "s": "White Grace"}, {"q": "True knowledge can be practiced, but it must also be practiced, and only when it is practiced can it be known to be true knowledge.", "s": "union of practice and knowledge"}, {"q": "Christian values are measured in what others judge and praise us for.", "s": "Value Criteria"}, {"q": "How does the video distinguish between “man-made religions” and “revealed beliefs of the true God”?", "s": "Religion & Spirituality"}, {"q": "According to the video, what are the priorities for Christians to use their gifts and serve each other in the church?", "s": "Gifts and Service"}]}, "ja": {"title": "レッスン26信仰を生きる", "content": "真の知識はそれを可能にします。この課では，一連の基本的な真理を要約します：信じるものを生き，人生でキリストについて証し，地の光と塩となりましょう。これらの26のレッスンがあなたの人生の祝福となりますように。生涯主に従い，死ぬまで忠実であり続けました。", "instructions": "", "guide": [{"title": "黙示録的な信仰と人工的な宗教の根本的な違い", "points": ["人間によって発明された宗教：人間は神自身を創造しました。この神は話すことも行動することもできません。神と人間の相互作用の様式は人間によって決定されます。", "一般的なパターンは、神々とのメリット交換をすることですが、この神々とは一体誰なのか、実際のところ、人々ははっきりしていません", "キリスト教の信仰は、宇宙には創造の生ける神がいることを強調しており、人間が神とどのように相互作用するかは神によって明らかにされ、決定されています。"]}, {"title": "聖書に戻る：真の知識の働き", "points": ["聖書を通して，民との交流を通して，神はご自分がどのような方であるか，どのような方であるかを明確にされます。", "真の知識を得ることができるのは、人が自分の考えや希望を知っているのであれば、神の御心に反することは何もありません。", "真の知識は，自分の真の知識を知るため，喜んで従うため，祝福された状況に置かれるためにも実践されなければなりません。"]}, {"title": "神の愛と人間の必要：神の像を回復する", "points": ["人々はしばしば、愛は私のすべてのニーズを満たし、環境を変え、困難を取り除くためのものだと誤解しています。これが人間の定義です", "聖書は，神は知恵をもってわたしたちを愛しておられると述べています。人が本当に必要としているのは，神に似せて造られた栄光の特質の回復であることを知っています。", "人生が間違っているとき、環境が変わり、人々はまだ苦労と悲しみに陥り、家族の崩壊、結婚の不誠実さが証拠です"]}, {"title": "財団の復習：唯一の真の神と人の罪", "points": ["唯一の真の神がいます。彼は永遠であり、人が造ったものではなく、人が望むものではありません。", "罪は世界の法則ではなく、神の真理に従って定義されます。重要な罪は、神がいることを知っていても、神を神として扱わないことです。", "人工的な偶像神が、心の逸脱が古い自己と罪深い性質に落ちるとき、神は人々がこの状況に落ちることを許します"]}, {"title": "学習の基礎：十字架の贖いと信仰によって生きる", "points": ["人々は自分自身を救うことはできません。人は自分の功績を補うために自分自身で設定した原則です。善行でそれを相殺するのではなく、罪が代償を払います。", "私たちを愛する神の方法は、根本的な原因を癒すことです：神は私たちの罪の代償を払うために御子を遣わし、罪によって妨げられている神と人との間の道を開きます", "わたしたちは主の鞭によって癒され，主の懲らしめによって平安に包まれています。わたしたちは信仰と謙遜と感謝をもってそれを受けます。"]}, {"title": "聖霊に導かれ、聖霊に支配される", "points": ["主を信じた後、行動はまだ不完全です。神はすべてのクリスチャンの人生に生きるために聖霊を送り、促し、動かし、慰め、禁止し、励ますという神聖な働きをします。", "聖霊は、聖霊に完全に支配され、聖霊の指導の要件を満たす人生を送ることが最も重要な意味に満ちています。", "三位一体は神の啓示であり、神が人間の本性とは異なることを認める限り、合理的に受け入れることができます。"]}, {"title": "ギフトマッチング：教会での奉仕と成長", "points": ["神はすべてのクリスチャンに，タレントショーではなく，お互いに仕え合い，教会のコミュニティで育つという贈り物を与えてくださいました。", "贈り物は小さくも小さくもなく、誰もすべての贈り物を持っておらず、誰も贈り物を持っていません。お互いを尊重し、感謝し、一致させます", "奉仕、献身、使命は神と恵みを交換するための欠片ではありません。恵みは無料の贈り物であり、奉仕の焦点は、その過程で人生が変化し、成熟することです。"]}, {"title": "証人として生きる：光の塩と永遠の希望", "points": ["クリスチャンの使命は、光の塩となること、すなわち、人々を唯一の真の神に引き寄せるあらゆる状況で力強い人生を送ることです。", "パウロは、私を裁くのは主であると言いました。私たちの価値は人間の裁きではなく、神の裁きによって測られます。才能の託されたたとえ話によれば、それは忠実な託されたことを思い出させます", "クリスチャンは、永遠の命の確実性の中でこの命を生きるという永遠の希望を持っています：この命を百回（命の完全さ）経験すること、来世で永遠の命を持つこと、人が奪うことのできない平和と喜びを持つこと"]}], "quizzes": [{"q": "〔聖句の穴埋め〕ただ________が欲しいだけで、________だけでなく、自分自身を欺いてはいけません", "s": "救いの愛"}, {"q": "〔聖句の穴埋め〕世界を模倣してはいけません。心が新しくなり、変化している限り、神の________、純粋で喜びに満ちた意志が何であるかを確認しましょう。", "s": "マインドアップデート"}, {"q": "〔聖句の穴埋め〕ですから、食べるにしても飲むにしても、何をするにしても、________のためにしてください", "s": "神の栄光の中を歩む"}, {"q": "人間が作った宗教は、人間が定めた規則を使って功績と神________を用いる人間自身の神の創造物であり、キリスト教は真の神のイニシアチブ________であり、人間は聖書に従って神を知っています。", "s": "宗教と信仰"}, {"q": "ビデオは， ________だけがそれを行うことができることを強調しています。もしそれが神に触発されていないことを知っていれば，それ以上のことをすることは神の御心ではありません。", "s": "真の知恵の実践"}, {"q": "聖書の啓示によると、重要な罪は、人々が神が存在することをはっきりと知っているが、神を________と見なさず、自分自身の偶像を作ることを好むことです。", "s": "犯罪の定義"}, {"q": "主イエスは，わたしたちにもう一つの________ ，すなわち真理の御霊を与えて，すべてのクリスチャンの生活の中に住まわせてくださるよう，御父に願うと約束されています。", "s": "保証人"}, {"q": "神は，各クリスチャンに，身体のさまざまな肢体のように，互いに一致させるために異なる________を与えておられます。", "s": "ギフトマッチング"}, {"q": "託されたタラントのたとえ話では、五千二千のタラントの召使いたちは、収入が________に比例していたため、神の前で同じ称賛を受けました。", "s": "能力によって委託されている"}, {"q": "ビデオによると，聖霊の完全さの最も重要な意味は何ですか。", "s": "聖霊に満たされている", "o": "A.異言を話し，奇跡を起こす,B.聖霊に完全に支配され、聖霊に導かれた生活を送る,C.特に感情が高い,D.スーパーパワーを持っている"}, {"q": "クリスチャンが贈り物を使うための正しい態度は何ですか。", "s": "贈答品の使用", "o": "A.自分の才能を見せびらかす,B.教会コミュニティでお互いにマッチングサービスを行い、サービスで人生が変わります,C.いくつかの贈り物を高く評価し、他の贈り物を侮辱する,D.隠す"}, {"q": "動画の「この世界で100回」の「100回」は何ですか？", "s": "100倍豊富", "o": "A.お金と物質的な商品の100倍のリターン,B.人生の成熟によってもたらされる豊かさ,C.Grandchildren''s Hall,D.長寿命、100歳"}, {"q": "（複数選択可）ビデオによると，クリスチャン生活における聖霊の働きには，", "s": "聖霊の働き", "o": "A.ハッスル,B.感動の慰め,C.励ましなし,D.何も考えずに私たちのために決定を下すことができます。"}, {"q": "（複数選択可）ビデオによると、光の塩としてのクリスチャンの人生には？", "s": "ライトソルトライフ", "o": "A.どんな状況でも神の栄光のために生きる,B.命をもって人々を真の神に引き寄せる,C.神が社会的地位を向上させるかどうかだけに注意を払う,D.聖書の真理に絶えず取り組み，聖霊に従う"}, {"q": "金銭，奉仕，使命の献身は，神とより多くの恵みを交換するための交渉の切り札として使うことができます。", "s": "ホワイトグレース"}, {"q": "真の知識は実践することができますが、実践する必要もあり、実践されて初めて真の知識であることがわかります。", "s": "知識と実践の一体性"}, {"q": "キリスト教の価値観は、他の人が私たちを評価し、賛美するもので測定されます。", "s": "価値基準"}, {"q": "ビデオでは，「人が造った宗教」と「真の神の啓示された信仰」をどのように区別していますか。", "s": "宗教と信仰"}, {"q": "ビデオによると，クリスチャンが自分の賜物を使い，教会でお互いに奉仕するための優先事項は何ですか。", "s": "贈答品とサービス"}]}, "ko": {"title": "제 26과 신앙 생활", "content": "진정한 지식이 그것을 할 수 있습니다. 이 과는 다음과 같은 일련의 기본 진리들을 요약한다. 믿는 대로 살고, 삶에서 그리스도를 증거하며, 땅의 빛과 소금이 되라. 이 26가지 교훈이 여러분의 삶에 축복이 되기를 바랍니다. 그는 평생 주님을 따랐고 죽을 때까지 충실했습니다.", "instructions": "", "guide": [{"title": "종말론적 신앙과 인위적 종교의 근본적 차이", "points": ["인간에 의해 발명된 종교: 인간이 직접 신을 창조했다. 이 신은 말하거나 행동할 수 없다. 신과 인간 사이의 상호 작용 방식은 인간에 의해 결정된다.", "일반적인 패턴은 신과 공적을 교환하는 것입니다. 하지만 정확히이 신은 누구입니까? 사실, 사람들은 명확하지 않습니다.", "그리스도교 신앙은 우주에 창조의 살아 계신 하나님이 계시며, 인간이 하나님과 상호 작용하는 방식이 그분에 의해 계시되고 결정된다는 것을 강조합니다."]}, {"title": "성경으로 돌아가기: 참된 지식은 역사한다", "points": ["성경을 통해, 한 백성과의 상호 작용을 통해 하나님은 자신이 누구이며 어떤 분이신지 분명히 밝히십니다.", "진정한 지식은 오직 할 수 있습니다: 알려진 것이 사람들 자신의 생각과 희망이라면, 어떤 행동도 하나님의 뜻에 위배되지 않습니다.", "참된 지식은 또한 실천되어야 하며, 우리의 참된 지식을 알고, 기쁘게 순종하고, 축복받은 상황에 놓여야 합니다."]}, {"title": "하나님의 사랑과 인간의 필요: 하나님의 형상 회복", "points": ["사람들은 종종 사랑이 나의 모든 필요를 충족시키고, 환경을 변화시키고, 어려움을 없애기 위한 것이라고 착각합니다. 이것이 인간의 정의입니다.", "성경은 하나님께서 그분의 지혜로 우리를 사랑하신다고 말합니다. 그분은 인간이 진정으로 필요로 하는 것은 하나님의 모습으로 만들어진 영광스러운 자질의 회복이라는 것을 알고 계십니다.", "인생이 잘못되었을 때, 환경이 바뀌고, 사람들은 여전히 수고와 슬픔에 빠지고, 가족이 파탄나고, 결혼 생활이 부정직하다는 것이 그 증거입니다."]}, {"title": "리뷰 재단: 유일하신 참 하나님과 인간의 죄", "points": ["참 하느님은 한 분뿐이십니다. 그분은 영원하시며 인간이 만든 것이 아니며 인간이 원하는 것이 아닙니다.", "죄는 세상의 법에 따라 정의되지 않고 하나님의 진리에 따라 정의됩니다. 중요한 죄는 하나님이 계시다는 것을 알고 있지만 하나님을 하나님으로 대하지 않는 것입니다.", "인위적인 우상 하느님, 마음의 편차가 낡은 자아와 죄 많은 본성에 떨어질 때, 하느님께서는 사람들이 이 상황에서 넘어지도록 허락하십니다."]}, {"title": "연구의 기초: 십자가의 구속과 믿음으로 살기", "points": ["사람들은 스스로를 구원할 수 없으며, 그것은 사람들이 자신의 공로를 만회하기 위해 스스로 설정한 원칙입니다. 죄는 선행으로 그것을 상쇄하기 위해서가 아니라 대가를 지불합니다.", "우리를 사랑하시는 하나님의 방법은 근본 원인을 치유하는 것입니다. 하나님은 우리 죄의 대가를 치르고 죄로 막힌 하나님과 인간 사이의 길을 열어주기 위해 당신의 아들을 보내셨습니다.", "우리는 그분의 징벌로 치유를 받고, 그분의 징벌로 평화를 누리고, 겸손과 감사로 신앙으로 그것을 받습니다."]}, {"title": "성령의 인도하심과 성령의 통치하심", "points": ["주님을 믿은 후에도 그 행동은 여전히 불완전합니다. 하나님께서는 모든 그리스도인의 삶에서 성령을 보내시어 촉구하고, 움직이고, 위로하고, 금하고, 격려하는 거룩한 일을 하십니다.", "성령은 성령의 통치를 완전히 받고 성령의 지도력의 요구 사항을 충족시키는 삶을 사는 것이 가장 중요한 의미로 가득 차 있습니다.", "삼위일체는 하나님에 대한 계시이며, 이성적으로 우리는 하나님이 인간 본성과 다르다는 것을 인정하는 한 그것을 받아들일 수 있습니다."]}, {"title": "은사 매칭: 교회에서 봉사하고 성장하기", "points": ["하나님께서는 재능 있는 쇼가 아니라 교회 공동체에서 서로 섬기고 성장할 수 있는 은사를 모든 그리스도인에게 주셨습니다.", "선물은 작거나 작지 않으며, 아무도 모든 선물을 가지고 있지 않으며, 아무도 선물을 가지고 있지 않습니다. 서로를 존중하고, 감사하고, 일치시킵니다.", "봉사, 헌신, 선교는 하나님과 은혜를 교환하는 칩이 아닙니다. 은혜는 공짜 선물이며, 봉사의 초점은 그 과정에서 삶이 변화되고 성숙해지는 것입니다."]}, {"title": "증인 생활: 빛의 소금과 영원한 희망", "points": ["그리스도인의 사명은 빛의 소금이 되는 것입니다. 사람들을 유일한 참 하느님께로 이끄는 모든 상황에서 강력한 삶을 사는 것입니다.", "바울은 나를 심판하시는 분은 주님이시라고 말했습니다. 우리의 가치는 인간의 판단이 아니라 하나님의 판단으로 측정됩니다. 달란트 맡김의 비유에 따르면, 그것은 신실한 맡김을 상기시킵니다.", "그리스도인들은 영생의 확신 안에서 이 삶을 살 수 있는 영원한 소망을 가지고 있습니다: 이 삶을 백 번 경험하는 것 (생명의 충만함), 다음 생에서 영생을 누리는 것, 사람이 빼앗을 수 없는 평화와 기쁨을 누리는 것."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 그저 ________ 을 (를) 원하는 것뿐입니다. ________ 만을 (를) 속이지 말고 자신을 속이세요.", "s": "구속 사랑"}, {"q": "[Scripture Fill in the Blank] 세상을 본받지 마십시오. 마음이 새롭게 되고 변화되는 한, 하나님의 ________, 순수하고 즐거운 뜻이 무엇인지 점검하십시오.", "s": "마인드 업데이트"}, {"q": "[Scripture Fill in the Blank] 따라서 먹든 마시든, 무엇을 하든 ________ 을 (를) 위해 하십시오.", "s": "하나님의 영광 속을 걸으십시오"}, {"q": "인간이 만든 종교는 공로와 신 ________ 을 사용하기 위해 인간이 정한 규칙을 사용하여 인간이 신을 창조 한 것입니다. 기독교는 진정한 하나님의 주도권 ________ 이며, 인간은 성경에 따라 그분을 알고 있습니다.", "s": "종교와 신앙"}, {"q": "이 동영상은 오직 ________ 만이 그것을 할 수 있음을 강조합니다. 그것이 하나님의 영감을 받지 못했다는 것을 안다면, 더 많은 일을 하는 것은 하나님의 뜻이 아닙니다.", "s": "진정한 지혜의 수련"}, {"q": "성경의 계시에 따르면 중요한 죄는 사람들이 하나님이 계시다는 것을 분명히 알고 있지만 하나님을 ________ 로 여기지 않고 자신의 우상을 만드는 것을 선호한다는 것입니다.", "s": "범죄의 정의"}, {"q": "주 예수께서는 모든 그리스도인의 삶에 거하도록 진리의 영인 또 다른 ________ 을 주시도록 아버지께 간구하겠다고 약속하십니다.", "s": "보증인"}, {"q": "하나님께서는 각 그리스도인에게 몸의 다른 지체와 같은 다른 ________ 을 (를) 서로 ________ 하여 서로 일치하게 하십니다.", "s": "선물 매칭"}, {"q": "맡겨진 달란트의 비유에서 오천 달란트와 이천 달란트의 종들은 수입이 ________ 에 비례하기 때문에 하나님 앞에서 같은 칭찬을 받았습니다.", "s": "능력에 의해 위탁됨"}, {"q": "동영상에 따르면, 성령 충만의 가장 중요한 의미는 무엇인가?", "s": "성령으로 충만함", "o": "A.방언을 말하고 기적을 행함,B.성령의 온전한 통치와 성령의 인도를 받는 삶,C.감정이 특히 높음,D.초능력 보유"}, {"q": "그리스도인들이 은사를 사용하는 올바른 태도는 무엇인가?", "s": "선물 사용", "o": "A.자신의 재능을 뽐내세요,B.교회 공동체에서 서로 섬김을 일치시키면 섬김 속에서 삶이 변화됩니다.,C.일부 은사를 높이고, 다른 사람들을 비하하십시오,D.숨기기"}, {"q": "영상 속 ''이 세상 100회'' 의 ''100회'' 는 무엇일까요?", "s": "백 배 더 풍부함", "o": "A.돈과 물질적 상품에 대한 100배의 수익률,B.생명의 성숙이 가져다주는 풍요로움,C.손자회관,D.긴 수명, 100세"}, {"q": "(복수 선택) 동영상에 따르면, 그리스도인의 삶에서 성령의 역사는 다음과 같습니다.", "s": "성령 역사", "o": "A.허슬,B.감동적인 위로,C.격려 없음,D.생각 없이 우리를 위해 결정을 내릴 수 있습니다."}, {"q": "(복수 선택) 동영상에 따르면, 빛의 소금으로서의 그리스도인의 삶에는 무엇이 포함됩니까?", "s": "라이트 솔트 라이프", "o": "A.어떤 상황에서도 하나님의 영광을 위해 살기,B.생명으로 사람들을 참 하느님께로 이끄는 것,C.하나님께서 그의 사회적 지위를 향상시키시는지에 대해서만 주의를 기울이십시오.,D.성경의 진리에 대해 끊임없이 노력하고 성령님께 순종함"}, {"q": "돈, 봉사, 선교 사업에 대한 헌신은 하나님과 더 많은 은혜를 교환하기 위한 교섭의 장으로 사용될 수 있다.", "s": "화이트 그레이스"}, {"q": "참된 지식은 실천할 수 있지만 실천해야 하며, 실천할 때만이 참된 지식임을 알 수 있다.", "s": "지식과 실천의 일치"}, {"q": "그리스도인의 가치는 다른 사람들이 우리를 판단하고 칭찬하는 것으로 측정됩니다.", "s": "가치 기준"}, {"q": "이 동영상은 “인간이 만든 종교” 와 “참 하나님에 대한 계시된 믿음” 을 어떻게 구별하는가?", "s": "종교와 신앙"}, {"q": "동영상에 따르면, 그리스도인들이 은사를 사용하고 교회에서 서로를 섬기는 우선순위는 무엇인가?", "s": "선물 및 봉사"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791216457736','基要真理','回顾一·认识真神篇','本套复习聚焦神论主题：人为何需要神、神是谁、耶稣的身份、圣灵的工作、三位一体的奥秘，以及圣经为何是最高权威。愿你更深认识这位又真又活的神，立定信仰的根基。','[{"type": "verse", "q": "【经文填空】自从造天地以来，神的永能和________是明明可知的，虽是眼不能见，但藉着所造之物就可以晓得，叫人________", "o": "《罗马书》1章20节", "s": "创造显明神", "a": "神性|无可推诿"}, {"type": "verse", "q": "【经文填空】神是个________，所以拜他的必须用________和诚实拜他", "o": "《约翰福音》4章24节", "s": "神是灵", "a": "灵|心灵"}, {"type": "verse", "q": "【经文填空】道成了________，住在我们中间，充充满满地有恩典有________", "o": "《约翰福音》1章14节", "s": "道成肉身", "a": "肉身|真理"}, {"type": "verse", "q": "【经文填空】我要求父，父就另外赐给你们一位________，就是真理的________，叫祂永远与你们同在", "o": "《约翰福音》14章16节", "s": "保惠师的应许", "a": "保惠师|圣灵"}, {"type": "verse", "q": "【经文填空】耶稣说：________原为一。", "o": "《约翰福音》10章30节", "s": "父子为一", "a": "我与父"}, {"type": "verse", "q": "【经文填空】圣经都是________所默示的，于教训、督责、使人归正、教导人学义都是有益的，叫属神的人得以完全，预备行各样的善事。", "o": "《提摩太后书》3章16节", "s": "圣经默示", "a": "神"}, {"type": "fill", "q": "正如精美的椅子必有制造它的人，规律精密的宇宙必有一位________", "o": "", "s": "宇宙的创造者", "a": "创造者"}, {"type": "fill", "q": "神是灵，不像人有身体，所以祂不受时间和________的限制", "o": "", "s": "超越时空", "a": "空间"}, {"type": "fill", "q": "证明耶稣是「神来做人」最有力、可被公开检验的证据是祂的________", "o": "", "s": "复活的证据", "a": "死里复活"}, {"type": "fill", "q": "耶稣的十一个门徒除老约翰外，都为见证复活付上了________的代价", "o": "", "s": "门徒的见证", "a": "殉道"}, {"type": "fill", "q": "圣经与一般宗教经典的本质区别在于________：是独一真神启示，还是人写的。", "o": "", "s": "圣经来源", "a": "来源"}, {"type": "single", "q": "基督教信仰和人造宗教最根本的区别是什么？", "o": "A.基督教的历史更悠久,B.基督教是神启示的真理，不是人造的宗教,C.基督教的仪式更庄重,D.基督教的信徒人数更多", "s": "启示与人造", "a": "B"}, {"type": "single", "q": "神用「父」来向人启示自己，最主要是要让人明白什么？", "o": "A.神的性情很温和,B.神是真理的源头，保护并带领人,C.神喜欢小孩子,D.神和人有血缘关系", "s": "神为父", "a": "B"}, {"type": "single", "q": "为什么「门徒偷走尸体、编造复活」的说法站不住脚？", "o": "A.门徒当时四散惊恐，不敢接近坟墓,B.门徒力气太小搬不动巨石,C.耶稣的尸体太重,D.坟墓离城太远", "s": "空坟的事实", "a": "A"}, {"type": "single", "q": "圣灵在信徒生命中的主要工作是什么？", "o": "A.包办信徒的一切事务,B.感动、催逼、带领信徒生命更新,C.让人一夜暴富,D.代替信徒做所有决定", "s": "圣灵的工作", "a": "B"}, {"type": "single", "q": "为什么不能用水有固态、液态、气态来解释三位一体？", "o": "A.水没有本质,B.水的三态不能同时存在,C.水太少,D.圣经禁止比喻", "s": "三一比喻", "a": "B"}, {"type": "multiple", "q": "耶稣与「被神化的人」有什么不同？（多选）", "o": "A.由童贞女从圣灵感孕而生,B.死里复活，空坟可被公开检验,C.活出无罪的生命,D.只是道德特别高尚的人", "s": "耶稣的独特性", "a": "A|B|C"}, {"type": "multiple", "q": "以下哪些是圣灵的果子？（多选）", "o": "A.仁爱,B.喜乐,C.嫉妒纷争,D.节制", "s": "圣灵的果子", "a": "A|B|D"}, {"type": "multiple", "q": "视频提出的圣经权威证据包括哪些？（多选）", "o": "A.超越文化的记载,B.准确的预言,C.历代圣徒的见证,D.作者都是同一时代", "s": "权威证据", "a": "A|B|C"}, {"type": "judge", "q": "神是灵，所以祂和人一样，一次只能出现在一个地方。", "o": "", "s": "神的属性", "a": "错"}, {"type": "judge", "q": "基督教信仰是否成立，关键在于耶稣有没有从死里复活。", "o": "", "s": "复活的关键", "a": "对"}, {"type": "judge", "q": "圣灵只是人的一种心理感受，不是真神的一位。", "o": "", "s": "圣灵的位格", "a": "错"}, {"type": "judge", "q": "圣经里有「三位一体」这个词，所以这是圣经的原话。", "o": "", "s": "三一的用词", "a": "错"}, {"type": "essay", "q": "人造宗教的神和圣经启示的真神有什么根本区别？请从人神关系的角度说明。", "o": "", "s": "人造神vs真神", "a": "人造宗教的神是人造出来的，人神互动的规则由人来定：人用「灵不灵」作标准，所求的成就了就继续拜，不灵就换一个，把神当成解决问题的工具。圣经启示的真神则完全相反：祂是创造宇宙、自有永有的那一位，智慧能力都比人高，人神互动的方式由祂来启示、由祂来定。人不能召之即来、挥之即去，而是要谦卑听祂、顺服祂，与祂建立真实的互动关系。"}, {"type": "essay", "q": "三位一体真神中，圣子与圣灵各有什么独特的工作？这对基督徒的信仰生活有什么意义？", "o": "", "s": "圣子圣灵的工作", "a": "圣子道成肉身，活出无罪的生命，在十字架上为人的罪付上代价，又从死里复活，成为神与人之间唯一的道路；圣灵是保惠师，内住在每个信徒生命里，感动、催逼、安慰、管教，带领信徒脱下旧人、穿上新人，结出圣灵的果子。这显明三一真神同心同工：圣父计划、圣子成就、圣灵施行。基督徒因此确信救恩稳固，又有圣灵天天同在带领，可以放心地活出信仰。"}]','','quiz','[]','','27','寇绍涵牧师•根基建造101','{"en": {"title": "Review 1 · Knowing the True God Chapter", "content": "This review focuses on the theological themes of why people need God, who God is, Jesus'' identity, the work of the Holy Spirit, the mysteries of the Trinity, and why the Bible is the supreme authority. May you know this true and living God better and lay the foundation of your faith.", "instructions": "", "guide": [], "quizzes": [{"q": "[Scripture Fill in the Blank] Since the creation of the heavens and the earth, God''s eternal power and ________ have been clearly known. Although they are invisible to the eyes, they can be known through the created things.", "s": "Creation reveals God"}, {"q": "[Scripture Fill in the Blank] God is a ________, so we must worship Him with ________ and honesty", "s": "God is Spirit"}, {"q": "[Scripture Fill in the Blank] The Word became ________, lived among us, full of grace and ________", "s": "Dao Incarnation Body"}, {"q": "[Scripture Fill in the Blank] I ask the Father, and He will give you another ________, the ________ of truth, that He may be with you forever.", "s": "The Marshal''s Promise"}, {"q": "[Scripture Fill in the Blank] Jesus said: ________ Originally one.", "s": "Father and son are one"}, {"q": "[Scripture Fill in the Blank] The Bible is inspired by ________, which is beneficial for teaching, condemning, converting, and teaching people to learn righteousness, so that those who belong to God can be perfected and prepared to do all kinds of good deeds.", "s": "Biblical inspiration"}, {"q": "Just as a beautiful chair must have a person who makes it, a regular universe must have a ________", "s": "Creator of the Universe"}, {"q": "God is spirit, unlike man who has a body, so He is not limited by time and ________", "s": "Beyond time and space"}, {"q": "The most powerful, publicly testable proof that Jesus is “God came to be man” is His ________", "s": "Evidence of the Resurrection"}, {"q": "The eleven disciples of Jesus, with the exception of John the Elder, all paid the price of ________ for witnessing the resurrection.", "s": "The Testimony of the Disciples"}, {"q": "The essential difference between the Bible and the general religious scriptures is ________: is it the revelation of the one true God, or is it written by man?", "s": "Biblical sources"}, {"q": "What is the fundamental difference between Christian faith and artificial religion?", "s": "Revelation and Artificiality", "o": "A.Christianity has a longer history,B.Christianity is a divinely revealed truth, not a man-made religion,C.Christian rituals are more solemn,D.Greater number of believers in Christianity"}, {"q": "What is the primary purpose of God''s use of the Father to reveal Himself to others?", "s": "God as Father", "o": "A.God''s disposition is very gentle,B.God is the source of truth, protecting and leading.,C.God loves children,D.God and man are related by blood"}, {"q": "Why is the claim that the disciples stole the body and invented the resurrection untenable?", "s": "Empty Cemetery Facts", "o": "A.The disciples were scared and did not dare to approach the tomb.,B.The disciple''s strength is too small to move the boulder,C.Jesus'' body was too heavy,D.The tomb is too far from the city"}, {"q": "What is the main work of the Holy Ghost in the lives of believers?", "s": "The Work of the Holy Spirit", "o": "A.Arranging all the affairs of the believer,B.Touch, urge, and lead believers in life renewal,C.Making people rich overnight,D.Make all the decisions for the believer"}, {"q": "Why can''t the Trinity be explained by the solid, liquid, and gaseous state of water?", "s": "Trinity Parable", "o": "A.Water has no essence,B.The three states of water cannot exist at the same time,C.it means that the sponge has little water<g id=\"1\">.</g>,D.The Bible forbids parables"}, {"q": "How is Jesus different from a “deified person”? (Multiple choice)", "s": "The uniqueness of Jesus", "o": "A.Born of a virgin inspired by the Holy Spirit,B.Resurrected from the dead, empty graves can be publicly examined,C.Live a sinless life,D.Just someone who is extraordinarily moral."}, {"q": "Which of the following is the fruit of the Holy Spirit? (Multiple choice)", "s": "<bpt i=\"1\" type=\"bold\">{}</bpt>The Fruit of the Spirit<ept i=\"1\">{}</ept>", "o": "A.Nhon Ai,B.joy,C.Jealousy and strife,D.Temperance"}, {"q": "What is the authoritative biblical evidence presented in the video? (Multiple choice)", "s": "Authoritative Evidence", "o": "A.A transcendent cultural record,B.Accurate predictions,C.The Testimony of the Saints,D.The authors are all from the same era"}, {"q": "God is spirit, so he, like man, can only be in one place at a time.", "s": "Attributes of God"}, {"q": "The key to the validity of the Christian faith is the resurrection of Jesus from the dead.", "s": "The Key to Resurrection"}, {"q": "The Holy Spirit is only a psychological feeling of man, not one of the true gods.", "s": "Person of the Holy Spirit"}, {"q": "The word “Trinity” is found in the Bible, so this is the original word of the Bible.", "s": "Terminology of Trinity"}, {"q": "What is the fundamental difference between the God of man-made religion and the true God of biblical revelation? Please explain from the perspective of the relationship between man and God.", "s": "Artificial God vs True God"}, {"q": "What is the unique work of the Son and the Holy Spirit in the Trinity? What does this mean for the Christian faith life?", "s": "The work of the Son and the Holy Spirit"}]}, "ja": {"title": "レビュー1・真の神を知る章", "content": "この復習では、なぜ人々が神を必要とするのか、神は誰であるのか、イエスの身分、聖霊の働き、三位一体の神秘、そしてなぜ聖書が至高の権威であるのかという神学的テーマに焦点を当てます。あなたがこの真の生ける神をよりよく知り，信仰の基礎を築くことができますように。", "instructions": "", "guide": [], "quizzes": [{"q": "〔聖句の穴埋め〕天地創造以来、神の永遠の力と________がはっきりと知られており、目には見えませんが、被造物を通して知ることができます。", "s": "創造は神を明らかにする"}, {"q": "〔聖句の穴埋め〕神は________なので、私たちは________と誠実さをもって神を礼拝しなければなりません", "s": "神は霊です"}, {"q": "〔聖句の穴埋め〕御言葉は________となり，わたしたちの間に住み，恵みと________に満ちていました。", "s": "道の化身の体"}, {"q": "〔聖句の穴埋め〕わたしが父に願うと，父はもう一つの________ ，すなわち真理の________をあなたに与え，永遠にあなたと共におられるようにしてくださいます。", "s": "元帥の約束"}, {"q": "〔聖句の穴埋め〕イエスは言いました： ________もともとは1つでした。", "s": "父と息子は一つです"}, {"q": "〔聖句の穴埋め〕聖書は________に触発されています。________は，神に属する人々が完全にされ，あらゆる種類の善行をする準備ができるように，義を学ぶように人々を教え，非難し，改心させ，教えるのに有益です。", "s": "聖書の霊感"}, {"q": "美しい椅子にはそれを作る人がいなければならないように、普通の宇宙には________", "s": "宇宙の創造主"}, {"q": "神は霊であり、肉体を持つ人とは異なり、時間と________に制限されません。", "s": "時間と空間を超えて"}, {"q": "イエスが「神が人となられた」ことを証明する最も強力で、公的に検証可能な証拠は、イエスの________です。", "s": "復活の証拠"}, {"q": "イエスの11人の弟子たちは，長老ヨハネを除いて，復活を目撃するために________の代価を払いました。", "s": "弟子たちの証"}, {"q": "聖書と一般的な宗教的経典の本質的な違いは________です：それは唯一の真の神の啓示ですか、それとも人間によって書かれたものですか？", "s": "聖書の情報源"}, {"q": "キリスト教信仰と人工宗教の根本的な違いは何ですか？", "s": "啓示と人工知能", "o": "A.キリスト教には長い歴史があります,B.キリスト教は神から啓示された真理であり、人工的な宗教ではありません,C.キリスト教の儀式はより厳粛です,D.キリスト教の信者数の増加"}, {"q": "神が御自分を他の人に明らかにするために御父を用いる主な目的は何ですか。", "s": "父としての神", "o": "A.神の性質は非常に穏やかです,B.神は真理の源であり，守り，導かれます。,C.神は子供を愛しておられる,D.神と人は血によって結ばれている"}, {"q": "弟子たちが死体を盗み，復活を発明したという主張は，なぜ成立しないのでしょうか。", "s": "空の墓地の事実", "o": "A.弟子たちは怯え、墓に近づく勇気がありませんでした。,B.弟子の力が小さすぎて石を動かすことができません,C.イエスの体は重すぎた,D.墓は街から遠すぎます"}, {"q": "信者の生活における聖霊の主な業は何ですか。", "s": "聖霊の働き", "o": "A.信者のすべての事柄を整理する,B.人生のリニューアルで信者に触れ、促し、導く,C.一夜にして人々を豊かにする,D.信者のためにすべての決定を下す"}, {"q": "水の固体、液体、気体の状態で三位一体を説明できないのはなぜですか？", "s": "トリニティのたとえ話", "o": "A.水には本質がない,B.水の3つの状態は同時に存在することはできません,C.水分が少なすぎる,D.聖書はたとえ話を禁じている"}, {"q": "イエスは「神格化された人」とどのように違うのでしょうか。（複数選択可）", "s": "イエスの独自性", "o": "A.聖霊に触発された処女から生まれた,B.死者の中から復活した、空の墓は公的に調べることができます,C.罪のない人生を送る,D.非常に道徳的な人物だ。"}, {"q": "次のうち，聖霊の実であるのはどれですか。（複数選択可）", "s": "聖霊の実", "o": "A.ノンアイ,B.喜び,C.嫉妬と争い,D.テンペランス"}, {"q": "ビデオに示されている権威ある聖書の証拠は何ですか。（複数選択可）", "s": "権威ある証拠", "o": "A.卓越した文化的記録,B.正確な予測,C.聖徒の証,D.著者はすべて同じ時代の出身です"}, {"q": "神は霊なので、人間と同じように、一度に一つの場所にしかいられません。", "s": "神の属性"}, {"q": "キリスト教信仰の有効性の鍵は，イエスが死者の中から復活することです。", "s": "復活への鍵"}, {"q": "聖霊は人間の心理的な感覚にすぎず、真の神の一人ではありません。", "s": "聖霊の人"}, {"q": "「三位一体」という言葉は聖書にありますので、これが聖書の原語です。", "s": "トリニティの用語"}, {"q": "人が造った宗教の神と聖書の啓示の真の神との根本的な違いは何ですか？人と神の関係の観点から説明してください。", "s": "人工神対真の神"}, {"q": "三位一体における御子と聖霊の独自の働きとは何でしょうか。これは，キリスト教の信仰生活にとってどのような意味がありますか。", "s": "御子と聖霊の働き"}]}, "ko": {"title": "복습 1 · 참 하나님을 아는 것 장", "content": "이 리뷰는 왜 사람들이 하나님을 필요로 하는지, 하나님이 누구인지, 예수님의 정체성, 성령의 역사, 삼위일체의 신비, 그리고 왜 성경이 최고 권위자인지에 대한 신학적 주제에 중점을 둡니다. 이 참되고 살아 계신 하나님을 더 잘 알고 신앙의 기초를 놓을 수 있기를 바랍니다.", "instructions": "", "guide": [], "quizzes": [{"q": "[Scripture Fill in the Blank] 하늘과 땅이 창조된 이래 하나님의 영원한 능력과 ________ 은 (는) 눈에 보이지 않지만 피조물을 통해 알 수 있습니다.", "s": "피조물이 하나님을 드러냄"}, {"q": "[Scripture Fill in the Blank] 하나님은 ________ 이시므로, 우리는 ____________________________________________________", "s": "하나님은 영이시다"}, {"q": "[Scripture Fill in the Blank] 말씀은 ________ 이 (가) 되었고, 우리 가운데 살았으며, 은총과 ________ 이 (가) 가득했습니다.", "s": "DAO 화신 몸"}, {"q": "[Scripture Fill in the Blank] 아버지께 구하노니 또 다른 ________, 곧 진리의 ________ 을 주사 영원토록 너희와 함께 있게 하시리니", "s": "원수의 약속"}, {"q": "[Scripture Fill in the Blank] 예수님은 이렇게 말씀하셨습니다. ________ 원래는 하나였습니다.", "s": "아버지와 아들은 하나이다"}, {"q": "[Scripture Fill in the Blank] 성경은 사람들에게 의를 가르치고, 정죄하고, 개종하고, 가르치는 데 유익한 ________ 에서 영감을 얻어 하나님께 속한 사람들이 모든 종류의 선행을 행할 수 있도록 완성되고 준비될 수 있도록 합니다.", "s": "성경적 영감"}, {"q": "아름다운 의자에는 그것을 만드는 사람이 있어야 하듯이, 정규 우주에는 ________", "s": "우주의 창조자"}, {"q": "하나님은 육신을 가진 인간과 달리 영이시므로 시간에 구애받지 않으시고 ________", "s": "시간과 공간을 초월한 공간"}, {"q": "예수님이 “하나님이 인간으로 오셨다” 는 가장 강력하고 공개적으로 입증할 수 있는 증거는 그분의 ________ 입니다.", "s": "부활의 증거"}, {"q": "장로 요한을 제외한 예수님의 열한 제자는 모두 부활을 목격한 대가로 ________ 의 대가를 치렀다.", "s": "제자들의 간증"}, {"q": "성경과 일반 종교 경전의 본질적인 차이점은 ________ 입니다. 그것은 유일한 참 하나님에 대한 계시입니까, 아니면 인간이 기록한 것입니까?", "s": "성경 자료"}, {"q": "기독교 신앙과 인공 종교의 근본적인 차이점은 무엇입니까?", "s": "계시와 인위성", "o": "A.기독교는 더 긴 역사를 가지고 있습니다,B.기독교는 인간이 만든 종교가 아니라 신성하게 계시된 진리입니다.,C.기독교 의식은 더 엄숙합니다,D.기독교 신자 수 증가"}, {"q": "하나님께서 다른 사람들에게 자신을 드러내시기 위해 아버지를 사용하시는 주된 목적은 무엇인가?", "s": "아버지로서의 하나님", "o": "A.하나님의 성품은 매우 온화합니다,B.하나님은 진리의 원천이시며, 보호하시고 인도하십니다.,C.하나님은 아이들을 사랑하십니다,D.하나님과 사람은 피로 연결되어 있다."}, {"q": "제자들이 시신을 훔치고 부활을 발명했다는 주장은 왜 지지할 수 없는가?", "s": "빈 묘지 정보", "o": "A.제자들은 겁에 질려 감히 무덤에 다가가지 못했다.,B.돌을 옮기기에는 제자의 힘이 너무 작습니다.,C.예수님의 몸이 너무 무거웠다,D.무덤이 도시에서 너무 멀리 떨어져 있습니다."}, {"q": "신자들의 삶에서 성신의 주요 사업은 무엇인가?", "s": "성령의 역사", "o": "A.믿는 자의 모든 일 정리하기,B.생명을 새롭게 하는 일에 신자들을 만지고, 격려하고, 이끄는 일,C.하룻밤 사이에 사람들을 부자로 만들기,D.신자를 위해 모든 결정을 내립니다."}, {"q": "삼위일체는 왜 물의 고체, 액체, 기체 상태로 설명할 수 없는가?", "s": "삼위일체 비유", "o": "A.물에는 에센스가 없다,B.세 가지 상태의 물은 동시에 존재할 수 없습니다.,C.물이 너무 적음,D.성경은 비유를 금한다"}, {"q": "예수님은 “신명기” 와 어떻게 다른가? (복수 선택)", "s": "예수님의 독특함", "o": "A.성령의 영감을 받은 동정녀에게서 태어남,B.죽은 자 가운데서 부활한 빈 무덤은 공개적으로 조사할 수 있습니다.,C.죄 없는 삶 살기,D.그저 대단히 도덕적인 사람일 뿐입니다."}, {"q": "다음 중 성령의 열매는 무엇인가? (복수 선택)", "s": "성령의 열매", "o": "A.자비,B.기쁨,C.질투와 다툼,D.절제"}, {"q": "동영상에 제시된 권위 있는 성경적 증거는 무엇인가? (복수 선택)", "s": "권위 있는 증거", "o": "A.초월적인 문화적 기록,B.정확한 예측,C.성도들의 간증,D.저자는 모두 같은 시대 출신이다."}, {"q": "하나님은 영이시므로 인간과 마찬가지로 한 번에 한 곳에만 계실 수 있습니다.", "s": "하나님의 속성"}, {"q": "그리스도교 신앙의 타당성의 열쇠는 예수님의 죽음으로부터의 부활입니다.", "s": "부활의 열쇠"}, {"q": "성령은 인간의 심리적 감정일 뿐, 참된 신 중 하나가 아닙니다.", "s": "성령의 사람"}, {"q": "\"삼위일체\" 라는 단어는 성경에서 발견되므로 성경의 원래 단어입니다.", "s": "삼위일체 용어"}, {"q": "인간이 만든 종교의 하나님과 성경 계시의 참 하나님 사이의 근본적인 차이점은 무엇입니까? 인간과 하나님의 관계의 관점에서 설명해 주십시오.", "s": "인공신 vs 참신"}, {"q": "성자와 성령이 삼위일체 안에서 하는 독특한 일은 무엇인가? 이것이 그리스도교 신앙 생활에 어떤 의미인가?", "s": "아들과 성령의 역사"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791216476321','基要真理','回顾二·罪与救恩篇','罪与救恩是信仰的根基：人按神形象被造却因悖逆堕落，亏缺了神的荣耀；神兼慈爱与公义，差遣独生子在十字架上付上代价，人因信称义、成为新造的人。本篇复习第2、3、9、10、11、12、19课，带你确知得救的确据，在恩典中长进。','[{"type": "verse", "q": "【经文填空】凡看见妇女就动________的，这人心里已经与她犯________了", "o": "《马太福音》5章28节", "s": "内心的罪", "a": "淫念|奸淫"}, {"type": "verse", "q": "【经文填空】神爱世人，甚至将他的独生子赐给他们，叫一切________的，不致灭亡，反得________", "o": "《约翰福音》3章16节", "s": "神爱世人", "a": "信他|永生"}, {"type": "verse", "q": "【经文填空】________，神创造天地", "o": "《创世记》1章1节", "s": "创造天地", "a": "起初"}, {"type": "verse", "q": "【经文填空】在世上你们有苦难，但你们可以________，我已经________了世界", "o": "《约翰福音》16章33节", "s": "胜过苦难", "a": "放心|胜"}, {"type": "verse", "q": "【经文填空】若有人在________，他就是新造的人，________，都变成新的了。", "o": "《哥林多后书》5章17节", "s": "新造的人", "a": "基督里|旧事已过"}, {"type": "fill", "q": "神定罪的标准连人的思想意念都涵盖，人不能用国家________的低标准证明自己无罪", "o": "", "s": "定罪标准", "a": "法律"}, {"type": "fill", "q": "救恩的根本是恢复人与神________的关系，而不是解决环境问题", "o": "", "s": "关系恢复", "a": "断绝"}, {"type": "fill", "q": "人按神的________被造，因此尊贵无比，价值从被造时已经存在", "o": "", "s": "神的形象", "a": "形象"}, {"type": "fill", "q": "神给人自由意志，因为爱的对象必须有________选择权，被迫的不是真爱", "o": "", "s": "自由意志", "a": "自主"}, {"type": "fill", "q": "成为新造的人是一个________，像生命成长不能揠苗助长，家人应能看见我们渐进的改变。", "o": "", "s": "成圣过程", "a": "过程"}, {"type": "single", "q": "人不能靠善行得救的根本原因是什么？", "o": "A.善行本身没有价值,B.人靠自己无法恢复与神的关系，善行是本分不是交换的筹码,C.神不喜悦人行善,D.行善实在太难了", "s": "恩典非赚取", "a": "B"}, {"type": "single", "q": "为什么说人是尊贵的？", "o": "A.人比动物更聪明,B.人按神的形象被造,C.人会制造和使用工具,D.人的数量众多", "s": "人的尊贵", "a": "B"}, {"type": "single", "q": "关于白色大宝座与基督台前，正确的是？", "o": "A.两者是同一个审判,B.白色大宝座是终极审判，基督台前是基督徒按所行领赏,C.基督徒不再面对任何审判,D.只有不信的人才受审判", "s": "两种审判", "a": "B"}, {"type": "single", "q": "“在基督里”是什么意思？", "o": "A.在教会里聚会,B.在耶稣基督所完成的救恩里面,C.心里相信耶稣,D.在基督徒群体中", "s": "在基督里", "a": "B"}, {"type": "multiple", "q": "真正的得救包括哪两方面？（多选）", "o": "A.口里认耶稣为主,B.心里信神叫他从死里复活,C.受洗加入教会,D.多做善事积功德", "s": "得救之道", "a": "A|B"}, {"type": "multiple", "q": "关于人的被造，正确的有哪些？（多选）", "o": "A.人按神的形象被造,B.人是偶然进化的产物,C.人的价值从被造时已经存在,D.神给了人自由意志", "s": "人的被造", "a": "A|C|D"}, {"type": "multiple", "q": "圣经救恩观中，神的哪两面同时在十字架上显明？（多选）", "o": "A.慈爱：主动为我们预备救恩,B.公义：罪必须付上代价,C.只讲慈爱不讲公义,D.只讲公义不讲慈爱", "s": "公义慈爱", "a": "A|B"}, {"type": "multiple", "q": "以下哪些是“新造的人”生命改变的表现？（多选）", "o": "A.结出圣灵的果子：仁爱、喜乐、和平等,B.行公义、好怜悯、存谦卑的心与神同行,C.老我个性被改变，不再伤害自己和别人,D.信耶稣后凡事顺利发财", "s": "生命改变", "a": "A|B|C"}, {"type": "judge", "q": "真正得救的基督徒就不会再生病或遭遇生活中的困难。", "o": "", "s": "得救与苦难", "a": "错"}, {"type": "judge", "q": "人是偶然进化的产物，并没有什么特别的尊贵可言。", "o": "", "s": "人的来源", "a": "错"}, {"type": "judge", "q": "基督徒得救之后，就不再需要面对任何形式的审判。", "o": "", "s": "信徒审判", "a": "错"}, {"type": "judge", "q": "雅各书讲因行为称义，与罗马书讲因信称义互相矛盾，只能选择相信其一。", "o": "", "s": "两卷调和", "a": "错"}, {"type": "judge", "q": "照着本相来到主面前，就等于可以一直活在本来的样子里，不必改变。", "o": "", "s": "本相与改变", "a": "错"}, {"type": "essay", "q": "请说明「因信称义」与「因行为称义」的根本区别，并解释信心与行为的关系。", "o": "", "s": "因信称义", "a": "因行为称义是人造宗教的思路：靠行善积功德与神交换福报，人定标准、人做主；因信称义是神启示的信仰：人承认自己是罪人、接受耶稣作生命的主，靠与神恢复关系而得救，得救本乎恩也因着信。信心与行为并不对立：罗马书讲人得救不是靠行为，雅各书讲真信心必带出行为——真信心扎根于与神的关系，必然带来生命的改变，结出行为的果子。没有行为的信心是死的。"}, {"type": "essay", "q": "请解释“旧事已过，都变成新的了”的真正含义。", "o": "", "s": "旧事已过", "a": "不只是过去的罪得赦免、错误一笔勾销，更是指过去主导生命的错误价值观、老我生命被神拿去；靠着圣灵内住，结出仁爱、喜乐、和平等果子，活出公义、良善、诚实的新生命。这是神的恩典，人也要负责任天天选择顺服。"}]','','quiz','[]','','28','寇绍涵牧师•根基建造101','{"en": {"title": "Review 2: Sin and Salvation", "content": "Sin and salvation are the foundation of faith: man is created in the image of God, but falls in disobedience, and falls short of the glory of God; God, being loving and righteous, sent the only begotten Son to pay the price on the cross, and man is justified by faith and becomes a new creation. In this review of lessons 2, 3, 9, 10, 11, 12, and 19, you will learn about the assurance of salvation and grow in grace.", "instructions": "", "guide": [], "quizzes": [{"q": "[Scripture Fill in the Blank] Anyone who sees a woman and moves ________ has already violated ________ with her in his heart.", "s": "Inner Sin"}, {"q": "[Scripture Fill in the Blank] God loved the world, and even gave His only begotten Son to them, so that all ________ would not perish, but ________", "s": "God Loves The Common People"}, {"q": "[Scripture Fill in the Blank] ________, God created the heavens and the earth", "s": "Creating Heaven and Earth"}, {"q": "[Scripture Fill in the Blank] In the world you have suffering, but you can ________, I have ________ the world", "s": "Victory over Suffering"}, {"q": "[Scripture Fill in the Blank] If anyone is in ________, he is a new creation, and ________ has become new.", "s": "Newly Created Man"}, {"q": "The standard of God''s condemnation even covers people''s thoughts and ideas. People cannot prove their innocence with the low standard of the state ________.", "s": "Conviction Criteria"}, {"q": "The essence of salvation is to restore the relationship between man and God ________, not to solve environmental problems.", "s": "Relationship Recovery"}, {"q": "Humans are created according to God''s ________, so they are incomparably noble, and their value has existed since the time of creation.", "s": "Image of God"}, {"q": "God gives people free will, because the object of love must have the right to choose ________, and it is not true love that is forced", "s": "Free will"}, {"q": "Becoming a new creation is a ________, like the growth of life cannot be fostered by seedlings, and our families should be able to see our gradual change.", "s": "Sanctification process"}, {"q": "What is the root cause of man''s inability to be saved by good works?", "s": "Grace is not earned", "o": "A.Good deeds have no value in themselves,B.Man cannot restore his relationship with God on his own. Good deeds are not a bargaining chip.,C.God does not like people to do good deeds,D.It''s too hard to do good."}, {"q": "Why are people noble?", "s": "The dignity of man", "o": "A.Humans are smarter than animals,B.Man was created in the image of God,C.People make and use tools,D.The number of people is huge"}, {"q": "What is true about the Great White Throne and the Stand of Christ?", "s": "Two Trial Types", "o": "A.Both are the same trial,B.The Great White Throne is the final judgment, and Christ stands before Christians to reap the rewards according to their deeds.,C.Christians no longer face any trials,D.Only unbelievers will be judged"}, {"q": "What does “in Christ” mean?", "s": "In Christ", "o": "A.Gathering in the Church,B.In the completed salvation of Jesus Christ,C.Believe in Jesus in your heart,D.In the Christian community"}, {"q": "What are two aspects of true salvation? (Multiple choice)", "s": "The Path to Salvation", "o": "A.Mouth confessing Jesus as Lord,B.Faith in God in his heart raised him from the dead,C.Baptized into the Church,D.Do more good deeds and accumulate merit"}, {"q": "What is true about the creation of man? (Multiple choice)", "s": "The Creation of Man", "o": "A.Man was created in the image of God,B.Man is the product of accidental evolution,C.The value of man has existed since the time of his creation,D.God has given man free will."}, {"q": "Which two aspects of God are revealed on the cross at the same time in the biblical concept of salvation? (Multiple choice)", "s": "Righteousness and mercy", "o": "A.Loving-kindness: taking the initiative to prepare us for salvation,B.Justice: Sin must pay,C.Speak only of mercy, not of righteousness,D.Speak only of righteousness, not of mercy."}, {"q": "Which of the following are manifestations of life-changing “newly created man”? (Multiple choice)", "s": "Life Changing", "o": "A.Producing the Fruit of the Holy Spirit: Love, Joy, and Equality,B.Walk with God in righteousness, compassion, and humility,C.My personality has changed and I no longer hurt myself and others,D.Become rich after believing in Jesus"}, {"q": "A truly saved Christian will no longer be sick or have difficulties in life.", "s": "Salvation and Suffering"}, {"q": "Humans are the product of accidental evolution, and there is nothing particularly noble about them.", "s": "Sources of people"}, {"q": "After the salvation of Christians, there is no longer any need to face any form of judgment.", "s": "The Judgment of the Belie"}, {"q": "James speaks of justification by works, contradicts Romans in justification by faith, and chooses only one.", "s": "Two Rolls of Harmony"}, {"q": "When you come to the Lord according to the true image, you can always live in the way you are, without having to change.", "s": "Factors and Changes"}, {"q": "Please explain the fundamental difference between “justification by faith” and “justification by works” and explain the relationship between faith and works.", "s": "Justification by Faith"}, {"q": "Please explain the true meaning of “old things are gone and become new”.", "s": "Old things are over"}]}, "ja": {"title": "復習2 ：罪と救い", "content": "罪と救いは信仰の基礎です。人は神のかたちに造られましたが，不従順に陥り，神の栄光に足りません。神は愛と義に満ちておられ，十字架の代価を払うために独り子をお遣わしになりました。そして人は信仰によって義とされ，新しい被造物となりました。このレッスン2 ， 3 ， 9 ， 10 ， 11 ， 12 ， 19の復習では，救いの確信と恵みの中で成長することについて学びます。", "instructions": "", "guide": [], "quizzes": [{"q": "〔聖句の穴埋め〕女性を見て________を動かす人は、すでに心の中で________を侵害しています。", "s": "内なる罪"}, {"q": "〔聖句の穴埋め〕神はこの世を愛し，すべての________が滅びないように，ご自分の独り子さえも彼らにお与えになりました。", "s": "神は世界を愛しておられる"}, {"q": "〔聖句の穴埋め〕________、神は天と地を創造されました", "s": "天地創造"}, {"q": "〔聖句の穴埋め〕世界ではあなたは苦しんでいますが、あなたは________することができます、私は________世界を持っています", "s": "苦しみに勝利する"}, {"q": "〔聖句の穴埋め〕誰かが________にいる場合、彼は新しい創造物であり、________は新しいものになりました。", "s": "新しく創造された男"}, {"q": "神の非難の基準は、人々の考えや考えさえも網羅しています。人々は、国家の低い基準________で自分の無実を証明することはできません。", "s": "有罪判決の基準"}, {"q": "救いの本質は，人と神との関係を回復することであり，環境問題を解決することではありません。", "s": "リレーションシップの回復"}, {"q": "人間は神の________に従って創造されているので、比類のない高貴さを持ち、その価値は創造の時から存在しています。", "s": "神の画像"}, {"q": "神は人々に自由意志を与えます。なぜなら、愛の対象は________を選択する権利を持たなければならず、強制されるのは真の愛ではないからです。", "s": "自由意志"}, {"q": "新しい創造物になることは________であり、生命の成長は苗木によって育まれることはできず、私たちの家族は私たちの徐々に変化を見ることができるはずです。", "s": "聖化プロセス"}, {"q": "人が良い行いによって救われることができない根本的な原因は何ですか。", "s": "グレースは獲得できません", "o": "A.善行自体に価値はない,B.人間は自分自身で神との関係を回復することはできません。善行は交渉の切り札ではありません。,C.神は人々が善行をするのを好まれない,D.良いことをするのは難しすぎます。"}, {"q": "なぜ人々は高貴なのでしょうか？", "s": "人間の尊厳", "o": "A.人間は動物よりも賢い,B.人は神のかたちに造られた,C.人々はツールを作り、使用しています,D.人数が多いですね"}, {"q": "大いなる白い玉座とキリストの立場について，どのようなことが真実ですか。", "s": "2つのトライアルタイプ", "o": "A.どちらも同じトライアルです,B.偉大な白い玉座は最後の審判であり、キリストはクリスチャンの前に立ち、彼らの行いに従って報酬を得ます。,C.クリスチャンはもはや試練に直面していない,D.信じない者だけが裁かれます"}, {"q": "「キリストにあって」とはどういう意味でしょうか。", "s": "キリストにあって", "o": "A.教会での集まり,B.イエス・キリストの完全な救いにおいて,C.心の中でイエスを信じる,D.キリスト教徒のコミュニティで"}, {"q": "真の救いの2つの側面は何ですか。（複数選択可）", "s": "救いへの道", "o": "A.イエスを主と告白する口,B.心の中の神への信仰が彼を死者の中からよみがえらせた,C.バプテスマを受けて教会に入る,D.より多くの善行を行い、功績を蓄積する"}, {"q": "人間の創造について何が真実なのでしょうか。（複数選択可）", "s": "人間の創造", "o": "A.人は神のかたちに造られた,B.人間は偶発的な進化の産物です,C.人間の価値は創造の時から存在していた,D.神は人間に自由意志を与えました。"}, {"q": "聖書の救いの概念において，十字架上で同時に啓示されている神の二つの側面はどれですか。（複数選択可）", "s": "義と憐れみ", "o": "A.愛と親切：主導権を握って救いに備える,B.正義：罪は償わなければならない,C.義のことではなく，憐れみのことだけを語る,D.憐れみではなく，ただ義について語りなさい。"}, {"q": "次のうち、人生を変える「新しく創造された人」の現れはどれですか？ （複数選択可）", "s": "人生を変える", "o": "A.聖霊の実を結ぶ：愛，喜び，平等,B.義と憐れみと謙遜さをもって神とともに歩む,C.性格が変わり、もはや自分や他の人を傷つけることはない,D.イエスを信じて豊かになる"}, {"q": "真に救われたクリスチャンは，もはや病気になったり，人生に困難を抱えたりすることはありません。", "s": "救いと苦しみ"}, {"q": "人間は偶発的な進化の産物であり、特に高貴なものはありません。", "s": "人物の情報源"}, {"q": "クリスチャンの救いの後，もはやいかなる形の裁きにも直面する必要はありません。", "s": "信者の裁き"}, {"q": "ヤコブは行いによる義認について語り，信仰による義認においてローマ人と矛盾し，一つだけを選びます。", "s": "調和のロール2つ"}, {"q": "真の姿に従って主のもとに来ると，変わることなく，いつでも自分のように生きることができます。", "s": "要因と変化"}, {"q": "「信仰による義」と「行いによる義」の根本的な違いを説明し，信仰と行いとの関係を説明してください。", "s": "信仰による義認"}, {"q": "「古いものはなくなり、新しいものになる」の本当の意味を説明してください。", "s": "古いものは終わった"}]}, "ko": {"title": "복습 2: 죄와 구원", "content": "죄와 구원은 믿음의 기초입니다. 인간은 하나님의 형상대로 창조되었지만 불순종으로 떨어지고 하나님의 영광에 미치지 못합니다. 하나님은 사랑과 의로움으로 독생자를 보내 십자가에서 값을 치르게 하셨고, 사람은 믿음으로 의롭다 하심을 받고 새로운 피조물이 되었습니다. 2, 3, 9, 10, 11, 12, 19 과를 복습하면서 구원의 확신에 대해 배우고 은혜 안에서 성장할 것이다.", "instructions": "", "guide": [], "quizzes": [{"q": "[Scripture Fill in the Blank] 여성을 보고 ________ 을 (를) 움직이는 사람은 이미 ________ 을 (를) 마음으로 위반했습니다.", "s": "내신"}, {"q": "[Scripture Fill in the Blank] 하느님은 세상을 사랑하셨고, 심지어 독생자를 그들에게 주셨기 때문에 모든 ________ 이 (가) 멸망하지 않고 ________", "s": "하나님은 세상을 사랑하십니다"}, {"q": "[Scripture Fill in the Blank] ________, 하나님은 천지를 창조하셨습니다", "s": "천지창조"}, {"q": "[Scripture Fill in the Blank] 세상에서 당신은 고통을 겪고 있지만, 당신은 ________ 할 수 있습니다. 나는 ________ 세계를 가지고 있습니다.", "s": "고통에 대한 승리"}, {"q": "[Scripture Fill in the Blank] ________ 에 속한 사람은 새로운 피조물이며 ________ 은 (는) 새로워졌습니다.", "s": "새로 창조된 인간"}, {"q": "하나님의 정죄의 기준은 사람들의 생각과 생각까지도 포함합니다. 사람들은 국가 ________ 의 낮은 기준으로는 결백을 증명할 수 없습니다.", "s": "유죄 판결 기준"}, {"q": "구원의 본질은 인간과 하나님과의 관계를 회복하는 것이지 환경문제를 해결하는 것이 아니다.", "s": "관계 회복"}, {"q": "인간은 하나님의 ________ 에 따라 창조되었기 때문에 비교할 수 없을 정도로 고귀하며 창조 시대부터 존재해 왔습니다.", "s": "하나님의 형상"}, {"q": "사랑의 대상은 ________ 을 (를) 선택할 권리가 있어야 하며, 강요된 것은 진정한 사랑이 아니기 때문에 하나님은 사람들에게 자유 의지를 주십니다.", "s": "자유 의지"}, {"q": "새로운 피조물이 되는 것은 생명의 성장이 묘목으로 육성될 수 없는 것과 마찬가지로 ________ 이며, 우리 가족은 점진적인 변화를 볼 수 있어야 합니다.", "s": "성화 과정"}, {"q": "인간이 선행으로 구원받지 못하는 근본 원인은 무엇인가?", "s": "유예는 적립되지 않습니다", "o": "A.선행은 그 자체로 가치가 없습니다.,B.인간은 하나님과의 관계를 스스로 회복할 수 없습니다. 선행은 협상 칩이 아닙니다.,C.하나님은 사람들이 선을 행하는 것을 좋아하지 않으십니다.,D.선을 행하는 것은 너무 어렵습니다."}, {"q": "왜 사람들은 고귀한가?", "s": "인간의 존엄성", "o": "A.인간은 동물보다 똑똑합니다.,B.인간은 하나님의 형상대로 창조되었습니다.,C.사람들은 도구를 만들고 사용합니다,D.인원수가 엄청납니다"}, {"q": "위대한 백보좌와 그리스도의 입장에 대해 무엇이 참된가?", "s": "두 가지 임상시험 유형", "o": "A.둘 다 동일한 임상시험입니다.,B.대백보좌는 최후의 심판이며, 그리스도께서는 그리스도인들 앞에 서서 그들의 행위에 따라 보상을 거두십니다.,C.그리스도인들은 더 이상 어떤 시련도 겪지 않습니다.,D.오직 불신자들만이 심판을 받을 것입니다."}, {"q": "“그리스도 안에서” 는 무엇을 의미하는가?", "s": "그리스도 안에서", "o": "A.교회에서 모이기,B.예수 그리스도의 완전한 구원 안에서,C.마음속으로 예수님을 믿으세요,D.기독교 공동체에서"}, {"q": "참된 구원의 두 가지 측면은 무엇인가? (복수 선택)", "s": "구원에 이르는 길", "o": "A.예수님을 주님으로 고백하는 입,B.그의 마음속에 있는 하나님에 대한 믿음이 그를 죽음에서 일으켰다.,C.교회로 침례를 받음,D.더 많은 선행을 행하고 공로를 쌓으십시오"}, {"q": "인간 창조에 대한 진실은 무엇인가? (복수 선택)", "s": "인간의 창조", "o": "A.인간은 하나님의 형상대로 창조되었습니다.,B.인간은 우연한 진화의 산물이다.,C.인간의 가치는 창조 때부터 존재해 왔다.,D.하느님께서는 인간에게 자유 의지를 주셨습니다."}, {"q": "성경의 구원 개념에서 십자가에서 동시에 드러나는 하나님의 두 가지 측면은 무엇입니까? (복수 선택)", "s": "의와 자비", "o": "A.사랑의 친절: 우리가 구원을 받을 수 있도록 주도적으로 준비하기,B.정의: 죄는 지불해야 합니다,C.자비에 대해서만 말하고 의에 대해서는 말하지 말라.,D.의로움에 대해서만 말하고 자비에 대해서는 말하지 마십시오."}, {"q": "다음 중 삶을 변화시키는 “새로 창조된 인간” 의 표현은 무엇인가? (복수 선택)", "s": "인생을 바꾸는 일", "o": "A.성령의 열매를 맺음: 사랑, 기쁨, 평등,B.의와 긍휼과 겸손으로 하나님과 동행하십시오.,C.내 성격이 바뀌었고 더 이상 나 자신과 다른 사람들을 해치지 않는다.,D.예수님을 믿은 후 부자가 되세요"}, {"q": "진정으로 구원받은 그리스도인은 더 이상 아프거나 삶의 어려움을 겪지 않을 것입니다.", "s": "구원과 고통"}, {"q": "인간은 우연한 진화의 산물이며, 특별히 고귀한 것은 없습니다.", "s": "인적 자원"}, {"q": "그리스도인들이 구원받은 후에는 더 이상 어떤 형태의 심판도 받을 필요가 없습니다.", "s": "믿는 자의 심판"}, {"q": "야고보는 행위에 의한 의화에 대해 말하고, 신앙에 의한 의화에 있어 로마인들과 모순되며, 오직 한 사람만을 선택한다.", "s": "두 롤의 조화"}, {"q": "참된 모습을 따라 주님께 나아갈 때, 여러분은 변화할 필요 없이 언제나 있는 그대로의 모습으로 살아갈 수 있습니다.", "s": "요인 및 변화"}, {"q": "“믿음으로 의롭다 함” 과 “행위로 의롭다 함” 의 근본적인 차이를 설명하고 믿음과 행위의 관계를 설명해 주십시오.", "s": "믿음에 의한 의화"}, {"q": "“옛 것이 없어지고 새로워지다” 의 진정한 의미를 설명해 주십시오.", "s": "오래된 것은 끝났습니다"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791216456319','基要真理','回顾三·成圣生活篇','成圣生活主题复习：分别为圣归属神、灵修祷告亲近主、苦难中经历神的同在与安慰、把所信真理活出来作光作盐。愿你在成圣路上靠主得胜，一生跟随不偏离。','[{"type": "verse", "q": "【经文填空】故此你们要________神，务要________魔鬼，魔鬼就必________逃跑了", "o": "《雅各书》4章7节", "s": "顺服与抵挡", "a": "顺服|抵挡|离开你们"}, {"type": "verse", "q": "【经文填空】应当一无________，只要凡事借着祷告、________和________，将你们所要的告诉神", "o": "《腓立比书》4章6节", "s": "交托与祷告", "a": "挂虑|祈求|感谢"}, {"type": "verse", "q": "【经文填空】我将这些事告诉你们，是要叫你们在我里面有________；在世上你们有________，但你们可以________，我已经胜了世界", "o": "《约翰福音》16章33节", "s": "主里平安", "a": "平安|苦难|放心"}, {"type": "verse", "q": "【经文填空】不要效法这个________，只要心意更新而________，叫你们查验何为神的善良、纯全、可喜悦的________", "o": "《罗马书》12章2节", "s": "心意更新", "a": "世界|变化|旨意"}, {"type": "fill", "q": "得救不是终点而是________，从决志称耶稣为主那天起，就要学习过得胜的生活。", "o": "", "s": "得胜的起点", "a": "开始"}, {"type": "fill", "q": "分别为圣不是躲进深山远离人群，而是从这个世界________出来，归属于神，按真理而活。", "o": "", "s": "分别为圣", "a": "分别"}, {"type": "fill", "q": "祷告的内容很丰富，除了祈求，还包括赞美、感恩、代祷和________，不只是为自己求。", "o": "", "s": "祷告内容", "a": "认罪"}, {"type": "fill", "q": "灵修与查经不一样：灵修是每天来到神面前________关系，查经是系统地明白整本圣经。", "o": "", "s": "灵修本质", "a": "亲近神"}, {"type": "fill", "q": "从圣经真理看，一切苦难的根源是________关系的破裂，神的爱是治本——恢复这关系。", "o": "", "s": "苦难根源", "a": "神人"}, {"type": "fill", "q": "神今天没有立刻审判世上的罪恶，乃是出于________；今天仍是福音广传的恩典时代。", "o": "", "s": "神的宽容", "a": "宽容"}, {"type": "fill", "q": "视频强调：________才能力行；若所知道的不是神所启示的真理，做得再多也不合神心意。", "o": "", "s": "真知力行", "a": "真知"}, {"type": "single", "q": "按本课所讲，“分别为圣”最准确的含义是？", "o": "A.避世修行，远离人群独居,B.从世界分别出来归属于神，按圣经真理而活并作见证,C.自认比别人圣洁、高人一等,D.遵守更多宗教规条和仪式", "s": "分别为圣", "a": "B"}, {"type": "single", "q": "按本课所讲，祷告最核心的意义是？", "o": "A.把神该做的事告诉祂，提醒祂,B.用华丽的辞藻背诵经文给人听,C.神的孩子真诚地来到天父面前交谈,D.用祷告改变神的心意", "s": "祷告本质", "a": "C"}, {"type": "single", "q": "按本课所讲，神面对苦难问题的方式是？", "o": "A.像救火员一样随叫随到，解决表面问题,B.治本：差独生子亲身受苦，恢复神人关系、更新生命,C.把一切苦难全部挪去,D.任凭人在苦难中自生自灭", "s": "神治本", "a": "B"}, {"type": "single", "q": "按本课所讲，“今世得百倍”的“百倍”主要指什么？", "o": "A.金钱物质上的百倍回报,B.生命成熟长大所带出来的丰盛,C.子孙满堂、家族兴旺,D.长命百岁、身体健康", "s": "百倍真义", "a": "B"}, {"type": "multiple", "q": "按本课所讲，神赐给我们得胜的资源包括？（多选）", "o": "A.一本圣经，载明行事为人的标准,B.圣灵内住，不断提醒更新我们,C.人运用自由意志选择顺服神,D.靠自己的意志力咬牙坚持", "s": "得胜资源", "a": "A|B|C"}, {"type": "multiple", "q": "按本课所讲，祷告的内容包括？（多选）", "o": "A.赞美,B.感恩,C.代祷,D.只为自己的需要祈求", "s": "祷告内容", "a": "A|B|C"}, {"type": "multiple", "q": "按本课所讲，神没有立即审判一切罪恶的原因包括？（多选）", "o": "A.神纵容罪恶,B.神忘记了这回事,C.神宽容，给人回转认识神的机会,D.今天仍是福音广传的恩典时代", "s": "神的宽容", "a": "C|D"}, {"type": "multiple", "q": "按本课所讲，圣灵在基督徒生命中的工作包括？（多选）", "o": "A.催逼,B.感动安慰,C.禁止鼓励,D.代替我们做决定、不用思考", "s": "圣灵工作", "a": "A|B|C"}, {"type": "judge", "q": "分别为圣就是自认全然圣洁、高人一等，可以轻看罪人。", "o": "", "s": "分别为圣", "a": "错"}, {"type": "judge", "q": "祷告完了之后，可以安静一段时间，等候神藉着经文和圣灵的感动来提醒我们。", "o": "", "s": "等候神", "a": "对"}, {"type": "judge", "q": "成功神学“信耶稣就一切顺利、发财致富”的说法符合圣经真理。", "o": "", "s": "成功神学", "a": "错"}, {"type": "judge", "q": "基督徒的价值应当衡量在别人对我们的评断和称赞上。", "o": "", "s": "价值标准", "a": "错"}, {"type": "essay", "q": "结合第13课与第16课，成圣生活的操练包括哪些方面？请说明。", "o": "", "s": "成圣操练", "a": "成圣是得救后的必然结果，操练包括两方面：一是分别为圣——从世界分别出来归属神，按圣经真理而活，得胜老我、世界和撒旦的诱惑，秘诀是亲近神、抵挡魔鬼（雅4:7-8），以圣经为标准、靠圣灵提醒更新；二是灵修祷告——每天亲近神建立关系，祷告包括赞美、感恩、代祷、认罪和祈求，祷告后安静等候神的提醒，并在生活中活出见证。"}, {"type": "essay", "q": "结合第22课与第26课，基督徒在苦难中应当如何活出信仰？", "o": "", "s": "苦难中活出信仰", "a": "苦难的根源是神人关系破裂，神的爱是治本——差独生子亲身受苦，恢复人与神的关系。基督徒在苦难中不抱怨、不推诿，知道主已胜了世界（约16:33），在主里有平安；以真知力行，把所信的活出来，在任何处境为荣耀神而活（林前10:31），作光作盐，用生命吸引人来到真神面前。"}]','','quiz','[]','','29','寇绍涵牧师•根基建造101','{"en": {"title": "Review of Sanctification Life Part III", "content": "Sanctification life theme review: Pray for holiness to belong to God, pray for spiritual devotion to draw closer to the Lord, experience God''s companionship and comfort in suffering, and live out the truths you believe as light and salt. May you be victorious by the Lord on the path to sanctification, and follow it all your life without deviation.", "instructions": "", "guide": [], "quizzes": [{"q": "[Scripture Fill in the Blank] Therefore, you must ________ God, you must ________ the devil, and the devil will ________ escape", "s": "Obedience and Resistance"}, {"q": "[Scripture Fill in the Blank] There should be no ________, as long as you tell God what you want through prayer, ________ and ________.", "s": "Entrustment & Prayer"}, {"q": "[Scripture Fill in the Blank] I tell you these things so that you have ________ in me; you have ________ in the world, but you can ________, I have overcome the world", "s": "Peace in the Lord"}, {"q": "[Scripture Fill in the Blank] Don''t follow this ________, as long as your heart is renewed and ________, let you check what is God''s good, pure, and joyful ________", "s": "Mind update"}, {"q": "Salvation is not the end but the ________, and we must learn to live a victorious life from the day we decide to call Jesus Lord.", "s": "The starting point for victory"}, {"q": "The sanctification is not to hide in the deep mountains and stay away from the crowd, but to come out of this world ________, belong to God, and live according to the truth.", "s": "<bpt i=\"1\" type=\"bold\">{}</bpt>CONSECRATION<ept i=\"1\">{}</ept>"}, {"q": "Prayer is rich, and in addition to prayer, it includes praise, gratitude, intercession, and ________, not just for yourself.", "s": "Prayer Content"}, {"q": "Spiritual practice is not the same as Bible study: Spiritual practice is a ________ relationship that comes to God every day, and Bible study is a systematic understanding of the entire Bible.", "s": "Spiritual Essence"}, {"q": "From the perspective of biblical truth, the root of all suffering is the breakdown of the ________ relationship, and God''s love is the root - to restore this relationship.", "s": "Root of Suffering"}, {"q": "God does not judge the sins of the world immediately today, but from ________; and today is still the age of grace in which the gospel is preached.", "s": "God''s Tolerance"}, {"q": "The video emphasizes that ________ can be done; it is not God''s will to do more of what is not God''s revealed truth.", "s": "True Wisdom Practice"}, {"q": "According to this lesson, what is the most accurate meaning of \"respectively holy\"?", "s": "<bpt i=\"1\" type=\"bold\">{}</bpt>CONSECRATION<ept i=\"1\">{}</ept>", "o": "A.Avoid worldly cultivation and live alone from the crowd,B.Separated from the world and belonging to God, living and witnessing according to biblical truth,C.Considered more holy and superior than others,D.Follow more religious rules and rituals"}, {"q": "What is the central meaning of prayer as taught in this lesson?", "s": "The Nature of Prayer", "o": "A.Tell God what to do and remind Him,B.Recite the Scriptures in gorgeous words,C.Children of God come to Heavenly Father sincerely to talk,D.Changing God''s Mind with Prayer"}, {"q": "According to this lesson, how does God deal with the problem of suffering?", "s": "Divine Zhi-bon", "o": "A.Resolve surface issues on call like a firefighter,B.Cure the root cause: Suffer the only child personally, restore the relationship between God and man, and renew life,C.Remove All Suffering,D.Allowing someone to die in their own misery"}, {"q": "According to this lesson, what does \"a hundred times\" of \"a hundred times in this world\" mainly mean?", "s": "A Hundred Times True Meaning", "o": "A.100x return on money and material goods,B.The abundance brought out by the maturity of life,C.Grandchildren and thriving families,D.Long life, good health"}, {"q": "According to this lesson, what are some of the resources God has given us to overcome? (Multiple choice)", "s": "Victory Resources", "o": "A.A Bible that sets out the standards for acting as a person,B.The Holy Spirit dwells within us, constantly reminding us to update,C.Man uses his free will to choose obedience to God,D.Clench your teeth with your own willpower"}, {"q": "What does the lesson say about prayer include? (Multiple choice)", "s": "Prayer Content", "o": "A.Praise,B.Thanksgiving,C.Intercessory prayer.,D.Pray only for your own needs"}, {"q": "According to this lesson, are some of the reasons why God did not immediately judge all sins? (Multiple choice)", "s": "God''s Tolerance", "o": "A.God condones sin,B.God forgot about that.,C.God is tolerant, giving people the opportunity to return to knowing God,D.Today is still the Age of Grace when the Gospel was widely preached"}, {"q": "What is included in the work of the Holy Spirit in the Christian life as taught in this lesson? (Multiple choice)", "s": "Holy Spirit Work", "o": "A.Hustle,B.Touching consolation,C.No Encouragement,D.Make decisions for us without thinking"}, {"q": "To be holy separately is to consider oneself completely holy and superior, and to despise sinners.", "s": "<bpt i=\"1\" type=\"bold\">{}</bpt>CONSECRATION<ept i=\"1\">{}</ept>"}, {"q": "After we have prayed, we can be quiet for a while, waiting for God to remind us through the scriptures and the Holy Ghost.", "s": "Waiting on God"}, {"q": "The prosperity theology statement that “Believe in Jesus and get rich” is consistent with biblical truth.", "s": "Success theology"}, {"q": "The value of a Christian should be measured in the judgments and praise that others give us.", "s": "Value Criteria"}, {"q": "In conjunction with Lesson 13 and Lesson 16, what are some aspects of the practice of living a sanctified life? Please explain.", "s": "Sanctification Exercise"}, {"q": "In connection with Lesson 22 and Lesson 26, how should Christians live out their faith in the midst of suffering?", "s": "Living Faith in Suffering"}]}, "ja": {"title": "聖化生活の復習パートIII", "content": "聖化生活のテーマの復習：神に属する聖性を祈り，主に近づくための霊的な献身を祈り，苦しみの中で神との交わりと慰めを経験し，あなたが信じる真理を光と塩として実践してください。あなたが聖化への道で主に勝利し、逸脱することなく一生それに従うことができますように。", "instructions": "", "guide": [], "quizzes": [{"q": "〔聖句の穴埋め〕したがって、あなたは________神、あなたは________悪魔を________しなければなりません、そして悪魔は________逃れるでしょう", "s": "従順と抵抗"}, {"q": "〔聖句の穴埋め〕祈りを通して望むことを神に伝える限り， ________と________はあってはなりません。", "s": "委任と祈り"}, {"q": "〔聖句の穴埋め〕あなたが私の中に________を持っているように、私はあなたにこれらのことを話します。あなたは世界に________を持っていますが、あなたは________することができます。私は世界を征服しました", "s": "主にある平安"}, {"q": "〔聖句の穴埋め〕この________に従わないでください。あなたの心が新しくなって________である限り、神の良いもの、純粋なもの、喜びのあるものを確認してください________", "s": "マインドアップデート"}, {"q": "救いは終わりではなく， ________であり，イエス・キリストと呼ばれる日から勝利の人生を送ることを学ばなければなりません。", "s": "勝利への出発点"}, {"q": "聖化とは、深い山に隠れて群衆から遠ざかることではなく、この世から出て来て________、神に属し、真理に従って生きることです。", "s": "別々に神聖"}, {"q": "祈りは豊かであり、祈りに加えて、賛美、感謝、執り成し、________を含み、自分だけのものではありません。", "s": "祈りの内容"}, {"q": "霊的な実践は聖書研究と同じではありません。霊的な実践は毎日神に来る________関係であり、聖書研究は聖書全体を体系的に理解することです。", "s": "スピリチュアルエッセンス"}, {"q": "聖書の真理の観点から、すべての苦しみの根源は________関係の崩壊であり、神の愛がこの関係を回復するための根源です。", "s": "苦しみの根源"}, {"q": "神は，今日，ただちに世の罪を裁かれるのではなく， ________から裁かれるのです。今日も，福音が宣べ伝えられる恵みの時代です。", "s": "神の寛容"}, {"q": "ビデオは， ________を行うことができることを強調しています。神が啓示された真理ではないことをさらに行うことは，神の御心ではありません。", "s": "真の知恵の実践"}, {"q": "このレッスンによれば，「それぞれ聖なる」の最も正確な意味は何でしょうか。", "s": "別々に神聖", "o": "A.世俗的な耕作を避け、群衆から一人で暮らす,B.世から切り離され、神に属し、聖書の真理に従って生き、証しする,C.他の人よりも神聖で優れていると考えられている,D.より多くの宗教的なルールと儀式に従う"}, {"q": "この課で教えられている祈りの中心的な意味は何ですか。", "s": "祈りの本質", "o": "A.神に何をすべきかを伝え，思い出させる,B.華やかな言葉で聖文を暗唱する,C.神の子供たちは，心から話すために天の御父のもとに来る,D.祈りで神の心を変える"}, {"q": "この課によると，神は苦しみの問題にどのように対処しておられますか。", "s": "Divine Zhi - bon", "o": "A.消防士のように、オンコールで表面の問題を解決します,B.根本的な原因を治す：一人っ子に個人的に苦しみを受け、神と人間の関係を回復し、人生を新しくする,C.すべての苦しみを取り除く,D.誰かが自分の惨めさの中で死ぬことを許す"}, {"q": "この教訓によれば，「この世で百回」の「百回」とは，主として何を意味するのであろうか。", "s": "百回の本当の意味", "o": "A.お金と物質的な商品の100倍のリターン,B.人生の成熟によってもたらされる豊かさ,C.孫と繁栄する家族,D.長寿命、健康"}, {"q": "このレッスンによると，神が克服するためにわたしたちに与えてくださったリソースにはどのようなものがありますか。（複数選択可）", "s": "勝利の資源", "o": "A.人として行動するための基準を定めた聖書,B.聖霊はわたしたちの内に住んでおられ，更新するよう絶えずわたしたちに思い出させてくれます。,C.人は自由意志を使って神への従順を選ぶ,D.自分の意志で歯ぎしり"}, {"q": "このレッスンでは，祈りについてどのようなことが含まれていますか。（複数選択可）", "s": "祈りの内容", "o": "A.好意的なコメント,B.感謝の気持ち,C.執り成しの祈り,D.自分の必要のためだけに祈る"}, {"q": "この課によれば，神がすべての罪を直ちに裁かれなかった理由は何かありますか。（複数選択可）", "s": "神の寛容", "o": "A.神は罪を赦してくださる,B.神はそれを忘れてしまった。,C.神は寛容であり、人々に神を知ることに戻る機会を与えます,D.今日は，福音が広く宣べ伝えられた恵みの時代です。"}, {"q": "この課で教えられているように，クリスチャン生活における聖霊の働きには何が含まれていますか。（複数選択可）", "s": "聖霊の働き", "o": "A.ハッスル,B.感動の慰め,C.励ましなし,D.考えずに私たちのために決定を下す"}, {"q": "別々に聖なる者となることは、自分自身を完全に聖なるものと見なし、罪人を軽蔑することです。", "s": "別々に神聖"}, {"q": "祈った後，しばらく静かにして，聖文と聖霊を通して神が思い出されるのを待つことができます。", "s": "神を待つ"}, {"q": "「イエスを信じて豊かになる」という繁栄神学の言葉は，聖書の真理と一致しています。", "s": "成功神学"}, {"q": "クリスチャンの価値は，ほかの人がわたしたちに下す裁きと賛美によって測られるべきです。", "s": "価値基準"}, {"q": "レッスン13とレッスン16と併せて、聖別された生活を送る実践のいくつかの側面は何ですか？説明してください。", "s": "聖化エクササイズ"}, {"q": "レッスン22とレッスン26に関連して，クリスチャンは苦しみの中で信仰をどのように実践すべきでしょうか。", "s": "苦しみに対する生きる信仰"}]}, "ko": {"title": "성화의 삶 3부 복습", "content": "성화 생활 주제 검토: 거룩함이 하나님께 속하도록 기도하고, 주님께 더 가까이 다가가기 위한 영적 헌신을 위해 기도하며, 고통 속에서 하나님의 동반과 위로를 경험하고, 여러분이 빛과 소금으로 믿는 진리를 실천하십시오. 성화의 길에서 주님께 승리하고, 일탈하지 않고 평생을 따라가기를 바랍니다.", "instructions": "", "guide": [], "quizzes": [{"q": "[Scripture Fill in the Blank] 그러므로 당신은 반드시 ________ 하나님, 당신은 반드시 _____________________________________________________________________________", "s": "순종과 저항"}, {"q": "[Scripture Fill in the Blank] 기도, ________ 및 ________ 을 통해 원하는 것을 하나님 께 말하면 ________ 은 (는) 없어야합니다.", "s": "위탁 & 기도"}, {"q": "[Scripture Fill in the Blank] 내 안에 ________ 이 (가) 있고, 세상에 ________ 이 (가) 있지만, ________ 할 수 있습니다. 내가 세상을 이겼습니다.", "s": "주님 안의 평화"}, {"q": "[Scripture Fill in the Blank] 이 ________ 을 (를) 따르지 마세요. 마음이 새로워지고 ________, 하나님의 선하심, 순수하심, 기쁨이 무엇인지 확인하세요 ________", "s": "마인드 업데이트"}, {"q": "구원은 끝이 아니라 ________ 이며, 우리는 예수님을 주님으로 부르기로 결심한 날부터 승리하는 삶을 사는 법을 배워야 합니다.", "s": "승리의 출발점"}, {"q": "성화는 깊은 산속에 숨어 군중을 멀리하는 것이 아니라 ________ 세상에서 나와 하나님께 속하고 진리를 따라 사는 것입니다.", "s": "별도로 거룩함"}, {"q": "기도는 풍부하며, 기도 외에도 자신만을 위한 것이 아니라 찬양, 감사, 중보, ________ 등이 포함됩니다.", "s": "기도 내용"}, {"q": "영적 연습은 성경 공부와 같지 않습니다. 영적 연습은 매일 하나님께 나아오는 ________ 관계이며, 성경 공부는 전체 성경을 체계적으로 이해하는 것입니다.", "s": "영적 정수"}, {"q": "성경적 진리의 관점에서 볼 때, 모든 고통의 뿌리는 ________ 관계의 붕괴이며, 하나님의 사랑은 이 관계를 회복하는 뿌리입니다.", "s": "고통의 뿌리"}, {"q": "하나님께서는 오늘날 세상의 죄를 즉시 심판하시는 것이 아니라 ________ 부터 심판하십니다. 오늘날도 복음이 전파되는 은혜의 시대입니다.", "s": "하나님의 관용"}, {"q": "이 동영상은 ________ 을 (를) 할 수 있음을 강조합니다. 하나님의 계시된 진리가 아닌 것을 더 많이 행하는 것은 하나님의 뜻이 아닙니다.", "s": "진정한 지혜의 수련"}, {"q": "이 수업에 따르면, ''각각 거룩함'' 의 가장 정확한 의미는 무엇인가?", "s": "별도로 거룩함", "o": "A.세속적인 경작을 피하고 군중으로부터 혼자 살기,B.세상과 동떨어져 하나님께 속하여 성경의 진리에 따라 살아가고 증언함,C.다른 사람들보다 더 거룩하고 우월하다고 여김,D.더 많은 종교 규칙과 의식을 따르십시오"}, {"q": "이 수업에서 가르치는 기도의 중심 의미는 무엇인가?", "s": "기도의 본질", "o": "A.하나님께 해야 할 일을 말씀드리고 그분을 상기시키십시오,B.멋진 단어로 경전 암송하기,C.하나님의 자녀들이 진심으로 하나님 아버지께 와서 이야기함,D.기도로 하나님의 마음을 바꾸기"}, {"q": "이 교훈에 따르면, 하나님은 고난의 문제를 어떻게 다루시는가?", "s": "신성한 지본", "o": "A.소방관처럼 통화 중 발생하는 표면적 문제 해결,B.근본 원인 치료: 외동아이를 개인적으로 고통받게 하고, 하나님과 인간의 관계를 회복시키며, 생명을 새롭게 한다.,C.모든 고통 제거,D.누군가가 자신의 불행 속에서 죽도록 내버려두는 것"}, {"q": "이 교훈에 따르면, ''이 세상에서 백 번'' 의 ''백 번'' 은 주로 무엇을 의미하는가?", "s": "진정한 의미의 100배", "o": "A.돈과 물질적 상품에 대한 100배의 수익률,B.생명의 성숙이 가져다주는 풍요로움,C.손주와 번성하는 가족,D.장수, 건강"}, {"q": "이 수업에 따르면, 하나님께서 극복하기 위해 우리에게 주신 자원에는 어떤 것들이 있는가? (복수 선택)", "s": "승리 자원", "o": "A.사람으로서 행동하기 위한 기준을 제시하는 성경,B.성령은 우리 안에 거하시며, 끊임없이 우리에게 업데이트하라고 일깨워 주십니다.,C.인간은 자유 의지를 사용하여 하나님에 대한 순종을 선택합니다.,D.나만의 의지력으로 이를 악물어 보세요"}, {"q": "기도에 대한 수업에는 무엇이 포함되는가? (복수 선택)", "s": "기도 내용", "o": "A.칭찬,B.감사,C.중보 기도,D.자신의 필요를 위해서만 기도하십시오"}, {"q": "이 교훈에 따르면, 하나님께서 모든 죄를 즉시 심판하지 않으신 이유 중 몇 가지가 있는가? (복수 선택)", "s": "하나님의 관용", "o": "A.하나님은 죄를 묵인하십니다,B.신은 그 사실을 잊어버렸다.,C.하나님은 관대하십니다. 사람들에게 하나님을 알기 위해 돌아갈 수 있는 기회를 주십니다.,D.오늘날은 여전히 복음이 널리 전파된 은혜의 시대입니다."}, {"q": "이 수업에서 가르치는 그리스도인의 삶에서 성령의 역사에 포함되는 것은 무엇인가? (복수 선택)", "s": "성령 역사", "o": "A.허슬,B.감동적인 위로,C.격려 없음,D.아무 생각 없이 우리를 위해 결정을 내리세요"}, {"q": "따로따로 거룩하다는 것은 자신을 완전히 거룩하고 우월하다고 여기고 죄인을 경멸하는 것입니다.", "s": "별도로 거룩함"}, {"q": "기도를 마친 후, 우리는 잠시 동안 조용히 있을 수 있으며, 하나님께서 경전과 성신을 통해 우리를 일깨워 주실 때까지 기다릴 수 있습니다.", "s": "하나님을 기다리는 것"}, {"q": "“예수를 믿고 부자가 되라” 는 번영신학의 진술은 성경적 진리와 일치한다.", "s": "성공회 신학"}, {"q": "그리스도인의 가치는 다른 사람들이 우리에게 주는 판단과 칭찬에서 측정되어야 합니다.", "s": "가치 기준"}, {"q": "제13과와 제16과를 병행하여 성화된 삶을 살기 위한 실천의 측면에는 어떤 것이 있습니까? 설명해 주십시오.", "s": "성화 운동"}, {"q": "제22과 및 제26과와 관련하여 그리스도인은 고통 속에서 어떻게 신앙을 실천해야 하는가?", "s": "고통에 대한 살아있는 신앙"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791216453772','基要真理','回顾四·教会生活篇','教会是神呼召的生命共同体，基督的身体。本篇复习洗礼圣餐、加入教会、服事与生命、属灵恩赐四课，帮你建立正确的教会观，在配搭服事中让生命被神塑造。各尽其职，建立基督的身体。','[{"type": "verse", "q": "【经文填空】所以，你们要去，使万民作我的________，奉父、子、________的名给他们施洗。", "o": "《马太福音》28章19节", "s": "大使命", "a": "门徒|圣灵"}, {"type": "verse", "q": "【经文填空】所以弟兄们，我以神的________劝你们，将身体________，当作活祭。", "o": "《罗马书》12章1节", "s": "献上活祭", "a": "慈悲|献上"}, {"type": "verse", "q": "【经文填空】所以，你们或________或喝，无论做什么，都要为________神而行。", "o": "《哥林多前书》10章31节", "s": "荣耀神而行", "a": "吃|荣耀"}, {"type": "verse", "q": "【经文填空】你们也是如此，既是切慕属灵的________，就当求多得________教会的恩赐。", "o": "《哥林多前书》14章12节", "s": "造就教会", "a": "恩赐|造就"}, {"type": "fill", "q": "圣经明定的圣礼只有两项：受洗和________，其余是教会传统中人加上去的。", "o": "", "s": "两大圣礼", "a": "圣餐"}, {"type": "fill", "q": "十字架上的强盗未经受洗仍蒙主应许，证明得救在于________，而不在仪式。", "o": "", "s": "得救在乎信", "a": "信心"}, {"type": "fill", "q": "社团以________结合，教会是以属灵新生命结合的生命共同体。", "o": "", "s": "生命共同体", "a": "兴趣"}, {"type": "fill", "q": "主日崇拜重在________真理，团契小组重在学习活出真理，两者不可偏废。", "o": "", "s": "崇拜与团契", "a": "领受"}, {"type": "fill", "q": "那位整天泡在教会却不顾家庭的姐妹，牧者劝她回到________把母亲妻子的本分做好。", "o": "", "s": "全人服事", "a": "家里"}, {"type": "fill", "q": "看见弟兄有明显的罪却视而不见不是真爱，真爱是按真理________，把他从错误中带回来。", "o": "", "s": "爱心说诚实话", "a": "说诚实话"}, {"type": "fill", "q": "没有一个人有所有的恩赐，也没有一个人一样恩赐都________。", "o": "", "s": "人人有恩赐", "a": "没有"}, {"type": "single", "q": "对于尚未明白圣餐意义、还未信主的人，本课认为应当如何？", "o": "A.照样来领，好叫他蒙福,B.暂不领，先清楚所信再领,C.无所谓，想领就领,D.领了就能自动得救", "s": "圣餐的资格", "a": "B"}, {"type": "single", "q": "葛理翰牧师说“世界上没有完美的教会”，这句话主要想说明什么？", "o": "A.教会本来就是完美的,B.没有完美的教会，人加入后教会更不完美，要存接纳的心,C.所以不必加入教会,D.教会可有可无", "s": "接纳不完美", "a": "B"}, {"type": "single", "q": "以下哪项最符合本课所讲的服事观？", "o": "A.多做圣工，神就多给恩典,B.服事是神建造我们生命、改变我们品格的方法,C.只有讲台上的服事才蒙神记念,D.服事是展现个人才华的舞台", "s": "服事的意义", "a": "B"}, {"type": "single", "q": "关于说方言的恩赐，以下哪项说法正确？", "o": "A.会说方言是得救的记号,B.不会说方言就是没有得救,C.主权在神，是造就自己的恩赐，不是每人都需要,D.应该找人教自己说方言", "s": "方言恩赐", "a": "C"}, {"type": "multiple", "q": "关于受洗，以下哪些是本课所强调的正确观念？（多选）", "o": "A.这是主耶稣的吩咐，称他为主就当遵行,B.受洗者本人必须清楚所信,C.受洗是公开宣告与主同死同复活,D.水点到身上就自动得救", "s": "正确的受洗观", "a": "A|B|C"}, {"type": "multiple", "q": "在教会中受了伤，本课劝勉我们应当？（多选）", "o": "A.靠主再站起来,B.检讨自己，做在主面前,C.定睛于主的肯定，不被人的论断捆绑,D.立刻离开教会不再回来", "s": "受伤后站起", "a": "A|B|C"}, {"type": "multiple", "q": "在服事中眼光正确、不容易受伤的表现包括？（多选）", "o": "A.看重神在我身上的作为，而不是人怎么看我,B.在服事中学习被建造、被改变,C.计较自己做了多少、别人知不知道,D.把服事当成交换恩典的筹码", "s": "服事的眼光", "a": "A|B"}, {"type": "multiple", "q": "以下哪些符合圣经关于属灵恩赐的原则？（多选）", "o": "A.没有一个人有所有的恩赐,B.没有一个人一样恩赐都没有,C.每一个恩赐都一样重要,D.讲台上的恩赐比默默打扫的恩赐更大", "s": "恩赐的原则", "a": "A|B|C"}, {"type": "judge", "q": "婴儿受洗可以洗去原罪，圣经对此有明确的根据。", "o": "", "s": "婴儿洗", "a": "错"}, {"type": "judge", "q": "在网上看讲道节目，就可以完全取代参加教会的主日崇拜和团契生活。", "o": "", "s": "不可取代教会", "a": "错"}, {"type": "judge", "q": "每一项服事在神面前都是宝贵的，在厨房默默做饭与在讲台讲道一样重要。", "o": "", "s": "服事无分贵贱", "a": "对"}, {"type": "judge", "q": "恩赐有大小之分，站在讲台上教导的恩赐比默默打扫的恩赐更大。", "o": "", "s": "恩赐无大小", "a": "错"}, {"type": "essay", "q": "为什么说教会不是建筑物？基督徒为什么应当加入教会？请结合所学说明。", "o": "", "s": "教会观", "a": "教会按希腊文原意是神呼召出来的一批人，是属灵生命的集合体、基督的身体；教堂只是聚会的建筑物，两者不可混淆。加入教会是神的吩咐，也是神建造我们的重要途径：众圣徒恩赐不同，在基督身体里彼此建造、装备；与人的横向关系能更新生命，也反映纵向的与神关系。在教会中找到属灵的家，在爱中彼此建立、同奔天路。"}, {"type": "essay", "q": "请说明合乎圣经的服事观，以及属灵恩赐在服事中的正确运用。", "o": "", "s": "服事与恩赐", "a": "服事不是与神交换恩典的筹码，也不是展现个人才华的舞台；罗马书12章1节教导先将身体献上当作活祭，先成为被神更新的人，再自然活出正确的生命。恩赐是圣灵随己意分给各人的，没有人有全部恩赐，也没有人一样都没有；每个恩赐都一样重要，如身体器官彼此配搭。要存谦卑感恩的心竭力操练恩赐，用恩赐彼此建造、帮助别人成长，而非自我表演。"}]','','quiz','[]','','30','寇绍涵牧师•根基建造101','{"en": {"title": "IV. Review of Church Life", "content": "The church is a community of life called by God, the body of Christ. This section reviews the four lessons of the sacrament of baptism, joining the Church, service and life, and spiritual gifts to help you build a correct view of the Church and allow life to be shaped by God in tie-in service. Do your part to build up the body of Christ.", "instructions": "", "guide": [], "quizzes": [{"q": "[Scripture Fill in the Blank] Go ye therefore, and make all nations my ________, and baptize them in the name of the Father, and of the Son, and of the ________.", "s": "The Great Commission"}, {"q": "[Scripture Fill in the Blank] Therefore, brethren, I exhort you with the ________ of God to sacrifice the body ________ as a living sacrifice.", "s": "Offer a living sacrifice"}, {"q": "[Scripture Fill in the Blank] So, whether you are ________ or drinking, whatever you do, do it for ________ God.", "s": "Walk in the Glory of God"}, {"q": "[Scripture Fill in the Blank] The same is true of you. Since you are eager for the spiritual ________, you should seek to obtain more gifts from the ________ church.", "s": "Building the Church"}, {"q": "There are only two sacraments specified in the Bible: baptism and ________, and the rest are added by people in the church tradition.", "s": "Two Great Sacraments"}, {"q": "The robbers on the cross were promised by the Lord without being baptized, proving that salvation lay in ________ and not in rituals.", "s": "Salvation is about faith"}, {"q": "The community is united by ________, and the church is a community of life united by new spiritual life.", "s": "Community of Life"}, {"q": "Sunday worship focuses on the truth of ________, and fellowship groups focus on learning and living the truth. Both should not be prejudiced.", "s": "Worship & Fellowship"}, {"q": "The sister who spent all day in the church but ignored the family, the pastor advised her to return to ________ to do her duty as a mother''s wife.", "s": "Whole-person service"}, {"q": "Seeing that the brother has obvious sins but ignores it is not true love. True love is to bring him back from his mistakes according to the truth ________.", "s": "Love Speaks Honestly"}, {"q": "No one person has all the gifts, and no one has the same gifts as ________.", "s": "Everyone has a gift"}, {"q": "What do you think the lesson should be for those who have not yet understood the meaning of the sacrament and who are not yet believers?", "s": "Eligibility for the Eucharist", "o": "A.I will collect it as it is, so that he can be blessed.,B.If you don''t want to receive it for the time being, first clear your belief and then,C.It doesn''t matter, I want to claim it,D.Receive it and you will be automatically rescued"}, {"q": "What does Pastor Graham mean when he says, “There is no perfect church in the world”?", "s": "Embrace imperfections", "o": "A.The church is perfect.,B.There is no perfect church, people join the church is more imperfect, to be accepting of the heart,C.so you don''t have to join the church.,D.Churches may or may not"}, {"q": "Which of the following best fits the concept of service taught in this lesson?", "s": "The Meaning of Service", "o": "A.Do more sacred work and God will give more grace,B.Serving is God''s way of building our lives and changing our character,C.Only the service on the podium is remembered by God,D.Serving is a stage for personal talent"}, {"q": "Which of the following statements is true about the gift of speaking in tongues?", "s": "Gift of tongues", "o": "A.Speaking in tongues is a sign of salvation,B.Not speaking in tongues means not being saved,C.Sovereignty is in God, it is a gift to build oneself, not everyone needs it,D.Someone should teach you to speak in tongues"}, {"q": "Which of the following is the correct concept of baptism emphasized in this lesson? (Multiple choice)", "s": "Correct view of baptism", "o": "A.This is the commandment of the Lord Jesus, call him Lord and do it,B.The person being baptized must clearly believe,C.Baptism is the public proclamation of death and resurrection with the Lord,D.When the water reaches the body, it is automatically saved"}, {"q": "Injured in the Church, does this lesson exhort us to? (Multiple choice)", "s": "Stand Up After Injury", "o": "A.Stand up again, leaning on the Lord,B.Review yourself and be in the presence of the Lord,C.Focus on the Lord''s affirmation, not being bound by human judgment,D.Leave the church immediately and don''t come back"}, {"q": "Examples of right-eyed and less vulnerable performance in ministry include? (Multiple choice)", "s": "A Servant''s Eye", "o": "A.Value what God does in me, not what people think of me,B.Learning to be built and transformed in service,C.Consider how much you have done, and whether others know it,D.Treat service as a bargaining chip for grace"}, {"q": "Which of the following is consistent with biblical principles about spiritual gifts? (Multiple choice)", "s": "The Principle of Gift", "o": "A.No one person has all the gifts,B.No one has the same gifts as you.,C.Every gift counts,D.The gifts on the podium are greater than the gifts of silent cleaning."}, {"q": "The Bible has a clear basis for the fact that infant baptism can wash away original sin.", "s": "Baby wash"}, {"q": "Watching a sermon online can completely replace attending church Sunday worship and fellowship.", "s": "Irreplaceable Church"}, {"q": "Every service is precious before God, and silent cooking in the kitchen is as important as preaching from the pulpit.", "s": "Serve nothing noble and lowly"}, {"q": "The gifts are great and small, and the gifts taught from the pulpit are greater than the gifts of silent cleansing.", "s": "Gift without size"}, {"q": "Why is the church not a building? Why should Christians join the church? Please combine with the instructions you have learned.", "s": "Ecclesiastical Pers"}, {"q": "Explain the concept of biblical service and the proper use of spiritual gifts in service.", "s": "Service and gifts"}]}, "ja": {"title": "IV.教会生活の復習", "content": "教会は，キリストのからだである神によって召された命の共同体です。このセクションでは，バプテスマの秘跡，教会への参加，奉仕と生活，霊的な賜物の4つのレッスンを復習して，教会についての正しい見方を築き，人生を神が結びつけて奉仕することによって形作ることができるようにします。キリストのからだを築くために，自分の役割を果たしてください。", "instructions": "", "guide": [], "quizzes": [{"q": "〔聖句の穴埋め〕したがって，行って，すべての国民をわたしの________とし，父と子と________の名によって彼らにバプテスマを授けなさい。", "s": "グレート・コミッション"}, {"q": "〔聖句の穴埋め〕したがって，兄弟たち，わたしは神の________をもって，身体________を生ける犠牲として犠牲にするよう勧めます。", "s": "生け贄を捧げる"}, {"q": "〔聖句の穴埋め〕したがって、あなたが________であろうと飲んでいようと、何をするにしても、________神のためにそれをしてください。", "s": "神の栄光の中を歩む"}, {"q": "〔聖句の穴埋め〕あなたも同じです。あなたは霊的な________を切望しているので、________教会からより多くの贈り物を得るように努めるべきです。", "s": "教会を建てる"}, {"q": "聖書にはバプテスマと________という2つの秘跡しか指定されておらず、残りは教会の伝統の人々によって追加されています。", "s": "2つの偉大な秘跡"}, {"q": "十字架上の強盗は，バプテスマを受けずに主から約束されたものであり，救いは儀式ではなく________にあることを証明しています。", "s": "救いとは信仰のことです"}, {"q": "共同体は________によって結ばれ，教会は新しい霊的生活によって結ばれた生活の共同体です。", "s": "コミュニティ・オブ・ライフ"}, {"q": "日曜日の礼拝は________の真理に焦点を当て、フェローシップグループは真理を学び、生きることに焦点を当てています。どちらも偏見を持つべきではありません。", "s": "崇拝と親睦"}, {"q": "教会で一日中過ごしたが家族を無視した姉妹である牧師は、母親の妻としての義務を果たすために________に戻るように勧めました。", "s": "まるまる貸切サービス"}, {"q": "兄弟が明らかな罪を持っているがそれを無視していることを見ることは真の愛ではありません。真の愛とは、真実________に従って彼を過ちから連れ戻すことです。", "s": "愛は正直に語る"}, {"q": "誰もすべての贈り物を持っておらず、誰も________と同じ贈り物を持っていません。", "s": "誰もが贈り物を持っています"}, {"q": "聖餐の意味をまだ理解しておらず，まだ信じていない人には，どのようなレッスンが必要だと思いますか。", "s": "聖体拝領の資格", "o": "A.彼が祝福されるように、私はそれをそのまま集めます。,B.とりあえず受け取りたくない場合は、まず自分の信念を明確にしてから,C.それは問題ではありません、私はそれを取得したいです,D.受け取ると自動的に救助されます"}, {"q": "グラハム牧師が「この世には完全な教会はない」と言うとき，何を意味するでしょうか。", "s": "不完全さを受け入れる", "o": "A.教会は完璧です。,B.完璧な教会はありません、人々は心を受け入れるために、教会に参加することはより不完全です,C.教会に参加する必要はありません。,D.教会は"}, {"q": "このレッスンで教えられた奉仕の概念に最も当てはまるのは，次のうちどれですか。", "s": "サービスの意味", "o": "A.もっと神聖な仕事をすれば、神はより多くの恵みを与えてくださる,B.奉仕することは，わたしたちの生活を築き，性格を変える神の方法です,C.表彰台での奉仕だけが神によって記憶されています,D.サービングは個人的な才能のためのステージです"}, {"q": "異言を話すという賜物について，次の記述のうち，正しいものはどれですか。", "s": "舌の贈り物", "o": "A.異言を話すことは救いのしるし,B.異言を話さないことは，救われないことを意味します,C.主権は神にあり、それは自分自身を構築するための贈り物であり、誰もがそれを必要とするわけではありません,D.誰かがあなたに異言を話すことを教えるべきです"}, {"q": "この課で強調されているバプテスマの正しい概念は，次のうちどれですか。（複数選択可）", "s": "バプテスマの正しい見方", "o": "A.これは主イエスの命令であり、彼を主と呼んでそれを行います,B.バプテスマを受ける人は，はっきりと信じなければなりません,C.バプテスマとは，主と共に死と復活を公に宣べ伝えることです,D.水が体に到達すると、自動的に保存されます"}, {"q": "教会で負傷したこのレッスンは、私たちに勧めていますか？ （複数選択可）", "s": "負傷後に立ち上がろう", "o": "A.再び立ち上がり，主に頼る,B.自分自身を振り返り，主の御前にいる,C.人間の裁きに縛られず，主の確信に焦点を当てる,D.すぐに教会を出て、戻ってこないでください"}, {"q": "ミニストリーにおける右目とそれほど脆弱でないパフォーマンスの例には、次のようなものがあります。（複数選択可）", "s": "従者の目", "o": "A.人々が私をどう思っているかではなく、神が私の中でなさることを大切にする,B.サービスで構築され、変革されることを学ぶ,C.あなたがどれだけのことをしたか、そして他の人がそれを知っているかどうかを考えてください,D.サービスを優雅さのための交渉のチップとして扱う"}, {"q": "次のうち，霊的な賜物に関する聖書の原則と一致するものはどれですか。（複数選択可）", "s": "贈り物の原則", "o": "A.誰もがすべての贈り物を持っているわけではありません,B.あなたと同じ才能を持っている人はいません。,C.すべてのギフトが重要です,D.表彰台上の贈り物は、サイレントクリーニングの贈り物よりも優れています。"}, {"q": "聖書には，幼児のバプテスマが原罪を洗い流すことができるという事実の明確な根拠があります。", "s": "ベビーウォッシュ"}, {"q": "オンラインで説教を見ることは，教会の日曜日の礼拝と親睦に完全に取って代わることができます。", "s": "かけがえのない教会"}, {"q": "すべてのサービスは神の前で貴重であり、台所での静かな料理は、説教壇から説教するのと同じくらい重要です。", "s": "高貴で卑しいものには何も仕えない"}, {"q": "贈り物は大きくても小さくても，説教壇から教えられる贈り物は，静かな清めの贈り物よりも大きいものです。", "s": "サイズなしのギフト"}, {"q": "教会が建物ではないのはなぜですか。クリスチャンが教会に加わるべき理由は何でしょうか。学習した手順と組み合わせてください。", "s": "Ecclesiastical Pers"}, {"q": "聖書の奉仕の概念と，奉仕における霊的な賜物の適切な使い方を説明します。", "s": "サービスと贈答品"}]}, "ko": {"title": "IV. 교회 생활의 검토", "content": "교회는 그리스도의 몸이신 하나님께서 부르신 생명의 공동체입니다. 이 섹션에서는 침례 성사의 네 가지 교훈, 교회 가입, 봉사 및 삶, 영적 은사를 검토하여 교회에 대한 올바른 견해를 구축하고 삶이 하나님에 의해 결합된 봉사에 의해 형성될 수 있도록 돕는다. 그리스도의 몸을 세우기 위해 여러분의 역할을 다하십시오.", "instructions": "", "guide": [], "quizzes": [{"q": "[Scripture Fill in the Blank] 그러므로 너희는 가서 모든 민족을 나의 것으로 삼아 아버지와 아들과 ________ 의 이름으로 침례를 베풀어라.", "s": "위대한 임무"}, {"q": "[Scripture Fill in the Blank] 그러므로 형제 여러분, 저는 하나님의 ________ (으) 로 여러분에게 산 제물로 몸을 ________ (으) 로 희생할 것을 권고합니다.", "s": "산 제물 바치기"}, {"q": "[Scripture Fill in the Blank] 따라서 ________ 이든, 술을 마시든, 무엇을 하든 ________ 하나님을 위해 하십시오.", "s": "하나님의 영광 속을 걸으십시오"}, {"q": "[Scripture Fill in the Blank] 여러분도 마찬가지입니다. 영적인 ________ 을 열망하기 때문에 ________ 교회에서 더 많은 은사를 받으려고 노력해야 합니다.", "s": "교회 세우기"}, {"q": "성경에 명시된 성사는 세례와 ________ 두 가지뿐이며, 나머지는 교회 전통의 사람들이 추가합니다.", "s": "두 개의 위대한 성사"}, {"q": "십자가에 달린 강도들은 침례를 받지 않고 주님께서 약속하셨으며, 구원이 의식에 있지 않고 ________ 에 있음을 증명했습니다.", "s": "구원은 믿음에 관한 것입니다"}, {"q": "공동체는 ________ 에 의해 결합되며, 교회는 새로운 영적 삶으로 결합된 삶의 공동체입니다.", "s": "생명의 공동체"}, {"q": "주일 예배는 ________ 의 진리에 초점을 맞추고, 친교 그룹은 진리를 배우고 생활하는 데 중점을 둡니다. 둘 다 편견을 가져서는 안 됩니다.", "s": "예배 및 친교"}, {"q": "하루 종일 교회에서 시간을 보냈지만 가족을 무시했던 자매는 어머니의 아내로서의 의무를 다하기 위해 ________ (으) 로 돌아가라고 권고했습니다.", "s": "전인 서비스"}, {"q": "형제가 명백한 죄가 있지만 그것을 무시하는 것을 보는 것은 진정한 사랑이 아닙니다. 진정한 사랑은 ________ 진리에 따라 자신의 실수에서 그를 다시 데려 오는 것입니다.", "s": "사랑은 정직하게 말합니다"}, {"q": "아무도 모든 선물을 가지고 있지 않으며, 아무도 ________ 와 (과) 같은 선물을 가지고 있지 않습니다.", "s": "누구에게나 선물이 있습니다"}, {"q": "아직 성찬의 의미를 이해하지 못했고 아직 믿지 않는 사람들에게 이 교훈은 무엇이어야 한다고 생각하는가?", "s": "성체성사 자격 요건", "o": "A.있는 그대로 모아서 축복을 받을 수 있도록 하겠습니다.,B.당분간 받고 싶지 않다면 먼저 신념을 분명히 한 다음,C.상관없습니다. 청구하고 싶습니다.,D.수령하면 자동으로 구조됩니다."}, {"q": "그레이엄 목사가 “세상에 완벽한 교회는 없다” 고 말하는 것은 무엇을 의미하는가?", "s": "불완전함을 받아들이기", "o": "A.교회는 완벽합니다.,B.완벽한 교회는 없습니다. 교회에 가입하는 사람들은 마음을 받아들이는 것이 더 불완전합니다.,C.따라서 교회에 가입할 필요가 없습니다.,D.교회는 그럴 수도 있고 아닐 수도 있습니다."}, {"q": "다음 중 이 수업에서 가르치는 봉사의 개념에 가장 적합한 것은 무엇인가?", "s": "봉사의 의미", "o": "A.더 많은 성역을 행하면 하나님께서 더 많은 은혜를 베푸실 것입니다.,B.섬김은 하나님께서 우리의 삶을 세우시고 우리의 성품을 변화시키시는 방법입니다.,C.오직 단상에 있는 예배만이 하나님께서 기억하신다.,D.섬김은 개인적 재능을 위한 단계입니다"}, {"q": "다음 중 방언을 말하는 은사에 대한 설명으로 옳은 것은?", "s": "언어의 은사", "o": "A.방언을 말하는 것은 구원의 표시입니다,B.방언을 말하지 않는 것은 구원받지 못한다는 것을 의미합니다.,C.주권은 하느님 안에 있으며, 자신을 구축하기 위한 선물입니다. 모든 사람에게 필요한 것은 아닙니다.,D.누군가가 당신에게 방언을 말하는 법을 가르쳐야 합니다."}, {"q": "다음 중 이 수업에서 강조하는 침례의 올바른 개념은 무엇인가? (복수 선택)", "s": "침례에 대한 올바른 견해", "o": "A.이것이 주 예수님의 계명입니다. 그분을 주님이라 부르고 행하십시오.,B.침례를 받는 사람은 분명히 믿어야 합니다,C.침례는 주님과 함께하는 죽음과 부활을 공개적으로 선포하는 것입니다.,D.물이 몸에 닿으면 자동으로 저장됩니다."}, {"q": "교회에서 상처를 입은 이 교훈은 우리에게 권고하는가? (복수 선택)", "s": "부상 후 일어서기", "o": "A.주님께 의지하며 다시 일어서십시오.,B.자신을 돌아보고 주님의 면전에서 지내십시오.,C.인간의 판단에 얽매이지 않고 주님의 단언에 집중하십시오.,D.즉시 교회를 떠나 돌아 오지 마십시오."}, {"q": "사역의 오른쪽 눈과 덜 취약한 성과의 예는 다음과 같습니다. (복수 선택)", "s": "하인의 눈", "o": "A.사람들이 나를 어떻게 생각하는지가 아니라, 하나님이 내 안에서 하시는 일을 소중히 여겨라.,B.봉사를 통해 구축되고 변화되는 것을 배우는 것,C.당신이 얼마나 많은 일을 했는지, 그리고 다른 사람들이 그것을 알고 있는지 생각해보십시오.,D.봉사를 은혜를 위한 교섭의 장으로 여겨라"}, {"q": "다음 중 영적 은사에 관한 성경의 원리와 일치하는 것은 무엇인가? (복수 선택)", "s": "선물의 원리", "o": "A.아무도 모든 선물을 가지고 있지 않습니다,B.아무도 당신과 같은 선물을 가지고 있지 않습니다.,C.모든 선물은 소중합니다,D.단상의 선물은 조용한 청소의 선물보다 큽니다."}, {"q": "성경은 유아 세례가 원죄를 씻을 수 있다는 사실에 대한 명확한 근거를 가지고 있습니다.", "s": "베이비 워시"}, {"q": "온라인 설교를 시청하는 것은 교회 주일 예배 참석과 친교를 완전히 대체할 수 있습니다.", "s": "대체 불가능한 교회"}, {"q": "모든 예배는 하나님 앞에서 소중하며, 강단에서 설교하는 것만큼이나 주방에서 조용히 요리하는 것도 중요합니다.", "s": "고귀하고 비천한 것을 섬기지 말라"}, {"q": "은사는 크고 작으며, 강단에서 가르치는 은사는 조용한 정화의 은사보다 큽니다.", "s": "사이즈가 없는 선물"}, {"q": "왜 교회는 건물이 아닌가? 왜 그리스도인들이 교회에 가입해야 하는가? 학습한 지침과 결합하십시오.", "s": "교회 페르"}, {"q": "성경 봉사의 개념과 봉사에서 영적 은사의 적절한 사용에 대해 설명한다.", "s": "봉사 및 선물"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791216500875','基要真理','回顾五·争战与末世篇','属灵争战与末世盼望主题复习：认清撒旦与偶像的真相，穿戴神的全副军装打美好的仗；思想最后审判的真实、天堂地狱的永恒结局，以永恒的眼光活出今生的价值。','[{"type": "verse", "q": "【经文填空】明亮之星，早晨之子啊，你何竟从天________！你这攻败列国的，何竟被________在地上", "o": "《以赛亚书》14章12节", "s": "撒旦堕落", "a": "坠落|砍倒"}, {"type": "verse", "q": "【经文填空】所以，要拿起神所赐的________，好在磨难的日子________仇敌，并且成就了一切，还能站立得住", "o": "《以弗所书》6章13节", "s": "全副军装", "a": "全副军装|抵挡"}, {"type": "verse", "q": "【经文填空】因为他已经________日子，要藉着他所设立的人按________审判天下", "o": "《使徒行传》17章31节", "s": "审判之日", "a": "定了|公义"}, {"type": "verse", "q": "【经文填空】神为爱他的人所________的，是眼睛未曾看见，耳朵未曾________，人心也未曾想到的", "o": "《哥林多前书》2章9节", "s": "天堂预备", "a": "预备|听见"}, {"type": "verse", "q": "【经文填空】认识你________的真神，并且认识你所________的耶稣基督，这就是永生", "o": "《约翰福音》17章3节", "s": "永生真义", "a": "独一|差来"}, {"type": "fill", "q": "属灵军装中，信徒脚上当穿________预备走路的鞋，手中要拿________的藤牌，可以灭尽恶者一切的火箭。", "o": "", "s": "全副军装", "a": "平安福音|信德"}, {"type": "fill", "q": "基督徒落在难处中，按视频教导不要先到处找人赶鬼，而要先________下来，在神面前________自己有无得罪神之处。", "o": "", "s": "面对难处", "a": "安静|省察"}, {"type": "fill", "q": "将来审判全地的主是________宇宙的真神，审判的依据是________的启示，而不是人自己定的标准。", "o": "", "s": "审判真理", "a": "创造|圣经"}, {"type": "fill", "q": "彼得后书说，主看千年如一日，不愿一人沉沦，乃愿________都悔改得救。", "o": "", "s": "神愿人得救", "a": "万人"}, {"type": "fill", "q": "不认识神的老我生命活在________主义、功利主义、享乐主义中，以自我为中心。", "o": "", "s": "老我生命", "a": "本位"}, {"type": "single", "q": "基督徒打属灵争战时，最根本的得胜兵器是什么？", "o": "A.圣灵的宝剑，就是神的道,B.靠自己的意志力硬扛过去,C.花钱请人作法驱邪,D.逃避人群、与世隔绝", "s": "得胜兵器", "a": "A"}, {"type": "single", "q": "按视频所讲，人想靠行善“将功补过”在审判台前站立，这个想法错在哪里？", "o": "A.善事做得还不够多，再多做一点就行,B.行善只是人的本分不是功劳，而且标准是人自己定的,C.神不喜欢人行善，做好事没用,D.只有穷人才需要靠行善", "s": "将功补过", "a": "B"}, {"type": "single", "q": "为什么说“神不只预备天堂这个地方，还要预备进天堂的人”？", "o": "A.因为天堂的房间不够住，要扩建,B.因为生命不改变的人，即使在天堂也不会幸福,C.因为神喜欢热闹，人越多越好,D.因为天堂需要人去打扫维持", "s": "预备进天堂的人", "a": "B"}, {"type": "single", "q": "按视频所讲，“永生”从什么时候开始？", "o": "A.从人死亡那一刻开始,B.从人认识真神、接受救恩、生命被改变的今生就开始,C.从世界末日开始,D.从人年老退休开始", "s": "永生开始", "a": "B"}, {"type": "multiple", "q": "按视频所讲，基督徒面对苦难时正确的态度包括？（多选）", "o": "A.先安静下来，在神面前省察自己,B.把一切问题都归为鬼附，到处找人赶鬼,C.若省察后无罪，就安心倚靠主胜过,D.好吃懒做也说成是被鬼附", "s": "面对苦难", "a": "A|C"}, {"type": "multiple", "q": "按视频所讲，关于“最后的审判”，以下哪些认识是正确的？（多选）", "o": "A.审判者是创造宇宙的真神，不是人造的偶像,B.审判的原则按圣经启示，不是由人自定,C.人可以自己定标准、自己当裁判,D.神差儿子第一次来是为拯救，不是为审判", "s": "审判真理", "a": "A|B|D"}, {"type": "multiple", "q": "按视频所讲，关于天堂，以下哪些说法正确？（多选）", "o": "A.天堂是新天新地，没有眼泪、死亡和悲哀,B.进天堂靠的是外在善行功德的积累,C.神预备的不只是地方，更是预备好进入天堂的人,D.天堂的启示来自圣经，不是人悟道想出来的", "s": "天堂真理", "a": "A|C|D"}, {"type": "multiple", "q": "按视频所讲，哪些是对“永生”的错误看法？（多选）", "o": "A.把今世解决不了的问题通通往后丢的虚幻盼望,B.因今世过得不好而消极逃避的心灵转移,C.从今生就开始的生命特质的改变,D.死了以后才开始的漫长时间", "s": "永生误解", "a": "A|B|D"}, {"type": "judge", "q": "基督徒不必惧怕邪灵鬼怪，因为那在我们里面的比这世界更大。", "o": "", "s": "胜过惧怕", "a": "对"}, {"type": "judge", "q": "属灵争战中，圣经教导我们靠主胜过仇敌，而不是一味躲避。", "o": "", "s": "争战态度", "a": "对"}, {"type": "judge", "q": "神既是慈爱的就不会审判，所以人人最终都能进天堂。", "o": "", "s": "慈爱与公义", "a": "错"}, {"type": "judge", "q": "关于天堂地狱的真相，只有创造宇宙、超越时空的真神有资格告诉我们。", "o": "", "s": "启示来源", "a": "对"}, {"type": "judge", "q": "真正的得救只是参加过布道会、受过洗、加入教会这些外在经历。", "o": "", "s": "真假得救", "a": "错"}, {"type": "essay", "q": "视频说撒旦“昼夜控告”信徒，又说牠像“吼叫的狮子”遍地游行。请结合第20、21课内容，说明基督徒应当如何识破撒旦的诡计并靠主得胜？", "o": "", "s": "识破与得胜", "a": "撒旦的诡计有三：欺哄迷惑，让人怀疑神的话、拜偶像；昼夜控告，在神面前控告信徒、叫人自卑绝望；装作光明的天使，连算命说准过去都是牠的伎俩。基督徒得胜之道：穿戴神的全副军装，尤其拿起圣灵的宝剑就是神的道；亲近神、抵挡魔鬼，牠就必逃跑；落在难处先安静省察自己，不把一切都推给鬼附；牢记那在我们里面的比世界更大，不必惧怕。"}, {"type": "essay", "q": "为什么说“神是慈爱的，所以不会审判”是错误的？请结合神的属性说明审判与救恩的关系。", "o": "", "s": "审判与救恩", "a": "出埃及记34章启示神“有恩典、有怜悯，不轻易发怒”，但同时“断不以有罪的为无罪”。慈爱与公义是同一位神不可分割的属性：若神不审判罪恶，祂就不是圣洁公义的神。神解决这个张力的办法不是取消审判，而是差遣儿子为罪人付上代价——神差儿子第一次来不是为定罪，乃是为拯救。人若拒绝这白白的救恩，将来就要亲自面对白色大宝座的审判。审判显明神的圣洁，救恩显明神的慈爱，两者并行不悖。"}]','','quiz','[]','','31','寇绍涵牧师•根基建造101','{"en": {"title": "Review of the Fifth Battle and the Last Days", "content": "Spiritual warfare and eschatological hope Review: Recognize the truth of Satan and idols, wear God''s full armor and fight beautiful battles; think about the truth of the final judgment, the eternal end of heaven and hell, and live out the value of this life with eternal eyes.", "instructions": "", "guide": [], "quizzes": [{"q": "[Scripture Fill in the Blank] Bright Star, son of the morning, how can you be ________ from heaven! How can you, who defeated the nations, be ________ on the ground?", "s": "The Fall of Satan"}, {"q": "[Scripture Fill in the Blank] So, pick up the ________ given by God, so that in the days of tribulation, ________ enemies, and have achieved everything, can still stand", "s": "Full armor"}, {"q": "[Scripture Fill in the Blank] Because he has been ________ days, he will judge the world by ________ through the person he has set up.", "s": "Judgment Day"}, {"q": "[Scripture Fill in the Blank] What God has ________ for those who love Him is that the eyes have not seen, the ears have not ________, and the human heart has not thought of it.", "s": "Heaven Preparation"}, {"q": "[Scripture Fill in the Blank] To know the true God of your ________, and to know the Jesus Christ of your ________, is eternal life.", "s": "The Truth About Immortality"}, {"q": "In the spiritual uniform, believers should wear ________ shoes on their feet to prepare for walking. They should hold ________ rattan cards in their hands, which can exterminate all the rockets of the evil one.", "s": "Full armor"}, {"q": "Christians are in trouble, according to the video teaching not to find people everywhere to cast out demons first, but to ________ first come down and ________ whether they have sinned against God in front of God.", "s": "Facing difficulties"}, {"q": "In the future, the Lord of the whole earth will be the true God of the ________ universe, and the basis for judgment will be the revelation of ________, not the standard set by man himself.", "s": "Judgment of Truth"}, {"q": "2 Peter says, “The Lord saw a thousand years as one day, and would not that any should perish, but that all should repent and be saved.”", "s": "God''s desire for man to be saved"}, {"q": "The old me who does not know God lives in ________ doctrine, utilitarianism, and hedonism, and is self-centered.", "s": "Old My Life"}, {"q": "When Christians fight spiritual battles, what is the most fundamental weapon for victory?", "s": "Victory Weapon", "o": "A.The sword of the Holy Spirit is the Word of God,B.Carry it through with your own willpower,C.Spend money and ask people to exorcise evil,D.Escaping crowds, isolation"}, {"q": "According to the video, what is wrong with the idea that people want to “make up for the merits” by doing good and stand in front of the judgment table?", "s": "make amends for one&apos;s faults by good deeds", "o": "A.I haven''t done enough good deeds, just do a little more,B.Doing good is only human duty, not merit, and the standard is determined by man himself,C.God does not like people to do good things, it is useless to do good things,D.Only the poor need to do good"}, {"q": "Why is it said that \"God not only prepares this place for heaven, but also prepares those who go to heaven\"?", "s": "Those who prepare for paradise", "o": "A.Because there are not enough rooms in heaven, we need to expand,B.Because those who do not change their lives will not be happy even in heaven.,C.Because God likes to be lively, the more people the better,D.Because paradise needs people to clean and maintain"}, {"q": "According to the video, when does “immortality” begin?", "s": "Beginning of eternal life", "o": "A.From the moment a person dies,B.Beginning in this life when man knows the true God, receives salvation, and his life is transformed,C.From the end of the world,D.Beginning with old age and retirement"}, {"q": "According to the video, what are the correct attitudes of Christians in the face of suffering? (Multiple choice)", "s": "Facing Suffering", "o": "A.First, calm down and examine yourself before God.,B.Classify all problems as ghosts, and find people everywhere to drive out ghosts,C.If you are innocent after investigation, trust in the Lord with peace of mind.,D.Tasty and lazy work is also said to be possessed by ghosts"}, {"q": "According to the video, which of the following is true about the Last Judgment? (Multiple choice)", "s": "Judgment of Truth", "o": "A.The Judge is the true God of the universe, not an artificial idol.,B.The principle of judgment is inspired by the Bible, not determined by man.,C.People can set their own standards and be their own referee,D.God sent His Son for salvation for the first time, not for judgment."}, {"q": "According to the video, which of the following statements is true about heaven? (Multiple choice)", "s": "Heavenly Truth", "o": "A.Heaven is a new heaven and a new earth, without tears, death and sorrow,B.Entering heaven relies on the accumulation of external good deeds and virtues.,C.God prepares not only places, but also people who are ready to enter heaven.,D.Heaven''s revelation comes from the Bible, not from human enlightenment."}, {"q": "According to the video, what is the wrong view of “immortality”? (Multiple choice)", "s": "Immortal Misunderstanding", "o": "A.The illusory hope of passing the world''s unsolvable problems backwards,B.Negative escape mind shift due to bad life in this world,C.Changes in life traits from this life,D.The long time it took to start after death"}, {"q": "Christians need not fear evil spirits and ghosts, for that which is in us is greater than the world.", "s": "Better Than Afraid"}, {"q": "In spiritual warfare, the Bible teaches us to overcome our enemies by the Lord, not to hide from them.", "s": "Fighting Attitude"}, {"q": "Since God is loving, He does not judge, so that eventually everyone can go to heaven.", "s": "Compassion and justice"}, {"q": "Only the true God who created the universe and transcended time and space is qualified to tell us the truth about heaven and hell.", "s": "Source of Revelation"}, {"q": "True salvation is simply the outward experience of attending a sermon, being baptized, or joining a church.", "s": "True and False Saved"}, {"q": "The video says that Satan “accuses” believers day and night, and that he marches like a “roaring lion.” In conjunction with Lessons 20 and 21, how should Christians discern Satan''s schemes and prevail against the Lord?", "s": "Recognize and win"}, {"q": "Why is it wrong to say that God is loving and therefore does not judge? Explain the relationship between judgment and salvation in conjunction with God''s attributes.", "s": "Judgment and Salvation"}]}, "ja": {"title": "五番目の戦いと最後の日々の復習", "content": "霊的な戦いと終末論的な希望の復習：サタンと偶像の真理を認識し，神の完全な武具を身に着け，美しい戦いを戦う。最後の裁きの真理，天と地獄の永遠の終わりについて考え，永遠の目でこの人生の価値を生きる。", "instructions": "", "guide": [], "quizzes": [{"q": "〔聖句の穴埋め〕明るい星、朝の息子よ、どうしてあなたは天国から________になれるのですか！諸国の民を打ち負かしたあなたがたは，どうして地上で________することができようか。", "s": "サタンの堕落"}, {"q": "〔聖句の穴埋め〕だから、神から与えられた________を拾ってください。そうすれば、苦難の日に________の敵、そしてすべてを達成した敵は、まだ立ち上がることができます", "s": "フルアーマー"}, {"q": "〔聖句の穴埋め〕彼は________日経っているので、彼は彼が設定した人を通して________によって世界を判断します。", "s": "審判の日"}, {"q": "〔聖句の穴埋め〕神がご自分を愛する人々のために________持っておられることは、目は見ておらず、耳は________せず、人間の心はそれを考えていないということです。", "s": "天国の準備"}, {"q": "〔聖句の穴埋め〕あなたの________の真の神を知り，あなたの________のイエス・キリストを知ることは永遠の命です。", "s": "不死の真実"}, {"q": "霊的な制服では、信者は歩く準備のために足に________の靴を履くべきです。彼らは手に________の藤のカードを持っていなければなりません。これは邪悪なもののすべてのロケットを駆除することができます。", "s": "フルアーマー"}, {"q": "ビデオによると、クリスチャンはまず悪霊を追い出すためにどこにでもいる人を見つけるのではなく、まず________降りて、彼らが神の前で神に罪を犯したかどうかを________するようにと教えられています。", "s": "困難に直面する"}, {"q": "将来、全地の主は________宇宙の真の神であり、裁きの基礎は人間自身が定めた基準ではなく________の啓示である。", "s": "真理の裁き"}, {"q": "2ペテロは次のように述べています。「主は千年を一日のように見ておられ，だれも滅びることはなく，すべての人が悔い改めて救われることを望んでおられます。」", "s": "人が救われることを望む神の願い"}, {"q": "神を知らない年老いたわたしは， ________教義，功利主義，享楽主義の中に住み，自己中心的です。", "s": "オールド・マイ・ライフ"}, {"q": "クリスチャンが霊的な戦いを戦うとき，勝利のための最も基本的な武器は何ですか。", "s": "勝利の武器", "o": "A.聖霊の剣は神の言葉です,B.自分の意志でやり遂げる,C.お金を使い、人々に悪を追い払うように頼む,D.人混みからの脱出、孤立"}, {"q": "ビデオによると、人々が善を行い、判断テーブルの前に立つことによって「メリットを補う」ことを望むという考えは何が間違っているのでしょうか？", "s": "メリットを補償します", "o": "A.私は十分な善行をしていません、もう少しだけしてください,B.善を行うことは人間の義務であり、功績ではなく、基準は人間自身によって決定される,C.神は人々が良いことをするのを好まれない、良いことをするのは無駄である,D.貧しい人だけが良いことをする必要があります"}, {"q": "なぜ「神はこの場所を天国に備えておられるだけでなく、天国に行く者も備えておられる」と言われるのでしょうか。", "s": "楽園に備える者", "o": "A.天国には十分な部屋がないので、私たちは拡大する必要があります,B.なぜなら、自分の人生を変えない人は、天国でさえ幸せにはなれないからです。,C.神は生き生きとしているのが好きなので、人が多ければ多いほど良い,D.パラダイスには清掃とメンテナンスが必要だから"}, {"q": "ビデオによると、「不死」はいつ始まりますか？", "s": "永遠の命の始まり", "o": "A.人が死んだ瞬間から,B.人が真の神を知り、救いを受け、人生が変わるこの人生の始まり,C.世界の果てから,D.高齢と退職から始まる"}, {"q": "ビデオによると，苦しみに直面したクリスチャンの正しい態度は何ですか。（複数選択可）", "s": "苦しみに直面する", "o": "A.まず、落ち着いて、神の前で自分自身を調べてください。,B.すべての問題をゴーストとして分類し、ゴーストを追い払うためにあらゆる場所の人々を見つけます,C.調査後に無実であれば，安心して主を信頼してください。,D.美味しくて怠惰な仕事は、幽霊に取り憑かれているとも言われています"}, {"q": "ビデオによると、最後の審判について次のうちどれが正しいですか？ （複数選択可）", "s": "真理の裁き", "o": "A.審判者は宇宙の真の神であり、人工的な偶像ではありません。,B.裁きの原則は，人が決めるのではなく，聖書に触発されています。,C.人々は自分の基準を設定し、自分のレフェリーになることができます,D.神は御子を初めて救いのために遣わされたのであって，裁きのためではありません。"}, {"q": "ビデオによると，天について次の記述のうち，正しいものはどれですか。（複数選択可）", "s": "天の真理", "o": "A.天は新しい天と新しい地であり、涙、死、悲しみはありません,B.天国に入ることは、外的な善行と美徳の蓄積に依存しています。,C.神は場所だけでなく、天国に入る準備ができている人々も備えておられます。,D.天の啓示は聖書から来るのであって、人間の悟りから来るのではありません。"}, {"q": "ビデオによると、「不死」の間違った見方は何ですか？ （複数選択可）", "s": "不滅の者の誤解", "o": "A.世界の解決不可能な問題を逆行させる幻想的な希望,B.この世の悪い生活によるネガティブな脱出マインドシフト,C.この人生からの人生の特性の変化,D.死後に始まるまでにかかった長い時間"}, {"q": "クリスチャンは悪霊や幽霊を恐れる必要はありません。なぜなら、私たちの中にあるものは世界よりも大きいからです。", "s": "恐れよりも優れている"}, {"q": "霊的な戦いでは，聖書は敵から隠れるのではなく，主によって敵に打ち勝つように教えています。", "s": "ファイティング・アティテュード"}, {"q": "神は愛しておられるので、裁くことはないので、最終的には誰もが天国に行くことができます。", "s": "思いやりと正義"}, {"q": "宇宙を創造し、時間と空間を超越した真の神だけが、天国と地獄についての真実を伝える資格があります。", "s": "啓示の源"}, {"q": "真の救いとは，単に説教に出席したり，バプテスマを受けたり，教会に参加したりすることです。", "s": "正誤問題が保存されました"}, {"q": "ビデオには，サタンが信者を昼も夜も「告発」し，「咆哮する獅子」のように行進していると書かれています。レッスン20と21と併せて，クリスチャンはサタンの策略をどのように見分け，主に打ち勝つべきでしょうか。", "s": "認識し、勝つ"}, {"q": "神が愛しておられ，したがって裁かないと言うのはなぜ間違っているのでしょうか。神の特質に関連して，裁きと救いの関係を説明してください。", "s": "裁きと救い"}]}, "ko": {"title": "제5차 전투와 최후의 날 검토", "content": "영적 전쟁과 종말론적 희망 검토: 사탄과 우상의 진리를 인식하고, 하나님의 전신 갑주를 착용하고 아름다운 전투를 치르며, 천국과 지옥의 영원한 종말인 최후의 심판의 진리를 생각하고, 영원한 눈으로 이 생명의 가치를 실천하십시오.", "instructions": "", "guide": [], "quizzes": [{"q": "[Scripture Fill in the Blank] 밝은 별아, 아침의 아들아, 네가 어찌하여 하늘로부터 ________ 이 될 수 있느냐! 열방을 패배시킨 여러분이 어떻게 지상에서 ________ 이 (가) 될 수 있겠습니까?", "s": "사탄의 타락"}, {"q": "[Scripture Fill in the Blank] 그러므로 환난의 날에 ________ 명의 적들이 모든 것을 이룰 수 있도록 하나님께서 주신 ________ 을 (를) 집으십시오.", "s": "전체 갑옷"}, {"q": "[Scripture Fill in the Blank] 그는 ________ 일이 되었기 때문에, 그는 자신이 설정한 사람을 통해 ________ 에 의해 세상을 심판할 것입니다.", "s": "심판의 날"}, {"q": "[Scripture Fill in the Blank] 하느님께서 당신을 사랑하는 사람들에게 ________ 을 (를) 가지신 것은 눈은 보지 못했고, 귀는 ________ 을 (를) 보지 못했으며, 인간의 마음은 그것을 생각하지 못했다는 것입니다.", "s": "천국 준비"}, {"q": "[Scripture Fill in the Blank] ________ 의 참 하나님을 아는 것과 ________ 의 예수 그리스도를 아는 것은 영생입니다.", "s": "불멸에 대한 진실"}, {"q": "영적인 제복을 입은 신자들은 걸을 준비를 하기 위해 ________ 신발을 발에 신어야 합니다. 그들은 악마의 모든 로켓을 몰살시킬 수 있는 ________ 등나무 카드를 손에 쥐어야 합니다.", "s": "전체 갑옷"}, {"q": "비디오 가르침에 따르면 그리스도인들은 마귀를 먼저 쫓아낼 사람들을 사방에서 찾을 것이 아니라 먼저 내려와 하나님 앞에서 하나님께 죄를 지었는지 __________________________________________________________________________________________________________", "s": "어려움에 직면"}, {"q": "앞으로 온 땅의 주님은 ________ 우주의 참 하나님이 되실 것이며, 심판의 근거는 사람이 스스로 정한 기준이 아닌 ________ 의 계시가 될 것입니다.", "s": "진리의 심판"}, {"q": "베드로후서는 이렇게 말합니다. “주께서 천 년을 하루로 여기셨으니 아무도 멸망하지 않고 다 회개하여 구원을 얻기를 원하시느니라.”", "s": "인간이 구원을 받기를 원하시는 하나님의 소망"}, {"q": "하나님을 모르는 늙은이는 ________ 교리, 공리주의, 쾌락주의에 살고 자기중심적입니다.", "s": "Old My Life"}, {"q": "그리스도인들이 영적 전투를 벌일 때, 승리를 위한 가장 기본적인 무기는 무엇인가?", "s": "승리 무기", "o": "A.성령의 검은 하나님의 말씀이다,B.나만의 의지로 수행하세요,C.돈을 쓰고 사람들에게 악을 구제해 달라고 요청하세요.,D.인파를 피해 고립된 공간으로 떠나기"}, {"q": "비디오에 따르면, 사람들이 선을 행하고 심판대 앞에 서서 \"장점을 보완하고 싶다\" 는 생각에 무엇이 잘못 되었습니까?", "s": "장점에 대해 보상할 것입니다.", "o": "A.선행을 충분히 하지 못했습니다. 조금만 더 하세요,B.선을 행하는 것은 공로가 아닌 인간의 의무일 뿐이며, 그 기준은 인간이 스스로 결정한다.,C.하나님은 사람들이 선을 행하는 것을 좋아하지 않으시며, 선을 행하는 것은 쓸모가 없습니다.,D.가난한 사람만이 선을 행할 수 있습니다."}, {"q": "왜 “하나님께서는 이곳을 천국을 위해 준비하실 뿐만 아니라 천국에 가는 자들을 준비시키신다” 고 하였는가?", "s": "낙원을 준비하는 사람들", "o": "A.천국에 방이 충분하지 않기 때문에 확장해야 합니다.,B.인생을 바꾸지 않는 사람은 천국에서도 행복하지 않을 것이기 때문입니다.,C.하나님은 활기찬 것을 좋아하시기 때문에 사람이 많을수록 좋습니다.,D.파라다이스는 사람들이 청소하고 관리해야 하기 때문에"}, {"q": "동영상에 따르면 ''불멸'' 은 언제 시작되나요?", "s": "영생의 시작", "o": "A.사람이 죽는 순간부터,B.사람이 참 하느님을 알고, 구원을 받고, 그의 삶이 변화될 때 이 삶에서 시작됩니다.,C.세상 끝에서,D.노후와 은퇴를 시작으로"}, {"q": "동영상에 따르면, 고통에 직면한 그리스도인들의 올바른 태도는 무엇인가? (복수 선택)", "s": "고통에 직면하기", "o": "A.먼저 진정하고 하나님 앞에서 자신을 점검하십시오.,B.모든 문제를 유령으로 분류하고, 모든 곳에서 유령을 쫓아낼 사람들을 찾으세요.,C.조사 후 결백하다면, 안심하고 주님을 신뢰하십시오.,D.맛있고 게으른 일도 유령이 빙의한다고 합니다."}, {"q": "동영상에 따르면, 최후의 심판에 대해 다음 중 어느 것이 사실입니까? (복수 선택)", "s": "진리의 심판", "o": "A.심판자는 인위적인 우상이 아닌 우주의 참 하나님이십니다.,B.심판의 원리는 사람이 결정하는 것이 아니라 성경에서 영감을 받는다.,C.사람들은 자신의 기준을 설정하고 자신의 심판이 될 수 있습니다.,D.하나님께서는 심판을 위해서가 아니라 구원을 위해 당신의 아들을 처음으로 보내셨다."}, {"q": "동영상에 따르면, 다음 중 천국에 대한 설명으로 옳은 것은? (복수 선택)", "s": "하늘의 진리", "o": "A.하늘은 눈물과 죽음과 슬픔이 없는 새 하늘과 새 땅입니다.,B.천국에 들어가는 것은 외부의 선행과 덕의 축적에 달려 있습니다.,C.하나님께서는 장소뿐만 아니라 천국에 들어갈 준비가 된 사람들도 준비하십니다.,D.하늘의 계시는 인간의 깨달음이 아니라 성경에서 나옵니다."}, {"q": "비디오에 따르면, \"불멸\" 에 대한 잘못된 견해는 무엇입니까? (복수 선택)", "s": "불멸의 오해", "o": "A.세상의 해결할 수 없는 문제를 거꾸로 넘길 수 있다는 환상의 희망,B.이 세상의 나쁜 삶으로 인한 부정적인 탈출 마인드 시프트,C.이 삶에서 오는 삶의 특성의 변화,D.사망 후 시작까지 걸린 시간"}, {"q": "그리스도인은 악령과 유령을 두려워 할 필요가 없습니다. 우리 안에있는 것이 세상보다 큽니다.", "s": "두려워하는 것보다 낫다"}, {"q": "영적 전쟁에서 성경은 적들에게서 숨지 말고 주님에 의해 적을 이겨야 한다고 가르칩니다.", "s": "전투 태도"}, {"q": "하나님은 사랑이시므로 판단하지 않으시므로 결국 모든 사람이 천국에 갈 수 있습니다.", "s": "연민과 정의"}, {"q": "우주를 창조하시고 시공을 초월하신 참 하나님만이 천국과 지옥에 대한 진리를 알려주실 자격이 있습니다.", "s": "계시의 원천"}, {"q": "진정한 구원은 단순히 설교에 참석하거나 침례를 받거나 교회에 가입하는 외적인 경험입니다.", "s": "참 및 거짓 저장됨"}, {"q": "이 동영상은 사탄이 밤낮으로 신자들을 “고발” 하고 “우는 사자” 처럼 행진한다고 말합니다. 제20과 및 제21과와 관련하여 그리스도인들은 사탄의 계략을 어떻게 분별하고 주님을 대적하여 승리해야 하는가?", "s": "인정하고 승리하기"}, {"q": "하나님께서 사랑하셔서 판단하지 않으신다고 말하는 것이 왜 잘못된가? 심판과 구원의 관계를 하나님의 속성과 함께 설명한다.", "s": "심판과 구원"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220938384','圣经导览','创世记','创世记是圣经第一卷，记载宇宙万物的起源、人类的被造与堕落、洪水的审判，以及神拣选亚伯拉罕、以撒、雅各、约瑟建立选民的历史。本卷奠定全本圣经救赎计划的根基，预告女人的后裔将击败仇敌。','[{"type": "verse", "q": "【经文填空】________，神创造________。", "o": "《创世记》1章1节", "s": "起初创造", "a": "起初|天地"}, {"type": "verse", "q": "【经文填空】神就照着自己的________造人，乃是照着他的形象造________造________。", "o": "《创世记》1章27节", "s": "神的形象", "a": "形象|男|女"}, {"type": "verse", "q": "【经文填空】我又要叫你和女人彼此为仇；你的后裔和女人的后裔也彼此为仇。女人的后裔要伤你的________；你要伤他的________。", "o": "《创世记》3章15节", "s": "原始福音", "a": "头|脚跟"}, {"type": "verse", "q": "【经文填空】亚伯兰信________，耶和华就以此为他的________。", "o": "《创世记》15章6节", "s": "因信称义", "a": "耶和华|义"}, {"type": "verse", "q": "【经文填空】从前你们的意思是要________我，但神的意思原是________的，要保全许多人的性命，成就今日的光景。", "o": "《创世记》50章20节", "s": "神意美好", "a": "害|好"}, {"type": "verse", "q": "【经文填空】惟有________在耶和华眼前蒙________。", "o": "《创世记》6章8节", "s": "挪亚蒙恩", "a": "挪亚|恩"}, {"type": "verse", "q": "【经文填空】并且地上万国都必因你的________得________，因为你听从了我的话。", "o": "《创世记》22章18节", "s": "万国得福", "a": "后裔|福"}, {"type": "fill", "q": "神用六日创造天地，在第________日歇了他一切的工，安息了。", "o": "", "s": "安息日", "a": "七"}, {"type": "fill", "q": "耶和华神用地上的________造人，将生气吹在他鼻孔里，他就成了有灵的活人。", "o": "", "s": "尘土造人", "a": "尘土"}, {"type": "fill", "q": "亚当夏娃违命吃禁果后，耶和华神为他们用________做衣服给他们穿。", "o": "", "s": "皮衣之恩", "a": "皮子"}, {"type": "fill", "q": "该隐因嫉妒，在田间杀了他的兄弟________，成为人类历史上第一桩谋杀。", "o": "", "s": "该隐杀弟", "a": "亚伯"}, {"type": "fill", "q": "神吩咐挪亚用________木建造方舟，以躲避将临的洪水审判。", "o": "", "s": "歌斐木", "a": "歌斐"}, {"type": "fill", "q": "神呼召亚伯兰离开本地、本族、父家，往神所指示的________去。", "o": "", "s": "亚伯兰蒙召", "a": "地"}, {"type": "fill", "q": "雅各与神摔跤之后，神将他的名字改为________，意为与神与人较力都得了胜。", "o": "", "s": "雅各改名", "a": "以色列"}, {"type": "fill", "q": "约瑟在埃及被法老立为________，掌管全地的粮食，在饥荒中拯救了全家。", "o": "", "s": "约瑟掌权", "a": "宰相"}, {"type": "fill", "q": "耶和华神将亚当安置在________园中，使他修理看守。", "o": "", "s": "伊甸园", "a": "伊甸"}, {"type": "fill", "q": "亚伯拉罕的使女夏甲为他生的儿子名叫________，成为阿拉伯多国的祖先。", "o": "", "s": "以实玛利", "a": "以实玛利"}, {"type": "single", "q": "神看亚当独居不好，为他造了谁作配偶？", "o": "A.夏娃,B.利百加,C.撒拉,D.拉结", "s": "夏娃被造", "a": "A"}, {"type": "single", "q": "洪水之后，神与挪亚立约的记号是什么？", "o": "A.星星,B.方舟,C.彩虹,D.橄榄枝", "s": "彩虹之约", "a": "C"}, {"type": "single", "q": "亚伯拉罕献以撒时，神预备了什么代替以撒作燔祭？", "o": "A.公牛,B.公羊,C.绵羊羔,D.斑鸠", "s": "耶和华以勒", "a": "B"}, {"type": "single", "q": "约瑟被哥哥们卖到了哪里？", "o": "A.巴比伦,B.亚述,C.埃及,D.迦南", "s": "下埃及", "a": "C"}, {"type": "single", "q": "雅各共有几个儿子，成为以色列十二支派的先祖？", "o": "A.十个,B.十二个,C.十一个,D.十三个", "s": "十二支派", "a": "B"}, {"type": "single", "q": "亚伯拉罕离开哈兰、往迦南去的时候，年纪是多少？", "o": "A.七十五岁,B.一百年,C.九十九岁,D.一百二十岁", "s": "亚伯兰年岁", "a": "A"}, {"type": "single", "q": "雅各为了娶拉结，在拉班家一共服事了多少年？", "o": "A.七年,B.十四年,C.二十年,D.二十一年", "s": "雅各服事", "a": "B"}, {"type": "multiple", "q": "神按自己形象造人，赋予人哪些独特的地位？（多选）", "o": "A.按神形象被造，尊贵无比,B.管理海里的鱼、空中的鸟和地上的活物,C.能与神建立亲密的交通关系,D.与动物毫无区别", "s": "人的尊贵", "a": "A|B|C"}, {"type": "multiple", "q": "约瑟一生虽经历苦难却始终信靠神，包括以下哪些？（多选）", "o": "A.被哥哥们卖为奴隶,B.被诬陷下在监里,C.在监中仍为同囚解梦,D.一生顺利从未受苦", "s": "约瑟受苦", "a": "A|B|C"}, {"type": "multiple", "q": "神给亚伯拉罕的应许包括以下哪些？（多选）", "o": "A.后裔多如天上的星、海边的沙,B.将迦南全地赐给他的后裔为业,C.地上万国必因他的后裔得福,D.他本人长生不老", "s": "亚伯拉罕之约", "a": "A|B|C"}, {"type": "multiple", "q": "巴别塔事件显明了人性的哪些罪？（多选）", "o": "A.骄傲自大，想要传扬自己的名,B.违背神“遍满地面”的命令，不愿分散,C.妄想建塔通天，与神同等,D.彼此相爱、合一同心", "s": "巴别之罪", "a": "A|B|C"}, {"type": "judge", "q": "神在第七日歇了他一切创造的工，就安息了，并赐福给第七日。", "o": "", "s": "第七日安息", "a": "对"}, {"type": "judge", "q": "该隐因神看中亚伯的供物，就真心悔改认罪，神便赦免了他。", "o": "", "s": "该隐结局", "a": "错"}, {"type": "judge", "q": "巴别塔事件后，耶和华变乱了人的口音，使他们分散在全地上。", "o": "", "s": "巴别塔", "a": "对"}, {"type": "judge", "q": "以撒是亚伯拉罕一百岁、撒拉九十岁时所生的应许之子。", "o": "", "s": "以撒出生", "a": "对"}, {"type": "judge", "q": "约瑟作埃及宰相后，怀恨报复了当年出卖他的哥哥们。", "o": "", "s": "约瑟饶恕", "a": "错"}, {"type": "judge", "q": "挪亚在洪水未来之先按神吩咐造方舟，凡神所吩咐的，他都照样行了。", "o": "", "s": "挪亚顺服", "a": "对"}, {"type": "judge", "q": "以扫因一碗红豆汤卖了长子的名分，后来懊悔流泪也无法挽回。", "o": "", "s": "以扫卖长子", "a": "对"}, {"type": "essay", "q": "创世记3章15节为什么被称为“原始福音”？请说明其含义。", "o": "", "s": "原始福音", "a": "这是圣经中第一个关于救恩的应许。神在人犯罪堕落后立即宣告：女人的后裔要伤蛇的头，预言将来有一位救主（耶稣基督）要彻底击败撒但。虽然救主的脚跟要被蛇咬伤（预表十字架的受苦），但最终得胜的是女人的后裔。这显明神的救恩计划在人类堕落之初就已定下，救恩完全出于神的恩典和主动，人只需凭信心领受。"}, {"type": "essay", "q": "从约瑟的一生，我们可以学到哪些属灵功课？", "o": "", "s": "约瑟榜样", "a": "约瑟虽被哥哥出卖为奴、被主母诬陷下狱，却始终敬畏神、不肯犯罪，在苦难中经历神的同在。他作宰相后饶恕哥哥们，说“神的意思原是好的”。这教导我们：苦难中有神的美意；持守圣洁不向试探妥协；以善胜恶、饶恕得罪我们的人；相信神掌管一切，能将人的恶意化为祝福，成就祂的计划。"}, {"type": "essay", "q": "请说明约瑟的一生如何在多方面预表耶稣基督。", "o": "", "s": "约瑟预表基督", "a": "约瑟是旧约中最清楚预表基督的人物之一：他是父亲所爱的儿子，却被弟兄们恨恶、出卖（创37章），预表基督被自己的百姓弃绝；他无辜受苦，被下在监里，预表基督无罪却受死；他在监中升高，三十岁作埃及宰相，预表基督复活升天、作万王之王；饥荒中全家投靠他得存活，预表万民投靠基督得救恩；他饶恕出卖他的哥哥们，说“神的意思原是好的”，预表基督在十字架上赦免罪人。约瑟的经历显明：神能将人的恶意化为美意，成就祂救赎的计划。"}]','','quiz','[{"title": "创造（1-2章）", "points": ["神六日创造天地，第七日安息", "人按神的形象被造，管理全地", "设立婚姻：一男一女成为一体", "神看着一切所造的都甚好", "伊甸园：神将人安置其中修理看守", "分别善恶树：顺服的考验"]}, {"title": "堕落与审判（3-11章）", "points": ["亚当夏娃违命吃禁果，罪进入世界", "蛇的诡诈与人的推诿：罪性的显露", "神为亚当夏娃做皮衣——恩典的预表", "该隐杀亚伯；拉麦的狂傲", "洪水审判，惟挪亚一家八口蒙恩", "巴别塔：人因骄傲被分散全地"]}, {"title": "亚伯拉罕（12-25章）", "points": ["蒙召离开吾珥，应许后裔多如繁星", "因信称义：亚伯兰信耶和华算为义", "神改名亚伯兰为亚伯拉罕（多国之父）", "罗得迁往所多玛，亚伯拉罕代求", "献以撒：信心达到巅峰的考验", "以实玛利与以撒：血气与应许之子"]}, {"title": "以撒与雅各（25-36章）", "points": ["以撒娶利百加，承受亚伯拉罕之约", "雅各得长子名分，改名以色列", "伯特利天梯：神应许与雅各同在", "雅各服事拉班二十年，神使他昌大", "毗努伊勒摔跤：雅各被神摸了大腿窝", "生十二个儿子，成为十二支派先祖"]}, {"title": "约瑟（37-50章）", "points": ["彩衣与异梦：兄弟嫉妒的开端", "被卖埃及，为奴下狱仍持守圣洁", "在监中解梦，神与约瑟同在", "解法老之梦，升为埃及宰相", "预备粮食度过七年大饥荒", "饶恕兄弟：神的意思原是好的", "雅各全家下埃及，以色列成大族"]}]','','32','旧约•律法书（摩西五经）','{"en": {"title": "Genesis", "content": "Genesis is the first book of the Bible that records the origin of all things in the universe, the creation and fall of mankind, the judgment of the flood, and the history of God''s election of Abraham, Isaac, Jacob, and Joseph to establish the elect. This book lays the foundation for the entire biblical plan of redemption, foretelling that the offspring of women will defeat their enemies.", "instructions": "", "guide": [{"title": "Creation (Chapters 1-2)", "points": ["God created heaven and earth on the sixth day and rested on the seventh day.", "Man was created in the image of God to rule the whole earth", "Setting up a marriage: one man and one woman become one", "God sees that everything He has made is very good.", "Garden of Eden: God placed people in it to repair guards", "The Tree of Good and Evil: The Trial of Obedience"]}, {"title": "The Fall and the Judgment (chapters 3-11)", "points": ["Adam and Eve disobeyed their orders to eat the forbidden fruit, and sin entered the world.", "The Deceitfulness of the Serpent and the Pushback of Man: The Reveal of Sinfulness", "God made a leather garment for Adam and Eve - a sign of grace", "Cain kills Abel; Lamech''s madness", "The Judgment of the Flood, Venoah''s Family of Eight Receives Grace", "Tower of Babel: Pride scattered across the land"]}, {"title": "Abraham (12-25)", "points": ["Called to leave Ur, promising descendants as numerous as the stars", "Justification by Faith: Abram''s Belief in Jehovah Counts as Righteousness", "God renamed Abram Abraham (father of many nations)", "Lot moves to Sodom, Abraham intercedes", "Isaac: The Test of Faith at its Peak", "Ishmael and Isaac: Blood and the Son of Promise"]}, {"title": "Isaac and Jacob (25-36)", "points": ["Isaac marries Rebekah and inherits the Abrahamic covenant", "Jacob renamed Israel after his birthright", "Bethel ladder: God promises to be with Jacob", "Jacob served Laban for twenty years, and God made him great.", "Penuel wrestles: Jacob is touched by God in his thigh socket", "Born twelve sons, became ancestors of twelve tribes"]}, {"title": "Joseph (37-50)", "points": ["Colored Clothes and Different Dreams: The Beginning of Brotherly Jealousy", "Sold into Egypt, imprisoned for slavery, and still holy.", "Interpreting dreams in prison, God was with Joseph", "Solve Pharaoh''s dream and become Prime Minister of Egypt", "Preparing grain for seven years of famine", "Forgive the Brothers: God''s Meaning Is Good", "Jacob''s family descends to Egypt, and Israel becomes a great tribe."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] ________, God created ________.", "s": "Originally created"}, {"q": "[Scripture Fill in the Blank] God created man according to His ________, but in His image He created ________.", "s": "Image of God"}, {"q": "[Scripture Fill in the Blank] And I will make thee and the woman enemies one to another: and thy seed and the woman''s seed shall be enemies one to another. The seed of the woman shall hurt thy ________; thou shalt hurt his ________.", "s": "Primitive Gospel"}, {"q": "[Scripture Fill in the Blank] Abram believed ________, and the Lord made it his ________.", "s": "Justification by Faith"}, {"q": "[Scripture Fill in the Blank] In the past, you meant ________ me, but God meant ________, to save the lives of many people and achieve today''s situation.", "s": "Wonderful"}, {"q": "[Scripture Fill in the Blank] Only ________ is ________ before the eyes of the Lord.", "s": "Noamun"}, {"q": "[Scripture Fill in the Blank] And by thy ________ shall all the kingdoms of the earth be ________, because thou hast obeyed my voice.", "s": "Wanguo Delphi"}, {"q": "God created the heavens and the earth in six days, and rested from all his work on the ________ day.", "s": "Day of Repose"}, {"q": "The Lord God created man from the ________ of the earth, breathed life into his nostrils, and he became a living soul.", "s": "Dust man-made"}, {"q": "After Adam and Eve had eaten the forbidden fruit in disobedience, the Lord God made clothes for them to wear.", "s": "Leatherwear Grace"}, {"q": "Cain, out of jealousy, killed his brother ________ in the field, becoming the first murder in human history.", "s": "Cain kills his brother"}, {"q": "God commanded Noah to build the ark of ________ wood to escape the coming flood judgment.", "s": "Gofemu"}, {"q": "God called Abram to leave his homeland, his clan, and his father''s house and go to the ________ that God had instructed him to go to.", "s": "Abram called"}, {"q": "After Jacob wrestled with God, God changed his name to ________, meaning that he was victorious against both God and man.", "s": "Jacob renamed"}, {"q": "Joseph was made ________ by Pharaoh in Egypt, and ruled over the food of the whole land, and saved his family in famine.", "s": "Joseph in power"}, {"q": "The Lord God placed Adam in the garden of ________ to repair the guards.", "s": "Garden of Eden"}, {"q": "Hagar, Abraham''s maid, bore him a son named ________, and became the father of many Arab nations.", "s": "ishmael"}, {"q": "God saw that it was not good for Adam to live alone, and who did He make to be his spouse?", "s": "Eve was created", "o": "A.eve,B.rebekah,C.sarah,D.Rachel"}, {"q": "What is the sign of God''s covenant with Noah after the Flood?", "s": "The Rainbow Appointment", "o": "A.Star,B.Ark (override) takover,C.Rainbows,D.symbol of peace"}, {"q": "When Abraham offered Isaac, what did God prepare in place of Isaac as a burnt offering?", "s": "Jehovah Jireh", "o": "A.Gongniu&#x0D;,B.Gong Yang,C.Lamb,D.turtledove"}, {"q": "Where was Joseph sold by his brothers?", "s": "Lower Egypt", "o": "A.Babylon,B.assyria,C.Egypt,D.canaan"}, {"q": "How many sons did Jacob have who became the ancestors of the twelve tribes of Israel?", "s": "Twelve Tribes", "o": "A.Ten,B.twelve,C.11,D.thirteen"}, {"q": "How old was Abraham when he left Haran for Canaan?", "s": "Abram years old", "o": "A.Seventy-five,B.100 years,C.99 years old,D.120 years old"}, {"q": "How many years did Jacob serve in Laban''s household in order to marry Rachel?", "s": "Jacob''s ministry", "o": "A.Seven years,B.14 years,C.20 years,D.Twenty-one years"}, {"q": "What unique status did God give to man when He created him in His own image? (Multiple choice)", "s": "The dignity of man", "o": "A.Made in the Image of God, Exalted,B.Managing the fish of the sea, the birds of the air and the creatures of the earth,C.Able to establish an intimate relationship with God,D.Indistinguishable from animals"}, {"q": "Throughout his life, Joseph experienced hardship but always trusted God, including which of the following? (Multiple choice)", "s": "Joseph suffers", "o": "A.Sold as a slave by his brothers,B.Being framed in jail,C.Still dreaming for fellow inmates in prison,D.Smooth life, never suffering."}, {"q": "Which of the following are some of God''s promises to Abraham? (Multiple choice)", "s": "The Abrahamic Covenant", "o": "A.The descendants are as numerous as the stars in the sky and the sand by the sea.,B.to give all the land of Canaan to his descendants for an inheritance.,C.All nations on earth will be blessed by his descendants,D.He himself is immortal"}, {"q": "What sins of humanity did the Tower of Babel events reveal? (Multiple choice)", "s": "The Sins of Babel", "o": "A.Proud and arrogant, wanting to promote his name,B.Disobeying God''s command to “fill the earth”, unwilling to disperse,C.Delusion of building a tower to connect the heavens, equal to God,D.Love each other and unite as one"}, {"q": "And God rested on the seventh day from all his creative work, and blessed the seventh day.", "s": "Seventh Day Sabbath"}, {"q": "And Cain sincerely repented and confessed his sins, because God looked upon Abel''s offering, and God forgave him.", "s": "The Clandestine Outcome"}, {"q": "After the events of the tower of Babel, the Lord changed the accent of the people and scattered them over the whole earth.", "s": "Tower of Babel"}, {"q": "Isaac was the promised son of Abraham at the age of one hundred and Sarah at the age of ninety.", "s": "Isaac was born"}, {"q": "After Joseph became Prime Minister of Egypt, he took revenge on his brothers who had betrayed him.", "s": "Joseph Forgive"}, {"q": "Noah made the ark before the flood, as God had commanded him; and he did all that God had commanded him.", "s": "Noah obeyed"}, {"q": "Esau sold the title of the eldest son for a bowl of red bean soup, and later repented and wept irretrievably.", "s": "Esau sells his eldest son"}, {"q": "Why is Genesis 3:15 called the “primitive gospel”? Please explain what it means.", "s": "Primitive Gospel"}, {"q": "What spiritual lessons can we learn from Joseph''s life?", "s": "Joseph''s example"}, {"q": "Explain how Joseph''s life represented Jesus Christ in many ways.", "s": "Joseph prefigured Christ"}]}, "ja": {"title": "ジェネシス", "content": "創世記は，宇宙の万物の起源，人類の創造と堕落，洪水の裁き，神が選民を確立するためにアブラハム，イサク，ヤコブ，ヨセフを選ばれた歴史を記録した聖書の最初の書です。この本は、聖書の贖いの計画全体の基礎を築き、女性の子孫が敵を打ち負かすことを予言しています。", "instructions": "", "guide": [{"title": "創造（第1章から第2章）", "points": ["神は六日目に天と地を創造し、七日目に休まれました。", "人は全地を支配するために神のかたちに創造された", "結婚の準備：一人の男性と一人の女性が一つになる", "神は，ご自分が造られたすべてのものが非常に良いものであることを見ておられます。", "エデンの園：神は警備員を修理するために人々をそこに入れました", "善悪の樹：従順の試練"]}, {"title": "堕落と裁き（ 3 － 11章）", "points": ["アダムとエバは禁断の果実を食べるという命令に従わず、罪が世に入りました。", "蛇の欺瞞と人間の押し返し：罪の啓示", "神はアダムとイブのために革の衣服を作った-恵みのしるし", "カインがアベルを殺す；レメクの狂気", "洪水の審判、ヴェノアの8人家族が恩寵を受ける", "バベルの塔：国中に散らばるプライド"]}, {"title": "アブラハム（ 12 － 25歳）", "points": ["ウルを去るために召喚され、星のように数多くの子孫を約束しました", "信仰による義認：エホバを信じるアブラムの信仰は義とみなされる", "神はアブラハムをアブラハム（多くの国民の父）と改名された", "ロトはソドムに向かい、アブラハムはとりなしをする", "アイザック：信仰の頂点での試練", "イシュマエルとイサク：血と約束の子"]}, {"title": "イサクとヤコブ（ 25 － 36歳）", "points": ["イサクはレベッカと結婚し、アブラハムの聖約を受け継ぎます", "ヤコブは生まれながらの権利を受けてイスラエルと改名した", "ベテルのはしご：神はヤコブと共におられると約束されています", "ヤコブはラバンに20年間仕えましたが、神は彼を大いなる者とされました。", "ペニュエルの格闘：ジェイコブは太もものソケットで神に触れられている", "12人の息子が生まれ、12部族の祖先となりました"]}, {"title": "ジョセフ（ 37 － 50歳）", "points": ["色とりどりの衣服と異なった夢：兄弟愛の嫉妬の始まり", "エジプトに売られ、奴隷として投獄され、今も聖なるものとされています。", "獄中で夢を解釈すると，神はヨセフと共におられた", "ファラオの夢を解き明かし、エジプトの首相になろう", "7年間の飢饉に備えて穀物を準備する", "兄弟たちを赦す：神の意味は良い", "ヤコブの家族はエジプトに下り，イスラエルは大きな部族になりました。"]}], "quizzes": [{"q": "〔聖句の穴埋め〕________、神は________を創造しました。", "s": "もともと作成された"}, {"q": "〔聖句の穴埋め〕神はご自分の________に従って人を創造されましたが，ご自分のかたちに________を創造されました。", "s": "神の画像"}, {"q": "〔聖句の穴埋め〕わたしはあなたと女とを互いに敵とし、あなたの子孫と女の子孫とは互いに敵となるであろう。女の子孫はあなたの________を傷つけ、あなたは彼の________を傷つけるであろう。", "s": "原始的な福音"}, {"q": "〔聖句の穴埋め〕アブラムは________を信じ，主はそれを________とされました。", "s": "信仰による義認"}, {"q": "〔聖句の穴埋め〕過去には、あなたは________私を意味していましたが、神は多くの人々の命を救い、今日の状況を達成するために________を意味していました。", "s": "素晴らしい"}, {"q": "〔聖句の穴埋め〕主の目の前にあるのは________だけです。", "s": "ノアムン"}, {"q": "〔聖句の穴埋め〕あなたがわたしの声に聞き従われたので、地上のすべての王国はあなたの________によって________となるであろう。", "s": "ワングオ・デルファイ"}, {"q": "神は6日間で天と地を創造し、________日にすべての働きから休まれました。", "s": "安息日"}, {"q": "主なる神は，地の________から人を創造し，その鼻孔に命を吹き込み，生ける霊魂となられました。", "s": "人工の粉塵"}, {"q": "アダムとエバが不従順に禁断の果実を食べた後，主なる神は彼らが着る服を作られました。", "s": "レザーウェアグレイス"}, {"q": "カインは嫉妬から兄________を現場で殺害し、人類史上初の殺人事件となりました。", "s": "カインが弟を殺す"}, {"q": "神はノアに，来る洪水の裁きを逃れるために________木の箱舟を建てるよう命じました。", "s": "ゴフェム"}, {"q": "神はアブラムを呼び出して，自分の故郷，一族，父の家を離れ，神が指示された________に行くようにと言われました。", "s": "アブラムから電話がありました"}, {"q": "ヤコブが神と格闘した後、神は彼の名前を________に変更しました。これは、彼が神と人間の両方に勝利したことを意味します。", "s": "ヤコブは名前を変更しました"}, {"q": "ヨセフはエジプトでファラオによって________とされ，全地の食物を支配し，飢饉の中で家族を救いました。", "s": "権力の座にあるジョセフ"}, {"q": "主なる神は，衛兵を修理するために，アダムを________の園に置かれました。", "s": "エデンの園"}, {"q": "アブラハムのメイドであるハガルは、彼に________という名前の息子を産み、多くのアラブ諸国の父となりました。", "s": "イシュマエル"}, {"q": "神はアダムが一人暮らしをするのは良くないことを見ておられ，だれを配偶者にされたのでしょうか。", "s": "イブが創造された", "o": "A.エバ,B.リベカ,C.サラ,D.ラケル"}, {"q": "洪水後のノアとの神の契約のしるしは何ですか。", "s": "レインボーアポイントメント", "o": "A.スター,B.箱船，ひつ，箱,C.虹,D.オリーブの枝"}, {"q": "アブラハムがイサクをささげたとき，神は全焼のいけにえとしてイサクの代わりに何を備えられましたか。", "s": "エホバジレ", "o": "A.雄牛，牛,B.牡羊,C.子羊,D.やまばと"}, {"q": "ジョセフは兄弟たちにどこで売られましたか。", "s": "ロウアー・エジプト", "o": "A.バビロン,B.アッシリア,C.エジプト,D.カナン"}, {"q": "イスラエルの十二部族の先祖となったヤコブには，何人の息子がいましたか。", "s": "12部族", "o": "A.10,B.12,C.イレブン,D.13"}, {"q": "アブラハムがハランを離れてカナンに向かったのは何歳のときでしたか。", "s": "エイブラム歳", "o": "A.セブンティファイブ,B.100年,C.99歳,D.120歳"}, {"q": "ラケルと結婚するために，ヤコブはラバンの家で何年仕えましたか。", "s": "ヤコブの務め", "o": "A.7年。,B.14年,C.20年。,D.21年"}, {"q": "神は御自身のかたちに造られたとき，人間にどのような特別な地位を与えられましたか。（複数選択可）", "s": "人間の尊厳", "o": "A.神のかたちに造られ、高く上げられる,B.海の魚、空の鳥、地球の生き物の管理,C.神と親密な関係を築くことができる,D.動物と区別がつかない"}, {"q": "生涯を通じて，ジョセフは苦難を経験しましたが，次のうちどれを含め，常に神を信頼していましたか。（複数選択可）", "s": "ジョセフは苦しんでいます", "o": "A.兄弟に奴隷として売られた,B.刑務所で罠にはめられている,C.刑務所にいる仲間のためにまだ夢を見ている,D.スムーズな生活、決して苦しむことはありません。"}, {"q": "次のうち，アブラハムに対する神の約束はどれですか。（複数選択可）", "s": "アブラハムの聖約", "o": "A.子孫は空の星や海辺の砂のように数が多い。,B.カナンの全地をその子孫に与えて相続させる。,C.地上のすべての国々は彼の子孫によって祝福される,D.彼自身は不死身です"}, {"q": "バベルの塔の出来事は，人類のどのような罪を明らかにしましたか。（複数選択可）", "s": "バベルの罪", "o": "A.誇り高く、傲慢で、自分の名前を宣伝したいと思っている,B.「地を満たす」という神の命令に従わず、分散させようとしない,C.神と同等の天を結ぶ塔を建てるという妄想,D.お互いを愛し、一つになる"}, {"q": "そして、神は七日目にすべての創造的な働きをやめて休まれ、七日目を祝福された。", "s": "七日目の安息日"}, {"q": "カインは心から悔い改め，自分の罪を告白しました。なぜなら，神はアベルのささげ物を見て，彼を赦してくださったからです。", "s": "秘密の結末"}, {"q": "バベルの塔の出来事の後、主は人々のアクセントを変え、彼らを全地に散らしました。", "s": "バベルの塔"}, {"q": "イサクは百歳でアブラハムの約束された息子であり、サラは九十歳でした。", "s": "アイザックは生まれました"}, {"q": "ヨセフはエジプトの首相になった後，自分を裏切った兄弟たちに復讐しました。", "s": "ジョセフ・フォーゲブ"}, {"q": "ノアは、神が命じられたように、洪水の前に箱舟を造り、神が命じられたことをすべて行いました。", "s": "ノアは従った"}, {"q": "エサウは長男の称号を赤い豆のスープのボウルで売り、後に悔い改めて取り返しのつかないほど泣きました。", "s": "エサウが長男を売る"}, {"q": "創世3 ： 15が「原始的な福音」と呼ばれるのはなぜですか。それが何を意味するのか説明してください。", "s": "原始的な福音"}, {"q": "ジョセフの生涯から，どのような霊的な教訓を学ぶことができるでしょうか。", "s": "ジョセフの模範"}, {"q": "ジョセフの生涯が，多くの点でイエス・キリストを表していることを説明してください。", "s": "ヨセフはキリストを予型した"}]}, "ko": {"title": "제네시스", "content": "창세기는 우주 만물의 기원, 인류의 창조와 타락, 홍수의 심판, 아브라함, 이삭, 야곱, 요셉이 택함 받은 자들을 세우신 역사를 기록한 성경의 첫 번째 책입니다. 이 책은 성경의 구속 계획 전체의 기초를 놓으며, 여성의 후손이 적을 물리칠 것이라고 예고한다.", "instructions": "", "guide": [{"title": "창조 (1-2장)", "points": ["하나님께서는 여섯째 날에 천지를 창조하시고 일곱째 날에 안식하셨다.", "인간은 온 땅을 다스리기 위해 하나님의 형상대로 창조되었습니다.", "결혼 준비: 한 남자와 한 여자가 하나가 됨", "하나님께서는 그분이 만드신 모든 것이 매우 좋다는 것을 보십니다.", "에덴 동산: 하나님께서는 경비병을 수리하기 위해 사람들을 그 안에 두셨습니다.", "선악과: 순종의 시련"]}, {"title": "타락과 심판 (3-11장)", "points": ["아담과 하와는 금지된 열매를 먹으라는 그들의 명령에 불순종했고, 죄는 세상에 들어왔다.", "뱀의 속임수와 인간의 반발: 죄의 드러남", "하나님은 아담과 하와를 위해 가죽 의복을 만드셨습니다 - 은혜의 표징", "카인이 아벨을 죽이다; 라멕의 광기", "홍수의 심판, 베노아의 여덟 가족이 은총을 받다", "바벨탑: 온 땅에 흩어져 있는 교만"]}, {"title": "아브라함 (12-25)", "points": ["별처럼 많은 후손을 약속하며 우르를 떠나라고 부름", "신앙에 의한 의화: 여호와에 대한 아브람의 믿음은 의로움으로 간주됩니다.", "하나님께서 아브라함의 이름을 아브라함 (여러 민족의 조상) 으로 바꾸셨습니다.", "롯은 소돔으로 이주하고, 아브라함은 중재한다.", "이삭: 절정에 달한 믿음의 시험", "이스마엘과 이삭: 피와 약속의 아들"]}, {"title": "이삭과 야곱 (25-36)", "points": ["이삭은 리브가와 결혼하여 아브라함의 언약을 상속받습니다.", "야곱은 장자권을 따서 이스라엘로 이름을 바꾸었다.", "벧엘 사다리: 하나님께서 야곱과 함께 하시겠다고 약속하심", "야곱은 20년 동안 라반을 섬겼고, 하나님은 그를 위대하게 만드셨습니다.", "페누엘이 씨름하다: 야곱이 허벅지 받침대에서 하나님의 손길을 받다", "열두 아들로 태어나 열두 지파의 조상이 됨"]}, {"title": "조셉 (37 ~ 50)", "points": ["색깔 있는 옷과 다른 꿈: 형제 질투의 시작", "이집트에 팔리고 노예로 투옥되었지만 여전히 거룩합니다.", "감옥에서 꿈을 해석하며 하나님은 요셉과 함께 하셨습니다.", "파라오의 꿈을 해결하고 이집트의 총리가 되세요", "7년 기근에 대비한 곡식 준비", "형제들을 용서하십시오: 하나님의 뜻은 선합니다", "야곱의 가족은 이집트로 내려가고, 이스라엘은 큰 지파가 된다."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] ________, 하나님은 ________ 을 (를) 창조하셨습니다.", "s": "원래 생성됨"}, {"q": "[Scripture Fill in the Blank] 하느님께서는 당신의 ________ 에 따라 인간을 창조하셨지만, 당신의 형상대로 ________ 을 (를) 창조하셨습니다.", "s": "하나님의 형상"}, {"q": "[Scripture Fill in the Blank] 너와 여자가 서로 원수가 되게 하리니 네 씨와 여자의 씨가 서로 원수가 되리라 여자의 후손은 당신의 ________ 을 (를) 다치게 할 것이고, 당신은 그의 ________ 을 (를) 다치게 할 것입니다.", "s": "원시 복음"}, {"q": "[Scripture Fill in the Blank] 아브람은 ________ 을 (를) 믿었고, 주님께서는 그것을 자신의 ________ (으) 로 만드셨습니다.", "s": "믿음에 의한 의화"}, {"q": "[Scripture Fill in the Blank] 과거에는 ________ 나를 의미했지만, 하나님은 많은 사람들의 생명을 구하고 오늘날의 상황을 달성하기 위해 ________ 을 의미하셨습니다.", "s": "멋져요"}, {"q": "[Scripture Fill in the Blank] 오직 ________ 만이 주님의 눈앞에 ________ 입니다.", "s": "노아문"}, {"q": "[Scripture Fill in the Blank] 그리고 당신이 내 목소리에 순종했기 때문에 당신의 ________ 을 (를) 통해 땅의 모든 왕국이 ________ 될 것입니다.", "s": "Wanguo Delphi"}, {"q": "하나님께서는 6일 동안 하늘과 땅을 창조하셨고, ________ 일에 그분의 모든 일을 쉬셨습니다.", "s": "안식일"}, {"q": "주 하느님께서는 땅의 ________ 에서 인간을 창조하시고 콧구멍에 생기를 불어넣어 생령이 되셨습니다.", "s": "인공 먼지"}, {"q": "아담과 이브가 금지된 열매를 불순종으로 먹은 후, 주 하나님은 그들이 입을 옷을 만드셨다.", "s": "레더웨어 그레이스"}, {"q": "카인은 질투심으로 밭에서 형 ________ 을 (를) 죽였고, 인류 역사상 첫 번째 살인이 되었습니다.", "s": "가인이 동생을 죽임"}, {"q": "하나님께서는 다가오는 홍수 심판을 피하기 위해 노아에게 ________ 나무로 방주를 지으라고 명령하셨습니다.", "s": "고페무"}, {"q": "하나님께서는 아브람이 고향과 가족과 아버지의 집을 떠나 하나님께서 그에게 지시하신 ________ (으) 로 가도록 부르셨습니다.", "s": "아브람이"}, {"q": "야곱이 하나님과 씨름한 후, 하나님은 그의 이름을 ________ (으) 로 바꾸셨는데, 이는 그가 하나님과 인간 모두에게 승리했다는 것을 의미합니다.", "s": "Jacob 이름이 변경됨"}, {"q": "요셉은 이집트에서 파라오에 의해 ________ 만들어져 온 땅의 식량을 다스렸고 기근 속에서 가족을 구했습니다.", "s": "권력을 잡은 요셉"}, {"q": "주 하나님은 아담을 ________ 의 동산에 두어 경비병들을 수리하게 하셨다.", "s": "에덴동산"}, {"q": "아브라함의 여종 하갈은 ________ 이라는 아들을 낳았고, 많은 아랍 국가의 조상이 되었습니다.", "s": "이스마엘"}, {"q": "아담이 혼자 사는 것이 좋지 않다는 것을 하나님께서 보셨는데, 하나님은 누구를 그의 배우자로 삼으셨습니까?", "s": "하와가 창조되었습니다", "o": "A.하와,B.리브가,C.사라,D.라헬"}, {"q": "대홍수 이후 노아와 맺으신 하나님의 언약의 표징은 무엇인가?", "s": "더 레인보우 어페인먼트", "o": "A.별,B.방주,C.무지개,D.올리브 가지"}, {"q": "아브라함이 이삭을 바쳤을 때, 하나님께서 번제물로 이삭 대신 무엇을 준비하셨습니까?", "s": "Jehovah Jireh", "o": "A.수소,B.램,C.어린양,D.산비둘기"}, {"q": "요셉은 형제들에게 어디로 팔렸는가?", "s": "로어이집트", "o": "A.바빌론,B.아시리아,C.이집트,D.가나안"}, {"q": "야곱은 이스라엘 열두 지파의 조상이 된 아들들을 몇 명이나 낳았는가?", "s": "열두 지파", "o": "A.10,B.Twelve,C.일레븐,D.13개"}, {"q": "아브라함은 하란을 떠나 가나안으로 갔을 때 몇 살이었습니까?", "s": "아브람 세", "o": "A.75,B.100년,C.99세,D.120세"}, {"q": "야곱은 라헬과 결혼하기 위해 라반의 집에서 몇 년 동안 봉사했는가?", "s": "야곱의 사역", "o": "A.7년.,B.14년,C.20년.,D.21년"}, {"q": "하나님께서 인간을 당신의 형상대로 창조하실 때 어떤 독특한 지위를 인간에게 주셨는가? (복수 선택)", "s": "인간의 존엄성", "o": "A.하나님의 형상대로 지음받음, 높임받음,B.바다의 물고기, 공중의 새, 땅의 생물을 관리하는 것,C.하나님과 친밀한 관계를 맺을 수 있음,D.동물과 구별할 수 없음"}, {"q": "조셉은 평생 동안 어려움을 겪었지만 다음 중 어느 것을 포함하여 항상 하나님을 신뢰했습니까? (복수 선택)", "s": "요셉이 고통받다", "o": "A.형제들에게 노예로 팔림,B.감옥에서 누명을 쓰다,C.여전히 교도소에 있는 동료 수감자들을 위한 꿈을 꾸고 있습니다.,D.고통받지 않고 부드러운 삶을 누리세요."}, {"q": "다음 중 아브라함에게 하신 하나님의 약속 중 몇 가지는 무엇인가? (복수 선택)", "s": "아브라함 언약", "o": "A.후손은 하늘의 별과 바닷가의 모래처럼 많다.,B.가나안의 모든 땅을 그의 후손에게 상속 재산으로 주겠다는 것이었다.,C.지상의 모든 민족은 그분의 후손에 의해 축복을 받을 것입니다.,D.그 자신은 불멸입니다"}, {"q": "바벨탑 사건은 인류의 어떤 죄를 드러냈는가? (복수 선택)", "s": "바벨의 죄", "o": "A.자랑스럽고 거만하며 그의 이름을 홍보하고 싶어합니다.,B.“땅을 가득 채우라” 는 하나님의 명령에 불순종하고 흩어지기를 꺼림,C.하나님과 동등하게 하늘을 연결하는 탑을 쌓는 망상,D.서로 사랑하고 하나로 뭉치세요"}, {"q": "하나님께서는 일곱째 날에 그의 모든 창조 사업을 쉬시고 일곱째 날에 복을 주셨다.", "s": "제칠일안식일"}, {"q": "그리고 가인은 진심으로 회개하고 자신의 죄를 고백했습니다. 왜냐하면 하느님께서 아벨의 제물을 보셨고 하느님께서 그를 용서하셨기 때문입니다.", "s": "은밀한 결과"}, {"q": "바벨탑 사건 이후, 주님께서는 백성의 억양을 바꾸셔서 온 땅에 흩으셨습니다.", "s": "바벨탑"}, {"q": "이삭은 백 살에 아브라함의 약속된 아들이었고, 사라는 아흔 살에 아브라함의 약속된 아들이었다.", "s": "이삭이 태어났습니다"}, {"q": "요셉은 이집트의 총리가 된 후 자신을 배반한 형제들에게 복수했습니다.", "s": "조셉 용서"}, {"q": "노아가 홍수 전에 하나님이 자기에게 명하신 대로 방주를 만들었으니 하나님이 자기에게 명하신 대로 다 준행하였더라", "s": "노아가 순종함"}, {"q": "에서가 팥죽 한 그릇으로 장남의 칭호를 팔았는데, 나중에 회개하고 눈물을 흘렸다.", "s": "에서가 장남을 팔다"}, {"q": "창세기 3장 15절 을 “원시 복음” 이라고 부르는 이유는 무엇인가? 어떤 의미인지 설명해주세요.", "s": "원시 복음"}, {"q": "우리는 조셉의 삶에서 어떤 영적인 교훈을 배울 수 있는가?", "s": "요셉의 모범"}, {"q": "조셉의 삶이 예수 그리스도를 어떻게 대표했는지 여러 가지 방법으로 설명한다.", "s": "요셉이 그리스도를 예표함"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220935688','圣经导览','出埃及记','出埃及记记载神藉摩西领以色列人出埃及、过红海，在西奈山立约颁布十诫，并指示建造会幕。从为奴到自由，从立约到同住，本卷显明耶和华是救赎的神，也是圣洁、信实、与人同在的神。','[{"type": "verse", "q": "【经文填空】神对摩西说：“________”；又说：“你要对以色列人这样说：‘那自有永有的打发我到________。’", "o": "《出埃及记》3章14节", "s": "神的名", "a": "我是自有永有的|你们这里来"}, {"type": "verse", "q": "【经文填空】这血要在你们所住的房屋上作记号，我一见这________，就________你们去。", "o": "《出埃及记》12章13节", "s": "逾越节", "a": "血|越过"}, {"type": "verse", "q": "【经文填空】耶和华必为你们________，你们只管________，不要作声。", "o": "《出埃及记》14章14节", "s": "过红海", "a": "争战|静默"}, {"type": "verse", "q": "【经文填空】除了我以外，你不可有________的神。", "o": "《出埃及记》20章3节", "s": "十诫第一条", "a": "别的"}, {"type": "verse", "q": "【经文填空】耶和华，耶和华，是有________有________的神，不轻易发怒，并有丰盛的慈爱和诚实。", "o": "《出埃及记》34章6节", "s": "神的属性", "a": "怜悯|恩典"}, {"type": "verse", "q": "【经文填空】你若留意听耶和华你神的话，又行我眼中看为正的事，留心听我的诫命，守我一切的律例，我就不将所加与埃及人的疾病加在你身上，因为我________是医治你的。", "o": "《出埃及记》15章26节", "s": "耶和华拉法", "a": "耶和华"}, {"type": "verse", "q": "【经文填空】如今你们若实在听从我的话，遵守我的约，就要在万民中作属我的________，因为全地都是我的。你们要归我作________的国度，为圣洁的国民。", "o": "《出埃及记》19章5节", "s": "圣洁国民", "a": "子民|祭司"}, {"type": "fill", "q": "以色列人在埃及为奴约________年之久。", "o": "", "s": "为奴年代", "a": "四百"}, {"type": "fill", "q": "摩西在________中看见荆棘被火烧着却没有烧毁，神在那里呼召他去见法老。", "o": "", "s": "摩西蒙召", "a": "荆棘火焰"}, {"type": "fill", "q": "十灾中的最后一灾是________之灾，法老在这灾之后才容以色列人离去。", "o": "", "s": "十灾", "a": "长子"}, {"type": "fill", "q": "吃逾越节羔羊的那夜，以色列人要把血涂在________和左右的门框上。", "o": "", "s": "逾越节", "a": "门楣"}, {"type": "fill", "q": "神在________海面前为以色列人分开海水，使他们走干地过去，法老的军兵却被水淹没。", "o": "", "s": "过红海", "a": "红"}, {"type": "fill", "q": "神在西奈山颁布________，亲自刻在两块石版上交给摩西。", "o": "", "s": "西奈立约", "a": "十诫"}, {"type": "fill", "q": "摩西上山四十天未归，以色列人便要求亚伦为他们铸造________来敬拜，大大得罪神。", "o": "", "s": "金牛犊事件", "a": "金牛犊"}, {"type": "fill", "q": "神详细指示摩西建造________，作为神与以色列人同在的居所。", "o": "", "s": "会幕", "a": "会幕"}, {"type": "fill", "q": "米利暗是摩西的________，曾在过红海之后带领妇女击鼓跳舞，赞美耶和华。", "o": "", "s": "米利暗", "a": "姐姐"}, {"type": "fill", "q": "以色列人与亚玛力人争战时，摩西何时举手以色列人就得胜，亚伦与________在旁边扶着他的手，直到日落。", "o": "", "s": "户珥", "a": "户珥"}, {"type": "single", "q": "摩西带领以色列人出埃及时年纪多大？", "o": "A.40岁,B.80岁,C.120岁,D.60岁", "s": "摩西年岁", "a": "B"}, {"type": "single", "q": "十灾之中，哪一灾降下之后法老才真正容以色列人离去？", "o": "A.雹灾,B.蝗灾,C.黑暗之灾,D.长子之灾", "s": "十灾", "a": "D"}, {"type": "single", "q": "以色列人在旷野每天早晨收取的神所赐的食物叫什么？", "o": "A.吗哪,B.鹌鹑,C.无酵饼,D.葡萄干", "s": "旷野供应", "a": "A"}, {"type": "single", "q": "以下哪一项不是十诫的内容？", "o": "A.不可杀人,B.不可偷盗,C.不可吃血,D.不可作假见证陷害人", "s": "十诫内容", "a": "C"}, {"type": "single", "q": "会幕中至圣所里最重要的物件是什么？", "o": "A.金灯台,B.约柜,C.陈设饼桌,D.香坛", "s": "会幕物件", "a": "B"}, {"type": "single", "q": "摩西在与亚玛力人争战得胜之后筑了一座坛，起名叫“耶和华尼西”，这座坛是为纪念哪件事？", "o": "A.以色列人过红海,B.与亚玛力人争战得胜,C.十灾降下,D.金牛犊事件后神赦免", "s": "耶和华尼西", "a": "B"}, {"type": "single", "q": "神吩咐以色列人在第六天要收取几天的吗哪，以预备安息日？", "o": "A.一天的,B.两天的,C.三天的,D.不用收取", "s": "安息日吗哪", "a": "B"}, {"type": "multiple", "q": "十灾包括以下哪些？（多选）", "o": "A.水变血,B.蛙灾,C.地震,D.长子之灾", "s": "十灾内容", "a": "A|B|D"}, {"type": "multiple", "q": "神在旷野供应以色列人的包括以下哪些？（多选）", "o": "A.吗哪,B.鹌鹑,C.磐石出水,D.迦南美地", "s": "旷野供应", "a": "A|B|C"}, {"type": "multiple", "q": "摩西的岳父叶忒罗向摩西提出的建议包括以下哪些？（多选）", "o": "A.从百姓中拣选有才能的人作千夫长、百夫长,B.小事由他们审判,C.大事都呈到摩西面前,D.摩西继续独自包办一切审判", "s": "叶忒罗建议", "a": "A|B|C"}, {"type": "multiple", "q": "会幕中圣所（外层）陈设的物件包括以下哪些？（多选）", "o": "A.金灯台,B.陈设饼桌,C.香坛,D.约柜", "s": "圣所物件", "a": "A|B|C"}, {"type": "judge", "q": "摩西出生时，法老曾下令杀死以色列人所生的男孩。", "o": "", "s": "摩西出生", "a": "对"}, {"type": "judge", "q": "逾越节的羔羊必须是无残疾、一岁的公羊羔。", "o": "", "s": "逾越节", "a": "对"}, {"type": "judge", "q": "以色列人过红海时，追赶他们的埃及军兵也一同安全过了红海。", "o": "", "s": "过红海", "a": "错"}, {"type": "judge", "q": "十诫是摩西自己想出来的道德规范，不是神颁布的。", "o": "", "s": "十诫来源", "a": "错"}, {"type": "judge", "q": "会幕造完立起之后，耶和华的荣光充满了帐幕。", "o": "", "s": "会幕完成", "a": "对"}, {"type": "judge", "q": "摩西的岳父叶忒罗看见摩西独自审判百姓，便建议他设立各级审判官分担工作，摩西听从了这个建议。", "o": "", "s": "叶忒罗", "a": "对"}, {"type": "judge", "q": "有以色列人在安息日出去收吗哪，结果什么也找不着，因为神在第七日并没有降下吗哪。", "o": "", "s": "安息日", "a": "对"}, {"type": "essay", "q": "逾越节的设立有什么属灵意义？与新约耶稣基督有什么关联？", "o": "", "s": "逾越节意义", "a": "逾越节是神在以色列人出埃及前夜设立的：每家取无残疾的羔羊，把血涂在门框门楣上，灭命的天使一见这血就越过那家。羔羊预表基督——保罗说“我们逾越节的羔羊基督，已经被杀献祭了”（林前5:7）。羔羊的血使以色列人免去死亡，预表基督的宝血救赎信他的人免去神的审判。除酵饼则预表除去罪恶、过圣洁生活。"}, {"type": "essay", "q": "从以色列人拜金牛犊事件，我们可以学到什么功课？", "o": "", "s": "金牛犊功课", "a": "摩西上西奈山四十天未归，百姓就要求亚伦造金牛犊来敬拜。功课有四：一、不可为自己雕刻偶像，神是忌邪的神；二、对神要有耐心等候，不可因神似乎迟延就另寻替代；三、领袖当站稳立场，亚伦的妥协带来全民犯罪；四、神公义圣洁必追讨罪，但也满有怜悯——因摩西的代求，神没有把百姓灭绝，这正是代祷与中保的预表。"}, {"type": "essay", "q": "会幕的各样物件和制度如何预表耶稣基督？请结合所学说明。", "o": "", "s": "会幕预表", "a": "会幕是神与人同在的居所，处处预表基督：约柜上的施恩座预表基督是神与人相会之处；幔子隔开圣所与至圣所，基督受死时幔子从上到下裂开，表明人可藉祂坦然亲近神；燔祭坛上的祭牲预表基督在十字架上一次献上、永远赎罪；金灯台预表基督是世界之光；陈设饼预表基督是生命之粮。整个会幕制度说明，罪人靠自己无法亲近圣洁的神，必须藉着神所设立的中保耶稣基督。"}]','','quiz','[{"title": "为奴与蒙召（1-4章）", "points": ["以色列人在埃及受苦，神听见他们的哀声", "法老下令杀希伯来男婴，摩西出生蒙保守", "摩西被公主收养，在米甸牧羊四十年", "荆棘火焰中蒙召：神启示圣名“我是自有永有的”", "神纪念与亚伯拉罕、以撒、雅各所立的约", "摩西推辞，神赐亚伦作帮手、赐神迹"]}, {"title": "十灾与逾越节（5-13章）", "points": ["摩西亚伦见法老，杖变蛇吞了术士的杖", "十灾显明耶和华胜过埃及一切假神", "黑暗之灾：以色列家却有光明（分别）", "逾越节：羔羊的血、除酵节，预表基督救赎", "长子之灾后，法老终于容百姓离去", "以色列人带走埃及人的金银（掳掠埃及）"]}, {"title": "出埃及与过红海（14-18章）", "points": ["红海分开走干地，法老军兵覆没海中", "“耶和华必为你们争战，你们只管静默”", "云柱火柱：白日云柱、夜间火柱引导", "米利暗带领妇女击鼓跳舞歌颂耶和华", "旷野供应：吗哪、鹌鹑、磐石出水", "叶忒罗建议设立千夫长百夫长分担审判"]}, {"title": "西奈立约与十诫（19-24章）", "points": ["西奈山立约：“你们要归我作祭司的国度”", "雷轰闪电中山上显现，百姓战兢", "十诫：爱神爱人的总纲，刻在石版上", "摩西上山四十昼夜领受法版", "百姓回应：凡耶和华所说的我们都要遵行", "约书的详细条例规范百姓生活"]}, {"title": "金牛犊与会幕（32-40章）", "points": ["金牛犊事件：拜偶像招致神的烈怒", "摩西摔碎法版，利未人执行审判", "摩西代求显明神的怜悯与赦免", "比撒列被圣灵充满，巧匠建造会幕", "会幕建成，耶和华的荣光充满帐幕", "安息日为永约的记号"]}]','','33','旧约•律法书（摩西五经）','{"en": {"title": "Book of Exodus", "content": "Exodus records that God brought the Israelites out of Egypt through Moses, crossed the Red Sea, made a covenant on Mount Sinai to promulgate the Ten Commandments, and instructed the building of the tabernacle of the congregation. From slavery to freedom, from covenant to dwelling together, this volume shows that the Lord is the God of redemption, the God of holiness, faithfulness, and companionship.", "instructions": "", "guide": [{"title": "Servitude and Calling (Chapters 1-4)", "points": ["The Israelites suffer in Egypt and God hears their cries", "Pharaoh orders killing of Hebrew baby boy, Moses born conservative", "Moses was adopted by the princess and shepherded in Midian for forty years.", "Calling in the Flame of Thorns: God Reveals the Holy Name “I Am What I Am”", "God Remembered His Covenant with Abraham, Isaac, and Jacob", "Moses refuses, God gives Aaron as a helper, gives miracles"]}, {"title": "Ten Plagues and the Passover (chapters 5-13)", "points": ["Moses and Aaron saw Pharaoh, and the rod turned into a serpent and swallowed the sorcerer''s rod.", "Ten plagues show that the Lord is better than all the false gods of Egypt", "The Calamity of Darkness: The House of Israel Has Light (Separate)", "Passover: Blood of the Lamb, Feast of Unleavened Bread, Foretells of Christ''s Redemption", "After the disaster of the eldest son, Pharaoh finally allowed the people to leave.", "The Israelites took the Egyptians'' gold and silver (captured Egypt)"]}, {"title": "Exodus and Crossing the Red Sea (chapters 14-18)", "points": ["The Red Sea separated from the dry land, and the Pharaoh''s army was lost in the sea.", "“The Lord will fight for you, and you will be silent.”", "Cloud Pillar Fire Pillar: Daytime Cloud Pillar, Nighttime Fire Pillar Guide", "Miriam led the women in drumming, dancing and singing to the Lord", "Wilderness Supply: Manna, Quail, Rock Water", "Jethro proposes to set up a Thousand Commanders Centurion to share the trial"]}, {"title": "The Sinai Covenant and the Ten Commandments (chapters 19-24)", "points": ["Mount Sinai covenant: “You shall be my kingdom as priests”", "The thunder and lightning appeared in the mountains, and the people trembled.", "The Ten Commandments: A Compendium of the Love of God and the Love of Man, Engraved on a Tablet", "Moses went up the mountain forty days and forty nights to receive the testimony.", "The people responded: We will do everything the Lord has said", "The detailed regulations of the book of covenant regulate the lives of the people"]}, {"title": "Curtain of the Golden Calf (Chapters 32-40)", "points": ["Golden Calf Event: Idolatry Causes God''s Wrath", "Moses broke the plates of the testimony, and the Levites executed the judgment.", "Moses asked for God''s mercy and forgiveness.", "Bezaleel was filled with the Holy Spirit and craftsmen built the Tabernacle.", "The tabernacle of the congregation was built, and the glory of the Lord filled the tabernacle.", "The Sabbath is the sign of the everlasting covenant."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] God said to Moses, “________”; and he said, “Say to the Israelites, ‘He who has eternal life has sent me to ________.’", "s": "Name of God"}, {"q": "[Scripture Fill in the Blank] This blood will be marked on the house where you live. When I see this ________, I will ________ you go.", "s": "passover"}, {"q": "[Scripture Fill in the Blank] The Lord will be ________ for you, and you will only be ________, and you will not be silent.", "s": "Across the Red Sea"}, {"q": "[Scripture Fill in the Blank] You must not have a god of ________ other than me.", "s": "First of the Ten Commandments"}, {"q": "[Scripture Fill in the Blank] The Lord, the Lord, is a God of ________ and ________, slow to anger, and abundant in mercy and truth.", "s": "Attributes of God"}, {"q": "[Scripture Fill in the Blank] If thou wilt hearken to the voice of the Lord thy God, and do that which is right in mine eyes, and hearken to my commandments, and keep all my statutes, I will not put upon thee the diseases which I have laid upon the Egyptians, because I have healed thee.", "s": "Jehovah Rafah"}, {"q": "[Scripture Fill in the Blank] And now, if ye will earnestly hearken unto my voice, and keep my covenant, ye shall be my ________ out of all nations; for all the earth is mine. And ye shall be unto me a kingdom of ________, and a holy nation.", "s": "Holy Nation"}, {"q": "The Israelites were slaves in Egypt for about ________ years.", "s": "Age of Slavery"}, {"q": "Moses saw in ________ that the thorns were burning without being burned, and there God called him to Pharaoh.", "s": "Moses is called"}, {"q": "The last of the ten plagues was the plague of ________, after which Pharaoh allowed the Israelites to depart.", "s": "Ten Calamities"}, {"q": "On the night they ate the Passover lamb, the Israelites were to paint the blood on the ________ and on the left and right door frames.", "s": "passover"}, {"q": "And God divided the waters of the sea before the sea, and caused the children of Israel to go on dry ground, and Pharaoh''s army was overwhelmed by the waters.", "s": "Across the Red Sea"}, {"q": "God promulgated ________ on Mount Sinai and personally handed it to Moses on two stone tablets.", "s": "Sinai Covenant"}, {"q": "And Moses went up into the mount forty days, and yet he did not return, and the children of Israel required Aaron to make them a molten ________ to worship, and to sin greatly against God.", "s": "Taurus Calf Incident"}, {"q": "God instructed Moses in detail to build ________ as God''s dwelling place with the Israelites.", "s": "TABERNACLE"}, {"q": "Miriam, the ________ of Moses, had led the women in drumming and dancing after the passage of the Red Sea, praising the Lord.", "s": "Miriam"}, {"q": "And it came to pass, when the children of Israel were at war with the Amalekites, that Moses lifted up his hand, and the children of Israel prevailed, and Aaron and ________ held his hand beside him until the sun went down.", "s": "Hur"}, {"q": "How old was Moses when he led the Israelites out of Egypt?", "s": "Moses years old", "o": "A.40 years,B.80 years,C.120 years old,D.60"}, {"q": "Which of the ten plagues did Pharaoh really allow the Israelites to leave after the plague fell?", "s": "Ten Calamities", "o": "A.Hail damage,B.locust disaster,C.Plague of Darkness,D.Disaster of the Eldest Son"}, {"q": "What was the name of the food the Israelites gathered from God every morning in the wilderness?", "s": "Wilderness Supply", "o": "A.Manna,B.quail,C.Unleavened cake,D.raisins"}, {"q": "Which of the following is not part of the Ten Commandments?", "s": "Contents of the Ten Commandments", "o": "A.Do not murder,B. Do not steal.,C.No blood,D.Do not falsely testify against the offender"}, {"q": "What is the most important item in the Tabernacle''s Sanctum?", "s": "Tabernacle Items", "o": "A.Golden Lampstand,B.Ark of the covenant,C.Decorate the pie table,D.incense altar"}, {"q": "What was Moses commemorating when he built an altar called “Jehovah Nisi” after his victory over the Amalekites?", "s": "Jehovah Nisi", "o": "A.Israelites crossing the Red Sea,B.Fight and conquer the Amalekites,C.Ten Disasters Descend,D.God''s Pardon After the Golden Calf Incident"}, {"q": "How many days of manna did God command the Israelites to collect on the sixth day in preparation for the Sabbath?", "s": "Sabbath Manna", "o": "A.1 Day,B.Two days,C.Three days,D.No need to collect"}, {"q": "Which of the following are included in the ten disasters? (Multiple choice)", "s": "Ten Disasters Content", "o": "A.Water turns to blood,B.Frog Plague,C.Earthquake,D.Disaster of the Eldest Son"}, {"q": "Which of the following did God provide for Israel in the wilderness? (Multiple choice)", "s": "Wilderness Supply", "o": "A.Manna,B.quail,C.Rock outlet,D.Canaan"}, {"q": "Which of the following suggestions did Jethro, Moses'' father-in-law, make to Moses? (Multiple choice)", "s": "Jethro Suggestion", "o": "A.Choose talented people from among the people as the captains of thousands and centurions,B.Small things are judged by them,C.It was all presented to Moses.,D.Moses continues to administer all the trials on his own"}, {"q": "Which of the following items are furnished in the Tabernacle sanctuary (outer level)? (Multiple choice)", "s": "Sanctuary Items", "o": "A.Golden Lampstand,B.Decorate the pie table,C.incense altar,D.Ark of the covenant"}, {"q": "When Moses was born, Pharaoh gave the order to kill the boy born to the Israelites.", "s": "Moses was born"}, {"q": "The Passover lamb must be a male lamb, one year old, without disability.", "s": "passover"}, {"q": "When the Israelites crossed the Red Sea, the Egyptian soldiers who pursued them also crossed the Red Sea safely.", "s": "Across the Red Sea"}, {"q": "The Ten Commandments are morals that Moses himself devised, not ordained by God.", "s": "Source of the Ten Commandments"}, {"q": "When the tabernacle of the congregation was finished, the glory of the Lord filled the tabernacle.", "s": "Tabernacle complete"}, {"q": "When Jethro, Moses'' father-in-law, saw that Moses judged the people alone, he suggested that he set up judges of all ranks to share the work, and Moses followed this advice.", "s": "Jethro"}, {"q": "There were Israelites who went out on the Sabbath to gather manna, and found nothing, for God had not sent down manna on the seventh day.", "s": "Day of Repose"}, {"q": "What is the spiritual significance of the Passover? How is it related to the New Testament Jesus Christ?", "s": "Passover Meaning"}, {"q": "What lesson can we learn from the worship of the golden calf by the Israelites?", "s": "Taurus calf homework"}, {"q": "How do the various objects and systems of the Tabernacle represent Jesus Christ? Please combine with the instructions you have learned.", "s": "Tabernacle Preview"}]}, "ja": {"title": "出エジプト記", "content": "出エジプト記には，神がモーセを通してイスラエル人をエジプトから連れ出し，紅海を渡り，シナイ山で十戒を宣べ伝える契約を結び，会見の幕屋の建設を指示したと記録されています。奴隷状態から自由，聖約から共に住むことまで，この巻は，主が贖いの神，聖性，忠実さ，友情の神であることを示しています。", "instructions": "", "guide": [{"title": "隷属と召し（ 1 ～ 4章）", "points": ["イスラエル人はエジプトで苦しみ、神は彼らの叫びを聞く", "ファラオ、ヘブライ人の男の子、モーゼ生まれの保守派の殺害を命じる", "モーセは王女の養子となり、40年間ミデアンで羊飼いをしました。", "いばらの炎を呼び起こす：神は聖なる御名「わたしはあるがままのわたし」を明らかにされる", "神はアブラハム，イサク，ヤコブとの契約を覚えておられた", "モーセは拒否し、神はアロンを助け主として与え、奇跡を与える"]}, {"title": "十災と過ぎ越しの祭り（ 5 － 13章）", "points": ["モーセとアロンはファラオを見て、杖が蛇に変わり、魔術師の杖を飲み込んだ。", "10の災害は、主がエジプトのすべての偽りの神々よりも優れていることを示しています", "闇の災難：イスラエルの家には光がある（分離）", "過越祭：小羊の血，種入れぬパンの祭り，キリストの贖いの預言", "長男の災難の後、ファラオはついに民を去らせました。", "イスラエル人はエジプト人の金銀を奪った（エジプトを占領した）"]}, {"title": "出エジプトと紅海を渡る（ 14 － 18章）", "points": ["紅海は乾いた土地から分離し、ファラオの軍隊は海で失われました。", "「主はあなたのために戦われ，あなたは黙っておられます。」", "雲柱火柱：昼間の雲柱、夜間の火柱ガイド", "ミリアムは女性たちを導き，太鼓を打ち，踊り，主に向かって歌いました", "荒野の供給：マナ、ウズラ、岩水", "ジェスロは試練を共有するために千人指揮官センチュリオンを設置することを提案する"]}, {"title": "シナイの聖約と十戒（ 19 － 24章）", "points": ["シナイ山の聖約：「あなたがたは祭司としてわたしの王国となる」", "山々に雷と稲妻が現れ、人々は震えた。", "十戒：タブレットに刻まれた神の愛と人の愛の要約", "モーセはあかしを受けるために、四十日四十夜山に登った。", "民は答えた。「わたしたちは主が言われたことをすべて行います。", "聖約の書の詳細な規定は、人々の生活を規定しています"]}, {"title": "黄金のふくらはぎのカーテン（ 32 ～ 40章）", "points": ["ゴールデンカーフイベント：偶像崇拝が神の怒りを引き起こす", "モーセは証の版を壊し，レビ人は裁きを実行しました。", "モーセは神の憐れみと赦しを求めました。", "ベザレエルは聖霊に満たされ，職人たちが幕屋を建てました。", "会見の幕屋が建てられ、主の栄光が幕屋を満たした。", "安息日は永遠の契約のしるしです。"]}], "quizzes": [{"q": "〔聖句の穴埋め〕神はモーセに言われた，「________」。モーセは言った，「イスラエルの人々に言いなさい，『永遠の命を持っておられる方が________にわたしを遣わされた』と。", "s": "神の御名"}, {"q": "〔聖句の穴埋め〕この血はあなたが住んでいる家に刻印されます。これを見ると________、私は________あなたを行きます。", "s": "過ぎ越し"}, {"q": "〔聖句の穴埋め〕主はあなたのために________であり，あなたは________だけであり，沈黙することはありません。", "s": "紅海の向こう側"}, {"q": "〔聖句の穴埋め〕私以外に________の神があってはなりません。", "s": "十戒の第一"}, {"q": "〔聖句の穴埋め〕主，主は________と________の神であり，怒りに鈍く，憐れみと真理に富んでおられます。", "s": "神の属性"}, {"q": "〔聖句の穴埋め〕もしあなたがあなたの神、主の声に聞き従い、わたしの目にかなう正しいことを行い、わたしの戒めに聞き従い、わたしのすべての定めを守るならば、わたしはあなたをいやしたので、わたしがエジプトびとに下した病をあなたに臨ませないであろう。", "s": "エホバラファ"}, {"q": "〔聖句の穴埋め〕今，もしあなたがたがわたしの声に熱心に耳を傾け，わたしの契約を守るならば，あなたがたはすべての国民の中からわたしの________となるであろう。全地はわたしのものであるからである。あなたがたはわたしにとって________の王国となり，聖なる国民となるであろう。", "s": "聖なる国"}, {"q": "イスラエル人は約________年間エジプトで奴隷でした。", "s": "奴隷時代"}, {"q": "モーセは＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿ ＿を見て", "s": "モーセは呼ばれています"}, {"q": "10の災害の最後は________の疫病でした。その後、ファラオはイスラエル人を去らせました。", "s": "10の災害"}, {"q": "過越の小羊を食べた夜，イスラエル人は________と左右の戸枠に血を塗りました。", "s": "過ぎ越し"}, {"q": "神は海の前で海の水を分け、イスラエルの人々をかわいた地に導かれたので、パロの軍勢は水におおわれた。", "s": "紅海の向こう側"}, {"q": "神はシナイ山に________を頒布し、2枚の石版でモーセに個人的に手渡しました。", "s": "シナイの聖約"}, {"q": "モーセは四十日のあいだ山に登ったが、帰ってこなかったので、イスラエルの人々はアロンに、彼らを鋳物にして礼拝させ、神に大いに罪を犯すように求めた。", "s": "牡牛座ふくらはぎ事件"}, {"q": "神はモーセに，イスラエル人と共に神の住まいとして________を建てるように詳しく指示されました。", "s": "タバナクル"}, {"q": "モーセの________であるミリアムは，紅海の通過後に女性たちを導いて太鼓と踊りを披露し，主を賛美しました。", "s": "ミリアム"}, {"q": "イスラエルの人々がアマレク人と戦っていたとき、モーセは手を上げ、イスラエルの人々は勝利し、アロンと________は日が沈むまで彼のそばで手を握った。", "s": "フルル"}, {"q": "モーセがイスラエル人をエジプトから導き出したのは何歳のときでしたか。", "s": "モーセの歳", "o": "A.40歳,B.80歳,C.120歳,D.60歳"}, {"q": "疫病が落ちた後，ファラオはイスラエル人が去ることを本当に許したのは， 10の疫病のうちどれですか。", "s": "10の災害", "o": "A.雹の嵐,B.イナゴの疫病,C.闇の疫病,D.長男の災難"}, {"q": "イスラエルの民が荒野で毎朝神から集めた食物の名前は何でしたか。", "s": "荒野の供給", "o": "A.マナ,B.うずら,C.種入れぬケーキ,D.レーズン"}, {"q": "次のうち，十戒に含まれていないものはどれですか。", "s": "十戒の内容", "o": "A.キルしない,B.盗まないでください,C.血液なし,D.違反者に対して虚偽の証言をしないでください"}, {"q": "幕屋の聖域で最も重要なアイテムは何ですか？", "s": "幕屋アイテム", "o": "A.ゴールデンランプスタンド,B.契約の箱,C.円卓を飾ろう,D.湘潭"}, {"q": "モーセは，アマレク人に勝利した後，「エホバニシ」と呼ばれる祭壇を築いたとき，どのようなことを記念していましたか。", "s": "エホバニシ", "o": "A.紅海を渡るイスラエル人,B.アマレク人と戦い、征服する,C.10の災害が降り立つ,D.ゴールデンカーフ事件後の神の赦し"}, {"q": "神は安息日の準備のために，イスラエル人に6日目にマナを集めるように命じられたのは何日ですか。", "s": "安息日マナ", "o": "A.of the day,B.2日間,C.3日間,D.回収する必要はありません"}, {"q": "次のうち、10の災害に含まれるのはどれですか？ （複数選択可）", "s": "テンディザスターズコンテンツ", "o": "A.水が血に変わる,B.カエルの疫病,C.地震,D.長男の災難"}, {"q": "荒野で神がイスラエルに備えられたのは，次のうちどれですか。（複数選択可）", "s": "荒野の供給", "o": "A.マナ,B.うずら,C.ロックアウトレット,D.カナン"}, {"q": "モーセの義父エトロがモーセにした提案は，次のうちどれですか。（複数選択可）", "s": "ジェスロの提案", "o": "A.数千人と百人隊長の隊長として、人々の中から才能のある人物を選ぶ,B.些細なことは彼らによって判断される,C.すべてモーセに贈られました。,D.モーセはすべての試練を自分で管理し続けています"}, {"q": "幕屋聖域（外層）には、次のうちどれが備わっていますか？ （複数選択可）", "s": "サンクチュアリアイテム", "o": "A.ゴールデンランプスタンド,B.円卓を飾ろう,C.湘潭,D.契約の箱"}, {"q": "モーセが生まれたとき、ファラオはイスラエルの民に生まれた少年を殺すように命じました。", "s": "モーセは生まれた"}, {"q": "過ぎ越しの子羊は、障害のない1歳の雄の子羊でなければなりません。", "s": "過ぎ越し"}, {"q": "イスラエル人が紅海を渡ると，彼らを追ったエジプト兵も無事に紅海を渡りました。", "s": "紅海の向こう側"}, {"q": "十戒は，モーセ自身が考案した道徳であり，神によって定められたものではありません。", "s": "十戒の源"}, {"q": "会見の幕屋が完成すると，主の栄光が幕屋を満たした。", "s": "幕屋完成"}, {"q": "モーセの義父エトロは，モーセが単独で民を裁くのを見たとき，その業を分かち合うためにすべての階級の裁き人を立てることを提案し，モーセはこの勧告に従いました。", "s": "ジェスロ"}, {"q": "イスラエルの人々は安息日にマナを集めるために出かけましたが、神は七日目にマナを下されなかったので、何も見つかりませんでした。", "s": "安息日"}, {"q": "過ぎ越しの祭りの霊的な意義とは何でしょうか。それは新約聖書のイエス・キリストとどのように関係していますか。", "s": "過ぎ越しの意味"}, {"q": "イスラエル人による金の子牛の崇拝から，どのような教訓を学ぶことができるでしょうか。", "s": "牡牛座カーフの宿題"}, {"q": "幕屋のさまざまな物体とシステムは，イエス・キリストをどのように表していますか。学習した手順と組み合わせてください。", "s": "幕屋プレビュー"}]}, "ko": {"title": "엑소더스:", "content": "출애굽기는 하나님께서 모세를 통해 이스라엘 백성을 이집트에서 데리고 나오시고, 홍해를 건너시며, 시내산에서 십계명을 선포하겠다고 언약을 맺으시고, 회막 건축을 지시하셨다고 기록하고 있다. 노예제도에서 자유에 이르기까지, 성약에서 동거에 이르기까지, 이 책은 주님이 구속의 하나님, 거룩함, 신실함, 동반의 하나님임을 보여준다.", "instructions": "", "guide": [{"title": "섬김과 부름 (1 ~ 4장)", "points": ["이스라엘 백성은 이집트에서 고난을 당하고 하나님은 그들의 부르짖음을 들으십니다.", "파라오가 히브리어 아기, 모세가 보수적으로 태어남을 죽이라고 명령하다", "모세는 공주에게 입양되어 미디안에서 40 년 동안 목양되었습니다.", "가시나무 불꽃 속의 부르심: 하느님께서는 “나는 있는 그대로의 나” 라는 거룩한 이름을 계시하십니다.", "하나님께서 아브라함, 이삭, 야곱과 맺으신 언약을 기억하셨습니다.", "모세는 거절합니다. 하나님은 아론을 돕는 자로 주시고 기적을 베푸십니다."]}, {"title": "열 가지 재앙과 유월절 (5 ~ 13장)", "points": ["모세와 아론은 파라오를 보았고, 지팡이는 뱀이 되어 마술사의 지팡이를 삼켰다.", "열 가지 재앙은 주님이 이집트의 모든 거짓 신들보다 낫다는 것을 보여줍니다.", "어둠의 재앙: 이스라엘 집에는 빛이 있다 (별도)", "유월절: 어린양의 피, 무교절, 그리스도의 구속 예고", "장남의 재앙 이후, 파라오는 마침내 백성들을 떠나게 했습니다.", "이스라엘 백성은 이집트인들의 금과 은을 빼앗았다 (이집트를 점령했다)."]}, {"title": "출애굽과 홍해 건너기 (14 ~ 18장)", "points": ["홍해는 마른 땅에서 갈라졌고, 파라오의 군대는 바다에서 길을 잃었다.", "“여호와께서 너희를 위하여 싸우시리니 너희는 가만히 있을지니라.”", "구름기둥 불기둥: 낮의 구름기둥, 밤의 불기둥 가이드", "미리암은 여성들을 이끌고 북을 치고 춤을 추며 주님께 노래했습니다.", "광야 보급품: 만나, 메추라기, 바위 물", "이드로는 재판을 공유하기 위해 천명의 지휘관 백부장을 설치할 것을 제안합니다."]}, {"title": "시내산 언약과 십계명 (19 ~ 24장)", "points": ["시내산 언약: “너희는 제사장으로서 내 나라가 되리라”", "천둥과 번개가 산에 나타나고 백성은 떨었다.", "십계명: 판에 새겨진 하나님의 사랑과 인간의 사랑의 요약", "모세는 증언을 받기 위해 사십 주야를 산에 올랐다.", "백성이 대답하되 주께서 말씀하신 모든 것을 우리가 행하겠나이다 하니", "언약서의 세부 규정은 백성의 삶을 규제합니다."]}, {"title": "금송아지의 커튼 (32 ~ 40장)", "points": ["황금 송아지 사건: 우상 숭배가 하나님의 진노를 일으킴", "모세는 증언판을 깨뜨렸고, 레위인들은 심판을 집행했다.", "모세는 하나님의 자비와 용서를 구했습니다.", "베살렐은 성령으로 충만했고 장인들은 성막을 지었습니다.", "회막이 지어지고 여호와의 영광이 성막에 가득 찼다.", "안식일은 영원한 성약의 표징이다."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 하나님께서는 모세에게 “________” 라고 말씀하셨고, 그는 “이스라엘 자손에게 ‘영생을 가진 자가 나를 ________ 에게 보냈다’ 고 말하라.", "s": "하나님의 이름"}, {"q": "[Scripture Fill in the Blank] 이 피는 당신이 사는 집에 표시될 것입니다. 이 ________ 을 (를) 보게 되면 ________ 을 (를) 가겠습니다.", "s": "유월절"}, {"q": "[Scripture Fill in the Blank] 주님께서는 여러분을 위해 ________ 이 (가) 되실 것이며, 여러분은 ________ 일 뿐이며, 침묵하지 않을 것입니다.", "s": "홍해 건너편"}, {"q": "[Scripture Fill in the Blank] 나 말고는 ________ 의 신이 없어야 한다.", "s": "십계명 중 첫 번째 계명"}, {"q": "[Scripture Fill in the Blank] 주님은 ________ 와 ________ 의 하나님이시며 분노에 더디시고 자비와 진리가 풍성하십니다.", "s": "하나님의 속성"}, {"q": "[Scripture Fill in the Blank] 네가 네 하나님 여호와의 말씀을 청종하고 내 목전에 정직을 행하며 내 계명에 귀를 기울이며 내 모든 규례를 지키면 내가 애굽 사람에게 내린 병을 네게로 옮기지 아니하리니 이는 내가 너를 고쳤음이니라", "s": "여호와 라파"}, {"q": "[Scripture Fill in the Blank] 이제 너희가 내 말을 열심히 듣고 내 언약을 지키면 너희는 모든 민족들 가운데서 나의 것이 될 것이다. 온 세상은 나의 것이기 때문이다. 그러면 너희는 나에게 ________ 의 왕국이 되고 거룩한 민족이 될 것이다.", "s": "거룩한 민족"}, {"q": "이스라엘 백성은 약 ________ 년 동안 이집트에서 노예로 살았습니다.", "s": "노예의 시대"}, {"q": "모세는 ________ 에서 가시덤불이 타지 않고 타는 것을 보았고, 하나님께서는 그를 파라오에게 부르셨다.", "s": "모세는"}, {"q": "열 재앙 중 마지막 재앙은 ________ 의 재앙이었고, 그 후 파라오는 이스라엘 백성을 떠나게 했다.", "s": "10가지 재난"}, {"q": "유월절 양을 먹은 날 밤, 이스라엘 백성은 ________ 와 좌우 문틀에 피를 칠해야 했다.", "s": "유월절"}, {"q": "하나님이 바닷물을 바다 앞에서 갈라지게 하시매 이스라엘 자손이 육지로 행하였고 바로의 군대는 물에 압도되었더라", "s": "홍해 건너편"}, {"q": "하나님께서는 시내산에서 ________ 을 (를) 선포하시고 두 돌판으로 모세에게 직접 넘겨주셨습니다.", "s": "시나이 언약"}, {"q": "모세가 사십 일 동안 산에 올라갔으나 그가 돌아오지 않았으므로 이스라엘 자손이 아론에게 자기들을 녹여 경배하게 하고 하나님께 크게 범죄하게 하였다.", "s": "황소자리 송아지 사건"}, {"q": "하나님께서는 이스라엘 백성과 함께 하나님의 거처로 ________ 을 (를) 지으라고 모세에게 자세히 지시하셨습니다.", "s": "태버내클"}, {"q": "모세의 ________ 인 미리암은 홍해가 지나간 후 여인들을 이끌고 북을 치며 춤을 추며 주님을 찬양했다.", "s": "미리암"}, {"q": "이스라엘 자손이 아말렉과 전쟁할 때에 모세가 손을 들어 이스라엘 자손이 이긴지라 아론과 그 ______ 이 해가 질 때까지 모세의 곁에서 모세의 손을 잡아", "s": "허"}, {"q": "모세는 이스라엘 백성을 이집트에서 데리고 나올 때 몇 살이었습니까?", "s": "모세 세", "o": "A.40세,B.80세,C.120세,D.60세"}, {"q": "파라오는 열 가지 재앙 중 어느 재앙을 이스라엘 백성들이 떠날 수 있도록 내버려 두었습니까?", "s": "10가지 재난", "o": "A.우박,B.메뚜기 전염병,C.어둠의 재앙,D.장자의 재난"}, {"q": "이스라엘 백성들이 광야에서 아침마다 하나님께로부터 모은 음식의 이름은 무엇이었는가?", "s": "황무지 보급", "o": "A.만나,B.메추라기,C.누룩 없는 케이크,D.건포도"}, {"q": "다음 중 십계명의 일부가 아닌 것은?", "s": "십계명의 내용", "o": "A.죽이지 않기,B.도둑질하지 마세요,C.피 없음,D.가해자를 상대로 거짓 증언을 하지 마세요."}, {"q": "성막에서 가장 중요한 물건은 무엇입니까?", "s": "태버내클 아이템", "o": "A.황금 등잔대,B.언약궤,C.파이 테이블 장식하기,D.샹탄"}, {"q": "모세는 아말렉을 이긴 후 “여호와 니시” 라는 제단을 쌓았을 때 무엇을 기념했는가?", "s": "여호와 니시", "o": "A.홍해를 건너는 이스라엘 민족,B.아말렉족과 싸워 정복하기,C.10가지 재난 내림차순,D.금송아지 사건 이후 신의 용서"}, {"q": "하나님께서는 안식일을 준비하기 위해 여섯째 날에 이스라엘 백성에게 몇 일 동안 만나를 모으라고 명하셨는가?", "s": "안식일 만나", "o": "A.당일,B.이틀,C.3일,D.수금할 필요 없음"}, {"q": "다음 중 10가지 재난에 포함되는 것은? (복수 선택)", "s": "10가지 재난 콘텐츠", "o": "A.물이 피로 변한다,B.개구리 역병,C.지진,D.장자의 재난"}, {"q": "다음 중 하나님께서 광야에서 이스라엘을 위해 마련하신 것은 무엇인가? (복수 선택)", "s": "황무지 보급", "o": "A.만나,B.메추라기,C.락아웃렛,D.가나안"}, {"q": "모세의 장인 이드로는 다음 중 모세에게 어떤 제안을 했는가? (복수 선택)", "s": "이드로의 제안", "o": "A.인재 중에서 재능 있는 인재를 천부장과 백부장으로 뽑으시오.,B.작은 것들은 그들에 의해 판단됩니다.,C.이 모든 것이 모세에게 주어졌다.,D.모세는 계속해서 스스로 모든 시련을 관리합니다."}, {"q": "다음 중 초막 성소 (바깥 층) 에 비치된 물품은 어느 것입니까? (복수 선택)", "s": "생츄어리 아이템", "o": "A.황금 등잔대,B.파이 테이블 장식하기,C.샹탄,D.언약궤"}, {"q": "모세가 태어났을 때, 파라오는 이스라엘 백성에게 태어난 아이를 죽이라고 명령했다.", "s": "모세가 태어났습니다"}, {"q": "유월절 양은 장애가 없는 일 년 된 수양이어야 합니다.", "s": "유월절"}, {"q": "이스라엘 백성이 홍해를 건넜을 때, 그들을 추격한 이집트 병사들도 홍해를 무사히 건넜습니다.", "s": "홍해 건너편"}, {"q": "십계명은 모세 자신이 고안한 도덕이며 하나님이 정하신 것이 아닙니다.", "s": "십계명의 근원"}, {"q": "회막이 끝나자 주님의 영광이 성막에 가득 찼다.", "s": "태버내클 완료"}, {"q": "모세의 장인 이드로는 모세가 백성을 단독으로 재판하는 것을 보고 모든 계급의 재판관들을 세워 일을 분담하자고 제안했고, 모세는 이 조언을 따랐다.", "s": "이드로"}, {"q": "안식일에 만나를 모으러 나갔다가 얻지 못한 이스라엘 백성이 있었는데, 이는 하나님께서 일곱째 날에 만나를 보내지 않으셨기 때문이다.", "s": "안식일"}, {"q": "유월절의 영적 의미는 무엇인가? 신약전서 예수 그리스도와 어떤 관련이 있는가?", "s": "유월절의 의미"}, {"q": "우리는 이스라엘 백성이 금송아지를 숭배함으로써 어떤 교훈을 얻을 수 있는가?", "s": "황소자리 송아지 숙제"}, {"q": "성막의 다양한 사물과 시스템은 어떻게 예수 그리스도를 대표하는가? 학습한 지침과 결합하십시오.", "s": "태버내클 미리보기"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220941100','圣经导览','利未记','圣洁，是利未记的钥匙。“你们要圣洁，因为我是圣洁的”——神藉五祭、祭司制度、洁净条例，教导百姓如何亲近圣洁的神。本卷揭示赎罪之道，预表基督一次永远的代赎。愿你渴慕圣洁，活出分别为圣的生命。','[{"type": "verse", "q": "【经文填空】我是耶和华你们的神，所以你们要成为________，因为我是________的", "o": "《利未记》11章44节", "s": "圣洁的呼召", "a": "圣洁|圣洁"}, {"type": "verse", "q": "【经文填空】不可________，也不可埋怨你本国的子民，却要________。我是耶和华", "o": "《利未记》19章18节", "s": "爱人如己", "a": "报仇|爱人如己"}, {"type": "verse", "q": "【经文填空】因在这日要为你们________，使你们洁净。你们要在耶和华面前得以洁净，脱尽一切的________", "o": "《利未记》16章30节", "s": "赎罪日", "a": "赎罪|罪愆"}, {"type": "verse", "q": "【经文填空】第五十年，你们要当作________，在遍地给一切的居民宣告________", "o": "《利未记》25章10节", "s": "禧年", "a": "圣年|自由"}, {"type": "verse", "q": "【经文填空】六日要做工，第七日是________的________，当有圣会", "o": "《利未记》23章3节", "s": "安息日", "a": "圣|安息日"}, {"type": "verse", "q": "【经文填空】因为活物的________是在血中，我把这血赐给你们，可以在坛上为你们的生命________。因血里有生命，所以能赎罪", "o": "《利未记》17章11节", "s": "血赎罪", "a": "生命|赎罪"}, {"type": "verse", "q": "【经文填空】我要在你们中间________，我要作你们的________，你们要作我的子民", "o": "《利未记》26章12节", "s": "神同在", "a": "行走|神"}, {"type": "fill", "q": "利未记1至7章记载了五种祭：________、素祭、平安祭、赎罪祭、赎愆祭", "o": "", "s": "五祭", "a": "燔祭"}, {"type": "fill", "q": "燔祭的祭物要________烧在坛上，象征毫无保留的完全奉献", "o": "", "s": "燔祭", "a": "全然"}, {"type": "fill", "q": "亚伦的儿子拿答和________因在耶和华面前献上凡火，被火烧灭", "o": "", "s": "凡火之戒", "a": "亚比户"}, {"type": "fill", "q": "利未记11章规定，水中的活物必须有________有鳞才可吃", "o": "", "s": "洁净食物", "a": "鳍"}, {"type": "fill", "q": "赎罪日大祭司一年________次进入至圣所，为百姓赎罪", "o": "", "s": "赎罪日", "a": "一"}, {"type": "fill", "q": "赎罪日那只归与________的羊，要被带到旷野，象征罪被带走除去", "o": "", "s": "代罪羊", "a": "阿撒泻勒"}, {"type": "fill", "q": "利未记23章规定，住棚节要在耶和华面前守________日", "o": "", "s": "节期", "a": "七"}, {"type": "fill", "q": "素祭的主要材料是________，调上油，加上乳香", "o": "", "s": "素祭", "a": "细面"}, {"type": "fill", "q": "献赎愆祭时，除了献上公绵羊为祭，还要按所亏负的加上________分之一赔还", "o": "", "s": "赎愆祭", "a": "五"}, {"type": "fill", "q": "平安祭中归给祭司的分是祭牲的________和________，要在耶和华面前摇一摇、举一举，称为摇祭和举祭", "o": "", "s": "举祭摇祭", "a": "胸|腿"}, {"type": "single", "q": "利未记全卷的中心主题是什么？", "o": "A.神的创造大能,B.圣洁——神是圣洁的，祂的子民也要圣洁,C.以色列人的战争史,D.末世的预言", "s": "主题", "a": "B"}, {"type": "single", "q": "以下哪一种祭是专门为“误犯了罪”而献的？", "o": "A.燔祭,B.素祭,C.赎罪祭,D.平安祭", "s": "赎罪祭", "a": "C"}, {"type": "single", "q": "拿答和亚比户被耶和华击杀的直接原因是？", "o": "A.没有按时献祭,B.在耶和华面前献上凡火，不是祂所吩咐的,C.偷吃了祭物,D.擅自进入至圣所", "s": "凡火之戒", "a": "B"}, {"type": "single", "q": "禧年（第五十年）的主要意义是？", "o": "A.庆祝农业丰收,B.土地归回原主、奴仆得自由，宣告神才是土地真正的主人,C.为圣殿募款,D.选立新的君王", "s": "禧年", "a": "B"}, {"type": "single", "q": "利未记中“平安祭”又被称为感恩的祭，它最主要的特点是？", "o": "A.祭物全部烧掉,B.献祭的人可以一同吃祭肉，象征与神团契,C.只有祭司能吃,D.必须在晚上献上", "s": "平安祭", "a": "B"}, {"type": "single", "q": "赎罪日那天，大祭司进入至圣所之前，必须先做什么？", "o": "A.先为自己和本家献上赎罪祭,B.先吃祭肉补充体力,C.先敲锣通知百姓安静,D.先沐浴更衣三次再进入", "s": "赎罪日程序", "a": "A"}, {"type": "single", "q": "会幕圣所中的金灯台有几个灯盏？", "o": "A.五个,B.六个,C.七个,D.十二个", "s": "金灯台", "a": "C"}, {"type": "multiple", "q": "利未记23章规定的节期包括以下哪些？（多选）", "o": "A.逾越节,B.五旬节,C.住棚节,D.普珥节", "s": "节期", "a": "A|B|C"}, {"type": "multiple", "q": "关于利未记中的圣洁生活，以下哪些说法是正确的？（多选）", "o": "A.要圣洁，因为神是圣洁的,B.要爱人如己，不可报仇,C.圣洁只关乎祭司，与百姓无关,D.要在日常生活中分别为圣", "s": "圣洁生活", "a": "A|B|D"}, {"type": "multiple", "q": "赎罪日所献的两只公山羊，要分别怎样处理？（多选）", "o": "A.拈阄，一只归与耶和华，一只归与阿撒泻勒,B.归与耶和华的要宰杀献为赎罪祭,C.归与阿撒泻勒的要活着立在耶和华面前用以赎罪，然后放逐到旷野,D.两只都要宰杀烧掉", "s": "赎罪日双羊", "a": "A|B|C"}, {"type": "multiple", "q": "按利未记11章，以下哪些活物是不可吃的？（多选）", "o": "A.没有鳍和鳞的水生动物,B.鹰、鹫等食腐的飞鸟,C.有翅膀爬行的昆虫（蝗虫、蚱蜢、蟋蟀除外）,D.牛、羊等分蹄倒嚼的走兽", "s": "不洁净食物", "a": "A|B|C"}, {"type": "judge", "q": "利未记的中心信息是“你们要圣洁，因为我是圣洁的”。", "o": "", "s": "主题", "a": "对"}, {"type": "judge", "q": "赎罪祭和赎愆祭是为故意明知故犯的大罪而设立的。", "o": "", "s": "赎罪祭", "a": "错"}, {"type": "judge", "q": "大祭司每天都可以自由进入至圣所亲近神。", "o": "", "s": "赎罪日", "a": "错"}, {"type": "judge", "q": "到了禧年，卖出去的土地要归回原主，卖身为奴的也要得自由。", "o": "", "s": "禧年", "a": "对"}, {"type": "judge", "q": "利未记只讲献祭的礼仪条例，与百姓的日常生活没有关系。", "o": "", "s": "全书结构", "a": "错"}, {"type": "judge", "q": "利未记规定，亚伦后裔中凡有残疾的，都不可近前来献耶和华的火祭。", "o": "", "s": "祭司资格", "a": "对"}, {"type": "judge", "q": "平安祭的祭肉只能由祭司独自享用，献祭的人一点都不能吃。", "o": "", "s": "平安祭享用", "a": "错"}, {"type": "essay", "q": "利未记1至7章记载了哪五种祭？请简述每种祭的主要意义。", "o": "", "s": "五祭总览", "a": "五祭是：燔祭、素祭、平安祭、赎罪祭、赎愆祭。燔祭将祭物全然烧在坛上，象征毫无保留地完全奉献给神；素祭以细面调油，象征把劳碌得来的献给神；平安祭是感恩的祭，献祭者可一同吃祭肉，象征与神和好的团契；赎罪祭为误犯的罪而献，流血赎罪；赎愆祭为亏负人或亏负神而献，还要另加五分之一赔偿。五祭共同启示：人亲近圣洁的神，必须藉着献祭赎罪，预表基督一次永远的代赎。"}, {"type": "essay", "q": "为什么说利未记的主题是“圣洁”？这对今天的基督徒有什么实际意义？", "o": "", "s": "圣洁主题", "a": "利未记反复宣告“你们要圣洁，因为我是圣洁的”（11:44，19:2）。全卷从献祭、祭司、洁净条例到道德生活，都围绕一个核心：圣洁的神要求祂的子民也圣洁，罪使人与神隔绝，必须藉赎罪才能亲近。对今天的基督徒，这提醒我们：得救不是终点，神呼召我们过分别为圣的生活；同时利未记的献祭制度预表基督，祂一次献上永远赎了我们的罪，使我们能坦然亲近圣洁的神，并在生活中活出“爱人如己”的圣洁见证。"}, {"type": "essay", "q": "利未记16章的赎罪日预表了基督的什么工作？请结合新约说明。", "o": "", "s": "赎罪日预表", "a": "赎罪日一年一度，大祭司带着血进入至圣所为全民赎罪，预表基督一次进入天上的至圣所（来9:11-12）。那只归与耶和华的羊被杀献祭，预表基督为我们的罪舍命流血；那只归与阿撒泻勒的羊被放逐到旷野，预表我们的罪被带走——“东离西有多远，祂叫我们的过犯离我们也有多远”（诗103:12）。大祭司每年都要重复进入，说明旧约的赎罪是暂时的；基督“只一次将自己献上，就把罪除掉”（来9:26），成就了永远的赎罪。今天信徒因着基督的血，可以坦然进入至圣所（来10:19）。"}]','','quiz','[{"title": "五祭之例（1-7章）", "points": ["燔祭：祭物全然烧在坛上，象征完全奉献", "素祭：细面调油加上乳香，不流血的供物", "平安祭：感恩的祭，可吃祭肉，象征与神团契", "赎罪祭：为误犯的罪，流血赎罪", "赎愆祭：为亏负人或神，另加五分之一赔偿", "祭物须无残疾：按手在祭物头上认罪", "举祭摇祭：胸归祭司，腿归献祭者"]}, {"title": "祭司的设立（8-10章）", "points": ["亚伦受膏为大祭司，七日承接圣职之礼", "圣衣、膏油：分别为圣供职的记号", "拿答亚比户献凡火被击杀——神是轻慢不得的", "祭司要在圣与俗、洁净与不洁净之间作分辨", "以利亚撒接续亚伦的大祭司职分"]}, {"title": "洁净的条例（11-15章）", "points": ["洁净与不洁净的食物：分蹄反刍、有鳍有鳞", "大麻风的察看、隔离与洁净之礼", "漏症与房屋霉病的处理", "妇人产后洁净的条例", "摸不洁净物至晚上不洁：要洗衣服沐浴", "分别为圣：饮食也见证属神子民的身份"]}, {"title": "赎罪日（16章）", "points": ["一年一度，大祭司独自进入至圣所", "大祭司沐浴更衣，先为自己和本家赎罪", "一只羊归耶和华作赎罪祭，一只归阿撒泻勒带到旷野", "百姓是日刻苦己心，什么工都不可做", "预表基督一次献上，永远赎罪（来9章）"]}, {"title": "圣洁的生活（17-26章）", "points": ["你们要圣洁，因为我是圣洁的（19:2）", "爱人如己，不可报仇（19:18）", "不可交鬼行巫术，玷污自己", "顾念穷人：收割留田角，不可摘尽葡萄", "节期：安息日、逾越节、五旬节、吹角节、赎罪日、住棚节", "禧年：第五十年，土地归回、奴仆得自由", "祝福与咒诅：顺从蒙福，悖逆受罚（26章）"]}]','','34','旧约•律法书（摩西五经）','{"en": {"title": "LEVITICUS", "content": "Holiness is the key of Leviticus. “Be ye holy, for I am holy” -God teaching the people by the five sacrifices, the priesthood, and the ordinance of cleansing, how to draw near to a holy God. This book reveals the way of atonement, and foretells one eternal atonement for Christ. May you yearn for holiness and live a life of sanctification.", "instructions": "", "guide": [{"title": "Examples of Five Sacrifices (Chapters 1-7)", "points": ["Burnt offering: the sacrifice is completely burned on the altar, symbolizing complete dedication", "Meat sacrifice: fine oils with frankincense, non-bleeding offerings", "Safe Sacrifice: A sacrifice of thanksgiving, where sacrificial meat can be eaten, symbolizing fellowship with the gods", "Atonement: Atonement for wrongdoing, bloodshed", "Ransom sacrifice: for the loser or God, plus one-fifth compensation", "The sacrifice does not have to be handicapped: lay your hands on the head of the sacrifice to confess gu", "Shake the sacrifice: the chest belongs to the priest, the legs to the sacrifice"]}, {"title": "Establishment of the Priesthood (chapters 8-10)", "points": ["Aaron was anointed high priest and took the priesthood on the seventh day.", "Holy Clothes, Anointing Oils: Signs of Separate Sacred Service", "Nadabihu offered a mortal fire and was killed - God is not to be taken lightly", "The priest must distinguish between holy and profane, clean and unclean.", "Eleazar succeeds Aaron as High Priest"]}, {"title": "Clean Ordinance (Chapters 11-15)", "points": ["Clean and unclean food: hoof rumination, fins and scales", "Observation, isolation and cleansing gifts of cannabis", "Leakage and house mildew management", "Regulations on Postnatal Cleanliness of Women", "Touch unclean items until evening: wash and bathe", "Sanctified: Diet also bears witness to the identity of God''s people"]}, {"title": "Day of Atonement (chapter 16)", "points": ["Once a year, the High Priest enters the Sanctum Alone", "The High Priest bathes and dresses first to make atonement for himself and his family", "One sheep to the Lord as a sin offering, and one to Asael to the wilderness.", "The people are hard-working and self-motivated every day, and you must not do any work.", "Foretells Christ''s one offering, eternal atonement (Hebrews 9)"]}, {"title": "A holy life (17-26)", "points": ["Be holy, for I am holy (19: 2)", "Love as yourself, do not avenge (19:18)", "Do not hand over ghosts to practice witchcraft and defile yourself", "Caring for the poor: harvesting the horns of the field, not picking the grapes", "Festivals: Sabbath, Passover, Pentecost, Feast of Trumpets, Day of Atonement, Feast of Tabernacles", "Jubilee: fiftieth year, return of land, freedom of slaves", "Blessings and Curses: Obedience to Blessings, Disobedience to Punishment (Chapter 26)"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] I am the Lord your God, therefore you shall be ________, for I am of ________", "s": "The Call of Holiness"}, {"q": "[Scripture Fill in the Blank] Thou shalt not ________, neither shalt thou blame thy people, but thou shalt ________. I am the Lord", "s": "Love as yourself"}, {"q": "[Scripture Fill in the Blank] For on this day shall I cleanse you ________. You shall be cleansed from all ________ before the Lord.", "s": "Day of Atonement"}, {"q": "[Scripture Fill in the Blank] In the fiftieth year, you shall proclaim ________ to all the inhabitants of the land as ________", "s": "jubilee"}, {"q": "[Scripture Fill in the Blank] Six days to work, the seventh day is ________ of ________, when there is a holy meeting", "s": "Day of Repose"}, {"q": "[Scripture Fill in the Blank] For the ________ of the living creature is in the blood, and I give you this blood, that it may be on the altar for your life ________. Because there is life in the blood, it can atone for sins.", "s": "Blood atonement"}, {"q": "[Scripture Fill in the Blank] I will be among you ________, I will be your ________, you will be my people", "s": "God is with us"}, {"q": "Leviticus 1-7 records five kinds of sacrifices: ________, the meat offering, the peace offering, the sin offering, and the trespass offering.", "s": "Korban"}, {"q": "The sacrifice of the burnt offering is to be burned on the altar ________, symbolizing the complete and unreserved devotion.", "s": "Holocaustos"}, {"q": "Nadab the son of Aaron and ________ were consumed by fire because they offered all kinds of fire before the Lord.", "s": "Ring of Mortal Fire"}, {"q": "Leviticus 11 states that living creatures in the water must have ________ scales to eat", "s": "Clean food"}, {"q": "Yom Kippur High Priest enters the Holy of Holies ________ times a year to atone for the sins of the people", "s": "Day of Atonement"}, {"q": "The sheep belonging to ________ on the Day of Atonement will be taken into the wilderness to symbolize the removal of sin.", "s": "Scapegoat"}, {"q": "Leviticus 23 stipulates that the Feast of Tabernacles shall be kept before the Lord for ________ days.", "s": "festival"}, {"q": "The main ingredients of the Meat Sacrifice are ________, oiled and frankincense", "s": "Meat Sacrifice"}, {"q": "When offering the trespass sacrifice, in addition to offering the ram as a sacrifice, you must pay back the loss plus one part of ________.", "s": "Ransom Sacrifice"}, {"q": "The portion of the sacrifice attributed to the priest shall be the ________ and ________ of the sacrifice, which shall be shaken and lifted before the Lord, and shall be called the shaking sacrifice and the lifting sacrifice.", "s": "Shake Festivals"}, {"q": "What is the central theme of the entire volume of Leviticus?", "s": "WordPress.org themes", "o": "A.God''s creative power,B.Holiness - God is holy and His people will be holy,C.Israeli War History,D.Prophecy of the End Times"}, {"q": "Which of the following sacrifices was made specifically for the purpose of “committing a crime by mistake”?", "s": "Atonement", "o": "A.Holocaustos,B.Meat Sacrifice,C.Atonement,D.Safe Festival"}, {"q": "The direct reason Nadab and Abihu were killed by the Lord?", "s": "Ring of Mortal Fire", "o": "A.Failure to sacrifice on time,B.Offer all kinds of fire before the Lord, not what he commands.,C.Stole the sacrifice,D.Unauthorized access to the Sanctum Sanctum"}, {"q": "What is the main significance of the Year of Jubilee (50th)?", "s": "jubilee", "o": "A.Celebrating a bumper agricultural harvest,B.The land is returned to its original owner and the slave is free, declaring that God is the true master of the land.,C.Fundraising for the Temple,D.Choose a new king"}, {"q": "The \"sacrifice of peace\" in Leviticus, also known as the sacrifice of thanksgiving, is its main feature?", "s": "Safe Festival", "o": "A.Burn all sacrifices,B.Sacrificers can eat sacrificial meat together, symbolizing fellowship with the gods,C.Only priests can eat it,D.Must be presented at night"}, {"q": "What must the High Priest do before entering the Holy of Holies on the Day of Atonement?", "s": "Yom Kippur Procedure", "o": "A.Offer atoning sacrifices for yourself and your family first,B.First, eat sacrificial meat to replenish physical strength,C.First, beat the gongs to tell the people to be quiet.,D.Bathe and change three times before entering"}, {"q": "How many beacons are in the golden lampstand in the Tabernacle Sanctuary?", "s": "Golden Lampstand", "o": "A.Five,B.Six?,C.Seven,D.twelve"}, {"q": "Which of the following holidays are provided for in Leviticus 23? (Multiple choice)", "s": "festival", "o": "A.passover,B.Pentecost,C.Sukot,D.purim"}, {"q": "Which of the following statements is true about the holy life in Leviticus? (Multiple choice)", "s": "Sacred Life", "o": "A.Be holy because God is holy,B.You must love your partner as yourself and not take revenge.,C.Holiness is only about the priests, not the people.,D.To be individually sanctified in daily life"}, {"q": "What should we do with the two male goats on the Day of Atonement? (Multiple choice)", "s": "Yom Kippur Twin Sheep", "o": "A.One to Jehovah and the other to Azadiel.,B.Slaughter for the Lord as a sin offering,C.The one who belongs to Asael stands alive before the Lord to atone for his sins, and is exiled into the wilderness.,D.Both must be slaughtered and burned."}, {"q": "According to Leviticus 11, which of the following living creatures are not edible? (Multiple choice)", "s": "Unclean food", "o": "A.Aquatic animals without fins and scales,B.Eagles, vultures and other scavenging birds,C.Winged crawling insects (except locusts, grasshoppers, crickets),D.Beast with chewed hooves of cattle and sheep"}, {"q": "The central message of Leviticus is, “Be ye holy, for I am holy.”", "s": "WordPress.org themes"}, {"q": "The sin offering and the trespass offering were instituted for the purpose of knowingly committing great sins.", "s": "Atonement"}, {"q": "The High Priest was free to enter the Most Holy Place every day to draw near to God.", "s": "Day of Atonement"}, {"q": "In the Jubilee year, the land sold will be returned to its original owner, and those who sold themselves into slavery will also be free.", "s": "jubilee"}, {"q": "Leviticus speaks only of the liturgical ordinances of sacrifice, and has nothing to do with the daily life of the people.", "s": "Encyclopedia Structure"}, {"q": "The book of Leviticus decreed that none of Aaron''s descendants who was handicapped should come near to offer the Lord''s sacrifice by fire.", "s": "Priesthood"}, {"q": "The sacrificial flesh of the sacrifice of peace offerings was to be enjoyed only by the priests, and none of the sacrifices were to be eaten.", "s": "Enjoying the Peace Celebration"}, {"q": "What five kinds of sacrifices are recorded in Leviticus 1-7? Briefly describe the main significance of each festival.", "s": "Five Rituals Overview"}, {"q": "Why is the theme of Leviticus “holy”? What does this really mean for Christians today?", "s": "Holiness Theme"}, {"q": "What does the Day of Atonement in Leviticus 16 foreshadow about Christ''s work? Please incorporate the New Testament description.", "s": "Yom Kippur Schedule"}]}, "ja": {"title": "レビ記", "content": "聖性はレビ記の鍵です。「あなたがたは聖なる者となりなさい。わたしは聖なる者だからです。」ー神は民に五つの犠牲，神権，清めの儀式によって，聖なる神に近づく方法を教えておられます。この書は，贖罪の道を明らかにし，キリストのための永遠の贖罪を予告しています。あなたが神聖さを切望し、神聖化された生活を送ることができますように。", "instructions": "", "guide": [{"title": "5つの犠牲の例（ 1 -7章）", "points": ["全焼のいけにえ：犠牲は祭壇の上で完全に焼かれ、完全な献身を象徴しています", "肉の犠牲：乳香入りのファインオイル、出血のない製品", "安全な犠牲：神々との交わりを象徴する、犠牲肉を食べることができる感謝祭の犠牲", "贖罪：不正行為、流血に対する贖罪", "身代金の犠牲：敗者か神か、さらに5分の1の補償", "犠牲は障害を持つ必要はありません：犠牲の頭に手を置いてグを告白してください", "犠牲を振る：宝箱は司祭のもの、脚は犠牲のもの"]}, {"title": "神権の確立（ 8 － 10章）", "points": ["アロンは大祭司に油を注がれ，七日目に神権を受けました。", "聖なる衣服、塗油：別々の神聖な奉仕のしるし", "Nadabihuは死ぬほどの火を提供し、殺されました-神は軽視されるべきではありません", "祭司は、聖なるものと俗なもの、清いものと汚れたものを区別しなければなりません。", "エレアザルがアーロンの後を継いで大祭司となる"]}, {"title": "清潔な条例（第11 -15章）", "points": ["清潔で汚れた食べ物：足の反省、ひれ、うろこ", "大麻の観察、隔離、クレンジングの贈り物", "漏れとハウスカビの管理", "女性の出生後の清潔さに関する規制", "夕方まで汚れたものに触れる：洗って入浴する", "聖化された：食事はまた、神の民のアイデンティティを証しする"]}, {"title": "贖罪の日（第16章）", "points": ["年に一度、大祭司は一人でサンクタムに入る", "大祭司はまず自分と家族のために贖罪をするためにお風呂に入り、服を着る", "罪祭として主に一つの羊をささげ、荒野でアサエルに一つをささげる。", "人々は毎日勤勉で自発的であり、あなたは何も仕事をしてはいけません。", "キリストの唯一の捧げ物，永遠の贖罪を予告する（ヘブル9章）"]}, {"title": "聖なる生活（ 17 － 26歳）", "points": ["わたしは聖なる者であるから，聖なる者となりなさい（ 19 ： 2 ）", "自分のように愛し，復讐してはならない（ 19 ： 18 ）", "魔術を練習し、自分自身を汚すために幽霊を引き渡さないでください", "貧しい人々の世話：ブドウを摘むのではなく、畑の角を収穫する", "祭り：安息日、過越祭、ペンテコステ、トランペットの祭り、贖罪の日、幕屋の祭り", "ヨベル： 50周年、土地の返還、奴隷の自由", "祝福と呪い：祝福への服従、罰への不服従（第26章）"]}], "quizzes": [{"q": "〔聖句の穴埋め〕わたしはあなたがたの神、主である。それゆえ、あなたがたは________となる。なぜなら、わたしは________の者だからである。", "s": "神聖さの呼び声"}, {"q": "〔聖句の穴埋め〕あなたは________してはならない。あなたの民を責めてはならない。あなたは________してはならない。わたしは主である", "s": "自分らしく愛する"}, {"q": "〔聖句の穴埋め〕なぜなら、この日、私はあなたを________浄化するからです。あなたは主の前ですべての________から清められるでしょう。", "s": "Yom Kippur"}, {"q": "〔聖句の穴埋め〕50年目に、あなたはその地のすべての住民に________を________として宣言しなければなりません。", "s": "ヨベル"}, {"q": "〔聖句の穴埋め〕働くのに6日、7日目は________の________で、聖なる集会があります", "s": "安息日"}, {"q": "〔聖句の穴埋め〕生き物の________は血の中にあり、私はこの血をあなたに与えます。それはあなたの命のために________祭壇の上にあるかもしれません。血の中に命があるので、罪を贖うことができます。", "s": "血の贖罪"}, {"q": "〔聖句の穴埋め〕私はあなたの中にいます________、私はあなたの________、あなたは私の民になります", "s": "神はわたしたちと共におられます"}, {"q": "レビ記1 － 7章には， 5種類の犠牲が記録されています。すなわち， ________ ，肉のささげ物，平安のささげ物，罪のささげ物，贖罪のささげ物です。", "s": "5つの犠牲"}, {"q": "全焼のいけにえの犠牲は祭壇________で焼かれ、完全で無条件の献身を象徴します。", "s": "全焼のいけにえ"}, {"q": "アロンの子ナダブと________は、主の前にすべての火をささげたので、火で焼き尽くされた。", "s": "死すべき炎の指輪"}, {"q": "レビ記11章は、水中の生き物は食べるために________スケールを持っていなければならないと述べています", "s": "清潔な食べ物"}, {"q": "ヨム・キプール大祭司は、人々の罪を贖うために年に________回、至聖所に入ります", "s": "Yom Kippur"}, {"q": "贖罪の日に________に属する羊は，罪の除去を象徴するために荒野に連れて行かれます。", "s": "身代わり"}, {"q": "レビ記23章には，幕屋の祭りは主の前で________日間行われると規定されています。", "s": "祭り"}, {"q": "肉の犠牲の主な成分は________、油を塗った乳香です", "s": "肉の犠牲"}, {"q": "不法侵入の犠牲を提供する場合、RAMを犠牲として提供することに加えて、損失と________の一部を返済する必要があります。", "s": "身代金の犠牲"}, {"q": "祭司に帰属する犠牲の部分は，犠牲の________と________となり，主の前で揺り動かして持ち上げるものとし，揺り動かす犠牲と持ち上げる犠牲と呼ばれるものとする。", "s": "シェイクフェスティバル"}, {"q": "レビ記全巻の中心テーマは何ですか？", "s": "件　　　　　名", "o": "A.神の創造力,B.神聖さ-神は神聖であり、神の民は聖なるものとなる,C.イスラエル戦争の歴史,D.終わりの時の預言"}, {"q": "次のうち、「誤って犯罪を犯す」目的で行われた犠牲はどれですか？", "s": "贖罪", "o": "A.全焼のいけにえ,B.肉の犠牲,C.贖罪,D.セーフフェスティバル"}, {"q": "ナダブとアビフが主に殺された直接の理由は？", "s": "死すべき炎の指輪", "o": "A.時間通りに犠牲を払わなかった,B.主が命じられることではなく，あらゆる種類の火を主の前にささげなさい。,C.生贄を奪った,D.サンクタム・サンクタムへの不正アクセス"}, {"q": "ヨベルの年（ 50周年）の主な意義は何ですか？", "s": "ヨベル", "o": "A.豊作の農業収穫を祝う,B.土地は元の所有者に返還され、奴隷は自由であり、神が土地の真の主人であることを宣言します。,C.神殿のための資金調達,D.新しいキングを選ぶ"}, {"q": "レビ記の「平和の犠牲」は、感謝祭の犠牲としても知られていますが、その主な特徴は何ですか？", "s": "セーフフェスティバル", "o": "A.すべての生贄を燃やす,B.犠牲者は一緒に犠牲の肉を食べることができ、神々との交わりを象徴しています,C.神官だけが食べることができます,D.夜間に提示する必要があります"}, {"q": "贖罪の日に至聖所に入る前に，大祭司は何をしなければなりませんか。", "s": "ヨム・キプール・プロシージャ", "o": "A.まずはご自身とご家族のために贖いの犠牲をささげましょう,B.まずは犠牲肉を食べて体力を補う,C.まず、ゴングを叩いて人々に静かにするように言います。,D.入る前に入浴して3回交換してください"}, {"q": "幕屋聖域の金のランプスタンドには何個のビーコンがありますか？", "s": "ゴールデンランプスタンド", "o": "A.ファイブ,B.6人,C.セブン,D.12"}, {"q": "次の祝日のうち、レビ記23章に規定されているのはどれですか？ （複数選択可）", "s": "祭り", "o": "A.過ぎ越し,B.ペンテコステ,C.スクコット,D.プリム"}, {"q": "レビ記の聖なる生活について，次の記述のうち，正しいものはどれですか。（複数選択可）", "s": "神聖な生命", "o": "A.神は聖なる方だから聖なる者となれ,B.パートナーを自分自身のように愛し、復讐してはいけません。,C.神聖さとは祭司のことであり、民のことではありません。,D.日常生活の中で個々に聖化されること"}, {"q": "贖罪の日に， 2匹の雄ヤギをどうするべきでしょうか。（複数選択可）", "s": "ヨム・キプール・ツインシープ", "o": "A.片方はエホバに，もう片方はアザディエルに。,B.罪の捧げ物としての主のための屠殺,C.アサエルに属する者は、その罪を贖うために主の前に生きており、荒野に追放されています。,D.どちらも屠殺して燃やさなければなりません。"}, {"q": "レビ記11章によると，次の生き物のうち，食べられないものはどれですか。（複数選択可）", "s": "汚れた食べ物", "o": "A.ヒレとうろこのない水生動物,B.ワシ、ハゲワシ、その他のゴミ漁り,C.有翼の這う昆虫（イナゴ、バッタ、コオロギを除く）,D.牛と羊の蹄を噛んだ獣"}, {"q": "レビ記の中心的なメッセージは，「わたしは聖なる者だから，聖なる者となりなさい」です。", "s": "件　　　　　名"}, {"q": "罪の捧げ物と贖罪の捧げ物は，故意に大きな罪を犯すことを目的として制定されました。", "s": "贖罪"}, {"q": "大祭司は毎日自由に至聖所に入って神に近づくことができました。", "s": "Yom Kippur"}, {"q": "ヨベルの年には、売られた土地は元の所有者に返還され、自分自身を奴隷に売った人も自由になります。", "s": "ヨベル"}, {"q": "レビ記は犠牲という典礼の儀式についてだけ語っており，民の日常生活とは何の関係もありません。", "s": "百科事典の構造"}, {"q": "レビ記は，障害のあるアロンの子孫はだれ一人，主の犠牲を火でささげるために近づいてはならないと定めています。", "s": "神権"}, {"q": "平和のいけにえのいけにえの肉は祭司だけが食べるものであり、いけにえのどれも食べるものではありませんでした。", "s": "平和のお祝いを楽しむ"}, {"q": "レビ記1 － 7章には，どの5種類の犠牲が記録されていますか。各フェスティバルの主な意義を簡単に説明してください。", "s": "5つの儀式の概要"}, {"q": "レビ記のテーマが「聖なる」ものであるのはなぜでしょうか。これは今日のクリスチャンにとって，どのような意味があるでしょうか。", "s": "ホーリネステーマ"}, {"q": "レビ記16章の贖罪の日は，キリストの働きについてどのような予兆を示していますか。新約聖書の説明を取り入れてください。", "s": "ヨム・キプールのスケジュール"}]}, "ko": {"title": "레위기", "content": "거룩함은 레위기의 열쇠입니다. “내가 거룩하니 너희도 거룩할지어다” -하느님은 다섯 가지 제사와 신권과 정결 의식, 거룩하신 하느님께 가까이 가는 법으로 백성들을 가르치신다. 이 책은 속죄의 길을 밝히고 그리스도를 위한 영원한 속죄를 예고한다. 거룩함을 갈망하고 성화의 삶을 살기를 바랍니다.", "instructions": "", "guide": [{"title": "다섯 가지 희생의 예 (1 ~ 7장)", "points": ["번제: 희생 제물은 완전한 헌신을 상징하는 제단에서 완전히 태워집니다.", "육류 희생: 유향이 함유된 고급 오일, 비출혈 제물", "안전한 희생: 희생적인 고기를 먹을 수 있는 감사의 희생으로, 신들과의 교제를 상징합니다.", "속죄: 죄에 대한 속죄, 유혈", "몸값 희생: 패배자 또는 신을 위한 희생 + 5분의 1 보상", "희생은 장애가 될 필요가 없습니다: 희생의 머리에 손을 얹고 gu를 고백하십시오.", "희생을 흔들어라: 가슴은 사제의 것이고, 다리는 희생의 것이다."]}, {"title": "신권의 확립 (8 ~ 10장)", "points": ["아론은 기름부음을 받은 대제사장이 되어 일곱째 날에 사제직을 맡았다.", "거룩한 옷, 기름부음 오일: 분리된 성스러운 봉사의 징조", "나다비후가 치명적인 불을 제안하여 죽임을 당함 - 신을 가볍게 여겨서는 안 됨", "사제는 거룩한 것과 불경한 것, 깨끗한 것과 부정한 것을 구별해야 한다.", "엘르아살이 아론의 뒤를 이어 대제사장으로 취임하다"]}, {"title": "청결한 의식 (11 ~ 15장)", "points": ["깨끗하고 불결한 음식: 발굽 반추, 지느러미 및 비늘", "대마초의 관찰, 분리 및 정화 선물", "누수 및 집 곰팡이 관리", "여성의 출생 후 청결에 관한 규정", "저녁까지 깨끗하지 않은 물품 만지기: 세탁 및 목욕", "성화됨: 식단은 또한 하나님의 백성의 신분을 증언합니다."]}, {"title": "속죄일 (16장)", "points": ["대제사장은 일 년에 한 번 성소에 홀로 들어갑니다.", "대제사장은 자신과 가족을 위해 속죄하기 위해 먼저 목욕과 드레스를 합니다.", "한 마리는 주님께 속죄 제물로 드리고, 다른 한 마리는 광야에서 아사엘에게 드린다.", "사람들은 매일 열심히 일하고 자기 동기를 부여받으며, 어떤 일도 해서는 안 됩니다.", "그리스도의 유일한 제물, 영원한 속죄를 예고함 (히브리서 9장)"]}, {"title": "거룩한 삶 (17-26)", "points": ["내가 거룩하니 너희도 거룩할지어다 (19: 2)", "너 자신처럼 사랑하고 복수하지 말라 (19:18)", "마술을 연습하고 자신을 더럽히기 위해 유령을 넘기지 마십시오.", "가난한 사람 돌보기: 밭의 뿔을 수확하는 것, 포도를 따지 않는 것", "축제: 안식일, 유월절, 오순절, 나팔절, 속죄일, 초막절", "희년: 제50년, 땅의 반환, 노예의 자유", "축복과 저주: 축복에 대한 순종, 형벌에 대한 불순종 (26장)"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 나는 주 너의 하나님이니, 그러므로 너는 ________ 이 되어야 한다. 나는 ________ 의 사람이기 때문이다.", "s": "거룩함의 부르심"}, {"q": "[Scripture Fill in the Blank] 너는 네 백성을 비난하지도 말고 탓하지도 말라. 나는 주님이다", "s": "나 자신처럼 사랑하기"}, {"q": "[Scripture Fill in the Blank] 이 날에 내가 너를 정결케 하리라 ________. 여러분은 주님 앞에서 모든 ________ 에서 정결함을 받을 것입니다.", "s": "Yom Kippur"}, {"q": "[Scripture Fill in the Blank] 제50년에 너희는 이 땅의 모든 주민에게 ________ 을 (를) ________ (으) 로 선포해야 한다.", "s": "희년"}, {"q": "[Scripture Fill in the Blank] 6일 출근, 7일째 되는 날은 ________ 의 ________ 인데, 거룩한 모임이 있을 때", "s": "안식일"}, {"q": "[Scripture Fill in the Blank] 생물의 ________ 이 (가) 피 속에 있으므로 내가 이 피를 너희에게 주노니 이는 너희 생명을 위하여 단 위에 있게 하려 함이라 ________. 피에는 생명이 있기 때문에 죄를 속죄할 수 있습니다.", "s": "피의 속죄"}, {"q": "[Scripture Fill in the Blank] 나는 너희 가운데 있을 것이다. 나는 너희 가운데 있을 것이다. 너희는 나의 백성이 될 것이다.", "s": "하나님께서 우리와 함께 하십니다"}, {"q": "레위기 1 ~ 7장은 ________, 소제, 화목제, 속죄제, 속건제 등 다섯 가지 제사를 기록하고 있다.", "s": "다섯 가지 희생"}, {"q": "번제물의 희생 제물은 제단 ________ 에서 불에 태워야하며, 이는 완전하고 예약되지 않은 헌신을 상징합니다.", "s": "번제"}, {"q": "아론의 아들 나답과 ________ 은 (는) 온갖 불을 주님 앞에 바쳤기 때문에 불에 타 죽었다.", "s": "치명적인 불의 반지"}, {"q": "레위기 11장은 물에 사는 생물이 먹을 수 있는 비늘이 ________ 가 있어야 한다고 명시하고 있습니다.", "s": "청결한 음식"}, {"q": "욤 키푸르 대제사장은 백성의 죄를 속죄하기 위해 일 년에 ________ 번 지성소에 들어갑니다.", "s": "Yom Kippur"}, {"q": "대속죄일에 ________ 에 속한 양들은 죄의 제거를 상징하기 위해 광야로 끌려갈 것이다.", "s": "희생양"}, {"q": "레위기 23장은 초막절을 ________ 일 동안 주님 앞에서 지킬 것을 규정한다.", "s": "축제"}, {"q": "육류 희생의 주요 성분은 ________, 기름 및 유향입니다.", "s": "고기 희생"}, {"q": "무단 침입 희생 제물을 바칠 때는 램을 희생 제물로 바치는 것 외에도 ________ 의 한 부분을 더한 손실을 갚아야 합니다.", "s": "몸값 희생"}, {"q": "사제에게 귀속된 희생의 부분은 희생의 ________ 및 ________ 로, 주님 앞에서 흔들어 올리고 흔들어 올리는 희생제물과 들어 올리는 희생제물이라고 부른다.", "s": "쉐이크 페스티벌"}, {"q": "레위기 전체의 중심 주제는 무엇인가?", "s": "제목", "o": "A.하나님의 창조 능력,B.거룩함 - 하나님은 거룩하시며 그분의 백성은 거룩할 것입니다,C.이스라엘 전쟁사,D.종말의 예언"}, {"q": "다음 중 “실수로 범죄를 저지른 것” 을 목적으로 특별히 행해진 희생은 무엇입니까?", "s": "속죄", "o": "A.번제,B.고기 희생,C.속죄,D.세이프 페스티벌"}, {"q": "나답과 아비후가 주님께 죽임을 당한 직접적인 이유는 무엇입니까?", "s": "치명적인 불의 반지", "o": "A.제때 희생하지 못함,B.그분께서 명령하시는 것이 아니라 주님 앞에 온갖 불을 바친다.,C.희생물을 훔쳤습니다,D.생텀 생텀 (Sanctum Sanctum) 에 대한 무단 액세스"}, {"q": "희년 (50번째) 의 주요 의미는 무엇인가?", "s": "희년", "o": "A.범퍼 농산물 수확 기념,B.그 땅은 원래의 소유자에게 반환되고 노예는 자유로워져 하나님이 그 땅의 진정한 주인임을 선언합니다.,C.성전을 위한 기금 모금,D.새 왕 선택"}, {"q": "감사의 희생이라고도 하는 레위기의 \"평화의 희생\" 이 그 주요 특징입니까?", "s": "세이프 페스티벌", "o": "A.모든 희생 태우기,B.희생자들은 신들과의 교제를 상징하는 희생적인 고기를 함께 먹을 수 있습니다.,C.사제만 먹을 수 있습니다,D.밤에 제시해야 함"}, {"q": "대제사장은 대속죄일에 지성소에 들어가기 전에 무엇을 해야 하는가?", "s": "Yom Kippur 절차", "o": "A.먼저 자신과 가족을 위해 속죄 희생을 바치십시오,B.첫째, 체력을 보충하기 위해 희생적인 고기를 먹는다.,C.먼저 징을 쳐서 백성들에게 조용히 하라고 말하십시오.,D.입욕하고 세 번 갈아입은 후 입장"}, {"q": "성막 성역의 황금 등잔대에는 몇 개의 비콘이 있습니까?", "s": "황금 등잔대", "o": "A.다섯,B.여섯,C.칠,D.Twelve"}, {"q": "다음 중 레위기 23장에 규정된 공휴일은 어느 것입니까? (복수 선택)", "s": "축제", "o": "A.유월절,B.오순절,C.Sukkot,D.부림"}, {"q": "다음 중 레위기의 거룩한 삶에 대한 설명으로 옳은 것은? (복수 선택)", "s": "성스러운 삶", "o": "A.하나님이 거룩하시므로 거룩하게 되십시오.,B.파트너를 자신처럼 사랑하고 복수하지 않아야 합니다.,C.거룩함은 사제에 관한 것이지 백성에 관한 것이 아닙니다.,D.일상 생활에서 개별적으로 성화되기 위해"}, {"q": "대속죄일에 두 수염소를 어떻게 해야 할까? (복수 선택)", "s": "욤키푸르 쌍둥이 양", "o": "A.하나는 여호와께, 다른 하나는 아사디엘에게.,B.속죄제물로서 주님을 위한 살육,C.아사엘에게 속한 사람은 자신의 죄를 속죄하기 위해 주님 앞에 살아 서서 광야로 유배됩니다.,D.둘 다 죽이고 태워야 합니다."}, {"q": "레위기 11장에 따르면, 다음 중 먹을 수 없는 생물은 어느 것입니까? (복수 선택)", "s": "청결하지 않은 음식", "o": "A.지느러미와 비늘이 없는 수생 동물,B.독수리, 독수리 및 기타 청소 조류,C.날개달린 기어다니는 곤충 (메뚜기, 메뚜기, 귀뚜라미 제외),D.소와 양의 발굽이 씹히는 짐승"}, {"q": "레위기의 중심 메시지는 “내가 거룩하니 너희도 거룩하라” 이다.", "s": "제목"}, {"q": "속죄제와 속건제는 고의로 큰 죄를 범하기 위한 목적으로 제정되었다.", "s": "속죄"}, {"q": "대제사장은 하나님께 가까이 가기 위해 매일 자유롭게 지성소에 들어갈 수 있었습니다.", "s": "Yom Kippur"}, {"q": "희년에 판매된 토지는 원래 소유자에게 반환되고 노예로 팔린 사람들도 자유로워집니다.", "s": "희년"}, {"q": "레위기는 희생의 전례 의식에 대해서만 이야기하며 백성의 일상 생활과는 아무런 관련이 없습니다.", "s": "백과사전 구조"}, {"q": "레위기는 장애인인 아론의 후손 중 누구도 주님의 희생을 불로 바치러 가까이 오지 말라고 명령했다.", "s": "신권"}, {"q": "화목제물의 희생적인 고기는 제사장들만이 즐길 수 있고, 제물은 먹지 말아야 했다.", "s": "평화 기념 행사 즐기기"}, {"q": "레위기 1 ~ 7장에 어떤 다섯 종류의 희생이 기록되어 있는가? 각 축제의 주요 의미를 간략하게 설명합니다.", "s": "5가지 의식 개요"}, {"q": "레위기 주제가 “거룩한” 이유는 무엇인가? 이것이 오늘날 그리스도인들에게 실제로 어떤 의미인가?", "s": "거룩함 테마"}, {"q": "레위기 16장의 속죄일은 그리스도의 사업에 대해 무엇을 예고하는가? 신약전서 설명을 포함하십시오.", "s": "욤키푸르 일정"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220942429','圣经导览','民数记','旷野漂流四十年，见证信实的神与悖逆的百姓。民数记记载两次数点、探子事件、可拉叛变、铜蛇与巴兰，神以云柱火柱引导、吗哪供应，也以公义审判不信。愿你从以色列的失败学功课，凭信心跟从到底。','[{"type": "verse", "q": "【经文填空】愿耶和华________你，________你。愿耶和华使他的脸光照你，________你。", "o": "《民数记》6章24节", "s": "祭司祝福", "a": "赐福|保护|赐恩"}, {"type": "verse", "q": "【经文填空】耶和华对摩西说：你制造一条________，挂在杆子上；凡被咬的，一________这铜蛇就必得活。", "o": "《民数记》21章8节", "s": "铜蛇", "a": "火蛇|望"}, {"type": "verse", "q": "【经文填空】神________人，必不致说谎，也________人，必不致后悔。", "o": "《民数记》23章19节", "s": "神非人", "a": "非|非"}, {"type": "verse", "q": "【经文填空】耶和华不轻易发怒，并有丰盛的________，赦免________和过犯。", "o": "《民数记》14章18节", "s": "神的慈爱", "a": "慈爱|罪孽"}, {"type": "verse", "q": "【经文填空】你们要知道你们的________必追上你们。", "o": "《民数记》32章23节", "s": "罪必追上", "a": "罪"}, {"type": "verse", "q": "【经文填空】立起帐幕的那日，有________遮盖帐幕；从晚上到早晨，帐幕上有________的形状。", "o": "《民数记》9章15节", "s": "云彩火柱", "a": "云彩|火"}, {"type": "verse", "q": "【经文填空】摩西为人________，胜过________。", "o": "《民数记》12章3节", "s": "摩西谦和", "a": "极其谦和|世上的众人"}, {"type": "fill", "q": "以色列人第一次数点是在出埃及第二年二月初一日，于________旷野。", "o": "", "s": "第一次数点", "a": "西奈"}, {"type": "fill", "q": "十二探子窥探迦南四十天，回来报恶信的探子有________个。", "o": "", "s": "探子报恶信", "a": "十"}, {"type": "fill", "q": "因百姓不信神能领他们进迦南，神罚他们在旷野漂流________年，直到那一代倒毙。", "o": "", "s": "四十年漂流", "a": "四十"}, {"type": "fill", "q": "可拉、大坍、亚比兰攻击摩西亚伦的领导，结果地开口把他们________。", "o": "", "s": "可拉叛变", "a": "吞灭"}, {"type": "fill", "q": "亚伦的杖一夜之间发了芽、开了花、结了________，证明神拣选亚伦家为祭司。", "o": "", "s": "亚伦杖发芽", "a": "熟杏"}, {"type": "fill", "q": "摩押王________请术士巴兰来咒诅以色列。", "o": "", "s": "巴勒请巴兰", "a": "巴勒"}, {"type": "fill", "q": "巴兰的________开口说话，责备巴兰，拦阻他去咒诅以色列。", "o": "", "s": "驴开口", "a": "驴"}, {"type": "fill", "q": "摩西在米利巴没有尊神为圣，用杖击打磐石________，因此不得进入迦南。", "o": "", "s": "摩西击打磐石", "a": "两下"}, {"type": "fill", "q": "利未人被神从以色列人中拣选出来，代替一切________，专办会幕的事务。", "o": "", "s": "利未人拣选", "a": "头生的"}, {"type": "fill", "q": "拿细耳人许愿分别为圣归耶和华，期间不可喝浓酒淡酒，不可用剃头刀剃头，也不可________死尸。", "o": "", "s": "拿细耳人", "a": "挨近"}, {"type": "single", "q": "以色列人出埃及后第一次被数点时，二十岁以外能打仗的男丁约有多少？", "o": "A.约六十万,B.约六万,C.约六百万,D.约六千", "s": "数点人数", "a": "A"}, {"type": "single", "q": "十二探子中，哪两位因专心跟从耶和华而得以进入迦南？", "o": "A.迦勒和约书亚,B.摩西和亚伦,C.以利亚撒和非尼哈,D.米利暗和户珥", "s": "迦勒约书亚", "a": "A"}, {"type": "single", "q": "摩西在旷野举起铜蛇，预表什么？", "o": "A.摩西的权柄,B.基督被举起，人仰望就得救,C.以色列的医药,D.神对旷野的审判", "s": "铜蛇预表", "a": "B"}, {"type": "single", "q": "巴兰几次想要咒诅以色列，结果如何？", "o": "A.一次，成功了,B.三次，都变成祝福,C.七次，失败了,D.根本没有去", "s": "巴兰祝福", "a": "B"}, {"type": "single", "q": "接续摩西、带领以色列人进入迦南的是谁？", "o": "A.迦勒,B.约书亚,C.以利亚撒,D.非尼哈", "s": "约书亚接班", "a": "B"}, {"type": "single", "q": "以色列人在旷野起行的记号是什么？", "o": "A.摩西举杖,B.云彩从帐幕收上去,C.号角长鸣三次,D.约柜自动前行", "s": "起行记号", "a": "B"}, {"type": "single", "q": "以色列人与米甸人争战时，非尼哈做了什么止住了瘟疫？", "o": "A.献上燔祭,B.用枪刺死行淫的以色列人和米甸女子,C.带领百姓认罪祷告,D.筑坛求神息怒", "s": "非尼哈止瘟疫", "a": "B"}, {"type": "multiple", "q": "以下哪些是民数记中百姓悖逆神的表现？（多选）", "o": "A.探子报恶信，不信神能领他们进迦南,B.可拉党攻击摩西亚伦的领导,C.在什亭与摩押女子行淫、拜巴力毘珥,D.为吗哪感恩、赞美神", "s": "百姓悖逆", "a": "A|B|C"}, {"type": "multiple", "q": "民数记中神信实的作为包括哪些？（多选）", "o": "A.云柱火柱引导、吗哪鹌鹑供应,B.预备铜蛇作救法、使巴兰口出祝福,C.让悖逆的第一代全部进入迦南,D.兴起约书亚接续摩西", "s": "神的信实", "a": "A|B|D"}, {"type": "multiple", "q": "利未人被分别出来归神，他们的职责包括哪些？（多选）", "o": "A.抬会幕的器具,B.看守会幕的门,C.代替以色列一切头生的归神,D.在以色列中分得地业为产业", "s": "利未人职责", "a": "A|B|C"}, {"type": "multiple", "q": "拿细耳人分别为圣期间的条例包括哪些？（多选）", "o": "A.不可喝酒,B.不可剃头,C.不可挨近死尸,D.必须住在会幕中", "s": "拿细耳条例", "a": "A|B|C"}, {"type": "judge", "q": "民数记记载以色列人在旷野共漂流四十年，直到出埃及的第一代（二十岁以外）都倒毙旷野。", "o": "", "s": "四十年", "a": "对"}, {"type": "judge", "q": "可拉党叛变时，是摩西用刀剑杀了可拉、大坍、亚比兰。", "o": "", "s": "可拉结局", "a": "错"}, {"type": "judge", "q": "摩西举起铜蛇，凡被火蛇咬的，一望这铜蛇就活了。", "o": "", "s": "铜蛇得活", "a": "对"}, {"type": "judge", "q": "巴兰成功咒诅了以色列，使摩押王巴勒大为欢喜。", "o": "", "s": "巴兰", "a": "错"}, {"type": "judge", "q": "摩西因没有尊神为圣、用杖击打磐石两下，最终未能进入迦南。", "o": "", "s": "摩西之过", "a": "对"}, {"type": "judge", "q": "利未人在以色列十二支派中分得了迦南美地为产业。", "o": "", "s": "利未无产业", "a": "错"}, {"type": "judge", "q": "米利暗因毁谤摩西而长了大麻风，被关在营外七天。", "o": "", "s": "米利暗麻风", "a": "对"}, {"type": "essay", "q": "民数记中“信实的神”与“悖逆的百姓”形成什么对比？这对今天的基督徒有什么提醒？", "o": "", "s": "信实与悖逆", "a": "民数记一面记述神的信实——云柱火柱日夜引导、四十年衣履不破、吗哪鹌鹑天天供应、铜蛇预备救法、使巴兰的咒诅变为祝福；另一面记述百姓的悖逆——探子报恶信、可拉党叛变、拜巴力毘珥、屡次发怨言。神不撇下祂的百姓，却也公义地审判不信。提醒今天的基督徒：蒙恩的人当以信心回应神的信实，不可硬着心试探神；神的慈爱与公义并存，恩典不是放纵的借口。"}, {"type": "essay", "q": "铜蛇事件如何预表基督的救恩？（参约翰福音3章14-15节）", "o": "", "s": "铜蛇预表基督", "a": "以色列人因怨渎神被火蛇咬伤，生命垂危；神吩咐摩西制造铜蛇挂在杆上，凡仰望的就得活。铜蛇本身没有医治能力，得救的关键在于“仰望”——信心的行动。耶稣在约翰福音3章14-15节亲自解释：“摩西在旷野怎样举蛇，人子也必照样被举起来，叫一切信他的都得永生。”正如以色列人不能靠自己解蛇毒，罪人也不能靠行为自救；惟有仰望十字架上被举起的基督，信祂的人就得着永生。这是神白白的恩典。"}, {"type": "essay", "q": "摩西多次为悖逆的百姓代祷（如探子事件后）。请结合民数记14章，谈谈摩西代祷的特点与属灵意义。", "o": "", "s": "摩西代祷", "a": "摩西的代祷不是为百姓开脱罪责，而是抓住神的荣耀与应许：他提醒神，若灭绝百姓，埃及人必听见，神的名会被外邦人亵渎；又抓住神不轻易发怒、有丰盛慈爱的属性求赦免。摩西站在破口之中代求，预表基督作神人之间的中保，也提醒今天的信徒：代祷是以神的荣耀为念、以神的应许为据，站在神与人之间的服事。"}]','','quiz','[{"title": "数点与整装待发（1-10章）", "points": ["西奈旷野第一次数点：二十岁以外能打仗的男丁", "利未人专管会幕，不在数点之内", "各支派按旗号安营：东犹大、南流便、西以法莲、北但", "云柱火柱引导，以色列人按云彩起行安营", "造两枝银号，招聚会众、起行吹号", "守逾越节：记念出埃及的救恩"]}, {"title": "探子事件与四十年刑罚（11-14章）", "points": ["十二探子窥探迦南四十天，十人报恶信", "迦勒专心跟从，主张立刻上去得地", "百姓不信、要另立首领回埃及", "摩西俯伏代求，神赦免却仍施惩罚", "神罚漂流四十年，一天顶一年", "惟迦勒、约书亚得以进入迦南"]}, {"title": "叛变与神的印证（15-19章）", "points": ["米利暗毁谤摩西，长大麻风七天", "可拉党攻击摩西亚伦，地开口吞灭叛党", "可拉子孙未死（后为诗篇作者）", "亚伦的杖发芽开花结熟杏，印证祭司职分", "红母牛灰预备除罪的洁净之礼", "擅敢行事者从民中剪除"]}, {"title": "铜蛇与得胜（20-25章）", "points": ["摩西击打磐石两下，未尊神为圣，不得进迦南", "亚伦死于何珥山，以利亚撒接续", "百姓被火蛇咬，摩西举铜蛇，望者得活", "铜蛇预表基督被举起（约3:14）", "巴兰三次欲咒诅，反出口祝福以色列", "以色列拜巴力毘珥受罚，非尼哈止息瘟疫"]}, {"title": "新一代数点与交接（26-36章）", "points": ["摩押平原第二次数点，新一代兴起", "西罗非哈女儿得承产业（女性承业之例）", "约书亚被按立接续摩西", "吕便、迦得及玛拿西半支派得河东之地", "设立逃城：误杀人者可逃避报血仇者", "利未城邑：四十八座城分给利未人"]}]','','35','旧约•律法书（摩西五经）','{"en": {"title": "Numbers", "content": "Forty years wandering in the wilderness, witnessing the faithful God and the rebellious people. The book of Numbers records two times the number of points, the incident of the spies, the rebellion of Korah, the bronze serpent and Balaam, God guided with a pillar of fire, the supply of manna, and the judgment of unbelief with righteousness. May you learn from Israel''s failures and follow them in faith to the end.", "instructions": "", "guide": [{"title": "Counting and Dressing (Chapters 1-10)", "points": ["Sinai wilderness first count: men who can fight beyond the age of 20", "The Levites are in charge of the Tabernacle, not within a few points", "Tribes camped under flags: East Judah, South Reuben, West Ephraim, North Dan", "The pillar of fire guided the Israelites as they set out to encamp according to the clouds.", "Build two silver horns, gather the congregation, start the trip and blow the horn", "Keeping the Passover: Remembering the Salvation of Exodus from Egypt"]}, {"title": "Probe Incident and Forty-Year Sentence (Chapters 11-14)", "points": ["The twelve spies spied on Canaan for forty days, and the ten announced bad news.", "Caleb concentrated on following, advocating immediate access to the land.", "The people did not believe, so they set up another leader to return to Egypt.", "Moses fell down and pleaded, but God forgave him and punished him.", "God''s punishment drifted for forty years, one year a day.", "But Caleb and Joshua were able to enter Canaan."]}, {"title": "Mutiny and God''s Seal (Chapters 15-19)", "points": ["Miriam slandered Moses and became leprous for seven days.", "Korah attacked Mosalon, and the ground swallowed up the rebels.", "Korah''s descendants are not dead (later Psalmist)", "Aaron''s rod sprouts and blossoms ripe apricots, confirming the priesthood", "Gift of cleansing the red heifer ash to prepare for exorcism", "Trespassers cut off from the people"]}, {"title": "The Bronze Serpent and Victory (chapters 20-25)", "points": ["Moses struck the rock twice. He was not allowed to enter Canaan without honoring God as holy.", "Aaron died on Mount Hor, followed by Eleazar", "The people were bitten by a fire snake, Moses held up a bronze snake, and the beholder lived.", "The bronze serpent foretells the lifting up of Christ (John 3:14)", "Balaam wants to curse three times and bless Israel against the exit.", "Israel punished by Baal Peor, Phinehas stopped the plague"]}, {"title": "Next Generation Algebraic Points and Handoffs (Chapters 26-36)", "points": ["The second time the plains of Moab are numbered, a new generation has risen.", "Xiluofeiha''s daughter has to inherit the industry (example of female employment)", "Joshua was ordained to succeed Moses", "Lubin, Gad and half the tribe of Manasseh to the east of the river", "Setting up a city of refuge: a manslayer can escape a blood avenger", "Levitical Cities: Forty-eight Cities Allocated to Levites"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] May the Lord ________ you, ________ you. May the Lord shine his face upon you, ________.", "s": "Priestly Blessing"}, {"q": "[Scripture Fill in the Blank] And the Lord said unto Moses, Make thee a ________, and hang it upon a pole: and every one that is bitten shall live a ________ of this bronze serpent.", "s": "Bronze Snake"}, {"q": "[Scripture Fill in the Blank] God ________ people will not lie, and ________ people will not regret.", "s": "God is not human"}, {"q": "[Scripture Fill in the Blank] The Lord is not easily angry, and has abundant ________, forgiving ________, and transgressions.", "s": "God''s Mercy"}, {"q": "[Scripture Fill in the Blank] Know that your ________ will catch up with you.", "s": "Sin will catch up"}, {"q": "[Scripture Fill in the Blank] On the day that the tabernacle was set up, the tabernacle was covered with ________; and the tabernacle was in the form of ________ from evening until morning.", "s": "Cloud Fire Pillar"}, {"q": "[Scripture Fill in the Blank] Moses was more ________ than ________.", "s": "Moses Humble"}, {"q": "The first time the Israelites numbered them was on the first day of February, the second year of the Exodus, in the wilderness of ________.", "s": "First time counting points"}, {"q": "The twelve spies spied on Canaan for forty days, and there were ________ spies who returned to report the evil message.", "s": "Spies report bad faith"}, {"q": "Because the people did not believe that God could lead them into Canaan, God condemned them to wander in the wilderness for ________ years, until that generation died.", "s": "Forty Years of Rafting"}, {"q": "Korah, Dathan, and Abiram attacked the leadership of Moses and Sharon, and as a result opened their mouths to them ________.", "s": "Korah mutiny"}, {"q": "Overnight, Aaron''s rod germinated, blossomed, and ended in ________, proving that God had chosen Aaron''s family as priests.", "s": "Aaron''s staff sprouts"}, {"q": "The king of Moab ________ invited Balaam the magician to curse Israel.", "s": "Ballagh, Balan, please."}, {"q": "The ________ of Balaam began to speak, rebuking Balaam and stopping him from cursing Israel.", "s": "Donkey opening"}, {"q": "Moses did not sanctify God at Meribah, and struck the rock ________ with his rod, so that he could not enter Canaan.", "s": "Moses strikes the rock"}, {"q": "The Levites were chosen by God from among the Israelites to take the place of all ________ in the affairs of the tabernacle.", "s": "Levite Choice"}, {"q": "The Nazirites vowed to consecrate to the Lord, during which they were not allowed to drink strong liquor or light wine, nor to use razors to shave their heads, nor to ________ dead bodies.", "s": "Nazirite"}, {"q": "When the Israelites were first counted after leaving Egypt, about how many men beyond the age of twenty could fight?", "s": "Number of Points", "o": "A.Approximately 600,000,B.Approximately 60,000,C.Approximately 6 million,D.About 6,000"}, {"q": "Which two of the twelve spies were able to enter Canaan by following the Lord attentively?", "s": "Caleb and Joshua", "o": "A.Caleb and Joshua,B.A Moses and Aaron,C.Eleazar and Phinehas,D.Miriam and Hur"}, {"q": "What did Moses predict by lifting up the bronze serpent in the wilderness?", "s": "Bronze Snake Preview", "o": "A.Moses'' Authority,B.Christ is lifted up and people look to Him for salvation,C.Medicine in Israel,D.God''s Judgment on the Wilderness"}, {"q": "How many times did Balaam try to curse Israel?", "s": "Blessing of Balaam", "o": "A.Once, it worked.,B.Three times, it becomes a blessing.,C.Seven times, it failed.,D.Not at all"}, {"q": "Who took Moses and led the Israelites into Canaan?", "s": "Joshua takes over", "o": "A.Caleb,B.Joshua.,C.Eleazar,D.Phinehas"}, {"q": "What is the sign of the journey of the Israelites in the wilderness?", "s": "Starting Mark", "o": "A.Moses lifts his staff,B.The clouds were taken from the tent.,C.Long trumpet three times,D.Automatic advance of the Ark of the Covenant"}, {"q": "What did Phinehas do to stop the plague when the Israelites fought the Midianites?", "s": "非尼哈止瘟疫", "o": "A.Offer a burnt offering,B.Gunned down prostituted Israelis and Midianites,C.Lead the people in confession and prayer,D.Building an Altar and Seeking God to Breathe"}, {"q": "Which of the following is a manifestation of the people''s disobedience to God in the book of Numbers? (Multiple choice)", "s": "Disobedience of the people", "o": "A.The spies repaid the bad faith and did not believe that God could lead them into Canaan.,B.Korah attacks Moscialon''s leadership,C.Adultery with Moabite women in Shittim, worshiping Baal Peor,D.Gratitude and praise to God for Manna"}, {"q": "What does God''s faithful deeds in the book of Numbers include? (Multiple choice)", "s": "God’s Faithfulness:"}, {"q": "What were the duties of the Levites, who were separated to God? (Multiple choice)", "s": "Levitical Duties"}, {"q": "What are the ordinances for the sanctification of the Nazirites? (Multiple choice)", "s": "Nazareth Ordinance", "o": "A.No alcohol,B.No shaving,C.Do not approach the corpse,D.Must live in the Tabernacle"}, {"q": "Numbers records that the Israelites wandered in the wilderness for forty years, until the first generation (twenty years old and older) of the Exodus fell into the wilderness.", "s": "Forty years"}, {"q": "When Korah''s party rebelled, Moses killed Korah, Dathan, and Abiram with the sword.", "s": "Korah Ending"}, {"q": "Moses lifted up the bronze snake. Anyone who was bitten by the fire snake looked at the bronze snake and lived.", "s": "Bronze Snake Gets Living"}, {"q": "Balaam succeeded in cursing Israel, and in making Balak king of Moab rejoice.", "s": "Ballan"}, {"q": "Moses was not able to enter Canaan because he did not honor God and struck the rock twice with his rod.", "s": "Passage of Moses"}, {"q": "The Levites divided the land of Canaan among the twelve tribes of Israel.", "s": "Levi has no property"}, {"q": "Miriam, who had developed leprosy by slandering Moses, was confined outside the camp for seven days.", "s": "Millikin leprosy"}, {"q": "What is the contrast between a “faithful God” and a “disobedient people” in the book of Numbers? What does this remind us of Christians today?", "s": "Faithful and disobedient"}, {"q": "How did the events of the bronze serpent portend Christ''s salvation? (See John 3:14 -15.)", "s": "The Bronze Serpent Predicts Christ"}, {"q": "Moses repeatedly interceded for a disobedient people (e.g., after the events of the spies). Please talk about the characteristics and spiritual significance of Moses'' intercession in combination with Numbers 14.", "s": "Moses Intercessory Prayer"}]}, "ja": {"title": "数字の数", "content": "40年間荒野をさまよい，忠実な神と反逆の民を証しました。民数記には， 2倍の点数，すなわち，スパイの事件，コラの反逆，青銅の蛇とバラム，火の柱で導かれた神，マナの供給，義による不信仰の裁きが記録されています。イスラエルの失敗から学び，最後まで信仰をもって従いますように。", "instructions": "", "guide": [{"title": "カウントとドレッシング（第1 -10章）", "points": ["SINAI WILDERNESS FIRST COUNT ： 20歳以上で戦える男性", "レビ人は幕屋を管理しているのであって、数ポイントの範囲内ではありません", "旗の下に宿営する部族：東ユダ、南ルベン、西エフライム、北ダン", "火の柱は，雲に沿って宿営するイスラエル人を導きました。", "2つの銀の角を作り、会衆を集め、旅を始めて角を吹き鳴らしましょう", "過越の祭りを守る：エジプトからの出エジプトの救いを思い出す"]}, {"title": "プローブインシデントと40年の刑（第11〜14章）", "points": ["十二人のスパイは四十日間カナンを偵察し、十人は悪い知らせを告げた。", "ケイレブは従うことに集中し、土地への即時アクセスを提唱しました。", "民衆は信じなかったので、エジプトに戻るために別の指導者を立てました。", "モーセはひれ伏して嘆願したが、神は彼を赦し、罰した。", "神の罰は、一日一年、四十年間流されました。", "しかし，カレブとヨシュアはカナンに入ることができました。"]}, {"title": "反逆と神の封印（ 15 － 19章）", "points": ["ミリアムはモーセを中傷し、7日間ハンセン病になりました。", "コラはモサロンを攻撃し、地面は反乱軍を飲み込んだ。", "コラの子孫は死んでいない（後の詩篇作家）", "アーロンのロッドスプラウトと花の熟したアプリコットは、神権を確認します", "エクソシズムに備えて赤い雌牛の灰を浄化する贈り物", "侵入者が人々から遮断された"]}, {"title": "青銅の蛇と勝利（ 20 － 25章）", "points": ["モーセは岩を二度打ちました。神を聖なる者として尊ばずにカナンに入ることは許されませんでした。", "アロンはホル山で死に、続いてエレアザルが死んだ", "民は火の蛇に噛まれ，モーセは青銅の蛇を掲げ，見張り人は生きていました。", "青銅の蛇は，キリストの高揚を予告しています（ヨハネ3 ： 14 ）", "バラムは3回の呪いをかけ、イスラエルの出口を祝福しようとしています。", "バアル・ペオルによって罰せられたイスラエル、ピネハスは疫病を止めた"]}, {"title": "次世代代数ポイントとハンドオフ（第26 -36章）", "points": ["モアブの平原が2度目に数えられたとき、新しい世代が生まれました。", "Xiluofeihaの娘は業界を継承しなければならない（女性雇用の例）", "ジョシュアはモーセの後継者として聖任された", "ルビン、ガド、および川の東のマナセの半部族", "避難都市の設定：人殺しは血の復讐者から逃れることができます", "レビ都市：レビ人に割り当てられた48の都市"]}], "quizzes": [{"q": "〔聖句の穴埋め〕主が________あなた、________あなたを________されますように。________主が御顔をあなたの上に照らしてくださいますように。", "s": "司祭の祝福"}, {"q": "〔聖句の穴埋め〕主はモーセに言われた、「あなたを一つの________にして、それを柱の上に掛けなさい。かまれた者はみな、この青銅の蛇の________を生きながらえなければならない。", "s": "銅の蛇"}, {"q": "〔聖句の穴埋め〕神________人は嘘をつかず、________人は後悔しません。", "s": "神は人間ではない"}, {"q": "〔聖句の穴埋め〕主は容易に怒ることはなく， ________が豊富で， ________を赦し，罪を犯しておられます。", "s": "神の憐れみ"}, {"q": "〔聖句の穴埋め〕あなたの________があなたに追いつくことを知ってください。", "s": "罪が追いつく"}, {"q": "〔聖句の穴埋め〕幕屋が設けられた日，幕屋は________で覆われ，幕屋は夕方から朝まで________の形をしていました。", "s": "雲火柱"}, {"q": "〔聖句の穴埋め〕モーセは________よりも________でした。", "s": "モーゼス・ハンブル"}, {"q": "イスラエル人が最初に数えたのは，出エジプト記2年目の2月1日， ________の荒野でした。", "s": "初回カウントポイント"}, {"q": "12人のスパイは40日間カナンをスパイしましたが、悪のメッセージを報告するために________人のスパイが戻ってきました。", "s": "スパイが悪意を報告"}, {"q": "人々は神が彼らをカナンに導くことができると信じていなかったので、神はその世代が死ぬまで________年の間、荒野をさまようことを彼らに宣告しました。", "s": "40年にわたるラフティング体験"}, {"q": "コラ，ダタン，アビラムは，モーセとシャロンの指導者たちを攻撃し，その結果，彼らに________口を開きました。", "s": "コラの反乱"}, {"q": "一夜にして，アロンの杖は発芽し，花を咲かせ， ________で終わり，神がアロンの家族を祭司として選ばれたことを証明しました。", "s": "アーロンの杖が芽を出す"}, {"q": "モアブの王は，イスラエルを呪うために魔術師バラムを招きました。", "s": "バラー、バラン、頼む。"}, {"q": "バラムの________が語り始め、バラムを叱責し、イスラエルを呪うのを止めました。", "s": "ロバの開け方"}, {"q": "モーセはメリバで神を聖別せず、その杖で岩を打ったので、カナンに入ることができなかった。", "s": "モーセが岩を打つ"}, {"q": "レビ人は神によってイスラエル人の中から選ばれ，幕屋の事柄においてすべての________の代わりとなりました。", "s": "レビ人の選択"}, {"q": "ナジル人は主に奉献することを誓いました。その間、彼らは強い酒や軽いワインを飲むことも、頭を剃るためにカミソリを使うことも、死体を________することも許されませんでした。", "s": "ナジル人"}, {"q": "イスラエルの民がエジプトを出た後に最初に数えられたとき， 20歳以上の男性は何人戦うことができましたか。", "s": "ポイント数", "o": "A.約60万人,B.約6万人,C.約600万人,D.約6,000"}, {"q": "12人のスパイのうち，主に注意深く従うことでカナンに入ることができたのはどの2人ですか。", "s": "カレブとジョシュア", "o": "A.カレブとジョシュア,B.モーセとアロン,C.エレアザルとフィネハス,D.ミリアムとハー"}, {"q": "モーセは荒野で青銅の蛇を持ち上げることで，何を予言しましたか。", "s": "ブロンズスネークプレビュー", "o": "A.モーセの権威,B.キリストは高く上げられ、人々は救いを求めます,C.イスラエルの医学,D.荒野に対する神の裁き"}, {"q": "バラムは何度イスラエルを呪おうとしましたか。", "s": "バラムの祝福", "o": "A.かつてはうまくいった。,B.3回、それは祝福になります。,C.7回失敗しました。,D.まったくない"}, {"q": "誰がモーセを連れて，イスラエル人をカナンに導いたのでしょうか。", "s": "ジョシュアが引き継ぐ", "o": "A.ケイレブ,B.ヨシュア,C.エレアザル,D.フェニハ"}, {"q": "荒野でのイスラエル人の旅のしるしは何ですか。", "s": "開始マーク", "o": "A.モーセが杖を持ち上げる,B.雲はテントから取り除かれた。,C.ロングトランペット3回,D.契約の箱の自動前進"}, {"q": "イスラエル人がミデヤン人と戦ったとき，疫病を止めるためにピネハスは何をしましたか。", "s": "非尼哈止瘟疫", "o": "A.全焼のいけにえを提供する,B.売春したイスラエル人とミディアン人を銃で撃ち殺した,C.告白と祈りで人々を導く,D.祭壇を築き、神に呼吸を求める"}, {"q": "民数記にある民の神への不従順の現れは，次のうちどれですか。（複数選択可）", "s": "民衆の不従順", "o": "A.スパイたちは悪意に報い、神が彼らをカナンに導くことができるとは信じていませんでした。,B.コラはモシクロンの指導部を攻撃する,C.シッティムでバアル・ペオルを崇拝するモアブ人の女性との姦淫,D.マナに対する神への感謝と賛美"}, {"q": "民数記にある神の忠実な業には，どのようなものが含まれていますか。（複数選択可）", "s": "神の忠実さ", "o": "A.雲柱火柱ガイド、マンナウズラ用品,B.救助のために銅の蛇を準備し、バラムの口を祝福する,C.反抗的なすべての第一世代をカナンに入らせましょう,D.モーセの後を継ぐためにジョシュアを育てる"}, {"q": "神のもとに引き離されたレビ人の務めは何でしたか。（複数選択可）", "s": "レビ人の義務", "o": "A.幕屋を運ぶための道具,B.幕屋の扉を守ろう,C.イスラエルのすべての長子の代わりに神に立ち返る,D.イスラエルの産業としての土地の共有"}, {"q": "ナジル人を聖めるための儀式とは何でしょうか。（複数選択可）", "s": "ナザレ条例", "o": "A.アルコール禁止,B.髭剃りなし,C.死体に近づかないでください,D.幕屋に住んでいる必要があります"}, {"q": "民数記によると，出エジプト記の最初の世代（ 20歳以上）が荒野に落ちるまで，イスラエル人は40年間荒野をさまよっていました。", "s": "40年"}, {"q": "コラの一行が反乱を起こしたとき、モーセはコラ、ダタン、アビラムを剣で殺しました。", "s": "コラの終わり"}, {"q": "モーセは青銅の蛇を持ち上げ、火の蛇に噛まれた者は青銅の蛇を見て生き延びた。", "s": "ブロンズスネークが生き返る"}, {"q": "バラムはイスラエルをのろい、モアブの王バラクを喜ばせることに成功した。", "s": "バラム"}, {"q": "モーセは神を敬わず，その杖で岩を二度打ったため，カナンに入ることができませんでした。", "s": "モーセの聖句"}, {"q": "レビ人はカナンの地をイスラエルの十二部族に分けました。", "s": "Leviさんは不動産を所有していません"}, {"q": "モーセを中傷してハンセン病を発症したミリアムは，宿営地の外に七日間閉じ込められました。", "s": "ミリキン麻痺"}, {"q": "民数記にある「忠実な神」と「不従順な民」の対比は何ですか。これは，今日のクリスチャンをどのように思い起こさせますか。", "s": "忠実で不従順"}, {"q": "青銅の蛇の出来事は，キリストの救いをどのように預言したでしょうか。（ヨハネ3 ： 14 － 15参照。）", "s": "青銅の蛇がキリストを予言"}, {"q": "モーセは，不従順な民のために繰り返し執り成しをしました（例：スパイの出来事の後）。民数記14章と組み合わせたモーセの執り成しの特質と霊的な意義について話してください。", "s": "モーセの執り成しの祈り"}]}, "ko": {"title": "숫자", "content": "40 년 동안 광야에서 방황하며 신실한 하나님과 반역하는 백성을 목격했습니다. 민수기는 점수의 두 배, 정탐꾼의 사건, 고라의 반역, 청동 뱀과 발람, 불기둥으로 인도하신 하나님, 만나의 공급, 의로움으로 불신의 심판을 기록합니다. 이스라엘의 실패에서 배우고 끝까지 신앙으로 따르기를 바랍니다.", "instructions": "", "guide": [{"title": "계수 및 드레싱 (1 ~ 10장)", "points": ["시나이 광야 첫 번째 집계: 20세 이상으로 싸울 수 있는 남성", "레위인들은 몇 지점 내에 있지 않고 성막을 책임지고 있습니다.", "깃발 아래 진을 친 부족들: 동유다, 남부 르우벤, 서부 에브라임, 북부 단", "불기둥이 이스라엘 백성을 인도하여 구름을 따라 진을 쳤습니다.", "두 개의 은색 뿔을 만들고, 회중을 모으고, 여행을 시작하고, 뿔을 날려버리세요.", "유월절 지키기: 이집트에서 출애굽한 구원을 기억하기"]}, {"title": "프로브 사건 및 40년 선고 (11-14장)", "points": ["열두 정탐꾼은 사십 일 동안 가나안을 염탐했고, 열두 정탐꾼은 나쁜 소식을 알렸다.", "갈렙은 땅으로의 즉각적인 접근을 옹호하며 따르는 데 집중했다.", "백성들은 믿지 않았기 때문에 또 다른 지도자를 세워 이집트로 돌아갔다.", "모세는 엎드려 간청했지만 하나님께서는 그를 용서하시고 벌하셨다.", "하나님의 형벌은 하루에 한 해씩 40년 동안이나 떠돌았습니다.", "그러나 갈렙과 여호수아는 가나안에 들어갈 수 있었습니다."]}, {"title": "반란과 하나님의 인 (15-19장)", "points": ["미리암은 모세를 비방하고 7일 동안 나병에 걸렸다.", "코라는 모살론을 공격했고, 땅은 반란군을 삼켰다.", "고라의 후손은 죽지 않았다 (후일 시편기사)", "아론의 막대기 나물과 꽃이 잘 익은 살구, 신권 확인", "구마를 준비하기 위해 붉은 암송아지 재를 정화하는 선물", "인민으로부터 단절된 침입자"]}, {"title": "청동 뱀과 승리 (20-25장)", "points": ["모세가 반석을 두 번 치니 하나님을 공경하지 않고는 가나안에 들어갈 수 없었습니다.", "아론이 호르산에서 죽고 엘르아살이 그 뒤를 이었다.", "백성은 불뱀에 물렸고, 모세는 놋뱀을 들고 있었고, 구경꾼은 살았습니다.", "놋뱀이 그리스도의 들리심을 예고함 (요한복음 3:14)", "발람은 세 번 저주하고 출구에 맞서 이스라엘을 축복하고자 합니다.", "바알브올에게 벌을 받은 이스라엘, 비느하스가 전염병을 막았다"]}, {"title": "차세대 대수적 지점 및 핸드오프 (26 ~ 36장)", "points": ["모압 평지가 두 번째로 점령될 때, 새로운 세대가 일어났다.", "Xiluofeiha의 딸은 업계를 물려 받아야합니다 (여성 고용의 예)", "여호수아는 모세의 뒤를 잇기 위해 성임되었다.", "강 동쪽의 루빈, 갓, 므낫세 반 지파", "도피성 설정: 살인자는 피의 복수자를 피할 수 있습니다.", "레위기 도시: 레위인에게 할당된 48개 도시"]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 주님께서 ________ 너, ________ 너. 주님께서 여러분에게 그분의 얼굴을 비추시기를 바랍니다. ________.", "s": "사제 축복"}, {"q": "[Scripture Fill in the Blank] 여호와께서 모세에게 이르시되 너는 네 형상을 만들어 장대 위에 매달라 무릇 물린 자는 이 놋뱀의 형상대로 살리라", "s": "청동뱀"}, {"q": "[Scripture Fill in the Blank] 하나님 ________ 사람들은 거짓말을 하지 않을 것이고, ________ 사람들은 후회하지 않을 것입니다.", "s": "신은 인간이 아니다"}, {"q": "[Scripture Fill in the Blank] 주님은 쉽게 분노하지 않으시고 ________ 을 (를) 풍성하게 하시고 ________ 을 (를) 용서하시며 범법을 저지르십니다.", "s": "하나님의 자비"}, {"q": "[Scripture Fill in the Blank] ________ 님이 회원님을 따라잡을 것입니다.", "s": "죄가 따라잡을 것입니다"}, {"q": "[Scripture Fill in the Blank] 성막이 세워진 날 성막은 ________ 로 덮여 있었고, 성막은 저녁부터 아침까지 ________ 의 형태였다.", "s": "구름 불기둥"}, {"q": "[Scripture Fill in the Blank] 모세는 ________ 보다 ________ 였다.", "s": "모세 겸손"}, {"q": "이스라엘 백성이 처음으로 그들을 계수한 것은 출애굽 둘째 해인 2월 1일 ________ 광야에서였다.", "s": "첫 번째 카운팅 포인트"}, {"q": "열두 정탐꾼은 사십 일 동안 가나안을 염탐했고, 악한 메시지를 전하기 위해 돌아온 ________ 정탐꾼도 있었다.", "s": "스파이가 악의적인 행위를 신고함"}, {"q": "사람들은 하나님께서 그들을 가나안으로 인도하실 수 있다고 믿지 않았기 때문에, 하나님께서는 그 세대가 죽을 때까지 ________ 년 동안 광야에서 방황하도록 그들을 정죄하셨습니다.", "s": "래프팅의 40년"}, {"q": "코라, 다단, 아비람은 모세와 샤론의 지도부를 공격했고, 그 결과 그들에게 입을 열었다 ________.", "s": "코라 반란"}, {"q": "하룻밤 사이에 아론의 막대가 발아하고 꽃을 피우고 ________ (으) 로 끝났으며, 하나님께서 아론의 가족을 제사장으로 선택하셨음을 증명했습니다.", "s": "아론의 지팡이 싹"}, {"q": "모압 왕은 마술사 발람에게 이스라엘을 저주해 달라고 요청했습니다.", "s": "발라, 발란, 제발."}, {"q": "발람의 ________ 은 (는) 발람을 꾸짖고 이스라엘을 저주하는 것을 막으며 말하기 시작했다.", "s": "당나귀 열기"}, {"q": "모세는 므리바에서 하나님을 거룩하게 하지 않고 지팡이로 ________ 반석을 쳐서 가나안에 들어가지 못했습니다.", "s": "모세가 바위를 치다"}, {"q": "레위인들은 성막의 일에서 모든 ________ 을 (를) 대신하기 위해 이스라엘 사람들 중에서 하나님에 의해 선택되었다.", "s": "레위인의 선택"}, {"q": "나지르인들은 강한 술이나 가벼운 와인을 마시거나 면도기를 사용하여 머리를 깎거나 시체를 ________ 할 수 없도록 주님께 봉헌하겠다고 맹세했다.", "s": "나지르인"}, {"q": "애굽을 떠난 후 이스라엘 백성이 처음 계수되었을 때, 스무 살이 넘은 사람이 몇 명이나 싸울 수 있었습니까?", "s": "포인트 수", "o": "A.약 600,000명,B.약 60,000명,C.약 600만 명,D.약 6,000명"}, {"q": "열두 정탐꾼 중 누가 주의를 기울여 가나안에 들어갈 수 있었는가?", "s": "갈렙과 여호수아", "o": "A.갈렙과 여호수아,B.모세와 아론,C.엘르아살과 비느하스,D.미리암과 훌"}, {"q": "모세가 광야에서 놋뱀을 들어 올림으로써 무엇을 예측했는가?", "s": "브론즈 스네이크 미리보기", "o": "A.모세의 권위,B.그리스도는 높이 들리셨고 사람들은 구원을 위해 그분을 바라봅니다.,C.이스라엘의 의학,D.광야에 대한 하나님의 심판"}, {"q": "발람은 이스라엘을 몇 번이나 저주하려고 했습니까?", "s": "발람의 축복", "o": "A.한 번은 성공했습니다.,B.세 번이면 축복이 됩니다.,C.일곱 번이나 실패했다.,D.전혀 아님"}, {"q": "누가 모세를 데리고 이스라엘 백성을 가나안으로 인도했습니까?", "s": "여호수아가 대신합니다"}, {"q": "광야에서 이스라엘 백성의 여정의 징조는 무엇인가?", "s": "시작 표시"}, {"q": "이스라엘 백성이 미디안과 싸웠을 때 비느하스는 전염병을 막기 위해 무엇을 했는가?", "s": "페니하지드 역병", "o": "A.번제 드리기,B.매춘한 이스라엘인과 미디안인을 총살함,C.백성을 고백과 기도로 이끄십시오,D.제단을 쌓고 호흡할 신을 찾는다"}, {"q": "다음 중 민수기에서 하느님께 대한 백성의 불순종을 나타내는 것은 무엇입니까? (복수 선택)", "s": "국민의 불순종", "o": "A.정탐꾼들은 나쁜 믿음을 갚았고 하나님께서 그들을 가나안으로 인도하실 수 있다는 것을 믿지 않았습니다.,B.Korah는 Moscialon의 리더십을 공격합니다,C.싯딤에서 모압 여인들과 간음하며 바알브올을 숭배함,D.만나에 대한 하나님에 대한 감사와 찬양"}, {"q": "민수기에 나오는 하나님의 신실한 행적에는 무엇이 포함되는가? (복수 선택)", "s": "하나님의 신실하심", "o": "A.구름 기둥 불 기둥 가이드, 만나 메추라기 보급품,B.구출을 위해 놋뱀을 준비하고 발람의 입을 축복하십시오,C.반역한 1세대들은 모두 가나안에 들어가게 하소서.,D.여호수아를 일으켜 모세를 계승하게 하십시오"}, {"q": "하나님께 분리된 레위인들의 의무는 무엇이었는가? (복수 선택)", "s": "레위기의 의무", "o": "A.성막을 운반하기 위한 기구,B.초막 문 지키기,C.이스라엘의 모든 장자를 대신하여 하나님께로 돌아오라,D.이스라엘의 산업으로서 토지 공유"}, {"q": "나지르인들의 성화를 위한 의식은 무엇인가? (복수 선택)", "s": "나사렛 의식", "o": "A.주류 없음,B.면도 금지,C.시체에 접근하지 마십시오.,D.초막에 거주해야 함"}, {"q": "출애굽기의 첫 세대 (스무 살 이상) 가 광야에 떨어질 때까지 이스라엘 백성이 40 년 동안 광야에서 방황했다는 숫자 기록.", "s": "40년"}, {"q": "고라의 일행이 반란을 일으켰을 때 모세는 고라, 다단, 아비람을 칼로 죽였다.", "s": "코라 엔딩"}, {"q": "모세는 놋뱀을 들어 올렸다. 불뱀에 물린 사람은 놋뱀을 보고 살았다.", "s": "청동뱀이 살아남다"}, {"q": "발람은 이스라엘을 저주하고 모압 왕 발락을 기쁘게 하는 데 성공했습니다.", "s": "발람"}, {"q": "모세는 하나님을 공경하지 않고 지팡이로 반석을 두 번 쳤기 때문에 가나안에 들어갈 수 없었습니다.", "s": "모세의 통로"}, {"q": "레위인들은 가나안 땅을 이스라엘의 열두 지파로 나누었다.", "s": "리바이스는 숙소가 없습니다"}, {"q": "모세를 비방하여 나병에 걸린 미리암은 7일 동안 진영 밖에 갇혀 있었다.", "s": "밀리킨 나병"}, {"q": "민수기에서 “충실한 하나님” 과 “불순종하는 백성” 의 대조는 무엇인가? 이것은 오늘날 그리스도인들에게 무엇을 상기시켜 주는가?", "s": "신실하고 불순종하는"}, {"q": "놋뱀의 사건은 그리스도의 구원을 어떻게 예고했는가? (요한복음 3:14 ~ 15 참조.)", "s": "그리스도를 예언하는 청동 뱀"}, {"q": "모세는 순종하지 않는 백성 (예: 정탐꾼들의 사건 이후) 을 위해 반복해서 중재했다. 모세의 중보기도의 특징과 영적 의의에 대해 민수기 14장과 함께 이야기해 주세요.", "s": "모세 중보기도"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220944825','圣经导览','申命记','摩西在摩押平原的临终三讲：回顾神四十年信实带领，重申十诫与示玛最大诫命，陈明祝福咒诅、劝选生命。本卷是旧约信仰纲要，确立独一真神与全心爱神的核心，为进迦南的新一代立定圣约根基。','[{"type": "verse", "q": "【经文填空】以色列啊，你要________！耶和华我们神是________的主。你要________爱耶和华你的神。", "o": "《申命记》6章4节", "s": "示玛", "a": "听|独一|尽心、尽性、尽力"}, {"type": "verse", "q": "【经文填空】人活着不是单靠________，乃是靠耶和华口里所出的________。", "o": "《申命记》8章3节", "s": "神的话", "a": "食物|一切话"}, {"type": "verse", "q": "【经文填空】我将________陈明在你面前，所以你要________，使你和你的后裔都得存活。", "o": "《申命记》30章19节", "s": "拣选生命", "a": "生死祸福|拣选生命"}, {"type": "verse", "q": "【经文填空】只要你________耶和华你的神，________，爱他，尽心尽性________他。", "o": "《申命记》10章12节", "s": "神的要求", "a": "敬畏|遵行他的道|事奉"}, {"type": "verse", "q": "【经文填空】以后以色列中再没有兴起________像摩西的。他是耶和华________所认识的。", "o": "《申命记》34章10节", "s": "摩西", "a": "先知|面对面"}, {"type": "verse", "q": "【经文填空】但你们在那里必寻求你们的神——耶和华；你________、________寻求他的时候，就必寻见。", "o": "《申命记》4章29节", "s": "寻求神", "a": "尽心|尽性"}, {"type": "verse", "q": "【经文填空】隐秘的事是属耶和华我们神的；惟有________的事是永远属我们和我们子孙的，好叫我们________这律法上的一切话。", "o": "《申命记》29章29节", "s": "隐秘与明显", "a": "明显|遵行"}, {"type": "fill", "q": "申命记是摩西在________平原对新一代以色列人的三篇讲道，是他的临终遗言。", "o": "", "s": "地点", "a": "摩押"}, {"type": "fill", "q": "申命记重申的是神在________山（何烈山）颁布的律法。", "o": "", "s": "律法来源", "a": "西奈"}, {"type": "fill", "q": "祝福的话要宣告在________山上。", "o": "", "s": "祝福之山", "a": "基利心"}, {"type": "fill", "q": "咒诅的话要宣告在________山上。", "o": "", "s": "咒诅之山", "a": "以巴路"}, {"type": "fill", "q": "摩西按手在________身上，立他为接班人，吩咐他刚强壮胆。", "o": "", "s": "接班人", "a": "约书亚"}, {"type": "fill", "q": "摩西死在________山上，享年一百二十岁，是耶和华亲自埋葬了他。", "o": "", "s": "摩西之死", "a": "尼波"}, {"type": "fill", "q": "申命记6章7节吩咐父母要________教训儿女神的话，无论坐在家里、行在路上都要谈论。", "o": "", "s": "教训儿女", "a": "殷勤"}, {"type": "fill", "q": "申命记规定以色列的王要为自己抄录律法书，________诵读，一生学习敬畏神。", "o": "", "s": "君王之法", "a": "平生"}, {"type": "fill", "q": "申命记7章吩咐以色列人对待迦南七族的态度是：把他们________，不可与他们立约，也不可怜恤他们。", "o": "", "s": "迦南七族", "a": "灭绝净尽"}, {"type": "fill", "q": "摩西在约旦河东设立了三座________，让误杀人的可以逃到那里避难，等候审判。", "o": "", "s": "逃城", "a": "逃城"}, {"type": "single", "q": "申命记主要是谁在约旦河东的临终讲道？", "o": "A.亚伦,B.约书亚,C.摩西,D.迦勒", "s": "作者", "a": "C"}, {"type": "single", "q": "“示玛”（申6:4-5）的核心要求是什么？", "o": "A.严守安息日不可做工,B.尽心、尽性、尽力爱耶和华你的神,C.每年三次上耶路撒冷朝圣,D.不可吃不洁之物", "s": "最大诫命", "a": "B"}, {"type": "single", "q": "摩西死后葬在何处？", "o": "A.西奈山,B.尼波山,C.何烈山,D.橄榄山", "s": "摩西之死", "a": "B"}, {"type": "single", "q": "申命记中祝福与咒诅分别宣告在哪两座山上？", "o": "A.基利心山宣告祝福，以巴路山宣告咒诅,B.以巴路山宣告祝福，基利心山宣告咒诅,C.西奈山宣告祝福，何烈山宣告咒诅,D.锡安山宣告祝福，橄榄山宣告咒诅", "s": "两山", "a": "A"}, {"type": "single", "q": "申18章预言“耶和华要从你们弟兄中间给你兴起一位先知像我”，基督徒认为这指向谁？", "o": "A.约书亚,B.以利亚,C.耶稣基督,D.施洗约翰", "s": "先知预言", "a": "C"}, {"type": "single", "q": "申命记18章说“不可效法那些国民行可憎的事”，其中特别禁止的是什么？", "o": "A.吃不洁之物,B.交鬼、占卜、观兆,C.不可剃胡须,D.不可穿混纺衣服", "s": "可憎之俗", "a": "B"}, {"type": "single", "q": "摩西在申命记32章所作的歌，主要内容是什么？", "o": "A.赞美迦南地的富饶,B.见证神的信实与以色列的悖逆，呼天唤地作见证,C.祝福十二支派,D.预言弥赛亚降生", "s": "摩西之歌", "a": "B"}, {"type": "multiple", "q": "申命记吩咐以色列人要把神的话（多选）", "o": "A.系在手上为记号,B.戴在额上为经文,C.写在房屋门框和城门上,D.藏在约柜里不让人看见", "s": "神的话", "a": "A|B|C"}, {"type": "multiple", "q": "摩西在申命记中回顾神在旷野四十年的作为包括（多选）", "o": "A.降吗哪养活百姓,B.使磐石出水,C.以云柱火柱引路,D.百姓的衣服没有穿破、脚没有肿", "s": "旷野回顾", "a": "A|B|C|D"}, {"type": "multiple", "q": "申命记17章对以色列王的告诫包括哪些？（多选）", "o": "A.不可为自己加添马匹,B.不可多立妃嫔、C.银子金子不可为自己多加,D.要专靠耶和华你的神", "s": "君王之戒", "a": "A|B|C"}, {"type": "multiple", "q": "申命记32章4节说神是“磐石”，他的本性包括？（多选）", "o": "A.作为完全,B.诚实无伪、公义正直,C.偏待富人,D.反复无常", "s": "神的本性", "a": "A|B"}, {"type": "judge", "q": "申命记是摩西在过了约旦河、进入迦南之后写成的。", "o": "", "s": "写作背景", "a": "错"}, {"type": "judge", "q": "申命记重申的十诫与出埃及记20章一字不差、完全相同。", "o": "", "s": "十诫", "a": "错"}, {"type": "judge", "q": "摩西因在米利巴击打磐石、没有尊神为圣，神不许他进入迦南。", "o": "", "s": "摩西之过", "a": "对"}, {"type": "judge", "q": "申命记应许：以色列人若顺服就必在应许之地长久蒙福，悖逆则必被赶散。", "o": "", "s": "祝福咒诅", "a": "对"}, {"type": "judge", "q": "约书亚是靠自己的勇敢和谋略接替摩西作领袖的。", "o": "", "s": "接班", "a": "错"}, {"type": "judge", "q": "申命记吩咐以色列人进入迦南后，可以与当地居民通婚、彼此来往，只要不拜他们的神就行。", "o": "", "s": "分别为圣", "a": "错"}, {"type": "judge", "q": "申命记18章15节预言“耶和华要从你们弟兄中间给你兴起一位先知像我”，使徒行传3章引用这段经文指向耶稣基督。", "o": "", "s": "先知预言", "a": "对"}, {"type": "essay", "q": "为什么说申命记6:4-5“示玛”是整本申命记乃至旧约信仰的核心？请结合本卷内容说明。", "o": "", "s": "示玛", "a": "示玛先宣告“耶和华我们神是独一的主”，确立一神信仰，与迦南多神偶像划清界限；接着要求“尽心、尽性、尽力爱”神，把信仰从外在仪式转向全人的委身。申命记全卷都在展开这一诫命：历史回顾显明神配得爱，律法细则教导如何去爱，祝福咒诅显明爱与不爱的后果。它成为以色列人每日诵念的信仰告白，也是耶稣所引用的最大诫命（太22:37）。"}, {"type": "essay", "q": "摩西一生忠心却未能进入迦南，这对今天的信徒有什么提醒？", "o": "", "s": "摩西之死", "a": "摩西与神面对面说话、一生忠心，却因在米利巴击打磐石、没有尊神为圣（申32:51），神不许他进迦南。这提醒信徒：神是圣洁公义的，属灵领袖也不能例外，一次的不顺服也有后果，当存敬畏之心顺服到底。但神仍恩待摩西，让他远望全地、亲自埋葬他（申34章）。信徒在失败中仍可经历神的恩典，同时更要谨慎自守、善始善终。"}, {"type": "essay", "q": "申命记28章的祝福与咒诅对今天的基督徒有什么意义？请结合新约说明。", "o": "", "s": "祝福咒诅", "a": "申命记28章陈明顺服蒙福、悖逆受祸的原则，显明神的圣洁公义与信实。新约中，基督在十字架上为我们成了咒诅（加3:13），使我们脱离律法的咒诅，得以因信承受亚伯拉罕的祝福。但这不等于可以任意犯罪——神管教儿女的原则仍在（来12:6），顺服仍带来平安与祝福。今天的意义在于：珍惜基督已付的代价，以感恩的心顺服神，活出蒙福的生命。"}]','','quiz','[{"title": "历史回顾（1-4章）", "points": ["摩西回顾出埃及与旷野四十年", "加低斯巴尼亚：探子事件的教训", "神为以色列争战，胜亚摩利二王", "神信实带领，悖逆的上一代倒毙旷野", "分地给河东二支派半作产业", "劝勉新一代记念神恩，不可重蹈覆辙"]}, {"title": "最大诫命（5-11章）", "points": ["重申十诫（与出20章略有差异）", "示玛：耶和华是独一的主，当尽心尽性尽力爱神", "把神的话殷勤教训儿女，系在手上、写在门框上", "不可加添删减神的命令", "记念出埃及：曾为奴仆，神救赎你", "试探中不可试探耶和华你的神"]}, {"title": "律法细则（12-26章）", "points": ["集中一处敬拜的条例（耶路撒冷）", "社会公义：顾念孤儿寡妇、寄居者", "君王、祭司、先知的法则", "假先知的辨别：预言成就与否", "什一奉献：分别为圣归耶和华", "安息年豁免债务，释放希伯来奴仆", "圣洁生活的具体规范"]}, {"title": "祝福与咒诅（27-28章）", "points": ["基利心山宣告祝福，以巴路山宣告咒诅", "顺服蒙福：城里田间、出入都蒙福", "悖逆受祸：疾病、饥荒、被掳的警告", "立约的严肃性：生死祸福陈明在前", "心里受割礼：真割礼是心里的", "神能将咒诅变为祝福（因祂爱你）"]}, {"title": "传承与告别（29-34章）", "points": ["劝选生命：拣选生命就得存活", "天地作见证：摩西的郑重嘱托", "约书亚接班——刚强壮胆，神必同在", "摩西之歌：耶和华是磐石，祂的作为完全", "摩西祝福各支派", "摩西120岁眼目未昏花，死于尼波山", "神亲自埋葬摩西，以色列哀哭三十天"]}]','','36','旧约•律法书（摩西五经）','{"en": {"title": "DEUTERONOMY", "content": "Moses in the plains of Moab speaks of the third death: Looking back on God''s forty years of faithful leadership, reaffirming the Ten Commandments and the greatest commandment of Shema, stating blessings, curses, and exhortations to life. This volume is the outline of the Old Testament faith, which establishes the core of the one true God and the love of God with all our hearts, and establishes the covenant foundation for the new generation entering Canaan.", "instructions": "", "guide": [{"title": "Historical Review (Chapters 1-4)", "points": ["Moses looks back on forty years of Exodus and the wilderness", "Kadeshbania: Lessons from the Probe Incident", "God fights for Israel, defeating the two Amorites", "God faithfully led the rebellious previous generation to die in the wilderness.", "Distribution of land to the Hedong Second Branch semi-work industry", "Encourage the new generation to remember God''s grace and not repeat it"]}, {"title": "The Greatest Commandment (chapters 5-11)", "points": ["Reaffirming the Ten Commandments (slightly different from Exodus 20)", "Shema: The Lord is the only Lord, so love God with all your heart and with all your strength.", "Discipline the children of God''s word with diligence, tie it on your hands and write it on the doorframe", "No additions or deletions of God''s commandments", "Remembering Exodus: Once a slave, God redeemed you", "Thou shalt not tempt the Lord thy God in temptation."]}, {"title": "By-Laws of the Law (chapters 12-26)", "points": ["Regulations Concerning One Place of Worship (Jerusalem)", "Social justice: caring for orphans, widows, and sojourners", "Laws of Kings, Priests, Prophets", "False Prophet Discernment: Prophecy Fulfilled or Not", "Tithing: Sacred to Jehovah", "Sabbath year debt forgiveness, release of Hebrew slaves", "Specific norms of holy living"]}, {"title": "Blessings and Curses (27-28)", "points": ["Mount Gerizim declares blessing, Mount Ebal declares curse", "Obedience to Blessings: Blessings in the fields and in and out of the city", "Disobedient Bane: Warning of Disease, Famine, Captivity", "The seriousness of the covenant: life and death are in front of you", "Circumcision of the Heart: True Circumcision of the Heart", "God can turn a curse into a blessing (because He loves you)"]}, {"title": "Inheritance and Farewell (Chapters 29-34)", "points": ["Persuade Life: Pick Life and Survive", "Heaven and earth testify: Moses'' solemn commission", "Joshua takes over - just be strong and bold, and God will be with you", "Song of Moses: Jehovah is the Rock, and His Works are Perfect", "Moses blessed the tribes", "Moses, 120 years old, blindfolded, died on Mount Nebo.", "God Himself buried Moses, and Israel wept for thirty days."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] O Israel, thou shalt ________! The Lord our God is the Lord of ________. You shall ________ love the Lord your God.", "s": "shema"}, {"q": "[Scripture Fill in the Blank] Man does not live by ________ alone, but by ________ from the mouth of the Lord.", "s": "God&apos;s Words"}, {"q": "[Scripture Fill in the Blank] I declare ________ before thee, therefore thou shalt ________, that thou and thy seed may live.", "s": "Pick Life"}, {"q": "[Scripture Fill in the Blank] As long as you ________ the Lord your God, ________, love him with all your heart and soul ________ him.", "s": "God''s Requirements"}, {"q": "[Scripture Fill in the Blank] There will be no more ________ like Moses in Israel. He is known to the Lord ________.", "s": "Moses"}, {"q": "[Scripture Fill in the Blank] But ye shall seek the Lord your God there; and thou shalt find him when thou seek him.", "s": "Seek God"}, {"q": "[Scripture Fill in the Blank] The secret things belong to the Lord our God; but the things which are ________ belong to us and to our children for ever, that we may ________ all the words of this law.", "s": "Hidden and obvious"}, {"q": "Deuteronomy is Moses'' last words to a new generation of Israelites in the plains of ________.", "s": "Location"}, {"q": "Deuteronomy restates the law that God promulgated on Mount ________ (Mount Horeb).", "s": "Sources of Law"}, {"q": "Blessings are to be proclaimed on the ________ mountain.", "s": "Mountain of Blessings"}, {"q": "The curse shall be pronounced on the ________ mountain.", "s": "Cursed Mountain"}, {"q": "Moses laid his hands on ________, made him his successor, and bade him be strong and courageous.", "s": "successor"}, {"q": "Moses died on Mount ________ at the age of one hundred and twenty, and the Lord Himself buried him.", "s": "The Death of Moses"}, {"q": "Deuteronomy 6: 7 tells parents to ________ to teach their children the word of God, and to talk about it both at home and on the road.", "s": "Teaching children a lesson"}, {"q": "Deuteronomy requires the kings of Israel to transcribe the Book of the Law for themselves, to read it ________, and to learn the fear of God throughout their lives.", "s": "Law of Kings"}, {"q": "Deuteronomy 7 commands the Israelites to treat the seven Canaanite tribes in such a way that they cannot make a covenant with them or have mercy on them.", "s": "Canaanite Seven Clans"}, {"q": "Moses set up three ________ buildings on the east side of the Jordan River, so that the murderer could flee there and take refuge, awaiting trial.", "s": "Escape City"}, {"q": "Who was the main preacher of Deuteronomy at his deathbed east of the Jordan River?", "s": "Author", "o": "A.aaron,B.Joshua.,C.Moses,D.Caleb"}, {"q": "What are the core requirements of “Shema” (Deuteronomy 6: 4-5)?", "s": "The Greatest Commandment", "o": "A.Do not work on the Sabbath,B.Love Jehovah thy God with all thy heart, thy soul, and thy strength.,C.Pilgrimage to Jerusalem three times a year,D.Do not eat unclean things"}, {"q": "Where was Moses buried after his death?", "s": "The Death of Moses", "o": "A.西奈山,B.Mount Nebo,C.Mount Horeb,D.Mount of Olives"}, {"q": "On which two mountains are the blessing and the curse declared in Deuteronomy?", "s": "Two Mountains", "o": "A.Mount Gerizim declares blessing, Mount Ebal declares curse,B.Mount Ebal proclaims blessing, Mount Gerizim proclaims curse,C.Mount Sinai declares blessing, Mount Ho declares curse,D.Mount Zion proclaims blessing, Mount Olive proclaims curse"}, {"q": "To whom do Christians think the prophecy in Deuteronomy 18 that “the Lord will raise up unto thee a prophet like unto me out of the midst of thy brethren” points?", "s": "Prophecy", "o": "A.Joshua.,B.elijah,C.Jesus,D.John the Baptist"}, {"q": "What specifically is forbidden in Deuteronomy 18, which says, “Thou shalt not imitate the abominations of those nations”?", "s": "Abominable customs", "o": "A.Eat something unclean,B.Ghosts, divination, omens,C.No shaving,D.No blended garments"}, {"q": "What is the main content of the song Moses wrote in Deuteronomy 32?", "s": "Song of Moses", "o": "A.Praise the richness of the land of Canaan,B.Witness God''s faithfulness and Israel''s rebellion, calling the heavens and the earth to bear witness,C.Blessing OF the twelve tribes,D.Prophesy of the Messiah''s Birth"}, {"q": "Deuteronomy commands Israel to take the word of God (multiple choice)", "s": "God&apos;s Words", "o": "A.Tied on the hand as a mark,B.Wear it on your forehead as a scripture,C.Write on the doorframe and city gates of the house,D.Hide in the ark of the covenant from view"}, {"q": "In Deuteronomy, Moses recalls God''s deeds in the wilderness for forty years, including (Multiple Choice)", "s": "Wilderness retrospectives", "o": "A.Descent of Manna to Feed the People,B.to get the rock out of the water.,C.Guide with Cloud Pillar Fire Pillar,D.The clothes of the people are not worn, the feet are not swollen"}, {"q": "What does Deuteronomy 17 include in its admonition to the king of Israel? (Multiple choice)", "s": "Ring of Kings", "o": "A.Don''t add horses to yourself,B.Not many concubines, C. Silver and gold cannot be added for themselves,D.Rely exclusively on the Lord your God"}, {"q": "Deuteronomy 32: 4 says that God is a “rock” whose nature includes? (Multiple choice)", "s": "Nature of God", "o": "A.as a complete,B.Honesty, Honesty and Integrity,C.Preference for the rich,D.fickle"}, {"q": "Deuteronomy was written after Moses crossed the Jordan into Canaan.", "s": "Writing background"}, {"q": "The Ten Commandments reiterated in Deuteronomy are exactly the same as in Exodus 20.", "s": "The Ten Commandments"}, {"q": "摩西因在米利巴击打磐石、没有尊神为圣，神不许他进入迦南。", "s": "Passage of Moses"}, {"q": "The Book of Deuteronomy promises that if the Israelites obey, they will be blessed in the promised land for a long time, and if they rebel, they will be scattered.", "s": "Blessed Curse"}, {"q": "Joshua succeeded Moses as leader by his own courage and strategy.", "s": "Succession: "}, {"q": "Deuteronomy commanded the Israelites to enter into Canaan, to intermarry with the inhabitants of the land, and to deal with one another, as long as they did not worship their gods.", "s": "<bpt i=\"1\" type=\"bold\">{}</bpt>CONSECRATION<ept i=\"1\">{}</ept>"}, {"q": "Deuteronomy 18:15 prophesies that “the Lord shall raise up unto thee a prophet like unto me out of the midst of thy brethren,” and this verse is quoted in Acts 3 as referring to Jesus Christ.", "s": "Prophecy"}, {"q": "Why is Deuteronomy 6: 4-5 “Shema” central to the whole book of Deuteronomy and even to the Old Testament faith? Please combine the descriptions with the contents of this volume.", "s": "shema"}, {"q": "What is a reminder to today''s believers that Moses remained faithful throughout his life but failed to enter Canaan?", "s": "The Death of Moses"}, {"q": "What do the blessings and curses of Deuteronomy 28 mean to Christians today? Please incorporate the New Testament description.", "s": "Blessed Curse"}]}, "ja": {"title": "申命記", "content": "モーセはモアブの平野で三度目の死について語っています。すなわち，神の40年にわたる忠実な指導を振り返り，十戒とシマの最も偉大な戒めを再確認し，命に対する祝福，呪い，勧めを述べています。この巻は旧約聖書の信仰の概要であり，唯一の真の神の核心と神の愛を心を尽くして確立し，カナンに入る新しい世代のための聖約の基礎を確立しています。", "instructions": "", "guide": [{"title": "歴史的見直し（第1 ～ 4章）", "points": ["モーセは出エジプト記と荒野の40年を振り返る", "カデシュバニア：プローブ事件からの教訓", "神がイスラエルのために戦い、二人のアモリ人を打ち負かす", "神は反抗的な前の世代を忠実に導いて荒野で死なせました。", "河東第二支店セミワーク産業への土地配分", "新しい世代に，神の恵みを思い出し，それを繰り返さないように勧める"]}, {"title": "最も重要な戒め（ 5 － 11章）", "points": ["十戒の再確認（出エジプト記20章とは少し異なります）", "シェマ：主は唯一の主ですから、心を尽くし、力を尽くして神を愛してください。", "神の言葉の子供たちを注意深く懲らしめ，手に結び，戸枠に書く", "神の戒めの追加や削除はしない", "出エジプト記：かつて奴隷であったあなたを神は贖われた", "あなたの神、主を試みてはならない。"]}, {"title": "法細則（ 12 ～ 26章）", "points": ["一つの礼拝所に関する規則（エルサレム）", "社会正義：孤児、未亡人、滞在者の世話", "王、司祭、預言者の律法", "偽預言者の識別：預言の成就か否か", "什分の一：エホバに神聖", "安息日の債務免除、ヘブライ人奴隷の解放", "聖なる生活の特定の規範"]}, {"title": "祝福と呪い（ 27 － 28 ）", "points": ["ゲリジム山が祝福を宣言し、エバル山が呪いを宣言", "祝福への従順：畑での祝福と街の内外での祝福", "不従順な災い：病気、飢餓、囚われの身の警告", "聖約の深刻さ：生と死が目の前にある", "心臓の割礼：心臓の真の割礼", "神は呪いを祝福に変えることができます（神はあなたを愛しておられるからです）"]}, {"title": "相続と別れ（ 29 ～ 34章）", "points": ["人生を説得する：人生を選んで生き残る", "天と地が証する：モーセの厳粛な任務", "ジョシュアが引き継ぎます。強く大胆になれば、神があなたと共におられます", "モーセの歌：エホバは岩であり，その業は完全である", "モーセは部族を祝福した", "目隠しされていた120歳のモーセは，ネボ山で亡くなりました。", "神ご自身がモーセを葬られたので、イスラエルは三十日間泣きました。"]}], "quizzes": [{"q": "〔聖句の穴埋め〕おお、イスラエルよ、あなたは________ ！私たちの神である主は________の主です。あなたの神である主を________愛しなさい。", "s": "シェマ"}, {"q": "〔聖句の穴埋め〕人は________だけで生きるのではなく，主の口から________によって生きるのです。", "s": "神の言葉"}, {"q": "〔聖句の穴埋め〕私はあなたの前に________を宣言します。したがって、あなたとあなたの子孫が生きるために________をしなければなりません。", "s": "ピックライフ"}, {"q": "〔聖句の穴埋め〕あなたが________あなたの神、________の主である限り、心と魂を尽くして________彼を愛してください。", "s": "神の要求"}, {"q": "〔聖句の穴埋め〕イスラエルには，もはやモーセのような________はありません。彼は主に知られています________。", "s": "モーセ"}, {"q": "〔聖句の穴埋め〕しかし、あなたがたはそこであなたがたの神、主を尋ね求めなければならない。あなたがたが主を尋ね求めるとき、あなたがたは主を見いだすであろう。", "s": "神を求める"}, {"q": "〔聖句の穴埋め〕秘密のものは，わたしたちの神である主に属します。しかし， ________であるものは，この律法のすべての言葉を________するために，永遠にわたしたちとわたしたちの子孫に属します。", "s": "隠れていてわかりやすい"}, {"q": "申命記は， ________の平原に住む新しい世代のイスラエル人に対するモーセの最後の言葉です。", "s": "地点"}, {"q": "申命記は，神が________山（ホレブ山）で公布された律法を再確認しています。", "s": "法の源泉"}, {"q": "祝福は________山で宣言されるべきです。", "s": "祝福の山"}, {"q": "呪いは________山で発音されるものとします。", "s": "呪われた山"}, {"q": "モーセは________に手を置き，彼を後継者にし，強く勇敢になるように命じました。", "s": "後継者"}, {"q": "モーセは百二十歳で________山で死に，主ご自身がモーセを葬られました。", "s": "モーセの死"}, {"q": "申命記6 ： 7は，両親に________神の言葉を子供たちに教え，家庭でも旅先でもそれについて話すように言います。", "s": "子供にレッスンを教える"}, {"q": "申命記は，イスラエルの王たちに，律法の書を自分のために書き起こし， ________それを読み，生涯を通して神を恐れることを学ぶよう求めています。", "s": "王の法則"}, {"q": "申命记7章吩咐以色列人对待迦南七族的态度是：把他们________，不可与他们立约，也不可怜恤他们。", "s": "カナン人の七つの一族"}, {"q": "モーセはヨルダン川の東岸に3棟の________建物を建て、殺人者がそこに逃げて逃げ出し、裁判を待つことができるようにしました。", "s": "エスケープシティ"}, {"q": "ヨルダン川の東にある死の床で，申命記の主要な説教者はだれでしたか。", "s": "作家", "o": "A.アロン,B.ヨシュア,C.モーセ,D.ケイレブ"}, {"q": "「シェマ」（申命記6 ： 4 － 5 ）の中心的な要件は何ですか。", "s": "最大の戒め", "o": "A.安息日には働かないでください,B.あなたの心と魂と力を尽くして，あなたの神エホバを愛しなさい。,C.エルサレム巡礼（年3回）,D.汚れたものを食べてはいけません"}, {"q": "モーセは死後，どこに埋葬されましたか。", "s": "モーセの死", "o": "A.シナイ山,B.ネボ山,C.He Lieshan,D.オリーブの山"}, {"q": "申命記では祝福と呪いはどの2つの山に宣言されていますか。", "s": "ツー・マウンテンズ", "o": "A.ゲリジム山が祝福を宣言し、エバル山が呪いを宣言,B.エバル山が祝福を宣言し、ゲリジム山が呪いを宣言,C.シナイ山が祝福を宣言、ホー山が呪いを宣言,D.シオンの山が祝福を宣言し、オリーブの山が呪いを宣言"}, {"q": "申命記18章の「主はあなたの兄弟の中から，わたしのような預言者をあなたのために立てられる」という預言は，だれのためのものだと思いますか。", "s": "予言", "o": "A.ヨシュア,B.エリヤ，i,C.イエス･キリスト,D.バプテスマのヨハネ"}, {"q": "申命記18章で具体的に禁止されていることは何ですか。「これらの国民の憎むべきことを模倣してはならない」と述べていますか。", "s": "忌まわしい習慣", "o": "A.汚れたものを食べる,B.幽霊、占い、前兆,C.髭剃りなし,D.ブレンドされた衣服はありません"}, {"q": "申命記32章でモーセが書いた歌の主な内容は何ですか。", "s": "モーセの歌", "o": "A.カナンの地の豊かさを賛美する,B.神の忠実さとイスラエルの反逆を証し，天と地を呼んで証しをする,C.12部族の祝福,D.メシアの誕生の預言"}, {"q": "申命記は，イスラエルに神の言葉を受けるよう命じています（複数選択）", "s": "神の言葉", "o": "A.マークとして手に結ばれている,B.聖典のように額につけてください,C.家の玄関枠と街の門に書いてください,D.聖約の箱の中に隠れよう"}, {"q": "申命記では、モーセは（多肢選択）を含む40年間の荒野での神の業を思い出します。", "s": "荒野の振り返り", "o": "A.人々を養うためのマナの降臨,B.岩を水から出すことができます。,C.雲柱火柱ガイド,D.人々の衣服は着用されておらず、足は腫れていません"}, {"q": "申命記17章には，イスラエルの王への訓戒に何が含まれていますか。（複数選択可）", "s": "リング・オブ・キングス", "o": "A.自分自身に馬を追加しないでください,B.側室はそれほど多くはありません、C.シルバーとゴールドは追加できません,D.あなたの神である主のみに頼る"}, {"q": "申命記32 ： 4は、神はその性質に含まれる「岩」であると述べています。（複数選択可）", "s": "神の性質", "o": "A.完全なものとして,B.誠実さ、正直さ、誠実さ,C.富裕層への嗜好,D.気まぐれ"}, {"q": "申命記は，モーセがヨルダン川を渡ってカナンに入った後に書かれました。", "s": "背景を書き込んでいます"}, {"q": "申命記で繰り返されている十戒は，出エジプト記20章とまったく同じです。", "s": "十戒"}, {"q": "神はモーセがメリバの岩を打ち、神を聖別しなかったので、彼がカナンに入ることを禁じられた。", "s": "摩西之过"}, {"q": "申命記は，イスラエルの人々が従うならば，約束の地で長い間祝福され，反抗するならば散らされると約束しています。", "s": "祝福された呪い"}, {"q": "ジョシュアは，自分の勇気と戦略によってモーセを指導者として継承しました。", "s": "継承"}, {"q": "申命記は、イスラエル人にカナンに入り、その地の住民と結婚し、彼らが自分たちの神々を崇拝しない限り、互いに対処するように命じました。", "s": "別々に神聖"}, {"q": "申命記18 ： 15は，「主はあなたの兄弟の中から，わたしのような預言者をあなたのために立てられる」と預言しています。この節は使徒行伝3章で，イエス・キリストを指して引用されています。", "s": "予言"}, {"q": "申命記6 ： 4 － 5「シーマ」は，なぜ申命記全体，さらには旧約聖書の信仰の中心なのでしょうか。この巻の内容と説明を組み合わせてください。", "s": "シェマ"}, {"q": "モーセが生涯忠実であったにもかかわらず，カナンに入ることができなかったことを，今日の信者に思い出させるものは何でしょうか。", "s": "モーセの死"}, {"q": "申命記28章の祝福とのろいは，今日のクリスチャンにとってどのような意味がありますか。新約聖書の説明を取り入れてください。", "s": "祝福された呪い"}]}, "ko": {"title": "신명기", "content": "모압 평원에서 모세는 세 번째 죽음에 대해 이야기합니다. 하나님의 신실한 지도자 40 년을 되돌아보고, 축복, 저주 및 삶에 대한 권고를 말하면서 십계명과 스마의 가장 큰 계명을 재확인합니다. 이 책은 유일한 참 하나님의 핵심과 하나님의 사랑을 온 마음으로 확립하고, 가나안에 들어가는 새로운 세대를 위한 언약의 기초를 세우는 구약 신앙의 개요이다.", "instructions": "", "guide": [{"title": "역사적 검토 (1 ~ 4장)", "points": ["모세는 출애굽 40년과 광야를 돌아보았다.", "카데시바니아: 탐사선 사건의 교훈", "하나님은 이스라엘을 위해 싸우시며 두 아모리인들을 물리치십니다.", "하나님께서는 반역한 이전 세대를 광야에서 죽도록 신실하게 인도하셨습니다.", "헤동2지점 준공산업에 토지분배", "새로운 세대가 하나님의 은혜를 기억하고 그것을 반복하지 않도록 격려하십시오."]}, {"title": "가장 위대한 계명 (5 ~ 11장)", "points": ["십계명 재확인 (출애굽기 20장과 약간 다름)", "쉐마: 주님은 유일한 주님이시니 마음을 다하고 힘을 다해 하나님을 사랑하세요.", "하나님의 말씀의 자녀들을 부지런히 훈육하고, 손에 묶고, 문틀에 기록하십시오.", "하나님의 계명을 추가하거나 삭제하지 마십시오", "출애굽기 기억하기: 한때 노예였던 하나님이 당신을 구속하셨습니다.", "시험 중에 네 하나님 여호와를 시험하지 말지니라"]}, {"title": "율법의 부칙 (12-26장)", "points": ["한 예배 장소에 관한 규정 (예루살렘)", "사회 정의: 고아, 과부, 체류자 돌보기", "왕, 사제, 선지자의 율법", "거짓 선지자 식별: 예언이 성취되었는지 여부", "십일조: 여호와께 거룩함", "안식일 연도 부채 용서, 히브리 노예 석방", "거룩한 생활의 특정 규범"]}, {"title": "축복과 저주 (27-28)", "points": ["게리짐 산은 축복을 선언하고, 에발 산은 저주를 선언합니다.", "축복에 대한 순종: 들판과 도시 안팎의 축복", "불순종 베인: 질병, 기근, 포로의 경고", "성약의 진지함: 삶과 죽음이 눈앞에 있습니다", "마음의 할례: 진정한 마음의 할례", "하나님은 저주를 축복으로 바꾸실 수 있습니다 (당신을 사랑하시기 때문에)."]}, {"title": "상속과 작별 (29-34장)", "points": ["삶을 설득하라: 삶을 선택하고 살아남기", "하늘과 땅이 증거함: 모세의 엄숙한 사명", "여호수아가 대신합니다. 강하고 담대하십시오. 그러면 하나님께서 여러분과 함께하실 것입니다.", "모세의 노래: 여호와는 반석이시니 그분의 작품은 완벽합니다", "모세가 지파들을 축복함", "120세의 모세는 눈을 가리고 느보산에서 죽었습니다.", "하나님께서는 모세를 장사하셨고 이스라엘은 삼십 일 동안 울었습니다."]}], "quizzes": [{"q": "[Scripture Fill in the Blank] 오 이스라엘아, 너는 ________ 하라! 주 우리 하나님은 ________ 의 주님이시다. 너희는 주 너희 하느님을 ________ 사랑해야 한다.", "s": "스마"}, {"q": "[Scripture Fill in the Blank] 인간은 ________ 에 의해서만 사는 것이 아니라 주님의 입에서 ________ 에 의해서 산다.", "s": "하나님의 말씀"}, {"q": "[Scripture Fill in the Blank] 내가 ________ 을 (를) 네 앞에 선언하노니, 너와 네 자손이 살리라.", "s": "생명 선택"}, {"q": "[Scripture Fill in the Blank] 네 하나님 여호와를 ___________________________________________________________________________________________________", "s": "하나님의 요구 사항"}, {"q": "[Scripture Fill in the Blank] 이스라엘에는 모세와 같은 ________ 이 더 이상 없을 것입니다. 그는 주님께 알려져 있습니다 ________.", "s": "모세"}, {"q": "[Scripture Fill in the Blank] 그러나 너희는 그곳에서 주 너희 하느님을 찾을 것이며, 그분을 찾을 때 그분을 만나게 될 것이다.", "s": "하나님을 찾으세요"}, {"q": "[Scripture Fill in the Blank] 은밀한 것은 우리 하나님 여호와의 것이요 은밀한 것은 영원히 우리와 우리 자손의 것이니 이는 우리로 이 율법의 모든 말씀을 영원히 범하게 하려 하심이라", "s": "숨겨진 명백한 정보"}, {"q": "신명기는 ________ 의 평원에서 이스라엘의 새로운 세대에 대한 모세의 마지막 말씀이다.", "s": "지점"}, {"q": "신명기는 하나님께서 ________ 산 (호렙산) 에서 선포하신 율법을 재조명합니다.", "s": "법률의 출처"}, {"q": "________ 산에서 축복이 선포되어야 합니다.", "s": "축복의 산"}, {"q": "저주는 ________ 산에서 발음되어야 합니다.", "s": "저주에 걸린 산"}, {"q": "모세는 ________ 에게 손을 얹고 그를 후계자로 삼았으며, 그에게 강하고 용감하라고 명령했다.", "s": "승계자"}, {"q": "모세는 백이십 세에 ________ 산에서 죽었고, 주님께서 친히 그를 묻으셨습니다.", "s": "모세의 죽음"}, {"q": "신명기 6장 7절 은 부모에게 ___________________________________________________________________________________________________", "s": "아이들에게 교훈을 가르치기"}, {"q": "신명기는 이스라엘 왕들이 스스로 율법책을 기록하고, ________ 을 읽고, 평생 동안 하나님에 대한 경외심을 배우도록 요구합니다.", "s": "왕의 법칙"}, {"q": "신명기 7 장은 이스라엘 백성들에게 가나안의 일곱 지파와 계약을 맺을 수 없거나 그들에게 자비를 베풀 수없는 방식으로 대우하라고 명령한다.", "s": "가나안 칠족"}, {"q": "모세는 요르단 강 동쪽에 세 개의 ________ 건물을 세워 살인자가 그곳으로 피신하여 재판을 기다릴 수 있도록 했습니다.", "s": "도시 탈출"}, {"q": "요르단 강 동쪽의 임종 때 신명기의 주요 설교자는 누구였습니까?", "s": "작성자", "o": "A.아론,B.여호수아,C.모세,D.갈렙"}, {"q": "“쉐마” 의 핵심 요건은 무엇인가? (신명기 6: 4 ~ 5)", "s": "가장 위대한 계명", "o": "A.안식일에 일하지 마십시오,B.네 마음을 다하고 목숨을 다하고 힘을 다하여 주 너의 하나님을 사랑하라.,C.1년에 세 번 예루살렘 순례,D.부정한 것을 먹지 말 것"}, {"q": "모세가 죽은 후 어디에 묻혔습니까?", "s": "모세의 죽음", "o": "A.시내산,B.느보산,C.He Lieshan,D.올리브산"}, {"q": "신명기에서 축복과 저주는 어느 두 산에서 선포됩니까?", "s": "투마운틴스", "o": "A.게리짐 산은 축복을 선언하고, 에발 산은 저주를 선언합니다.,B.에발 산은 축복을 선포하고, 게리짐 산은 저주를 선포합니다.,C.시내산은 축복을, 호산은 저주를 선포합니다.,D.시온 산은 축복을 선포하고, 올리브 산은 저주를 선포합니다."}, {"q": "그리스도인들은 “주께서 네 형제들 가운데서 나와 같은 선지자를 네게 일으키시리라” 는 신명기 18장의 예언을 누구에게 생각하는가?", "s": "예언", "o": "A.여호수아,B.엘리야,C.예수 그리스도,D.세례자 요한"}, {"q": "“그 민족들의 가증한 것을 본받지 말지니라” 는 신명기 18장에는 구체적으로 어떤 내용이 금지되어 있는가?", "s": "가증스러운 관습", "o": "A.부정한 음식 먹기,B.유령, 점쟁이, 전조,C.면도 금지,D.블렌딩 의류 없음"}, {"q": "모세가 신명기 32장에서 쓴 노래의 주요 내용은 무엇인가?", "s": "모세의 노래", "o": "A.가나안 땅의 풍요로움을 찬양하세요,B.하나님의 신실하심과 이스라엘의 반역을 목격하고 하늘과 땅을 증언하라,C.열두 지파의 축복,D.메시아의 탄생을 예언함"}, {"q": "신명기는 이스라엘에게 하나님의 말씀을 취하라고 명령합니다 (복수 선택)", "s": "하나님의 말씀", "o": "A.손에 표시로 묶음,B.경전처럼 이마에 쓰세요.,C.숙소 문틀과 도시 문에 글씨를 쓰세요.,D.시야에서 내려다보며 언약궤에 숨어라"}, {"q": "신명기에서 모세는 (객관식) 을 포함하여 40 년 동안 광야에서 하나님의 행사를 회상합니다.", "s": "황무지 회고", "o": "A.만나의 하강으로 백성 먹이주기,B.바위를 물에서 꺼낼 수 있습니다.,C.구름기둥 불기둥 가이드,D.사람들의 옷은 입지 않았고, 발은 부어 오르지 않았습니다."}, {"q": "신명기 17장은 이스라엘 왕에 대한 훈계에 무엇을 포함하고 있는가? (복수 선택)", "s": "왕의 반지", "o": "A.자신에게 말을 추가하지 마세요.,B.첩이 많지 않다, C. 실버와 골드는 단독으로 추가할 수 없습니다.,D.오직 주 너의 하나님께 의지하라"}, {"q": "신명기 32장 4절에 따르면 하나님은 본성에 포함되는 “반석” 이십니다. (복수 선택)", "s": "하나님의 본성", "o": "A.완전한,B.정직, 정직, 성실,C.부자에 대한 선호도,D.변덕쟁이"}, {"q": "신명기는 모세가 요단을 건너 가나안으로 간 후에 기록되었다.", "s": "배경 글쓰기"}, {"q": "신명기에서 반복되는 십계명은 출애굽기 20 장과 정확히 동일합니다.", "s": "십계명"}, {"q": "하나님께서는 모세가 므리바에서 반석을 치고 하나님을 거룩하게 하지 않았기 때문에 가나안으로 들어가는 것을 금하셨습니다.", "s": "모세의 통로"}, {"q": "신명기는 이스라엘 백성이 순종하면 약속의 땅에서 오랫동안 축복을 받고 반역하면 흩어질 것이라고 약속합니다.", "s": "축복받은 저주"}, {"q": "여호수아는 자신의 용기와 전략으로 모세를 지도자로 계승했다.", "s": "승계"}, {"q": "신명기는 이스라엘 백성들이 가나안에 들어가 그 땅의 주민들과 혼인하고 그들의 신들을 섬기지 않는 한 서로 상대하라고 명령했다.", "s": "별도로 거룩함"}, {"q": "신명기 18장 15절 은 “주께서 네 형제 중에서 나와 같은 선지자 하나를 너를 위하여 일으키시리라” 고 예언하며, 이 구절은 사도행전 3장에서 예수 그리스도를 언급하는 것으로 인용된다.", "s": "예언"}, {"q": "왜 신명기 6장 4 ~ 5절 “세마” 가 신명기 전체와 구약전서 신앙의 중심이 되는가? 이 볼륨의 내용과 설명을 결합하십시오.", "s": "스마"}, {"q": "모세가 평생 충실했지만 가나안에 들어가지 못했다는 오늘날의 신앙인들에게 상기시켜 주는 것은 무엇인가?", "s": "모세의 죽음"}, {"q": "신명기 28장 의 축복과 저주는 오늘날 그리스도인들에게 어떤 의미인가? 신약전서 설명을 포함하십시오.", "s": "축복받은 저주"}]}}');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220950001','圣经导览','约书亚记','约书亚记记载以色列人在约书亚带领下过约旦河、攻取耶利哥、征服迦南、分地为业的历史。“刚强壮胆”“至于我和我家必定事奉耶和华”等名言，见证神信实的应许与得胜的秘诀。','[{"type": "verse", "q": "【经文填空】你当________！因为你必使这百姓得这地为业，就是我向他们列祖起誓应许________。", "a": "刚强壮胆|赐给他们的地", "ref": "《约书亚记》1章6节", "s": "", "o": "约书亚记1章6节"}, {"type": "verse", "q": "【经文填空】这律法书不可离开你的口，总要________，好使你谨守遵行这书上所写的一切话。如此，你的道路就可以________，凡事顺利。", "a": "昼夜思想|亨通", "ref": "《约书亚记》1章8节", "s": "", "o": "约书亚记1章8节"}, {"type": "verse", "q": "【经文填空】我岂没有吩咐你吗？你当刚强壮胆！不要________，也不要________；因为你无论往哪里去，耶和华你的神必与你同在。", "a": "惧怕|惊惶", "ref": "《约书亚记》1章9节", "s": "", "o": "约书亚记1章9节"}, {"type": "verse", "q": "【经文填空】约书亚吩咐百姓说：你们要________，因为明天耶和华必在你们中间________。", "a": "自洁|行奇事", "ref": "《约书亚记》3章5节", "s": "", "o": "约书亚记3章5节"}, {"type": "verse", "q": "【经文填空】到了第七次，祭司吹角的时候，约书亚吩咐百姓说：________吧！因为耶和华已经把城交给你们了。", "a": "呼喊", "ref": "《约书亚记》6章16节", "s": "", "o": "约书亚记6章16节"}, {"type": "verse", "q": "【经文填空】约书亚祷告耶和华说：日头啊，你要________；月亮啊，你要________。", "a": "停在基遍|止在亚雅仑谷", "ref": "《约书亚记》10章12节", "s": "", "o": "约书亚记10章12节"}, {"type": "verse", "q": "【经文填空】至于我和我家，我们必定________。", "a": "事奉耶和华", "ref": "《约书亚记》24章15节", "s": "", "o": "约书亚记24章15节"}, {"type": "fill", "q": "摩西死后，________接续他带领以色列人进迦南。", "a": "约书亚", "s": ""}, {"type": "fill", "q": "探子到耶利哥，________接待他们，并用朱红线绳帮助他们逃脱。", "a": "喇合", "s": ""}, {"type": "fill", "q": "以色列人过约旦河时，抬约柜的祭司脚一入水，水就________，立起成垒。", "a": "断绝", "s": ""}, {"type": "fill", "q": "以色列人在________行割礼，滚去了埃及的羞辱。", "a": "吉甲", "s": ""}, {"type": "fill", "q": "以色列人吃了迦南地的出产，第二天________就止住了。", "a": "吗哪", "s": ""}, {"type": "fill", "q": "________私取当灭之物，连累以色列人在艾城战败。", "a": "亚干", "s": ""}, {"type": "fill", "q": "________人用陈饼破衣设诡计，与以色列人立约。", "a": "基遍", "s": ""}, {"type": "fill", "q": "迦勒________岁时，仍向约书亚求希伯仑山地为业。", "a": "八十五", "s": ""}, {"type": "fill", "q": "以色列人设立________座逃城，使误杀人者可逃避报血仇者。", "a": "六", "s": ""}, {"type": "fill", "q": "约书亚去世时享年________岁，葬在亭拿西拉。", "a": "一百一十", "s": ""}, {"type": "single", "q": "谁接续摩西带领以色列人进迦南？", "o": ["约书亚", "迦勒", "以利亚撒", "非尼哈"], "a": "约书亚", "s": ""}, {"type": "single", "q": "喇合用什么记号帮助以色列探子？", "o": ["朱红线绳", "白色旗子", "铜号", "火把"], "a": "朱红线绳", "s": ""}, {"type": "single", "q": "以色列人过约旦河时，谁抬约柜先下水？", "o": ["祭司", "利未人", "族长", "勇士"], "a": "祭司", "s": ""}, {"type": "single", "q": "耶利哥城墙是怎样倒塌的？", "o": ["绕城七日后百姓呼喊", "攻城锤撞倒", "大地震动", "河水冲垮"], "a": "绕城七日后百姓呼喊", "s": ""}, {"type": "single", "q": "亚干私藏了什么当灭之物？", "o": ["示拿衣服和金银", "偶像", "兵器", "粮食"], "a": "示拿衣服和金银", "s": ""}, {"type": "single", "q": "日头停留的神迹发生在与谁的争战中？", "o": ["五王联军", "耶利哥王", "艾城王", "北方诸王"], "a": "五王联军", "s": ""}, {"type": "single", "q": "约书亚临终在哪里与百姓立约？", "o": ["示剑", "吉甲", "示罗", "伯特利"], "a": "示剑", "s": ""}, {"type": "multiple", "q": "以下哪些是约书亚记中的著名事件？", "o": ["过约旦河", "耶利哥城倒塌", "日头停留", "分地为业"], "a": "过约旦河,耶利哥城倒塌,日头停留,分地为业", "s": ""}, {"type": "multiple", "q": "以色列人过约旦河之后、攻耶利哥之前，发生了哪些事？", "o": ["吉甲行割礼", "守逾越节", "吗哪止住", "耶和华军队的元帅显现"], "a": "吉甲行割礼,守逾越节,吗哪止住,耶和华军队的元帅显现", "s": ""}, {"type": "multiple", "q": "以下哪些人物的信心值得我们学习？", "o": ["喇合", "迦勒", "约书亚", "亚干"], "a": "喇合,迦勒,约书亚", "s": ""}, {"type": "multiple", "q": "约书亚遗命劝勉百姓的内容包括：", "o": ["专靠耶和华", "不可与外邦人掺杂", "谨守遵行律法", "选择事奉耶和华"], "a": "专靠耶和华,不可与外邦人掺杂,谨守遵行律法,选择事奉耶和华", "s": ""}, {"type": "judge", "q": "约书亚是摩西的帮手，原名何西阿。", "a": "对", "s": ""}, {"type": "judge", "q": "以色列人过约旦河时正值水涨，神使河水断绝成垒。", "a": "对", "s": ""}, {"type": "judge", "q": "耶利哥城攻陷后，城中一切金银都归约书亚个人所有。", "a": "错", "s": ""}, {"type": "judge", "q": "艾城初战失败，是因为亚干私取了当灭之物。", "a": "对", "s": ""}, {"type": "judge", "q": "基遍人与以色列人立约是出于诚实正直。", "a": "错", "s": ""}, {"type": "judge", "q": "日头在天当中停住，不急速下落，约有一日之久。", "a": "对", "s": ""}, {"type": "judge", "q": "约书亚死后葬在以法莲山地的亭拿西拉。", "a": "对", "s": ""}, {"type": "essay", "q": "“刚强壮胆”的秘诀是什么？（结合约书亚记1章6-9节）", "a": "秘诀在于神的同在、神的话语和神的应许。神三次吩咐约书亚“当刚强壮胆”，根基是“耶和华你的神必与你同在”以及“这律法书不可离开你的口，总要昼夜思想”。刚强壮胆不是靠自己的勇气，而是靠神的同在壮胆、靠神的话语得力、靠神的应许站立。", "s": ""}, {"type": "essay", "q": "亚干犯罪给我们什么警戒？", "a": "亚干贪恋示拿衣服和金银，私藏当灭之物，一人犯罪连累全营，以色列人在艾城战败。警戒我们：贪心是万恶之根；罪具有连累性，会影响群体；神是圣洁轻慢不得的；必须彻底认罪对付罪，才能恢复与神的关系和得胜的生活。", "s": ""}, {"type": "essay", "q": "“至于我和我家，我们必定事奉耶和华”对今日家庭有何意义？", "a": "这是约书亚在示剑向全民的立志宣告，对今日家庭意义重大：信仰需要主动抉择，而非被动承袭传统；家长要带领全家事奉神，作属灵的头；在众人面前表明立场，不随波逐流；每个家庭都当立定心志，以事奉耶和华为家训。", "s": ""}]','','study','[{"title": "蒙召与过约旦河（1-5章）", "points": ["摩西死后，约书亚蒙召接续：“你当刚强壮胆”", "昼夜思想律法书，道路亨通、凡事顺利", "差派探子往耶利哥，喇合接待并藏匿", "祭司抬约柜脚踏约旦河，水断绝立起成垒", "取十二块石头立为纪念", "吉甲行割礼、守逾越节，吗哪止住", "耶和华军队的元帅向约书亚显现"]}, {"title": "攻取耶利哥与艾城（6-8章）", "points": ["绕城七日，百姓呼喊，耶利哥城墙塌陷", "喇合一家因朱红线绳得救", "亚干取当灭之物，连累艾城初战失败", "除罪之后，以色列人攻取艾城", "基遍人用陈饼破衣设诡计求和立约"]}, {"title": "征服迦南（9-12章）", "points": ["基遍求救，五王联盟攻打基遍", "约书亚祷告：日头停在基遍，月亮止在亚雅仑谷", "耶和华从天降大冰雹击杀敌军", "南方战役与北方战役，击败三十一个王", "“耶和华为以色列争战”", "迦南地大体平定，战争止息"]}, {"title": "分地为业（13-22章）", "points": ["迦勒八十五岁仍求希伯仑山地为业", "九个半支派拈阄分得迦南地", "设立六座逃城，误杀人者可逃避报仇", "利未人得四十八座城", "河东二支派半筑坛，几乎引起内战", "“耶和华应许赐福的话，一句都没有落空”"]}, {"title": "约书亚遗命（23-24章）", "points": ["劝勉专靠耶和华，不可与外邦人掺杂通婚", "示剑立约，回顾神的恩典历史", "“至于我和我家，我们必定事奉耶和华”", "立大石为证，百姓承诺事奉耶和华", "约书亚一百一十岁去世，葬亭拿西拉", "约瑟骸骨葬于示剑，大祭司以利亚撒去世"]}]','','37','旧约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220950002','圣经导览','士师记','士师记记载约书亚死后，以色列人陷入“犯罪—受苦—呼求—拯救”的循环。神兴起俄陀聂、底波拉、基甸、参孙等士师施行拯救。“那时以色列中没有王，各人任意而行”道出全书悲剧的根源。','[{"type": "verse", "q": "【经文填空】耶和华________，士师就拯救他们脱离________人的手。", "a": "兴起士师|抢夺他们", "ref": "《士师记》2章16节", "s": "", "o": "士师记2章16节"}, {"type": "verse", "q": "【经文填空】耶和华的使者向基甸显现，对他说：大能的________啊，耶和华与你________！", "a": "勇士|同在", "ref": "《士师记》6章12节", "s": "", "o": "士师记6章12节"}, {"type": "verse", "q": "【经文填空】三队的人就吹角，打破瓶子，左手拿着________，右手拿着角，喊叫说：________！", "a": "火把|耶和华和基甸的刀", "ref": "《士师记》7章20节", "s": "", "o": "士师记7章20节"}, {"type": "verse", "q": "【经文填空】这孩子一出胎就归神作________，他必起首拯救以色列人脱离________人的手。", "a": "拿细耳人|非利士", "ref": "《士师记》13章5节", "s": "", "o": "士师记13章5节"}, {"type": "verse", "q": "【经文填空】神啊，求你________我，神啊，求你赐我这一次的________，使我在非利士人身上报那剜我双眼的仇。", "a": "眷念|力量", "ref": "《士师记》16章28节", "s": "", "o": "士师记16章28节"}, {"type": "verse", "q": "【经文填空】耶和华啊，愿你的仇敌都这样________！愿爱你的人如________出现，光辉烈烈！", "a": "灭亡|日头", "ref": "《士师记》5章31节", "s": "", "o": "士师记5章31节"}, {"type": "verse", "q": "【经文填空】那时，以色列中________，各人________。", "a": "没有王|任意而行", "ref": "《士师记》21章25节", "s": "", "o": "士师记21章25节"}, {"type": "fill", "q": "以色列人离弃耶和华，去事奉________和亚斯他录。", "a": "巴力", "s": ""}, {"type": "fill", "q": "第一位士师是________，迦勒兄弟基纳斯的儿子。", "a": "俄陀聂", "s": ""}, {"type": "fill", "q": "以笏是________人，左手便利，用两刃剑刺杀摩押王伊矶伦。", "a": "便雅悯", "s": ""}, {"type": "fill", "q": "女先知________与巴拉一同出战，击败迦南王耶宾的将军西西拉。", "a": "底波拉", "s": ""}, {"type": "fill", "q": "________用帐棚的橛子，趁西西拉睡熟将他钉死。", "a": "雅亿", "s": ""}, {"type": "fill", "q": "基甸率领________人，带着火把、瓦瓶和角，大胜米甸大军。", "a": "三百", "s": ""}, {"type": "fill", "q": "基甸的儿子________杀了兄弟七十人，在示剑自立为王。", "a": "亚比米勒", "s": ""}, {"type": "fill", "q": "________是妓女的儿子，作了基列的士师，许愿献上女儿。", "a": "耶弗他", "s": ""}, {"type": "fill", "q": "参孙作________，力气的秘密在于不可用剃头刀剃头。", "a": "拿细耳人", "s": ""}, {"type": "fill", "q": "________用美色探出参孙力气的秘密，非利士人便剃了他的头发。", "a": "大利拉", "s": ""}, {"type": "single", "q": "士师在以色列中的主要职分是？", "o": ["审判兼拯救者", "祭司", "先知", "君王"], "a": "审判兼拯救者", "s": ""}, {"type": "single", "q": "以笏用什么兵器杀死摩押王伊矶伦？", "o": ["两刃剑", "弓箭", "长枪", "石头"], "a": "两刃剑", "s": ""}, {"type": "single", "q": "西西拉死于谁之手？", "o": ["雅亿", "底波拉", "巴拉", "以笏"], "a": "雅亿", "s": ""}, {"type": "single", "q": "基甸求印证时，神使什么神迹出现？", "o": ["羊毛一夜干湿", "火烧祭物", "日影倒退", "天降吗哪"], "a": "羊毛一夜干湿", "s": ""}, {"type": "single", "q": "参孙最后在哪里与非利士人同归于尽？", "o": ["大衮庙", "迦萨城门", "利希", "梭烈谷"], "a": "大衮庙", "s": ""}, {"type": "single", "q": "米迦私设神堂，用什么人作祭司？", "o": ["利未人", "便雅悯人", "但人", "以法莲人"], "a": "利未人", "s": ""}, {"type": "single", "q": "基比亚惨案中，哪个支派几乎被灭绝？", "o": ["便雅悯", "但", "以法莲", "流便"], "a": "便雅悯", "s": ""}, {"type": "multiple", "q": "以下哪些是士师记中的士师？", "o": ["俄陀聂", "以笏", "底波拉", "基甸"], "a": "俄陀聂,以笏,底波拉,基甸", "s": ""}, {"type": "multiple", "q": "士师循环的四个阶段是？", "o": ["犯罪", "受苦", "呼求", "拯救"], "a": "犯罪,受苦,呼求,拯救", "s": ""}, {"type": "multiple", "q": "参孙违背拿细耳人条例的行为有哪些？", "o": ["从狮尸中取蜜吃", "头发被剃", "与大利拉亲近", "喝浓酒"], "a": "从狮尸中取蜜吃,头发被剃", "s": ""}, {"type": "multiple", "q": "底波拉之歌颂赞的内容包括：", "o": ["耶和华的得胜", "自愿献上的首领", "雅亿的勇敢", "爱神者如日头出现"], "a": "耶和华的得胜,自愿献上的首领,雅亿的勇敢,爱神者如日头出现", "s": ""}, {"type": "judge", "q": "士师记中记载的士师共有十二位。", "a": "对", "s": ""}, {"type": "judge", "q": "以笏是左手便利的人。", "a": "对", "s": ""}, {"type": "judge", "q": "基甸因拆毁巴力的坛，被称为耶路巴力。", "a": "对", "s": ""}, {"type": "judge", "q": "参孙的母亲也是一位拿细耳人。", "a": "错", "s": ""}, {"type": "judge", "q": "耶弗他许愿战胜亚扪人后，要将女儿终身献给神作处女。", "a": "错", "s": ""}, {"type": "judge", "q": "米迦的母亲为儿子铸造了偶像。", "a": "对", "s": ""}, {"type": "judge", "q": "士师记的结语是“各人任意而行”。", "a": "对", "s": ""}, {"type": "essay", "q": "士师循环给今日信徒什么警戒？", "a": "以色列人一再陷入“犯罪—受苦—呼求—拯救—又犯罪”的循环，警戒我们：罪有习惯性，不彻底对付就会重蹈覆辙；离弃神必带来管教；神的怜悯一再施行拯救；真正的悔改应当带来持久的顺服，而非循环往复。信徒要靠圣灵治死罪行，打破循环。", "s": ""}, {"type": "essay", "q": "基甸从胆怯到刚强的转变说明什么？", "a": "基甸起初在酒榨打麦子躲避米甸人，自称“我家在玛拿西支派中是至贫的，我在我父家是至微小的”。神却称他为“大能的勇士”，多次给他印证（羊毛干湿、听见敌人的梦），最终他靠三百人、火把瓦瓶大胜米甸。说明：神看人是看他未来的潜能；神的同在使胆怯者刚强；得胜不在乎人数多寡，而在乎耶和华。", "s": ""}, {"type": "essay", "q": "为什么说“以色列中没有王，各人任意而行”是全书的钥匙？", "a": "这句话在17章6节和21章25节首尾呼应，道出士师时代混乱的根源：没有公认的权柄，人人都以自己为王，宗教混乱（米迦偶像）、道德败坏（基比亚惨案）接踵而至。它预表人心需要真正的王——神自己，最终指向基督作王。今日教会和信徒也需要顺服基督的主权。", "s": ""}]','','study','[{"title": "士师循环的开端（1-3章）", "points": ["约书亚死后，以色列人未能赶出迦南各族", "行耶和华眼中看为恶的事，事奉巴力", "犯罪—受苦—哀求—拯救的循环模式确立", "俄陀聂：迦勒兄弟基纳斯之子，首位士师", "以笏：左手便利，刺杀摩押王伊矶伦", "珊迦用赶牛棍杀六百非利士人", "国中太平八十年"]}, {"title": "底波拉与基甸（4-8章）", "points": ["女先知底波拉与巴拉出战西西拉", "雅亿用帐棚橛子钉死西西拉", "底波拉之歌颂赞耶和华的得胜", "基甸蒙召：“大能的勇士啊，耶和华与你同在”", "三百人、火把瓦瓶，大胜米甸大军", "基甸造以弗得，成了以色列人的网罗", "基甸晚节不保，家生祸患"]}, {"title": "耶弗他与参孙（9-16章）", "points": ["亚比米勒杀兄弟七十人，约坦说树的比喻", "耶弗他许愿，忍痛献上女儿", "参孙一出胎就归神作拿细耳人", "参孙娶非利士女子，设谜语", "大利拉探出秘密，头发被剃、眼睛被剜", "参孙末后祷告，拉倒大衮庙与仇敌同死", "他死时杀的人比活着杀的还多"]}, {"title": "米迦的偶像（17-18章）", "points": ["米迦为母亲铸造偶像，私设神堂", "雇利未人作祭司，“以为耶和华必赐福”", "但支派夺取米迦的偶像和祭司", "但人另建但城，设立偶像直到被掳", "宗教混乱：“那时以色列中没有王”", "私设敬拜的鉴戒"]}, {"title": "基比亚的惨案（19-21章）", "points": ["利未人的妾在基比亚被凌辱致死", "切成十二块，送往以色列四境", "以色列人与便雅悯支派开战", "便雅悯支派几乎灭绝，仅剩六百人", "为便雅悯人设法娶妻，保存支派", "全书结语：各人任意而行"]}]','','38','旧约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220950003','圣经导览','路得记','路得记是士师时代的一束光：摩押女子路得跟随婆婆拿俄米归回伯利恒，蒙波阿斯以至近亲属的身份救赎。她成为大卫的曾祖母，被列入基督家谱。“你的神就是我的神”传颂千古。','[{"type": "verse", "q": "【经文填空】你往哪里去，我也往________；你在哪里住宿，我也在________；你的国就是我的国，你的神就是我的神。", "a": "那里去|那里住宿", "ref": "《路得记》1章16节", "s": "", "o": "路得记1章16节"}, {"type": "verse", "q": "【经文填空】你在哪里死，我也在________，也葬在哪里。除非________能使你我相离，不然，愿耶和华重重地降罚与我。", "a": "哪里死|死", "ref": "《路得记》1章17节", "s": "", "o": "路得记1章17节"}, {"type": "verse", "q": "【经文填空】愿耶和华照你所行的________你。你来投靠耶和华以色列神的________下，愿你满得他的赏赐。", "a": "赏赐|翅膀", "ref": "《路得记》2章12节", "s": "", "o": "路得记2章12节"}, {"type": "verse", "q": "【经文填空】我就是你的婢女路得。求你用你的衣襟________我，因为你是我一个________。", "a": "遮盖|至近的亲属", "ref": "《路得记》3章9节", "s": "", "o": "路得记3章9节"}, {"type": "verse", "q": "【经文填空】波阿斯正从伯利恒来，对收割的人说：________！", "a": "愿耶和华与你们同在", "ref": "《路得记》2章4节", "s": "", "o": "路得记2章4节"}, {"type": "verse", "q": "【经文填空】耶和华是应当________的！因为今日没有撇下你，使你无________。愿这孩子在以色列中得名声。", "a": "称颂|至近的亲属", "ref": "《路得记》4章14节", "s": "", "o": "路得记4章14节"}, {"type": "verse", "q": "【经文填空】不要叫我________，要叫我________，因为全能者使我受了大苦。", "a": "拿俄米|玛拉", "ref": "《路得记》1章20节", "s": "", "o": "路得记1章20节"}, {"type": "fill", "q": "路得记的故事发生在________时代。", "a": "士师", "s": ""}, {"type": "fill", "q": "以利米勒带着妻子________和两个儿子迁往摩押地。", "a": "拿俄米", "s": ""}, {"type": "fill", "q": "路得是________女子，俄珥巴是她的嫂子。", "a": "摩押", "s": ""}, {"type": "fill", "q": "路得到________的田间拾取麦穗。", "a": "波阿斯", "s": ""}, {"type": "fill", "q": "波阿斯是以利米勒本族的亲戚，是至近的________。", "a": "亲属", "s": ""}, {"type": "fill", "q": "路得在波阿斯田间拾了约一________大麦带回家。", "a": "伊法", "s": ""}, {"type": "fill", "q": "拿俄米叫路得夜里到________去，躺在波阿斯的脚下。", "a": "禾场", "s": ""}, {"type": "fill", "q": "那位比波阿斯更近的亲属，因怕于________有碍，放弃了赎权。", "a": "产业", "s": ""}, {"type": "fill", "q": "从前以色列人办理交易立约，以________为证。", "a": "脱鞋", "s": ""}, {"type": "fill", "q": "路得所生的儿子名叫________，是耶西的父亲。", "a": "俄备得", "s": ""}, {"type": "single", "q": "路得的丈夫名叫什么？", "o": ["玛伦", "基连", "以利米勒", "波阿斯"], "a": "玛伦", "s": ""}, {"type": "single", "q": "“拿俄米”这个名字的意思是？", "o": ["甜", "苦", "恩慈", "喜乐"], "a": "甜", "s": ""}, {"type": "single", "q": "路得在谁的田里拾麦穗？", "o": ["波阿斯", "以利米勒", "拿俄米", "俄备得"], "a": "波阿斯", "s": ""}, {"type": "single", "q": "波阿斯与以利米勒的关系是？", "o": ["本族亲戚", "亲兄弟", "朋友", "邻舍"], "a": "本族亲戚", "s": ""}, {"type": "single", "q": "那位更近的亲属为什么放弃赎权？", "o": ["怕于产业有碍", "没有钱", "不喜欢路得", "年纪太大"], "a": "怕于产业有碍", "s": ""}, {"type": "single", "q": "俄备得是谁的父亲？", "o": ["耶西", "大卫", "波阿斯", "撒门"], "a": "耶西", "s": ""}, {"type": "single", "q": "路得记共有几章？", "o": ["四章", "三章", "五章", "六章"], "a": "四章", "s": ""}, {"type": "multiple", "q": "拿俄米一家遭遇了哪些变故？", "o": ["伯利恒遭饥荒", "以利米勒去世", "两个儿子去世", "剩下三个寡妇"], "a": "伯利恒遭饥荒,以利米勒去世,两个儿子去世,剩下三个寡妇", "s": ""}, {"type": "multiple", "q": "波阿斯恩待路得的表现有哪些？", "o": ["吩咐仆人故意留麦穗", "请她与收割的人同吃", "称赞她的贤德", "保护她不受欺负"], "a": "吩咐仆人故意留麦穗,请她与收割的人同吃,称赞她的贤德,保护她不受欺负", "s": ""}, {"type": "multiple", "q": "至近亲属的责任包括：", "o": ["赎回弟兄所卖的产业", "娶寡嫂为她留后", "为被杀者报血仇", "抚养孤儿"], "a": "赎回弟兄所卖的产业,娶寡嫂为她留后,为被杀者报血仇", "s": ""}, {"type": "multiple", "q": "路得的美好品格有哪些？", "o": ["孝敬婆婆", "忠诚专一", "勤劳肯干", "谦卑柔和"], "a": "孝敬婆婆,忠诚专一,勤劳肯干,谦卑柔和", "s": ""}, {"type": "judge", "q": "路得是摩押女子。", "a": "对", "s": ""}, {"type": "judge", "q": "俄珥巴跟随拿俄米回到了伯利恒。", "a": "错", "s": ""}, {"type": "judge", "q": "波阿斯是拿俄米丈夫以利米勒的亲兄弟。", "a": "错", "s": ""}, {"type": "judge", "q": "拿俄米婆媳回到伯利恒时，正是收割大麦的时候。", "a": "对", "s": ""}, {"type": "judge", "q": "波阿斯是第一位有赎买权的人。", "a": "错", "s": ""}, {"type": "judge", "q": "脱鞋是以色列人办理交易立约的凭据。", "a": "对", "s": ""}, {"type": "judge", "q": "路得是马太福音家谱中提到的四位女性之一。", "a": "对", "s": ""}, {"type": "essay", "q": "路得“你的神就是我的神”的抉择有何意义？", "a": "路得本是摩押女子，拜假神，却因婆婆拿俄米美好的见证，决志归向耶和华。这是信心的抉择、立约的委身：她撇下本国、本族、父家，如同亚伯拉罕蒙召。神大大赐福她的抉择，使她从拾麦穗的外邦女子，成为大卫的曾祖母、基督家谱中的一员。", "s": ""}, {"type": "essay", "q": "波阿斯如何预表基督？", "a": "波阿斯是至近的亲属，甘愿付代价赎回路得和以利米勒的产业，预表基督道成肉身成为我们的“至近亲属”，付上生命的代价救赎我们。波阿斯的恩慈（恩待穷人）、圣洁（持守律法）、慷慨（厚赐麦穗），都反映基督的品格。", "s": ""}, {"type": "essay", "q": "从拿俄米的“玛拉”到“甜”，看到神怎样的作为？", "a": "拿俄米自称玛拉（苦），觉得全能者使她受大苦、两手空空归回。但神借着路得的孝顺和波阿斯的救赎，使她得着孙子俄备得，邻舍妇女说“有这儿妇比有七个儿子还好”。神能将苦境转为祝福，祂的作为超过我们所求所想，祂从不撇下属祂的人。", "s": ""}]','','study','[{"title": "拿俄米的苦境（1章）", "points": ["士师时代，伯利恒遭遇饥荒", "以利米勒全家迁往摩押地", "丈夫、两个儿子相继去世，剩下三个寡妇", "拿俄米劝两个儿妇归回本家", "俄珥巴回去，路得紧跟不舍", "“你的国就是我的国，你的神就是我的神”", "归回伯利恒，正是收割大麦之时"]}, {"title": "路得拾麦穗（2章）", "points": ["路得到田间拾取遗落的麦穗", "恰巧到了波阿斯的田里", "波阿斯恩待路得：同吃、留麦穗、保护", "“愿耶和华照你所行的赏赐你”", "路得拾取约一伊法大麦归家", "拿俄米认出波阿斯是至近的亲属"]}, {"title": "禾场求救赎（3章）", "points": ["拿俄米为路得谋安身之处", "路得夜往禾场，躺在波阿斯脚下", "“求你用衣襟遮盖我，你是至近亲属”", "波阿斯称赞路得的贤德", "还有一位比他更近的亲属", "波阿斯赠六簸箕大麦，嘱她天亮前离开"]}, {"title": "至近亲属的救赎（4:1-12）", "points": ["波阿斯在城门口与那至近亲属谈判", "那人怕于产业有碍，放弃赎权", "脱鞋为证，交易在长老面前成立", "波阿斯娶路得为妻", "众人祝福：愿家像法勒斯家", "至近亲属甘愿付代价的预表"]}, {"title": "大卫的家谱（4:13-22）", "points": ["路得生俄备得，拿俄米得安慰", "俄备得是耶西的父，耶西是大卫的父", "从法勒斯到大卫的十代家谱", "外邦女子路得进入弥赛亚家谱", "预表基督救赎外邦人", "神在士师黑暗时代预备大卫王朝"]}]','','39','旧约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220950004','圣经导览','撒母耳记上','撒母耳记上记载以色列从士师过渡到王国：哈拿祷告得撒母耳，约柜被掳与归回，百姓求立王，扫罗悖逆被弃，大卫受膏、胜歌利亚、合神心意。“听命胜于献祭”是全书钥言。','[{"type": "verse", "q": "【经文填空】我________为要得这孩子，耶和华已将我所________赐给我了。", "a": "祈求|求的", "ref": "《撒母耳记上》1章27节", "s": "", "o": "撒母耳记上1章27节"}, {"type": "verse", "q": "【经文填空】耶和华啊，________，仆人________！", "a": "请说|敬听", "ref": "《撒母耳记上》3章9节", "s": "", "o": "撒母耳记上3章10节"}, {"type": "verse", "q": "【经文填空】撒母耳将一块石头立在米斯巴和善的中间，给石头起名叫________，说：________都帮助我们。", "a": "以便以谢|到如今耶和华", "ref": "《撒母耳记上》7章12节", "s": "", "o": "撒母耳记上7章12节"}, {"type": "verse", "q": "【经文填空】________胜于献祭，________胜于公羊的脂油。", "a": "听命|顺从", "ref": "《撒母耳记上》15章22节", "s": "", "o": "撒母耳记上15章22节"}, {"type": "verse", "q": "【经文填空】耶和华不像人看人，人是看________，耶和华是看________。", "a": "外貌|内心", "ref": "《撒母耳记上》16章7节", "s": "", "o": "撒母耳记上16章7节"}, {"type": "verse", "q": "【经文填空】耶和华使人得胜，不是用________，因为争战的胜败全在乎________。", "a": "刀用枪|耶和华", "ref": "《撒母耳记上》17章47节", "s": "", "o": "撒母耳记上17章47节"}, {"type": "verse", "q": "【经文填空】尊重我的，我必________他；藐视我的，他必被________。", "a": "重看|轻视", "ref": "《撒母耳记上》2章30节", "s": "", "o": "撒母耳记上2章30节"}, {"type": "fill", "q": "哈拿的丈夫名叫________。", "a": "以利加拿", "s": ""}, {"type": "fill", "q": "哈拿的对头________因她不生育而大大激动她。", "a": "毗尼拿", "s": ""}, {"type": "fill", "q": "以利的两个儿子________和非尼哈都是恶人，亵渎祭物。", "a": "何弗尼", "s": ""}, {"type": "fill", "q": "约柜被掳时，以利的儿妇生子起名叫________，意思是荣耀离开以色列。", "a": "以迦博", "s": ""}, {"type": "fill", "q": "约柜被放在________的庙中，神像仆倒，头和手都断了。", "a": "大衮", "s": ""}, {"type": "fill", "q": "撒母耳膏________为以色列的第一位王。", "a": "扫罗", "s": ""}, {"type": "fill", "q": "扫罗是________支派、基士的儿子。", "a": "便雅悯", "s": ""}, {"type": "fill", "q": "大卫是伯利恒人________最小的儿子。", "a": "耶西", "s": ""}, {"type": "fill", "q": "大卫用________和甩石杀死非利士勇士歌利亚。", "a": "机弦", "s": ""}, {"type": "fill", "q": "扫罗在________山与非利士人争战，阵亡沙场。", "a": "基利波", "s": ""}, {"type": "single", "q": "撒母耳的母亲是谁？", "o": ["哈拿", "毗尼拿", "亚比该", "米甲"], "a": "哈拿", "s": ""}, {"type": "single", "q": "“撒母耳”名字的含义与哪件事有关？", "o": ["从耶和华求来", "神听见祷告", "神赐福", "神拣选"], "a": "从耶和华求来", "s": ""}, {"type": "single", "q": "约柜被掳后，被放在谁的庙中？", "o": ["大衮", "巴力", "亚斯他录", "米勒公"], "a": "大衮", "s": ""}, {"type": "single", "q": "以色列人要求立王，撒母耳认为这件事的实质是？", "o": ["厌弃神作王", "羡慕列国", "撒母耳年老", "儿子不行道"], "a": "厌弃神作王", "s": ""}, {"type": "single", "q": "扫罗最终被神废弃的直接原因是什么？", "o": ["未灭尽亚玛力人，留下上好牛羊", "吉甲擅自献祭", "嫉妒追杀大卫", "求问隐多珥女巫"], "a": "未灭尽亚玛力人，留下上好牛羊", "s": ""}, {"type": "single", "q": "大卫迎战歌利亚时带了几块石子？", "o": ["五块", "一块", "七块", "三块"], "a": "五块", "s": ""}, {"type": "single", "q": "约拿单与大卫的关系是？", "o": ["生死之交", "君臣", "仇敌", "兄弟"], "a": "生死之交", "s": ""}, {"type": "multiple", "q": "哈拿之歌颂赞的内容包括：", "o": ["神使人卑微升高", "神是圣洁的磐石", "神掌管生死", "神必审判地极的人"], "a": "神使人卑微升高,神是圣洁的磐石,神掌管生死,神必审判地极的人", "s": ""}, {"type": "multiple", "q": "扫罗悖逆的表现有哪些？", "o": ["吉甲擅自献祭", "不灭尽亚玛力人", "留下上好的牛羊", "嫉妒追杀大卫"], "a": "吉甲擅自献祭,不灭尽亚玛力人,留下上好的牛羊,嫉妒追杀大卫", "s": ""}, {"type": "multiple", "q": "大卫两次不杀扫罗的原因是：", "o": ["扫罗是耶和华的受膏者", "相信神必为他伸冤", "尊重神的主权", "惧怕扫罗的权势"], "a": "扫罗是耶和华的受膏者,相信神必为他伸冤,尊重神的主权", "s": ""}, {"type": "multiple", "q": "撒母耳一身兼任的职分有：", "o": ["士师", "先知", "祭司", "君王"], "a": "士师,先知,祭司", "s": ""}, {"type": "judge", "q": "哈拿许愿若得儿子，就将他终身归耶和华，不用剃头刀剃他的头。", "a": "对", "s": ""}, {"type": "judge", "q": "以利起初误以为哈拿喝醉了酒。", "a": "对", "s": ""}, {"type": "judge", "q": "以色列人抬约柜上阵，以为约柜必能使他们得胜。", "a": "对", "s": ""}, {"type": "judge", "q": "大衮神像在大衮庙中仆倒，头和手都断了。", "a": "对", "s": ""}, {"type": "judge", "q": "扫罗是以色列人要求立王之后，神亲自拣选的。", "a": "对", "s": ""}, {"type": "judge", "q": "大卫是耶西的长子。", "a": "错", "s": ""}, {"type": "judge", "q": "扫罗在走投无路时，去隐多珥求问交鬼的妇人。", "a": "对", "s": ""}, {"type": "essay", "q": "“听命胜于献祭”对今日信徒有何提醒？", "a": "扫罗留下亚玛力上好的牛羊，辩称是要献给神，实则违背神“灭尽”的命令。撒母耳指出：神喜悦的不是宗教仪式，而是听从祂的话。提醒我们：顺服比宗教热心更重要；不能用“为神”的名义掩盖悖逆；部分顺服就是不顺服；神看重内心顺服过于外在奉献。", "s": ""}, {"type": "essay", "q": "大卫合神心意的特质有哪些？", "a": "信靠神：少年时凭信心胜歌利亚；敬畏神：两次不杀扫罗，因他是耶和华的受膏者；谦卑：蒙拣选时说“我是谁”；爱神：弹琴歌颂，写诗篇；敏锐悔改。神拣选他正因“耶和华不像人看人，人是看外貌，耶和华是看内心”。", "s": ""}, {"type": "essay", "q": "从扫罗的失败看领袖有哪些危机？", "a": "扫罗起初谦卑（被寻见时藏在器具中），后渐骄傲：吉甲擅自献祭僭越职分；不听命令留下亚玛力牛羊；嫉妒追杀大卫；最终求问交鬼。领袖危机在于：骄傲、嫉妒、不顺服、远离神。警戒领袖要持续谦卑、顺服神、保守清洁的心。", "s": ""}]','','study','[{"title": "哈拿的祷告（1-3章）", "points": ["以利加拿的妻子哈拿不生育，受毗尼拿刺激", "哈拿在圣殿痛痛哭泣，默祷祈求", "许愿将儿子终身归耶和华", "撒母耳出生：“这是我从耶和华求来的”", "哈拿之歌颂赞神的圣洁与大能", "以利二子何弗尼、非尼哈亵渎祭物", "童子撒母耳蒙召：“耶和华啊，请说，仆人敬听”"]}, {"title": "约柜被掳与归回（4-7章）", "points": ["以色列人抬约柜上阵，以为必胜", "约柜被掳，以利二子被杀，以利跌断颈项死", "以迦博：“荣耀离开以色列”", "约柜在大衮庙，大衮仆倒断头断手", "非利士人遭灾，送约柜回伯示麦", "米斯巴悔改，除掉外邦的神", "以便以谢：“到如今耶和华都帮助我们”"]}, {"title": "百姓求立王（8-12章）", "points": ["百姓厌弃士师，要求立王“像列国一样”", "撒母耳警告立王的弊端", "神拣选基士的儿子扫罗，撒母耳膏他", "扫罗战胜亚扪人，王位得坚立", "撒母耳临别赠言：立王是得罪耶和华", "吉甲重立国度"]}, {"title": "扫罗悖逆被弃（13-15章）", "points": ["吉甲擅自献祭，撒母耳宣告王位不长久", "约拿单勇闯非利士营，神使地震", "未灭尽亚玛力人，留下上好的牛羊", "“听命胜于献祭，顺从胜于公羊的脂油”", "撒母耳与扫罗断绝往来", "耶和华后悔立扫罗为王"]}, {"title": "大卫兴起（16-31章）", "points": ["撒母耳膏伯利恒少年大卫", "“耶和华不像人看人，人看外貌，耶和华看内心”", "大卫用机弦甩石杀歌利亚", "“争战的胜败全在乎耶和华”", "扫罗嫉妒：“扫罗杀死千千，大卫杀死万万”", "约拿单与大卫立约，生死之交", "大卫逃亡，两次不杀耶和华的受膏者", "隐多珥交鬼，基利波山扫罗阵亡"]}]','','40','旧约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791223563076','圣经导览','撒母耳记下','撒母耳记下记载合神心意的大卫作以色列王四十年的历史：攻取锡安建都耶路撒冷，迎约柜入城，神与大卫立约应许后裔永远作王；也记大卫犯罪跌倒、家变叛乱，显明神公义的管教与不离不弃的怜悯。','[{"type": "verse", "q": "你的家和你的国必在我面前永远________。你的国位也必坚定，直到永远。", "a": "坚立", "ref": "《撒母耳记下》7章16节", "s": "", "o": "撒母耳记下7章16节"}, {"type": "verse", "q": "主耶和华啊，你本为________，照我们耳中听见，没有可比你的；除你以外再无神。", "a": "大", "ref": "《撒母耳记下》7章22节", "s": "", "o": "撒母耳记下7章22节"}, {"type": "verse", "q": "大卫对拿单说：我________耶和华了！", "a": "得罪", "ref": "《撒母耳记下》12章13节", "s": "", "o": "撒母耳记下12章13节"}, {"type": "verse", "q": "大卫穿着细麻布的以弗得，在耶和华面前极力________。", "a": "跳舞", "ref": "《撒母耳记下》6章14节", "s": "", "o": "撒母耳记下6章14节"}, {"type": "verse", "q": "我不肯用白得之物作________，献给耶和华我的神。", "a": "燔祭", "ref": "《撒母耳记下》24章24节", "s": "", "o": "撒母耳记下24章24节"}, {"type": "verse", "q": "耶和华的灵借着我________，他的话在我口中。", "a": "说", "ref": "《撒母耳记下》23章2节", "s": "", "o": "撒母耳记下23章2节"}, {"type": "verse", "q": "主耶和华啊，惟有你是________，你的话是真实的。", "a": "神", "ref": "《撒母耳记下》7章28节", "s": "", "o": "撒母耳记下7章28节"}, {"type": "fill", "q": "大卫在________作犹大王七年零六个月，后迁都耶路撒冷。", "a": "希伯仑", "s": ""}, {"type": "fill", "q": "大卫攻取________保障，定为大卫城，建都于耶路撒冷。", "a": "锡安", "s": ""}, {"type": "fill", "q": "运约柜时，________伸手扶住约柜，被耶和华击杀。", "a": "乌撒", "s": ""}, {"type": "fill", "q": "大卫迎约柜入城极力跳舞，________从窗户看见，心里轻视他。", "a": "米甲", "s": ""}, {"type": "fill", "q": "拿单用________的故事责备大卫，使他认罪悔改。", "a": "穷人的羊羔", "s": ""}, {"type": "fill", "q": "大卫与________犯奸淫，并借刀杀害其夫乌利亚。", "a": "拔示巴", "s": ""}, {"type": "fill", "q": "________为妹他玛报仇杀了暗嫩，后起兵反叛大卫。", "a": "押沙龙", "s": ""}, {"type": "fill", "q": "押沙龙的头发被________绕住，悬挂在空中，被约押所杀。", "a": "树枝", "s": ""}, {"type": "fill", "q": "大卫数点百姓，神降________三日，以色列死了七万人。", "a": "瘟疫", "s": ""}, {"type": "fill", "q": "大卫买下耶布斯人________的禾场筑坛献祭，瘟疫就止住了。", "a": "阿珥楠", "s": ""}, {"type": "single", "q": "大卫作以色列众人的王共多少年？", "o": ["二十年", "三十年", "四十年", "五十年"], "a": "四十年", "s": ""}, {"type": "single", "q": "扫罗死后，谁被立为以色列王与大卫争战？", "o": ["伊施波设", "米非波设", "亚比筛", "约押"], "a": "伊施波设", "s": ""}, {"type": "single", "q": "米非波设是谁的儿子，大卫恩待他？", "o": ["扫罗", "约拿单", "押尼珥", "伊施波设"], "a": "约拿单", "s": ""}, {"type": "single", "q": "押沙龙在何处自立为王，反叛大卫？", "o": ["耶路撒冷", "希伯仑", "伯特利", "示剑"], "a": "希伯仑", "s": ""}, {"type": "single", "q": "谁假意投靠押沙龙，实为大卫破坏亚希多弗的计谋？", "o": ["亚比该", "户筛", "比拿雅", "以太"], "a": "户筛", "s": ""}, {"type": "single", "q": "大卫的勇士约设巴设一时击杀了多少人？", "o": ["三百人", "五百人", "八百人", "一千人"], "a": "八百人", "s": ""}, {"type": "single", "q": "耶和华借拿单与大卫所立的约被称为什么？", "o": ["西奈之约", "大卫之约", "亚伯拉罕之约", "摩押之约"], "a": "大卫之约", "s": ""}, {"type": "multiple", "q": "以下哪些是大卫攻取锡安建都后所做的事？", "o": ["迎约柜入耶路撒冷", "建造宫殿", "击败非利士人", "建造圣殿"], "a": "迎约柜入耶路撒冷,建造宫殿,击败非利士人", "s": ""}, {"type": "multiple", "q": "大卫之约的内容包括以下哪些？", "o": ["大卫后裔永远作王", "神作他后裔的父", "慈爱不离开他", "大卫亲自建圣殿"], "a": "大卫后裔永远作王,神作他后裔的父,慈爱不离开他", "s": ""}, {"type": "multiple", "q": "押沙龙叛乱期间发生了以下哪些事？", "o": ["亚希多弗投靠押沙龙", "户筛作大卫的内应", "大卫渡过约旦河逃亡", "押沙龙被约押所杀"], "a": "亚希多弗投靠押沙龙,户筛作大卫的内应,大卫渡过约旦河逃亡,押沙龙被约押所杀", "s": ""}, {"type": "multiple", "q": "以下哪些人是大卫的将领或勇士？", "o": ["约押", "亚比筛", "比拿雅", "示每"], "a": "约押,亚比筛,比拿雅", "s": ""}, {"type": "judge", "q": "大卫先在希伯仑作犹大王，后作以色列全家的王。", "a": "对", "s": ""}, {"type": "judge", "q": "乌撒伸手扶约柜被击杀，显明神不喜悦人轻忽圣物。", "a": "对", "s": ""}, {"type": "judge", "q": "米甲因轻视大卫在耶和华面前跳舞，终身没有生养儿女。", "a": "对", "s": ""}, {"type": "judge", "q": "拿单预言，因大卫的罪，刀剑必永不离开他的家。", "a": "对", "s": ""}, {"type": "judge", "q": "押沙龙叛乱成功，杀了大卫自立为王。", "a": "错", "s": ""}, {"type": "judge", "q": "所罗门是大卫与拔示巴所生的儿子。", "a": "对", "s": ""}, {"type": "judge", "q": "大卫数点百姓后，神让他从三样灾中选择一样。", "a": "对", "s": ""}, {"type": "essay", "q": "大卫之约的内容是什么？它在救恩历史中有何重要意义？", "a": "内容：神应许大卫的家和国永远坚立，后裔永远作王，神作他后裔的父，慈爱永不离开；他的儿子（所罗门）要为神建殿。意义：这是无条件的恩典之约，指向弥赛亚——耶稣基督是大卫的子孙，永远作王，应验了神的应许，是救恩历史的核心线索。", "s": ""}, {"type": "essay", "q": "简述大卫与拔示巴犯罪的经过，并谈谈给你的属灵教训。", "a": "经过：大卫在王宫平顶看见拔示巴沐浴，召她入宫犯奸淫；为遮掩罪恶，召乌利亚回家不成，便借亚扪人之手杀害乌利亚。教训：罪从眼目情欲开始，一步步滑向深渊；遮掩罪只会带来更大的罪；神必追讨，但真心认罪（诗篇51篇）必蒙赦免；罪的后果（刀剑不离家）却需承担。", "s": ""}, {"type": "essay", "q": "从押沙龙叛乱看，大卫的管教缺失带来什么后果？神又如何保守大卫？", "a": "后果：大卫对暗嫩玷辱他玛、押沙龙杀暗嫩处置失当，纵容埋下祸根；押沙龙收买人心、自立为王，大卫被迫逃离耶路撒冷，家变国乱。神的保守：借户筛破坏亚希多弗的良谋，使押沙龙追击延迟；保守大卫渡过约旦河得供应；最终押沙龙败亡，大卫复位。显明神的管教与信实同在。", "s": ""}]','','study','[{"title": "大卫登基作王（1-5章）", "points": ["为扫罗和约拿单作哀歌", "在希伯仑作犹大王七年半", "伊施波设与大卫争战", "押尼珥、约押之死", "攻取锡安建都耶路撒冷", "迁都的战略与属灵意义", "击败非利士人"]}, {"title": "约柜与大卫之约（6-10章）", "points": ["运约柜乌撒被击杀", "米甲轻视大卫跳舞", "大卫之约：后裔永远作王", "大卫之约的弥赛亚指向", "大卫感恩的祷告", "恩待米非波设", "善待约拿单的后裔"]}, {"title": "大卫犯罪与管教（11-12章）", "points": ["与拔示巴犯奸淫", "借刀杀害乌利亚", "拿单用穷人羊羔故事责备", "大卫认罪：我得罪耶和华了", "孩子病死", "所罗门出生（耶底底亚）", "刀剑必不离开大卫的家"]}, {"title": "押沙龙叛乱（13-19章）", "points": ["暗嫩玷辱他玛", "押沙龙杀暗嫩逃往基述", "押沙龙在希伯仑自立为王", "大卫逃离耶路撒冷", "户筛破坏亚希多弗计谋", "押沙龙悬挂橡树被杀", "大卫为押沙龙哀哭"]}, {"title": "晚年与数点百姓（20-24章）", "points": ["示巴的叛乱", "约押杀亚玛撒", "基遍人报复扫罗家", "大卫勇士的功绩", "数点百姓招致瘟疫", "买阿珥楠禾场筑坛", "不肯用白得之物献祭"]}]','','41','旧约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791223563523','圣经导览','列王纪上','列王纪上记载所罗门继位向神求智慧、建造圣殿的辉煌，也记他晚年随从妃嫔拜偶像导致王国分裂为南北两国；北国耶罗波安立金牛犊，先知以利亚在迦密山独战巴力先知，显明耶和华是独一真神。','[{"type": "verse", "q": "求你赐我________，可以判断你的民，能辨别是非。", "a": "智慧", "ref": "《列王纪上》3章9节", "s": "", "o": "列王纪上3章9节"}, {"type": "verse", "q": "天和天上的天尚且不足你居住的，何况我所建的这________呢？", "a": "殿", "ref": "《列王纪上》8章27节", "s": "", "o": "列王纪上8章27节"}, {"type": "verse", "q": "你们心持________要到几时呢？若耶和华是神，就当顺从耶和华。", "a": "两意", "ref": "《列王纪上》18章21节", "s": "", "o": "列王纪上18章21节"}, {"type": "verse", "q": "地震后有火，火后有________的声音。", "a": "微小", "ref": "《列王纪上》19章12节", "s": "", "o": "列王纪上19章12节"}, {"type": "verse", "q": "耶和华以色列的神啊，天上地下没有神可________你的！", "a": "比", "ref": "《列王纪上》8章23节", "s": "", "o": "列王纪上8章23节"}, {"type": "verse", "q": "我就应允你所求的，赐你聪明________。", "a": "智慧", "ref": "《列王纪上》3章12节", "s": "", "o": "列王纪上3章12节"}, {"type": "verse", "q": "坛内的面必不________，瓶里的油必不缺短。", "a": "减少", "ref": "《列王纪上》17章14节", "s": "", "o": "列王纪上17章14节"}, {"type": "fill", "q": "所罗门在________梦见耶和华，求智慧而不求富贵长寿。", "a": "基遍", "s": ""}, {"type": "fill", "q": "所罗门断两妇争子案，显明神赐他________。", "a": "智慧", "s": ""}, {"type": "fill", "q": "所罗门建造圣殿用了________年，建造宫室用了十三年。", "a": "七", "s": ""}, {"type": "fill", "q": "________女王带着香料宝石来访，见证所罗门的智慧。", "a": "示巴", "s": ""}, {"type": "fill", "q": "所罗门为妃嫔在耶路撒冷对面山上建________，随从拜偶像。", "a": "邱坛", "s": ""}, {"type": "fill", "q": "先知________撕裂新衣为十二片，预言国度将分裂。", "a": "亚希雅", "s": ""}, {"type": "fill", "q": "罗波安不听老臣劝戒，坚持________，导致十支派背叛。", "a": "重税", "s": ""}, {"type": "fill", "q": "耶罗波安在________和但铸造金牛犊，叫百姓拜。", "a": "伯特利", "s": ""}, {"type": "fill", "q": "以利亚在________树下求死，神派天使给他饼吃。", "a": "罗腾", "s": ""}, {"type": "fill", "q": "以利亚在________山上祷告，神降火烧尽祭物和水。", "a": "迦密", "s": ""}, {"type": "single", "q": "所罗门作以色列王共多少年？", "o": ["二十年", "三十年", "四十年", "五十年"], "a": "四十年", "s": ""}, {"type": "single", "q": "哪位外邦王为所罗门建殿供应香柏木和工匠？", "o": ["埃及法老", "推罗王希兰", "摩押王米沙", "亚兰王便哈达"], "a": "推罗王希兰", "s": ""}, {"type": "single", "q": "圣殿至圣所中安放的是什么？", "o": ["金灯台", "陈设饼桌", "约柜", "铜祭坛"], "a": "约柜", "s": ""}, {"type": "single", "q": "北国以色列的第一位王是谁？", "o": ["罗波安", "耶罗波安", "亚哈", "暗利"], "a": "耶罗波安", "s": ""}, {"type": "single", "q": "亚哈的王后耶洗别从何地引进巴力崇拜？", "o": ["埃及", "西顿", "摩押", "亚扪"], "a": "西顿", "s": ""}, {"type": "single", "q": "拿伯的葡萄园在什么地方？", "o": ["耶路撒冷", "耶斯列", "撒玛利亚", "伯特利"], "a": "耶斯列", "s": ""}, {"type": "single", "q": "亚哈在何处战死？", "o": ["基列的拉末", "米吉多", "耶斯列", "撒玛利亚"], "a": "基列的拉末", "s": ""}, {"type": "multiple", "q": "所罗门建造圣殿所用的材料和人力包括以下哪些？", "o": ["香柏木", "精金", "铜", "推罗的巧匠"], "a": "香柏木,精金,铜,推罗的巧匠", "s": ""}, {"type": "multiple", "q": "以利亚所行的神迹包括以下哪些？", "o": ["使寡妇的面油不缺", "使寡妇的儿子复活", "迦密山求神降火", "祷告求雨"], "a": "使寡妇的面油不缺,使寡妇的儿子复活,迦密山求神降火,祷告求雨", "s": ""}, {"type": "multiple", "q": "导致王国分裂的原因有哪些？", "o": ["所罗门晚年拜偶像", "罗波安坚持重税", "耶罗波安的野心", "神借先知预言"], "a": "所罗门晚年拜偶像,罗波安坚持重税,耶罗波安的野心,神借先知预言", "s": ""}, {"type": "multiple", "q": "以下哪些是北国以色列的王？", "o": ["耶罗波安", "亚哈", "暗利", "约沙法"], "a": "耶罗波安,亚哈,暗利", "s": ""}, {"type": "judge", "q": "所罗门求智慧不求富贵，神连富贵尊荣也赐给他。", "a": "对", "s": ""}, {"type": "judge", "q": "圣殿奉献时，耶和华的荣光充满了圣殿。", "a": "对", "s": ""}, {"type": "judge", "q": "示巴女王送给所罗门许多金子、香料和宝石。", "a": "对", "s": ""}, {"type": "judge", "q": "耶罗波安立金牛犊是为方便百姓敬拜耶和华。", "a": "错", "s": ""}, {"type": "judge", "q": "以利亚吩咐人拿住巴力的先知，在基顺河边杀了他们。", "a": "对", "s": ""}, {"type": "judge", "q": "以利亚在罗腾树下求死后，神用旋风接他升天。", "a": "错", "s": ""}, {"type": "judge", "q": "先知米该雅预言亚哈上基列的拉末必阵亡。", "a": "对", "s": ""}, {"type": "essay", "q": "所罗门由盛转衰的原因是什么？给你什么教训？", "a": "原因：妃嫔众多（七百妃三百嫔）引诱他随从拜西顿女神亚斯她录、摩洛等偶像，为偶像建邱坛，违背神“不可随从别神”的命令。教训：智慧若不用在敬畏神上也会堕落；婚姻、财富、权力的试探能腐蚀最智慧的人；神的警告（两次显现）不可轻忽；领袖犯罪连累整个国家。", "s": ""}, {"type": "essay", "q": "简述王国分裂的经过，并分析其属灵原因。", "a": "经过：所罗门死后，罗波安到示剑即位；耶罗波安代表百姓求减重税，罗波安听少年人建议反加重担；十支派背叛，立耶罗波安为北国以色列王，罗波安只剩犹大便雅悯为南国犹大。属灵原因：所罗门拜偶像干犯神，神应许撕裂国度（留一支派给大卫家）；罗波安骄傲刚愎；耶罗波安为保王位设金牛犊，使北国陷入拜偶像的罪。", "s": ""}, {"type": "essay", "q": "以利亚在迦密山大有信心，在罗腾树下却求死，这给你什么启发？", "a": "启发：属灵高峰之后常有低谷，信心的伟人也有软弱时刻；疲惫、孤单、惧怕会压垮刚强的先知；神没有责备，而是用饼、水和睡眠恢复他，再用微小声音亲自显现；神留下七千未拜巴力者，提醒我们不凭眼见判断；软弱时当回到神面前得力，而非逃避。", "s": ""}]','','study','[{"title": "所罗门登基（1-2章）", "points": ["亚多尼雅自立为王", "拔示巴与拿单拥立所罗门", "大卫遗命：刚强作大丈夫", "遵行耶和华的律例", "除掉约押、亚多尼雅", "示每的结局", "所罗门的国位坚定"]}, {"title": "求智慧与建圣殿（3-9章）", "points": ["基遍梦中求智慧", "两妇争子显智慧", "建圣殿用七年", "约柜进入至圣所", "献殿的祷告", "耶和华荣光充满圣殿", "示巴女王来访"]}, {"title": "所罗门堕落（10-11章）", "points": ["金银财富极多", "妃嫔七百引诱拜偶像", "为摩洛基抹建邱坛", "神两次显现警告", "兴起哈达、利逊为敌", "亚希雅预言撕裂国度", "为大卫留一支派"]}, {"title": "王国分裂（12-16章）", "points": ["罗波安到示剑即位", "少年人的狂言", "十支派立耶罗波安", "耶罗波安铸金牛犊", "神人预言约西亚", "南北朝诸王行恶", "暗利建撒玛利亚为都"]}, {"title": "以利亚事工（17-22章）", "points": ["预言三年不降雨", "基立溪与撒勒法寡妇", "迦密山独战巴力先知", "罗腾树下求死", "何烈山微小声音", "膏以利沙接续", "拿伯葡萄园与亚哈之死"]}]','','42','旧约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791223564013','圣经导览','列王纪下','列王纪下记载以利亚乘旋风升天、以利沙承接双倍感动行了许多神迹；北国以色列终因拜偶像被亚述掳去，南国希西家王倚靠神大得胜、约西亚王复兴信仰，末了犹大被巴比伦掳掠、圣殿被毁。','[{"type": "verse", "q": "愿感动你的灵________地感动我。", "a": "加倍", "ref": "《列王纪下》2章9节", "s": "", "o": "列王纪下2章9节"}, {"type": "verse", "q": "不要惧怕！与我们同在的比与他们同在的________。", "a": "更多", "ref": "《列王纪下》6章16节", "s": "", "o": "列王纪下6章16节"}, {"type": "verse", "q": "我听见了你的祷告，看见了你的________，我必医治你。", "a": "眼泪", "ref": "《列王纪下》20章5节", "s": "", "o": "列王纪下20章5节"}, {"type": "verse", "q": "使天下万国都知道惟独你耶和华是________！", "a": "神", "ref": "《列王纪下》19章19节", "s": "", "o": "列王纪下19章19节"}, {"type": "verse", "q": "我父啊！我父啊！以色列的________马兵啊！", "a": "战车", "ref": "《列王纪下》2章12节", "s": "", "o": "列王纪下2章12节"}, {"type": "verse", "q": "在他以后也没有兴起一个王________他。", "a": "像", "ref": "《列王纪下》23章25节", "s": "", "o": "列王纪下23章25节"}, {"type": "verse", "q": "他的肉复原，好像________的肉，他就洁净了。", "a": "小孩子", "ref": "《列王纪下》5章14节", "s": "", "o": "列王纪下5章14节"}, {"type": "fill", "q": "以利亚在________河边被旋风接升天，以利沙亲眼看见。", "a": "约旦", "s": ""}, {"type": "fill", "q": "以利沙拾起以利亚的________打水，分开约旦河走过去。", "a": "外衣", "s": ""}, {"type": "fill", "q": "________妇人的儿子死了，以利沙使他复活。", "a": "书念", "s": ""}, {"type": "fill", "q": "亚兰元帅________在大麻风得洁净后，立志只拜耶和华。", "a": "乃缦", "s": ""}, {"type": "fill", "q": "基哈西贪爱________的礼物，撒谎索取，长了大麻风。", "a": "乃缦", "s": ""}, {"type": "fill", "q": "耶户在________杀了约兰和亚哈谢，灭绝亚哈家。", "a": "耶斯列", "s": ""}, {"type": "fill", "q": "________作犹大王时修复圣殿，发现了律法书。", "a": "约西亚", "s": ""}, {"type": "fill", "q": "希西家病得医治，神使亚哈斯的日晷上日影________十度。", "a": "后退", "s": ""}, {"type": "fill", "q": "巴比伦王________攻陷耶路撒冷，掳走犹大百姓。", "a": "尼布甲尼撒", "s": ""}, {"type": "fill", "q": "犹大末代君王________被剜眼，用铜链锁往巴比伦。", "a": "西底家", "s": ""}, {"type": "single", "q": "以利沙向以利亚求的是什么？", "o": ["长寿", "财富", "双倍的感动", "作先知"], "a": "双倍的感动", "s": ""}, {"type": "single", "q": "摩押王米沙每年进贡给以色列王的是什么？", "o": ["十万羊羔的毛", "一千他连得银子", "一百匹马", "五千石小麦"], "a": "十万羊羔的毛", "s": ""}, {"type": "single", "q": "北国以色列被亚述掳去时，在位的王是谁？", "o": ["耶罗波安", "亚哈", "何细亚", "耶户"], "a": "何细亚", "s": ""}, {"type": "single", "q": "希西家作犹大王共多少年？", "o": ["十九年", "二十五年", "二十九年", "三十五年"], "a": "二十九年", "s": ""}, {"type": "single", "q": "亚述王西拿基立派谁到耶路撒冷城下恐吓希西家？", "o": ["拉伯沙基", "他尔探", "拉撒勒", "尼布甲尼撒"], "a": "拉伯沙基", "s": ""}, {"type": "single", "q": "约西亚几岁登基作犹大王？", "o": ["八岁", "十二岁", "十八岁", "二十岁"], "a": "八岁", "s": ""}, {"type": "single", "q": "耶路撒冷陷落后，巴比伦立谁治理犹大剩下的余民？", "o": ["西底家", "基大利", "以实玛利", "约哈难"], "a": "基大利", "s": ""}, {"type": "multiple", "q": "以利沙所行的神迹包括以下哪些？", "o": ["使书念妇人之子复活", "治好乃缦的大麻风", "使斧头从水中漂起", "使有毒的汤变甜"], "a": "使书念妇人之子复活,治好乃缦的大麻风,使斧头从水中漂起,使有毒的汤变甜", "s": ""}, {"type": "multiple", "q": "希西家信靠耶和华的表现有哪些？", "o": ["废去邱坛、毁碎铜蛇", "亚述围城时向神祷告", "病危时痛哭祷告得医治", "与巴比伦结盟抗亚述"], "a": "废去邱坛、毁碎铜蛇,亚述围城时向神祷告,病危时痛哭祷告得医治", "s": ""}, {"type": "multiple", "q": "约西亚宗教复兴的内容包括以下哪些？", "o": ["修复圣殿", "宣读发现的律法书", "守逾越节", "除掉偶像邱坛"], "a": "修复圣殿,宣读发现的律法书,守逾越节,除掉偶像邱坛", "s": ""}, {"type": "multiple", "q": "犹大国被掳到巴比伦的原因有哪些？", "o": ["玛拿西流无辜人的血", "长期拜偶像不悔改", "不听先知的警告", "西底家背叛巴比伦"], "a": "玛拿西流无辜人的血,长期拜偶像不悔改,不听先知的警告,西底家背叛巴比伦", "s": ""}, {"type": "judge", "q": "以利亚升天时，有火车火马将以利亚和以利沙隔开。", "a": "对", "s": ""}, {"type": "judge", "q": "以利沙承接双倍的感动，所行神迹比以利亚更多。", "a": "对", "s": ""}, {"type": "judge", "q": "乃缦起初嫌约旦河水不如大马士革河水，发怒要回去。", "a": "对", "s": ""}, {"type": "judge", "q": "耶户彻底除掉了北国一切拜偶像的事，包括金牛犊。", "a": "错", "s": ""}, {"type": "judge", "q": "希西家祷告后，神应许加给他十五年的寿数。", "a": "对", "s": ""}, {"type": "judge", "q": "约西亚死于米吉多与埃及王尼哥的交战。", "a": "对", "s": ""}, {"type": "judge", "q": "西底家背叛巴比伦王，导致耶路撒冷被围困陷落。", "a": "对", "s": ""}, {"type": "essay", "q": "以利沙承接双倍感动的经过是怎样的？这给你什么启发？", "a": "经过：以利亚被接升天之前，以利沙紧紧跟随，从吉甲到伯特利、耶利哥、约旦河，不肯离开；以利亚问他要什么，他求“愿感动你的灵加倍地感动我”；以利亚说所求难得，但若看见他被接去就必得着；忽有火车火马显现，以利亚乘旋风升天，以利沙得着外衣，分开约旦河。启发：属灵的承接需要专心跟随、渴慕追求；双倍事奉伴随双倍代价；神的灵是能力源头。", "s": ""}, {"type": "essay", "q": "希西家面对亚述大军围城时，是如何倚靠神得胜的？", "a": "亚述王西拿基立派拉伯沙基用亚兰语恐吓，希西家撕裂衣服、披上麻布进圣殿祷告，并求先知以赛亚代求；他将亚述王的书信展开在耶和华面前祷告：“耶和华我们的神啊，求你救我们脱离亚述王的手”；当夜耶和华的使者杀了十八万五千亚述兵，西拿基立败逃回国。显明倚靠神的必不羞愧。", "s": ""}, {"type": "essay", "q": "从北国以色列和南国犹大先后被掳，看神的公义与怜悯。", "a": "公义：两国长期拜偶像、流无辜血、不听先知警告，神多次忍耐后终施行审判——北国被亚述掳去，南国被巴比伦掳掠，圣殿被毁，显明神是公义审判的主。怜悯：被掳前差遣众多先知劝戒；为大卫的缘故屡次延迟审判；被掳后仍应许归回，保留余种；约雅斤在巴比伦得优待，显明神的约不废去。", "s": ""}]','','study','[{"title": "以利亚被提（1-2章）", "points": ["亚哈谢求问巴力西卜", "以利亚预言亚哈谢必死", "火烧灭五十夫长", "约旦河水分开", "火车火马旋风升天", "以利沙求双倍感动", "拾外衣分开约旦河"]}, {"title": "以利沙的神迹（3-8章）", "points": ["书念妇人之子复活", "二十饼饱一百人", "乃缦大麻风得洁净", "基哈西贪心长大麻风", "失落的斧头漂起", "毒汤变甜可吃", "祷告开仆人眼目"]}, {"title": "北国衰亡（9-17章）", "points": ["耶户受膏为王", "灭绝亚哈全家", "耶洗别被抛下楼", "北国仍拜金牛犊", "撒玛利亚被围三年", "百姓被掳到亚述", "外邦人迁入撒玛利亚"]}, {"title": "希西家改革（18-20章）", "points": ["废邱坛毁铜蛇尼忽探", "亚述大军围耶路撒冷", "拉伯沙基的恐吓", "展开书信祷告", "一夜杀十八万五千", "病危祷告延寿十五年", "日影后退十度"]}, {"title": "约西亚与被掳（21-25章）", "points": ["玛拿西行恶多年", "约西亚修殿得律法书", "撕裂衣服立约", "除偶像守逾越节", "战死米吉多", "西底家背叛巴比伦", "圣殿被毁百姓被掳"]}]','','43','旧约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791223564487','圣经导览','历代志上','历代志上从亚当的家谱开始追溯以色列人的历史，重点记载大卫迎约柜入城、预备建造圣殿的材料与蓝图、设立利未人的事奉体系，强调圣殿敬拜与大卫之约，坚固被掳归回余民的信心与盼望。','[{"type": "verse", "q": "应当________耶和华，因他本为善，他的慈爱永远长存！", "a": "称谢", "ref": "《历代志上》16章34节", "s": "", "o": "历代志上16章34节"}, {"type": "verse", "q": "耶和华啊，尊大、能力、荣耀、强胜、________都是你的。", "a": "威严", "ref": "《历代志上》29章11节", "s": "", "o": "历代志上29章11节"}, {"type": "verse", "q": "我算什么，我的民算什么，竟能如此________奉献？", "a": "乐意", "ref": "《历代志上》29章14节", "s": "", "o": "历代志上29章14节"}, {"type": "verse", "q": "当以圣洁的________敬拜耶和华。", "a": "妆饰", "ref": "《历代志上》16章29节", "s": "", "o": "历代志上16章29节"}, {"type": "verse", "q": "我儿所罗门哪，你当________耶和华你父的神，诚心乐意地侍奉他。", "a": "认识", "ref": "《历代志上》28章9节", "s": "", "o": "历代志上28章9节"}, {"type": "verse", "q": "我却要将他永远坚立在我家里和我国里，他的国位也必坚定，直到________。", "a": "永远", "ref": "《历代志上》17章14节", "s": "", "o": "历代志上17章14节"}, {"type": "verse", "q": "现在你们应当________心意，寻求耶和华你们的神。", "a": "立定", "ref": "《历代志上》22章19节", "s": "", "o": "历代志上22章19节"}, {"type": "fill", "q": "历代志上1至9章的主要内容是________，从亚当记到以色列众支派。", "a": "家谱", "s": ""}, {"type": "fill", "q": "扫罗和他儿子们死在________山上。", "a": "基利波", "s": ""}, {"type": "fill", "q": "大卫攻取________保障，定为大卫城，建都于此。", "a": "锡安", "s": ""}, {"type": "fill", "q": "乌撒被击杀后，大卫惧怕，把约柜运到迦特人________家中。", "a": "俄别以东", "s": ""}, {"type": "fill", "q": "大卫吩咐________用杠抬约柜，因为神拣选他们搬运圣物。", "a": "利未人", "s": ""}, {"type": "fill", "q": "神不许大卫建造圣殿，因为他是________，流了多人的血。", "a": "战士", "s": ""}, {"type": "fill", "q": "大卫为建殿预备了________万他连得金子，百万他连得银子。", "a": "十", "s": ""}, {"type": "fill", "q": "大卫设立________、希幔、耶杜顿为歌唱的领袖。", "a": "亚萨", "s": ""}, {"type": "fill", "q": "大卫把建殿的________（蓝图）交给儿子所罗门。", "a": "样式", "s": ""}, {"type": "fill", "q": "大卫年老时，立________接续他作以色列王。", "a": "所罗门", "s": ""}, {"type": "single", "q": "历代志上共有多少章？", "o": ["二十四章", "二十九章", "三十四章", "三十九章"], "a": "二十九章", "s": ""}, {"type": "single", "q": "传统上认为历代志的作者是谁？", "o": ["撒母耳", "以斯拉", "尼希米", "耶利米"], "a": "以斯拉", "s": ""}, {"type": "single", "q": "大卫数点以色列人惹神发怒，是谁激动大卫的？", "o": ["扫罗", "撒但", "约押", "亚比筛"], "a": "撒但", "s": ""}, {"type": "single", "q": "大卫买阿珥楠的禾场作祭坛，付了多少舍客勒金子？", "o": ["五十舍客勒", "四百舍客勒", "六百舍客勒", "一千舍客勒"], "a": "六百舍客勒", "s": ""}, {"type": "single", "q": "大卫设立的歌唱领袖不包括以下哪一位？", "o": ["亚萨", "希幔", "耶杜顿", "拿单"], "a": "拿单", "s": ""}, {"type": "single", "q": "所罗门在何处献祭千只燔祭，神夜间向他显现？", "o": ["耶路撒冷", "基遍", "希伯仑", "示罗"], "a": "基遍", "s": ""}, {"type": "single", "q": "大卫死时享寿多少岁？", "o": ["六十岁", "七十岁", "八十岁", "九十岁"], "a": "七十岁", "s": ""}, {"type": "multiple", "q": "大卫为建造圣殿所做的预备包括以下哪些？", "o": ["预备金银铜铁", "预备香柏木", "得圣殿建造样式", "亲自奠定根基"], "a": "预备金银铜铁,预备香柏木,得圣殿建造样式", "s": ""}, {"type": "multiple", "q": "利未人的职责包括以下哪些？", "o": ["抬约柜", "歌唱赞美", "看守圣殿的门", "治理百姓"], "a": "抬约柜,歌唱赞美,看守圣殿的门", "s": ""}, {"type": "multiple", "q": "大卫迎约柜入耶路撒冷时的安排有哪些？", "o": ["利未人用杠抬约柜", "亚萨等歌唱赞美", "弹琴鼓瑟跳舞", "大卫穿细麻布以弗得"], "a": "利未人用杠抬约柜,亚萨等歌唱赞美,弹琴鼓瑟跳舞,大卫穿细麻布以弗得", "s": ""}, {"type": "multiple", "q": "以下哪些是大卫的勇士（三勇士）？", "o": ["雅朔班", "以利亚撒", "沙玛", "约押"], "a": "雅朔班,以利亚撒,沙玛", "s": ""}, {"type": "judge", "q": "历代志上与撒母耳记下记载同一时期历史，但神学角度不同。", "a": "对", "s": ""}, {"type": "judge", "q": "神不许大卫建殿，因为他是战士、流了多人的血。", "a": "对", "s": ""}, {"type": "judge", "q": "约柜在俄别以东家中三个月，神赐福他的全家。", "a": "对", "s": ""}, {"type": "judge", "q": "大卫数点百姓后神降瘟疫，以色列死了七万人。", "a": "对", "s": ""}, {"type": "judge", "q": "大卫在希伯仑作王七年，在耶路撒冷作王三十三年。", "a": "对", "s": ""}, {"type": "judge", "q": "大卫在临终前把圣殿的样式交给了所罗门。", "a": "对", "s": ""}, {"type": "judge", "q": "大卫临终嘱咐所罗门，主要是为约押报仇的事。", "a": "错", "s": ""}, {"type": "essay", "q": "历代志上与撒母耳记有何异同？历代志的写作目的可能是什么？", "a": "相同：都记大卫作王的历史，许多事件重叠。不同：撒母耳记按历史顺序记大卫的兴衰成败（包括犯罪、家变）；历代志上省略大卫的失败（拔示巴、押沙龙叛乱），突出约柜、圣殿预备、利未人事奉，充满家谱与敬拜。目的：被掳归回后，坚固余民的身份认同（家谱），重建以圣殿敬拜为中心的生活，持守大卫之约的盼望。", "s": ""}, {"type": "essay", "q": "大卫为建造圣殿做了哪些预备？给你什么启发？", "a": "预备：积攒十万他连得金子、百万他连得银子、铜铁无数；预备香柏木；得圣殿样式（蓝图）；组织利未人、祭司、歌唱者、守门者的班次；公开奉献、嘱咐所罗门“刚强壮胆去行”。启发：神的事工需要忠心预备；自己不能做的（建殿），可为下一代铺路；甘心乐意的奉献蒙神喜悦；领袖的异象要传承下去。", "s": ""}, {"type": "essay", "q": "从大卫晚年的奉献（代上29章），谈谈何为甘心乐意的奉献。", "a": "大卫说“我为我神的殿已经尽力”，奉献三千他连得俄斐金子、七千他连得精银；众首领也乐意奉献；大卫祷告：“我算什么，我的民算什么，竟能如此乐意奉献？因为万物都从你而来，我们把从你而得的献给你。”甘心乐意的奉献是：认识一切属神所有、感恩回应的行动，不勉强、不计算、欢喜快乐，是敬拜的一部分。", "s": ""}]','','study','[{"title": "家谱（1-9章）", "points": ["从亚当到亚伯拉罕", "以色列十二支派家谱", "犹大支派与大卫家谱", "便雅悯家谱（扫罗家）", "利未支派家谱", "祭司与守门者", "被掳归回的余民名单"]}, {"title": "大卫作王（10-12章）", "points": ["扫罗死于基利波山", "大卫攻取锡安建都", "勇士来归附大卫", "三勇士的英勇事迹", "便雅悯人来投奔", "迦得人归附", "以色列众人立大卫为王"]}, {"title": "迎约柜入城（13-16章）", "points": ["第一次运约柜乌撒之死", "约柜在俄别以东家蒙福", "利未人用杠抬约柜", "大卫跳舞赞美", "亚萨的称谢诗", "设立歌唱者赞美", "为约柜支搭帐幕"]}, {"title": "大卫之约与预备建殿（17-22章）", "points": ["拿单传达大卫之约", "大卫感恩的祷告", "征战得胜得财宝", "预备金银铜铁木材", "得圣殿建造样式", "嘱咐所罗门建殿", "招聚首领公开奉献"]}, {"title": "圣殿事奉体制（23-29章）", "points": ["利未人数点分班次", "祭司亚伦子孙班次", "歌唱者亚萨希幔班次", "守门者与府库职分", "大卫的奉献祷告", "所罗门登基作王", "大卫享寿七十而终"]}]','','44','旧约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-179122352313345','圣经导览','历代志下','历代志下记载所罗门建殿与献殿祷告，王国分裂后犹大诸王兴衰：约沙法信靠神得胜、希西家洁净圣殿复兴、玛拿西被掳悔改、约西亚发现律法书改革，终因悖逆被掳巴比伦，见证顺服蒙福、悖逆受罚。','[{"type": "verse", "q": "【经文填空】这称为我名下的子民，若是自卑、祷告，寻求我的面，转离他们的恶行，我必从天上垂听，赦免他们的罪，________。", "a": "医治他们的地", "ref": "《历代志下》7章14节", "s": "", "o": "历代志下7章14节"}, {"type": "verse", "q": "【经文填空】现在我已选择这殿，分别为圣，使我的名永在其中，我的眼、________也必常在那里。", "a": "我的心", "ref": "《历代志下》7章16节", "s": "", "o": "历代志下7章16节"}, {"type": "verse", "q": "【经文填空】耶和华的眼目遍察全地，要显大能帮助向他________的人。", "a": "心存诚实", "ref": "《历代志下》16章9节", "s": "", "o": "历代志下16章9节"}, {"type": "verse", "q": "【经文填空】不要因这大军恐惧惊惶；因为胜败不在乎你们，________。", "a": "乃在乎神", "ref": "《历代志下》20章15节", "s": "", "o": "历代志下20章15节"}, {"type": "verse", "q": "【经文填空】他既强盛，就心高气傲，以致行事邪僻，干犯耶和华他的神，进耶和华的殿，要在________上烧香。", "a": "香坛", "ref": "《历代志下》26章16节", "s": "", "o": "历代志下26章16节"}, {"type": "verse", "q": "【经文填空】你们若转向耶和华，你们的弟兄和儿女必在掳掠他们的人面前蒙怜恤，得以归回这地，因为耶和华你们的神有________、施怜悯。", "a": "恩典", "ref": "《历代志下》30章9节", "s": "", "o": "历代志下30章9节"}, {"type": "verse", "q": "【经文填空】你们中间凡作他子民的，可以上去，愿耶和华他的神________。", "a": "与他同在", "ref": "《历代志下》36章23节", "s": "", "o": "历代志下36章23节"}, {"type": "fill", "q": "所罗门在________山建造圣殿（亚劳拿的禾场）。", "a": "摩利亚", "s": ""}, {"type": "fill", "q": "________女王听见所罗门的名声，前来用难解的话试问他。", "a": "示巴", "s": ""}, {"type": "fill", "q": "罗波安不听老年人的谏言，听从与他一同长大的________之言。", "a": "少年人", "s": ""}, {"type": "fill", "q": "亚撒呼求耶和华，击败________王谢拉的百万大军。", "a": "古实", "s": ""}, {"type": "fill", "q": "约沙法在犹大设立________，吩咐他们办事当谨慎。", "a": "审判官", "s": ""}, {"type": "fill", "q": "希西家除掉邱坛，打碎柱像，砍断木偶，击碎摩西所造的________。", "a": "铜蛇", "s": ""}, {"type": "fill", "q": "玛拿西被亚述王用铙钩钩住，被掳到________，后在急难中恳求神。", "a": "巴比伦", "s": ""}, {"type": "fill", "q": "约西亚年间，大祭司希勒家在圣殿发现了________。", "a": "律法书", "s": ""}, {"type": "fill", "q": "乌西雅在香坛烧香时，额上忽然发出________，至死被隔离。", "a": "大麻风", "s": ""}, {"type": "fill", "q": "犹大被掳________年，使地享受安息，应验耶利米的话。", "a": "七十", "s": ""}, {"type": "single", "q": "谁为所罗门建殿预备了材料？", "o": ["大卫", "扫罗", "约拿单", "押沙龙"], "a": "大卫", "s": ""}, {"type": "single", "q": "所罗门献殿祷告时站在哪里？", "o": ["铜台", "金坛", "圣殿门口", "橄榄山"], "a": "铜台", "s": ""}, {"type": "single", "q": "北国以色列第一位王是谁？", "o": ["耶罗波安", "罗波安", "亚哈", "耶户"], "a": "耶罗波安", "s": ""}, {"type": "single", "q": "亚撒作王年间，太平了多少年？", "o": ["十年", "二十年", "三十年", "四十年"], "a": "十年", "s": ""}, {"type": "single", "q": "约沙法面对摩押、亚扪联军，利未人雅哈悉预言胜败在乎谁？", "o": ["神", "约沙法", "犹大军队", "埃及援军"], "a": "神", "s": ""}, {"type": "single", "q": "西拿基立围困耶路撒冷时，希西家做了什么？", "o": ["向神祷告", "纳贡求和", "弃城逃跑", "与亚述结盟"], "a": "向神祷告", "s": ""}, {"type": "single", "q": "约西亚几岁登基作王？", "o": ["八岁", "十二岁", "十八岁", "二十岁"], "a": "八岁", "s": ""}, {"type": "multiple", "q": "所罗门向神求了什么？", "o": ["智慧", "聪明", "资财", "尊荣"], "a": "智慧,聪明", "s": ""}, {"type": "multiple", "q": "约沙法在犹大的改革包括哪些？", "o": ["设立审判官", "差利未人教导律法", "与北国结盟拜偶像", "除掉邱坛"], "a": "设立审判官,差利未人教导律法", "s": ""}, {"type": "multiple", "q": "希西家的宗教改革包括哪些？", "o": ["洁净圣殿", "除偶像", "守逾越节", "重修圣殿"], "a": "洁净圣殿,除偶像,守逾越节", "s": ""}, {"type": "multiple", "q": "玛拿西的恶行包括哪些？", "o": ["拜天上万象", "使儿女经火", "行邪术", "塞耳不听先知"], "a": "拜天上万象,使儿女经火,行邪术", "s": ""}, {"type": "judge", "q": "所罗门建造圣殿用了七年时间。", "a": "对", "s": ""}, {"type": "judge", "q": "王国分裂后，南国犹大共有十九位王。", "a": "错", "s": ""}, {"type": "judge", "q": "亚撒晚年患脚病，仍不求耶和华，只求医生。", "a": "对", "s": ""}, {"type": "judge", "q": "约沙法与以色列王亚哈谢交好造船，神借以利以谢责备他。", "a": "对", "s": ""}, {"type": "judge", "q": "希西家因心里骄傲，神曾向他和犹大发怒。", "a": "对", "s": ""}, {"type": "judge", "q": "玛拿西一生作恶，至死没有悔改。", "a": "错", "s": ""}, {"type": "judge", "q": "约西亚在米吉多与埃及王法老尼哥交战，中箭身亡。", "a": "对", "s": ""}, {"type": "essay", "q": "所罗门献殿祷告的核心内容是什么？对今日教会祷告有何启发？", "a": "核心是求神垂听赦免：百姓犯罪向此殿祷告，神在天上垂听赦免；七项祈求涵盖争战、干旱、饥荒、瘟疫等。启发：祷告当以神的名为中心，认罪悔改是蒙垂听的前提，教会是万民祷告的殿。", "s": ""}, {"type": "essay", "q": "从乌西雅王的结局，我们学到什么功课？", "a": "乌西雅行正道、神帮助他强盛，却心高气傲，擅闯圣殿烧香，长大麻风至死。功课：成功易使人骄傲；神的圣洁不可轻慢；职分有界限，不可越分；谦卑到底才能善终。", "s": ""}, {"type": "essay", "q": "历代志下评价诸王的标准是什么？", "a": "标准是是否行耶和华眼中看为正的事：是否寻求神、依靠神，除偶像、守律法；悖逆拜偶像的王国势衰微，寻求神的王蒙福。这提醒我们，神看重的是人心的归向，而非外在成就。", "s": ""}]','','study','[{"title": "所罗门建殿（1-9章）", "points": ["基遍献祭，神夜间显现：求什么都必赐你", "所罗门求智慧聪明治理百姓，神赐他资财丰富尊荣", "摩利亚山建殿七年，户兰巧匠督工", "献殿祷告：求神垂听赦免，七项祈求", "神应许：自卑祷告寻求我面，必医治这地（7:14）", "示巴女王来访，见所罗门智慧大受震惊", "所罗门晚年娶外邦女子，心偏离神"]}, {"title": "王国分裂（10-12章）", "points": ["罗波安听少年人之言，加重百姓轭", "十支派背叛，耶罗波安作以色列王", "神禁止罗波安与以色列争战：这事出于我", "耶罗波安铸金牛犊，拜偶像", "埃及王示撒攻耶路撒冷，夺圣殿宝物", "罗波安自卑，神怒气转消"]}, {"title": "犹大诸王的兴衰（13-27章）", "points": ["亚撒除偶像，依靠神击败古实百万大军", "亚撒晚年求医生不求神，脚患病而死", "约沙法设立审判官，差利未人教导律法", "摩押亚扪联军来攻：胜败不在乎你们乃在乎神", "约沙法与亚哈谢交好，船只破坏", "乌西雅心高气傲烧香，长大麻风至死", "约坦行正道，亚哈斯拜巴力偶像"]}, {"title": "希西家与约西亚的复兴（28-35章）", "points": ["希西家洁净圣殿，除掉邱坛偶像", "守逾越节：邀请南北众民归向耶和华", "亚述王西拿基立围城，希西家祷告", "耶和华使者一夜杀亚述十八万五千人", "约西亚八岁登基，发现律法书大改革", "约西亚守逾越节，自摩西以来未有之盛", "约西亚在米吉多与法老尼哥交战阵亡"]}, {"title": "被掳与归回的应许（36章）", "points": ["末代诸王行恶：约哈斯、约雅敬、约雅斤、西底家", "先知耶利米屡次劝戒，百姓藐视", "巴比伦王尼布甲尼撒攻陷耶路撒冷", "圣殿被焚，百姓被掳，应验安息年之数", "被掳七十年，土地享安息", "波斯王古列下诏，准百姓归回建殿"]}]','','45','旧约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-179122352361046','圣经导览','以斯拉记','以斯拉记记载波斯王古列下诏，百姓归回重建圣殿；工程虽遭拦阻停顿十六年，靠先知哈该、撒迦利亚的鼓励得以完成。以斯拉归回考究遵行教导律法，带领百姓为娶外邦女子认罪悔改，重建属灵生活。','[{"type": "verse", "q": "【经文填空】在你们中间凡作他子民的，可以上犹大的耶路撒冷，在耶路撒冷重建耶和华以色列神的殿，________。", "a": "愿神与这人同在", "ref": "《以斯拉记》1章3节", "s": "", "o": "以斯拉记1章3节"}, {"type": "verse", "q": "【经文填空】他们彼此唱和，赞美称谢耶和华说：他本为善，他向以色列人________。", "a": "永发慈爱", "ref": "《以斯拉记》3章11节", "s": "", "o": "以斯拉记3章11节"}, {"type": "verse", "q": "【经文填空】以斯拉定志考究遵行耶和华的律法，又将________教训以色列人。", "a": "律例典章", "ref": "《以斯拉记》7章10节", "s": "", "o": "以斯拉记7章10节"}, {"type": "verse", "q": "【经文填空】我曾对王说：我们神施恩的手必帮助一切________的人。", "a": "寻求他", "ref": "《以斯拉记》8章22节", "s": "", "o": "以斯拉记8章22节"}, {"type": "verse", "q": "【经文填空】所以我们禁食祈求我们的神，他就________了我们。", "a": "应允", "ref": "《以斯拉记》8章23节", "s": "", "o": "以斯拉记8章23节"}, {"type": "verse", "q": "【经文填空】我的神啊，我抱愧蒙羞，不敢向我神仰面；因为我们的罪孽________，我们的罪恶滔天。", "a": "灭顶", "ref": "《以斯拉记》9章6节", "s": "", "o": "以斯拉记9章6节"}, {"type": "verse", "q": "【经文填空】当向耶和华你们列祖的神认罪，遵行他的旨意，离绝这些国的民和________。", "a": "外邦的女子", "ref": "《以斯拉记》10章11节", "s": "", "o": "以斯拉记10章11节"}, {"type": "fill", "q": "下诏准许犹大人归回重建圣殿的是波斯王________。", "a": "古列", "s": ""}, {"type": "fill", "q": "带领百姓第一次归回的是________（设巴萨）。", "a": "所罗巴伯", "s": ""}, {"type": "fill", "q": "归回的以色列人共有四万二千________六十名。", "a": "三百", "s": ""}, {"type": "fill", "q": "百姓先筑________献燔祭，然后才立殿的根基。", "a": "坛", "s": ""}, {"type": "fill", "q": "拦阻建殿、贿赂谋士的是________人。", "a": "撒玛利亚", "s": ""}, {"type": "fill", "q": "先知________和________奉神名劝勉百姓复工建殿。", "a": "哈该|撒迦利亚", "s": ""}, {"type": "fill", "q": "圣殿在大流士王第________年完工。", "a": "六", "s": ""}, {"type": "fill", "q": "以斯拉是________，精通耶和华以色列神所赐摩西的律法书。", "a": "文士", "s": ""}, {"type": "fill", "q": "以斯拉在________王第七年上耶路撒冷。", "a": "亚达薛西", "s": ""}, {"type": "fill", "q": "以斯拉为百姓娶________女子之事忧伤认罪。", "a": "外邦", "s": ""}, {"type": "single", "q": "古列下诏准犹大人归回，记载在以斯拉记第几章？", "o": ["第一章", "第三章", "第五章", "第七章"], "a": "第一章", "s": ""}, {"type": "single", "q": "圣殿的根基立定是在归回后的第几年？", "o": ["第二年二月", "第一年七月", "第三年三月", "第五年九月"], "a": "第二年二月", "s": ""}, {"type": "single", "q": "建殿工程因拦阻停工了大约多少年？", "o": ["十六年", "十年", "七年", "三年"], "a": "十六年", "s": ""}, {"type": "single", "q": "河西总督达乃上本查问建殿事，寻得哪位王的诏书存档？", "o": ["古列", "大流士", "亚达薛西", "亚哈随鲁"], "a": "古列", "s": ""}, {"type": "single", "q": "以斯拉不敢求王派兵护送，原因是什么？", "o": ["曾对王说神施恩的手帮助寻求他的人", "没有钱财", "相信仇敌不敢来", "王不肯派兵"], "a": "曾对王说神施恩的手帮助寻求他的人", "s": ""}, {"type": "single", "q": "以斯拉听见娶外邦女子之事，有何举动？", "o": ["撕裂衣服拔头发胡须", "立刻休妻", "上本奏告王", "召集百姓开会"], "a": "撕裂衣服拔头发胡须", "s": ""}, {"type": "single", "q": "查办娶外邦女子之事用了多长时间？", "o": ["三个月", "一个月", "六个月", "一年"], "a": "三个月", "s": ""}, {"type": "multiple", "q": "古列诏书的内容包括哪些？", "o": ["准犹大人归回", "为神建殿", "归还圣殿器皿", "免除一切赋税"], "a": "准犹大人归回,为神建殿,归还圣殿器皿", "s": ""}, {"type": "multiple", "q": "仇敌拦阻建殿的方式有哪些？", "o": ["贿赂谋士", "上本控告", "武力攻打", "散布谣言"], "a": "贿赂谋士,上本控告", "s": ""}, {"type": "multiple", "q": "以斯拉从巴比伦带回了什么？", "o": ["金银", "圣殿器皿", "利未人", "马兵护送"], "a": "金银,圣殿器皿,利未人", "s": ""}, {"type": "multiple", "q": "以斯拉认罪祷告中提到哪些内容？", "o": ["罪孽灭顶", "神仍施恩留余种", "不可再娶外邦女子", "求神降火"], "a": "罪孽灭顶,神仍施恩留余种,不可再娶外邦女子", "s": ""}, {"type": "judge", "q": "耶和华激动波斯王古列的心，使他下诏通告全国。", "a": "对", "s": ""}, {"type": "judge", "q": "第一次归回的以色列人共有四万二千三百六十名。", "a": "对", "s": ""}, {"type": "judge", "q": "圣殿在古列王在位时就建成了。", "a": "错", "s": ""}, {"type": "judge", "q": "以斯拉是亚伦的后裔，精通摩西的律法。", "a": "对", "s": ""}, {"type": "judge", "q": "以斯拉独自一人从巴比伦上耶路撒冷。", "a": "错", "s": ""}, {"type": "judge", "q": "归回的百姓在七月守了住棚节。", "a": "对", "s": ""}, {"type": "judge", "q": "以斯拉记和尼希米记在希伯来圣经中原为一卷。", "a": "对", "s": ""}, {"type": "essay", "q": "以斯拉“定志考究遵行，又将律例典章教训以色列人”，对今日信徒有何启发？", "a": "启发有三：先考究（认真研读圣经）、再遵行（活出真理）、后教训（传授他人）。今日信徒也当立志作神话语的学生和教师，知行合一，才能带出属灵的复兴。", "s": ""}, {"type": "essay", "q": "从建殿屡遭拦阻看，事奉神会遇到怎样的争战？当如何面对？", "a": "争战来自仇敌的贿赂、控告、政治压力，事奉常遇拦阻。面对之道：像所罗巴伯拒绝妥协，像先知传神话语鼓励，像百姓靠神刚强复工；认定工程属神，神必为自己的工作负责到底。", "s": ""}, {"type": "essay", "q": "以斯拉处理娶外邦女子之事的原则是什么？", "a": "原则：圣洁分别为圣，不可与不信者同负一轭。处理方式：先自己认罪撕裂衣服，再带领百姓立约悔改，彻底离绝。今日应用：婚姻与信仰生活当以神为首，犯罪后当彻底悔改，不留地步。", "s": ""}]','','study','[{"title": "古列诏书与归回（1-2章）", "points": ["耶和华激动波斯王古列的心，下诏准犹大人归回", "诏书：为耶和华建殿，归还圣殿器皿", "应验耶利米七十年的预言", "设巴萨（所罗巴伯）带领首次归回", "归回人数四万二千三百六十", "祭司、利未人、尼提宁各按家谱归回"]}, {"title": "立坛与建殿根基（3章）", "points": ["七月，百姓如同一人聚集耶路撒冷", "先筑坛献燔祭，守住棚节", "次年二月，立耶和华殿根基", "祭司吹号、利未人敲钹赞美", "称谢：他本为善，向以色列人永发慈爱", "年老者见旧殿根基而哭号，众民大声欢呼"]}, {"title": "拦阻与停工（4章）", "points": ["撒玛利亚人求同建殿，所罗巴伯拒绝", "当地民贿赂谋士，扰乱建殿", "亚达薛西王时上本控告耶路撒冷", "王降旨停工，直到大流士第二年", "仇敌的拦阻：从贿赂到政治控告", "停工约十六年，百姓只顾自己房屋"]}, {"title": "复工与圣殿完工（5-6章）", "points": ["先知哈该、撒迦利亚奉神名劝勉", "所罗巴伯、耶书亚奋起重建", "河西总督达乃上本大流士查问", "寻得古列诏书存档，证实建殿合法", "大流士降旨：拨国库银子供给，不可拦阻", "大流士六年亚达月初三，殿工完成", "行奉献礼，守逾越节，大大欢喜"]}, {"title": "以斯拉归回与认罪（7-10章）", "points": ["以斯拉是文士，精通摩西律法", "定志考究、遵行、教训律法（7:10）", "亚达薛西七年，率众上耶路撒冷", "不敢求王派兵：神施恩的手帮助寻求他的人", "禁食祈求，神应允，平安到达", "娶外邦女子之罪：首领先犯罪", "以斯拉拔发撕衣，俯伏祷告认罪"]}]','','46','旧约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-179122352442347','圣经导览','尼希米记','尼希米记记载尼希米听见耶路撒冷荒凉便禁食祷告，蒙波斯王允准归回，率领百姓五十二天建成城墙。面对参巴拉等人反对，一手做工一手拿兵器；以斯拉宣读律法，百姓禁食认罪郑重立约，信仰大复兴。','[{"type": "verse", "q": "【经文填空】我听见这话，就坐下哭泣，悲哀几日，在________面前禁食祈祷。", "a": "天上的神", "ref": "《尼希米记》1章4节", "s": "", "o": "尼希米记1章4节"}, {"type": "verse", "q": "【经文填空】我告诉他们我神施恩的手怎样帮助我，并王对我所说的话。他们就说：我们________！于是他们奋勇做这善工。", "a": "起来建造吧", "ref": "《尼希米记》2章18节", "s": "", "o": "尼希米记2章18节"}, {"type": "verse", "q": "【经文填空】这样，我们修造城墙，城墙就都连络，高至一半，因为百姓________。", "a": "专心做工", "ref": "《尼希米记》4章6节", "s": "", "o": "尼希米记4章6节"}, {"type": "verse", "q": "【经文填空】不要怕他们！当记念主是大而可畏的。你们要为弟兄、儿女、妻子、________争战。", "a": "家产", "ref": "《尼希米记》4章14节", "s": "", "o": "尼希米记4章14节"}, {"type": "verse", "q": "【经文填空】你们不要忧愁，因靠耶和华而得的喜乐是你们的________。", "a": "力量", "ref": "《尼希米记》8章10节", "s": "", "o": "尼希米记8章10节"}, {"type": "verse", "q": "【经文填空】你，惟独你是耶和华！你造了天和天上的天，并天上的万象，地和地上的万物，海和海中所有的；这一切都是________的。", "a": "你所保存", "ref": "《尼希米记》9章6节", "s": "", "o": "尼希米记9章6节"}, {"type": "verse", "q": "【经文填空】我的神啊，求你________我，施恩与我。", "a": "记念", "ref": "《尼希米记》13章31节", "s": "", "o": "尼希米记13章22节"}, {"type": "fill", "q": "尼希米是波斯王________的酒政。", "a": "亚达薛西", "s": ""}, {"type": "fill", "q": "向尼希米报告耶路撒冷光景的是他的兄弟________。", "a": "哈拿尼", "s": ""}, {"type": "fill", "q": "尼希米听见消息悲哀禁食，是在________月。", "a": "基斯流", "s": ""}, {"type": "fill", "q": "耶路撒冷城墙共修造了________天完工。", "a": "五十二", "s": ""}, {"type": "fill", "q": "城墙在________月二十五日修完。", "a": "以禄", "s": ""}, {"type": "fill", "q": "讥笑建城墙的主要有________、多比雅和阿拉伯人基善。", "a": "参巴拉", "s": ""}, {"type": "fill", "q": "假先知________受贿恐吓，要尼希米躲入圣殿。", "a": "示玛雅", "s": ""}, {"type": "fill", "q": "以斯拉在七月初一日，于________门前的宽阔处宣读律法。", "a": "水", "s": ""}, {"type": "fill", "q": "百姓在七月________日禁食认罪，披麻蒙灰。", "a": "二十四", "s": ""}, {"type": "fill", "q": "尼希米发现________占据了圣殿的库房，将其家具抛出。", "a": "多比雅", "s": ""}, {"type": "single", "q": "尼希米在王面前愁容满面，王在几月问他缘故？", "o": ["尼散月", "基斯流月", "以禄月", "亚达月"], "a": "尼散月", "s": ""}, {"type": "single", "q": "尼希米夜间查看城墙，带了多少人同去？", "o": ["几个人", "全城百姓", "一百人", "独自一人"], "a": "几个人", "s": ""}, {"type": "single", "q": "修造城墙时，百姓如何防备仇敌？", "o": ["一半做工一半拿兵器", "昼夜不停赶工", "请波斯军队护卫", "先谈判后开工"], "a": "一半做工一半拿兵器", "s": ""}, {"type": "single", "q": "以斯拉宣读律法书，从什么时候到什么时候？", "o": ["清早到晌午", "整整一日", "三日三夜", "七日"], "a": "清早到晌午", "s": ""}, {"type": "single", "q": "立约签名排在首位的是谁？", "o": ["省长尼希米", "文士以斯拉", "大祭司以利亚实", "族长所罗巴伯"], "a": "省长尼希米", "s": ""}, {"type": "single", "q": "尼希米在亚达薛西王第几年回波斯述职？", "o": ["三十二年", "二十年", "第七年", "第一年"], "a": "三十二年", "s": ""}, {"type": "single", "q": "尼希米为安息日采取了什么措施？", "o": ["关闭城门禁止买卖", "加派利未人巡逻", "写信警告商人", "向王上奏"], "a": "关闭城门禁止买卖", "s": ""}, {"type": "multiple", "q": "尼希米第一章的祷告包括哪些内容？", "o": ["称颂神的信实", "为民族认罪", "记念神的应许", "求王赐下诏书"], "a": "称颂神的信实,为民族认罪,记念神的应许", "s": ""}, {"type": "multiple", "q": "仇敌拦阻建城墙的方式有哪些？", "o": ["讥笑藐视", "武力威胁", "贿赂假先知恐吓", "离间分化"], "a": "讥笑藐视,武力威胁,贿赂假先知恐吓", "s": ""}, {"type": "multiple", "q": "尼希米的改革包括哪些？", "o": ["洁净圣殿", "谨守安息日", "禁娶外邦女子", "恢复十一奉献"], "a": "洁净圣殿,谨守安息日,禁娶外邦女子,恢复十一奉献", "s": ""}, {"type": "multiple", "q": "以斯拉读律法时，百姓有何反应？", "o": ["哭泣", "说阿们", "俯伏敬拜", "欢呼跳舞"], "a": "哭泣,说阿们,俯伏敬拜", "s": ""}, {"type": "judge", "q": "尼希米从未在王面前露出愁容。", "a": "错", "s": ""}, {"type": "judge", "q": "耶路撒冷城墙用了五十二天修完。", "a": "对", "s": ""}, {"type": "judge", "q": "参巴拉是亚扪人，多比雅是撒玛利亚人。", "a": "错", "s": ""}, {"type": "judge", "q": "尼希米作总督期间，没有领取总督的俸禄。", "a": "对", "s": ""}, {"type": "judge", "q": "以斯拉宣读律法从清早直到晌午。", "a": "对", "s": ""}, {"type": "judge", "q": "百姓立约只是口头答应，没有起誓。", "a": "错", "s": ""}, {"type": "judge", "q": "尼希米记以尼希米的祷告“求你记念我，施恩与我”结束。", "a": "对", "s": ""}, {"type": "essay", "q": "尼希米的祷告有何特点？对今日信徒的祷告生活有何启发？", "a": "特点：先称颂神的伟大信实，再为民族认罪（我与父家都有罪），接着抓住神的应许，最后才提具体祈求。启发：祷告不是先求事，乃是先亲近神、认罪对齐神，再按神旨意祈求；大事小事都祷告，祷告与行动并行。", "s": ""}, {"type": "essay", "q": "“一手做工，一手拿兵器”对今日教会事奉有何意义？", "a": "意义：事奉一面积极建造（做工），一面警醒争战（拿兵器）。今日教会传福音、建造生命时，也当警醒祷告，抵挡仇敌的攻击；不因惧怕停工，也不因忙碌疏于防范，靠神刚强壮胆。", "s": ""}, {"type": "essay", "q": "从尼希米的改革，看属灵领袖应具备哪些品格？", "a": "品格：敬畏神过于敬畏人；不谋私利、不领俸禄；敢于责备罪恶、洁净圣殿；以身作则、恒切祷告。领袖的权柄来自圣洁生活与无私奉献，才能带出真实的复兴。", "s": ""}]','','study','[{"title": "尼希米的祷告（1章）", "points": ["哈拿尼从犹大来，报告耶路撒冷城墙拆毁", "尼希米坐下哭泣，悲哀禁食祈祷", "称颂：大而可畏的神，向爱他守诫命的人守约施慈爱", "认罪：我与父家都有罪，违背诫命", "记念应许：被赶散者归回，必领回圣所", "求亨通：在王面前蒙恩（时为基斯流月）"]}, {"title": "蒙允归回（2章）", "points": ["尼希米在王面前愁容，王问：你为何愁容满面", "尼希米默祷后求王差遣他往犹大重建", "王问：要去多久，何时回来（时为尼散月）", "蒙王赐诏书、木料，神施恩的手帮助他", "夜间查看城墙，不告诉任何人", "宣告：我们起来建造吧，众民奋勇做善工"]}, {"title": "建城墙与反对（3-6章）", "points": ["各家各族分段修造：祭司、利未人、商人齐上阵", "参巴拉、多比雅、基善讥笑：你们作什么呢", "祷告交托：一手做工，一手拿兵器", "五十二天修完城墙，以禄月二十五日", "内部问题：贵族重利剥削，尼希米斥责", "假先知示玛雅恐吓，尼希米识破", "仇敌四面设谋，神破坏他们的计谋"]}, {"title": "读律法与认罪立约（7-10章）", "points": ["七月初一，以斯拉在水门广场读律法", "从清早到晌午，众民侧耳而听", "百姓听见律法就哭泣：不要忧愁，靠主喜乐得力", "守住棚节：自约书亚以来未曾如此", "七月二十四日禁食认罪，利未人带领", "追述历史：从亚伯拉罕到归回的神信实", "郑重立约：签名盖印，不娶外邦女子、守安息日"]}, {"title": "奉献城墙与改革（11-13章）", "points": ["城墙奉献礼：两大队称谢的人游行", "立利未人职分，收十一奉献入库", "尼希米回波斯，亚达薛西三十二年再返", "多比雅占据圣殿库房，尼希米抛其家具", "安息日谨守：关闭城门，禁止买卖", "禁娶外邦女子：拉扯咒诅，洁净祭司职分", "结束祷告：我的神啊，求你记念我，施恩与我"]}]','','47','旧约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-179122352498448','圣经导览','以斯帖记','以斯帖记记载被掳中的犹大人：瓦实提被废，以斯帖被立为王后；哈曼阴谋灭绝犹大人，末底改劝勉“焉知你得了王后位分不是为现今机会”。以斯帖冒险见王，全族反败为胜，设立普珥日纪念。','[{"type": "verse", "q": "【经文填空】此时你若闭口不言，犹大人必从别处得解脱，蒙拯救；你和你父家必致灭亡。焉知你得了王后的位分，不是为________吗？", "a": "现今的机会", "ref": "《以斯帖记》4章14节", "s": "", "o": "以斯帖记4章14节"}, {"type": "verse", "q": "【经文填空】我若死就________吧！", "a": "死", "ref": "《以斯帖记》4章16节", "s": "", "o": "以斯帖记4章16节"}, {"type": "verse", "q": "【经文填空】王爱以斯帖过于爱________，她在王眼前蒙宠爱。", "a": "众女", "ref": "《以斯帖记》2章17节", "s": "", "o": "以斯帖记2章17节"}, {"type": "verse", "q": "【经文填空】犹大人有________，欢喜快乐而得尊贵。", "a": "光荣", "ref": "《以斯帖记》8章16节", "s": "", "o": "以斯帖记8章16节"}, {"type": "verse", "q": "【经文填空】犹大人末底改作亚哈随鲁王的宰相，在犹大人中为大，得他众弟兄的喜悦，为本族的人________，向他们说和平的话。", "a": "求好处", "ref": "《以斯帖记》10章3节", "s": "", "o": "以斯帖记10章3节"}, {"type": "verse", "q": "【经文填空】哈曼见末底改不跪不拜，就________。", "a": "怒气填胸", "ref": "《以斯帖记》3章5节", "s": "", "o": "以斯帖记3章5节"}, {"type": "verse", "q": "【经文填空】王对王后以斯帖说：你要什么，我必赐给你；你求什么，就是国的一半，也必________。", "a": "为你成就", "ref": "《以斯帖记》7章2节", "s": "", "o": "以斯帖记5章3节"}, {"type": "fill", "q": "波斯王名叫________，统管一百二十七省。", "a": "亚哈随鲁", "s": ""}, {"type": "fill", "q": "因违命不来见王而被废的王后是________。", "a": "瓦实提", "s": ""}, {"type": "fill", "q": "以斯帖的希伯来名字叫________，意思是桃金娘。", "a": "哈大沙", "s": ""}, {"type": "fill", "q": "抚养以斯帖长大的是她的堂兄________。", "a": "末底改", "s": ""}, {"type": "fill", "q": "哈曼是________族人，亚玛力的后裔。", "a": "亚甲", "s": ""}, {"type": "fill", "q": "哈曼为末底改预备了________肘高的木架。", "a": "五十", "s": ""}, {"type": "fill", "q": "王后违例见王，若不蒙召而入内院，定例是治________。", "a": "死", "s": ""}, {"type": "fill", "q": "以斯帖________日禁食，然后冒险去见王。", "a": "三", "s": ""}, {"type": "fill", "q": "犹大人杀戮仇敌是在________月十三日。", "a": "亚达", "s": ""}, {"type": "fill", "q": "为纪念拯救所设立的节期叫________日。", "a": "普珥", "s": ""}, {"type": "single", "q": "亚哈随鲁王设宴款待群臣贵胄，共多少天？", "o": ["一百八十天", "七天", "三十天", "一年"], "a": "一百八十天", "s": ""}, {"type": "single", "q": "末底改是哪个支派的人？", "o": ["便雅悯", "犹大", "利未", "以法莲"], "a": "便雅悯", "s": ""}, {"type": "single", "q": "女子见王之前，要用香膏抹身多长时间？", "o": ["十二个月", "六个月", "三个月", "一个月"], "a": "十二个月", "s": ""}, {"type": "single", "q": "末底改曾救王脱离什么阴谋？", "o": ["太监谋杀", "外敌入侵", "毒酒", "叛军"], "a": "太监谋杀", "s": ""}, {"type": "single", "q": "哈曼在朝中官居何职？", "o": ["宰相", "太监长", "护卫长", "文士"], "a": "宰相", "s": ""}, {"type": "single", "q": "王向以斯帖伸出金杖，表示什么？", "a": "蒙恩得赦", "o": ["蒙恩得赦", "准其所求", "封她为后", "命她退下"], "s": ""}, {"type": "single", "q": "“普珥”是什么意思？", "o": ["掣签", "拯救", "欢喜", "记念"], "a": "掣签", "s": ""}, {"type": "multiple", "q": "以斯帖被立为王后的预备包括哪些？", "o": ["香膏抹身十二个月", "学习宫廷礼仪", "末底改的嘱咐", "王的亲自挑选"], "a": "香膏抹身十二个月,末底改的嘱咐,王的亲自挑选", "s": ""}, {"type": "multiple", "q": "哈曼图谋灭绝犹大人的原因有哪些？", "o": ["末底改不跪拜", "藐视犹大人", "贪图一万他连得银子", "王的授意"], "a": "末底改不跪拜,藐视犹大人", "s": ""}, {"type": "multiple", "q": "以斯帖拯救本族的行动包括哪些？", "o": ["禁食三日", "冒险见王", "两次设筵", "亲自领兵"], "a": "禁食三日,冒险见王,两次设筵", "s": ""}, {"type": "multiple", "q": "以斯帖记中显明神护理的记号有哪些？", "o": ["王夜不能睡", "末底改功绩被记", "哈曼自挂木架", "以斯帖的美貌"], "a": "王夜不能睡,末底改功绩被记,哈曼自挂木架", "s": ""}, {"type": "judge", "q": "以斯帖记全书没有提到神的名字。", "a": "对", "s": ""}, {"type": "judge", "q": "瓦实提因不肯来见王而被废黜。", "a": "对", "s": ""}, {"type": "judge", "q": "末底改是犹大支派的人。", "a": "错", "s": ""}, {"type": "judge", "q": "哈曼死在他为末底改预备的木架上。", "a": "对", "s": ""}, {"type": "judge", "q": "普珥日只守一天，即亚达月十四日。", "a": "错", "s": ""}, {"type": "judge", "q": "以斯帖是自愿进宫参选王后的。", "a": "错", "s": ""}, {"type": "judge", "q": "犹大人杀戮仇敌时，没有下手夺取财物。", "a": "对", "s": ""}, {"type": "essay", "q": "“焉知你得了王后的位分不是为现今的机会吗”对今日信徒有何意义？", "a": "意义：神把我们放在特定位置（家庭、职场、教会），自有他的美意；当为神国挺身而出时，不可闭口不言。今日信徒也当思想：我的身份、恩赐、机会，是神为此时此刻预备的，要勇敢为主使用。", "s": ""}, {"type": "essay", "q": "以斯帖记虽未提到神的名字，如何显明神的护理？", "a": "处处见神的手：以斯帖奇妙被选为后、王失眠念史书、哈曼自陷木架、犹大人反败为胜。神在幕后掌管万有，虽未见其名，却无处不在。提醒我们：环境再黑暗，神仍在掌权护理属他的人。", "s": ""}, {"type": "essay", "q": "从末底改的一生，看忠心事奉与神的奖赏。", "a": "末底改忠心救王却未得赏，不跪拜哈曼持守信仰，撕衣禁食为本族代求；神记念他的忠心，使他反得尊荣作宰相。功课：忠心不求回报，神必记念；在试炼中持守，神的时候必高举。", "s": ""}]','','study','[{"title": "瓦实提被废（1章）", "points": ["亚哈随鲁王在书珊城设宴一百八十天", "第七日王命太监请王后瓦实提来", "瓦实提违命不来，王大发烈怒", "米母干建议：废瓦实提，另立优于她的", "诏告全国：丈夫在家中作主", "为以斯帖登场埋下伏笔"]}, {"title": "以斯帖被立为后（2章）", "points": ["为王另寻美女，以斯帖（哈大沙）被选入宫", "末底改抚养她，嘱咐不可将籍贯宗族告诉人", "女子依次进去见王前，先用香膏抹身十二个月", "王爱以斯帖过于众女，立她为王后", "末底改坐朝门，救王免于太监谋杀", "功绩记在史书，时未得赏赐"]}, {"title": "哈曼的阴谋（3章）", "points": ["王抬举亚甲族哈曼，超乎众首领", "末底改不跪不拜，哈曼怒气填胸", "哈曼不屑只下手害末底改，图灭犹大人", "掣普珥（签）定日子：亚达月十三日", "许银一万他连得入王库，换灭族诏书", "诏书传遍各省，书珊城慌乱"]}, {"title": "以斯帖的拯救（4-7章）", "points": ["末底改撕衣披麻，命以斯帖见王求恩", "劝勉：焉知你得王后位分不是为现今机会", "以斯帖：禁食三日，我若死就死吧", "违例见王，王伸金杖，以斯帖蒙恩", "设筵两次，请王带哈曼赴席", "王夜不能睡，念史书想起末底改", "二次筵席揭露哈曼，哈曼挂在其木架上"]}, {"title": "普珥日的设立（8-10章）", "points": ["王将哈曼家产赐以斯帖，戒指给末底改", "新诏：准犹大人在各城聚集自卫", "亚达月十三日反杀仇敌七万五千人", "不夺取财物，守为圣洁的争战", "设立普珥日：十四十五两日宴乐互赠", "普珥日世代記念，永不废掉", "末底改作宰相，为本族求好处说和平话"]}]','','48','旧约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220960049','圣经导览','约伯记','约伯记探讨义人为何受苦的千古之谜。撒但的控告、三友的辩论都不能解释约伯的苦难；神在旋风中显现，不解释原因却显明主权，让约伯从风闻转为亲眼见神。苦难是神炼净信心的熔炉。最终神加倍祝福约伯，显明信靠的人必得安慰。','[{"type": "verse", "q": "【经文填空】我赤身出于母胎，也必赤身归回。________的是耶和华，________的也是耶和华。耶和华的名是应当称颂的。", "a": "赏赐|收取", "ref": "《约伯记》1章21节", "s": "", "o": "约伯记1章21节"}, {"type": "verse", "q": "【经文填空】我知道我的________活着，末了必站立在地上。", "a": "救赎主", "ref": "《约伯记》19章25节", "s": "", "o": "约伯记19章25节"}, {"type": "verse", "q": "【经文填空】然而他知道我所行的路，他________我之后，我必如________。", "a": "试炼|精金", "ref": "《约伯记》23章10节", "s": "", "o": "约伯记23章10节"}, {"type": "verse", "q": "【经文填空】我从前________有你，现在________看见你。", "a": "风闻|亲眼", "ref": "《约伯记》42章5节", "s": "", "o": "约伯记42章5节"}, {"type": "verse", "q": "【经文填空】难道我们从神手里________，不也________吗？", "a": "得福|受祸", "ref": "《约伯记》2章10节", "s": "", "o": "约伯记2章10节"}, {"type": "verse", "q": "【经文填空】我立大地根基的时候，你在________？你若有聪明，只管说吧！", "a": "哪里", "ref": "《约伯记》38章4节", "s": "", "o": "约伯记38章4节"}, {"type": "verse", "q": "【经文填空】我知道你________都能做，你的________不能拦阻。", "a": "万事|旨意", "ref": "《约伯记》42章2节", "s": "", "o": "约伯记42章2节"}, {"type": "fill", "q": "撒但在神面前控告约伯，说他敬畏神是因神________他。", "a": "赐福", "s": ""}, {"type": "fill", "q": "约伯的三个朋友是以利法、________、琐法。", "a": "比勒达", "s": ""}, {"type": "fill", "q": "约伯的妻子在约伯受苦时劝他________神，死了吧。", "a": "弃掉", "s": ""}, {"type": "fill", "q": "以利户自称年纪________，因此不敢在年长者面前先发言。", "a": "幼小", "s": ""}, {"type": "fill", "q": "神在________中回答约伯，向他显明创造的大能。", "a": "旋风", "s": ""}, {"type": "fill", "q": "约伯为他的________祈祷之后，耶和华使他从苦境转回。", "a": "朋友", "s": ""}, {"type": "fill", "q": "约伯末后所得的福分比先前所有的________。", "a": "加倍", "s": ""}, {"type": "fill", "q": "约伯住在________地，为人完全正直，敬畏神，远离恶事。", "a": "乌斯", "s": ""}, {"type": "fill", "q": "神吩咐以利法等人要献________只公牛、________只公羊作燔祭。", "a": "七|七", "s": ""}, {"type": "fill", "q": "约伯在受苦之后又活了________年，得见四代子孙。", "a": "一百四十", "s": ""}, {"type": "single", "q": "撒但第一次攻击，约伯失去了什么？", "o": ["儿女和牲畜", "健康", "性命", "妻子"], "a": "儿女和牲畜", "s": ""}, {"type": "single", "q": "约伯开口咒诅的是什么？", "o": ["自己的生日", "神", "撒但", "三友"], "a": "自己的生日", "s": ""}, {"type": "single", "q": "以利户是哪里人？", "o": ["布西人", "提幔人", "书亚人", "拿玛人"], "a": "布西人", "s": ""}, {"type": "single", "q": "神在旋风中用哪两种动物向约伯显明大能？", "o": ["河马与鳄鱼", "狮子与野牛", "鹰与鸵鸟", "熊与鹿"], "a": "河马与鳄鱼", "s": ""}, {"type": "single", "q": "约伯的女儿不包括以下哪一位？", "o": ["耶米玛", "基洗亚", "基连哈朴", "底拿"], "a": "底拿", "s": ""}, {"type": "single", "q": "三友中，提幔人是谁？", "o": ["以利法", "比勒达", "琐法", "以利户"], "a": "以利法", "s": ""}, {"type": "single", "q": "神允许撒但攻击约伯，但有一条界限是：", "o": ["不可害他的性命", "不可动他的牲畜", "不可碰他的儿女", "不可使他生病"], "a": "不可害他的性命", "s": ""}, {"type": "multiple", "q": "约伯的三位朋友是：", "o": ["以利法", "比勒达", "琐法", "以利户"], "a": "以利法,比勒达,琐法", "s": ""}, {"type": "multiple", "q": "撒但两次攻击约伯，神允许的范围包括：", "o": ["夺去儿女牲畜", "击打约伯的健康", "取去约伯的性命", "离间约伯的妻子"], "a": "夺去儿女牲畜,击打约伯的健康", "s": ""}, {"type": "multiple", "q": "神在旋风中向约伯提到的创造之工有：", "o": ["大地的根基", "海的门", "晨星", "雪雹的库"], "a": "大地的根基,海的门,晨星,雪雹的库", "s": ""}, {"type": "multiple", "q": "约伯记中指向基督救赎的经文有：", "o": ["伯19:25救赎主活着", "伯16:19在天有中保", "伯33:23-24代求者寻得赎价", "伯1:1完全正直"], "a": "伯19:25救赎主活着,伯16:19在天有中保,伯33:23-24代求者寻得赎价", "s": ""}, {"type": "judge", "q": "约伯受苦是因为他犯了大罪。", "a": "错", "s": ""}, {"type": "judge", "q": "撒但第一次攻击后，约伯仍然持守纯正，没有以口犯罪。", "a": "对", "s": ""}, {"type": "judge", "q": "约伯的三友用正确的神学安慰了约伯。", "a": "错", "s": ""}, {"type": "judge", "q": "以利户比约伯的三友年长。", "a": "错", "s": ""}, {"type": "judge", "q": "神在旋风中逐一回答了约伯所有的疑问。", "a": "错", "s": ""}, {"type": "judge", "q": "约伯最终在神面前懊悔，承认自己所说的是他不明白的。", "a": "对", "s": ""}, {"type": "judge", "q": "约伯死的时候年纪老迈，日子满足。", "a": "对", "s": ""}, {"type": "essay", "q": "约伯受苦的真正原因是什么？这对“善有善报、恶有恶报”的传统观念有何冲击？", "a": "约伯受苦并非因犯罪，而是撒但在神面前的控告，以及神允许的试炼。这打破了三友“苦难必因罪”的机械报应神学，显明苦难可以是神主权的试炼，为要炼净人的信心，使人更深认识神。", "s": ""}, {"type": "essay", "q": "神在旋风中的回答为何没有直接解释苦难的原因？这给你什么启发？", "a": "神没有解释“为什么”，而是向约伯显明祂创造与护理的大能，让约伯认识自己的有限。启发：面对苦难，答案不在解释，而在更深认识神的所是；信心的根基是神的信实，而非对原因的理解。", "s": ""}, {"type": "essay", "q": "“我知道我的救赎主活着”（伯19:25）在整卷书中有何神学意义？", "a": "这是全书信仰的高峰：在极深的痛苦中，约伯仍抓住末后复活的盼望，预表基督的救赎。它显明真信心在黑暗中依然仰望神，也为新约复活的真理埋下伏笔。", "s": ""}]','','study','[{"title": "撒但的控告（1-2章）", "points": ["约伯完全正直，是乌斯地的义人", "撒但控告：约伯敬畏神是为得福", "神允许撒但夺去儿女牲畜", "约伯仍说：耶和华的名是应当称颂的", "撒但再击打约伯的健康", "约伯妻子劝他弃掉神", "难道我们从神手里得福，不也受祸吗"]}, {"title": "三友的辩论（3-31章）", "points": ["约伯咒诅自己的生日", "以利法：温和劝诫，人岂能比神公义", "比勒达：传统报应神学，神不丢弃完全人", "琐法：严厉定罪，要求约伯认罪", "约伯坚持自己无辜，要求与神理论", "三友的神学正确却用错了对象", "约伯在黑暗中仍抓住救赎主活着的盼望"]}, {"title": "以利户的发言（32-37章）", "points": ["以利户年幼，不敢先发言", "向三友和约伯发怒", "神藉苦难开通人的耳朵", "神大有能力，不轻看人", "为神的公义辩护", "描述神在自然中的大能", "为旋风中的神预备道路"]}, {"title": "旋风中的神（38-41章）", "points": ["耶和华从旋风中回答约伯", "我立大地根基时你在哪里", "海的门、晨星、雪雹的库", "河马与鳄鱼：神大能的见证", "神没有解释苦难的原因", "约伯认识自己的无知", "启示神的主权超越人的理解"]}, {"title": "悔改与加倍祝福（42章）", "points": ["我从前风闻有你，现在亲眼看见你", "约伯在尘土中懊悔", "神向三友发怒，要约伯为他们代求", "约伯为朋友祈祷，神使他从苦境转回", "神赐给他的比从前加倍", "又活一百四十年，见四代子孙", "苦难的终点是更深地认识神"]}]','','49','旧约•诗歌智慧书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220960050','圣经导览','诗篇','诗篇是圣经的赞美诗集，共一百五十篇，是历代圣徒的祷告与诗歌。从大卫的悔罪到弥赛亚的预言，从青草地的安息到哈利路亚的欢呼，诗篇是信徒灵修与敬拜的宝库。无论顺境逆境，诗篇都教导我们向神倾心吐意。','[{"type": "verse", "q": "【经文填空】耶和华是我的________，我必不至________。", "a": "牧者|缺乏", "ref": "《诗篇》23章1节", "s": "", "o": "诗篇23篇1节"}, {"type": "verse", "q": "【经文填空】他要像一棵树栽在________旁，按时候________，叶子也不枯干。", "a": "溪水|结果子", "ref": "《诗篇》1章3节", "s": "", "o": "诗篇1篇3节"}, {"type": "verse", "q": "【经文填空】你们要________，要知道我是________。", "a": "休息|神", "ref": "《诗篇》46章10节", "s": "", "o": "诗篇46篇10节"}, {"type": "verse", "q": "【经文填空】神啊，求你为我造________的心，使我里面重新有________的灵。", "a": "清洁|正直", "ref": "《诗篇》51章10节", "s": "", "o": "诗篇51篇10节"}, {"type": "verse", "q": "【经文填空】你的话是我脚前的________，是我路上的________。", "a": "灯|光", "ref": "《诗篇》119章105节", "s": "", "o": "诗篇119篇105节"}, {"type": "verse", "q": "【经文填空】求你指教我们怎样________自己的日子，好叫我们得着________的心。", "a": "数算|智慧", "ref": "《诗篇》90章12节", "s": "", "o": "诗篇90篇12节"}, {"type": "verse", "q": "【经文填空】一宿虽然有________，早晨便必________。", "a": "哭泣|欢呼", "ref": "《诗篇》30章5节", "s": "", "o": "诗篇30篇5节"}, {"type": "fill", "q": "诗篇共________篇，是圣经中篇数最多的一卷。", "a": "一百五十", "s": ""}, {"type": "fill", "q": "诗篇第________篇最长，全篇颂赞神的律法。", "a": "119", "s": ""}, {"type": "fill", "q": "“我的神，我的神，为什么离弃我”是诗篇第________篇的开篇。", "a": "22", "s": ""}, {"type": "fill", "q": "大卫为与拔示巴犯罪而悔罪的诗是第________篇。", "a": "51", "s": ""}, {"type": "fill", "q": "“匠人所弃的石头已成了房角的头块石头”出自诗篇第________篇。", "a": "118", "s": ""}, {"type": "fill", "q": "摩西的祈祷是诗篇第________篇。", "a": "90", "s": ""}, {"type": "fill", "q": "上行之诗是指诗篇第________篇至134篇。", "a": "120", "s": ""}, {"type": "fill", "q": "诗篇119篇是按________字母顺序写成的离合诗。", "a": "希伯来", "s": ""}, {"type": "fill", "q": "“耶和华是我的牧者”出自诗篇第________篇。", "a": "23", "s": ""}, {"type": "fill", "q": "诗篇中多次出现的“________”，可能是音乐或休止的记号。", "a": "细拉", "s": ""}, {"type": "single", "q": "诗篇2篇“你是我的儿子，我今日生你”在新约中指向：", "o": ["大卫", "所罗门", "基督", "以色列"], "a": "基督", "s": ""}, {"type": "single", "q": "诗篇22篇主要预言了基督的：", "o": ["降生", "受难", "复活", "升天"], "a": "受难", "s": ""}, {"type": "single", "q": "诗篇110篇“照麦基洗德的等次永远为祭司”预言基督的：", "o": ["君王职分", "祭司职分", "先知职分", "三个职分"], "a": "祭司职分", "s": ""}, {"type": "single", "q": "诗篇51篇的写作背景是：", "o": ["大卫与拔示巴犯罪后", "大卫逃避扫罗", "大卫攻取耶路撒冷", "大卫数点百姓"], "a": "大卫与拔示巴犯罪后", "s": ""}, {"type": "single", "q": "“如鹿切慕溪水”出自：", "o": ["诗42篇", "诗63篇", "诗84篇", "诗122篇"], "a": "诗42篇", "s": ""}, {"type": "single", "q": "诗篇90篇的作者是：", "o": ["摩西", "大卫", "所罗门", "亚萨"], "a": "摩西", "s": ""}, {"type": "single", "q": "诗篇中篇幅最短的是：", "o": ["诗117篇", "诗131篇", "诗133篇", "诗134篇"], "a": "诗117篇", "s": ""}, {"type": "multiple", "q": "以下属于弥赛亚诗篇的有：", "o": ["诗2篇", "诗22篇", "诗110篇", "诗118篇"], "a": "诗2篇,诗22篇,诗110篇,诗118篇", "s": ""}, {"type": "multiple", "q": "诗篇23篇中神的供应包括：", "o": ["青草地", "可安歇的水边", "筵席", "福杯满溢"], "a": "青草地,可安歇的水边,筵席,福杯满溢", "s": ""}, {"type": "multiple", "q": "诗篇51篇大卫的认罪包括：", "o": ["求神涂抹过犯", "求造清洁的心", "神所要的是忧伤痛悔的心", "求神赐他作王的智慧"], "a": "求神涂抹过犯,求造清洁的心,神所要的是忧伤痛悔的心", "s": ""}, {"type": "multiple", "q": "诗篇的作者包括：", "o": ["大卫", "亚萨", "可拉的后裔", "所罗门"], "a": "大卫,亚萨,可拉的后裔,所罗门", "s": ""}, {"type": "judge", "q": "诗篇是圣经中篇数最多的一卷。", "a": "对", "s": ""}, {"type": "judge", "q": "诗篇119篇是全书最短的一篇。", "a": "错", "s": ""}, {"type": "judge", "q": "诗篇22篇预言了基督在十字架上的受难。", "a": "对", "s": ""}, {"type": "judge", "q": "诗篇全部150篇都是大卫写的。", "a": "错", "s": ""}, {"type": "judge", "q": "“细拉”一词只出现在诗篇中。", "a": "错", "s": ""}, {"type": "judge", "q": "诗篇150篇呼召凡有气息的都要赞美耶和华。", "a": "对", "s": ""}, {"type": "judge", "q": "诗篇51篇是大卫为数点百姓认罪而写。", "a": "错", "s": ""}, {"type": "essay", "q": "诗篇22篇如何预言基督的受难？请列举至少三处在十字架上的应验。", "a": "开篇“我的神，为什么离弃我”正是基督在十字架上的呼喊；“他们扎了我的手，我的脚”预言钉十字架；“他们分我的外衣，为我的里衣拈阄”应验在兵丁分基督衣服的事上。整篇是从受难转向复活的赞美。", "s": ""}, {"type": "essay", "q": "从诗篇51篇看，大卫的认罪有何特点？对今日信徒有何提醒？", "a": "大卫不推诿，直认“我向你犯罪，惟独得罪了你”；求神造清洁的心，而非只求免罚；承认神要的是忧伤痛悔的心。提醒：真认罪是对神认罪、求心被洁净，而非只求后果消除。", "s": ""}, {"type": "essay", "q": "诗篇23篇如何描绘神作牧者的慈爱与信实？", "a": "供应（青草地、可安歇的水边）、引导（义路）、保护（死荫幽谷不怕遭害）、同在（杖与竿安慰）、丰盛（筵席、福杯满溢）、永恒（住在耶和华殿中直到永远）。神是全备的牧者。", "s": ""}]','','study','[{"title": "智慧与律法之歌（1、19、119篇）", "points": ["诗1篇：义人如树栽于溪水旁", "恶人如糠秕被风吹散", "诗19篇：诸天述说神的荣耀", "神的律法全备，能苏醒人心", "诗119篇：全书最长，颂赞律法", "你的话是我脚前的灯、路上的光", "少年人用何洁净行为？遵行神的话"]}, {"title": "悔罪与切慕（32、42、51篇）", "points": ["诗32篇：认罪蒙赦免的福", "我闭口不认罪，骨头枯干", "诗42篇：如鹿切慕溪水", "我的心切慕你，如鹿切慕溪水", "诗51篇：大卫为拔示巴事件悔罪", "神啊，求你为我造清洁的心", "神所要的祭是忧伤痛悔的心"]}, {"title": "弥赛亚诗篇（2、22、110、118篇）", "points": ["诗2篇：你是我的儿子，我今日生你", "诗22篇：我的神，为什么离弃我", "预言十字架：分外衣、拈阄分里衣", "诗110篇：你坐在我的右边", "照麦基洗德的等次永远为祭司", "诗118篇：匠人所弃的石头成房角石", "和散那归于大卫的子孙的出处"]}, {"title": "赞美与感恩（100、103、150篇）", "points": ["诗100篇：普天下当向耶和华欢呼", "当称谢进入他的门", "诗103篇：不可忘记他一切的恩惠", "他赦免你一切罪孽，医治你一切疾病", "东离西有多远，神叫过犯离我们多远", "诗150篇：凡有气息的都要赞美耶和华", "用各样乐器赞美神"]}, {"title": "上行与信靠之诗（121、127、139篇）", "points": ["诗121篇：我的帮助从造天地的耶和华而来", "保护以色列的不打盹也不睡觉", "诗127篇：若不是耶和华建造房屋", "儿女是耶和华所赐的产业", "诗139篇：神无所不知、无所不在", "我往哪里去躲避你的灵", "受造奇妙可畏，神早已认识我"]}]','','50','旧约•诗歌智慧书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220960051','圣经导览','箴言','箴言是所罗门的智慧之书，以敬畏耶和华为智慧的开端。从言语、勤劳、交友到家庭，从义人与恶人的对比到才德妇人的颂歌，箴言把属天的智慧带进日常生活的每个细节。敬畏神的人，必在凡事上得着真智慧与福分。','[{"type": "verse", "q": "【经文填空】敬畏耶和华是________的开端，愚妄人藐视________和训诲。", "a": "知识|智慧", "ref": "《箴言》1章7节", "s": "", "o": "箴言1章7节"}, {"type": "verse", "q": "【经文填空】你要________仰赖耶和华，不可倚靠自己的________。", "a": "专心|聪明", "ref": "《箴言》3章5节", "s": "", "o": "箴言3章5节"}, {"type": "verse", "q": "【经文填空】你要保守你心，胜过保守一切，因为一生的________是由心发出。", "a": "果效", "ref": "《箴言》4章23节", "s": "", "o": "箴言4章23节"}, {"type": "verse", "q": "【经文填空】敬畏耶和华是________的开端，认识至圣者便是________。", "a": "智慧|聪明", "ref": "《箴言》9章10节", "s": "", "o": "箴言9章10节"}, {"type": "verse", "q": "【经文填空】人心________自己的道路，惟耶和华________他的脚步。", "a": "筹算|指引", "ref": "《箴言》16章9节", "s": "", "o": "箴言16章9节"}, {"type": "verse", "q": "【经文填空】教养孩童，使他走当行的道，就是到老他也不________。", "a": "偏离", "ref": "《箴言》22章6节", "s": "", "o": "箴言22章6节"}, {"type": "verse", "q": "【经文填空】不要为________自夸，因为一日要生何事，你尚且________。", "a": "明日|不能知", "ref": "《箴言》27章1节", "s": "", "o": "箴言27章1节"}, {"type": "fill", "q": "箴言的主要作者是________王。", "a": "所罗门", "s": ""}, {"type": "fill", "q": "箴言第30章的作者是________。", "a": "亚古珥", "s": ""}, {"type": "fill", "q": "箴言31章颂赞________的妇人。", "a": "才德", "s": ""}, {"type": "fill", "q": "“懒惰人哪，你去察看________的动作就可得智慧。”", "a": "蚂蚁", "s": ""}, {"type": "fill", "q": "箴言共有________章。", "a": "三十一", "s": ""}, {"type": "fill", "q": "“耶和华所赐的福使人富足，并不加上________。”", "a": "忧虑", "s": ""}, {"type": "fill", "q": "“回答柔和，使怒消退；言语________，触动怒气。”", "a": "暴戾", "s": ""}, {"type": "fill", "q": "箴言多次警告不可为________作保。", "a": "外人", "s": ""}, {"type": "fill", "q": "“________磨________，磨出刃来；朋友相感也是如此。”", "a": "铁|铁", "s": ""}, {"type": "fill", "q": "利慕伊勒是________的王。", "a": "玛撒", "s": ""}, {"type": "single", "q": "“敬畏耶和华是知识的开端”出自：", "o": ["箴1:7", "箴3:5", "箴9:10", "诗111:10"], "a": "箴1:7", "s": ""}, {"type": "single", "q": "箴言中智慧拟人化呼唤的主要篇章是：", "o": ["第8章", "第1章", "第31章", "第30章"], "a": "第8章", "s": ""}, {"type": "single", "q": "“才德的妇人价值远胜过”：", "o": ["珍珠", "黄金", "宝石", "白银"], "a": "珍珠", "s": ""}, {"type": "single", "q": "“铁磨铁，磨出刃来”出自：", "o": ["箴27:17", "箴15:1", "箴17:17", "箴18:24"], "a": "箴27:17", "s": ""}, {"type": "single", "q": "亚古珥求神使他不贫穷也不富足，原因是：", "o": ["恐怕饱足不认神，贫穷就偷窃", "想过平淡生活", "不喜欢钱财", "怕被人嫉妒"], "a": "恐怕饱足不认神，贫穷就偷窃", "s": ""}, {"type": "single", "q": "“朋友乃时常亲爱，弟兄为________而生”：", "o": ["患难", "喜乐", "富足", "平安"], "a": "患难", "s": ""}, {"type": "single", "q": "箴言31章是何人母亲教训他的话？", "o": ["利慕伊勒", "所罗门", "亚古珥", "希西家"], "a": "利慕伊勒", "s": ""}, {"type": "multiple", "q": "箴言论到言语的教训有：", "o": ["回答柔和使怒消退", "生死在舌头的权下", "多言多语难免有过", "一句话合宜如金苹果"], "a": "回答柔和使怒消退,生死在舌头的权下,多言多语难免有过,一句话合宜如金苹果", "s": ""}, {"type": "multiple", "q": "箴言中义人与恶人的对比包括：", "o": ["义人的路如黎明的光", "恶人的路如幽暗", "义人的口是生命泉源", "恶人必如糠秕"], "a": "义人的路如黎明的光,恶人的路如幽暗,义人的口是生命泉源", "s": ""}, {"type": "multiple", "q": "箴言对勤劳的教训有：", "o": ["去察看蚂蚁的动作", "懒惰人羡慕却无所得", "殷勤人的手必掌权", "冬天不耕种就无收"], "a": "去察看蚂蚁的动作,懒惰人羡慕却无所得,殷勤人的手必掌权", "s": ""}, {"type": "multiple", "q": "才德妇人的品德包括：", "o": ["终身使丈夫有益无损", "甘心用手做工", "怜悯贫穷人", "开口就发智慧"], "a": "终身使丈夫有益无损,甘心用手做工,怜悯贫穷人,开口就发智慧", "s": ""}, {"type": "judge", "q": "箴言全书都是所罗门一人写的。", "a": "错", "s": ""}, {"type": "judge", "q": "“敬畏耶和华是智慧的开端”是箴言的核心主题。", "a": "对", "s": ""}, {"type": "judge", "q": "箴言只讲处世哲学，与信仰无关。", "a": "错", "s": ""}, {"type": "judge", "q": "箴言31章是利慕伊勒王母亲教训他的话。", "a": "对", "s": ""}, {"type": "judge", "q": "箴言主张完全禁酒，一滴都不可沾。", "a": "错", "s": ""}, {"type": "judge", "q": "箴言肯定管教孩童的智慧。", "a": "对", "s": ""}, {"type": "judge", "q": "箴言第8章的智慧被认为预表基督。", "a": "对", "s": ""}, {"type": "essay", "q": "“敬畏耶和华是智慧的开端”如何贯穿整卷箴言？", "a": "开篇1:7提出，9:10重申，中间所有伦理教训（言语、勤劳、交友、家庭）都以此为根基，结尾31:30“敬畏耶和华的女子必得称赞”收束。真智慧不是技巧，而是与神正确的关系。", "s": ""}, {"type": "essay", "q": "箴言第8章智慧的自我描述与基督有何关联？", "a": "智慧说“在耶和华造化的起头，在太初创造万物之先，就有了我”，新约称基督为“神的智慧”（林前1:24），约翰福音的“道”与此呼应。智慧参与创造、喜悦人世，预表基督创造与救赎之工。", "s": ""}, {"type": "essay", "q": "从才德的妇人（箴31章）看，圣经中的女性美德是什么？", "a": "能干（经商、田产）、慈惠（周济穷人）、智慧（开口发智慧）、敬虔（敬畏耶和华）。价值不在外貌（“艳丽是虚假的”），而在敬畏神与忠心服事家庭。", "s": ""}]','','study','[{"title": "智慧的开端（1-9章）", "points": ["敬畏耶和华是知识的开端", "要专心仰赖耶和华，不可倚靠聪明", "你要保守你心，胜过保守一切", "智慧在街市上呼喊", "第8章智慧的拟人化，预表基督", "远离淫妇，走生命的道", "认识至圣者便是聪明"]}, {"title": "义人与恶人（10-15章）", "points": ["义人的口是生命的泉源", "生死在舌头的权下", "回答柔和，使怒消退", "耶和华的眼目无处不在", "心中安静是肉体的生命", "义人的路如黎明的光", "恶人的路如幽暗"]}, {"title": "君王与人生（16-22章）", "points": ["人心筹算，耶和华指引脚步", "骄傲在败坏以先，狂心在跌倒之前", "朋友乃时常亲爱，弟兄为患难而生", "教养孩童走当行的道", "好名声胜过大财", "耶和华所赐的福使人富足", "不可为外人作保"]}, {"title": "智言与警戒（23-29章）", "points": ["不要为明日自夸", "铁磨铁，磨出刃来", "懒惰人的田地长满荆棘", "管教孩童的智慧", "义人所结的果子就是生命树", "愚妄人怒气全发，智慧人忍气含怒", "多言多语难免有过"]}, {"title": "亚古珥与才德妇人（30-31章）", "points": ["亚古珥的祷告：不贫穷也不富足", "蚂蚁、沙番、蝗虫、守宫的智慧", "利慕伊勒王母亲的教训", "才德的妇人价值远胜过珍珠", "她终身使丈夫有益无损", "怜悯贫穷人，开口发智慧", "艳丽是虚假的，敬畏耶和华的女子必得称赞"]}]','','51','旧约•诗歌智慧书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220960052','圣经导览','传道书','传道书是所罗门晚年的沉思录，看透日光之下尽是虚空。享乐、智慧、财富、工程都不能填满人心；唯有趁年幼记念造物主，敬畏神、谨守他的诫命，才是人生的出路与归宿。敬畏神谨守诫命，这是人所当尽的本分。','[{"type": "verse", "q": "【经文填空】________的虚空，________的虚空，凡事都是虚空。", "a": "虚空|虚空", "ref": "《传道书》1章2节", "s": "", "o": "传道书1章2节"}, {"type": "verse", "q": "【经文填空】凡事都有________，天下万务都有________。", "a": "定期|定时", "ref": "《传道书》3章1节", "s": "", "o": "传道书3章1节"}, {"type": "verse", "q": "【经文填空】神造万物，各按其时成为________，又将________安置在世人心里。", "a": "美好|永生", "ref": "《传道书》3章11节", "s": "", "o": "传道书3章11节"}, {"type": "verse", "q": "【经文填空】你趁着年幼、衰败的日子尚未来到，当________造你的主。", "a": "记念", "ref": "《传道书》12章1节", "s": "", "o": "传道书12章1节"}, {"type": "verse", "q": "【经文填空】敬畏神，________他的诫命，这是人所当尽的________。", "a": "谨守|本分", "ref": "《传道书》12章13节", "s": "", "o": "传道书12章13节"}, {"type": "verse", "q": "【经文填空】你到神的殿要________脚步。", "a": "谨慎", "ref": "《传道书》5章1节", "s": "", "o": "传道书5章1节"}, {"type": "verse", "q": "【经文填空】两个人总比一个人好，因为二人劳碌同得________。", "a": "美好的果效", "ref": "《传道书》4章9节", "s": "", "o": "传道书4章9节"}, {"type": "fill", "q": "传道书的作者传统上认为是________王。", "a": "所罗门", "s": ""}, {"type": "fill", "q": "“日光之下”在传道书中出现约________次，形容属地的生活。", "a": "二十九", "s": ""}, {"type": "fill", "q": "传道者自称“在耶路撒冷作过以色列的________”。", "a": "王", "s": ""}, {"type": "fill", "q": "“我见日光之下所做的一切事，都是虚空，都是________。”", "a": "捕风", "s": ""}, {"type": "fill", "q": "传道书第3章说“生有时，________有时”。", "a": "死", "s": ""}, {"type": "fill", "q": "“你当从心中除掉________，从肉体克去邪恶。”", "a": "愁烦", "s": ""}, {"type": "fill", "q": "“往遭丧的家去，强如往________的家去。”", "a": "宴乐", "s": ""}, {"type": "fill", "q": "传道书说“智慧胜过________，如同光明胜过黑暗”。", "a": "愚昧", "s": ""}, {"type": "fill", "q": "“当将你的粮食撒在________。”", "a": "水面", "s": ""}, {"type": "fill", "q": "传道书共________章。", "a": "十二", "s": ""}, {"type": "single", "q": "传道书的中心钥词是：", "o": ["虚空", "智慧", "劳碌", "日光之下"], "a": "虚空", "s": ""}, {"type": "single", "q": "“凡事都有定期”出自：", "o": ["传3章", "传1章", "传7章", "传12章"], "a": "传3章", "s": ""}, {"type": "single", "q": "传道书结尾的结论是：", "o": ["敬畏神谨守诫命", "享受人生", "追求智慧", "积攒财富"], "a": "敬畏神谨守诫命", "s": ""}, {"type": "single", "q": "“日光之下无新事”的意思是：", "o": ["历史循环，属地生活无真正新意", "太阳下没有新发明", "神不再创造", "人不能创新"], "a": "历史循环，属地生活无真正新意", "s": ""}, {"type": "single", "q": "“神将永生安置在世人心里”表明：", "o": ["人有超越今生的渴望", "人不会死", "人人都得救", "永生就是长寿"], "a": "人有超越今生的渴望", "s": ""}, {"type": "single", "q": "“两个人总比一个人好”的上下文是论：", "o": ["婚姻", "友谊与同工", "商业", "战争"], "a": "友谊与同工", "s": ""}, {"type": "single", "q": "传道书的作者在书中自称是：", "o": ["大卫的儿子", "在耶路撒冷作王", "传道者", "以上都是"], "a": "以上都是", "s": ""}, {"type": "multiple", "q": "传道者试验过的人生追求包括：", "o": ["享乐宴乐", "智慧知识", "财富工程", "敬虔祷告"], "a": "享乐宴乐,智慧知识,财富工程", "s": ""}, {"type": "multiple", "q": "传3章“凡事都有定时”包括：", "o": ["生有时死有时", "哭有时笑有时", "战争有时和平有时", "爱有时恨有时"], "a": "生有时死有时,哭有时笑有时,战争有时和平有时,爱有时恨有时", "s": ""}, {"type": "multiple", "q": "传道书对青年的劝勉有：", "o": ["幼年时当快乐", "当记念造你的主", "神必为这一切审问你", "及时行乐不顾后果"], "a": "幼年时当快乐,当记念造你的主,神必为这一切审问你", "s": ""}, {"type": "multiple", "q": "传道书中“美好/强如”的对比有：", "o": ["智慧胜过愚昧", "名誉强如美好的膏油", "往遭丧家强如宴乐家", "贫穷强如富足"], "a": "智慧胜过愚昧,名誉强如美好的膏油,往遭丧家强如宴乐家", "s": ""}, {"type": "judge", "q": "传道书的结论是人生毫无意义和盼望。", "a": "错", "s": ""}, {"type": "judge", "q": "“虚空的虚空”是传道书的钥词。", "a": "对", "s": ""}, {"type": "judge", "q": "传道书鼓励人敬畏神、谨守他的诫命。", "a": "对", "s": ""}, {"type": "judge", "q": "传道者认为智慧与愚昧毫无区别。", "a": "错", "s": ""}, {"type": "judge", "q": "“日光之下”指属神的永恒国度。", "a": "错", "s": ""}, {"type": "judge", "q": "传统认为传道书是所罗门晚年的作品。", "a": "对", "s": ""}, {"type": "judge", "q": "传道书12章劝少年人当记念造他的主。", "a": "对", "s": ""}, {"type": "essay", "q": "“虚空的虚空”是什么意思？传道书是悲观的书吗？", "a": "“虚空”原文如蒸气、捕风，形容日光之下属地追求的短暂无常。传道书不是悲观，而是诚实的诊断：离了神，一切都是虚空；归向神，人生就有意义。结尾指向敬畏神的出路。", "s": ""}, {"type": "essay", "q": "传3:1-8“凡事都有定时”对今日信徒有何安慰？", "a": "神掌管时间，万事各按其时。哭有时笑有时，顺境逆境都在神手中。信徒不必焦虑强求，学会等候神的时间，信靠祂的美意。", "s": ""}, {"type": "essay", "q": "传道书的结论“敬畏神，谨守他的诫命”如何回应全书的“虚空”主题？", "a": "全书论证日光之下皆虚空，结论给出出路：虚空的解药是敬畏神。人生的意义不在日光之下寻找，而在日光之上——与神恢复关系、遵行祂的诫命。", "s": ""}]','','study','[{"title": "虚空的开篇（1-2章）", "points": ["虚空的虚空，凡事都是虚空", "日光之下无新事", "传道者在耶路撒冷作过以色列的王", "试验享乐：我心所乐的，我没有禁止", "建造工程、积蓄财富的试验", "智慧与愚昧的比较", "一切都是捕风，日光之下无益处"]}, {"title": "定时与永生（3-4章）", "points": ["凡事都有定期，天下万务都有定时", "生有时，死有时；哭有时，笑有时", "神造万物各按其时成为美好", "神将永生安置在世人心里", "两个人总比一个人好", "劳碌的果效与孤独的悲哀", "敬畏神的人终得好处"]}, {"title": "神殿与言语（5-7章）", "points": ["到神的殿要谨慎脚步", "许愿不还，不如不许", "多梦和多言，其中多有虚幻", "不要因亢奋在神面前冒失开口", "智慧胜过愚昧，如光明胜过黑暗", "名誉强如美好的膏油", "不要说先前的日子强过如今"]}, {"title": "智慧与青年（8-11章）", "points": ["智慧使人的脸发光", "无人能掌管生命，无人能掌管死期", "当将你的粮食撒在水面", "早晚撒种，不知哪一样发旺", "少年人哪，在幼年时当快乐", "神必为这一切审问你", "从心中除掉愁烦，从肉体克去邪恶"]}, {"title": "归宿与结论（12章）", "points": ["当记念造你的主", "衰败的日子、艰难的岁月", "银链折断、金罐破裂的比喻", "尘土仍归于地，灵仍归于赐灵的神", "传道者训众人的结语", "敬畏神，谨守他的诫命", "这是人所当尽的本分"]}]','','52','旧约•诗歌智慧书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220960053','圣经导览','雅歌','雅歌是所罗门的歌中之歌，歌颂圣洁专一的爱情。从相遇到相知，从寻求到联合，良人与书拉密女的爱情预表基督爱教会——那如死之坚强、众水不能熄灭的爱。愿每位信徒都经历这份专一、圣洁、永恒的爱。','[{"type": "verse", "q": "【经文填空】所罗门的歌，是________中的________。", "a": "歌|雅歌", "ref": "《雅歌》1章1节", "s": "", "o": "雅歌1章1节"}, {"type": "verse", "q": "【经文填空】他带我入________所，以________为旗在我以上。", "a": "筵宴|爱", "ref": "《雅歌》2章4节", "s": "", "o": "雅歌2章4节"}, {"type": "verse", "q": "【经文填空】良人属我，我也属他；他在________中牧放群羊。", "a": "百合花", "ref": "《雅歌》2章16节", "s": "", "o": "雅歌2章16节"}, {"type": "verse", "q": "【经文填空】我属我的________，我的良人也属我。", "a": "良人", "ref": "《雅歌》6章3节", "s": "", "o": "雅歌6章3节"}, {"type": "verse", "q": "【经文填空】爱情如________之坚强，嫉恨如________之残忍。", "a": "死|阴间", "ref": "《雅歌》8章6节", "s": "", "o": "雅歌8章6节"}, {"type": "verse", "q": "【经文填空】爱情，________不能熄灭，大水也不能________。", "a": "众水|淹没", "ref": "《雅歌》8章7节", "s": "", "o": "雅歌8章7节"}, {"type": "verse", "q": "【经文填空】我的佳偶，你全然美丽，毫无________。", "a": "瑕疵", "ref": "《雅歌》4章7节", "s": "", "o": "雅歌4章7节"}, {"type": "fill", "q": "雅歌的作者是________王。", "a": "所罗门", "s": ""}, {"type": "fill", "q": "雅歌共________章。", "a": "八", "s": ""}, {"type": "fill", "q": "雅歌中的新妇名叫________女子。", "a": "书拉密", "s": ""}, {"type": "fill", "q": "“我是沙仑的________，是谷中的玫瑰花。”", "a": "百合花", "s": ""}, {"type": "fill", "q": "新郎称赞新妇“你的眼好像________”。", "a": "鸽子", "s": ""}, {"type": "fill", "q": "“不要惊动，不要叫醒我所亲爱的，等他________。”", "a": "自己情愿", "s": ""}, {"type": "fill", "q": "新妇夜间寻找良人，遇见________的人被打伤。", "a": "看守城", "s": ""}, {"type": "fill", "q": "“我妹子，我新妇，乃是________关锁的园。”", "a": "关锁", "s": ""}, {"type": "fill", "q": "雅歌预表________爱教会。", "a": "基督", "s": ""}, {"type": "fill", "q": "“你的两腮因________而秀美。”", "a": "发辫", "s": ""}, {"type": "single", "q": "“雅歌”的希伯来文原意是：", "o": ["歌中的雅歌", "爱情之歌", "所罗门的歌", "最美的歌"], "a": "歌中的雅歌", "s": ""}, {"type": "single", "q": "雅歌主要预表：", "o": ["基督爱教会", "神爱以色列", "两者都是", "只是爱情诗"], "a": "两者都是", "s": ""}, {"type": "single", "q": "“以爱为旗在我以上”出自：", "o": ["歌2:4", "歌8:6", "歌1:2", "歌4:1"], "a": "歌2:4", "s": ""}, {"type": "single", "q": "书拉密女是雅歌中的：", "o": ["新妇", "耶路撒冷众女子", "王后", "使女"], "a": "新妇", "s": ""}, {"type": "single", "q": "“众水不能熄灭爱情”出自：", "o": ["第8章", "第2章", "第4章", "第6章"], "a": "第8章", "s": ""}, {"type": "single", "q": "新约中阐明基督爱教会的是：", "o": ["弗5章", "林前13章", "约3:16", "罗8章"], "a": "弗5章", "s": ""}, {"type": "single", "q": "雅歌在圣经正典中的位置属于：", "o": ["诗歌智慧书", "大先知书", "历史书", "摩西五经"], "a": "诗歌智慧书", "s": ""}, {"type": "multiple", "q": "雅歌中的主要人物有：", "o": ["良人（所罗门）", "书拉密女", "耶路撒冷众女子", "法老"], "a": "良人（所罗门）,书拉密女,耶路撒冷众女子", "s": ""}, {"type": "multiple", "q": "雅歌对爱情的描述包括：", "o": ["爱情如死之坚强", "众水不能熄灭", "以爱为旗在我以上", "爱情可以用钱财换取"], "a": "爱情如死之坚强,众水不能熄灭,以爱为旗在我以上", "s": ""}, {"type": "multiple", "q": "雅歌预表基督与教会的关系体现在：", "o": ["良人深爱新妇", "新妇全然美丽无瑕疵", "基督为教会舍己（弗5章）", "所罗门广纳妃嫔"], "a": "良人深爱新妇,新妇全然美丽无瑕疵,基督为教会舍己（弗5章）", "s": ""}, {"type": "multiple", "q": "雅歌中的自然意象有：", "o": ["百合花", "鸽子", "葡萄园", "利巴嫩"], "a": "百合花,鸽子,葡萄园,利巴嫩", "s": ""}, {"type": "judge", "q": "雅歌只是描写男女爱情，与信仰无关。", "a": "错", "s": ""}, {"type": "judge", "q": "雅歌的作者是所罗门。", "a": "对", "s": ""}, {"type": "judge", "q": "雅歌共八章。", "a": "对", "s": ""}, {"type": "judge", "q": "教会传统认为雅歌预表基督爱教会。", "a": "对", "s": ""}, {"type": "judge", "q": "“书拉密女”是雅歌中的新郎。", "a": "错", "s": ""}, {"type": "judge", "q": "雅歌中从未直接提到神的名字。", "a": "对", "s": ""}, {"type": "judge", "q": "犹太拉比称雅歌为圣中之圣。", "a": "对", "s": ""}, {"type": "essay", "q": "为什么说雅歌预表基督爱教会？请从新约举例。", "a": "良人对新妇专一、舍己、珍视的爱，预表基督对教会的爱。以弗所书5章明说“基督爱教会，为教会舍己”；启示录称教会为羔羊的新妇。新妇“全然美丽无瑕疵”指向基督使教会成圣的工作。", "s": ""}, {"type": "essay", "q": "歌8:6-7“爱情如死之坚强，众水不能熄灭”如何帮助我们理解神的爱？", "a": "神的爱坚强胜过死亡，恒久不因环境改变；“众水不能熄灭”显明爱的永恒与能力。这正是十字架之爱的写照：基督的爱不被苦难、逼迫、死亡熄灭，今日仍激励信徒。", "s": ""}, {"type": "essay", "q": "雅歌把婚姻之爱分别为圣，对今日信徒的婚恋观有何提醒？", "a": "爱情是神所赐的美好礼物，应当圣洁、专一、委身；“不要惊动爱情”提醒按神的时间等候；婚姻预表基督与教会，当以舍己的爱彼此相待，而非自我满足。", "s": ""}]','','study','[{"title": "爱情的相遇（1-2章）", "points": ["所罗门的歌，是歌中的雅歌", "愿他用口与我亲嘴", "你的爱情比酒更美", "我是沙仑的玫瑰花，谷中的百合花", "他带我入筵宴所，以爱为旗", "良人属我，我也属他", "不要惊动爱情，等他自愿"]}, {"title": "良人的俊美（3-4章）", "points": ["新妇夜间寻找良人", "守城的人遇见新妇", "我的佳偶，你全然美丽", "你的眼好像鸽子眼", "你的头发如山羊群", "你的牙齿如新剪毛的母羊", "毫无瑕疵的赞美"]}, {"title": "寻求与相属（5-6章）", "points": ["我身睡卧，我心却醒", "良人叩门，新妇开门", "看守的人打伤新妇", "耶路撒冷众女子作见证", "我的良人白而且红，超乎万人", "我属我的良人，良人也属我", "他在百合花中牧放群羊"]}, {"title": "爱情的坚强（7-8章）", "points": ["王女啊，你的脚何等佳美", "我妹子，我新妇，关锁的园", "爱情如死之坚强", "嫉恨如阴间之残忍", "众水不能熄灭爱情", "人若倾家所有换爱情，就全被藐视", "小妹的成长与预备"]}, {"title": "预表基督爱教会", "points": ["良人预表基督，新妇预表教会", "弗5章：基督爱教会，为教会舍己", "全然美丽无瑕疵：教会的圣洁", "以爱为旗：基督爱的彰显", "爱情如死坚强：十字架的爱", "众水不能熄灭：爱永不止息", "圣洁婚姻是福音的见证"]}]','','53','旧约•诗歌智慧书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224360566','圣经导览','以赛亚书','以赛亚书被称为「第五福音书」，弥赛亚预言最为丰富：以马内利降生、受苦的仆人、荣耀的新天新地。从神的圣洁、列国的审判到末后的救恩，全书显明耶和华是独一的救主，呼召万民悔改归向祂。','[{"a": "圣哉|圣哉|圣哉|荣光", "q": "________！________！________！万军之耶和华，他的________充满全地！", "ref": "《以赛亚书》6章3节", "s": "", "type": "verse", "o": "以赛亚书6章3节"}, {"a": "兆头|童女|以马内利", "q": "因此，主自己要给你们一个________，必有________怀孕生子，给他起名叫________。", "ref": "《以赛亚书》7章14节", "s": "", "type": "verse", "o": "以赛亚书7章14节"}, {"a": "婴孩|子|政权", "q": "因有一________为我们而生，有一________赐给我们，________必担在他的肩头上。", "ref": "《以赛亚书》9章6节", "s": "", "type": "verse", "o": "以赛亚书9章6节"}, {"a": "等候|鹰", "q": "但那________耶和华的，必从新得力，他们必如________展翅上腾。", "ref": "《以赛亚书》40章31节", "s": "", "type": "verse", "o": "以赛亚书40章31节"}, {"a": "过犯|罪孽", "q": "哪知他为我们的________受害，为我们的________压伤。", "ref": "《以赛亚书》53章5节", "s": "", "type": "verse", "o": "以赛亚书53章5节"}, {"a": "羊|己路|他", "q": "我们都如________走迷，各人偏行________，耶和华使我们众人的罪孽都归在________身上。", "ref": "《以赛亚书》53章6节", "s": "", "type": "verse", "o": "以赛亚书53章6节"}, {"a": "意念|道路", "q": "耶和华说：我的________非同你们的意念，我的________非同你们的道路。", "ref": "《以赛亚书》55章8节", "s": "", "type": "verse", "o": "以赛亚书55章8节"}, {"a": "乌西雅", "q": "以赛亚在________王崩的那年蒙召作先知。", "s": "", "type": "fill"}, {"a": "红炭", "q": "撒拉弗用________沾以赛亚的口，除掉他的罪孽。", "s": "", "type": "fill"}, {"a": "我在这里", "q": "以赛亚回应神的呼召说：「________，请差遣我！」", "s": "", "type": "fill"}, {"a": "神与我们同在", "q": "以马内利的意思是________。", "s": "", "type": "fill"}, {"a": "希西家", "q": "________王病得医治，神使日影后退十度为记号。", "s": "", "type": "fill"}, {"a": "古列", "q": "神预言________王将下令重建耶路撒冷，称他为我的牧人。", "s": "", "type": "fill"}, {"a": "巴比伦", "q": "「明亮之星，早晨之子」坠落的预言指向________王。", "s": "", "type": "fill"}, {"a": "十八万五千", "q": "亚述王西拿基立围困耶路撒冷，一夜被杀________人。", "s": "", "type": "fill"}, {"a": "六十六", "q": "以赛亚书共有________章，是先知书中最长的一卷。", "s": "", "type": "fill"}, {"a": "六十一", "q": "耶稣在拿撒勒会堂读了以赛亚书第________章「主的灵在我身上」。", "s": "", "type": "fill"}, {"a": "主坐在高高的宝座上", "o": ["主坐在高高的宝座上", "约柜", "铜蛇", "吗哪"], "q": "以赛亚蒙召时看见什么？", "s": "", "type": "single"}, {"a": "亚哈斯", "o": ["亚哈斯", "希西家", "玛拿西", "约西亚"], "q": "「以马内利」的预言是对哪位王说的？", "s": "", "type": "single"}, {"a": "十五年", "o": ["十五年", "十年", "二十年", "五年"], "q": "希西家病得医治后，神加给他多少年寿命？", "s": "", "type": "single"}, {"a": "古列", "o": ["古列", "尼布甲尼撒", "大流士", "亚达薛西"], "q": "预言将准许重建圣殿的外邦君王是谁？", "s": "", "type": "single"}, {"a": "受苦的仆人", "o": ["受苦的仆人", "大卫", "所罗门", "希西家"], "q": "以赛亚书53章描述的是谁？", "s": "", "type": "single"}, {"a": "巴比伦", "o": ["巴比伦", "埃及", "亚述", "摩押"], "q": "「明亮之星，早晨之子」坠落指向哪国？", "s": "", "type": "single"}, {"a": "掳掠速临，抢夺快到", "o": ["掳掠速临，抢夺快到", "神与我们同在", "余民将归回", "耶和华是拯救"], "q": "以赛亚儿子的名字「玛黑珥沙拉勒哈施罢斯」意思是？", "s": "", "type": "single"}, {"a": "以马内利,受苦的仆人,政权担在肩头上,新天新地", "o": ["以马内利", "受苦的仆人", "政权担在肩头上", "新天新地"], "q": "以下哪些是以赛亚书中的弥赛亚预言？", "s": "", "type": "multiple"}, {"a": "日影后退十度,亚述大军一夜被灭,病得医治延寿十五年", "o": ["日影后退十度", "亚述大军一夜被灭", "病得医治延寿十五年", "约旦河分开"], "q": "希西家在位时发生过哪些神迹？", "s": "", "type": "multiple"}, {"a": "巴比伦,摩押,推罗,亚述", "o": ["巴比伦", "摩押", "推罗", "亚述"], "q": "以赛亚预言受审判的列国包括？", "s": "", "type": "multiple"}, {"a": "争战已满期,罪孽已赦免,如鹰展翅上腾,旷野中有声音", "o": ["争战已满期", "罪孽已赦免", "如鹰展翅上腾", "旷野中有声音"], "q": "以赛亚书40章安慰的信息包括？", "s": "", "type": "multiple"}, {"a": "对", "q": "以赛亚是南国犹大的先知。", "s": "", "type": "judge"}, {"a": "对", "q": "以赛亚预言必有童女怀孕生子。", "s": "", "type": "judge"}, {"a": "错", "q": "希西家向巴比伦使者展示府库蒙神称赞。", "s": "", "type": "judge"}, {"a": "对", "q": "以赛亚书53章预言弥赛亚为人的罪受苦。", "s": "", "type": "judge"}, {"a": "错", "q": "古列是犹大国的王。", "s": "", "type": "judge"}, {"a": "对", "q": "「圣哉三颂」出现在以赛亚蒙召的异象中。", "s": "", "type": "judge"}, {"a": "对", "q": "以赛亚书以新天新地的异象作结。", "s": "", "type": "judge"}, {"a": "他被藐视、受痛苦，为我们的过犯受害、为罪孽压伤，如羊被牵到宰杀之地不开口，与财主同葬。新约多处引用此章，腓利向埃提阿伯太监传讲的正是这段经文，耶稣在十字架上完全成就了这预言。", "q": "以赛亚书53章如何描述受苦的仆人？这与耶稣基督有何关系？", "s": "", "type": "essay"}, {"a": "先看见神的圣洁，才认识自己的污秽；罪得洁净后才能回应呼召。「我在这里，请差遣我」是每个蒙恩者的回应。事奉的起点不是能力，而是被神洁净、被神差遣。", "q": "以赛亚蒙召的经历对今天的信徒有何启发？", "s": "", "type": "essay"}, {"a": "审判显明神的公义圣洁，救恩显明神的慈爱信实。审判为要炼净余民，救恩临到悔改的人。两者都指向弥赛亚的到来：祂担当审判，成就救恩。", "q": "从以赛亚书看，神的审判与救恩有何关系？", "s": "", "type": "essay"}]','','study','[{"points": ["乌西雅王崩的那年，以赛亚见主坐在高高的宝座上", "撒拉弗三呼圣哉：圣哉！圣哉！圣哉！", "自认嘴唇不洁，红炭沾口罪孽除掉", "「我在这里，请差遣我」的回应", "以马内利的预言（7:14）", "政权必担在他的肩头上（9:6）"], "title": "先知的蒙召（1-12章）"}, {"points": ["巴比伦倾倒的预言", "摩押、亚述、推罗都要受审判", "明亮之星早晨之子坠落（14:12）", "大灾难中神仍存留余民", "他已经吞灭死亡直到永远（25:8）", "坚心倚赖你的，你必保守他十分平安（26:3）"], "title": "列国的审判（13-27章）"}, {"points": ["亚述围困耶路撒冷，希西家进殿祷告", "一夜之间十八万五千亚述军被杀", "希西家病得医治，寿命延长十五年", "日影后退十度为记号", "希西家向巴比伦使者炫耀府库", "预言犹大将被掳到巴比伦"], "title": "锡安的拯救（28-39章）"}, {"points": ["你们的神说：你们要安慰，安慰我的百姓", "等候耶和华的必如鹰展翅上腾（40:31）", "古列被膏立，称为神的牧人（44-45章）", "仆人之歌：受苦的仆人", "他为我们的过犯受害（53:5）", "我们都如羊走迷（53:6）", "你们都来买，白白得救恩（55:1）"], "title": "安慰与受苦的仆人（40-55章）"}, {"points": ["真禁食的意义：松开凶恶的绳（58章）", "耶和华的膀臂并非缩短（59:1）", "兴起发光，因为你的光已经来到（60:1）", "主的灵在我身上，传好信息给谦卑的人（61:1）", "新天新地（65-66章）", "万民归向耶路撒冷敬拜"], "title": "新天新地（56-66章）"}]','','54','旧约•大先知书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224361566','圣经导览','耶利米书','耶利米被称为「流泪的先知」，在犹大亡国前的四十年间不断呼喊悔改。从窑匠的泥、折断的轭到新约的应许，他亲身经历逼迫仍忠心传讲，显明神在审判中仍存留怜悯，为余民存留复兴的盼望。','[{"a": "腹|晓得|母胎", "q": "我未将你造在________中，我已________你；你未出________，我已分别你为圣。", "ref": "《耶利米书》1章5节", "s": "", "type": "verse", "o": "耶利米书1章5节"}, {"a": "平安|灾祸|指望", "q": "耶和华说：我知道我向你们所怀的意念，是赐________的意念，不是降________的意念，要叫你们末后有________。", "ref": "《耶利米书》29章11节", "s": "", "type": "verse", "o": "耶利米书29章11节"}, {"a": "永远|慈爱", "q": "我以________的爱爱你，因此我以________吸引你。", "ref": "《耶利米书》31章3节", "s": "", "type": "verse", "o": "耶利米书31章3节"}, {"a": "以色列|犹大|新约", "q": "耶和华说：日子将到，我要与________家和________家另立________。", "ref": "《耶利米书》31章31节", "s": "", "type": "verse", "o": "耶利米书31章31节"}, {"a": "求告|应允|难", "q": "你________我，我就________你，并将你所不知道、又大又________的事指示你。", "ref": "《耶利米书》33章3节", "s": "", "type": "verse", "o": "耶利米书33章3节"}, {"a": "活水|破裂", "q": "我的百姓做了两件恶事，就是离弃我这________的泉源，为自己凿出池子，是________不能存水的池子。", "ref": "《耶利米书》2章13节", "s": "", "type": "verse", "o": "耶利米书2章13节"}, {"a": "诡诈|极处", "q": "人心比万物都________，坏到________，谁能识透呢？", "ref": "《耶利米书》17章9节", "s": "", "type": "verse", "o": "耶利米书17章9节"}, {"a": "约西亚", "q": "耶利米在犹大王________十三年蒙召作先知。", "s": "", "type": "fill"}, {"a": "杏树枝", "q": "神给耶利米看________的异象，表明神留意保守自己的话。", "s": "", "type": "fill"}, {"a": "窑匠", "q": "耶利米下到________家里，看他用泥造器皿。", "s": "", "type": "fill"}, {"a": "哈拿尼雅", "q": "假先知________折断耶利米颈项上的木轭。", "s": "", "type": "fill"}, {"a": "七十", "q": "耶利米预言犹大被掳到巴比伦________年。", "s": "", "type": "fill"}, {"a": "亚拿突", "q": "耶利米买________的一块地，作为日后归回的凭据。", "s": "", "type": "fill"}, {"a": "以伯米勒", "q": "古实人________将耶利米从枯井中救出来。", "s": "", "type": "fill"}, {"a": "巴录", "q": "文士________将耶利米的预言记录成书。", "s": "", "type": "fill"}, {"a": "尼布甲尼撒", "q": "西底家王不听劝告，耶路撒冷被________王攻破。", "s": "", "type": "fill"}, {"a": "流泪", "q": "耶利米被称为「________的先知」。", "s": "", "type": "fill"}, {"a": "约西亚", "o": ["约西亚", "西底家", "约雅敬", "玛拿西"], "q": "耶利米在哪位犹大王年间蒙召？", "s": "", "type": "single"}, {"a": "窑匠的泥", "o": ["窑匠的泥", "杏树枝", "烧开的锅", "无花果"], "q": "神用哪个异象表明祂有权柄塑造列国？", "s": "", "type": "single"}, {"a": "七十年", "o": ["七十年", "四十年", "五十年", "七年"], "q": "耶利米预言犹大被掳巴比伦多少年？", "s": "", "type": "single"}, {"a": "王子们", "o": ["王子们", "祭司", "假先知", "巴比伦人"], "q": "谁把耶利米下在枯井里？", "s": "", "type": "single"}, {"a": "31章", "o": ["31章", "33章", "29章", "25章"], "q": "「另立新约」的应许记载在耶利米书哪一章？", "s": "", "type": "single"}, {"a": "日后必归回的凭据", "o": ["日后必归回的凭据", "商业投资", "养老之用", "送给亲属"], "q": "耶利米买亚拿突地的意义是什么？", "s": "", "type": "single"}, {"a": "埃及", "o": ["埃及", "摩押", "亚述", "以东"], "q": "余民不听耶利米的话，逃往哪里？", "s": "", "type": "single"}, {"a": "被掳七十年,另立新约,拉结哭她的儿女,巴比伦倾倒", "o": ["被掳七十年", "另立新约", "拉结哭她的儿女", "巴比伦倾倒"], "q": "以下哪些是耶利米书中的重要预言？", "s": "", "type": "multiple"}, {"a": "被下监狱,被下枯井,在圣殿被捉拿", "o": ["被下监狱", "被下枯井", "在圣殿被捉拿", "被刀杀害"], "q": "耶利米遭受的逼迫包括？", "s": "", "type": "multiple"}, {"a": "离弃活水的泉源,为自己凿破裂的池子", "o": ["离弃活水的泉源", "为自己凿破裂的池子", "拜偶像", "不守安息日"], "q": "「两件恶事」指什么？", "s": "", "type": "multiple"}, {"a": "投降巴比伦就可以存活", "o": ["投降巴比伦就可以存活", "坚守耶路撒冷到底", "逃往埃及避难", "与埃及结盟抗巴比伦"], "q": "耶利米给西底家王的劝告是？", "s": "", "type": "multiple"}, {"a": "对", "q": "耶利米自称年幼，神说不要说年幼。", "s": "", "type": "judge"}, {"a": "错", "q": "哈拿尼雅是神所差遣的真先知。", "s": "", "type": "judge"}, {"a": "对", "q": "耶利米预言被掳七十年满后必归回。", "s": "", "type": "judge"}, {"a": "错", "q": "西底家听从耶利米投降了巴比伦。", "s": "", "type": "judge"}, {"a": "对", "q": "古实人以伯米勒救耶利米出枯井。", "s": "", "type": "judge"}, {"a": "对", "q": "新约是神与以色列家和犹大家另立的约。", "s": "", "type": "judge"}, {"a": "对", "q": "耶利米书最后记载巴比伦王善待被掳的约雅斤。", "s": "", "type": "judge"}, {"a": "神将律法放在人里面、写在心上，人人认识耶和华，神赦免他们的罪孽。旧约是外在石版、靠人遵行；新约是内在更新、靠神在人心里动工。希伯来书8章引用此预言，耶稣的宝血立了新约。", "q": "「新约」的内容是什么？与旧约有何不同？", "s": "", "type": "essay"}, {"a": "神是窑匠，我们是泥土；神有权柄塑造列国，也有权柄拆毁重建。以色列虽悖逆，神仍能重新塑造。人在神手中当存顺服的心，让神按祂的美意陶造。", "q": "「窑匠的泥」给我们什么启示？", "s": "", "type": "essay"}, {"a": "明知人不听仍忠心传讲四十年；为百姓的罪忧伤流泪；个人受逼迫不改信息；审判的信息中仍传递复兴的盼望。忠心比果效更重要。", "q": "耶利米被称为「流泪的先知」，对今天的传道人有何榜样？", "s": "", "type": "essay"}]','','study','[{"points": ["约西亚十三年蒙召作先知", "我未将你造在腹中，我已晓得你", "自称年幼，神说不要说年幼", "杏树枝的异象：神留意保守自己的话", "烧开的锅：灾祸从北方临到", "被立管理列国列邦，拆毁与建立"], "title": "先知的蒙召（1章）"}, {"points": ["离弃活水的泉源，为自己凿破裂的池子", "窑匠的泥：神有权柄塑造列国", "摔碎瓦瓶的预言", "预言犹大被掳巴比伦七十年", "假先知哈拿尼雅折断木轭，当年死亡", "人心比万物都诡诈（17:9）"], "title": "呼喊悔改（2-25章）"}, {"points": ["在圣殿门口传讲被捉拿", "被下在监狱、枯井之中", "古实人以伯米勒救耶利米出井", "劝告西底家：投降巴比伦就可以存活", "买亚拿突的地：复兴的凭据", "文士巴录记录预言成书"], "title": "逼迫与坚忍（26-38章）"}, {"points": ["尼布甲尼撒攻破耶路撒冷", "西底家被剜眼掳到巴比伦", "基大利被立为省长后被杀", "余民不听劝告逃往埃及", "耶利米被迫同往埃及", "在埃及仍预言神的审判"], "title": "耶路撒冷倾覆（39-45章）"}, {"points": ["新约的应许：律法写在心上（31:31-34）", "我以永远的爱爱你（31:3）", "拉结哭她的儿女（31:15）", "你求告我，我就应允你（33:3）", "审判埃及、摩押、巴比伦列国", "约雅斤在巴比伦蒙恩优待"], "title": "列国与新约（30-33章，46-52章）"}]','','55','旧约•大先知书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224362566','圣经导览','耶利米哀歌','耶利米哀歌是先知为耶路撒冷倾覆所作的挽歌，五首哀歌诉说圣城的荒凉与百姓的苦难。然而在绝望深处仍有亮光：「每早晨这都是新的」，神的慈爱与诚实永不断绝，诚心悔改祷告必带来复兴。','[{"a": "慈爱|怜悯|新|诚实", "q": "我们不至消灭，是出于耶和华诸般的________，是因他的________不致断绝。每早晨这都是________的，你的________极其广大！", "ref": "《耶利米哀歌》3章22-23节", "s": "", "type": "verse", "o": "耶利米哀歌3章22节"}, {"a": "等候|寻求", "q": "凡________耶和华，心里________他的，耶和华必施恩给他。", "ref": "《耶利米哀歌》3章25节", "s": "", "type": "verse", "o": "耶利米哀歌3章25节"}, {"a": "静默|救恩", "q": "人仰望耶和华，________等候他的________，这原是好的。", "ref": "《耶利米哀歌》3章26节", "s": "", "type": "verse", "o": "耶利米哀歌3章26节"}, {"a": "独坐|寡妇", "q": "先前满有人民的城，现在何竟________！先前在列国中为大的，现在竟如________。", "ref": "《耶利米哀歌》1章1节", "s": "", "type": "verse", "o": "耶利米哀歌1章1节"}, {"a": "回转|复新", "q": "耶和华啊，求你使我们向你________，我们便得回转；求你________我们的日子，像古时一样。", "ref": "《耶利米哀歌》5章21节", "s": "", "type": "verse", "o": "耶利米哀歌5章21节"}, {"a": "甘心|忧愁", "q": "他并不________使人受苦，使人________。", "ref": "《耶利米哀歌》3章33节", "s": "", "type": "verse", "o": "耶利米哀歌3章33节"}, {"a": "考察|归向", "q": "我们当深深________自己的行为，再________耶和华。", "ref": "《耶利米哀歌》3章40节", "s": "", "type": "verse", "o": "耶利米哀歌3章40节"}, {"a": "五", "q": "耶利米哀歌共有________首哀歌。", "s": "", "type": "fill"}, {"a": "希伯来", "q": "哀歌前四首按________字母顺序写成。", "s": "", "type": "fill"}, {"a": "三", "q": "「每早晨这都是新的」出自哀歌第________章。", "s": "", "type": "fill"}, {"a": "忿怒", "q": "先知形容自己是「因耶和华________的杖遭遇困苦的人」。", "s": "", "type": "fill"}, {"a": "寡妇", "q": "锡安被称为________，因丈夫离弃了她。", "s": "", "type": "fill"}, {"a": "冠冕", "q": "哀歌中说「我们的________坠落了」。", "s": "", "type": "fill"}, {"a": "回转", "q": "先知祷告说：「求你使我们________，我们便得回转」。", "s": "", "type": "fill"}, {"a": "尼布甲尼撒", "q": "耶路撒冷被________王攻破后，先知作此哀歌。", "s": "", "type": "fill"}, {"a": "瓦器", "q": "哀歌4章说锡安宝贵的儿女被看为________。", "s": "", "type": "fill"}, {"a": "祷告", "q": "哀歌的最后一章是向神的________。", "s": "", "type": "fill"}, {"a": "耶路撒冷", "o": ["耶路撒冷", "撒玛利亚", "巴比伦", "大马士革"], "q": "耶利米哀歌为哪座城作哀歌？", "s": "", "type": "single"}, {"a": "第三章", "o": ["第三章", "第一章", "第五章", "第二章"], "q": "「每早晨这都是新的」在哀歌第几章？", "s": "", "type": "single"}, {"a": "五首", "o": ["五首", "三首", "七首", "四首"], "q": "耶利米哀歌共有几首？", "s": "", "type": "single"}, {"a": "寡妇", "o": ["寡妇", "处女", "新妇", "母亲"], "q": "荒凉的锡安被比作什么？", "s": "", "type": "single"}, {"a": "诚实", "o": ["诚实", "慈爱", "能力", "智慧"], "q": "先知说神的什么「极其广大」？", "s": "", "type": "single"}, {"a": "字母离合诗", "o": ["字母离合诗", "对偶排比", "用典", "问答体"], "q": "哀歌前四章的写作形式有何特点？", "s": "", "type": "single"}, {"a": "祷告", "o": ["祷告", "预言", "历史", "家谱"], "q": "哀歌第五章的性质是？", "s": "", "type": "single"}, {"a": "城门荒凉,祭司叹息,处女悲伤,仇敌作头", "o": ["城门荒凉", "祭司叹息", "处女悲伤", "仇敌作头"], "q": "哀歌中描述的耶路撒冷光景包括？", "s": "", "type": "multiple"}, {"a": "慈爱怜悯不至断绝,每早晨都是新的,等候的必蒙恩,静默等候救恩", "o": ["慈爱怜悯不至断绝", "每早晨都是新的", "等候的必蒙恩", "静默等候救恩"], "q": "第三章中的盼望包括？", "s": "", "type": "multiple"}, {"a": "祭司的罪,先知的罪,我们的罪", "o": ["祭司的罪", "先知的罪", "我们的罪", "列国的罪"], "q": "先知承认的罪包括？", "s": "", "type": "multiple"}, {"a": "审判,哀哭,悔改,盼望", "o": ["审判", "哀哭", "悔改", "盼望"], "q": "耶利米哀歌的主题包括？", "s": "", "type": "multiple"}, {"a": "对", "q": "耶利米哀歌共有五章。", "s": "", "type": "judge"}, {"a": "错", "q": "「每早晨这都是新的」出自哀歌第一章。", "s": "", "type": "judge"}, {"a": "对", "q": "哀歌为耶路撒冷的倾覆哀哭。", "s": "", "type": "judge"}, {"a": "错", "q": "哀歌中没有任何盼望的信息。", "s": "", "type": "judge"}, {"a": "对", "q": "荒凉的锡安被称为寡妇。", "s": "", "type": "judge"}, {"a": "对", "q": "哀歌第五章是先知向神的祷告。", "s": "", "type": "judge"}, {"a": "错", "q": "耶利米哀歌的作者是但以理。", "s": "", "type": "judge"}, {"a": "神的慈爱怜悯永不枯竭，每天早晨都是新的恩典。无论昨夜多么黑暗，早晨必有亮光。诚实的神信实到底，祂的应许永不落空。", "q": "「每早晨这都是新的」给你什么安慰？", "s": "", "type": "essay"}, {"a": "承认神的审判公义严厉；深知神并不甘心使人受苦；抓住神的慈爱与诚实永不断绝；以祷告考察自己、回转归向神，仰望复兴。", "q": "哀歌如何在审判中仍持守盼望？", "s": "", "type": "essay"}, {"a": "罪必带来审判，神的话绝不落空；离弃神的结局是荒凉；先知早已警告，人却不听。今天我们当趁还有机会回转归向神。", "q": "从耶路撒冷倾覆我们学到什么教训？", "s": "", "type": "essay"}]','','study','[{"points": ["先前满有人民的城，如今何竟独坐", "在列国中为大的，如今竟如寡妇", "仇敌夸胜，朋友变为仇敌", "节期无人赴会，祭司叹息", "先知为圣城昼夜哭泣"], "title": "圣城的荒凉（1章）"}, {"points": ["神发怒拆毁锡安的保障", "祭司先知在圣所被杀", "城墙为百姓哀哭", "神的审判公义而严厉", "要为罪忧伤，向神举手祷告"], "title": "神的审判（2章）"}, {"points": ["我是因耶和华忿怒的杖遭遇困苦的人", "他使我的皮肉枯干，折断我的骨头", "每早晨这都是新的（3:23）", "你的诚实极其广大", "凡等候耶和华的必蒙恩", "人当静默等候神的救恩"], "title": "绝望中的盼望（3章）"}, {"points": ["圣所的石头倒在各市口上", "锡安宝贵的儿女被看为瓦器", "祭司先知的罪带来审判", "君王被掳，荣耀失去", "求神记念我们的羞辱"], "title": "锡安的羞辱（4章）"}, {"points": ["求神记念我们的羞辱，观看我们的凌辱", "产业归与外邦人，房屋归与外路人", "我们的冠冕坠落了", "求你使我们回转，我们便得回转", "求你复新我们的日子，像古时一样"], "title": "祷告与复兴（5章）"}]','','56','旧约•大先知书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224363566','圣经导览','以西结书','以西结在被掳之地的迦巴鲁河边蒙召，异象奇特：四活物、枯骨复活、新圣殿。从审判的信息到复兴的应许，神应许赐下新心新灵，显明祂是那位使枯骨复活、重建以色列全家的耶和华真神阿们。','[{"a": "新心|新灵|石心", "q": "我也要赐给你们一个________，将________放在你们里面，又从你们的肉体中除掉________，赐给你们肉心。", "ref": "《以西结书》36章26节", "s": "", "type": "verse", "o": "以西结书36章26节"}, {"a": "气息|活|军队", "q": "于是我遵命说预言，________就进入骸骨，骸骨便________了，并且站起来，成为极大的________。", "ref": "《以西结书》37章10节", "s": "", "type": "verse", "o": "以西结书37章10节"}, {"a": "守望|警戒", "q": "人子啊，我立你作以色列家________的人，所以你要听我口中的话，替我________他们。", "ref": "《以西结书》3章17节", "s": "", "type": "verse", "o": "以西结书3章17节"}, {"a": "河水|生活", "q": "这________所到之处，凡滋生的动物都必________，并且因这流来的水必有极多的鱼。", "ref": "《以西结书》47章9节", "s": "", "type": "verse", "o": "以西结书47章9节"}, {"a": "荣耀|俯伏", "q": "这就是耶和华________的形像。我一看见就________在地，又听见一位说话的声音。", "ref": "《以西结书》1章28节", "s": "", "type": "verse", "o": "以西结书1章28节"}, {"a": "喜悦|回头", "q": "主耶和华说：我不________那死人之死，所以你们当________而存活。", "ref": "《以西结书》18章32节", "s": "", "type": "verse", "o": "以西结书18章32节"}, {"a": "失丧|领回", "q": "________的，我必寻找；被逐的，我必________；受伤的，我必缠裹。", "ref": "《以西结书》34章16节", "s": "", "type": "verse", "o": "以西结书34章16节"}, {"a": "迦巴鲁", "q": "以西结在________河边看见异象蒙召。", "s": "", "type": "fill"}, {"a": "书卷", "q": "以西结吃了________，口中觉得甘甜如蜜。", "s": "", "type": "fill"}, {"a": "守望者", "q": "神立以西结作以色列家的________。", "s": "", "type": "fill"}, {"a": "左", "q": "以西结向________侧卧三百九十日，担当以色列家的罪孽。", "s": "", "type": "fill"}, {"a": "三十七", "q": "枯骨复活的异象记载在以西结书第________章。", "s": "", "type": "fill"}, {"a": "新心|新灵", "q": "神应许赐下________与________，代替石心。", "s": "", "type": "fill"}, {"a": "圣殿", "q": "以西结的妻子忽然死亡，成为________被毁的预兆。", "s": "", "type": "fill"}, {"a": "死海", "q": "圣殿流出的水使________得医治。", "s": "", "type": "fill"}, {"a": "耶和华的所在", "q": "异象中新城的名字叫「________」。", "s": "", "type": "fill"}, {"a": "祭司", "q": "以西结出身于________家族。", "s": "", "type": "fill"}, {"a": "迦巴鲁河边", "o": ["迦巴鲁河边", "约旦河边", "尼罗河边", "幼发拉底河边"], "q": "以西结在哪里蒙召见异象？", "s": "", "type": "single"}, {"a": "守望者", "o": ["守望者", "君王", "祭司", "文士"], "q": "神立以西结作以色列家的什么？", "s": "", "type": "single"}, {"a": "37章", "o": ["37章", "36章", "38章", "40章"], "q": "枯骨复活的异象在第几章？", "s": "", "type": "single"}, {"a": "新心新灵", "o": ["新心新灵", "金银财宝", "长寿", "土地"], "q": "神应许赐给百姓什么代替石心？", "s": "", "type": "single"}, {"a": "书卷", "o": ["书卷", "吗哪", "无花果", "饼"], "q": "以西结吃了什么？", "s": "", "type": "single"}, {"a": "死海", "o": ["死海", "加利利海", "地中海", "红海"], "q": "圣殿流出的水最终流向哪里？", "s": "", "type": "single"}, {"a": "祭司", "o": ["祭司", "木匠", "牧人", "渔夫"], "q": "以西结的出身是？", "s": "", "type": "single"}, {"a": "四活物,枯骨复活,新圣殿,圣殿中流出的水", "o": ["四活物", "枯骨复活", "新圣殿", "圣殿中流出的水"], "q": "以西结书中的异象包括？", "s": "", "type": "multiple"}, {"a": "听神口中的话,替神警戒百姓,不警戒则要担罪", "o": ["听神口中的话", "替神警戒百姓", "不警戒则要担罪", "只报喜不报忧"], "q": "守望者的职责包括？", "s": "", "type": "multiple"}, {"a": "推罗,埃及,亚扪,摩押", "o": ["推罗", "埃及", "亚扪", "摩押"], "q": "以西结预言受审判的列国包括？", "s": "", "type": "multiple"}, {"a": "新心新灵,枯骨复活,两杖合而为一,荣光重返圣殿", "o": ["新心新灵", "枯骨复活", "两杖合而为一", "荣光重返圣殿"], "q": "复兴的应许包括？", "s": "", "type": "multiple"}, {"a": "对", "q": "以西结是祭司出身。", "s": "", "type": "judge"}, {"a": "对", "q": "枯骨复活预表以色列家的复兴。", "s": "", "type": "judge"}, {"a": "错", "q": "以西结向右侧卧三百九十日。", "s": "", "type": "judge"}, {"a": "错", "q": "神的荣光离开圣殿后就不再回来。", "s": "", "type": "judge"}, {"a": "对", "q": "圣殿流出的水使死海的水得医治。", "s": "", "type": "judge"}, {"a": "错", "q": "以西结在耶路撒冷蒙召。", "s": "", "type": "judge"}, {"a": "对", "q": "异象中的新城名叫「耶和华的所在」。", "s": "", "type": "judge"}, {"a": "以色列虽如枯骨毫无指望，神的气息一吹便复活成为极大的军队。预表以色列的复兴与属灵的重生，显明神是叫死人复活、使无变有的神。", "q": "枯骨复活的异象说明什么？", "s": "", "type": "essay"}, {"a": "传道人有责任听神的话、警戒罪人；听见而不传，流血的罪归传者；传了人不听，罪归自己。忠心传讲是本分，果效在乎神。", "q": "「守望者」的信息对今天有何提醒？", "s": "", "type": "essay"}, {"a": "预言新约的内在更新：石心变肉心，律法写在心上。五旬节圣灵降临是此应许的应验，重生是圣灵的工作，不是人的努力。", "q": "「新心新灵」的应许与新约有何关系？", "s": "", "type": "essay"}]','','study','[{"points": ["迦巴鲁河边看见天开了", "四活物与轮子的异象", "吃书卷：口中觉得甘甜如蜜", "被立作以色列家的守望者", "不警戒恶人，流血的罪归于你", "言语要像金刚钻，硬过燧石"], "title": "先知的蒙召（1-3章）"}, {"points": ["向左侧卧三百九十日担当罪孽", "剃头须：三分之一的审判", "圣殿中行可憎的事", "耶和华的荣光离开圣殿", "妻子忽然死亡为预兆", "耶路撒冷必被围困攻破"], "title": "审判的信息（4-24章）"}, {"points": ["审判亚扪、摩押、以东、非利士", "推罗的倾倒与哀歌", "埃及法老如大鱼被拖出", "巴比伦为神审判的器皿", "列国就知道我是耶和华"], "title": "列国的审判（25-32章）"}, {"points": ["守望者的职责再次重申", "枯骨复活的异象（37章）", "两根杖合而为一：南北国合一", "新心新灵的应许（36:26）", "歌革和玛各的结局", "我必作他们的神，他们必作我的子民"], "title": "复兴的应许（33-39章）"}, {"points": ["新圣殿的异象与度量", "耶和华的荣光重返圣殿", "圣殿门槛下流出的水", "水流到之处，百物得活", "以色列全地重新分给十二支派", "城名「耶和华的所在」"], "title": "新圣殿异象（40-48章）"}]','','57','旧约•大先知书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224364566','圣经导览','但以理书','但以理在巴比伦宫廷中持守圣洁，为王解梦、在火窑与狮子坑中蒙保守。异象揭示列国的更替与人子永远的国度：「七十个七」的预言精确指向弥赛亚，显明至高者在人的国中掌权作王直到永远。','[{"a": "时候|废王", "q": "他改变________、日期，________，立王，将智慧赐与智慧人，将知识赐与聪明人。", "ref": "《但以理书》2章21节", "s": "", "type": "verse", "o": "但以理书2章21节"}, {"a": "烈火|救", "q": "即便如此，我们所侍奉的神能将我们从________的窑中________出来。", "ref": "《但以理书》3章17节", "s": "", "type": "verse", "o": "但以理书3章17节"}, {"a": "使者|口", "q": "我的神差遣________，封住狮子的________，叫狮子不伤我。", "ref": "《但以理书》6章22节", "s": "", "type": "verse", "o": "但以理书6章22节"}, {"a": "权柄|国", "q": "他的________是永远的，不能废去，他的________必不败坏。", "ref": "《但以理书》7章14节", "s": "", "type": "verse", "o": "但以理书7章14节"}, {"a": "圣城|七十", "q": "为你本国之民和你________，已经定了________个七。", "ref": "《但以理书》9章24节", "s": "", "type": "verse", "o": "但以理书9章24节"}, {"a": "尘埃|永生", "q": "睡在________中的，必有多人复醒，其中有得________的，有受羞辱永远被憎恶的。", "ref": "《但以理书》12章2节", "s": "", "type": "verse", "o": "但以理书12章2节"}, {"a": "至高者|掌权", "q": "好叫世人知道________在人的国中________。", "ref": "《但以理书》4章17节", "s": "", "type": "verse", "o": "但以理书4章17节"}, {"a": "王膳", "q": "但以理立志不用________玷污自己。", "s": "", "type": "fill"}, {"a": "米煞", "q": "但以理的三个朋友是沙得拉、________、亚伯尼歌。", "s": "", "type": "fill"}, {"a": "精金", "q": "尼布甲尼撒梦见的大像，头部是________做的。", "s": "", "type": "fill"}, {"a": "人手", "q": "非________凿出来的一块石头把大像打得粉碎。", "s": "", "type": "fill"}, {"a": "弥尼", "q": "墙上写着「________，弥尼，提客勒，乌法珥新」。", "s": "", "type": "fill"}, {"a": "狮子", "q": "但以理在________坑中过了一夜，神封住狮子的口。", "s": "", "type": "fill"}, {"a": "三", "q": "但以理一日________次面向耶路撒冷祷告。", "s": "", "type": "fill"}, {"a": "九", "q": "「七十个七」的预言记载在但以理书第________章。", "s": "", "type": "fill"}, {"a": "人子", "q": "但以理在异象中看见一位像________的，来到亘古常在者面前。", "s": "", "type": "fill"}, {"a": "七", "q": "尼布甲尼撒如牛吃草，共经过了________年。", "s": "", "type": "fill"}, {"a": "王膳", "o": ["王膳", "素菜", "清水", "饼"], "q": "但以理立志不吃什么？", "s": "", "type": "single"}, {"a": "精金", "o": ["精金", "银", "铜", "铁"], "q": "大像的头部是什么材料？", "s": "", "type": "single"}, {"a": "火窑", "o": ["火窑", "狮子坑", "监狱", "河中"], "q": "但以理的三个朋友被扔进哪里？", "s": "", "type": "single"}, {"a": "伯沙撒", "o": ["伯沙撒", "尼布甲尼撒", "大流士", "古列"], "q": "看见墙上写字的王是谁？", "s": "", "type": "single"}, {"a": "大流士", "o": ["大流士", "尼布甲尼撒", "伯沙撒", "古列"], "q": "但以理在谁年间被扔进狮子坑？", "s": "", "type": "single"}, {"a": "弥赛亚", "o": ["弥赛亚", "被掳之民", "归回之民", "建殿之工"], "q": "「七十个七」的预言最终指向谁？", "s": "", "type": "single"}, {"a": "三次", "o": ["三次", "两次", "一次", "七次"], "q": "但以理一日祷告几次？", "s": "", "type": "single"}, {"a": "金头,银胸,铜腹,铁腿", "o": ["金头", "银胸", "铜腹", "铁腿"], "q": "大像的构成包括？", "s": "", "type": "multiple"}, {"a": "立志持守圣洁,为王解梦,狮子坑中蒙保守,恒切祷告", "o": ["立志持守圣洁", "为王解梦", "狮子坑中蒙保守", "恒切祷告"], "q": "但以理的美好见证包括？", "s": "", "type": "multiple"}, {"a": "被捆扔入火窑,火焰不能伤身,见第四位如神子", "o": ["被捆扔入火窑", "火焰不能伤身", "见第四位如神子", "王因此敬拜真神"], "q": "三友在火窑中的经历包括？", "s": "", "type": "multiple"}, {"a": "列国更替,人子得国,七十个七,死人复活", "o": ["列国更替", "人子得国", "七十个七", "死人复活"], "q": "但以理书的预言包括？", "s": "", "type": "multiple"}, {"a": "错", "q": "但以理吃了王膳所以面貌俊美。", "s": "", "type": "judge"}, {"a": "对", "q": "大像被非人手凿出的石头打得粉碎。", "s": "", "type": "judge"}, {"a": "错", "q": "三个朋友在火窑中被烧伤。", "s": "", "type": "judge"}, {"a": "对", "q": "但以理在狮子坑中一夜平安无事。", "s": "", "type": "judge"}, {"a": "错", "q": "墙上写字发生在尼布甲尼撒年间。", "s": "", "type": "judge"}, {"a": "对", "q": "「七十个七」共计四百九十年。", "s": "", "type": "judge"}, {"a": "对", "q": "但以理书预言人子必得国权、荣耀。", "s": "", "type": "judge"}, {"a": "立志不用王膳玷污自己；坚持一日三次面向耶路撒冷祷告；面对王命不妥协，温柔而坚定；以智慧和见识服侍。神使他在外邦君王面前为真神作见证。", "q": "但以理在异教宫廷中如何持守信仰？", "s": "", "type": "essay"}, {"a": "从出令重建耶路撒冷到受膏君，共六十九个七（483年），精确指向基督；一七之内祂必与多人坚定盟约。显明神掌管历史长河，弥赛亚按时而来，预言从不落空。", "q": "「七十个七」预言的意义是什么？", "s": "", "type": "essay"}, {"a": "但以理因恒切祷告被陷害，仍不停止祷告；神差遣使者封住狮子的口；大流士王亲口见证永活的神；逼迫反使神的名在全国被尊崇。", "q": "从「狮子坑」看神的保守与见证？", "s": "", "type": "essay"}]','','study','[{"points": ["立志不用王膳玷污自己", "只吃素菜喝清水十天试试", "面貌比用王膳的少年更俊美", "神赐四少年知识和聪明", "但以理能明白各样的异象和梦兆", "在尼布甲尼撒面前侍立"], "title": "宫廷中的见证（1章）"}, {"points": ["大像的异象：金头银胸铜腹铁腿泥脚", "非人手凿出的石头打碎大像", "但以理被立为巴比伦总理", "三友不拜金像，被扔火窑蒙保守", "尼布甲尼撒吃草七年如牛", "至高者在人的国中掌权（4:17）"], "title": "尼布甲尼撒的梦（2-4章）"}, {"points": ["墙上写字：弥尼弥尼提客勒乌法珥新", "但以理讲解墙上的文字", "当夜伯沙撒被杀，玛代人大流士得国", "大流士立但以理为全国总长", "同僚嫉妒，设禁令陷害", "狮子坑中神封住狮子的口", "王下令全国敬畏但以理的神"], "title": "伯沙撒与狮子坑（5-6章）"}, {"points": ["四兽从海中上来的异象", "亘古常在者坐在宝座上", "一位像人子的得国权荣耀", "公绵羊与公山羊的异象", "小角兴起亵渎圣所", "圣民必得国直到永永远远"], "title": "异象（7-8章）"}, {"points": ["为耶路撒冷禁食披麻祷告", "七十个七的预言（9:24-27）", "从出令重建到受膏君六十九个七", "睡在尘埃中的必有多人复醒（12:2）", "大患难中你本国之民必得拯救", "你且去等候结局（12:13）"], "title": "七十个七（9-12章）"}]','','58','旧约•大先知书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220962001','圣经导览','何西阿书','北国将亡之际，神命何西阿娶淫妇歌篾为妻，以破碎的婚姻预表以色列对神的不忠。“我喜爱怜恤，不喜爱祭祀”——全书显明神对背道子民不离不弃的慈爱，末了呼召以色列归向耶和华他们的神。','[{"type": "verse", "q": "【经文填空】我喜爱________，不喜爱祭祀；喜爱________，胜于燔祭。", "a": "怜恤|认识神", "ref": "《何西阿书》6章6节", "s": "", "o": "何西阿书6章6节"}, {"type": "verse", "q": "【经文填空】以色列啊，你要________耶和华你的神；你是因自己的________跌倒了。", "a": "归向|罪孽", "ref": "《何西阿书》14章1节", "s": "", "o": "何西阿书14章1节"}, {"type": "verse", "q": "【经文填空】你去娶________为妻，也收那从________所生的儿女。", "a": "淫妇|淫乱", "ref": "《何西阿书》1章2节", "s": "", "o": "何西阿书1章2节"}, {"type": "verse", "q": "【经文填空】以色列年幼的时候，我________他，就从________召出我的儿子来。", "a": "爱|埃及", "ref": "《何西阿书》11章1节", "s": "", "o": "何西阿书11章1节"}, {"type": "verse", "q": "【经文填空】我的民因________而灭亡。你弃掉________，我也必弃掉你。", "a": "无知识|知识", "ref": "《何西阿书》4章6节", "s": "", "o": "何西阿书4章6节"}, {"type": "verse", "q": "【经文填空】以法莲哪，我怎能________你？以色列啊，我怎能________你？", "a": "舍弃|弃绝", "ref": "《何西阿书》11章8节", "s": "", "o": "何西阿书11章8节"}, {"type": "verse", "q": "【经文填空】我必聘你________归我为妻，以仁义、公平、________、怜悯聘你归我。", "a": "永远|慈爱", "ref": "《何西阿书》2章19节", "s": "", "o": "何西阿书2章19节"}, {"type": "fill", "q": "何西阿的妻子名叫________。", "a": "歌篾", "s": ""}, {"type": "fill", "q": "歌篾所生长子，何西阿给他起名叫________，预表耶斯列的血债。", "a": "耶斯列", "s": ""}, {"type": "fill", "q": "次女名叫________，意为“不蒙怜悯”。", "a": "罗路哈玛", "s": ""}, {"type": "fill", "q": "幼子名叫________，意为“非我民”。", "a": "罗阿米", "s": ""}, {"type": "fill", "q": "何西阿用________舍客勒银子把歌篾赎回。", "a": "十五", "s": ""}, {"type": "fill", "q": "以色列拜________，行淫乱离弃神。", "a": "巴力", "s": ""}, {"type": "fill", "q": "以法莲是________的饼，没有翻过。", "a": "未翻过", "s": ""}, {"type": "fill", "q": "神说：“他们种的是________，收的是暴风。”", "a": "风", "s": ""}, {"type": "fill", "q": "何西阿主要在北国________二世年间传道。", "a": "耶罗波安", "s": ""}, {"type": "fill", "q": "以色列求告________和埃及，却不归向神。", "a": "亚述", "s": ""}, {"type": "single", "q": "何西阿娶谁为妻？", "o": ["歌篾", "底波拉", "哈拿", "亚比该"], "a": "歌篾", "s": ""}, {"type": "single", "q": "“罗阿米”的意思是？", "o": ["非我民", "不蒙怜恤", "耶和华已播种", "神与我们同在"], "a": "非我民", "s": ""}, {"type": "single", "q": "何西阿书共有多少章？", "o": ["12", "13", "14", "15"], "a": "14", "s": ""}, {"type": "single", "q": "神喜爱什么胜于燔祭？", "o": ["认识神", "金银", "长寿", "子孙"], "a": "认识神", "s": ""}, {"type": "single", "q": "何西阿向哪个国家传道？", "o": ["北国以色列", "南国犹大", "亚述", "巴比伦"], "a": "北国以色列", "s": ""}, {"type": "single", "q": "以色列的偶像敬拜主要拜谁？", "o": ["巴力", "摩洛", "亚斯她录", "大衮"], "a": "巴力", "s": ""}, {"type": "single", "q": "何西阿用什么把歌篾赎回？", "o": ["十五舍客勒银子", "三十舍客勒银子", "一头牛", "一只羊"], "a": "十五舍客勒银子", "s": ""}, {"type": "multiple", "q": "歌篾三个儿女的名字是？", "o": ["耶斯列", "罗路哈玛", "罗阿米", "以实玛利"], "a": "耶斯列,罗路哈玛,罗阿米", "s": ""}, {"type": "multiple", "q": "以下哪些是何西阿书提到的以色列之罪？", "o": ["拜巴力偶像", "弃掉知识", "与外邦掺杂", "倚靠亚述"], "a": "拜巴力偶像,弃掉知识,与外邦掺杂,倚靠亚述", "s": ""}, {"type": "multiple", "q": "神对以色列的慈爱表现在？", "o": ["年幼时从埃及召出", "以慈绳爱索牵引", "不忍舍弃以法莲", "应许医治背道"], "a": "年幼时从埃及召出,以慈绳爱索牵引,不忍舍弃以法莲,应许医治背道", "s": ""}, {"type": "multiple", "q": "何西阿书的中心信息包括？", "o": ["神必审判罪恶", "神慈爱不离不弃", "呼召以色列归回", "预言弥赛亚降生"], "a": "神必审判罪恶,神慈爱不离不弃,呼召以色列归回", "s": ""}, {"type": "judge", "q": "何西阿是南国犹大的先知。", "a": "错", "s": ""}, {"type": "judge", "q": "歌篾象征对神不忠的以色列。", "a": "对", "s": ""}, {"type": "judge", "q": "“罗路哈玛”意为“蒙怜悯”。", "a": "错", "s": ""}, {"type": "judge", "q": "神说“我喜爱怜恤，不喜爱祭祀”。", "a": "对", "s": ""}, {"type": "judge", "q": "何西阿书共有十五章。", "a": "错", "s": ""}, {"type": "judge", "q": "神最终呼召以色列归向祂。", "a": "对", "s": ""}, {"type": "judge", "q": "以法莲在何西阿书中指南国犹大。", "a": "错", "s": ""}, {"type": "essay", "q": "何西阿的婚姻如何预表神与以色列的关系？", "a": "何西阿娶淫妇歌篾为妻，歌篾离家追随情夫，何西阿仍用银子将她赎回；正如以色列离弃神、拜偶像行淫，神却以不离不弃的慈爱接纳他们归回。", "s": ""}, {"type": "essay", "q": "“我喜爱怜恤，不喜爱祭祀”对今日信徒有何提醒？", "a": "神看重内心的怜悯与对神真实的认识，胜过外在的宗教仪式；没有爱心与顺服的敬拜，是神所厌恶的。", "s": ""}, {"type": "essay", "q": "何西阿书14章的归回呼召包含哪些应许？", "a": "神必医治他们的背道，甘心爱他们；祂如甘露滋润以色列，使他们如百合花开放、如黎巴嫩香柏树扎根，重新结果，智慧人必明白这些事。", "s": ""}]','','study','[{"title": "先知的婚姻（1-3章）", "points": ["神命何西阿娶淫妇歌篾为妻", "三儿女：耶斯列、罗路哈玛、罗阿米", "名字预表审判：血债、不蒙怜悯、非我民", "歌篾离家追随情夫", "何西阿用十五舍客勒银子赎回她", "预表以色列离弃神、神仍接纳"]}, {"title": "以色列的罪（4-7章）", "points": ["我的民因无知识而灭亡", "祭司弃掉知识，神也弃掉祭司", "拜巴力、行淫乱，离弃耶和华", "以法莲如未翻过的饼，与外邦掺杂", "求告亚述和埃及，不归向至上者", "他们种的是风，收的是暴风"]}, {"title": "审判的宣告（8-10章）", "points": ["以色列忘记造他的主，建造宫殿", "撒玛利亚的牛犊偶像必被打碎", "伯亚文的邱坛必毁灭", "以法莲如产难的妇人，愚昧不智", "神必追讨他们的罪孽，刑罚他们的罪恶"]}, {"title": "神的慈爱（11-13章）", "points": ["以色列年幼时我爱他，从埃及召出", "我怎能舍弃你？怎能弃绝你？", "以慈绳爱索牵引他们", "我不发猛烈的怒气，不再毁灭以法莲", "虽审判，怜爱仍存，心肠回转", "以色列自取败坏，惟靠神才得帮助"]}, {"title": "归回的呼召（14章）", "points": ["以色列啊，归向耶和华你的神", "求神除净罪孽，悦纳善行", "不再倚靠亚述，不骑埃及马", "神必医治他们的背道，甘心爱他们", "如甘露、百合花、香柏树般复兴", "智慧人必明白，义人必行在其中"]}]','','59','旧约•小先知书（十二小先知书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220962002','圣经导览','约珥书','蝗虫遮天之灾临到犹大，约珥宣告耶和华大而可畏的日子。“撕裂心肠，不撕裂衣服”——神要真心的悔改；“我要将我的灵浇灌凡有血气的”预言五旬节圣灵降临；末了万国要在约沙法谷受审判。','[{"type": "verse", "q": "【经文填空】你们要________，不撕裂衣服，归向耶和华你们的神。", "a": "撕裂心肠", "ref": "《约珥书》2章13节", "s": "", "o": "约珥书2章13节"}, {"type": "verse", "q": "【经文填空】以后，我要将我的________浇灌________。", "a": "灵|凡有血气的", "ref": "《约珥书》2章28节", "s": "", "o": "约珥书2章28节"}, {"type": "verse", "q": "【经文填空】到那时候，凡________耶和华名的就必得救。", "a": "求告", "ref": "《约珥书》2章32节", "s": "", "o": "约珥书2章32节"}, {"type": "verse", "q": "【经文填空】________剩下的，蝗虫来吃；蝗虫剩下的，________来吃。", "a": "剪虫|蝻子", "ref": "《约珥书》1章4节", "s": "", "o": "约珥书1章4节"}, {"type": "verse", "q": "【经文填空】我打发到你们中间的大军队所吃的那些年，我要________你们。", "a": "补还", "ref": "《约珥书》2章25节", "s": "", "o": "约珥书2章25节"}, {"type": "verse", "q": "【经文填空】要将________打成刀剑，将________打成戈矛。", "a": "犁头|镰刀", "ref": "《约珥书》3章10节", "s": "", "o": "约珥书3章10节"}, {"type": "verse", "q": "【经文填空】________在断定谷，因为耶和华的日子临近________。", "a": "许多许多的人|断定谷", "ref": "《约珥书》3章14节", "s": "", "o": "约珥书3章14节"}, {"type": "fill", "q": "约珥书描述的灾难是________之灾。", "a": "蝗虫", "s": ""}, {"type": "fill", "q": "四种蝗虫：剪虫、蝗虫、________、蚂蚱。", "a": "蝻子", "s": ""}, {"type": "fill", "q": "约珥呼吁祭司________哀哭。", "a": "披麻", "s": ""}, {"type": "fill", "q": "神说祂有________，有怜悯，不轻易发怒。", "a": "恩典", "s": ""}, {"type": "fill", "q": "圣灵浇灌时，老年人要做________，少年人要见________。", "a": "异梦|异象", "s": ""}, {"type": "fill", "q": "万国受审判的地点是________谷。", "a": "约沙法", "s": ""}, {"type": "fill", "q": "约珥书共有________章。", "a": "三", "s": ""}, {"type": "fill", "q": "蝗虫________奔跑，像战士爬城。", "a": "如勇士", "s": ""}, {"type": "fill", "q": "复兴时神应许山要滴________，冈要流奶。", "a": "新酒", "s": ""}, {"type": "fill", "q": "耶和华的日子临近时，日月________，星宿无光。", "a": "昏暗", "s": ""}, {"type": "single", "q": "约珥书开头的灾难是什么？", "o": ["蝗灾", "水灾", "地震", "瘟疫"], "a": "蝗灾", "s": ""}, {"type": "single", "q": "“撕裂心肠，不撕裂衣服”出自哪卷书？", "o": ["约珥书", "何西阿书", "阿摩司书", "弥迦书"], "a": "约珥书", "s": ""}, {"type": "single", "q": "圣灵浇灌的预言在新约应验于哪个节期？", "o": ["五旬节", "逾越节", "住棚节", "吹角节"], "a": "五旬节", "s": ""}, {"type": "single", "q": "万国受审判之地是哪里？", "o": ["约沙法谷", "欣嫩谷", "以琳", "汛"], "a": "约沙法谷", "s": ""}, {"type": "single", "q": "约珥的父亲是谁？", "o": ["毗土珥", "比利", "哈迦", "玛拉基"], "a": "毗土珥", "s": ""}, {"type": "single", "q": "神应许补还的是什么年？", "o": ["蝗虫所吃之年", "饥荒之年", "被掳之年", "旱灾之年"], "a": "蝗虫所吃之年", "s": ""}, {"type": "single", "q": "凡求告耶和华名的会怎样？", "o": ["就必得救", "必蒙福", "必长寿", "必富足"], "a": "就必得救", "s": ""}, {"type": "multiple", "q": "蝗灾带来的后果有哪些？", "o": ["田地荒凉", "五谷断绝", "新酒干竭", "油也缺乏"], "a": "田地荒凉,五谷断绝,新酒干竭,油也缺乏", "s": ""}, {"type": "multiple", "q": "圣灵浇灌时，哪些人要说预言、见异象？", "o": ["儿女", "老年人", "少年人", "仆人和使女"], "a": "儿女,老年人,少年人,仆人和使女", "s": ""}, {"type": "multiple", "q": "约珥呼召百姓如何悔改？", "o": ["禁食", "哭泣", "悲哀", "撕裂心肠"], "a": "禁食,哭泣,悲哀,撕裂心肠", "s": ""}, {"type": "multiple", "q": "复兴时神的应许有哪些？", "o": ["补还蝗虫所吃之年", "五谷新酒满溢", "灵浇灌凡有血气", "耶和华住在锡安"], "a": "补还蝗虫所吃之年,五谷新酒满溢,灵浇灌凡有血气,耶和华住在锡安", "s": ""}, {"type": "judge", "q": "约珥书共有四章。", "a": "错", "s": ""}, {"type": "judge", "q": "蝗灾预表耶和华大而可畏的日子。", "a": "对", "s": ""}, {"type": "judge", "q": "神喜悦人只撕裂衣服的悔改。", "a": "错", "s": ""}, {"type": "judge", "q": "圣灵的浇灌只限于以色列人。", "a": "错", "s": ""}, {"type": "judge", "q": "约沙法谷是万国受审判之地。", "a": "对", "s": ""}, {"type": "judge", "q": "凡求告耶和华名的就必得救。", "a": "对", "s": ""}, {"type": "judge", "q": "约珥是北国以色列的先知。", "a": "错", "s": ""}, {"type": "essay", "q": "约珥书2章28节圣灵浇灌的预言如何应验？", "a": "五旬节圣灵降临（使徒行传2章），彼得引用此经文讲解；圣灵浇灌凡有血气的，不分男女老幼、仆人使女，显明救恩临到万民。", "s": ""}, {"type": "essay", "q": "“撕裂心肠，不撕裂衣服”是什么意思？", "a": "神要的是内心真实的痛悔，而非外在的宗教仪式；心灵破碎、真心归向神，才是神所悦纳的悔改。", "s": ""}, {"type": "essay", "q": "蝗灾与“耶和华的日子”有何关联？", "a": "蝗灾是耶和华日子临近的预兆和缩影；历史中的灾难提醒人，终极的审判将至，应当趁早悔改归向神。", "s": ""}]','','study','[{"title": "蝗灾的警告（1章）", "points": ["四种蝗虫接连吞吃：剪虫、蝗虫、蝻子、蚂蚱", "田荒粮绝，新酒干竭，油也缺乏", "祭司披麻哀哭，素祭奠祭断绝", "前所未有、后无来者的灾难", "唤醒醉酒的人为此哭泣", "牲畜哀鸣，火烧旷野的草场"]}, {"title": "耶和华的日子（2:1-17）", "points": ["大而可畏的日子临近，要吹角警告", "蝗虫如强盛的民，如早晨铺满山", "日月昏暗，星宿无光", "你们要撕裂心肠，不撕裂衣服", "神有恩典有怜悯，不轻易发怒", "吹角禁食，招聚老少聚集"]}, {"title": "圣灵的浇灌（2:18-32）", "points": ["耶和华为自己的地发热心，怜恤百姓", "补还蝗虫、蝻子、蚂蚱所吃之年", "五谷新酒和油充足，百姓不再羞愧", "将我的灵浇灌凡有血气的", "儿女说预言，老年做异梦，少年见异象", "凡求告耶和华名的就必得救"]}, {"title": "万国的审判（3:1-16）", "points": ["我必聚集万民到约沙法谷审判", "为选民伸冤，追讨列国之罪", "推罗、西顿、非利士受报应", "将犁头打成刀剑，镰刀打成戈矛", "许多许多的人在断定谷", "耶和华的日子临近断定谷"]}, {"title": "犹大的复兴（3:17-21）", "points": ["锡安山必成圣，外邦人不再经过", "山滴新酒，冈流奶，小河有水流", "埃及荒凉，以东凄凉，因向犹大行强暴", "犹大必存到永远，耶路撒冷存到万代", "耶和华住在锡安，洗净流血之罪"]}]','','60','旧约•小先知书（十二小先知书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220962003','圣经导览','阿摩司书','南国牧人阿摩司蒙召向北国发预言：“惟愿公平如大水滚滚，公义如江河滔滔”。他责备富户欺压穷人、伯特利的偶像敬拜，藉蝗虫、烈火、准绳等五异象宣告审判，末了应许复兴大卫倒塌的帐幕。','[{"type": "verse", "q": "【经文填空】惟愿________如大水滚滚，使________如江河滔滔。", "a": "公平|公义", "ref": "《阿摩司书》5章24节", "s": "", "o": "阿摩司书5章24节"}, {"type": "verse", "q": "【经文填空】________若不同心，岂能同行呢？", "a": "二人", "ref": "《阿摩司书》3章3节", "s": "", "o": "阿摩司书3章3节"}, {"type": "verse", "q": "【经文填空】主耶和华若不将________指示他的仆人________，就一无所行。", "a": "奥秘|众先知", "ref": "《阿摩司书》3章7节", "s": "", "o": "阿摩司书3章7节"}, {"type": "verse", "q": "【经文填空】人饥饿非因无饼，干渴非因无水，乃因不听________。", "a": "耶和华的话", "ref": "《阿摩司书》8章11节", "s": "", "o": "阿摩司书8章11节"}, {"type": "verse", "q": "【经文填空】以色列啊，我既这样行，你当________迎见你的神。", "a": "预备", "ref": "《阿摩司书》4章12节", "s": "", "o": "阿摩司书4章12节"}, {"type": "verse", "q": "【经文填空】他们为________卖了义人，为________卖了穷人。", "a": "银子|一双鞋", "ref": "《阿摩司书》2章6节", "s": "", "o": "阿摩司书2章6节"}, {"type": "verse", "q": "【经文填空】我必出令，将以色列家分散在列国中，好像用________筛谷。", "a": "筛子", "ref": "《阿摩司书》9章9节", "s": "", "o": "阿摩司书9章9节"}, {"type": "fill", "q": "阿摩司是________人，原以牧羊和修理桑树为业。", "a": "提哥亚", "s": ""}, {"type": "fill", "q": "阿摩司是南国人，却向________国传道。", "a": "北国以色列", "s": ""}, {"type": "fill", "q": "五异象之一：神拿________站在墙上，预表审判的标准。", "a": "准绳", "s": ""}, {"type": "fill", "q": "________是伯特利的祭司，起来抵挡阿摩司。", "a": "亚玛谢", "s": ""}, {"type": "fill", "q": "阿摩司看见一筐________，预表以色列的结局近了。", "a": "夏果", "s": ""}, {"type": "fill", "q": "他们见穷人头上所蒙的灰也都________。", "a": "践踏", "s": ""}, {"type": "fill", "q": "有祸了，那些在________安逸无虑的。", "a": "锡安", "s": ""}, {"type": "fill", "q": "神应许到那日必建立________倒塌的帐幕。", "a": "大卫", "s": ""}, {"type": "fill", "q": "阿摩司书共有________章。", "a": "九", "s": ""}, {"type": "fill", "q": "神说：“我厌恶你们的________，也不喜悦你们的严肃会。”", "a": "节期", "s": ""}, {"type": "single", "q": "阿摩司原来的职业是？", "o": ["牧人", "祭司", "文士", "君王"], "a": "牧人", "s": ""}, {"type": "single", "q": "“公平如大水滚滚”出自哪卷书？", "o": ["阿摩司书", "弥迦书", "以赛亚书", "耶利米书"], "a": "阿摩司书", "s": ""}, {"type": "single", "q": "抵挡阿摩司的伯特利祭司是谁？", "o": ["亚玛谢", "玛西雅", "希勒家", "撒督"], "a": "亚玛谢", "s": ""}, {"type": "single", "q": "阿摩司所见“准绳”的异象预表什么？", "o": ["神的审判标准", "建造圣殿", "测量土地", "纺织工具"], "a": "神的审判标准", "s": ""}, {"type": "single", "q": "阿摩司是哪里人？", "o": ["提哥亚", "伯特利", "耶路撒冷", "希伯仑"], "a": "提哥亚", "s": ""}, {"type": "single", "q": "北国拜偶像的宗教中心在哪里？", "o": ["伯特利", "耶路撒冷", "希伯仑", "示罗"], "a": "伯特利", "s": ""}, {"type": "single", "q": "神末了应许复兴什么？", "o": ["大卫倒塌的帐幕", "所罗门圣殿", "约柜", "祭坛"], "a": "大卫倒塌的帐幕", "s": ""}, {"type": "multiple", "q": "五异象包括以下哪些？", "o": ["蝗虫", "烈火", "准绳", "夏果"], "a": "蝗虫,烈火,准绳,夏果", "s": ""}, {"type": "multiple", "q": "以色列的罪状有哪些？", "o": ["为银子卖了义人", "践踏穷人", "拜伯特利的偶像", "以物配主"], "a": "为银子卖了义人,践踏穷人,拜伯特利的偶像", "s": ""}, {"type": "multiple", "q": "神藉阿摩司宣告审判的列国有哪些？", "o": ["大马士革", "非利士", "摩押", "以东"], "a": "大马士革,非利士,摩押,以东", "s": ""}, {"type": "multiple", "q": "神对以色列的呼召有哪些？", "o": ["寻求耶和华就必存活", "求善不求恶", "恨恶邪恶", "预备迎见你的神"], "a": "寻求耶和华就必存活,求善不求恶,恨恶邪恶,预备迎见你的神", "s": ""}, {"type": "judge", "q": "阿摩司是职业先知，出身先知门徒。", "a": "错", "s": ""}, {"type": "judge", "q": "“二人若不同心，岂能同行”出自阿摩司书。", "a": "对", "s": ""}, {"type": "judge", "q": "阿摩司只向南国犹大传道。", "a": "错", "s": ""}, {"type": "judge", "q": "神厌恶没有公义的节期和祭祀。", "a": "对", "s": ""}, {"type": "judge", "q": "五异象中神没有给阿摩司代求的机会。", "a": "错", "s": ""}, {"type": "judge", "q": "伯特利是北国敬拜神的正统中心。", "a": "错", "s": ""}, {"type": "judge", "q": "阿摩司书末了有复兴的应许。", "a": "对", "s": ""}, {"type": "essay", "q": "“惟愿公平如大水滚滚，使公义如江河滔滔”对今日信徒有何意义？", "a": "神看重社会公义过于宗教仪式；信徒当在生活中行公义、好怜悯，而非只有敬拜聚会却没有行为见证。", "s": ""}, {"type": "essay", "q": "阿摩司虽是牧人，神为何拣选他作先知？", "a": "神不看人的出身地位，拣选卑微的牧人向北国发预言；显明传道的能力在乎神的呼召与同在，不在乎人的资历背景。", "s": ""}, {"type": "essay", "q": "五异象显明神怎样的属性？", "a": "神既公义，必审判罪恶（蝗虫、烈火、准绳）；又满有怜悯，垂听阿摩司的代求；审判之后仍应许复兴，显明审判中有恩典。", "s": ""}]','','study','[{"title": "列国的审判（1-2章）", "points": ["三番四次犯罪，我必不免去刑罚", "审判大马士革、非利士、推罗", "审判以东、亚扪、摩押的残暴", "犹大弃绝律法，随从虚假", "以色列为银子卖了义人，为鞋卖穷人", "践踏穷人头上的尘土，屈枉困苦人"]}, {"title": "责备与呼召（3-4章）", "points": ["二人若不同心，岂能同行", "神不将奥秘指示先知，就一无所行", "伯特利的祭坛必被拆毁", "你们在床上安逸，却不行公义", "五次说“你们仍不归向我”", "以色列啊，预备迎见你的神"]}, {"title": "公义的呼声（5-6章）", "points": ["寻求耶和华就必存活，不要往伯特利寻求", "恨恶在城门口责备人的", "惟愿公平如大水滚滚，公义如江河滔滔", "我厌恶你们的节期，不喜悦严肃会", "有祸了，那些在锡安安逸无虑的", "躺卧在象牙床上，吞吃肥美羊羔"]}, {"title": "五异象（7-9:10）", "points": ["蝗虫之灾：阿摩司代求，神后悔", "烈火焚烧：代求蒙应允", "准绳量墙：不再宽恕，以色列必被掳", "一筐夏果：我民的结局到了", "耶和华站在祭坛旁：击打柱顶", "亚玛谢抵挡：你必死在污秽之地", "筛以色列如筛谷，一粒不落空"]}, {"title": "复兴的应许（9:11-15）", "points": ["到那日必建立大卫倒塌的帐幕", "堵住其中的破口，重修废墟", "使以色列人得未得之地", "栽种葡萄园，喝其酒，吃果子", "将他们栽于本地，不再拔出", "这是耶和华说的"]}]','','61','旧约•小先知书（十二小先知书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220962004','圣经导览','俄巴底亚书','旧约最短的先知书，全书仅二十一节。神藉俄巴底亚审判以东：因向兄弟雅各行强暴、幸灾乐祸，又狂傲自欺自恃天险。“你虽如大鹰高飞，我必拉下你来”；末了宣告：国度就归耶和华了。','[{"type": "verse", "q": "【经文填空】你虽如________高飞，在________之间搭窝，我必从那里拉下你来。", "a": "大鹰|星宿", "ref": "《俄巴底亚书》1章4节", "s": "", "o": "俄巴底亚书1章4节"}, {"type": "verse", "q": "【经文填空】必有拯救者上到________，审判以扫山；________就归耶和华了。", "a": "锡安山|国度", "ref": "《俄巴底亚书》1章21节", "s": "", "o": "俄巴底亚书1章21节"}, {"type": "verse", "q": "【经文填空】因你向兄弟________行强暴，羞愧必遮盖你。", "a": "雅各", "ref": "《俄巴底亚书》1章10节", "s": "", "o": "俄巴底亚书1章10节"}, {"type": "verse", "q": "【经文填空】耶和华降罚的日子临近________。你怎样行，他也必照样向你行。", "a": "万国", "ref": "《俄巴底亚书》1章15节", "s": "", "o": "俄巴底亚书1章15节"}, {"type": "verse", "q": "【经文填空】你兄弟遭难的日子，你不当________看着。", "a": "瞪眼", "ref": "《俄巴底亚书》1章12节", "s": "", "o": "俄巴底亚书1章12节"}, {"type": "verse", "q": "【经文填空】住在________中、居所在高处的啊，你因________自欺。", "a": "山穴|狂傲", "ref": "《俄巴底亚书》1章3节", "s": "", "o": "俄巴底亚书1章3节"}, {"type": "verse", "q": "【经文填空】在________必有逃脱的人，那山也必成圣。", "a": "锡安山", "ref": "《俄巴底亚书》1章17节", "s": "", "o": "俄巴底亚书1章17节"}, {"type": "fill", "q": "俄巴底亚书是旧约最________的书卷之一，全书仅二十一节。", "a": "短", "s": ""}, {"type": "fill", "q": "本卷预言审判的对象是________。", "a": "以东", "s": ""}, {"type": "fill", "q": "以东的祖先是________。", "a": "以扫", "s": ""}, {"type": "fill", "q": "以扫是雅各的________。", "a": "兄弟", "s": ""}, {"type": "fill", "q": "以东人住在________中，自以为稳固难攻。", "a": "山穴", "s": ""}, {"type": "fill", "q": "犹大人被灭的日子，以东不当因此________。", "a": "欢乐", "s": ""}, {"type": "fill", "q": "神必从以东除灭________人，使提幔的勇士惊惶。", "a": "智慧", "s": ""}, {"type": "fill", "q": "与以东结盟的都________他，将他送到边界。", "a": "欺哄", "s": ""}, {"type": "fill", "q": "雅各家必得________的产业。", "a": "原有", "s": ""}, {"type": "fill", "q": "俄巴底亚意为“________的仆人”。", "a": "耶和华", "s": ""}, {"type": "single", "q": "俄巴底亚书审判哪个国家？", "o": ["以东", "摩押", "亚扪", "非利士"], "a": "以东", "s": ""}, {"type": "single", "q": "以东的祖先是谁？", "o": ["以扫", "以实玛利", "罗得", "含"], "a": "以扫", "s": ""}, {"type": "single", "q": "俄巴底亚书全书共有几节？", "o": ["21", "25", "31", "36"], "a": "21", "s": ""}, {"type": "single", "q": "“国度就归耶和华了”出自哪卷书？", "o": ["俄巴底亚书", "约珥书", "弥迦书", "哈巴谷书"], "a": "俄巴底亚书", "s": ""}, {"type": "single", "q": "以东因何受审判？", "o": ["向兄弟雅各行强暴", "拜偶像", "不守安息日", "欺压穷人"], "a": "向兄弟雅各行强暴", "s": ""}, {"type": "single", "q": "以东自恃的是什么？", "o": ["山穴高处", "大军", "财富", "智慧"], "a": "山穴高处", "s": ""}, {"type": "single", "q": "俄巴底亚书在十二小先知中排第几？", "o": ["第四", "第五", "第六", "第七"], "a": "第四", "s": ""}, {"type": "multiple", "q": "以东的罪状有哪些？", "o": ["狂傲自欺", "向兄弟雅各行强暴", "幸灾乐祸", "趁火抢夺财物"], "a": "狂傲自欺,向兄弟雅各行强暴,幸灾乐祸,趁火抢夺财物", "s": ""}, {"type": "multiple", "q": "神对以东的审判有哪些？", "o": ["从高处拉下", "智慧人被剪除", "结盟者欺哄", "无一人存留"], "a": "从高处拉下,智慧人被剪除,结盟者欺哄,无一人存留", "s": ""}, {"type": "multiple", "q": "本卷末了的应许有哪些？", "o": ["锡安山必有逃脱的人", "雅各家必得原有产业", "拯救者上到锡安山", "国度就归耶和华了"], "a": "锡安山必有逃脱的人,雅各家必得原有产业,拯救者上到锡安山,国度就归耶和华了", "s": ""}, {"type": "multiple", "q": "以东与以色列的关系是？", "o": ["以扫是雅各的哥哥", "两国同源而分", "以东曾助敌攻犹大", "神审判不偏待人"], "a": "以扫是雅各的哥哥,两国同源而分,以东曾助敌攻犹大,神审判不偏待人", "s": ""}, {"type": "judge", "q": "俄巴底亚书是旧约最长的先知书。", "a": "错", "s": ""}, {"type": "judge", "q": "以东是雅各的后代。", "a": "错", "s": ""}, {"type": "judge", "q": "神审判以东是因它向兄弟雅各行强暴。", "a": "对", "s": ""}, {"type": "judge", "q": "以东的骄傲在于住在山穴高处。", "a": "对", "s": ""}, {"type": "judge", "q": "“国度就归耶和华了”是俄巴底亚书的结语。", "a": "对", "s": ""}, {"type": "judge", "q": "以东在犹大遭难时伸出援手。", "a": "错", "s": ""}, {"type": "judge", "q": "俄巴底亚书没有提及复兴的应许。", "a": "错", "s": ""}, {"type": "essay", "q": "以东为何受神严厉审判？", "a": "以东向兄弟雅各行强暴，在犹大遭难时幸灾乐祸、趁火打劫、剪除逃脱的人；又因狂傲自欺，自恃山穴天险而不敬畏神。", "s": ""}, {"type": "essay", "q": "“你虽如大鹰高飞，我必拉下你来”给今日信徒何提醒？", "a": "人不可自高自傲；再高的权势地位，在神面前都不堪一击；骄傲在败坏以先，谦卑才能蒙恩。", "s": ""}, {"type": "essay", "q": "“国度就归耶和华了”有何末世意义？", "a": "预告神国的完全实现；万国的权势都要过去，唯有神的国永远长存；信徒当以神的国度为盼望和归宿。", "s": ""}]','','study','[{"title": "以东的骄傲（1-4节）", "points": ["住在山穴中，居所在高处", "因狂傲自欺，心里说谁能拉我下去", "你虽如大鹰高飞，在星宿间搭窝", "我必从那里拉下你来，这是耶和华说的", "天险不能成为骄傲的资本"]}, {"title": "彻底的倾覆（5-9节）", "points": ["盗贼夜来岂会拿光吗？以东却被搜尽", "以扫的隐密处都被搜出", "与你结盟的都欺哄你，送你到边界", "与你和好的设网罗陷害你", "智慧人从以东剪除，提幔勇士惊惶", "以扫山的人必被杀戮剪除"]}, {"title": "向兄弟行强暴（10-14节）", "points": ["因向兄弟雅各行强暴，羞愧遮盖你", "兄弟遭难之日，不当瞪眼看着", "犹大被灭之日，不当因此欢乐", "不当伸手拿他的财物", "不当在岔路口剪除逃脱的人", "不当将幸存者交付仇敌"]}, {"title": "报应的日子（15-18节）", "points": ["耶和华降罚的日子临近万国", "你怎样行，也必照样向你行", "你的报应必归到你头上", "雅各家必为火，约瑟家为火焰", "以扫家必如碎秸，被烧灭无存留", "这是耶和华说的"]}, {"title": "国度归耶和华（19-21节）", "points": ["南地的人必得以扫山为业", "高原有人得非利士地", "被掳的以色列人必得迦南地", "必有拯救者上到锡安山", "审判以扫山", "国度就归耶和华了"]}]','','62','旧约•小先知书（十二小先知书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224175311','圣经导览','约拿书','约拿书讲述先知约拿逃避神命、被大鱼吞吃、终往尼尼微传警告，全城悔改蒙赦免。本书显明神的怜悯超越国界，祂顾惜外邦人，也光照约拿自义的心，预表基督三日复活。','[{"type": "verse", "q": "【经文填空】耶和华安排一条________吞了约拿，他在鱼腹中________三夜。", "a": "大鱼|三日", "ref": "《约拿书》1章17节", "s": "", "o": "约拿书1章17节"}, {"type": "verse", "q": "【经文填空】但我必用________的声音献祭与你。________出于耶和华。", "a": "感谢|救恩", "ref": "《约拿书》2章9节", "s": "", "o": "约拿书2章9节"}, {"type": "verse", "q": "【经文填空】于是神察看他们的________，见他们离开恶道，他就________，不把所说的灾祸降与他们了。", "a": "行为|后悔", "ref": "《约拿书》3章10节", "s": "", "o": "约拿书3章10节"}, {"type": "verse", "q": "【经文填空】我知道你是有________、有________的神，不轻易发怒，有丰盛的慈爱。", "a": "恩典|怜悯", "ref": "《约拿书》4章2节", "s": "", "o": "约拿书4章2节"}, {"type": "verse", "q": "【经文填空】我是________人。我敬畏耶和华那创造________旱地之天上的神。", "a": "希伯来|沧海", "ref": "《约拿书》1章9节", "s": "", "o": "约拿书1章9节"}, {"type": "verse", "q": "【经文填空】何况这尼尼微大城，其中不能分辨左手右手的有________多人。", "a": "十二万", "ref": "《约拿书》4章11节", "s": "", "o": "约拿书4章11节"}, {"type": "verse", "q": "【经文填空】我遭遇患难________耶和华，你就应允我。", "a": "求告", "ref": "《约拿书》2章2节", "s": "", "o": "约拿书2章2节"}, {"type": "fill", "q": "约拿违背神命，逃往________。", "a": "他施", "s": ""}, {"type": "fill", "q": "约拿书共________章。", "a": "四|4", "s": ""}, {"type": "fill", "q": "神安排的蓖麻一夜________，一夜干死。", "a": "发生", "s": ""}, {"type": "fill", "q": "尼尼微王下令，人与牲畜都当________。", "a": "披麻", "s": ""}, {"type": "fill", "q": "约拿向神求________，说“求你取我的命吧”。", "a": "死", "s": ""}, {"type": "fill", "q": "耶稣以“约拿的神迹”预表自己死后________复活。", "a": "三日", "s": ""}, {"type": "fill", "q": "船主叫约拿起来，求告他的________。", "a": "神", "s": ""}, {"type": "fill", "q": "尼尼微人信服神，宣告________。", "a": "禁食", "s": ""}, {"type": "fill", "q": "神使一条________咬这蓖麻，以致枯槁。", "a": "虫子", "s": ""}, {"type": "fill", "q": "约拿出城，坐在城的________，要看那城究竟如何。", "a": "东边", "s": ""}, {"type": "single", "q": "神差遣约拿往哪座城去传警告？", "o": ["尼尼微", "他施", "约帕", "大马士革"], "a": "尼尼微", "s": ""}, {"type": "single", "q": "约拿逃往他施，在哪座城上了船？", "o": ["约帕", "推罗", "西顿", "该撒利亚"], "a": "约帕", "s": ""}, {"type": "single", "q": "约拿在鱼腹中几日几夜？", "o": ["三日三夜", "七日七夜", "四十昼夜", "一日一夜"], "a": "三日三夜", "s": ""}, {"type": "single", "q": "尼尼微王听到警告后做了什么？", "o": ["披麻坐灰悔改", "杀约拿", "逃往他施", "不理会"], "a": "披麻坐灰悔改", "s": ""}, {"type": "single", "q": "神安排什么为约拿遮荫？", "o": ["蓖麻", "葡萄树", "橄榄树", "无花果树"], "a": "蓖麻", "s": ""}, {"type": "single", "q": "耶稣说的“约拿的神迹”是指什么？", "o": ["三日后复活", "大鱼吞人", "尼尼微悔改", "蓖麻速长"], "a": "三日后复活", "s": ""}, {"type": "single", "q": "约拿为什么逃避神的命令？", "o": ["知道神有恩典怜悯不愿降灾", "害怕尼尼微人", "不想离开家乡", "身体有病"], "a": "知道神有恩典怜悯不愿降灾", "s": ""}, {"type": "multiple", "q": "神为教导约拿安排了哪些？", "o": ["大鱼", "蓖麻", "虫子", "炎热的东风"], "a": "大鱼,蓖麻,虫子,炎热的东风", "s": ""}, {"type": "multiple", "q": "尼尼微人悔改的表现有哪些？", "o": ["披麻蒙灰", "宣告禁食", "离开恶道", "专心求告神"], "a": "披麻蒙灰,宣告禁食,离开恶道,专心求告神", "s": ""}, {"type": "multiple", "q": "约拿书显明神的哪些属性？", "o": ["怜悯外邦人", "主权掌管万物", "有恩典不轻易发怒", "只爱以色列人"], "a": "怜悯外邦人,主权掌管万物,有恩典不轻易发怒", "s": ""}, {"type": "multiple", "q": "船上的人在风浪中做了什么？", "o": ["抛货物", "抽签", "向耶和华献祭", "把约拿抛下海"], "a": "抛货物,抽签,向耶和华献祭,把约拿抛下海", "s": ""}, {"type": "judge", "q": "约拿是自愿前往尼尼微传道的。", "a": "错", "s": ""}, {"type": "judge", "q": "约拿在鱼腹中向神祷告。", "a": "对", "s": ""}, {"type": "judge", "q": "尼尼微全城从大到小都悔改了。", "a": "对", "s": ""}, {"type": "judge", "q": "神最终把所说的灾祸降给了尼尼微。", "a": "错", "s": ""}, {"type": "judge", "q": "约拿为蓖麻枯槁而发怒。", "a": "对", "s": ""}, {"type": "judge", "q": "约拿书共有五章。", "a": "错", "s": ""}, {"type": "judge", "q": "耶稣以约拿三日三夜在鱼腹中预表自己的复活。", "a": "对", "s": ""}, {"type": "essay", "q": "约拿书如何显明神对外邦人的怜悯？", "a": "神差遣约拿向外邦大城尼尼微传警告，尼尼微人悔改后神就后悔不降灾；书末神说祂顾惜城中十二万不能分辨左右手的人，显明神的怜悯超越以色列国界，临到万民。", "s": ""}, {"type": "essay", "q": "从约拿的逃避和发怒，我们学到什么功课？", "a": "约拿逃避神命显明人的悖逆，神却用风浪、大鱼挽回他；他为尼尼微蒙赦免发怒，显明先知的自义与狭隘，神用蓖麻教导他。功课：顺服神、除去偏见，与神同心怜悯失丧者。", "s": ""}, {"type": "essay", "q": "“约拿的神迹”与基督复活有什么关系？", "a": "耶稣说约拿三日三夜在大鱼腹中，人子也要这样三日三夜在地里头（太12:40）。约拿从鱼腹中出来预表基督死后第三日复活，这是神给不信世代的神迹。", "s": ""}]','','study','[{"title": "逃避与风浪（1章）", "points": ["神命约拿往尼尼微传警告", "约拿逃往他施，违背神命", "海中起大风，船几乎破坏", "抽签查出约拿是祸首", "约拿被抛入海，海就平静", "船上的人敬畏耶和华，向祂献祭许愿"]}, {"title": "鱼腹中的祷告（2章）", "points": ["耶和华安排大鱼吞了约拿", "约拿在鱼腹中三日三夜", "祷告：我遭遇患难求告耶和华", "救恩出于耶和华（2:9）", "预表基督死后三日复活（太12:40）", "神吩咐鱼把约拿吐在旱地上"]}, {"title": "尼尼微的悔改（3章）", "points": ["约拿第二次蒙召往尼尼微去", "宣告：再等四十日，尼尼微必倾覆", "从君王到百姓都披麻蒙灰悔改", "王下令：人不可吃喝，专心求告神", "神察看他们的行为就后悔不降灾"]}, {"title": "蓖麻与约拿的怒气（4章）", "points": ["约拿大大不悦，向神发怒", "祷告求死：我知道你是有恩典有怜悯的神", "神安排蓖麻，一夜发生一夜干死", "约拿为蓖麻发怒，神以此教导他", "神顾惜尼尼微十二万不能分辨左右手的人"]}, {"title": "神学信息", "points": ["神的怜悯超越以色列国界", "外邦人的悔改蒙神悦纳", "先知的自义与狭隘被光照", "神的主权：风、海、大鱼、蓖麻、虫子", "预表基督：三日三夜在地里头"]}]','','63','旧约•小先知书（十二小先知书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224190508','圣经导览','弥迦书','弥迦与以赛亚同时代，宣告撒玛利亚和耶路撒冷因罪受审判。书中预言基督生于伯利恒（5:2），提出“行公义、好怜悯、存谦卑的心与神同行”（6:8），末后以神的赦免与信实作结。','[{"type": "verse", "q": "【经文填空】________、以法他啊，你在犹大诸城中为小，将来必有一位从你那里出来，在以色列中为我作________。", "a": "伯利恒|掌权的", "ref": "《弥迦书》5章2节", "s": "", "o": "弥迦书5章2节"}, {"type": "verse", "q": "【经文填空】只要你________，好怜悯，存________的心，与你的神同行。", "a": "行公义|谦卑", "ref": "《弥迦书》6章8节", "s": "", "o": "弥迦书6章8节"}, {"type": "verse", "q": "【经文填空】至于我，我要________耶和华，要________那救我的神。", "a": "仰望|等候", "ref": "《弥迦书》7章7节", "s": "", "o": "弥迦书7章7节"}, {"type": "verse", "q": "【经文填空】有何神像你，________罪孽，饶恕你产业之________的罪过。", "a": "赦免|余民", "ref": "《弥迦书》7章18节", "s": "", "o": "弥迦书7章18节"}, {"type": "verse", "q": "【经文填空】他们要将刀打成________，把枪打成________。", "a": "犁头|镰刀", "ref": "《弥迦书》4章3节", "s": "", "o": "弥迦书4章3节"}, {"type": "verse", "q": "【经文填空】首领为________行审判，祭司为雇价施训诲，先知为________行占卜。", "a": "贿赂|银钱", "ref": "《弥迦书》3章11节", "s": "", "o": "弥迦书3章11节"}, {"type": "verse", "q": "【经文填空】必再怜悯我们，将我们的罪孽踏在脚下，又将我们的一切罪投于________。", "a": "深海", "ref": "《弥迦书》7章19节", "s": "", "o": "弥迦书7章19节"}, {"type": "fill", "q": "弥迦是________人。", "a": "摩利沙", "s": ""}, {"type": "fill", "q": "弥迦与先知________同时代。", "a": "以赛亚", "s": ""}, {"type": "fill", "q": "弥迦预言基督生于________。", "a": "伯利恒", "s": ""}, {"type": "fill", "q": "弥迦书共________章。", "a": "七|7", "s": ""}, {"type": "fill", "q": "神说锡安必被________像田地。", "a": "耕种", "s": ""}, {"type": "fill", "q": "弥迦时代，________和耶路撒冷都因罪被审判。", "a": "撒玛利亚", "s": ""}, {"type": "fill", "q": "末后的日子，万民都要________这山（耶和华殿的山）。", "a": "流归", "s": ""}, {"type": "fill", "q": "先知说“我的神必________我”。", "a": "应允", "s": ""}, {"type": "fill", "q": "神喜爱________，不永远怀怒。", "a": "施恩", "s": ""}, {"type": "fill", "q": "神要按古时向列祖所起的誓，施________与雅各。", "a": "信实", "s": ""}, {"type": "single", "q": "弥迦是哪里人？", "o": ["摩利沙", "伯利恒", "耶路撒冷", "撒玛利亚"], "a": "摩利沙", "s": ""}, {"type": "single", "q": "基督降生伯利恒的预言在弥迦书哪一章？", "o": ["5章", "3章", "6章", "7章"], "a": "5章", "s": ""}, {"type": "single", "q": "“行公义，好怜悯”出自哪一节？", "o": ["6:8", "5:2", "7:7", "4:3"], "a": "6:8", "s": ""}, {"type": "single", "q": "弥迦责备的首领为什么行审判？", "o": ["为贿赂", "为公义", "为敬畏神", "为百姓"], "a": "为贿赂", "s": ""}, {"type": "single", "q": "弥迦书预言哪两座城因罪受审判？", "o": ["撒玛利亚和耶路撒冷", "尼尼微和巴比伦", "所多玛和蛾摩拉", "推罗和西顿"], "a": "撒玛利亚和耶路撒冷", "s": ""}, {"type": "single", "q": "“将刀打成犁头”描绘的是什么景象？", "o": ["和平", "战争", "饥荒", "审判"], "a": "和平", "s": ""}, {"type": "single", "q": "弥迦书末了强调神的什么属性？", "o": ["赦免与信实", "愤怒", "遗忘", "偏心"], "a": "赦免与信实", "s": ""}, {"type": "multiple", "q": "神向人所要的是什么？", "o": ["行公义", "好怜悯", "存谦卑的心与神同行", "千千的公羊"], "a": "行公义,好怜悯,存谦卑的心与神同行", "s": ""}, {"type": "multiple", "q": "弥迦责备了哪些人？", "o": ["首领", "祭司", "先知", "农夫"], "a": "首领,祭司,先知", "s": ""}, {"type": "multiple", "q": "弥迦书关于基督的预言包括？", "o": ["生于伯利恒", "在以色列中作掌权者", "根源从亘古从太初就有", "生于拿撒勒"], "a": "生于伯利恒,在以色列中作掌权者,根源从亘古从太初就有", "s": ""}, {"type": "multiple", "q": "神赦免的应许包括？", "o": ["不永远怀怒", "喜爱施恩", "将罪投于深海", "永不赦免"], "a": "不永远怀怒,喜爱施恩,将罪投于深海", "s": ""}, {"type": "judge", "q": "弥迦与以赛亚是同时代的先知。", "a": "对", "s": ""}, {"type": "judge", "q": "弥迦预言基督生于拿撒勒。", "a": "错", "s": ""}, {"type": "judge", "q": "神喜悦千千的公羊过于公义怜悯。", "a": "错", "s": ""}, {"type": "judge", "q": "弥迦说“至于我，我要仰望耶和华”。", "a": "对", "s": ""}, {"type": "judge", "q": "弥迦书共有七章。", "a": "对", "s": ""}, {"type": "judge", "q": "神应许将我们的罪投于深海。", "a": "对", "s": ""}, {"type": "judge", "q": "弥迦书只预言审判，没有复兴的应许。", "a": "错", "s": ""}, {"type": "essay", "q": "弥迦书5:2的预言如何应验在基督身上？", "a": "弥迦预言基督生于伯利恒以法他，在以色列中作掌权者，且根源从亘古就有。马太福音2章记载耶稣生于伯利恒，文士引用此预言回答希律，显明耶稣就是那位从太初就有的弥赛亚君王。", "s": ""}, {"type": "essay", "q": "“行公义，好怜悯，存谦卑的心与神同行”对今日信徒有何意义？", "a": "神看重内心的顺服过于外表的祭物。今日信徒也当活出公义正直、怜悯他人、谦卑依靠神的生命，而不是以宗教仪式代替真实的敬虔，这是神向历代圣徒不变的要求。", "s": ""}, {"type": "essay", "q": "弥迦书如何平衡神的审判与怜悯？", "a": "前三章严厉宣告撒玛利亚和耶路撒冷因罪受审判，中间应许末后复兴与基督降生，末了以神赦免罪孽、将罪投于深海作结。审判显明神的圣洁公义，赦免显明祂的慈爱信实，两者在十字架上完全调和。", "s": ""}]','','study','[{"title": "审判的宣告（1-3章）", "points": ["为撒玛利亚和耶路撒冷的罪哀号", "首领为贿赂行审判，祭司为雇价施训诲", "先知为银钱行占卜", "锡安必被耕种像田地", "耶路撒冷必变为乱堆", "假先知为饼说平安"]}, {"title": "复兴的应许（4-5章）", "points": ["末后耶和华殿的山必坚立", "万民都要流归这山", "将刀打成犁头，把枪打成镰刀", "伯利恒必生出掌权者（5:2）", "祂的根源从亘古从太初就有", "余民必归回，神作王治理"]}, {"title": "神的要求（6章）", "points": ["耶和华与以色列争辩", "岂是千千的公羊、万万的油河", "行公义，好怜悯（6:8）", "存谦卑的心与神同行（6:8）", "不以祭物代替顺服", "神已指示何为善"]}, {"title": "悔改与信靠（7章）", "points": ["先知为百姓的败坏哀叹", "至于我，我要仰望耶和华（7:7）", "要等候那救我的神", "虽跌倒，仍要起来", "仇敌的羞辱终必过去"]}, {"title": "赦免与信实（7:18-20）", "points": ["有何神像你，赦免罪孽（7:18）", "不永远怀怒，喜爱施恩", "将罪投于深海", "按古时向列祖起誓施信实与雅各", "施慈爱与亚伯拉罕"]}]','','64','旧约•小先知书（十二小先知书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224205196','圣经导览','那鸿书','那鸿书宣告尼尼微的倾覆。约拿时代尼尼微曾悔改，百年后又恶贯满盈。先知显明神是忌邪施报的神，也是患难中的保障（1:7），本书见证神公义的审判与对祂子民的安慰。','[{"type": "verse", "q": "【经文填空】耶和华本为________，在患难的日子为人的________，并且认得那些投靠他的人。", "a": "善|保障", "ref": "《那鸿书》1章7节", "s": "", "o": "那鸿书1章7节"}, {"type": "verse", "q": "【经文填空】耶和华不轻易________，大有能力，万不以________的为无罪。", "a": "发怒|有罪", "ref": "《那鸿书》1章3节", "s": "", "o": "那鸿书1章3节"}, {"type": "verse", "q": "【经文填空】看哪，有________传平安之人的脚登山。", "a": "报好信", "ref": "《那鸿书》1章15节", "s": "", "o": "那鸿书1章15节"}, {"type": "verse", "q": "【经文填空】________之耶和华说：我与你为敌。", "a": "万军", "ref": "《那鸿书》2章13节", "s": "", "o": "那鸿书2章13节"}, {"type": "verse", "q": "【经文填空】祸哉，这________的城，充满谎诈和强暴。", "a": "流人血", "ref": "《那鸿书》3章1节", "s": "", "o": "那鸿书3章1节"}, {"type": "verse", "q": "【经文填空】耶和华是________施报的神。", "a": "忌邪", "ref": "《那鸿书》1章2节", "s": "", "o": "那鸿书1章2节"}, {"type": "verse", "q": "【经文填空】你的损伤无法________，你的伤痕极其重大。", "a": "医治", "ref": "《那鸿书》3章19节", "s": "", "o": "那鸿书3章19节"}, {"type": "fill", "q": "那鸿书预言________城的倾覆。", "a": "尼尼微", "s": ""}, {"type": "fill", "q": "那鸿是________人。", "a": "伊勒歌斯", "s": ""}, {"type": "fill", "q": "那鸿书共________章。", "a": "三|3", "s": ""}, {"type": "fill", "q": "尼尼微是________国的首都。", "a": "亚述", "s": ""}, {"type": "fill", "q": "约拿时代尼尼微曾________，百年后又堕落。", "a": "悔改", "s": ""}, {"type": "fill", "q": "神说尼尼微如________初熟的果子被摇落。", "a": "无花果树", "s": ""}, {"type": "fill", "q": "那鸿以________的倾覆为鉴戒。", "a": "挪亚蒙", "s": ""}, {"type": "fill", "q": "神应许犹大可以守________，还所许的愿。", "a": "节期", "s": ""}, {"type": "fill", "q": "凡听见尼尼微消息的，必都________。", "a": "拍掌", "s": ""}, {"type": "fill", "q": "尼尼微的勇士________，满面羞惭。", "a": "战兢", "s": ""}, {"type": "single", "q": "那鸿书预言哪座城倾覆？", "o": ["尼尼微", "巴比伦", "耶路撒冷", "大马士革"], "a": "尼尼微", "s": ""}, {"type": "single", "q": "尼尼微是哪个国家的首都？", "o": ["亚述", "巴比伦", "波斯", "埃及"], "a": "亚述", "s": ""}, {"type": "single", "q": "“耶和华本为善”出自哪一节？", "o": ["1:7", "1:3", "2:13", "3:19"], "a": "1:7", "s": ""}, {"type": "single", "q": "那鸿是哪里人？", "o": ["伊勒歌斯", "摩利沙", "提哥亚", "伯利恒"], "a": "伊勒歌斯", "s": ""}, {"type": "single", "q": "尼尼微曾因哪位先知传警告而悔改？", "o": ["约拿", "弥迦", "那鸿", "以利亚"], "a": "约拿", "s": ""}, {"type": "single", "q": "神说尼尼微像什么果子被摇落？", "o": ["无花果初熟的果子", "葡萄", "橄榄", "石榴"], "a": "无花果初熟的果子", "s": ""}, {"type": "single", "q": "那鸿书给犹大带来什么信息？", "o": ["安慰", "审判", "被掳", "咒诅"], "a": "安慰", "s": ""}, {"type": "multiple", "q": "那鸿书显明神的哪些属性？", "o": ["忌邪施报", "不轻易发怒", "本为善", "以有罪的为无罪"], "a": "忌邪施报,不轻易发怒,本为善", "s": ""}, {"type": "multiple", "q": "尼尼微的罪包括？", "o": ["流人血", "谎诈强暴", "淫行邪术", "真心悔改"], "a": "流人血,谎诈强暴,淫行邪术", "s": ""}, {"type": "multiple", "q": "尼尼微倾覆的景象包括？", "o": ["勇士羞惭", "财宝被掳掠", "宫殿冲没", "更加兴盛"], "a": "勇士羞惭,财宝被掳掠,宫殿冲没", "s": ""}, {"type": "multiple", "q": "那鸿书给信徒的安慰包括？", "o": ["神是患难中的保障", "神认得投靠祂的人", "报好信之人的脚登山", "神不审判恶人"], "a": "神是患难中的保障,神认得投靠祂的人,报好信之人的脚登山", "s": ""}, {"type": "judge", "q": "那鸿书预言巴比伦的倾覆。", "a": "错", "s": ""}, {"type": "judge", "q": "尼尼微曾因约拿的警告悔改。", "a": "对", "s": ""}, {"type": "judge", "q": "神是忌邪施报的神。", "a": "对", "s": ""}, {"type": "judge", "q": "“耶和华本为善”出自那鸿书。", "a": "对", "s": ""}, {"type": "judge", "q": "那鸿书共有三章。", "a": "对", "s": ""}, {"type": "judge", "q": "神应许尼尼微永不倾覆。", "a": "错", "s": ""}, {"type": "judge", "q": "那鸿书只有审判，没有对神子民的安慰。", "a": "错", "s": ""}, {"type": "essay", "q": "约拿书与那鸿书都论到尼尼微，两书信息有何异同？", "a": "同：都论及尼尼微这座亚述大城，显明神掌管列国。异：约拿书是神差遣先知传警告，尼尼微悔改蒙赦免，主题是神的怜悯临到外邦；那鸿书是百年后尼尼微重陷罪恶，神宣告其倾覆，主题是神公义的审判。两书合在一起显明：神给悔改的机会，也必审判终不悔改者。", "s": ""}, {"type": "essay", "q": "“耶和华本为善，在患难的日子为人的保障”对受苦信徒有何安慰？", "a": "当神子民受亚述欺压时，那鸿宣告神是良善的，是患难中的保障，且认得投靠祂的人。对今日受苦的信徒，这是极大的安慰：神不忘记属祂的人，祂的良善与保护是患难中的避难所，公义的审判终必来到。", "s": ""}, {"type": "essay", "q": "从尼尼微的倾覆看神公义审判的必然性。", "a": "尼尼微曾蒙怜悯却重蹈罪恶，流人血、行邪术、欺压列国，罪恶满盈。神是忌邪施报、不以有罪为无罪的神，审判虽迟到但必然来到。警戒我们不可滥用神的宽容，当趁蒙怜悯时真心悔改。", "s": ""}]','','study','[{"title": "神的属性（1章）", "points": ["耶和华是忌邪施报的神", "不轻易发怒，大有能力", "万不以有罪的为无罪", "耶和华本为善（1:7）", "在患难的日子为人的保障", "认得那些投靠他的人"]}, {"title": "尼尼微的罪", "points": ["曾因约拿悔改，后又堕落", "流人血的城，充满谎诈强暴", "行邪术，多有淫行", "欺压列国，残暴成性", "设谋攻击耶和华"]}, {"title": "倾覆的预言（2章）", "points": ["尼尼微的勇士满面羞惭", "城门被攻破，宫殿冲没", "财宝被掳掠一空", "如狮子洞穴变为荒场", "万军之耶和华与她为敌"]}, {"title": "审判的原因（3章）", "points": ["祸哉，这流人血的城", "因淫行邪术迷惑列国", "神必揭露她的羞耻", "像无花果初熟的果子被摇落", "以挪亚蒙的倾覆为鉴戒"]}, {"title": "安慰与警戒", "points": ["对犹大：报好信之人的脚登山", "神为受欺压者伸冤", "公义审判终必来到", "警戒：罪恶满盈必受报", "投靠神的人得保障"]}]','','65','旧约•小先知书（十二小先知书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224220233','圣经导览','哈巴谷书','哈巴谷书记录先知与神的辩论：恶人猖狂、公义颠倒，神竟用更恶的迦勒底人施行审判。神宣告“义人必因信得生”（2:4），先知终以“虽然无花果树不发旺，我却因耶和华欢欣”作结。','[{"type": "verse", "q": "【经文填空】迦勒底人自高自大，心不正直；惟________必因信得生。", "a": "义人", "ref": "《哈巴谷书》2章4节", "s": "", "o": "哈巴谷书2章4节"}, {"type": "verse", "q": "【经文填空】虽然________不发旺，葡萄树不结果……然而，我要因耶和华________，因救我的神喜乐。", "a": "无花果树|欢欣", "ref": "《哈巴谷书》3章17-18节", "s": "", "o": "哈巴谷书3章17节"}, {"type": "verse", "q": "【经文填空】惟耶和华在他的________中；全地的人都当在他面前肃敬静默。", "a": "圣殿", "ref": "《哈巴谷书》2章20节", "s": "", "o": "哈巴谷书2章20节"}, {"type": "verse", "q": "【经文填空】认识耶和华荣耀的知识要充满遍地，好像________充满洋海一般。", "a": "水", "ref": "《哈巴谷书》2章14节", "s": "", "o": "哈巴谷书2章14节"}, {"type": "verse", "q": "【经文填空】主耶和华是我的________；他使我的脚快如母鹿的蹄，又使我稳行在高处。", "a": "力量", "ref": "《哈巴谷书》3章19节", "s": "", "o": "哈巴谷书3章19节"}, {"type": "verse", "q": "【经文填空】你眼目________，不看邪僻，不看奸恶。", "a": "清洁", "ref": "《哈巴谷书》1章13节", "s": "", "o": "哈巴谷书1章13节"}, {"type": "verse", "q": "【经文填空】将这默示________地写在版上，使读的人容易读。", "a": "明明", "ref": "《哈巴谷书》2章2节", "s": "", "o": "哈巴谷书2章2节"}, {"type": "fill", "q": "神兴起________人审判犹大。", "a": "迦勒底", "s": ""}, {"type": "fill", "q": "哈巴谷书共________章。", "a": "三|3", "s": ""}, {"type": "fill", "q": "先知站在________上，观看神要对他说什么。", "a": "望楼", "s": ""}, {"type": "fill", "q": "迦勒底人比________更快，比晚上的狼更猛。", "a": "豹", "s": ""}, {"type": "fill", "q": "神说迦勒底人以自己的________为神。", "a": "势力", "s": ""}, {"type": "fill", "q": "哈巴谷求神在________复兴祂的作为。", "a": "这些年间", "s": ""}, {"type": "fill", "q": "先知说神从________而来，圣者从巴兰山临到。", "a": "提幔", "s": ""}, {"type": "fill", "q": "保罗在罗马书引用“义人必因信得生”论证________的真理。", "a": "因信称义", "s": ""}, {"type": "fill", "q": "先知说虽然田地不出________，他仍要欢欣。", "a": "粮食", "s": ""}, {"type": "fill", "q": "哈巴谷书的体裁是先知与神的________。", "a": "辩论", "s": ""}, {"type": "single", "q": "神兴起哪个民族审判犹大？", "o": ["迦勒底", "亚述", "埃及", "波斯"], "a": "迦勒底", "s": ""}, {"type": "single", "q": "“义人必因信得生”出自哪一章？", "o": ["2章", "1章", "3章", "4章"], "a": "2章", "s": ""}, {"type": "single", "q": "先知在哪里等候神的回答？", "o": ["望楼", "圣殿", "山顶", "旷野"], "a": "望楼", "s": ""}, {"type": "single", "q": "哈巴谷书共有几章？", "o": ["3", "4", "5", "7"], "a": "3", "s": ""}, {"type": "single", "q": "“虽然无花果树不发旺”出自哪一章？", "o": ["3章", "1章", "2章", "4章"], "a": "3章", "s": ""}, {"type": "single", "q": "保罗在《罗马书》中引用了哈巴谷书哪句话？", "o": ["义人必因信得生", "耶和华本为善", "行公义好怜悯", "救恩出于耶和华"], "a": "义人必因信得生", "s": ""}, {"type": "single", "q": "迦勒底人以什么为神？", "o": ["自己的势力", "金牛犊", "巴力", "亚舍拉"], "a": "自己的势力", "s": ""}, {"type": "multiple", "q": "先知向神质问的内容包括？", "o": ["恶人围困义人", "公义颠倒", "呼求而神不听", "神不圣洁"], "a": "恶人围困义人,公义颠倒,呼求而神不听", "s": ""}, {"type": "multiple", "q": "神对迦勒底人的描述包括？", "o": ["残忍暴躁", "比豹更快", "讥诮君王", "温柔良善"], "a": "残忍暴躁,比豹更快,讥诮君王", "s": ""}, {"type": "multiple", "q": "“五祸”针对哪些罪行？", "o": ["强暴", "贪婪", "醉酒", "怜悯"], "a": "强暴,贪婪,醉酒", "s": ""}, {"type": "multiple", "q": "先知在祷告中表达了什么？", "o": ["求神复兴作为", "发怒时以怜悯为念", "因耶和华欢欣", "咒诅仇敌"], "a": "求神复兴作为,发怒时以怜悯为念,因耶和华欢欣", "s": ""}, {"type": "judge", "q": "哈巴谷质问神为什么用义人审判恶人。", "a": "错", "s": ""}, {"type": "judge", "q": "“义人必因信得生”出自哈巴谷书2:4。", "a": "对", "s": ""}, {"type": "judge", "q": "哈巴谷书共有三章。", "a": "对", "s": ""}, {"type": "judge", "q": "神说迦勒底人是温柔良善的。", "a": "错", "s": ""}, {"type": "judge", "q": "先知最后说“然而我要因耶和华欢欣”。", "a": "对", "s": ""}, {"type": "judge", "q": "哈巴谷从未对神的公义发出疑问。", "a": "错", "s": ""}, {"type": "judge", "q": "保罗在新约中引用过哈巴谷书的话。", "a": "对", "s": ""}, {"type": "essay", "q": "“义人必因信得生”在新约中有何重要意义？", "a": "保罗在罗马书1:17、加拉太书3:11引用此经文，论证人称义不是靠行律法，而是因信。这是宗教改革“因信称义”教义的核心经文之一，显明从旧约到新约，神救人的原则始终是本乎恩、因着信。", "s": ""}, {"type": "essay", "q": "哈巴谷从质问到欢欣，信心经历了怎样的转变？", "a": "起初先知因恶人猖狂、神用更恶的迦勒底人审判而困惑质问；经神启示，他学会在望楼上等候、凭信心接受神的主权；末了他写下祷告之歌，即使一无所有仍因耶和华欢欣，信心从眼见转为超越环境的确信。", "s": ""}, {"type": "essay", "q": "神用更恶的迦勒底人审判犹大，这给你什么启发？", "a": "神的主权超越人的道德判断，祂可用不信者成就旨意，之后也必审判他们。启发：不可因恶人暂时兴旺而跌倒；神的时间和方式高过我们；当存敬畏等候祂的作为，而非按自己的标准要求神。", "s": ""}]','','study','[{"title": "先知的质问（1:1-4）", "points": ["恶人围困义人，公义颠倒", "先知呼求，神为何不听", "律法放松，公理显为屈枉", "强暴、争端、相斗的事", "信心的困惑与挣扎"]}, {"title": "神的回答（1:5-11）", "points": ["神兴起迦勒底人", "残忍暴躁，通行遍地", "比豹更快，比晚上的狼更猛", "讥诮君王，笑话保障", "以自己的势力为神"]}, {"title": "再问与等候（1:12-2:1）", "points": ["神圣洁，为何看恶人行奸恶", "迦勒底人比犹大更恶", "先知立在望楼上观看", "静默等候神的回答", "谦卑寻求的心"]}, {"title": "义人必因信得生（2:2-20）", "points": ["将默示明明写在版上", "惟义人因信得生（2:4）", "五祸：祸哉行强暴贪婪者", "认识耶和华的知识充满遍地", "耶和华在圣殿中，全地当静默"]}, {"title": "先知的祷告与凯歌（3章）", "points": ["求神在这些年间复兴作为", "发怒的时候以怜悯为念", "神从提幔而来，圣者从巴兰山临到", "虽然无花果树不发旺（3:17）", "然而我要因耶和华欢欣（3:18）", "主是我的力量，使我稳行高处"]}]','','66','旧约•小先知书（十二小先知书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224289983','圣经导览','西番雅书','约西亚王年间，王室后裔西番雅高喊耶和华的大日临近。神必审判犹大与列国，却应许留下困苦贫寒的余民，在锡安中间因你欢欣喜乐，末后领被赶散者归回聚集。这是审判中的安慰与盼望。','[{"type": "verse", "q": "【经文填空】你要在主耶和华面前________，因为耶和华的日子________。", "a": "静默无声|快到", "ref": "《西番雅书》1章7节", "s": "", "o": "西番雅书1章7节"}, {"type": "verse", "q": "【经文填空】耶和华的大日________，临近而且________。", "a": "临近|甚快", "ref": "《西番雅书》1章14节", "s": "", "o": "西番雅书1章14节"}, {"type": "verse", "q": "【经文填空】世上遵守耶和华典章的________哪，你们都当寻求耶和华！当寻求________，或者在耶和华发怒的日子可以隐藏起来。", "a": "谦卑人|公义谦卑", "ref": "《西番雅书》2章3节", "s": "", "o": "西番雅书2章3节"}, {"type": "verse", "q": "【经文填空】我却要在你中间留下________的民，他们必投靠我________。", "a": "困苦贫寒|耶和华的名", "ref": "《西番雅书》3章12节", "s": "", "o": "西番雅书3章12节"}, {"type": "verse", "q": "【经文填空】耶和华已经除去你的刑罚，________。以色列的王耶和华在你中间，你必不再________。", "a": "赶出你的仇敌|惧怕灾祸", "ref": "《西番雅书》3章15节", "s": "", "o": "西番雅书3章15节"}, {"type": "verse", "q": "【经文填空】耶和华你的神是________、大有能力的主。他在你中间必因你________，默然爱你，且因你喜乐而欢呼。", "a": "施行拯救|欢欣喜乐", "ref": "《西番雅书》3章17节", "s": "", "o": "西番雅书3章17节"}, {"type": "verse", "q": "【经文填空】当耶和华发怒的日子，他们的金银不能________。", "a": "救他们", "ref": "《西番雅书》1章18节", "s": "", "o": "西番雅书1章18节"}, {"type": "fill", "q": "西番雅在________王年间作先知。", "a": "约西亚", "s": ""}, {"type": "fill", "q": "西番雅是希西家的________，出身王室。", "a": "玄孙", "s": ""}, {"type": "fill", "q": "西番雅书的主题是耶和华的________临近。", "a": "日子", "s": ""}, {"type": "fill", "q": "西番雅劝勉不知羞耻的国民应当________，寻求耶和华。", "a": "聚集", "s": ""}, {"type": "fill", "q": "摩押和亚扪因________神的百姓而受审判。", "a": "毁谤辱骂", "s": ""}, {"type": "fill", "q": "尼尼微是________国的京城，神预言它变为荒凉。", "a": "亚述", "s": ""}, {"type": "fill", "q": "锡安的民应当歌唱、________，满心欢喜快乐。", "a": "欢呼", "s": ""}, {"type": "fill", "q": "神应许那时必领你们进来，________你们。", "a": "聚集", "s": ""}, {"type": "fill", "q": "西番雅书共有________章。", "a": "三", "s": ""}, {"type": "fill", "q": "西番雅的父亲名叫________。", "a": "古示", "s": ""}, {"type": "single", "q": "西番雅在哪个王年间作先知？", "o": ["约西亚", "希西家", "玛拿西", "约沙法"], "a": "约西亚", "s": ""}, {"type": "single", "q": "“耶和华的日子”主要指什么？", "o": ["节期", "审判的日子", "安息日", "禧年"], "a": "审判的日子", "s": ""}, {"type": "single", "q": "神应许在锡安中间留下哪种民？", "o": ["富足的民", "困苦贫寒的民", "骁勇的民", "有学问的民"], "a": "困苦贫寒的民", "s": ""}, {"type": "single", "q": "番3:17说神在你中间必因你怎样？", "o": ["发怒", "欢欣喜乐", "静默", "忧伤"], "a": "欢欣喜乐", "s": ""}, {"type": "single", "q": "摩押和亚扪受罚的原因是什么？", "o": ["拜偶像", "毁谤辱骂神的百姓", "不献祭", "不守安息日"], "a": "毁谤辱骂神的百姓", "s": ""}, {"type": "single", "q": "尼尼微是哪国的京城？", "o": ["巴比伦", "亚述", "波斯", "埃及"], "a": "亚述", "s": ""}, {"type": "single", "q": "西番雅书最后，神应许作什么？", "o": ["降灾", "领他们归回聚集", "分散他们", "静默不语"], "a": "领他们归回聚集", "s": ""}, {"type": "multiple", "q": "耶和华的日子临近，哪些将受审判？", "o": ["犹大", "耶路撒冷", "列国", "祭司家族"], "a": "犹大,耶路撒冷,列国", "s": ""}, {"type": "multiple", "q": "番2章提到神要审判哪些列国？", "o": ["非利士", "摩押", "亚扪", "以东"], "a": "非利士,摩押,亚扪", "s": ""}, {"type": "multiple", "q": "锡安的民应当怎样？", "o": ["歌唱", "欢呼", "满心欢喜快乐", "哭泣哀号"], "a": "歌唱,欢呼,满心欢喜快乐", "s": ""}, {"type": "multiple", "q": "神在余民中间要作什么？", "o": ["除去刑罚", "赶出仇敌", "与他们同在", "使他们被掳"], "a": "除去刑罚,赶出仇敌,与他们同在", "s": ""}, {"type": "judge", "q": "西番雅书的主题是“耶和华的日子”。", "a": "对", "s": ""}, {"type": "judge", "q": "西番雅在希西家年间作先知。", "a": "错", "s": ""}, {"type": "judge", "q": "神只审判犹大，不审判列国。", "a": "错", "s": ""}, {"type": "judge", "q": "神应许留下困苦贫寒的民投靠祂的名。", "a": "对", "s": ""}, {"type": "judge", "q": "番3:17说神必因锡安欢欣喜乐。", "a": "对", "s": ""}, {"type": "judge", "q": "摩押亚扪因善待以色列而蒙福。", "a": "错", "s": ""}, {"type": "judge", "q": "西番雅书共有四章。", "a": "错", "s": ""}, {"type": "essay", "q": "“耶和华的日子”是什么意思？对今日信徒有何提醒？", "a": "指神审判的日子，临近而且甚快。提醒信徒警醒预备、圣洁度日，不倚靠金银势力，唯投靠耶和华的名。", "s": ""}, {"type": "essay", "q": "番2:3劝勉谦卑人寻求耶和华，这对我们有何教导？", "a": "在神发怒的日子，惟谦卑寻求神、寻求公义的人可得隐藏。教导我们以谦卑亲近神，行公义，好在审判中蒙保守。", "s": ""}, {"type": "essay", "q": "番3:17描绘了神怎样的爱？", "a": "神是施行拯救大有能力的主，祂在我们中间因我们欢欣喜乐、默然爱我们、且因我们喜乐而欢呼。这是父亲般深情的爱，审判之后满有安慰。", "s": ""}]','','study','[{"title": "先知的背景（1:1）", "points": ["约西亚王年间作先知", "希西家的玄孙，出身王室", "犹大属灵光景败坏", "约西亚宗教改革之前", "神兴起先知发出警告"]}, {"title": "审判犹大（1:2-18）", "points": ["耶和华的日子临近", "神必除灭万类", "要在主面前静默无声", "大日临近而且甚快", "那日是急难困苦的日子", "金银不能救他们"]}, {"title": "劝勉与列国审判（2:1-15）", "points": ["不知羞耻的国民当聚集", "谦卑人当寻求耶和华", "审判非利士沿海之地", "摩押亚扪因毁谤受罚", "古实人被刀杀", "亚述尼尼微变为荒凉"]}, {"title": "耶路撒冷的罪（3:1-8）", "points": ["悖逆污秽欺压的城", "首领如吼叫的狮子", "先知轻浮诡诈", "祭司亵渎圣所", "神每日显明公义", "恶人不知羞耻", "等候神兴起审判"]}, {"title": "余民的复兴（3:9-20）", "points": ["万民同心求告耶和华", "留下困苦贫寒的民", "投靠耶和华的名", "除去刑罚赶出仇敌", "神因你欢欣喜乐（3:17）", "领被赶散者归回聚集"]}]','','67','旧约•小先知书（十二小先知书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224289984','圣经导览','哈该书','被掳归回十六年，圣殿依然荒凉，百姓却各顾自己的房屋。哈该奉命呼喊你们要省察行为，激动所罗巴伯与约书亚的心重新动工。神应许这殿后来的荣耀必大过先前，从这日起必赐福，并以所罗巴伯为印。','[{"type": "verse", "q": "【经文填空】这殿仍然________，你们各人却顾自己的________吗？", "a": "荒凉|房屋", "ref": "《哈该书》1章4节", "s": "", "o": "哈该书1章4节"}, {"type": "verse", "q": "【经文填空】现在万军之耶和华如此说：你们要________。", "a": "省察自己的行为", "ref": "《哈该书》1章5节", "s": "", "o": "哈该书1章5节"}, {"type": "verse", "q": "【经文填空】你们要上山取木料，________这殿，我就因此欢喜，也被________。", "a": "建造|荣耀", "ref": "《哈该书》1章8节", "s": "", "o": "哈该书1章8节"}, {"type": "verse", "q": "【经文填空】你们盼望多得，所得的却________。", "a": "少", "ref": "《哈该书》1章9节", "s": "", "o": "哈该书1章9节"}, {"type": "verse", "q": "【经文填空】所罗巴伯啊，你当________！这地的百姓，你们都当________做工，因为我与你们同在。", "a": "刚强|刚强", "ref": "《哈该书》2章4节", "s": "", "o": "哈该书2章4节"}, {"type": "verse", "q": "【经文填空】这殿后来的荣耀必大过________的荣耀。", "a": "先前", "ref": "《哈该书》2章9节", "s": "", "o": "哈该书2章9节"}, {"type": "verse", "q": "【经文填空】我仆人撒拉铁的儿子所罗巴伯啊，我必以你为________，因我拣选了你。", "a": "印", "ref": "《哈该书》2章23节", "s": "", "o": "哈该书2章23节"}, {"type": "fill", "q": "哈该在________王第二年传讲信息。", "a": "大流士", "s": ""}, {"type": "fill", "q": "归回的百姓说建造耶和华殿的时候________。", "a": "尚未来到", "s": ""}, {"type": "fill", "q": "神借哈该责备百姓只顾自己的房屋，让圣殿________。", "a": "荒凉", "s": ""}, {"type": "fill", "q": "省长________和大祭司约书亚听从了哈该的话。", "a": "所罗巴伯", "s": ""}, {"type": "fill", "q": "百姓盼望多得所得却少，因为神________。", "a": "吹去", "s": ""}, {"type": "fill", "q": "神应许“我必________天地、海和旱地”。", "a": "震动", "s": ""}, {"type": "fill", "q": "万国的珍宝必运来，这殿的荣耀必________。", "a": "大过先前", "s": ""}, {"type": "fill", "q": "神以所罗巴伯为________，表明拣选。", "a": "印", "s": ""}, {"type": "fill", "q": "哈该书共有________章。", "a": "二", "s": ""}, {"type": "fill", "q": "从这日起，神必________你们。", "a": "赐福", "s": ""}, {"type": "single", "q": "哈该在哪个王年间传道？", "o": ["古列", "大流士", "亚达薛西", "亚哈随鲁"], "a": "大流士", "s": ""}, {"type": "single", "q": "百姓不建殿的借口是什么？", "o": ["没有材料", "时候尚未来到", "没有工人", "没有钱财"], "a": "时候尚未来到", "s": ""}, {"type": "single", "q": "当时犹大的省长是谁？", "o": ["所罗巴伯", "尼希米", "以斯拉", "约书亚"], "a": "所罗巴伯", "s": ""}, {"type": "single", "q": "当时的大祭司是谁？", "o": ["以利亚撒", "约书亚", "非尼哈", "撒督"], "a": "约书亚", "s": ""}, {"type": "single", "q": "神要百姓省察什么？", "o": ["奉献", "自己的行为", "祷告", "禁食"], "a": "自己的行为", "s": ""}, {"type": "single", "q": "这殿后来的荣耀怎样？", "o": ["不如先前", "大过先前", "与先前一样", "归于无有"], "a": "大过先前", "s": ""}, {"type": "single", "q": "神以所罗巴伯为什么？", "o": ["为王", "为印", "为祭司", "为先知"], "a": "为印", "s": ""}, {"type": "multiple", "q": "百姓遭遇哪些缺乏？", "o": ["撒多种收少", "吃不饱", "喝不足", "衣不暖"], "a": "撒多种收少,吃不饱,喝不足,衣不暖", "s": ""}, {"type": "multiple", "q": "神应许与谁同在？", "o": ["所罗巴伯", "约书亚", "剩下的百姓", "外邦君王"], "a": "所罗巴伯,约书亚,剩下的百姓", "s": ""}, {"type": "multiple", "q": "建殿的信息临到哪些人？", "o": ["所罗巴伯", "约书亚", "剩下的百姓", "撒玛利亚人"], "a": "所罗巴伯,约书亚,剩下的百姓", "s": ""}, {"type": "multiple", "q": "神说祂必震动什么？", "o": ["天", "地", "海", "旱地"], "a": "天,地,海,旱地", "s": ""}, {"type": "judge", "q": "哈该责备百姓只顾自己的房屋，不顾神的殿。", "a": "对", "s": ""}, {"type": "judge", "q": "百姓听从哈该的话，重新动工建殿。", "a": "对", "s": ""}, {"type": "judge", "q": "神说这殿后来的荣耀必不如先前。", "a": "错", "s": ""}, {"type": "judge", "q": "所罗巴伯是当时的省长。", "a": "对", "s": ""}, {"type": "judge", "q": "神应许从这日起必赐福他们。", "a": "对", "s": ""}, {"type": "judge", "q": "哈该书共有三章。", "a": "错", "s": ""}, {"type": "judge", "q": "神以所罗巴伯为印，表明拣选。", "a": "对", "s": ""}, {"type": "essay", "q": "“你们要省察自己的行为”对今日信徒有何意义？", "a": "提醒我们定期反省：是否把神放在首位，还是只顾自己的事。生活的缺乏有时是神管教的信号，当回转归向神、先求祂的国。", "s": ""}, {"type": "essay", "q": "百姓说“时候尚未来到”，这反映什么属灵光景？", "a": "反映以借口拖延顺服，把神的事放在次要。十六年过去殿仍荒凉，显明不是时候未到，而是心未到。今日我们也当警醒，勿以忙碌为借口忽略神的工。", "s": ""}, {"type": "essay", "q": "神为何以所罗巴伯为印？", "a": "印代表权柄与拣选。所罗巴伯是大卫后裔、弥赛亚谱系中的一环，神借此应许延续大卫之约，显明神的救赎计划不因被掳中断。", "s": ""}]','','study','[{"title": "建殿的呼召（1:1-11）", "points": ["大流士王第二年六月初一日", "时候尚未来到的借口", "殿荒凉却顾自己房屋", "你们要省察行为", "撒多种收的却少", "吃不饱喝不足衣不暖", "神吹去他们的劳碌"]}, {"title": "百姓顺从动工（1:12-15）", "points": ["所罗巴伯约书亚听从", "剩下百姓都敬畏耶和华", "神激动他们的心", "我与你们同在", "六月二十四日动工", "顺服带来同在"]}, {"title": "圣殿的荣耀（2:1-9）", "points": ["七月二十一日的话", "刚强壮胆做工", "我与你们同在", "我必震动天地", "万国珍宝必运来", "后来荣耀大过先前", "在这地方必赐平安"]}, {"title": "圣洁与祝福（2:10-19）", "points": ["九月二十四日的话", "圣洁不能传染", "污秽却能传染", "从前没有出产", "从这日起必赐福", "顺服是蒙福转折点"]}, {"title": "所罗巴伯的应许（2:20-23）", "points": ["同日第二次的话", "震动天地万国", "倾覆列国的宝座", "以你为印", "因我拣选了你", "大卫之约的延续"]}]','','68','旧约•小先知书（十二小先知书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224289985','圣经导览','撒迦利亚书','与哈该同时期的先知，以八异象安慰归回的百姓。金灯台、洁净的大祭司、不是倚靠势力乃是倚靠神的灵；更预言王骑驴而来、三十块钱、被扎仰望，末后耶和华必作全地的王。异象与预言交织，满有弥赛亚盼望。','[{"type": "verse", "q": "【经文填空】你们要________我，我就必________你们。", "a": "转向|转向", "ref": "《撒迦利亚书》1章3节", "s": "", "o": "撒迦利亚书1章3节"}, {"type": "verse", "q": "【经文填空】不是倚靠________，不是倚靠________，乃是倚靠我的灵方能成事。", "a": "势力|才能", "ref": "《撒迦利亚书》4章6节", "s": "", "o": "撒迦利亚书4章6节"}, {"type": "verse", "q": "【经文填空】看哪，你的王来到你这里！他是公义的，并且施行拯救，________地骑着驴。", "a": "谦谦和和", "ref": "《撒迦利亚书》9章9节", "s": "", "o": "撒迦利亚书9章9节"}, {"type": "verse", "q": "【经文填空】他们就秤了________作为我的工价。", "a": "三十块钱", "ref": "《撒迦利亚书》11章12节", "s": "", "o": "撒迦利亚书11章12节"}, {"type": "verse", "q": "【经文填空】他们必仰望我，就是他们所________的。", "a": "扎", "ref": "《撒迦利亚书》12章10节", "s": "", "o": "撒迦利亚书12章10节"}, {"type": "verse", "q": "【经文填空】________牧人，羊就分散了。", "a": "击打", "ref": "《撒迦利亚书》13章7节", "s": "", "o": "撒迦利亚书13章7节"}, {"type": "verse", "q": "【经文填空】耶和华必作________的王。", "a": "全地", "ref": "《撒迦利亚书》14章9节", "s": "", "o": "撒迦利亚书14章9节"}, {"type": "fill", "q": "撒迦利亚与________同时期作先知，鼓励建殿。", "a": "哈该", "s": ""}, {"type": "fill", "q": "撒迦利亚书前八章共有________个异象。", "a": "八", "s": ""}, {"type": "fill", "q": "金灯台旁有两棵________树。", "a": "橄榄", "s": ""}, {"type": "fill", "q": "大祭司________在异象中衣服污秽，神除去他的罪孽。", "a": "约书亚", "s": ""}, {"type": "fill", "q": "飞行的书卷长________肘，宽十肘。", "a": "二十", "s": ""}, {"type": "fill", "q": "四辆车从两山中间出来，山是________山。", "a": "铜", "s": ""}, {"type": "fill", "q": "神应许“我要作耶路撒冷四围的________”。", "a": "火城", "s": ""}, {"type": "fill", "q": "牧人被卖三十块钱，预表________被卖。", "a": "基督", "s": ""}, {"type": "fill", "q": "末后列国必上来攻击________。", "a": "耶路撒冷", "s": ""}, {"type": "fill", "q": "那日必有________从耶路撒冷流出来。", "a": "活水", "s": ""}, {"type": "single", "q": "与撒迦利亚同时期的先知是谁？", "o": ["哈该", "玛拉基", "西番雅", "俄巴底亚"], "a": "哈该", "s": ""}, {"type": "single", "q": "“不是倚靠势力……乃是倚靠什么方能成事？”", "o": ["智慧", "我的灵", "军队", "财富"], "a": "我的灵", "s": ""}, {"type": "single", "q": "预言中的王骑什么进耶路撒冷？", "o": ["马", "驴", "骆驼", "战车"], "a": "驴", "s": ""}, {"type": "single", "q": "牧人的工价是多少？", "o": ["五十块钱", "三十块钱", "二十块钱", "十块钱"], "a": "三十块钱", "s": ""}, {"type": "single", "q": "金灯台旁的两棵树是什么树？", "o": ["橄榄树", "无花果树", "葡萄树", "香柏树"], "a": "橄榄树", "s": ""}, {"type": "single", "q": "神要作耶路撒冷四围的什么？", "o": ["铜墙", "火城", "高山", "深壕"], "a": "火城", "s": ""}, {"type": "single", "q": "撒迦利亚书共有几章？", "o": ["十二章", "十三章", "十四章", "十章"], "a": "十四章", "s": ""}, {"type": "multiple", "q": "撒迦利亚的异象包括哪些？", "o": ["骑马者", "金灯台", "飞行的书卷", "四辆车"], "a": "骑马者,金灯台,飞行的书卷,四辆车", "s": ""}, {"type": "multiple", "q": "哪些预言应验在基督身上？", "o": ["骑驴进京", "三十块钱被卖", "被扎仰望", "击打牧人羊分散"], "a": "骑驴进京,三十块钱被卖,被扎仰望,击打牧人羊分散", "s": ""}, {"type": "multiple", "q": "神应许耶路撒冷什么？", "o": ["作四围的火城", "荣耀在其中", "万民归向耶和华", "被毁灭"], "a": "作四围的火城,荣耀在其中,万民归向耶和华", "s": ""}, {"type": "multiple", "q": "末后耶和华作王时有何景象？", "o": ["活水流出", "不再有咒诅", "耶和华独一无二", "永恒黑夜"], "a": "活水流出,不再有咒诅,耶和华独一无二", "s": ""}, {"type": "judge", "q": "撒迦利亚与哈该同时期鼓励百姓建殿。", "a": "对", "s": ""}, {"type": "judge", "q": "“不是倚靠势力，乃是倚靠我的灵”是撒迦利亚书的名言。", "a": "对", "s": ""}, {"type": "judge", "q": "三十块钱的预言与犹大卖耶稣有关。", "a": "对", "s": ""}, {"type": "judge", "q": "撒迦利亚书共有十二章。", "a": "错", "s": ""}, {"type": "judge", "q": "异象中大祭司约书亚的污秽衣服被除去。", "a": "对", "s": ""}, {"type": "judge", "q": "神应许作耶路撒冷四围的火城。", "a": "对", "s": ""}, {"type": "judge", "q": "撒迦利亚书没有提到弥赛亚。", "a": "错", "s": ""}, {"type": "essay", "q": "亚4:6“不是倚靠势力……乃是倚靠我的灵”对今日事奉有何教导？", "a": "事奉的果效不在乎人的势力才能，而在乎圣灵的工作。建殿如此，今日传福音、建造教会也如此，当倚靠圣灵而非人的方法。", "s": ""}, {"type": "essay", "q": "撒迦利亚书中有哪些弥赛亚预言？有何意义？", "a": "王骑驴而来（9:9）、三十块钱被卖（11:12）、被扎仰望（12:10）、击打牧人（13:7）。这些精确预言显明耶稣就是弥赛亚，神的救赎计划早已命定。", "s": ""}, {"type": "essay", "q": "八异象带给被掳归回的百姓什么安慰？", "a": "神仍眷顾耶路撒冷，除去罪孽，圣灵同在建殿，列国受审判，神作火城保护。让灰心百姓看见神掌权、有盼望，刚强做工。", "s": ""}]','','study','[{"title": "归回的呼召（1:1-6）", "points": ["大流士王第二年八月", "易多的孙子比利家的儿子", "你们要转向我", "列祖在哪里呢", "先知能永远存活吗", "我的言语临到列祖", "神的话不徒然返回"]}, {"title": "八异象（1:7-6:15）", "points": ["骑马者巡查全地", "四个角与四个匠人", "持准绳量耶路撒冷", "约书亚污衣被除去", "金灯台与两橄榄树", "不是倚靠势力乃倚靠灵", "飞行书卷除罪", "量器中妇人被带走", "四辆车巡行全地"]}, {"title": "禁食与真理（7-8章）", "points": ["伯特利人问禁食", "你们禁食是为我吗", "当行诚实公义", "神为锡安心里火热", "老人孩童街上安居", "余民得地为业", "万民来求告耶和华"]}, {"title": "弥赛亚预言（9-11章）", "points": ["王骑驴而来（9:9）", "锡安的民当欢乐", "三十块钱的工价", "丢给窑户", "击打牧人羊分散", "两分的杖折断"]}, {"title": "耶和华作王（12-14章）", "points": ["耶路撒冷作杯和重石", "仰望所扎的哀哭", "击打牧人羊分散", "活水从耶路撒冷流出", "不再有咒诅", "耶和华作全地的王", "万民上耶路撒冷守住棚节"]}]','','69','旧约•小先知书（十二小先知书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224289986','圣经导览','玛拉基书','旧约最后一卷，神六次发问、百姓六次顶撞。从轻慢的祭物、诡诈的婚姻到抢夺的奉献，神呼唤归回；炼金之人的火必洁净，十一奉献者必蒙倾福。应许以利亚先来、公义日头出现，为新约铺路。','[{"type": "verse", "q": "【经文填空】以扫不是雅各的________吗？我却爱________，恶以扫。", "a": "哥哥|雅各", "ref": "《玛拉基书》1章2节", "s": "", "o": "玛拉基书1章2节"}, {"type": "verse", "q": "【经文填空】从日出之地到日落之处，我的________在外邦中必尊为大。", "a": "名", "ref": "《玛拉基书》1章11节", "s": "", "o": "玛拉基书1章11节"}, {"type": "verse", "q": "【经文填空】耶和华以色列的神说：________是他所恨恶的。", "a": "休妻的事", "ref": "《玛拉基书》2章16节", "s": "", "o": "玛拉基书2章16节"}, {"type": "verse", "q": "【经文填空】他来的日子，谁能当得起呢？他如________的火，如漂布之人的碱。", "a": "炼金之人", "ref": "《玛拉基书》3章2节", "s": "", "o": "玛拉基书3章2节"}, {"type": "verse", "q": "【经文填空】你们要将当纳的________全然送入仓库，以此________我。", "a": "十分之一|试试", "ref": "《玛拉基书》3章10节", "s": "", "o": "玛拉基书3章10节"}, {"type": "verse", "q": "【经文填空】必有________出现，其光线有医治之能。", "a": "公义的日头", "ref": "《玛拉基书》4章2节", "s": "", "o": "玛拉基书4章2节"}, {"type": "verse", "q": "【经文填空】看哪，耶和华大而可畏之日未到以前，我必差遣先知________到你们那里去。", "a": "以利亚", "ref": "《玛拉基书》4章5节", "s": "", "o": "玛拉基书4章5节"}, {"type": "fill", "q": "玛拉基的意思是“________”。", "a": "我的使者", "s": ""}, {"type": "fill", "q": "神说“我曾________你们”，百姓却问在何事上爱我们。", "a": "爱", "s": ""}, {"type": "fill", "q": "祭司将瞎眼瘸腿的献上，神说这是________。", "a": "恶", "s": ""}, {"type": "fill", "q": "神恨恶________，因婚姻是盟约。", "a": "休妻", "s": ""}, {"type": "fill", "q": "你们要将当纳的十分之一全然送入________。", "a": "仓库", "s": ""}, {"type": "fill", "q": "神应许敞开天窗倾福，甚至________。", "a": "无处可容", "s": ""}, {"type": "fill", "q": "敬畏神的人，神为他们记________。", "a": "纪念册", "s": ""}, {"type": "fill", "q": "那日临近势如________，行恶的必如碎秸。", "a": "烧着的火炉", "s": ""}, {"type": "fill", "q": "以利亚来要使父亲的心________儿女。", "a": "转向", "s": ""}, {"type": "fill", "q": "玛拉基书是旧约________卷书。", "a": "最后一", "s": ""}, {"type": "single", "q": "玛拉基名字的意思是什么？", "o": ["神的仆人", "我的使者", "耶和华拯救", "神是光"], "a": "我的使者", "s": ""}, {"type": "single", "q": "神爱谁、恶谁？", "o": ["爱以扫恶雅各", "爱雅各恶以扫", "都爱", "都恶"], "a": "爱雅各恶以扫", "s": ""}, {"type": "single", "q": "神恨恶什么？", "o": ["献祭", "休妻", "祷告", "禁食"], "a": "休妻", "s": ""}, {"type": "single", "q": "当纳的多少送入仓库？", "o": ["十分之一", "五分之一", "一半", "全部"], "a": "十分之一", "s": ""}, {"type": "single", "q": "谁要在耶和华大日之前来？", "o": ["以利亚", "以利沙", "摩西", "撒母耳"], "a": "以利亚", "s": ""}, {"type": "single", "q": "公义的日头有何特性？", "o": ["审判", "其光线有医治之能", "黑暗", "烈焰"], "a": "其光线有医治之能", "s": ""}, {"type": "single", "q": "玛拉基书在旧约中的位置？", "o": ["第一卷", "中间", "最后一卷", "智慧书"], "a": "最后一卷", "s": ""}, {"type": "multiple", "q": "百姓在何事上顶撞神？", "o": ["轻慢神的名", "献有残疾的祭", "抢夺神的供物", "婚姻诡诈"], "a": "轻慢神的名,献有残疾的祭,抢夺神的供物,婚姻诡诈", "s": ""}, {"type": "multiple", "q": "神应许赐福给谁？", "o": ["纳十分之一者", "敬畏神的人", "行恶的人", "吝啬的人"], "a": "纳十分之一者,敬畏神的人", "s": ""}, {"type": "multiple", "q": "那日将如何？", "o": ["势如烧着的火炉", "骄傲和行恶的如碎秸", "公义日头出现", "永恒黑夜"], "a": "势如烧着的火炉,骄傲和行恶的如碎秸,公义日头出现", "s": ""}, {"type": "multiple", "q": "以利亚来的使命是什么？", "o": ["使父亲心转向儿女", "使儿女心转向父亲", "免得神咒诅遍地", "建造圣殿"], "a": "使父亲心转向儿女,使儿女心转向父亲,免得神咒诅遍地", "s": ""}, {"type": "judge", "q": "玛拉基是旧约最后一卷书。", "a": "对", "s": ""}, {"type": "judge", "q": "神说“我曾爱你们”，以色列却质疑。", "a": "对", "s": ""}, {"type": "judge", "q": "神喜悦人将瞎眼瘸腿的献上。", "a": "错", "s": ""}, {"type": "judge", "q": "神恨恶休妻。", "a": "对", "s": ""}, {"type": "judge", "q": "十一奉献的原则今日已完全过时。", "a": "错", "s": ""}, {"type": "judge", "q": "以利亚要在耶和华大而可畏之日前来。", "a": "对", "s": ""}, {"type": "judge", "q": "敬畏神的人有名录在神面前被记念。", "a": "对", "s": ""}, {"type": "essay", "q": "玛3:10的十一奉献对今日信徒有何教导？", "a": "奉献是神的命令，也是信心的功课。神说“以此试试我”，应许倾福无处可容。今日信徒当甘心乐意奉献，经历神信实的供应。", "s": ""}, {"type": "essay", "q": "神为何恨恶休妻？婚姻之约有何属灵意义？", "a": "婚姻是神见证的盟约，休妻是以诡诈待妻、违背盟约。婚姻预表基督与教会的关系，当忠贞持守，谨守自己的心。", "s": ""}, {"type": "essay", "q": "玛拉基书作为旧约最后一卷，如何指向新约？", "a": "预言使者预备道路（施洗约翰）、以利亚先来、公义日头出现（基督）。四百年后新约应验，显明神救赎计划的连贯。", "s": ""}]','','study','[{"title": "神的爱被质疑（1:1-5）", "points": ["耶和华借玛拉基的话", "我曾爱你们", "在何事上爱我们", "爱雅各恶以扫", "以东荒凉无复建", "神的拣选之爱"]}, {"title": "祭司轻慢（1:6-2:9）", "points": ["藐视我的名", "献瞎眼瘸腿的祭", "如此献给省长可否", "从日出到日落名尊为大", "利未之约是生命平安", "祭司嘴当守知识", "偏离正道绊倒多人"]}, {"title": "婚姻与盟约（2:10-16）", "points": ["以诡诈待弟兄", "娶事奉外邦神的女子", "耶和华见证婚约", "谨守你们的心", "休妻是神所恨恶", "以强暴待妻可憎"]}, {"title": "奉献与审判（3:1-12）", "points": ["差遣使者预备道路", "如炼金之人的火", "洁净利未人", "抢夺神的供物", "十分之一送入仓库", "以此试试我", "倾福无处可容", "万国称你们为有福"]}, {"title": "敬畏与应许（3:13-4:6）", "points": ["用话顶撞神", "事奉神徒然吗", "敬畏者彼此谈论", "纪念册记录敬畏者", "烧着火炉的日子", "公义日头出现", "差遣以利亚先来", "父子心彼此转向"]}]','','70','旧约•小先知书（十二小先知书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224378822','圣经导览','马太福音','马太福音显明耶稣是旧约预言的弥赛亚君王。从家谱到登山宝训，从天国比喻到橄榄山预言，他以君王权柄教导、医治、赦罪，死而复活后颁布大使命，差遣门徒去使万民作主的门徒，主必常与他们同在。','[{"type": "verse", "q": "虚心的人有福了！因为________是他们的。", "a": "天国", "ref": "《马太福音》5章3节", "s": "", "o": "马太福音5章3节"}, {"type": "verse", "q": "你们的光也当这样照在人前，叫他们看见你们的好行为，便将荣耀归给你们在________的父。", "a": "天上", "ref": "《马太福音》5章16节", "s": "", "o": "马太福音5章16节"}, {"type": "verse", "q": "你们要先求他的________和他的________，这些东西都要加给你们了。", "a": "国|义", "ref": "《马太福音》6章33节", "s": "", "o": "马太福音6章33节"}, {"type": "verse", "q": "凡劳苦担重担的人可以到我这里来，我就使你们得________。", "a": "安息", "ref": "《马太福音》11章28节", "s": "", "o": "马太福音11章28节"}, {"type": "verse", "q": "西门彼得回答说：你是________，是________神的儿子。", "a": "基督|永生", "ref": "《马太福音》16章16节", "s": "", "o": "马太福音16章16节"}, {"type": "verse", "q": "你要尽心、尽性、尽意爱________你的神。这是诫命中的第一，且是最大的。", "a": "主", "ref": "《马太福音》22章37节", "s": "", "o": "马太福音22章37节"}, {"type": "verse", "q": "所以，你们要去，使万民作我的门徒，奉________、________、________的名给他们施洗。", "a": "父|子|圣灵", "ref": "《马太福音》28章19节", "s": "", "o": "马太福音28章19节"}, {"type": "fill", "q": "马太福音的家谱从________起首，显明耶稣是大卫的子孙。", "a": "亚伯拉罕", "s": ""}, {"type": "fill", "q": "有几个博士从________来朝拜那新生的王。", "a": "东方", "s": ""}, {"type": "fill", "q": "施洗约翰在犹太的________传道，说：天国近了，你们应当悔改！", "a": "旷野", "s": ""}, {"type": "fill", "q": "耶稣在旷野禁食________昼夜，后来就饿了。", "a": "四十", "s": ""}, {"type": "fill", "q": "主祷文的开头是：我们在________的父。", "a": "天上", "s": ""}, {"type": "fill", "q": "耶稣差遣________个门徒出去，赐他们权柄赶鬼医病。", "a": "十二", "s": ""}, {"type": "fill", "q": "五饼二鱼的神迹后，剩下的零碎装满了________个篮子。", "a": "十二", "s": ""}, {"type": "fill", "q": "耶稣骑着________进了耶路撒冷，众人喊着说：和散那！", "a": "驴驹", "s": ""}, {"type": "fill", "q": "耶稣带着彼得、雅各、约翰，暗暗地上了________，在他们面前变了形像。", "a": "高山", "s": ""}, {"type": "fill", "q": "耶稣预言圣殿：将来在这里没有一块________留在石头上，都要拆毁了。", "a": "石头", "s": ""}, {"type": "single", "q": "谁为耶稣施洗？", "o": ["施洗约翰", "彼得", "雅各", "腓力"], "a": "A", "s": ""}, {"type": "single", "q": "马太福音记载耶稣所行的第一个神迹是？", "o": ["平静风浪", "洁净长大麻风的", "五饼二鱼", "水面行走"], "a": "B", "s": ""}, {"type": "single", "q": "彼得认耶稣为基督，发生在什么地方？", "o": ["加利利海边", "耶路撒冷", "该撒利亚腓立比境内", "拿撒勒"], "a": "C", "s": ""}, {"type": "single", "q": "耶稣说“凯撒的物当归给凯撒”，是回答关于什么的问题？", "o": ["安息日治病", "休妻", "纳税给凯撒", "最大的诫命"], "a": "C", "s": ""}, {"type": "single", "q": "最后的晚餐上，耶稣设立了什么？", "o": ["洗脚礼", "逾越节", "坚振礼", "圣餐"], "a": "D", "s": ""}, {"type": "single", "q": "耶稣复活的那日是七日的哪一日？", "o": ["第七日", "第一日", "第三日", "安息日"], "a": "B", "s": ""}, {"type": "single", "q": "博士朝拜耶稣时献上了哪三样礼物？", "o": ["金银铜", "乳香没药沉香", "黄金、乳香、没药", "珍珠宝石玛瑙"], "a": "C", "s": ""}, {"type": "multiple", "q": "登山宝训包括以下哪些教导？", "o": ["八福", "主祷文", "爱仇敌", "不要为明天忧虑"], "a": "A,B,C,D", "s": ""}, {"type": "multiple", "q": "马太福音记载了耶稣的哪些比喻？", "o": ["撒种的比喻", "稗子的比喻", "芥菜种的比喻", "十个童女的比喻"], "a": "A,B,C,D", "s": ""}, {"type": "multiple", "q": "耶稣曾三次预言自己将要？", "o": ["受长老祭司长的苦", "被杀", "第三日复活", "升上高天"], "a": "A,B,C", "s": ""}, {"type": "multiple", "q": "以下哪些是马太福音记载耶稣医治的神迹？", "o": ["长大麻风的", "百夫长的仆人", "彼得的岳母", "两个瞎子"], "a": "A,B,C,D", "s": ""}, {"type": "judge", "q": "马太福音的作者马太，原是税吏。", "a": "对", "s": ""}, {"type": "judge", "q": "耶稣说过：狐狸有洞，天空的飞鸟有窝，人子却没有枕头的地方。", "a": "对", "s": ""}, {"type": "judge", "q": "彼得在鸡叫以先，三次不认主。", "a": "对", "s": ""}, {"type": "judge", "q": "犹大卖耶稣，得了三十块钱。", "a": "对", "s": ""}, {"type": "judge", "q": "耶稣是在七日的第七日复活的。", "a": "错", "s": ""}, {"type": "judge", "q": "大使命吩咐门徒往普天下去，传福音给万民听。", "a": "对", "s": ""}, {"type": "judge", "q": "耶稣降生时，希律王下令杀伯利恒两岁以里的男孩。", "a": "对", "s": ""}, {"type": "essay", "q": "马太福音如何显明耶稣是旧约预言的弥赛亚君王？", "a": "家谱显明他是大卫的子孙；降生应验多处先知预言；登山宝训以君王权柄教导；神迹显明国度的权柄；骑驴进京应验撒迦利亚书；复活后宣告天上地下所有的权柄都赐给我了。", "s": ""}, {"type": "essay", "q": "登山宝训的核心教导是什么？", "a": "天国子民的生命品格：八福中的虚心、温柔、清心；义要胜过文士和法利赛人；爱仇敌、为逼迫者祷告；先求神的国和神的义；作世上的盐和光。", "s": ""}, {"type": "essay", "q": "大使命（太28:19-20）的内容和意义是什么？", "a": "内容：去使万民作门徒，奉父、子、圣灵的名施洗，教训他们遵守主的一切吩咐。意义：福音从犹太扩展到万邦，教会承接基督的使命，主应许常与我们同在，直到世界末了。", "s": ""}]','','study','[{"title": "君王降生（1-2章）", "points": ["家谱：从亚伯拉罕经大卫到基督，显明君王血统", "童女怀孕生子，名为以马内利（神与我们同在）", "博士从东方来朝拜，献上黄金、乳香、没药", "约瑟带婴孩逃往埃及，躲避希律", "希律杀伯利恒两岁以内男孩，应验先知预言", "耶稣在拿撒勒长大，被称为拿撒勒人"]}, {"title": "天国之王显现（3-7章）", "points": ["施洗约翰在旷野预备道路：天国近了，应当悔改", "耶稣受洗，天开了，圣灵降临，天父发声", "旷野四十昼夜受试探，以神的话得胜", "登山宝训：八福、天国子民的品格", "主祷文：愿你的国降临，愿你的旨意行在地上", "金律：你们愿意人怎样待你们，也要怎样待人"]}, {"title": "国度的权柄（8-16章）", "points": ["医治：长大麻风的、百夫长的仆人、彼得的岳母", "平静风浪：他斥责风，向海说住了吧，静了吧", "五饼二鱼喂饱五千人，剩下十二篮", "海面行走：彼得凭信心也能行走", "彼得认信：你是基督，是永生神的儿子", "耶稣预言受难、复活，教导背十字架跟从"]}, {"title": "天国比喻与预言（17-25章）", "points": ["登山变像：脸面明亮如日头，摩西以利亚显现", "骑驴进耶路撒冷，众人喊和散那", "洁净圣殿：我的殿必称为祷告的殿", "天国比喻：撒种、稗子、芥菜种、藏宝、童女", "橄榄山预言：圣殿被毁、大灾难、人子降临", "绵羊山羊的审判：作在我弟兄中最小的身上"]}, {"title": "王的受难与复活（26-28章）", "points": ["最后晚餐设立圣餐：这是我的身体，为你们舍的", "客西马尼祷告：不要照我的意思，只要照你的意思", "犹大以亲嘴为号卖耶稣，彼得三次不认主", "彼拉多前受审，被钉十字架，断气时遍地黑暗", "七日的第一日复活，向妇女和门徒显现", "大使命：去使万民作门徒，主常与我们同在"]}]','','71','新约•福音书（四福音书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224389822','圣经导览','马可福音','马可福音以“立刻”贯穿全卷，显明耶稣是服事的仆人。神迹最多、行动最快，从加利利到各各他：人子来不是要受服事，乃是要服事人，舍命作多人的赎价，第三日复活升天，门徒往普天下传福音。','[{"type": "verse", "q": "日期满了，________近了。你们当悔改，信福音！", "a": "神的国", "ref": "《马可福音》1章15节", "s": "", "o": "马可福音1章15节"}, {"type": "verse", "q": "若有人要跟从我，就当________，背起他的十字架来跟从我。", "a": "舍己", "ref": "《马可福音》8章34节", "s": "", "o": "马可福音8章34节"}, {"type": "verse", "q": "耶稣说：你若能信，在信的人，________都能。", "a": "凡事", "ref": "《马可福音》9章23节", "s": "", "o": "马可福音9章23节"}, {"type": "verse", "q": "因为人子来，并不是要受人的服事，乃是要________人，并且要舍命作多人的________。", "a": "服事|赎价", "ref": "《马可福音》10章45节", "s": "", "o": "马可福音10章45节"}, {"type": "verse", "q": "凡你们祷告祈求的，无论是什么，只要信是得着的，就必________。", "a": "得着", "ref": "《马可福音》11章24节", "s": "", "o": "马可福音11章24节"}, {"type": "verse", "q": "你要尽心、尽性、尽意、尽力爱________你的神。", "a": "主", "ref": "《马可福音》12章30节", "s": "", "o": "马可福音12章30节"}, {"type": "verse", "q": "他又对他们说：你们往________去，传福音给________听。", "a": "普天下|万民", "ref": "《马可福音》16章15节", "s": "", "o": "马可福音16章15节"}, {"type": "fill", "q": "马可福音中“________”一词出现约四十次，显明耶稣行动迅速。", "a": "立刻", "s": ""}, {"type": "fill", "q": "耶稣呼召西门彼得和兄弟________跟从他。", "a": "安得烈", "s": ""}, {"type": "fill", "q": "耶稣平静风浪时，在船尾靠着枕头________。", "a": "睡觉", "s": ""}, {"type": "fill", "q": "格拉森被鬼附的人住在________中间，没有人能制伏他。", "a": "坟茔", "s": ""}, {"type": "fill", "q": "睚鲁是管________的人，来求耶稣救他快死的女儿。", "a": "会堂", "s": ""}, {"type": "fill", "q": "患血漏的妇人得病已经________年，摸耶稣的衣裳就好了。", "a": "十二", "s": ""}, {"type": "fill", "q": "耶稣在海面上走，往门徒那里去，约在夜里________更天。", "a": "四", "s": ""}, {"type": "fill", "q": "彼得认信后，耶稣预言人子必须受苦，被杀，________后复活。", "a": "三日", "s": ""}, {"type": "fill", "q": "捉拿耶稣时，有个少年人赤身披着麻布，众人捉他，他却________逃走了。", "a": "丢下麻布", "s": ""}, {"type": "fill", "q": "百夫长看见耶稣断气，就说：这人真是________。", "a": "神的儿子", "s": ""}, {"type": "single", "q": "马可福音着重显明耶稣的哪一重身份？", "o": ["君王", "仆人", "祭司", "先知"], "a": "B", "s": ""}, {"type": "single", "q": "“好撒玛利亚人”的比喻记载在哪卷福音书？", "o": ["马可福音", "马太福音", "路加福音", "约翰福音"], "a": "C", "s": ""}, {"type": "single", "q": "耶稣登山变像时，同在的三位门徒是？", "o": ["彼得、安得烈、约翰", "彼得、雅各、约翰", "雅各、约翰、多马", "彼得、腓力、巴多罗买"], "a": "B", "s": ""}, {"type": "single", "q": "穷寡妇往圣殿库里投了几个小钱？", "o": ["一个", "两个", "三个", "七个"], "a": "B", "s": ""}, {"type": "single", "q": "马可福音记载耶稣医治的第一个病人是在哪里？", "o": ["加利利海边", "拿撒勒", "迦百农会堂", "伯赛大"], "a": "C", "s": ""}, {"type": "single", "q": "彼得不认主之后，鸡叫了几遍？（按马可福音）", "o": ["一遍", "两遍", "三遍", "没有叫"], "a": "B", "s": ""}, {"type": "single", "q": "耶稣被钉十字架的时刻是？", "o": ["巳初", "午正", "申初", "酉初"], "a": "B", "s": ""}, {"type": "multiple", "q": "马可福音记载了耶稣的哪些神迹？", "o": ["平静风浪", "五饼二鱼", "海面行走", "治好耳聋舌结的人"], "a": "A,B,C,D", "s": ""}, {"type": "multiple", "q": "耶稣在马可福音中讲过哪些比喻？", "o": ["撒种的比喻", "芥菜种的比喻", "葡萄园的比喻", "好撒玛利亚人的比喻"], "a": "A,B,C", "s": ""}, {"type": "multiple", "q": "马可福音16章记载，哪些妇女清早去坟墓？", "o": ["抹大拉的马利亚", "雅各的母亲马利亚", "撒罗米", "约亚拿"], "a": "A,B,C", "s": ""}, {"type": "multiple", "q": "耶稣预言圣殿将要怎样？", "o": ["没有一块石头留在石头上", "更加辉煌", "被洁净", "成为万国祷告的殿"], "a": "A", "s": ""}, {"type": "judge", "q": "马可福音是四福音书中最短的一卷。", "a": "对", "s": ""}, {"type": "judge", "q": "马可曾与保罗、巴拿巴一同传道。", "a": "对", "s": ""}, {"type": "judge", "q": "耶稣在安息日治病，法利赛人就商议要除灭他。", "a": "对", "s": ""}, {"type": "judge", "q": "法利赛人求神迹，耶稣就从天上显个神迹给他们看。", "a": "错", "s": ""}, {"type": "judge", "q": "耶稣说过：安息日是为人设立的，人不是为安息日设立的。", "a": "对", "s": ""}, {"type": "judge", "q": "大祭司该亚法审问时，耶稣承认自己是基督，是至高者的儿子。", "a": "对", "s": ""}, {"type": "judge", "q": "马可福音记载耶稣复活后向五百弟兄显现。", "a": "错", "s": ""}, {"type": "essay", "q": "“人子来是要服事人”（可10:45）显明耶稣怎样的使命？", "a": "耶稣虽是神的儿子，却取了仆人的形象；他的使命不是受人的服事，而是服事人，并且舍命作多人的赎价，以死成就救赎。", "s": ""}, {"type": "essay", "q": "马可福音中门徒多次失败，给我们什么鉴戒？", "a": "门徒争为大、信心小、不明白、逃跑，彼得三次不认主，显明人性的软弱。鉴戒我们不靠自己，要谦卑依靠圣灵；失败后仍可被主赦免、恢复、重用。", "s": ""}, {"type": "essay", "q": "马可福音为什么多次使用“立刻”“随即”？", "a": "显明耶稣是行动的仆人，神的国带着能力迅速推进；也呼召读者对福音立刻回应，不拖延、不迟疑。", "s": ""}]','','study','[{"title": "仆人显现（1-3章）", "points": ["施洗约翰在旷野预备道路，传悔改的洗礼", "耶稣受洗，天开了，圣灵如鸽子降临", "旷野四十天受撒但试探，有天使伺候", "呼召西门、安得烈、雅各、约翰跟从他", "迦百农会堂赶鬼、医治彼得岳母、洁净麻风", "设立十二门徒，要他们传道、赶鬼"]}, {"title": "仆人权柄（4-6章）", "points": ["撒种的比喻：道种落在好土里结实百倍", "平静风浪：住了吧！静了吧！风就止住", "格拉森赶鬼：群鬼入猪群，闯下山崖", "睚鲁女儿复活、血漏妇人摸衣得医治", "五饼二鱼喂饱五千人，剩下十二篮", "海面行走：放心！是我，不要怕"]}, {"title": "仆人教导（7-10章）", "points": ["真污秽从心里发出，不是从口入的", "外邦妇人的信心：狗也吃桌下碎渣", "彼得认信：你是基督；预言受难复活", "登山变像：衣服洁白放光，云中有声", "为首的必作仆人：人子来是服事人", "瞎子巴底买：大卫的子孙，可怜我吧"]}, {"title": "仆人受难（11-15章）", "points": ["骑驴荣进圣城，众人铺衣服砍棕枝", "洁净圣殿：我的殿必称为万国祷告的殿", "寡妇两个小钱：比众人投的更多", "橄榄山预言：圣殿被毁、人子驾云降临", "最后晚餐、客西马尼祷告、被卖被捕", "十字架受难，百夫长认信：真是神的儿子"]}, {"title": "仆人复活（16章）", "points": ["七日第一日清早，妇女带着香膏去坟墓", "少年人宣告：他已经复活了，不在这里", "向抹大拉的马利亚显现，她去告诉门徒", "大使命：往普天下去，传福音给万民听", "信而受洗的必然得救，不信的必被定罪", "主升天，坐在神的右边，门徒传道主同工"]}]','','72','新约•福音书（四福音书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224400822','圣经导览','路加福音','路加福音显明耶稣是完全的人子，满有怜悯。好撒玛利亚人、浪子回头、税吏撒该、以马忤斯路上，人子来为要寻找、拯救失丧的人，将救恩带给万民，直到地极，凡悔改相信他的都必得着永生。','[{"type": "verse", "q": "因为，出于神的话，没有一句不带________的。", "a": "能力", "ref": "《路加福音》1章37节", "s": "", "o": "路加福音1章37节"}, {"type": "verse", "q": "在至高之处荣耀归与神！在地上________归与他所喜悦的人！", "a": "平安", "ref": "《路加福音》2章14节", "s": "", "o": "路加福音2章14节"}, {"type": "verse", "q": "主的灵在我身上，因为他用膏膏我，叫我传________给贫穷的人。", "a": "福音", "ref": "《路加福音》4章18节", "s": "", "o": "路加福音4章18节"}, {"type": "verse", "q": "若有人要跟从我，就当舍己，________背起他的十字架来跟从我。", "a": "天天", "ref": "《路加福音》9章23节", "s": "", "o": "路加福音9章23节"}, {"type": "verse", "q": "一个罪人悔改，在天上也要这样为他欢喜，较比为________个不用悔改的义人欢喜更大。", "a": "九十九", "ref": "《路加福音》15章7节", "s": "", "o": "路加福音15章7节"}, {"type": "verse", "q": "人子来，为要________、________失丧的人。", "a": "寻找|拯救", "ref": "《路加福音》19章10节", "s": "", "o": "路加福音19章10节"}, {"type": "verse", "q": "于是从摩西和众先知起，凡经上所指着自己的话都给他们________明白了。", "a": "讲解", "ref": "《路加福音》24章27节", "s": "", "o": "路加福音24章27节"}, {"type": "fill", "q": "天使加百列奉差往加利利的拿撒勒，向童女________报喜。", "a": "马利亚", "s": ""}, {"type": "fill", "q": "施洗约翰的父亲撒迦利亚是________。", "a": "祭司", "s": ""}, {"type": "fill", "q": "耶稣降生在犹大的________城，被放在马槽里。", "a": "伯利恒", "s": ""}, {"type": "fill", "q": "天使向野地里看守羊群的________报大喜的信息。", "a": "牧羊人", "s": ""}, {"type": "fill", "q": "耶稣十二岁时在圣殿里，坐在________中间，一面听一面问。", "a": "教师", "s": ""}, {"type": "fill", "q": "路加福音的家谱从耶稣一直追溯到________。", "a": "亚当", "s": ""}, {"type": "fill", "q": "好撒玛利亚人把受伤的人带到店里，拿出二钱________交给店主。", "a": "银子", "s": ""}, {"type": "fill", "q": "浪子对父亲说：父亲，请你把我应得的________分给我。", "a": "家业", "s": ""}, {"type": "fill", "q": "撒该是________长，又很富有，爬上桑树要看耶稣。", "a": "税吏", "s": ""}, {"type": "fill", "q": "以马忤斯离耶路撒冷约有________里。", "a": "二十五", "s": ""}, {"type": "single", "q": "路加的职业是什么？", "o": ["渔夫", "医生", "税吏", "木匠"], "a": "B", "s": ""}, {"type": "single", "q": "路加福音是写给谁的？", "o": ["保罗", "提阿非罗大人", "彼得", "众教会"], "a": "B", "s": ""}, {"type": "single", "q": "西面抱着婴孩耶稣，称他是照亮外邦人的光，又是以色列百姓的什么？", "o": ["审判", "荣耀", "安慰", "盼望"], "a": "B", "s": ""}, {"type": "single", "q": "耶稣差遣多少人两个两个地出去传道？", "o": ["十二人", "七十人", "一百二十人", "五百人"], "a": "B", "s": ""}, {"type": "single", "q": "十个长大麻风的得医治，有几个回来归荣耀与神？", "o": ["十个", "五个", "两个", "一个"], "a": "D", "s": ""}, {"type": "single", "q": "耶稣对十字架上悔改的强盗说什么？", "o": ["你的罪赦了", "起来行走吧", "今日你要同我在乐园里了", "父啊赦免他们"], "a": "C", "s": ""}, {"type": "single", "q": "往以马忤斯去的两个门徒中，圣经提到名字的是谁？", "o": ["彼得", "约翰", "革流巴", "多马"], "a": "C", "s": ""}, {"type": "multiple", "q": "以下哪些比喻只记载在路加福音？", "o": ["好撒玛利亚人", "浪子回头", "财主与拉撒路", "大筵席的比喻"], "a": "A,B,C,D", "s": ""}, {"type": "multiple", "q": "圣诞故事中出现的人物有？", "o": ["撒迦利亚", "马利亚", "牧羊人", "西面"], "a": "A,B,C,D", "s": ""}, {"type": "multiple", "q": "耶稣在路加福音中医治了？", "o": ["十个长大麻风", "血漏的妇人", "睚鲁的女儿", "耳聋舌结的人"], "a": "A,B,C", "s": ""}, {"type": "multiple", "q": "路加福音24章记载，复活的主向哪些人显现？", "o": ["以马忤斯的两个门徒", "十一位使徒", "西门彼得", "抹大拉的马利亚"], "a": "A,B,C", "s": ""}, {"type": "judge", "q": "路加福音是四福音书中最长的一卷。", "a": "对", "s": ""}, {"type": "judge", "q": "马利亚是因圣灵感孕而怀了耶稣。", "a": "对", "s": ""}, {"type": "judge", "q": "耶稣在拿撒勒因众人信心大，就在那里行了许多神迹。", "a": "错", "s": ""}, {"type": "judge", "q": "“财主与拉撒路”是耶稣讲的比喻。", "a": "对", "s": ""}, {"type": "judge", "q": "撒该把所有的一半分给穷人，讹诈了谁就还他四倍。", "a": "对", "s": ""}, {"type": "judge", "q": "耶稣被钉十字架时，遍地黑暗，太阳变黑了。", "a": "对", "s": ""}, {"type": "judge", "q": "耶稣复活升天是在伯大尼的对面。", "a": "对", "s": ""}, {"type": "essay", "q": "浪子回头的比喻显明天父怎样的心肠？", "a": "父亲远远看见小儿子就动了慈心，跑去抱着连连亲嘴，吩咐拿上好的袍子、戒指、鞋子，为他摆设筵席。显明天父主动寻找、接纳、赦免罪人，为一个罪人悔改而欢喜快乐。", "s": ""}, {"type": "essay", "q": "路加福音如何显明耶稣是完全的人子？", "a": "详细记载他的降生、成长（智慧和身量增长）、祷告、流泪、受试探、受苦；家谱追溯至亚当；他体恤人的软弱，与税吏罪人为友，显明他是完全的人，也是全人类的救主。", "s": ""}, {"type": "essay", "q": "以马忤斯路上，耶稣如何坚固门徒的信心？", "a": "与他们同行，倾听他们的困惑；从摩西和众先知讲解经上指着自己的话；擘饼时他们的眼睛明亮认出他。显明复活的主借着圣经和团契向门徒显现，点燃信心。", "s": ""}]','','study','[{"title": "人子降生（1-2章）", "points": ["天使向撒迦利亚报喜：施洗约翰将要出生", "天使向马利亚报喜：圣灵感孕生圣者", "马利亚尊主颂：我心尊主为大，我灵以神为乐", "耶稣降生伯利恒马槽，天使向牧羊人报喜", "西面亚拿在圣殿称颂：照亮外邦人的光", "十二岁耶稣在圣殿：岂不知我应当以我父的事为念"]}, {"title": "人子预备（3-4章）", "points": ["施洗约翰传悔改的洗礼，预备主的道", "耶稣受洗祷告，天开了，圣灵降临", "家谱：从耶稣追溯至亚当、至神", "旷野四十天受试探，以经上记着说得胜", "拿撒勒讲道：主的灵在我身上", "本乡人厌弃他，要把他推下山崖"]}, {"title": "人子怜悯（5-15章）", "points": ["呼召门徒：得人如得鱼；拣选十二使徒", "医治：大麻风、瘫子、枯干的手", "差遣十二门徒，又差遣七十人", "好撒玛利亚人：爱邻舍的具体榜样", "浪子回头：父亲慈心接纳悔改的儿子", "财主与拉撒路：今生的选择决定永恒"]}, {"title": "人子舍命（16-23章）", "points": ["撒该悔改：人子来为要寻找拯救失丧的人", "荣进圣城，耶稣为耶路撒冷哭泣", "最后晚餐设立圣餐，预言彼得不认主", "客西马尼祷告，汗珠如大血点滴在地上", "受审：希律彼拉多前无罪，众人喊钉十字架", "十字架上赦免悔改的强盗：今日同我在乐园"]}, {"title": "人子复活（24章）", "points": ["七日第一日清早，妇女见石头滚开", "天使宣告：他不在这里，已经复活了", "以马忤斯路上同行、讲解圣经、擘饼显现", "向十一位显现：愿你们平安，摸我看看", "圣经指着他：基督必受害，第三日复活", "在伯大尼举手祝福，升天；门徒传道到万邦"]}]','','73','新约•福音书（四福音书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224411822','圣经导览','约翰福音','约翰福音显明耶稣是神的儿子。太初有道，道与神同在，道就是神；道成肉身住在我们中间，充充满满有恩典有真理。七个“我是”、七个神迹，叫一切信他的不至灭亡，反得永生，这是为要你们信耶稣是基督。','[{"type": "verse", "q": "太初有道，道与神________，道就是神。", "a": "同在", "ref": "《约翰福音》1章1节", "s": "", "o": "约翰福音1章1节"}, {"type": "verse", "q": "道成了________，住在我们中间，充充满满地有恩典有真理。", "a": "肉身", "ref": "《约翰福音》1章14节", "s": "", "o": "约翰福音1章14节"}, {"type": "verse", "q": "神爱世人，甚至将他的________赐给他们，叫一切信他的，不至灭亡，反得永生。", "a": "独生子", "ref": "《约翰福音》3章16节", "s": "", "o": "约翰福音3章16节"}, {"type": "verse", "q": "我是世界的________。跟从我的，就不在黑暗里走，必要得着生命的光。", "a": "光", "ref": "《约翰福音》8章12节", "s": "", "o": "约翰福音8章12节"}, {"type": "verse", "q": "我是好________；好牧人为羊舍命。", "a": "牧人", "ref": "《约翰福音》10章11节", "s": "", "o": "约翰福音10章11节"}, {"type": "verse", "q": "复活在我，________也在我。信我的人虽然死了，也必复活。", "a": "生命", "ref": "《约翰福音》11章25节", "s": "", "o": "约翰福音11章25节"}, {"type": "verse", "q": "我就是________、________、________；若不借着我，没有人能到父那里去。", "a": "道路|真理|生命", "ref": "《约翰福音》14章6节", "s": "", "o": "约翰福音14章6节"}, {"type": "fill", "q": "约翰福音开篇宣告：太初有________。", "a": "道", "s": ""}, {"type": "fill", "q": "施洗约翰说自己是在旷野________的声音。", "a": "有人声", "s": ""}, {"type": "fill", "q": "耶稣行的第一个神迹，是在加利利的________变水为酒。", "a": "迦拿", "s": ""}, {"type": "fill", "q": "尼哥底母是犹太人的官，是________人，夜间来见耶稣。", "a": "法利赛", "s": ""}, {"type": "fill", "q": "耶稣与撒玛利亚妇人谈道，是在________井旁。", "a": "雅各", "s": ""}, {"type": "fill", "q": "毕士大池边，耶稣医治了一个病了________年的瘫子。", "a": "三十八", "s": ""}, {"type": "fill", "q": "耶稣宣告：我就是生命的________。", "a": "粮", "s": ""}, {"type": "fill", "q": "生来瞎眼的人在________池里去洗，回头就看见了。", "a": "西罗亚", "s": ""}, {"type": "fill", "q": "拉撒路住在________，是马利亚和马大的兄弟。", "a": "伯大尼", "s": ""}, {"type": "fill", "q": "耶稣在十字架上说“________”，便低下头，将灵魂交付神了。", "a": "成了", "s": ""}, {"type": "single", "q": "约翰福音的作者是谁？", "o": ["施洗约翰", "使徒约翰", "马可", "路加"], "a": "B", "s": ""}, {"type": "single", "q": "约翰福音中的“道”是指谁？", "o": ["施洗约翰", "圣灵", "耶稣基督", "摩西"], "a": "C", "s": ""}, {"type": "single", "q": "尼哥底母什么时候来见耶稣？", "o": ["清晨", "正午", "夜间", "安息日"], "a": "C", "s": ""}, {"type": "single", "q": "撒玛利亚妇人曾经有几个丈夫？", "o": ["三个", "五个", "七个", "一个"], "a": "B", "s": ""}, {"type": "single", "q": "耶稣为门徒洗脚时，彼得最初说什么？", "o": ["求主多洗几次", "你永不可洗我的脚", "我不配", "让约翰先洗"], "a": "B", "s": ""}, {"type": "single", "q": "多马又被称为什么？", "o": ["多疑者", "低土马", "小雅各", "拿但业"], "a": "B", "s": ""}, {"type": "single", "q": "耶稣复活后在提比哩亚海边，向几个门徒显现？", "o": ["两个", "五个", "七个", "十一个"], "a": "C", "s": ""}, {"type": "multiple", "q": "耶稣在约翰福音中的七个“我是”包括？", "o": ["我是生命的粮", "我是世界的光", "我是好牧人", "我是真葡萄树"], "a": "A,B,C,D", "s": ""}, {"type": "multiple", "q": "约翰福音记载了耶稣的哪些神迹？", "o": ["迦拿变水为酒", "医治大臣之子", "毕士大池医治瘫子", "叫拉撒路复活"], "a": "A,B,C,D", "s": ""}, {"type": "multiple", "q": "耶稣在14至16章安慰门徒说？", "o": ["你们心里不要忧愁", "我去原是为你们预备地方", "我留下平安给你们", "世界将要过去"], "a": "A,B,C", "s": ""}, {"type": "multiple", "q": "约翰福音记载的十字架七言包括？", "o": ["妇人，看，你的儿子", "我渴了", "成了", "我的神，为什么离弃我"], "a": "A,B,C", "s": ""}, {"type": "judge", "q": "约翰福音没有记载耶稣设立圣餐的过程。", "a": "对", "s": ""}, {"type": "judge", "q": "施洗约翰曾为耶稣施洗。", "a": "对", "s": ""}, {"type": "judge", "q": "尼哥底母带着没药和沉香，与约瑟一同安葬耶稣。", "a": "对", "s": ""}, {"type": "judge", "q": "撒玛利亚妇人信主后，城里有好些撒玛利亚人信了耶稣。", "a": "对", "s": ""}, {"type": "judge", "q": "犹太人想要杀耶稣，因他称神为父，将自己和神当作平等。", "a": "对", "s": ""}, {"type": "judge", "q": "彼得在约翰福音中三次不认主。", "a": "对", "s": ""}, {"type": "judge", "q": "多马说：我非看见他手上的钉痕，我总不信。", "a": "对", "s": ""}, {"type": "essay", "q": "约翰福音七个“我是”显明耶稣怎样的身份？", "a": "生命的粮、世界的光、羊的门、好牧人、复活与生命、道路真理生命、真葡萄树，显明耶稣是神的儿子，是生命的源头、唯一的救主；信他的人得生命，不信的被定罪。", "s": ""}, {"type": "essay", "q": "“道成肉身”（约1:14）有什么重要意义？", "a": "神的儿子取了完全的人性，住在我们中间；他是完全的神，也是完全的人，能体恤我们，将神表明出来，并为我们死在十字架上，成就救赎。", "s": ""}, {"type": "essay", "q": "约翰福音写作的目的是什么？（约20:31）", "a": "要叫你们信耶稣是基督，是神的儿子；并且叫你们信了他，就可以因他的名得生命。全卷的神迹与见证都为此目的。", "s": ""}]','','study','[{"title": "道成肉身（1章）", "points": ["太初有道，道与神同在，道就是神", "施洗约翰见证：看哪，神的羔羊", "呼召门徒：腓力、拿但业（真以色列人）", "拿但业认信：你是神的儿子，以色列的王", "迦拿婚宴变水为酒：耶稣所行的第一件神迹", "门徒就信他了，显出他的荣耀来"]}, {"title": "生命之道（2-6章）", "points": ["洁净圣殿：不要将我父的殿当作买卖的地方", "尼哥底母：人若不重生，就不能见神的国", "约3:16：神爱世人，赐下独生子", "撒玛利亚妇人：喝我所赐的水就永远不渴", "毕士大瘫子：起来，拿你的褥子行走吧", "五饼二鱼、生命之粮：我是从天上降下来的粮"]}, {"title": "光照黑暗（7-10章）", "points": ["住棚节宣告：人若渴了，可以到我这里来喝", "行淫妇人：我也不定你的罪，去吧", "生来瞎子在西罗亚池洗后看见", "我是世界的光，跟从我的不在黑暗里走", "好牧人：为羊舍命，认得他的羊", "犹太人拿石头要打他，因他称自己为神"]}, {"title": "荣耀之时（11-17章）", "points": ["拉撒路复活：复活在我，生命也在我", "马利亚用真哪哒香膏抹耶稣的脚", "为门徒洗脚：我是你们的主，尚且洗你们的脚", "安慰之言：我去原是为你们预备地方", "保惠师圣灵：引导你们明白一切真理", "大祭司祷告：使他们合而为一，像我们合一"]}, {"title": "十架与复活（18-21章）", "points": ["客西马尼被捕：我就是，你们来捉拿吧", "彼拉多三次宣告：我查不出他有什么罪来", "十字架：我渴了、成了，将母亲托付约翰", "七日第一日复活，向抹大拉马利亚显现", "多马：我的主，我的神；不见而信的有福", "提比哩亚海：你爱我吗？喂养我的羊"]}]','','74','新约•福音书（四福音书）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-179122437789501','圣经导览','使徒行传','使徒行传记载圣灵降临、教会诞生与福音从耶路撒冷扩展到地极的历程。从彼得五旬节讲道、司提反殉道，到扫罗归主、耶路撒冷大会，再到保罗三次布道旅程与上诉凯撒，展现初代教会靠圣灵勇敢见证的生命。','[{"type": "verse", "q": "但圣灵降临在你们身上，你们就必得着________，并要在耶路撒冷、犹太全地和撒玛利亚，直到________，作我的见证。", "a": "能力|地极", "ref": "《使徒行传》1章8节", "s": "", "o": "使徒行传1章8节"}, {"type": "verse", "q": "彼得说：你们各人要________，奉耶稣基督的名________，叫你们的罪得赦，就必领受所赐的圣灵。", "a": "悔改|受洗", "ref": "《使徒行传》2章38节", "s": "", "o": "使徒行传2章38节"}, {"type": "verse", "q": "到那时候，凡______________的，就必得救。", "a": "求告主名", "ref": "《使徒行传》2章21节", "s": "", "o": "使徒行传2章21节"}, {"type": "verse", "q": "金银我都没有，只把我所有的给你。我奉拿撒勒人耶稣基督的名，叫你________！", "a": "起来行走", "ref": "《使徒行传》3章6节", "s": "", "o": "使徒行传3章6节"}, {"type": "verse", "q": "除他以外，别无________；因为在天下人间，没有赐下别的名，我们可以________。", "a": "拯救|靠着得救", "ref": "《使徒行传》4章12节", "s": "", "o": "使徒行传4章12节"}, {"type": "verse", "q": "原来，各国中那敬畏主、________的人都为主所悦纳。", "a": "行义", "ref": "《使徒行传》10章35节", "s": "", "o": "使徒行传10章35节"}, {"type": "verse", "q": "当________，你和你一家都必得救。", "a": "信主耶稣", "ref": "《使徒行传》16章31节", "s": "", "o": "使徒行传16章31节"}, {"type": "fill", "q": "五旬节到了，门徒都聚集在一处，忽然有________从天上响起，好像一阵大风吹过。", "a": "响声", "s": ""}, {"type": "fill", "q": "彼得在五旬节讲道，听的人觉得扎心，那一天门徒约添了________人。", "a": "三千", "s": ""}, {"type": "fill", "q": "第一位殉道的执事是________，他被众人用石头打死。", "a": "司提反", "s": ""}, {"type": "fill", "q": "扫罗在大马士革路上遇见主而归主，后来改名为________。", "a": "保罗", "s": ""}, {"type": "fill", "q": "彼得在约帕看见________，明白神也将福音赐给外邦人。", "a": "异象", "s": ""}, {"type": "fill", "q": "门徒称为“________”是从安提阿起首。", "a": "基督徒", "s": ""}, {"type": "fill", "q": "保罗第一次布道旅程是与________同工，从安提阿出发。", "a": "巴拿巴", "s": ""}, {"type": "fill", "q": "耶路撒冷大会决议：外邦信徒不必受________，只要禁戒几样污秽。", "a": "割礼", "s": ""}, {"type": "fill", "q": "保罗在________城传道两年，许多行邪术的人把书拿来烧毁。", "a": "以弗所", "s": ""}, {"type": "fill", "q": "保罗在该撒利亚向非斯都申诉，声明自己要向________上诉。", "a": "凯撒", "s": ""}, {"type": "single", "q": "第一位殉道的执事是谁？", "o": ["司提反", "腓利", "巴拿巴", "提摩太"], "a": "司提反", "s": ""}, {"type": "single", "q": "扫罗是在前往哪座城的路上归主的？", "o": ["大马士革", "耶路撒冷", "安提阿", "该撒利亚"], "a": "大马士革", "s": ""}, {"type": "single", "q": "接替犹大作使徒职分的是谁？", "o": ["马提亚", "巴拿巴", "西拉", "提多"], "a": "马提亚", "s": ""}, {"type": "single", "q": "保罗在雅典传福音、与人辩论的地方叫什么？", "o": ["亚略巴古", "会堂", "剧场", "市集"], "a": "亚略巴古", "s": ""}, {"type": "single", "q": "亚基帕王听完保罗的申诉后说了什么？", "o": ["你这样劝我，几乎叫我作基督徒了", "你是疯了", "应当释放这个人", "把他押回耶路撒冷"], "a": "你这样劝我，几乎叫我作基督徒了", "s": ""}, {"type": "single", "q": "保罗最后被押送到哪座城，在租的房子里传道两年？", "o": ["罗马", "西班牙", "耶路撒冷", "安提阿"], "a": "罗马", "s": ""}, {"type": "single", "q": "彼得见异象时，正在谁的房顶上祷告？", "o": ["硝皮匠西门", "约翰·马可", "哥尼流", "大数扫罗"], "a": "硝皮匠西门", "s": ""}, {"type": "multiple", "q": "保罗三次布道旅程到过以下哪些地方？", "o": ["安提阿", "以弗所", "哥林多", "罗马"], "a": "安提阿,以弗所,哥林多", "s": ""}, {"type": "multiple", "q": "五旬节圣灵降临时出现了哪些现象？", "o": ["好像大风的响声", "如火焰般的舌头", "说起别国的话来", "大地震动"], "a": "好像大风的响声,如火焰般的舌头,说起别国的话来", "s": ""}, {"type": "multiple", "q": "耶路撒冷大会写信吩咐外邦信徒要禁戒哪些？", "o": ["拜偶像之物", "血", "勒死的牲畜", "奸淫"], "a": "拜偶像之物,血,勒死的牲畜,奸淫", "s": ""}, {"type": "multiple", "q": "司提反殉道前看见了什么？", "o": ["天开了", "人子站在神的右边", "众天使环绕", "摩西迎接他"], "a": "天开了,人子站在神的右边", "s": ""}, {"type": "judge", "q": "保罗是在往大马士革的路上归主的。", "a": "对", "s": ""}, {"type": "judge", "q": "五旬节那天，门徒都被圣灵充满，按着圣灵所赐的口才说起别国的话来。", "a": "对", "s": ""}, {"type": "judge", "q": "彼得因为三次不认主，所以失去了使徒的职分。", "a": "错", "s": ""}, {"type": "judge", "q": "耶路撒冷大会决议外邦信徒必须受割礼才能得救。", "a": "错", "s": ""}, {"type": "judge", "q": "保罗在罗马被囚期间不能传道，只能等候审判。", "a": "错", "s": ""}, {"type": "judge", "q": "哥尼流一家是福音临到外邦人的重要记号。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗的三次布道旅程都是从安提阿教会出发的。", "a": "对", "s": ""}, {"type": "essay", "q": "耶路撒冷大会决议了什么？这一决议对福音广传有何意义？", "a": "大会决议外邦信徒不必受割礼、不用全守摩西律法，只要禁戒偶像之物、血、勒死的牲畜和奸淫。意义在于确认救恩本乎恩、因着信，拆除了犹太律法对外邦人的拦阻，使福音得以自由地传向万邦。", "s": ""}, {"type": "essay", "q": "圣灵降临对教会的诞生有何意义？", "a": "五旬节圣灵降临标志着教会的诞生。圣灵赐下能力，使胆怯的门徒放胆见证；彼得一次讲道三千人悔改；信徒形成彼此相爱、擘饼祈祷的团契。教会从此靠圣灵的大能，从耶路撒冷向地极扩展。", "s": ""}, {"type": "essay", "q": "扫罗归主的经历给今天的信徒什么启示？", "a": "扫罗原是逼迫教会的人，却在神的主权拣选中戏剧性归主，改名保罗成为外邦人的使徒。启示我们：没有神不能改变的人；神的呼召带着使命；真正的悔改必带来生命方向的彻底翻转，并甘愿为福音受苦。", "s": ""}]','','study','[{"title": "圣灵降临（1-2章）", "points": ["主升天前的应许：圣灵降临就必得着能力", "主的使命：从耶路撒冷直到地极作见证", "马提亚被选补足十二使徒", "五旬节圣灵如大风、火焰般降临", "门徒说起别国的话来", "彼得讲道：众人扎心悔改", "那一天约添三千人，教会诞生"]}, {"title": "福音广传（3-7章）", "points": ["彼得奉主名医治生来瘸腿的人", "彼得约翰被囚仍放胆传讲复活的基督", "除他以外别无拯救", "亚拿尼亚和撒非喇欺哄圣灵受警戒", "拣选七位执事管理饭食", "司提反被圣灵充满放胆见证", "司提反殉道，看见天开了"]}, {"title": "福音临到外邦（8-12章）", "points": ["腓利向撒玛利亚人传道", "埃提阿伯太监信主受洗", "扫罗在大马士革路上归主", "亚拿尼亚为扫罗按手祷告", "彼得在约帕见异象", "哥尼流一家受圣灵、外邦人得救", "安提阿教会兴起，门徒首称基督徒"]}, {"title": "保罗布道旅程（13-20章）", "points": ["圣灵差派巴拿巴和扫罗出去", "第一次旅程：居比路、小亚细亚", "耶路撒冷大会：外邦信徒免割礼", "第二次旅程：马其顿异象", "腓立比：吕底亚信主、狱卒全家得救", "以弗所大复兴：烧毁邪术的书", "米利都告别：设立长老、交托神"]}, {"title": "保罗上诉凯撒（21-28章）", "points": ["保罗在耶路撒冷被捕", "向千夫长、公会分诉", "在非斯都和亚基帕王面前申诉", "宣告向凯撒上诉", "海难中蒙神保守全船得救", "抵达罗马，在租屋中传道两年", "放胆传讲神国，无人禁止"]}]','','75','新约•历史书','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-179122437789502','圣经导览','罗马书','罗马书是保罗阐释福音真理的巅峰之作，系统论述人人犯罪亏缺神荣耀、唯独因信称义。从称义、成圣到圣灵里的得胜生命，再论以色列的奥秘，最后劝勉信徒献上活祭，活出讨神喜悦、爱人如己的人生。','[{"type": "verse", "q": "因为世人都犯了罪，________。", "a": "亏缺了神的荣耀", "ref": "《罗马书》3章23节", "s": "", "o": "罗马书3章23节"}, {"type": "verse", "q": "我们既因信称义，就借着我们的主耶稣基督得与神________。", "a": "相和", "ref": "《罗马书》5章1节", "s": "", "o": "罗马书5章1节"}, {"type": "verse", "q": "因为罪的工价乃是死，惟有神的恩赐，在我们的主基督耶稣里，乃是________。", "a": "永生", "ref": "《罗马书》6章23节", "s": "", "o": "罗马书6章23节"}, {"type": "verse", "q": "我们晓得万事都互相效力，叫________得益处，就是按他旨意被召的人。", "a": "爱神的人", "ref": "《罗马书》8章28节", "s": "", "o": "罗马书8章28节"}, {"type": "verse", "q": "你若口里认耶稣为主，心里信神叫他从死里复活，就必________。", "a": "得救", "ref": "《罗马书》10章9节", "s": "", "o": "罗马书10章9节"}, {"type": "verse", "q": "所以弟兄们，我以神的慈悲劝你们，将身体献上，当作________、________、________的祭物，这是你们所当行的。", "a": "活祭|圣洁|神所喜悦", "ref": "《罗马书》12章1节", "s": "", "o": "罗马书12章1节"}, {"type": "verse", "q": "因为神的义正在这福音上显明出来，这义是本于信，以至于信。如经上所记：“________。”", "a": "义人必因信得生", "ref": "《罗马书》1章17节", "s": "", "o": "罗马书1章17节"}, {"type": "fill", "q": "罗马书的作者是________。", "a": "保罗", "s": ""}, {"type": "fill", "q": "保罗写罗马书时身在________城，计划前往西班牙途中经过罗马。", "a": "哥林多", "s": ""}, {"type": "fill", "q": "这福音本是神的________，要救一切相信的。", "a": "大能", "s": ""}, {"type": "fill", "q": "亚伯拉罕因________被算为义，成为一切信之人的父。", "a": "信", "s": ""}, {"type": "fill", "q": "罪的工价乃是________，惟有神的恩赐乃是永生。", "a": "死", "s": ""}, {"type": "fill", "q": "“立志为善由得我，只是行出来由不得我”是保罗在第________章的挣扎告白。", "a": "七", "s": ""}, {"type": "fill", "q": "“如今那些在基督耶稣里的就不定罪了”是第________章开篇的宣告。", "a": "八", "s": ""}, {"type": "fill", "q": "以色列的枝子被折下来，外邦野橄榄反被________上去。", "a": "接", "s": ""}, {"type": "fill", "q": "保罗说：爱人的就________了律法。", "a": "完全", "s": ""}, {"type": "fill", "q": "在上有权柄的，人人当________，因为没有权柄不是出于神的。", "a": "顺服", "s": ""}, {"type": "single", "q": "罗马书中“因信称义”的旧约榜样是谁？", "o": ["亚伯拉罕", "摩西", "大卫", "以利亚"], "a": "亚伯拉罕", "s": ""}, {"type": "single", "q": "保罗说这福音本是神的什么，要救一切相信的？", "o": ["大能", "智慧", "奥秘", "应许"], "a": "大能", "s": ""}, {"type": "single", "q": "第七章中保罗描述信徒内心的挣扎，核心是什么？", "o": ["立志行善却行不出来", "不明白律法精意", "遭受逼迫患难", "身体有疾病"], "a": "立志行善却行不出来", "s": ""}, {"type": "single", "q": "根据第八章，谁能使我们与基督的爱隔绝？", "o": ["患难逼迫", "死亡", "天使掌权者", "都不能"], "a": "都不能", "s": ""}, {"type": "single", "q": "以色列人跌倒，救恩便临到了谁？", "o": ["外邦人", "撒玛利亚人", "税吏", "妇女"], "a": "外邦人", "s": ""}, {"type": "single", "q": "保罗劝信徒将身体献上，当作什么样的祭？", "o": ["活祭", "燔祭", "赎罪祭", "平安祭"], "a": "活祭", "s": ""}, {"type": "single", "q": "保罗写罗马书时，他本人去过罗马吗？", "o": ["还没有去过", "已经去过一次", "正在罗马", "去过两次"], "a": "还没有去过", "s": ""}, {"type": "multiple", "q": "根据罗马书，以下哪些不能使人称义？", "o": ["行为", "遵行律法", "割礼", "信心"], "a": "行为,遵行律法,割礼", "s": ""}, {"type": "multiple", "q": "第八章提到圣灵的工作有哪些？", "o": ["释放我们脱离罪和死的律", "用说不出来的叹息替我们祷告", "见证我们是神的儿女", "定我们的罪"], "a": "释放我们脱离罪和死的律,用说不出来的叹息替我们祷告,见证我们是神的儿女", "s": ""}, {"type": "multiple", "q": "保罗在9-11章论到神对以色列的旨意，包括？", "o": ["神没有弃绝他的百姓", "外邦人数添满以色列全家都要得救", "以色列人永远被神弃绝", "救恩只归犹太人"], "a": "神没有弃绝他的百姓,外邦人数添满以色列全家都要得救", "s": ""}, {"type": "multiple", "q": "第十三章教导基督徒对待在上权柄当如何？", "o": ["顺服在上的权柄", "当纳的税给他", "当惧怕的惧怕他", "起来反抗不义之政"], "a": "顺服在上的权柄,当纳的税给他,当惧怕的惧怕他", "s": ""}, {"type": "judge", "q": "世人都犯了罪，亏缺了神的荣耀。", "a": "对", "s": ""}, {"type": "judge", "q": "人称义是因着信，不在乎遵行律法。", "a": "对", "s": ""}, {"type": "judge", "q": "受洗归入基督耶稣的人，就是受洗归入他的死。", "a": "对", "s": ""}, {"type": "judge", "q": "如今那些在基督耶稣里的，就不定罪了。", "a": "对", "s": ""}, {"type": "judge", "q": "以色列人跌倒，神就永远弃绝了他们。", "a": "错", "s": ""}, {"type": "judge", "q": "爱就完全了律法，所以爱人如己是律法的总纲。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗写罗马书时已经亲自去过罗马教会。", "a": "错", "s": ""}, {"type": "essay", "q": "什么是“因信称义”？它对基督徒的生活有何意义？", "a": "因信称义指人得称为义不是靠行为功德，而是因信耶稣基督的救赎，白白得神的恩典。意义在于：使人脱离靠行为得救的重担，得享与神和好的平安；确立救恩的根基在于基督已完成的工作；激励信徒以感恩的心活出圣洁，而非以功德换取救恩。", "s": ""}, {"type": "essay", "q": "罗马书第八章“圣灵里的生命”带给信徒哪些确据？", "a": "圣灵释放我们脱离罪和死的律；在基督里的就不定罪；圣灵用说不出来的叹息替我们祷告；万事互相效力叫爱神的人得益处；没有什么能叫我们与神的爱隔绝。这些确据使信徒在苦难中仍有不能动摇的盼望。", "s": ""}, {"type": "essay", "q": "“将身体献上当作活祭”在日常生活中应当如何实践？", "a": "活祭意味着将整个人生的主权交给神：时间、金钱、才能都为神所用；心意更新而变化，不效法这个世界；按所得恩赐彼此服事；以善胜恶、爱人如己。这不是一次性的奉献，而是每天持续地摆上自己，活出讨神喜悦的人生。", "s": ""}]','','study','[{"title": "福音的大能（1-2章）", "points": ["保罗的使徒职分与问安", "福音本是神的大能，要救一切相信的", "神的义在福音上显明，本于信以至于信", "外邦人在罪恶中，神的忿怒显明", "犹太人有律法也犯了罪", "神不偏待人，按行为报应各人", "律法本是叫人知罪"]}, {"title": "因信称义（3-5章）", "points": ["世人都犯了罪，亏缺神的荣耀", "人称义是因着信，不在乎遵行律法", "亚伯拉罕因信被算为义", "我们既因信称义，就得与神相和", "在亚当里众人都死了", "在基督里众人都要复活", "罪在哪里显多，恩典就更显多"]}, {"title": "成圣的生命（6-8章）", "points": ["受洗归入基督，向罪死向神活", "不要将肢体献给罪作不义的器具", "脱离律法的辖制，作义的奴仆", "立志行善却行不出来的挣扎", "靠圣灵脱离罪和死的律", "圣灵用说不出来的叹息替我们祷告", "万事互相效力，爱隔绝不了我们"]}, {"title": "以色列的奥秘（9-11章）", "points": ["保罗为同胞大有忧愁", "神主权的拣选：不在乎人的行为", "以色列人追求律法的义反得不着", "他们失脚，救恩临到外邦人", "野橄榄被接上，原枝子被折下", "神没有弃绝他的百姓", "外邦人数添满，以色列全家都要得救"]}, {"title": "献上活祭（12-16章）", "points": ["将身体献上当作圣洁的活祭", "心意更新而变化，察验神的旨意", "按所得恩赐彼此服事", "爱人如己，爱就完全了律法", "在上有权柄的，人人当顺服", "坚固的人当担代不坚固人的软弱", "保罗的问安、劝勉与祝福"]}]','','76','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-179122447523701','圣经导览','哥林多前书','哥林多前书是保罗写给哥林多教会的书信，针对分党结派、淫乱、圣餐混乱、恩赐纷争等问题，以十字架为根基教导圣洁、爱心与复活的盼望，爱篇（13章）为全书高峰，勉励信徒坚固不摇动、多做主工。','[{"type": "verse", "q": "爱是________，又有________；爱是不嫉妒，爱是不自夸。", "a": "恒久忍耐|恩慈", "ref": "《哥林多前书》13章4节", "s": "", "o": "哥林多前书13章4节"}, {"type": "verse", "q": "如今常存的有信，有望，有爱这三样，其中________的是爱。", "a": "最大", "ref": "《哥林多前书》13章13节", "s": "", "o": "哥林多前书13章13节"}, {"type": "verse", "q": "所以，我亲爱的弟兄们，你们务要________，不可摇动，常常竭力多做主工。", "a": "坚固", "ref": "《哥林多前书》15章58节", "s": "", "o": "哥林多前书15章58节"}, {"type": "verse", "q": "神是________的，必不叫你们受试探过于所能受的。", "a": "信实", "ref": "《哥林多前书》10章13节", "s": "", "o": "哥林多前书10章13节"}, {"type": "verse", "q": "岂不知你们的身子就是________的殿吗？这圣灵是从神而来，住在你们里头的。", "a": "圣灵", "ref": "《哥林多前书》6章19节", "s": "", "o": "哥林多前书6章19节"}, {"type": "verse", "q": "神为爱他的人所预备的是眼睛未曾________，耳朵未曾听见，人心也未曾想到的。", "a": "看见", "ref": "《哥林多前书》2章9节", "s": "", "o": "哥林多前书2章9节"}, {"type": "verse", "q": "你们务要________，在真道上站立得稳，要作大丈夫，要刚强。", "a": "警醒", "ref": "《哥林多前书》16章13节", "s": "", "o": "哥林多前书16章13节"}, {"type": "fill", "q": "保罗在哥林多前书指出，教会分党结派，有人说我是属________的，有人说我是属矶法的。", "a": "保罗", "s": ""}, {"type": "fill", "q": "保罗责备哥林多教会容忍淫乱，说：岂不知一点________能使全团发起来吗？", "a": "面酵", "s": ""}, {"type": "fill", "q": "保罗论婚姻说，没有娶妻的是为________的事挂虑，想怎样叫主喜悦。", "a": "主", "s": ""}, {"type": "fill", "q": "主耶稣在被卖的那一夜，拿起饼来祝谢了，就擘开，说：这是我的________，为你们舍的。", "a": "身体", "s": ""}, {"type": "fill", "q": "保罗论恩赐说：恩赐原有分别，圣灵却是一位；________虽有分别，主却是一位。", "a": "职事", "s": ""}, {"type": "fill", "q": "保罗说：你们就是基督的________，并且各自作肢体。", "a": "身子", "s": ""}, {"type": "fill", "q": "论到复活，保罗说：基督照圣经所说，为我们的________死了，而且埋葬了。", "a": "罪", "s": ""}, {"type": "fill", "q": "保罗说：凡我所行的，都是为________的缘故，为要与人同得这福音的好处。", "a": "福音", "s": ""}, {"type": "fill", "q": "保罗在书信结尾警告：若有人不爱主，这人________！", "a": "可咒可诅", "s": ""}, {"type": "fill", "q": "保罗说：知识是叫人________，惟有爱心能造就人。", "a": "自高自大", "s": ""}, {"type": "single", "q": "保罗说一点面酵能使全团发起来，这是针对哪件事的责备？", "o": ["分党结派", "容忍淫乱", "吃祭偶像之物", "妇女蒙头"], "a": "容忍淫乱", "s": ""}, {"type": "single", "q": "保罗说你们每逢吃这饼、喝这杯，是表明主的死，直等到他________。", "o": ["再来", "复活", "升天", "降生"], "a": "再来", "s": ""}, {"type": "single", "q": "哥林多前书12章论到属灵恩赐，保罗把教会比作什么？", "o": ["身体", "房屋", "军队", "学校"], "a": "身体", "s": ""}, {"type": "single", "q": "保罗说如今常存的有信、有望、有爱这三样，其中最大的是？", "o": ["信", "望", "爱", "忍耐"], "a": "爱", "s": ""}, {"type": "single", "q": "哥林多前书15章的主题是？", "o": ["论婚姻", "论复活", "论圣餐", "论恩赐"], "a": "论复活", "s": ""}, {"type": "single", "q": "保罗劝勉你们务要警醒，在真道上站立得稳之后，还劝他们要？", "o": ["作大丈夫，要刚强", "多多奉献", "常常禁食", "远离人群"], "a": "作大丈夫，要刚强", "s": ""}, {"type": "single", "q": "保罗说信徒的身子是圣灵的殿，因此应当？", "o": ["在身子上荣耀神", "禁食祷告", "独身事奉", "远离人群"], "a": "在身子上荣耀神", "s": ""}, {"type": "multiple", "q": "以下哪些是哥林多前书13章提到的爱的特质？", "o": ["恒久忍耐", "恩慈", "不嫉妒", "轻易发怒"], "a": "恒久忍耐,恩慈,不嫉妒", "s": ""}, {"type": "multiple", "q": "保罗在哥林多前书指出的教会问题有哪些？", "o": ["分党结派", "容忍淫乱", "圣餐混乱", "恩赐纷争"], "a": "分党结派,容忍淫乱,圣餐混乱,恩赐纷争", "s": ""}, {"type": "multiple", "q": "以下哪些是保罗在哥林多前书12章提到的属灵恩赐？", "o": ["智慧的言语", "知识的言语", "信心", "翻方言"], "a": "智慧的言语,知识的言语,信心,翻方言", "s": ""}, {"type": "multiple", "q": "哥林多前书15章提到，基督复活后显给哪些人看？", "o": ["矶法", "十二使徒", "五百多弟兄", "保罗"], "a": "矶法,十二使徒,五百多弟兄,保罗", "s": ""}, {"type": "judge", "q": "保罗说哥林多教会分党结派是属灵成熟的表现。", "a": "错", "s": ""}, {"type": "judge", "q": "保罗教导信徒的身子是圣灵的殿，应当在身子上荣耀神。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗说爱是恒久忍耐，又有恩慈；爱是不嫉妒。", "a": "对", "s": ""}, {"type": "judge", "q": "哥林多前书15章说，若基督没有复活，我们的信便是徒然。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗认为知识是叫人自高自大，惟有爱心能造就人。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗说设立圣餐是为记念主的降生。", "a": "错", "s": ""}, {"type": "judge", "q": "保罗劝勉信徒你们务要警醒，在真道上站立得稳。", "a": "对", "s": ""}, {"type": "essay", "q": "哥林多前书13章论到爱的哪几方面特质？对今日信徒有何提醒？", "a": "爱是恒久忍耐、又有恩慈，不嫉妒、不自夸、不张狂，不做害羞的事、不求自己的益处、不轻易发怒、不计算人的恶，不喜欢不义、只喜欢真理；凡事包容、凡事相信、凡事盼望、凡事忍耐，爱是永不止息。提醒今日信徒：恩赐、知识、方言终将过去，惟有爱永存；事奉若没有爱，就成了鸣的锣、响的钹；行事为人当以爱为最高准则，用爱心说诚实话。", "s": ""}, {"type": "essay", "q": "保罗在哥林多前书15章如何论证基督复活的真实性？这对信徒的盼望有何意义？", "a": "保罗列举复活的见证人：基督先显给矶法看，又显给十二使徒看，后来一时显给五百多弟兄看，最后也显给他自己看；又指出若基督没有复活，所传的便是枉然，信也是枉然，仍在罪里。这给信徒确据：基督复活是睡了之人初熟的果子，信他的人将来也必复活；因此当坚固不摇动、常常竭力多做主工，因为劳苦在主里面不是徒然的。", "s": ""}, {"type": "essay", "q": "哥林多前书指出哥林多教会有分党、淫乱、圣餐混乱等问题，保罗的解决之道是什么？对今日教会有何借鉴？", "a": "保罗以十字架的道理为根基：分党是高举人，要单单高举基督；淫乱要除去旧酵、圣洁自守；圣餐要省察自己、记念主死；恩赐纷争要彼此配搭、以爱为上。对今日教会的借鉴：教会问题多源于属肉体与自我中心，解决之道不是人的方法，而是回到十字架、以爱心说诚实话、让基督居首位，凡事规规矩矩按次序行。", "s": ""}]','','study','[{"title": "分党与十字架（1-4章）", "points": ["哥林多教会分党结派：属保罗、属亚波罗、属矶法、属基督", "保罗指出分党是属肉体、属世俗的表现", "十字架的道理：在灭亡的人为愚拙，在得救的人为神的大能", "神拣选世上愚拙的，叫有智慧的羞愧", "传道不靠智慧委婉的言语，只靠圣灵的大能", "信徒是神的殿，神的灵住在其中", "保罗栽种、亚波罗浇灌，惟有神叫他生长"]}, {"title": "圣洁与纪律（5-7章）", "points": ["责备教会容忍淫乱：一点面酵能使全团发起来", "要把行恶的人从中间赶出去，除去旧酵", "信徒彼此告状是羞耻，宁可吃亏", "身子是圣灵的殿，要在身子上荣耀神", "论婚姻：独身与结婚各有恩赐，未婚者可专心事主", "已婚者不可彼此亏负，惟为禁食祷告暂时分房", "各人蒙召时是什么身份，仍要守住这身份"]}, {"title": "圣餐与敬拜（8-11章）", "points": ["知识叫人自高自大，惟有爱心能造就人", "吃祭偶像之物：凡事都可行，但不都有益处", "不可绊倒软弱的弟兄，爱心大过知识", "妇女蒙头与敬拜中的次序", "圣餐混乱：有人先吃自己的饭，羞辱贫穷人", "主的晚餐：这是我的身体，为你们舍的", "吃喝要省察自己，记念主的死直等到他来"]}, {"title": "恩赐与爱（12-14章）", "points": ["恩赐原有分别，圣灵却是一位；职事有分别，主却是一位", "教会是基督的身体，各自作肢体，彼此配搭", "眼不能对手说我用不着你", "爱篇：爱是恒久忍耐、又有恩慈，不嫉妒不自夸", "先知讲道、方言、知识终必归于无有，惟爱永不止息", "如今常存的有信有望有爱，其中最大的是爱", "聚会中凡事都要规规矩矩地按着次序行"]}, {"title": "复活与盼望（15-16章）", "points": ["基督照圣经所说为我们的罪死了，第三天复活了", "复活的见证：矶法、十二使徒、五百多弟兄、保罗", "若基督没有复活，信便是徒然，仍在罪里", "基督是睡了之人初熟的果子", "血肉之体不能承受神的国，号筒末次吹响时都要改变", "务要坚固不可摇动，劳苦在主里不是徒然", "劝勉：警醒、站立得稳、作大丈夫、要刚强"]}]','','77','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-179122447523702','圣经导览','哥林多后书','哥林多后书是保罗为使徒职分辩白的书信，论患难中的安慰、新约精意的职事、瓦器里的宝贝、与神和好、乐捐的原则，见证我的恩典够你用的应许，勉励信徒在软弱中经历神的大能，劝人与神和好。','[{"type": "verse", "q": "他对我说：我的________够你用的，因为我的能力是在人的软弱上显得完全。", "a": "恩典", "ref": "《哥林多后书》12章9节", "s": "", "o": "哥林多后书12章9节"}, {"type": "verse", "q": "若有人在基督里，他就是________的人，旧事已过，都变成新的了。", "a": "新造", "ref": "《哥林多后书》5章17节", "s": "", "o": "哥林多后书5章17节"}, {"type": "verse", "q": "我们有这宝贝放在________里，要显明这莫大的能力是出于神，不是出于我们。", "a": "瓦器", "ref": "《哥林多后书》4章7节", "s": "", "o": "哥林多后书4章7节"}, {"type": "verse", "q": "主就是那灵；主的灵在哪里，那里就得以________。", "a": "自由", "ref": "《哥林多后书》3章17节", "s": "", "o": "哥林多后书3章17节"}, {"type": "verse", "q": "各人要随本心所酌定的，不要作难，不要勉强，因为________的人是神所喜爱的。", "a": "捐得乐意", "ref": "《哥林多后书》9章7节", "s": "", "o": "哥林多后书9章7节"}, {"type": "verse", "q": "愿颂赞归与我们的主耶稣基督的父神，就是发慈悲的父，赐________的神。", "a": "各样安慰", "ref": "《哥林多后书》1章3节", "s": "", "o": "哥林多后书1章3节"}, {"type": "verse", "q": "所以，我们不丧胆。外体虽然毁坏，________却一天新似一天。", "a": "内心", "ref": "《哥林多后书》4章16节", "s": "", "o": "哥林多后书4章16节"}, {"type": "fill", "q": "保罗说他身上的那根刺是________的差役，免得他过于自高。", "a": "撒但", "s": ""}, {"type": "fill", "q": "保罗论新约的执事：不是凭着字句，乃是凭着________；因为那字句是叫人死，精意是叫人活。", "a": "精意", "s": ""}, {"type": "fill", "q": "保罗说，神在基督里叫世人与自己________，不将他们的过犯归到他们身上。", "a": "和好", "s": ""}, {"type": "fill", "q": "保罗劝哥林多信徒：你们总要自己________有信心没有，也要自己试验。", "a": "省察", "s": ""}, {"type": "fill", "q": "论捐助，保罗说：________的少收，多种的多收，这是属灵的定律。", "a": "少种", "s": ""}, {"type": "fill", "q": "保罗说：基督本来富足，却为你们成了________，叫你们因他的贫穷可以成为富足。", "a": "贫穷", "s": ""}, {"type": "fill", "q": "保罗说：我们争战的兵器本不是属________的，乃是在神面前有能力。", "a": "血气", "s": ""}, {"type": "fill", "q": "保罗在哥林多后书说，神用各样安慰安慰我们，叫我们能去安慰那遭各样________的人。", "a": "患难", "s": ""}, {"type": "fill", "q": "保罗说：我为基督的缘故，就以软弱、凌辱、急难、逼迫、困苦为可喜乐的，因我什么时候________，什么时候就刚强了。", "a": "软弱", "s": ""}, {"type": "fill", "q": "论到提多，保罗说：他是我的________，与我同为你们劳碌的。", "a": "同伴", "s": ""}, {"type": "single", "q": "保罗身上的刺是什么？", "o": ["疾病", "撒但的差役", "逼迫", "贫穷"], "a": "撒但的差役", "s": ""}, {"type": "single", "q": "主对保罗说我的恩典够你用的，是在什么处境下？", "o": ["三次求主挪去刺", "被下监", "船坏", "被鞭打"], "a": "三次求主挪去刺", "s": ""}, {"type": "single", "q": "哥林多后书3章说，新约的执事是凭着什么？", "o": ["字句", "精意", "律法", "传统"], "a": "精意", "s": ""}, {"type": "single", "q": "保罗把传道人比作什么器皿？", "o": ["金器", "银器", "瓦器", "铜器"], "a": "瓦器", "s": ""}, {"type": "single", "q": "哥林多后书8-9章的主题是？", "o": ["论复活", "论捐助", "论婚姻", "论恩赐"], "a": "论捐助", "s": ""}, {"type": "single", "q": "保罗说若有人在基督里，他就是？", "o": ["完全人", "新造的人", "义人", "圣人"], "a": "新造的人", "s": ""}, {"type": "single", "q": "马其顿众教会在极穷之间，还格外显出什么？", "o": ["乐捐的厚恩", "祷告", "禁食", "传道"], "a": "乐捐的厚恩", "s": ""}, {"type": "multiple", "q": "保罗说他为基督的缘故，以哪些为可喜乐的？", "o": ["软弱", "凌辱", "逼迫", "困苦"], "a": "软弱,凌辱,逼迫,困苦", "s": ""}, {"type": "multiple", "q": "以下哪些是保罗论捐助的原则？", "o": ["随本心所酌定", "不要作难勉强", "捐得乐意", "越多越好"], "a": "随本心所酌定,不要作难勉强,捐得乐意", "s": ""}, {"type": "multiple", "q": "神在基督里与世人和好，托付了我们什么？", "o": ["和好的道理", "和好的职分", "审判的权柄", "律法的要求"], "a": "和好的道理,和好的职分", "s": ""}, {"type": "multiple", "q": "保罗说新约执事的特点包括？", "o": ["不是凭字句乃凭精意", "精意叫人活", "主的灵在哪里就得以自由", "靠行为称义"], "a": "不是凭字句乃凭精意,精意叫人活,主的灵在哪里就得以自由", "s": ""}, {"type": "judge", "q": "保罗说他身上的那根刺是撒但的差役。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗三次求主叫刺离开他，主就应允挪去了刺。", "a": "错", "s": ""}, {"type": "judge", "q": "保罗说我的恩典够你用的，因为我的能力是在人的软弱上显得完全。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗教导捐助要勉强多捐，这样才是神所喜爱的。", "a": "错", "s": ""}, {"type": "judge", "q": "保罗说若有人在基督里，他就是新造的人。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗说我们有这宝贝放在金器里。", "a": "错", "s": ""}, {"type": "judge", "q": "保罗劝信徒要自己省察有信心没有，也要自己试验。", "a": "对", "s": ""}, {"type": "essay", "q": "保罗身上的刺是什么？主说我的恩典够你用的对今日受苦的信徒有何安慰？", "a": "保罗说那根刺是撒但的差役，要攻击我，免得我过于自高。他三次求主挪去，主却说：我的恩典够你用的，因为我的能力是在人的软弱上显得完全。对今日信徒的安慰：神不一定挪去苦难，但他的恩典够用；人的软弱正是神能力彰显之处；保罗因此以软弱为可喜乐，因什么时候软弱、什么时候就刚强。苦难不是神缺席的证据，而是经历恩典的管道。", "s": ""}, {"type": "essay", "q": "哥林多后书8-9章论到捐助的哪些原则？对今日教会奉献有何指导？", "a": "原则包括：先把自己献给主（马其顿教会榜样）；随本心所酌定，不作难、不勉强；捐得乐意的人是神所喜爱的；少种少收、多种多收；神能将各样恩惠多多加给，使凡事充足、多行善事。对今日教会的指导：奉献是恩典不是税赋，甘心乐意重于数额；教会当教导信徒以感恩奉献，而非以压力索取；神必供应乐捐者的需要。", "s": ""}, {"type": "essay", "q": "我们有这宝贝放在瓦器里是什么意思？对传道人及信徒的自我认识有何提醒？", "a": "宝贝指福音真光、认识基督的知识；瓦器指传道人软弱、卑微、易碎的肉身。意思是：福音的大能全然出于神，不出于传道人自己；器皿越卑微软弱，越显明能力属神。提醒：传道人不应倚靠自己的才干口才，而要倚靠神；信徒不因软弱灰心，神乐意使用瓦器；成功时不归功自己，失败时不致绝望——四面受敌却不被困住，遭逼迫却不被丢弃。", "s": ""}]','','study','[{"title": "患难中的安慰（1-2章）", "points": ["愿颂赞归与发慈悲的父、赐各样安慰的神", "我们在患难中得安慰，就能安慰遭各样患难的人", "保罗在亚细亚遭遇苦难，被压太重力不能胜", "神曾救我们脱离极大的死亡，现在仍要救我们", "保罗为行程辩白：所行的并有用心计吗", "饶恕悔改的人，免得他忧愁太过", "在基督里夸胜，散发基督馨香之气"]}, {"title": "新约的职事（3-4章）", "points": ["你们就是我们的荐信，写在心版上", "新约的执事：不是凭字句，乃是凭精意", "字句叫人死，精意叫人活", "主就是那灵，主的灵在哪里那里就得以自由", "我们有这宝贝放在瓦器里，能力出于神", "四面受敌却不被困住，遭逼迫却不被丢弃", "外体虽毁坏内心却一天新似一天，至暂至轻的苦楚成就极重无比的荣耀"]}, {"title": "与神和好（5-7章）", "points": ["地上的帐棚拆毁，必得神所造天上的房屋", "行事为人是凭着信心，不是凭着眼见", "若有人在基督里，他就是新造的人", "神在基督里叫世人与自己和好，将和好的道理托付我们", "我们作基督的使者，替基督求你们与神和好", "神使那无罪的替我们成为罪，好叫我们成为神的义", "洁净自己，除去身体灵魂一切的污秽"]}, {"title": "捐助的原则（8-9章）", "points": ["马其顿众教会在患难中格外显出乐捐的厚恩", "先把自己献给主，又归附了我们", "基督本来富足，却为你们成了贫穷", "少种的少收，多种的多收", "各人随本心酌定，不作难不勉强，捐得乐意是神所喜爱的", "神能将各样恩惠多多加给你们，凡事充足多行善事", "感谢神，因他有说不尽的恩赐"]}, {"title": "使徒的辩白（10-13章）", "points": ["争战的兵器不是属血气的，能攻破坚固营垒", "保罗被迫自夸：论出身、论劳苦、论启示", "身上的刺：撒但的差役，免得过于自高", "三次求主挪去，主说我的恩典够你用的", "什么时候软弱，什么时候就刚强了", "你们总要自己省察有信心没有", "愿主耶稣基督的恩惠、神的慈爱、圣灵的感动常与众人同在"]}]','','78','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-179122447523703','圣经导览','加拉太书','加拉太书是保罗为因信称义真理辩护的书信，驳斥靠行律法称义的错谬，阐明圣灵与情欲相争、圣灵所结九种果子，呼召信徒在基督里得自由、只夸基督十字架，不再被奴仆的轭挟制，在爱中彼此服事。','[{"type": "verse", "q": "圣灵所结的果子，就是仁爱、喜乐、________、忍耐、恩慈、良善、信实、温柔、节制。", "a": "和平", "ref": "《加拉太书》5章22节", "s": "", "o": "加拉太书5章22节"}, {"type": "verse", "q": "我已经与基督同钉十字架，现在活着的不再是________，乃是基督在我里面活着。", "a": "我", "ref": "《加拉太书》2章20节", "s": "", "o": "加拉太书2章20节"}, {"type": "verse", "q": "既知道人称义不是因________，乃是因信耶稣基督。", "a": "行律法", "ref": "《加拉太书》2章16节", "s": "", "o": "加拉太书2章16节"}, {"type": "verse", "q": "基督释放了我们，叫我们得以________。所以要站立得稳，不要再被奴仆的轭挟制。", "a": "自由", "ref": "《加拉太书》5章1节", "s": "", "o": "加拉太书5章1节"}, {"type": "verse", "q": "但我断不以别的夸口，只夸我们主耶稣基督的________。", "a": "十字架", "ref": "《加拉太书》6章14节", "s": "", "o": "加拉太书6章14节"}, {"type": "verse", "q": "因为情欲和________相争，圣灵和情欲相争，这两个是彼此相敌。", "a": "圣灵", "ref": "《加拉太书》5章17节", "s": "", "o": "加拉太书5章17节"}, {"type": "verse", "q": "不要自欺，神是________不得的。人种的是什么，收的也是什么。", "a": "轻慢", "ref": "《加拉太书》6章7节", "s": "", "o": "加拉太书6章7节"}, {"type": "fill", "q": "保罗责备加拉太人：你们既靠圣灵入门，如今还靠________成全吗？", "a": "肉身", "s": ""}, {"type": "fill", "q": "保罗说：你们因信基督耶稣，都是神的________。", "a": "儿子", "s": ""}, {"type": "fill", "q": "保罗劝勉：你们当顺着圣灵而行，就不放纵肉体的________了。", "a": "情欲", "s": ""}, {"type": "fill", "q": "保罗列出情欲的事后警告：行这样事的人，必不能承受神的________。", "a": "国", "s": ""}, {"type": "fill", "q": "保罗说：我们行善，不可________；若不灰心，到了时候就要收成。", "a": "丧志", "s": ""}, {"type": "fill", "q": "保罗说：各人必担当自己的________。", "a": "担子", "s": ""}, {"type": "fill", "q": "保罗问加拉太人：我现在是要得人的心呢，还是要得神的心呢？我岂是讨人的________吗？", "a": "喜欢", "s": ""}, {"type": "fill", "q": "保罗说：律法是我们训蒙的________，引我们到基督那里，使我们因信称义。", "a": "师傅", "s": ""}, {"type": "fill", "q": "保罗说：基督为我们受了咒诅，就赎出我们脱离律法的________。", "a": "咒诅", "s": ""}, {"type": "fill", "q": "保罗劝弟兄们：若有人偶然被过犯所胜，属灵的人当用________的心把他挽回过来。", "a": "温柔", "s": ""}, {"type": "single", "q": "加拉太书的中心主题是？", "o": ["因信称义", "爱心", "复活", "圣餐"], "a": "因信称义", "s": ""}, {"type": "single", "q": "保罗说人称义不是因行律法，乃是因？", "o": ["善行", "信耶稣基督", "守安息日", "受割礼"], "a": "信耶稣基督", "s": ""}, {"type": "single", "q": "以下哪一项不属于圣灵的果子？", "o": ["仁爱", "嫉妒", "和平", "节制"], "a": "嫉妒", "s": ""}, {"type": "single", "q": "保罗说他断不以别的夸口，只夸什么？", "o": ["自己的学问", "主耶稣基督的十字架", "使徒的权柄", "神迹奇事"], "a": "主耶稣基督的十字架", "s": ""}, {"type": "single", "q": "保罗责备加拉太人靠什么成全？", "o": ["圣灵", "肉身", "信心", "爱心"], "a": "肉身", "s": ""}, {"type": "single", "q": "律法在救恩历史中的作用是？", "o": ["使人称义", "训蒙的师傅引人到基督", "代替基督", "废掉信心"], "a": "训蒙的师傅引人到基督", "s": ""}, {"type": "single", "q": "保罗说各人必担当自己的？", "o": ["罪孽", "担子", "十字架", "产业"], "a": "担子", "s": ""}, {"type": "multiple", "q": "以下哪些属于圣灵的果子？", "o": ["仁爱", "喜乐", "和平", "嫉妒"], "a": "仁爱,喜乐,和平", "s": ""}, {"type": "multiple", "q": "保罗列出的情欲的事包括？", "o": ["奸淫", "拜偶像", "仇恨", "仁爱"], "a": "奸淫,拜偶像,仇恨", "s": ""}, {"type": "multiple", "q": "保罗说基督徒的自由应当如何使用？", "o": ["不可将自由当作放纵情欲的机会", "总要用爱心互相服侍", "全律法都包在爱人如己中", "随心所欲"], "a": "不可将自由当作放纵情欲的机会,总要用爱心互相服侍,全律法都包在爱人如己中", "s": ""}, {"type": "multiple", "q": "加拉太书中保罗为福音辩护的论据包括？", "o": ["他的使徒职分从神而来", "亚伯拉罕因信称义的榜样", "律法是训蒙的师傅", "靠行律法称义"], "a": "他的使徒职分从神而来,亚伯拉罕因信称义的榜样,律法是训蒙的师傅", "s": ""}, {"type": "judge", "q": "保罗说人称义是因行律法，不是因信耶稣基督。", "a": "错", "s": ""}, {"type": "judge", "q": "保罗说我已经与基督同钉十字架，现在活着的不再是我。", "a": "对", "s": ""}, {"type": "judge", "q": "圣灵的果子包括仁爱、喜乐、和平、忍耐、恩慈、良善、信实、温柔、节制。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗说情欲和圣灵相争，使你们不能做所愿意做的。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗以自己的学问和出身夸口。", "a": "错", "s": ""}, {"type": "judge", "q": "保罗说各人必担当自己的担子。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗说行善不可丧志，若不灰心到了时候就要收成。", "a": "对", "s": ""}, {"type": "essay", "q": "加拉太书2章16节人称义不是因行律法，乃是因信耶稣基督是什么意思？对今日信徒有何意义？", "a": "意思是：人得称为义、与神和好，不是靠遵行律法条文、靠自己的行为功德，而是因信靠耶稣基督的救赎。律法叫人知罪，不能救人；基督为我们受咒诅，赎我们脱离律法的咒诅。对今日信徒的意义：救恩全是恩典，不靠行为；警惕靠行为称义的律法主义倾向，无论是靠守规条、靠功德还是靠宗教表现；同时真信心必结出圣灵果子，自由不是放纵的借口。", "s": ""}, {"type": "essay", "q": "圣灵的果子（加5:22-23）有哪九样？与情欲的事有何对比？信徒当如何结出圣灵的果子？", "a": "九样果子：仁爱、喜乐、和平、忍耐、恩慈、良善、信实、温柔、节制。对比：情欲的事如奸淫、拜偶像、仇恨、嫉妒、醉酒等，行这样事的人不能承受神的国；圣灵的果子则是生命的彰显，这样的事没有律法禁止。结出果子之道：顺着圣灵而行，不放纵肉体情欲；与基督同钉十字架，把邪情私欲钉死；果子是结出来的，不是做出来的——是圣灵在顺服者生命中的自然产物。", "s": ""}, {"type": "essay", "q": "保罗说断不以别的夸口，只夸基督的十字架，这对今日信徒的价值观有何挑战？", "a": "保罗拒绝以割礼、出身、学问、功德夸口，单单夸耀基督的十字架——因这十字架，世界向他已经钉死，他向世界也已经钉死。对今日信徒的挑战：在看重学历、财富、地位、事工果效的文化中，是否仍以十字架为唯一的夸口？是否把人的荣耀带进教会？十字架意味着舍己与顺服，信徒当省察：我所夸的是基督还是自己？安全感是建立在十字架上，还是世界的肯定上？", "s": ""}]','','study','[{"title": "使徒的辩白（1-2章）", "points": ["保罗的使徒职分不是从人来，乃是从神和基督来", "若仍讨人喜欢，就不是基督的仆人", "所传的福音不是从人领受，乃是从基督启示", "奉启示上耶路撒冷，与彼得、雅各相见", "当面抵挡彼得：他因怕奉割礼的人而装假", "人称义不是因行律法，乃是因信耶稣基督", "我已经与基督同钉十字架，基督在我里面活着"]}, {"title": "因信称义（3-4章）", "points": ["你们既靠圣灵入门，如今还靠肉身成全吗", "亚伯拉罕信神，这就算为他的义", "以信为本的人和有信心的亚伯拉罕一同得福", "律法是我们训蒙的师傅，引我们到基督那里", "你们因信基督耶稣都是神的儿子", "并不分犹太人、希腊人，俱各为一", "基督释放我们得自由，不要再被奴仆的轭挟制"]}, {"title": "圣灵与情欲（5章）", "points": ["当顺着圣灵而行，就不放纵肉体的情欲", "情欲和圣灵相争，使你们不能做所愿意做的", "情欲的事：奸淫、拜偶像、仇恨、嫉妒、醉酒等", "行这样事的人必不能承受神的国", "圣灵的果子：仁爱、喜乐、和平、忍耐、恩慈、良善、信实、温柔、节制", "属基督的人已把肉体连同邪情私欲钉在十字架上", "全律法都包在爱人如己这一句话之内"]}, {"title": "彼此担当（6章）", "points": ["若有人被过犯所胜，用温柔的心把他挽回", "各人的重担要互相担当，如此就完全了基督的律法", "各人必担当自己的担子", "不要自欺，神是轻慢不得的；种什么收什么", "顺着情欲撒种的必收败坏，顺着圣灵撒种的必收永生", "行善不可丧志，若不灰心到了时候就要收成", "有了机会就当向众人行善，向信徒一家更当如此"]}, {"title": "十字架的夸口（6章）", "points": ["勉强人受割礼的，是怕为基督十字架受逼迫", "受割礼的不守律法，愿你们受割礼好夸耀你们的肉体", "断不以别的夸口，只夸主耶稣基督的十字架", "因这十字架，世界向我钉死，我向世界钉死", "受割礼不受割礼都无关紧要，要紧的是作新造的人", "从今以后人都不要搅扰我，我身上带着耶稣的印记", "愿主耶稣基督的恩常在你们心里"]}]','','79','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220980001','圣经导览','以弗所书','保罗在罗马狱中致以弗所教会，阐明信徒“在基督里”的丰盛福气：创世前蒙拣选、藉爱子血得蒙救赎、得救本乎恩也因着信。教会是基督的身体，信徒当脱去旧人穿上新人，穿戴神所赐的全副军装，靠主刚强抵挡魔鬼。','[{"type": "verse", "q": "【经文填空】你们得救是本乎____，也因着____；这并不是出于自己，乃是神所赐的。", "a": "恩|信", "ref": "《以弗所书》2章8节", "s": "", "o": "以弗所书2章8节"}, {"type": "verse", "q": "【经文填空】也不是出于____，免得有人____。", "a": "行为|自夸", "ref": "《以弗所书》2章9节", "s": "", "o": "以弗所书2章9节"}, {"type": "verse", "q": "【经文填空】我们藉这爱子的____得蒙救赎，____得以赦免，乃是照他丰富的恩典。", "a": "血|过犯", "ref": "《以弗所书》1章7节", "s": "", "o": "以弗所书1章7节"}, {"type": "verse", "q": "【经文填空】要穿戴神所赐的____，就能抵挡魔鬼的____。", "a": "全副军装|诡计", "ref": "《以弗所书》6章11节", "s": "", "o": "以弗所书6章11节"}, {"type": "verse", "q": "【经文填空】并戴上救恩的____，拿着圣灵的____，就是神的道。", "a": "头盔|宝剑", "ref": "《以弗所书》6章17节", "s": "", "o": "以弗所书6章17节"}, {"type": "verse", "q": "【经文填空】并要以____相待，存____的心，彼此饶恕，正如神在基督里饶恕了你们一样。", "a": "恩慈|怜悯", "ref": "《以弗所书》4章32节", "s": "", "o": "以弗所书4章32节"}, {"type": "verse", "q": "【经文填空】我们原是他的____，在基督耶稣里造成的，为要叫我们____。", "a": "工作|行善", "ref": "《以弗所书》2章10节", "s": "", "o": "以弗所书2章10节"}, {"type": "fill", "q": "以弗所书的中心短语是“在____里”，全书出现约三十多次。", "a": "基督", "s": ""}, {"type": "fill", "q": "神从____以前，在基督里拣选了我们。", "a": "创立世界", "s": ""}, {"type": "fill", "q": "信徒听见真理的道、信了基督，就受了所应许的____为印记。", "a": "圣灵", "s": ""}, {"type": "fill", "q": "基督拆毁了犹太人和外邦人中间____的墙，使两下合而为一。", "a": "隔断", "s": ""}, {"type": "fill", "q": "教会“被建造在使徒和先知的____上，有基督耶稣自己为房角石”。", "a": "根基", "s": ""}, {"type": "fill", "q": "保罗为信徒祷告，求神“藉着他的灵，叫你们心里的力量____起来”。", "a": "刚强", "s": ""}, {"type": "fill", "q": "“生气却不要____，不可含怒到日落”。", "a": "犯罪", "s": ""}, {"type": "fill", "q": "“不要醉酒……乃要被____充满”。", "a": "圣灵", "s": ""}, {"type": "fill", "q": "作丈夫的要爱妻子，“正如基督爱____，为____舍己”。", "a": "教会|教会", "s": ""}, {"type": "fill", "q": "“你们作儿女的，要在____听从父母，这是理所当然的”。", "a": "主里", "s": ""}, {"type": "single", "q": "以弗所书共有几章？", "o": ["4章", "5章", "6章", "7章"], "a": "6章", "s": ""}, {"type": "single", "q": "“一主，一信，一洗，一神”出自以弗所书第几章？", "o": ["第1章", "第2章", "第3章", "第4章"], "a": "第4章", "s": ""}, {"type": "single", "q": "保罗打发谁把这封信带到以弗所？", "o": ["推基古", "提摩太", "提多", "以巴弗提"], "a": "推基古", "s": ""}, {"type": "single", "q": "弗4:11所列五重职分不包括哪一项？", "o": ["使徒", "先知", "传福音的", "执事"], "a": "执事", "s": ""}, {"type": "single", "q": "属灵军装中，“公义”当作什么？", "o": ["护心镜", "头盔", "腰带", "藤牌"], "a": "护心镜", "s": ""}, {"type": "single", "q": "以弗所书写作时保罗身在何处？", "o": ["罗马监狱", "耶路撒冷", "安提阿", "哥林多"], "a": "罗马监狱", "s": ""}, {"type": "single", "q": "弗5章论夫妻关系，妻子的本分是？", "o": ["顺服自己的丈夫", "管辖丈夫", "与丈夫争竞", "凡事自己作主"], "a": "顺服自己的丈夫", "s": ""}, {"type": "multiple", "q": "弗4:4-6提到哪几个“一”？", "o": ["一主", "一信", "一洗", "一神"], "a": "一主,一信,一洗,一神", "s": ""}, {"type": "multiple", "q": "以下哪些属于神所赐全副军装的内容？", "o": ["真理的腰带", "公义的护心镜", "救恩的头盔", "圣灵的宝剑"], "a": "真理的腰带,公义的护心镜,救恩的头盔,圣灵的宝剑", "s": ""}, {"type": "multiple", "q": "弗2章描述信徒得救前光景包括？", "o": ["死在过犯罪恶之中", "随从今世的风俗", "放纵肉体的私欲", "行在光明中"], "a": "死在过犯罪恶之中,随从今世的风俗,放纵肉体的私欲", "s": ""}, {"type": "multiple", "q": "保罗在弗1章为信徒的祷告内容包括？", "o": ["照明心中的眼睛", "知道所赐的指望", "知道基业的丰盛", "知道能力的浩大"], "a": "照明心中的眼睛,知道所赐的指望,知道基业的丰盛,知道能力的浩大", "s": ""}, {"type": "judge", "q": "以弗所书的核心主题是“在基督里”。", "a": "对", "s": ""}, {"type": "judge", "q": "得救是本乎恩，也因着行为。", "a": "错", "s": ""}, {"type": "judge", "q": "教会是基督的身体，基督是教会的头。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗教导信徒可以醉酒放荡。", "a": "错", "s": ""}, {"type": "judge", "q": "生气本身就是犯罪。", "a": "错", "s": ""}, {"type": "judge", "q": "儿女要在主里听从父母，这是理所当然的。", "a": "对", "s": ""}, {"type": "judge", "q": "我们争战的对象是属血气的。", "a": "错", "s": ""}, {"type": "essay", "q": "解释“你们得救是本乎恩，也因着信；也不是出于行为”的含义。", "a": "得救完全是神的恩典，人凭信心领受，不是靠行为功德，免得有人自夸；但得救后必有行善的生命见证。", "s": ""}, {"type": "essay", "q": "以弗所书6章属灵军装的各项装备及其属灵意义是什么？", "a": "真理腰带、公义护心镜、平安福音鞋、信德藤牌、救恩头盔、圣灵宝剑（神的道），加上随时多方祷告，装备信徒抵挡魔鬼。", "s": ""}, {"type": "essay", "q": "以弗所书如何论述教会是基督的身体？", "a": "教会是基督的身体，基督是头；信徒被建造在使徒先知根基上，房角石是基督；教会彰显神百般的智慧，满有基督长成的身量。", "s": ""}]','','study','[{"title": "在基督里的福气（1章）", "points": ["愿颂赞归与父神：在基督里赐天上各样属灵福气", "创世前拣选：使我们成为圣洁无瑕疵", "藉爱子血得蒙救赎，过犯得赦免", "受圣灵为印记：得基业的凭据", "保罗的祷告：照明心眼，知道指望与能力", "基督为教会作万有之首"]}, {"title": "得救本乎恩（2章）", "points": ["从前死在过犯罪恶之中，随从今世风俗", "神因大爱叫我们与基督一同活过来", "得救本乎恩因着信，不是出于行为", "我们是神的工作，在基督里为行善而造", "拆毁隔断的墙：两下合而为一", "与圣徒同国，是神家里的人", "建造在使徒先知根基上，基督为房角石"]}, {"title": "教会的奥秘（3章）", "points": ["外邦人在基督里同为后嗣、同为一体", "保罗作福音执事：把奥秘传给外邦人", "教会彰显神百般的智慧", "在父面前屈膝：求心里的力量刚强", "基督因信住在心里，爱心有根有基", "神能充充足足成就一切，超过所求所想"]}, {"title": "新人的生活（4-5章）", "points": ["行事与蒙召的恩相称：谦虚温柔忍耐", "一主一信一洗一神：竭力保守合一", "五重职分：成全圣徒，建立基督身体", "脱去旧人，穿上新人", "生气却不要犯罪，不可含怒到日落", "以恩慈怜悯彼此饶恕", "不要醉酒，乃要被圣灵充满", "夫妻之道：爱与顺服，预表基督与教会"]}, {"title": "属灵的军装（6章）", "points": ["靠主倚赖大能大力作刚强的人", "穿戴全副军装，抵挡魔鬼诡计", "争战对象：管辖幽暗世界的恶魔", "真理腰带、公义护心镜、平安福音鞋", "信德藤牌、救恩头盔、圣灵宝剑", "靠圣灵随时多方祷告祈求", "儿女父母、仆人主人的本分", "推基古送信，保罗祝福"]}]','','80','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220980002','圣经导览','腓立比书','保罗在狱中写给腓立比教会，称为“喜乐的书信”。虽身陷捆锁，保罗仍劝勉“靠主常常喜乐”。书中高举基督虚己的榜样（2:5-11），见证“忘记背后、努力面前”的标竿人生，宣告信徒是天上的国民，等候救主降临。','[{"type": "verse", "q": "【经文填空】因我活着就是____，我死了就有____。", "a": "基督|益处", "ref": "《腓立比书》1章21节", "s": "", "o": "腓立比书1章21节"}, {"type": "verse", "q": "【经文填空】你们当以基督耶稣的____为____。", "a": "心|心", "ref": "《腓立比书》2章5节", "s": "", "o": "腓立比书2章5节"}, {"type": "verse", "q": "【经文填空】我们却是____的国民，并且等候____从天上降临。", "a": "天上|救主", "ref": "《腓立比书》3章20节", "s": "", "o": "腓立比书3章20节"}, {"type": "verse", "q": "【经文填空】你们要靠主常常____！我再说，你们要____！", "a": "喜乐|喜乐", "ref": "《腓立比书》4章4节", "s": "", "o": "腓立比书4章4节"}, {"type": "verse", "q": "【经文填空】应当一无____，只要凡事藉着祷告、祈求和感谢，将你们所要的告诉神。", "a": "挂虑", "ref": "《腓立比书》4章6节", "s": "", "o": "腓立比书4章6节"}, {"type": "verse", "q": "【经文填空】我靠着那加给我____的，凡事都能做。", "a": "力量", "ref": "《腓立比书》4章13节", "s": "", "o": "腓立比书4章13节"}, {"type": "verse", "q": "【经文填空】我的神必照他荣耀的丰富，在基督耶稣里，使你们一切____都充足。", "a": "所需用的", "ref": "《腓立比书》4章19节", "s": "", "o": "腓立比书4章19节"}, {"type": "fill", "q": "腓立比书被称为“____的书信”。", "a": "喜乐", "s": ""}, {"type": "fill", "q": "保罗写腓立比书时身在____之中。", "a": "监狱", "s": ""}, {"type": "fill", "q": "“我深信那在你们心里动了善工的，必____这工”。", "a": "成全", "s": ""}, {"type": "fill", "q": "基督“反倒____，取了奴仆的形像”。", "a": "虚己", "s": ""}, {"type": "fill", "q": "保罗“____背后，努力面前的，向着标竿直跑”。", "a": "忘记", "s": ""}, {"type": "fill", "q": "“无不口称耶稣基督为____，使荣耀归与父神”。", "a": "主", "s": ""}, {"type": "fill", "q": "友阿爹和循都基是腓立比教会中需要同心的两位____。", "a": "姊妹", "s": ""}, {"type": "fill", "q": "以巴弗提是腓立比教会打发来____保罗的。", "a": "供给", "s": ""}, {"type": "fill", "q": "“神所赐出人意外的____，必保守你们的心怀意念”。", "a": "平安", "s": ""}, {"type": "fill", "q": "腓立比教会是保罗在____建立的第一间教会。", "a": "欧洲", "s": ""}, {"type": "single", "q": "腓立比书共有几章？", "o": ["3章", "4章", "5章", "6章"], "a": "4章", "s": ""}, {"type": "single", "q": "腓立比城位于哪个地区？", "o": ["亚细亚", "马其顿", "亚该亚", "加拉太"], "a": "马其顿", "s": ""}, {"type": "single", "q": "“以基督耶稣的心为心”在第几章？", "o": ["第1章", "第2章", "第3章", "第4章"], "a": "第2章", "s": ""}, {"type": "single", "q": "按腓3:5，保罗是哪个支派的人？", "o": ["犹大支派", "便雅悯支派", "利未支派", "以法莲支派"], "a": "便雅悯支派", "s": ""}, {"type": "single", "q": "以巴弗提为何险些丧命？", "o": ["为作基督的工夫", "被官府逼迫", "年老体衰", "长途旅行劳累"], "a": "为作基督的工夫", "s": ""}, {"type": "single", "q": "保罗说“看作粪土”的是指什么？", "o": ["万事", "律法条文", "割礼", "世上财富"], "a": "万事", "s": ""}, {"type": "single", "q": "腓立比教会是保罗第几次布道旅程中建立的？", "o": ["第一次", "第二次", "第三次", "第四次"], "a": "第二次", "s": ""}, {"type": "multiple", "q": "腓2:6-11基督虚己的历程包括？", "o": ["本有神的形像", "取了奴仆的形像", "成为人的样式", "存心顺服以至于死"], "a": "本有神的形像,取了奴仆的形像,成为人的样式,存心顺服以至于死", "s": ""}, {"type": "multiple", "q": "保罗在腓3章自述的犹太背景包括？", "o": ["第八天受割礼", "便雅悯支派的人", "法利赛人", "曾逼迫教会"], "a": "第八天受割礼,便雅悯支派的人,法利赛人,曾逼迫教会", "s": ""}, {"type": "multiple", "q": "腓4:8保罗劝勉要思念哪些事？", "o": ["真实的", "可敬的", "公义的", "清洁的"], "a": "真实的,可敬的,公义的,清洁的", "s": ""}, {"type": "multiple", "q": "保罗在狱中仍喜乐的秘诀包括？", "o": ["靠主喜乐", "祷告交托", "凡事谢恩", "学会知足"], "a": "靠主喜乐,祷告交托,凡事谢恩,学会知足", "s": ""}, {"type": "judge", "q": "腓立比书的主题是“喜乐”。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗写腓立比书时正在监狱中。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗说“我死了就有益处”是因为他厌世轻生。", "a": "错", "s": ""}, {"type": "judge", "q": "基督徒应当一无挂虑。", "a": "对", "s": ""}, {"type": "judge", "q": "以巴弗提是腓立比教会的牧师。", "a": "错", "s": ""}, {"type": "judge", "q": "我们的国民身份是在天上。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗认为自己已经完全得着了。", "a": "错", "s": ""}, {"type": "essay", "q": "腓2:5-11基督虚己的榜样对信徒有何意义？", "a": "基督本有神形像却虚己取奴仆形像，顺服至死；信徒当以基督的心为心，谦卑顺服、舍己为人，神必将他升为至高。", "s": ""}, {"type": "essay", "q": "保罗“忘记背后，努力面前，向着标竿直跑”是怎样的属灵操练？", "a": "不留恋过去成就或失败，专心追求认识基督，得着从上面召来的奖赏，一生向标竿直跑。", "s": ""}, {"type": "essay", "q": "信徒如何在患难中“靠主常常喜乐”？", "a": "喜乐的源头在主而不在环境；藉祷告交托、凡事谢恩、思念美善的事，经历出人意外的平安。", "s": ""}]','','study','[{"title": "问安与感恩（1:1-11）", "points": ["保罗与提摩太问安腓立比圣徒", "为腓立比教会感恩：从头一天同心合意", "深信动善工的必成全这工", "爱心在知识见识上多而又多", "诚实无过，直到基督的日子"]}, {"title": "为基督而活（1:12-30）", "points": ["捆锁反叫福音兴旺：御营全军都知道", "活着就是基督，死了就有益处", "或生或死，总叫基督被显大", "行事为人与基督福音相称", "为基督受苦是蒙恩"]}, {"title": "虚己的榜样（2章）", "points": ["以基督耶稣的心为心", "本有神形像，反倒虚己取奴仆形像", "存心顺服，以至于死在十字架上", "神将他升为至高，超乎万名之上", "无不口称耶稣基督为主", "作成得救的工夫：立志行事都是神", "提摩太与以巴弗提的榜样"]}, {"title": "标竿的人生（3章）", "points": ["靠主喜乐，防备犬类妄自行割的", "先前有益的，因基督都当作有损", "丢弃万事看作粪土，为要得着基督", "忘记背后，努力面前的", "向着标竿直跑，得神的奖赏", "我们是天上的国民，等候救主降临"]}, {"title": "喜乐的秘诀（4章）", "points": ["靠主常常喜乐，我再说要喜乐", "当一无挂虑，凡事祷告感谢告诉神", "出人意外的平安保守心怀意念", "思念一切真实、可敬、公义、清洁的事", "我靠着加力量的，凡事都能做", "神必使你们一切所需用的都充足", "腓立比教会的供给，神必悦纳"]}]','','81','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220980003','圣经导览','歌罗西书','保罗在狱中写给歌罗西教会，驳斥贬低基督的异端，高举基督的超越：他在万有之先、万有靠他而立、在凡事上居首位。信徒在基督里得了丰盛，当思念上面的事，脱去旧人穿上新人，恒切祷告，用智慧与外人交往。','[{"type": "verse", "q": "【经文填空】他在____之先，万有也靠他而____。", "a": "万有|立", "ref": "《歌罗西书》1章17节", "s": "", "o": "歌罗西书1章17节"}, {"type": "verse", "q": "【经文填空】因为神本性一切的____，都有形有体地居住在____里面。", "a": "丰盛|基督", "ref": "《歌罗西书》2章9节", "s": "", "o": "歌罗西书2章9节"}, {"type": "verse", "q": "【经文填空】所以你们若真与基督一同____，就当求在____的事。", "a": "复活|上面", "ref": "《歌罗西书》3章1节", "s": "", "o": "歌罗西书3章1节"}, {"type": "verse", "q": "【经文填空】你们要思念____的事，不要思念____的事。", "a": "上面|地上", "ref": "《歌罗西书》3章2节", "s": "", "o": "歌罗西书3章2节"}, {"type": "verse", "q": "【经文填空】无论做什么，都要从心里做，像是给____做的，不是给____做的。", "a": "主|人", "ref": "《歌罗西书》3章23节", "s": "", "o": "歌罗西书3章23节"}, {"type": "verse", "q": "【经文填空】你们要____祷告，在此警醒____。", "a": "恒切|感恩", "ref": "《歌罗西书》4章2节", "s": "", "o": "歌罗西书4章2节"}, {"type": "verse", "q": "【经文填空】他也是教会全体之____，使他可以在凡事上居____。", "a": "首|首位", "ref": "《歌罗西书》1章18节", "s": "", "o": "歌罗西书1章18节"}, {"type": "fill", "q": "歌罗西书的主题是基督的____与丰盛。", "a": "超越", "s": ""}, {"type": "fill", "q": "“爱子是那不能看见之神的____”。", "a": "像", "s": ""}, {"type": "fill", "q": "“万有都是藉着他造的，又是为他____的”。", "a": "造", "s": ""}, {"type": "fill", "q": "“就是基督在你们心里成了有荣耀的____”。", "a": "盼望", "s": ""}, {"type": "fill", "q": "神涂抹了在律例上所写、攻击我们的____，钉在十字架上。", "a": "字据", "s": ""}, {"type": "fill", "q": "“你们的生命与基督一同藏在____里面”。", "a": "神", "s": ""}, {"type": "fill", "q": "“把基督的道理____地存在心里”。", "a": "丰丰富富", "s": ""}, {"type": "fill", "q": "保罗打发____和阿尼西母到歌罗西送信。", "a": "推基古", "s": ""}, {"type": "fill", "q": "“所亲爱的医生____”问候歌罗西教会。", "a": "路加", "s": ""}, {"type": "fill", "q": "歌罗西教会是____所建立、所牧养的。", "a": "以巴弗", "s": ""}, {"type": "single", "q": "歌罗西城位于哪个地区？", "o": ["亚细亚", "马其顿", "加拉太", "叙利亚"], "a": "亚细亚", "s": ""}, {"type": "single", "q": "谁建立了歌罗西教会？", "o": ["保罗", "以巴弗", "提摩太", "路加"], "a": "以巴弗", "s": ""}, {"type": "single", "q": "“神本性一切的丰盛”在第几章？", "o": ["第1章", "第2章", "第3章", "第4章"], "a": "第2章", "s": ""}, {"type": "single", "q": "与歌罗西书同时写成的书信是？", "o": ["腓利门书", "腓立比书", "加拉太书", "罗马书"], "a": "腓利门书", "s": ""}, {"type": "single", "q": "保罗警告歌罗西信徒要防备什么？", "o": ["人间的哲学和虚空的妄言", "割礼", "饮食条例", "守节期"], "a": "人间的哲学和虚空的妄言", "s": ""}, {"type": "single", "q": "西3章教导要脱去旧人，穿上？", "o": ["新人", "圣衣", "白衣", "军装"], "a": "新人", "s": ""}, {"type": "single", "q": "保罗劝亚基布要谨慎什么？", "o": ["尽从主所受的职分", "恒切祷告", "常常禁食", "多多奉献"], "a": "尽从主所受的职分", "s": ""}, {"type": "multiple", "q": "歌罗西书论基督超越性的内容包括？", "o": ["他在万有之先", "万有靠他而立", "他是教会全体之首", "他在凡事上居首位"], "a": "他在万有之先,万有靠他而立,他是教会全体之首,他在凡事上居首位", "s": ""}, {"type": "multiple", "q": "西3:12新人的品格包括？", "o": ["怜悯", "恩慈", "谦虚", "温柔"], "a": "怜悯,恩慈,谦虚,温柔", "s": ""}, {"type": "multiple", "q": "保罗在歌罗西书末问安的同工有？", "o": ["推基古", "阿尼西母", "马可", "路加"], "a": "推基古,阿尼西母,马可,路加", "s": ""}, {"type": "multiple", "q": "歌罗西的异端掺杂包括？", "o": ["人间的哲学", "虚空的妄言", "拘泥饮食", "守节期安息日"], "a": "人间的哲学,虚空的妄言,拘泥饮食,守节期安息日", "s": ""}, {"type": "judge", "q": "歌罗西书强调基督在凡事上居首位。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗亲自建立了歌罗西教会。", "a": "错", "s": ""}, {"type": "judge", "q": "神本性一切的丰盛都有形有体居住在基督里面。", "a": "对", "s": ""}, {"type": "judge", "q": "信徒应当思念地上的事。", "a": "错", "s": ""}, {"type": "judge", "q": "无论做什么，都要像是给主做的。", "a": "对", "s": ""}, {"type": "judge", "q": "信徒要恒切祷告，在此警醒感恩。", "a": "对", "s": ""}, {"type": "judge", "q": "阿尼西母曾是腓利门的奴仆。", "a": "对", "s": ""}, {"type": "essay", "q": "歌罗西书如何论证基督的超越性？", "a": "基督是不能看见之神的像，万有藉他而造、为他而造；他在万有之先，万有靠他而立；他是教会之首、从死里首先复生，在凡事上居首位。", "s": ""}, {"type": "essay", "q": "“与基督一同复活”的新生命应当如何活出？", "a": "思念上面的事，治死地上的肢体，脱去旧人穿上新人，存怜悯恩慈谦虚温柔忍耐，彼此包容饶恕，让基督的平安作主。", "s": ""}, {"type": "essay", "q": "保罗如何驳斥歌罗西的异端？", "a": "指出在基督里有丰盛，神本性丰盛居住在他里面；字据已钉十字架；不要被哲学虚空妄言掳去，持定元首基督。", "s": ""}]','','study','[{"title": "感恩与代祷（1:1-14）", "points": ["保罗问安歌罗西圣徒", "听见信心爱心，为他们感谢神", "福音结果增长，如同普天之下", "从以巴弗所学，知神恩惠", "不住祷告祈求：满心知道神旨意", "行事为人对得起主，凡事蒙喜悦"]}, {"title": "基督的超越（1:15-29）", "points": ["爱子是不能看见之神的像", "万有藉他而造，又是为他而造", "他在万有之先，万有靠他而立", "他是教会全体之首，在凡事上居首位", "藉他十字架的血成就和平", "基督在你们心里成了荣耀的盼望"]}, {"title": "在基督里的丰盛（2章）", "points": ["神本性一切丰盛居住在基督里面", "你们在他里面也得了丰盛", "防备哲学和虚空妄言掳去", "字据已撤去，钉在十字架上", "基督仗着十字架夸胜", "饮食节期安息日都是后事的影儿"]}, {"title": "穿上新人（3章）", "points": ["与基督一同复活，就当求上面的事", "思念上面的事，不思念地上的事", "治死地上的肢体：淫乱污秽邪情", "脱去旧人和旧人的行为，穿上新人", "怜悯恩慈谦虚温柔忍耐", "彼此包容，彼此饶恕", "基督的平安在心里作主", "无论做什么，像是给主做的"]}, {"title": "祷告与见证（4章）", "points": ["恒切祷告，警醒感恩", "用智慧与外人交往，言语带着和气", "推基古与阿尼西母送信问安", "马可、路加等同工问安", "劝亚基布谨慎尽职", "保罗亲笔问安，记念捆锁"]}]','','82','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220980004','圣经导览','帖撒罗尼迦前书','保罗写给帖撒罗尼迦教会，称许他们的信、望、爱，坚固受逼迫中的信徒。全书突出主再来的真理：在基督里死了的人必先复活，活着的人被提到云里与主相遇。勉励信徒圣洁自守、警醒预备，常常喜乐、不住祷告、凡事谢恩。','[{"type": "verse", "q": "【经文填空】因为主必亲自从天____，有呼叫的声音和天使长的声音，又有神的号吹响，那在基督里死了的人必先____。", "a": "降临|复活", "ref": "《帖撒罗尼迦前书》4章16节", "s": "", "o": "帖撒罗尼迦前书4章16节"}, {"type": "verse", "q": "【经文填空】以后我们这活着还存留的人，必和他们一同被提到____里，在空中与主____。", "a": "云|相遇", "ref": "《帖撒罗尼迦前书》4章17节", "s": "", "o": "帖撒罗尼迦前书4章17节"}, {"type": "verse", "q": "【经文填空】因为你们自己明明晓得，主的日子来到，好像夜间的____一样。", "a": "贼", "ref": "《帖撒罗尼迦前书》5章2节", "s": "", "o": "帖撒罗尼迦前书5章2节"}, {"type": "verse", "q": "【经文填空】要常常____。", "a": "喜乐", "ref": "《帖撒罗尼迦前书》5章16节", "s": "", "o": "帖撒罗尼迦前书5章16节"}, {"type": "verse", "q": "【经文填空】____地祷告。", "a": "不住", "ref": "《帖撒罗尼迦前书》5章17节", "s": "", "o": "帖撒罗尼迦前书5章17节"}, {"type": "verse", "q": "【经文填空】凡事____，因为这是神在基督耶稣里向你们所定的旨意。", "a": "谢恩", "ref": "《帖撒罗尼迦前书》5章18节", "s": "", "o": "帖撒罗尼迦前书5章18节"}, {"type": "verse", "q": "【经文填空】不要消灭圣灵的____。", "a": "感动", "ref": "《帖撒罗尼迦前书》5章19节", "s": "", "o": "帖撒罗尼迦前书5章19节"}, {"type": "fill", "q": "帖撒罗尼迦城位于____地区。", "a": "马其顿", "s": ""}, {"type": "fill", "q": "保罗在帖撒罗尼迦传道共____个安息日。", "a": "三", "s": ""}, {"type": "fill", "q": "帖撒罗尼迦教会是保罗第____次布道旅程中建立的。", "a": "二", "s": ""}, {"type": "fill", "q": "“神的旨意就是要你们成为____，远避淫行”。", "a": "圣洁", "s": ""}, {"type": "fill", "q": "“把信和爱当作____遮胸，把得救的盼望当作头盔戴上”。", "a": "护心镜", "s": ""}, {"type": "fill", "q": "“各样的恶事要____不做”。", "a": "禁戒", "s": ""}, {"type": "fill", "q": "保罗称帖撒罗尼迦信徒是他的____和喜乐。", "a": "冠冕", "s": ""}, {"type": "fill", "q": "保罗打发____去帖撒罗尼迦，带回他们信心爱心的好消息。", "a": "提摩太", "s": ""}, {"type": "fill", "q": "帖撒罗尼迦信徒“离弃____，归向神”。", "a": "偶像", "s": ""}, {"type": "fill", "q": "保罗在帖撒罗尼迦“昼夜做工”，靠____养活自己。", "a": "织帐篷", "s": ""}, {"type": "single", "q": "帖撒罗尼迦前书共有几章？", "o": ["3章", "4章", "5章", "6章"], "a": "5章", "s": ""}, {"type": "single", "q": "保罗在帖撒罗尼迦传道了多久？", "o": ["三个安息日", "一年", "三年", "一个月"], "a": "三个安息日", "s": ""}, {"type": "single", "q": "“被提”的教导在第几章？", "o": ["第2章", "第3章", "第4章", "第5章"], "a": "第4章", "s": ""}, {"type": "single", "q": "保罗打发谁去帖撒罗尼迦坚固信徒？", "o": ["提摩太", "提多", "路加", "西拉"], "a": "提摩太", "s": ""}, {"type": "single", "q": "帖撒罗尼迦信徒离弃什么归向神？", "o": ["偶像", "律法", "哲学", "财富"], "a": "偶像", "s": ""}, {"type": "single", "q": "保罗在帖撒罗尼迦以何种手艺自食其力？", "o": ["织帐篷", "打鱼", "耕种", "经商"], "a": "织帐篷", "s": ""}, {"type": "single", "q": "搅扰帖撒罗尼迦教会的主要是？", "o": ["不信的犹太人", "罗马官兵", "税吏", "撒都该人"], "a": "不信的犹太人", "s": ""}, {"type": "multiple", "q": "帖前1:3提到的信、望、爱是？", "o": ["因信心所做的工夫", "因爱心所受的劳苦", "因盼望所存的忍耐", "因行为称义"], "a": "因信心所做的工夫,因爱心所受的劳苦,因盼望所存的忍耐", "s": ""}, {"type": "multiple", "q": "主再来时的情形包括？", "o": ["主亲自从天降临", "呼叫的声音", "天使长的声音", "神的号吹响"], "a": "主亲自从天降临,呼叫的声音,天使长的声音,神的号吹响", "s": ""}, {"type": "multiple", "q": "信徒警醒预备的装备包括？", "o": ["信和爱当护心镜", "得救盼望当头盔", "常常喜乐", "不住祷告"], "a": "信和爱当护心镜,得救盼望当头盔,常常喜乐,不住祷告", "s": ""}, {"type": "multiple", "q": "保罗在帖撒罗尼迦传道的榜样包括？", "o": ["劳苦昼夜做工", "不累着任何人", "传神的福音", "圣洁公义无可指摘"], "a": "劳苦昼夜做工,不累着任何人,传神的福音,圣洁公义无可指摘", "s": ""}, {"type": "judge", "q": "帖撒罗尼迦前书的主题之一是主的再来。", "a": "对", "s": ""}, {"type": "judge", "q": "那在基督里死了的人必先复活。", "a": "对", "s": ""}, {"type": "judge", "q": "主的日子来到好像夜间的贼一样。", "a": "对", "s": ""}, {"type": "judge", "q": "信徒应当消灭圣灵的感动。", "a": "错", "s": ""}, {"type": "judge", "q": "保罗在帖撒罗尼迦住了三年之久。", "a": "错", "s": ""}, {"type": "judge", "q": "神的旨意是要信徒凡事谢恩。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗在帖撒罗尼迦白吃人的饭。", "a": "错", "s": ""}, {"type": "essay", "q": "帖前4:13-18关于主再来与被提的教导是什么？", "a": "主必亲自从天降临，有呼叫声、天使长声音、神号吹响；在基督里死了的人必先复活，活着存留的人一同被提到云里与主相遇，永远同在。", "s": ""}, {"type": "essay", "q": "信徒应当如何警醒等候主的再来？", "a": "主的日子如夜间贼来到；信徒属白昼，当谨慎自守，把信和爱当护心镜、得救盼望当头盔，常常喜乐、不住祷告、凡事谢恩。", "s": ""}, {"type": "essay", "q": "“不住祷告、凡事谢恩”的操练有何意义？", "a": "这是神在基督里向信徒定的旨意；祷告使人与神 constant 交通，谢恩使人在各样环境中认定神的主权与美善。", "s": ""}]','','study','[{"title": "信望爱的教会（1章）", "points": ["保罗西拉提摩太问安", "为教会信望爱感谢神", "因信心做工、因爱心劳苦、因盼望忍耐", "离弃偶像归向神，等候儿子从天降临", "作了马其顿亚该亚信徒的榜样", "主的道传遍各处，信心传开"]}, {"title": "传道的榜样（2章）", "points": ["在腓立比受辱后仍放胆传福音", "传道不为讨人喜欢，乃讨神喜欢", "温柔如母亲乳养孩子", "劳苦昼夜做工，不累着人", "圣洁公义无可指摘的见证", "信徒领受的道实在是神的道", "你们是我们的荣耀喜乐冠冕"]}, {"title": "坚固与圣洁（3-4章）", "points": ["打发提摩太坚固信心", "提摩太带回信心爱心的好消息", "神旨意要你们成为圣洁远避淫行", "各人当用圣洁尊贵守着身体", "在基督里睡了的人必与主同来", "主降临：在基督里死的必先复活", "被提到云里与主相遇，永远同在"]}, {"title": "警醒等候（5:1-11）", "points": ["主的日子如夜间贼来到", "你们都是光明之子、白昼之子", "谨慎自守，不可睡觉", "信和爱当护心镜，得救盼望当头盔", "神预定我们得救，不是受刑", "彼此劝慰，互相建立"]}, {"title": "生活的劝勉（5:12-28）", "points": ["敬重劳苦的领袖", "彼此和睦，警戒不守规矩的人", "常常喜乐，不住祷告，凡事谢恩", "不要消灭圣灵的感动", "各样恶事要禁戒不做", "愿全人灵魂体得蒙保守", "保罗的祝福与亲笔问安"]}]','','83','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220980005','圣经导览','帖撒罗尼迦后书','保罗写给帖撒罗尼迦教会的第二封信，纠正“主的日子已经来到”的误传，预言主再来前必有离道反教、大罪人显露。勉励信徒站立得稳、坚守教训，并以亲手做工为榜样，吩咐游手好闲者安静做工、吃自己的饭。','[{"type": "verse", "q": "【经文填空】因你们的____格外增长，并且你们众人彼此____的心也都充足。", "a": "信心|相爱", "ref": "《帖撒罗尼迦后书》1章3节", "s": "", "o": "帖撒罗尼迦后书1章3节"}, {"type": "verse", "q": "【经文填空】因为那日子以前，必有____的事，并有那____显露出来。", "a": "离道反教|大罪人", "ref": "《帖撒罗尼迦后书》2章3节", "s": "", "o": "帖撒罗尼迦后书2章3节"}, {"type": "verse", "q": "【经文填空】主耶稣要用口中的____灭绝他，用降临的____废掉他。", "a": "气|荣光", "ref": "《帖撒罗尼迦后书》2章8节", "s": "", "o": "帖撒罗尼迦后书2章8节"}, {"type": "verse", "q": "【经文填空】凡所领受的____，不拘口传或信上写的，都要____。", "a": "教训|坚守", "ref": "《帖撒罗尼迦后书》2章15节", "s": "", "o": "帖撒罗尼迦后书2章15节"}, {"type": "verse", "q": "【经文填空】愿主引导你们的心，叫你们____，并学基督的____。", "a": "爱神|忍耐", "ref": "《帖撒罗尼迦后书》3章5节", "s": "", "o": "帖撒罗尼迦后书3章5节"}, {"type": "verse", "q": "【经文填空】若有人不肯____，就不可____。", "a": "做工|吃饭", "ref": "《帖撒罗尼迦后书》3章10节", "s": "", "o": "帖撒罗尼迦后书3章10节"}, {"type": "verse", "q": "【经文填空】要安静____，吃自己的____。", "a": "做工|饭", "ref": "《帖撒罗尼迦后书》3章12节", "s": "", "o": "帖撒罗尼迦后书3章12节"}, {"type": "fill", "q": "大罪人又称为“____之子”。", "a": "沉沦", "s": ""}, {"type": "fill", "q": "不法的人显露时，主用口中的气____他。", "a": "灭绝", "s": ""}, {"type": "fill", "q": "“弟兄们，你们要____得稳”。", "a": "站立", "s": ""}, {"type": "fill", "q": "口传的和信上写的教训都要____。", "a": "坚守", "s": ""}, {"type": "fill", "q": "“凡有弟兄不按____而行……就当远离他”。", "a": "规矩", "s": ""}, {"type": "fill", "q": "保罗在帖撒罗尼迦未曾____人的饭。", "a": "白吃", "s": ""}, {"type": "fill", "q": "保罗“____做工”，劳苦努力作榜样。", "a": "昼夜", "s": ""}, {"type": "fill", "q": "保罗亲笔问安，作为每封信的____。", "a": "记号", "s": ""}, {"type": "fill", "q": "有人谎称“主的日子____了”，保罗予以纠正。", "a": "现在", "s": ""}, {"type": "fill", "q": "神拣选信徒得救，是“藉着圣灵的____和真道的信”。", "a": "成圣", "s": ""}, {"type": "single", "q": "帖撒罗尼迦后书共有几章？", "o": ["2章", "3章", "4章", "5章"], "a": "3章", "s": ""}, {"type": "single", "q": "大罪人要坐在何处自称是神？", "o": ["神的殿", "王宫", "圣城", "旷野"], "a": "神的殿", "s": ""}, {"type": "single", "q": "保罗用什么作为书信的记号？", "o": ["亲笔问安", "印章", "签名画押", "指环"], "a": "亲笔问安", "s": ""}, {"type": "single", "q": "“不肯做工就不可吃饭”是针对哪种人？", "o": ["游手好闲者", "贫穷人", "寡妇", "病人"], "a": "游手好闲者", "s": ""}, {"type": "single", "q": "主再来之前必先发生什么事？", "o": ["离道反教", "世界大战", "大饥荒", "大地震"], "a": "离道反教", "s": ""}, {"type": "single", "q": "保罗吩咐要远离怎样的弟兄？", "o": ["不按规矩而行的", "外邦人", "税吏", "初信者"], "a": "不按规矩而行的", "s": ""}, {"type": "single", "q": "帖后2:13神拣选人得救是藉着什么？", "o": ["圣灵成圣与信真道", "人的行为", "律法功德", "割礼"], "a": "圣灵成圣与信真道", "s": ""}, {"type": "multiple", "q": "主再来施行审判的情形包括？", "o": ["在火焰中显现", "同有能力的天使", "报应不认识神的人", "报应不听福音的人"], "a": "在火焰中显现,同有能力的天使,报应不认识神的人,报应不听福音的人", "s": ""}, {"type": "multiple", "q": "信徒当坚守的教训包括？", "o": ["口传的教训", "信上写的教训", "使徒的传统", "都要坚守"], "a": "口传的教训,信上写的教训,使徒的传统,都要坚守", "s": ""}, {"type": "multiple", "q": "保罗劳苦的榜样包括？", "o": ["昼夜做工", "不白吃人饭", "不累着任何人", "为给信徒作榜样"], "a": "昼夜做工,不白吃人饭,不累着任何人,为给信徒作榜样", "s": ""}, {"type": "multiple", "q": "对游手好闲之人的吩咐包括？", "o": ["安静做工", "吃自己的饭", "当远离他", "仍要劝戒如弟兄"], "a": "安静做工,吃自己的饭,当远离他,仍要劝戒如弟兄", "s": ""}, {"type": "judge", "q": "帖撒罗尼迦后书纠正了“主的日子已经来到”的误传。", "a": "对", "s": ""}, {"type": "judge", "q": "大罪人就是沉沦之子。", "a": "对", "s": ""}, {"type": "judge", "q": "信徒可以游手好闲不用做工。", "a": "错", "s": ""}, {"type": "judge", "q": "若有人不肯做工，就不可吃饭。", "a": "对", "s": ""}, {"type": "judge", "q": "大罪人要在神的殿中坐着，自称是神。", "a": "对", "s": ""}, {"type": "judge", "q": "信徒要站立得稳，坚守所领受的教训。", "a": "对", "s": ""}, {"type": "judge", "q": "主耶稣要用口中的气灭绝不法之人。", "a": "对", "s": ""}, {"type": "essay", "q": "帖后2章关于大罪人与主再来的预言是什么？", "a": "主的日子以前必有离道反教的事，大罪人（沉沦之子）显露，自称是神坐在神的殿；主再来时要用口中的气灭绝他，用降临的荣光废掉他。", "s": ""}, {"type": "essay", "q": "为什么保罗强调“若有人不肯做工，就不可吃饭”？", "a": "因有人游手好闲、专管闲事；保罗以昼夜做工作榜样，吩咐人安静做工吃自己的饭，不累着教会。", "s": ""}, {"type": "essay", "q": "信徒当如何“站立得稳，坚守所领受的教训”？", "a": "不被谣言摇动，持定使徒口传与书信的教训，远离不按规矩而行的人，靠主刚强，爱神并学基督的忍耐。", "s": ""}]','','study','[{"title": "患难中的称赞（1章）", "points": ["为教会信心增长、爱心充足感谢神", "在逼迫患难中仍存忍耐信心", "神的审判：患难是配得神国的明证", "主在火焰中显现，报应不认识神者", "受患难者与圣徒同得平安", "主在他圣徒身上得荣耀"]}, {"title": "大罪人显露（2:1-12）", "points": ["不要被谣言摇动：主的日子未到", "那日子前必有离道反教的事", "大罪人（沉沦之子）显露，自称是神", "坐在神的殿里，自称是神", "主用口中的气灭绝他", "不法之人的迷惑与沉沦"]}, {"title": "站立得稳（2:13-17）", "points": ["神从起初拣选你们得救", "藉圣灵成圣与信真道", "蒙召得着主耶稣基督的荣光", "站立得稳，坚守口传与书信的教训", "主安慰坚固你们的心"]}, {"title": "亲手做工（3:1-10）", "points": ["请为我们祷告，主的道快快行开", "主是信实的，必坚固保护你们", "远离不按规矩而行的弟兄", "保罗昼夜做工的榜样", "不白吃人饭，不累着人", "不肯做工的，就不可吃饭"]}, {"title": "劝勉与祝福（3:11-18）", "points": ["有人游手好闲，专管闲事", "吩咐劝戒：安静做工吃自己的饭", "行善不可丧志", "记下不听话者，仍劝戒如弟兄", "愿平安的主赐平安", "保罗亲笔问安为记号"]}]','','84','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224337284','圣经导览','提摩太前书','保罗写给提摩太的教牧书信，指导以弗所教会治理与牧养。论监督执事资格、抵挡异端、敬虔操练、祷告敬拜与钱财观，是教会拣选领袖、组织事工、牧养群羊的经典指南，历代教会都当遵行持守。','[{"type": "verse", "q": "【经文填空】“________降世，为要拯救罪人。”这话是可信的，是十分可佩服的。", "a": "基督耶稣", "ref": "《提摩太前书》1章15节", "s": "", "o": "提摩太前书1章15节"}, {"type": "verse", "q": "【经文填空】因为只有一位神，在神和人中间也只有一位中保，乃是降世为人的________。", "a": "基督耶稣", "ref": "《提摩太前书》2章5节", "s": "", "o": "提摩太前书2章5节"}, {"type": "verse", "q": "【经文填空】人若想要得监督的职分，就是________善工。", "a": "羡慕", "ref": "《提摩太前书》3章1节", "s": "", "o": "提摩太前书3章1节"}, {"type": "verse", "q": "【经文填空】大哉，敬虔的奥秘，无人不以为然：就是神在________显现，被圣灵称义。", "a": "肉身", "ref": "《提摩太前书》3章16节", "s": "", "o": "提摩太前书3章16节"}, {"type": "verse", "q": "【经文填空】操练身体，益处还少；惟独________，凡事都有益处，因有今生和来生的应许。", "a": "敬虔", "ref": "《提摩太前书》4章8节", "s": "", "o": "提摩太前书4章8节"}, {"type": "verse", "q": "【经文填空】然而，________加上知足的心便是大利了。", "a": "敬虔", "ref": "《提摩太前书》6章6节", "s": "", "o": "提摩太前书6章6节"}, {"type": "verse", "q": "【经文填空】________是万恶之根！有人贪恋钱财，就被引诱离了真道。", "a": "贪财", "ref": "《提摩太前书》6章10节", "s": "", "o": "提摩太前书6章10节"}, {"type": "fill", "q": "保罗写提摩太前书时，提摩太被留在________牧养教会。", "a": "以弗所", "s": ""}, {"type": "fill", "q": "保罗将许米乃和________交给撒但，使他们受责罚不再谤讟。", "a": "亚历山大", "s": ""}, {"type": "fill", "q": "监督必须只作________妇人的丈夫。", "a": "一个", "s": ""}, {"type": "fill", "q": "执事要先受试验，若没有可责之处，然后叫他们作________。", "a": "执事", "s": ""}, {"type": "fill", "q": "神的教会是真理的________和根基。", "a": "柱石", "s": ""}, {"type": "fill", "q": "保罗劝提摩太因胃口不清、屡次患病，可以稍微用点________。", "a": "酒", "s": ""}, {"type": "fill", "q": "已经信主的妇女，若家中有寡妇，自己就当________她们。", "a": "救济", "s": ""}, {"type": "fill", "q": "那美好的仗我已经打过了——保罗在提摩太前书吩咐提摩太要为________打那美好的仗。", "a": "真道", "s": ""}, {"type": "fill", "q": "保罗说：我们没有带什么到世上来，也不能带什么________。", "a": "去", "s": ""}, {"type": "fill", "q": "你要嘱咐那些今世富足的人，不要________，也不要倚靠无定的钱财。", "a": "自高", "s": ""}, {"type": "single", "q": "提摩太前书是保罗写给谁的？", "o": ["提摩太", "提多", "腓利门", "路加"], "a": "提摩太", "s": ""}, {"type": "single", "q": "保罗称提摩太为什么？", "o": ["真儿子", "同工", "学生", "执事"], "a": "真儿子", "s": ""}, {"type": "single", "q": "提前2章吩咐要为什么人祷告？", "o": ["君王和一切在位的", "只为信徒", "只为传道人", "只为家人"], "a": "君王和一切在位的", "s": ""}, {"type": "single", "q": "监督的资格不包括哪一项？", "o": ["初入教的", "无可指责", "只作一个妇人的丈夫", "好好管理自己的家"], "a": "初入教的", "s": ""}, {"type": "single", "q": "“大哉，敬虔的奥秘”在提摩太前书第几章？", "o": ["第3章", "第1章", "第4章", "第6章"], "a": "第3章", "s": ""}, {"type": "single", "q": "保罗劝提摩太在哪些事上作信徒的榜样？", "o": ["言语、行为、爱心、信心、清洁", "财富、地位", "口才、学问", "禁食、苦修"], "a": "言语、行为、爱心、信心、清洁", "s": ""}, {"type": "single", "q": "贪恋钱财的人会有什么结果？", "o": ["被引诱离了真道，用许多愁苦把自己刺透了", "更加蒙福", "得着永生", "身体健康"], "a": "被引诱离了真道，用许多愁苦把自己刺透了", "s": ""}, {"type": "multiple", "q": "提前2章提到的祷告种类有哪些？", "o": ["恳求", "祷告", "代求", "祝谢"], "a": "恳求,祷告,代求,祝谢", "s": ""}, {"type": "multiple", "q": "监督必须具备哪些品格？", "o": ["无可指责", "节制自守", "乐意接待远人", "善于教导"], "a": "无可指责,节制自守,乐意接待远人,善于教导", "s": ""}, {"type": "multiple", "q": "执事的资格包括？", "o": ["端庄", "不一口两舌", "不好喝酒", "存清洁的良心固守真道奥秘"], "a": "端庄,不一口两舌,不好喝酒,存清洁的良心固守真道奥秘", "s": ""}, {"type": "multiple", "q": "保罗说末世有人离弃真道，听从哪些道理？", "o": ["引诱人的邪灵", "鬼魔的道理", "说谎之人的假冒", "禁止嫁娶禁戒食物"], "a": "引诱人的邪灵,鬼魔的道理,说谎之人的假冒,禁止嫁娶禁戒食物", "s": ""}, {"type": "judge", "q": "保罗自称在罪人中是个罪魁。", "a": "对", "s": ""}, {"type": "judge", "q": "提前说女人可以讲道辖管男人。", "a": "错", "s": ""}, {"type": "judge", "q": "初入教的可以作监督。", "a": "错", "s": ""}, {"type": "judge", "q": "操练身体，益处还少。", "a": "对", "s": ""}, {"type": "judge", "q": "钱财是万恶之根。", "a": "错", "s": ""}, {"type": "judge", "q": "敬虔加上知足的心便是大利了。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗劝提摩太因胃病可稍微用点酒。", "a": "对", "s": ""}, {"type": "essay", "q": "提前3:16“大哉，敬虔的奥秘”指什么？有何神学意义？", "a": "指基督道成肉身、被圣灵称义、被天使看见、被传于外邦、被世人信服、被接在荣耀里。显明福音的核心是基督自己，敬虔生活的根基在于认识并效法基督。", "s": ""}, {"type": "essay", "q": "保罗为什么说“不可叫人小看你年轻”？对年轻传道人有何勉励？", "a": "提摩太年轻，在以弗所牧会易被轻看。保罗勉励他不在于年龄，而在于生命榜样——在言语、行为、爱心、信心、清洁上作榜样。今日年轻事奉者同样当以生命服人。", "s": ""}, {"type": "essay", "q": "提前论钱财的教训（6:6-10,17-19）对今日信徒有何提醒？", "a": "贪财是万恶之根，知足加上敬虔才是大利。钱财无定不可倚靠，当倚靠厚赐百物的神；富足的人要行善、甘心施舍，为将来积成美好根基，持定永生。", "s": ""}]','','study','[{"title": "问安与嘱托（1章）", "points": ["保罗称提摩太为因信主作我真儿子", "嘱咐他抵挡传异教、讲荒渺无凭之话的人", "律法不是为义人设立，乃是为不法之人", "基督耶稣降世为要拯救罪人", "保罗自称在罪人中是个罪魁却蒙怜悯", "许米乃和亚历山大被交给撒但"]}, {"title": "祷告与敬拜（2章）", "points": ["为万人、君王和在位者恳求祷告代求祝谢", "只有一位神，一位中保基督耶稣", "男人无忿无疑举起圣洁的手祷告", "女人以正派衣裳、廉耻自守为妆饰", "不许女人讲道辖管男人", "女人沉静学道是保罗的吩咐"]}, {"title": "监督与执事（3章）", "points": ["羡慕善工想要得监督职分", "监督必须无可指责、只作一个妇人的丈夫", "好好管理自己的家，端正品行", "初入教的不可作监督免得自高自大", "执事要端庄、不一口两舌、存清洁良心", "大哉敬虔的奥秘：神在肉身显现"]}, {"title": "敬虔的操练（4章）", "points": ["圣灵明说末世必有人离弃真道", "禁止嫁娶、禁戒食物是鬼魔的道理", "凡神所造的物都是好的", "操练身体益处还少，惟独敬虔凡事有益", "不可叫人小看你年轻", "在言语、行为、爱心、信心、清洁上作榜样", "以宣读、劝勉、教导为念"]}, {"title": "牧养与钱财（5-6章）", "points": ["不看顾亲属的就是背了真道", "劳苦传道教导的长老配受加倍敬奉", "牛在场上踹谷不可笼住它的嘴", "贪财是万恶之根", "敬虔加上知足的心便是大利", "打那美好的仗持定永生", "嘱咐今世富足的人行善、甘心施舍"]}]','','85','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224337291','圣经导览','提摩太后书','保罗殉道前在罗马狱中写给提摩太的最后书信，语重心长。论圣经默示、末世预言、刚强壮胆与为真道打美好的仗，勉励提摩太忠心到底不以福音为耻，是传道人持守真道、为主受苦的临别遗言。','[{"type": "verse", "q": "【经文填空】因为神赐给我们，不是________的心，乃是刚强、仁爱、谨守的心。", "a": "胆怯", "ref": "《提摩太后书》1章7节", "s": "", "o": "提摩太后书1章7节"}, {"type": "verse", "q": "【经文填空】你当竭力在神面前得蒙喜悦，作无愧的工人，按着________分解真理的道。", "a": "正意", "ref": "《提摩太后书》2章15节", "s": "", "o": "提摩太后书2章15节"}, {"type": "verse", "q": "【经文填空】________都是神所默示的，于教训、督责、使人归正、教导人学义都是有益的。", "a": "圣经", "ref": "《提摩太后书》3章16节", "s": "", "o": "提摩太后书3章16节"}, {"type": "verse", "q": "【经文填空】那美好的仗我已经打过了，当跑的路我已经跑尽了，所信的道我已经________了。", "a": "守住", "ref": "《提摩太后书》4章7节", "s": "", "o": "提摩太后书4章7节"}, {"type": "verse", "q": "【经文填空】从此以后，有公义的________为我存留，就是按着公义审判的主到了那日要赐给我的。", "a": "冠冕", "ref": "《提摩太后书》4章8节", "s": "", "o": "提摩太后书4章8节"}, {"type": "verse", "q": "【经文填空】然而，神坚固的根基立住了，上面有这印记说：主________谁是他的人。", "a": "认识", "ref": "《提摩太后书》2章19节", "s": "", "o": "提摩太后书2章19节"}, {"type": "verse", "q": "【经文填空】因为知道我所信的是谁，也深信他能________我所交付他的，直到那日。", "a": "保全", "ref": "《提摩太后书》1章12节", "s": "", "o": "提摩太后书1章12节"}, {"type": "fill", "q": "提摩太的外祖母名叫________，母亲名叫友尼基。", "a": "罗以", "s": ""}, {"type": "fill", "q": "保罗写提摩太后书时正在________坐监，即将殉道。", "a": "罗马", "s": ""}, {"type": "fill", "q": "________贪爱现今的世界，就离弃保罗往帖撒罗尼迦去了。", "a": "底马", "s": ""}, {"type": "fill", "q": "铜匠________多多地害保罗。", "a": "亚历山大", "s": ""}, {"type": "fill", "q": "保罗要提摩太把________带来，更要紧的是那些皮卷。", "a": "外衣和书", "s": ""}, {"type": "fill", "q": "雅尼和________怎样敌挡摩西，这等人也怎样敌挡真道。", "a": "佯庇", "s": ""}, {"type": "fill", "q": "末世必有________的日子来到。", "a": "危险", "s": ""}, {"type": "fill", "q": "凡立志在基督耶稣里敬虔度日的，也都要受________。", "a": "逼迫", "s": ""}, {"type": "fill", "q": "有________的外貌，却背了敬虔的实意，这等人你要躲开。", "a": "敬虔", "s": ""}, {"type": "fill", "q": "主的仆人不可________，只要温温和和地待众人，善于教导，存心忍耐。", "a": "争竞", "s": ""}, {"type": "single", "q": "提摩太后书是保罗第几次在罗马坐监时写的？", "o": ["第二次", "第一次", "第三次", "没有坐监"], "a": "第二次", "s": ""}, {"type": "single", "q": "保罗用哪三种人比喻传道人当同受苦难？", "o": ["精兵、竞跑者、农夫", "君王、祭司、先知", "牧人、教师、长老", "商人、渔夫、农夫"], "a": "精兵、竞跑者、农夫", "s": ""}, {"type": "single", "q": "保罗吩咐提摩太把所听见的交托给什么人？", "o": ["那忠心能教导别人的人", "有学问的人", "有钱财的人", "年长的人"], "a": "那忠心能教导别人的人", "s": ""}, {"type": "single", "q": "公义的冠冕要赐给谁？", "o": ["凡爱慕他显现的人", "只有保罗", "只有使徒", "只有殉道者"], "a": "凡爱慕他显现的人", "s": ""}, {"type": "single", "q": "保罗临终前要提摩太带来什么？", "o": ["外衣、书、皮卷", "金银财宝", "食物衣服", "兵器"], "a": "外衣、书、皮卷", "s": ""}, {"type": "single", "q": "谁不以保罗的锁链为耻，屡次找他？", "o": ["阿尼色弗", "底马", "亚历山大", "许米乃"], "a": "阿尼色弗", "s": ""}, {"type": "single", "q": "保罗说“我离世的时候到了”在第几章？", "o": ["第4章", "第1章", "第2章", "第3章"], "a": "第4章", "s": ""}, {"type": "multiple", "q": "末世人的光景包括哪些？", "o": ["专顾自己", "贪爱钱财", "自夸、狂傲", "违背父母、忘恩负义"], "a": "专顾自己,贪爱钱财,自夸、狂傲,违背父母、忘恩负义", "s": ""}, {"type": "multiple", "q": "圣经的功用有哪些？", "o": ["教训", "督责", "使人归正", "教导人学义"], "a": "教训,督责,使人归正,教导人学义", "s": ""}, {"type": "multiple", "q": "保罗说自己是哪三种身份？", "o": ["传福音的", "使徒", "外邦人的师傅", "君王"], "a": "传福音的,使徒,外邦人的师傅", "s": ""}, {"type": "multiple", "q": "提摩太当逃避什么、追求什么？", "o": ["逃避少年的私欲", "追求公义", "追求信德、仁爱", "追求和平"], "a": "逃避少年的私欲,追求公义,追求信德、仁爱,追求和平", "s": ""}, {"type": "judge", "q": "神赐给我们的是胆怯的心。", "a": "错", "s": ""}, {"type": "judge", "q": "圣经都是神所默示的。", "a": "对", "s": ""}, {"type": "judge", "q": "凡立志在基督耶稣里敬虔度日的都要受逼迫。", "a": "对", "s": ""}, {"type": "judge", "q": "底马因贪爱世界离弃了保罗。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗说离世的时候到了。", "a": "对", "s": ""}, {"type": "judge", "q": "提摩太后书吩咐要为君王祷告。", "a": "错", "s": ""}, {"type": "judge", "q": "主认识谁是他的人。", "a": "对", "s": ""}, {"type": "essay", "q": "提后3:16-17论圣经的默示与功用，对今日信徒读经有何指导？", "a": "圣经都是神所默示的，不是人意的产物。功用有四：教训、督责、使人归正、教导人学义，叫属神的人得以完全，预备行各样的善事。信徒当以圣经为最高权威，勤读圣经、按正意分解。", "s": ""}, {"type": "essay", "q": "保罗“那美好的仗我已经打过了”对今日信徒有何激励？", "a": "保罗一生为福音打美好的仗、跑尽当跑的路、守住所信的道，临终无悔。激励信徒忠心到底，不贪爱世界，爱慕主显现，将来必得公义的冠冕。", "s": ""}, {"type": "essay", "q": "提后3:1-5描述的末世特征在今日有何应验？信徒当如何自守？", "a": "专顾自己、贪爱钱财、自夸、爱宴乐不爱神等在今日处处可见。信徒当躲开这等人，持守圣经，逃避私欲，追求公义、信德、仁爱、和平，作贵重的器皿。", "s": ""}]','','study','[{"title": "问安与勉励（1章）", "points": ["保罗纪念提摩太无伪之信", "外祖母罗以、母亲友尼基的信心传承", "提摩太从小明白圣经", "挑旺神藉按手所给的恩赐", "神赐的不是胆怯的心，乃是刚强仁爱谨守的心", "不要以给主作见证为耻", "阿尼色弗不以保罗的锁链为耻"]}, {"title": "刚强的精兵（2章）", "points": ["把所听见的交托忠心能教导别人的人", "和我同受苦难：精兵、竞跑者、农夫的比喻", "按着正意分解真理的道", "主认识谁是他的人", "大户人家有金器银器也有木器瓦器", "逃避少年私欲，追求公义信德仁爱和平", "主的仆人不可争竞"]}, {"title": "末世的预言（3章）", "points": ["末世必有危险的日子来到", "那时人要专顾自己、贪爱钱财、自夸狂傲", "有敬虔的外貌却背了敬虔的实意", "雅尼和佯庇怎样敌挡摩西", "凡立志在基督耶稣里敬虔度日的都要受逼迫", "圣经都是神所默示的", "圣经能使人因信基督有得救的智慧"]}, {"title": "美好的仗（4章）", "points": ["务要传道，无论得时不得时", "用百般忍耐各样教训责备警戒劝勉", "保罗被浇奠离世时候到了", "那美好的仗已经打过，当跑的路跑尽", "有公义的冠冕存留，赐给凡爱慕他显现的人", "底马贪爱现今世界离弃保罗", "铜匠亚历山大多多害我"]}, {"title": "最后嘱托（4章下）", "points": ["把外衣、书和皮卷带来", "主站在我旁边加给我力量", "主必救我脱离诸般凶恶", "进入他天上的国", "问安与祝福", "愿恩惠与众人同在", "保罗一生忠心的榜样"]}]','','86','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224337298','圣经导览','提多书','保罗写给提多的教牧书信，指导革哩底教会设立长老、整顿秩序。论长老资格、恩典的教训、重生的洗与敬虔善行，显明纯正信仰必带出圣洁生活，是教会治理与信徒日常生活的实用指南，值得反复研读。','[{"type": "verse", "q": "【经文填空】我从前留你在革哩底，是要你将那没有办完的事都办整齐了，又照我所吩咐你的，在各城________长老。", "a": "设立", "ref": "《提多书》1章5节", "s": "", "o": "提多书1章5节"}, {"type": "verse", "q": "【经文填空】在洁净的人，________都洁净；在污秽不信的人，什么都不洁净。", "a": "凡物", "ref": "《提多书》1章15节", "s": "", "o": "提多书1章15节"}, {"type": "verse", "q": "【经文填空】因为神________众人的恩典已经显明出来。", "a": "救", "ref": "《提多书》2章11节", "s": "", "o": "提多书2章11节"}, {"type": "verse", "q": "【经文填空】教训我们除去________和世俗的情欲，在今世自守、公义、敬虔度日。", "a": "不敬虔的心", "ref": "《提多书》2章12节", "s": "", "o": "提多书2章12节"}, {"type": "verse", "q": "【经文填空】他便救了我们，并不是因我们自己所行的义，乃是照他的怜悯，藉着________和圣灵的更新。", "a": "重生的洗", "ref": "《提多书》3章5节", "s": "", "o": "提多书3章5节"}, {"type": "verse", "q": "【经文填空】他们说是认识神，行事却和他________；本是可憎恶的，是悖逆的。", "a": "相背", "ref": "《提多书》1章16节", "s": "", "o": "提多书1章16节"}, {"type": "verse", "q": "【经文填空】这话是________的，我也愿你把这些事切切实实地讲明。", "a": "可信", "ref": "《提多书》3章8节", "s": "", "o": "提多书3章8节"}, {"type": "fill", "q": "保罗把提多留在________，要他设立长老。", "a": "革哩底", "s": ""}, {"type": "fill", "q": "有人说：革哩底人常说谎话，乃是恶兽，又馋又________。", "a": "懒", "s": ""}, {"type": "fill", "q": "长老的儿女必须________，不放荡，不受约束。", "a": "信主", "s": ""}, {"type": "fill", "q": "老年妇人要以________为妆饰，不说谗言。", "a": "圣洁", "s": ""}, {"type": "fill", "q": "保罗劝少年人要________。", "a": "谨守", "s": ""}, {"type": "fill", "q": "仆人行事要显出善行全备的________，荣耀神的道。", "a": "忠心", "s": ""}, {"type": "fill", "q": "我们等候所盼望的福，并我们神和救主耶稣基督的________显现。", "a": "荣耀", "s": ""}, {"type": "fill", "q": "分门结党的人，警戒过________次，就要弃绝他。", "a": "一两", "s": ""}, {"type": "fill", "q": "保罗打发________或推基古到提多那里去。", "a": "亚提马", "s": ""}, {"type": "fill", "q": "保罗已经定意在________过冬，要提多赶紧到他那里去。", "a": "尼哥波立", "s": ""}, {"type": "single", "q": "提多书是保罗写给谁的？", "o": ["提多", "提摩太", "腓利门", "以巴弗"], "a": "提多", "s": ""}, {"type": "single", "q": "提多被留在哪个岛设立长老？", "o": ["革哩底", "马耳他", "塞浦路斯", "米利大"], "a": "革哩底", "s": ""}, {"type": "single", "q": "“革哩底人常说谎话”是出自谁的话？", "o": ["他们自己的先知", "保罗", "彼得", "摩西"], "a": "他们自己的先知", "s": ""}, {"type": "single", "q": "长老必须具备什么首要条件？", "o": ["无可指责", "有钱财", "有学问", "年纪大"], "a": "无可指责", "s": ""}, {"type": "single", "q": "分门结党的人警戒几次后要弃绝？", "o": ["一两次", "三次", "七次", "七十个七次"], "a": "一两次", "s": ""}, {"type": "single", "q": "提多书共有几章？", "o": ["3章", "4章", "5章", "6章"], "a": "3章", "s": ""}, {"type": "single", "q": "保罗要提多在哪里等他过冬？", "o": ["尼哥波立", "罗马", "以弗所", "哥林多"], "a": "尼哥波立", "s": ""}, {"type": "multiple", "q": "长老的资格包括哪些？", "o": ["无可指责", "只作一个妇人的丈夫", "乐意接待远人", "坚守所教真实的道理"], "a": "无可指责,只作一个妇人的丈夫,乐意接待远人,坚守所教真实的道理", "s": ""}, {"type": "multiple", "q": "神的恩典教训我们什么？", "o": ["除去不敬虔的心", "除去世俗的情欲", "自守、公义、敬虔度日", "等候有福的盼望"], "a": "除去不敬虔的心,除去世俗的情欲,自守、公义、敬虔度日,等候有福的盼望", "s": ""}, {"type": "multiple", "q": "各样年纪的人当如何行？", "o": ["老年人庄重节制", "老年妇人以圣洁为妆饰", "少年妇人爱丈夫爱儿女", "少年人谨守"], "a": "老年人庄重节制,老年妇人以圣洁为妆饰,少年妇人爱丈夫爱儿女,少年人谨守", "s": ""}, {"type": "multiple", "q": "信徒对在上掌权者当如何？", "o": ["顺服", "预备行各样善事", "不毁谤不争竞", "存心温柔"], "a": "顺服,预备行各样善事,不毁谤不争竞,存心温柔", "s": ""}, {"type": "judge", "q": "在洁净的人，凡物都洁净。", "a": "对", "s": ""}, {"type": "judge", "q": "革哩底人都是诚实可信的。", "a": "错", "s": ""}, {"type": "judge", "q": "我们是藉着重生的洗和圣灵的更新得救的。", "a": "对", "s": ""}, {"type": "judge", "q": "分门结党的人警戒一两次就要弃绝他。", "a": "对", "s": ""}, {"type": "judge", "q": "提多书共有四章。", "a": "错", "s": ""}, {"type": "judge", "q": "神救众人的恩典已经显明出来。", "a": "对", "s": ""}, {"type": "judge", "q": "仆人可以私拿主人的东西。", "a": "错", "s": ""}, {"type": "essay", "q": "多2:11-14论“恩典的教训”，恩典教导我们什么？", "a": "恩典不是放纵的借口，而是教训我们除去不敬虔的心和世俗情欲，在今世自守、公义、敬虔度日，等候有福的盼望——神和救主耶稣基督荣耀显现。真恩典必带出圣洁生活。", "s": ""}, {"type": "essay", "q": "提多书所列长老资格对今日教会选立领袖有何意义？", "a": "长老是神的管家，必须无可指责、好善、公义圣洁自持、坚守真道。今日选立领袖不当单看才干，更要看生命与家庭见证，儿女信主、好名声是基本要求。", "s": ""}, {"type": "essay", "q": "“重生的洗和圣灵的更新”（多3:5）指什么？", "a": "指神藉圣灵使人重生得救的工作。“洗”象征除去罪污，“更新”指圣灵赐新生命。得救本乎恩、藉着信，不是因行为，使人称义、有永生的盼望。", "s": ""}]','','study','[{"title": "设立长老（1章）", "points": ["保罗留提多在革哩底办整齐未完之事", "在各城设立长老", "长老必须无可指责，儿女信主不放荡", "监督是神的管家，不任性不暴躁", "驳倒传异教和不服之人的口", "革哩底人常说谎、乃是恶兽、又馋又懒", "在洁净的人凡物都洁净"]}, {"title": "各样人的本分（2章）", "points": ["老年人要庄重、节制、纯全", "老年妇人举止行动要恭敬，以圣洁为妆饰", "好指教少年妇人爱丈夫爱儿女", "少年妇人要谨守、贞洁、料理家务", "劝少年人要谨守", "提多在善行言语上作榜样无可指责", "劝仆人顺服主人，凡事讨他喜欢"]}, {"title": "恩典的教训（2:11-14）", "points": ["神救众人的恩典已经显明出来", "教训我们除去不敬虔的心和世俗情欲", "在今世自守、公义、敬虔度日", "等候所盼望的福", "等候神和救主耶稣基督的荣耀显现", "基督为我们舍己，赎我们脱离罪恶", "洁净我们作他的子民，热心为善"]}, {"title": "信徒的生活（3章）", "points": ["提醒众人顺服作官的掌权的", "预备行各样的善事", "不要毁谤，不要争竞，总要和平", "我们从前也是无知、悖逆、被引诱的", "神的恩慈和爱显明，藉重生的洗救了我们", "圣灵厚厚浇灌在我们身上", "因他的恩得称为义，凭永生盼望成为后嗣"]}, {"title": "最后嘱托（3章下）", "points": ["这话是可信的，要切切实实讲明", "使信神的人留心作正经事业", "避开无知的辩论和律法上的争竞", "分门结党的人警戒一两次就要弃绝他", "打发亚提马或推基古到提多那里", "保罗要在尼哥波立过冬", "同工问安，愿恩惠与众人同在"]}]','','87','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224337305','圣经导览','腓利门书','保罗最短的一封书信，为逃奴阿尼西母向腓利门爱心代求。从奴仆到亲爱的兄弟，福音彻底改变人与人的关系；保罗愿代偿亏欠，预表基督的中保工作，是饶恕接纳、爱心代求的典范之作，感人至深。','[{"type": "verse", "q": "【经文填空】愿你与人所同有的信心________，使人知道你们各样善事都是为基督做的。", "a": "显出功效", "ref": "《腓利门书》1章6节", "s": "", "o": "腓利门书1章6节"}, {"type": "verse", "q": "【经文填空】就是为我在捆锁中所生的儿子________，求你。", "a": "阿尼西母", "ref": "《腓利门书》1章10节", "s": "", "o": "腓利门书1章10节"}, {"type": "verse", "q": "【经文填空】不再是奴仆，乃是________，是亲爱的兄弟。", "a": "高过奴仆", "ref": "《腓利门书》1章16节", "s": "", "o": "腓利门书1章16节"}, {"type": "verse", "q": "【经文填空】你若以我为同伴，就________他，如同接纳我一样。", "a": "收纳", "ref": "《腓利门书》1章17节", "s": "", "o": "腓利门书1章17节"}, {"type": "verse", "q": "【经文填空】他若亏负你，或欠你什么，都________在我的账上。", "a": "归", "ref": "《腓利门书》1章18节", "s": "", "o": "腓利门书1章18节"}, {"type": "verse", "q": "【经文填空】我必________；我保罗亲笔写了。", "a": "偿还", "ref": "《腓利门书》1章19节", "s": "", "o": "腓利门书1章19节"}, {"type": "verse", "q": "【经文填空】我写信给你，深信你必________，知道你所要行的，必过于我所说的。", "a": "顺服", "ref": "《腓利门书》1章21节", "s": "", "o": "腓利门书1章21节"}, {"type": "fill", "q": "腓利门书是保罗写给________的一封私人信件。", "a": "腓利门", "s": ""}, {"type": "fill", "q": "阿尼西母原是腓利门的________，后来逃跑了。", "a": "奴仆", "s": ""}, {"type": "fill", "q": "阿尼西母的名字意思是“________”。", "a": "有益处", "s": ""}, {"type": "fill", "q": "保罗在________中带领阿尼西母信主，称他为“在捆锁中所生的儿子”。", "a": "监狱", "s": ""}, {"type": "fill", "q": "保罗打发________回到腓利门那里去。", "a": "阿尼西母", "s": ""}, {"type": "fill", "q": "与阿尼西母一同去的还有________（西4:9）。", "a": "推基古", "s": ""}, {"type": "fill", "q": "亚腓亚可能是腓利门的________。", "a": "妻子", "s": ""}, {"type": "fill", "q": "亚基布是与保罗________的。", "a": "同当兵", "s": ""}, {"type": "fill", "q": "保罗请腓利门为他预备________，盼望能去见他们。", "a": "住处", "s": ""}, {"type": "fill", "q": "和保罗一同问安的有马可、亚里达古、________、路加。", "a": "底马", "s": ""}, {"type": "single", "q": "腓利门书是保罗写给谁的私人信件？", "o": ["腓利门", "提摩太", "提多", "歌罗西教会"], "a": "腓利门", "s": ""}, {"type": "single", "q": "阿尼西母原来的身份是什么？", "o": ["奴仆", "商人", "士兵", "祭司"], "a": "奴仆", "s": ""}, {"type": "single", "q": "保罗在哪里写腓利门书？", "o": ["罗马监狱", "以弗所", "哥林多", "耶路撒冷"], "a": "罗马监狱", "s": ""}, {"type": "single", "q": "阿尼西母名字的意思是什么？", "o": ["有益处", "无益处", "逃跑者", "自由人"], "a": "有益处", "s": ""}, {"type": "single", "q": "保罗称阿尼西母为什么？", "o": ["在捆锁中所生的儿子", "同工", "执事", "使徒"], "a": "在捆锁中所生的儿子", "s": ""}, {"type": "single", "q": "腓利门书共有几章？", "o": ["1章", "2章", "3章", "4章"], "a": "1章", "s": ""}, {"type": "single", "q": "保罗希望腓利门把阿尼西母当作什么？", "o": ["亲爱的兄弟", "奴仆", "仇人", "陌生人"], "a": "亲爱的兄弟", "s": ""}, {"type": "multiple", "q": "保罗为阿尼西母向腓利门求什么？", "o": ["收纳他如同接纳保罗", "不再是奴仆乃是兄弟", "亏欠归在保罗账上", "从重惩罚他"], "a": "收纳他如同接纳保罗,不再是奴仆乃是兄弟,亏欠归在保罗账上", "s": ""}, {"type": "multiple", "q": "腓利门的爱心表现在哪里？", "o": ["向主和众圣徒有爱心", "有信心", "使圣徒的心得畅快", "甘心接待"], "a": "向主和众圣徒有爱心,有信心,使圣徒的心得畅快", "s": ""}, {"type": "multiple", "q": "与保罗一同问安的同工有？", "o": ["以巴弗", "马可", "亚里达古", "路加"], "a": "以巴弗,马可,亚里达古,路加", "s": ""}, {"type": "multiple", "q": "保罗说他本可凭什么吩咐，却宁愿凭什么求？", "o": ["使徒的权柄", "爱心", "命令", "恳求"], "a": "使徒的权柄,爱心", "s": ""}, {"type": "judge", "q": "腓利门书是保罗最长的书信。", "a": "错", "s": ""}, {"type": "judge", "q": "阿尼西母原是腓利门的奴仆。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗在监狱中带领阿尼西母信主。", "a": "对", "s": ""}, {"type": "judge", "q": "保罗要腓利门把阿尼西母仍当奴仆看待。", "a": "错", "s": ""}, {"type": "judge", "q": "保罗愿意替阿尼西母偿还一切亏欠。", "a": "对", "s": ""}, {"type": "judge", "q": "腓利门书全书只有25节。", "a": "对", "s": ""}, {"type": "judge", "q": "亚基布是与保罗同当兵的。", "a": "对", "s": ""}, {"type": "essay", "q": "腓利门书如何体现福音改变人与人的关系？", "a": "阿尼西母从逃奴变为“亲爱的兄弟”，主仆关系在基督里成为肢体关系。福音不废除社会身份，却赋予新意义：在主里互为弟兄，彼此接纳、饶恕，这是福音的大能。", "s": ""}, {"type": "essay", "q": "保罗为阿尼西母代求，如何预表基督的中保工作？", "a": "保罗说“他若亏负你，都归在我的账上，我必偿还”，正如基督在神面前为我们代偿罪债。保罗的代求是基督代赎的缩影，显明福音的核心——代赎。", "s": ""}, {"type": "essay", "q": "“不再是奴仆，乃是高过奴仆的兄弟”对今日教会肢体关系有何教导？", "a": "在基督里不分社会地位、贫富贵贱，都是弟兄姊妹。教会当彼此接纳、饶恕，不轻看任何人，以爱心说诚实话，用和平彼此联络。", "s": ""}]','','study','[{"title": "问安与感恩（1-7节）", "points": ["保罗为基督耶稣被囚的", "写信给亲爱的同工腓利门", "问安亚腓亚、亚基布和腓利门家的教会", "听说腓利门的爱心和信心就感谢神", "众圣徒的心因你得了畅快", "保罗为腓利门的善行感恩"]}, {"title": "为阿尼西母代求（8-16节）", "points": ["保罗本有胆量吩咐，却宁愿凭爱心求", "为捆锁中所生的儿子阿尼西母求你", "他从前于你无益，如今有益", "阿尼西母名字意为“有益处”", "保罗亲手打发他回到你那里", "不再是奴仆，乃是高过奴仆的兄弟", "在主里是亲爱的兄弟"]}, {"title": "担保与偿还（17-21节）", "points": ["你若以我为同伴，就收纳他如接纳我", "他若亏负你，都归在我的账上", "我保罗亲笔写，我必偿还", "预表基督为我们代偿罪债", "深信你必顺服，所行过于所求", "爱心不勉强，乃是甘心"]}, {"title": "盼望与问安（22-25节）", "points": ["为我预备住处，盼望得释放见你们", "与我一同坐监的以巴弗问安", "马可、亚里达古、底马、路加问安", "愿主耶稣基督的恩常在你们心里", "全书25节，保罗最短书信"]}, {"title": "书信的意义", "points": ["福音打破主仆的隔阂", "在基督里成为一家人", "代求预表基督的中保工作", "饶恕接纳是爱的实践", "为今日处理人际关系立榜样"]}]','','88','新约•保罗书信','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220960000','圣经导览','希伯来书','希伯来书向犹太信徒显明基督超越旧约一切：超越天使、摩西与亚伦等次的祭司，是更美之约的中保，一次献上成就永远赎罪。第十一章列出信心伟人榜，第十二章劝勉忍耐奔跑，在管教中得圣洁，持定永不震动的国。','[{"type": "verse", "q": "【经文填空】神的道是________的，是有功效的，比一切两刃的剑更快，甚至魂与灵、骨节与骨髓，都能刺入、剖开，连心中的思念和主意都能辨明。", "a": "活泼", "ref": "《希伯来书》4章12节", "s": "", "o": "希伯来书4章12节"}, {"type": "verse", "q": "【经文填空】信就是所望之事的________，未见之事的确据。", "a": "实底", "ref": "《希伯来书》11章1节", "s": "", "o": "希伯来书11章1节"}, {"type": "verse", "q": "【经文填空】人非有信，就不能得神的________；因为到神面前来的人必须信有神，且信他赏赐那寻求他的人。", "a": "喜悦", "ref": "《希伯来书》11章6节", "s": "", "o": "希伯来书11章6节"}, {"type": "verse", "q": "【经文填空】我们既有这许多的见证人，如同云彩围着我们，就当放下各样的重担，脱去容易缠累我们的________，存心忍耐，奔那摆在我们前头的路程。", "a": "罪", "ref": "《希伯来书》12章1节", "s": "", "o": "希伯来书12章1节"}, {"type": "verse", "q": "【经文填空】你们要追求与众人和睦，并要追求________；非圣洁没有人能见主。", "a": "圣洁", "ref": "《希伯来书》12章14节", "s": "", "o": "希伯来书12章14节"}, {"type": "verse", "q": "【经文填空】因为主所爱的，他必________，又鞭打凡所收纳的儿子。", "a": "管教", "ref": "《希伯来书》12章6节", "s": "", "o": "希伯来书12章6节"}, {"type": "verse", "q": "【经文填空】耶稣基督，昨日、今日、一直到永远，是________的。", "a": "一样", "ref": "《希伯来书》13章8节", "s": "", "o": "希伯来书13章8节"}, {"type": "fill", "q": "希伯来书没有署名作者，历来有人认为是________所写，但不能确定。", "a": "保罗", "s": ""}, {"type": "fill", "q": "麦基洗德是________王，又是至高神的祭司，亚伯拉罕将所得的十分之一分给他。", "a": "撒冷", "s": ""}, {"type": "fill", "q": "基督是照着麦基洗德的________永远为祭司，超越亚伦等次。", "a": "等次", "s": ""}, {"type": "fill", "q": "律法既是将来美事的________，不是本物的真像，总不能藉着年年常献一样的祭物叫那近前来的人得以完全。", "a": "影儿", "s": ""}, {"type": "fill", "q": "公牛和山羊的血，断不能________。", "a": "除罪", "s": ""}, {"type": "fill", "q": "以撒因着信，就指着将来的事给雅各、________祝福。", "a": "以扫", "s": ""}, {"type": "fill", "q": "摩西因着信，长大了就不肯称为________之子；他宁可和神的百姓同受苦害，也不愿暂时享受罪中之乐。", "a": "法老女儿", "s": ""}, {"type": "fill", "q": "那进入安息的，乃是歇了自己的工，正如神歇了他的工一样；以色列人因________未能进入安息。", "a": "不信", "s": ""}, {"type": "fill", "q": "我们并非有一位不能体恤我们软弱的大祭司，他也曾凡事受过试探，与我们一样，只是他没有________。", "a": "犯罪", "s": ""}, {"type": "fill", "q": "你们不可忘记用爱心________，因为曾有接待客旅的，不知不觉就接待了天使。", "a": "接待客旅", "s": ""}, {"type": "single", "q": "希伯来书说，神的儿子比天使所得的名是？", "o": ["更尊贵", "更美", "更大", "更荣耀"], "a": "更美", "s": ""}, {"type": "single", "q": "麦基洗德又名叫什么王？", "o": ["公义王", "平安王", "仁义王", "永生王"], "a": "公义王", "s": ""}, {"type": "single", "q": "希伯来书第十一章通常被称为什么？", "o": ["爱的诗篇", "信心伟人榜", "智慧之言", "救恩颂歌"], "a": "信心伟人榜", "s": ""}, {"type": "single", "q": "挪亚因着信预备方舟，希伯来书说他因此做了什么？", "o": ["逃避洪水", "拯救全家", "定了那世代的罪", "以上都是"], "a": "以上都是", "s": ""}, {"type": "single", "q": "希伯来书劝勉不可停止什么？", "o": ["祷告", "聚会", "奉献", "禁食"], "a": "聚会", "s": ""}, {"type": "single", "q": "“我们的神乃是烈火”出自希伯来书哪一章？", "o": ["第十章", "第十一章", "第十二章", "第十三章"], "a": "第十二章", "s": ""}, {"type": "single", "q": "更美之约的中保是谁？", "o": ["摩西", "亚伦", "耶稣", "约书亚"], "a": "耶稣", "s": ""}, {"type": "multiple", "q": "希伯来书论证基督超越旧约的哪些人物或制度？", "o": ["天使", "摩西", "亚伦等次的祭司", "约书亚"], "a": "天使,摩西,亚伦等次的祭司", "s": ""}, {"type": "multiple", "q": "以下哪些是希伯来书第十一章提到的信心伟人？", "o": ["亚伯", "以诺", "挪亚", "亚伯拉罕"], "a": "亚伯,以诺,挪亚,亚伯拉罕", "s": ""}, {"type": "multiple", "q": "神管教儿女的目的包括？", "o": ["使我们得益处", "使我们在他的圣洁上有分", "结出平安的果子", "叫我们受苦"], "a": "使我们得益处,使我们在他的圣洁上有分,结出平安的果子", "s": ""}, {"type": "multiple", "q": "希伯来书末了劝勉信徒要？", "o": ["彼此相顾", "激发爱心", "勉励行善", "不可停止聚会"], "a": "彼此相顾,激发爱心,勉励行善,不可停止聚会", "s": ""}, {"type": "judge", "q": "希伯来书开篇明确署名作者是保罗。", "a": "错", "s": ""}, {"type": "judge", "q": "基督是照着麦基洗德的等次永远为祭司。", "a": "对", "s": ""}, {"type": "judge", "q": "公牛和山羊的血能除罪。", "a": "错", "s": ""}, {"type": "judge", "q": "摩西在神的全家尽忠，为要证明将来必传说的事。", "a": "对", "s": ""}, {"type": "judge", "q": "以扫为一碗红豆汤把长子的名分卖了，后来虽然号哭切求也得不着祝福。", "a": "对", "s": ""}, {"type": "judge", "q": "信徒应当轻看主的管教。", "a": "错", "s": ""}, {"type": "judge", "q": "“不要以恶报恶”这句话出自希伯来书。", "a": "错", "s": ""}, {"type": "essay", "q": "希伯来书如何论证基督超越旧约的一切？", "a": "希伯来书层层论证基督的超越：他是神的儿子，远超过天使（一章）；比摩西更配多得荣耀（三章）；照麦基洗德的等次为大祭司，超越亚伦体系（七章）；作更美之约的中保（八章）；用自己的血一次进入圣所，成就了永远赎罪（九至十章）。", "s": ""}, {"type": "essay", "q": "解释“信就是所望之事的实底，未见之事的确据”。", "a": "“实底”指信使所盼望的事成为真实可靠的根基，“确据”指信使未见之事有了把握。信心不是空想，而是抓住神应许的确信，如亚伯拉罕仰望应许之地、摩西看为基督受凌辱比埃及财物更宝贵。", "s": ""}, {"type": "essay", "q": "神的管教对信徒有什么意义？", "a": "管教证明我们是神的儿子（主所爱的他必管教），目的是使我们得益处、在他的圣洁上有分，并结出平安的果子，就是义。当被管教时不可轻看，也不可灰心，要存心忍耐，从中学习顺服与圣洁。", "s": ""}]','','study','[{"title": "基督的超越（1-4章）", "points": ["基督是神的儿子，远超过天使", "神藉他创造诸世界，他是神本体的真像", "基督比摩西更配多得荣耀", "进入安息的应许：信的人得以进入", "神的道是活泼有功效的，能辨明人心"]}, {"title": "更美的祭司（5-7章）", "points": ["基督照麦基洗德的等次永远为祭司", "麦基洗德无父无母、无生之始，预表基督", "亚伯拉罕献十分之一给麦基洗德，显明其超越", "利未祭司有死亡阻隔，基督长远活着代求", "更美之约的中保，带来更美的应许"]}, {"title": "更美的约与祭（8-10章）", "points": ["新约：神将律法放在他们里面，写在心上", "律法是将来美事的影儿，不是本物真像", "公牛山羊的血断不能除罪", "基督一次献上永远赎罪，坐下在至大者右边", "我们既因耶稣的血得以坦然进入至圣所"]}, {"title": "信心的见证（11章）", "points": ["信是所望之事的实底，未见之事的确据", "亚伯以诺挪亚：因信蒙神喜悦", "亚伯拉罕：出去的时候还不知往哪里去", "摩西：看为基督受凌辱比埃及财物更宝贵", "云彩般的见证人激励我们忍耐奔跑"]}, {"title": "奔跑与圣洁生活（12-13章）", "points": ["放下重担脱去缠累的罪，仰望耶稣", "主所爱的他必管教，管教结出平安的果子", "追求与众人和睦，并要追求圣洁", "耶稣基督昨日今日一直到永远是一样的", "以颂赞为祭献给神，不可忘记行善捐输"]}]','','89','新约•普通书信（大公书信）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220960001','圣经导览','雅各书','雅各书是实践性极强的书信，强调真信心必有好行为：要行道不单听道，信心没有行为是死的。要勒住舌头、谦卑顺服神、忍耐等候主来，在试炼中生忍耐，凭信心求智慧，作言行一致的完全人。','[{"type": "verse", "q": "【经文填空】只是你们要________，不要单单听道，自己欺哄自己。", "a": "行道", "ref": "《雅各书》1章22节", "s": "", "o": "雅各书1章22节"}, {"type": "verse", "q": "【经文填空】身体没有灵魂是死的，信心没有________也是死的。", "a": "行为", "ref": "《雅各书》2章26节", "s": "", "o": "雅各书2章26节"}, {"type": "verse", "q": "【经文填空】你们要________魔鬼，魔鬼就必离开你们逃跑了。", "a": "抵挡", "ref": "《雅各书》4章7节", "s": "", "o": "雅各书4章7节"}, {"type": "verse", "q": "【经文填空】神阻挡________，赐恩给谦卑的人。", "a": "骄傲的人", "ref": "《雅各书》4章6节", "s": "", "o": "雅各书4章6节"}, {"type": "verse", "q": "【经文填空】你们中间若有缺少________的，应当求那厚赐与众人、也不斥责人的神，主就必赐给他。", "a": "智慧", "ref": "《雅各书》1章5节", "s": "", "o": "雅各书1章5节"}, {"type": "verse", "q": "【经文填空】在神我们的父面前，那清洁没有玷污的虔诚，就是看顾在患难中的________，并且保守自己不沾染世俗。", "a": "孤儿寡妇", "ref": "《雅各书》1章27节", "s": "", "o": "雅各书1章27节"}, {"type": "verse", "q": "【经文填空】原来我们在许多事上都有________；若有人在话语上没有过失，他就是完全人，也能勒住自己的全身。", "a": "过失", "ref": "《雅各书》3章2节", "s": "", "o": "雅各书3章2节"}, {"type": "fill", "q": "雅各是耶稣的________，是耶路撒冷教会的重要领袖。", "a": "兄弟", "s": ""}, {"type": "fill", "q": "忍受试探的人是有福的，因为他经过试验以后，必得________的冠冕。", "a": "生命", "s": ""}, {"type": "fill", "q": "人被试探，不可说“我是被神试探”，因为神不能被________试探，也不试探人。", "a": "恶", "s": ""}, {"type": "fill", "q": "亚伯拉罕把儿子以撒献在坛上，这就应验经上所说：“亚伯拉罕信神，这就算为他的________。”", "a": "义", "s": ""}, {"type": "fill", "q": "妓女喇合接待使者，又放他们从别的路上出去，不也是一样因________称义吗？", "a": "行为", "s": ""}, {"type": "fill", "q": "舌头就是________，在我们百体中，舌头是个罪恶的世界，能污秽全身。", "a": "火", "s": ""}, {"type": "fill", "q": "你们贪恋还是得不着，你们杀害嫉妒，又斗殴争战，也不能得；你们得不着，是因为你们不________。", "a": "求", "s": ""}, {"type": "fill", "q": "你们中间有病了的呢，他就该请教会的________来，他们可以奉主的名用油抹他，为他祷告。", "a": "长老", "s": ""}, {"type": "fill", "q": "出于信心的祈祷要救那________，主必叫他起来；他若犯了罪，也必蒙赦免。", "a": "病人", "s": ""}, {"type": "fill", "q": "弟兄们哪，你们要________，直到主来。看哪，农夫忍耐等候地里宝贵的出产。", "a": "忍耐", "s": ""}, {"type": "single", "q": "雅各书的作者雅各是？", "o": ["使徒约翰的哥哥", "耶稣的兄弟", "彼得的同工", "保罗的门徒"], "a": "耶稣的兄弟", "s": ""}, {"type": "single", "q": "“信心没有行为是死的”出自雅各书哪一章？", "o": ["第一章", "第二章", "第三章", "第五章"], "a": "第二章", "s": ""}, {"type": "single", "q": "雅各用什么比喻舌头的破坏力？", "o": ["刀剑", "火", "毒箭", "洪水"], "a": "火", "s": ""}, {"type": "single", "q": "雅各劝勉人要快快地听，慢慢地说，慢慢地什么？", "o": ["行动", "动怒", "祷告", "离开"], "a": "动怒", "s": ""}, {"type": "single", "q": "以利亚恳切祷告使天三年零六个月不下雨，雅各说他是怎样的人？", "o": ["大先知", "与我们一样性情的人", "完全人", "祭司"], "a": "与我们一样性情的人", "s": ""}, {"type": "single", "q": "雅各书共有几章？", "o": ["三章", "四章", "五章", "六章"], "a": "五章", "s": ""}, {"type": "single", "q": "雅各说富足的人应当为什么喜乐？", "o": ["财富加增", "降卑", "享乐", "积蓄"], "a": "降卑", "s": ""}, {"type": "multiple", "q": "雅各书的主要实践主题包括？", "o": ["信心必有行为", "勒住舌头", "忍耐等候主来", "谦卑顺服神"], "a": "信心必有行为,勒住舌头,忍耐等候主来,谦卑顺服神", "s": ""}, {"type": "multiple", "q": "雅各书提到的旧约人物有？", "o": ["亚伯拉罕", "喇合", "以利亚", "约伯"], "a": "亚伯拉罕,喇合,以利亚,约伯", "s": ""}, {"type": "multiple", "q": "雅各责备按外貌待人，举的例子是？", "o": ["戴金戒指穿华美衣服的人", "穿肮脏衣服的穷人", "法利赛人", "税吏"], "a": "戴金戒指穿华美衣服的人,穿肮脏衣服的穷人", "s": ""}, {"type": "multiple", "q": "从上头来的智慧有何特征？", "o": ["清洁温柔", "结出善果", "没有偏见", "没有假冒"], "a": "清洁温柔,结出善果,没有偏见,没有假冒", "s": ""}, {"type": "judge", "q": "雅各书说，人称义是因着行为，不是单因着信。", "a": "对", "s": ""}, {"type": "judge", "q": "人被试探是神在试探他。", "a": "错", "s": ""}, {"type": "judge", "q": "按外貌待人、偏心待人是罪。", "a": "对", "s": ""}, {"type": "judge", "q": "舌头虽小，却能说大话，如同小火点燃大树林。", "a": "对", "s": ""}, {"type": "judge", "q": "与世俗为友的，就是与神为敌。", "a": "对", "s": ""}, {"type": "judge", "q": "雅各说，富足的人应当哭泣号啕，因为有苦难临到他们。", "a": "对", "s": ""}, {"type": "judge", "q": "“主若愿意，我们就可以活着”这句话出自雅各书。", "a": "对", "s": ""}, {"type": "essay", "q": "雅各书二章“信心没有行为是死的”与保罗“因信称义”是否矛盾？", "a": "不矛盾。保罗讲称义的根基唯独是信心，反对靠律法行为称义；雅各讲真实信心的必然表现是行为，反对没有行为的空洞信心。亚伯拉罕献以撒、喇合接待使者，都证明真信心必结出行为的果子。", "s": ""}, {"type": "essay", "q": "雅各书论舌头的教训对今日信徒有何提醒？", "a": "舌头虽小却能污秽全身、点燃生命轮子；完全人能勒住舌头。提醒我们说话要快快地听、慢慢地说，不可用舌头咒诅人，要用言语造就人、荣神益人。", "s": ""}, {"type": "essay", "q": "雅各书的“忍耐”主题如何应用在苦难中？", "a": "雅各以农夫等候出产、约伯的忍耐为例，劝勉受苦的弟兄忍耐直到主来。苦难中不发怨言、不彼此埋怨，坚固己心，因为主来的日子近了，主是满心怜悯、大有慈悲的。", "s": ""}]','','study','[{"title": "试炼与智慧（1章）", "points": ["落在百般试炼中都要以为大喜乐", "试炼生忍耐，忍耐当成功使人完全", "缺少智慧的当求神，主必厚赐", "要行道不要单单听道，自己欺哄自己", "清洁的虔诚：看顾孤儿寡妇，不沾染世俗"]}, {"title": "信心与行为（2章）", "points": ["不可按外貌待人，偏心待人便是犯罪", "信心没有行为是死的", "亚伯拉罕献以撒，信心与行为并行", "喇合接待使者，因行为称义", "身体没有灵魂是死的，信心没有行为也是死的"]}, {"title": "勒住舌头（3章）", "points": ["在话语上没有过失的就是完全人", "舌头虽小能说大话，如小火点燃大树林", "舌头是个罪恶的世界，能污秽全身", "泉源不能发出甜苦两样的水", "从上头来的智慧是清洁、温柔、结善果的"]}, {"title": "谦卑与顺服（4章）", "points": ["贪恋得不着是因为不求，妄求也得不着", "与世俗为友的就是与神为敌", "神阻挡骄傲的人，赐恩给谦卑的人", "务要抵挡魔鬼，亲近神", "人若知道行善却不去行，这就是他的罪了"]}, {"title": "忍耐等候主来（5章）", "points": ["富足人要为将来的苦难哭泣号啕", "要忍耐直到主来，如农夫等候出产", "你们也当忍耐，坚固你们的心", "以利亚是与我们一样性情的人，祷告大有功效", "叫罪人回转的，必救灵魂不死并遮盖许多罪"]}]','','90','新约•普通书信（大公书信）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220960002','圣经导览','彼得前书','彼得前书写给受苦中的信徒，勉励持守活泼的盼望：你们是被拣选的族类、君尊的祭司。要圣洁、顺服在上掌权者，为义受苦不羞愧反以为荣，效法基督受苦的榜样，将一切忧虑卸给顾念你们的神。','[{"type": "verse", "q": "【经文填空】愿颂赞归与我们主耶稣基督的父神！他曾照自己的大怜悯，藉耶稣基督从死里复活，重生了我们，叫我们有________的盼望。", "a": "活泼", "ref": "《彼得前书》1章3节", "s": "", "o": "彼得前书1章3节"}, {"type": "verse", "q": "【经文填空】惟有你们是被拣选的族类，是有________的祭司，是圣洁的国度，是属神的子民。", "a": "君尊", "ref": "《彼得前书》2章9节", "s": "", "o": "彼得前书2章9节"}, {"type": "verse", "q": "【经文填空】你们蒙召原是为此，因基督也为你们受过苦，给你们留下________，叫你们跟随他的脚踪行。", "a": "榜样", "ref": "《彼得前书》2章21节", "s": "", "o": "彼得前书2章21节"}, {"type": "verse", "q": "【经文填空】神阻挡骄傲的人，赐恩给________的人。", "a": "谦卑", "ref": "《彼得前书》5章5节", "s": "", "o": "彼得前书5章5节"}, {"type": "verse", "q": "【经文填空】务要谨守、警醒，因为你们的仇敌________，如同吼叫的狮子，遍地游行，寻找可吞吃的人。", "a": "魔鬼", "ref": "《彼得前书》5章8节", "s": "", "o": "彼得前书5章8节"}, {"type": "verse", "q": "【经文填空】亲爱的弟兄啊，你们是客旅，是________的。我劝你们要禁戒肉体的私欲，这私欲是与灵魂争战的。", "a": "寄居", "ref": "《彼得前书》2章11节", "s": "", "o": "彼得前书2章11节"}, {"type": "verse", "q": "【经文填空】你们要将一切的________卸给神，因为他顾念你们。", "a": "忧虑", "ref": "《彼得前书》5章7节", "s": "", "o": "彼得前书5章7节"}, {"type": "fill", "q": "彼得前书是使徒________写给分散在本都、加拉太等地的信徒。", "a": "彼得", "s": ""}, {"type": "fill", "q": "那召你们的既是圣洁，你们在一切所行的事上也要________。", "a": "圣洁", "s": ""}, {"type": "fill", "q": "你们既称那不偏待人、按各人行为审判人的主为父，就当存________的心度你们在世寄居的日子。", "a": "敬畏", "s": ""}, {"type": "fill", "q": "你们得赎乃是凭着基督的宝血，如同无瑕疵、无________的羔羊之血。", "a": "玷污", "s": ""}, {"type": "fill", "q": "主乃活石，固然是被人所弃的，却是被神所拣选、所________的。", "a": "宝贵", "s": ""}, {"type": "fill", "q": "你们来到主面前，也就像活石，被建造成________，作圣洁的祭司。", "a": "灵宫", "s": ""}, {"type": "fill", "q": "只要心里尊主基督为________，有人问你们心中盼望的缘由，就要常作准备回答。", "a": "圣", "s": ""}, {"type": "fill", "q": "有火炼的试验临到你们，不要以为________，似乎是遭遇非常的事。", "a": "奇怪", "s": ""}, {"type": "fill", "q": "倒要欢喜，因为你们是与基督一同________的。", "a": "受苦", "s": ""}, {"type": "fill", "q": "不以恶报恶，以辱骂还辱骂，倒要________，因你们是为此蒙召。", "a": "祝福", "s": ""}, {"type": "single", "q": "彼得前书说信徒在世上的身份是？", "o": ["主人", "客旅寄居者", "过客", "公民"], "a": "客旅寄居者", "s": ""}, {"type": "single", "q": "“君尊的祭司”出自彼得前书哪一章？", "o": ["第一章", "第二章", "第三章", "第五章"], "a": "第二章", "s": ""}, {"type": "single", "q": "彼得劝仆人顺服主人，即使主人怎样？", "o": ["温和", "乖僻", "公义", "慈爱"], "a": "乖僻", "s": ""}, {"type": "single", "q": "丈夫对待妻子当如何？", "o": ["管辖", "按情理敬重", "吩咐", "疏远"], "a": "按情理敬重", "s": ""}, {"type": "single", "q": "彼得说爱能遮掩什么？", "o": ["一切", "许多的罪", "过犯", "羞耻"], "a": "许多的罪", "s": ""}, {"type": "single", "q": "彼得说神的审判要从哪里起首？", "o": ["世界", "神的家", "外邦", "以色列"], "a": "神的家", "s": ""}, {"type": "single", "q": "彼得在书信末了自称是什么？", "o": ["使徒", "长老", "先知", "教师"], "a": "长老", "s": ""}, {"type": "multiple", "q": "彼得前书论为义受苦的意义包括？", "o": ["与基督一同受苦", "试验信心", "荣耀神", "受刑罚"], "a": "与基督一同受苦,试验信心,荣耀神", "s": ""}, {"type": "multiple", "q": "彼得劝勉信徒当顺服？", "o": ["君王", "臣宰", "主人", "丈夫"], "a": "君王,臣宰,主人,丈夫", "s": ""}, {"type": "multiple", "q": "基督受苦给我们留下榜样，包括？", "o": ["被骂不还口", "受害不说威吓的话", "将自己交托公义审判的主", "以暴制暴"], "a": "被骂不还口,受害不说威吓的话,将自己交托公义审判的主", "s": ""}, {"type": "multiple", "q": "彼得对长老牧养群羊的劝勉是？", "o": ["按着神旨意照管", "不是出于勉强", "不是贪财", "作群羊的榜样"], "a": "按着神旨意照管,不是出于勉强,不是贪财,作群羊的榜样", "s": ""}, {"type": "judge", "q": "彼得前书说，我们重生得的盼望是会朽坏、会衰残的。", "a": "错", "s": ""}, {"type": "judge", "q": "基督曾一次为罪受苦，就是义的代替不义的，为要引我们到神面前。", "a": "对", "s": ""}, {"type": "judge", "q": "洗礼所求的是除掉肉体的污秽。", "a": "错", "s": ""}, {"type": "judge", "q": "万物的结局近了，所以要谨慎自守，警醒祷告。", "a": "对", "s": ""}, {"type": "judge", "q": "彼得劝勉年幼的要顺服年长的，众人要以谦卑束腰。", "a": "对", "s": ""}, {"type": "judge", "q": "魔鬼如同吼叫的狮子，遍地游行寻找可吞吃的人。", "a": "对", "s": ""}, {"type": "judge", "q": "彼得前书是使徒保罗写给罗马教会的。", "a": "错", "s": ""}, {"type": "essay", "q": "“君尊的祭司”对今日信徒有何意义？", "a": "彼得说信徒是被拣选的族类、有君尊的祭司、圣洁国度。意义是：每位信徒都能直接亲近神，不必经人中保；要在世人中宣扬召我们出黑暗入光明者的美德，以圣洁生活作见证。", "s": ""}, {"type": "essay", "q": "彼得前书如何看待为义受苦？", "a": "为义受苦是有福的：不要以为奇怪，倒要欢喜，因与基督一同受苦；受苦是试验信心如火炼金子；若为作基督徒受苦却不要羞耻，倒要荣耀神；神的审判从神的家起首，受苦是暂时的，神必亲自成全坚固。", "s": ""}, {"type": "essay", "q": "彼得前书第五章对教会领袖有何教导？", "a": "劝长老按神旨意牧养群羊，不是出于勉强，不是贪财，不辖制托付的群羊，乃作榜样；到了牧长显现时必得永不衰残的荣耀冠冕。同时劝年幼顺服年长，众人谦卑束腰。", "s": ""}]','','study','[{"title": "活泼的盼望（1章）", "points": ["神藉基督复活重生我们，有活泼盼望", "得不能朽坏、不能玷污的基业", "信心经过试验比金子更显宝贵", "那召你们的既圣洁，你们也要圣洁", "你们得赎是凭基督如羔羊的宝血"]}, {"title": "圣洁的子民（2章）", "points": ["除去一切恶毒诡诈，爱慕纯净灵奶", "主乃活石，被神拣选宝贵", "你们是被拣选的族类、君尊的祭司", "宣扬召你们出黑暗入光明者的美德", "你们是客旅寄居的，禁戒肉体私欲"]}, {"title": "顺服与见证（2-3章）", "points": ["顺服人的一切制度，为主的缘故", "仆人顺服主人，就是乖僻的也要顺服", "基督受苦留下榜样，跟随他的脚踪", "妻子顺服丈夫，以贞洁品行感化", "不以恶报恶倒要祝福，常作准备回答盼望缘由"]}, {"title": "为义受苦（3-4章）", "points": ["为义受逼迫是有福的，不要怕人的威吓", "有火炼试验临到不要以为奇怪", "与基督一同受苦倒要欢喜", "若为作基督徒受苦不要羞耻，倒要荣耀神", "神的审判从神的家起首"]}, {"title": "牧养与警醒（5章）", "points": ["劝长老按神旨意牧养，不贪财作榜样", "年幼的顺服年长，众人以谦卑束腰", "将一切忧虑卸给神，因他顾念你们", "务要谨守警醒，抵挡如狮子的魔鬼", "神必亲自成全你们，坚固赐力量"]}]','','91','新约•普通书信（大公书信）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791220960003','圣经导览','彼得后书','彼得后书是彼得离世前的遗言，中心是防备假师傅：他们私引异端、随情欲行、贪不义之财。信徒要在恩典和知识上长进，记念先知与使徒的话，圣洁敬虔切切仰望主的日子，盼望有义居其中的新天新地。','[{"type": "verse", "q": "【经文填空】但主的日子要像________来到一样。那日，天必大有响声废去，有形质的都要被烈火销化，地和其上的物都要烧尽了。", "a": "贼", "ref": "《彼得后书》3章10节", "s": "", "o": "彼得后书3章10节"}, {"type": "verse", "q": "【经文填空】神的神能已将一切关乎生命和________的事赐给我们，皆因我们认识那用自己荣耀和美德召我们的主。", "a": "虔敬", "ref": "《彼得后书》1章3节", "s": "", "o": "彼得后书1章3节"}, {"type": "verse", "q": "【经文填空】第一要紧的，该知道经上所有的预言没有可随私意________的。", "a": "解说", "ref": "《彼得后书》1章20节", "s": "", "o": "彼得后书1章20节"}, {"type": "verse", "q": "【经文填空】主所应许的尚未成就，有人以为他是耽延，其实不是耽延，乃是________你们，不愿有一人沉沦，乃愿人人都悔改。", "a": "宽容", "ref": "《彼得后书》3章9节", "s": "", "o": "彼得后书3章9节"}, {"type": "verse", "q": "【经文填空】你们却要在我们主救主耶稣基督的________和知识上有长进。愿荣耀归给他，从今直到永远。", "a": "恩典", "ref": "《彼得后书》3章18节", "s": "", "o": "彼得后书3章18节"}, {"type": "verse", "q": "【经文填空】有了信心，又要加上________；有了德行，又要加上知识。", "a": "德行", "ref": "《彼得后书》1章5节", "s": "", "o": "彼得后书1章5节"}, {"type": "verse", "q": "【经文填空】主知道搭救________的人脱离试探，把不义的人留在刑罚之下，等候审判的日子。", "a": "敬虔", "ref": "《彼得后书》2章9节", "s": "", "o": "彼得后书2章9节"}, {"type": "fill", "q": "彼得后书警告，将来必有________私自引进陷害人的异端，连买他们的主他们也不承认。", "a": "假师傅", "s": ""}, {"type": "fill", "q": "他们应许人得以自由，自己却作________的奴仆，因为人被谁制伏就是谁的奴仆。", "a": "败坏", "s": ""}, {"type": "fill", "q": "比珥的儿子巴兰贪爱________的工价，彼得以后书引为贪心假师傅的鉴戒。", "a": "不义", "s": ""}, {"type": "fill", "q": "亲爱的弟兄啊，有一件事你们不可忘记，就是主看一日如________，千年如一日。", "a": "千年", "s": ""}, {"type": "fill", "q": "但我们照他的应许，盼望________，有义居在其中。", "a": "新天新地", "s": ""}, {"type": "fill", "q": "所以弟兄们，应当更加殷勤，使你们所蒙的________坚定不移。", "a": "恩召", "s": ""}, {"type": "fill", "q": "彼得说他快要________这帐棚，正如主耶稣基督所指示他的。", "a": "脱离", "s": ""}, {"type": "fill", "q": "我们并有先知更确的________，如同灯照在暗处，你们在这预言上留意直等到天发亮，是好的。", "a": "预言", "s": ""}, {"type": "fill", "q": "预言从来没有出于________，乃是人被圣灵感动，说出神的话来。", "a": "人意", "s": ""}, {"type": "fill", "q": "神也没有宽容________的天使，将他们丢在地狱，交在黑暗坑中，等候审判。", "a": "犯罪", "s": ""}, {"type": "single", "q": "彼得写后书的主要目的是？", "o": ["讲论历史", "防备假师傅", "颂赞诗歌", "劝人奉献"], "a": "防备假师傅", "s": ""}, {"type": "single", "q": "彼得说预言是人被谁感动说出的？", "o": ["天使", "圣灵", "君王", "自己"], "a": "圣灵", "s": ""}, {"type": "single", "q": "彼得形容假师傅像什么？", "o": ["无水的井", "被狂风催逼的雾气", "吼叫的狮子", "无水之井与雾气"], "a": "无水之井与雾气", "s": ""}, {"type": "single", "q": "“主的日子要像贼来到”出自彼得后书哪一章？", "o": ["第一章", "第二章", "第三章", "第四章"], "a": "第三章", "s": ""}, {"type": "single", "q": "彼得后书说要防备的是？", "o": ["假先知", "假师傅", "法利赛人", "撒都该人"], "a": "假师傅", "s": ""}, {"type": "single", "q": "彼得写后书时说自己快要怎样？", "o": ["退休", "脱离帐棚离世", "回耶路撒冷", "被提"], "a": "脱离帐棚离世", "s": ""}, {"type": "single", "q": "彼得后书共有几章？", "o": ["两章", "三章", "四章", "五章"], "a": "三章", "s": ""}, {"type": "multiple", "q": "彼得后书第一章生命长进的阶梯包括？", "o": ["信心加上德行", "德行加上知识", "节制忍耐虔敬", "爱弟兄的心爱众人的心"], "a": "信心加上德行,德行加上知识,节制忍耐虔敬,爱弟兄的心爱众人的心", "s": ""}, {"type": "multiple", "q": "假师傅的特征包括？", "o": ["随肉身纵污秽情欲", "轻慢主治之的", "胆大任性", "毁谤在尊位的"], "a": "随肉身纵污秽情欲,轻慢主治之的,胆大任性,毁谤在尊位的", "s": ""}, {"type": "multiple", "q": "彼得后书引用的旧约审判鉴戒有？", "o": ["犯罪的天使", "挪亚的世代", "所多玛蛾摩拉", "巴兰"], "a": "犯罪的天使,挪亚的世代,所多玛蛾摩拉,巴兰", "s": ""}, {"type": "multiple", "q": "等候主的日子当如何行？", "o": ["圣洁", "敬虔", "殷勤", "切切仰望"], "a": "圣洁,敬虔,殷勤,切切仰望", "s": ""}, {"type": "judge", "q": "彼得后书说，经上的预言可以随私意解说。", "a": "错", "s": ""}, {"type": "judge", "q": "主耽延不是耽延，乃是宽容，不愿有一人沉沦。", "a": "对", "s": ""}, {"type": "judge", "q": "引进异端的假师傅将来必速速地自取沉沦。", "a": "对", "s": ""}, {"type": "judge", "q": "彼得说他曾亲眼见过主的威荣，指登山变像的经历。", "a": "对", "s": ""}, {"type": "judge", "q": "神应许的新天新地有义居在其中。", "a": "对", "s": ""}, {"type": "judge", "q": "彼得后书一共有两章。", "a": "错", "s": ""}, {"type": "judge", "q": "“要在恩典和知识上有长进”是彼得后书的结语劝勉。", "a": "对", "s": ""}, {"type": "essay", "q": "今日信徒如何辨别和防备假师傅？", "a": "按彼得后书：看他们的教训是否否认主、随私意解经；看他们的行为是否纵情欲、贪不义之财、轻慢权柄。防备之法是：记念先知与使徒的话，在真道上长进，不被异端引诱，就不至失脚。", "s": ""}, {"type": "essay", "q": "“主的日子要像贼来到”给今日信徒什么提醒？", "a": "提醒主再来是突然的、不可预测的；那日天地都要废去。因此当圣洁敬虔、殷勤等候，切切仰望神的日子来到，不可因主耽延就懈怠，乃要趁宽容之日悔改长进。", "s": ""}, {"type": "essay", "q": "彼得后书第一章生命长进的“阶梯”如何实践？", "a": "从信心起步，依次加上德行、知识、节制、忍耐、虔敬、爱弟兄的心、爱众人的心。充充足足地有这几样，就不至闲懒不结果子；人若没有这几样就是瞎眼。每日在恩典和知识上操练，生命自然长进。", "s": ""}]','','study','[{"title": "生命的长进（1章）", "points": ["神已将关乎生命和虔敬的一切赐给我们", "信心加上德行、知识、节制、忍耐、虔敬、爱心", "充充足足有这几样就不至闲懒不结果子", "使所蒙的恩召坚定不移，永不失脚", "彼得快要脱离帐棚，提醒信徒记念真道"]}, {"title": "预言的确据（1章）", "points": ["我们亲眼见过主的威荣（登山变像）", "先知更确的预言如灯照在暗处", "经上预言没有可随私意解说的", "预言出于圣灵感动人说出神的话", "要在预言上留意直到天发亮晨星出现"]}, {"title": "防备假师傅（2章）", "points": ["将来必有假师傅私引陷害人的异端", "他们随肉身纵污秽情欲，轻慢主治", "如无水的井、被狂风催逼的雾气", "贪爱不义工价如巴兰，终必速速沉沦", "主知道搭救敬虔人脱离试探"]}, {"title": "主的日子（3章）", "points": ["末世必有好讥诮的人随私欲行", "主看一日如千年，千年如一日", "主耽延是宽容，不愿一人沉沦", "主的日子要像贼来到，天地废去", "照应许盼望新天新地，有义居其中"]}, {"title": "圣洁敬虔等候（3章）", "points": ["既盼望这些事就当圣洁敬虔", "切切仰望神的日子来到", "要殷勤使自己无可指摘安然见主", "防备恶人错谬免得失脚", "要在恩典和知识上有长进直到永远"]}]','','92','新约•普通书信（大公书信）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224281960','圣经导览','约翰一书','约翰一书是使徒约翰写给众教会的书信，强调「神就是光」与「神就是爱」两大主题。论认罪得赦免、基督为中保、彼此相爱的命令、防备敌基督、不爱世界的警戒、胜过世界的信心，使信徒确知自己有永生。','[{"type": "verse", "q": "我们若________，神是信实的，是公义的，必要________，________。", "a": "认自己的罪|赦免我们的罪|洗净我们一切的不义", "ref": "《约翰一书》1章9节", "s": "", "o": "约翰一书1章9节"}, {"type": "verse", "q": "我们若在光明中行，如同神在光明中，就彼此相交，他儿子耶稣的血也________。", "a": "洗净我们一切的罪", "ref": "《约翰一书》1章7节", "s": "", "o": "约翰一书1章7节"}, {"type": "verse", "q": "若有人犯罪，在父那里我们有一位________，就是那________耶稣基督。", "a": "中保|义者", "ref": "《约翰一书》2章1节", "s": "", "o": "约翰一书2章1节"}, {"type": "verse", "q": "主为我们________，我们从此就知道何为爱；我们也当________。", "a": "舍命|为弟兄舍命", "ref": "《约翰一书》3章16节", "s": "", "o": "约翰一书3章16节"}, {"type": "verse", "q": "没有爱心的，就不认识神，因为________。", "a": "神就是爱", "ref": "《约翰一书》4章8节", "s": "", "o": "约翰一书4章8节"}, {"type": "verse", "q": "________，因为神先爱我们。", "a": "我们爱", "ref": "《约翰一书》4章19节", "s": "", "o": "约翰一书4章19节"}, {"type": "verse", "q": "人有了神的儿子就有________，没有神的儿子就没有________。", "a": "生命|生命", "ref": "《约翰一书》5章12节", "s": "", "o": "约翰一书5章12节"}, {"type": "fill", "q": "约翰一书的作者是使徒________。", "a": "约翰", "s": ""}, {"type": "fill", "q": "「神就是________，在他毫无黑暗。」（1:5）", "a": "光", "s": ""}, {"type": "fill", "q": "「不要爱________和世界上的事。」（2:15）", "a": "世界", "s": ""}, {"type": "fill", "q": "世界上的事包括肉体的情欲、眼目的情欲，并________的骄傲。（2:16）", "a": "今生", "s": ""}, {"type": "fill", "q": "不认耶稣为基督的，就是________。（2:22）", "a": "敌基督", "s": ""}, {"type": "fill", "q": "「你看父赐给我们是何等的________，使我们得称为神的儿女。」（3:1）", "a": "慈爱", "s": ""}, {"type": "fill", "q": "神的儿子显现出来，为要________魔鬼的作为。（3:8）", "a": "除灭", "s": ""}, {"type": "fill", "q": "「我们相爱，不要只在言语和舌头上，总要在________和诚实上。」（3:18）", "a": "行为", "s": ""}, {"type": "fill", "q": "「爱里没有________；爱既完全，就把惧怕除去。」（4:18）", "a": "惧怕", "s": ""}, {"type": "fill", "q": "「使我们胜了世界的，就是我们的________。」（5:4）", "a": "信心", "s": ""}, {"type": "single", "q": "约翰一书中「生命之道」是指谁？", "o": ["耶稣基督", "施洗约翰", "摩西", "保罗"], "a": "耶稣基督", "s": ""}, {"type": "single", "q": "谁为我们的罪作了挽回祭？", "o": ["耶稣基督", "摩西", "亚伦", "大卫"], "a": "耶稣基督", "s": ""}, {"type": "single", "q": "约翰写约翰一书的主要目的是什么？", "o": ["叫信徒知道自己有永生", "讨论教会行政", "为保罗辩护", "解释旧约律法"], "a": "叫信徒知道自己有永生", "s": ""}, {"type": "single", "q": "「小子们哪」在约翰书信中是对谁的称呼？", "o": ["众信徒", "儿童", "少年门徒", "外邦人"], "a": "众信徒", "s": ""}, {"type": "single", "q": "敌基督的主要特征是什么？", "o": ["不认耶稣是基督", "不行神迹", "不守安息日", "不奉献"], "a": "不认耶稣是基督", "s": ""}, {"type": "single", "q": "该隐为什么杀他的兄弟亚伯？（3:12）", "o": ["因自己的行为是恶的，兄弟的是善的", "为争夺产业", "受人唆使", "一时失手"], "a": "因自己的行为是恶的，兄弟的是善的", "s": ""}, {"type": "single", "q": "约翰一书结尾劝勉信徒要自守，远避什么？（5:21）", "o": ["偶像", "世界", "试探", "仇敌"], "a": "偶像", "s": ""}, {"type": "multiple", "q": "以下哪些是「世界上的事」？（2:16）", "o": ["肉体的情欲", "眼目的情欲", "今生的骄傲", "爱弟兄"], "a": "肉体的情欲,眼目的情欲,今生的骄傲", "s": ""}, {"type": "multiple", "q": "约翰一书宣告神是怎样的神？", "o": ["神就是光", "神就是爱", "神是忌邪的神", "神是独一的灵"], "a": "神就是光,神就是爱", "s": ""}, {"type": "multiple", "q": "以下哪些是属神儿女的记号？", "o": ["认耶稣是成了肉身来的", "爱弟兄", "遵守神的命令", "能行神迹"], "a": "认耶稣是成了肉身来的,爱弟兄,遵守神的命令", "s": ""}, {"type": "multiple", "q": "约翰一书给信徒的「知道」（确据）包括哪些？", "o": ["知道自己有永生", "知道凡从神生的必不犯罪", "知道我们是属神的", "知道明天发生的事"], "a": "知道自己有永生,知道凡从神生的必不犯罪,知道我们是属神的", "s": ""}, {"type": "judge", "q": "约翰一书说「神就是光，在他毫无黑暗」。（1:5）", "a": "对", "s": ""}, {"type": "judge", "q": "约翰说我们若说自己无罪，便是自欺。（1:8）", "a": "对", "s": ""}, {"type": "judge", "q": "爱世界和爱父可以同时并存。（2:15）", "a": "错", "s": ""}, {"type": "judge", "q": "约翰时代已经有好些敌基督的出来了。（2:18）", "a": "对", "s": ""}, {"type": "judge", "q": "凡恨他弟兄的，就是杀人的。（3:15）", "a": "对", "s": ""}, {"type": "judge", "q": "完全的爱里仍然存有惧怕。（4:18）", "a": "错", "s": ""}, {"type": "judge", "q": "人有了神的儿子就有生命。（5:12）", "a": "对", "s": ""}, {"type": "essay", "q": "约翰一书1章9节的认罪应许包含哪几层含义？", "a": "三层：神是信实的、是公义的；必要赦免我们的罪；洗净我们一切的不义。认罪是恢复与神交通的蒙恩之路。", "s": ""}, {"type": "essay", "q": "「神就是光」（1:5）与「神就是爱」（4:8）如何共同描绘神的本性？", "a": "光显明神的圣洁公义、毫无黑暗；爱显明神主动差儿子作挽回祭。圣洁的神以大爱救赎罪人，光与爱并行不悖。", "s": ""}, {"type": "essay", "q": "约翰一书如何帮助信徒确知自己有永生？", "a": "藉着信神儿子之名（5:13）、遵守神的命令、爱弟兄、圣灵的内证，信徒可以确知有永生，并靠信心胜过世界。", "s": ""}]','','study','[{"title": "生命之道与神就是光（1章）", "points": ["从起初原有的生命之道：听见、看见、亲手摸过", "使徒将所见所听见的传给信徒，为要彼此相交", "神就是光，在他毫无黑暗（1:5）", "在光明中行，耶稣的血洗净一切的罪", "认罪的应许：赦免与洗净（1:9）", "若说自己无罪，便是自欺，真理不在心里"]}, {"title": "中保与不要爱世界（2章）", "points": ["写信为要叫你们不犯罪", "基督为中保，为普天下人作挽回祭", "遵守主命令的，爱神的心在他里面完全", "不要爱世界：肉体情欲、眼目情欲、今生骄傲", "这世界和其上的情欲都要过去", "敌基督已经出来：不认耶稣是基督", "从圣者受了恩膏，凡事知道"]}, {"title": "神的儿女与爱弟兄（3章）", "points": ["父赐何等慈爱，得称为神的儿女", "凡向他有这指望的，就洁净自己", "神儿子显现，为要除灭魔鬼的作为", "主为我们舍命，也当为弟兄舍命", "相爱要在行为和诚实上（3:18）", "恨弟兄的就是杀人的"]}, {"title": "神就是爱（4章）", "points": ["总要试验那些灵：认道成肉身的出于神", "神就是爱（4:8）", "神差儿子作挽回祭，这就是爱了", "我们爱，因为神先爱我们", "爱里没有惧怕，完全的爱除去惧怕", "不爱看得见的弟兄，就不能爱神"]}, {"title": "胜世界与永生确据（5章）", "points": ["凡信耶稣是基督的，都是从神而生", "使我们胜了世界的，就是我们的信心", "作见证的有三：圣灵、水与血", "人有了神的儿子就有生命（5:12）", "写信为叫你们知道自己有永生", "小子们哪，要自守，远避偶像"]}]','','93','新约•普通书信（大公书信）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224302241','圣经导览','约翰二书','约翰二书是使徒约翰写给「蒙拣选的太太」（教会）的短信，全书仅十三节。强调要在真理中彼此相爱，警戒防备不认基督道成肉身的迷惑人，吩咐不可接待传异端者到家里，也不要问他的安。','[{"type": "verse", "q": "我们若照他的命令行，这就是________。你们从起初所听见当行的，就是这________。", "a": "爱|命令", "ref": "《约翰二书》6节", "s": "", "o": "约翰二书1章6节"}, {"type": "verse", "q": "因为世上有许多________出来，他们不认耶稣基督是________来的；这就是那迷惑人、敌基督的。", "a": "迷惑人的|成了肉身", "ref": "《约翰二书》7节", "s": "", "o": "约翰二书1章7节"}, {"type": "verse", "q": "你们要小心，不要失去你们________，乃要得着________的赏赐。", "a": "所做的工|满足", "ref": "《约翰二书》8节", "s": "", "o": "约翰二书1章8节"}, {"type": "verse", "q": "凡________基督的教训、不常守着的，就没有神；常守这教训的，就有父又有子。", "a": "越过", "ref": "《约翰二书》9节", "s": "", "o": "约翰二书1章9节"}, {"type": "verse", "q": "若有人到你们那里，不是传这教训，________，也不要问他的安。", "a": "不要接他到家里", "ref": "《约翰二书》10节", "s": "", "o": "约翰二书1章10节"}, {"type": "verse", "q": "爱你们是为________的缘故，这真理存在我们里面，也必________与我们同在。", "a": "真理|永远", "ref": "《约翰二书》2节", "s": "", "o": "约翰二书1章2节"}, {"type": "verse", "q": "但盼望到你们那里，与你们________，使你们的喜乐________。", "a": "当面谈论|满足", "ref": "《约翰二书》12节", "s": "", "o": "约翰二书1章12节"}, {"type": "fill", "q": "约翰二书的作者自称「________」。", "a": "作长老的", "s": ""}, {"type": "fill", "q": "收信人是「蒙拣选的________」。（1节）", "a": "太太", "s": ""}, {"type": "fill", "q": "长老诚心所爱的是太太和她的________。（1节）", "a": "儿女", "s": ""}, {"type": "fill", "q": "「我见你的儿女，有照我们从父所受之命令________的，就甚欢喜。」（4节）", "a": "遵行真理", "s": ""}, {"type": "fill", "q": "从起初所听见的命令，就是要________。（5节）", "a": "彼此相爱", "s": ""}, {"type": "fill", "q": "迷惑人的特征，是不认耶稣基督是________来的。（7节）", "a": "成了肉身", "s": ""}, {"type": "fill", "q": "「因为问他安的，就在他的________上有分。」（11节）", "a": "恶行", "s": ""}, {"type": "fill", "q": "长老不愿意用________写出来，要当面谈论。（12节）", "a": "纸墨", "s": ""}, {"type": "fill", "q": "末了问安的是「那蒙拣选之________的儿女」。（13节）", "a": "姊妹", "s": ""}, {"type": "fill", "q": "约翰二书全书只有________章十三节。", "a": "一", "s": ""}, {"type": "single", "q": "「蒙拣选的太太」是指什么？", "o": ["教会", "某位姊妹", "马利亚", "长老的妻子"], "a": "教会", "s": ""}, {"type": "single", "q": "约翰二书强调的核心主题是什么？", "o": ["真理与爱", "教会组织", "末世预言", "奉献制度"], "a": "真理与爱", "s": ""}, {"type": "single", "q": "迷惑人、敌基督的特征是什么？", "o": ["不认耶稣基督成了肉身来", "不守安息日", "不奉献", "不祷告"], "a": "不认耶稣基督成了肉身来", "s": ""}, {"type": "single", "q": "对传异端教训的人应当如何？", "o": ["不要接他到家里", "与他辩论三天", "请他吃饭", "向他学习"], "a": "不要接他到家里", "s": ""}, {"type": "single", "q": "「越过基督的教训、不常守着的」结果是什么？", "o": ["就没有神", "得着赏赐", "更有智慧", "蒙神祝福"], "a": "就没有神", "s": ""}, {"type": "single", "q": "长老写信时最欢喜的是什么？", "o": ["见儿女遵行真理", "教会人数增长", "收到奉献", "建了会堂"], "a": "见儿女遵行真理", "s": ""}, {"type": "single", "q": "常守基督教训的人有什么福分？", "o": ["有父又有子", "得着财富", "身体健康", "长寿"], "a": "有父又有子", "s": ""}, {"type": "multiple", "q": "约翰二书论到「真理」的哪些方面？", "o": ["真理存在我们里面", "真理必永远与我们同在", "为真理的缘故彼此相爱", "真理就是摩西律法"], "a": "真理存在我们里面,真理必永远与我们同在,为真理的缘故彼此相爱", "s": ""}, {"type": "multiple", "q": "关于爱的命令，书中说了什么？", "o": ["要彼此相爱", "照他的命令行就是爱", "这是从起初听见的命令", "要爱世界"], "a": "要彼此相爱,照他的命令行就是爱,这是从起初听见的命令", "s": ""}, {"type": "multiple", "q": "防备迷惑人的教导包括哪些？", "o": ["要小心不要失去所做的工", "不要接传异教者到家里", "不要问他的安", "与他们公开辩论"], "a": "要小心不要失去所做的工,不要接传异教者到家里,不要问他的安", "s": ""}, {"type": "multiple", "q": "约翰二书的问安涉及哪些对象？", "o": ["蒙拣选的太太", "她的儿女", "蒙拣选之姊妹的儿女", "罗马的教会"], "a": "蒙拣选的太太,她的儿女,蒙拣选之姊妹的儿女", "s": ""}, {"type": "judge", "q": "约翰二书是写给「蒙拣选的太太」，指教会。（1节）", "a": "对", "s": ""}, {"type": "judge", "q": "长老说爱你们是为真理的缘故。（2节）", "a": "对", "s": ""}, {"type": "judge", "q": "见儿女遵行真理，长老就甚欢喜。（4节）", "a": "对", "s": ""}, {"type": "judge", "q": "迷惑人的是指不认耶稣基督成了肉身来的。（7节）", "a": "对", "s": ""}, {"type": "judge", "q": "对传异端者应当接他到家里好好招待。（10节）", "a": "错", "s": ""}, {"type": "judge", "q": "问传异端者安的，就在他的恶行上有分。（11节）", "a": "对", "s": ""}, {"type": "judge", "q": "长老盼望用纸墨把一切都写清楚，不必见面。（12节）", "a": "错", "s": ""}, {"type": "essay", "q": "为什么约翰吩咐不可接待传异端者到家里？", "a": "因为问他安、接待他的，就在他的恶行上有分（11节）。为保守教会真理纯正，不给异端传播的机会，当分别为圣。", "s": ""}, {"type": "essay", "q": "「真理」在约翰二书中有何重要地位？", "a": "真理存在信徒里面并永远同在；为真理的缘故彼此相爱；按真理而行带来喜乐；常守基督教训的就有父又有子。", "s": ""}, {"type": "essay", "q": "约翰二书如何平衡「爱」与「真理」？", "a": "爱必须在真理中：为真理的缘故爱，照命令行就是爱；但对偏离真理的异端，爱不等于妥协，要坚决不接待、不问安。", "s": ""}]','','study','[{"title": "蒙拣选的太太（1-3节）", "points": ["作长老的写信给蒙拣选的太太和她的儿女", "「太太」指教会，「儿女」指众信徒", "诚心所爱：为真理的缘故", "真理存在我们里面，也必永远同在", "恩惠、怜悯、平安从父神和基督而来", "要在真理和爱中蒙恩"]}, {"title": "按真理而行（4节）", "points": ["见你的儿女遵行真理，就甚欢喜", "照从父所受之命令而行", "真理是行事为人的标准", "儿女的顺服是牧者最大的喜乐", "部分儿女持守真理，值得称赞"]}, {"title": "爱的命令（5-6节）", "points": ["从起初所听见的命令：彼此相爱", "这不是新命令，乃是旧命令", "照他的命令行，这就是爱", "爱与顺服不可分割", "在真理中的爱才是真爱"]}, {"title": "防备迷惑人的（7-9节）", "points": ["世上有许多迷惑人的出来", "不认耶稣基督成了肉身来", "这就是那迷惑人、敌基督的", "要小心，不要失去所做的工", "乃要得着满足的赏赐", "越过基督教训的，就没有神", "常守这教训的，就有父又有子"]}, {"title": "不接待传异教者（10-13节）", "points": ["不传这教训的，不要接他到家里", "也不要问他的安", "问安的就在他的恶行上有分", "不愿用纸墨写，盼望当面谈论", "使你们的喜乐满足", "蒙拣选之姊妹的儿女问你们安"]}]','','94','新约•普通书信（大公书信）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224309209','圣经导览','约翰三书','约翰三书是使徒约翰写给该犹的私人信函，全书仅十五节。称赞该犹按真理而行、忠心接待客旅的爱心，责备在教会中好为首的丢特腓，举荐行善蒙见证的低米丢，劝勉不要效法恶，只要效法善。','[{"type": "verse", "q": "亲爱的兄弟啊，我愿你________，________，正如你的灵魂兴盛一样。", "a": "凡事兴盛|身体健壮", "ref": "《约翰三书》2节", "s": "", "o": "约翰三书1章2节"}, {"type": "verse", "q": "我听见我的儿女们________，我的喜乐就没有比这个大的。", "a": "按真理而行", "ref": "《约翰三书》4节", "s": "", "o": "约翰三书1章4节"}, {"type": "verse", "q": "因他们是为________出外，对于外邦人________。", "a": "主的名|一无所取", "ref": "《约翰三书》7节", "s": "", "o": "约翰三书1章7节"}, {"type": "verse", "q": "所以我们应该________，叫我们与他们________。", "a": "接待这样的人|一同为真理做工", "ref": "《约翰三书》8节", "s": "", "o": "约翰三书1章8节"}, {"type": "verse", "q": "亲爱的兄弟啊，不要________，只要________。行善的属乎神；行恶的未曾见过神。", "a": "效法恶|效法善", "ref": "《约翰三书》11节", "s": "", "o": "约翰三书1章11节"}, {"type": "verse", "q": "有弟兄来证明你心里存的________，正如你________，我就甚欢喜。", "a": "真理|按真理而行", "ref": "《约翰三书》3节", "s": "", "o": "约翰三书1章3节"}, {"type": "verse", "q": "________。众位朋友都问你安。请你替我按着姓名问众位朋友安。", "a": "愿你平安", "ref": "《约翰三书》15节", "s": "", "o": "约翰三书1章15节"}, {"type": "fill", "q": "约翰三书的收信人是亲爱的________。（1节）", "a": "该犹", "s": ""}, {"type": "fill", "q": "长老愿该犹身体健壮，正如他的________兴盛一样。（2节）", "a": "灵魂", "s": ""}, {"type": "fill", "q": "该犹向作客旅之弟兄所行的，都是________的。（5节）", "a": "忠心", "s": ""}, {"type": "fill", "q": "为主的名出外的人，对于外邦人________。（7节）", "a": "一无所取", "s": ""}, {"type": "fill", "q": "在教会中好为首、不接待使徒的是________。（9节）", "a": "丢特腓", "s": ""}, {"type": "fill", "q": "丢特腓用________妄论使徒。（10节）", "a": "恶言", "s": ""}, {"type": "fill", "q": "丢特腓禁止人接待弟兄，还把接待的人________。（10节）", "a": "赶出教会", "s": ""}, {"type": "fill", "q": "行善的________；行恶的未曾见过神。（11节）", "a": "属乎神", "s": ""}, {"type": "fill", "q": "行善、有众人给他作见证的是________。（12节）", "a": "低米丢", "s": ""}, {"type": "fill", "q": "长老盼望快快见该犹，要________谈论。（14节）", "a": "当面", "s": ""}, {"type": "single", "q": "约翰三书主要称赞该犹什么？", "o": ["按真理而行并接待客旅", "财富丰富", "口才出众", "建造会堂"], "a": "按真理而行并接待客旅", "s": ""}, {"type": "single", "q": "丢特腓的主要问题是什么？", "o": ["好为首，不接待使徒", "贫穷", "不识字", "年纪太小"], "a": "好为首，不接待使徒", "s": ""}, {"type": "single", "q": "低米丢的特点是什么？", "o": ["行善，有众人作见证", "很有钱", "是长老的亲戚", "会行神迹"], "a": "行善，有众人作见证", "s": ""}, {"type": "single", "q": "对为主名出外传道的人，教会应当如何？", "o": ["应当接待", "不理他们", "把他们赶走", "向他们收费"], "a": "应当接待", "s": ""}, {"type": "single", "q": "「行恶的」结局如何？（11节）", "o": ["未曾见过神", "会被赶出教会", "神仍接纳", "只是软弱"], "a": "未曾见过神", "s": ""}, {"type": "single", "q": "长老最大的喜乐是什么？", "o": ["听见儿女按真理而行", "收到礼物", "教会人数增长", "身体健康"], "a": "听见儿女按真理而行", "s": ""}, {"type": "single", "q": "约翰三书结尾的祝福是什么？", "o": ["愿你平安", "愿你发财", "愿你长寿", "愿你成功"], "a": "愿你平安", "s": ""}, {"type": "multiple", "q": "该犹的好行为包括哪些？", "o": ["按真理而行", "接待客旅之弟兄", "凡事忠心", "好为首"], "a": "按真理而行,接待客旅之弟兄,凡事忠心", "s": ""}, {"type": "multiple", "q": "丢特腓的恶行包括哪些？", "o": ["好为首", "不接待使徒", "用恶言妄论", "禁止人接待并赶出教会"], "a": "好为首,不接待使徒,用恶言妄论,禁止人接待并赶出教会", "s": ""}, {"type": "multiple", "q": "有哪些见证为低米丢作保？（12节）", "o": ["众人给他作见证", "真理给他作见证", "长老也给他作见证", "天使给他作见证"], "a": "众人给他作见证,真理给他作见证,长老也给他作见证", "s": ""}, {"type": "multiple", "q": "接待客旅的属灵意义有哪些？", "o": ["与他们一同为真理做工", "显明爱心", "忠心的表现", "得人的称赞"], "a": "与他们一同为真理做工,显明爱心,忠心的表现", "s": ""}, {"type": "judge", "q": "约翰三书是写给亲爱的该犹。（1节）", "a": "对", "s": ""}, {"type": "judge", "q": "长老愿该犹凡事兴盛、身体健壮。（2节）", "a": "对", "s": ""}, {"type": "judge", "q": "为主名出外的人向外邦人有所取。（7节）", "a": "错", "s": ""}, {"type": "judge", "q": "丢特腓在教会中好为首，不接待使徒。（9节）", "a": "对", "s": ""}, {"type": "judge", "q": "丢特腓用恶言妄论使徒。（10节）", "a": "对", "s": ""}, {"type": "judge", "q": "行善的属乎神，行恶的未曾见过神。（11节）", "a": "对", "s": ""}, {"type": "judge", "q": "低米丢行善，有众人给他作见证。（12节）", "a": "对", "s": ""}, {"type": "essay", "q": "该犹、丢特腓、低米丢三人形成怎样的对比？", "a": "该犹是按真理而行、接待人的榜样；丢特腓是好为首、排斥人的反面教材；低米丢是行善蒙众人见证的模范。劝勉信徒效法善、不效法恶。", "s": ""}, {"type": "essay", "q": "接待客旅在约翰三书中有何属灵意义？", "a": "接待为真道出外的人，就是与他们一同为真理做工（8节）；是忠心与爱心的表现；教会应当支持福音工作者。", "s": ""}, {"type": "essay", "q": "从丢特腓身上，教会领袖当警戒什么？", "a": "警戒好为首、专权、排斥异己、用恶言攻击神仆、拦阻人行善。领袖当谦卑服事，而非辖制群羊。", "s": ""}]','','study','[{"title": "该犹按真理而行（1-4节）", "points": ["作长老的写信给亲爱的该犹", "愿你凡事兴盛，身体健壮", "灵魂兴盛是首要的祝福", "弟兄证明他心里存真理", "按真理而行，令长老甚欢喜", "听见儿女按真理而行，喜乐无比"]}, {"title": "接待客旅的爱心（5-8节）", "points": ["向作客旅之弟兄所行的是忠心的", "他们在教会面前证明了你的爱", "为福音送行，配得过神", "为主的名出外，一无所取", "应当接待这样的人", "与他们一同为真理做工"]}, {"title": "丢特腓好为首（9-10节）", "points": ["在教会中好为首", "不接待使徒", "用恶言妄论", "禁止人接待弟兄", "把接待的人赶出教会", "专权跋扈的反面教材"]}, {"title": "效法善的低米丢（11-12节）", "points": ["不要效法恶，只要效法善", "行善的属乎神", "行恶的未曾见过神", "低米丢行善，众人作见证", "真理也为他作见证", "长老也为他作见证"]}, {"title": "平安的问候（13-15节）", "points": ["不愿用笔墨多写", "盼望快快见面，当面谈论", "愿你平安", "众位朋友都问你安", "按着姓名问众位朋友安"]}]','','95','新约•普通书信（大公书信）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224315107','圣经导览','犹大书','犹大书是主耶稣的兄弟犹大所写，劝信徒为从前一次交付圣徒的真道竭力争辩。揭露混入教会的假师傅，引用以诺预言其结局，勉励在至圣真道上造就自己，保守在神爱中，等候主怜悯直到永生。','[{"type": "verse", "q": "要为从前________圣徒的真道________地争辩。", "a": "一次交付|竭力", "ref": "《犹大书》3节", "s": "", "o": "犹大书1章3节"}, {"type": "verse", "q": "亲爱的弟兄啊，你们却要在________上造就自己，在________祷告。", "a": "至圣的真道|圣灵里", "ref": "《犹大书》20节", "s": "", "o": "犹大书1章20节"}, {"type": "verse", "q": "保守自己常在________，仰望我们主耶稣基督的怜悯，直到________。", "a": "神的爱中|永生", "ref": "《犹大书》21节", "s": "", "o": "犹大书1章21节"}, {"type": "verse", "q": "亚当的七世孙________曾预言这些人说：看哪，主带着他的________降临。", "a": "以诺|千万圣者", "ref": "《犹大书》14节", "s": "", "o": "犹大书1章14节"}, {"type": "verse", "q": "天使长________为摩西的尸首与魔鬼争辩的时候，只说：________！", "a": "米迦勒|主责备你吧", "ref": "《犹大书》9节", "s": "", "o": "犹大书1章9节"}, {"type": "verse", "q": "他们有祸了！因为走了________，又为利往________里直奔，并在________中灭亡了。", "a": "该隐的道路|巴兰的错谬|可拉的背叛", "ref": "《犹大书》11节", "s": "", "o": "犹大书1章11节"}, {"type": "verse", "q": "那能保守你们________、叫你们无瑕无疵、欢欢喜喜站在他荣耀之前的我们的救主——独一的神。", "a": "不失脚", "ref": "《犹大书》24节", "s": "", "o": "犹大书1章24节"}, {"type": "fill", "q": "犹大是耶稣基督的仆人，________的弟兄。（1节）", "a": "雅各", "s": ""}, {"type": "fill", "q": "写信给那被召、在父神里蒙爱、为耶稣基督________的人。（1节）", "a": "保守", "s": ""}, {"type": "fill", "q": "有些人________进来，将神的恩变作放纵情欲的机会。（4节）", "a": "偷着", "s": ""}, {"type": "fill", "q": "主救百姓出埃及地，后来把那些________的灭绝了。（5节）", "a": "不信", "s": ""}, {"type": "fill", "q": "不守本位的天使，主用________把他们永远拘留在黑暗里。（6节）", "a": "锁链", "s": ""}, {"type": "fill", "q": "所多玛、蛾摩拉受________的刑罚，作为鉴戒。（7节）", "a": "永火", "s": ""}, {"type": "fill", "q": "这些人是私下议论，常发________的。（16节）", "a": "怨言", "s": ""}, {"type": "fill", "q": "末世必有好________的人，随从自己不敬虔的私欲而行。（18节）", "a": "讥诮", "s": ""}, {"type": "fill", "q": "有些人存疑心，你们要________他们。（22节）", "a": "怜悯", "s": ""}, {"type": "fill", "q": "有些人你们要从________抢出来，搭救他们。（23节）", "a": "火中", "s": ""}, {"type": "single", "q": "犹大书的作者是谁？", "o": ["耶稣基督的仆人、雅各的弟兄犹大", "加略人犹大", "使徒多马", "马提亚"], "a": "耶稣基督的仆人、雅各的弟兄犹大", "s": ""}, {"type": "single", "q": "犹大写信的主要目的是什么？", "o": ["为真道竭力争辩", "讲述家谱", "解释预言", "为教会筹款"], "a": "为真道竭力争辩", "s": ""}, {"type": "single", "q": "偷着进来的人把神的恩变成什么？", "o": ["放纵情欲的机会", "赚钱的工具", "政治资本", "社交手段"], "a": "放纵情欲的机会", "s": ""}, {"type": "single", "q": "天使长米迦勒为谁的尸首与魔鬼争辩？", "o": ["摩西", "亚伯拉罕", "以利亚", "以诺"], "a": "摩西", "s": ""}, {"type": "single", "q": "预言「主带着他的千万圣者降临」的是谁？", "o": ["以诺", "以利亚", "但以理", "撒迦利亚"], "a": "以诺", "s": ""}, {"type": "single", "q": "「走了该隐的道路」是指什么？", "o": ["嫉妒凶杀、离弃正道", "贪爱钱财", "拜偶像", "说谎"], "a": "嫉妒凶杀、离弃正道", "s": ""}, {"type": "single", "q": "犹大书结尾的颂赞归给谁？", "o": ["独一的神我们的救主", "众天使", "使徒们", "教会"], "a": "独一的神我们的救主", "s": ""}, {"type": "multiple", "q": "犹大引用的历史鉴戒有哪些？", "o": ["出埃及后不信者被灭", "不守本位的天使被拘黑暗", "所多玛受永火刑罚", "巴别塔变乱口音"], "a": "出埃及后不信者被灭,不守本位的天使被拘黑暗,所多玛受永火刑罚", "s": ""}, {"type": "multiple", "q": "假师傅的特征包括哪些？", "o": ["将恩典变为放纵机会", "不认主耶稣基督", "私下议论常发怨言", "随从自己的情欲"], "a": "将恩典变为放纵机会,不认主耶稣基督,私下议论常发怨言,随从自己的情欲", "s": ""}, {"type": "multiple", "q": "信徒自守之道包括哪些？（20-21节）", "o": ["在至圣真道上造就自己", "在圣灵里祷告", "保守自己常在神的爱中", "仰望主怜悯直到永生"], "a": "在至圣真道上造就自己,在圣灵里祷告,保守自己常在神的爱中,仰望主怜悯直到永生", "s": ""}, {"type": "multiple", "q": "对待不同的人，犹大吩咐如何？", "o": ["存疑心的要怜悯", "从火中抢出来搭救", "恨恶那被情欲沾染的衣服", "一律赶出教会"], "a": "存疑心的要怜悯,从火中抢出来搭救,恨恶那被情欲沾染的衣服", "s": ""}, {"type": "judge", "q": "犹大是雅各的弟兄。（1节）", "a": "对", "s": ""}, {"type": "judge", "q": "要为从前一次交付圣徒的真道竭力争辩。（3节）", "a": "对", "s": ""}, {"type": "judge", "q": "偷进来的人将神的恩变为放纵情欲的机会。（4节）", "a": "对", "s": ""}, {"type": "judge", "q": "天使长米迦勒用毁谤的话责备魔鬼。（9节）", "a": "错", "s": ""}, {"type": "judge", "q": "以诺是亚当的七世孙。（14节）", "a": "对", "s": ""}, {"type": "judge", "q": "信徒要在至圣的真道上造就自己，在圣灵里祷告。（20节）", "a": "对", "s": ""}, {"type": "judge", "q": "保守自己常在神的爱中是信徒的本分。（21节）", "a": "对", "s": ""}, {"type": "essay", "q": "犹大书为什么强调「为真道竭力争辩」？", "a": "因有假师傅偷着进来，将恩典变为放纵、不认独一主宰；真道是从前一次交付圣徒的，当竭力持守、分辨异端。", "s": ""}, {"type": "essay", "q": "犹大引用的旧约鉴戒（出埃及、天使、所多玛；该隐、巴兰、可拉）说明什么？", "a": "神对悖逆的审判是确定的，无论以色列人、天使或外邦城邑；假师傅的结局早已注定，警戒信徒不可随从他们。", "s": ""}, {"type": "essay", "q": "20-21节给信徒的四重自守之道是什么？", "a": "在至圣真道上造就自己、在圣灵里祷告、保守自己常在神的爱中、仰望主耶稣基督的怜悯直到永生。这是抵挡异端、持守真道的积极路径。", "s": ""}]','','study','[{"title": "为真道竭力争辩（1-4节）", "points": ["犹大：耶稣基督的仆人，雅各的弟兄", "写信给蒙召、蒙爱、蒙保守的人", "原想写论救恩，现劝为真道争辩", "真道是从前一次交付圣徒的", "有人偷着进来：变恩典为放纵", "不认独一的主宰耶稣基督"]}, {"title": "历史的鉴戒（5-11节）", "points": ["出埃及后不信的被灭绝", "不守本位的天使被拘在黑暗里", "所多玛受永火刑罚，作为鉴戒", "米迦勒为摩西尸首争辩只说主责备你", "该隐的道路：嫉妒凶杀", "巴兰的错谬：为利直奔", "可拉的背叛：抗拒权柄"]}, {"title": "假师傅的特征（12-16节）", "points": ["爱筵上的玷污：只顾自己", "无雨的云、秋天无果的树", "海里狂浪、流荡的星", "以诺预言主带千万圣者降临", "私下议论，常发怨言", "随从情欲，说夸大阿谀的话"]}, {"title": "信徒的自守（17-23节）", "points": ["记念使徒预言：末世有讥诮者", "在至圣真道上造就自己", "在圣灵里祷告", "保守自己常在神的爱中", "仰望主怜悯，直到永生", "存疑心的要怜悯", "从火中抢救，恨恶沾染的衣"]}, {"title": "荣耀的颂赞（24-25节）", "points": ["神能保守你们不失脚", "无瑕无疵站在荣耀之前", "独一的神，我们的救主", "愿荣耀威严能力权柄归与他", "从万古以前并现今直到永远"]}]','','96','新约•普通书信（大公书信）','');
INSERT OR REPLACE INTO courses (id,category,title,content,quizzes_json,video_url,mode,guide_json,instructions,sort_order,subcategory,i18n_json) VALUES ('ID-1791224160852','圣经导览','启示录','启示录是圣经最后一卷，使徒约翰在拔摩海岛所见的异象。从给七教会的书信，到七印七号七碗的审判，从羔羊的婚筵到千禧年、白色大宝座，最终新天新地降临，显明基督必快来，神的国度永远长存。','[{"type": "verse", "q": "【经文填空】主神说：我是________，我是________，是昔在、今在、以后永在的全能者。", "a": "阿拉法|俄梅戛", "ref": "《启示录》1章8节", "s": "", "o": "启示录1章8节"}, {"type": "verse", "q": "【经文填空】你务要________，我就赐给你那生命的________。", "a": "至死忠心|冠冕", "ref": "《启示录》2章10节", "s": "", "o": "启示录2章10节"}, {"type": "verse", "q": "【经文填空】看哪，我站在________叩门，若有听见我声音就开门的，我要进到他那里去，我与他，他与我一同________。", "a": "门外|坐席", "ref": "《启示录》3章20节", "s": "", "o": "启示录3章20节"}, {"type": "verse", "q": "【经文填空】看哪，犹大支派中的________，大卫的________，他已得胜，能以展开那书卷，揭开那七印。", "a": "狮子|根", "ref": "《启示录》5章5节", "s": "", "o": "启示录5章5节"}, {"type": "verse", "q": "【经文填空】在主里面而死的人________了！他们息了自己的劳苦，作工的________也随着他们。", "a": "有福|果效", "ref": "《启示录》14章13节", "s": "", "o": "启示录14章13节"}, {"type": "verse", "q": "【经文填空】神要擦去他们一切的________；不再有________，也不再有悲哀、哭号、疼痛，因为以前的事都过去了。", "a": "眼泪|死亡", "ref": "《启示录》21章4节", "s": "", "o": "启示录21章4节"}, {"type": "verse", "q": "【经文填空】证明这事的说：是了，我必________！阿们！主耶稣啊，我愿你________！", "a": "快来|来", "ref": "《启示录》22章20节", "s": "", "o": "启示录22章20节"}, {"type": "fill", "q": "约翰在________海岛上，为神的道、为给耶稣作见证。", "a": "拔摩", "s": ""}, {"type": "fill", "q": "七教会都位于________省。", "a": "亚西亚", "s": ""}, {"type": "fill", "q": "以弗所教会有一件事可责备，就是离弃了________的爱心。", "a": "起初", "s": ""}, {"type": "fill", "q": "老底嘉教会________，主说要从口中把他吐出去。", "a": "不冷不热", "s": ""}, {"type": "fill", "q": "揭开第五印时，看见为神的道被杀之人的________在祭坛底下。", "a": "灵魂", "s": ""}, {"type": "fill", "q": "第七号吹响时，宣告世上的国成了我主和主基督的________。", "a": "国", "s": ""}, {"type": "fill", "q": "兽的数目是________。", "a": "六百六十六", "s": ""}, {"type": "fill", "q": "巴比伦倾倒之后，圣徒为________的婚筵欢喜快乐。", "a": "羔羊", "s": ""}, {"type": "fill", "q": "撒但被捆绑________年，之后必暂时释放。", "a": "一千", "s": ""}, {"type": "fill", "q": "新耶路撒冷有________个门，________个根基。", "a": "十二|十二", "s": ""}, {"type": "single", "q": "启示录的作者是谁？", "o": ["约翰", "彼得", "保罗", "雅各"], "a": "约翰", "s": ""}, {"type": "single", "q": "七教会中，哪间教会将要受患难十日？", "o": ["以弗所", "士每拿", "别迦摩", "推雅推喇"], "a": "士每拿", "s": ""}, {"type": "single", "q": "谁配展开书卷、揭开七印？", "o": ["米迦勒", "被杀的羔羊", "二十四位长老", "四活物"], "a": "被杀的羔羊", "s": ""}, {"type": "single", "q": "第七印揭开后，天上寂静约有多久？", "o": ["一刻", "二刻", "半小时", "一小时"], "a": "二刻", "s": ""}, {"type": "single", "q": "两个见证人传道多少天？", "o": ["一千二百六十天", "三年半", "四十二个月", "一千天"], "a": "一千二百六十天", "s": ""}, {"type": "single", "q": "白色大宝座审判后，死亡和阴间被扔在哪里？", "o": ["无底坑", "火湖", "外边黑暗", "深渊"], "a": "火湖", "s": ""}, {"type": "single", "q": "生命河的水从哪里流出来？", "o": ["伊甸园", "神和羔羊的宝座", "锡安山", "橄榄山"], "a": "神和羔羊的宝座", "s": ""}, {"type": "multiple", "q": "七教会是哪七间教会？", "o": ["以弗所", "士每拿", "别迦摩", "推雅推喇", "撒狄", "非拉铁非", "老底嘉", "安提阿"], "a": "以弗所,士每拿,别迦摩,推雅推喇,撒狄,非拉铁非,老底嘉", "s": ""}, {"type": "multiple", "q": "四活物分别像什么？", "o": ["狮子", "牛犊", "人", "飞鹰"], "a": "狮子,牛犊,人,飞鹰", "s": ""}, {"type": "multiple", "q": "以下哪些是七碗之灾的内容？", "o": ["恶臭的疮", "海变成血", "众水变成血", "日头烤人"], "a": "恶臭的疮,海变成血,众水变成血,日头烤人", "s": ""}, {"type": "multiple", "q": "新耶路撒冷有哪些特点？", "o": ["不再有黑夜", "神亲自与人同住", "生命树每月都结果子", "城门永不关闭"], "a": "不再有黑夜,神亲自与人同住,生命树每月都结果子,城门永不关闭", "s": ""}, {"type": "judge", "q": "启示录是约翰在拔摩海岛上领受异象后写成的。", "a": "对", "s": ""}, {"type": "judge", "q": "七教会都位于亚西亚省。", "a": "对", "s": ""}, {"type": "judge", "q": "揭开七印的是二十四位长老。", "a": "错", "s": ""}, {"type": "judge", "q": "兽的数目是六百六十六。", "a": "对", "s": ""}, {"type": "judge", "q": "千禧年之后，撒但被永远扔在火湖里。", "a": "对", "s": ""}, {"type": "judge", "q": "新天新地中还有死亡和眼泪。", "a": "错", "s": ""}, {"type": "judge", "q": "启示录最后一节是“愿主耶稣的恩惠常与众圣徒同在。阿们！”", "a": "对", "s": ""}, {"type": "essay", "q": "七教会书信对今日教会有何提醒？", "a": "要持守起初的爱心，至死忠心；警醒悔改，防备异端；不作不冷不热的基督徒；得胜者必得主的应许。", "s": ""}, {"type": "essay", "q": "启示录中“被杀的羔羊”形象有何意义？", "a": "羔羊被杀却配得权柄尊贵，表明基督借十字架代赎得胜；祂是犹大支派的狮子、大卫的根，是配展开书卷、审判全地的主。", "s": ""}, {"type": "essay", "q": "“主必快来”对信徒生活有何意义？", "a": "提醒信徒警醒预备、过圣洁生活；传福音有紧迫感；在患难中有盼望；以“主耶稣啊，我愿你来”回应主的应许。", "s": ""}]','','study','[{"title": "拔摩异象与七教会书信（1-3章）", "points": ["约翰在拔摩海岛，为神的道被囚", "人子异象：右手拿七星，七金灯台", "以弗所：失去起初的爱心，当悔改", "士每拿：务要至死忠心，得生命冠冕", "别迦摩、推雅推喇：持守真道，防备异端", "撒狄、非拉铁非、老底嘉：警醒、敞开的门、不冷不热"]}, {"title": "宝座与七印（4-7章）", "points": ["天上宝座：神坐宝座，四活物昼夜颂赞", "被杀的羔羊配展开书卷，揭开七印", "四马：白马、红马、黑马、灰马", "第五印：殉道者在祭坛底下呼求", "第六印：大地震，日月星辰变色", "十四万四千人受印，数不清的人穿白衣"]}, {"title": "七号与七碗（8-16章）", "points": ["七号之灾：雹火、海变血、星坠、日月昏暗", "两个见证人传道一千二百六十天", "第七号：世上的国成了主基督的国", "七碗之灾：疮、血水、日烤、黑暗、河干、地震雹", "兽的数目：六百六十六", "哈米吉多顿：列王聚集争战"]}, {"title": "巴比伦倾倒与羔羊婚筵（17-20章）", "points": ["大淫妇巴比伦倾倒，圣徒欢呼", "羔羊的婚筵：新妇自己预备整齐", "万王之王骑白马降临，口出利剑", "兽和假先知被扔进烧着硫磺的火湖", "千禧年：撒但被捆绑一千年", "白色大宝座审判：照各人所行受审"]}, {"title": "新天新地（21-22章）", "points": ["新天新地：先前的天地都过去了", "新耶路撒冷从天而降，如新妇妆饰", "神擦去一切眼泪，不再有死亡悲哀", "生命河与生命树：每月结果子，叶子医治万民", "城门永不关闭，不再有黑夜", "主必快来：主耶稣啊，我愿你来"]}]','','97','新约•预言书','');
CREATE TABLE IF NOT EXISTS categories (parent TEXT DEFAULT '', name TEXT, description TEXT DEFAULT '', created_at TEXT DEFAULT '', i18n_json TEXT DEFAULT '', PRIMARY KEY (parent, name));
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('基要真理','寇绍涵牧师•根基建造101','讲员：寇绍涵牧师（美国加州曙光华人基督教会主任牧师，晨星之光基金会）

信仰需要根基。正如房屋建在磐石上才能经风历雨，基督徒的生命也必须建造在稳固的真理根基上。本系列从"救恩是什么"等最核心的基要问题入手，带领信徒用圣经真理辨别各样信息，以永恒不变的真理检视自己的信仰和生活经历，把信仰的根基打深、打牢。

适合初信者系统学习，也适合每一位渴望在真道上扎根成长的弟兄姊妹。','{"en": {"name": "Reverend Kou Shaohan•Foundation Construction 101", "description": "Foundation 101 | Reverend Kou Shaohan\n\nSpeaker: Pastor Kou Shaohan (Senior Pastor, Dawn Chinese Christian Church, California, USA, Morningstar Light Foundation)\n\nFaith needs a foundation.Just as houses are built on rocks to weather the storm, so must the Christian life be built on a firm foundation of truth.Starting with the most central and fundamental questions such as \"What is salvation?\", this series leads believers to discern various messages with biblical truths, examine their beliefs and life experiences with eternal and unchanging truths, and deepen and strengthen the foundation of their faith.\n\nIt is suitable for new believers to learn systematically, and it is also suitable for every brother and sister who are eager to take root and grow in the true way."}, "ja": {"name": "Kou Shaohan牧師•基礎建設101", "description": "財団101 | Kou Shaohan牧師\n\n講演者： Kou Shaohan牧師（米国カリフォルニア州Dawn Chinese Christian Church、Morningstar Light Foundation、シニア牧師）\n\n信仰には基盤が必要です。家が嵐を乗り切るために岩の上に建てられているように、クリスチャンの生活も真理のしっかりした基盤の上に建てられなければなりません。このシリーズは，「救いとは何か」などの最も中心的で根本的な質問から始まり，聖書の真理でさまざまなメッセージを識別し，永遠に変わらない真理で自分の信念と人生経験を調べ，信仰の基礎を深め，強化するよう信者を導きます。\n\n新しい信者が体系的に学ぶのに適しており、真の方法で根付き、成長することを熱望するすべての兄弟姉妹にも適しています。"}, "ko": {"name": "코우 샤오한 (Kou Shaohan) 목사•기초 건축 개론", "description": "파운데이션 101 | 코우 샤오한 목사\n\n연사: Kou Shaohan 목사 (Morningstar Light Foundation 미국 캘리포니아 Dawn Chinese Christian Church 담임목사)\n\n신앙에는 기초가 필요합니다.폭풍우를 견디기 위해 바위 위에 집들이 지어지듯이 그리스도인의 삶도 진리의 굳건한 기초 위에 세워져야 합니다.이 시리즈는 \"구원이란 무엇인가?\" 와 같은 가장 중심적이고 근본적인 질문으로 시작하여 신자들이 성경적 진리로 다양한 메시지를 분별하고, 영원하고 변하지 않는 진리로 신념과 삶의 경험을 검토하며, 신앙의 기초를 심화하고 강화하도록 이끕니다.\n\n새로운 신자들이 체계적으로 배우기에 적합하며, 참된 방법으로 뿌리를 내리고 성장하기를 열망하는 모든 형제 자매들에게도 적합합니다."}}');
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('','基要真理','基要真理，是基督徒信仰的根基——关乎我们所信的是谁、为何而信、以及如何活出这份信仰。本系列从圣经、神、基督、圣灵，到救恩、教会、祷告与末世，系统梳理信仰的核心要道，帮助每一位信徒打下扎实稳固的根基，在真道上长大成熟，行事为人能与所蒙的恩相称。','{"en": {"name": "Fundamental Truths", "description": "Fundamental truths are the foundation of the Christian faith-who we believe in, why we believe it, and how we live it. From the Bible, God, Christ, and the Holy Spirit to salvation, church, prayer, and the last days, this series systematically combs the core tenets of faith to help every believer lay a solid and solid foundation, grow and mature in the true way, and act in a way that is commensurate with the grace received."}, "ja": {"name": "基本的な真理", "description": "基本的な真理は，キリスト教の信仰の基礎です。わたしたちは誰を信じ，なぜそれを信じ，どのようにそれを生きるのかを信じています。聖書、神、キリスト、聖霊から救い、教会、祈り、終わりの日まで、このシリーズは、すべての信者がしっかりとした堅固な基礎を築き、真の方法で成長し成熟し、受けた恵みに見合った方法で行動するのを助けるために、信仰の中心的な教義を体系的に梳きます。"}, "ko": {"name": "기본 진리", "description": "근본적인 진리는 그리스도교 신앙의 기초입니다. 우리는 무엇을 믿으며, 왜 그것을 믿으며, 어떻게 살아가는가? 이 시리즈는 성경, 하나님, 그리스도, 성령에서 구원, 교회, 기도, 말세에 이르기까지 모든 신자가 견고하고 견고한 기초를 세우고 참된 방식으로 성장하고 성숙하며 받은 은혜에 상응하는 방식으로 행동하도록 돕기 위해 신앙의 핵심 교리를 체계적으로 결합합니다."}}');
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('','圣经导览','**圣经导览｜66卷逐卷精读**

圣经是神给人最完整的启示，66卷书贯穿创造、堕落、救赎、新造的宏大叙事。本系列按卷逐卷导览，从创世记到启示录，帮助你掌握每卷书的写作背景、结构大纲、核心信息与关键经文，在整本圣经的脉络中认识神的作为。

适合想要系统读经、建立整全圣经观的每一位信徒。愿神的话语成为你脚前的灯、路上的光。','{"en": {"name": "Bible tour", "description": "Bible Tour | 66 Volumes Reading\n\nThe Bible is God''s most complete revelation to man, and the 66 books run through the grand narrative of creation, fall, redemption, and new creation.This series of scroll-by-scroll guides, from Genesis to Revelation, helps you grasp the writing background, structural outlines, core messages, and key scriptures of each book, and learn about God''s work throughout the context of the Bible.\n\nFor every believer who wants to read the Bible systematically and build a holistic view of the Bible.May the word of God be a lamp to your feet and a light to your path."}, "ja": {"name": "聖書ツアー", "description": "聖書ツアー| 66巻読書\n\n聖書は人間に対する神の最も完全な啓示であり、66冊の書物は創造、堕落、贖い、新しい創造の壮大な物語を通しています。創世記から黙示録までのこの一連のスクロールバイスクロールガイドは，各書籍の執筆背景，構造的な概要，コアメッセージ，重要な聖句を把握し，聖書の文脈全体を通して神の働きについて学ぶのに役立ちます。\n\n体系的に聖書を読み、聖書の全体像を構築したいすべての信者のために。神の言葉があなたの足のともしびと，あなたの道の光となりますように。"}, "ko": {"name": "성경 투어", "description": "성경 투어 | 66권 읽기\n\n성경은 인간에 대한 하나님의 가장 완전한 계시이며, 66 권의 책은 창조, 타락, 구속 및 새로운 창조에 대한 웅장한 서술을 통해 진행됩니다.창세기부터 요한계시록까지 스크롤 바이 스크롤 가이드 시리즈는 각 책의 글쓰기 배경, 구조적 개요, 핵심 메시지 및 핵심 경전을 파악하고 성경의 맥락에서 하나님의 역사에 대해 배우는 데 도움이 된다.\n\n체계적으로 성경을 읽고 성경에 대한 전체적인 관점을 구축하고자하는 모든 신자를 위해.하나님의 말씀이 여러분의 발에 등불이 되고 여러분의 길에 빛이 되기를 바랍니다."}}');
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('圣经导览','旧约•律法书（摩西五经）','摩西五经是整本圣经的根基，由摩西在圣灵感动下写成，记载从创造天地到以色列人在摩押平原预备进入迦南的历史。

- **创世记**：创造、堕落、拣选——神拣选亚伯拉罕建立选民
- **出埃及记**：救赎、立约——神领以色列出埃及，在西奈山颁布律法
- **利未记**：圣洁、敬拜——教导神的子民如何过圣洁生活亲近圣洁的神
- **民数记**：旷野、试炼——以色列四十年旷野漂流的信实与失败
- **申命记**：重申、祝福——摩西临终重申律法，祝福与警告并陈

五经奠定了整本圣经的神学基础：创造、约、救赎、圣洁、顺服。','{"en": {"name": "Old Testament•Book of the Law (Pentateuch)", "description": "The Pentateuch is the foundation of the entire Bible, written by Moses in the Holy Spirit, and records the history from the creation of the heavens and the earth to the preparation of the Israelites for their entry into Canaan in the plains of Moab.\n\n- Genesis: Creation, Fall, Election - God Chosen Abraham to Build His Chosen People\n- Exodus: Redemption, covenant - God brought Israel out of Egypt and promulgated the law on Mount Sinai\n- Leviticus: Holiness, Worship - Teaching God''s people how to live holy lives and draw near to a holy God\n- Numbers: Wilderness, Trial - Faithfulness and Failure of Israel''s Forty Years of Wandering in the Wilderness\n- Deuteronomy: Reaffirmation, Blessings - Moses'' final restatement of the law, blessings and warnings.\n\nThe Pentateuch lays the theological foundation for the entire Bible: creation, covenant, redemption, holiness, obedience."}, "ja": {"name": "旧約聖書•律法の書（五）", "description": "聖霊によってモーセによって書かれた聖書全体の基礎は、五であり、天と地の創造から、モアブの平野でカナンに入るためのイスラエル人の準備までの歴史を記録しています。\n\n-創世記：創造、堕落、選挙-神は選ばれた民を築くためにアブラハムを選ばれました\n-出エジプト記：贖い、聖約-神はイスラエルをエジプトから連れ出し、シナイ山に律法を公布されました\n-レビ記：聖性、崇拝-聖なる生活を送り、聖なる神に近づく方法を神の民に教える\n-数字：荒野、試練-イスラエルの荒野をさまよう40年の忠実さと失敗\n-申命記：再確認、祝福-モーセの律法、祝福、警告の最終的な再陳述。\n\n五は、聖書全体の神学的基盤、すなわち創造、契約、贖い、聖性、従順を築きます。"}, "ko": {"name": "구약성경•율법서 (오경)", "description": "오경은 모세가 성령으로 기록한 성경 전체의 기초이며, 하늘과 땅의 창조부터 모압 평원에서 가나안으로 들어가기 위한 이스라엘 백성의 준비에 이르기까지의 역사를 기록한다.\n\n- 창세기: 창조, 타락, 선택 - 하나님께서 아브라함을 택하사 택하신 백성을 세우셨음\n- 출애굽: 구속, 언약 - 하나님께서 이스라엘을 애굽에서 인도하여 내시고 시내산에서 율법을 공포하셨다.\n- 레위기: 거룩함, 예배 - 하나님의 백성들에게 거룩한 삶을 살고 거룩한 하나님을 가까이하는 방법을 가르칩니다.\n- 숫자: 광야, 시련 - 광야에서 헤매는 이스라엘의 40년간의 충실함과 실패\n- 신명기: 재확인, 축복 - 모세의 마지막 율법, 축복 및 경고.\n\n오경은 창조, 성약, 구속, 거룩함, 순종 등 성경 전체의 신학적 기초를 놓는다."}}');
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('圣经导览','旧约•历史书','从约书亚进迦南到以色列被掳归回，十二卷历史书记载神子民的得胜与失败。士师的循环、王国的兴衰、被掳与归回，都显明神的信实与人对顺服的亏欠。','{"en": {"name": "Old Testament•History Books", "description": "From the entry of Joshua into Canaan to the return of the captivity of Israel, the twelve books of history record the triumphs and defeats of God''s people. The circulation of judges, the rise and fall of the kingdom, the exile and return, all revealed God''s faithfulness and man''s debt to obedience."}, "ja": {"name": "旧約聖書•歴史書", "description": "ヨシュアのカナンへの入国から，イスラエルの捕囚の帰還まで，歴史の十二書は，神の民の勝利と敗北を記録しています。裁判官の流布、王国の興亡、追放と帰還、すべてが神の忠実さと従順に対する人間の借りを明らかにしました。"}, "ko": {"name": "구약성경•역사서", "description": "여호수아가 가나안에 입성할 때부터 이스라엘의 포로가 돌아올 때까지, 열두 권의 역사서는 하나님의 백성의 승리와 패배를 기록하고 있다. 사사의 순환, 왕국의 흥망, 유배와 귀환은 모두 하나님의 신실하심과 순종에 대한 인간의 빚을 드러냈다."}}');
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('圣经导览','旧约•诗歌智慧书','五卷诗歌智慧书是圣经的心灵之声：约伯记探讨苦难之谜，诗篇是历代圣徒的祷告赞美，箴言传授生活智慧，传道书看透日光之下的虚空，雅歌歌颂圣洁的爱情。','{"en": {"name": "Old Testament•Wisdom Book of Poetry", "description": "The five-volume Book of Songs and Wisdom is the spiritual voice of the Bible: Job explores the mystery of suffering, the Psalms are the prayers and praises of the saints of all ages, the Proverbs teach the wisdom of life, the Ecclesiastes sees through the void under the sun, and the Song of Songs praises holy love."}, "ja": {"name": "旧約聖書•詩の知恵の書", "description": "五巻の歌と知恵の書は聖書の霊的な声です。ヨブは苦しみの神秘を探求し、詩篇はすべての時代の聖徒の祈りと賛美であり、箴言は人生の知恵を教え、伝道者は太陽の下の空虚を見抜き、歌の歌は聖なる愛を賛美します。"}, "ko": {"name": "구약성경•시의 지혜서", "description": "욥은 고난의 신비를 탐구하고, 시편은 모든 시대의 성도들의 기도와 찬양이며, 잠언은 삶의 지혜를 가르치고, 전도서는 태양 아래 공허를 통해 보며, 노래는 거룩한 사랑을 찬양합니다."}}');
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('圣经导览','旧约•大先知书','以赛亚、耶利米、以西结、但以理——大先知书宣告审判与安慰，预言弥赛亚的降临与国度的复兴。哀歌则为耶路撒冷的倾覆哀哭。','{"en": {"name": "Old Testament•The Great Prophet", "description": "Isaiah, Jeremiah, Ezekiel, Daniel - the great prophets proclaimed judgment and consolation, prophesied the coming of the Messiah and the restoration of the kingdom. Lamentations weep for the overthrow of Jerusalem."}, "ja": {"name": "旧約聖書•偉大な預言者", "description": "イザヤ，エレミヤ，エゼキエル，ダニエル-偉大な預言者たちは裁きと慰めを宣べ伝え，メシアの到来と王国の回復を預言しました。嘆きはエルサレムの打倒のために泣き叫びます。"}, "ko": {"name": "구약성경•위대한 선지자", "description": "이사야, 예레미야, 에스겔, 다니엘 - 위대한 선지자들은 심판과 위로를 선포하고 메시아의 오심과 왕국의 회복을 예언했습니다. 예루살렘의 전복을 위해 애통이 울부짖는다."}}');
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('圣经导览','旧约•小先知书（十二小先知书）','从何西阿到玛拉基，十二卷小先知书篇幅虽小、分量却重：呼吁悔改、宣告审判、应许复兴，为弥赛亚铺平道路。','{"en": {"name": "Old Testament•Lesser Prophets (12 Lesser Prophets)", "description": "From Hosea to Malachi, the twelve small prophets, though small in size and weight, called for repentance, pronounced judgment, promised restoration, and paved the way for the Messiah."}, "ja": {"name": "旧約聖書•小預言者（ 12人の小預言者）", "description": "ホセアからマラキに至るまで， 12人の小さな預言者たちは，大きさも重さも小さいものの，悔い改めを求め，裁きを宣べ伝え，回復を約束し，メシアへの道を開きました。"}, "ko": {"name": "구약성경•소선지자 (12명의 소선지자)", "description": "호세아에서 말라기까지, 작은 선지자 열두 명은 크기와 무게는 작지만 회개를 요구하고, 심판을 선고하고, 회복을 약속하고, 메시아의 길을 닦았다."}}');
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('圣经导览','新约•福音书（四福音书）','四福音书记载耶稣基督的生平、教训、神迹、受死与复活。马太显明他是君王，马可显明他是仆人，路加显明他是人子，约翰显明他是神的儿子。四卷互相补足，见证同一位基督。','{"en": {"name": "New Testament•Gospels (Four Gospels)", "description": "The four Gospels record the life, teachings, miracles, death, and resurrection of Jesus Christ. Matthew shows that he is a king, Mark shows that he is a servant, Luke shows that he is a son of man, and John shows that he is a son of God. The four volumes complement each other and bear witness to the same Christ."}, "ja": {"name": "新約聖書•福音書（ 4つの福音書）", "description": "4つの福音書は，イエス・キリストの生涯，教え，奇跡，死，復活を記録しています。マタイは自分が王であることを示し，マルコは自分がしもべであることを示し，ルカは自分が人の子であることを示し，ヨハネは自分が神の子であることを示しています。四巻は互いに補完し合い，同じキリストの証となります。"}, "ko": {"name": "신약성경•복음서 (4복음서)", "description": "사복음서는 예수 그리스도의 생애, 가르침, 기적, 죽음, 부활을 기록한다. 마태는 그가 왕이라는 것을 보여주고, 마가는 그가 종이라는 것을 보여주고, 누가는 그가 사람의 아들이라는 것을 보여주고, 요한은 그가 하나님의 아들이라는 것을 보여줍니다. 네 권은 서로를 보완하고 동일한 그리스도를 증언합니다."}}');
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('圣经导览','新约•历史书','使徒行传记载圣灵降临、教会诞生、福音从耶路撒冷传到地极，是教会历史的第一章，也是今日宣教的蓝图。','{"en": {"name": "New Testament•History Book", "description": "The Acts of the Apostles, which records the coming of the Holy Spirit, the birth of the Church, and the spread of the gospel from Jerusalem to the ends of the earth, is the first chapter in the history of the Church and the blueprint of today''s mission."}, "ja": {"name": "新約聖書•歴史書", "description": "聖霊の到来，教会の誕生，エルサレムから地の果てまでの福音の広がりを記録した使徒行伝は，教会の歴史の第一章であり，今日の宣教の青写真です。"}, "ko": {"name": "신약성경•역사서", "description": "성령의 임하심, 교회의 탄생, 예루살렘에서 땅 끝까지의 복음 전파를 기록한 사도행전은 교회 역사의 첫 장이자 오늘날 선교의 청사진입니다."}}');
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('圣经导览','新约•保罗书信','罗马书到腓利门书，十三卷保罗书信阐明因信称义、基督里的新生命、教会的真理与生活，是基督徒信仰的基石。','{"en": {"name": "New Testament•Epistles of Paul", "description": "From Romans to Philemon, the thirteenth book of Paul''s epistles clarifies that justification by faith, new life in Christ, and the truth and life of the church are the cornerstones of the Christian faith."}, "ja": {"name": "新約聖書•パウロの手紙", "description": "ローマ人への手紙からフィレモンへの手紙まで、パウロの手紙の13番目の本は、信仰による義とされること、キリストにある新しいいのち、教会の真理といのちがキリスト教信仰の礎石であることを明確にしています。"}, "ko": {"name": "신약전서•바울서신", "description": "로마서에서 빌레몬서에 이르기까지 바울의 열세 번째 서간은 신앙에 의한 의화, 그리스도 안에서의 새로운 삶, 교회의 진리와 삶이 그리스도교 신앙의 초석임을 분명히합니다."}}');
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('圣经导览','新约•普通书信（大公书信）','希伯来书到犹大书，八卷普通书信写给众教会：持守真道、警醒异端、在苦难中忍耐、彼此相爱。','{"en": {"name": "New Testament•General Epistles (Grand Duke Epistles)", "description": "From the Book of Hebrews to the Book of Jude, eight ordinary volumes of letters were written to the churches: to hold on to the word of truth, to guard against heresy, to endure suffering, and to love one another."}, "ja": {"name": "新約聖書一般書簡（公会議書簡）", "description": "ヘブル書からユダ書まで、真理の言葉を守り、異端を防ぎ、苦しみに耐え、互いに愛し合うために、8巻の通常の手紙が教会に書かれていました。"}, "ko": {"name": "신약•일반 서신 (대공 서신)", "description": "히브리서에서 유다서에 이르기까지, 진리의 말씀을 붙잡고, 이단을 막고, 고통을 견디고, 서로 사랑하라는 여덟 권의 평범한 편지가 교회에 쓰여졌다."}}');
INSERT OR REPLACE INTO categories (parent,name,description,i18n_json) VALUES ('圣经导览','新约•预言书','启示录是圣经的终卷：羔羊得胜、撒但被捆、新天新地。预言给受苦的教会带来盼望，给全地带来警醒。','{"en": {"name": "New Testament•Book of Prophecies", "description": "The book of Revelation is the final book of the Bible: the victory of the Lamb, the bondage of Satan, the new heavens and the new earth. Prophecy brings hope to the suffering church, and vigilance to the whole earth."}, "ja": {"name": "新約聖書•預言書", "description": "黙示録は聖書の最後の本です：子羊の勝利、サタンの束縛、新しい天と新しい地。預言は，苦しんでいる教会に希望をもたらし，全地に警戒をもたらします。"}, "ko": {"name": "신약성경•예언서", "description": "요한계시록은 성경의 마지막 책입니다. 어린양의 승리, 사탄의 속박, 새 하늘과 새 땅. 예언은 고통받는 교회에 희망을, 온 땅에 경계를 가져다줍니다."}}');
CREATE TABLE IF NOT EXISTS bible_verses (ref TEXT PRIMARY KEY, book TEXT, chapter INTEGER, verse_start INTEGER, verse_end INTEGER, niv TEXT DEFAULT '', kjv TEXT DEFAULT '');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《罗马书》1章20节','罗马书','1','20','20','For since the creation of the world God’s invisible qualities—his eternal power and divine nature—have been clearly seen, being understood from what has been made, so that men are without excuse.','For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse: <sup>so: or, that they may be</sup>');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《出埃及记》34章6节','出埃及记','34','6','6','And he passed in front of Moses, proclaiming, “The Lord, the Lord, the compassionate and gracious God, slow to anger, abounding in love and faithfulness,','And the LORD passed by before him, and proclaimed, The LORD, The LORD God, merciful and gracious, longsuffering , and abundant in goodness and truth,');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《诗篇》19章1节','诗篇','19','1','1','Psalm 19<br/>For the director of music. A psalm of David.<br/>The heavens declare the glory of God;<br/>the skies proclaim the work of his hands.','To the chief Musician, A Psalm of David. The heavens declare the glory of God; and the firmament sheweth his handywork .');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《以弗所书》2章8节','以弗所书','2','8','8','For it is by grace you have been saved, through faith—and this not from yourselves, it is the gift of God—','For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《罗马书》3章23节','罗马书','3','23','23','for all have sinned and fall short of the glory of God,','For all have sinned, and come short of the glory of God;');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《马太福音》5章28节','马太福音','5','28','28','But I tell you that anyone who looks at a woman lustfully has already committed adultery with her in his heart.','But I say unto you, That whosoever looketh on a woman to lust after her hath committed adultery with her already in his heart.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰福音》3章16节','约翰福音','3','16','16','“For God so loved the world that he gave his one and only Son, that whoever believes in him shall not perish but have eternal life.','For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《罗马书》10章9节','罗马书','10','9','9','That if you confess with your mouth, “Jesus is Lord,” and believe in your heart that God raised him from the dead, you will be saved.','That if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《以赛亚书》53章5节','以赛亚书','53','5','5','But he was pierced for our transgressions,<br/>he was crushed for our iniquities;<br/>the punishment that brought us peace was upon him,<br/>and by his wounds we are healed.','But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed. <sup>wounded: or, tormented</sup> <sup>stripes: Heb. bruise</sup>');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰福音》4章24节','约翰福音','4','24','24','God is spirit, and his worshipers must worship in spirit and in truth.”','God is a Spirit: and they that worship him must worship him in spirit and in truth.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《马太福音》6章9节','马太福音','6','9','9','“This, then, is how you should pray:<br/>“‘Our Father in heaven,<br/>hallowed be your name,','After this manner therefore pray ye: Our Father which art in heaven, Hallowed be thy name.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《诗篇》115章5节','诗篇','115','5','5','They have mouths, but cannot speak,<br/>eyes, but they cannot see;','They have mouths, but they speak not: eyes have they, but they see not:');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰福音》1章14节','约翰福音','1','14','14','The Word became flesh and made his dwelling among us. We have seen his glory, the glory of the One and Only, who came from the Father, full of grace and truth.','And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《罗马书》1章4节','罗马书','1','4','4','and who through the Spirit of holiness was declared with power to be the Son of God by his resurrection from the dead: Jesus Christ our Lord.','And declared to be the Son of God with power, according to the spirit of holiness, by the resurrection from the dead: <sup>declared: Gr. determined</sup>');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《哥林多前书》15章17节','哥林多前书','15','17','17','And if Christ has not been raised, your faith is futile; you are still in your sins.','And if Christ be not raised, your faith is vain; ye are yet in your sins.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰福音》14章16节','约翰福音','14','16','16','And I will ask the Father, and he will give you another Counselor to be with you forever—','And I will pray the Father, and he shall give you another Comforter, that he may abide with you for ever;');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《加拉太书》5章22节','加拉太书','5','22','22','But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faithfulness,','But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰福音》3章8节','约翰福音','3','8','8','The wind blows wherever it pleases. You hear its sound, but you cannot tell where it comes from or where it is going. So it is with everyone born of the Spirit.”','The wind bloweth where it listeth, and thou hearest the sound thereof, but canst not tell whence it cometh, and whither it goeth: so is every one that is born of the Spirit.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《出埃及记》20章3节','出埃及记','20','3','3','“You shall have no other gods before me.','Thou shalt have no other gods before me.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《以赛亚书》9章6节','以赛亚书','9','6','6','For to us a child is born,<br/>to us a son is given,<br/>and the government will be on his shoulders.<br/>And he will be called<br/>Wonderful Counselor, Mighty God,<br/>Everlasting Father, Prince of Peace.','For unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰福音》10章30节','约翰福音','10','30','30','I and the Father are one.”','I and my Father are one.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《提摩太后书》3章16节','提摩太后书','3','16','16','All Scripture is God-breathed and is useful for teaching, rebuking, correcting and training in righteousness,','All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness:');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《利未记》19章9节','利未记','19','9','9','“‘When you reap the harvest of your land, do not reap to the very edges of your field or gather the gleanings of your harvest.','And when ye reap the harvest of your land, thou shalt not wholly reap the corners of thy field, neither shalt thou gather the gleanings of thy harvest.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《马太福音》17章20节','马太福音','17','20','20','He replied, “Because you have so little faith. I tell you the truth, if you have faith as small as a mustard seed, you can say to this mountain, ‘Move from here to there’ and it will move. Nothing will be impossible for you.”','And Jesus said unto them, Because of your unbelief: for verily I say unto you, If ye have faith as a grain of mustard seed, ye shall say unto this mountain, Remove hence to yonder place; and it shall remove; and nothing shall be impossible unto you.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《创世记》1章1节','创世记','1','1','1','The Beginning<br/>In the beginning God created the heavens and the earth.','In the beginning God created the heaven and the earth.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《创世记》1章27节','创世记','1','27','27','So God created man in his own image,<br/>in the image of God he created him;<br/>male and female he created them.','So God created man in his own image, in the image of God created he him; male and female created he them.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《哥林多后书》5章17节','哥林多后书','5','17','17','Therefore, if anyone is in Christ, he is a new creation; the old has gone, the new has come!','Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new. <sup>he is: or, let him be</sup>');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰福音》16章33节','约翰福音','16','33','33','“I have told you these things, so that in me you may have peace. In this world you will have trouble. But take heart! I have overcome the world.”','These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《罗马书》1章17节','罗马书','1','17','17','For in the gospel a righteousness from God is revealed, a righteousness that is by faith from first to last, just as it is written: “The righteous will live by faith.”','For therein is the righteousness of God revealed from faith to faith: as it is written, The just shall live by faith.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《罗马书》12章2节','罗马书','12','2','2','Do not conform any longer to the pattern of this world, but be transformed by the renewing of your mind. Then you will be able to test and approve what God’s will is—his good, pleasing and perfect will.','And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《雅各书》4章7节','雅各书','4','7','7','Submit yourselves, then, to God. Resist the devil, and he will flee from you.','Submit yourselves therefore to God. Resist the devil, and he will flee from you.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《以弗所书》4章22节','以弗所书','4','22','22','You were taught, with regard to your former way of life, to put off your old self, which is being corrupted by its deceitful desires;','That ye put off concerning the former conversation the old man, which is corrupt according to the deceitful lusts;');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《马太福音》16章26节','马太福音','16','26','26','What good will it be for a man if he gains the whole world, yet forfeits his soul? Or what can a man give in exchange for his soul?','For what is a man profited, if he shall gain the whole world, and lose his own soul? or what shall a man give in exchange for his soul?');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《马太福音》28章19节','马太福音','28','19','19','Therefore go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit,','Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost: <sup>teach: or, make disciples, or, Christians of all nations</sup>');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《路加福音》23章43节','路加福音','23','43','43','Jesus answered him, “I tell you the truth, today you will be with me in paradise.”','And Jesus said unto him, Verily I say unto thee, To day shalt thou be with me in paradise.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《马可福音》12章30节','马可福音','12','30','30','Love the Lord your God with all your heart and with all your soul and with all your mind and with all your strength.’','And thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind, and with all thy strength: this is the first commandment.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《罗马书》12章1节','罗马书','12','1','1','Living Sacrifices<br/>Therefore, I urge you, brothers, in view of God’s mercy, to offer your bodies as living sacrifices, holy and pleasing to God—this is your spiritual act of worship.','I beseech you therefore, brethren, by the mercies of God, that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《哥林多前书》3章6节','哥林多前书','3','6','6','I planted the seed, Apollos watered it, but God made it grow.','I have planted, Apollos watered; but God gave the increase.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《腓立比书》4章6节','腓立比书','4','6','6','Do not be anxious about anything, but in everything, by prayer and petition, with thanksgiving, present your requests to God.','Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《路加福音》18章13节','路加福音','18','13','13','“But the tax collector stood at a distance. He would not even look up to heaven, but beat his breast and said, ‘God, have mercy on me, a sinner.’','And the publican, standing afar off, would not lift up so much as his eyes unto heaven, but smote upon his breast, saying, God be merciful to me a sinner.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《罗马书》8章32节','罗马书','8','32','32','He who did not spare his own Son, but gave him up for us all—how will he not also, along with him, graciously give us all things?','He that spared not his own Son, but delivered him up for us all, how shall he not with him also freely give us all things?');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《哥林多前书》10章31节','哥林多前书','10','31','31','So whether you eat or drink or whatever you do, do it all for the glory of God.','Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《哥林多前书》14章12节','哥林多前书','14','12','12','So it is with you. Since you are eager to have spiritual gifts, try to excel in gifts that build up the church.','Even so ye, forasmuch as ye are zealous of spiritual gifts, seek that ye may excel to the edifying of the church. <sup>of spiritual gifts: Gr. of spirits</sup>');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《哥林多前书》12章29节','哥林多前书','12','29','29','Are all apostles? Are all prophets? Are all teachers? Do all work miracles?','Are all apostles? are all prophets? are all teachers? are all workers of miracles? <sup>workers: or, powers?</sup>');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰福音》6章39节','约翰福音','6','39','39','And this is the will of him who sent me, that I shall lose none of all that he has given me, but raise them up at the last day.','And this is the Father''s will which hath sent me, that of all which he hath given me I should lose nothing , but should raise it up again at the last day.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《哥林多前书》11章30节','哥林多前书','11','30','30','That is why many among you are weak and sick, and a number of you have fallen asleep.','For this cause many are weak and sickly among you, and many sleep.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《以赛亚书》14章12节','以赛亚书','14','12','12','How you have fallen from heaven,<br/>O morning star, son of the dawn!<br/>You have been cast down to the earth,<br/>you who once laid low the nations!','How art thou fallen from heaven, O Lucifer, son of the morning ! how art thou cut down to the ground, which didst weaken the nations! <sup>O Lucifer: or, O day star</sup>');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰一书》4章4节','约翰一书','4','4','4','You, dear children, are from God and have overcome them, because the one who is in you is greater than the one who is in the world.','Ye are of God, little children, and have overcome them: because greater is he that is in you, than he that is in the world.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约伯记》42章5节','约伯记','42','5','5','My ears had heard of you<br/>but now my eyes have seen you.','I have heard of thee by the hearing of the ear: but now mine eye seeth thee.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《以赛亚书》26章3节','以赛亚书','26','3','3','You will keep in perfect peace<br/>him whose mind is steadfast,<br/>because he trusts in you.','Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee. <sup>perfect: Heb. peace, peace</sup> <sup>mind: or, thought, or, imagination</sup>');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《罗马书》8章19节','罗马书','8','19','19','The creation waits in eager expectation for the sons of God to be revealed.','For the earnest expectation of the creature waiteth for the manifestation of the sons of God.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰福音》3章17节','约翰福音','3','17','17','For God did not send his Son into the world to condemn the world, but to save the world through him.','For God sent not his Son into the world to condemn the world; but that the world through him might be saved.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《启示录》21章4节','启示录','21','4','4','He will wipe every tear from their eyes. There will be no more death or mourning or crying or pain, for the old order of things has passed away.”','And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰福音》14章2节','约翰福音','14','2','2','In my Father’s house are many rooms; if it were not so, I would have told you. I am going there to prepare a place for you.','In my Father''s house are many mansions: if it were not so, I would have told you. I go to prepare a place for you.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰福音》17章3节','约翰福音','17','3','3','Now this is eternal life: that they may know you, the only true God, and Jesus Christ, whom you have sent.','And this is life eternal, that they might know thee the only true God, and Jesus Christ, whom thou hast sent.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《约翰福音》3章5节','约翰福音','3','5','5','Jesus answered, “I tell you the truth, no one can enter the kingdom of God unless he is born of water and the Spirit.','Jesus answered, Verily, verily, I say unto thee, Except a man be born of water and of the Spirit, he cannot enter into the kingdom of God.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《雅各书》1章22节','雅各书','1','22','22','Do not merely listen to the word, and so deceive yourselves. Do what it says.','But be ye doers of the word, and not hearers only, deceiving your own selves.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《以弗所书》6章13节','以弗所书','6','13','13','Therefore put on the full armor of God, so that when the day of evil comes, you may be able to stand your ground, and after you have done everything, to stand.','Wherefore take unto you the whole armour of God, that ye may be able to withstand in the evil day, and having done all, to stand. <sup>having: or, having overcome all</sup>');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《使徒行传》17章31节','使徒行传','17','31','31','For he has set a day when he will judge the world with justice by the man he has appointed. He has given proof of this to all men by raising him from the dead.”','Because he hath appointed a day, in the which he will judge the world in righteousness by that man whom he hath ordained; whereof he hath given assurance unto all men, in that he hath raised him from the dead. <sup>hath given: or, offered faith</sup>');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《哥林多前书》2章9节','哥林多前书','2','9','9','However, as it is written:<br/>“No eye has seen,<br/>no ear has heard,<br/>no mind has conceived<br/>what God has prepared for those who love him”—','But as it is written, Eye hath not seen, nor ear heard, neither have entered into the heart of man, the things which God hath prepared for them that love him.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《出埃及记》3章14节','出埃及记','3','14','14','God said to Moses, “I am who I am. This is what you are to say to the Israelites: ‘I am has sent me to you.’”','And God said unto Moses, I AM THAT I AM: and he said, Thus shalt thou say unto the children of Israel, I AM hath sent me unto you.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《出埃及记》12章13节','出埃及记','12','13','13','The blood will be a sign for you on the houses where you are; and when I see the blood, I will pass over you. No destructive plague will touch you when I strike Egypt.','And the blood shall be to you for a token upon the houses where ye are: and when I see the blood, I will pass over you, and the plague shall not be upon you to destroy you, when I smite the land of Egypt. <sup>to destroy: Heb. for a destruction</sup>');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《出埃及记》14章14节','出埃及记','14','14','14','The Lord will fight for you; you need only to be still.”','The LORD shall fight for you, and ye shall hold your peace.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《出埃及记》15章26节','出埃及记','15','26','26','He said, “If you listen carefully to the voice of the Lord your God and do what is right in his eyes, if you pay attention to his commands and keep all his decrees, I will not bring on you any of the diseases I brought on the Egyptians, for I am the Lord, who heals you.”','And said, If thou wilt diligently hearken to the voice of the LORD thy God, and wilt do that which is right in his sight, and wilt give ear to his commandments, and keep all his statutes, I will put none of these diseases upon thee, which I have brought upon the Egyptians: for I am the LORD that healeth thee.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《出埃及记》19章5节','出埃及记','19','5','5','Now if you obey me fully and keep my covenant, then out of all nations you will be my treasured possession. Although the whole earth is mine,','Now therefore, if ye will obey my voice indeed, and keep my covenant, then ye shall be a peculiar treasure unto me above all people: for all the earth is mine:');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《创世记》3章15节','创世记','3','15','15','And I will put enmity<br/>between you and the woman,<br/>and between your offspring and hers;<br/>he will crush your head,<br/>and you will strike his heel.”','And I will put enmity between thee and the woman, and between thy seed and her seed; it shall bruise thy head, and thou shalt bruise his heel.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《创世记》15章6节','创世记','15','6','6','Abram believed the Lord, and he credited it to him as righteousness.','And he believed in the LORD; and he counted it to him for righteousness.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《创世记》50章20节','创世记','50','20','20','You intended to harm me, but God intended it for good to accomplish what is now being done, the saving of many lives.','But as for you, ye thought evil against me; but God meant it unto good, to bring to pass, as it is this day, to save much people alive.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《创世记》6章8节','创世记','6','8','8','But Noah found favor in the eyes of the Lord.','But Noah found grace in the eyes of the LORD.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《创世记》22章18节','创世记','22','18','18','and through your offspring all nations on earth will be blessed, because you have obeyed me.”','And in thy seed shall all the nations of the earth be blessed; because thou hast obeyed my voice.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《利未记》11章44节','利未记','11','44','44','I am the Lord your God; consecrate yourselves and be holy, because I am holy. Do not make yourselves unclean by any creature that moves about on the ground.','For I am the LORD your God: ye shall therefore sanctify yourselves, and ye shall be holy; for I am holy: neither shall ye defile yourselves with any manner of creeping thing that creepeth upon the earth.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《利未记》19章18节','利未记','19','18','18','“‘Do not seek revenge or bear a grudge against one of your people, but love your neighbor as yourself. I am the Lord.','Thou shalt not avenge, nor bear any grudge against the children of thy people, but thou shalt love thy neighbour as thyself: I am the LORD.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《利未记》16章30节','利未记','16','30','30','because on this day atonement will be made for you, to cleanse you. Then, before the Lord, you will be clean from all your sins.','For on that day shall the priest make an atonement for you, to cleanse you, that ye may be clean from all your sins before the LORD.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《利未记》25章10节','利未记','25','10','10','Consecrate the fiftieth year and proclaim liberty throughout the land to all its inhabitants. It shall be a jubilee for you; each one of you is to return to his family property and each to his own clan.','And ye shall hallow the fiftieth year, and proclaim liberty throughout all the land unto all the inhabitants thereof: it shall be a jubile unto you; and ye shall return every man unto his possession, and ye shall return every man unto his family.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《利未记》23章3节','利未记','23','3','3','The Sabbath<br/>“‘There are six days when you may work, but the seventh day is a Sabbath of rest, a day of sacred assembly. You are not to do any work; wherever you live, it is a Sabbath to the Lord.','Six days shall work be done: but the seventh day is the sabbath of rest, an holy convocation; ye shall do no work therein: it is the sabbath of the LORD in all your dwellings.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《利未记》17章11节','利未记','17','11','11','For the life of a creature is in the blood, and I have given it to you to make atonement for yourselves on the altar; it is the blood that makes atonement for one’s life.','For the life of the flesh is in the blood: and I have given it to you upon the altar to make an atonement for your souls: for it is the blood that maketh an atonement for the soul.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《利未记》26章12节','利未记','26','12','12','I will walk among you and be your God, and you will be my people.','And I will walk among you, and will be your God, and ye shall be my people.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《民数记》6章24节','民数记','6','24','24','“‘“The Lord bless you<br/>and keep you;','The LORD bless thee, and keep thee:');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《民数记》21章8节','民数记','21','8','8','The Lord said to Moses, “Make a snake and put it up on a pole; anyone who is bitten can look at it and live.”','And the LORD said unto Moses, Make thee a fiery serpent, and set it upon a pole: and it shall come to pass, that every one that is bitten, when he looketh upon it, shall live.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《民数记》23章19节','民数记','23','19','19','God is not a man, that he should lie,<br/>nor a son of man, that he should change his mind.<br/>Does he speak and then not act?<br/>Does he promise and not fulfill?','God is not a man, that he should lie; neither the son of man, that he should repent: hath he said, and shall he not do it? or hath he spoken, and shall he not make it good?');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《民数记》14章18节','民数记','14','18','18','‘The Lord is slow to anger, abounding in love and forgiving sin and rebellion. Yet he does not leave the guilty unpunished; he punishes the children for the sin of the fathers to the third and fourth generation.’','The LORD is longsuffering , and of great mercy, forgiving iniquity and transgression, and by no means clearing the guilty, visiting the iniquity of the fathers upon the children unto the third and fourth generation.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《民数记》32章23节','民数记','32','23','23','“But if you fail to do this, you will be sinning against the Lord; and you may be sure that your sin will find you out.','But if ye will not do so, behold, ye have sinned against the LORD: and be sure your sin will find you out.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《民数记》9章15节','民数记','9','15','15','The Cloud Above the Tabernacle<br/>On the day the tabernacle, the Tent of the Testimony, was set up, the cloud covered it. From evening till morning the cloud above the tabernacle looked like fire.','And on the day that the tabernacle was reared up the cloud covered the tabernacle, namely, the tent of the testimony: and at even there was upon the tabernacle as it were the appearance of fire, until the morning.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《民数记》12章3节','民数记','12','3','3','(Now Moses was a very humble man, more humble than anyone else on the face of the earth.)','(Now the man Moses was very meek , above all the men which were upon the face of the earth.)');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《申命记》6章4节','申命记','6','4','4','Hear, O Israel: The Lord our God, the Lord is one.','Hear, O Israel: The LORD our God is one LORD:');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《申命记》8章3节','申命记','8','3','3','He humbled you, causing you to hunger and then feeding you with manna, which neither you nor your fathers had known, to teach you that man does not live on bread alone but on every word that comes from the mouth of the Lord.','And he humbled thee, and suffered thee to hunger, and fed thee with manna, which thou knewest not, neither did thy fathers know; that he might make thee know that man doth not live by bread only, but by every word that proceedeth out of the mouth of the LORD doth man live.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《申命记》30章19节','申命记','30','19','19','This day I call heaven and earth as witnesses against you that I have set before you life and death, blessings and curses. Now choose life, so that you and your children may live','I call heaven and earth to record this day against you, that I have set before you life and death, blessing and cursing: therefore choose life, that both thou and thy seed may live:');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《申命记》10章12节','申命记','10','12','12','Fear the Lord<br/>And now, O Israel, what does the Lord your God ask of you but to fear the Lord your God, to walk in all his ways, to love him, to serve the Lord your God with all your heart and with all your soul,','And now, Israel, what doth the LORD thy God require of thee, but to fear the LORD thy God, to walk in all his ways, and to love him, and to serve the LORD thy God with all thy heart and with all thy soul,');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《申命记》34章10节','申命记','34','10','10','Since then, no prophet has risen in Israel like Moses, whom the Lord knew face to face,','And there arose not a prophet since in Israel like unto Moses, whom the LORD knew face to face,');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《申命记》4章29节','申命记','4','29','29','But if from there you seek the Lord your God, you will find him if you look for him with all your heart and with all your soul.','But if from thence thou shalt seek the LORD thy God, thou shalt find him, if thou seek him with all thy heart and with all thy soul.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《申命记》29章29节','申命记','29','29','29','The secret things belong to the Lord our God, but the things revealed belong to us and to our children forever, that we may follow all the words of this law.','The secret things belong unto the LORD our God: but those things which are revealed belong unto us and to our children for ever, that we may do all the words of this law.');
INSERT OR REPLACE INTO bible_verses (ref,book,chapter,verse_start,verse_end,niv,kjv) VALUES ('《诗篇》34篇8节','诗篇','34','8','8','Taste and see that the Lord is good;<br/>blessed is the man who takes refuge in him.','O taste and see that the LORD is good: blessed is the man that trusteth in him.');
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT);
INSERT OR REPLACE INTO settings (key,value) VALUES ('notice','给弟兄姊妹的一封信｜团契智学平台  亲爱的弟兄姊妹，主内平安！  想和大家分享一个好消息：我们的线上学习平台「团契智学」最近做了一些贴心的升级，希望能陪伴大家在真道上走得更稳、更远。  ✨ 一些贴心的小功能 － 右下角「字」按钮，字太小看不清就点它放大 － 首页可按系列、子栏目折叠浏览，也可直接搜索 － 记得先写上你的名字，成绩会安安静静记在你名下 － 核对完可看每道错题的"你的答案 vs 正确答案"，错题自动进错题本方便复习 － 老师分享的单课链接点开即学，学完点「返回智学课程系统」回首页  不用赶进度，按自己的节奏来就好。愿我们在真道上一起扎根，一起成长。🌱');
INSERT OR REPLACE INTO settings (key,value) VALUES ('notice_en','A Letter to Brothers and Sisters | Dear Brothers and Sisters of the Fellowship of Wisdom Platform, Peace in the Lord! I want to share some good news with you: our online learning platform "Fellowship Intelligence" has recently made some thoughtful upgrades, hoping to accompany you to walk more steadily and further in the true way.  ✨ Some thoughtful small functions - The "Word" button in the bottom right corner, click it to enlarge if the word is too small to see it - The homepage can be folded and browsed by series and sub-columns, or directly searched - Remember to write your name first, and the grades will be quietly and quietly recorded in your name - After checking, you can see "Your Answers vs. Correct Answers" for each wrong question. The wrong question automatically enters the wrong question book for easy review - The teacher shares a single lesson link and clicks on it to learn, and after learning, "Return to the Intelligence Course System" The homepage does not need to catch up with progress, just follow your own rhythm. May we take root and grow together in the true way.🌱');
INSERT OR REPLACE INTO settings (key,value) VALUES ('notice_ja','兄弟姉妹への手紙|知恵プラットフォーム親愛なる兄弟姉妹の皆さん，主にある平安！良いお知らせがあります。当社のオンライン学習プラットフォーム「Fellowship Intelligence」は最近、いくつかの考え抜かれたアップグレードを行い、より着実に真の道を歩むためにあなたに同行したいと考えています。✨いくつかの思慮深い小さな機能-右下隅の「単語」ボタンをクリックして、単語が小さすぎて見えない場合は拡大します-ホームページは、シリーズとサブ列で折り畳んで閲覧することも、直接検索することもできます-最初に名前を書くことを忘れないでください。成績はあなたの名前に静かに静かに記録されます-チェックすると、間違った質問ごとに「あなたの答えと正しい答え」が表示されます。間違った質問は、簡単に確認できるように間違った質問帳に自動的に入力されます-教師は単一のレッスンリンクを共有し、それをクリックして学習し、学習後に「インテリジェンスコースシステムに戻る」ホームページは進捗状況に追いつく必要はなく、自分のリズムに従うだけです。私たちが根を張り、真の方法で共に成長しますように。🌱');
INSERT OR REPLACE INTO settings (key,value) VALUES ('notice_ko','형제자매들에게 보내는 편지 | 지혜의 원정대 형제자매 여러분, 주님 안에서 평화를 빕니다! 여러분과 좋은 소식을 나누고자 합니다. 저희 온라인 학습 플랫폼 "Fellowship Intelligence" 는 최근 몇 가지 사려 깊은 업그레이드를 진행했습니다. 여러분과 함께 진정한 방식으로 더 안정적이고 더 멀리 걸어갈 수 있기를 바랍니다.  ✨ 몇 가지 사려 깊은 작은 기능 - 오른쪽 하단의 "단어" 버튼을 클릭하면 단어가 너무 작아서 볼 수없는 경우 확대 할 수 있습니다. 홈페이지는 시리즈 및 하위 열별로 접어서 탐색하거나 직접 검색 할 수 있습니다. 먼저 이름을 적어 두어야하며 성적이 조용하고 조용히 이름으로 기록됩니다. 확인 후 각 잘못된 질문에 대해 "답변 대 정답" 을 볼 수 있습니다. 잘못된 질문은 자동으로 잘못된 질문 책에 들어가서 쉽게 복습 할 수 있습니다. - 교사는 하나의 수업 링크를 공유하고 클릭하여 배우고 학습 한 후 "지능 과정 시스템으로 돌아가기" 홈페이지는 진행 상황을 따라 잡을 필요가 없으며 자신의 리듬을 따르기 만하면됩니다. 참된 방법으로 뿌리를 내리고 함께 성장하길 바랍니다.🌱');
INSERT OR REPLACE INTO settings (key,value) VALUES ('schema_v2','1');
COMMIT;
